('2101143295810867202','嗳','1','ài','口','13',NULL,'[{"def": "嗳", "example": null}, {"def": "同哎”", "example": null}, {"def": "表示应答与呼唤", "example": null}, {"def": "表示应答", "example": null}, {"def": "王二桂兰!”王妻∶嗳!”--张庚编《秧歌剧选》", "example": null}, {"def": "表示提醒或呼唤。如嗳!小心别摔着了;嗳!快来呀", "example": null}, {"def": "表示不满或惊讶", "example": null}, {"def": "嗳!别哄我罢!--《老残游记》", "example": null}, {"def": "嗳（噯）āi叹词。", "example": null}, {"def": "①〈表〉不满或提醒～，你怎么又忘了！～，该走了！", "example": null}, {"def": "②〈表〉惊讶，痛苦～呀！～哟！", "example": null}, {"def": "嗳（噯）ǎi叹词。〈表〉否定，不同意～，不去。～，这件事不能那么办。", "example": null}, {"def": "嗳（噯）ài叹词。〈表〉懊恼、悔恨～，早晓得是这样，我才不干。同\\"哎\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295810867203','艾','1','ài','艹','5',NULL,'[{"def": "艾〈名〉", "example": null}, {"def": "(形声。本义草名)", "example": null}, {"def": "即艾蒿 。一种菊科的多年生草本植物叶制成艾绒,供针灸用", "example": null}, {"def": "艾,冰台也。--《说文》", "example": null}, {"def": "削冰令圆举以向日,干艾于后,承其景则得火,故曰冰台。--《博物志》", "example": null}, {"def": "彼采艾兮,一日不见,如三岁兮。--《诗·王风·采葛》", "example": null}, {"def": "求三年之艾也。--《孟子》。", "example": null}, {"def": "又如艾人(用艾草结成的草人。旧俗在端午节以艾人悬挂于门上,可以避邪除毒)", "example": null}, {"def": "老年,对老年人的敬称", "example": null}, {"def": "有幼、壮、艾之期。--刘禹锡《送鸿举师游江南引》", "example": null}, {"def": "五十曰艾,服官政。--《礼记》。郑玄注艾,老也", "example": null}, {"def": "艾ài", "example": null}, {"def": "⒈多年生草本，有香气，秋季开黄色小花。全草供药用，可杀虫，防治植物病虫害。叶可制艾绒，供灸病用。枝叶熏烟，可驱蚊、蝇等。", "example": null}, {"def": "⒉止，绝方兴未～。", "example": null}, {"def": "⒊美好幼～。", "example": null}, {"def": "艾yì", "example": null}, {"def": "⒈治理，改正。", "example": null}]','chinese-xinhua','0'),
('2101143295810867204','伌','1','ài','','10',NULL,'[{"def": "伌ài 1.困厄。", "example": null}]','chinese-xinhua','0'),
('2101143295810867205','爱','1','ài','爫','10',NULL,'[{"def": "爱〈动〉", "example": null}, {"def": "(形声。从心,旡声。本义亲爱;喜爱)", "example": null}, {"def": "对人或事物有深厚真挚的感情", "example": null}, {"def": "惠,爱也。--《尔雅》", "example": null}, {"def": "爱施者,仁之端也。--《说苑·说丛》", "example": null}, {"def": "君子自爱,仁之至也。--《法言》", "example": null}, {"def": "爱亲者不敢恶于人。--《孝经》。沈宏曰亲至结心为爱。”", "example": null}, {"def": "爱共叔段,欲立之。--《左传·隐公元年》", "example": null}, {"def": "停车坐爱枫林晚,霜叶红于二月花。--杜牧《山行》", "example": null}, {"def": "父母之爱子也,则为之计深远。--《战国策》", "example": null}, {"def": "公夫人甚爱女。--明·崔铣《记王忠肃公翱三事》", "example": null}, {"def": "爱其子,择师而教之。--唐·韩愈《师说》", "example": null}, {"def": "非疏骨肉爱过客。--《韩非子·五蠹》。", "example": null}, {"def": "爱（愛）ài", "example": null}, {"def": "⒈对人或事物有真诚、深厚的感情～人民。～祖国。她～教育工作。", "example": null}, {"def": "⒉喜好～清洁。她～唱歌。", "example": null}, {"def": "⒊重视，保护～惜时间。～护公物。", "example": null}, {"def": "⒋容易喝冷水～生病。", "example": null}, {"def": "⒌特指男女间的感情～情。恩～夫妻。", "example": null}]','chinese-xinhua','0'),
('2101143295810867206','砹','1','ài','石','10',NULL,'[{"def": "砹〈名〉", "example": null}, {"def": "一种属于卤族的放射性元素,原子序数85--元素符号at", "example": null}, {"def": "砹ài化学元素，具有放射性。符号at。", "example": null}]','chinese-xinhua','0'),
