('2101143295810867278','鞍','1','ān','革','15',NULL,'[{"def": "鞍", "example": null}, {"def": "(形声。从革,安声。本义马鞍) 同本义,放在骡马等背上供人骑坐或载物的器具。", "example": null}, {"def": "鞌,鞁具也。--《说文》", "example": null}, {"def": "令皆下马解鞍。--《汉书·李广传》", "example": null}, {"def": "投鞌高如城者数所。--《汉书·韩安国传》", "example": null}, {"def": "汉王下马踞鞍而问。--《史记·留侯世家》。", "example": null}, {"def": "又如鞍桥(指马鞍。因马鞍的形状像桥而得名);鞍辔(骑马的用具。鞍为坐具,辔为控马的缰束)", "example": null}]','chinese-xinhua','0'),
('2101143295810867279','闇','1','ān','閠','17',NULL,'[{"def": "闇", "example": null}, {"def": "(形声。从门,音声。本义闭门)", "example": null}, {"def": "同本义", "example": null}, {"def": "闇,闭门也。--《说文》", "example": null}, {"def": "见蔼闇阁读书。--《梁书·乐蔼传》", "example": null}, {"def": "又如闇门(隐蔽的门)", "example": null}, {"def": "蒙蔽;遮蔽", "example": null}, {"def": "桑麻闇日。--《水经注·江水》", "example": null}, {"def": "不下比以闇上。--《荀子·不苟》。注掩上之月也。”", "example": null}, {"def": "又如闇室(遮去光线的房间);闇没(埋没,掩没)", "example": null}, {"def": "闇", "example": null}, {"def": "同暗”(经传多以闇为之)", "example": null}, {"def": "闇,冥也。--《小尔雅》", "example": null}, {"def": "夏后氏祭其闇。--《礼记·祭义》", "example": null}, {"def": "孝子不服闇。--《礼记·曲礼》。注冥也。”", "example": null}, {"def": "彼日月兮闇昧。--王逸《九思·守志》", "example": null}, {"def": "又如闇时(昏暗的时代);闇昧(暗淡;指", "example": null}, {"def": "闇yīn 1.缄默不语。", "example": null}, {"def": "闇àn 1.晦暗;不亮。 2.指天未明时。 3.愚昧;昏乱。 4.深。 5.深黑。 6.不明了;不了解。 7.暗中;私下里。 8.湮没;埋没。 9.蒙蔽;遮蔽。", "example": null}, {"def": "闇ān 1.见\\"谅暗\\"。 2.通\\"谙\\"。熟悉，了解。", "example": null}, {"def": "闇yǎn 1.忽然。", "example": null}]','chinese-xinhua','0'),
('2101143295810867280','鮟','1','ān','魚','17',NULL,'[{"def": "鮟鱧", "example": null}, {"def": "鱼名，属于足鳍目的一种欧美产的海鱼,头大而扁,常半埋在泥沙里,移动头上的一根诱物和嘴边的一些肉质附器,引诱吞食其他的鱼。", "example": null}]','chinese-xinhua','0'),
