('2101143295815061512','枊','1','ànɡ','木','8',NULL,'[{"def": "枊〈名〉", "example": null}, {"def": "拴马桩", "example": null}, {"def": "枊,马柱也。从木,卬声。--《说文》", "example": null}, {"def": "刘备解绶,缚督邮马枊。--《三国志·蜀志》", "example": null}, {"def": "斗拱", "example": null}, {"def": "飞枊鸟踊。--何晏《景福殿赋》。注今人名屋四阿栱曰杄枊,或曰柳,当作枊,借枊为栱,柱头,斗栱也。”", "example": null}]','chinese-xinhua','0'),
('2101143295815061513','盎','1','ànɡ','皿','10',NULL,'[{"def": "盎〈名〉", "example": null}, {"def": "(形声。从皿,央声。本义腹大口小的盛物洗物的瓦盆)", "example": null}, {"def": "同本义", "example": null}, {"def": "盎,盆也。--《说文》", "example": null}, {"def": "盎谓之缶。--《尔雅》", "example": null}, {"def": "盎中无斗米储。--《乐府诗集·东门行》", "example": null}, {"def": "又如盎盂相敲(比喻家庭口角)", "example": null}, {"def": "盎齐(浊酒)的省称", "example": null}, {"def": "三曰盎齐。--《周礼·酒正》", "example": null}, {"def": "盎〈动〉", "example": null}, {"def": "充溢", "example": null}, {"def": "其生色也瞓然,见于面,盎于背。--《孟子·尽心上》", "example": null}, {"def": "又如兴趣盎然;盎盎(洋溢的样子,充盈的样子);盎溢(充盈洋溢)", "example": null}, {"def": "盎àng", "example": null}, {"def": "⒈〈古〉一种盛器，腹大口小。", "example": null}, {"def": "⒉洋溢，充满兴趣～然。", "example": null}]','chinese-xinhua','0'),
('2101143295815061514','醠','1','ànɡ','酉','17',NULL,'[{"def": "醠〈名〉", "example": null}, {"def": "清酒", "example": null}, {"def": "醠,浊酒也。从酉,盎声。清于醴而浊于缇,沈者,礼经皆以盎为之。--《说文》", "example": null}, {"def": "清醠之美,始于耒耜。--《淮南子·说林训》\\"清醠之美，始于耒耜。\\"高诱注\\"醠，清酒。\\"宋梅尧臣《送渭州刘太保》诗\\"千蹄使椎牛，百瓮令设醠。\\"", "example": null}]','chinese-xinhua','0'),
('2101143295815061515','肮','1','ānɡ','月','8',NULL,'[{"def": "肮脏", "example": null}, {"def": "脏;不干净", "example": null}, {"def": "肮脏的街道", "example": null}, {"def": "肮脏的池塘", "example": null}, {"def": "比喻卑鄙、丑恶;道义上应受指责", "example": null}, {"def": "肮脏的交易", "example": null}, {"def": "肮háng 1.咽喉。", "example": null}]','chinese-xinhua','0'),
('2101143295815061516','敖','1','áo','攵','10',NULL,'[{"def": "敖〈动〉", "example": null}, {"def": "(会意。从也,从出,俗字作遨。本义漫游;闲游)", "example": null}, {"def": "同本义", "example": null}, {"def": "敖,出游也。--《说文》", "example": null}, {"def": "敖不可长。--《礼记·曲礼》", "example": null}, {"def": "微我无酒,以敖以游。--《诗·邶风·柏舟》", "example": null}, {"def": "民不敖,则业不败。--《商君书·垦令》", "example": null}, {"def": "邑亡敖民。--《汉书·食货志》", "example": null}, {"def": "不得令晨夜去皇孙敖荡。--《汉书·丙吉传》", "example": null}, {"def": "又如敖民(游民);敖翔(遨游飞翔)", "example": null}, {"def": "喧哗;叫喊", "example": null}, {"def": "而日为乱人之道,百姓欢敖。--《荀子·强国》", "example": null}, {"def": "敖〈名〉", "example": null}, {"def": "粮仓。如敖仓(敖庾。秦代所建谷仓名。在河南省郑州市西北邙山上。山上有城,秦于其中置谷仓,故曰敖仓”", "example": null}, {"def": "傲慢;骄傲◇通作\\"傲\\"。", "example": null}]','chinese-xinhua','0'),
