('2101143295815061527','翱','1','áo','羽','16',NULL,'[{"def": "翱〈动〉", "example": null}, {"def": "(形声。从羽,皋声。本义翅膀上下振动而回旋地飞)", "example": null}, {"def": "同本义", "example": null}, {"def": "翱,翱翔也。--《说文》", "example": null}, {"def": "思从祥风翱。--《汉书·王褒传》", "example": null}, {"def": "翱翔四海之外。--《淮南子·览冥》。注翼一上一下曰翱。”", "example": null}, {"def": "鸟之高飞,翼上下曰翱,直剌不动曰翔。--《淮南子·俶真》注", "example": null}, {"def": "齐子翱翔。--《诗·齐风·载驱》", "example": null}, {"def": "羔裘翱翔。--《诗·桧风·羔裘》", "example": null}, {"def": "逸翮后尘,翱翥先路。--鲍照《舞鹤赋》", "example": null}, {"def": "又如翱翥(飞翔的样子)", "example": null}, {"def": "喻人自由自在地遨游,游乐", "example": null}, {"def": "将翱将翔。--《诗·郑风·女曰鸡鸣》", "example": null}, {"def": "翱翔", "example": null}, {"def": "翱（耾）áo", "example": null}]','chinese-xinhua','0'),
('2101143295815061528','聱','1','áo','耳','16',NULL,'[{"def": "聱〈形〉", "example": null}, {"def": "(形声。从耳敖声。本义不接受意见)", "example": null}, {"def": "同本义", "example": null}, {"def": "聱,不入人语也。--《广雅》", "example": null}, {"def": "彼诮为聱者,为其不相从听。--元结《自释》", "example": null}, {"def": "又如聱牙(乖忤,抵触。亦谓与人意见不同,不随世俗)", "example": null}, {"def": "文词艰涩。如聱牙戟口(聱牙诎曲,聱牙诘曲,聱牙诘屈。都形容文辞艰涩难读);聱屈(拗口难读)", "example": null}, {"def": "聱牙", "example": null}, {"def": "文句别扭,读不上口", "example": null}, {"def": "聱áo话不顺耳。不接受他人意见。", "example": null}, {"def": "聱yóu 1.众声杂作貌。参见\\"聱耴\\"﹑\\"聱聱\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295815061529','螯','1','áo','虫','16',NULL,'[{"def": "螯〈名〉", "example": null}, {"def": "(形声。从虫,敖声。本义节肢动物的螯夹)", "example": null}, {"def": "节足动物的第一对脚。足端两歧,开合如钳,可取食并作防卫之用", "example": null}, {"def": "蟹六跪而二螯。--《荀子·劝学》", "example": null}, {"def": "又如螯胶(百足蟹所煮成的胶)", "example": null}, {"def": "蟹,螃蟹。如螯蟹(螃蟹)", "example": null}, {"def": "螯áo 螃蟹、虾等甲壳动物变形的脚，末端两歧，形如钳子，用于取食或自卫。", "example": null}]','chinese-xinhua','0'),
('2101143295815061530','謷','1','áo','言','17',NULL,'[{"def": "謷〈动〉", "example": null}, {"def": "(形声。从言,敖声。本义不省人言)", "example": null}, {"def": "同本义", "example": null}, {"def": "謷,不省人言也。--《说文》", "example": null}, {"def": "令尹兮謷謷。--《楚辞·怨上》。注不听话言而妄语也。字亦作聱。”", "example": null}, {"def": "又如謷謷(不听善言而妄语)", "example": null}, {"def": "诋毁,造谣中伤", "example": null}, {"def": "謷丑先王,排訾旧典。--《吕氏春秋》", "example": null}, {"def": "又如謷丑(诋毁)", "example": null}, {"def": "哭不止;哀声", "example": null}, {"def": "謷, 一曰,哭不止,悲声謷謷也。--《说文》", "example": null}, {"def": "声謷謷尻益高。--《汉书·东方朔传》", "example": null}, {"def": "又如謷謷(众口哀怨的样子)", "example": null}]','chinese-xinhua','0'),
('2101143295815061531','鳌','1','áo','鱼','18',NULL,'[{"def": "鰲、鼇", "example": null}, {"def": "传说中海里的大龟或大鳖", "example": null}, {"def": "于是女娲炼五色石以补苍天,断鳌足以立四极。--《淮南子·览里》", "example": null}, {"def": "又如鳌里夺尊(做杰出人物中的佼佼者)", "example": null}, {"def": "鳌山", "example": null}, {"def": "宋元时俗。元宵节用彩灯堆叠成的山,像传说中的巨鳌形状", "example": null}, {"def": "鳌头", "example": null}, {"def": "指皇宫大殿前石阶上刻的鳌的头,考上状元的人可以踏上◇来用独占鳌头”比喻占首位或取得第一名", "example": null}, {"def": "鳌（鼇）áo〈古〉传说中的巨大海龟。另说是大鳖。", "example": null}]','chinese-xinhua','0'),
('2101143295815061532','鏖','1','áo','金','19',NULL,'[{"def": "鏖〈动〉", "example": null}, {"def": "(形声。从金,鏶声。本义温器)", "example": null}, {"def": "假借为熬。苦战。激烈战斗", "example": null}, {"def": "合短兵,鏖皋兰下。--《汉书·霍去病传》。注谓苦击而多杀也。”", "example": null}, {"def": "又如鏖杀(杀尽所有的人而不留活口)", "example": null}, {"def": "喧嚷,喧扰", "example": null}, {"def": "市声鏖午枕。--黄庭坚《仁亭》", "example": null}, {"def": "鏖兵", "example": null}, {"def": "大规模的激烈战争", "example": null}, {"def": "赤壁鏖兵(赤壁山名,在今湖北省蒲圻县长江南岸。东汉建安十三年,孙权与刘备联军在此打败曹操的军队)", "example": null}, {"def": "鏖战", "example": null}, {"def": "激烈地战斗;竭力苦战", "example": null}, {"def": "引兵三千,与贼鏖战。--《新唐书·王翃传》", "example": null}, {"def": "到了近代,又有多少人民的", "example": null}, {"def": "鏖áo激战，苦战海湾～兵。", "example": null}]','chinese-xinhua','0'),
