('2101143295815061547','傲','1','ào','亻','12',NULL,'[{"def": "傲〈形〉", "example": null}, {"def": "(形声。从人,敖声。本义骄傲;傲慢无理)", "example": null}, {"def": "同本义", "example": null}, {"def": "傲,倨也。--《说文》", "example": null}, {"def": "经传以敖为之", "example": null}, {"def": "凡视上于面则敖。--《礼记·曲礼》", "example": null}, {"def": "彼交匪敖。--《诗·小雅·桑柔》", "example": null}, {"def": "不吴不敖。--《诗·周颂·丝衣》", "example": null}, {"def": "敖而无足数者。--《史记·游侠传》", "example": null}, {"def": "执币,傲。--《左传·文公九年》", "example": null}, {"def": "齐音傲辟乔志。--《礼记·乐记》", "example": null}, {"def": "图傲救世之士哉。--《庄子·天下》", "example": null}, {"def": "弟敬爱兄谓之悌,反悌为傲。--《贾子道术》", "example": null}, {"def": "令尹甚傲而好兵,子必谨敬。--《韩非子·内储说下》", "example": null}, {"def": "傲不可长,欲不可纵。--魏征《十三斩不克终疏》", "example": null}, {"def": "又如傲兀(", "example": null}, {"def": "傲ào", "example": null}, {"def": "⒈自高自大～慢。骄～。", "example": null}, {"def": "⒉藐视，不屈～然而视。", "example": null}, {"def": "傲áo 1.出游。参见\\"傲虐\\"﹑\\"傲戏\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295815061548','奥','1','ào','大','12',NULL,'[{"def": "奥〈名〉", "example": null}, {"def": "(形声。本义古时指房屋的西南角。古时祭祀设神主或尊者居坐之处)", "example": null}, {"def": "同本义", "example": null}, {"def": "奥,宛也。室之西南隅。--《说文》", "example": null}, {"def": "燔柴于奥。--《礼记·礼器》", "example": null}, {"def": "西南隅谓之奥。--《尔雅》", "example": null}, {"def": "司宫筵于奥。--《仪礼·少牢礼》", "example": null}, {"def": "设于奥。--《仪礼·士丧礼》", "example": null}, {"def": "经堂入奥。--《楚辞·招魂》", "example": null}, {"def": "又如奥阼(室之西南隅,为尊者、主人之位)", "example": null}, {"def": "泛指室内深处", "example": null}, {"def": "室无奥阼。--《仲尼燕居》", "example": null}, {"def": "无能老蝙蝠,乘夜出堂奥。--张耒《夏日杂感》", "example": null}, {"def": "又如堂奥", "example": null}, {"def": "宫廷内机密的地方", "example": null}, {"def": "出入往来禁", "example": null}]','chinese-xinhua','0'),
