('2101143295815061559','袄','1','ǎo','衤','9',NULL,'[{"def": "袄", "example": null}, {"def": "(形声。从衣,夭声。本义有衬里的上衣)", "example": null}, {"def": "皮衣之类的御寒衣服", "example": null}, {"def": "身上穿着银红撇花半旧大袄。--《红楼梦》", "example": null}, {"def": "又如皮袄;袄子(棉袄的俗称)", "example": null}, {"def": "泛指上衣。如棉袄;夹袄", "example": null}, {"def": "袄（襖）ǎo有衬里的上衣棉～。皮～。夹～。", "example": null}]','chinese-xinhua','0'),
('2101143295815061560','媪','1','ǎo','女','12',NULL,'[{"def": "媪〈名〉", "example": null}, {"def": "(形声。从女,昷)声。本义对老年妇女的敬称)", "example": null}, {"def": "同本义", "example": null}, {"def": "白发谁家翁媪。--辛弃疾《清平乐》", "example": null}, {"def": "老臣窃以为媪之爱燕后,贤于长安君。--《战国策·赵策》", "example": null}, {"def": "又如媪妪(年老的妇女)", "example": null}, {"def": "对妇女的通称", "example": null}, {"def": "昂年五岁,乳媪(奶母)携抱匿于庐山。--《南史·袁昂传》", "example": null}, {"def": "母亲", "example": null}, {"def": "卫君自请薄媪。--《韩非子·外储说右上》", "example": null}, {"def": "袄", "example": null}, {"def": "(形声。从衣,夭声。本义有衬里的上衣)", "example": null}, {"def": "皮衣之类的御寒衣服", "example": null}, {"def": "身上穿着银红撇花半旧大袄。--《红楼梦》", "example": null}, {"def": "又如皮袄;袄子(棉袄的俗称)", "example": null}, {"def": "泛指上衣。如棉袄;夹袄", "example": null}, {"def": "媪ǎo年老的妇女。也泛指妇女乳～。", "example": null}]','chinese-xinhua','0'),
