('2101143295815061569','跋','1','bá','足','12',NULL,'[{"def": "跋", "example": null}, {"def": "(形声。从足,犮声。本义草中行走,越山过岭)", "example": null}, {"def": "同本义", "example": null}, {"def": "文公躬擐甲胄,跋履山川。--《左传·成公十三年》", "example": null}, {"def": "跋涉山川,蒙犯霜露。--《左传·襄公二十八年》", "example": null}, {"def": "大夫跋涉,我心则怃。--《诗·鄘风 ·载驰》", "example": null}, {"def": "又如跋援(犹攀登);跋履(登山涉水)", "example": null}, {"def": "扭转", "example": null}, {"def": "跋马望君非一度,冷猿秋雁不胜悲╠严武《巴岭答杜二见忆》", "example": null}, {"def": "又如跋马(勒紧马绳,使马回转)", "example": null}, {"def": "踏,踩", "example": null}, {"def": "又如跋浪(踏浪;破浪);跋足(踮起脚跟)", "example": null}, {"def": "见跋扈”", "example": null}, {"def": "跋", "example": null}, {"def": "火炬,火把", "example": null}, {"def": "通茇”。", "example": null}, {"def": "跋 bá", "example": null}, {"def": "①翻山越岭～山涉水。", "example": null}, {"def": "②一般写在书籍、文章、金石拓片等后面的短文。多为评介、鉴定、解释或说明写作经过之类的文字～语、序、题。", "example": null}, {"def": "【跋前痜（zhì）后】", "example": null}, {"def": "【跋前踬后】比喻进退两难。跋踩；踏。痜跌倒。", "example": null}, {"def": "【跋山涉水】翻过山岭，淌水过河。形容远足的艰辛。", "example": null}, {"def": "跋bèi 1.行不正貌。", "example": null}]','chinese-xinhua','0'),
('2101143295815061570','魃','1','bá','鬼','14',NULL,'[{"def": "魃", "example": null}, {"def": "旱魃,传说中能引起旱灾的鬼", "example": null}, {"def": "魃,旱鬼也。从鬼,犮声。--《说文》", "example": null}, {"def": "旱魃为虐,如惔如焚。--《诗·大雅·云汉》", "example": null}, {"def": "有人衣青衣名曰黄帝女魃。--《山海经·大荒北经》", "example": null}, {"def": "又如旱魃(古代传说中造成旱灾的鬼);魃虐(旱灾);魃蜮(鬼蜮)", "example": null}, {"def": "魃bá 1.神话传说中的旱神。", "example": null}]','chinese-xinhua','0'),
