('2101143295823450129','办','1','bàn','力','4',NULL,'[{"def": "办", "example": null}, {"def": "(形声。从力,辡声。力取致力之意。本义办理;治理)", "example": null}, {"def": "同本义", "example": null}, {"def": "办,致力也。--《说文新附》", "example": null}, {"def": "卿能办之者诚决。--《资治通鉴》", "example": null}, {"def": "又如办案;办事;办理", "example": null}, {"def": "做,干", "example": null}, {"def": "吾已无事可办,惟待死期耳。--清·梁启超《谭嗣同传》", "example": null}, {"def": "又如怎么办;群众发动起来了,事情就好办了", "example": null}, {"def": "创设,经营,管理", "example": null}, {"def": "是年,谢庄办团。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如办工厂;办学校;办报;办卖(变卖)", "example": null}, {"def": "准备,操办", "example": null}, {"def": "船、粮、战具俱办。--《资治通鉴》", "example": null}, {"def": "又如办酒(备办酒席);办丧事", "example": null}, {"def": "惩罚", "example": null}, {"def": "君信可人,必能办贼", "example": null}, {"def": "办 bàn", "example": null}, {"def": "①办理；处理～公、～案。", "example": null}, {"def": "②创建；经营～学、～企业。", "example": null}, {"def": "③采购；置备～酒席。", "example": null}, {"def": "④惩治首恶必～。", "example": null}]','chinese-xinhua','0'),
('2101143295823450130','半','1','bàn','十','5',NULL,'[{"def": "半", "example": null}, {"def": "(会意。从八,从牛。八”是分解的意思;牛大,易于分割,所以取牛”会意。本义一半,二分之一)", "example": null}, {"def": "同本义", "example": null}, {"def": "半,物中分也。--《说文》", "example": null}, {"def": "今汉有天下太半。--《汉书·高帝纪上》", "example": null}, {"def": "士卒食半。--《汉书·项籍传》", "example": null}, {"def": "先帝创业未半而中道崩殂。--诸葛亮《出师表》", "example": null}, {"def": "半匹红绡一丈绫。--唐·白居易《卖炭翁》", "example": null}, {"def": "身已半入,只露尻尾。--《聊斋志异·狼三则》", "example": null}, {"def": "又如太半(三分之二);半日;半工;半升", "example": null}, {"def": "中", "example": null}, {"def": "部分的,不完全的", "example": null}, {"def": "犹抱琵琶半遮面。", "example": null}]','chinese-xinhua','0'),
('2101143295823450131','伴','1','bàn','亻','7',NULL,'[{"def": "伴", "example": null}, {"def": "陪同;依随", "example": null}, {"def": "伴张驰之信期。--《楚辞·悲回风》。注俱也。”", "example": null}, {"def": "二贵酋名曰馆伴。(名义上是招待使者的官员。)--宋·文天祥《指南录·后序》", "example": null}, {"def": "又如伴宿(出殡前一天夜里,亲属等人通宵守灵);伴游(陪同游玩)", "example": null}, {"def": "配合", "example": null}, {"def": "相比", "example": null}, {"def": "他都是前生修的,咱拿甚么伴他?--《醒世姻缘传》", "example": null}, {"def": "伴", "example": null}, {"def": "伴侣;同伴", "example": null}, {"def": "众骇遽以离心兮,又何以为此伴也?--《楚辞·九章·惜诵》", "example": null}, {"def": "青春作伴好还乡。--唐·杜甫《闻官军收河南河北》", "example": null}, {"def": "羁魂(旅魂)有伴,当不孤寂。--清·袁枚《祭妹文》", "example": null}, {"def": "伴 bàn", "example": null}, {"def": "①同伴结～同行。", "example": null}, {"def": "②陪伴；随同～奏。", "example": null}, {"def": "【伴侣】一起生活，或一起工作，或一起旅行的人终身～（指夫妻）。", "example": null}, {"def": "【伴性遗传】性染色体上基因的遗传与性别相联系。如男性$染色体上的血友病基因，只能随$染色体传给其女儿，而不能传给其儿子。又称性连环、性连锁。", "example": null}, {"def": "【伴奏】乐曲有机组成部分之一，由一件或多件乐器担任，来衬托主要的歌唱或器乐演奏部分。也指烘托舞蹈的器乐配乐。", "example": null}]','chinese-xinhua','0'),
('2101143295823450132','扮','1','bàn','扌','7',NULL,'[{"def": "扮", "example": null}, {"def": "(形声。从手,分声。(蝦??))本义握,并)", "example": null}, {"def": "打扮,装扮", "example": null}, {"def": "鲁智深、武松扮作行脚僧。--《征四寇传》", "example": null}, {"def": "又如扮作客人;扮女人;扮相;扮戏子(化妆演戏的人)", "example": null}, {"def": "装出", "example": null}, {"def": "扮fěn 1.握持。 2.合并。", "example": null}, {"def": "扮bàn 1.装扮。 2.谓脸部表情装成某种样子。 3.扮演。 4.方言。犹打。脱粒。", "example": null}]','chinese-xinhua','0'),
('2101143295823450133','姅','1','bàn','女','8',NULL,'[{"def": "姅", "example": null}, {"def": "月经", "example": null}, {"def": "姅,媍人污也。从女,半声。--《说文》", "example": null}, {"def": "见姅变不得侍祠。--《汉律》", "example": null}, {"def": "姅bàn 1.指女性月经﹑生育﹑小产等。", "example": null}]','chinese-xinhua','0'),
('2101143295823450134','拌','1','bàn','扌','8',NULL,'[{"def": "拌", "example": null}, {"def": "搅和;调匀", "example": null}, {"def": "拿香油一收,外加糟油一拌。--《红楼梦》", "example": null}, {"def": "又如用水拌面粉;拌种;拌草;拌匀(搅拌使均匀)", "example": null}, {"def": "争吵", "example": null}, {"def": "拌 bàn 搅和往面条里～菜。", "example": null}, {"def": "拌pān 1.舍弃;豁出。 2.谓耗费。 3.摧残。 4.放，撒。参见\\"拌娇\\"。", "example": null}, {"def": "拌pàn 1.分开;剖割。", "example": null}]','chinese-xinhua','0'),
('2101143295823450135','绊','1','bàn','纟','8',NULL,'[{"def": "绊", "example": null}, {"def": "羁绊;拘束;束缚", "example": null}, {"def": "细推物理须行乐,何用浮荣绊此身。--杜甫《曲江二首》", "example": null}, {"def": "今绊姜维于沓中,使不得东顾。--《资治通鉴》", "example": null}, {"def": "用绳子把足系住", "example": null}, {"def": "不羁不绊。--扬雄《交州牧箴》", "example": null}, {"def": "又如绊脚(用绳子绑住脚)", "example": null}, {"def": "走路或跑步时被别的东西挡住或缠住", "example": null}, {"def": "被门槛子绊倒。--《红楼梦》", "example": null}, {"def": "绊 bàn 挡住或缠住，使其跌倒或行走不方便～倒、～手～脚。", "example": null}]','chinese-xinhua','0'),
