('2101143295823450172','蚌','1','bànɡ','虫','10',NULL,'[{"def": "蚌", "example": null}, {"def": "(形声。从虫,丰声。本义一种软体动物。有的能产珍珠)", "example": null}, {"def": "同本义", "example": null}, {"def": "离为蚌。--《易·说卦》", "example": null}, {"def": "蚌方出曝,而鹬啄其肉,蚌合而其喙。--《战国策·燕策》", "example": null}, {"def": "巨 蝝函蛛。--《文选·左思·南都赋》", "example": null}, {"def": "民食果菰 蝝蛤腥臊恶臭。--《韩非子·五蠹》", "example": null}, {"def": "又如蚌蛤(蚌与蛤。长者曰蚌,圆者曰蛤);蚌壳(蚌的外壳)", "example": null}, {"def": "美珠", "example": null}, {"def": "蚌,美珠。--《类篇·虫部》", "example": null}, {"def": "蚌 bàng 软体动物。有两个可以开合的椭圆形贝壳，里面有珍珠层。生活在淡水中，有的种类产珍珠。又见bèng。", "example": null}, {"def": "蚌 bèng又见bàng。", "example": null}, {"def": "【蚌埠】市名。在安徽省。", "example": null}]','chinese-xinhua','0'),
('2101143295823450173','傍','1','bànɡ','亻','12',NULL,'[{"def": "傍", "example": null}, {"def": "(形声。从人,旁声。本义靠近,临近)同本义", "example": null}, {"def": "傍,近也。--《说文》", "example": null}, {"def": "双兔傍地走。--《乐府诗集·木兰诗》", "example": null}, {"def": "又如傍边(靠近边沿);傍通(靠近四方通达之地);傍境(边境);傍户而立", "example": null}, {"def": "傍", "example": null}, {"def": "依附,依靠", "example": null}, {"def": "辅佐", "example": null}, {"def": "四贤傍之。--《新书》", "example": null}, {"def": "顺着;沿着", "example": null}, {"def": "陪随,陪伴", "example": null}, {"def": "傍", "example": null}, {"def": "同旁”。旁边,侧", "example": null}, {"def": "傍,近也。--《说文》。按,与旁别,四旁四方", "example": null}, {"def": "傍 bàng", "example": null}, {"def": "①靠近依山～水。", "example": null}, {"def": "②接近（指时间）～晚。", "example": null}, {"def": "【傍人门户】依赖别人，不能自立。", "example": null}, {"def": "傍páng 1.旁边;侧近。 2.本身之外的，别的。 3.广。见\\"傍通\\"﹑\\"傍接\\"﹑\\"傍概\\"等。 4.汉字的偏旁。 5.偏颇;邪僻。参见\\"傍门\\"。 6.偏斜，仄曲。参见\\"傍蹊\\"。", "example": null}, {"def": "7.见\\"傍午\\"。 8.见\\"傍偟\\"。 9.见\\"傍薄\\"。 10.通\\"方\\"。逆，倒转。参见\\"傍戟\\"。 11.通\\"访\\"。访求。参见\\"傍荐\\"。", "example": null}, {"def": "傍bēng 1.见\\"傍傍\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295823450174','棒','1','bànɡ','木','12',NULL,'[{"def": "棒", "example": null}, {"def": "(形声。从木,奉声。本义棍,杖)", "example": null}, {"def": "同本义", "example": null}, {"def": "人马逼战,刀不如棒。--《魏书·尔朱荣传》", "example": null}, {"def": "又如棒糖;棍棒;棒打鸳鸯(以强硬手段,破坏他人的夫妇关系,或指阻挠男女的婚事)", "example": null}, {"def": "棒", "example": null}, {"def": "用棍棒打", "example": null}, {"def": "其或迟违,则赤棒棒之。--《北齐书·琅琊王(萧)俨传》", "example": null}, {"def": "又如棒杀(用棍棒打死);棒毒(用棒毒打)", "example": null}, {"def": "棒", "example": null}, {"def": "棒 bàng", "example": null}, {"def": "①棍子木～。", "example": null}, {"def": "②（体力或能力）强；（水平）高；（成绩）好身体真～、球踢得太～了、学习真～。", "example": null}, {"def": "【棒操】一种以棒为器械的艺术体操项目。基本动作有摆动、绕环、抛接、打击等。", "example": null}, {"def": "【棒球】", "example": null}, {"def": "①球类运动之一。球场成直角扇形，设四个垒位一垒、二垒、三垒、本垒。分两队比赛，每队9人。两队轮攻1次为1局，共9局，得分多者胜。", "example": null}, {"def": "②棒球运动用的球。球体较小，圆周23厘米左右。橡皮或软木为球芯，缠上线后再用马皮或牛皮缝制而成。", "example": null}]','chinese-xinhua','0'),
('2101143295823450175','棓','1','bànɡ','木','12',NULL,'[{"def": "棓", "example": null}, {"def": "棍,杖。棒”的俗字", "example": null}, {"def": "梿枷", "example": null}, {"def": "棓bàng 1.农具名。即连枷。 2.通\\"棒\\"。棍棒。 3.用杖击。", "example": null}, {"def": "棓pǒu 1.铺设于不平处的跳板。", "example": null}, {"def": "棓bēi 1.古代盛羹注酒之器。", "example": null}, {"def": "棓péi 1.姓『有棓生。见《史记·袁盎晁错列传》。", "example": null}]','chinese-xinhua','0'),
('2101143295823450176','谤','1','bànɡ','讠','12',NULL,'[{"def": "谤", "example": null}, {"def": "(形声兼会意。从言,旁声。本义在背后公开地议论或批评某人的短处)", "example": null}, {"def": "同本义", "example": null}, {"def": "谤,毁也。--《说文》。按,谤者道人之实,事与诬谮不同。大言曰谤,小言曰诽,曰讥。", "example": null}, {"def": "厉王虐,国人谤王。--《国语·周语上》", "example": null}, {"def": "有能谤讥于市朝。--《战国策·齐策》", "example": null}, {"def": "以致天下怨谤也。--宋·王安石《答司马谏议书》", "example": null}, {"def": "又如谤书(攻击别人或揭发别人隐私的文书;亦专指《史记》)", "example": null}, {"def": "诽谤", "example": null}, {"def": "信而见疑,忠而被谤,能无怨乎?--《史记·屈原贾生列传》", "example": null}, {"def": "是故事修而谤兴。--唐·韩愈《原毁》", "example": null}, {"def": "又如谤言(公开指责他人的话。同", "example": null}, {"def": "谤 bàng", "example": null}, {"def": "①公开指责别人的过失厉王虐，国人～王。（《国语·周语上》）", "example": null}, {"def": "②诽谤～书（诽谤人的信件或书籍）。", "example": null}]','chinese-xinhua','0'),
('2101143295823450177','稖','1','bànɡ','禾','13',NULL,'[{"def": "稖头，耜一类的农具。", "example": null}]','chinese-xinhua','0'),
('2101143295823450178','蒡','1','bànɡ','艹','13',NULL,'[{"def": "蒡--牛蒡”多年生草本植物,心脏形叶夏季开紫红色小花,果实瘦小", "example": null}, {"def": "蒡 bàng ［牛蒡］二年生草本植物,叶子是心脏形，初夏开花，紫色，根和嫩叶都可以吃，种子入药。", "example": null}, {"def": "蒡páng 1.草名。一名隐莥。", "example": null}]','chinese-xinhua','0'),
('2101143295823450179','镑','1','bànɡ','钅','15',NULL,'[{"def": "镑", "example": null}, {"def": "(形声。从金,旁声。英国的货币单位。如英镑) 英国、埃及、爱尔兰等的本位货币", "example": null}, {"def": "镑张", "example": null}, {"def": "莫要镑张", "example": null}, {"def": "镑pāng 1.切削。 2.铲子的别名。", "example": null}, {"def": "镑bàng 1.英语pound的音译。英国﹑埃及﹑爱尔兰等国的本位货币。", "example": null}]','chinese-xinhua','0'),
('2101143295823450180','艕','1','bànɡ','','15',NULL,'[{"def": "艕bàng 1.船。 2.两船相并。", "example": null}]','chinese-xinhua','0'),
('2101143295823450181','玤','1','bànɡ','','14',NULL,'[{"def": "玤bàng 1.次于玉的美石。 2.古代地名。春秋虢地，今河南渑池县境。", "example": null}]','chinese-xinhua','0'),
('2101143295823450182','绑','1','bǎnɡ','纟','9',NULL,'[{"def": "绑", "example": null}, {"def": "(形声。从糸,邦声。古无此字。绑”字出现于元、明之间。本义捆,缚)", "example": null}, {"def": "同本义", "example": null}, {"def": "众军向前,用索绑缚住了。--《三国演义》", "example": null}, {"def": "又如绑扎所(军队在战地特设为伤员包扎、治疗的处所);绑缚(捆绑)", "example": null}, {"def": "绑票", "example": null}, {"def": "绑带,绑带儿", "example": null}, {"def": "绑 bāng 用绳、带等缠或捆～腿。", "example": null}, {"def": "【绑架】用强力把人劫走。", "example": null}, {"def": "【绑票】匪徒把人劫走，强迫被绑架者的家属或有某种特殊关系的人用钱去赎。", "example": null}, {"def": "绑bǎng 1.用绳﹑带等缠绕或捆扎。 2.犹绑票。", "example": null}]','chinese-xinhua','0'),
('2101143295823450183','榜','1','bǎnɡ','木','14',NULL,'[{"def": "榜", "example": null}, {"def": "木片", "example": null}, {"def": "载米三十万斛,钱布数十舫,竖榜为城。--《资治通鉴》", "example": null}, {"def": "匾额", "example": null}, {"def": "魏时,凌云殿榜未题而匠者误钉之。--《晋书·王献之传》", "example": null}, {"def": "又如榜题(匾额题字);榜字(写在匾额上的大字)", "example": null}, {"def": "告示应试取录的名单", "example": null}, {"def": "既而试榜出,时所推誉洞房花烛夜,金榜挂名时。--汪洙《喜》", "example": null}, {"def": "皆不在榜。--《宋史·选举志》", "example": null}, {"def": "又如放榜,榜上无名", "example": null}, {"def": "公开张贴的名单、文书、告示", "example": null}, {"def": "鲁达看见众人看榜。--《水浒全传》", "example": null}, {"def": "又如光荣榜;榜示(文告,告示)", "example": null}, {"def": "屋栋", "example": null}, {"def": "榜 bǎng", "example": null}, {"def": "①张贴出的名单光荣～。", "example": null}, {"def": "②旧指文告～文。", "example": null}, {"def": "【榜文】古代的文告。", "example": null}, {"def": "榜bàng 1.船桨。亦代指船。 2.划船。", "example": null}, {"def": "榜bēng 1.矫正弓弩的器具。参见\\"榜檠\\"。 2.古代刑法之一。杖击或鞭打。 3.泛指击打。", "example": null}, {"def": "榜pǎng 1.耪地，用锄翻松土地。参见\\"榜青\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295823450184','牓','1','bǎnɡ','','14',NULL,'[{"def": "牓bǎng 1.牌匾;匾额。 2.指题写匾额。 3.告示;文书。 4.张挂的科举考试中第者名单。 5.张挂榜文或张贴告示﹑诗文等。 6.通\\"妨\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295823450185','膀','1','bǎnɡ','月','14',NULL,'[{"def": "膀", "example": null}, {"def": "(形声。从肉,旁声。本义肩膀)", "example": null}, {"def": "同本义", "example": null}, {"def": "十分腰围膀阔。--《水浒传》", "example": null}, {"def": "又如膀阔腰圆;腰细膀宽", "example": null}, {"def": "臂膀。指肩和肘之间的手臂", "example": null}, {"def": "兽类或家畜腿的上部或前肢和躯干相连的部分", "example": null}, {"def": "肉则羊膀豕胁,脂肤相半。--《初学记》", "example": null}, {"def": "鸟类等的翅膀", "example": null}, {"def": "膀 bǎng", "example": null}, {"def": "①肩膀～大腰圆。", "example": null}, {"def": "②鸟类等的翅膀。又见pāng；páng。", "example": null}, {"def": "【膀臂】比喻得力的帮手。", "example": null}, {"def": "膀（胮）pāng浮肿脸有些～。", "example": null}, {"def": "膀páng", "example": null}, {"def": "膀bàng 1.见\\"膀子吊\\"。", "example": null}]','chinese-xinhua','0'),
