('2101143295827644466','鞴','1','bèi','革','19',NULL,'[{"def": "鞴", "example": null}, {"def": "车絥,覆盖在车轼上的一种饰物", "example": null}, {"def": "絥,《说文》车絥也”。鞴,絥同。--《广韵》", "example": null}, {"def": "鞴", "example": null}, {"def": "把鞍辔等套在马身上。装备车马", "example": null}, {"def": "鞴马宿严霜。--王昌龄《塞上曲》", "example": null}, {"def": "又如鞴马(备驾,装备坐骑);鞴勒(备马)", "example": null}, {"def": "鞴bèi 1.指装备车马，把鞍辔等套在马上。", "example": null}, {"def": "鞴bù 1.见\\"鞴靫\\"。", "example": null}, {"def": "鞴bài 1.鼓风吹火的皮囊。俗称风箱。 2.指鼓鞴吹火使熔化。参见\\"鞴液\\"。 3.指水受压而喷涌奔流。", "example": null}, {"def": "鞴gōu 1.臂套。用皮制成。射箭﹑架鹰时缚于两臂束住衣袖以便动作。 2.用为妇女装饰。 3.谓架(鹰)。 4.皮制鼓风囊。俗称风箱。", "example": null}]','chinese-xinhua','0'),
('2101143295827644467','鐾','1','bèi','金','21',NULL,'[{"def": "鐾", "example": null}, {"def": "在布、皮、石头等物上把刀反复摩擦几下,使锋利", "example": null}, {"def": "鐾 bèi把刀在布、皮、石头等上面反复磨擦，使其锋利～刀。", "example": null}]','chinese-xinhua','0'),
('2101143295827644468','背','1','bèi','月','9',NULL,'[{"def": "背", "example": null}, {"def": "人用脊背驮", "example": null}, {"def": "早背胡霜过戍楼,又随寒日下汀州。--罗邺《雁》", "example": null}, {"def": "又如背粮食;背头(男子头发由鬓角起都向后梳的发式);背锅(方言。驼背)", "example": null}, {"def": "负担;承受", "example": null}, {"def": "背 bēi", "example": null}, {"def": "①（人）用脊背驮～粮食。", "example": null}, {"def": "②负担～了一身债。又见bèi。", "example": null}, {"def": "【背黑锅】受冤枉。", "example": null}, {"def": "背 bèi", "example": null}, {"def": "①躯干的一部分，部位跟胸和腹相对。", "example": null}, {"def": "②某些物体的反面或后部手～、刀～。", "example": null}, {"def": "③背部对着～山面海。", "example": null}, {"def": "④离开离乡～井。", "example": null}, {"def": "⑤躲避没干过～人的事。", "example": null}, {"def": "⑥台词。", "example": null}, {"def": "⑦违背；违犯～信弃义。", "example": null}, {"def": "⑧偏僻那里很～。", "example": null}, {"def": "⑨不顺利～时。", "example": null}, {"def": "⑩听觉不灵耳～。又见bēi。", "example": null}, {"def": "【背道而驰】朝相反的方向走。比喻彼此的方向、目标完全相反。", "example": null}, {"def": "【背井离乡】不得已地离开故乡，在外地生活。又作离乡背井。", "example": null}, {"def": "【背景】", "example": null}, {"def": "①对人物、事件有影响的环境或情况家庭～、历史～。", "example": null}, {"def": "②在戏剧、电影中的布景。", "example": null}, {"def": "③绘画、摄影作品中衬托主体的背后的景物。", "example": null}, {"def": "【背谬】见【悖谬】。", "example": null}, {"def": "【背弃】违背和抛弃～诺言。", "example": null}, {"def": "【背神经管】脊索动物所特有。位于脊索背面的中枢神经系统，呈管状。脊椎动物背神经管的前部膨大成脑。", "example": null}, {"def": "【背水一战】比喻决一死战，死里求生。", "example": null}, {"def": "【背斜】褶曲构造中岩层向上凸突的部分。从岩层的新老关系来看，背斜中心岩层较老，两翼岩层较新。在地形上，背斜形成为山，但受风化剥蚀。也可成为谷。", "example": null}, {"def": "【背信弃义】违背诺言，不讲道义。", "example": null}, {"def": "【背约】违背约定；失信。", "example": null}, {"def": "【背越式跳高】跳高姿势之一。助跑后腾空，使身体转成背对横竿，过竿后肩背落垫。20世纪60年代始盛行。", "example": null}]','chinese-xinhua','0'),
('2101143295827644469','钡','1','bèi','钅','9',NULL,'[{"def": "钡", "example": null}, {"def": "钡餐", "example": null}, {"def": "金属元素。符号ba。原子序数56。碱土金属之一。轻金属。银白色，有延展性有毒的二价碱土族，质软。化学性质活泼，易氧化，焰色反应为黄绿色。用于制焰火、钡合金等，也是精炼铜的去氧剂。存在于重晶石和碳酸钡矿中。可电解熔氯化钡和氯化铵混合物制取。", "example": null}]','chinese-xinhua','0'),
