('2101143295831838723','贲','1','bēn','贝','9',NULL,'[{"def": "贲", "example": null}, {"def": "通奔”。急走;逃亡", "example": null}, {"def": "虎贲三千人。--《孟子·尽心下》", "example": null}, {"def": "卫士旅贲。--《汉书·百官公卿表》", "example": null}, {"def": "下比周贲溃以离上矣。(比周勾结)--《荀子·强国》", "example": null}, {"def": "又如贲溃(奔走溃散)", "example": null}, {"def": "奔流", "example": null}, {"def": "蚕珥丝而商絣绝,贲星坠而渤海决。--《淮南子·天文》", "example": null}, {"def": "又如贲星(流星)", "example": null}, {"def": "贲", "example": null}, {"def": "今名膈膜或横隔膜,膈的古称", "example": null}, {"def": "虎贲勇士", "example": null}, {"def": "令贲士主将皆听城鼓之音而出。--《墨子·备梯》", "example": null}, {"def": "又如贲士(敏捷善战的勇士);贲石(指古代勇士孟贲和石蕃);贲育(", "example": null}, {"def": "贲 bì", "example": null}, {"def": "【贲临】敬辞。光临。", "example": null}, {"def": "贲fén 1.大。参见\\"贲庸\\"﹑\\"贲鼓\\"。 2.三足龟。参见\\"贲j\\"。 3.通\\"坟\\"。典籍;简策。 4.通\\"獖\\"。参见\\"贲彘\\"。", "example": null}, {"def": "贲bēn 1.通\\"奔\\"。奔走。 2.引申为勇。参见\\"贲士\\"。 3.通\\"奔\\"。星之一种，参见\\"贲星\\"。 4.横隔膜。", "example": null}, {"def": "贲fèn 1.通\\"愤\\"。怒气。 2.通\\"坟\\"。隆起。", "example": null}, {"def": "贲lù 1.见\\"贲浑\\"。", "example": null}, {"def": "贲pān 1.见\\"贲禺\\"。", "example": null}, {"def": "贲féi 1.姓。", "example": null}]','chinese-xinhua','0'),
