('2101143295831838728','奔','1','bēn','大','8',NULL,'[{"def": "奔", "example": null}, {"def": "(会意。金文字形,上面从大”(人),象人挥动双手,下面从止”(趾),而且是三个止”,表示快跑。本义快跑)", "example": null}, {"def": "同本义", "example": null}, {"def": "中庭谓之走,大路谓之奔。--《尔雅·释宫》", "example": null}, {"def": "将奔走之。--《左传·昭公三十一年》。注犹赴趣也。”", "example": null}, {"def": "弗迓克奔。--《书·牧誓》", "example": null}, {"def": "猛浪若奔。--吴均《与朱元思书》", "example": null}, {"def": "屠乃奔倚其下。--《聊斋志异·狼三则》", "example": null}, {"def": "又如东奔西跑;奔冲(奔驰,猛冲);奔走呼号(一面奔跑,一面叫喊);奔马;奔驹;奔丧(父母丧,儿女由外地赶回安葬守丧)", "example": null}, {"def": "逃跑,逃亡", "example": null}, {"def": "大奔曰败。--《左传·庄公十一年》", "example": null}, {"def": "得间奔真州。", "example": null}, {"def": "奔 bēn奴隶社会、封建社会中把男女不依照礼教的规定而自相结合称为奔文君夜亡～相如。（《史记·司马相如列传》）", "example": null}, {"def": "②奔走；急跑飞～。", "example": null}, {"def": "③赶紧；赶忙或赶急事～丧。", "example": null}, {"def": "④逃跑东～西逃。又见bèn。", "example": null}, {"def": "【奔驰】（车、马等）飞快地前进。", "example": null}, {"def": "【奔窜】走投无路地乱跑；狼狈逃跑四处～。", "example": null}, {"def": "【奔放】（思想感情、文章气势等）尽情流露；不受拘束她的歌声热情～。", "example": null}, {"def": "【奔丧】得到直系尊亲去世的消息，急忙赶去料理丧事。", "example": null}, {"def": "【奔腾】跳跃着奔跑万马～。", "example": null}, {"def": "【奔突】横冲直撞；奔驰。", "example": null}, {"def": "【奔袭】向距离较远的敌人迅速袭击。", "example": null}, {"def": "【奔泻】（水流）向低处急速地流长江～千里。", "example": null}, {"def": "【奔走】", "example": null}, {"def": "①急走；跑～相告。", "example": null}, {"def": "②为一定目的而到处活动为筹集资金四处～。", "example": null}, {"def": "奔 bèn", "example": null}, {"def": "①直向目的地走去直～教学楼。", "example": null}, {"def": "②介词。朝；向汽车～煤场驶去。", "example": null}, {"def": "③年纪接近（四十、五十等）他已经放下四十～五十岁了。", "example": null}, {"def": "④为某事奔走～戏票。又见bēn(。", "example": null}, {"def": "【奔头】经过努力奋斗，可指望或有希望的前途这一生还有～。", "example": null}, {"def": "奔fèn 1.覆败。", "example": null}]','chinese-xinhua','0'),
('2101143295831838729','甭','1','bénɡ','用','9',NULL,'[{"def": "甭", "example": null}, {"def": "不同”的合音(一般认为是方言词),相当于不用”,不要”", "example": null}, {"def": "甭 béng方言。\\"不用\\"两字的合音。不要；用不着；不必。", "example": null}]','chinese-xinhua','0'),
('2101143295831838730','泵','1','bènɡ','水','9',NULL,'[{"def": "泵", "example": null}, {"def": "音译字。吸入和排除流体的机械。能提升、输送或压缩流体", "example": null}, {"def": "泵 bèng吸入和排出流体的机械。能把流体抽出或压入容器，也能把液体提送到高处。如水泵。又叫唧筒。", "example": null}, {"def": "泵pìn 1.方言。谓水冲激矶石。", "example": null}]','chinese-xinhua','0'),
('2101143295831838731','迸','1','bènɡ','辶','9',NULL,'[{"def": "迸", "example": null}, {"def": "(从辵,并声。辵”(档遵????)意思是在路上行走。本义奔散,走散)", "example": null}, {"def": "同本义", "example": null}, {"def": "督将迸走,死伤过半。--《三国志·满宠传》", "example": null}, {"def": "又如迸豆之疾(像豆子倒入锅内时乱迸那样快);迸窜(逃窜);迸逸(逃窜)", "example": null}, {"def": "涌出;喷射", "example": null}, {"def": "银瓶乍破水浆迸。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如迸泉(涌出的泉水);迸撺(喷涌飞溅);迸放(喷射发出)", "example": null}, {"def": "爆开,断裂", "example": null}, {"def": "打得眼棱缝裂,乌珠迸出。--《水浒传》", "example": null}, {"def": "又如迸穴(迸裂而成的洞穴)", "example": null}, {"def": "冒出,突然向外发出", "example": null}, {"def": "迸 bèng溅出或喷射唾沫星乱～。", "example": null}, {"def": "【迸发】猛然发出～革命激情。", "example": null}, {"def": "【迸裂】破开；裂开而飞溅。", "example": null}, {"def": "迸pēng 1.使;支派。", "example": null}]','chinese-xinhua','0'),
