('2101143295848615988','逼','1','bī','辶','12',NULL,'[{"def": "逼", "example": null}, {"def": "(形声。从辵),畐(鉦??)声。本义接近,靠近)", "example": null}, {"def": "同本义(仅表示空间距离的接近、靠近)", "example": null}, {"def": "逼,近也。--《说文新附》", "example": null}, {"def": "秦兵逼淝水而陈。(陈布阵)--《资治通鉴》", "example": null}, {"def": "鸡健进,逐逼之,虫已在爪下矣。--《聊斋志异·促织》", "example": null}, {"def": "不可偪也。--《国语·郑语》", "example": null}, {"def": "是故入小而不偪。--《淮南子·兵略》", "example": null}, {"def": "逼,近也。--《小尔雅·广诂》", "example": null}, {"def": "又如逼水(迫近水边);逼曙(天快亮的时候);逼战(近战)", "example": null}, {"def": "逼迫,即紧紧催促", "example": null}, {"def": "又荆州之民附操者,逼兵势耳。--《资治通鉴》", "example": null}, {"def": "其家逼之,乃投水而死。--《玉", "example": null}, {"def": "逼 bī", "example": null}, {"def": "①强迫；威胁别～我了。", "example": null}, {"def": "②索要～债。", "example": null}, {"def": "③逼近兵～城郊。", "example": null}, {"def": "④狭窄～仄。", "example": null}, {"def": "【逼宫】旧时指宫廷内部强迫皇帝让位。", "example": null}, {"def": "【逼供】用酷刑或威胁等手段迫使人招供。", "example": null}, {"def": "【逼上梁山】《水浒传》中林冲等人为官府所迫，上梁山造反◇比喻被迫采取反抗行动或做某种事。", "example": null}, {"def": "【逼视】向前靠近目标，紧紧盯着。", "example": null}, {"def": "【逼肖】相像。", "example": null}, {"def": "【逼真】", "example": null}, {"def": "①如同真的形象～。", "example": null}, {"def": "②清楚；切实听得～。", "example": null}, {"def": "【逼仄】地方窄新居虽小，布置得体，也不觉得～。", "example": null}]','chinese-xinhua','0'),
('2101143295848615989','鲾','1','bī','鱼','17',NULL,'[{"def": "鲾", "example": null}, {"def": "鱼名", "example": null}, {"def": "鲾bī 1.鱼名。今指鲾科鱼类。身体小而侧扁，略呈卵圆形，青褐色，口小，鳞细。生活在近海。", "example": null}]','chinese-xinhua','0'),
