('2101143295852810248','熛','1','biāo','火','15',NULL,'[{"def": "熛", "example": null}, {"def": "火星迸飞,也指迸飞的火焰", "example": null}, {"def": "熛,火飞也。从火,票声。--《说文》", "example": null}, {"def": "火烈熛林。--左思《吴都赋》", "example": null}, {"def": "百尺之宝,以突隙之熛焚。--《韩非子》", "example": null}, {"def": "又如熛炭(燃烧着的炭火。熛迸飞的火焰);熛火(火焰);熛矢(带火的箭矢)", "example": null}, {"def": "光", "example": null}, {"def": "海内云蒸,雷动电摽。--《后汉书》。李贤注熛,光也。”", "example": null}, {"def": "通飙”。暴风", "example": null}, {"def": "雷动熛至,星流霆击。--《史记·司马相如列传》", "example": null}, {"def": "胜广熛起,梁籍扇烈。--《汉书·叙传下》", "example": null}, {"def": "又如熛至(指疾风迅猛来临。比喻来势迅猛)", "example": null}, {"def": "熛", "example": null}, {"def": "迅疾", "example": null}, {"def": "气冲郁而熛起。╠", "example": null}, {"def": "熛biāo 1.火焰。 2.赤色。参见\\"熛阙\\"。 3.闪光。 4.焚烧。 5.疾风，暴风。 6.风迅疾貌。", "example": null}]','chinese-xinhua','0'),
('2101143295852810249','膘','1','biāo','月','15',NULL,'[{"def": "膘", "example": null}, {"def": "肥肉", "example": null}, {"def": "膘,牛胁后髀前合革肉也。从肉,票声。--《说文》", "example": null}, {"def": "自膘而射之。--《诗·车攻传》", "example": null}, {"def": "马无他损,特膘稍落,微磨破耳。(特仅仅,只。)--李新《与冯德夫》", "example": null}, {"def": "又如膘肥体壮(形容牲畜肥壮结实);膘息(指牲畜的肥硕处)", "example": null}, {"def": "膘情", "example": null}, {"def": "膘实,骠实", "example": null}, {"def": "这匹马很膘实", "example": null}, {"def": "膘壮", "example": null}, {"def": "牧场上膘壮的马群在嬉戏追逐", "example": null}, {"def": "膘piǎo 牲畜小腹两边之肉。", "example": null}, {"def": "膘biāo", "example": null}, {"def": "①畜兽肥壮或其肥壮之处。", "example": null}, {"def": "② 指人肥壮。", "example": null}, {"def": "③方言。聚精会神;盯住或缠住不放。", "example": null}, {"def": "④用同\\"鱞\\"。鱼类体内可胀缩的囊状物", "example": null}, {"def": "【膘肥】 牲畜肉膘肥实。", "example": null}, {"def": "【膘肥體壯】 形容牲畜肥壮结实。", "example": null}, {"def": "【膘息】 指牲畜的肥硕处。", "example": null}, {"def": "【膘情】 牲畜长膘的情况。", "example": null}, {"def": "【膘膠】即鳔胶。", "example": null}]','chinese-xinhua','0'),
('2101143295852810250','麃','1','biāo','鹿','15',NULL,'[{"def": "麃", "example": null}, {"def": "假借为穮。耕耘", "example": null}, {"def": "厌厌其苗,绵绵麃其。--《诗·周颂·载芟》", "example": null}, {"def": "麃páo 1.即狍。 2.麋鹿。", "example": null}, {"def": "麃biāo 1.见\\"麃麃\\"。 2.通\\"穮\\"。耕耘。 3.秦邑名。参见\\"麃邑\\"。 4.姓。", "example": null}, {"def": "麃piǎo 1.鸟毛变色。泛指变色。", "example": null}]','chinese-xinhua','0'),
