('2101143295852810288','髌','1','bìn','骨','19',NULL,'[{"def": "髌膝盖骨。", "example": null}, {"def": "古代除去膝盖骨的酷刑。", "example": null}, {"def": "髌 bìn", "example": null}, {"def": "①古代一种削去膝盖骨的酷刑孙子～脚。（司马迁《报任少卿书》）", "example": null}, {"def": "②髌骨膝盖部的一块骨，略呈三角形，尖端朝下。又叫膝盖骨。", "example": null}]','chinese-xinhua','0'),
('2101143295852810289','鬓','1','bìn','髟','20',NULL,'[{"def": "鬓", "example": null}, {"def": "(形声。从髟),宾声。髟”,意思是头发长。髟”的字多与毛发有关。本义颊发。两颊两旁近耳的头发) 同本义", "example": null}, {"def": "鬓,颊发也。--《说文》", "example": null}, {"def": "美鬓长大则贤。--《国语·晋语》", "example": null}, {"def": "连发曰鬓。--《释名》", "example": null}, {"def": "两鬓苍苍十指黑。--唐·白居易《卖炭翁》", "example": null}, {"def": "少小离家老大回,乡音无改鬓毛衰。--唐·贺知章《回乡偶书》", "example": null}, {"def": "又如鬓影(面颊两旁近耳的头发);鬓发霜侵(鬓发花白)", "example": null}, {"def": "鬓发", "example": null}, {"def": "鬓角", "example": null}, {"def": "鬓脚", "example": null}, {"def": "鬓 bìn鬓角。耳朵前边长头发的部位。也指长在那里的头发双～斑白。", "example": null}]','chinese-xinhua','0'),
('2101143295852810290','镔','1','bīn','钅','15',NULL,'[{"def": "镔", "example": null}, {"def": "冶炼质量很高的金属铁", "example": null}, {"def": "三尺镔刀耀雪光。--洪昻《长生殿》", "example": null}, {"def": "襢瑮蝩郿嬲眀", "example": null}, {"def": "镔bīn 1.精铁。 2.见\\"镔芬\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295852810291','濒','1','bīn','氵','16',NULL,'[{"def": "濒", "example": null}, {"def": "(形声。从水,频声。本义水边) 同本义", "example": null}, {"def": "是故昔者舜耕于历山,陶于河濒。--《墨子·尚贤》", "example": null}, {"def": "行举濒河之郡。--《汉书·成帝纪》。师古曰滨,水涯也。”", "example": null}, {"def": "濒海之观毕至。--《汉书·贾山传》", "example": null}, {"def": "濒", "example": null}, {"def": "靠近;临近", "example": null}, {"def": "濒南山,近夏阳。--《汉书·地理志》", "example": null}, {"def": "又如濒危;濒近;濒于(亦作濒於”。指临近某种坏的遭遇)", "example": null}, {"def": "濒 bīn接近南～长江、～临绝境。", "example": null}, {"def": "【濒临】紧接～太平洋、～崩溃。", "example": null}, {"def": "【濒危】接近危难。", "example": null}]','chinese-xinhua','0'),
