('2101143295852810302','滨','1','bīn','氵','13',NULL,'[{"def": "滨", "example": null}, {"def": "(形声。从水,宾声。本义水边)", "example": null}, {"def": "湖、河、海的水边陆地", "example": null}, {"def": "南涧之滨。--《诗·召南·采蘯》", "example": null}, {"def": "率土之滨。--《诗·小雅·北山》。传滨,涯也。”", "example": null}, {"def": "海滨广斥。--《书·禹贡》", "example": null}, {"def": "屈原至于江滨。--《史记·屈原贾生列传》", "example": null}, {"def": "又如湘江之滨;溪滨;滨涯(水边);湖滨;海滨", "example": null}, {"def": "古州名", "example": null}, {"def": "姓", "example": null}, {"def": "滨", "example": null}, {"def": "通濒”。靠近;临近", "example": null}, {"def": "夫管夷吾射寡人中钩,是以滨于死。--《", "example": null}, {"def": "滨 bīn", "example": null}, {"def": "①水边；近水的地方东海之～。", "example": null}, {"def": "②靠近（水边）～河路。", "example": null}]','chinese-xinhua','0'),
('2101143295852810303','缤','1','bīn','纟','13',NULL,'[{"def": "缤", "example": null}, {"def": "(形声。从糸,宾声。本义繁盛,众多)", "example": null}, {"def": "同本义", "example": null}, {"def": "芳草鲜美,落英缤纷。--晋·陶渊明《桃花源记》", "example": null}, {"def": "又如缤翻(繁盛的样子)", "example": null}, {"def": "紊乱", "example": null}, {"def": "时缤纷其变易兮。--《楚辞·屈原·离骚》", "example": null}, {"def": "又如缤乱(杂乱);缤纷(纷乱的样子;纷飞的样子);缤缤(飞的样子)", "example": null}, {"def": "缤 bīn", "example": null}, {"def": "【缤纷】繁多而杂乱的样子彩旗～。", "example": null}]','chinese-xinhua','0'),
