('2101143295852810331','柄','1','bǐnɡ','木','9',NULL,'[{"def": "柄", "example": null}, {"def": "(形声。从木,丙声。本义器物的把儿)", "example": null}, {"def": "同本义", "example": null}, {"def": "柄,柯也。(柯斧柄。)--《说文》", "example": null}, {"def": "覆之南柄。--《仪礼·少牢礼》", "example": null}, {"def": "有柄。--《仪礼·大射礼》", "example": null}, {"def": "柄(铁椎把)铁折叠环复。--明·魏禧《大铁椎传》", "example": null}, {"def": "又如柄子(方言。器物的把儿);刀柄;勺柄;曲柄(曲轴的弯曲部分)", "example": null}, {"def": "权力", "example": null}, {"def": "而皇上无寸柄。--清·梁启超《谭嗣同传》", "example": null}, {"def": "又如权柄(所掌握的权力);柄用(被重用而掌握大权);柄令(权柄;命令)", "example": null}, {"def": "植物的花、叶、果和枝茎相连的部分", "example": null}, {"def": "比喻言行上被人抓住的缺点、漏洞", "example": null}, {"def": "根本", "example": null}, {"def": "柄 bǐng", "example": null}, {"def": "①器具的把锄～。", "example": null}, {"def": "②植物的花、叶或果实与茎或枝连着的部分花～、叶～。", "example": null}, {"def": "③比喻言行上的短处把～、话～。", "example": null}, {"def": "④执掌～政。", "example": null}, {"def": "⑤权国～。", "example": null}, {"def": "⑥量词。两～斧子。", "example": null}]','chinese-xinhua','0'),
('2101143295852810332','炳','1','bǐnɡ','火','9',NULL,'[{"def": "炳", "example": null}, {"def": "(形声。从火,丙声。本义光明,明亮)", "example": null}, {"def": "同本义", "example": null}, {"def": "炳,明也。--《说文》", "example": null}, {"def": "其文炳也。--《易·革》", "example": null}, {"def": "炳炳,明也。--《广雅》", "example": null}, {"def": "大汉之文章炳然与三代同风 。--班固《两都赋》", "example": null}, {"def": "又如炳著(光明显著);炳焕(光明显耀);炳映(光芒照耀);炳然(光明、明白的样子);炳耀(光耀明亮)", "example": null}, {"def": "显著;明显;昭著", "example": null}, {"def": "炳", "example": null}, {"def": "点燃", "example": null}, {"def": "古人思炳烛夜游。--《与吴质书》", "example": null}, {"def": "炳烛之明,熟与昧行乎。--刘向《说苑》", "example": null}, {"def": "又如炳烛(点燃烛火以照明)", "example": null}, {"def": "显示,显现", "example": null}, {"def": "炳 bǐng光辉；显著彪～千秋。", "example": null}]','chinese-xinhua','0'),
