('2101143295857004600','播','1','bō','扌','15',NULL,'[{"def": "播", "example": null}, {"def": "(形声。从手,番声。本义撒种)", "example": null}, {"def": "同本义", "example": null}, {"def": "播,种也。--《说文》", "example": null}, {"def": "其始播百谷。--《诗·豳风 ·七月》", "example": null}, {"def": "播时百谷,--《书·舜典》", "example": null}, {"def": "周弃能播殖百谷蔬。--《国语·郑语》", "example": null}, {"def": "又如条播;夏播;播田(种田;种植);播植(播种;种植);播谷(播种谷物)", "example": null}, {"def": "散布开去,散布得开而远;传布", "example": null}, {"def": "播于诸侯。--《左传·昭公四年》", "example": null}, {"def": "道大名播。--柳宗元《三戒》", "example": null}, {"def": "又如广播;播音;播名(传扬名声)", "example": null}, {"def": "分佈;散布", "example": null}, {"def": "又北播为九河。--《书·禹贡》", "example": null}, {"def": "播余香而莫闻。--张衡《思", "example": null}, {"def": "播 bō", "example": null}, {"def": "①传播～送。", "example": null}, {"def": "②播种秋～。", "example": null}, {"def": "③搬迁；流亡～迁（迁徙）。", "example": null}, {"def": "【播报员】播音员。", "example": null}, {"def": "【播弄是非】挑拨是非。", "example": null}, {"def": "播bǒ 1.摇，簸扬。", "example": null}, {"def": "播fān 1.通\\"藩\\"。 2.通\\"幡\\"。", "example": null}]','chinese-xinhua','0'),
