('2101143295857004622','怖','1','bù','忄','8',NULL,'[{"def": "怖", "example": null}, {"def": "(形声。从心,布声。《说文》作‘悑’”。本义惶恐,惊惧)", "example": null}, {"def": "同本义", "example": null}, {"def": "昔者纣为象箸而箕子怖。--《韩非子·喻老》", "example": null}, {"def": "吾畏其卒,故怖其始。", "example": null}, {"def": "焦心怖肝。--《淮南子·脩务》", "example": null}, {"def": "神心怖覆。--《文选·宋玉·神女赋》", "example": null}, {"def": "又如恐怖(由于生命受到威胁而引起的恐惧);怖畏(恐惧);怖怯(胆小害怕;恐惧);怖覆(恐怖而反复);怖肝(戒惧);怖沮(恐惧沮丧)", "example": null}, {"def": "恐吓", "example": null}, {"def": "依托鬼神,诈怖愚民。--《后汉书》", "example": null}, {"def": "怖bù", "example": null}, {"def": "①惊惧，害怕。", "example": null}, {"def": "②恐吓。", "example": null}, {"def": "【怖忌】畏忌。", "example": null}, {"def": "【怖沮】恐惧沮丧。", "example": null}, {"def": "【怖怯】胆小害怕;恐惧。", "example": null}, {"def": "【怖畏】", "example": null}, {"def": "①亦作\\"怖愄\\"。", "example": null}, {"def": "②恐惧。", "example": null}, {"def": "【怖恐】恐怖，害怕。", "example": null}, {"def": "【怖栗】", "example": null}, {"def": "①亦作\\"怖慄\\"。", "example": null}, {"def": "②害怕得发抖。", "example": null}, {"def": "【怖悸】惊惧。", "example": null}, {"def": "【怖愄】见\\"怖畏\\"。", "example": null}, {"def": "【怖慄】见\\"怖栗\\"。", "example": null}, {"def": "【怖慴】恐惧。", "example": null}, {"def": "【怖駭】惊恐。", "example": null}, {"def": "【怖頭】谓迷失真性而惑于妄相。语本《楞严经》卷四\\"汝豰不聞室羅城中演若達多，忽於晨朝以鐁照面，愛鐁中頭，眉目可見，瞋責己頭，不見面目，以爲魑魅，無狀怖走。", "example": null}, {"def": "\\"", "example": null}, {"def": "【怖遽】惊惶。", "example": null}, {"def": "【怖鴿】佛教传说一鸽为鹰所逐，飞向佛旁，佛以身影蔽鸽，鸽乃不怖。见《涅槃经》卷二八﹑《大智度论》卷十一◇诗文中常以\\"怖鴿\\"为穷无所归的典故。", "example": null}, {"def": "【怖懾】恐惧。", "example": null}, {"def": "【怖懼】恐惧;惶恐。", "example": null}]','chinese-xinhua','0'),
