('2101143295857004651','庯','1','bū','广','10',NULL,'[{"def": "庯--庯峭” 同峬峭”", "example": null}, {"def": "庯bū 1.平顶屋。 2.见\\"庯峭\\"﹑\\"庯庩\\"。 3.石门。", "example": null}]','chinese-xinhua','0'),
('2101143295857004652','逋','1','bū','辶','10',NULL,'[{"def": "逋", "example": null}, {"def": "(形声。从辵),甫声。逋的原始意义是奴隶逃亡。本义逃亡,逃跑)", "example": null}, {"def": "同本义", "example": null}, {"def": "逋,亡也。--《说文》", "example": null}, {"def": "乃惟四方之多罪逋逃,是崇是长。--《书·牧誓》", "example": null}, {"def": "于伐殷逋播臣。--《书·大诰》", "example": null}, {"def": "为天下逋逃主。--《书·武臣》", "example": null}, {"def": "六年其逋。--《左传·僖公十五年》", "example": null}, {"def": "狼失声而逋。--明·马中锡《中山狼传》", "example": null}, {"def": "又如逋臣(逃亡的大臣);逋逃薮(逃亡的罪犯或流亡者聚集的地方);逋客(逃亡的人;避世的人)", "example": null}, {"def": "拖欠,欠税", "example": null}, {"def": "逋租宿债勿复收。--沈约《宋书》", "example": null}, {"def": "又如逋债(拖延付债);逋租(拖欠租税)", "example": null}, {"def": "懈怠;拖延", "example": null}, {"def": "逋 bū", "example": null}, {"def": "①逃；逃亡～逃。", "example": null}, {"def": "②拖欠～债。", "example": null}]','chinese-xinhua','0'),
('2101143295857004653','钸','1','bū','钅','10',NULL,'[{"def": "钸", "example": null}, {"def": "金属板", "example": null}, {"def": "饰,金版。--《玉篇》", "example": null}, {"def": "钸bū 1.金版。", "example": null}]','chinese-xinhua','0'),
('2101143295857004654','晡','1','bū','日','11',NULL,'[{"def": "晡", "example": null}, {"def": "(形声。从日,甫声。本义申时(等于现在下午三时至五时))", "example": null}, {"def": "申时,即午后三时至五时", "example": null}, {"def": "晡时,门坏。元济于城上请罪,进城梯而下之。--《资治通鉴·唐纪》", "example": null}, {"def": "贺发,晡时至定陶。--汉·班固《汉书》", "example": null}, {"def": "傍晚", "example": null}, {"def": "晡bū 1.申时，即十五时至十七时。 2.傍晚;夜。 3.指太阳西移至晡时的视觉位置。", "example": null}]','chinese-xinhua','0'),
