('2101143295861198899','藏','1','cánɡ','艹','17',NULL,'[{"def": "藏", "example": null}, {"def": "(形声,臧声。本义把谷物保藏起来)", "example": null}, {"def": "储积,收藏", "example": null}, {"def": "农夫春耕夏耘,秋敛冬藏。--《墨子·三辩》", "example": null}, {"def": "子不闻藏书者乎?--清·袁枚《黄生借书说》", "example": null}, {"def": "又如矿藏;收藏(收集保藏)", "example": null}, {"def": "隐匿", "example": null}, {"def": "藏,匿也。--《说文新附》", "example": null}, {"def": "慢藏海盗。--《易·系辞上》", "example": null}, {"def": "即藏其尸,持童抵主人所。--唐·柳宗元《童区寄传》", "example": null}, {"def": "见瓶水之冰,而知天下之寒,鱼鳖之藏也。--《吕氏春秋·察今》", "example": null}, {"def": "又如藏掩(遮盖,隐瞒);藏拙(因怕丢丑而不显露自己的技能和意见);藏娇(把娇娃藏起来。指娶妾别居);藏名(隐匿名声)", "example": null}, {"def": "怀有", "example": null}, {"def": "藏 cāng", "example": null}, {"def": "①～隐蔽埋～。", "example": null}, {"def": "②收存；储藏～书。又见zàng。", "example": null}, {"def": "【藏垢纳污】比喻包容种种坏人坏事。又作藏污纳垢。", "example": null}, {"def": "【藏奸】～心怀恶意。", "example": null}, {"def": "②不肯拿出全部精力或不肯尽力帮助人～耍滑。", "example": null}, {"def": "【藏龙卧虎】比喻潜藏着的未被发现的人才。", "example": null}, {"def": "【藏匿】隐藏起来不让人发现。", "example": null}, {"def": "【藏头露尾】形容躲躲闪闪，不把真实情况全都摊出来。", "example": null}, {"def": "【藏污纳垢】见【藏垢纳污】。", "example": null}, {"def": "【藏掖】", "example": null}, {"def": "①怕人知道或发现而竭力掩藏～躲闪。", "example": null}, {"def": "②掩饰住的弊端他办事可从来没有～。", "example": null}, {"def": "【藏拙】怕出丑，不肯让别人知道自己的看法或技能。常用为自谦之辞。", "example": null}, {"def": "藏zàng", "example": null}, {"def": "⒈储存东西的地方库～。宝～。", "example": null}, {"def": "⒉道教、佛教经典的统称道～。大～经。", "example": null}, {"def": "⒊", "example": null}, {"def": "①佛教经典\\"经、律、论\\"三部分。", "example": null}, {"def": "②唐玄奘号\\"三藏法师\\"。", "example": null}, {"def": "⒋西藏自治区的简称。", "example": null}, {"def": "⒌", "example": null}, {"def": "藏cáng 1.隐藏;潜匿。 2.收藏;储藏。 3.怀，藏在心中。 4.深，从上到下或从外到里的距离大。", "example": null}, {"def": "藏zāng 1.草名。 2.通\\"臧\\"。善。 3.通\\"赃\\"。窝主。", "example": null}]','chinese-xinhua','0'),
