('2101143295865393152','沧','1','cānɡ','氵','7',NULL,'[{"def": "沧", "example": null}, {"def": "(形声。从水,仓声。本义寒冷)", "example": null}, {"def": "同凔”‘冷", "example": null}, {"def": "沧,寒也。--《说文》", "example": null}, {"def": "天地之间有沧热。--《周书·周祝》", "example": null}, {"def": "疾养滄热,滑铍轻重以形体异。--《荀子·正名》", "example": null}, {"def": "欲汤之滄,一人炊之,百人扬之,无益也,不如绝薪止火而已。--《汉书·枚乘传》", "example": null}, {"def": "日初出,沧沧凉凉。--《列子·汤问》", "example": null}, {"def": "又如沧凉(寒凉;寒冷);沧热(寒冷与炎热)", "example": null}, {"def": "通苍”。水深绿色", "example": null}, {"def": "沧", "example": null}, {"def": "州名", "example": null}, {"def": "沧 cāng（水）暗绿色～海。", "example": null}, {"def": "【沧海桑田】大海变成农田，农田变为大海。比喻世事变化很大。", "example": null}, {"def": "【沧海一粟】大海里的一颗谷粒。比喻非常渺小集体的力量是无穷的，个人的力量只不过是～。", "example": null}, {"def": "【沧桑】\'沧海桑田\'的略语历尽～。", "example": null}]','chinese-xinhua','0'),
('2101143295865393153','苍','1','cānɡ','艹','7',NULL,'[{"def": "苍", "example": null}, {"def": "(形声。从苃,仓声。本义草色)", "example": null}, {"def": "同本义,引申为青黑色", "example": null}, {"def": "苍,草色也。--《说文》", "example": null}, {"def": "苍,青也。--《广雅》", "example": null}, {"def": "在色为苍。--《素问·阴阳应象大论》。注谓薄青色。”", "example": null}, {"def": "彼苍者天。--《诗·秦风·黄鸟》", "example": null}, {"def": "春为苍天。--《尔雅·释天》", "example": null}, {"def": "东方曰苍天。--《吕氏春秋·有始》", "example": null}, {"def": "驾苍龙。--《礼记·月令孟春》。注苍亦青也。”", "example": null}, {"def": "染于苍则苍,染于黄则黄。--《墨子·所染》", "example": null}, {"def": "又如苍山(青山);苍苔(青苔);苍头(旧指仆人『时奴仆皆以深青色巾包头,故名;又指老年人)", "example": null}, {"def": "灰白色", "example": null}, {"def": "满面尘灰烟火色,两鬓苍苍十指黑。╠", "example": null}, {"def": "苍 cāng", "example": null}, {"def": "①青色～松。", "example": null}, {"def": "②灰白色，面色～白。", "example": null}, {"def": "③姓。", "example": null}, {"def": "【苍白】", "example": null}, {"def": "①灰白；（脸）没有血色面色～。", "example": null}, {"def": "②形容缺乏旺盛的生命力～无力。", "example": null}, {"def": "【苍苍】", "example": null}, {"def": "①灰白色两鬓～。", "example": null}, {"def": "②苍茫天～，野茫茫。", "example": null}, {"def": "【苍翠】（草木等）深绿～欲滴。", "example": null}, {"def": "【苍黄】见【仓黄】。", "example": null}, {"def": "【苍劲】（树木、书法、绘画等）雄健挺拔。", "example": null}, {"def": "【苍凉】悲凉。", "example": null}, {"def": "【苍茫】空阔辽远；无边无际暮色～。", "example": null}, {"def": "【苍莽】苍茫。", "example": null}, {"def": "【苍穹】天空。又作穹苍。", "example": null}, {"def": "【苍生】古时指老百姓。", "example": null}, {"def": "【苍术】菊科，多年生草本植物。花白色或淡红色。其根茎含挥发油及较多量的维生素a、b，有健胃作用。分布于我国浙江、江苏、安徽等省。", "example": null}, {"def": "苍cǎng 1.见\\"苍莽\\"。", "example": null}]','chinese-xinhua','0'),
