('2101143295865393182','册','1','cè','丿','5',NULL,'[{"def": "册", "example": null}, {"def": "(象形。金文、小篆字形与甲骨文相似,象简册形。本义书简。古代文书用竹简。编简名为册,后凡簿籍均可称册”)", "example": null}, {"def": "同本义", "example": null}, {"def": "册,符命也。诸侯进受于王者。象其札,一长一短,中有二编之形。古文又从竹。--《说文》", "example": null}, {"def": "经传多以策为之,字俗作筴", "example": null}, {"def": "史乃册祝。--《书·金滕》", "example": null}, {"def": "公归,乃纳册于金滕之匮中。", "example": null}, {"def": "王命作册。--《书·洛诰》", "example": null}, {"def": "有册有典。--《书·多士》", "example": null}, {"def": "又如名册;画册;纪念册;册书(史籍,史书)", "example": null}, {"def": "古时称编串好的许多竹简,现在指装订好的纸本子", "example": null}, {"def": "特指皇帝的诏书", "example": null}, {"def": "册 cè", "example": null}, {"def": "①装订好的本子手～、名～。", "example": null}, {"def": "②量词。本三～书。", "example": null}, {"def": "【册封】中国古代帝王用于封爵、册立时的仪式和制度。以册书、册命的形式颁布册立、封赠、任命等事宜，在被封赠者面前宣读，然后连同印玺等物一起交予受封者。", "example": null}]','chinese-xinhua','0'),
('2101143295865393183','侧','1','cè','亻','8',NULL,'[{"def": "侧", "example": null}, {"def": "(形声。从人,则声。本义旁边)", "example": null}, {"def": "同本义。亦用作谦词", "example": null}, {"def": "侧,旁也。--《说文》", "example": null}, {"def": "居侧室。--《礼记·内则》。注谓夹之室次燕寝也。”", "example": null}, {"def": "立于侧阶。--《书·顾命》", "example": null}, {"def": "倾容幸而待侧。--《楚辞·思古》", "example": null}, {"def": "有泉侧出。--宋·王安石《游褒禅山记》", "example": null}, {"def": "又如左侧;右侧;侧闻(谦词。表示从旁听到);侧畔(旁边)", "example": null}, {"def": "边缘", "example": null}, {"def": "坎坎伐辐兮,置之河之侧兮。--《诗·魏风·伐檀》", "example": null}, {"def": "铸钟官赤侧。--《史记·平准书》。集解以赤铜为其廓也。”", "example": null}, {"def": "侧", "example": null}, {"def": "向旁边歪斜", "example": null}, {"def": "樊哙侧其盾以撞。--《史记·项羽本纪》", "example": null}, {"def": "侧弁之俄", "example": null}, {"def": "侧 cě", "example": null}, {"def": "①旁边～面、两～。", "example": null}, {"def": "②向一边歪斜～目、～耳细听、～重效果。又见zè。", "example": null}, {"def": "【侧锋】〈美〉中国画技法。运笔时笔头向左右倾斜，使笔尖、笔腰、笔根同时发挥作用。兼有粗、细、浓、淡、干、湿等变化。常用于中国画的意笔画。又称偏锋。", "example": null}, {"def": "【侧棱】棱柱或棱台的两个侧面的公共边。", "example": null}, {"def": "【侧面】", "example": null}, {"def": "①旁边的一面（区别于\'正面\'）从、了解。", "example": null}, {"def": "②〈数〉在几何图形中，区别于底面或正面的各个面（平面或曲面）。如棱柱的侧面（平面）、圆柱的侧面（曲面）等。", "example": null}, {"def": "【侧面积】侧面的面积。", "example": null}, {"def": "【侧目】不敢正视，斜着眼睛看。形容害怕而又愤恨～而视。", "example": null}, {"def": "【侧线】〈生〉动物身体两侧，排列成直线形的一种构造。某些蛔虫的侧线由外胚层所形成，排泄管由此通过。鱼类及水生两栖类动物的侧线能感觉水流振动及声音。", "example": null}, {"def": "【侧芽】生在叶腋、尚未发育成长的枝或花的雏体。又叫腋芽。", "example": null}, {"def": "【侧泳】一种游泳姿势。游时侧卧水面，两手臂轮流划水。", "example": null}, {"def": "【侧足】、形容因畏惧而不敢对面站立～而立。", "example": null}, {"def": "②置足；落脚。", "example": null}, {"def": "侧zè", "example": null}, {"def": "⒈［侧声］即\\"仄声\\"，见 \\"仄", "example": null}, {"def": "⒋\\"。", "example": null}, {"def": "侧zhāi", "example": null}, {"def": "⒈斜着～歪（歪斜）。～棱（向一边倾斜）。", "example": null}, {"def": "侧cè 1.旁边。 2.用作谦词。 3.倾斜。 4.不公正;不正派。 5.僻远。 6.独;特。 7.瘗埋。《左传．襄公二十五年》\\"崔氏侧庄公于北郭。\\"杜预注\\"侧，瘗埋之。\\"", "example": null}, {"def": "清袁枚《随园随笔．诸经》\\"三《传》多古字，余尝戏集之。在《左氏》则……埋曰侧。\\"一说侧为厕。清汪中《经义知新记》\\"襄十五年《传》\'崔氏侧庄公于北郭。\'侧与", "example": null}, {"def": "厕同。\\" 8.藏伏。 9.轻微。 10.汉字笔画中\\"点\\"的古称。参见\\"永字八法\\"。 11.通\\"恻\\"。悲伤。", "example": null}]','chinese-xinhua','0'),
('2101143295865393184','厕','1','cè','厂','8',NULL,'[{"def": "厠", "example": null}, {"def": "(形声。从厂),则声。厂”,小篆字形象山崖,可以住人。厂”作为汉字部首之一,常与广”(?", "example": null}, {"def": "同本义", "example": null}, {"def": "厠,杂也。言人杂厠在上非一也。--《释名·释宫室》", "example": null}, {"def": "沛公起如厕。--《史记·项羽本纪》", "example": null}, {"def": "又如男厕;女厕;厕屋(厕溷。厕所);厕筹(厕简。大便后用来拭粪的小木片片)", "example": null}, {"def": "假借为侧”。旁边", "example": null}, {"def": "上踞厠视之。--《汉书·汲黯传》。注厠,床边侧也。”", "example": null}, {"def": "居霸陵,北临厠。--《汉书·刘向传》。注厠,侧近水也。”", "example": null}, {"def": "上居外临厠。--《汉书·张释之传》。", "example": null}, {"def": "厕 cè", "example": null}, {"def": "①厕所。专供人们大小便的处所公～、男～。", "example": null}, {"def": "②夹杂在里面；参与～身（谦辞，指参与某一部门工作）。又见·si。", "example": null}, {"def": "【厕足其间】插足到那里边。指参与了某件事。", "example": null}]','chinese-xinhua','0');
