('2101143295873781760','恻','1','cè','忄','9',NULL,'[{"def": "恻", "example": null}, {"def": "(形声。从心,则声。本义悲痛)", "example": null}, {"def": "同本义", "example": null}, {"def": "恻,痛也。--《说文》", "example": null}, {"def": "恻,悲也。--《广雅》", "example": null}, {"def": "井渫不食,为我心恻。--《易·井》", "example": null}, {"def": "朕恻焉不忍闻。--《汉书·淮南宪王钦传》", "example": null}, {"def": "岂有肯加恻隐于细民?--《汉书·鲍宣传》", "example": null}, {"def": "又如凄恻(哀伤;悲痛);恻痛(忧伤,悲痛)", "example": null}, {"def": "恳切", "example": null}, {"def": "又如恻恻(诚恳;恳切)", "example": null}, {"def": "恻 cè哀痛；悲伤凄～、～隐之心。", "example": null}, {"def": "【恻隐之心】对受苦难的人表示同情的心意。", "example": null}]','chinese-xinhua','0'),
('2101143295873781761','测','1','cè','氵','9',NULL,'[{"def": "测", "example": null}, {"def": "(形声。从水,则声。本义度量水的深浅)", "example": null}, {"def": "度量;测量", "example": null}, {"def": "测,深所至也。--《说文》", "example": null}, {"def": "测土深。--《周礼·大司徒》。注犹度也。”", "example": null}, {"def": "穷高极远,而深深厚。--《礼记·乐记》。疏知也。”", "example": null}, {"def": "毋测未至。--《礼记·少仪》。注意度也。”", "example": null}, {"def": "抑欲测吾心也。--《国语·晋语》。注度也。”", "example": null}, {"def": "大不可量,深不可测。--《韩非子·主道》", "example": null}, {"def": "又如测海(测量海水的深浅。比喻浅薄无知);测景(度量日影);测汽车的速度;测房子的高度;测地(测定土地的广狭、高低);测步(测量)", "example": null}, {"def": "观测,观察", "example": null}, {"def": "夜则测阴,昼则测阳。--《太玄经", "example": null}, {"def": "测 cè", "example": null}, {"def": "①测量；观察～绘（测量和绘图）、～定（测量和确定）。", "example": null}, {"def": "②测度观～。", "example": null}, {"def": "【测交】〈生〉最早由孟德尔设计的一种实验方法。是用杂种或杂种后代与纯合型隐性亲本交配，用以测定杂种或杂种后代基因型。", "example": null}, {"def": "【测量学】研究在地球表面测定地面点的相互位置与高程、绘成各种地图或确定地球形状与大小的一门科学。包括大地测量学、地形测量学、摄影测量学、工程测量学和海道测", "example": null}, {"def": "量学等。", "example": null}, {"def": "【测算】测量并计算。", "example": null}, {"def": "【测验赛】为达到一定的标准或了解运动员素质和水平提高情况而组织的竞赛。", "example": null}, {"def": "【测字】将汉字的偏旁部首拆开或合并，作出各种解说来推算凶吉。是一种迷信做法。又叫拆字。", "example": null}]','chinese-xinhua','0'),
('2101143295873781762','敇','1','cè','攵','10',NULL,'[{"def": "姓", "example": null}, {"def": "敇cè 1.鞭策马◇作\\"策\\"。 2.姓。", "example": null}]','chinese-xinhua','0'),
('2101143295873781763','箣','1','cè','竹','14',NULL,'[{"def": "箣竹", "example": null}, {"def": "箣cè 1.同\\"策\\"。占卜。 2.竹名。箣竹。又名大簕竹√本科植物。秆丛生，表面粗糙，每节生多枝，其下方小枝短硬化成刺形。分布于我国福建﹑台湾﹑广东﹑广西等地。", "example": null}]','chinese-xinhua','0'),
