('2101143295877976064','层','1','cénɡ','尸','7',NULL,'[{"def": "层", "example": null}, {"def": "(形声。从尸,尸者象屋形,从屋省。本义楼房)", "example": null}, {"def": "同本义", "example": null}, {"def": "层,重屋也。--《说文》", "example": null}, {"def": "珠殿连云,金层辉景。--刘孝绰《栖隐寺碑》", "example": null}, {"def": "又如层楹(高楼大厦)", "example": null}, {"def": "构成整个事物的一个层次", "example": null}, {"def": "层", "example": null}, {"def": "重叠", "example": null}, {"def": "高堂邃宇,槛层轩些。--《楚辞·招魂》", "example": null}, {"def": "又", "example": null}, {"def": "层台累榭。", "example": null}, {"def": "巡曾楹而空楹。--《文选·江淹·别赋》", "example": null}, {"def": "熊咆龙吟殷岩泉,慄深林兮惊层巅。--唐·李白《梦游天姥吟留别》", "example": null}, {"def": "又如层观(重叠高耸的宫观楼宇);层台(多层的高台);层云(重重云层);层澜(叠起", "example": null}, {"def": "层 céng", "example": null}, {"def": "①量词。用于重叠、可分出层次的事物千～饼、三～楼。", "example": null}, {"def": "②重叠；重复～峦叠嶂。", "example": null}, {"def": "【层出不穷】接连不断地出现，没有尽头。层重迭；重复。穷尽；完。", "example": null}, {"def": "【层递】〈语〉修辞学上辞格之一。用结构相似的语句表达层层递进的事理。如\'火车风驰电掣地猛冲过来……五十米，马不动。四十米，马不动。三十米，马还是不动！\'", "example": null}, {"def": "【层峦】形容山岭重迭（峦连着的山）。", "example": null}, {"def": "【层析】色层分析的简称。", "example": null}]','chinese-xinhua','0'),
('2101143295877976065','曾','1','cénɡ','曰','12',NULL,'[{"def": "曾", "example": null}, {"def": "(形声。从八,从曰。本义未明。副词。用来加强语气)", "example": null}, {"def": "过去发生过--表示有过某些行为或情况", "example": null}, {"def": "江南好,风景旧曾谙。--唐·白居易《忆江南》", "example": null}, {"def": "斜阳草树,寻常巷陌,人道寄奴曾住。--宋·辛弃疾《永遇乐·京口北固亭怀古》", "example": null}, {"def": "又如曾不(不曾);几年前我曾见过他一面;我曾去过杜坪乡", "example": null}, {"def": "已经", "example": null}, {"def": "竟,竟然;尚", "example": null}, {"def": "以残年余力,曾不能毁山之一毛,其如土石何?--《列子·汤问》", "example": null}, {"def": "曾", "example": null}, {"def": "通层”。重叠", "example": null}, {"def": "有虞之王,烧曾薮,斩", "example": null}, {"def": "曾 céng曾经（表示从前有过某种行为或情况）他～来过。又见zēng。", "example": null}, {"def": "曾zēng", "example": null}, {"def": "⒈重，指中间隔着两代的亲属～祖。～孙。", "example": null}]','chinese-xinhua','0'),
('2101143295877976066','蹭','1','cènɡ','足','19',NULL,'[{"def": "蹭", "example": null}, {"def": "(形声。从足,曾声。本义摩擦)", "example": null}, {"def": "同本义", "example": null}, {"def": "因擦过某物而沾上", "example": null}, {"def": "磨蹭,行动拖拉;慢慢地走", "example": null}, {"def": "蹭 cèng", "example": null}, {"def": "①摩擦～破一块皮。", "example": null}, {"def": "②因擦过去而沾上～了一身油。", "example": null}, {"def": "③慢腾腾地行动磨～。", "example": null}, {"def": "【蹭蹬】遭受挫折，困顿失意。", "example": null}]','chinese-xinhua','0'),
('2101143295877976067','噌','1','cēnɡ','口','15',NULL,'[{"def": "噌", "example": null}, {"def": "噌", "example": null}, {"def": "多以形容带动周围空气而起的声音", "example": null}, {"def": "cheng", "example": null}, {"def": "噌吰", "example": null}, {"def": "而大声发于水上,噌吰如钟鼓不绝。--苏轼《石钟山记》", "example": null}, {"def": "噌 cēng象声词他～的一下跳到墙上去了。又见chēng。", "example": null}, {"def": "噌 chēng", "example": null}, {"def": "【噌吰】象声词。多用以形容钟鼓声。又见cēng。", "example": null}]','chinese-xinhua','0'),
