('2101143295877976075','茬','1','chá','艹','9',NULL,'[{"def": "茬", "example": null}, {"def": "(形声。从苃,在声。)本义草茂盛的样子)", "example": null}, {"def": "栽培植物(如麦子、玉米、苜蓿、豆或草)收割后余留的残株", "example": null}, {"def": "茬口", "example": null}, {"def": "茬子", "example": null}, {"def": "他下巴", "example": null}, {"def": "茬 chá", "example": null}, {"def": "①农作物收割后留在地里的茎和根麦～。", "example": null}, {"def": "②作物在同一块地里种植或生长一次叫一茬换～。", "example": null}, {"def": "【茬口】", "example": null}, {"def": "①〈农〉两季作物的种类及其轮作的次序。", "example": null}, {"def": "②某种作物收割以后的土壤。", "example": null}, {"def": "茬（楂）chá", "example": null}, {"def": "⒈庄稼收割后残留在土里的茎、根豆～。麦～。稻～儿。", "example": null}, {"def": "⒉一块田土里庄稼种植的或收获的次数头～。二～。换～儿。", "example": null}, {"def": "⒊短硬的头发或胡子。", "example": null}]','chinese-xinhua','0'),
('2101143295877976076','茶','1','chá','艹','9',NULL,'[{"def": "茶", "example": null}, {"def": "茶树", "example": null}, {"def": "茶叶。由茶树的嫩叶加工制成,供泡取饮料用", "example": null}, {"def": "前月浮梁买茶去。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如茶市(茶叶市场)", "example": null}, {"def": "用茶叶泡制、烹制或煎制而成的饮料", "example": null}, {"def": "唐人煎茶,用姜用盐。--苏轼《东坡志林》", "example": null}, {"def": "日高人渴漫思茶。--宋·苏轼《浣溪沙》", "example": null}, {"def": "又如茶座(茶馆为卖茶而设的座位);茶坊(茶局子、茶局。指茶馆)", "example": null}, {"def": "某些由蒸发或研磨所制的调匀的食用品", "example": null}, {"def": "某些饮料", "example": null}, {"def": "茶 chá", "example": null}, {"def": "①灌木。嫩叶加工后即成茶叶。", "example": null}, {"def": "②用茶叶冲泡成的饮料。", "example": null}, {"def": "③某些饮料的名称奶～、油～。", "example": null}, {"def": "④指油茶树～油。", "example": null}, {"def": "【茶馆】中国现代作家老舍的剧作。全剧以北京一座茶馆为舞台，概括了半个世纪的旧中国日渐衰落的过程，揭示了另寻出路的必然。", "example": null}, {"def": "【茶褐色】赤黄而略带黑的颜色。", "example": null}, {"def": "【茶花女】法国作家小仲马的小说（后又由作者改编为剧本）。作品通过一个苦难妓女的恋爱悲剧，揭露了资产阶级道德的伪善。", "example": null}, {"def": "【茶经】书名。唐代陆羽撰。论述了茶的性状、品质、产地、采制、烹饮方法及用具等。是第一部关于茶的专门著作。", "example": null}, {"def": "【茶青】深绿而微黄的颜色。", "example": null}, {"def": "【茶余饭后】指休息或空闲时间。又作茶余酒后。", "example": null}, {"def": "【茶余酒后】见【茶余饭后】。", "example": null}, {"def": "茶chá", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉用茶叶沏成的饮料请喝～。", "example": null}, {"def": "⒊某些饮料的名称奶油～。杏仁～。", "example": null}, {"def": "⒋黄褐色～色玻璃。", "example": null}]','chinese-xinhua','0'),
