('2101143295877976090','姹','1','chà','女','9',NULL,'[{"def": "姹", "example": null}, {"def": "(形声。从女,宅声。本义少女) 少女;美女", "example": null}, {"def": "奼,少女也。--《说文》", "example": null}, {"def": "河间姹女工数钱。--《汉书·五行志》", "example": null}, {"def": "又如姹女(美女。道教指水银)", "example": null}, {"def": "姹", "example": null}, {"def": "娇美,艳丽", "example": null}, {"def": "姹紫嫣红", "example": null}, {"def": "姹紫嫣红三春晖,赏心悦目百事兴", "example": null}, {"def": "姹 chà美丽～女。", "example": null}, {"def": "【姹紫嫣红】形容各种鲜艳美丽的花。", "example": null}, {"def": "姹chà美丽～紫嫣红，百花争艳。", "example": null}]','chinese-xinhua','0'),
('2101143295877976091','差','1','chà','工','9',NULL,'[{"def": "差  cha", "example": null}, {"def": "(会意。小篆,从左(手)。本义失当;错;相差) 同本义", "example": null}, {"def": "差,贰也,差不相值也。--《说文》", "example": null}, {"def": "乱生其差。--《荀子·天论》。注谬也。”", "example": null}, {"def": "称轻重而不差。--《楚辞·严忌哀时命》", "example": null}, {"def": "毋有差贷。--《礼记·月令仲冬》", "example": null}, {"def": "差若毫厘,谬以千里,其此之谓乎?--《魏书·张普惠传》", "example": null}, {"def": "又如说差啦;认差了", "example": null}, {"def": "差", "example": null}, {"def": "区别", "example": null}, {"def": "何必更以多寡为差。--清·方苞《狱中杂记》", "example": null}, {"def": "又如差别(区别,分别);差异(不同)", "example": null}, {"def": "两数相减的结果", "example": null}, {"def": "差", "example": null}, {"def": "略微,比较", "example": null}, {"def": "差 chā", "example": null}, {"def": "①～不相同；不相合～异。", "example": null}, {"def": "②甲数减去乙数剩余的数。又作差数。又见chà；chāi；cī。", "example": null}, {"def": "【差动滑轮】用特殊方法联成的用于起重的滑轮。由动滑轮c和同轴固定连结且直径相近的、有齿穴的圆盘a、b组成的定滑轮连结而成。沿f方向力拉链条，当定滑轮转动一周，", "example": null}, {"def": "g上升的距离等于a、b两圆周长之差的一半。", "example": null}, {"def": "【差额选举】候选人名额多于应选人名额的不等额选举办法。", "example": null}, {"def": "【差价】同一种商品因各种原因而产生的价格差别。如批发和零售的差价、地区差价、季节差价等。", "example": null}, {"def": "【差平方】两数差的平方。若两数为", "example": null}, {"def": "⑤和挘则它们的差平方应为? (挘挕", "example": null}, {"def": "【差强人意】大致能使人满意。", "example": null}, {"def": "【差异】、差别这两类汽车之间有很大的～。", "example": null}, {"def": "②〈政〉没有激化的矛盾。有内在差异与外在差异之分。", "example": null}, {"def": "【差之毫厘，谬以千里】开始时稍微差一点，结果就能造成很大的错误。多用于强调不能有一点差错。又作失之毫厘，差以千里。", "example": null}, {"def": "【差转台】电视转播台。", "example": null}, {"def": "差 chà", "example": null}, {"def": "①不相同；不相合～得远。", "example": null}, {"def": "②错误说、了。", "example": null}, {"def": "③缺欠～一些。", "example": null}, {"def": "④不好；不够标准质量太～。又见chā；chāi；ci。", "example": null}, {"def": "差 chāi", "example": null}, {"def": "①派遣鬼使神～。", "example": null}, {"def": "②差役。", "example": null}, {"def": "③被派遣去做的事；公务；职务出～。又见chā；chà；cī。", "example": null}, {"def": "【差遣】分派外出工作；派遣。", "example": null}, {"def": "【差使】", "example": null}, {"def": "①差遣；派遣。", "example": null}, {"def": "②（·shi）旧时指临时委任之职。也泛指官职。", "example": null}, {"def": "【差役】", "example": null}, {"def": "①封建统治者强迫人从事的无偿劳动。", "example": null}, {"def": "②旧指在官府里当差的人。", "example": null}, {"def": "差 cī见【参差】。又见chā；chà；chāi。", "example": null}, {"def": "差chāi", "example": null}, {"def": "⒈派遣～遣。", "example": null}, {"def": "⒉公务，被派遣去做的事～事。公～。出～。美～。", "example": null}, {"def": "⒊旧时称供差遣的人～役。", "example": null}, {"def": "差chà", "example": null}, {"def": "⒈短少，欠缺～五元钱。～道工序。", "example": null}, {"def": "⒉不相当，不相合～得多。相～甚远。", "example": null}, {"def": "⒊不好，未达标准～劲。质量太～。", "example": null}, {"def": "⒋错话说的不～。", "example": null}, {"def": "差chā", "example": null}, {"def": "⒈比较而出现的区别～异。～距。千～万别。", "example": null}, {"def": "⒉稍微，勉强～强。～可告慰。", "example": null}, {"def": "⒊错误出了～错。", "example": null}, {"def": "⒋两数相减的余数～数。", "example": null}]','chinese-xinhua','0'),
('2101143295877976092','镲','1','chǎ','钅','19',NULL,'[{"def": "镲", "example": null}, {"def": "一种打击乐器,即小钹。或称镲子、铰子等", "example": null}, {"def": "镲chǎ小钹。", "example": null}]','chinese-xinhua','0'),
('2101143295877976093','衩','1','chǎ','衤','8',NULL,'[{"def": "衩--裤衩”短裤", "example": null}, {"def": "衩chǎ", "example": null}, {"def": "衩chà衣裙旁边开口的部位～口。", "example": null}]','chinese-xinhua','0'),
('2101143295877976094','叉','1','chā','又','3',NULL,'[{"def": "叉", "example": null}, {"def": "(指事。小篆为又”(即手)上加一点,指出叉手的动向。本义交错,交叉)", "example": null}, {"def": "手指相交错。也泛指一般的交错、交叉", "example": null}, {"def": "叉,手指相错也。--《说文》。段注谓手指与物相错也。凡布指错物间而取之曰叉,因之凡岐头皆曰叉。”", "example": null}, {"def": "凡八叉手而八韵成。--《全唐诗话》", "example": null}, {"def": "又如叉手", "example": null}, {"def": "刺;扎取", "example": null}, {"def": "叉", "example": null}, {"def": "古代的一种兵器,头有分杈", "example": null}, {"def": "红漆了叉。--元·睢景臣《", "example": null}, {"def": "叉 chā", "example": null}, {"def": "①一端有长齿、另一端有柄的器具～子。", "example": null}, {"def": "②同\'杈\'。用叉取东西～鱼。", "example": null}, {"def": "③\'×\'形符号，一般用作错误或作废的标志。又见chǎ;chà。", "example": null}, {"def": "叉 chǎ分开成叉（chā）形～腿站着。又见chā；chà。", "example": null}, {"def": "叉 chà劈叉。体操、武术等的一种动作，两腿向相反方向分开，臀部着地。又见chā；chǎ。", "example": null}, {"def": "叉chǎ分开，张开～开。～着腿。", "example": null}, {"def": "叉chā", "example": null}, {"def": "⒈相交，交错～腰。～手。～着脚。", "example": null}, {"def": "⒉一端有两个或两个以上分岐的扎取器具钢～。鱼～子。三齿～。", "example": null}, {"def": "⒊用叉扎取～鸡肉。～蛋糕。～着吃。", "example": null}, {"def": "叉chá挡住，卡住，堵住汽车太多，～住了街口。", "example": null}]','chinese-xinhua','0'),
('2101143295877976095','杈','1','chā','木','7',NULL,'[{"def": "杈", "example": null}, {"def": "(形声。从木,叉声。本义树干的分枝或树枝的分岔)", "example": null}, {"def": "同本义", "example": null}, {"def": "杈,杈枝也。--《说文》", "example": null}, {"def": "江东谓树枝为桠杈。--《方言》", "example": null}, {"def": "突杈枒而皆折,又有触邪之气也。--杜甫《雕赋》", "example": null}, {"def": "又如杈桠(杈丫;杈儿。树的分枝)", "example": null}, {"def": "叉状用具", "example": null}, {"def": "杈chà植物干茎分枝或枝的再分树～。棉花～子。枝～儿。", "example": null}, {"def": "杈chā一种叉着稻草、麦秆或柴草等挑运的用具木～。", "example": null}]','chinese-xinhua','0'),
('2101143295877976096','臿','1','chā','臼','9',NULL,'[{"def": "臿", "example": null}, {"def": "(会意。从臼,从干,干所以臼之。与舂同意。本义舂去麦皮。引申为舂捣)", "example": null}, {"def": "同本义", "example": null}, {"def": "臿,舂出麦皮也。--《说文》", "example": null}, {"def": "红莲米新臿。--清·吴景旭《历代诗话·唐诗·红莲》", "example": null}, {"def": "夹杂;穿插◇作插”", "example": null}, {"def": "赤瑕驳犖,杂臿其间。--司马相如《上林赋》", "example": null}, {"def": "臿", "example": null}, {"def": "铁锹", "example": null}, {"def": "禹之王天下也,身执耒臿以为民先。--《韩非子·五蠹》", "example": null}, {"def": "又如臿筑(锹与捣土的杵)", "example": null}, {"def": "臿chā 1.插地起土的工具。即锹。 2.通\\"插\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295877976097','偛','1','chā','','8',NULL,'[{"def": "偛chā 1.见\\"偛?\\"。 2.狡猾。 3.皮肤起皱。", "example": null}]','chinese-xinhua','0'),
('2101143295877976098','嗏','1','chā','口','12',NULL,'[{"def": "嗏", "example": null}, {"def": "叹词", "example": null}, {"def": "嗏,酩子里自寻思。--元·高明《琵琶记·赵五娘忆夫》", "example": null}, {"def": "语气词", "example": null}, {"def": "见人不住偷睛抹,被你风魔了人也嗏!--金·董解元《西厢记诸宫调》", "example": null}, {"def": "嗏chā 1.语助词。用于句中或句末，多用于散曲﹑杂剧中。 2.叹词。表示提醒或应答等。", "example": null}]','chinese-xinhua','0'),
('2101143295877976099','插','1','chā','扌','12',NULL,'[{"def": "插", "example": null}, {"def": "(形声。从手,臿)声。本义刺入、挤放进去)", "example": null}, {"def": "同本义", "example": null}, {"def": "插,刺内也。--《说文》", "example": null}, {"def": "沉吟放拨插弦中。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "是日城内遍插白旗。--《广州军务记》", "example": null}, {"def": "又如插花筵席(流水席,即客人随到随开的筵席);插标(古人出售物品时,把茅草插在物品上表示出售);插管(双肩式大门的门闩)", "example": null}, {"def": "参与,加入", "example": null}, {"def": "把秧苗、枝条移栽到田地中去", "example": null}, {"def": "加进", "example": null}, {"def": "插 chā", "example": null}, {"def": "①长形或片状的东西进入别的东西里见缝～针。", "example": null}, {"def": "②中间加进去或加进中间去～嘴、～手。", "example": null}, {"def": "【插队落户】", "example": null}, {"def": "①\'文革\'期间在职干部下放劳动的一种形式。按一定比例，让一些在职干部连同其家属迁到农村落户，参加所在公社、生产队的生产劳动。住房由国家帮助解决。有的照拿工资", "example": null}, {"def": "，有的则按离职处理。", "example": null}, {"def": "②\'文革\'中，初中、高中和部分大学毕业生被安排到农村生产队参加农业劳动，他们或在贫下中农家里居住，或成立\'知青点\'，与社员一样，依靠工分生活。知识青年插队落户", "example": null}, {"def": "，是\'上山下乡\'运动的～、～差插 隿?一个重要组成部分。", "example": null}, {"def": "【插科打诨】指戏曲演员在演出中穿插些滑稽的言语和动作来引人发笑。诨戏谑，开玩笑。", "example": null}, {"def": "【插曲】", "example": null}, {"def": "①穿插在电影或话剧中比较有独立性的乐曲。", "example": null}, {"def": "②比喻连续进行的事情中插入的特殊片断。", "example": null}, {"def": "【插入语】在句子里插入的一个成分，不作句子成分，也不同句子成分发生结构关系，既不起联结作用，也不表示语气。如\'这部小说，在我看来，写得很生动\'。\'在我看来\'就", "example": null}, {"def": "是插入语。", "example": null}, {"def": "【插穗】见【插条】。", "example": null}, {"def": "【插条】〈生〉植物营养繁殖的一种方式。把某些植物的枝条插在潮湿的土壤里，让它生根出芽，长成新的植物体。优点是材料易得，技术简单。又叫插枝、插穗。", "example": null}, {"def": "【插图】插印于正文中的图画，起补充说明或艺术欣赏作用。我国古代文艺作品很早就出现了\'出相\'、\'绣像\'、\'全图\'等插图形式。", "example": null}, {"def": "【插叙】叙述方法之一，指在叙述过程中由于表达的需要，中断了原来的叙述而插入另一段叙述，插入的叙述结束后，再继续原来的叙述。插叙可以丰富情节，扩展内容，深化", "example": null}, {"def": "主题或刻画人物性格。", "example": null}, {"def": "【插页】书刊内印有图表、照片等的单页。", "example": null}, {"def": "【插枝】见【插条】。", "example": null}, {"def": "【插足】比喻参与某种活动。", "example": null}, {"def": "插chā放入，扎进去将花～在花瓶里。～秧。〈引〉参与，加入～话。～班学习。", "example": null}]','chinese-xinhua','0'),
