('2101143295877976132','婵','1','chán','女','11',NULL,'[{"def": "婵 (形声。从女,单声。本义婵娟形容女子姿态美好)", "example": null}, {"def": "婵娟", "example": null}, {"def": "不醉莫言还,请看枝间。已飘零一片减婵娟。--《金瓶梅》", "example": null}, {"def": "绮窗罗幕锁婵娟", "example": null}, {"def": "但愿人长久,千里共婵娟。--苏轼《水调歌头》", "example": null}, {"def": "婵媛", "example": null}, {"def": "心婵媛而伤怀兮。--屈原《九章·哀郢》", "example": null}, {"def": "婵 chán", "example": null}, {"def": "【婵娟】", "example": null}, {"def": "①（姿态）美好。古代诗文里多用来形容貌美的女子。", "example": null}, {"def": "②指月亮。又作婵媛。", "example": null}, {"def": "【婵媛】", "example": null}, {"def": "①见【婵娟】。", "example": null}, {"def": "②牵连；相连。", "example": null}, {"def": "婵（嬋）chán", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "婵shàn 1.见\\"婉婵\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295877976133','谗','1','chán','讠','11',NULL,'[{"def": "谗", "example": null}, {"def": "(形声。从言,毚)声。本义说别人的坏话) 同本义", "example": null}, {"def": "谗,谮也。--《说文》", "example": null}, {"def": "谗,诞也。--《韩诗外传》", "example": null}, {"def": "谗口嚣嚣。--《诗·小雅·十月之交》", "example": null}, {"def": "败言为谗。--《左传·昭公五年》", "example": null}, {"def": "谗鼎之铭。--《左传·昭公三年》。服注疾谗之鼎。”", "example": null}, {"def": "取彼谗人。--《后汉书·马援传》", "example": null}, {"def": "屈平属草稿未定,上官大夫见而欲夺之,屈平不与。因谗之曰…--《史记·屈原贾生列传》", "example": null}, {"def": "又如谗谤(诋毁,诽谤);谗言冷语(毁谤、讥刺的冷言冷语)", "example": null}, {"def": "谗", "example": null}, {"def": "说别人坏话的人", "example": null}, {"def": "谗与佞,俱小人也。--《论衡·答佞》", "example": null}, {"def": "又如谗人(喜", "example": null}, {"def": "谗 chán说别人的坏话进～言。", "example": null}, {"def": "【谗害】通过说坏话陷害人。", "example": null}, {"def": "【谗言】陷害别人的坏话。", "example": null}, {"def": "谗（讒）chán说别人的坏话～言。伤良曰～（良好人）。", "example": null}]','chinese-xinhua','0'),
('2101143295877976134','孱','1','chán','子','12',NULL,'[{"def": "孱头", "example": null}, {"def": "我今夜拿不住他算孱头", "example": null}, {"def": "孱", "example": null}, {"def": "(会意。从尸,犹从屋省,本义狭窄)", "example": null}, {"def": "同本义", "example": null}, {"def": "孱,迮也,--《说文》", "example": null}, {"def": "孱,窄也。--《集韵》", "example": null}, {"def": "浅陋,低劣", "example": null}, {"def": "术学肤孱。--宋祁《授龙图阁谢恩表》", "example": null}, {"def": "形容谨小慎微的样子", "example": null}, {"def": "君子博学而孱守之。--《大戴礼记·曾子立事》", "example": null}, {"def": "懦弱", "example": null}, {"def": "若素名勇,徒能藉贫孱者耳。--明·高启《书博鸡者事》", "example": null}, {"def": "又如孱夫(懦弱的人);孱王(懦弱的君王)", "example": null}, {"def": "瘦弱", "example": null}, {"def": "孱弱", "example": null}, {"def": "孱 chán", "example": null}, {"def": "①瘦弱，软弱。", "example": null}, {"def": "②低能。", "example": null}, {"def": "【孱弱】", "example": null}, {"def": "①（身体）瘦弱。", "example": null}, {"def": "②懦弱无能。", "example": null}, {"def": "③薄弱；不充实。", "example": null}, {"def": "孱chán", "example": null}, {"def": "⒈懦弱，低劣～弱。～才。", "example": null}, {"def": "孱jiān 1.窘迫。 2.迫近。", "example": null}, {"def": "孱càn 1.见\\"孱头\\"。", "example": null}, {"def": "孱zhàn 1.孱陵。古地名。见《汉书·地理志上》。", "example": null}]','chinese-xinhua','0'),
