('2101143295877976146','躔','1','chán','足','22',NULL,'[{"def": "躔", "example": null}, {"def": "(形声。从足,廛)声。本义践,践履)", "example": null}, {"def": "同本义", "example": null}, {"def": "躔,践也。--《说文》", "example": null}, {"def": "未知英雄之所躔也。--晋·左思《吴都赋》", "example": null}, {"def": "又如躔躔的(快速舞动或转动);躔陛(指石级)", "example": null}, {"def": "运行", "example": null}, {"def": "躔,历行也。日运为躔,月运为逡。--《方言十二》", "example": null}, {"def": "躔,行也。--《广雅》", "example": null}, {"def": "日月初躔。--《汉书·律历志上》", "example": null}, {"def": "月躔二十八宿。--《吕氏春秋·圜道》", "example": null}, {"def": "日月星辰在黄道上运行", "example": null}, {"def": "躔", "example": null}, {"def": "麋鹿的足迹。又泛指脚迹,行迹", "example": null}, {"def": "麋其迹躔。", "example": null}, {"def": "躔chán", "example": null}, {"def": "⒈行进中停留。", "example": null}, {"def": "⒉行迹，足迹迹～。", "example": null}, {"def": "⒊日月星辰运行时经过天空中某一区域书（记录）日月之所～。", "example": null}]','chinese-xinhua','0'),
