('2101143295882170401','掺','1','chān','扌','11',NULL,'[{"def": "掺  chan", "example": null}, {"def": "同参”。古时候的一种鼓曲名。也指击鼓三次", "example": null}, {"def": "镗鎝《渔阳掺》,怨抑胡笳断。--《乐府诗集·横吹曲辞》", "example": null}, {"def": "掺  shan", "example": null}, {"def": "细小", "example": null}, {"def": "掺,细也。--《方言》。戴震疏证掺,细小也。”", "example": null}, {"def": "同扦”。女手纤美的样子", "example": null}, {"def": "掺掺女手,可以缝裳。--《诗·魏风·葛屦》", "example": null}, {"def": "掺（摻）chān混合～杂。～点糖。不能～沙子。", "example": null}, {"def": "掺shǎn 1.执，操。 2.操守。", "example": null}, {"def": "掺shān 1.女手纤美貌。", "example": null}, {"def": "掺sēn 1.树木众盛貌。", "example": null}, {"def": "掺càn 1.古代鼓曲名。 2.指古代乐曲演奏中的一种击鼓之法。", "example": null}]','chinese-xinhua','0'),
('2101143295882170402','搀','1','chān','扌','12',NULL,'[{"def": "搀", "example": null}, {"def": "(形声。从手,毚)声。本义扶,牵挽)", "example": null}, {"def": "同本义", "example": null}, {"def": "混杂;搀和", "example": null}, {"def": "搀 chān", "example": null}, {"def": "①搀扶让我～你一把。", "example": null}, {"def": "②把一种东西混入另一种东西里～沙子、～假。", "example": null}, {"def": "【掺兑】把成分不同的东西混合在一起把白面和玉米面～在一起蒸丝糕。", "example": null}, {"def": "搀（攙）chān", "example": null}, {"def": "⒈挽，牵扶～扶。手～手。～着老大娘走人行道。", "example": null}, {"def": "⒉混合～杂。～点糖。不能～沙子。", "example": null}]','chinese-xinhua','0'),
