('2101143295882170409','肠','1','chánɡ','月','7',NULL,'[{"def": "肠", "example": null}, {"def": "(形声。从肉,?", "example": null}, {"def": "肠子或肠子制成的食品", "example": null}, {"def": "内心,情怀", "example": null}, {"def": "肠 cháng（～子）消化器官的一部分，形状像管子，上端连胃，下端通肛门。起消化和吸收作用。又叫肠管。", "example": null}, {"def": "【肠断】形容极度悲伤忧愁。", "example": null}, {"def": "【肠肥脑满】见【脑满肠肥】。", "example": null}, {"def": "【肠骨】见【髂骨】。", "example": null}, {"def": "【肠管】肠。", "example": null}, {"def": "肠（腸）cháng内脏之一，长管形，分小肠和大肠，对食物起消化、吸收作用断～（〈喻〉异常悲痛）人在天涯。牵～割肚（形容惦念得放不下心）。", "example": null}]','chinese-xinhua','0'),
('2101143295882170410','苌','1','chánɡ','艹','7',NULL,'[{"def": "苌", "example": null}, {"def": "即苌楚", "example": null}, {"def": "姓", "example": null}, {"def": "苌 cháng", "example": null}, {"def": "①苌楚，古书上说的一种植物。", "example": null}, {"def": "②姓。", "example": null}, {"def": "【苌弘化碧】苌弘的血化作了碧玉。形容精诚。苌弘，又称苌叔，春秋时周大夫。神话传说苌弘被杀后，其血三年化为碧玉。", "example": null}, {"def": "苌（萶cháng", "example": null}]','chinese-xinhua','0'),
('2101143295882170411','尝','1','chánɡ','小','9',NULL,'[{"def": "尝", "example": null}, {"def": "(形声。从旨,尚声。旨”,滋味美。本义辨别滋味,品尝)", "example": null}, {"def": "同本义", "example": null}, {"def": "天子乃以雏尝黍。--《礼记·月令》", "example": null}, {"def": "臣先尝之。--《礼记·曲礼》", "example": null}, {"def": "不敢尝。--《论语》", "example": null}, {"def": "百鬼迪尝。--《汉书·礼乐志》", "example": null}, {"def": "尝其旨否。--《诗·小雅·甫田》", "example": null}, {"def": "又如尝酒;尝食(试辨食物的味道);尝酎(祭祀的时候,尝一尝新酒的滋味)", "example": null}, {"def": "尝试", "example": null}, {"def": "尝,试也。--《小尔雅》", "example": null}, {"def": "诸侯方睦于晋,臣请尝人,若何?--《左传·襄公十八年》", "example": null}, {"def": "又如尝巧(试验其技巧);尝汤戏(正戏前加演的短戏)", "example": null}, {"def": "经历", "example": null}, {"def": "险阻艰难,备尝之矣。--《左传·", "example": null}, {"def": "尝 cháng", "example": null}, {"def": "①吃一点试试；辨别滋味～鲜。", "example": null}, {"def": "②曾经未～、何～。", "example": null}, {"def": "【尝新】吃应时的新鲜蔬菜、水果等。", "example": null}, {"def": "尝（噇）cháng", "example": null}, {"def": "⒈辨别滋味～味。品～。卧薪～胆。〈喻〉经历险阻艰难，备～之矣（备全都）。", "example": null}, {"def": "⒉试，试一试～试。", "example": null}, {"def": "⒊曾经何～？", "example": null}]','chinese-xinhua','0'),
('2101143295882170412','偿','1','chánɡ','亻','11',NULL,'[{"def": "偿", "example": null}, {"def": "(形声。从人,赏声。本义归还,赔偿)", "example": null}, {"def": "同本义", "example": null}, {"def": "偿,还也。--《说文》", "example": null}, {"def": "偿,复也。--《广雅》", "example": null}, {"def": "西邻责言不可偿也。--《左传·僖公十五年》", "example": null}, {"def": "使吏召诸民当偿者悉来合券。--《战国策·齐策四》", "example": null}, {"def": "又如偿债(偿还欠债);偿付(归还所欠的债)", "example": null}, {"def": "报答;酬报", "example": null}, {"def": "补偿,抵偿", "example": null}, {"def": "相如视秦王无意偿赵城。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "又如偿罪;偿死(抵命);得不偿失", "example": null}, {"def": "满足,实现", "example": null}, {"def": "偿", "example": null}, {"def": "酬报", "example": null}, {"def": "偿 cháng", "example": null}, {"def": "①归还；低偿血债要用血来～。", "example": null}, {"def": "②满足如愿以～。", "example": null}, {"def": "【偿还】归还（所欠的债）。", "example": null}, {"def": "【偿命】用生命偿还杀人～。", "example": null}, {"def": "偿（償）cháng", "example": null}, {"def": "⒈归还，赔给～还。～债。赔～。", "example": null}, {"def": "⒉抵当，抵补抵～。补～。得不～失。", "example": null}, {"def": "⒊回报，回答不可～也。", "example": null}, {"def": "⒋满足，实现如愿以～。", "example": null}]','chinese-xinhua','0'),
('2101143295882170413','常','1','chánɡ','巾','11',NULL,'[{"def": "常", "example": null}, {"def": "(形声。从巾,尚声。本义旗)", "example": null}, {"def": "同本义", "example": null}, {"def": "纪于太常。--《书·君牙》。传王之旌旗画日月曰太常。", "example": null}, {"def": "载是常服。--《诗·小雅·六月》", "example": null}, {"def": "裙子", "example": null}, {"def": "叔旦泣涕于常,悲不能对。--《逸周书》", "example": null}, {"def": "常,下裙也。--《说文》。朱骏声曰常裳二字,经传截然分开,并不通借。”", "example": null}, {"def": "规则,规律", "example": null}, {"def": "陈常于时夏。--《诗·周颂·思文》", "example": null}, {"def": "天行有常,不为尧存,不为桀亡。--《荀子·天论》", "example": null}, {"def": "又如常古(旧法,常法);常故(旧例;常例);常式(法式)", "example": null}, {"def": "封建社会宣扬的所谓恒久不变的人与人之间的关系准则,即伦常;纲常", "example": null}, {"def": "常 cháng", "example": null}, {"def": "①一般；普通；平常～识、～态。", "example": null}, {"def": "②不变的；永久的～数。", "example": null}, {"def": "③时常；常常～来～往。", "example": null}, {"def": "④姓。", "example": null}, {"def": "【常备不懈】时刻有所准备，丝毫不松懈。", "example": null}, {"def": "【常备军】国家平时经常保持的正规军队。", "example": null}, {"def": "【常规能源】广泛使用、技术上比较成熟的能源。如煤炭、石油、天然气、水能等。又称传统能源。", "example": null}, {"def": "【常规战争】用常规武器进行的战争（区别于\'核战争\'）。", "example": null}, {"def": "【常轨】正常的、平常的方法或途径。", "example": null}, {"def": "【常量】考察过程中保持不变或只能取一个数值的量叫常量。如等速运动中的速度。", "example": null}, {"def": "【常绿阔叶林】亚热带湿润地区植被类型。乔木层多为樟科、壳斗科、山茶科、木兰科等常绿阔叶树种。在我国分布于华东、中南和西南地区。", "example": null}, {"def": "【常染色体】性染色体以外的染色体。", "example": null}, {"def": "【常数】固定不变的数值，如圆周率π。", "example": null}, {"def": "【常数列】每一项都相等的数列，如\'1，1，1，…。\'", "example": null}, {"def": "【常数项】在多项式中，不含字母的4x-5，-5是常数项。", "example": null}, {"def": "【常数项矩阵】参见【线性方程组】。", "example": null}, {"def": "【常微分方程】数学的一门分科，研究常微分方程的解法及解的性质。主要有定性理论、稳定性理论、解析理论等部分。", "example": null}, {"def": "【常温动物】具有完善的体温调节机制，体温受环境影响较小，保持相对稳定的动物。鸟类、哺乳类是常温动物。又称温血动物、恒温动物。", "example": null}, {"def": "【常用对数】以10为底的对数。", "example": null}, {"def": "【常用对数表】数学用表之一，供查找常用对数之用，列有正实数的常用对数的尾数数值。又叫常用对数的尾数表。简称对数表。", "example": null}, {"def": "常cháng", "example": null}, {"def": "⒈随时，时时时～。经～。～ ～在一起工作。", "example": null}, {"def": "⒉永久的，固定的～绿。～在。松柏～青。", "example": null}, {"def": "⒊规律，准则天行有～。", "example": null}, {"def": "⒋普通，一般通～。平～。反～。～识。～态。寻～。", "example": null}, {"def": "⒌〈古〉长度单位。八尺为寻，两寻为～。", "example": null}, {"def": "⒍〈古〉通\\"尝\\"。曾经。", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
