('2101143295882170425','韔','1','chànɡ','韋','17',NULL,'[{"def": "韔", "example": null}, {"def": "弓袋,古代装弓的套子", "example": null}, {"def": "韔,弓衣也。从韋,长声。--《说文》", "example": null}, {"def": "虎韔镂膺。--《诗·秦风·小戎》", "example": null}, {"def": "又", "example": null}, {"def": "交韔二弓。", "example": null}, {"def": "猛士腰间虎文韔。--宋·陆游诗", "example": null}, {"def": "韔", "example": null}, {"def": "藏弓于弓袋", "example": null}, {"def": "之子于狩,言韔其弓。--《诗·小雅·采绿》", "example": null}, {"def": "又如 韔弓(弛弓弦将弓放进弓袋)", "example": null}, {"def": "韔chàng〈古〉", "example": null}, {"def": "⒈弓套。", "example": null}, {"def": "⒉将弓放入弓套里。", "example": null}]','chinese-xinhua','0'),
('2101143295882170426','怅','1','chànɡ','忄','7',NULL,'[{"def": "怅", "example": null}, {"def": "(形声。从心,长声。本义因失意而不痛快) 同本义", "example": null}, {"def": "恨,望恨也。--《说文》", "example": null}, {"def": "陈涉少时,尝与人佣耕,辍耕之垄上,怅恨久之苟富贵,无相忘。”--《史记·陈涉世家》", "example": null}, {"def": "怅寥廓,向苍茫大地,谁主沉浮。--毛泽东《沁园春·长沙》", "example": null}, {"def": "又如惆怅(伤感;失意);怅况(恍惚);怅触(惆怅感触)", "example": null}, {"def": "怅 chàng失意；不称心；不痛快；惆～。", "example": null}, {"def": "【怅然若失】不如意，仿佛丢了什么似的。", "example": null}, {"def": "【怅惘】惆怅迷惘；心事重重，无精打采。", "example": null}, {"def": "怅（悵）chàng失意，懊恼～惘。～恨。惆～。", "example": null}]','chinese-xinhua','0'),
('2101143295882170427','玚','1','chànɡ','王','7',NULL,'[{"def": "玚", "example": null}, {"def": "古代祭祀用的一种圭。也叫玚圭", "example": null}, {"def": "yang", "example": null}, {"def": "瑒", "example": null}, {"def": "一种玉。", "example": null}, {"def": "玚chàng 1.圭璧名。即鬯圭。", "example": null}, {"def": "玚dàng 1.黄金。参见\\"玚琫\\"。", "example": null}, {"def": "玚yáng 1.玉名。 2.人名用字『代有应玚。见《后汉书·应奉传》﹑《三国志·魏志·应玚传》。", "example": null}]','chinese-xinhua','0'),
('2101143295882170428','畅','1','chànɡ','田','8',NULL,'[{"def": "畅", "example": null}, {"def": "(形声。从申,?", "example": null}, {"def": "同本义", "example": null}, {"def": "登台四望,三面皆畅。--《韩非子·说林上》", "example": null}, {"def": "美在其中,而畅于四支。--《易·坤》", "example": null}, {"def": "又如通畅(运行无阻);顺畅(顺利通畅,没有阻碍)", "example": null}, {"def": "舒畅", "example": null}, {"def": "旧国旧都,望之畅然。--《庄子·则阳》", "example": null}, {"def": "感条畅之气。--《礼记·乐记》", "example": null}, {"def": "美声畅于虞氏。--《文选·张衡·西京赋》", "example": null}, {"def": "又如宽畅(心里舒畅);酣畅(畅快)", "example": null}, {"def": "茂盛", "example": null}, {"def": "草木畅茂。--《孟子·滕文公上》", "example": null}, {"def": "流畅,言辞敏捷、自在而流利", "example": null}, {"def": "畅", "example": null}, {"def": "正;极;甚", "example": null}, {"def": "畅 chàng", "example": null}, {"def": "①顺畅，没有阻碍～通无阻。痛快；尽情欢～。", "example": null}, {"def": "【畅达】（语言、文章、交通等）通顺流利行文～。", "example": null}, {"def": "【畅所欲言】把想要说出的话痛痛快快地全说出来。", "example": null}, {"def": "【畅想】放开思路，无拘无束地想象～曲。", "example": null}, {"def": "【畅游】", "example": null}, {"def": "①尽情愉快地游览。", "example": null}, {"def": "②舒畅地游泳。", "example": null}, {"def": "畅(暢)chàng", "example": null}, {"def": "⒈无阻碍～通。～达。～销。流～。", "example": null}, {"def": "⒉通晓晓～军事。", "example": null}, {"def": "⒊舒适舒～。欢～。", "example": null}, {"def": "⒋痛快，尽情～快。～谈。～所欲言。", "example": null}, {"def": "⒌盛～茂。～盛。", "example": null}]','chinese-xinhua','0'),
('2101143295882170429','倡','1','chànɡ','亻','10',NULL,'[{"def": "倡", "example": null}, {"def": "(形声。从人,昌声。本义唱歌的艺人)", "example": null}, {"def": "同本义", "example": null}, {"def": "倡,乐也。--《说文》", "example": null}, {"def": "倡,俳也。--《声类》", "example": null}, {"def": "倡,优乐也。--《字林》", "example": null}, {"def": "令倡俳赢戏坐中。--《汉书·广川惠王越传》。注乐人也。”", "example": null}, {"def": "孝武李夫人本以倡进。--《汉书·外戚传》", "example": null}, {"def": "幸倡郭舍人。--《汉书·东方朔传》", "example": null}, {"def": "孝武李夫人本以倡进。--《汉书·外戚传》", "example": null}, {"def": "优旃者,秦倡。--《史记·滑稽列传》", "example": null}, {"def": "问其人,本长安倡女。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如倡家(歌楼酒馆。也 指妓院)", "example": null}, {"def": "泛指中国古代表演歌舞杂戏的艺人。又称倡人,倡优,倡伎,倡女,倡", "example": null}, {"def": "倡 chàng首先发起；提倡～议。", "example": null}, {"def": "【倡导】首先提倡～节约。", "example": null}, {"def": "【倡言】公开提出。", "example": null}, {"def": "【倡议书】首先提出某种建议的文章、书信。", "example": null}, {"def": "【倡优】中国古代以乐舞戏谑为业的艺人。", "example": null}, {"def": "倡chàng首先提出，带头发起～议。～导。先～。提～。", "example": null}, {"def": "倡chāng 1.古代表演歌舞杂戏的艺人。 2.娼妓。 3.通\\"猖\\"。狂乱貌。", "example": null}, {"def": "倡cháng 1.见\\"倡佯\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295882170430','鬯','1','chànɡ','鬯','10',NULL,'[{"def": "鬯", "example": null}, {"def": "(象形。甲骨文字形,象器皿中盛酒形,中有小点,表示酒糟。本义古代祭祀、宴饮用的香酒,用郁金草合黑黍酿成)", "example": null}, {"def": "同本义", "example": null}, {"def": "共介鬯。--《周礼·鬯人》", "example": null}, {"def": "凡挚子鬯。--《礼记·曲礼》", "example": null}, {"def": "也代指宗庙祭祀", "example": null}, {"def": "荐鬯之夕。--《汉书·宣帝纪》", "example": null}, {"def": "又如鬯圭(古代礼器,玉制,酌鬯酒);鬯酒(用于祭祀的香酒)", "example": null}, {"def": "通韔”。弓袋", "example": null}, {"def": "抑鬯弓忌。--《诗·郑风·大叔于田》", "example": null}, {"def": "鬯", "example": null}, {"def": "通畅”。旺盛", "example": null}, {"def": "草木鬯茂。--《汉书·郊祀志》", "example": null}, {"def": "又如鬯逐(生物生长舒肆旺盛)", "example": null}, {"def": "鬯chàng", "example": null}, {"def": "⒈〈古〉祭祀用的香酒。", "example": null}, {"def": "⒉通\\"畅\\"。～谈。～通。草木～茂。", "example": null}]','chinese-xinhua','0'),
('2101143295882170431','唱','1','chànɡ','口','11',NULL,'[{"def": "唱〈动〉", "example": null}, {"def": "(形声。从口,昌声。唱”字经传以倡”为之。本义领唱)", "example": null}, {"def": "同本义", "example": null}, {"def": "唱,导也。--《说文》", "example": null}, {"def": "取其唱予和女。--《左传·昭公十六年》注", "example": null}, {"def": "唱和有应。--《荀子·乐论》", "example": null}, {"def": "晷漏肃唱。--《文选·左思·魏都赋》", "example": null}, {"def": "又如唱和(唱歌时此唱彼和)", "example": null}, {"def": "倡导;发起◇作倡”", "example": null}, {"def": "为天下唱,宜多应者。--《史记·陈涉世家》", "example": null}, {"def": "予三十年前所主唱之三民主义、五权宪法,为诸先烈所不惜牺牲生命以争之者。--孙文《黄花冈七十二烈士事略·序》", "example": null}, {"def": "又如唱义(倡导起义);唱谋(率先策划);唱始(倡始;首倡)", "example": null}, {"def": "歌唱,吟咏", "example": null}, {"def": "唱 chàng", "example": null}, {"def": "①口中发出（乐音）；依照乐律发出声音歌～、吟～。", "example": null}, {"def": "②大声念；高声叫～票、鸡～三遍。", "example": null}, {"def": "③姓。", "example": null}, {"def": "【唱独角戏】演只有一个角色的戏。比喻独自做一般不是一个人做的工作。", "example": null}, {"def": "【唱对台戏】原指旧时两个戏班为了互相竞争，同时演出同样的戏。比喻就某一件事或某一问题，有意发表与对方相反的意见或采取相反的做法。", "example": null}, {"def": "【唱反调】比喻有意持相反意见。", "example": null}, {"def": "【唱高调】比喻话说得漂亮但实际做不到；或者光说好话不做实事‖贬义。", "example": null}, {"def": "【唱和】一个人做了诗或词，别的人相应作答（大多按照原韵）。", "example": null}, {"def": "【唱名】〈音〉唱谱中使用的名称。种类很多，一般唱名用do、re、mi、fa、sol、la、si来表示。首调唱名法中si唱作ti。我国工尺谱记谱法中的唱名用上、尺、工、凡、六", "example": null}, {"def": "、五、乙。", "example": null}, {"def": "【唱腔】戏曲名词。指人声演唱的部分，是戏曲音乐的组成部分。\'乐队伴奏\'的对称。", "example": null}, {"def": "【唱支山歌给党听】歌名。践耳曲，焦萍词。1964年根据雷锋日记谱写而成。为三部曲式抒情歌曲，歌曲充分表达了雷锋对旧社会的仇恨，对新社会、对党的炽热的爱。", "example": null}, {"def": "唱chàng", "example": null}, {"def": "⒈吟咏，依照音律发声～歌。～戏。大合～。二重～。〈引〉高声叫，大声唸～名。～票。", "example": null}, {"def": "⒉歌曲你来唱个～儿。", "example": null}]','chinese-xinhua','0'),
('2101143295882170432','畼','1','chànɡ','','10',NULL,'[{"def": "畼chàng 1.田荒芜不生谷物。 2.除草。 3.同\\"畅\\"。通达;畅通。 4.通\\"畅\\"。舒畅;欢快。 5.通\\"畅\\"。充;充实。参见\\"畼月\\"。 6.通\\"鬯\\"。古代祭祀用的一种酒。", "example": null}]','chinese-xinhua','0'),
('2101143295882170433','誯','1','chànɡ','','10',NULL,'[{"def": "誯chàng 1.作人名用字。《宋史．宗室世系表十二》有赵崇誯。", "example": null}]','chinese-xinhua','0'),
('2101143295882170434','氅','1','chǎnɡ','毛','16',NULL,'[{"def": "氅〈名〉", "example": null}, {"def": "用鸟类的羽毛缝制成的外衣", "example": null}, {"def": "指一般的外套大衣", "example": null}, {"def": "鹙鸟的羽毛", "example": null}, {"def": "尝见王恭乘高舆,被鹤氅裘。--刘义庆《世说新语》", "example": null}, {"def": "氅 chǎng外套大～（大衣）。", "example": null}, {"def": "氅chǎng", "example": null}, {"def": "⒈〈古〉用鸟羽制的衣服，叫\\"鹤氅\\"。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143295882170435','鋹','1','chǎnɡ','釒','16',NULL,'[{"def": "鋹", "example": null}, {"def": "锐利", "example": null}, {"def": "鋹,利也。--《玉篇》", "example": null}, {"def": "鋹chǎng 1.利;锐势。", "example": null}]','chinese-xinhua','0'),
('2101143295886364672','厂','1','chǎnɡ','厂','2',NULL,'[{"def": "厂", "example": null}, {"def": "(形声。从广，敞声。从广”,表示与房屋有关。本义棚舍)", "example": null}, {"def": "没有墙壁的简易房屋", "example": null}, {"def": "又如厂屋(棚舍;无隔墙的房屋)", "example": null}, {"def": "马屋;牲口棚子", "example": null}, {"def": "架北墙为厂。--《齐民要术》", "example": null}, {"def": "工厂", "example": null}, {"def": "正德十四年,广州置铁厂。--《明史·食货志》", "example": null}, {"def": "又如纱厂;钢厂;面粉厂;纺织厂;造纸厂;木器厂", "example": null}, {"def": "明代的一种特务机构", "example": null}, {"def": "厂ān", "example": null}, {"def": "⒈小寺庙。多称尼姑居住处～堂。", "example": null}, {"def": "⒉圆形的草屋。\\"厂\\"多见于人名。", "example": null}, {"def": "厂 chǎng工厂塑料～、面粉～。", "example": null}, {"def": "【厂长责任制】全民所有制工业企业中所实行的一种制度。在这种制度下，厂长具有企业经营管理工作的决策权和生产指挥权，在企业中处于中心地位，对企业的物质文明建设和精神文明建设负有全面责任。", "example": null}, {"def": "厂（厰、弒）chǎng", "example": null}, {"def": "⒈通常指制造生产资料或生活资料的企业单位工～。轧钢～。食品～。", "example": null}, {"def": "⒉可以存货或可进行加工的场所煤～。汽车修配～。", "example": null}, {"def": "⒊跟棚子相似的房屋～棚。", "example": null}]','chinese-xinhua','0'),
('2101143295886364673','场','1','chǎnɡ','土','6',NULL,'[{"def": "场", "example": null}, {"def": "(形声。从土?", "example": null}, {"def": "祭坛旁的平地", "example": null}, {"def": "牺牲壇场。--《汉书·郊祀志》。注平地为场。”", "example": null}, {"def": "灵场之威。--《法言·问明》。注鬼神之壇也。”", "example": null}, {"def": "谷场,场子", "example": null}, {"def": "一曰治谷田也。--《说文》", "example": null}, {"def": "季秋除圃中为之。--《周礼·场人》注", "example": null}, {"def": "以场圃任园地。--《周礼·载师》", "example": null}, {"def": "九月筑场圃。--《诗·豳风·七月》", "example": null}, {"def": "又", "example": null}, {"def": "十月涤场。", "example": null}, {"def": "顾野有麦场,场主积薪其中。--《聊斋志异·狼三则》", "example": null}, {"def": "又如打场(在场上脱粒);禾场;摊场;晒场", "example": null}, {"def": "场 cháng", "example": null}, {"def": "①平坦的空地。多用来翻晒粮食，碾轧谷物打谷～。", "example": null}, {"def": "②量词。用于事情的经过他得了一、大病，现在身体很弱。又见chǎng。", "example": null}, {"def": "场 chǎng", "example": null}, {"def": "①适合进行某种活动的比较大的地方会～、广～、商～。", "example": null}, {"def": "②舞台上～、下～、出～。", "example": null}, {"def": "③戏剧中较小的段落，每场表演故事的一个片断。", "example": null}, {"def": "④量词。用于文娱体育活动两～舞会、五～足球赛。", "example": null}, {"def": "⑤指某种活动领域官～。", "example": null}, {"def": "⑥电视接收机中，电子束对一幅画面的奇数行或偶数行完成一次隔行扫描，叫做一场。奇数场和偶数场合为一幅完整画面。", "example": null}, {"def": "⑦物质存在的一种基本形式。具有能量、动量和质量，能传递实物间的相互作用。如电场、磁场等。又见cháng。", "example": null}, {"def": "【场记】在摄影或摄像时，将现场拍摄的每个分镜头的内容作详细记录，以供继续拍摄或剪辑时参考和查对。", "example": null}, {"def": "【场景】", "example": null}, {"def": "①特指戏剧、电影中的场面。", "example": null}, {"def": "②泛指各种景象助人为乐的动人～。", "example": null}, {"def": "【场面描写】对在特定时间、地点里各类人物的活动进行总体面貌的描写，用以反映人与人之间的关系，揭示人物之间的矛盾冲突。", "example": null}, {"def": "场（場、塲）chǎng", "example": null}, {"def": "⒈许多人聚集的、活动的或事情发生的地方～所。会～。市～。操～子。广～儿。现～。", "example": null}, {"def": "⒉舞台登～。出～。", "example": null}, {"def": "⒊戏剧的分段三幕六～。", "example": null}, {"def": "⒋量词。用于文娱、体育方面两～电影。三～足球赛。", "example": null}, {"def": "⒌", "example": null}, {"def": "场（場、塲）cháng", "example": null}, {"def": "⒈平坦的空地，多用于晒、打粮食～院。打麦～。", "example": null}, {"def": "⒉量词。常指一件事情的经过一～暴风雨。大干一～。", "example": null}, {"def": "场shāng 1.蚂蚁﹑田鼠﹑蚯蚓等翻起的松散泥土或堆在穴口的小土堆。 2.\\"墒\\"的古字。", "example": null}]','chinese-xinhua','0'),
('2101143295886364674','昶','1','chǎnɡ','日','9',NULL,'[{"def": "昶", "example": null}, {"def": "白天时间长的", "example": null}, {"def": "昶,日长也。--《说文新附》", "example": null}, {"def": "通畅”。舒畅,通畅", "example": null}, {"def": "譬犹众目营方,则天纲自昶。--《文选·陆机·五等论》。《广雅》云昶,通也。", "example": null}, {"def": "固以和昶而足耽矣。--嵇康《琴赋》", "example": null}, {"def": "昶chǎng", "example": null}, {"def": "⒈白天时间长。", "example": null}, {"def": "⒉通\\"畅\\"。畅通，舒畅。", "example": null}]','chinese-xinhua','0'),
('2101143295886364675','惝','1','chǎnɡ','忄','11',NULL,'[{"def": "惝恍", "example": null}, {"def": "步徒倚而遥思兮,怊惝恍而乖怀。--屈原《远游》", "example": null}, {"def": "视眩眠而无见兮,听惝恍而无闻。--《史记》", "example": null}, {"def": "惝tǎng(又读chǎng)失意。", "example": null}]','chinese-xinhua','0'),
('2101143295886364676','敞','1','chǎnɡ','攵','12',NULL,'[{"def": "敞", "example": null}, {"def": "将高起的土地筑成平台,用以远望", "example": null}, {"def": "同本义", "example": null}, {"def": "敞,平治高土,可以远望也。--《说文》", "example": null}, {"def": "张开,敞开", "example": null}, {"def": "显露;露出", "example": null}, {"def": "奇踪隐五百,一朝敞神界。--陶潜《桃花源诗》", "example": null}, {"def": "敞", "example": null}, {"def": "(形声。从攴,尚声。本义宽敞)", "example": null}, {"def": "宽敞", "example": null}, {"def": "其母死,贫无以葬,然乃行营高敞地。--《史记·淮阴侯列传》", "example": null}, {"def": "中轩敞者为舱。--清·张潮《核舟记》", "example": null}, {"def": "又如敞平(宽阔平坦);敞阔(宽阔清静)", "example": null}, {"def": "随便", "example": null}, {"def": "敞 chǎng", "example": null}, {"def": "①宽绰；无遮掩这个地方真宽～。", "example": null}, {"def": "②张开；打开～开胸怀。", "example": null}, {"def": "【敞开系统】与外界有热和功交换并有质量交换的系统。", "example": null}, {"def": "敞chǎng", "example": null}, {"def": "⒈宽阔，高朗～亮。～丽。宽～。轩～。", "example": null}, {"def": "⒉打开，大开，尽量～开窗户。有的是洁净水，你就～开喝吧！", "example": null}]','chinese-xinhua','0'),
