('2101143295886364683','伥','1','chānɡ','亻','6',NULL,'[{"def": "伥", "example": null}, {"def": "(形声。从人,长声。本义狂)", "example": null}, {"def": "同本义", "example": null}, {"def": "伥,狂也。俗字作猖。--《说文》", "example": null}, {"def": "何桀纠之昌披兮。(以昌为之。)--《离骚》", "example": null}, {"def": "号为伥子”。--《资治通鉴》→三省注伥,狂。”", "example": null}, {"def": "迷信传说中的被老虎咬死的人变成的鬼,这种鬼引导老虎咬别的人", "example": null}, {"def": "旧指为盗贼察情探路的人。也指助纣为虐的恶人", "example": null}, {"def": "其为响马贼之伥无疑。--清·酉阳《女盗侠传》", "example": null}, {"def": "伥", "example": null}, {"def": "无所适从。又称伥伥", "example": null}, {"def": "人无法则伥伥然。--《荀子·修身》", "example": null}, {"def": "伥鬼", "example": null}, {"def": "伥（倀）chāng〈古〉迷信传说\\"被老虎吃了的人变成鬼，又帮助老虎伤人\\"为虎作～（〈喻〉帮恶人作恶事）。", "example": null}]','chinese-xinhua','0'),
('2101143295886364684','昌','1','chānɡ','日','8',NULL,'[{"def": "昌", "example": null}, {"def": "(会意。从日,从曰。本义善,正当)", "example": null}, {"def": "同本义", "example": null}, {"def": "昌,美言也。--《说文》", "example": null}, {"def": "禹拜昌言。--《书·大禹谟》", "example": null}, {"def": "又如昌言(正直的善言、好话);昌教(善美的教化)", "example": null}, {"def": "兴旺发达,与亡”相对", "example": null}, {"def": "邦乃其昌。--《书·仲虺之诰》", "example": null}, {"def": "顺之者昌,逆之者不死则亡。--《史记·太史公自序》", "example": null}, {"def": "今中国未闻有因变法而流血者,此国之所以不昌也。--清·梁启超《谭嗣同传》", "example": null}, {"def": "又如昌瑞(昌盛祥瑞);昌乐(兴盛安乐)", "example": null}, {"def": "光;光明", "example": null}, {"def": "一曰日光。诗曰东方昌昌。--《说文》", "example": null}, {"def": "又如昌晖(光明);昌华(光华)", "example": null}, {"def": "壮大;美好", "example": null}, {"def": "猗嗟昌兮,颀", "example": null}, {"def": "昌 chāng", "example": null}, {"def": "①兴旺；茂盛～盛。", "example": null}, {"def": "②姓。", "example": null}, {"def": "【昌明】（政治、文化）兴旺发达科学～。", "example": null}, {"def": "昌chāng兴旺，繁荣～盛。～明。", "example": null}, {"def": "昌chàng 1.通\\"倡\\"。倡导。参见\\"昌导\\"。 2.通\\"唱\\"。吟唱。参见\\"昌诵\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295886364685','娼','1','chānɡ','女','11',NULL,'[{"def": "娼", "example": null}, {"def": "指从事歌舞的女艺人。娼,本作倡", "example": null}, {"def": "娼妓", "example": null}, {"def": "娼 chāng妓女～妓、～妇。", "example": null}, {"def": "【娼妓】妓女。", "example": null}, {"def": "娼chāng妓女。", "example": null}]','chinese-xinhua','0'),
('2101143295886364686','猖','1','chānɡ','犭','11',NULL,'[{"def": "猖", "example": null}, {"def": "(形声。从犬,昌声。本义猖狂) 同本义", "example": null}, {"def": "猖", "example": null}, {"def": "猖狂的人", "example": null}, {"def": "苏枯弱强,龈其奸猖。--唐·韩愈《曹成王碑》", "example": null}, {"def": "猖 chāng凶猛～狂（狂妄而放肆）。", "example": null}, {"def": "【猖獗】", "example": null}, {"def": "①凶猛而放肆黑市～。", "example": null}, {"def": "②倾覆；跌倒。", "example": null}, {"def": "猖chāng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143295886364687','菖','1','chānɡ','艹','11',NULL,'[{"def": "菖", "example": null}, {"def": "草名。菖蒲的简称", "example": null}, {"def": "菖蒲", "example": null}, {"def": "菖chāng", "example": null}]','chinese-xinhua','0'),
('2101143295886364688','阊','1','chānɡ','门','11',NULL,'[{"def": "阊 (形声。从门,昌声。 本义阊阖)", "example": null}, {"def": "阊阖", "example": null}, {"def": "阊,天门也。楚人名门曰阊阖。--《说文》", "example": null}, {"def": "排阊阖而入帝宫。--《史记·司马相如传》", "example": null}, {"def": "吾令帝阍开关兮,倚阊阖而望予。--屈原《楚辞·离骚》", "example": null}, {"def": "九天阊阖开宫殿,万国衣冠拜冕旒。--王维《和贾舍人早朝大明宫之作》", "example": null}, {"def": "阊门", "example": null}, {"def": "《阊门即事》--唐·张继", "example": null}, {"def": "阊chāng", "example": null}, {"def": "⒈", "example": null}, {"def": "①神话传说中的天门。", "example": null}, {"def": "②皇宫的正门。", "example": null}, {"def": "⒉", "example": null}, {"def": "阊tāng 1.鼓声。", "example": null}]','chinese-xinhua','0'),
