('2101143295886364713','抄','1','chāo','扌','7',NULL,'[{"def": "抄", "example": null}, {"def": "(形声。从手,少声。本义叉取)", "example": null}, {"def": "同本义", "example": null}, {"def": "掠取,抢掠", "example": null}, {"def": "抄写", "example": null}, {"def": "搜查并没收", "example": null}, {"def": "而抄捕南海馆之报忽至。--清·梁启超《谭嗣同传》", "example": null}, {"def": "又如抄籍(抄没并登记归公);抄没(查抄没收)", "example": null}, {"def": "从侧面绕过去", "example": null}, {"def": "两手交叉在胸前或背后插在袖筒里", "example": null}, {"def": "顺手牵羊拿走", "example": null}, {"def": "抄 chāo", "example": null}, {"def": "①写～作业、～书本。", "example": null}, {"def": "②照着别人的作品、作业等写下来当做自己的～袭。", "example": null}, {"def": "③搜查并没收～家。", "example": null}, {"def": "④从侧面或较近的路过去～近路走。", "example": null}, {"def": "⑤两手在胸前相互地插在袖筒里～着手。", "example": null}, {"def": "⑥同\'绰", "example": null}, {"def": "①\'。", "example": null}, {"def": "【抄本】抄写的书本。宋代以前，书本全靠手抄，宋代以后，雕版印刷盛行，但少数流传面不广的书仍以抄本形式流传。", "example": null}, {"def": "【抄袭】", "example": null}, {"def": "①把别人的作品或语句抄来当作自己的。", "example": null}, {"def": "②机械地沿用别人的经验、方法等。", "example": null}, {"def": "③（军队）绕道袭击敌人。", "example": null}, {"def": "抄chāo", "example": null}, {"def": "⒈誊写～写。照～。", "example": null}, {"def": "⒉掠夺，搜查～家。～身。", "example": null}, {"def": "⒊用瓢或勺取物。", "example": null}, {"def": "⒋从侧面过去～近路。～到敌人后面去。", "example": null}, {"def": "⒌拿起～起车把。", "example": null}, {"def": "⒍", "example": null}, {"def": "①抄别人的文章、作品等当作自己的。", "example": null}, {"def": "②死板的沿用别人的经验、方法等。", "example": null}, {"def": "③绕到敌人的背面或侧面，出其不意的袭击敌人。", "example": null}, {"def": "⒎", "example": null}, {"def": "①两手交叉于胸前。", "example": null}, {"def": "②一种用面皮包馅，包成菱角形的食品。", "example": null}, {"def": "⒏通\\"绰\\"～起。～波菜。", "example": null}, {"def": "抄chào 1.用耖整地。即将翻耕过的土壤再用耖进行浅耕松土。 2.泛指翻土。", "example": null}]','chinese-xinhua','0'),
('2101143295886364714','弨','1','chāo','弓','8',NULL,'[{"def": "弨", "example": null}, {"def": "弓", "example": null}, {"def": "弨,弓反也。从弓,召声。--《说文》", "example": null}, {"def": "彤弓弨兮。--《诗·小雅·彤弓》", "example": null}, {"def": "大弨挂壁无由弯。--唐·韩愈《雪后寄崔二十六丞公》", "example": null}, {"def": "又如大弨(大弓)", "example": null}, {"def": "弨chāo 1.弓弦松弛貌。 2.弓。", "example": null}]','chinese-xinhua','0'),
('2101143295886364715','怊','1','chāo','忄','8',NULL,'[{"def": "怊", "example": null}, {"def": "悲痛", "example": null}, {"def": "怊,悲也。--《说文新附》", "example": null}, {"def": "怊乎若婴儿之失其母也。--《庄子·天地》", "example": null}, {"def": "怅恨;失意", "example": null}, {"def": "怊怅", "example": null}, {"def": "怊怅自失", "example": null}, {"def": "怊chāo悲伤失意～怅。", "example": null}]','chinese-xinhua','0'),
