('2101143295886364717','钞','1','chāo','钅','9',NULL,'[{"def": "钞", "example": null}, {"def": "掠取;抢掠◇作抄”", "example": null}, {"def": "钞,叉取也。从金,少声。--《说文》。俗字作抄。", "example": null}, {"def": "遮取谓之抄掠。--《通俗文》", "example": null}, {"def": "攻钞郡县。--《后汉书·公孙瓒传》", "example": null}, {"def": "又如钞掠(劫掠骚扰;劫夺他人财物)", "example": null}, {"def": "誊写。也作抄”", "example": null}, {"def": "溥幼嗜学,所读书必手钞。--《明史·张溥传》", "example": null}, {"def": "又如钞白(抄录的公文副本);钞胥(担任誊录钞写工作的小吏。也作抄胥”)", "example": null}, {"def": "钞", "example": null}, {"def": "纸币名。现在称纸币为钞票,简称钞", "example": null}, {"def": "递制交钞,与钱并用。--《金史·食货志三》", "example": null}, {"def": "又如外钞(外国的钞票);冥钞(迷信人给死人烧的假钞票,有些地方叫纸钱)", "example": null}, {"def": "泛指钱", "example": null}, {"def": "钞chāo", "example": null}, {"def": "⒈纸币～票。现～。", "example": null}, {"def": "⒉通\\"抄\\"。誊写。", "example": null}]','chinese-xinhua','0'),
('2101143295886364718','焯','1','chāo','火','12',NULL,'[{"def": "焯", "example": null}, {"def": "把蔬菜放在开水里略微一煮就拿出来", "example": null}, {"def": "焯 chāo把蔬菜等放入开水里略微煮一下拿出来～萝卜丝。又见zhuō。", "example": null}, {"def": "焯chāo", "example": null}, {"def": "⒈也作\\"绰\\"。将菜放入开水里稍微一煮就取出来～豌豆尖。", "example": null}, {"def": "焯zhuō", "example": null}, {"def": "⒈显明，明白。", "example": null}]','chinese-xinhua','0'),
('2101143295886364719','超','1','chāo','走','12',NULL,'[{"def": "超", "example": null}, {"def": "(形声。从走,召声。本义跃上;跳过,跃过)", "example": null}, {"def": "同本义", "example": null}, {"def": "超,跳也。--《说文》", "example": null}, {"def": "超乘者五百乘。--《吕氏春秋·悔过》。注巨踊上车也。”", "example": null}, {"def": "超回志度。--《楚辞·九章·抽思》", "example": null}, {"def": "超五岭兮嵯峨。--《楚辞·九思·伤时》", "example": null}, {"def": "方投石超距。--《史记·白起王翦传》", "example": null}, {"def": "挟泰山以超北海。--《孟子·梁惠王上》", "example": null}, {"def": "又如超乘(跃登战车);超足(腾跃);超步(跨登;迈步);超次(超越等级升迁)", "example": null}, {"def": "提拔;擢升", "example": null}, {"def": "故莫敢超等逾官。--《管子·法禁》", "example": null}, {"def": "又如超拜(越级升授官职);超阶(指超级擢升的官职)", "example": null}, {"def": "超过;胜过", "example": null}]','chinese-xinhua','0'),
