('2101143295890559002','龀','1','chèn','齿','10',NULL,'[{"def": "龀", "example": null}, {"def": "(会意。从齿,匕声。本义儿童换牙,脱乳齿换恒齿) 同本义", "example": null}, {"def": "龀,毁齿也。男八月生齿,八岁而龀;女七月生齿,七岁而龀。--《说文》", "example": null}, {"def": "未龀不入军门。--《管子·小问》", "example": null}, {"def": "又如龀髫(换牙和垂发。喻幼年);龀龆(指幼年);始龀(刚换牙,指七八岁)", "example": null}, {"def": "龀", "example": null}, {"def": "乳齿", "example": null}, {"def": "泛指童年", "example": null}, {"def": "龀chèn小孩脱掉乳齿，长出（换上）恒齿的过程。", "example": null}]','chinese-xinhua','0'),
('2101143295890559003','趁','1','chèn','走','12',NULL,'[{"def": "趁", "example": null}, {"def": "(形声。本义追逐)", "example": null}, {"def": "同本义", "example": null}, {"def": "急逐趁之,蟆入草间。--《聊斋志异·促织》", "example": null}, {"def": "又如疾趁(急追);趁逐(追逐;追求);趁赶(追逐)", "example": null}, {"def": "乘便", "example": null}, {"def": "满足,遂。用同称”", "example": null}, {"def": "趁", "example": null}, {"def": "组成介词结构,用在动词前面,表示利用某种条件、某个时间或机会进行某种事情", "example": null}, {"def": "趁 chèn", "example": null}, {"def": "①利用某种便利条件～机、～便。", "example": null}, {"def": "②追逐；赶上。", "example": null}, {"def": "【趁火打劫】趁别人家失火去抢劫钱财。比喻趁危机的时候占别人的便宜，侵犯别人的权益等。", "example": null}, {"def": "【趁热打铁】比喻做事抓紧时机，加速行动。", "example": null}, {"def": "趁chèn", "example": null}, {"def": "⒈顺便，乘机会～便。～车。～机。～虚而入。", "example": null}, {"def": "⒉〈方〉富有～钱。～粮。", "example": null}, {"def": "⒊通\\"称\\"。适合～心。～意。", "example": null}]','chinese-xinhua','0'),
('2101143295890559004','榇','1','chèn','木','13',NULL,'[{"def": "榇", "example": null}, {"def": "古时指空棺,后泛指棺材", "example": null}, {"def": "榇,棺也。--《说文》", "example": null}, {"def": "空棺谓之榇,有尸谓之柩。--《小尔雅》", "example": null}, {"def": "自为榇与颂琴。--《左传·襄公二年》", "example": null}, {"def": "送汝昌榇南归。--《清稗类钞·外交类》", "example": null}, {"def": "又如扶榇归里", "example": null}, {"def": "梧桐的别名", "example": null}, {"def": "榇（櫬）chèn棺材扶～。", "example": null}, {"def": "榇qìn 1.木名。即木槿。", "example": null}]','chinese-xinhua','0'),
('2101143295890559005','衬','1','chèn','衤','8',NULL,'[{"def": "衬", "example": null}, {"def": "(形声。从衣,觝声。本义外衣内的单衫)", "example": null}, {"def": "同本义。又称衬衫", "example": null}, {"def": "附在衣服鞋帽里的布", "example": null}, {"def": "垫,衬垫", "example": null}, {"def": "衬", "example": null}, {"def": "施舍,布施", "example": null}, {"def": "衬托", "example": null}, {"def": "相帮", "example": null}, {"def": "衬 chèn", "example": null}, {"def": "①在里面托一层～一点纸。", "example": null}, {"def": "②衬在里面的～衣、西服、布。", "example": null}, {"def": "③附在衣裳、鞋、帽等某一部分的布制品帽～。", "example": null}, {"def": "④映衬；衬托绿叶、红花。", "example": null}, {"def": "【衬托】利用事物间的近似或对立的条件、用一些事物为陪衬来突出所要表现的事物的写作手法。它可以使被陪衬事物显得更加突出、形象，富有艺术魅力，是情节构造、意境", "example": null}, {"def": "创造、人物描写等的有效手法。衬托有正衬、反衬两类利用事物的相似条件来衬托的是正衬；利用事物的相反条件来衬托的是反衬。", "example": null}, {"def": "【衬字】歌词里为使韵律优美或表达意境的需要而增加的没有实义的字。如\'风吹那个雪花满天飘\'中的\'那个\'。", "example": null}, {"def": "衬（襯）chèn", "example": null}, {"def": "⒈里面的，托在里面的～衣。～上一层棉絮。", "example": null}, {"def": "⒉配搭，从旁帮助～托。帮～。相互映～。", "example": null}]','chinese-xinhua','0'),
