('2101143295894753290','琛','1','chēn','王','12',NULL,'[{"def": "琛", "example": null}, {"def": "(形声。从玉,羇声。本义珍宝)", "example": null}, {"def": "同本义。常作贡物", "example": null}, {"def": "琛,宝也。--《说文新附》", "example": null}, {"def": "来献其琛。--《诗·鲁颂·泮水》", "example": null}, {"def": "献琛执贽。--张衡《东京赋》", "example": null}, {"def": "其琛赂则琨瑶之阜。--左思《吴都赋》", "example": null}, {"def": "又如琛贡(珍宝贡品);琛宝(珠宝)", "example": null}, {"def": "玉", "example": null}, {"def": "琛chēn珍宝献～。", "example": null}]','chinese-xinhua','0'),
('2101143295894753291','嗔','1','chēn','口','13',NULL,'[{"def": "嗔", "example": null}, {"def": "(形声。从口,真声。本义发怒;生气)", "example": null}, {"def": "同本义。也作謓”", "example": null}, {"def": "謓,恚也。--《说文》", "example": null}, {"def": "字亦作嗔。又如嗔怒(生气;发怒);嗔怪(生气怪罪)", "example": null}, {"def": "责怪;埋怨", "example": null}, {"def": "用同謓”。睁大眼睛", "example": null}, {"def": "嗔怪", "example": null}, {"def": "孩子不懂事,你就别总嗔怪他了", "example": null}, {"def": "嗔 chēn", "example": null}, {"def": "①发怒；生气。", "example": null}, {"def": "②对人不满；生气；怪罪～怪。", "example": null}, {"def": "【嗔怪】对别人的言行表示不满。", "example": null}, {"def": "嗔(也写作\\"瞋\\")chēn生气，对人不满，嫌～怒。～怪。莫～着他。", "example": null}, {"def": "嗔tián 1.盛貌。参见\\"嗔嗔\\"﹑\\"嗔咽\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295894753292','綿','1','chēn','糹','14',NULL,'[{"def": "綿", "example": null}, {"def": "止", "example": null}, {"def": "綿,止也。--《说文》。王筠句读綿,盖谓针线之讫止也。”", "example": null}, {"def": "善", "example": null}, {"def": "綿,善也。--《尔雅》", "example": null}, {"def": "lin", "example": null}, {"def": "（佩物等）下垂的样子，如冠其映盖兮，嵒嵒珮～～以煇煌。”", "example": null}, {"def": "綿shēn 1.衣裳﹑羽毛下垂貌。亦以形容彗星拖长的尾巴。", "example": null}, {"def": "綿lín 1.衣裳﹑羽毛下垂貌。亦以形容彗星拖长的尾巴。", "example": null}]','chinese-xinhua','0'),
