('2101143295898947586','惩','1','chénɡ','心','12',NULL,'[{"def": "惩", "example": null}, {"def": "(形声。从心,征声。本义警戒;鉴戒)", "example": null}, {"def": "同本义", "example": null}, {"def": "惩,戒也。--《玉篇》", "example": null}, {"def": "惩,恐也。--《广雅》", "example": null}, {"def": "则民有所惩。--《礼记·表记》", "example": null}, {"def": "不惩其心。--《诗·小雅·节南山》", "example": null}, {"def": "又如惩毖(受创于前,当戒慎于后);惩纠(告戒督察);惩示(警告)", "example": null}, {"def": "处罚", "example": null}, {"def": "惩恶而劝善。--《左传·成公十四年》", "example": null}, {"def": "惩肆而去贪。--《左传·成公三十一年》", "example": null}, {"def": "又如惩劝(责罚与奖赏);惩恶劝善(贬斥坏人,奖励好人);惩创(惩戒;警惕)", "example": null}, {"def": "改定", "example": null}, {"def": "变律改经,一皆惩革。--陆倕《新刻漏铭》", "example": null}, {"def": "克制;制止", "example": null}, {"def": "惩 chéng", "example": null}, {"def": "①处罚～处。", "example": null}, {"def": "②警戒～前毖后。", "example": null}, {"def": "【惩恶劝善】惩罚坏人，奖励好人。", "example": null}, {"def": "【惩戒】通过惩罚来达到警戒的目的。", "example": null}, {"def": "【惩前毖后】以过去的教训为警戒，谨防以后重犯错误。毖使谨慎。", "example": null}, {"def": "惩（懲）chéng", "example": null}, {"def": "⒈警戒～前毖后。", "example": null}, {"def": "⒉责罚，处罚～罚。～办。严～。", "example": null}]','chinese-xinhua','0'),
('2101143295898947587','程','1','chénɡ','禾','12',NULL,'[{"def": "程", "example": null}, {"def": "(形声。从禾,呈声。本义称量谷物,并用作度量衡的总名)", "example": null}, {"def": "度量衡的总称", "example": null}, {"def": "按度程。--《礼记·月令》", "example": null}, {"def": "程者,物之准也。--《荀子·致仕》", "example": null}, {"def": "法式;章程,规格", "example": null}, {"def": "张苍定章程。--《汉书·高帝纪》", "example": null}, {"def": "又如章程(书面写定的组织规程或办事条例);程考(按科举常规考试);程品(法式;规范);程法(程式;法则)", "example": null}, {"def": "典范;法度", "example": null}, {"def": "匪先民是程。--《诗·小雅》", "example": null}, {"def": "后世以为法程。--《吕氏春秋·慎行》", "example": null}, {"def": "又如程律(法律);程墨(作为范本阅读的八股文选集)", "example": null}, {"def": "限度;期限", "example": null}]','chinese-xinhua','0'),
