('2101143295898947595','酲','1','chénɡ','酉','14',NULL,'[{"def": "酲", "example": null}, {"def": "(形声。从酉,呈声。酉”,意思是酒。本义酒醒后神志不清有如患病的感觉)", "example": null}, {"def": "同本义", "example": null}, {"def": "酲,病酒也。--《说文》", "example": null}, {"def": "忧心如酲。--《诗·小雅·节南山》", "example": null}, {"def": "嗅之则使人狂酲。--《庄子·人间世》", "example": null}, {"def": "罔然若酲。--张衡《东京赋》", "example": null}, {"def": "又如酲困(酒后困疲如病);酲酲(酒醉昏沉的样子)", "example": null}, {"def": "烦病", "example": null}, {"def": "嘘唏烦酲。--枚乘《七发》", "example": null}, {"def": "酲烦兮海鸟欲飞而无羽翼。--章炳麟《邹容画像赞》", "example": null}, {"def": "酲", "example": null}, {"def": "酒醒;清醒", "example": null}, {"def": "酲,一曰醉而觉也。--《说文》", "example": null}, {"def": "酲,醉解也。--《字林》", "example": null}, {"def": "其甘不爽,醉而不酲…--《文选·张衡·南都赋》", "example": null}, {"def": "酒醉", "example": null}, {"def": "酲 chéng酒醒后出现的困倦沉重感觉忧心如～。", "example": null}]','chinese-xinhua','0'),
('2101143295898947596','澄','1','chénɡ','氵','15',NULL,'[{"def": "澄  cheng", "example": null}, {"def": "(形声。从水,登声。本义水静而清)", "example": null}, {"def": "同本义", "example": null}, {"def": "澄,水清定也。--《集韵》", "example": null}, {"def": "澄,水静而清也。--《增韵》", "example": null}, {"def": "水色澄碧。--黄肇敏《黄山纪游》", "example": null}, {"def": "又如澄水(清澈而平静无波的水);澄江(清澄明澈的江水);澄泉(清泉);澄酒(清酒,淡酒)", "example": null}, {"def": "清澈,透明", "example": null}, {"def": "心澄体静。--徐干《中论》", "example": null}, {"def": "又如 澄空(晴朗无云的天空);澄明(澄澈明洁)", "example": null}, {"def": "静,宁静", "example": null}, {"def": "公退则敛膝澄坐以养心。--方孝儒《静斋记》", "example": null}, {"def": "又如澄凝(沉静的);澄谧(清静);澄宁(清静安定)", "example": null}, {"def": "澄", "example": null}, {"def": "让水中物沉淀;使清静;使清明", "example": null}, {"def": "澄 chéng", "example": null}, {"def": "①（水）清。", "example": null}, {"def": "②澄清。又见dèng。", "example": null}, {"def": "【澄彻】", "example": null}, {"def": "【澄澈】清彻透明。", "example": null}, {"def": "【澄清】", "example": null}, {"def": "①清亮。", "example": null}, {"def": "②肃清（混乱局势）。", "example": null}, {"def": "③弄清楚（认识、问题等）。", "example": null}, {"def": "澄（澂）chéng", "example": null}, {"def": "⒈水清～澈。", "example": null}]','chinese-xinhua','0'),
('2101143295898947597','橙','1','chénɡ','木','16',NULL,'[{"def": "橙", "example": null}, {"def": "(形声。从木,登声。本义果树名,果实叫橙子)", "example": null}, {"def": "同本义", "example": null}, {"def": "橙色", "example": null}, {"def": "橙", "example": null}, {"def": "①常绿乔木或灌木。果实叫橙子，呈圆形，果皮红黄色。", "example": null}, {"def": "②红和黄合成的颜色。", "example": null}, {"def": "橙chéng常绿乔木。花白色。果实叫\\"橙子\\"，品种很多，味酸甜不一，可食。果皮可供药用。种子可榨油。", "example": null}, {"def": "橙dèng 1.凳子。没有靠背的有足坐具。", "example": null}]','chinese-xinhua','0'),
