('2101143295898947611','逞','1','chěnɡ','辶','10',NULL,'[{"def": "逞", "example": null}, {"def": "(形声。从辵,呈声。本义通,通达)", "example": null}, {"def": "同本义", "example": null}, {"def": "逞,通也。--《说文》。傅云龙古语考补正通,达也,是其本义。通有行义,无疾义。”", "example": null}, {"def": "快意,实现,使称心", "example": null}, {"def": "今民馁而君逞欲。--《左传·桓公六年》", "example": null}, {"def": "使归就戮于秦,以逞寡君之志。--《左传·僖公三十三年》", "example": null}, {"def": "又如逞志(逐心如意,以求快意);逞欲(逐心如意,以求得到欲望的满足);逞心(快意;称心)", "example": null}, {"def": "炫耀", "example": null}, {"def": "放纵,恣肆", "example": null}, {"def": "逞 chěng", "example": null}, {"def": "①显示（才能、威风等）；夸耀～能、～凶。", "example": null}, {"def": "②（坏主意）达到目的得～。", "example": null}, {"def": "③纵容放任～性子。", "example": null}, {"def": "【逞强】显示自己能力强～好胜。", "example": null}, {"def": "逞chěng", "example": null}, {"def": "⒈显示，炫耀～能。～威风。", "example": null}, {"def": "⒉放任，放肆～性妄为。", "example": null}, {"def": "⒊称意，实现如愿以～。 骋chěng", "example": null}, {"def": "⒈奔驰弛～。", "example": null}, {"def": "⒉尽情施展，无拘束，放任～能。～望。～其邪欲。", "example": null}]','chinese-xinhua','0'),
('2101143295898947612','骋','1','chěnɡ','马','10',NULL,'[{"def": "骋", "example": null}, {"def": "(形声。从马,甹声。本义纵马向前奔驰)", "example": null}, {"def": "同本义", "example": null}, {"def": "骋,直驰也。--《说文》", "example": null}, {"def": "林楚怒马,及衢而骋。--《左传·定公八年》", "example": null}, {"def": "乘骐骥以驰骋兮。--《楚辞·离骚》", "example": null}, {"def": "又如驰骋(骑马奔驰);骋鹜(奔走驰骋);骋步(驰步快走)", "example": null}, {"def": "放任,放纵", "example": null}, {"def": "故其与万物接也,至无而供其求,时骋而要其宿。--《庄子·天地》", "example": null}, {"def": "又如骋心(恣意,快心);骋快(放纵);骋情(纵情)", "example": null}, {"def": "施展;发挥", "example": null}, {"def": "骋", "example": null}, {"def": "古州名", "example": null}, {"def": "骋 chěng", "example": null}, {"def": "①（马）奔驰驰～纵横。", "example": null}, {"def": "②尽情施展；不受拘束～目（放眼远望）。", "example": null}, {"def": "【骋怀】开怀。", "example": null}]','chinese-xinhua','0'),
