('2101143295898947620','撑','1','chēnɡ','扌','15',NULL,'[{"def": "撑", "example": null}, {"def": "(形声。从手,掌声。本义支撑,支持)", "example": null}, {"def": "同本义", "example": null}, {"def": "天津流水波赤血,白骨相撑如乱麻。--李白《扶风豪士歌》", "example": null}, {"def": "又如用两手撑着下巴;撑扶(支撑扶持);撑天拄地(喻顶天立地)", "example": null}, {"def": "用篙抵住河底使船行进", "example": null}, {"def": "维持,保持", "example": null}, {"def": "他死活也得把这个门面撑着", "example": null}, {"def": "两场球下来,他恐怕撑不住了", "example": null}, {"def": "又如撑场面;撑持", "example": null}, {"def": "抢", "example": null}, {"def": "积攒;购买", "example": null}, {"def": "我儿花衣裳、头面,多末勿算多,撑得来", "example": null}, {"def": "撑 chēng", "example": null}, {"def": "①抵住用手、腰。", "example": null}, {"def": "②用篙抵住河底使船行进～船。", "example": null}, {"def": "③支持这儿人手太少，你先给、上两天。", "example": null}, {"def": "④张开把口袋～开、～伞。", "example": null}, {"def": "⑤充满到容不下的地步；饱胀吃～了。", "example": null}, {"def": "【撑竿跳高】田赛项目之一。运动员经快速助跑后，把所持竿子插入抽斗内起跳，使身体悬垂竿上，再越过横竿。", "example": null}, {"def": "撑（撐）chēng", "example": null}, {"def": "⒈抵住～篙。～竿跳高。", "example": null}, {"def": "⒉支持～腰。～门面。", "example": null}, {"def": "⒊张开～伞。将包～开。", "example": null}, {"def": "⒋装满，塞足～肠拄肚（腹中饱满，装满了肠胃。〈喻〉能够容纳）。箱子里～不下了。", "example": null}]','chinese-xinhua','0'),
('2101143295898947621','瞠','1','chēnɡ','目','16',NULL,'[{"def": "瞠〈动〉", "example": null}, {"def": "瞪着眼看", "example": null}, {"def": "瞠,直视也。--《集韵》", "example": null}, {"def": "夫子奔逸绝尘,而回瞠若乎后矣。--《庄子·田子方》", "example": null}, {"def": "又如瞠瞠(张目直视貌)。又指惊视", "example": null}, {"def": "众目亦益瞠,口亦益张。--鲁迅《集外集拾遗》", "example": null}, {"def": "瞠 chēng瞪着眼睛看。", "example": null}, {"def": "【瞠乎其后】在后面干瞪眼。形容远远落后于人。", "example": null}, {"def": "【瞠目结舌】干瞪眼说不出话来。形容受窘或惊呆了的样子。", "example": null}, {"def": "瞠chēng直视，瞪着眼睛～目而视。～乎其后（落在后面干瞪眼，赶不上）。", "example": null}]','chinese-xinhua','0'),
('2101143295898947622','頳','1','chēnɡ','','6',NULL,'[{"def": "頳chēng", "example": null}, {"def": "⒈古同??”。", "example": null}]','chinese-xinhua','0'),
('2101143295898947623','称','1','chēnɡ','禾','10',NULL,'[{"def": "称  chen", "example": null}, {"def": "符合,相当", "example": null}, {"def": "令作诗,不能称前时之闻。--宋·王安石《伤仲永》", "example": null}, {"def": "薄罚不为慈,诛严不为戾,称俗而行也。--《韩非子·王蠹》", "example": null}, {"def": "夫才德不称,固自知之矣。--宗臣《报刘一丈书》", "example": null}, {"def": "又如对称;相称;称合(相当);称任(称职,犹胜任);称位(与职位相符)", "example": null}, {"def": "称  cheng", "example": null}, {"def": "(形声。从禾,爯声。本义称量物体轻重的器具。这个意义后来写作秤”。又指称量)", "example": null}, {"def": "测定重量", "example": null}, {"def": "苦称量之不审兮。--《楚辞·惜誓》。注称所以知轻重。”", "example": null}, {"def": "又如称物(衡量物之多少,轻重);称亭(称量平正);称验(过称检验)。泛指衡量、揣度。又", "example": null}, {"def": "称 chèn合适；相当～心如意。又见chēng。", "example": null}, {"def": "【称体裁衣】按照身体的长短大小裁衣服。比喻做事要恰到好处。", "example": null}, {"def": "【称职】才能与职位相称；思想、能力等能胜任所担任的职务。", "example": null}, {"def": "称 chēng", "example": null}, {"def": "①叫；叫做人们～他为老英雄。", "example": null}, {"def": "②名称昵～、蔑～。", "example": null}, {"def": "③说连声～好、点头～是。", "example": null}, {"def": "④赞扬～许。", "example": null}, {"def": "⑤测重量～2斤糖。", "example": null}, {"def": "⑥举～觞。又见chèn。", "example": null}, {"def": "【称道】称赞；夸奖值得～。", "example": null}, {"def": "【称孤道寡】以帝王、首脑自居。\'孤\'、\'寡人\'均为古代封建帝王的自称。现多讽刺自大的人。", "example": null}, {"def": "【称量瓶】精确称量分析试样用的小型玻璃仪器。一般为圆柱形，带有磨口密合的瓶盖。", "example": null}, {"def": "【称叹】赞叹～不已。", "example": null}, {"def": "【称谓】人们由于血缘和其他方面的相互关系以及由于身分、职业等等而得来的名称。如父亲、同志、先生、姑姑等。", "example": null}, {"def": "【称羡】称赞羡慕。", "example": null}, {"def": "【称雄】凭借武力或其他势力统治一方割据～。", "example": null}, {"def": "【称许】赞许。", "example": null}, {"def": "【称誉】表扬赞美。", "example": null}, {"def": "称（穛）chèng衡量轻重的器具台～。标准～。", "example": null}, {"def": "称（穛）chēng", "example": null}, {"def": "⒈衡量轻重～三斤肉。", "example": null}, {"def": "⒉名号名～。省～。别～。", "example": null}, {"def": "⒊叫，叫做～谓。～作。～兄道弟。", "example": null}, {"def": "⒋说，声言～谢。～好。～病。声～。", "example": null}, {"def": "⒌颂扬，赞许～颂。～许。～赞。", "example": null}, {"def": "⒍举，推举～兵。～贤举能。", "example": null}, {"def": "称（穛）chèn", "example": null}, {"def": "⒈适合，相当，相等～心。～职。相～。对～。德必～位。", "example": null}]','chinese-xinhua','0'),
