('2101143295898947628','浾','1','chēnɡ','','6',NULL,'[{"def": "浾chēng 1.棠枣之汁。《说文．赤部》\\"浾，棠枣之汁也。\\"棠枣之汁色赤，故亦泛指赤色汁液。", "example": null}]','chinese-xinhua','0'),
('2101143295898947629','偁','1','chēnɡ','亻','11',NULL,'[{"def": "偁", "example": null}, {"def": "同称”。称赞;称谓", "example": null}, {"def": "偁chēng 1.称举。 2.称呼。", "example": null}]','chinese-xinhua','0'),
('2101143295898947630','蛏','1','chēnɡ','虫','11',NULL,'[{"def": "蛏", "example": null}, {"def": "蛏子", "example": null}, {"def": "竹蛏等种类", "example": null}, {"def": "蛏（蟶）chēng", "example": null}, {"def": "⒈蛏子，蚌类软体动物。两块长方形的贝壳，呈淡褐色。生活在浅海泥沙中。肉鲜美可口。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143295898947631','铛','1','chēnɡ','钅','11',NULL,'[{"def": "铛", "example": null}, {"def": "锒铛。锁系囚人的铁索", "example": null}, {"def": "铛,锒铛也。从金,当声。--《说文》。按,锁曰锒铛。", "example": null}, {"def": "女子的耳饰", "example": null}, {"def": "足履革屣,耳悬金铛。--《北史》", "example": null}, {"def": "铛", "example": null}, {"def": "钟鼓的声音", "example": null}, {"def": "铛铛晓漏。--徐陵《与杨仆射书》", "example": null}, {"def": "又如铛铛", "example": null}, {"def": "cheng", "example": null}, {"def": "温器,似锅,三足", "example": null}, {"def": "烙饼或做菜用的平底浅锅", "example": null}, {"def": "鼎铛玉石,金块珠砾,弃掷逦迤。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如铛头(厨师)", "example": null}, {"def": "铛（鑛）chēng", "example": null}, {"def": "⒈一种平底浅锅。", "example": null}, {"def": "铛dāng 1.见\\"锒铛\\"。 2.女子的耳饰。 3.象声词。形容撞击金属的声音。", "example": null}, {"def": "铛tāng 1.见\\"铛?\\"。 2.一种小铜鼓。 3.古兵器名。形如半月，有柄。", "example": null}]','chinese-xinhua','0'),
('2101143295898947632','牚','1','chēnɡ','牙','12',NULL,'[{"def": "牚", "example": null}, {"def": "同撑”。支撑,抵拒", "example": null}, {"def": "拨", "example": null}, {"def": "斜柱。", "example": null}, {"def": "桌椅等腿中间的横木。", "example": null}, {"def": "牚", "example": null}, {"def": "斜柱。也作樘”", "example": null}, {"def": "枝牚杈枒而斜据。--《文选·王延寿·鲁灵光殿赋》", "example": null}, {"def": "牚儿", "example": null}, {"def": "牚chèng 1.起支撑作用的构件。如建筑物梁上的斜柱，桌椅腿间横档等。", "example": null}, {"def": "牚chēng 1.支撑;抵拒。参见\\"牚距\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295898947633','琤','1','chēnɡ','王','10',NULL,'[{"def": "琤", "example": null}, {"def": "玉相击声", "example": null}, {"def": "琤,玉声也。--《说文》", "example": null}, {"def": "非琴非筑,金撞而玉琤。--陈造《听雨赋》", "example": null}, {"def": "物的相击声", "example": null}, {"def": "琤,凡物戛击有声皆曰琤。--《正字通》", "example": null}, {"def": "琤琤", "example": null}, {"def": "琤璪", "example": null}, {"def": "琴声", "example": null}, {"def": "琤璪的溪水", "example": null}, {"def": "琤 chēng", "example": null}, {"def": "【琤琤】象声词。玉器相击声、琴声或流水声。", "example": null}, {"def": "琤chēng像声词。玉声、琴声、流水声等流水～ ～。", "example": null}]','chinese-xinhua','0'),
('2101143295898947634','趙','1','chēnɡ','赤','13',NULL,'[{"def": "趙", "example": null}, {"def": "浅红色;红色", "example": null}, {"def": "岸土赤而壁立,东坡先生所谓舟人指点岸如趙”者也。--宋·陆游《过大孤山小孤山》", "example": null}, {"def": "又如趙尾(赤色的鱼尾。比喻忧劳。旧说鱼劳则尾赤);趙霞(红色的云霞)", "example": null}, {"def": "趙", "example": null}, {"def": "颜色变红", "example": null}, {"def": "趙chēng红色。", "example": null}]','chinese-xinhua','0'),
