('2101143295898947638','踟','1','chí','足','15',NULL,'[{"def": "踟", "example": null}, {"def": "(形声。从足,知声。踟蹰。本义徘徊不进,犹豫)行不进也", "example": null}, {"def": "踟蹰", "example": null}, {"def": "搔首踟蹰。--《诗·邶风·静女》", "example": null}, {"def": "使君从南来,五马立踟蹰。--汉乐府《陌上桑》", "example": null}, {"def": "踟蹰不知所措", "example": null}, {"def": "也作踟躇”", "example": null}, {"def": "踟 chí", "example": null}, {"def": "【踟蹰不前】拿不定主意，不敢前进。", "example": null}, {"def": "踟chí", "example": null}, {"def": "①徘徊犹豫步～蹰于山隅。", "example": null}, {"def": "②相连的样子。", "example": null}]','chinese-xinhua','0'),
('2101143295898947639','篪','1','chí','竹','16',NULL,'[{"def": "篪", "example": null}, {"def": "(形声。从竹,虒声。本义古时候一种用竹管制成的乐器)", "example": null}, {"def": "同本义", "example": null}, {"def": "泛指吹管乐器", "example": null}, {"def": "快马健儿,不知老妪吹篪。--《洛阳伽蓝记》", "example": null}, {"def": "篪（竾、箎）chí", "example": null}, {"def": "⒈一种竹子～竹。", "example": null}, {"def": "⒉〈古〉一种竹管乐器吹～。", "example": null}]','chinese-xinhua','0'),
