('2101143295898947641','弛','1','chí','弓','6',NULL,'[{"def": "弛", "example": null}, {"def": "(形声。从弓,也声。本义放松弓弦)", "example": null}, {"def": "同本义", "example": null}, {"def": "弛,弓解也。--《说文》", "example": null}, {"def": "弛弓尚角。--《礼记·曲礼》", "example": null}, {"def": "一张一弛。--《礼记·杂记》", "example": null}, {"def": "乃弛弓而自后缚之。--《左传·襄公十八年》", "example": null}, {"def": "弧弓弛而不张。--《楚辞·谬谏》", "example": null}, {"def": "又如弛张(一松一紧。弛,放松弓弦;张,拉紧弓弦)", "example": null}, {"def": "松弛,放松", "example": null}, {"def": "弛,缓也。--《广雅》", "example": null}, {"def": "四日弛力。--《周礼·大司徒》。注息徭役也。”", "example": null}, {"def": "病热而筋弛。--《素问·刺要论》", "example": null}, {"def": "又如弛易(松慢;变换);弛纵(放纵);弛玩(松懈玩忽)", "example": null}, {"def": "解除", "example": null}, {"def": "令弛县。--《周礼·大司乐》。注释下", "example": null}, {"def": "弛chí", "example": null}, {"def": "⒈放松弓弦～弓。", "example": null}, {"def": "⒉放松，松懈松～。", "example": null}, {"def": "⒊延缓～期。", "example": null}, {"def": "⒋毁坏废～。", "example": null}, {"def": "⒌解除～禁。～于负担。", "example": null}, {"def": "弛shǐ 1.放松弓弦。 2.解除。 3.松懈;放纵;松弛。 4.延缓。参见\\"弛期\\"。 5.减弱。 6.舍弃;放下。 7.毁坏;败坏。 8.脱落。 9.改易，更换。", "example": null}, {"def": "弛shī 1.施予。 2.施行，实施。", "example": null}]','chinese-xinhua','0'),
('2101143295898947642','池','1','chí','氵','6',NULL,'[{"def": "池", "example": null}, {"def": "(形声。从水,也声。本义水停积处)", "example": null}, {"def": "水塘", "example": null}, {"def": "池,停水曰池。--《广韵》", "example": null}, {"def": "穿地畜水,圆者曰池,方者曰塘。--《中文大辞典》", "example": null}, {"def": "池之竭矣。--《诗·大雅·召》", "example": null}, {"def": "或饮于池。--《诗·小雅·无羊》", "example": null}, {"def": "毋漉陂池。--《礼记·月令》。注穿地通水曰池。”", "example": null}, {"def": "掌沟渎浍池之禁。--《周礼·雍氏》。注谓陂障之水道也。”", "example": null}, {"def": "囿有林池。--《国语·周语》", "example": null}, {"def": "有良田美池桑竹之属。--晋·陶渊明《桃花源记》", "example": null}, {"def": "鸟宿池边树,僧敲月下门。--唐·贾岛《题李凝幽居》", "example": null}, {"def": "又如游泳池;池苑(池林园。有池水与林木的地方);池阁(位于池畔的楼", "example": null}, {"def": "池 chí", "example": null}, {"def": "①池塘养鱼～。", "example": null}, {"def": "②旁边高中间低的地方舞～。", "example": null}, {"def": "③旧指剧场正厅的前部～座。", "example": null}, {"def": "④护城河城～。", "example": null}, {"def": "⑤姓。", "example": null}, {"def": "池chí", "example": null}, {"def": "⒈水塘（多指人工挖的）～塘。～沼。鱼～子。游泳～。", "example": null}, {"def": "⒉像池的，周边高中间凹的砚～。乐～。花～。便～。", "example": null}, {"def": "⒊护城河城～。城门失火，殃及～鱼。", "example": null}]','chinese-xinhua','0'),
('2101143295898947643','驰','1','chí','马','6',NULL,'[{"def": "驰", "example": null}, {"def": "(形声。从马,也声。本义车马疾行)", "example": null}, {"def": "同本义", "example": null}, {"def": "驰,大驱也。--《说文》", "example": null}, {"def": "弗驰弗驱。--《诗·唐风·山有枢》", "example": null}, {"def": "车驰卒奔。--《左传·宣公十二年》", "example": null}, {"def": "好驰马试剑。--《孟子·滕文公上》", "example": null}, {"def": "啬夫驰。--《左传·昭公十七年》", "example": null}, {"def": "项伯乃夜驰之沛公军。--《史记·项羽本纪》", "example": null}, {"def": "又驱使", "example": null}, {"def": "公诚能驰一介之使,加咫尺之书,则孝章可致,友道可弘矣。--汉·孔融《论盛孝章书》", "example": null}, {"def": "又如驰车(古代战场上快速奔走的马车、轻车;驾车行走);驰马(骑马快跑);驰道(为帝王行驶马车所筑的马路);驰报(疾驰传报);驰夫(骑马送信的差役)", "example": null}, {"def": "疾行", "example": null}, {"def": "驰 chí", "example": null}, {"def": "①（车马等）快跑奔～。", "example": null}, {"def": "②传扬～名中外。", "example": null}, {"def": "③（心神）向往神～。", "example": null}, {"def": "【驰骋】（骏马）奔驰～千里。", "example": null}, {"def": "【驰名】声名远扬。又作驰誉。", "example": null}, {"def": "【驰誉】见【驰名】。", "example": null}, {"def": "【驰骤】奔驰纵横～。", "example": null}, {"def": "驰chí", "example": null}, {"def": "⒈奔跑，使劲赶马。〈引〉车马疾行奔～。～骋。疾～。特指驱马进击将～之。", "example": null}, {"def": "⒉向往心～神往。", "example": null}, {"def": "⒊传扬～名中外。", "example": null}, {"def": "驰tuó 1.参见\\"橐驰\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295898947644','迟','1','chí','辶','7',NULL,'[{"def": "迟", "example": null}, {"def": "(形声。本义慢慢走)", "example": null}, {"def": "同本义。泛指慢", "example": null}, {"def": "迟,徐行也。--《说文》", "example": null}, {"def": "迟,缓也。--《广雅》", "example": null}, {"def": "废彻不迟。--《诗·小雅·楚茨》", "example": null}, {"def": "行道迟迟。--《诗·邶风·谷风》", "example": null}, {"def": "迟归有待。--《易·归妹》", "example": null}, {"def": "陵迟故也。--《荀子·宥坐》", "example": null}, {"def": "三日断五匹,大人故嫌迟。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "又如迟徐(缓慢);迟滞(缓慢阻滞)", "example": null}, {"def": "迟钝;反应慢,不灵敏", "example": null}, {"def": "料事同而迟速不同。--魏源《默觚下》", "example": null}, {"def": "周少言重迟。--《汉书·杜周传》。注谓性非敏速也。”", "example": null}, {"def": "迟疑;犹豫", "example": null}, {"def": "寻声暗问弹者谁,琵琶声", "example": null}, {"def": "迟 chí", "example": null}, {"def": "①缓慢行动～缓。", "example": null}, {"def": "②比规定或合适的时间靠后推～、～到早退。", "example": null}, {"def": "③姓。", "example": null}, {"def": "【迟暮】指人的晚年。", "example": null}, {"def": "【迟效肥料】所含养分必须经过微生物分解转化才能被植物吸收利用的肥料。其见效迟缓而后效长，适于作基肥。包括大部分有机肥料及溶解度小的无机肥料。", "example": null}, {"def": "【迟疑】拿不定主意～不决。", "example": null}, {"def": "【迟滞】（流通）缓慢河水～。", "example": null}, {"def": "迟（遲）chí", "example": null}, {"def": "⒈缓慢～缓。～ ～不走。", "example": null}, {"def": "⒉晚～到。～熟。", "example": null}, {"def": "⒊不灵敏～钝。", "example": null}, {"def": "⒋长久～久而不相及。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①早晚。", "example": null}, {"def": "②或早或晚。", "example": null}, {"def": "迟zhì 1.等待。 2.比及，等到。 3.想望，希望。 4.接待，招待。 5.副词。乃。", "example": null}]','chinese-xinhua','0'),
