('2101143295898947646','持','1','chí','扌','9',NULL,'[{"def": "持", "example": null}, {"def": "(形声。从手,寺声。本义拿着)", "example": null}, {"def": "同本义", "example": null}, {"def": "持,握也。--《说文》", "example": null}, {"def": "持弓矢审固。--《礼记·射义》", "example": null}, {"def": "有持盈。--《国语·越语》", "example": null}, {"def": "客持头往见楚王,王大喜。--晋·干宝《干将莫邪》", "example": null}, {"def": "秦王谓轲曰起,取武阳所持图。”--《战国策·燕策》", "example": null}, {"def": "又如持仗(手持武器);持斧操斤(拿着斧头);持笔;持戟", "example": null}, {"def": "引申为掌握;控制", "example": null}, {"def": "悖乱不可以持国。--《吕氏春秋·察 今》", "example": null}, {"def": "夫仁义辩智,非所以持国也。--《韩非子·五蠹》", "example": null}, {"def": "又如主持(负责掌握或处理);持事(管理事务);持权(掌权)", "example": null}, {"def": "保守,保持", "example": null}, {"def": "持久者知止足也。--《后", "example": null}, {"def": "持 chí", "example": null}, {"def": "①拿着；握着～枪。", "example": null}, {"def": "②保持住～久。", "example": null}, {"def": "③掌管；料理主～、～家。", "example": null}, {"def": "②对抗相～不下。", "example": null}, {"def": "【持家】料理家务～有方。", "example": null}, {"def": "【持久战】持续时间较长的作战。通常是在一方较强大并企图速战速决的条件下，另一方采取逐步削弱敌人、最后战胜敌人的战略方针而形成的。", "example": null}, {"def": "【持平】", "example": null}, {"def": "①公正；没有偏向。", "example": null}, {"def": "②指某一时期的数额同所相比时期的数额没有增加或减少，大致相等。", "example": null}, {"def": "【持球】", "example": null}, {"def": "①排球比赛规则。球在运动员腰部以上任何部位停留时间较长，或捞球、捧球等，皆为持球。", "example": null}, {"def": "②手球运动技术名词。是射门和传球的准备。包括单手持球和双手持球。", "example": null}, {"def": "【持续】连续不断最近以来、高温。", "example": null}, {"def": "【持续音】〈音〉指上方声部的进行脱离了低音的和弦结构，低音部采用延长音或重复音的手法来持续主音或属音。上方声部的进行一般都要还原到与低音相吻和的和弦来结束", "example": null}, {"def": "。持续音用于多声部音乐，有主音持续音、属音持续音与二重持续音等。", "example": null}, {"def": "【持斋】宗教信仰者遵守不吃荤或其它某种食物的戒律。", "example": null}, {"def": "【持之以恒】长期坚持下去。", "example": null}, {"def": "【持之有故】所持的见解和主张有根据。", "example": null}, {"def": "【持重】举动谨慎稳重老成～。", "example": null}, {"def": "持chí", "example": null}, {"def": "⒈拿着，撑住，支撑～笔。～刀。支～。扶～。", "example": null}, {"def": "⒉掌握，经管～政。主～。勤俭～家。", "example": null}, {"def": "⒊遵守不变～久。～续。坚～。保～。独～己见。～之以恒。", "example": null}, {"def": "⒋对抗，各不相让相～不下。各～己见。", "example": null}, {"def": "⒌控制，挟制劫～。", "example": null}]','chinese-xinhua','0'),
('2101143295898947647','墀','1','chí','土','15',NULL,'[{"def": "墀", "example": null}, {"def": "(形声。从土,犀声。本义古代殿堂上经过涂饰的地面)", "example": null}, {"def": "同本义", "example": null}, {"def": "墀,涂地也。--《说文》", "example": null}, {"def": "以丹漆地,故称丹墀。--《汉典职仪》", "example": null}, {"def": "故愿一登文石之陛,涉赤墀之涂。--《汉书》", "example": null}, {"def": "台阶上面的空地。也指台阶", "example": null}, {"def": "青琐丹墀。--《文选·张衡·西京赋》", "example": null}, {"def": "墀chí宫殿前台阶上面的空地。泛指台阶。", "example": null}]','chinese-xinhua','0'),
