('2101143295898947656','炽','1','chì','火','9',NULL,'[{"def": "炽", "example": null}, {"def": "(会意。从火,戠声。本义火旺)", "example": null}, {"def": "同本义。引申为凶猛,激烈;气焰高涨", "example": null}, {"def": "炽,盛也。--《说文》", "example": null}, {"def": "三月而炽之。--《考工记·钟氏》", "example": null}, {"def": "环顾国内,贼氛方炽。--孙文《黄花冈七十二烈士事略·序》", "example": null}, {"def": "又如炽火(炽燎。烈火);炽焰(烈焰);炽火(燃点灯烛);炽腾(火势猛烈,火苗上窜)", "example": null}, {"def": "兴盛,昌盛", "example": null}, {"def": "齐虽炽盛,不如如此。--《论衡·艺增》", "example": null}, {"def": "又如炽昌(昌盛);炽富(昌盛富足);炽茂(茂盛);炽发(勃发)", "example": null}, {"def": "炽", "example": null}, {"def": "烹煮", "example": null}, {"def": "钟氏染羽,以朱湛丹秫,三月而炽之。--《周礼·考工记·钟氏》", "example": null}, {"def": "湛炽必洁。--《礼记·月", "example": null}, {"def": "炽 chì热烈旺盛～热。", "example": null}, {"def": "【炽烈】旺盛猛烈。", "example": null}, {"def": "炽（熾）chì盛，火旺～盛。～炭。～热。", "example": null}]','chinese-xinhua','0'),
('2101143295898947657','翅','1','chì','羽','10',NULL,'[{"def": "翅", "example": null}, {"def": "(形声。从羽,支声。本义鸟类、昆虫的翅膀)", "example": null}, {"def": "同本义", "example": null}, {"def": "翅,翼也。--《说文》", "example": null}, {"def": "审视,巨身修尾,青项金翅。--《聊斋志异·促织》", "example": null}, {"def": "又如翅关(翅膀);翅趫(像张开两翼的样子);翅羽(鸟类两翅上的长羽)", "example": null}, {"def": "翼状物。事物的形状或作用像翅的部分", "example": null}, {"def": "鱼类的鳍", "example": null}, {"def": "翅 chì", "example": null}, {"def": "①鸟和昆虫的飞行器官，通称翅膀。", "example": null}, {"def": "②鱼翅。", "example": null}, {"def": "③物体上形状像翅膀的部分。", "example": null}, {"def": "【翅果】具有一个或多个翅状附属物的果实。翅由果皮延展而成，果皮干燥、不开裂，适于风传播。如榆、枫杨、槭等的果实。", "example": null}, {"def": "翅（翄）chì", "example": null}, {"def": "⒈鸟类、昆虫等用于飞行的器官～膀。振～飞翔。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143295898947658','敕','1','chì','攵','11',NULL,'[{"def": "敕", "example": null}, {"def": "(形声。从攴,束声。本义告诫,嘱咐)", "example": null}, {"def": "同本义", "example": null}, {"def": "敕,诫也。--《说文》", "example": null}, {"def": "敕天之命。--《虞书》", "example": null}, {"def": "又如敕晓(告戒晓谕);敕谕天下(朝廷告谕全国);敕戒(警戒,教诫)", "example": null}, {"def": "通饬”。整治;整饬", "example": null}, {"def": "既匡既敕。--《诗·小雅·楚茨》", "example": null}, {"def": "君子以明罚勅法。--《易·噬嗑》", "example": null}, {"def": "敕身齐戒。--《汉书·礼乐志》", "example": null}, {"def": "惧余身之未敕。--《后汉书·张衡传》", "example": null}, {"def": "又如敕法(整饬法令);敕设(整饬周备)", "example": null}, {"def": "委任,任命", "example": null}, {"def": "皇帝下命令", "example": null}, {"def": "敕", "example": null}, {"def": "皇", "example": null}, {"def": "敕 chì旧指皇帝的诏令；手～、～封。", "example": null}, {"def": "敕（勅）chì", "example": null}, {"def": "⒈告诫，嘱咐。特指皇帝的命令或诏书。", "example": null}, {"def": "⒉通\\"饬\\"。整顿，整治。", "example": null}]','chinese-xinhua','0'),
