('2101143295898947662','傺','1','chì','亻','13',NULL,'[{"def": "傺", "example": null}, {"def": "住,逗留", "example": null}, {"def": "傺,逗也。南楚谓之傺。--《方言》", "example": null}, {"def": "傺 chì", "example": null}]','chinese-xinhua','0'),
('2101143295898947663','彳','1','chì','彳','3',NULL,'[{"def": "彳", "example": null}, {"def": "(象形。小篆字字形象行”,象纵横相交的十字路。彳”是汉字部首之一,习惯上称为双人旁。从彳”的字多与行走、行为和道路有关。本义慢步行走)同本义", "example": null}, {"def": "slowly]", "example": null}, {"def": "彳,小步也。象人胫三属相连也。--《说文》。谓股、胫、足三属。", "example": null}, {"def": "彳亍中辍。--潘岳《射雉赋》", "example": null}, {"def": "又如彳彳亍亍(脚步声)", "example": null}, {"def": "彳亍", "example": null}, {"def": "踟蹰横渡口,彳亍上滩舟。--李贽《观涨》", "example": null}, {"def": "彳亍而无所趋", "example": null}, {"def": "彳chì左脚走叫\\"彳\\"，右脚走叫\\"亍\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295898947664','叱','1','chì','口','5',NULL,'[{"def": "叱", "example": null}, {"def": "(形声。从口,匕声。本义大声呵斥)", "example": null}, {"def": "同本义", "example": null}, {"def": "叱,呵也。--《说文》", "example": null}, {"def": "大呵为叱。--《苍颉篇》", "example": null}, {"def": "迮而吐之曰叱。--《通俗文》", "example": null}, {"def": "手剑而叱之。--《公羊传·庄公十二年》", "example": null}, {"def": "大儿初醒,夫叱大儿声。--《虞初新志·秋声诗自序》", "example": null}, {"def": "又如叱咤(怒喝);叱教(严格指教);叱辱(斥责侮辱)", "example": null}, {"def": "呼喊;吆喝", "example": null}, {"def": "回车叱牛牵向北。--白居易《卖炭翁》", "example": null}, {"def": "又如叱名(呼名,报名);叱令(喝令);叱叫(大声呼喝);叱嚷(叫嚷)", "example": null}, {"def": "叱", "example": null}, {"def": "斥声或叫声", "example": null}, {"def": "喑恶叱咤。--《史记·淮阴侯传》", "example": null}, {"def": "又如叱叱(呼喝声;大声指责的声音);叱咄(怒斥", "example": null}, {"def": "叱 chì大声斥骂怒～、～责。", "example": null}, {"def": "【叱骂】责骂。", "example": null}, {"def": "【叱咤风云】呵斥一声，风云都为之改变颜色。形容声势威力极大。", "example": null}, {"def": "叱chì", "example": null}, {"def": "⒈大声呵斥～敌∏～。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊呼喝，呼喊～牛声。", "example": null}]','chinese-xinhua','0'),
('2101143295898947665','斥','1','chì','斤','5',NULL,'[{"def": "斥", "example": null}, {"def": "(形声。从广,屰声。从广”,表示与房屋有关。屰”(不顺)也兼表字义,表示人从房屋里逆行而出。本义驱逐)", "example": null}, {"def": "同本义", "example": null}, {"def": "斥,却屋也。--《说文》。谓却退其屋不居。", "example": null}, {"def": "无益于民者斥。--《汉书·五帝纪》", "example": null}, {"def": "击吉斥之。--《汉书·江都易王非传》", "example": null}, {"def": "斥小疏弱。--《史记·天官书》", "example": null}, {"def": "程一日果以眦睚杀人,上大怒,立命斥出,付京兆。--王谠《唐语林》", "example": null}, {"def": "又如斥放(斥退放逐);斥遣(斥退,驱逐);斥远(摒拒疏远);斥去(排斥并使之离去)", "example": null}, {"def": "责备。又称斥詈,斥遣", "example": null}, {"def": "目晋侯斥杀。--《谷梁传·僖公五年》", "example": null}, {"def": "如申斥(斥责);驳", "example": null}, {"def": "斥 chì", "example": null}, {"def": "①责备～责、怒～。", "example": null}, {"def": "②使离开排～。", "example": null}, {"def": "③开拓；扩展～地千里。", "example": null}, {"def": "④侦查探测", "example": null}, {"def": "②候（侦查敌情的士兵）。", "example": null}, {"def": "⑤斥卤（指土地含有过多的盐碱成分，不适于耕种）。", "example": null}, {"def": "斥chì", "example": null}, {"def": "⒈使退去，使离去～退。屏～。排～。", "example": null}, {"def": "⒉谴责～责。驳～。痛～。", "example": null}, {"def": "⒊开拓～地千里。", "example": null}, {"def": "⒋多、广、满充～。", "example": null}, {"def": "⒌侦察，探测～骑。～山泽之险。～候（侦察敌情的士兵）。", "example": null}, {"def": "斥chǐ 1.小。", "example": null}]','chinese-xinhua','0'),
