('2101143295903141925','沖','1','chònɡ','','6',NULL,'[{"def": "沖chōng", "example": null}, {"def": "⒈液体浇、灌～茶。～服。～洗。", "example": null}, {"def": "⒉水撞击此处的堤不怕水～。", "example": null}, {"def": "⒊直上，向上钻向上～。干劲～天。气～牛斗。", "example": null}]','chinese-xinhua','0'),
('2101143295903141926','铳','1','chònɡ','钅','11',NULL,'[{"def": "铳", "example": null}, {"def": "斧头上受柄的孔", "example": null}, {"def": "铳,斧穿也。--《集韵》", "example": null}, {"def": "古代用火药发射弹丸的一种火器", "example": null}, {"def": "金属制的打眼器具,即铳子", "example": null}, {"def": "铳", "example": null}, {"def": "用铳射击", "example": null}, {"def": "不许说我回来过,说了张少爷会一枪铳了你。--沈从文《大小阮》", "example": null}, {"def": "顶撞", "example": null}, {"def": "铳子", "example": null}, {"def": "铳chòng", "example": null}, {"def": "⒈旧时的一种火枪火～。", "example": null}, {"def": "⒉铳子，金属制的一种打眼器具。又指使用铳子打眼或除去。", "example": null}, {"def": "⒊斧头装柄的地方。", "example": null}]','chinese-xinhua','0'),
('2101143295903141927','宠','1','chǒnɡ','宀','8',NULL,'[{"def": "宠", "example": null}, {"def": "(形声。从宀,龙声。本义尊崇)", "example": null}, {"def": "同本义", "example": null}, {"def": "宠神其祖。--《国语·楚语》。注尊也。”", "example": null}, {"def": "宠,尊居也。--《说文》", "example": null}, {"def": "宠名皆弃。--《左传·襄公三十年》。谓族也。", "example": null}, {"def": "又如宠存(尊崇慰问);宠重(尊崇重视);崇厉(尊崇勉励)", "example": null}, {"def": "宠爱", "example": null}, {"def": "君以为忠,而甚宠之。--《左传·昭公十年》", "example": null}, {"def": "不宜爱而受宠。--《论衡·幸偶》", "example": null}, {"def": "少姜有宠而死。--《左传·昭公三年》", "example": null}, {"def": "宠辱若惊。--《老子》", "example": null}, {"def": "上官大夫与之同列,争宠而心害其能。--《史记·屈原贾生列传》", "example": null}, {"def": "又如一家人很宠他;宠冠一时(备受宠爱,冠绝一时);宠拔(", "example": null}, {"def": "宠 chǒng（上对下）偏爱得～。", "example": null}, {"def": "【宠爱】过分喜爱；偏爱。", "example": null}, {"def": "【宠辱不惊】无论受宠或是受辱都无动于衷。形容把荣辱得失置之度外。", "example": null}, {"def": "【宠辱若惊】受宠受辱都感到不安。形容患得患失。", "example": null}, {"def": "【宠信】宠爱偏信（多含贬义）。", "example": null}, {"def": "【宠幸】旧时指帝王对后妃、臣下宠爱，后泛指地位高的人对地位低的人的宠爱。", "example": null}, {"def": "宠（寵）chǒng", "example": null}, {"def": "⒈偏爱，溺爱～爱。", "example": null}, {"def": "⒉荣耀～辱不惊。", "example": null}]','chinese-xinhua','0'),
