('2101143295903141933','翀','1','chōnɡ','羽','10',NULL,'[{"def": "翀", "example": null}, {"def": "鸟直着向上飞", "example": null}, {"def": "翀 天王子去,对日圣君怜。--唐·王维《恭懿太子抚歌》", "example": null}, {"def": "翀chōng通\\"冲\\"。向上直飞。", "example": null}]','chinese-xinhua','0'),
('2101143295903141934','舂','1','chōnɡ','臼','11',NULL,'[{"def": "舂", "example": null}, {"def": "把东西放在石臼或钵里捣去皮壳或捣碎", "example": null}, {"def": "舂,捣粟也。--《说文》", "example": null}, {"def": "城曰舂。--《后汉书·明帝纪》", "example": null}, {"def": "水舂河漕。--《后汉书·西羌传》。注即水碓也。”", "example": null}, {"def": "又如舂堂(又叫舂塘。舂谷的木槽);舂谷(舂捣谷物);舂揄(指舂米。捣米于臼曰舂,自臼取出曰揄)", "example": null}, {"def": "通冲”。冲击", "example": null}, {"def": "舂其喉以戈,杀之。--《史记·鲁周公世家》", "example": null}, {"def": "舂,撞也。以舂筑地为节也。--《释名》", "example": null}, {"def": "又如舂击(冲击);舂撞(冲撞;冲击)", "example": null}, {"def": "舂", "example": null}, {"def": "臼", "example": null}, {"def": "刚勇有力,能举石舂。--《聊斋志异》", "example": null}, {"def": "古代因犯罪或被俘等成为舂膳的奴隶", "example": null}, {"def": "舂 chōng把东西放在石臼或乳钵里捣去皮壳或捣碎～米、～药。", "example": null}, {"def": "舂chōng将谷物等放入臼里，捣去皮壳或捣碎～米。～花椒。", "example": null}]','chinese-xinhua','0'),
