('2101143295903141939','充','1','chōnɡ','儿','6',NULL,'[{"def": "充", "example": null}, {"def": "(会意。从儿,育省声。育子长大成人。本义长,高)", "example": null}, {"def": "同本义", "example": null}, {"def": "充,长也,高也。--《说文》", "example": null}, {"def": "宗人视牲告充。--《仪礼·特牲礼》", "example": null}, {"def": "满", "example": null}, {"def": "充,塞也。--《小尔雅》", "example": null}, {"def": "充,满也。--《广雅》", "example": null}, {"def": "冠盗充斥。--《左传·襄公三十一年》", "example": null}, {"def": "言充其阳也。--《谷梁传·庄公二十五年》", "example": null}, {"def": "颜色充盈。--《荀子·子道》", "example": null}, {"def": "又如充多(众多);充车(满车;喻数量众多);充房(满屋);充堂(满堂)", "example": null}, {"def": "足;实;富厚", "example": null}, {"def": "肥胖", "example": null}, {"def": "充", "example": null}, {"def": "装满;塞满", "example": null}, {"def": "充 chōng", "example": null}, {"def": "①满；实～足、～分。", "example": null}, {"def": "②装满；塞住～气、～耳不闻。", "example": null}, {"def": "③担当；担任～任。", "example": null}, {"def": "④冒充～内行。", "example": null}, {"def": "⑤姓。", "example": null}, {"def": "【充斥】充满（含贬意）。", "example": null}, {"def": "【充电】把直流电接到蓄电池的两极上，使蓄电池获得放电能力。也指电容器在电路中两极间带电。", "example": null}, {"def": "【充分必要条件】见【充要条件】。", "example": null}, {"def": "【充分必要条件假言推理】见【充要条件假言推理】。", "example": null}, {"def": "【充分条件】有甲必有乙，而没有甲也可能有乙这样一种条件。", "example": null}, {"def": "【充分条件假言推理】以充分条件假言判断为大前提的假言推理。规则是承认前件就要承认后件，否认后件就要否认前件；否认前件不能否认后件，承认后件不能承认前件。", "example": null}, {"def": "【充军】古代的一种流刑。把罪犯押解到边远的地方去服役。", "example": null}, {"def": "【充沛】充足旺盛精力～。", "example": null}, {"def": "【充气灯泡】灯泡的一种。制作时把灯泡内的空气抽空，放进一些惰性气体，如氖、氩等，以保持对灯丝的压力，减少离子的产生。", "example": null}, {"def": "【充要条件】有甲必有乙，无甲必无乙这样一种条件。又作充分必要条件。", "example": null}, {"def": "【充要条件假言推理】以充分必要条件假言判断为大前提的假言推理。规则是承认前件就要承认后件，否认前件就要否认后件；承认后件就要承认前件，否认后件就要否认前", "example": null}, {"def": "件。又作充分必要条件假言推理。", "example": null}, {"def": "【充溢】充满；流露心中、着幸福感。", "example": null}, {"def": "【充裕】充足宽裕国力～、时间～。", "example": null}, {"def": "【充足理由律】逻辑思维的基本规律之一，要求在同一思维过程中，思想要有论证性，一个真实的判断必须有它的充足理由为依据。", "example": null}, {"def": "充chōng", "example": null}, {"def": "⒈满，实，足～满。～实。～足。～分。～其量。", "example": null}, {"def": "⒉装填，塞住～电。～耳不闻。", "example": null}, {"def": "⒊担任，当做～任。～当。", "example": null}, {"def": "⒋假装冒～。～内行。～强。～能。", "example": null}]','chinese-xinhua','0'),
('2101143295903141940','冲','1','chōnɡ','冫','6',NULL,'[{"def": "冲", "example": null}, {"def": "(形声。从水,中声。本义向上涌流)", "example": null}, {"def": "同本义", "example": null}, {"def": "冲溶沅瀥。--木华《海赋》", "example": null}, {"def": "直上", "example": null}, {"def": "又如冲天(直上天空);冲汉(直上霄汉)", "example": null}, {"def": "以水、酒等浇注调制", "example": null}, {"def": "幸而后手里渐渐翻过来了,除了冲账的,反赢了好些--《红楼梦》", "example": null}, {"def": "又如红字冲销", "example": null}, {"def": "使曝光过的照相材料显影", "example": null}, {"def": "用水或其他液体冲洗", "example": null}, {"def": "冲", "example": null}, {"def": "深远", "example": null}]','chinese-xinhua','0'),
('2101143295903141941','忡','1','chōnɡ','忄','7',NULL,'[{"def": "忡", "example": null}, {"def": "(形声。从心,中声。忧愁的样子) 同本义", "example": null}, {"def": "忡,忧也。--《说文》", "example": null}, {"def": "忧心有忡。--《诗·邶风·击鼓》", "example": null}, {"def": "忧心忡忡。--《诗·召南·草虫》", "example": null}, {"def": "极劳心兮忡忡。--《楚辞·云中君》", "example": null}, {"def": "又如忡然(忧愁的样子);忡怅(忧伤惆怅)", "example": null}, {"def": "忡chōng忧愁不安的样子忧心～ ～。", "example": null}]','chinese-xinhua','0'),
('2101143295903141942','憧','1','chōnɡ','忄','15',NULL,'[{"def": "憧", "example": null}, {"def": "(形声。从心,童声。本义心神不定)", "example": null}, {"def": "同本义", "example": null}, {"def": "憧,意不定也。--《说文》", "example": null}, {"def": "憧憧往来。--《易·咸》", "example": null}, {"def": "心憧憧若涉大川,遭风而未薄。--《盐铁论》", "example": null}, {"def": "通憃”。愚笨的", "example": null}, {"def": "作起不敬以欺惑憧愚。--《大戴礼记·千乘》", "example": null}, {"def": "憧", "example": null}, {"def": "摇晃;摇曳", "example": null}, {"def": "憧 chōng", "example": null}, {"def": "【憧憧】往来不定；亿不定灯影～。", "example": null}, {"def": "【憧憬】对美好事物的向往～未来。", "example": null}, {"def": "憧chōng", "example": null}, {"def": "⒈心意不定。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "憧zhuàng 1.愚昩无知。", "example": null}]','chinese-xinhua','0'),
