('2101143295903141945','惆','1','chóu','忄','11',NULL,'[{"def": "惆", "example": null}, {"def": "(形声。从心,周声。本义失意)", "example": null}, {"def": "同本义", "example": null}, {"def": "惆,失意也。--《说文》", "example": null}, {"def": "惆然不嗛。--《荀子·礼论》。注怅然也。”", "example": null}, {"def": "心惆焉而自伤。--陆机《叹逝赋》", "example": null}, {"def": "又如惆然(失意的样子);惆惋(伤感惋惜)", "example": null}, {"def": "悲痛;悲伤", "example": null}, {"def": "惆 chóu悲伤；失意。", "example": null}, {"def": "【惆怅】因失意而伤感。", "example": null}, {"def": "惆chóu", "example": null}]','chinese-xinhua','0'),
('2101143295903141946','绸','1','chóu','纟','11',NULL,'[{"def": "绸", "example": null}, {"def": "(形声。从糸,周声。本义缠绕)", "example": null}, {"def": "同本义", "example": null}, {"def": "绸,缪也。--《说文》", "example": null}, {"def": "绸,缠也。--《广雅》", "example": null}, {"def": "绸缪束薪,三星在天。--《诗·唐风·绸缪》。毛传绸缪犹缠绵也。”", "example": null}, {"def": "捆缚", "example": null}, {"def": "薜荔柏兮蕙绸,荃桡兮兰旌。--屈原《九歌》。王逸注绸,束缚也。”", "example": null}, {"def": "绸", "example": null}, {"def": "(按古代汉语绸”字不当绸缎讲。作丝织品的绸”本写作紬”) 丝织品的总称", "example": null}, {"def": "绸", "example": null}, {"def": "通稠”。致密;稠密", "example": null}, {"def": "彼君子女,绸直如发。--《诗·小雅·都人士》。", "example": null}, {"def": "又如绸直(情情慎密,操行正直);绸沓(密集)", "example": null}, {"def": "绸 chóu薄而软的丝织品～缎、红～。", "example": null}, {"def": "【绸缪】", "example": null}, {"def": "①缠绵情意～。", "example": null}, {"def": "②用绳索紧密缠捆。引申为修补未雨～。", "example": null}, {"def": "【绸舞】中国一种传统舞蹈。表演者手执彩绸舞动并配以各种步伐。多为单人表演，现也有集体表演。多用于传统戏曲民间舞蹈表演及其他喜庆场合。", "example": null}, {"def": "绸chóu", "example": null}, {"def": "⒈绸子，一种薄而细软的丝织品～缎。纺～。", "example": null}, {"def": "⒉", "example": null}, {"def": "①缠绵，缠绕情意～缪。～缪束薪（束薪成捆的柴）。", "example": null}, {"def": "②整修未雨～缪（〈喻〉事先做好准备）。", "example": null}, {"def": "绸tāo 1.缠裹;套。", "example": null}]','chinese-xinhua','0'),
