('2101143295903141948','畴','1','chóu','田','12',NULL,'[{"def": "畴", "example": null}, {"def": "(形声。从田,寿声。本义已耕作的田地)", "example": null}, {"def": "同本义", "example": null}, {"def": "畴,耕地也。--《苍颉篇》", "example": null}, {"def": "畴,耕治之田也。象耕屈之形。--《说文》", "example": null}, {"def": "取我田畴而伍之。--《左传·襄公三十年》", "example": null}, {"def": "田畴荒芜。--《国语·周语 》", "example": null}, {"def": "修农圃之畴。--《汉书·萧望之传》", "example": null}, {"def": "农人告余以春及,将有事于西畴。--陶渊明《归去来兮辞》", "example": null}, {"def": "又如田畴(田地);畴陇(畦田;田亩)", "example": null}, {"def": "特指种麻的田", "example": null}, {"def": "同类,类别◇作俦”", "example": null}, {"def": "十日不食,无畴类尽死矣。--《管子·枢言》", "example": null}, {"def": "人与人相畴,家与家相畴。--《国语·齐语》。注畴,", "example": null}, {"def": "畴 chóu", "example": null}, {"def": "①田地田～、平～千里。", "example": null}, {"def": "②种类范～。", "example": null}, {"def": "畴（疇）chóu", "example": null}, {"def": "⒈田地田～。", "example": null}, {"def": "⒉类，同类，类别范～。物各有～。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
