('2101143295903141952','稠','1','chóu','禾','13',NULL,'[{"def": "稠", "example": null}, {"def": "(形声。从禾,周声。本义禾多而密)", "example": null}, {"def": "多", "example": null}, {"def": "稠,多也。--《说文》。按,禾多也。", "example": null}, {"def": "歌者稠。--《礼记·文王世子》注", "example": null}, {"def": "书策稠浊。--《战国策·秦策》。注多也。”", "example": null}, {"def": "稠人广众。--《汉书·灌夫传》", "example": null}, {"def": "忆往者峥嵘岁月稠。--毛泽东《沁园春·长沙》", "example": null}, {"def": "又如稠人(众人);稠人广坐(很多人聚会的场所);稠伙(犹稠众);稠众(众多)", "example": null}, {"def": "繁密", "example": null}, {"def": "稠,密也。--《玉篇》", "example": null}, {"def": "亦作绸”", "example": null}, {"def": "绸直如发。--《诗·小雅·都人》。传密直如发也。”", "example": null}, {"def": "又如稠云(密集的云);稠掩掩(密集而隐约无光);稠林(密林)", "example": null}, {"def": "浓厚,与稀”相对", "example": null}, {"def": "稠 chóu", "example": null}, {"def": "①液体中含某种固体成分很多；浓颜料调得太～了。", "example": null}, {"def": "②多而密麦苗很～、地窄人～。", "example": null}, {"def": "【稠环化合物】两个或两个以上碳环或杂环以共有环边而形成的多环有机化合物。如萘为稠环芳香烃。", "example": null}, {"def": "稠chóu", "example": null}, {"def": "⒈多而密～密。～人广坐。", "example": null}, {"def": "⒉浓厚，跟\\"稀\\"相对～粥。", "example": null}, {"def": "稠diào 1.见\\"稠?\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295903141953','筹','1','chóu','竹','13',NULL,'[{"def": "筹", "example": null}, {"def": "(形声。从竹,夀声。本义计数的用具)", "example": null}, {"def": "壶矢。古代投壶用的签子,形如箭筩", "example": null}, {"def": "筹,壶矢也。--《说文》。谓投壶之矢为 筹。", "example": null}, {"def": "筹室中五扶。--《礼记·投壶》。注矢也。”", "example": null}, {"def": "箭筹八十。--《仪礼·乡射礼》", "example": null}, {"def": "签筹;算筹", "example": null}, {"def": "射者中,弈者胜,觥筹交错。--欧阳修《醉翁亭记》", "example": null}, {"def": "又如竹筹;筹马(古时投壶计数的用具)", "example": null}, {"def": "筹", "example": null}, {"def": "算计", "example": null}, {"def": "运筹帷幄之中。--《史记·高祖纪》", "example": null}, {"def": "又如筹设(计划设置);筹计(盘算);筹昏(谓无法算计)", "example": null}, {"def": "策划", "example": null}, {"def": "筹 chóu", "example": null}, {"def": "①计数用具竹～。", "example": null}, {"def": "②谋划；筹划；计划～款、统～。", "example": null}, {"def": "【筹安会】袁世凯复辟帝制的御用团体。1915年8月由杨度、孙毓筠、严复、李燮和、胡瑛、刘师培等所谓\'六君子\'在北京发起成立。该会名义上以\'研究君主、民主国体二者", "example": null}, {"def": "孰适于中国\'为宗旨，实际公开进行复辟帝制活动。", "example": null}, {"def": "【筹措】设法弄到（钱）～经费。", "example": null}, {"def": "【筹划】想办法；定计划～工作。", "example": null}, {"def": "【筹算法】〈数〉我国古代用竹制的算筹记数并进行加、减、乘、除、开方等运算的方法。始于春秋时期，到明代被珠算代替。", "example": null}, {"def": "筹（籭）chóu", "example": null}, {"def": "⒈计数的用具～码。", "example": null}, {"def": "⒉谋划，计划，计谋～备。熟～。统～安排。运～帷幄。一～莫展。", "example": null}, {"def": "⒊想办法收集～款。", "example": null}]','chinese-xinhua','0'),
('2101143295903141954','酬','1','chóu','酉','13',NULL,'[{"def": "酬", "example": null}, {"def": "(形声。从酉,夀声。本义客人给主人祝酒后,主人再次给客人敬酒作答)", "example": null}, {"def": "同本义", "example": null}, {"def": "酬,主人进客也。--《说文》。凡主人酌宾曰献,宾还酌主人曰醋,主人又自饮以酌宾曰酬。", "example": null}, {"def": "又如酬献(相互劝酒);酬劝(劝酒)", "example": null}, {"def": "酬答,报答", "example": null}, {"def": "主人酬宾。--《仪礼·士冠礼》。注饮宾客而从之以财货,曰酬,所以申畅厚意也。”", "example": null}, {"def": "交酬好货皆厚。--《国语·周语》。注交酬相酬之币也。”", "example": null}, {"def": "吾无以酬之。--《左传·昭公二十七年》", "example": null}, {"def": "不有死者,无以酬圣主。--梁启超《谭嗣同传》", "example": null}, {"def": "天将以酬长厚者。--《聊斋志异·促织》", "example": null}, {"def": "酬 chóu", "example": null}, {"def": "①〈古〉客人给主人祝酒后，主人再次给客人敬酒樽前自献自为～。（杜牧《念昔游》）", "example": null}, {"def": "②用财物等报答。", "example": null}, {"def": "③报酬同工同～。", "example": null}, {"def": "④交际往来应～。", "example": null}, {"def": "⑤实现（志愿）壮志未～。", "example": null}, {"def": "【酬报】用财物或行动来报答。", "example": null}, {"def": "【酬宾】以优惠价给顾客供应商品本店今日起举行大、活动。", "example": null}, {"def": "【酬唱】用诗词相互赠答。", "example": null}, {"def": "【酬劳】", "example": null}, {"def": "①对出力人给予酬谢。", "example": null}, {"def": "②给出力的人的报酬。", "example": null}, {"def": "【酬谢】送上金钱礼物等表示谢意。", "example": null}, {"def": "酬（醥、醻）chóu", "example": null}, {"def": "⒈敬酒。", "example": null}, {"def": "⒉应付，交际往来应～。", "example": null}, {"def": "⒊报答，偿付，偿还～报。～谢。报～。同工同～。", "example": null}, {"def": "⒋实现（志愿）壮志未～誓不休。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143295903141955','踌','1','chóu','足','14',NULL,'[{"def": "踌 (形声。从足,夀声。本义踌躇;徘徊)", "example": null}, {"def": "踌躇", "example": null}, {"def": "操欲立后嗣,踌躇不定 。--《三国演义》", "example": null}, {"def": "他两个眉来眼去,不由我暗暗踌躇,似这般哑谜儿怎猜做?--元·关汉卿《鲁斋郎》", "example": null}, {"def": "蹇淹留而踌躇。--宋玉《九辩》", "example": null}, {"def": "踌躇满志", "example": null}, {"def": "望西都,意踌躇。--张养浩《山坡羊》", "example": null}, {"def": "踌躇满志", "example": null}, {"def": "提刀", "example": null}, {"def": "踌 chóu", "example": null}, {"def": "①", "example": null}, {"def": "【踌躇】", "example": null}, {"def": "①犹豫不定～不前。", "example": null}, {"def": "②得意的样子～满志（对自己取得的成就非常得意）。", "example": null}, {"def": "踌（躳）chóu", "example": null}, {"def": "①徘徊，犹豫～躇不前。", "example": null}, {"def": "②从容自得的样子～躇满志。", "example": null}]','chinese-xinhua','0'),
