('2101143295903141973','瘳','1','chōu','疒','16',NULL,'[{"def": "瘳", "example": null}, {"def": "(形声。从疒”,表示与疾病有关。本义病愈)", "example": null}, {"def": "同本义", "example": null}, {"def": "其伤于缚者,即幸留,病数月乃瘳。--方苞《狱中杂记》", "example": null}, {"def": "又如瘳恙(病愈);瘳健(病愈,恢复健康)", "example": null}, {"def": "减损,损失", "example": null}, {"def": "君不度而贺大国之袭,于己也何瘳?--《国语·晋语二》", "example": null}, {"def": "瘳chōu", "example": null}, {"def": "⒈病好了。", "example": null}, {"def": "⒉损失，损害。", "example": null}]','chinese-xinhua','0'),
('2101143295903141974','犨','1','chōu','牛','20',NULL,'[{"def": "犨", "example": null}, {"def": "牛喘息声", "example": null}, {"def": "犨,牛息声。--《说文》", "example": null}, {"def": "水名。在今河南省鲁山县境", "example": null}, {"def": "滍水又东,犨水注之。--《水经注·滍水》", "example": null}, {"def": "犨", "example": null}, {"def": "突出", "example": null}, {"def": "南家之墙犨于前而不直。--《吕氏春秋》", "example": null}, {"def": "犨chōu 1.牛息声。", "example": null}, {"def": "2.突出。《吕氏春秋．召类》\\"南家之墙犨于前而不直。\\"高诱注\\"犨，犹出。曲出子罕堂前也。\\"一说同\\"雠\\"，犹当，正对着。陈奇猷校释引洪颐煊曰\\"犨，当为雠。《汉书", "example": null}, {"def": "．灌夫传》晋灼注\'雠，当也。\'\\"", "example": null}]','chinese-xinhua','0'),
