('2101143295903141976','抽','1','chōu','扌','8',NULL,'[{"def": "抽", "example": null}, {"def": "(形声。从手,由声。本义拔出,抽出)", "example": null}, {"def": "拔出,把夹在中间的东西取出", "example": null}, {"def": "抽,拔也。--《广雅》", "example": null}, {"def": "每射,抽矢菆。--《左传·宣公十二年》", "example": null}, {"def": "挈水若抽。--《庄子·天地》。李注引也。”", "example": null}, {"def": "左旋右抽。--《诗·郑风·清人》", "example": null}, {"def": "抽刀断水水更流。--李白《宣州谢眺楼饯别校书叔云》", "example": null}, {"def": "又如抽简禄马(算命);抽匣(抽剑出匣);抽毫(抽笔出套);抽宝剑;抽刀", "example": null}, {"def": "从全部里取出一部分;拔除", "example": null}, {"def": "言抽其棘。--《诗·小雅·楚茨》", "example": null}, {"def": "抽其半。--《仪礼·丧服传》", "example": null}, {"def": "又如抽分(从中取得一分);抽功夫(", "example": null}, {"def": "抽 chōu", "example": null}, {"def": "①从中取出；从中脱开～刀、～身。", "example": null}, {"def": "②从全部中取出一部分；～样调查。", "example": null}, {"def": "③长出～穗。", "example": null}, {"def": "④吸～烟。", "example": null}, {"def": "⑤收缩新买的衣服刚穿了一水就有点～了。", "example": null}, {"def": "⑥打（多指用条状物）用鞭子～ 。", "example": null}, {"def": "【抽水机】通过动力设备和传动装置将水由低处提升到高处的水力机械。广泛用于农田灌溉，工矿、城市供给、排水方面。又称水泵。", "example": null}, {"def": "【抽穗】禾谷类作物穗分化完成之后，穗部从叶鞘中逐渐伸出的过程和状态。一般以穗子抽出1/2、1/3为抽穗期标准。全田50%达到这个程度为抽穗期。", "example": null}, {"def": "【抽屉原理】〈数〉把比n还多的物体放入(个抽屉里，则至少有一个抽屉有两个或两个以上的物体。", "example": null}, {"def": "【抽象概念】反映的对象为事物性质或事物间关系的概念。如勇敢、高于。又作属性概念。", "example": null}, {"def": "【抽象劳动】\'具体劳动\'的对称。撇开具体形态的一般的、无差别的人类劳动，即人类劳动力在生理学意义上（包括脑力、体力等）的耗费。是生产商品的劳动二重性的一个方", "example": null}, {"def": "面。又称人类劳动。", "example": null}, {"def": "【抽象名词】表示动作、状态、品质、感情等抽象概念的名词。如英语的work、life、love等。", "example": null}, {"def": "【抽象思维】人们在认识过程中借助于概念、判断、推理反映事物的思维方法。它与形象思维不同，是用科学的抽象概念揭示事物本质、表述认识现实的结果。", "example": null}, {"def": "【抽薪止沸】抽掉柴火，使水停止沸腾。比喻从根本上解决问题。", "example": null}, {"def": "【抽样调查法】从某类事物中随意抽取一部分作不全面的调查。目的是以该部分的调查结果推测事物总体的情况。", "example": null}, {"def": "抽chōu", "example": null}, {"def": "⒈拔出，取出，提出一部分～出。～刀。～两本书。～空走走。", "example": null}, {"def": "⒉长出～芽。", "example": null}, {"def": "⒊吸，引出～烟。～水灌田。", "example": null}, {"def": "⒋牵动，收缩～搐（抽风）。这块布洗后～了两厘米。", "example": null}, {"def": "⒌使用软的、细长的东西打～了牠两鞭子。", "example": null}, {"def": "⒍除掉～掉。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①笼统，不具体讲得太～象，听不懂。", "example": null}, {"def": "②从各个事物中抽出共同的本质特点成为概念。", "example": null}, {"def": "⒐", "example": null}]','chinese-xinhua','0'),
('2101143295903141977','紬','1','chōu','糹','11',NULL,'[{"def": "紬", "example": null}, {"def": "引出", "example": null}, {"def": "燕见紬绎。--《汉书·谷永传》。注引其端绪也。”", "example": null}, {"def": "紬大弦而雅声流。--宋玉《高唐赋》", "example": null}, {"def": "又如紬绩(缀织,抽丝,纺绩)", "example": null}, {"def": "缀集", "example": null}, {"def": "紬绩晄。--《史记·历书》。索壹椉楟紬绩女工紬绩之意。”", "example": null}, {"def": "紬史记。--《太史公自序》。索隐谓缀集也。”", "example": null}, {"def": "又如紬次(缀集排列);紬绩(缀集;编集)", "example": null}, {"def": "紬绎", "example": null}, {"def": "紬chōu缀集，引出～绎（也作\\"抽绎\\"。阐述，引出头绪）。", "example": null}, {"def": "紬chóu同\\"绸\\"。", "example": null}]','chinese-xinhua','0'),
