('2101143295915724800','蜍','1','chú','虫','13',NULL,'[{"def": "蜍〈名〉", "example": null}, {"def": "(形声。从虫,余声。本义蟾蜍的省称) 同本义", "example": null}, {"def": "天边蜍兔,去我堂堂。--清·陈维崧《风流子》", "example": null}, {"def": "蜍chú", "example": null}]','chinese-xinhua','0'),
('2101143295915724801','趎','1','chú','','9',NULL,'[{"def": "趎chú 1.人名用字。《庄子．庚桑楚》有南荣趎。", "example": null}]','chinese-xinhua','0'),
('2101143295915724802','雏','1','chú','隹','13',NULL,'[{"def": "雏〈名〉", "example": null}, {"def": "(形声。从隹,刍声。本义小鸡)", "example": null}, {"def": "同本义", "example": null}, {"def": "雏,鸡子也。--《说文》", "example": null}, {"def": "乃以雏尝黍。--《礼记·月令》。注新鸡也。”", "example": null}, {"def": "有人于此,力不能胜一匹雏,则为无力人矣。--《孟子》", "example": null}, {"def": "引申为幼禽", "example": null}, {"def": "雏烧。--《礼记·内则》。疏鸟之小者也。”", "example": null}, {"def": "又如雏雉(幼雉);雏禽(幼鸟);雏莺(幼莺。也喻指幼龄的歌妓)", "example": null}, {"def": "幼小的动物", "example": null}, {"def": "乳虎,曾纩息之未定兮,乃敢探其穴,而啖其雏。--宋·苏轼《思子台》", "example": null}, {"def": "幼儿", "example": null}, {"def": "丈夫生儿有如此二雏者,名位岂肯卑微休!--唐·杜甫《徐卿二子歌》", "example": null}, {"def": "挈妇将雏鬓有丝。--鲁", "example": null}, {"def": "雏 chú生下不久的；幼小的（多指鸟类）～鸡、～燕。", "example": null}, {"def": "【雏形】", "example": null}, {"def": "①初步形成的规模。", "example": null}, {"def": "②照原形缩小后的模型。", "example": null}, {"def": "雏（雛）chú幼禽～鸡。～莺。〈喻〉幼儿。", "example": null}, {"def": "雏jù 1.人名用字。", "example": null}]','chinese-xinhua','0'),
('2101143295915724803','犓','1','chú','','13',NULL,'[{"def": "犓chú 1.用割下的草喂牛。亦泛指喂养牛羊等。 2.泛指牛羊等牲畜。参见\\"犓牛\\"﹑\\"犓豢\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295915724804','橱','1','chú','木','16',NULL,'[{"def": "橱〈名〉", "example": null}, {"def": "(形声。从木,厨声。本义 放置东西的家具)同本义", "example": null}, {"def": "橱 chú前面有门的放置衣物的家具衣～、壁～。", "example": null}, {"def": "橱（櫥）chú放置衣物的家具，前面有门书～。衣～儿。碗～子。", "example": null}]','chinese-xinhua','0'),
('2101143295915724805','幮','1','chú','巾','18',NULL,'[{"def": "幮〈名〉", "example": null}, {"def": "一种似橱形的帏帐", "example": null}, {"def": "幮,帐也,似厨形也。--陆该《字林》", "example": null}, {"def": "青山掩障碧纱幮。--王建《赠王处士诗》", "example": null}, {"def": "尽日无人只高卧,一双白鸟隔纱幮。--唐·司空图《王官》之二", "example": null}, {"def": "幮chú 1.形状象橱的床帐。", "example": null}]','chinese-xinhua','0'),
