('2101143295915724820','俶','1','chù','亻','10',NULL,'[{"def": "俶〈形〉", "example": null}, {"def": "(形声。从人,叔声。经传皆以淑为之。本义善;美好)", "example": null}, {"def": "同本义", "example": null}, {"def": "俶,善也。--《说文》", "example": null}, {"def": "有俶其城。--《诗·大雅·崧高》", "example": null}, {"def": "又如俶辰(良辰);俶灵(天赋的聪明才智);俶献(古时把应时珍美新物献给国君)", "example": null}, {"def": "厚", "example": null}, {"def": "俶,厚也。俶甚者,厚甚也。平地七尺雪,厚莫甚于此矣。--王引之《经义述闻·公羊传》", "example": null}, {"def": "奇异", "example": null}, {"def": "俶傥瑰玮。--司马相如《子虚赋》", "example": null}, {"def": "又如俶奇(奇异);俶诡(奇异滑稽);俶乱(诡奇杂乱)", "example": null}, {"def": "俶〈副〉", "example": null}, {"def": "开始", "example": null}, {"def": "令终有俶。--《诗·大雅·既醉》", "example": null}, {"def": "俶拢天经。--《书·伪允征》", "example": null}, {"def": "燕与羞俶。--", "example": null}, {"def": "俶chù", "example": null}, {"def": "⒈〈古〉作，筑，开始～其城。～衽则请（衽席子。此处指铺席）。", "example": null}, {"def": "俶tì［俶傥］不拘束，豪爽大方风流～傥。", "example": null}]','chinese-xinhua','0'),
('2101143295915724821','搐','1','chù','扌','13',NULL,'[{"def": "搐〈动〉", "example": null}, {"def": "(形声。从手,畜声。本义牵动,抽缩)", "example": null}, {"def": "同本义", "example": null}, {"def": "束", "example": null}, {"def": "退缩", "example": null}, {"def": "我有刀来你有枪,前前搐搐不成像。--清·蒲松龄《聊斋俚曲集》", "example": null}, {"def": "搐动", "example": null}, {"def": "全身搐动了一下", "example": null}, {"def": "搐缩", "example": null}, {"def": "搐 chù抽搐。", "example": null}, {"def": "搐chù牵动抽～（肌肉不自主地剧烈收缩，痉挛）。", "example": null}]','chinese-xinhua','0'),
('2101143295915724822','怵','1','chù','忄','8',NULL,'[{"def": "怵〈动〉", "example": null}, {"def": "(形声。从心,术声。本义恐惧,害怕)", "example": null}, {"def": "同本义", "example": null}, {"def": "怵,恐也。--《说文》", "example": null}, {"def": "怵,惧也。--《广雅》", "example": null}, {"def": "劳形怵心者也。--《庄子·应帝王》", "example": null}, {"def": "怵悼栗而耸兢。--张衡《西京赋》", "example": null}, {"def": "皆有怵惕恻隐之心。--《孟子·公孙丑上》", "example": null}, {"def": "又如怵栗(恐惧);怵悸(恐惧心跳);怵怵(戒惧、警惕的样子)", "example": null}, {"def": "伤心", "example": null}, {"def": "心怵而奉之以礼。--《礼记·祭统》", "example": null}, {"def": "是以君子不怵乎好,不迫乎恶。--《管子·心术上》", "example": null}, {"def": "人迫于恶,则失其所好;怵于好,则忘其所恶,非道也。", "example": null}, {"def": "得于好恶,怵于淫物,而后变乱。--《韩非子·解老》", "example": null}, {"def": "怵迫之", "example": null}, {"def": "怵 chù", "example": null}, {"def": "①〈古〉警惕～以为戒。（《庄子、养生主》）", "example": null}, {"def": "②恐惧；害怕发～。", "example": null}, {"def": "【怵目惊心】看到某种严重事态引起内心的震动。形容局势严重。又作触目惊心。", "example": null}, {"def": "【怵惕】恐惧警惕。", "example": null}, {"def": "怵chù恐惧，害怕～心。～惕。", "example": null}, {"def": "怵xù 1.诱导;诱惑。", "example": null}]','chinese-xinhua','0'),
