('2101143295915724839','齼','1','chǔ','齲','28',NULL,'[{"def": "齼〈动〉", "example": null}, {"def": "牙齿酸痛", "example": null}, {"def": "莫向君家樊素口,瓠犀微齼远山颦。--曾几《曾宏父分饷洞庭柑诗》", "example": null}, {"def": "畏怯", "example": null}, {"def": "齼字《玉篇》不载。齿怯也。音楚去声。今京师语谓怯皆曰齼,不独齿怯也。--杨慎", "example": null}, {"def": "齼chǔ 1.牙齿接触酸味的感觉。 2.畏怯。 3.凄楚;悲伤。", "example": null}]','chinese-xinhua','0'),
('2101143295915724840','杵','1','chǔ','木','8',NULL,'[{"def": "杵〈名〉", "example": null}, {"def": "(形声。从木,午声。本义舂米的棒槌)", "example": null}, {"def": "同本义", "example": null}, {"def": "杵,舂杵也。--《说文》", "example": null}, {"def": "断木为杵,掘地为臼。--《易·系辞》传", "example": null}, {"def": "又如杵臼交(不嫌贫贱的交情);杵臼(杵与臼);杵头(杵)", "example": null}, {"def": "捶衣用的短木棒", "example": null}, {"def": "筑墙、筑堤时,用来填实泥土的棒槌", "example": null}, {"def": "筑谓之杵。--《广雅》", "example": null}, {"def": "杵以梧。--《礼记·杂记》", "example": null}, {"def": "又如杵声(筑城填土的杵槌声);杵木(筑土的木槌)", "example": null}, {"def": "古代的一种棒形兵器。形如杵", "example": null}, {"def": "杵 〈动〉", "example": null}, {"def": "捣,砸", "example": null}, {"def": "傲童不讴歌,舂筑者不相杵。", "example": null}, {"def": "杵 chǔ", "example": null}, {"def": "①一头粗一头细的圆木棒，用来舂米或洗衣时捶衣服～臼。", "example": null}, {"def": "②用细长的东西戳或捅。楮楮树。落叶乔木，叶卵形有硬毛，开淡绿色花。树皮可造纸，也叫树构。", "example": null}, {"def": "杵chǔ", "example": null}, {"def": "⒈舂米的棒槌。泛指捶物的棒槌。", "example": null}, {"def": "⒉用长形的东西捅、戳只是手指头～了他一下。", "example": null}, {"def": "⒊〈古〉兵器降魔～。", "example": null}]','chinese-xinhua','0'),
('2101143295915724841','础','1','chǔ','石','10',NULL,'[{"def": "础〈名〉", "example": null}, {"def": "(形声。从石,楚声。本义柱脚石,垫在房屋柱子下的石头)", "example": null}, {"def": "同本义", "example": null}, {"def": "云蒸柱础润。--《淮南子·说林》。", "example": null}, {"def": "又如础石;", "example": null}, {"def": "事物的基底或根基", "example": null}, {"def": "础（礱）chǔ柱子底下的石礅。〈引〉基底或根基基～。", "example": null}]','chinese-xinhua','0'),
