('2101143295919919115','嘬','1','chuài','口','15',NULL,'[{"def": "嘬〈动〉", "example": null}, {"def": "大口吞食", "example": null}, {"def": "叮,咬", "example": null}, {"def": "嘬chuài", "example": null}, {"def": "⒈咬，吃。", "example": null}, {"def": "嘬zuō", "example": null}, {"def": "⒈使嘴吮吸婴儿～奶。", "example": null}]','chinese-xinhua','0'),
('2101143295919919116','踹','1','chuài','足','16',NULL,'[{"def": "踹〈动〉", "example": null}, {"def": "踩;踏;踩踏", "example": null}, {"def": "追者至踹足而怒。--《淮南子·人间》。注跃足也。今苏俗曰跳脚。”", "example": null}, {"def": "又如踹水(踏水);踹浑水(浑水摸鱼);踹踏(踩踏)", "example": null}, {"def": "跟踪寻找", "example": null}, {"def": "只青天白日,府里失盗,外贼从何得来?这还在左右前后踹。--《三国演义》", "example": null}, {"def": "踹 chuài", "example": null}, {"def": "①脚底向外踢用脚～门。", "example": null}, {"def": "②踩一脚～在水里了。", "example": null}, {"def": "踹chuài踩踏，顿脚，用脚底踢～脚。～了一脚稀泥。一脚将门～开。", "example": null}, {"def": "踹chuǎn 1.小腿肚。", "example": null}, {"def": "踹duàn 1.跺脚。参见\\"踹足\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295919919117','膪','1','chuài','月','16',NULL,'[{"def": "膪--囊膪”猪胸∶猪胸腹部肥而松的肉", "example": null}, {"def": "膪chuài", "example": null}, {"def": "膪zhà 1.肥貌。", "example": null}, {"def": "膪zhài 1.剔取骨间肉。", "example": null}]','chinese-xinhua','0'),
('2101143295919919118','搋','1','chuāi','扌','13',NULL,'[{"def": "搋〈动〉", "example": null}, {"def": "用力揉物", "example": null}, {"def": "藏物于怀", "example": null}, {"def": "只见陶铁僧栾了四五十钱,鹰觑鹘望,看布帘里面,约莫没人见,把那见钱怀中便搋。--《警世通言》", "example": null}, {"def": "搋子", "example": null}, {"def": "搋chuāi用手揉、压，使搀入物和匀～面粉。～糯米饭。", "example": null}]','chinese-xinhua','0'),
('2101143295919919119','揣','1','chuāi','扌','12',NULL,'[{"def": "揣〈动〉", "example": null}, {"def": "藏入;塞进", "example": null}, {"def": "怀孕", "example": null}, {"def": "强给;给与", "example": null}, {"def": "揣〈动〉", "example": null}, {"def": "(会意。本义测量;量度)", "example": null}, {"def": "同本义", "example": null}, {"def": "揣,量也。--《说文》", "example": null}, {"def": "度量曰揣。--《方言》十二", "example": null}, {"def": "揣高卑。--《左传·昭公三十二年》", "example": null}, {"def": "不揣其本而齐其末。--《孟子·告子下》", "example": null}, {"def": "猜想,推测;估量", "example": null}, {"def": "淮主调说以取尊贵,是名为揣。--《论衡·逢遇》", "example": null}, {"def": "内符者,揣之主也。--《鬼谷子·", "example": null}, {"def": "揣 chuāi藏在衣服里把钥匙、在衣袋里。又见chuǎi；chuài。", "example": null}, {"def": "揣 chuǎi", "example": null}, {"def": "①估计；忖度；测量～测、不～冒昧。", "example": null}, {"def": "②姓。又见chuāi；chuài。", "example": null}, {"def": "【揣测】推测。", "example": null}, {"def": "【揣度】估计；推测。", "example": null}, {"def": "【揣摩】反复思考推求。", "example": null}, {"def": "揣 chuài 用于", "example": null}, {"def": "【挣揣】。又见chuāi；chuǎi。", "example": null}, {"def": "揣chuǎi", "example": null}, {"def": "⒈测量～高低。", "example": null}, {"def": "⒉估量，猜测～测。不～冒昧。我～他今天回来。", "example": null}, {"def": "⒊", "example": null}, {"def": "①探求，仔细研究悉心～摩。", "example": null}, {"def": "②估计，推测我～摩她能做好这件事。", "example": null}, {"def": "揣chuāi藏于衣服里～着手。～入怀里。", "example": null}, {"def": "揣chuài", "example": null}, {"def": "揣duǒ 1.摇动。", "example": null}]','chinese-xinhua','0'),
('2101143295919919120','船','1','chuán','舟','11',NULL,'[{"def": "船〈名〉", "example": null}, {"def": "(形声。本义水运工具。古称舟)", "example": null}, {"def": "同本义", "example": null}, {"def": "船,舟也。--《说文》。段注古人言舟,汉人言船,毛以今语释古,故云舟即今之船也。”", "example": null}, {"def": "小曰舟,大曰船。--《说文义证》", "example": null}, {"def": "有渔父者,下船而来。--《庄子·渔父》", "example": null}, {"def": "便舍船,从口入。--陶潜《桃花源记》", "example": null}, {"def": "姑苏城外寒山寺,夜半钟声到客船--张继《枫桥夜泊》", "example": null}, {"def": "又如船坞(船厂;停泊、修理或制造船只的地方);船把板(船主);船不漏针(比喻绝无遗失);船多不碍路(数量虽多,但互不妨碍);船横芦篚嚣(轩然大波;闹出乱子);船人(船夫。", "example": null}, {"def": "也作舩人);船头(船的前部;船老大)", "example": null}, {"def": "空间交通工具", "example": null}, {"def": "船 chuán水上主要运输工具木～、轮～、气垫～。", "example": null}, {"def": "【船闸】为船舶克服水道落差而设置的一种结构简单、使用方便的通航建筑物。一般由闸室、上下闸以及上下游引航道组成。其类型很多，主要有单级船闸和多级船闸。", "example": null}, {"def": "船（舩、舡）chuán水上交通工具（种类很多）渔～。帆～。战～。运输～。旅游～。", "example": null}]','chinese-xinhua','0'),
('2101143295919919121','遄','1','chuán','辶','12',NULL,'[{"def": "遄〈形〉", "example": null}, {"def": "(形声。从辵,聑声。本义快,疾速) 同本义", "example": null}, {"def": "遄,速也。--《尔雅》", "example": null}, {"def": "已事遄往。--《易·损卦》", "example": null}, {"def": "胡不遄死?--《诗·鄘风·相鼠》", "example": null}, {"def": "乱庶遄沮。--《左传·宣公十七年》", "example": null}, {"def": "又如遄归(速归);遄飞(迅急飞扬);遄急(急速)", "example": null}, {"def": "遄chuán", "example": null}, {"def": "⒈快，迅速～至。", "example": null}, {"def": "⒉往来频繁。", "example": null}]','chinese-xinhua','0'),
('2101143295919919122','椽','1','chuán','木','13',NULL,'[{"def": "椽", "example": null}, {"def": "(形声。从木,彖(畴溄??　)声。本义承屋瓦的圆木) 同本义", "example": null}, {"def": "椽,榱也。--《说文》", "example": null}, {"def": "以大宫之椽归,为卢门之椽。--《左传·桓公十四年》", "example": null}, {"def": "采椽不斫。--《韩非子·五蠹》", "example": null}, {"def": "架梁之椽,多于机上之工女。--杜牧《阿房宫赋》", "example": null}, {"def": "不数岁,田百顷,楼阁万椽,牛羊蹄躰各千计。--《聊斋志异·促织》", "example": null}, {"def": "又如椽杙(椽子和小木桩);椽桷(承屋瓦用的圆木与方木。圆的叫椽,方的叫桷。泛指椽子);椽笔(大笔);椽栋(椽子与正梁)", "example": null}, {"def": "椽条", "example": null}, {"def": "椽子", "example": null}, {"def": "椽 chuán放在檩上架着屋顶的木条或木棒。", "example": null}, {"def": "椽chuán", "example": null}]','chinese-xinhua','0'),
