('2101143295919919132','舛','1','chuǎn','夕','6',NULL,'[{"def": "舛", "example": null}, {"def": "(会意。小篆字形,是两只方向相反的脚,合起来表示相违背的意思。本义相违背,颠倒)", "example": null}, {"def": "同本义", "example": null}, {"def": "舛,对卧也。--《说文》段注谓人与人相对而休也,相背,犹相对也。”", "example": null}, {"def": "本末舛逆。--贾谊《治安策》", "example": null}, {"def": "雄见诸子,各以其知舛驰。--《汉书·扬雄传》", "example": null}, {"def": "又如舛驰(异道而驰;交互);舛令(违命);舛午(抵触;违背)", "example": null}, {"def": "交互;交错", "example": null}, {"def": "舛", "example": null}, {"def": "错乱", "example": null}, {"def": "此臣所谓舛也。--《汉书·贾谊传》", "example": null}, {"def": "如舛讹(差错;错误);舛差(差误;差错);舛误(差错;错误)", "example": null}, {"def": "不幸", "example": null}, {"def": "舛 chuǎn", "example": null}, {"def": "①差错；错乱～错。", "example": null}, {"def": "②违背。", "example": null}, {"def": "【舛驰】背道而驰。", "example": null}, {"def": "【舛误】错误；差错。", "example": null}, {"def": "舛、踳chuǎn", "example": null}, {"def": "⒈差错，错乱～谬。", "example": null}, {"def": "⒉相违背前程多～。", "example": null}]','chinese-xinhua','0'),
('2101143295919919133','喘','1','chuǎn','口','12',NULL,'[{"def": "喘", "example": null}, {"def": "(形声。从口,聑声。本义喘息,急速地呼吸)", "example": null}, {"def": "同本义", "example": null}, {"def": "喘,疾息也。--《说文》", "example": null}, {"def": "其发咳喘。--《素问·五常正大论》", "example": null}, {"def": "牛喘吐舌。--《汉书·丙吉传》", "example": null}, {"def": "喘喘然将死。--《庄子·大宗师》", "example": null}, {"def": "又如心跳气喘;累得直喘;喘喝(中气不顺,口鼻有声的样子);喘乏(气喘困乏)", "example": null}, {"def": "轻声说话", "example": null}, {"def": "礼义以为文,伦类以为理,喘而言。--《荀子·臣道》", "example": null}, {"def": "喘 chuǎn", "example": null}, {"def": "①呼吸急促。", "example": null}, {"def": "②气喘◆吸困难的症状。", "example": null}, {"def": "喘chuǎn", "example": null}, {"def": "⒈急促的呼吸～气。～息。哮～。", "example": null}, {"def": "⒉气喘的省称～咳。", "example": null}]','chinese-xinhua','0'),
