('2101143295924113432','辍','1','chuò','车','12',NULL,'[{"def": "辍", "example": null}, {"def": "(形声。本义中途停止,废止)", "example": null}, {"def": "同本义", "example": null}, {"def": "辍车小缺复合者。--《说文》", "example": null}, {"def": "君子不为小人之匈匈也辍行。--《荀子·天论》", "example": null}, {"def": "陈涉少时,尝与人佣耕,辍耕之垄上,怅恨久之。--《史记·陈涉世家》", "example": null}, {"def": "又如辍斤(停止挥斧。比喻没有伙伴,就不再施展技艺);辍朝(暂停中止朝见);辍耕陇上(停止耕作,在田中高地休息)", "example": null}, {"def": "放下,舍弃", "example": null}, {"def": "偶命厨者进芋,辍箸叹曰…--周容《芋老人传》", "example": null}, {"def": "又如辍己(舍己);辍弃(抛弃);辍食弃餐", "example": null}, {"def": "撤销;撤除", "example": null}, {"def": "取出,拿出", "example": null}, {"def": "辍 chuò中止；停止～学、终日不～。", "example": null}, {"def": "【辍学】中途停止上学。", "example": null}, {"def": "辍chuò停止，废止～学。～止。日夜不～。中途不能～。", "example": null}]','chinese-xinhua','0'),
('2101143295924113433','龊','1','chuò','齿','15',NULL,'[{"def": "龊", "example": null}, {"def": "整治;整顿", "example": null}, {"def": "戒备", "example": null}, {"def": "龊", "example": null}, {"def": "局促,拘谨", "example": null}, {"def": "见龌龊”", "example": null}, {"def": "龊chuò 〈方〉", "example": null}, {"def": "①肮脏，不干净。", "example": null}, {"def": "②卑鄙。", "example": null}]','chinese-xinhua','0'),
