('2101143295924113441','绰','1','chuō','纟','11',NULL,'[{"def": "绰  chuo", "example": null}, {"def": "(形声。从糸,卓声。本义宽大,舒缓)", "example": null}, {"def": "同本义", "example": null}, {"def": "宽兮绰兮。--《诗·卫风·淇奥》", "example": null}, {"def": "又如绰步(大步);绰板婆(大脚婆娘);绰绰(宽舒裕如)", "example": null}, {"def": "姿态柔美", "example": null}, {"def": "柔情绰态,媚于语言。--曹植《洛神赋》", "example": null}, {"def": "又如绰态(柔媚多姿);绰俏(漂亮;俊俏)", "example": null}, {"def": "隐隐约约", "example": null}, {"def": "端正", "example": null}, {"def": "曾经绰立侍丹墀,绽蕊宫花拂面权。--唐·元稹《酬孝甫见赠诗》", "example": null}, {"def": "又如绰立", "example": null}, {"def": "绰", "example": null}, {"def": "吹拂", "example": null}, {"def": "搅乱", "example": null}, {"def": "绰 chāo", "example": null}, {"def": "①抓取顺手～起棍子。", "example": null}, {"def": "②同\'焯\'。又见chuò", "example": null}, {"def": "绰 chuò富足宽～。又见chāo。", "example": null}, {"def": "【绰绰有余】形容很宽绰，用不完。", "example": null}, {"def": "【绰号】外号。", "example": null}, {"def": "【绰约】形容女子体态柔美的样子。", "example": null}, {"def": "绰chāo", "example": null}, {"def": "⒈匆忙抓起～起木凳。", "example": null}, {"def": "⒉通\\"焯\\"～波菜。", "example": null}, {"def": "绰chuò", "example": null}, {"def": "⒈宽裕，舒缓宽～。～有余裕。～ ～有余。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143295924113442','踔','1','chuō','足','15',NULL,'[{"def": "踔", "example": null}, {"def": "践踏", "example": null}, {"def": "跳,跳跃", "example": null}, {"def": "踔攳枝。--《后汉书·马融传》。注跳也。”", "example": null}, {"def": "煮头,三日三夕不烂,头踔出汤中。--干宝《搜神记》", "example": null}, {"def": "若鸟之摩空,猿之踔虚,似非手足之灵所能及也。--《徐霞客游记》", "example": null}, {"def": "又如踔虚(谓在空中腾跃);踔跃(跳跃);踔掉(摇晃,摆动)", "example": null}, {"def": "逾越,走过", "example": null}, {"def": "踔宇宙而遗俗兮。--《后汉书·蔡邕传》", "example": null}, {"def": "日夜踔数舍,冒没于凶党中。--宋·苏舜卿语", "example": null}, {"def": "又如踔绝(卓越出众);踔远(相去辽远);踔厉风发(形容议论精辟浑厚,如风势的强劲有力);踔越(超越,胜过)", "example": null}, {"def": "跛行", "example": null}, {"def": "踔厉", "example": null}, {"def": "踔 chuō", "example": null}, {"def": "【踔绝】高超。", "example": null}, {"def": "踔chuō", "example": null}, {"def": "⒈跳～腾。", "example": null}, {"def": "⒉超越，高超～绝。", "example": null}, {"def": "踔zhuō 1.卓然特立。参见\\"踔絶\\"﹑\\"踔踔\\"。 2.见\\"踔远\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295924113443','戳','1','chuō','戈','18',NULL,'[{"def": "戳", "example": null}, {"def": "(形声。从戈,翟声。本义用锐器的尖端刺击)", "example": null}, {"def": "同本义", "example": null}, {"def": "戳,枪戳也。--《篇海类篇》", "example": null}, {"def": "众强盗拚命死战,戳伤了几个庄客。--《醒世恒言》", "example": null}, {"def": "又如戳伤;戳舌(搬弄是非,挑拨);戳弄(摆布,捉弄);戳背脊(背后指责讥笑);戳纱(一种特殊的刺绣品);戳锅漏(方言。指暗中捣鬼的人);戳无路儿(捣鬼,无中生有的挑拨);戳", "example": null}, {"def": "腿(拳脚套式之一);戳包儿(掉包,暗中掉换某物)", "example": null}, {"def": "用指头指点", "example": null}, {"def": "向他头上戳了一指头。--《红楼梦》", "example": null}, {"def": "又如戳点(用指尖指点);戳指(伸出指头指着)", "example": null}, {"def": "刺激", "example": null}, {"def": "竖立的;站的", "example": null}, {"def": "戳 chuō", "example": null}, {"def": "①用尖端刺；～破。", "example": null}, {"def": "②被尖硬物刺伤～了手。", "example": null}, {"def": "③图章邮～。", "example": null}, {"def": "【戳记】图章；印记。", "example": null}, {"def": "戳chuō", "example": null}, {"def": "⒈刺，触击～个洞。～了他一刀。指头～了一下额。", "example": null}, {"def": "⒉图章、印记等盖个～子。", "example": null}, {"def": "⒊竖立～起来。", "example": null}]','chinese-xinhua','0'),
('2101143295924113444','垐','1','cí','','11',NULL,'[{"def": "垐cí 1.用土铺路。 2.用于人名。《明史．林汝翥传》有林垐。", "example": null}]','chinese-xinhua','0'),
