('2101143295928307726','凑','1','còu','冫','11',NULL,'[{"def": "凑", "example": null}, {"def": "(形声。从水,奏声。本义水流会合)", "example": null}, {"def": "同本义", "example": null}, {"def": "凑,水会也,聚也。--《广韵》", "example": null}, {"def": "凑,水上人所会也。--《 说文》。", "example": null}, {"def": "顺波凑而下降。--《楚辞·九叹·逢纷》。注聚也。”", "example": null}, {"def": "聚集", "example": null}, {"def": "趋舍相凑。--《淮南子·原道》。注所合也。”", "example": null}, {"def": "则人物归之,繈至而辐凑。--《史记·货殖列传》", "example": null}, {"def": "又如凑队(集合在一起);凑聚(集合,聚集);凑泊(凝聚,结合);凑会(聚集,会合)", "example": null}, {"def": "奔向;趋", "example": null}, {"def": "衰世凑学。--《淮南子·精神》。注趋也。”", "example": null}, {"def": "又如凑亟(急切);凑手不及(事情来得太快,出人意料,来不及应付)", "example": null}, {"def": "挨近;靠", "example": null}, {"def": "凑 còu", "example": null}, {"def": "①聚集～钱。", "example": null}, {"def": "②碰；赶；趁～巧撞上一个人。", "example": null}, {"def": "③接近～到近处看。", "example": null}, {"def": "【凑合】", "example": null}, {"def": "①聚集同学们～在一起热闹热闹。", "example": null}, {"def": "②拼凑预先准备好，别临时～。", "example": null}, {"def": "③将就你们就～着过吧。", "example": null}, {"def": "【凑微分法】把被积分式凑成某个函数的微分的积分方法。", "example": null}]','chinese-xinhua','0'),
('2101143295928307727','腠','1','còu','月','13',NULL,'[{"def": "腠", "example": null}, {"def": "(形声。从肉,奏声。本义腠理。皮下肌肉之间的空隙) 同本义", "example": null}, {"def": "君有疾在腠理,不治将恐深。--《韩非子》", "example": null}, {"def": "腠 còu", "example": null}, {"def": "【腠理】中医指皮肤的纹理和皮下肌肉之间的空隙。", "example": null}]','chinese-xinhua','0'),
('2101143295928307728','辏','1','còu','车','13',NULL,'[{"def": "辏", "example": null}, {"def": "(形声。从车,奏声。本义车轮上的辐条集中于觳上)", "example": null}, {"def": "同本义", "example": null}, {"def": "辐辏而轮转,出入更卷舒。--《参同契》", "example": null}, {"def": "聚集", "example": null}, {"def": "四方辐辏。--《汉书·叔孙通传》。师古曰辏,聚也,言如车辐之聚于毂也。”", "example": null}, {"def": "又如辏集(聚集;稠密);晗(凑合;聚集);辏泊(聚集)", "example": null}, {"def": "添加", "example": null}, {"def": "靠近", "example": null}, {"def": "辏力", "example": null}, {"def": "辏còu 1.车轮的辐条内端聚集于毂上。参见\\"辐辏\\"。 2.聚集。 3.通\\"凑\\"。接近，靠。 4.通\\"凑\\"。碰。", "example": null}]','chinese-xinhua','0'),
('2101143295928307729','徂','1','cú','彳','8',NULL,'[{"def": "徂", "example": null}, {"def": "(形声。从彳且声。从彳”,表示与行走有关。本义往;去)", "example": null}, {"def": "同本义", "example": null}, {"def": "徂,往也。--《尔雅》", "example": null}, {"def": "汝徂征。--《书·大禹谟》", "example": null}, {"def": "胤后承王命徂征。--《书·胤征》", "example": null}, {"def": "自我徂尔。--《诗·卫风·氓》", "example": null}, {"def": "我征徂西。--《诗·小雅·小明》", "example": null}, {"def": "又如徂川(流去的河水);徂徕(往复);徂征(前往征讨)", "example": null}, {"def": "及,至", "example": null}, {"def": "后先相继,自夏徂秋。--李渔《闲情偶寄·种植部》", "example": null}, {"def": "自堂徂基,自羊徂牛。--《诗·周颂·丝衣》", "example": null}, {"def": "行,行走", "example": null}, {"def": "思无邪,思马斯徂。--《诗·鲁颂·駉》", "example": null}, {"def": "死亡", "example": null}, {"def": "二十有八载,放勋乃徂落,百姓如丧考妣。--《孟子·万", "example": null}, {"def": "徂cú", "example": null}, {"def": "①〈动〉往。自西～东。。", "example": null}, {"def": "②〈动〉去，过去。岁月其～。\\"", "example": null}, {"def": "③〈动〉开始＞\\"四月维夏六月～暑。\\"", "example": null}, {"def": "④〈动〉死亡＞诗曰∶\\"～谢易永久，松柏森已行。\\"", "example": null}]','chinese-xinhua','0'),
('2101143295928307730','殂','1','cú','歹','9',NULL,'[{"def": "殂", "example": null}, {"def": "(形声。从歹,且声。从歹”,表示与死亡有关。本义死亡) 同本义", "example": null}, {"def": "殂,往死也。--《说文》", "example": null}, {"def": "帝乃殂落。--《书·舜典》。传殂落,死也。”", "example": null}, {"def": "放勋乃殂落。--《孟子·万章上》", "example": null}, {"def": "先帝创业未半而中道崩殂。--诸葛亮《出师表》", "example": null}, {"def": "又如殂谢(死亡);殂夭(夭亡);殂化(逝世);殂没(死亡)", "example": null}, {"def": "殂cú 1.死亡。", "example": null}]','chinese-xinhua','0'),
('2101143295928307731','促','1','cù','亻','9',NULL,'[{"def": "促", "example": null}, {"def": "(形声。从人,足声。本义紧迫。又指急促,赶快)", "example": null}, {"def": "同本义", "example": null}, {"def": "促,速也。--《广韵》", "example": null}, {"def": "促,速也。--《汉书·高帝纪》注", "example": null}, {"def": "长来觉日月益促。--唐·柳宗元《与萧俛书》", "example": null}, {"def": "又如促柱(急切的絣音);促装(急忙整治行装);促速(急速);促病(急病)", "example": null}, {"def": "小,狭窄", "example": null}, {"def": "短。时间、距离拉得不长的", "example": null}, {"def": "可命促而意长。--晋·陆机《吊魏武帝文》", "example": null}, {"def": "又如促节(乐曲快板短促);促死(立刻死去);促生(短促的生命);促促(短短的)", "example": null}, {"def": "促", "example": null}, {"def": "使加", "example": null}, {"def": "促 cù", "example": null}, {"def": "①时间短；紧迫仓～、急～。", "example": null}, {"def": "②催；推动～使、督～。", "example": null}, {"def": "③接近～膝交谈。", "example": null}, {"def": "【促膝谈心】紧挨着坐在一起谈心。", "example": null}, {"def": "【促织】见【蟋蟀】。", "example": null}]','chinese-xinhua','0'),
('2101143295928307732','猝','1','cù','犭','11',NULL,'[{"def": "猝", "example": null}, {"def": "(形声。从犬,卒声。本义狗从草丛中突然跑出追人) 同本义", "example": null}, {"def": "又如猝嗟(叱咤。发怒呼喝);猝暴(肆虐)", "example": null}, {"def": "猝", "example": null}, {"def": "突然地,出其不意地", "example": null}, {"def": "大阉亦逡巡畏义,非常之谋难于猝发。--张溥《五人墓碑记》", "example": null}, {"def": "又如猝死(突然死亡);猝故(突然发生的变故)", "example": null}, {"def": "猝 cù突然，出乎意外～死、～不及防。", "example": null}, {"def": "【猝不及防】突然来到，不及防备。", "example": null}, {"def": "【猝然】突然；出乎意外～倒地。", "example": null}]','chinese-xinhua','0'),
