('2101143295928307735','蔟','1','cù','艹','14',NULL,'[{"def": "蔟", "example": null}, {"def": "蚕蔟,供蚕作茧的东西。用稻麦杆等堆聚而成", "example": null}, {"def": "蔟,行蚕蓐。--《说文》", "example": null}, {"def": "帅导群妾,咸循蚕蔟。--扬雄《元后诔》", "example": null}, {"def": "巢", "example": null}, {"def": "读为爵蔟之蔟,谓巢也。--《周礼·哲蔟氏司农注》", "example": null}, {"def": "又如柴蔟", "example": null}, {"def": "蔟", "example": null}, {"def": "聚集,堆积", "example": null}, {"def": "律中太蔟。--《礼记·月令》", "example": null}, {"def": "野绿蔟草树,眼界蚕秦原。--唐·白居易《游悟真寺诗》", "example": null}, {"def": "蔟 cù 蚕蔟，用麦杆等做成，蚕在上面做茧。", "example": null}, {"def": "蔟còu 1.乐律名，古乐十二律中的第三律。", "example": null}, {"def": "蔟chuò 1.叉取，刺破。", "example": null}]','chinese-xinhua','0'),
