('2101143295928307755','欑','1','cuān','木','23',NULL,'[{"def": "欑", "example": null}, {"def": "把木或竹片捆在一起", "example": null}, {"def": "停放棺木暂时不葬", "example": null}, {"def": "若袭与柩,则安能有逾月不殓,逾月不櫕之理。--清·毛奇龄《丧礼言事不实说》", "example": null}, {"def": "镩cuàn 1.一种兵器。短矛。", "example": null}, {"def": "镩cuān 1.见\\"镩子\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295928307756','汆','1','cuān','水','6',NULL,'[{"def": "汆", "example": null}, {"def": "一种烹调方法。把食物放到沸水里稍微一煮", "example": null}, {"def": "引申为把东西丢到水里或人钻入水中", "example": null}, {"def": "所以才几天就搁下来了,眼睁睁汆了它妈一大堆钱进去。--沙汀《淘金记》", "example": null}, {"def": "汆tǔn", "example": null}, {"def": "①方言。漂流在水上。如冰块在水上汆。", "example": null}, {"def": "②用油炸。如油氽花生米。", "example": null}, {"def": "汆cuān烹饪法的一种，把食物放在开水中稍煮一下。如汆丸子。", "example": null}, {"def": "汆cuān", "example": null}, {"def": "①烹调的一种方法。把食物放入沸水中稍煮一下。", "example": null}, {"def": "②引申为把东西丢到水里或人钻入水中。", "example": null}]','chinese-xinhua','0'),
('2101143295928307757','撺','1','cuān','扌','15',NULL,'[{"def": "撺", "example": null}, {"def": "匆匆忙忙地做", "example": null}, {"def": "长出", "example": null}, {"def": "怂恿,唆使别人去干坏事", "example": null}, {"def": "紧握。用同攥”", "example": null}, {"def": "跳。用同蹿”", "example": null}, {"def": "逃走;乱跑", "example": null}, {"def": "用同汆”。把食物放到沸水里稍微煮一下就捞出", "example": null}, {"def": "撺 cuān", "example": null}, {"def": "①抛掷。", "example": null}, {"def": "②匆忙地做，乱抓事先没准备.1临时旋～.", "example": null}, {"def": "③（-儿)发怒,发脾气他～儿了.《撺 掇》（duo）怂恿,劝诱别人做某种事情你就是～～他,他也不去.你自己不干,为什么～～我呢？", "example": null}]','chinese-xinhua','0'),
('2101143295928307758','镩','1','cuān','钅','17',NULL,'[{"def": "镩", "example": null}, {"def": "冰镩。一种凿冰的器具", "example": null}, {"def": "镩", "example": null}, {"def": "用凿加工", "example": null}, {"def": "镩", "example": null}, {"def": "短矛", "example": null}, {"def": "镩,短矛。", "example": null}, {"def": "镩cuàn 1.一种兵器。短矛。", "example": null}, {"def": "镩cuān 1.见\\"镩子\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295928307759','蹿','1','cuān','足','19',NULL,'[{"def": "蹿", "example": null}, {"def": "向上跳,向前跳", "example": null}, {"def": "奔跑", "example": null}, {"def": "跃行", "example": null}, {"def": "我一个箭步蹿出去,那小子就玩了个嘴吃屎。--老舍《四世同堂》", "example": null}, {"def": "蹿 cuān", "example": null}, {"def": "①逃跑;奔跑。", "example": null}, {"def": "②向前或向上跳。", "example": null}, {"def": "③喻向上猛长。", "example": null}, {"def": "④迅速上升。", "example": null}, {"def": "⑤方言。喷射;疾流。", "example": null}]','chinese-xinhua','0'),
