('2101143295928307799','鹾','1','cuó','卤','16',NULL,'[{"def": "鹾", "example": null}, {"def": "咸味", "example": null}, {"def": "齹,碱也。--《说文》", "example": null}, {"def": "又如鹾咸(咸味);鹾鱼", "example": null}, {"def": "鹾", "example": null}, {"def": "盐的别名", "example": null}, {"def": "盐曰碱鹾。--《礼记·曲礼》", "example": null}, {"def": "又如鹾政(盐政。管理盐务方面的事);鹾务(盐务);鹾商(盐商);鹾价(盐价);鹾馆(经营盐业的场所)", "example": null}, {"def": "鹾cuó 1.盐的别名。 2.味咸。", "example": null}]','chinese-xinhua','0'),
('2101143295928307800','矬','1','cuó','矢','12',NULL,'[{"def": "矬", "example": null}, {"def": "身材短小", "example": null}, {"def": "容貌丑陋", "example": null}, {"def": "矬", "example": null}, {"def": "将身子蜷缩起来", "example": null}, {"def": "下坠", "example": null}, {"def": "矬子", "example": null}, {"def": "矬子里选将军", "example": null}, {"def": "矬cuó 1.身材短小。 2.泛指高度较低。 3.向下降，从高到低。 4.容貌丑陋。 5.逼，逼迫。", "example": null}]','chinese-xinhua','0'),
