('2101143295928307807','挫','1','cuò','扌','10',NULL,'[{"def": "挫", "example": null}, {"def": "(形声。从手,坐声。本义折断;摧折)", "example": null}, {"def": "同本义", "example": null}, {"def": "挫,摧也。--《说文》", "example": null}, {"def": "或挫或隳。--《老子》", "example": null}, {"def": "而未尝有所挫也。--《国语·吴语》。注毁折也。”", "example": null}, {"def": "又如挫折(劈断,折断);挫顿(摧折损伤)", "example": null}, {"def": "失败", "example": null}, {"def": "挫我于内。--《战国策·秦策》", "example": null}, {"def": "又如挫顿(挫败损伤);挫过(错过);挫北(败北,打败仗)", "example": null}, {"def": "挫伤,折伤", "example": null}, {"def": "顿兵挫锐。--《淮南子·脩务》", "example": null}, {"def": "锐而不挫。--《淮南子·时则》", "example": null}, {"def": "蚊虫之声,闻则挫其精。--《荀子·解蔽》", "example": null}, {"def": "又如挫动(打击;挫折);挫诎(摧挫贬黜);挫强(挫伤强敌);挫锋(锋芒受挫)", "example": null}, {"def": "使减小规模或降低程度", "example": null}, {"def": "挫 cuò", "example": null}, {"def": "①挫折受～。", "example": null}, {"def": "②压下去；降低～败。", "example": null}, {"def": "【挫败】", "example": null}, {"def": "①挫折和失败。", "example": null}, {"def": "②打败。", "example": null}, {"def": "【挫伤】", "example": null}, {"def": "①身体因受重力摩擦或突然挤压而形成的伤。", "example": null}, {"def": "②损伤（积极性、上进心等）。", "example": null}, {"def": "【挫折】", "example": null}, {"def": "①因受压制等使削弱或停顿。", "example": null}, {"def": "②失败；失利。", "example": null}, {"def": "挫zuò 1.捏起，提起。", "example": null}]','chinese-xinhua','0'),
