('2101143295928307819','磋','1','cuō','石','14',NULL,'[{"def": "磋", "example": null}, {"def": "(形声。从石,差声。本义①失足跌倒。见《广韵》。②把骨、角制成器物)", "example": null}, {"def": "磨治象牙。泛指磨治器物", "example": null}, {"def": "治象牙曰磋。--《广韵》", "example": null}, {"def": "骨谓之切,象谓之磋,玉谓之琢,石谓之磨。--《尔雅》", "example": null}, {"def": "切磋琢磨,乃成宝器。--《论衡·量知》", "example": null}, {"def": "如切如磋。--《诗·卫风·淇奥》", "example": null}, {"def": "又如磋磨(磨治器物);磋琢(磨治雕琢);磋切(摩擦)", "example": null}, {"def": "研讨。相互仔细地研究或讨论", "example": null}, {"def": "磋 cuō", "example": null}, {"def": "①把象牙加工成器物。", "example": null}, {"def": "②商量讨论～商。", "example": null}, {"def": "【磋商】讨论的双方交换意见，反复商讨。", "example": null}]','chinese-xinhua','0'),
('2101143295928307820','撮','1','cuō','扌','15',NULL,'[{"def": "撮", "example": null}, {"def": "(形声。从手,最声。本义用手指抓取粒状物)", "example": null}, {"def": "用三指取物;抓取", "example": null}, {"def": "撮,四圭也,一曰两指撮也。--《说文》", "example": null}, {"def": "量多少者不失圭撮。--《汉书·律历志上》", "example": null}, {"def": "鸱鸺夜撮蚤。--《庄子·秋水》", "example": null}, {"def": "又如撮一点儿盐;撮药(抓药);撮土(抓一把土);撮拾(撮取);撮台子(拾掇桌子)", "example": null}, {"def": "把聚拢的东西用簸箕等物铲起", "example": null}, {"def": "拉拢", "example": null}, {"def": "玩弄", "example": null}, {"def": "簇拥", "example": null}, {"def": "摘要,摘取", "example": null}, {"def": "撮 cuō", "example": null}, {"def": "①聚合；聚拢。", "example": null}, {"def": "②用簸箕等把东西聚集起来～垃圾。", "example": null}, {"def": "③摘取（要点）报告～要。", "example": null}, {"def": "④容量单位。十撮等于一勺。现用市撮，一市撮等于一毫升。", "example": null}, {"def": "⑤量词。用于手所撮取的东西一～烟丝。借用于极少的坏人或事物一小～坏人。又见zuǒ。", "example": null}, {"def": "【撮合】从中介绍促成（多指婚姻）。", "example": null}, {"def": "【撮要】", "example": null}, {"def": "①摘取要点。", "example": null}, {"def": "②摘取出来的要点。", "example": null}, {"def": "撮zuǒ", "example": null}, {"def": "⒈量词，用于丛状的毛发一～儿毛。两～子头发。", "example": null}, {"def": "撮zuān 1.古代一种乘载之器。 2.乘。参见\\"撮风\\"。", "example": null}, {"def": "撮zuì 1.项椎。", "example": null}, {"def": "撮chuā 1.握持。", "example": null}]','chinese-xinhua','0'),
