('2101143295932502080','殆','1','dài','歹','9',NULL,'[{"def": "殆", "example": null}, {"def": "(形声。从歹,台声。本义危险)", "example": null}, {"def": "同本义", "example": null}, {"def": "殆,危也。--《说文》", "example": null}, {"def": "民今方殆,视民梦梦--《诗·小雅·正月》", "example": null}, {"def": "亦曰殆哉。--《书·秦誓》。传危殆。”", "example": null}, {"def": "晋有三不殆。--《左传·昭公四年》。注危也。”", "example": null}, {"def": "兵殆于垂沙。--《荀子·议兵》。注谓危亡也。”", "example": null}, {"def": "知己知彼,百战不殆。--《孙子·谋攻》", "example": null}, {"def": "三守不完,则国危身殆。--《韩非子·三守》", "example": null}, {"def": "备危恐殆,急置太子,祸乃无从起。--《韩非子·扬权》", "example": null}, {"def": "此二者,殆物也。--《韩非子·忠孝》", "example": null}, {"def": "又如殆危(危险)", "example": null}, {"def": "困乏;疲惫", "example": null}, {"def": "以有涯雜无涯,殆已。--《庄子·养生", "example": null}, {"def": "殆 dài", "example": null}, {"def": "①〈古〉近于小事～乎遂。（《荀子·王制》）。", "example": null}, {"def": "②〈古〉大概；恐怕～君之子也。（《史记·赵世家》）", "example": null}, {"def": "③〈古〉通\'怠\'。懒惰农者～则土地荒。（《商君书·农战》）", "example": null}, {"def": "④几乎丧失～尽。", "example": null}, {"def": "⑤危险知己知彼，百战不～。", "example": null}, {"def": "【殆尽】几乎所有的都用完了或不存在了伤亡～。", "example": null}]','chinese-xinhua','0'),
('2101143295932502081','玳','1','dài','王','9',NULL,'[{"def": "玳瑁", "example": null}, {"def": "玳瑁筵,亦称玳筵,指精美的筵席", "example": null}, {"def": "足下蹑丝履,头上玳瑁光。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "玳dài 1.\\"玳瑁\\"的简称。", "example": null}]','chinese-xinhua','0'),
('2101143295932502082','贷','1','dài','贝','9',NULL,'[{"def": "贷", "example": null}, {"def": "(形声。从贝,代声。从贝”,表示与钱财有关。本义施予;给予)", "example": null}, {"def": "同本义", "example": null}, {"def": "贷,施也。--《说文》", "example": null}, {"def": "贷,予也。--《广雅》", "example": null}, {"def": "以财投长曰贷。--《大戴礼记·千乘》", "example": null}, {"def": "凡民之货者。--《周礼·泉府》。司农注谓从官借本贾也。”", "example": null}, {"def": "又称贷而益之。--《孟子》", "example": null}, {"def": "不贷无出也。--《庄子·天运》", "example": null}, {"def": "贳贷卖买。--《汉书·食货志下》", "example": null}, {"def": "又如贷施(施舍);贷恤(赈施抚恤)", "example": null}, {"def": "借出钱财", "example": null}, {"def": "宁积粟腐仓而不忍贷人一斗。--《潜夫论·忠贵》", "example": null}, {"def": "又如贷借(金钱物品的借出和借入);贷项(记入账户贷方的账项);贷卖(放贷或出卖)", "example": null}, {"def": "借入", "example": null}, {"def": "贷 dài", "example": null}, {"def": "①借入或借出～款。", "example": null}, {"def": "②所贷的款农～。", "example": null}, {"def": "③推卸责无旁～。", "example": null}, {"def": "④宽恕严惩不～。", "example": null}, {"def": "【贷学金制度】高等院校给家庭经济困难的学生发放无息贷款，以保障他们正常的学习和生活的制度。", "example": null}, {"def": "贷tè 1.通\\"忒\\"。差错。", "example": null}]','chinese-xinhua','0'),
('2101143295932502083','帯','1','dài','','9',NULL,'[{"def": "帯dài 1.《宋元以来俗字谱》\\"带\\"，《太平乐府》﹑《东牕记》﹑《目连记》﹑《金瓶梅》﹑《岭南逸事》作\\"帯\\"。按，亦为\\"带\\"的日本用简体汉字。", "example": null}]','chinese-xinhua','0'),
('2101143295932502084','埭','1','dài','土','11',NULL,'[{"def": "埭", "example": null}, {"def": "堵水的土坝", "example": null}, {"def": "及到新城,策埭于城北。--《晋书·谢安传》", "example": null}, {"def": "又如埭岸(堤岸);埭程(过堰钱。古时在江河水流湍急、沿路险阻处设埭,用牛或人力助船过埭,借以收税)", "example": null}, {"def": "埭dāi〈名〉坝。现多用于地名＞石～（在安徽）", "example": null}, {"def": "埭dài 1.堵水的土坝。古时于水浅不利行船处，筑土遏水，两岸树立转轴，遇有船过，以缆系船，用人或畜力挽之而渡。 2.方言。量词。动量词，相当于\\"次\\"﹑\\"趟\\"。 3.", "example": null}, {"def": "方言。量词。物量词。相当于\\"座\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295932502085','袋','1','dài','衣','11',NULL,'[{"def": "袋", "example": null}, {"def": "(形声。从衣,代声。本义有口的盛器,囊属。也指衣袋) 同本义", "example": null}, {"def": "羊骨杂他骨,作五袋盛之。--《南史·羊鸦仁传》", "example": null}, {"def": "又如网袋;塑料袋;旅行袋;工具袋;子弹袋;烟叶袋;水泥袋", "example": null}, {"def": "袋", "example": null}, {"def": "计量用口袋装的东西", "example": null}, {"def": "袋 dài", "example": null}, {"def": "①口袋；兜子衣～、面～。", "example": null}, {"def": "②量词一～米。", "example": null}, {"def": "【袋狼】哺乳纲有袋目。似狼，但略小。毛棕褐色，有黑褐色横纹。雌兽有育儿袋。夜行性，捕猎方式似狼。产于塔斯马尼亚。", "example": null}, {"def": "【袋鼠】哺乳动物。雌兽腹部有一育儿袋。前肢小，后肢发达，善于跳跃；尾巴粗大，能支持身体，以植物为食。种类多，分布于澳洲。", "example": null}]','chinese-xinhua','0'),
