('2101143295932502111','啖','1','dàn','口','11',NULL,'[{"def": "啖", "example": null}, {"def": "(形声。从口,炎声。本义吃,咬着吃硬的或囫囵吞整的食物)", "example": null}, {"def": "同本义", "example": null}, {"def": "啖,噍啖也。--《说文》", "example": null}, {"def": "啖,食也。--《广雅》", "example": null}, {"def": "啖啖常欲人之有。--《荀子·王霸》。注并吞之貌。”", "example": null}, {"def": "啖函启化。--《太玄·玄莹》。注含也。”", "example": null}, {"def": "樊哙覆其盾于地,加彘肩上,拔剑切而啖之。--《史记·项羽本纪》", "example": null}, {"def": "日啖荔枝三百颗,不辞长作岭南人。--宋·苏轼《食荔枝二首》", "example": null}, {"def": "茹啖其草木之荑实。--明·刘基《苦斋记》", "example": null}, {"def": "又如啖蔗(吃甘蔗,愈吃愈甜。比喻渐入佳境);啖啖(贪吃的样子);啖指咬舌(恐惧不敢多言的样子)", "example": null}, {"def": "给吃", "example": null}, {"def": "吉妇取枣以啖吉。", "example": null}, {"def": "啖 dàn", "example": null}, {"def": "①〈古〉吃或给别人吃。", "example": null}, {"def": "②拿利益引诱人～以私利。", "example": null}]','chinese-xinhua','0'),
('2101143295932502112','弹','1','dàn','弓','11',NULL,'[{"def": "弹", "example": null}, {"def": "(形声。从弓,单声。本义弹丸)", "example": null}, {"def": "同本义", "example": null}, {"def": "弹,行丸也。--《说文》", "example": null}, {"def": "长安大道边,挟弹谁家儿?--唐·苏涣《变律》其三", "example": null}, {"def": "又如枪弹;弹子涡(卵石);枪林弹雨(形容战斗激烈);弹丸黑子(形容地域狭小)", "example": null}, {"def": "形状像弹丸的东西,如圆形的果实;禽鸟的卵等", "example": null}, {"def": "其法乃以凫弹数十,黄、白各聚一器。--宋·周密《齐东野语》", "example": null}, {"def": "弹弓", "example": null}, {"def": "援弹飞丸,应弦而落。--《魏书》", "example": null}, {"def": "炸弹", "example": null}, {"def": "弹 dàn", "example": null}, {"def": "①弹子；弹丸。", "example": null}, {"def": "②枪弹、炮弹、炸弹之类的总称。又见tán。", "example": null}, {"def": "【弹道导弹】\'弹道式导弹\'的简称。由火箭发动机推送到一定高度和一定速度后，发动机关闭，弹头沿着预定弹道飞向目标。", "example": null}, {"def": "【弹道曲线】炮弹飞行的轨迹。", "example": null}, {"def": "【弹道式导弹】见【弹道导弹】。", "example": null}, {"def": "【弹尽粮绝】见【弹尽援绝】。", "example": null}, {"def": "【弹尽援绝】弹药用尽，又得不到补给和救援。形容战事艰难，处境十分险恶。又作弹尽粮绝。", "example": null}, {"def": "【弹丸】", "example": null}, {"def": "①弹弓弹射所用的泥石小球或铁制小球。", "example": null}, {"def": "②比喻地方狭小～之地。", "example": null}, {"def": "弹（彈）tán", "example": null}, {"def": "⒈利用弹性射出弹丸等～击。", "example": null}, {"def": "⒉用手指拨弄，敲击。或手指受压后，用力伸出的动作～琴。～冠。～了他两下。", "example": null}, {"def": "⒊使振动～动。～棉花。", "example": null}, {"def": "⒋批评，抨击，检举评～。讥～。～劾。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎［弹性］物体受外力后变形，外力一去即恢复原状的性能。〈引〉收缩性。", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
('2101143295932502113','惮','1','dàn','忄','11',NULL,'[{"def": "惮", "example": null}, {"def": "使惊恐", "example": null}, {"def": "则虽有疾风,亦弗之能惮矣。--《周礼》", "example": null}, {"def": "惮", "example": null}, {"def": "(形声。从心,单声。本义畏难,怕麻烦)", "example": null}, {"def": "同本义", "example": null}, {"def": "岂敢惮行?--《诗·小雅·?蛮》", "example": null}, {"def": "何惮于病?--《左传·僖公七年》", "example": null}, {"def": "过则勿惮改。--《论语·学而》", "example": null}, {"def": "何许子之不惮烦?--《孟子·滕文公上》", "example": null}, {"def": "小人而无忌惮也。--《礼记·中庸》", "example": null}, {"def": "以缚即炉火烧绝之,虽疮手勿惮。--唐·柳宗元《童区寄传》", "example": null}, {"def": "又如肆无忌惮;惮劳(害怕劳苦);惮惮(忧惧惶恐);惮烦(畏惧烦琐)", "example": null}, {"def": "憎恶;忌恨", "example": null}, {"def": "权内", "example": null}, {"def": "惮 dàn怕肆无忌～。", "example": null}, {"def": "惮dá 1.惊骇。", "example": null}]','chinese-xinhua','0'),
('2101143295932502114','淡','1','dàn','氵','11',NULL,'[{"def": "淡", "example": null}, {"def": "(形声。从水,炎声。本义味淡;味道不浓,不咸)", "example": null}, {"def": "同本义", "example": null}, {"def": "淡,薄味也。--《说文》", "example": null}, {"def": "淡而不厌。--《礼记·中庸》", "example": null}, {"def": "君子淡以成。--《礼记·表记》。注无酸酢少味也。”", "example": null}, {"def": "淡也者,五味之中也。--《管子·水地》", "example": null}, {"def": "大味必淡。--《汉书·扬雄传》。注谓无主味也。”", "example": null}, {"def": "其水淡而清。--《世说新语·言语》", "example": null}, {"def": "又如淡酒;淡味;淡句(平淡乏味的诗句);淡而不厌(指诗文恬淡而不乏味);淡菜", "example": null}, {"def": "稀薄", "example": null}, {"def": "天高云淡,望断南飞雁。--毛泽东《清平乐·六盘山》", "example": null}, {"def": "又如淡水白酒(薄酒);淡蛾(淡眉);淡烟(轻烟);淡粥(稀", "example": null}, {"def": "淡 dàn", "example": null}, {"def": "①含的盐分少，不咸菜太～。", "example": null}, {"def": "②含某种成分少，不浓～酒、～绿、云～风清。", "example": null}, {"def": "③不热情冷～。", "example": null}, {"def": "④生意不兴旺～季。", "example": null}, {"def": "【淡泊】不追求名利。又作澹泊。", "example": null}, {"def": "【淡薄】", "example": null}, {"def": "①密度小云雾～。", "example": null}, {"def": "②味道不浓酒味～。", "example": null}, {"def": "③（感情、兴趣）不浓厚。", "example": null}, {"def": "④印象不深。", "example": null}, {"def": "【淡化】", "example": null}, {"def": "①将海水由咸变淡。", "example": null}, {"def": "②文学创作上的一种新手段，即消除造作和人为的成份，追求真实、自然地表现生活。", "example": null}, {"def": "【淡季】", "example": null}, {"def": "①生意不兴旺的季节旅游～。", "example": null}, {"def": "②某种东西出产少的季节蔬菜～。", "example": null}, {"def": "【淡漠】", "example": null}, {"def": "①冷淡；不热情。", "example": null}, {"def": "②记忆不真切；印象不深刻。", "example": null}, {"def": "【淡青】浅蓝而微绿的颜色。", "example": null}, {"def": "【淡然】形容不经心，不在意。又作澹然。", "example": null}, {"def": "【淡水资源】主要指陆地水，包括江河湖泊中的水、高山积雪和冰川、潜入地下浅层可以利用的地下水等。主要来源于大气降水。是工农业生产和人民生活所必需的水资源。", "example": null}, {"def": "【淡雅】（颜色花样）素净雅致。", "example": null}, {"def": "淡yǎn 1.见\\"淡淡\\"。 2.见\\"澹淡\\"。", "example": null}, {"def": "淡yàn 1.见\\"淡淡\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295932502115','萏','1','dàn','艹','11',NULL,'[{"def": "菡萏 (形声。从苃,函声。菡萏。本义荷花) 同本义", "example": null}, {"def": "迨至菡萏成花。--明·李渔《闲情偶寄·种植部》", "example": null}, {"def": "菡萏", "example": null}, {"def": "萏dàn ［菡萏］荷花的别称。", "example": null}]','chinese-xinhua','0'),
('2101143295932502116','蛋','1','dàn','虫','11',NULL,'[{"def": "蛋", "example": null}, {"def": "禽类或龟、蛇等所产的卵", "example": null}, {"def": "骂人的话", "example": null}, {"def": "完蛋", "example": null}, {"def": "形状像蛋的东西", "example": null}, {"def": "蛋 dàn", "example": null}, {"def": "①家禽、鸟、龟、蛇等所产的卵；特指鸡蛋。", "example": null}, {"def": "②形状象蛋的东西山药～。", "example": null}, {"def": "【蛋白质】由多种氨基酸结合而成的高分子有机化合物。是构成生物体活质的最重要的部分，是生命的基础。由于所含的氨基酸的数量、性质和结合方式不同，可分很多种。任", "example": null}, {"def": "何一种蛋白质中不同氨基酸的联结顺序是高度专一的，因而具有特征性。又称朊。", "example": null}, {"def": "【蛋品】用蛋类制成的食品。如咸鸭蛋、松花蛋、蛋黄粉等。", "example": null}, {"def": "【蛋青】像青鸭蛋壳那样蓝中带绿的颜色。", "example": null}]','chinese-xinhua','0'),
