('2101143295932502142','赕','1','dǎn','贝','12',NULL,'[{"def": "赕", "example": null}, {"def": "古代南方一些少数民族以财赎罪。亦指赎罪的财货", "example": null}, {"def": "古代一些少数民族对江河的称呼", "example": null}, {"def": "川谓之賧,谷谓之浪,山谓之和。--《蛮夷风俗》", "example": null}, {"def": "賧佛", "example": null}, {"def": "赕tàn 1.谓古代南方一些少数民族以财赎罪。亦指这些民族赎罪的财货。 2.傣语指以物献佛。 3.古代一些少数民族对江河的称呼。地名亦多用此字。", "example": null}]','chinese-xinhua','0'),
('2101143295936696320','紞','1','dǎn','糹','10',NULL,'[{"def": "紞", "example": null}, {"def": "紞,冕冠县塞耳者。从糸,冘声。--《说文》。", "example": null}, {"def": "王后亲织玄紞。--《国语·鲁语》", "example": null}, {"def": "又如紞纩", "example": null}, {"def": "缝在被端的丝带", "example": null}, {"def": "象声词。击鼓声", "example": null}, {"def": "紞dǎn 1.古代冠冕上用以系瑱的丝绳。 2.缝在被端的丝带。用以识别首尾。 3.象声词。击鼓声。参见\\"紞如\\"﹑\\"紞然\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295936696321','掸','1','dǎn','扌','11',NULL,'[{"def": "掸", "example": null}, {"def": "拂去", "example": null}, {"def": "筛", "example": null}, {"def": "无皮的罗儿掸三遍。--《中国民谣资料·孟姜女》", "example": null}, {"def": "掸  shan", "example": null}, {"def": "中国史书上对傣族的一种称呼", "example": null}, {"def": "古国名", "example": null}, {"def": "掸,西南夷国名。--《集韵》", "example": null}, {"def": "掸 dǎn用掸子之类的东西轻轻拂扫或拍打，以去掉器物上的灰尘等～桌子、～衣服。又见shàn。", "example": null}, {"def": "【掸子】用鸡毛或布条等绑成的除去灰尘的用具。", "example": null}, {"def": "掸（撣）shàn", "example": null}, {"def": "⒈〈古〉我国对傣族的称呼。", "example": null}, {"def": "掸chán 1.牵引。 2.相缠不去。参见\\"掸掸\\"。 3.调戏。", "example": null}, {"def": "掸tān 1.持不坚;瘫倒。", "example": null}, {"def": "掸dàn 1.触。 2.用同\\"弹\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295936696322','亶','1','dǎn','亠','13',NULL,'[{"def": "亶", "example": null}, {"def": "(形声。本义谷多)", "example": null}, {"def": "同本义", "example": null}, {"def": "亶,多谷也。--《说文》", "example": null}, {"def": "择三有事,亶侯多藏。--《诗·小雅·十月之交》", "example": null}, {"def": "厚道;忠实", "example": null}, {"def": "亶,信也;又,诚也。--《尔雅》", "example": null}, {"def": "不实于亶。--《诗·大雅·板》", "example": null}, {"def": "又如亶厚(忠厚,淳厚);亶诚(真诚)", "example": null}, {"def": "平坦;广大", "example": null}, {"def": "姓", "example": null}, {"def": "亶dǎn 1.谷多貌。 2.诚;信。 3.厚道，忠实。 4.广大;平坦。参见\\"亶亶\\"。 5.通\\"殚\\"。竭尽。 6.通\\"瘅\\"。疲惫;病。 7.飞貌。参见\\"亶翔\\"。 8.姓『代有亶诵。", "example": null}, {"def": "见《后汉书．律历志中》。", "example": null}, {"def": "亶dàn 1.仅；只。", "example": null}, {"def": "亶chán 1.见\\"亶爰\\"。", "example": null}, {"def": "亶zhān 1.难行貌。", "example": null}]','chinese-xinhua','0'),
