('2101143295936696333','殚','1','dān','歹','12',NULL,'[{"def": "殚", "example": null}, {"def": "(形声。从歹,单声。本义用尽,竭尽)", "example": null}, {"def": "同本义", "example": null}, {"def": "殚,极尽也。从歹,单声。--《说文》", "example": null}, {"def": "殚,尽也。--《广雅》", "example": null}, {"def": "殚所未见。--张衡《西京赋》", "example": null}, {"def": "穆穆之礼殚。--张衡《东京赋》", "example": null}, {"def": "相为殚智竭力。--《吕氏春秋·本味》", "example": null}, {"def": "殚天下之财。--《汉书·杜钦传》", "example": null}, {"def": "犹未殚于《九章》。--《楚辞·忧苦》", "example": null}, {"def": "彦博以爱国故,耗思殚神。--《唐书·温彦博传》", "example": null}, {"def": "殚其地之出,竭其庐之入。(殚、竭同义,尽也。)。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "不可殚言。--唐·李朝威《柳毅传》", "example": null}, {"def": "又如殚心竭力(用尽心思,竭尽心力);殚虑(竭尽智虑);殚形(使人", "example": null}, {"def": "殚 dān,用尽；竭尽～力、～心。", "example": null}, {"def": "【殚精竭虑】用尽心思谋虑。瘅 dān又见dàn。", "example": null}, {"def": "【瘅疟】一种疟疾。主要症状是发高烧，烦躁，口渴，呕吐等。", "example": null}]','chinese-xinhua','0'),
('2101143295936696334','瘅','1','dān','疒','13',NULL,'[{"def": "瘅", "example": null}, {"def": "热症;湿热症", "example": null}, {"def": "下民卒瘅。--《诗·大雅·板》", "example": null}, {"def": "又如瘅疾(热病)", "example": null}, {"def": "瘅疟", "example": null}, {"def": "瘅", "example": null}, {"def": "病;劳苦", "example": null}, {"def": "瘅,痨病也。从疒,单声。--《说文》。字亦作癲”。", "example": null}, {"def": "瘅,劳也。--《尔雅》", "example": null}, {"def": "故书货之瘅于民用者。--《周礼·泉府》", "example": null}, {"def": "又如瘅疽(恶疮。俗名对口疽)", "example": null}, {"def": "通疸”。黄疸病", "example": null}, {"def": "瘅", "example": null}, {"def": "厚(与薄”相对);", "example": null}, {"def": "名曰瘅疟。--《素问·疟论》", "example": null}, {"def": "又如瘅暑(盛热,酷热);瘅热", "example": null}, {"def": "瘅 dàn", "example": null}, {"def": "①因劳累而生病。", "example": null}, {"def": "②憎恨彰善～恶。又见dān。", "example": null}, {"def": "瘅tán 1.手足风病。指风瘫。", "example": null}, {"def": "瘅dǎn 1.指疫鬼。", "example": null}]','chinese-xinhua','0'),
('2101143295936696335','箪','1','dān','竹','14',NULL,'[{"def": "箪", "example": null}, {"def": "(形声。从竹,单声。本义古代盛饭的圆形竹器)", "example": null}, {"def": "同本义", "example": null}, {"def": "箪,笥也。从竹,单声。--《说文》", "example": null}, {"def": "箪,小筐也。--《汉律令》", "example": null}, {"def": "苞苴箪笥。--《礼记·曲礼》", "example": null}, {"def": "栉实于箪。--《仪礼·士冠礼》", "example": null}, {"def": "箪食与肉。--《左传·宣公二年》", "example": null}, {"def": "一箪食,一豆羹,得之则生,弗得则死。--《孟子·告子上》", "example": null}, {"def": "又如箪笥(盛饭竹器);箪瓢(箪食器;瓢饮器。比喻家境贫寒,生活清苦)", "example": null}, {"def": "盛物件的小筐", "example": null}, {"def": "与之一箪珠,使问赵孟。--《左传·哀公二十年》", "example": null}, {"def": "箪食", "example": null}, {"def": "箪 dān古代盛饭用的圆形竹器。", "example": null}, {"def": "【箪食壶浆】原指百姓用酒饭欢迎军队。现多形容正义之师受人民欢迎的情状。", "example": null}]','chinese-xinhua','0'),
