('2101143295936696361','凼','1','dànɡ','凵','6',NULL,'[{"def": "凼", "example": null}, {"def": "凼dàng同\\"氹\\"。义同\\"荡\\"。水坑；小池子。一般用以积制沤肥。", "example": null}, {"def": "凼dàng同\\"氹\\"。", "example": null}, {"def": "凼gān 1.方言。蓄水池。", "example": null}]','chinese-xinhua','0');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`,`hit_count`) VALUES
('2101143295945084928','宕','1','dànɡ','宀','8',NULL,'[{"def": "宕", "example": null}, {"def": "洞穴;洞屋", "example": null}, {"def": "宕,过也。一曰洞屋。从宀,磝省声。--《说文》。按,字从宀,洞屋当为本训。洞屋者,四围无障蔽之谓。", "example": null}, {"def": "引申为空旷或昏暗。如宕冥(辽阔无垠的天空;迟钝昏昧)", "example": null}, {"def": "坑洼", "example": null}, {"def": "宕", "example": null}, {"def": "穿过;通过", "example": null}, {"def": "邗子寻犬,宕入仙穴。--《列仙传》", "example": null}, {"def": "引申为流荡;游荡", "example": null}, {"def": "回过曰宕。--《通俗文》", "example": null}, {"def": "长狄兄弟三人佚宕中国。--《谷梁传·文公十一年》", "example": null}, {"def": "借问叹者谁,言是宕子妻。--曹植《怨歌行》", "example": null}, {"def": "又如宕子(荡子。到处流浪的人);宕宕(无定止的样子);宕落(流动而富于变化)", "example": null}, {"def": "放", "example": null}, {"def": "宕dàng", "example": null}, {"def": "①拖延延～│推～│拖～。", "example": null}, {"def": "②不受拘束∶跌～。", "example": null}]','chinese-xinhua','0'),
('2101143295945084929','砀','1','dànɡ','石','8',NULL,'[{"def": "砀", "example": null}, {"def": "有花纹的石头", "example": null}, {"def": "砀,文石也。从石,?", "example": null}, {"def": "梁国砀。--《汉书·地理志》。注山出文石,在今河南归德府。”", "example": null}, {"def": "君看石芒砀,掩泪悲千古。--李白《丁都护歌》", "example": null}, {"def": "又如芒砀(形容山石大而多);砀基(用有花纹的石头造的墙基)", "example": null}, {"def": "砀山(山名),在安徽省砀山县东南", "example": null}, {"def": "砀", "example": null}, {"def": "突然", "example": null}, {"def": "肱砀骇以奋肆。--马融《长笛赋》。注突也。”", "example": null}, {"def": "又如砀骇(突然跌起)", "example": null}, {"def": "砀dàng 1.有花纹的石头。 2.荡漾;荡溢。 3.广大。 4.突;闯。 5.见\\"砀极\\"。 6.山名。在安徽省砀山县东南。 7.古地名。本战国楚邑，秦置县，隋改砀山。今安徽", "example": null}, {"def": "省砀山县。", "example": null}]','chinese-xinhua','0'),
('2101143295945084930','垱','1','dànɡ','','10',NULL,'[{"def": "垱dàng 1.方言。为便于灌溉而筑的小土堤。 2.用为与当地所筑堤堰有关的地名。江西省南昌县嵩安乡有舒家垱，丰城县剑江西有绳湾垱，又县西七十里滨瑞河有滕坊垱，都", "example": null}, {"def": "是堤堰之属。见清《嘉庆一统志．江西．南昌府二》。", "example": null}]','chinese-xinhua','0'),
('2101143295945084931','荡','1','dànɡ','艹','9',NULL,'[{"def": "荡", "example": null}, {"def": "(会意。从皿,从汤,汤亦声。本义洗涤)", "example": null}, {"def": "同本义", "example": null}, {"def": "荡亡秦之毒螫。--班固《西都赋》", "example": null}, {"def": "动;摇动;震动", "example": null}, {"def": "此四六者不荡,胸中则正。--《庄子·庚桑楚》", "example": null}, {"def": "天下不能荡也。--《荀子·劝学》", "example": null}, {"def": "以荡上心。--《吕氏春秋·季春纪》", "example": null}, {"def": "以其休止不荡也。--《淮南子·说山》", "example": null}, {"def": "从流漂荡,任意东西。--吴均《与朱元思书》", "example": null}, {"def": "波心荡,冷月无声。--宋·姜夔《扬州慢》", "example": null}, {"def": "又如;荡突(冲撞);荡心(摇荡心神);荡摇(动摇);荡荡悠悠(摇荡、飘流的样子)", "example": null}, {"def": "清除", "example": null}, {"def": "荡平塞表。--曹操《表论田畴功》", "example": null}, {"def": "又如荡风", "example": null}, {"def": "荡 dàng", "example": null}, {"def": "①摇动；摆动动～、飘～。", "example": null}, {"def": "②无事走来走去；闲～。", "example": null}, {"def": "③清洗～涤。", "example": null}, {"def": "④清除全部弄光；扫～。", "example": null}, {"def": "⑤放纵；行为不检点放～。", "example": null}, {"def": "⑥浅水湖芦苇～。", "example": null}, {"def": "【荡涤】冲洗；清除。", "example": null}, {"def": "【荡气回肠】见【回肠荡气】。", "example": null}, {"def": "【荡然】形容原有的东西完全消失～无存。", "example": null}, {"def": "【荡漾】（水波等）轻轻动微波～、春风～。", "example": null}, {"def": "荡tàng 1.量词。", "example": null}, {"def": "荡tāng 1.古水名。即今之汤水，在河南省汤阴县北境。", "example": null}]','chinese-xinhua','0'),
('2101143295945084932','档','1','dànɡ','木','10',NULL,'[{"def": "档", "example": null}, {"def": "(形声。从木,当声。本义器物上用以分格或撑的横木条)", "example": null}, {"def": "同本义", "example": null}, {"def": "俗谓横木框档。--《正字通》", "example": null}, {"def": "又如床档;十三档算盘", "example": null}, {"def": "档案,排列或分类过的卡片或文件卷宗", "example": null}, {"def": "存放案卷用的带格子的橱", "example": null}, {"def": "按重要性、质量或价值排列的级别", "example": null}, {"def": "指曲艺、杂技表演一个节目", "example": null}, {"def": "档 dàng", "example": null}, {"def": "①存放案卷用的带格子的架子或橱柜归～。", "example": null}, {"def": "②档案，分类保存的文件、材料等查～。", "example": null}, {"def": "③（器物上）起支撑固定作用的木条或细棍。", "example": null}, {"def": "④（商品、产品的）等级高～。", "example": null}, {"def": "【档案】具有使用价值、分类保存的各种文件材料。中国从夏、商起，就有了档案。", "example": null}, {"def": "【档案学】揭示档案和档案工作的本质和发展规律，研究档案的管理、利用的原则和方法的学科。", "example": null}, {"def": "【档次】按照一定的标准排列的等级次序。起初常用于指商品（产品）的等级，现扩展到指某一类事物发展的层次性、阶段性。", "example": null}]','chinese-xinhua','0'),
