('2101143295945084950','当','1','dānɡ','彐','6',NULL,'[{"def": "当", "example": null}, {"def": "(形声。从田,尚声。本义两块田相当、相等)", "example": null}, {"def": "对等;相当于", "example": null}, {"def": "当,田相值也。--《说文》", "example": null}, {"def": "必当其位。--《吕氏春秋·孟夏纪》", "example": null}, {"def": "蔽贤者当之。--《孟子·离娄下》", "example": null}, {"def": "朱也当御。--《国语·晋语》", "example": null}, {"def": "当之者戕焉。--《国语·晋语一》", "example": null}, {"def": "又如旗鼓相当;门当户对;当才(才能与所任之事相当);当匹(匹敌;对等);实力相当", "example": null}, {"def": "面对着", "example": null}, {"def": "木兰当户织。--《乐府诗集·木兰诗》", "example": null}, {"def": "又如当户(对着门户);当风(正对着风);当着矮人,别说短话(面对着某种有缺陷的人,不要说有关他短处的话,以避影射之嫌);当头对面(面", "example": null}]','chinese-xinhua','0'),
('2101143295945084951','珰','1','dānɡ','','6',NULL,'[{"def": "珰dāng 1.古代妇女的耳饰。 2.借指宦官『代宦官充武职者，其冠用珰和貂尾为饰，故后代用称宦官。 3.瓦当。屋椽头的装饰。 4.见\\"珰琅\\"﹑\\"珰珰\\"。 5.见\\"琅珰\\"", "example": null}, {"def": "。", "example": null}]','chinese-xinhua','0'),
('2101143295945084952','裆','1','dānɡ','衤','11',NULL,'[{"def": "裆", "example": null}, {"def": "(形声。从衣,当声。本义两裤腿相连的地方)", "example": null}, {"def": "同本义", "example": null}, {"def": "两条裤腿缝相接触的接口部分", "example": null}, {"def": "裆,穷裦也。今以裦有当而旁开者为裆。--《六书故》", "example": null}, {"def": "独不见群虱之处禈中,…动不敢出禈(裤子)裆。--阮籍《大人先生传》", "example": null}, {"def": "又如横裆;直裆;裤裆", "example": null}, {"def": "又指两条腿的中间,由于两条腿的分离而形成的一个形似锐角的空间。如腿裆", "example": null}, {"def": "坎肩儿,背心", "example": null}, {"def": "裤", "example": null}, {"def": "裆dāng 1.衣名。 2.裤裆。两裤腿相连的地方。", "example": null}]','chinese-xinhua','0'),
