('2101143295949279314','敌','1','dí','攵','10',NULL,'[{"def": "敌", "example": null}, {"def": "(形声。从攴,啇声。本义匹敌;对等)", "example": null}, {"def": "同本义", "example": null}, {"def": "敌,仇也。--《说文》", "example": null}, {"def": "敌,匹也。--《尔雅》", "example": null}, {"def": "四国之兵敌。--《战国策·秦策》。注强弱等也。”", "example": null}, {"def": "且夫自敌以下。--《国语·楚语》", "example": null}, {"def": "敌国宾至。--《国语·周语》", "example": null}, {"def": "敌则能战之。--《孙子·谋攻》", "example": null}, {"def": "又如试看天下谁能敌;敌体(彼此地位相等,不分上下);敌礼(平等的礼节);匹敌(谓才艺相当);势均力敌", "example": null}, {"def": "抵抗;抵挡", "example": null}, {"def": "(司马懿)乃魏之名将,恐汝不能敌之。--《三国演义》", "example": null}, {"def": "又如敌不住;寡不敌众", "example": null}, {"def": "攻击", "example": null}, {"def": "屠大窘,恐前后受其敌。--《聊斋志异", "example": null}, {"def": "敌 dí", "example": null}, {"def": "①仇敌～人、抗～。", "example": null}, {"def": "②对抗；抵拒所向无～。", "example": null}, {"def": "③同等；相当势均力～。", "example": null}, {"def": "【敌敌畏】〈外〉一种有机磷杀虫剂，为稍带芳香臭体的无色透明液体。", "example": null}, {"def": "【敌酋】敌人的头子。", "example": null}, {"def": "【敌人】敌对的人或敌对的方面。", "example": null}]','chinese-xinhua','0'),
('2101143295949279315','涤','1','dí','氵','10',NULL,'[{"def": "涤", "example": null}, {"def": "(形声。从水,条声。本义洗)", "example": null}, {"def": "同本义", "example": null}, {"def": "涤,洒也。--《说文》", "example": null}, {"def": "射人宿视涤。--《仪礼·大射仪》", "example": null}, {"def": "水曰清涤。--《礼记·曲礼》", "example": null}, {"def": "及执事,视涤濯。--《周礼·太宰》", "example": null}, {"def": "又如涤篆(洗印。用以检查印是否有缺陷);涤濯(洗涤);涤耳(洗耳)", "example": null}, {"def": "除,清除", "example": null}, {"def": "进明德而崇业,涤饕餮之贪欲。--张衡《东京赋》", "example": null}, {"def": "又如涤瑕(洗除瑕疵。有改过迁善之意);涤地无类(荡涤无遗。形容清除得彻底)", "example": null}, {"def": "打扫", "example": null}, {"def": "十月涤场。--《诗·豳风·七月》", "example": null}, {"def": "又如涤场(打扫场地)", "example": null}, {"def": "涤", "example": null}, {"def": "涤宫,古代宫中饲养祭祀牲畜的房子", "example": null}, {"def": "古", "example": null}, {"def": "涤 dí洗～除、洗～。", "example": null}, {"def": "【涤荡】同\'荡涤\'。洗涤；清除。", "example": null}, {"def": "【涤纶】一种合成纤维。用乙二醇、对苯二甲酸二甲酯等原料合成。", "example": null}, {"def": "【涤罪所】见【炼狱】。", "example": null}]','chinese-xinhua','0'),
('2101143295949279316','荻','1','dí','艹','10',NULL,'[{"def": "荻", "example": null}, {"def": "多年生草本植物,生在水边,叶子长形,似芦苇,秋天开紫花", "example": null}, {"def": "浔阳江头夜送客,枫叶荻花秋瑟瑟。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如荻画(用荻杆在地上画画写字);荻竹(即荻);荻苗(荻的花穗)", "example": null}, {"def": "荻 dí多年生草本植物。形状象芦苇，地下茎蔓延，叶子长形，紫色花穗，生长在水边。茎可以编席箔。", "example": null}]','chinese-xinhua','0'),
