('2101143295949279351','谛','1','dì','讠','11',NULL,'[{"def": "谛", "example": null}, {"def": "(形声。从言,帝声。本义细察;详审)", "example": null}, {"def": "同本义", "example": null}, {"def": "谛,审也。从言,帝声,字亦作謆。--《说文》", "example": null}, {"def": "军当远出,卿诸人好谛其事。--《三国志》", "example": null}, {"def": "明白;了解", "example": null}, {"def": "或有未谛,循循诱之。--鲁迅《且介亭杂文》", "example": null}, {"def": "谛", "example": null}, {"def": "详细,仔细", "example": null}, {"def": "当时乍见惊心目,凝视谛听殊未足。--白居易《霓裳羽衣舞歌》", "example": null}, {"def": "审谛之,短小,黑赤色,顿非前物。--《聊斋志异·促织》", "example": null}, {"def": "又如谛听(仔细地听)", "example": null}, {"def": "谛", "example": null}, {"def": "佛教名词。谓真实无谬的道理", "example": null}, {"def": "实义是谛义、真义、如义、不颠倒义、无虚诳义。--《大毗婆沙论》", "example": null}, {"def": "事物的", "example": null}, {"def": "谛 dì", "example": null}, {"def": "①仔细（看或听）～听。", "example": null}, {"def": "②道理；真理真～。", "example": null}, {"def": "谛tí 1.号哭。", "example": null}]','chinese-xinhua','0'),
('2101143295949279352','棣','1','dì','木','12',NULL,'[{"def": "棣", "example": null}, {"def": "(形声。从木,隶声。本义木名。常棣,即白棣”,喻兄弟)", "example": null}, {"def": "同本义", "example": null}, {"def": "弟", "example": null}, {"def": "棣 dì", "example": null}, {"def": "①植物～棠（落叶灌木、花黄色、果实黑色）、棠～。", "example": null}, {"def": "②同\'弟\'。旧时多用于书信贤～。", "example": null}, {"def": "【棣莫佛】（1667-1754） 法国数学家。", "example": null}, {"def": "【棣莫佛定理】〈数〉复数的n(n是是自然数)次幂的模等于这个复数的模的(次幂，它的辐角等于这个复数的辐角的n倍。", "example": null}, {"def": "棣tì 1.相通，通达。参见\\"棣通\\"﹑\\"棣达\\"。", "example": null}, {"def": "棣dài 1.见\\"棣棣\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295949279353','睇','1','dì','目','12',NULL,'[{"def": "睇", "example": null}, {"def": "(形声。从目,弟声。本义斜视) 同本义", "example": null}, {"def": "睇,目小袤视也。--《说文》", "example": null}, {"def": "睇视。--《礼记·内则》。注睇,倾视也。”", "example": null}, {"def": "既含睇兮又宜笑。--《楚辞·山鬼》", "example": null}, {"def": "离娄微睇。--《史记·屈原贾生列传》", "example": null}, {"def": "又如睇目(斜着眼);睇眄(目光流动;斜视);睇盼(顾盼);睇视(斜视)", "example": null}, {"def": "睇dì 1.斜视;流盼。", "example": null}, {"def": "睇tī 1.视;望。 2.明察。", "example": null}]','chinese-xinhua','0'),
('2101143295949279354','缔','1','dì','纟','12',NULL,'[{"def": "缔", "example": null}, {"def": "(形声。从糸,帝声。本义结在一起)", "example": null}, {"def": "同本义", "example": null}, {"def": "缔,结不解也。--《说文》", "example": null}, {"def": "合从缔交。--贾谊《过秦论》。注连接也。”", "example": null}, {"def": "缔交翩翩。--左思《吴都赋》", "example": null}, {"def": "又如缔婚(结婚);缔生(联结而生);缔连(联结)", "example": null}, {"def": "引申为郁结", "example": null}, {"def": "气缭转而自缔。--《楚辞》", "example": null}, {"def": "结合", "example": null}, {"def": "订立", "example": null}, {"def": "构造,建造", "example": null}, {"def": "约束;限制", "example": null}, {"def": "缔 dì结合；订立；～约。", "example": null}, {"def": "【缔结】订立（条约等）。", "example": null}, {"def": "【缔约】订立条约。", "example": null}, {"def": "【缔造】创立；建立（多指伟大的事业或重大的组织）。", "example": null}]','chinese-xinhua','0'),
