('2101143295953473558','诋','1','dǐ','讠','7',NULL,'[{"def": "诋", "example": null}, {"def": "(形声。从言,氐声。本义诬蔑,毁谤)", "example": null}, {"def": "同本义", "example": null}, {"def": "诋,毁也。--《广雅·释诂二》", "example": null}, {"def": "诋毁也,辱也。--《汉书·刘向传》注", "example": null}, {"def": "历诋公卿大臣。--《汉书·息夫躬传》", "example": null}, {"def": "虽有诋讦之民,无所依矣。--《墨子·修身》", "example": null}, {"def": "又如诋诟(诬蔑;毁谤);诋讦(诋毁攻击);诋辱(毁谤侮辱)", "example": null}, {"def": "谴责", "example": null}, {"def": "露表告将入关,因诋宦竖柄朝,垢蠹纪纲。--《新唐书》", "example": null}, {"def": "骂", "example": null}, {"def": "弟闻得世兄也诋尽流俗,性情中另有一番见解。--《红楼梦》", "example": null}, {"def": "诋大酋当死。--宋·文天祥《指南录·后序》", "example": null}, {"def": "欺", "example": null}, {"def": "朔擅诋欺天子从官,当弃市。--《汉", "example": null}, {"def": "诋 dǐ毁谤；说坏话～毁。", "example": null}, {"def": "【诋毁】毁谤；诬蔑。", "example": null}]','chinese-xinhua','0'),
('2101143295953473559','邸','1','dǐ','阝','7',NULL,'[{"def": "邸", "example": null}, {"def": "(形声。从邑,氐声。本义战国时诸侯或朝见皇帝时在京城的住所。泛指官员办事或居住的处所)", "example": null}, {"def": "同本义", "example": null}, {"def": "邸,属国舍也。--《说文》", "example": null}, {"def": "舍燕邸。--《汉书·卢绾传》。注诸侯王及诸郡朝宿之馆,在京师者谓之邸。”", "example": null}, {"def": "又如邸城(古代在京师为郡国诸侯或外藩君主朝觐起居所建的小城)", "example": null}, {"def": "高级官员、贵族办事或居住的地方", "example": null}, {"def": "店铺", "example": null}, {"def": "止,到", "example": null}, {"def": "自中山西邸瓠口为渠。--", "example": null}, {"def": "邸 dǐ", "example": null}, {"def": "①旧指高级官员的住所官～。", "example": null}, {"def": "②姓。", "example": null}]','chinese-xinhua','0'),
