('2101143295953473579','嘀','1','dī','口','14',NULL,'[{"def": "嘀嗒", "example": null}, {"def": "嘀咕", "example": null}, {"def": "你一个人在这里嘀咕什么?", "example": null}, {"def": "他又犯嘀咕了", "example": null}, {"def": "嘀 dī又见dí。", "example": null}, {"def": "【嘀里嘟噜】形容说话很快，使人听不清楚。", "example": null}, {"def": "嘀 dí。又见dī。", "example": null}, {"def": "【嘀咕】", "example": null}, {"def": "①小声说；私下说。", "example": null}, {"def": "②猜疑；犹疑听他这么说，我心里直～。", "example": null}]','chinese-xinhua','0'),
('2101143295953473580','滴','1','dī','氵','14',NULL,'[{"def": "滴", "example": null}, {"def": "(形声。从水,啇声。本义液体一点一点落下来。成语滴水成冰) 同本义", "example": null}, {"def": "滴,水注也。--《说文》", "example": null}, {"def": "若何滴滴。--《列子·力命》", "example": null}, {"def": "临岐别数子,握手泪再滴。--唐·杜甫《发同谷县》", "example": null}, {"def": "又如滴沥(水下滴);滴溜(涓滴的水);滴水(滴下来的水);滴溜当啷(不断下滴的样子)", "example": null}, {"def": "滴", "example": null}, {"def": "水点;点点下落的液体", "example": null}, {"def": "滴", "example": null}, {"def": "形容雨水下落和钟摆等的声音", "example": null}, {"def": "滴 dī", "example": null}, {"def": "①液体一点一点地向下落～眼药。", "example": null}, {"def": "②一点一点地向下落的液体雨～。", "example": null}, {"def": "③量词。", "example": null}, {"def": "②用于滴下的液体的数量一～血。", "example": null}, {"def": "【滴定管】化学分析用的仪器。为一细长而内径均匀的玻璃管，管壁上有刻度，下端附有活塞或带玻璃珠的橡皮管，前者为酸式滴定管，后者为碱式滴定管。此外还有自动滴定", "example": null}, {"def": "管等。", "example": null}, {"def": "【滴水穿石】见【水滴石穿】。", "example": null}]','chinese-xinhua','0'),
('2101143295953473581','氐','1','dī','氏','5',NULL,'[{"def": "氐", "example": null}, {"def": "低,低下◇作低”。头向下垂", "example": null}, {"def": "封君皆氐首仰给焉。--《汉书·食货志下》。师古曰氐首,犹俯首也。”", "example": null}, {"def": "氐", "example": null}, {"def": "低;低廉", "example": null}, {"def": "氐", "example": null}, {"def": "中国古代的一个少数民族", "example": null}, {"def": "自彼氐羌。--《诗·商颂·殷武》", "example": null}, {"def": "星名", "example": null}, {"def": "氐", "example": null}, {"def": "根本", "example": null}, {"def": "尹氏大师,维周之氐。--《诗·小雅·节南山》", "example": null}, {"def": "氐,本也。--《说文》。按,柢之", "example": null}, {"def": "氐 dī", "example": null}, {"def": "①我国古代西部的少数民族。", "example": null}, {"def": "②二十八宿之一。又见dǐ。", "example": null}, {"def": "【氐人】中国古族名。原在中国北部和西部的广大地区游牧。从东汉起陆续内迁，主要居住在今陕西、甘肃、四川等广大地区。从事畜牧、农业。魏晋时大量接受汉族文化和生", "example": null}, {"def": "产技术。历史上曾建立过仇池、前秦、后凉等国。", "example": null}, {"def": "氐 dǐ根本。又见dī。", "example": null}]','chinese-xinhua','0'),
