('2101143295953473586','坫','1','diàn','土','8',NULL,'[{"def": "坫", "example": null}, {"def": "(形声。从土,占声。本义古代设于堂中供祭祀、宴会时放礼器和酒具的土台)", "example": null}, {"def": "同本义", "example": null}, {"def": "受虚爵复于坫。--《新唐书》", "example": null}, {"def": "坛坫。特指文坛", "example": null}, {"def": "弱冠后,雄长坛坫。--《清史稿》", "example": null}, {"def": "屏障", "example": null}, {"def": "坫diàn", "example": null}, {"def": "①古代筑在廊庙内两柱中间的土台。反坫。反爵之坫。诸侯相会，宴饮礼毕，将空酒杯放回坫上。", "example": null}, {"def": "②古代筑在廊庙内两柱中间的土台。崇坫。用以置放来会诸侯所赠送的玉圭等物。", "example": null}, {"def": "③古代筑在室内的土台。靠近厨房，放食物的坫。", "example": null}, {"def": "④古代筑在室内的土台。屋角的坫，爲士举行冠礼﹑丧礼仪式的地方。", "example": null}, {"def": "⑤泛指台。", "example": null}, {"def": "⑥屏障。", "example": null}, {"def": "坫 zhēn人死入棺后浅埋或停柩以待葬。", "example": null}]','chinese-xinhua','0'),
('2101143295953473587','店','1','diàn','广','8',NULL,'[{"def": "店", "example": null}, {"def": "(形声。从广,占声。从广”,表示与房屋有关。本义栈房)", "example": null}, {"def": "同本义", "example": null}, {"def": "肆,所以陈货鬻之物也;店,所以置货鬻之物也。--晋·崔豹《古今注》", "example": null}, {"def": "旅舍;客店", "example": null}, {"def": "付的费用)", "example": null}, {"def": "商店;铺子", "example": null}, {"def": "都邑集镇名", "example": null}, {"def": "店东", "example": null}, {"def": "店 diàn", "example": null}, {"def": "①商店；铺子书～、副食～。", "example": null}, {"def": "②旅馆；客店住～。", "example": null}, {"def": "【店铺】商店。", "example": null}]','chinese-xinhua','0'),
('2101143295953473588','垫','1','diàn','土','9',NULL,'[{"def": "垫", "example": null}, {"def": "(形声。从土,执声。本义下陷,淹没)", "example": null}, {"def": "同本义", "example": null}, {"def": "垫,下也。--《说文》", "example": null}, {"def": "垫,下也。凡屋而下曰垫。--《方言六》", "example": null}, {"def": "洪水滔天,浩浩怀山襄陵,下民昏垫。--《书·益稷》。郑注垫,陷也。”疏垫是下湿之名。”", "example": null}, {"def": "武功中水乡民三舍垫为池。--《汉书·王莽传下》", "example": null}, {"def": "则厕足而垫之。--《庄子·外物》", "example": null}, {"def": "又如垫没(下沉);垫溺(陷溺);垫裂(塌陷破裂);垫陷(下陷。亦指陷入困境)", "example": null}, {"def": "用别的东西衬在下面,使物加高、加厚或起隔离作用", "example": null}, {"def": "垫 diàn", "example": null}, {"def": "①在主体物件上面或底下铺放一些东西，使加高、加厚或平整～桌子、～上褥子、把路～平。", "example": null}, {"def": "②专供铺放的东西鞋～、座～。", "example": null}, {"def": "③替人暂付款项～钱。", "example": null}, {"def": "【垫脚石】比喻借用来向上爬的人或事物。", "example": null}, {"def": "【垫球】排球运动基本技术之一。两臂自然伸直相靠，两手相并，虎口向上，伸出垫击球。控制面积大，起球效果好。", "example": null}, {"def": "【垫圈】垫在螺母与被连接件之间的零件。", "example": null}, {"def": "【垫支资本】见【预付总资本】。", "example": null}, {"def": "垫dié 1.垫江，古县名。在今四川省合川县。 2.垫江，今县名。在四川省东部。", "example": null}]','chinese-xinhua','0'),
