('2101143295953473590','玷','1','diàn','王','9',NULL,'[{"def": "玷", "example": null}, {"def": "(形声。本义白玉上的斑点)", "example": null}, {"def": "同本义", "example": null}, {"def": "玷,玉瑕。--《广韵》", "example": null}, {"def": "白圭之玷,尚可磨也。--《诗·大雅·抑》。传玷,缺也。”", "example": null}, {"def": "不知其玷。--《诗·大雅·召昮》", "example": null}, {"def": "元成复作自荐复玷缺之艰难。--《汉书·韦元成传》。注玉缺曰玷。”", "example": null}, {"def": "又如玷缺(白玉有斑点、缺损。比喻人的品德有缺点);玷翳(玉上斑痕)", "example": null}, {"def": "引申为过失;缺点", "example": null}, {"def": "污点", "example": null}, {"def": "玷", "example": null}, {"def": "玷污,污辱", "example": null}, {"def": "玷 diàn", "example": null}, {"def": "①白玉上面的斑点。", "example": null}, {"def": "②使有污点～污。", "example": null}, {"def": "【玷辱】使蒙受耻辱。", "example": null}, {"def": "【玷污】污损（多指人的名声）。", "example": null}, {"def": "玷diān 1.以手称物。参见\\"玷捶\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295953473591','钿','1','diàn','钅','10',NULL,'[{"def": "钿", "example": null}, {"def": "(形声。从金,田声。本义金花,用金嵌成花状的美饰) 同本义", "example": null}, {"def": "钿", "example": null}, {"def": "以金银珠宝介壳镶嵌器物", "example": null}, {"def": "衬垫", "example": null}, {"def": "莲花衔青雀,宝粟钿金虫。--吴均诗", "example": null}, {"def": "钿头", "example": null}, {"def": "钿头银篦击节碎。--唐·白居", "example": null}, {"def": "钿 diàn", "example": null}, {"def": "①用金翠珠宝等制成的花朵形的首饰。", "example": null}, {"def": "②把金银贝壳之类镶嵌在器物上。", "example": null}, {"def": "钿tián", "example": null}, {"def": "⒈〈方〉钱，硬币铜～。银～。", "example": null}]','chinese-xinhua','0'),
