('2101143295953473614','踮','1','diǎn','足','15',NULL,'[{"def": "踮〈动〉", "example": null}, {"def": "提起脚跟,用脚尖着地", "example": null}, {"def": "踮 diǎn提起脚跟，用脚尖着地。", "example": null}]','chinese-xinhua','0'),
('2101143295953473615','典','1','diǎn','八','8',NULL,'[{"def": "典", "example": null}, {"def": "(会意。甲骨文字形,上面是册”字,下面是大。本义重要的文献、典籍)", "example": null}, {"def": "同本义", "example": null}, {"def": "典,五帝之书也…庄都说,典,大册也。--《说文》。按,谓从册,从大,古文从古文册。", "example": null}, {"def": "典,经也。--《尔雅·释言》", "example": null}, {"def": "不可为典要。--《易·系辞》", "example": null}, {"def": "是能读三坟、五典、八索、九丘。--《左传·昭公十二年》", "example": null}, {"def": "司晋之典籍。--《左传·昭公十五年》", "example": null}, {"def": "不远而复,先典攸高(重贵)。--丘迟《与陈伯之书》", "example": null}, {"def": "自书典所记,未之有也。--《后汉书·张衡传》", "example": null}, {"def": "又如药典;字典;释典(佛经);法典;佛典;引经据典;典志(记载政", "example": null}, {"def": "典 diǎn", "example": null}, {"def": "①标准；法则～范、～型。", "example": null}, {"def": "②典范性的书籍～籍、词～。", "example": null}, {"def": "③郑重的仪式～礼。", "example": null}, {"def": "④诗文中引用的古书里的故事或词句～故、用～。", "example": null}, {"def": "⑤抵押（旧时一方将土地或房屋押给另一方，换取一定款项，不计利息，议定还款期限，到时赎回）。", "example": null}, {"def": "⑥姓。", "example": null}, {"def": "【典范】可以作为学习榜样的人物或事件。", "example": null}, {"def": "【典故】诗文中引用的古书里的故事或词句。", "example": null}, {"def": "【典籍】记载古代法制的图书。也泛指可以作为标准、典范的书籍。", "example": null}, {"def": "【典礼】隆重举行的仪式。", "example": null}, {"def": "【典型】", "example": null}, {"def": "①具有代表性的人物或事件。", "example": null}, {"def": "②具有代表性的他的看法很～，值得重视。", "example": null}, {"def": "③文学艺术作品中用艺术概括手法表现人的社会特征的艺术形象。它既表现了人的一定的社会特征，同时又具有鲜明的个性特征。", "example": null}, {"def": "【典型化】指概括现实生活、创造典型形象的艺术方法。作家、艺术家在创作时，根据自己对生活的深刻观察和独特理解，把日常现象集中起来，进行深入的开掘和精细的提炼", "example": null}, {"def": "，创造出既具有鲜明个性特征又能反映某一特定时代的社会本质的艺术形象。", "example": null}, {"def": "【典型环境】文艺作品中典型人物所生活的、决定人物性格的形成和发展、促使人物行动的特定环境。它能概括地反映出一定历史时代的社会生活及其发展趋势。", "example": null}, {"def": "【典型性】指作家、艺术家塑造艺术形象所达到的概括化和个性化统一的程度。艺术形象的个性特征越鲜明、生动，而所揭示的社会本质越深刻，即个性与共性越统一，典型性", "example": null}, {"def": "就越高。也指一般讲话、论著对事物所作的既有高度概括力、又有鲜明个性特征的评述。", "example": null}, {"def": "【典雅】文章内容有根基，文词优美不粗俗。", "example": null}, {"def": "【典章】法令制度。", "example": null}, {"def": "典tiǎn 1.见\\"颀典\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295953473616','点','1','diǎn','灬','9',NULL,'[{"def": "点", "example": null}, {"def": "(形声。从黑,占声。本义斑点)", "example": null}, {"def": "细小的黑色斑痕", "example": null}, {"def": "点,黑也。--《说文》。按,小黑曰点。", "example": null}, {"def": "又如墨点儿;斑点;污点;点缺(瑕疵,缺点);点漆(形容极黑)", "example": null}, {"def": "小滴", "example": null}, {"def": "七八个星天外,两三点雨山前。--宋·辛弃疾《西江月》", "example": null}, {"def": "又如雨点;掉点儿(落下稀疏的雨点);点叶(叶上的斑点);点璧(白璧的斑点)", "example": null}, {"def": "汉字笔画名", "example": null}, {"def": "数学名词。数学上表示小数的符号叫小数点,省称为点”。", "example": null}, {"def": "几何系统,尤指欧几里", "example": null}]','chinese-xinhua','0'),
