('2101143295957667869','谍','1','dié','讠','11',NULL,'[{"def": "谍", "example": null}, {"def": "(形声。从言,枼声。本义间谍,细作)", "example": null}, {"def": "间谍", "example": null}, {"def": "谍,军中反间也。--《说文》", "example": null}, {"def": "掌斩杀贼谍而搏之。--《周礼·掌戮》", "example": null}, {"def": "搏贼谍。--《周礼·环人》。注反间为国贼。”", "example": null}, {"def": "晋人获秦谍。--《左传·宣公八年》", "example": null}, {"def": "谍报敌情至。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如防谍;谍贼(暗探和叛国贼);谍人(间谍)", "example": null}, {"def": "传递的情报", "example": null}, {"def": "宁边军数日间连受八十余谍。--《续资治通鉴》", "example": null}, {"def": "通牒”。书札", "example": null}, {"def": "太史公读春秋历谱谍。--《史记·十二诸侯年表序》", "example": null}, {"def": "又", "example": null}, {"def": "宫童效异,披图案谍。--《汉书·礼乐志》", "example": null}, {"def": "故", "example": null}, {"def": "谍 dié", "example": null}, {"def": "①秘密刺探军事、政治及经济方面的情报～报。", "example": null}, {"def": "②进行谍报活动的人间～。", "example": null}, {"def": "【谍报】", "example": null}, {"def": "①刺探到的情报。", "example": null}, {"def": "②将刺探到的情报交给上级或有关方面。", "example": null}]','chinese-xinhua','0'),
('2101143295957667870','喋','1','dié','口','12',NULL,'[{"def": "喋  die", "example": null}, {"def": "(形声。从口,葉声。本义喋喋形容说话多)", "example": null}, {"def": "同本义。常叠用", "example": null}, {"def": "喋,便语也。--《玉篇》", "example": null}, {"def": "岂效此啬夫喋喋利口捷口哉?--《汉书·张释之传》", "example": null}, {"def": "又如喋聒(多言扰耳;噜嗦)", "example": null}, {"def": "通蹀”。踏,蹈", "example": null}, {"def": "然已席卷千里,南面称孤,喋血乘胜日有闻矣。--《史记·魏豹彭越列传》。", "example": null}, {"def": "今已诛诸吕,新喋血京师。--《汉书·文帝纪》。颜师古注本字当作蹀。蹀,谓履涉之耳。", "example": null}, {"def": "又如喋盟(歃血盟誓)", "example": null}, {"def": "喋  zha", "example": null}, {"def": "口开合,吮吸", "example": null}, {"def": "喋 dié又见zhá。", "example": null}, {"def": "【喋喋不休】说话没完没了。喋喋形容话多。", "example": null}, {"def": "【喋血】流血满地。指杀人很多。又作蹀血。", "example": null}, {"def": "喋 dīé", "example": null}, {"def": "①喋喋，说话烦琐,没完没了～～不休.", "example": null}, {"def": "②流血满地～血.", "example": null}, {"def": "喋 zhá", "example": null}, {"def": "⒈", "example": null}]','chinese-xinhua','0'),
