('2101143295957667892','爹','1','diē','父','10',NULL,'[{"def": "爹", "example": null}, {"def": "(形声。从父,多声。本义父亲)", "example": null}, {"def": "对老者、长者的尊称", "example": null}, {"def": "女(徐七娘)臭项", "example": null}, {"def": "阿爹!妈等你吃中饭呢!--茅盾《春蚕》", "example": null}, {"def": "旧时对官长的尊称或作官长的代称", "example": null}, {"def": "比及爹有这个心,小人打听在肚里了。--关汉卿《鲁斋郎》", "example": null}, {"def": "爹爹", "example": null}, {"def": "爹妈", "example": null}, {"def": "爹diē", "example": null}, {"def": "①对父亲的称呼。有些方言也以称祖父。", "example": null}, {"def": "②对老年人的尊称。如阿爹。", "example": null}, {"def": "爹diē", "example": null}, {"def": "①父亲。", "example": null}, {"def": "②对老年男子的尊称。", "example": null}, {"def": "③僮仆对主人的尊称。", "example": null}]','chinese-xinhua','0'),
('2101143295957667893','跌','1','diē','足','12',NULL,'[{"def": "跌", "example": null}, {"def": "(形声。从足,失声。本义失足摔倒)", "example": null}, {"def": "同本义", "example": null}, {"def": "失蹑曰跌。--《通俗文》", "example": null}, {"def": "跌而不振。--《汉书·晁错传》。注足失据也。”", "example": null}, {"def": "若跌而据。--《淮南子·缪称》", "example": null}, {"def": "又如他跌伤了;跌磕(挫折,栽筋斗);跌翻(跌倒,摔倒);跌跌滚滚(跌交打滚的样子);跌跌爬爬(连跌带爬);跌坐(身体迅速坐下)", "example": null}, {"def": "失足。喻指犯过失", "example": null}, {"def": "一跌将赤吾之族。--《汉书·扬雄传》", "example": null}, {"def": "又如跌磕(受到挫折);跌磕蹭蹬(倒霉;不顺利);跌失(闪失);跌蹼(喻指挫折和灾难)", "example": null}, {"def": "落,降低", "example": null}, {"def": "快走", "example": null}, {"def": "跌 diē", "example": null}, {"def": "①摔倒～了一跤。", "example": null}, {"def": "②下降；下落～价、水位下～。", "example": null}, {"def": "【跌宕】", "example": null}, {"def": "【跌荡】", "example": null}, {"def": "①性格洒脱，毫不拘束。", "example": null}, {"def": "②音调抑扬顿挫或文章富于变化。", "example": null}, {"def": "【跌落】", "example": null}, {"def": "①（物体）下落。", "example": null}, {"def": "②（价格、产量等）下降。", "example": null}, {"def": "【跌足】跺脚。", "example": null}]','chinese-xinhua','0'),
