('2101143295957667895','钉','1','dìnɡ','钅','7',NULL,'[{"def": "钉", "example": null}, {"def": "(形声。从金,丁声。本义鍊饼黄金)", "example": null}, {"def": "钉子", "example": null}, {"def": "假借为丁,今俗用为铁钉字。--《说文通训定声》", "example": null}, {"def": "又如钉铰(一种金属零件。凡刀柄鞍首等皆有此);钉靴(鞋底钉钉,雨天可以防滑的鞋)", "example": null}, {"def": "通常是圆锥形,有尖头或尖顶的木料、金属或其他材料做的钉状物", "example": null}, {"def": "刺", "example": null}, {"def": "钉", "example": null}, {"def": "紧跟不放,监视", "example": null}, {"def": "催促;监督;紧迫", "example": null}, {"def": "小珍儿还是尽钉着问,这叫什么,那叫什么。--张天翼《宝葫芦的秘密》", "example": null}, {"def": "钉", "example": null}, {"def": "用钉", "example": null}, {"def": "钉 dīng", "example": null}, {"def": "①竹、木、金属等制成的细棍形物件。一端有扁平的头，另一端尖锐，主要起固定或连接作用，也可以用来悬挂物品。", "example": null}, {"def": "②紧跟着不放松～住对方。", "example": null}, {"def": "③督促；催问经常～着点。", "example": null}, {"def": "④同\'盯\'。又见dìng。", "example": null}, {"def": "【钉螺】软体动物。螺壳厚，高10毫米左右，螺层7个左右，雌雄异体。生活在杂草丛生的河湖、沟渠、池塘。水陆两栖。是日本血吸虫的中间宿主。", "example": null}, {"def": "【钉梢】暗中紧跟在别人身后以监视别人的行动。又作盯梢。", "example": null}, {"def": "【钉是钉， 铆是铆】见【丁是丁，卯是卯】。", "example": null}, {"def": "钉 dìng", "example": null}, {"def": "①把钉子捶入～皮鞋。", "example": null}, {"def": "②用针线缝住～衣扣。又见dīng。", "example": null}]','chinese-xinhua','0'),
('2101143295957667896','订','1','dìnɡ','讠','4',NULL,'[{"def": "订", "example": null}, {"def": "(形声。从言,丁声。本义评议)", "example": null}, {"def": "同本义", "example": null}, {"def": "订,平议也。--《说文》。按,字亦作评。", "example": null}, {"def": "订太平文王之道。--《诗·天作》笺", "example": null}, {"def": "两论相订,是非乃见。--《论衡·案书》", "example": null}, {"def": "又如订铨(评议衡量);《订鬼篇》", "example": null}, {"def": "改正,修正", "example": null}, {"def": "下足以订史氏之失者。--李清照《金石录后序》", "example": null}, {"def": "亦足有所订正。--《晋书·荀崧传》", "example": null}, {"def": "又如订顽(改正愚顽);修订", "example": null}, {"def": "达成协议订立;使生效", "example": null}, {"def": "预先约定", "example": null}, {"def": "把零散的纸张、书页加工成本", "example": null}, {"def": "订 dìng", "example": null}, {"def": "①经研究商讨而立下（条约、契约、计划、章程等）。", "example": null}, {"def": "②约定～报。", "example": null}, {"def": "③修改；改正～正、校～。", "example": null}, {"def": "④用线、铁丝等把书页等连在一起装～。", "example": null}, {"def": "【订正】修正（文字中的错误）。", "example": null}]','chinese-xinhua','0'),
('2101143295957667897','饤','1','dìnɡ','','7',NULL,'[{"def": "饤dìng 1.贮食;堆放食品于器。一般供陈设。 2.引申为准备﹑安排食品。 3.量词。", "example": null}]','chinese-xinhua','0'),
('2101143295957667898','定','1','dìnɡ','宀','8',NULL,'[{"def": "定", "example": null}, {"def": "(会意。从宀,从正。正”亦兼表字音。本义安定;安稳)", "example": null}, {"def": "同本义,与乱”或动”相对", "example": null}, {"def": "定,安也。--《说文》", "example": null}, {"def": "靡所定处。--《诗·大雅·桑柔》", "example": null}, {"def": "岂敢定居,一月三捷。--《诗·小雅·采薇》", "example": null}, {"def": "昏定而晨省。--《礼记·曲礼》", "example": null}, {"def": "以待阴阳之所定。--《礼记·月令》", "example": null}, {"def": "天下属安定,何故反乎?--《史记·留侯世家》", "example": null}, {"def": "痛定思痛,痛何如哉!--宋·文天祥《指南录·后序》", "example": null}, {"def": "如其克谐,天下可定也。--《资治通鉴》", "example": null}, {"def": "又如定迭(定叠。安定,太平);定害(定搅,定虐。扰乱,扰害);定帖(稳定;安定);定昏(请晚安)", "example": null}, {"def": "镇", "example": null}]','chinese-xinhua','0'),
('2101143295957667899','啶','1','dìnɡ','口','11',NULL,'[{"def": "啶--译音用字。如吡啶”", "example": null}, {"def": "啶dìng ［语］嘧～。〈名〉有机化合物，无色液体，有臭味。", "example": null}]','chinese-xinhua','0'),
