('2101143295957667940','动','1','dònɡ','力','6',NULL,'[{"def": "动", "example": null}, {"def": "(形声。从力,重声。《说文》古文从辵”。本义行动;发作)", "example": null}, {"def": "同本义", "example": null}, {"def": "动,作也。--《说文》", "example": null}, {"def": "动而健。--《易·彖传》。虞注震也。”", "example": null}, {"def": "效天下之动者也。--《易·系辞》。虞注发也,变动不居。”", "example": null}, {"def": "将终岁勤动。--《孟子》。注作也。”", "example": null}, {"def": "度义而后动。--宋·王安石《答司马谏议书》", "example": null}, {"def": "寨中人蜷伏不少动。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如按兵不动;动着(开始下棋);动止(行动和静止;训练调度);动烦(爆发战乱);动转(行动,活动)", "example": null}, {"def": "摇动,震动,移动。与静”相对", "example": null}, {"def": "风移影动。╠", "example": null}]','chinese-xinhua','0'),
('2101143295957667941','冻','1','dònɡ','冫','7',NULL,'[{"def": "冻", "example": null}, {"def": "(形声。从仌,东声。本义结冰)", "example": null}, {"def": "同本义", "example": null}, {"def": "冻,仌也。--《说文》", "example": null}, {"def": "壮冰曰冻。--《风俗通》", "example": null}, {"def": "水始冰,地始冻。--《礼记·月令》", "example": null}, {"def": "风掣红旗冻不翻。--唐·岑参《白雪歌送武判官归京》", "example": null}, {"def": "又如冻柱(冻住);冻浦(结了冰的河川)", "example": null}, {"def": "受冻;感到寒冷", "example": null}, {"def": "夜冻寒。--《管子·五辅》", "example": null}, {"def": "人马冻死者相望。--《资治通鉴·唐纪》", "example": null}, {"def": "又如冻草(使草受冻);冻树(寒霜凝结在树木上);冻笔(因寒冷而冻结的毛笔)", "example": null}, {"def": "冻", "example": null}, {"def": "厚冰", "example": null}, {"def": "冰解而冻释。--《管子·五行》", "example": null}, {"def": "又如冻合(冰封);冻冻(冰);冻轮(冰轮);冻雪(冰雪)", "example": null}, {"def": "汁液或其他含", "example": null}, {"def": "冻 dòng", "example": null}, {"def": "①（液体或含水分的东西）遇冷凝结～肉。", "example": null}, {"def": "②汤汁类凝结成半固体肉～。", "example": null}, {"def": "③感到寒冷或受到寒冷脚～了。", "example": null}, {"def": "【冻土】指温度在0℃以下，因冻结而含冰的各种土石层。按保持时间可分为暂时性冻土、多年冻土和季节性冻土。多年冻土在地球上的分布约占陆地面积的1/4，主要分布在苏", "example": null}, {"def": "联和加拿大。", "example": null}, {"def": "冻dōng 1.见\\"冻雨\\"﹑\\"冻冻\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295957667942','侗','1','dònɡ','亻','8',NULL,'[{"def": "侗", "example": null}, {"def": "侗族。中国少数民族名", "example": null}, {"def": "侗", "example": null}, {"def": "诚实忠厚", "example": null}, {"def": "侗〈形〉 tong", "example": null}, {"def": "幼稚无知", "example": null}, {"def": "狂而不直,侗而不愿。--《论语·泰伯》", "example": null}, {"def": "又如倥侗(蒙昧无知)", "example": null}, {"def": "样子轻佻", "example": null}, {"def": "毋侗好轶。--《史记》", "example": null}, {"def": "侗〈名〉", "example": null}, {"def": "通僮”。幼童,未成年的男性", "example": null}, {"def": "侗,未成器之人。--《集韵》", "example": null}, {"def": "在后之侗,敬迓天威。--《书·顾命》", "example": null}, {"def": "侗 dòng侗族。又见tóng；tǒng。", "example": null}, {"def": "【侗族】中国少数民族。分布于贵州、湖南、广西。2514014人（1990）。说侗语，属壮侗语族。侗族源于古越人。从事农业经济。其鼓楼、风雨楼建筑工艺精湛。盛行崇拜圣", "example": null}, {"def": "母\'萨\'。", "example": null}, {"def": "侗tǒng", "example": null}, {"def": "侗tóng", "example": null}, {"def": "⒈童蒙无知。", "example": null}, {"def": "⒉儿童。", "example": null}]','chinese-xinhua','0'),
