('2101143295961862153','逗','1','dòu','辶','10',NULL,'[{"def": "逗", "example": null}, {"def": "(形声。从辵,豆声。本义止住,停留)", "example": null}, {"def": "同本义", "example": null}, {"def": "逗,止也。--《说文》", "example": null}, {"def": "廷尉奏恢逗桡。当斩。--《汉书·韩安国传》", "example": null}, {"def": "逗留不进。--《汉书·匈奴传》", "example": null}, {"def": "逗华阴之湍渚。--《思元赋》", "example": null}, {"def": "又如逗延(逗留;停留);逗宿(留宿);", "example": null}, {"def": "赶,趁", "example": null}, {"def": "临,到", "example": null}, {"def": "透入", "example": null}, {"def": "撩拨;调戏", "example": null}, {"def": "招引", "example": null}, {"def": "透露;显露", "example": null}, {"def": "逗 dòu", "example": null}, {"def": "①哄孩子玩。", "example": null}, {"def": "②和人闹着玩～引。", "example": null}, {"def": "③招人（喜欢）。", "example": null}, {"def": "④停留", "example": null}, {"def": "②留。", "example": null}, {"def": "⑤同\'读\'（dòu），语气中的停顿。", "example": null}, {"def": "【逗号】标点符号的一种，即\'，\'，表示一句话中间的停顿。", "example": null}, {"def": "【逗留】", "example": null}, {"def": "【逗遛】暂时停留。", "example": null}, {"def": "【逗引】用言语、行动哄引对方，借以取乐。", "example": null}]','chinese-xinhua','0'),
