('2101143295961862162','抖','1','dǒu','扌','7',NULL,'[{"def": "抖", "example": null}, {"def": "(形声。从手,斗声。本义抖擞)", "example": null}, {"def": "振动;甩动", "example": null}, {"def": "颤动,哆嗦", "example": null}, {"def": "把隐讳的事情揭露出来", "example": null}, {"def": "振作", "example": null}, {"def": "抖起精神", "example": null}, {"def": "讽刺人突然得势或生活水平突然提高", "example": null}, {"def": "讽刺或骂人耍威风", "example": null}, {"def": "抖 dǒu", "example": null}, {"def": "①使振动～～雨衣。", "example": null}, {"def": "②哆嗦全身发～。", "example": null}, {"def": "③振作；鼓起～起精神。", "example": null}, {"def": "④全部倒出；彻底揭穿（别人的缺点或毛病）。", "example": null}, {"def": "⑤讽刺别人突然得势或致富他现在可～了。", "example": null}, {"def": "【抖擞】振作精神～。", "example": null}]','chinese-xinhua','0'),
('2101143295961862163','陡','1','dǒu','阝','9',NULL,'[{"def": "陡", "example": null}, {"def": "(形声。从阜,走声。从阜”,表示与地形地势的高低上下有关。本义山势陡峭) 同本义", "example": null}, {"def": "陡,峻立也。--《集韵》", "example": null}, {"def": "塞者凿之,陡者级之。--《徐霞客游记·游黄山记》", "example": null}, {"def": "又如陡山;山陡路险;陡直(山势峻峭壁立);陡崖(陡峭的山崖)", "example": null}, {"def": "陡", "example": null}, {"def": "顿时;突然", "example": null}, {"def": "程度深,范围广", "example": null}, {"def": "曾经消瘦,每遍犹闲,这番最陡。--元·王实甫《西厢记》", "example": null}, {"def": "陡", "example": null}, {"def": "哆嗦。也作抖”", "example": null}, {"def": "陡 dǒu坡度很大，近于垂直山路又～又窄。②突然脸色～变。", "example": null}, {"def": "【陡峻】（地势）高而陡。", "example": null}, {"def": "【陡峭】（山势等）坡度很大，直上直下。", "example": null}, {"def": "【陡然】突然天～下起雨。", "example": null}]','chinese-xinhua','0'),
