('2101143295961862182','读','1','dú','讠','10',NULL,'[{"def": "读", "example": null}, {"def": "(形声。从言,卖声。本义读书)", "example": null}, {"def": "籀书,抽释理解书的意义", "example": null}, {"def": "读,诵书也。--《说文》", "example": null}, {"def": "主人习其读而问其传。--《公羊传·定公元年》", "example": null}, {"def": "读其书。--《孟子》", "example": null}, {"def": "相随观读,讽述以谈。--《论衡·谈天》", "example": null}, {"def": "又如读法(诵读法令);读祝(祭祀时宣读祈祷文);读鞫(审判时,宣读起诉理由)", "example": null}, {"def": "阅读", "example": null}, {"def": "好读书,不求甚解。--晋·陶潜《五柳先生传》", "example": null}, {"def": "则其读书也必专,而其归书也必速。--清·袁枚《黄生借书说》", "example": null}, {"def": "楚人贫居,读《淮南方》。--邯郸淳《笑林》", "example": null}, {"def": "又如读报;默读(不出声地读书);朗读;读律(学习法律);读画(用心鉴赏绘画的意境,", "example": null}, {"def": "读 dòu语句中的停顿。古代诵读文章时，完整的长句或小段的停顿称为\'句\'，\'句\'中的小停顿称为\'读\'。又见dú。", "example": null}, {"def": "读 dú", "example": null}, {"def": "①照着文字念。", "example": null}, {"def": "②阅读；看书或文章。", "example": null}, {"def": "②上学～大学。又见dòu。", "example": null}, {"def": "【读后感】一种文体。读书看报之后，把心得、感受、看法等写成文章或笔记。", "example": null}, {"def": "【读卖新闻】日本最有影响的报纸之一。1874年创刊。面向大众，注重社会新闻和体育新闻。每天早刊24版，晚刊12版。", "example": null}, {"def": "【读秒】", "example": null}, {"def": "①围棋、象棋等体育比赛规则。对局者自由支配时间已用到事先规定的保留时限后始由裁判员报时。", "example": null}, {"def": "②比喻非常紧张繁忙的状态或阶段亚运工程已进入～阶段。", "example": null}, {"def": "【读破】同一个字形因意思不同而有两个或几个读音时，不照习惯上最通常的读音来读。如\'称职\'的\'称\'不读chēng,而读chèn，\'禁不住\'的\'禁\'不读jìn,而读jīn。", "example": null}, {"def": "【读数据语句】〈计〉basic语言语句之一。它向运行中的程序的某些变量提供数据。date语句设置数据表，由read语句提取数据，每提取一个数据时，指向下一个将要提取的", "example": null}, {"def": "数据位置。", "example": null}, {"def": "【读友】〈港台〉读者。", "example": null}]','chinese-xinhua','0'),
('2101143295961862183','渎','1','dú','氵','11',NULL,'[{"def": "渎", "example": null}, {"def": "(形声。从水,卖声。本义水沟,水渠)", "example": null}, {"def": "同本义。又特指邑中的沟", "example": null}, {"def": "渎,沟也。一曰邑中沟。--《说文》", "example": null}, {"def": "坎为沟渎。--《易·读卦》", "example": null}, {"def": "开其渎。--《荀子·脩身》", "example": null}, {"def": "彼寻常之?渎兮。--《史记·屈原贾生列传》。索隐小渠也。”", "example": null}, {"def": "掌沟渎浍池之禁。--《周礼·雍氏》", "example": null}, {"def": "有决渎于殷周之世者,必为汤武笑矣。--《韩非子·五蠹》", "example": null}, {"def": "又如渎田(开沟渠而溉田)", "example": null}, {"def": "大川", "example": null}, {"def": "江淮河济为四渎。--《尔雅》", "example": null}, {"def": "再三渎。--《易·蒙》", "example": null}, {"def": "又如四渎(长江、黄河、淮水、济水)", "example": null}, {"def": "渎", "example": null}, {"def": "轻慢;不敬", "example": null}, {"def": "渎货无厌。╠", "example": null}, {"def": "渎 dú", "example": null}, {"def": "①水沟；小渠。", "example": null}, {"def": "②轻慢；对人不敬", "example": null}, {"def": "②职～、亵～。", "example": null}, {"def": "【渎职】工作不负责任，以致在执行任务时出现重大事故，犯了严重过失。", "example": null}, {"def": "【渎职罪】罪名类别。指国家工作人员利用职权或玩忽职守，侵害国家机关、企业、事业单位的正常管理活动，严重桅国家和人民利益的行为。如受贿、玩忽职守、徇私枉法", "example": null}, {"def": "等罪。", "example": null}, {"def": "渎dòu 1.洞穴。", "example": null}]','chinese-xinhua','0'),
('2101143295961862184','椟','1','dú','木','12',NULL,'[{"def": "椟", "example": null}, {"def": "(形声。从木,卖声。本义木柜,木匣)", "example": null}, {"def": "同本义", "example": null}, {"def": "龟玉毁于椟中。--《论语·季氏》", "example": null}, {"def": "又如椟玉(收藏在匣中的美玉);椟匮(匣柜);椟栌(汲水器具);椟丸(古代盛箭的器具)", "example": null}, {"def": "盛饭菜的食盒", "example": null}, {"def": "棺材", "example": null}, {"def": "椟 dú匣子；盒子买～还珠。", "example": null}]','chinese-xinhua','0'),
('2101143295961862185','牍','1','dú','片','12',NULL,'[{"def": "牍", "example": null}, {"def": "(形声。从片,卖声。片”,本指木头竖剖成的一半。古时用木片作书写材料。故从片”。本义古代写字用的木片,也称木简)", "example": null}, {"def": "同本义", "example": null}, {"def": "牍,书版也。长一尺,既书曰牍,未书曰椠。--《说文》", "example": null}, {"def": "与人尺牍。--《史记·陈遵传》", "example": null}, {"def": "削牍为疏。--《史记·游侠原涉传》。注木简也。”", "example": null}, {"def": "吏乃书牍背示之。--《史记·周勃传》", "example": null}, {"def": "握牍持笔。--杨修《答临淄侯笺》", "example": null}, {"def": "又如牍背(狱吏于书板背面书写文句◇用为遭受冤狱的典实)", "example": null}, {"def": "引申为公文", "example": null}, {"def": "无丝竹之乱耳,无案牍之", "example": null}, {"def": "牍 dú", "example": null}, {"def": "①古代书写用的木片。", "example": null}, {"def": "②文件；书信文～、尺～。", "example": null}]','chinese-xinhua','0'),
('2101143295961862186','犊','1','dú','牜','12',NULL,'[{"def": "犊", "example": null}, {"def": "(形声。从牛,卖声。小牛)", "example": null}, {"def": "同本义", "example": null}, {"def": "犊,牛子也。--《说文》", "example": null}, {"def": "诸侯膳以犊。--《礼记·礼器》", "example": null}, {"def": "用犊贵诚也。--《礼记·郊特牲》", "example": null}, {"def": "又如犊牛(犊子,犊儿。小牛);犊角茧(喻指年轻人);犊鼻(小牛鼻。又作犊鼻裨的简称;人体穴位名。在膝盖骨之下,胫骨之上。俗称,膝眼)", "example": null}, {"def": "泛指牛", "example": null}, {"def": "姓", "example": null}, {"def": "犊车", "example": null}, {"def": "乘犊车。--《资治通鉴》", "example": null}, {"def": "犊牧采薪", "example": null}, {"def": "犊子", "example": null}, {"def": "犊 dú牛犊；小牛。", "example": null}]','chinese-xinhua','0'),
