('2101143295961862201','妒','1','dù','女','7',NULL,'[{"def": "妒", "example": null}, {"def": "(形声。从女,户声。本义妇女忌妒丈夫。也指忌妒别的女子的姿色)", "example": null}, {"def": ")", "example": null}, {"def": "泛指忌妒别人", "example": null}, {"def": "妆成每被秋娘妒。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如妒害(妒忌陷害);妒纷(因互相妒忌而引起的争执、纠纷);妒痴(过度的妒忌而引发的痴病);妒刻(嫉妒刻薄);妒富愧贫(忌妒别人富裕,羞愧自己贫穷);妒敌(相忌恨的敌手)", "example": null}, {"def": "妒 dù因别人好而忌恨。", "example": null}, {"def": "【妒忌】同\'忌妒\'。对品德、才能、名誉、地位或境遇比自己好的人心怀怨恨。", "example": null}, {"def": "【妒贤嫉能】嫉妒品行好、有才能的人。", "example": null}]','chinese-xinhua','0'),
('2101143295961862202','杜','1','dù','木','7',NULL,'[{"def": "杜", "example": null}, {"def": "(形声。从木,土声。本义杜梨,棠梨,一种木本植物)", "example": null}, {"def": "同本义", "example": null}, {"def": "杜,甘棠也。--《说文》。按牡曰棠,牝曰杜。”", "example": null}, {"def": "杜树大者插五枝。--《齐民要术》", "example": null}, {"def": "姓", "example": null}, {"def": "杜", "example": null}, {"def": "堵塞", "example": null}, {"def": "杜,塞也。--《小尔雅·广诂》", "example": null}, {"def": "犯令陵政则杜之。--《周礼·大司马》。注杜塞使不得与邻国交通。”", "example": null}, {"def": "又如杜耳恶闻(塞住耳朵不愿听);杜隔(阻塞隔离);杜闭(堵塞,关闭);杜禁(堵塞)", "example": null}, {"def": "关门,封闭", "example": null}, {"def": "杜乃护王。--《书·费誓》。注闭也。”", "example": null}, {"def": "犯令陵政则杜之。--《周礼·夏官·大司马》", "example": null}, {"def": "强公室,杜私门。--《史记·李斯列", "example": null}]','chinese-xinhua','0'),
('2101143295961862203','肚','1','dù','月','7',NULL,'[{"def": "肚", "example": null}, {"def": "(形声。从肉,土声。本义人或动物的腹部)", "example": null}, {"def": "同本义", "example": null}, {"def": "物体突起或中间鼓出的部分", "example": null}, {"def": "指思维器官", "example": null}, {"def": "肚 dǔ胃。特指用做食物的猪羊等的胃猪～。又见dù。", "example": null}, {"def": "肚 dù腹部。又见dǔ。", "example": null}, {"def": "【肚量】见【度量】。", "example": null}]','chinese-xinhua','0'),
('2101143295961862204','度','1','dù','广','9',NULL,'[{"def": "度", "example": null}, {"def": "(形声。从又,庶省声。又”即手,古代多用手、臂等来测量长度。本义计量长短的标准,尺码)", "example": null}, {"def": "同本义", "example": null}, {"def": "度,法制也。--《说文》。按,五度,分寸尺丈引也。度起于人手取法,故从又。", "example": null}, {"def": "同律度量衡。--《虞书》", "example": null}, {"def": "度然后知长短。--《孟子》", "example": null}, {"def": "执鞭度守门。--《周礼·司市》", "example": null}, {"def": "吾忘持度。--《韩非子》", "example": null}, {"def": "又如尺度", "example": null}, {"def": "法制;法度", "example": null}, {"def": "公室无度。--《左传·昭公三年》", "example": null}, {"def": "度不可改。--《左传·昭公四年》", "example": null}, {"def": "九曰以度教节。--《周礼·大司徒》。注谓宫室车服之制。”", "example": null}, {"def": "度作刑以诘四方。--《书·", "example": null}, {"def": "度 dù", "example": null}, {"def": "①〈古〉估计；推测～已失期。（《陈涉世家》）", "example": null}, {"def": "②计量长短的标准。如米、分米、厘米、毫米等（旧制是丈、尺、寸、分、厘等）。", "example": null}, {"def": "③按一定计量标准划分的单位温～、湿～、硬～。", "example": null}, {"def": "④弧和角的计算单位。", "example": null}, {"def": "⑤划分地球经纬度的单位北京在地球上的位置是东京117～，北纬40～。", "example": null}, {"def": "⑥1千瓦小时电量的通称。", "example": null}, {"def": "⑦程度；限度极～、高～、过～。", "example": null}, {"def": "⑧法则制～。", "example": null}, {"def": "⑨器量；对人对事宽容的程度～量。", "example": null}, {"def": "⑩过；渡过欢～节日。（11）题词。次回。一年一～。(12)姓。又见duó。", "example": null}, {"def": "【度牒】中国封建时代由官府发给和尚、尼姑的证明身份的文件，有度牒可以免除赋税、劳役。", "example": null}, {"def": "【度量】对人对事宽容的程度。又作肚量。", "example": null}, {"def": "【度量衡】计量轻重、长短和容积的统称。度用于计量长短，量用于计量容积，衡用于计量轻重。", "example": null}, {"def": "【度日如年】过一天像熬一年似的。形容日子很不好过。", "example": null}, {"def": "【度数】以度为计量单位所得的数目角的～、眼镜的～。", "example": null}, {"def": "【度制】〈数〉把圆周分为360等份，每一等份所对的角就是1度，再把1度分为60等份，每一等份就是1分，再把1分为60等份，每一等份就是1秒。以度、分、秒作为角的度量", "example": null}, {"def": "单位的单位制叫做角的度分秒制，度、分、秒分别用\'。\'、\'′\'、\'″\'作记号。简称度制。", "example": null}, {"def": "度 duó推测；估计揣～。又见dù。", "example": null}, {"def": "【度德量力】衡量自己的德行是否能服人，估计自己的才能是否能胜任。", "example": null}, {"def": "度zhái 1.居。 2.葬地。", "example": null}]','chinese-xinhua','0'),
