('2101143295961862214','赌','1','dǔ','贝','12',NULL,'[{"def": "赌", "example": null}, {"def": "(形声。从贝,者声。本义用财物作注比输赢)", "example": null}, {"def": "同本义", "example": null}, {"def": "钱(以金钱为输赢的赌博);赌运(赌博的运气);赌贩(赌棍);赌经(专记赌术的书籍)", "example": null}, {"def": "泛指比胜负;争输赢", "example": null}, {"def": ";赌气);赌胆(比赛胆量的大小);赌戏(比赛争胜);赌兴(尽兴争胜);赌说(斗嘴,争辩);赌棋", "example": null}, {"def": "赌 dǔ", "example": null}, {"def": "①赌博。一种用财物作注争输赢的恶习。", "example": null}, {"def": "②泛指争输赢打～。", "example": null}, {"def": "【赌咒】发誓。", "example": null}, {"def": "【赌注】赌博时所押的钱财。", "example": null}]','chinese-xinhua','0'),
('2101143295961862215','睹','1','dǔ','目','13',NULL,'[{"def": "睹", "example": null}, {"def": "(形声。从目,者声。本义见,看见)", "example": null}, {"def": "同本义", "example": null}, {"def": "睹,见也。--《说文》", "example": null}, {"def": "圣人作而万物睹。--《易·文言传》", "example": null}, {"def": "今我睹子之难穷也。--《庄子·秋水》", "example": null}, {"def": "云霞明灭或可睹。--唐·李白《梦游天姥吟留别》", "example": null}, {"def": "令人目不忍睹。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "又如有目共睹;睹睐(看见;发现);睹闻(亲见亲闻);睹始知终(看见事物的开始阶段,就预见到它的最终结果);睹记(见闻与记忆)", "example": null}, {"def": "察看", "example": null}, {"def": "赵简子将袭卫,使史默往睹之。--《吕氏春秋·召类》", "example": null}, {"def": "又如耳闻目睹;秋毫必睹", "example": null}, {"def": "明白;懂得", "example": null}, {"def": "不务深迂而难睹。--《论", "example": null}, {"def": "睹 dǔ看见耳闻目～。", "example": null}]','chinese-xinhua','0'),
('2101143295961862216','笃','1','dǔ','竹','9',NULL,'[{"def": "笃", "example": null}, {"def": "(形声。从马,竹声。本义马行迟顿)", "example": null}, {"def": "同本义", "example": null}, {"def": "笃,马行顿迟也。--《说文》", "example": null}, {"def": "笃癃无家属。--《后汉书·先武纪》。注引《尔雅》曰笃,困也。”", "example": null}, {"def": "又如笃么(笃笃末末,笃笃寞寞。转来转去,徘徊不前)", "example": null}, {"def": "忠实,不虚伪", "example": null}, {"def": "朋友不笃,非孝也。--《吕氏春秋·孝行》", "example": null}, {"def": "慎思之,明辨之,笃行之。--《礼记·中庸》", "example": null}, {"def": "笃公刘。--《诗·大雅·公刘》", "example": null}, {"def": "尧九男,皆益笃。--《史记·五帝纪》", "example": null}, {"def": "又如笃人(忠实厚道的人);笃仁(笃实而仁厚);笃亮(笃实亮直);笃美(笃实美善);笃敏(诚笃而敏锐);笃教(竭诚于教化);笃烈(诚厚刚正", "example": null}, {"def": "笃 dǔ", "example": null}, {"def": "①忠实～信。", "example": null}, {"def": "②（病势）沉重。", "example": null}, {"def": "【笃厚】诚实厚道。", "example": null}, {"def": "【笃实】", "example": null}, {"def": "①忠诚老实。", "example": null}, {"def": "②扎实学问～。", "example": null}, {"def": "【笃信】忠实地信仰。", "example": null}, {"def": "【笃学】专心好学。", "example": null}]','chinese-xinhua','0'),
('2101143295961862217','堵','1','dǔ','土','11',NULL,'[{"def": "堵", "example": null}, {"def": "(形声。从土,者声。本义墙壁)", "example": null}, {"def": "同本义", "example": null}, {"def": "堵,垣也。五版为一堵。--《说文》", "example": null}, {"def": "环堵之室。--《淮南子·原道》", "example": null}, {"def": "止如堵墙。--《尉缭子·战威》", "example": null}, {"def": "又如堵墙(墙垣,土墙。用来比喻密集的人群);堵垣(墙)", "example": null}, {"def": "古代墙壁的面积单位,古代用板筑法筑土墙,五板为一堵,板的长度就是堵的长度,五层板的高度就是堵的高度", "example": null}, {"def": "百堵皆作。--《诗·小雅·鸿雁》", "example": null}, {"def": "又如堵雉(墙垣的长度和高度)", "example": null}, {"def": "堵", "example": null}, {"def": "堵塞", "example": null}, {"def": "堵 dǔ", "example": null}, {"def": "①阻塞～洞。", "example": null}, {"def": "②憋闷～心。", "example": null}, {"def": "③墙观者如～。", "example": null}, {"def": "④量词。用于墙。", "example": null}, {"def": "⑤姓。", "example": null}, {"def": "堵zhě 1.水名。堵河，在湖北省西北部，是汉水支流。", "example": null}]','chinese-xinhua','0'),
