('2101143295970250754','嘟','1','dū','口','13',NULL,'[{"def": "嘟", "example": null}, {"def": "嘟", "example": null}, {"def": "表示申斥。多用于戏曲中", "example": null}, {"def": "嘟!你身为七品知县,竟然殴打国公的差官。--京剧《海瑞背纤》", "example": null}, {"def": "嘟", "example": null}, {"def": "嘟嘟声,管乐器(如喇叭)发出的短促的声音", "example": null}, {"def": "嘟dū", "example": null}, {"def": "①拟声词喇叭～～地响.", "example": null}, {"def": "②嘴向前突出,撅着他生气了,～着嘴谁也不理.", "example": null}]','chinese-xinhua','0'),
('2101143295970250755','督','1','dū','目','13',NULL,'[{"def": "督", "example": null}, {"def": "(形声。从目,叔声。本义察看督促,监督)", "example": null}, {"def": "同本义", "example": null}, {"def": "督,察也。--《说文》", "example": null}, {"def": "禁督逆祀命者。--《周礼·春官·大祝》", "example": null}, {"def": "植中枢,立督虑。--《太玄卷一周》", "example": null}, {"def": "行督责之术。--《史记·李斯传》", "example": null}, {"def": "离娄督绳。--《汉书·王褒传》", "example": null}, {"def": "督责大臣。--《汉书·公孙贺传》", "example": null}, {"def": "闻将军有意督过之。--《汉书·高帝纪》", "example": null}, {"def": "亮使马谡督诸军在前。--《三国志·诸葛亮传》", "example": null}, {"def": "又如", "example": null}, {"def": "督邮(官员。系汉时代表太守督察下属县吏政绩优劣、宣讲教会等的佐吏);", "example": null}, {"def": "督责(督察处罚);", "example": null}, {"def": "督过(督察责罚);", "example": null}, {"def": "督训(督察教育);", "example": null}, {"def": "督参(督察参验);", "example": null}, {"def": "督 dū", "example": null}, {"def": "①〈古〉中央；中间缘～以为经。（《庄子·养生主》）", "example": null}, {"def": "②监视督促～战、总～。", "example": null}, {"def": "【督促】监督催促。", "example": null}, {"def": "【督抚】总督和巡抚。明清两代的最高地方官。", "example": null}, {"def": "【督军】官名。最初由三国时魏置。历朝皆为军事长官或领兵将帅。北洋政府时期，为地方最高军政长官。", "example": null}, {"def": "【督政府】法国资产阶级革命时期的资产阶级共和制政府。1795年11月3日建立。由5名督政官组成。曾镇压了王党叛乱和平等会起义。对外推行扩张政策。政局十分不稳定。1", "example": null}, {"def": "799年11月被执政府取代。", "example": null}]','chinese-xinhua','0'),
