('2101143295974445114','钝','1','dùn','钅','9',NULL,'[{"def": "钝", "example": null}, {"def": "(形声。从金,屯声。本义不锋利)", "example": null}, {"def": "同本义", "example": null}, {"def": "兵不钝锋。--《文选·檄吴将校部曲》", "example": null}, {"def": "庶竭驽钝。--诸葛亮《出师表》", "example": null}, {"def": "又如钝刀(钝兵。不锋利的兵刃)", "example": null}, {"def": "呆;笨拙", "example": null}, {"def": "钝,迟也。--《广雅·释诂四》", "example": null}, {"def": "俗谓愚为钝椎。--《史记·周勃世家》注", "example": null}, {"def": "其刚心勇气消耗钝眊(衰颓)。--宋·苏轼《教战守策》", "example": null}, {"def": "又如钝愚(愚笨;迟钝);钝货(蠢货,笨蛋);钝皮老脸(厚脸皮);钝兵(士气不壮盛)", "example": null}, {"def": "钝 dùn", "example": null}, {"def": "①不锋利；不锐利刀～了。", "example": null}, {"def": "②笨拙；不灵活迟～。", "example": null}, {"def": "【钝角】大于直角小于平角的角。若a为钝角，则90°", "example": null}]','chinese-xinhua','0'),
('2101143295974445115','顿','1','dùn','页','10',NULL,'[{"def": "顿", "example": null}, {"def": "(形声。从页,屯声。从页”,表示与头有关。本义叩头,磕头)", "example": null}, {"def": "同本义", "example": null}, {"def": "顿,下首也。--《说文》", "example": null}, {"def": "二曰顿首。--《周礼·大祝》。注拜头叩地也。”", "example": null}, {"def": "又如顿颡(屈膝下拜,以额叩地,多在请罪投降时用);顿筑(以头或物撞地);顿头(磕头);顿膝(下跪)", "example": null}, {"def": "用脚底或用脚使劲往下踩", "example": null}, {"def": "顿足失色。--《聊斋志异·促织》", "example": null}, {"def": "牵衣顿足拦道哭。--唐·杜甫《兵车行》", "example": null}, {"def": "又如顿脚;顿足(以足跺地。形容着急、悲痛的样子)", "example": null}, {"def": "倒下,跌倒", "example": null}, {"def": "故兵不顿而利可全。--《孙子·谋攻》", "example": null}, {"def": "又如顿仆(僵仆);顿落(低落);顿碌(折腾);顿毙(倒毙)", "example": null}, {"def": "顿 dùn", "example": null}, {"def": "①稍停停～。", "example": null}, {"def": "②忽然；立刻～悟。", "example": null}, {"def": "③用头或手叩地～首。", "example": null}, {"def": "④处理；安置安～。", "example": null}, {"def": "⑤量词。用于吃饭、劝说等行为的次数三～饭。", "example": null}, {"def": "⑥书法上指用力使笔着（zhuó）纸而暂不移动。", "example": null}, {"def": "⑦姓。", "example": null}, {"def": "【顿挫】停顿转折。多形容声音和谐悦耳，节奏感强。", "example": null}, {"def": "【顿号】标点符号的一种，即\'、\'，表示一句话中并列的词或词组之间的停顿。", "example": null}, {"def": "【顿开茅塞】见【茅塞顿开】。", "example": null}, {"def": "【顿然】忽然；一下子。", "example": null}, {"def": "【顿首】叩头；磕头。旧时多用于书信的起头或末尾。", "example": null}, {"def": "【顿音】缩短音符时值，使音与音不相连贯的一种奏（唱）法。听起来富于弹跳性。又称断音。", "example": null}, {"def": "顿dú 1.见\\"冒顿\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295974445116','遁','1','dùn','辶','12',NULL,'[{"def": "遁", "example": null}, {"def": "(形声。从辵,盾声。本义逃避)", "example": null}, {"def": "同本义", "example": null}, {"def": "遁,迁也。--《说文》", "example": null}, {"def": "遁,避也。--《广雅·释诂三》", "example": null}, {"def": "遁,犹回避也。--《后汉书·杜林传》注", "example": null}, {"def": "阳遁而不能蒸。--《国语·周语》", "example": null}, {"def": "平当逡遁有耻。--《汉书·隽疏干薛平传赞》", "example": null}, {"def": "又如遁隐(避世隐居);遁天(逃遁天理,违背自然);遁命(逃避任命);遁俗(犹言逃避世俗);遁避(犹逃避)", "example": null}, {"def": "逃跑,逃走", "example": null}, {"def": "一曰逃也。--《说文》", "example": null}, {"def": "晋将遁矣。--《国语·楚语》", "example": null}, {"def": "敌弃炮仓皇遁。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "虎大骇,远遁。--唐·柳宗元《三戒》", "example": null}, {"def": "又如遁世离群(逃离人世,", "example": null}, {"def": "遁 dùn", "example": null}, {"def": "①逃走～逃。", "example": null}, {"def": "②回避～世。", "example": null}, {"def": "【遁词】", "example": null}, {"def": "【遁辞】在理屈词穷时故意避开正题的话。", "example": null}, {"def": "【遁迹】避开人世；隐居。", "example": null}, {"def": "遁qūn 1.见\\"遁巡\\"。", "example": null}]','chinese-xinhua','0'),
