('2101143295974445169','趓','1','duǒ','','11',NULL,'[{"def": "趓duǒ 1.同\\"躲\\"。躲避;避开。 2.同\\"躲\\"。躲藏。 3.同\\"垛\\"。参见\\"趓楼\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295974445170','躲','1','duǒ','身','13',NULL,'[{"def": "躲", "example": null}, {"def": "(形声。从身,朵声。①本义身。②避开,隐匿)", "example": null}, {"def": "藏身", "example": null}, {"def": "避开;避让", "example": null}, {"def": "躲 duǒ隐藏；避开～雨、～债。", "example": null}]','chinese-xinhua','0'),
('2101143295974445171','亸','1','duǒ','','11',NULL,'[{"def": "亸duǒ 1.下垂。 2.摇曵;飘动。 3.松弛。参见\\"亸鞚\\"。 4.同\\"躲\\"。躲避;隐遁。 5.指责。参见\\"亸剥\\"。", "example": null}]','chinese-xinhua','0'),
