('2101143295974445176','咄','1','duō','口','8',NULL,'[{"def": "咄", "example": null}, {"def": "(形声。从口,出声。本义呵叱声) 同本义", "example": null}, {"def": "咄,相调也。--《说文》", "example": null}, {"def": "咄,相诃也。--《字林》", "example": null}, {"def": "咄,啐也。--《苍颉篇》", "example": null}, {"def": "咄!口无毛。--《汉书·东方朔传》。注叱咄之声。”", "example": null}, {"def": "郭舍人疾言骂之曰咄!老女子!何不疾行!”--《史记》", "example": null}, {"def": "咄!你是个破落户。--《水浒传》", "example": null}, {"def": "又如咄叱(呵责);咄啐(呵斥);咄骂(呵斥辱骂)", "example": null}, {"def": "咄 duō表示呵（hē）叱。", "example": null}, {"def": "【咄咄逼人】形容气势汹汹，盛气凌人。也形容形势发展迅速，给人以压力。", "example": null}, {"def": "【咄咄怪事】令人十分惊讶的怪事。", "example": null}]','chinese-xinhua','0'),
('2101143295978639360','哆','1','duō','口','9',NULL,'[{"def": "哆", "example": null}, {"def": "形容敲击声", "example": null}, {"def": "张姑娘含着笑,皱着眉,把两只小脚儿点的脚踏儿哆哆的乱响。--《儿女英雄传》", "example": null}, {"def": "哆", "example": null}, {"def": "战栗", "example": null}, {"def": "哆哆(喋喋。说话没完没了)", "example": null}, {"def": "哆嗦", "example": null}, {"def": "冷得打哆嗦", "example": null}, {"def": "哆chǐ", "example": null}, {"def": "①张口貌。", "example": null}, {"def": "②哗然；纷纷指责状。", "example": null}, {"def": "哆duō", "example": null}, {"def": "【哆嗦】发抖、颤动。", "example": null}, {"def": "哆chǐ", "example": null}, {"def": "①谓张口。", "example": null}, {"def": "②谓扩大。", "example": null}, {"def": "③分散。", "example": null}, {"def": "④放荡;放佚。", "example": null}, {"def": "哆duō", "example": null}, {"def": "①象声词。形容敲击声。", "example": null}, {"def": "②方言。噘起，翘起。", "example": null}, {"def": "③见\\"哆哆\\"。", "example": null}, {"def": "④见\\"哆嗦\\"。", "example": null}, {"def": "【哆弄】方言。翻弄，摆弄。", "example": null}, {"def": "【哆哆】犹喋喋﹐说话没完没了。", "example": null}, {"def": "【哆哩哆嗦】哆嗦。", "example": null}, {"def": "【哆唆】哆嗦。", "example": null}, {"def": "【哆嗦】颤动;发抖。", "example": null}, {"def": "【哆羅呢】即哆啰呢。", "example": null}, {"def": "【哆囉】法droguet即哆啰呢。", "example": null}, {"def": "【哆囉呢】一种较厚的宽幅毛织呢料。", "example": null}, {"def": "【哆囉絨】即哆啰呢。", "example": null}, {"def": "【哆囉嗹】即哆啰呢。", "example": null}]','chinese-xinhua','0'),
