('2101143295978639401','扼','1','è','扌','7',NULL,'[{"def": "扼", "example": null}, {"def": "(形声。从手,厄声。本义抓住;掐住)", "example": null}, {"def": "同本义", "example": null}, {"def": "搤,捉也。--《说文》", "example": null}, {"def": "力扼虎,射命中。--《汉书·李陵传》", "example": null}, {"def": "搤其喉而不得进。--《后汉书·荀彧传》", "example": null}, {"def": "不搤其亢。--《汉书·娄敬传》", "example": null}, {"def": "搤熊罴。--《汉书·扬雄传》", "example": null}, {"def": "搤,持也。--《广雅·释诂三》", "example": null}, {"def": "又如扼虎(用双手掐住猛虎);扼吭拊背(本指控制咽喉。引申为扼制要冲之意);扼襟(握持衣服的襟领。引申为控制要害,掌握要领);扼臂(手臂)", "example": null}, {"def": "扼守;据守", "example": null}, {"def": "阻碍,堵住", "example": null}, {"def": "因而搤之可也。--《庄子》。又如扼昧(暗", "example": null}, {"def": "扼 è", "example": null}, {"def": "①用力掐捏～杀。", "example": null}, {"def": "②把守～守。", "example": null}, {"def": "【扼守】把守（险要的地方）～关隘。", "example": null}, {"def": "【扼腕】用一只手握住自己另一只手的手腕。表示激动、振奋或惋惜。", "example": null}, {"def": "【扼要】写文章或谈话能抓住要点。", "example": null}]','chinese-xinhua','0'),
('2101143295978639402','苊','1','è','艹','7',NULL,'[{"def": "苊", "example": null}, {"def": "有机化合物的一类。一种结晶状三环烃c12h10,熔点92度,不溶于水,主要得自煤焦油,用作染料中间体,在生物学中用于诱发多倍性染色体", "example": null}, {"def": "苊 è 分子式c12h10的有机化合物,无色针状结晶,可做媒染剂.", "example": null}]','chinese-xinhua','0'),
('2101143295978639403','轭','1','è','车','8',NULL,'[{"def": "轭", "example": null}, {"def": "(形声。从车,厄声。本义驾车时套在牲口脖子上的曲木) 同本义", "example": null}, {"def": "轭,辕前也。--《说文》。段注辕前者,谓衡也。”", "example": null}, {"def": "楔貌如輖。--《仪礼·既夕礼》", "example": null}, {"def": "三公奉輖持纳。--《荀子·正论》", "example": null}, {"def": "牵牛(牵牛星)不负轭。--《古诗十九首》", "example": null}, {"def": "轭", "example": null}, {"def": "束缚", "example": null}, {"def": "君以名桎臣,官以名轭民,父以名压子。--谭嗣同《仁学界说二十七界说》", "example": null}, {"def": "控制", "example": null}, {"def": "意大利之大部被轭于奥国。--梁启超《国家思想变迁异同论》", "example": null}, {"def": "轭 è牛、马等拉东西时架在颈部的套具。", "example": null}]','chinese-xinhua','0'),
('2101143295978639404','咢','1','è','','13',NULL,'[{"def": "咢è 1.击鼓而歌。 2.泛指无伴奏而歌唱;歌唱。 3.\\"锷\\"的古字。刀剑的刃。 4.指屋棱。 5.通\\"愕\\"。参见\\"咢然\\"。 6.通\\"谔\\"。参见\\"咢咢\\"。 7.通\\"噩\\"。 8.通\\"遌", "example": null}, {"def": "\\"。参见\\"咢布\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295978639405','垩','1','è','土','9',NULL,'[{"def": "垩", "example": null}, {"def": "(形声。从土,亚声。本义白色土,可用来粉饰墙壁) 同本义", "example": null}, {"def": "垩,白涂也。--《说文》", "example": null}, {"def": "大次之山,其阳多垩。--《山海经·西山经》。注垩似土,色甚白。”", "example": null}, {"def": "其土则丹青赭垩。--司马相如《子虚赋》", "example": null}, {"def": "天子诸侯黝垩。--《谷梁传·庄公二十三年》", "example": null}, {"def": "后泛指可用来涂饰的各色泥土。如垩灰(石灰的别名);垩笔(粉笔)", "example": null}, {"def": "垩", "example": null}, {"def": "用白色涂料粉刷墙壁", "example": null}, {"def": "垩,涂也。--《广雅·释室》", "example": null}, {"def": "垩墁。--《后汉书·尹敏传》", "example": null}, {"def": "其祧则守祧黝垩之。--《周礼·司祧》", "example": null}, {"def": "又如垩帚(粉刷墙壁的工具);垩室(古时居丧者居住的屋子,四壁用白", "example": null}, {"def": "垩 shèng", "example": null}, {"def": "①\\"圣\\"的俗字。见《明成化说唱词话．花关索认父传》。", "example": null}, {"def": "②\\"堊\\"的简化字。", "example": null}]','chinese-xinhua','0'),
