('2101143295978639497','尔','1','ěr','小','5',NULL,'[{"def": "尔", "example": null}, {"def": "(形声。本义窗格花纹)", "example": null}, {"def": "同本义", "example": null}, {"def": "后引作薾。华盛的样子", "example": null}, {"def": "彼尔维何?维常之华。--《诗·小雅》。毛传尔,华盛貌。”", "example": null}, {"def": "又如丽尔(华丽的样子)", "example": null}, {"def": "近。通迩”", "example": null}, {"def": "戚戚兄弟,莫远具尔。--《诗·大雅》", "example": null}, {"def": "尔上敦黍于筵上右之。--《仪礼·少牢馈食礼》", "example": null}, {"def": "公降立于阼阶之东南,南乡尔卿。--《仪礼·燕礼》", "example": null}, {"def": "名相近者相远也,实相近者相尔也。--《周礼·地官·肆长》", "example": null}, {"def": "士不信悫而有多知能,譬之其豺狼也,不可以身尔也。--《荀子·哀公》", "example": null}, {"def": "又如尔者(近来);尔语(凑向跟前说话)", "example": null}, {"def": "浅近", "example": null}, {"def": "尔 ěr", "example": null}, {"def": "①〈古〉你；你们；你的；你们的～作言造语。（《庄子·盗跖》）、以～车来。（《诗经·卫风·氓》）", "example": null}, {"def": "②〈古〉这；那～夜风恬月朗。（刘义庆《世说新语·赏誉下》）", "example": null}, {"def": "③〈古〉这样问君何能～。（陶潜《饮酒》）", "example": null}, {"def": "④〈古〉近实相近者相～也。（《周礼·地官·肆长》）", "example": null}, {"def": "⑤〈古〉语气词。表示肯定或\'罢了\'的意思明日取虞～（《公羊传·僖公二年》）、如反手～。（《荀子·非相》）", "example": null}, {"def": "⑥词尾。相当于\'地\'、\'然\'卓～、率～。", "example": null}, {"def": "【尔曹】你们这些人。", "example": null}, {"def": "【尔虞我诈】互相猜疑，互相欺骗。又作尔诈我虞。", "example": null}, {"def": "【尔诈我虞】见【尔虞我诈】。", "example": null}]','chinese-xinhua','0'),
('2101143295982833664','耳','1','ěr','耳','6',NULL,'[{"def": "耳", "example": null}, {"def": "(象形。甲骨文字形,象耳朵形『字部首之一。本义耳朵)", "example": null}, {"def": "同本义", "example": null}, {"def": "耳,主听也。--《说文》", "example": null}, {"def": "耳者,肾之候。--《白虎通·情性》", "example": null}, {"def": "耳者,心之候。--《春秋·元命苞》", "example": null}, {"def": "耳目者,心思之助也。--《鬼谷子·权篇》", "example": null}, {"def": "坎为耳。--《易·说卦》", "example": null}, {"def": "忠言逆耳利于行。--明·刘基《苦斋记》", "example": null}, {"def": "事不目见耳闻,而臆断其有无,可乎?--宋·苏轼《石钟山记》", "example": null}, {"def": "又如耳目官(指耳、目两种器官);耳斡儿(亦作耳挖子”。掏耳垢的小勺,另一头有尖头);耳朵垂子(借指耳窝);耳根厢(耳边);耳顺(六十岁)", "example": null}, {"def": "听觉,听力", "example": null}, {"def": "耳 ěr", "example": null}, {"def": "①〈古〉语气词。表示肯定或\'罢了\'的意思且吾所为者极难～。（《史记·刺客列传》）、如反覆手～。（《史记·陆贾传》）", "example": null}, {"def": "②耳朵～聋。", "example": null}, {"def": "③形状像耳朵的东西木～。", "example": null}, {"def": "④位置在两旁的～门（大门两旁的小门）。", "example": null}, {"def": "【耳鬓厮磨】形容亲密相处的情景（多指青年男女之间十分亲近）。鬓面颊两旁近耳的头发。厮相互。", "example": null}, {"def": "【耳聪目明】形容视听灵敏。", "example": null}, {"def": "【耳目】", "example": null}, {"def": "①见闻～不广。", "example": null}, {"def": "②替人刺探消息的人。", "example": null}, {"def": "【耳目一新】听到的看到的都换了样子，给人以新鲜的感觉。", "example": null}, {"def": "【耳濡目染】形容见得多听得多之后，无形中受影响。濡沾湿；润泽。", "example": null}, {"def": "【耳食之谈】见【耳食之言】。", "example": null}, {"def": "【耳食之言】传闻的没有根据的话。又作耳食之谈。", "example": null}, {"def": "【耳熟能详】听得多了，也就能详尽地说出来。", "example": null}, {"def": "【耳提面命】不但当面告诉，而且凑近耳朵讲。形容严厉而又恳切地教导。耳提附耳。面当面。", "example": null}, {"def": "【耳蜗】〈生〉内耳的组成部分。形似蜗牛壳，故名。内有淋巴液和听神经，是听觉感受器官。", "example": null}, {"def": "【耳咽管】见【咽鼓管】。", "example": null}, {"def": "【耳语】凑近别人耳朵小声说话。", "example": null}, {"def": "耳réng 1.见\\"耳孙\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295982833665','迩','1','ěr','辶','8',NULL,'[{"def": "迩", "example": null}, {"def": "(形声。从辵,尔声。本义近)", "example": null}, {"def": "同本义", "example": null}, {"def": "迩,近也。--《说文》", "example": null}, {"def": "柔远能迩。--《虞书》", "example": null}, {"def": "父母孔迩。--《诗·周南·汝坟》", "example": null}, {"def": "节远迩之期也。--《礼记·郊特性》", "example": null}, {"def": "戎事不迩女器。--《左传·僖公二十二年》", "example": null}, {"def": "既而敌行益迩。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "举类迩而见义远。--《史记·屈原贾生列传》", "example": null}, {"def": "又如迩来(近来);遐迩(远近);迩人(近人;亲近的人);迩日(近日;近来);迩年(犹近年);迩狭(近);迩时(近时,近来)", "example": null}, {"def": "浅", "example": null}, {"def": "维迩言是听,维迩言是争。--《诗·小雅·小昮》", "example": null}, {"def": "又如迩文(浅近的文章)", "example": null}, {"def": "迩", "example": null}, {"def": "接近", "example": null}, {"def": "迩 ěr近遐～闻名。", "example": null}, {"def": "【迩来】近来。", "example": null}]','chinese-xinhua','0'),
('2101143295982833666','洱','1','ěr','氵','9',NULL,'[{"def": "洱海", "example": null}, {"def": "洱ěr洱海，湖名，在云南。", "example": null}, {"def": "洱 ěr 见\\"洱水\\"﹑\\"洱海\\"。", "example": null}, {"def": "【洱水】", "example": null}, {"def": "①古水名。源出今河南省内乡县熊耳山，东南流注于渦水。", "example": null}, {"def": "②即洱海。", "example": null}, {"def": "【洱河】即今云南省的西洱河。", "example": null}, {"def": "【洱海】湖名。古称叶榆泽。在云南省大理市﹑洱源县间。因其形如耳得名。西汇点苍山麓诸水，冲积为肥沃的大理平原。北纳西洱河，流出大理市，汇合漾濞江，注入澜沧江", "example": null}, {"def": "。有\\"三岛\\"﹑\\"四洲\\"﹑\\"九曲\\"之胜，是著名风景区。", "example": null}]','chinese-xinhua','0'),
('2101143295982833667','饵','1','ěr','饣','9',NULL,'[{"def": "饵", "example": null}, {"def": "(形声。从食,耳声。本义糕饼)", "example": null}, {"def": "同本义", "example": null}, {"def": "饵,粉饼也。--《说文》", "example": null}, {"def": "鱼胶饵。--《考工记·弓人》", "example": null}, {"def": "又如果饵(果饼)", "example": null}, {"def": "钓鱼用的鱼食", "example": null}, {"def": "临川靡芳饵。--《文选·傅长虞诗》", "example": null}, {"def": "又如鱼饵;钓饵", "example": null}, {"def": "药饵", "example": null}, {"def": "得而猎之以为饵,可以已大风、挛踠、瘘、疠。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "又如饵治(以药饵治病)", "example": null}, {"def": "食物的总称", "example": null}, {"def": "筋腱", "example": null}, {"def": "捶反铡之,去其饵。--《礼记·内则》", "example": null}, {"def": "饵", "example": null}, {"def": "吞食", "example": null}, {"def": "适足以饵大国耳。--《汉书·贾谊传》。注谓为其所吞食。”", "example": null}, {"def": "又如饵名钓禄(以不正当的手段取得名", "example": null}, {"def": "饵 ěr", "example": null}, {"def": "①糕饼果～。", "example": null}, {"def": "②钓鱼用的鱼食鱼～。", "example": null}, {"def": "③引诱以此～敌。", "example": null}]','chinese-xinhua','0'),
