('2101143295982833740','返','1','fǎn','辶','7',NULL,'[{"def": "返〈动〉", "example": null}, {"def": "(形声。从辵,反声。字本作反”。本义回归,返回)", "example": null}, {"def": "同本义", "example": null}, {"def": "返,还也。--《说文》", "example": null}, {"def": "返,归也。--《广雅》", "example": null}, {"def": "祖伊返。--《书·西伯勘黎》", "example": null}, {"def": "黄鹤一去不复返,白云千载空悠悠。--唐·崔颢《黄鹤楼》", "example": null}, {"def": "公子往而臣不送,以是知公子恨之复返也。--《史记·魏公子列传》", "example": null}, {"def": "久在樊笼里,复得返自然。--晋·陶渊明《归园田居》", "example": null}, {"def": "返字本作反”", "example": null}, {"def": "福禄来反。--《诗·周颂·执竞》", "example": null}, {"def": "而反其侵地。--《国语·齐语》", "example": null}, {"def": "又如返命(办完事情后,回来复命);返书(回信);返棹(船只返回)", "example": null}, {"def": "归还", "example": null}, {"def": "其子长而返其璧。--《", "example": null}, {"def": "返 fǎn", "example": null}, {"def": "⒈归，回～家。～老还童。流连忘～。", "example": null}, {"def": "⒉", "example": null}, {"def": "【返工】工作没有做好，再重新做。", "example": null}]','chinese-xinhua','0'),
('2101143295982833741','氾','1','fǎn','氵','5',NULL,'[{"def": "氾〈名〉", "example": null}, {"def": "古地名。春秋郑邑", "example": null}, {"def": "南氾。在今河南省襄城县南", "example": null}, {"def": "东氾。在今河南省中牟县", "example": null}, {"def": "古氾水的省称", "example": null}, {"def": "晋军函陵,秦军氾南。--《左传》", "example": null}, {"def": "古国名", "example": null}, {"def": "氾,国名。--《广韵》", "example": null}, {"def": "氾〈动〉", "example": null}, {"def": "大水漫流;淹没", "example": null}, {"def": "河水决濮阳,氾郡十六。--《汉书·武帝纪》", "example": null}, {"def": "漂浮◇作泛”", "example": null}, {"def": "是故氾舟于河。--《国语》", "example": null}, {"def": "氾〈形〉", "example": null}, {"def": "地势低下的", "example": null}, {"def": "有氾下渐泽之壤。--《管子·山国轨》", "example": null}, {"def": "以范围", "example": null}, {"def": "反 fǎn", "example": null}, {"def": "⒈翻转，颠倒，与\\"正\\"相对～转。～倒。～攻。～面。相～。如～手尔。皮袄穿～了。", "example": null}, {"def": "⒉不正常，和预想的不同气候～常。～而不好。画虎不成～类犬。", "example": null}, {"def": "⒊回还，回击，抵制，对抗～问。～驳。～对。～抗。～贪污。～腐败。", "example": null}, {"def": "⒋违背，背叛违～。～叛。～戈。～水。", "example": null}, {"def": "⒌类推举一～三。", "example": null}, {"def": "⒍", "example": null}, {"def": "【反复】重复，翻来覆去～复操作。～复无常。", "example": null}, {"def": "⒎", "example": null}, {"def": "【反间】利用敌人的弱点或间谍使敌人内部自相矛盾、自相残杀。", "example": null}, {"def": "⒏", "example": null}, {"def": "【反正】", "example": null}, {"def": "①平定混乱，恢复秩序拨乱～正。", "example": null}, {"def": "②敌方人员或军队投入己方。", "example": null}, {"def": "③副词♂竖，不管怎样～正我们都要去。", "example": null}, {"def": "⒐", "example": null}, {"def": "【反动】", "example": null}, {"def": "①指思想、行为上维护旧的，反对革新的～动言论。～动阶级。", "example": null}, {"def": "②相反的作用从历史来看，党八股是对于\\"五四运动\\"的一个～动。", "example": null}, {"def": "⒑", "example": null}, {"def": "【反省】对自己的思想言行加以检讨。", "example": null}, {"def": "⒒", "example": null}, {"def": "【反映】", "example": null}, {"def": "①反照月光～映。〈喻〉把客观事物的实质表现出来。", "example": null}, {"def": "②把情况、意见等向上级或有关部门报告。", "example": null}, {"def": "⒓", "example": null}, {"def": "【反应】", "example": null}, {"def": "①有机体受到刺激而引起的相应活动应激～应。", "example": null}, {"def": "②化学上称物质相互作用而引起变化的现象化学～应。", "example": null}, {"def": "③由于打针、服药等而引起的发热、头昏、呕吐等副作用药物～应。", "example": null}, {"def": "④事物引起的意见、评论、态度或行动～应良好。", "example": null}, {"def": "⒔", "example": null}, {"def": "【反刍】倒嚼。骡驼、牛、羊等把粗粗吃进的食物再返回到嘴里细嚼。", "example": null}, {"def": "反fān 1.翻案。 2.倒出，倒掉。", "example": null}, {"def": "反fàn 1.贩卖。", "example": null}, {"def": "反pàn 1.见\\"反衍\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295982833742','反','1','fǎn','又','4',NULL,'[{"def": "反〈动〉", "example": null}, {"def": "(象形。甲骨文字形,从又从厂。厂”音。本义手心翻转)", "example": null}, {"def": "同本义。通翻”。覆,倾倒", "example": null}, {"def": "反,覆也。--《说文》", "example": null}, {"def": "以齐王,由反手也。--《孟子·公孙丑上》", "example": null}, {"def": "何以知其不反水浆邪?--《汉书·张安世传》", "example": null}, {"def": "反覆", "example": null}, {"def": "安反侧于万物。--南朝梁·丘迟《与陈伯之书》", "example": null}, {"def": "不思其反。--《诗·卫风·氓》", "example": null}, {"def": "成反复自念。--《聊斋志异·促织》", "example": null}, {"def": "又如辗转反侧;反易(颠倒);反风(风向倒转)", "example": null}, {"def": "通返”。返回;回归", "example": null}, {"def": "使子路反见之。--《论语·微子》", "example": null}, {"def": "夫迷途知反,往哲是与。--南朝梁", "example": null}, {"def": "反 fǎn", "example": null}, {"def": "⒈翻转，颠倒，与\\"正\\"相对～转。～倒。～攻。～面。相～。如～手尔。皮袄穿～了。", "example": null}, {"def": "⒉不正常，和预想的不同气候～常。～而不好。画虎不成～类犬。", "example": null}, {"def": "⒊回还，回击，抵制，对抗～问。～驳。～对。～抗。～贪污。～腐败。", "example": null}, {"def": "⒋违背，背叛违～。～叛。～戈。～水。", "example": null}, {"def": "⒌类推举一～三。", "example": null}, {"def": "⒍", "example": null}, {"def": "【反复】重复，翻来覆去～复操作。～复无常。", "example": null}, {"def": "⒎", "example": null}, {"def": "【反间】利用敌人的弱点或间谍使敌人内部自相矛盾、自相残杀。", "example": null}, {"def": "⒏", "example": null}, {"def": "【反正】", "example": null}, {"def": "①平定混乱，恢复秩序拨乱～正。", "example": null}, {"def": "②敌方人员或军队投入己方。", "example": null}, {"def": "③副词♂竖，不管怎样～正我们都要去。", "example": null}, {"def": "⒐", "example": null}, {"def": "【反动】", "example": null}, {"def": "①指思想、行为上维护旧的，反对革新的～动言论。～动阶级。", "example": null}, {"def": "②相反的作用从历史来看，党八股是对于\\"五四运动\\"的一个～动。", "example": null}, {"def": "⒑", "example": null}, {"def": "【反省】对自己的思想言行加以检讨。", "example": null}, {"def": "⒒", "example": null}, {"def": "【反映】", "example": null}, {"def": "①反照月光～映。〈喻〉把客观事物的实质表现出来。", "example": null}, {"def": "②把情况、意见等向上级或有关部门报告。", "example": null}, {"def": "⒓", "example": null}, {"def": "【反应】", "example": null}, {"def": "①有机体受到刺激而引起的相应活动应激～应。", "example": null}, {"def": "②化学上称物质相互作用而引起变化的现象化学～应。", "example": null}, {"def": "③由于打针、服药等而引起的发热、头昏、呕吐等副作用药物～应。", "example": null}, {"def": "④事物引起的意见、评论、态度或行动～应良好。", "example": null}, {"def": "⒔", "example": null}, {"def": "【反刍】倒嚼。骡驼、牛、羊等把粗粗吃进的食物再返回到嘴里细嚼。", "example": null}, {"def": "反fān 1.翻案。 2.倒出，倒掉。", "example": null}, {"def": "反fàn 1.贩卖。", "example": null}, {"def": "反pàn 1.见\\"反衍\\"。", "example": null}]','chinese-xinhua','0'),
