('2101143295982833760','旛','1','fān','','12',NULL,'[{"def": "旛fān 1.长幅下垂的旗。亦泛指旌旗◇作\\"幡\\"。 2.见\\"旛旛\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295982833761','翻','1','fān','羽','18',NULL,'[{"def": "翻〈动〉", "example": null}, {"def": "(形声。从羽,番声。本义鸟飞)", "example": null}, {"def": "同本义", "example": null}, {"def": "青菰临水映,白鸟向山翻。--王维《辋川闲居》", "example": null}, {"def": "又如翻泊(或飞或止);翻翔(翻飞,飞翔);翻簸(飞驰)", "example": null}, {"def": "翻转;翻腾", "example": null}, {"def": "波翻晓霞影。--李白《姑熟十咏》", "example": null}, {"def": "又如翻滚滚(上下急速滚动的样子);翻海(形容声响如海浪翻腾);翻雪(形容白浪翻滚);翻扑(翻腾)", "example": null}, {"def": "反转,倾倒,变动位置", "example": null}, {"def": "钿头银篦击节碎,白色罗裙翻酒污。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "多少好汉被蒙汗酒麻翻了。--《水浒传》", "example": null}, {"def": "又如翻席(吃完一席,再到他处吃另一席);翻台(嫖客在一妓院宴毕,再到另一妓院饮宴);", "example": null}, {"def": "翻（飜） fān", "example": null}, {"def": "⒈反转，歪倒，上下、内外移位～倒。～转。～滚。～腾。～补。汽车～了。～箱倒柜。", "example": null}, {"def": "⒉改变原先的～然图改。～冤假错案。", "example": null}, {"def": "⒊数量成倍增长～番。", "example": null}, {"def": "⒋爬过，越过～越。～山越岭。", "example": null}, {"def": "⒌感情破裂～脸。闹～了。", "example": null}, {"def": "⒍翻译，把一种语言、文字等译成另一种语言、文字，以及做此种工作的人把中文～成英语。她是英语～译。", "example": null}, {"def": "⒎", "example": null}, {"def": "【翻身】", "example": null}, {"def": "①翻转身体,翻来覆去（也形容多次重复）～身难眠。", "example": null}, {"def": "②〈喻〉从被压迫、被剥削的情况下解放出来～身不忘共产党。", "example": null}, {"def": "⒏", "example": null}, {"def": "【翻阅】翻着看书报、文件等这本书我一页一页地～阅过。", "example": null}, {"def": "⒐", "example": null}, {"def": "【翻版】按照原本复制印刷。〈引〉贬义地指旧调重弹，形式不同而实质一样他这次发言，就是上个月一次讲话的～版。", "example": null}, {"def": "⒑", "example": null}, {"def": "【翻砂】将熔化的金属倒入用湿砂制成的模型里，铸造成器具或机件。", "example": null}, {"def": "⒒", "example": null}, {"def": "【翻然】转变得很快～然悔悟。", "example": null}, {"def": "翻fán 1.见\\"翻?\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295982833762','藩','1','fān','艹','18',NULL,'[{"def": "藩〈名〉", "example": null}, {"def": "(形声。从苃,潘声。本义篱笆)", "example": null}, {"def": "同本义", "example": null}, {"def": "藩,屏也。--《说文》", "example": null}, {"def": "藩,篱也。--《广雅·释室》", "example": null}, {"def": "羝羊触藩。--《易·大壮卦》", "example": null}, {"def": "吴人藩卫侯之舍。--《左传·哀公十二年》", "example": null}, {"def": "而青蝇点素,同兹在藩。--《后汉书·杨震传》", "example": null}, {"def": "又如藩屏(藩篱屏障);藩柴(篱笆);藩架(篱芭);藩落(篱落,篱芭)", "example": null}, {"def": "屏障", "example": null}, {"def": "国有故,则藩塞阻路,而止行者。--《周礼·夏官》", "example": null}, {"def": "乃使蒙恬北筑长城而守藩篱。--贾谊《过秦论》", "example": null}, {"def": "王侯的封国", "example": null}, {"def": "藩fān", "example": null}, {"def": "⒈篱笆～篱。〈引〉屏障屏～。", "example": null}, {"def": "⒉遮盖～饰。", "example": null}, {"def": "⒊封建王朝分给诸侯王的封国。也用于称属国、属地～国。～属。", "example": null}, {"def": "藩fán 1.草名。 2.用同\\"蕃\\"。生育，繁殖。参见\\"藩衍\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295982833763','颿','1','fān','','18',NULL,'[{"def": "颿fān 1.马奔驰。 2.泛指疾速。参见\\"帆风\\"。 3.同\\"帆\\"。船帆。亦借指帆船。", "example": null}]','chinese-xinhua','0'),
('2101143295982833764','蕃','1','fān','艹','15',NULL,'[{"def": "蕃〈名，动〉", "example": null}, {"def": "通藩”", "example": null}, {"def": "篱落;屏障", "example": null}, {"def": "四国于蕃,四方于宣。--《诗·大雅·崧高》", "example": null}, {"def": "夫蕃篱之鶠,岂能与之料天地之高哉?--宋玉《对楚王问》", "example": null}, {"def": "又如蕃蔽(屏障);蕃篱(篱笆。引申为屏障)", "example": null}, {"def": "藩屏;捍卫", "example": null}, {"def": "故封建亲戚以蕃屏周。--《国语·楚语下》", "example": null}, {"def": "又如蕃杆(藩屏;护卫);蕃辅(捍卫辅助);蕃宣(本指藩篱与垣墙。引申为藩屏护卫);蕃卫(捍卫)", "example": null}, {"def": "封建王朝分封的侯国", "example": null}, {"def": "颊侧", "example": null}, {"def": "蕃者,颊侧也。--《灵枢经》。张志聪注蕃蔽在外。”", "example": null}, {"def": "通番”", "example": null}, {"def": "周代谓九州", "example": null}, {"def": "蕃 fán", "example": null}, {"def": "⒈茂盛林木～盛。〈喻〉繁多，增多～衍。", "example": null}, {"def": "⒉繁殖，滋生五谷～息。", "example": null}, {"def": "蕃fān 1.通\\"藩\\"。篱落;屏障。 2.通\\"藩\\"。藩屏;捍卫。 3.通\\"藩\\"。封建王朝分封的侯国。 4.通\\"藩\\"。颊侧。 5.通\\"番\\"。周代谓九州之外的夷服﹑镇服﹑蕃服◇用以泛指域外或外族。 6.通\\"番\\"。轮流更替。参见\\"蕃匠\\"。 7.通\\"?\\"﹑\\"辬\\"。车耳两旁反出如耳的部分，用来遮蔽尘土。", "example": null}, {"def": "蕃pí 1.姓『有蕃向。见《后汉书．党锢传》。", "example": null}, {"def": "蕃bō 1.见\\"蕃荷\\"。 2.见\\"吐蕃\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295982833765','防','1','fánɡ','阝','6',NULL,'[{"def": "防〈名〉", "example": null}, {"def": "(形声。从阜,方声。本义堤坝)", "example": null}, {"def": "同本义", "example": null}, {"def": "防,堤也。--《说文》", "example": null}, {"def": "以防止水。--《周礼·稻人》", "example": null}, {"def": "町原防。--《左传·襄公二十五年》", "example": null}, {"def": "祭防与水庸。--《礼记·郊特性》", "example": null}, {"def": "大者为之堤,小者为之防。--《管子·度地》", "example": null}, {"def": "巨防容蝼而漂邑杀人。--《吕氏春秋·慎小》。又如防隅(水防山隅);沟防;堤防", "example": null}, {"def": "要塞;关防", "example": null}, {"def": "地名", "example": null}, {"def": "春秋陈邑,在今河南省淮阳县北", "example": null}, {"def": "春秋鲁地。在今山东省费城县东北", "example": null}, {"def": "春秋宋地,后属鲁,在今山东省金乡县西南", "example": null}, {"def": "通房”。住室", "example": null}, {"def": "夏,有芝生殿", "example": null}, {"def": "防 fáng", "example": null}, {"def": "⒈戒备，预置～备。～务。～止。设～。～汛。～患未然。以～万一。～微杜渐。", "example": null}, {"def": "⒉堤坝，挡水的建筑物堤～。", "example": null}, {"def": "⒊", "example": null}, {"def": "【国防】为着保卫国家的领土、主权而设置的一切防务国～军队。国～工厂。国～重镇。", "example": null}]','chinese-xinhua','0'),
('2101143295982833766','妨','1','fánɡ','女','7',NULL,'[{"def": "妨〈动〉", "example": null}, {"def": "(形声。从女,方声。本义损害;有害于)", "example": null}, {"def": "同本义", "example": null}, {"def": "妨,害也。--《说文》", "example": null}, {"def": "将妨于国家。--《国语·越语》", "example": null}, {"def": "敬而无妨些。--《楚辞·招魂》", "example": null}, {"def": "令人行妨。--《老子》。注伤也。”", "example": null}, {"def": "不以自妨也。--《荀子·解蔽》", "example": null}, {"def": "贼父之子,妨兄之弟,与此同召。--《论衡·偶会》", "example": null}, {"def": "又如妨要(妨害要务);妨紊(伤害扰乱)", "example": null}, {"def": "阻碍", "example": null}, {"def": "无发令而干时,以妨神农之事。--《吕氏春秋·季夏》", "example": null}, {"def": "又如妨贤(阻碍贤者登进)", "example": null}, {"def": "妨碍", "example": null}, {"def": "不以小功妨大务。--《韩非子·难二》", "example": null}, {"def": "又如不妨;何妨;妨蔽(妨碍)", "example": null}, {"def": "中止", "example": null}, {"def": "丁亥", "example": null}, {"def": "妨 fáng", "example": null}, {"def": "⒈阻碍，损害～碍。～害。", "example": null}, {"def": "⒉", "example": null}, {"def": "【不妨】可以这样做，没有什么障碍不～明白说出。", "example": null}, {"def": "⒊", "example": null}, {"def": "【何妨】使用反问的语气，〈表〉\\"不妨\\"这个何～？何～去看看她？", "example": null}]','chinese-xinhua','0'),
('2101143295982833767','房','1','fánɡ','户','8',NULL,'[{"def": "房〈名〉", "example": null}, {"def": "(形声。从户,方声。上古边室皆用单扇门(即户”),庙门大门才用双扇门,故房”从户”。本义正室左右的住室)", "example": null}, {"def": "古代堂中间叫正室,两旁的叫房", "example": null}, {"def": "房,室在傍者也。--《说文》", "example": null}, {"def": "房,室旁夹室也。--《六书故》。段曰凡堂之内,中为正室,左右为房,所谓东房、西房也”。桂馥曰古者宫室之制,前堂后室。前堂之两头有夹室,后室之两旁有东西房", "example": null}, {"def": "。”", "example": null}, {"def": "记宰夫宴出自东房。--《仪礼·乡食礼》", "example": null}, {"def": "在东房。--《书·顾命》", "example": null}, {"def": "鄐子登,妇人笑于房。--《左传·宣公十七年》", "example": null}, {"def": "又如厢房(正房前面两旁的房屋);房植(房室四角的柱);房", "example": null}, {"def": "房 fáng", "example": null}, {"def": "⒈室，屋～屋。草～子。高楼～。厂～。书～。", "example": null}, {"def": "⒉像房间的莲子～。蜜蜂～。左心～。右心～。", "example": null}, {"def": "⒊家族的一支长～。远～。", "example": null}, {"def": "⒋星宿名。二十八宿之一。", "example": null}, {"def": "房páng 1.见\\"阿房宫\\"。 2.见\\"房皇\\"。", "example": null}]','chinese-xinhua','0'),
('2101143295982833768','肪','1','fánɡ','月','8',NULL,'[{"def": "肪〈名〉", "example": null}, {"def": "脂肪", "example": null}, {"def": "窃见玉书,称美玉白如截肪。--曹丕《与钟大理书》", "example": null}, {"def": "也特指动物腰部肥厚的油", "example": null}, {"def": "脂在腰曰肪。--《文选》李善注引《通俗文》", "example": null}, {"def": "肪 fáng油脂，油膏或特指动物腰部肥厚的油脂～。腰～。", "example": null}]','chinese-xinhua','0'),
('2101143295982833769','鲂','1','fánɡ','鱼','12',NULL,'[{"def": "鲂", "example": null}, {"def": "魚名。鳊鱼的古称", "example": null}, {"def": "其钓维何,维鲂及鱮。--《诗·小雅·采绿》", "example": null}, {"def": "鱼名,似鳊鱼,银灰色,腹部隆起", "example": null}, {"def": "比喻人的劳苦", "example": null}, {"def": "鲂 fáng鲂鱼，与鳊鱼相似。体扁侧，银白色。头小而尖。腹部隆起。武昌鱼就是鲂鱼的一种。", "example": null}]','chinese-xinhua','0'),
('2101143295987027968','放','1','fànɡ','攵','8',NULL,'[{"def": "放〈动〉", "example": null}, {"def": "(形声。从攴,方声。本义驱逐,流放)", "example": null}, {"def": "同本义", "example": null}, {"def": "放,逐也。--《说文》", "example": null}, {"def": "见伯夷之放迹。--《楚辞·悲回风》", "example": null}, {"def": "卿大夫外淫者放。--刘向《列女传》", "example": null}, {"def": "放髈兜于崇山。--《虞书》", "example": null}, {"def": "放弑其君则残之。--《周礼·大司马》", "example": null}, {"def": "放其大夫。--《左传·襄公二十九年》", "example": null}, {"def": "齐放其大臣孟尝君于诸侯。--《战国策·齐策》", "example": null}, {"def": "虽放流,眷顾楚国,系心怀王。--《史记·屈原贾生列传》", "example": null}, {"def": "又", "example": null}, {"def": "何故怀瑾握瑜而自令见放为?", "example": null}, {"def": "又如流放(把犯人驱逐到边远地方去);放伐(以武力讨伐并放逐暴君);放徒(放野。放逐于野);放远(远逐);放废(放逐罢黜);放迁(", "example": null}, {"def": "放 fàng", "example": null}, {"def": "⒈解脱约束，获得自由解～。释～。～松。～手。〈引〉", "example": null}, {"def": "①散，耍～学回家。～暑假。～工休假。", "example": null}, {"def": "②赶牲畜或家禽到野外活动、觅食～牛儿。～羊子。～鸭。～鸽子。", "example": null}, {"def": "⒉任意，不拘束～任自流。大～厥词。～荡不羁。", "example": null}, {"def": "⒊发出，发射，点燃～电。～炮。～焰火。～火烧荒。", "example": null}, {"def": "⒋借钱财给人，收取利息～债。", "example": null}, {"def": "⒌扩大，扩展～大一寸。～宽一尺。～眼世界。〈引〉花开百花齐～。江南红梅已～春。", "example": null}, {"def": "⒍搁。置安～。存～。～在床上。", "example": null}, {"def": "⒎", "example": null}, {"def": "【放心】消除忧虑和牵挂。", "example": null}, {"def": "⒏", "example": null}, {"def": "【放晴】阴雨之后转晴。", "example": null}, {"def": "⒐", "example": null}, {"def": "【放弃】丢掉，不再保留。", "example": null}, {"def": "⒑", "example": null}, {"def": "【外放】旧时指京官调任出京任职。", "example": null}, {"def": "⒒", "example": null}, {"def": "【流放】", "example": null}, {"def": "【放逐】旧时将人驱逐到边远地区。", "example": null}, {"def": "⒓", "example": null}, {"def": "【放哨】站岗、警戒或巡逻。", "example": null}, {"def": "放fǎng 1.仿效;模拟。 2.依据。 3.仿佛，类似。 4.至，到。 5.姓。《书．尧典》有放齐。", "example": null}, {"def": "放fāng 1.并船。两船并列。 2.背逆，违背。 3.副词。正;当。", "example": null}]','chinese-xinhua','0'),
('2101143295987027969','仿','1','fǎnɡ','亻','6',NULL,'[{"def": "仿", "example": null}, {"def": "(形声。从人,方声。本义相似。或作彷”)", "example": null}, {"def": "同本义", "example": null}, {"def": "仿,相似也。--《说文》。俗亦作倣。", "example": null}, {"def": "又如仿像(仿佛相像);他俩长得相仿", "example": null}, {"def": "仿效;模仿。也作彷”、倣”", "example": null}, {"def": "见所制蜡人,悉仿生人。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "又如他们的罐子似乎是仿皮革容器制作的;仿刻(仿照原本的款式和字体刻印);仿模(模仿);仿写(模仿书写)", "example": null}, {"def": "仿", "example": null}, {"def": "供人描红的范本", "example": null}, {"def": "照着范本写的字", "example": null}, {"def": "正说得热闹", "example": null}, {"def": "仿 fǎng", "example": null}, {"def": "⒈效法，照样做～做。民相～效。", "example": null}, {"def": "⒉写字的范本或照范本写的字～本。写～。", "example": null}, {"def": "⒊", "example": null}, {"def": "【相仿】类似。", "example": null}, {"def": "⒋", "example": null}, {"def": "【仿佛】", "example": null}, {"def": "【彷彿】", "example": null}, {"def": "【髣髴】", "example": null}, {"def": "①好像，似乎你和我～佛见过面。", "example": null}, {"def": "②类似，差不多姐妹俩的长相很～佛。", "example": null}, {"def": "仿páng 1.见\\"仿佯\\"﹑\\"仿洋\\"。 2.见\\"仿偟\\"。", "example": null}, {"def": "仿bàng 1.靠在一边;在一旁。", "example": null}]','chinese-xinhua','0'),
('2101143295987027970','访','1','fǎnɡ','讠','6',NULL,'[{"def": "访", "example": null}, {"def": "(形声。从言,方声。本义广泛地征求意见)", "example": null}, {"def": "同本义", "example": null}, {"def": "詌,泛谋也。--《说文》", "example": null}, {"def": "詌,谋也。--《尔雅》", "example": null}, {"def": "王访于箕子。--《书·洪范》", "example": null}, {"def": "访予落止。--《诗·周颂·访落》", "example": null}, {"def": "受纳访--《周礼·内史》", "example": null}, {"def": "使访物官。--《国语·楚语》", "example": null}, {"def": "穆公访诸蹇叔。--《左传·僖公三十二年》", "example": null}, {"def": "又如访断(咨询决疑);访覃(问及);访讯(讯问;打听)", "example": null}, {"def": "引申为访问、拜访(敬词)", "example": null}, {"def": "此行殊访戴,自可缓归桡。--李白《陪从祖济南太守泛鹊山湖》", "example": null}, {"def": "时余方访君寓。--清·梁启超《谭嗣同传》", "example": null}, {"def": "径造庐访成。--《聊斋志异·促织》", "example": null}, {"def": "又如访", "example": null}, {"def": "访 fǎng", "example": null}, {"def": "⒈询问，调查～贫济困。查～。采～。", "example": null}, {"def": "⒉探望～亲会友。相～。探～。拜～。〈引〉寻求～求。", "example": null}, {"def": "⒊查，侦察明察暗～。", "example": null}, {"def": "⒋", "example": null}, {"def": "【访问】有目的地探望～问水稻专家。", "example": null}]','chinese-xinhua','0'),
('2101143295987027971','纺','1','fǎnɡ','纟','7',NULL,'[{"def": "纺", "example": null}, {"def": "(形声。从糸,方声。本义将丝麻纤维制成纱或线)", "example": null}, {"def": "同本义", "example": null}, {"def": "纺,网丝也。--《说文》", "example": null}, {"def": "纺焉以度而去之。--《左传·昭公十九年》", "example": null}, {"def": "村南有夫妇守贫者,织纺井臼,佐读勤苦。--清·周容《芋老人传》", "example": null}, {"def": "如纺绩(纺纱与绩麻);纺手(指纺纱、纺线的人);纺缉(纺丝和缉麻)", "example": null}, {"def": "通绷”。捆绑,悬挂;束缚", "example": null}, {"def": "献子执而纺于庭之槐。--《国语·晋语》。韦昭注纺,悬也。”", "example": null}, {"def": "纺", "example": null}, {"def": "绸属;素纱", "example": null}, {"def": "宾裼,迎大夫,贿用束纺。--《仪礼·聘礼》", "example": null}, {"def": "又指平纹丝绸织物。如纺绸(丝织品名。质地柔", "example": null}, {"def": "纺 fǎng", "example": null}, {"def": "⒈将丝、棉、麻、毛、化工纤维等制成纱或线～细纱。～毛线。", "example": null}, {"def": "⒉质地比绸子轻薄的丝织物或绸子的一种～绸。蜀～。", "example": null}, {"def": "纺bǎng 1.悬空绑着;捆缚。", "example": null}]','chinese-xinhua','0'),
