('2101143295987027983','方','1','fānɡ','方','4',NULL,'[{"def": "方〈动〉", "example": null}, {"def": "(象形。下从舟省,而上有竝头之象。故知并船为本义。本义并行的两船;泛指并列;并行)", "example": null}, {"def": "同本义", "example": null}, {"def": "方,併船也。象两舟总头形。--《说文》", "example": null}, {"def": "大夫方舟。--《尔雅》。李注竝两船曰方舟。”", "example": null}, {"def": "方舟而济于河。--《庄子·山木》", "example": null}, {"def": "不足方。--《仪礼·乡射礼》。注犹併也。”", "example": null}, {"def": "方舟设泭。--《国语·齐语》", "example": null}, {"def": "江之永矣,不可方思。--《诗·周南·汉广》", "example": null}, {"def": "操军方连战舰,首尾相接。--《资治通鉴》", "example": null}, {"def": "蜀汉之粟,方船而下。--《史记·郦食其列传》", "example": null}, {"def": "又如方轨(两车并排行驶);方轩(并排的窗户)", "example": null}, {"def": "等同;相当", "example": null}, {"def": "方 fāng", "example": null}, {"def": "⒈四角都是直角的四边形或每个面都是直角四边形的六面体正～形。长～形。立～体。", "example": null}, {"def": "⒉正直～正。志行忠～（志行志向和行为）。", "example": null}, {"def": "⒊位置，地位上～。西北～。", "example": null}, {"def": "⒋一边或一面后～。静观对～。志在四～。〈引〉一个区域或地带地～。～言。～内安宁。", "example": null}, {"def": "⒌法子，办法～法。教子有～。〈引〉处方，药方开个～子。按～拣药。", "example": null}, {"def": "⒍副词。正，正在，正当～兴未艾。来日～长。", "example": null}, {"def": "⒎副词。刚，才～才到达。事后～知。", "example": null}, {"def": "⒏", "example": null}, {"def": "【方针】引导事业前进的指针。", "example": null}, {"def": "⒐", "example": null}, {"def": "【方略】计划和策略。", "example": null}, {"def": "⒑", "example": null}, {"def": "【方案】具体规划，实施办法或规定。", "example": null}, {"def": "⒒", "example": null}, {"def": "【方向】", "example": null}, {"def": "①东西南北等区域的划分。", "example": null}, {"def": "②目标做事要看清～向。", "example": null}, {"def": "⒓一个数目的自乘平～（本数乘本数）。立～（本数乘本数乘本数）。", "example": null}, {"def": "⒔量词。", "example": null}, {"def": "①计量面积一～（一平方米）地板。", "example": null}, {"def": "②计量体积一～（立方米）木材。五～沙子。", "example": null}, {"def": "③计算方形的东西两～砚台。", "example": null}, {"def": "⒕", "example": null}, {"def": "【方寸】一寸见方。〈喻〉人的心～寸乱矣。", "example": null}, {"def": "⒖", "example": null}, {"def": "【方圆】周围～圆十里茂竹林。", "example": null}, {"def": "⒗", "example": null}, {"def": "【方式】讲话、做事所采用的方法和形式生活～式。讲究～式方法。", "example": null}, {"def": "⒘", "example": null}, {"def": "【方程】含有未知数的等式。", "example": null}, {"def": "方fáng 1.通\\"房\\"。谷物初生尚未结实之谓。 2.通\\"防\\"。防御。", "example": null}, {"def": "方páng 1.通\\"旁\\"。广大;广博。 2.指遍及。 3.见\\"方羊\\"。 4.见\\"方皇\\"。", "example": null}, {"def": "方wǎng 1.见\\"方良\\"。", "example": null}, {"def": "方fēng 1.响度级单位。用方表示的声音的响度级，数值上等于根据人耳判断为等响的1000赫纯音的声压级的分贝数。", "example": null}]','chinese-xinhua','0'),
('2101143295987027984','邡','1','fānɡ','阝','6',NULL,'[{"def": "什邡”(县)县名,在四川德阳", "example": null}, {"def": "邡 fāng什～市，在四川省。", "example": null}, {"def": "邡fǎng 1.谋划。", "example": null}]','chinese-xinhua','0'),
('2101143295987027985','坊','1','fānɡ','土','7',NULL,'[{"def": "坊〈名〉", "example": null}, {"def": "(形声。从土,方声。本义城市中街市里巷的通称)", "example": null}, {"def": "古代把一个城邑划分为若干区,通称为坊", "example": null}, {"def": "两京及州县之郭内为坊,郊外为村。--《唐元典》", "example": null}, {"def": "坊隅众人,慌忙拢来。--《水浒传》", "example": null}, {"def": "又如坊隅(街巷,街坊);坊厢(古代城市区划,城中曰坊,近城曰厢);坊市(街市);坊郭(城郭市街)", "example": null}, {"def": "官署名", "example": null}, {"def": "明年春,大疫,为病坊,处疾病之无归者。--宋·曾巩《越州赵公救灾记》", "example": null}, {"def": "又如坊局(詹事府属下的左、右春坊和司经局的合称)", "example": null}, {"def": "牌坊", "example": null}, {"def": "坊 fāng", "example": null}, {"def": "⒈街、村的统称。也用作街巷、里弄的名称街～。村～。窄～子。", "example": null}, {"def": "⒉街市里的店铺茶～。", "example": null}, {"def": "⒊牌坊,旧时统治阶级为表\\"功德\\"或宣扬封建礼教而造的建筑物多用石建成功德～。孝女牌～。", "example": null}, {"def": "坊 fáng工场，有些小工业者的工作场所作～。磨粉～。榨油～。", "example": null}]','chinese-xinhua','0'),
('2101143295987027986','芳','1','fānɡ','艹','7',NULL,'[{"def": "芳〈名〉", "example": null}, {"def": "(形声。从苃,方声。本义花草)", "example": null}, {"def": "同本义", "example": null}, {"def": "野芳发而幽香。--宋·欧阳修《醉翁亭记》", "example": null}, {"def": "又如芳芷(香草名);芳苓(芳荃。香草名);芳草(香草)", "example": null}, {"def": "香气", "example": null}, {"def": "芳,草香也。--《说文》", "example": null}, {"def": "芳菲菲其弥章。--《楚辞·离骚》。注香貌。”", "example": null}, {"def": "兰芝以芳未尝见霜。--《淮南子·说林》", "example": null}, {"def": "芳与泽其杂糅兮。--《楚辞·离骚》", "example": null}, {"def": "兰有莠兮菊有芳。--汉武帝《秋风辞》", "example": null}, {"def": "指春天", "example": null}, {"def": "指女子", "example": null}, {"def": "芳 fāng", "example": null}, {"def": "⒈花草的香味～香。芬～。〈喻〉美好的德行或名声万古流～。", "example": null}, {"def": "⒉花草篱边野外多众～。", "example": null}]','chinese-xinhua','0'),
('2101143295987027987','枋','1','fānɡ','木','8',NULL,'[{"def": "枋〈名〉fang", "example": null}, {"def": "枋树。木名", "example": null}, {"def": "枋,枋木也。可作车,从木,方声。--《说文》", "example": null}, {"def": "我决起而飞,枪榆枋。--《庄子·逍遥游》", "example": null}, {"def": "又如枋榆(枋树与榆树)", "example": null}, {"def": "筑堤堰用的大木桩", "example": null}, {"def": "后背洪枋巨堰,深渠高堤者也。--《水经注》", "example": null}, {"def": "泛指木棒", "example": null}, {"def": "突然,他抓起一根短短的木枋,站起来,走到柜台边。--谭秀牧《失去的黑金刚》", "example": null}, {"def": "两柱之间起联系作用的方柱形木材", "example": null}, {"def": "枋 bing", "example": null}, {"def": "古同柄”，权柄。", "example": null}, {"def": "枋 fāng", "example": null}, {"def": "⒈方柱长形的木材。", "example": null}, {"def": "⒉", "example": null}, {"def": "【枋子】棺材。", "example": null}, {"def": "枋bǐng 1.器物的把子。 2.权柄。 3.执掌。 4.量词。多用于兵器。", "example": null}]','chinese-xinhua','0'),
