('2101143295987028071','奋','1','fèn','大','8',NULL,'[{"def": "奋", "example": null}, {"def": "(会意。金文字形,中间是隹”(鸟);外面象鸟振翅欲飞之势;下面是田”,表示空旷的田野。本义鸟类振羽展翅)", "example": null}, {"def": "同本义", "example": null}, {"def": "奮,翚也。--《说文》", "example": null}, {"def": "奋隼归凫。--张衡《西京赋》", "example": null}, {"def": "羽翼奋也。--《淮南子·原道》", "example": null}, {"def": "雉绝有力奋,鸡绝有力奋。--《尔雅·释鸟》", "example": null}, {"def": "不能奋飞。--《诗·邶风·柏舟》", "example": null}, {"def": "于是宾客无不变色离席,奋袖出臂。--《虞初新志·秋声诗自序》", "example": null}, {"def": "虫暴怒,直奔,遂相腾击,振奋作声。--《聊斋志异·促织》", "example": null}, {"def": "又如奋翅(振翼起飞);奋翼(振翼高飞);奋翔(振翼高飞);奋鳞(龙腾飞);奋翮(展翅,振羽", "example": null}, {"def": "奋（奮） fèn", "example": null}, {"def": "⒈鸟类展翅～飞。", "example": null}, {"def": "⒉振作，鼓劲，拼搏～发。～斗。～起直追。发～（愤）图强。～不顾身。", "example": null}]','chinese-xinhua','0'),
('2101143295987028072','忿','1','fèn','心','8',NULL,'[{"def": "忿〈动〉", "example": null}, {"def": "(形声。从心,分声。从心”,表示与心情有关。本义愤怒,怨恨)", "example": null}, {"def": "同本义", "example": null}, {"def": "忿,悁也。--《说文》", "example": null}, {"def": "忿,怒也。--《广雅》", "example": null}, {"def": "君子以惩忿窒欲。--《易·象传》", "example": null}, {"def": "身有所忿窒。--《礼记·大学》", "example": null}, {"def": "惩违改忿兮。--《楚辞·怀沙》。注恨也。”", "example": null}, {"def": "忿慳之气。--《庄子·达生》", "example": null}, {"def": "忿,恨也,怒也。--《玉篇》", "example": null}, {"def": "伯主约而不忿。--《战国制·秦策》", "example": null}, {"def": "将不胜其忿而蚁附之。--《孙子·谋攻》", "example": null}, {"def": "吾意久怀忿,汝岂得自由。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "又如忿恨(愤怒怨恨);忿气(气愤;生气);忿怒(愤怒);忿疾(愤怒厌恶)", "example": null}, {"def": "忿 fèn怒，怨恨，生气～怒。～恨。不胜其～。～ ～（也写作\\"愤愤\\"）不平。", "example": null}]','chinese-xinhua','0'),
