('2101143295987028074','偾','1','fèn','亻','11',NULL,'[{"def": "偾", "example": null}, {"def": "(形声。从人,贲声。本义僵仆)", "example": null}, {"def": "同本义", "example": null}, {"def": "偾,僵也。--《说文》", "example": null}, {"def": "牛虽瘠,偾于豚上,其畏不死。--《左传·昭公十三年》。注偾,仆也。”", "example": null}, {"def": "一死一生,一偾一起。--《庄子·天运》", "example": null}, {"def": "又如偾仆(倒仆);偾踣(僵仆);偾蹶(颠仆)", "example": null}, {"def": "覆,翻倒在地", "example": null}, {"def": "郑伯之车偾于济。--《左传·隐公三年》", "example": null}, {"def": "又如偾辕(覆车,喻失败);偾辙(覆辙,喻失败)", "example": null}, {"def": "覆败", "example": null}, {"def": "偾军之将,蒙朝廷待以不死。--《醒世姻缘传》", "example": null}, {"def": "又如偾师(偾军。使军队覆败);偾败(覆没);偾将(败军之将)", "example": null}, {"def": "使灭亡", "example": null}, {"def": "毁坏;败坏", "example": null}, {"def": "偾 fèn", "example": null}, {"def": "⒈败坏，毁坏～事。～军之将。", "example": null}, {"def": "⒉扑倒，跌倒一～一起。", "example": null}]','chinese-xinhua','0'),
('2101143295987028075','愤','1','fèn','忄','12',NULL,'[{"def": "愤", "example": null}, {"def": "(形声。从心,贲声。从心”,表示与心情等有关。本义郁结于心;憋闷)", "example": null}, {"def": "同本义", "example": null}, {"def": "愤,懑也。--《说文》", "example": null}, {"def": "发愤以杼情。--《楚辞·九章·惜诵》", "example": null}, {"def": "志意蕴愤。--《后汉书·王符传》", "example": null}, {"def": "又如愤切(内心极度愤懑);愤悁(愤懑郁积);愤薄(郁结,充塞);愤厥(由于愤气郁结造成的痉挛昏厥)", "example": null}, {"def": "充盈,旺盛", "example": null}, {"def": "愤,盈也。--《方言十二》", "example": null}, {"def": "阳瘅愤盈。--《国语·周语》", "example": null}, {"def": "又如愤盈(充溢,积满;气愤,愤懑);愤盛(积满,充盈)", "example": null}, {"def": "愤", "example": null}, {"def": "愤怒;怨恨。同忿”", "example": null}, {"def": "所以昭炯戒,激众愤", "example": null}, {"def": "愤 fèn", "example": null}, {"def": "⒈因不满意而激动发怒～怒。气～得很。激起公～。", "example": null}, {"def": "⒉努力，进取发～（也写作\\"发奋\\"）攻书。", "example": null}]','chinese-xinhua','0'),
('2101143295987028076','粪','1','fèn','米','12',NULL,'[{"def": "粪", "example": null}, {"def": "(会意。小篆字形,从采(矢)∠起来表示双手持簸箕清除污秽。本义扫除)", "example": null}, {"def": "同本义", "example": null}, {"def": "粪,弃除也。--《说文》", "example": null}, {"def": "堂上不粪,则郊草不芸。--《荀子·强国》", "example": null}, {"def": "又如粪除(扫除);粪洒(洒扫)", "example": null}, {"def": "施肥", "example": null}, {"def": "凡粪种。--《周礼·草人》。注凡所以粪种者,皆谓煮取汁也。”", "example": null}, {"def": "却是走马以粪。--《老子》。注粪田也。”", "example": null}, {"def": "又如粪治(施肥治田);粪种(古代的一种耕种方法)", "example": null}, {"def": "粪", "example": null}, {"def": "屎,粪便", "example": null}, {"def": "一亩之稼,则粪溉者先芽。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "又如粪清(粪汁);粪溷(粪坑;厕所);马粪;牛粪;粪", "example": null}, {"def": "粪（約） fèn", "example": null}, {"def": "⒈屎，大便～便。", "example": null}, {"def": "⒉施肥～地。～田。", "example": null}, {"def": "⒊扫除～除。", "example": null}, {"def": "⒋", "example": null}, {"def": "【粪土】粪便和泥土。〈喻〉不值钱的东西，含有蔑视～土当年万户侯。", "example": null}]','chinese-xinhua','0'),
