('2101143295991222275','纷','1','fēn','纟','7',NULL,'[{"def": "纷", "example": null}, {"def": "(形声。从糸,分声。从糸”,表示与线丝等有关。本义马尾韬,扎束马尾的丝麻织物)", "example": null}, {"def": "同本义", "example": null}, {"def": "纷,马尾韬也。--《说文》。段玉裁注韬,剑衣也。引申凡为衣之称。《释名》曰‘纷,放也,防其放弛以拘之也。’”", "example": null}, {"def": "旗上的飘带", "example": null}, {"def": "青云为纷,虹霓为缳。--汉·扬雄《羽猎赋》", "example": null}, {"def": "又如佩纷(佩饰丝带)", "example": null}, {"def": "花边", "example": null}, {"def": "次席纷纯,左右玉几。--张衡《东京赋》", "example": null}, {"def": "祸乱;灾难", "example": null}, {"def": "唯天轨之不辟兮,何纯絜而离纷!--《汉书》", "example": null}, {"def": "争执;纠纷", "example": null}, {"def": "谈言微中,亦可以解纷。--《史记·滑稽列传》", "example": null}, {"def": "又如纷", "example": null}, {"def": "纷 fēn", "example": null}, {"def": "⒈众多，杂乱～至沓来。～杂的声音。～乱的人群。", "example": null}, {"def": "【纷纷】", "example": null}, {"def": "①人或事物接二连三地～ ～响应献血。", "example": null}, {"def": "②既多又杂乱议论～ ～。落叶～ ～。", "example": null}, {"def": "⒉争执～争。排难解～。", "example": null}]','chinese-xinhua','0'),
('2101143295991222276','芬','1','fēn','艹','7',NULL,'[{"def": "芬〈名〉", "example": null}, {"def": "(会意。从苃,从分,分亦声。本义香气)", "example": null}, {"def": "同本义", "example": null}, {"def": "芬,草初生其香分布也。--《说文》", "example": null}, {"def": "芬,芬香也。--《广雅》", "example": null}, {"def": "天地之行分、苦味也。--《春秋繁露》", "example": null}, {"def": "苾苾芬芬。--《诗·小雅·信南山》", "example": null}, {"def": "芬馥脄蚸。--左思《吴都赋》", "example": null}, {"def": "芳菲菲而难亏兮,芬至今犹未沬。--《楚辞·离骚》", "example": null}, {"def": "又如芬苾(芳香);芬烈(香气郁烈);芬郁(香气浓郁;亦谓芳香和腐臭)。使感到芬芳", "example": null}, {"def": "至其可人之口者,则莲实与藕皆并列盘餐而互芬齿颊者也。--明·李渔《闲情偶寄·种植部》", "example": null}, {"def": "特别好闻的香气", "example": null}, {"def": "流芬赋采,风靡云旋。--潘岳《芙蓉赋》", "example": null}, {"def": "比喻", "example": null}, {"def": "芬fēn", "example": null}, {"def": "⒈香，香气～芳。〈喻〉美名扬～千载之上。", "example": null}, {"def": "⒉通\\"fenh纷\\"。众多的样子～哉茫茫。", "example": null}]','chinese-xinhua','0'),
('2101143295991222277','氛','1','fēn','气','8',NULL,'[{"def": "氛", "example": null}, {"def": "(形声。从气,分声。本义凶气,古时迷信说法指预示吉凶的云气,多指凶气 )", "example": null}, {"def": "同本义", "example": null}, {"def": "楚氛甚恶。--《左传·襄公二十七年》", "example": null}, {"def": "台不过望氛祥。--《国语·楚语》。注凶气为氛。”", "example": null}, {"def": "氛邪岁增。--《汉书·元帝纪》。注恶气也。”", "example": null}, {"def": "环顾国内,贼氛方炽。--孙文《序》", "example": null}, {"def": "又如氛慝,氛邪(邪恶之气);氛厉(祸害之气);氛霓(凶气,妖气);氛杂(杂乱之气);氛秽(邪恶肮脏之气);氛妖(妖气)", "example": null}, {"def": "泛指雾气;云气", "example": null}, {"def": "氛雾冥冥。--《礼记·月令》", "example": null}, {"def": "寒氛结为霜雪。--《素问·", "example": null}, {"def": "氛、雰fēn", "example": null}, {"def": "⒈气。〈引〉情势或景象战～激烈。团结友好的气～。", "example": null}, {"def": "⒉雾气寒～结为霜雪。", "example": null}, {"def": "⒊", "example": null}, {"def": "【雰雰】雪下得很大的样子雨雪～ ～（雨雪下雪）。", "example": null}]','chinese-xinhua','0');
