('2101143295999610886','綘','1','fénɡ','','10',NULL,'[{"def": "綘féng", "example": null}, {"def": "⒈古同缝”。", "example": null}]','chinese-xinhua','0'),
('2101143295999610887','缝','1','fénɡ','纟','13',NULL,'[{"def": "缝", "example": null}, {"def": "(形声。从糸,表示与线丝等有关, 逢声。本义以针线连缀)", "example": null}, {"def": "同本义", "example": null}, {"def": "缝,以针紩衣也。--《说文》", "example": null}, {"def": "缝,合也。--《广雅》", "example": null}, {"def": "缝齐倍要。--《礼记·玉藻》。注紩也。”", "example": null}, {"def": "可以缝裳。--《诗·魏风·葛屦》", "example": null}, {"def": "临行密密缝。--孟郊《游子吟》", "example": null}, {"def": "又如缝衣(缝制衣服);缝刺(缝纫与刺绣);缝缉(缝纫);缝织(缝纫编织)", "example": null}, {"def": "补合", "example": null}, {"def": "缝", "example": null}, {"def": "缝合处", "example": null}, {"def": "古者冠缩缝,今也衡缝。--《礼记·檀弓》", "example": null}, {"def": "又如衣缝;裤缝;缝际(缝合之处)", "example": null}, {"def": "缝 féng用针线连缀～补。", "example": null}, {"def": "【缝纫】剪裁制做服装。", "example": null}, {"def": "缝 fèng", "example": null}, {"def": "⒈裂开的或自然显露的窄长口子一条裂～。有道～隙。墙上有～。", "example": null}, {"def": "⒉接合的地方无～钢管。这是～合口留下的痕迹。", "example": null}, {"def": "⒊空子～隙。见～插针。", "example": null}]','chinese-xinhua','0'),
('2101143295999610888','艂','1','fénɡ','','10',NULL,'[{"def": "艂féng 1.船名。", "example": null}]','chinese-xinhua','0'),
('2101143295999610889','冯','1','fénɡ','冫','5',NULL,'[{"def": "冯", "example": null}, {"def": "古地名", "example": null}, {"def": "郑于是乎伐冯、滑、胥靡,负黍、狐人、阙外。--《左传·定公六年》", "example": null}, {"def": "姓", "example": null}, {"def": "冯", "example": null}, {"def": "(形声。从马,冫声。冫,古冰字的楷书写法。本义马跑得快)", "example": null}, {"def": "同本义", "example": null}, {"def": "冯,马行疾也。--《说文》", "example": null}, {"def": "又如冯冯(马行疾速的样子)", "example": null}, {"def": "大,盛", "example": null}, {"def": "今君奋焉震电冯怒。--《左传·昭公五年》", "example": null}, {"def": "冯弱犯寡。--《周礼·大司马》", "example": null}, {"def": "帝冯怒。--《列子·汤问》", "example": null}, {"def": "又如冯戎(富盛);冯怒(盛怒,震怒);冯隆(高大的样子)", "example": null}, {"def": "冯", "example": null}, {"def": "徒步过水", "example": null}, {"def": "不敢暴虎,不敢冯河。--《诗·小雅·小昮》", "example": null}, {"def": "又如冯河(徒步渡过河水)", "example": null}, {"def": "冯 féng", "example": null}, {"def": "⒈姓。", "example": null}, {"def": "⒉〈古〉通\\"piηp凭\\"。", "example": null}, {"def": "冯píng 1.马行疾。引申为激怒，愤懑。 2.大;盛大;满。参见\\"冯怒\\"﹑\\"冯闳\\"。 3.贪得;贪求。参见\\"冯生\\"。 4.欺陵;侵侮。 5.挟持。参见\\"冯珧\\"。 6.徒涉;蹚水。", "example": null}, {"def": "7.登;乘。 8.\\"凭\\"的古字。依着;靠着。 9.\\"凭\\"的古字。亦指所靠之物。 10.\\"凭\\"的古字。凭借;依恃。 11.通\\"朋\\"。古代计算货币的单位。上古以贝壳为货币，五贝为", "example": null}, {"def": "一串，两串为一朋。", "example": null}]','chinese-xinhua','0'),
