('2101143295999610892','俸','1','fènɡ','亻','10',NULL,'[{"def": "俸〈名〉", "example": null}, {"def": "(形声。从人,奉声。本义俸禄,薪俸。旧官吏所得的薪金)", "example": null}, {"def": "同本义", "example": null}, {"def": "立名誉,以取尊官厚俸。--《韩非子·奸劫弑臣》", "example": null}, {"def": "又如厚俸;俸钱(官吏所得的薪金);俸饷(官兵的俸禄和粮饷);俸薪(年俸和月薪)", "example": null}, {"def": "旧指官吏任职的年资", "example": null}, {"def": "俸,俸秩。--《广韵》", "example": null}, {"def": "俸满,一齐转了员外。--《儒林外史》", "example": null}, {"def": "又如俸满(官吏任职满一定年限后,依例升调);俸深;俸浅(官吏担任某一职务时间较短,资历较浅)", "example": null}, {"def": "姓", "example": null}, {"def": "俸 fèng旧时指官员等所得的薪金～禄。薪～。官高厚～。", "example": null}]','chinese-xinhua','0'),
('2101143295999610893','湗','1','fènɡ','','10',NULL,'[{"def": "湗fèng 1.深泥。 2.同\\"葑\\"。菰根，即茭白根。", "example": null}]','chinese-xinhua','0'),
('2101143295999610894','凤','1','fènɡ','几','4',NULL,'[{"def": "凤", "example": null}, {"def": "(形声。从鸟,凡声。本义凤凰。中国古代传说中的百鸟之王。常用来象征祥瑞。雄的叫凤,雌的叫凰)", "example": null}, {"def": "同本义", "example": null}, {"def": "凤,神鸟也。朋,古文凤。--《说文》", "example": null}, {"def": "凤皇来仪。--《书·益稷》", "example": null}, {"def": "凤皇于飞。--《诗·大雅·卷阿》。传凤皇,灵鸟仁瑞也。雄曰凤,雌曰皇。”", "example": null}, {"def": "故鸟有凤而鱼有鲲。--宋玉《对楚王问》", "example": null}, {"def": "又如凤求凰;凤子(绣有凤凰的轿子);凤舸(雕有凤凰的大游船);凤毛(凤凰的羽毛。多用以赞美人的文采俊秀,有先人遗风)", "example": null}, {"def": "古时比喻有圣德的人", "example": null}, {"def": "潘陆张左,擅侈丽之才,饰羽仪于凤穴。--《北史·文苑传序》", "example": null}, {"def": "凤(鴓) fèng", "example": null}, {"def": "⒈", "example": null}, {"def": "【凤凰】传说中的百鸟之王。通常单称为\\"凤\\"。又说雄的叫凤，雌的叫凰（\\"凰\\"〈古〉写作\\"皇\\"）。", "example": null}, {"def": "⒉", "example": null}, {"def": "【凤毛麟角】凤凰的毛，麒麟的角。〈喻〉稀罕、珍贵的事物，也指难得的人才。", "example": null}]','chinese-xinhua','0'),
('2101143295999610895','奉','1','fènɡ','大','8',NULL,'[{"def": "奉〈动〉", "example": null}, {"def": "(会意。小篆字形,从手,从収(双手),最上面像一串玉或树盖子。是用手捧物的意思。本义两手恭敬地捧着◇作捧”)", "example": null}, {"def": "同本义", "example": null}, {"def": "奉,承也。--《说文》", "example": null}, {"def": "黔敖左奉食,右执饮。--《礼记·檀弓下》", "example": null}, {"def": "常山王奉头鼠窜。--《汉书·蒯通传》", "example": null}, {"def": "项伯即入见沛公,沛公奉卮酒为寿,约为婚姻。--《史记·项羽本纪》", "example": null}, {"def": "臣愿奉璧往使。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "荆轲奉樊於期头函,而秦武阳奉地图匣,以次进。--《战国策·燕策》", "example": null}, {"def": "又如奉书;奉地图;奉手(捧握长者之手)", "example": null}, {"def": "恭敬地接受", "example": null}, {"def": "奉 fèng", "example": null}, {"def": "⒈两手捧着臣愿～璧往使。〈引〉进献，送双手～上。～马牛。", "example": null}, {"def": "⒉恭敬地接受，遵从，遵守～命。～行。谨～法令。", "example": null}, {"def": "⒊敬词～答。～陪。～还。", "example": null}, {"def": "⒋信仰，推崇信～。～为楷模。", "example": null}, {"def": "⒌伺候，供养侍～。供～。～养。", "example": null}, {"def": "⒍", "example": null}, {"def": "【奉承】恭维，谄媚。", "example": null}]','chinese-xinhua','0'),
('2101143295999610896','蘹','1','fènɡ','','10',NULL,'[{"def": "蘹péng", "example": null}, {"def": "⒈纄”的讹字。", "example": null}]','chinese-xinhua','0'),
('2101143295999610897','讽','1','fěnɡ','讠','6',NULL,'[{"def": "讽", "example": null}, {"def": "(形声。从言,风声。本义背诵;朗读;传诵)", "example": null}, {"def": "同本义", "example": null}, {"def": "讽,诵也。--《说文》", "example": null}, {"def": "兴道讽诵言语。--《周礼·大司乐》。注倍文曰讽,以声节之曰诵。”", "example": null}, {"def": "少不讽。--《荀子·大略》。注谓就学讽诗书也。”按,诗风雅颂三类,以风为之,风借为讽。", "example": null}, {"def": "今我讽遗文,思人至其乡。--唐·白居易《游襄阳怀孟浩然》", "example": null}, {"def": "三藏就合掌讽起斋经。--《西游记》", "example": null}, {"def": "又如讽味(诵读诗文而玩索其中的意味);讽经(念经);讽书(背书);讽术(背诵经艺)", "example": null}, {"def": "婉言微辞或指责", "example": null}, {"def": "讽,谏也。--《广雅》", "example": null}, {"def": "论礼有五,谏讽为上。--《", "example": null}, {"def": "讽 fěng", "example": null}, {"def": "⒈用含蓄的话词劝告或讥刺谈笑～谏。～刺小品。挖苦讥～。", "example": null}, {"def": "⒉背书，不看着书本子念读～诵。", "example": null}]','chinese-xinhua','0'),
('2101143295999610898','唪','1','fěnɡ','口','11',NULL,'[{"def": "唪〈动〉", "example": null}, {"def": "佛教徒、道教徒大声吟诵", "example": null}, {"def": "梵策无须唪,公案何劳颂。--清·褚人获《坚瓠八集》", "example": null}, {"def": "又如唪经;唱偈(念经和吟唱佛教的颂词。偈梵文偈陀”的简称。义译为颂”);唪诵(高声吟诵)", "example": null}, {"def": "唪 fěng大声朗诵。", "example": null}, {"def": "【唪经】僧人或道徒高声念经。", "example": null}, {"def": "唪běng 1.大笑。 2.见\\"唪唪\\"。", "example": null}]','chinese-xinhua','0'),
