('2101143296003805218','怫','1','fú','忄','8',NULL,'[{"def": "怫〈名〉", "example": null}, {"def": "愤怒", "example": null}, {"def": "我怫然而怒。--《庄子·德充符》", "example": null}, {"def": "又如怫然(愤怒的样子);怫恕(愤怒);怫恚(愤怒)", "example": null}, {"def": "怫 〈动〉", "example": null}, {"def": "通悖”。违反,逆乱", "example": null}, {"def": "五家之文怫异,维太初之元论。--《史记·太史公自序》", "example": null}, {"def": "知权者不以常人怫吾虑。--柳宗元《断刑论》", "example": null}, {"def": "又如怫志(逆乱的心志)", "example": null}, {"def": "怫〈形、副〉", "example": null}, {"def": "(形声。从心,弗声。本义抑郁;心情不舒畅)", "example": null}, {"def": "同本义", "example": null}, {"def": "怫,郁也。--《说文》", "example": null}, {"def": "怫,郁也,心不安也。--《字林》", "example": null}, {"def": "太后怫郁泣血。--《汉书·邹阳传》", "example": null}, {"def": "我心何怫郁。--曹操《苦寒行》", "example": null}, {"def": "又如怫郁(忧郁)", "example": null}, {"def": "怫 fú", "example": null}, {"def": "⒈", "example": null}, {"def": "【怫郁】心情不舒畅我心何～郁（何多么）。", "example": null}, {"def": "⒉", "example": null}, {"def": "【怫然】忿怒的样子～然不悦。～然作色。", "example": null}, {"def": "怫fèi 1.见\\"怫?\\"。", "example": null}, {"def": "怫bèi 1.违反﹔悖逆。", "example": null}]','chinese-xinhua','0'),
('2101143296003805219','拂','1','fú','扌','8',NULL,'[{"def": "拂士", "example": null}, {"def": "入则无法家拂士。--《孟子·告子下》", "example": null}, {"def": "拂〈动〉", "example": null}, {"def": "(形声。从手。弗声。本义拂拭;掸除)", "example": null}, {"def": "同本义", "example": null}, {"def": "拂,过击也。--《说文》。按,随击随过,犹拍也。”", "example": null}, {"def": "拂,去也。--《广雅》", "example": null}, {"def": "授弓拂弓。--《仪礼·大射仪》。注去尘也。”", "example": null}, {"def": "和弓击摩。--《考工记·弓人》。注拂之摩之。”", "example": null}, {"def": "商祝拂柩。--《仪礼·既文礼》", "example": null}, {"def": "主人拂几。--《仪礼》", "example": null}, {"def": "以手拂之,其印自落。--宋·沈括《梦溪笔谈·活板》", "example": null}, {"def": "又如拂掉(拂杓。拂拭;扫除);拂帚(拂尘);拂子(拂尘);拂须(揩拭胡须);拂去桌上的", "example": null}, {"def": "拂 fú", "example": null}, {"def": "⒈掸，轻轻擦过～去灰尘⊥风～面。", "example": null}, {"def": "⒉甩，抖动～袖而去（〈表〉生气走开）。", "example": null}, {"def": "⒊违背，不顺～意（不满意）。", "example": null}, {"def": "⒋", "example": null}, {"def": "【拂晓】", "example": null}, {"def": "【拂晨】天快亮的时候。", "example": null}, {"def": "拂bì 1.辅佐。 2.矫正;纠正。", "example": null}, {"def": "拂pì 1.见\\"拂汨\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296003805220','服','1','fú','月','8',NULL,'[{"def": "服〈动〉", "example": null}, {"def": "(会意。古文从舟,兼做声符。本义舟两旁的夹木)", "example": null}, {"def": "服从,顺服", "example": null}, {"def": "敌已服矣。--《吕氏春秋·论威》", "example": null}, {"def": "以一服八。--《孟子·梁惠王上》", "example": null}, {"def": "以力服人者,非心服也。--《孟子·公孙丑上》", "example": null}, {"def": "当舜之时,有苗不服。--《韩非子·五蠹》", "example": null}, {"def": "授之政,西土服。--《墨子·尚贤》", "example": null}, {"def": "远人不服而不能来也。--《论语·季氏》", "example": null}, {"def": "强国请服,弱国入朝。--汉·贾谊《过秦论》", "example": null}, {"def": "又如服听(服从听命);服低(屈服;低头);服杀(折服;倾倒。杀用在动词后,表示程度深);服主(轻易服输的人);服属(顺从归属)", "example": null}, {"def": "佩服;信服;使信服", "example": null}, {"def": "服 fú", "example": null}, {"def": "⒈衣裳，衣装～装。军～。学生～。", "example": null}, {"def": "⒉穿夏～单衣。", "example": null}, {"def": "⒊做，承受，担任～务。～刑。～兵役。", "example": null}, {"def": "⒋听从，顺从～从。以理～人。口～心～。", "example": null}, {"def": "⒌习惯，适应卒（兵）不～习。水土不～。", "example": null}, {"def": "⒍吃～中药。", "example": null}, {"def": "服 fù量词。指中药，也作\\"付\\"头～药。吃两～药就会好的。", "example": null}, {"def": "服bì 1.通\\"腷\\"。郁结貌。参见\\"服臆\\"。 2.通\\"逼\\"。堵塞。", "example": null}, {"def": "服bó 1.啼呼。 2.通\\"保\\"。保卫。", "example": null}]','chinese-xinhua','0'),
