('2101143296003805222','绂','1','fú','纟','8',NULL,'[{"def": "绂", "example": null}, {"def": "(形声。从糸,表示与线丝有关。本义系印章或佩玉用的丝带。绂的颜色依官位品级而不同)", "example": null}, {"def": "同本义", "example": null}, {"def": "降尊就卑,怀玺藏绂。--《文选·张衡·西京赋》", "example": null}, {"def": "授单于印绂。--《汉书·匈奴传下》", "example": null}, {"def": "古代作祭服的蔽膝", "example": null}, {"def": "朱绂方来。--《易·困卦》", "example": null}, {"def": "绂 fú", "example": null}, {"def": "⒈〈古〉用于系挂印章或佩玉的丝带。", "example": null}, {"def": "⒉同\\"黻\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296003805223','绋','1','fú','纟','8',NULL,'[{"def": "绋", "example": null}, {"def": "乱丝", "example": null}, {"def": "绋,乱丝也。从系,弗声。--《说文》。", "example": null}, {"def": "大绳", "example": null}, {"def": "绋纚维之。--《诗·小雅·采菽》", "example": null}, {"def": "特指下葬时引柩入穴的绳索", "example": null}, {"def": "绋者,所牵持棺者也。--《白虎通》", "example": null}, {"def": "先君有所助执绋矣。--《左传·昭公三十年》", "example": null}, {"def": "助葬必执绋。--《礼记·曲礼上》", "example": null}, {"def": "通韨”。蔽膝", "example": null}, {"def": "绋者,蔽也,行以蔽前。…天子朱绋,诸侯赤绋。--《白虎通·绋冕》", "example": null}, {"def": "通绂”。系印章或佩玉的丝带。也代指官印", "example": null}, {"def": "吉疾病,上将使人加绋而封之。--《汉书·丙吉传》", "example": null}, {"def": "又如印", "example": null}, {"def": "绋 fú", "example": null}, {"def": "⒈大绳。", "example": null}, {"def": "⒉旧时特指出殡时拉引棺材所用的绳索执～（送殡）。", "example": null}]','chinese-xinhua','0'),
