('2101143296003805227','祓','1','fú','礻','9',NULL,'[{"def": "祓〈动〉", "example": null}, {"def": "(形声。从示”,表示与祭神有关。本义古代为除灾求福而举行的一种仪式)", "example": null}, {"def": "同本义", "example": null}, {"def": "祓,除恶祭也。--《说文》", "example": null}, {"def": "祓,祭也。--《尔雅·释天》", "example": null}, {"def": "祓禳于四方。--《左传·昭公十八年》", "example": null}, {"def": "王其祗祓监农不易。--《国语·周语》", "example": null}, {"def": "帝祓霸上。--《汉书·外戚传上》", "example": null}, {"def": "又如祓楔(古代春秋两季在水边举行的祈求福佑的祭礼);祓禳(除凶之祭);祓殡(祭于殡以除凶邪)", "example": null}, {"def": "清除;消除", "example": null}, {"def": "祓fú〈古〉迷信者的习俗，用斋戒沐浴等方法所谓\\"求福消灾\\"。〈引〉清除。", "example": null}, {"def": "祓fèi 1.汉代侯国名。在今山东省胶州市西南。", "example": null}]','chinese-xinhua','0'),
('2101143296003805228','罘','1','fú','罒','9',NULL,'[{"def": "罘", "example": null}, {"def": "捕兔网。泛指狩猎用的网", "example": null}, {"def": "举趾触罘羋。--《后汉书·寇荣传》", "example": null}, {"def": "羋罘罗网。--《吕氏春秋·季春纪》。注罘,射鹿罟也。", "example": null}, {"def": "解罘放麟。--汉·张衡《东京赋》", "example": null}, {"def": "又如罘罕(泛指罗网);罘罟(泛指罗网);罘网(泛指渔猎用网);罘羜(设在屋檐或窗上以防鸟雀的金属网或丝网)", "example": null}, {"def": "罘 fú", "example": null}, {"def": "⒈", "example": null}, {"def": "【罘羜】\\"羓羜\\"", "example": null}, {"def": "①〈古〉设在屋檐下防鸟雀的网。", "example": null}, {"def": "②〈古〉设在宫门外或城角的屏风，上有孔，形状似网，用于守望和防卫。", "example": null}, {"def": "⒉", "example": null}, {"def": "【芝（之）罘山】靠渤海，在山东省。", "example": null}]','chinese-xinhua','0'),
('2101143296003805229','茯','1','fú','艹','9',NULL,'[{"def": "茯苓", "example": null}, {"def": "茯 fú", "example": null}, {"def": "【茯苓】［茯灵］寄生在松树根上的一种菌类植物，现可人工培植。团块状，像番薯，外皮黑褐色，有皱纹，内部白色或粉红色，有红筋。包含松根的叫茯神。供药用，也可食", "example": null}, {"def": "用。", "example": null}]','chinese-xinhua','0'),
('2101143296003805230','郛','1','fú','阝','9',NULL,'[{"def": "郛〈名〉", "example": null}, {"def": "(形声。从邑,孚声。从邑”表示与城郭有关。本义外城,古代指城圈外围的大城) 同本义", "example": null}, {"def": "郛,郭也。字亦作垺。--《说文》", "example": null}, {"def": "城卫楚丘之郛。--《左传·僖公十二年》", "example": null}, {"def": "城成郛。--《左传·襄公十五年》", "example": null}, {"def": "伐宋,入其郛。--《左传·隐公五年》", "example": null}, {"def": "又如郛郭(外城。比喻保障)", "example": null}, {"def": "郛 fú〈古〉称城圈外围的城。", "example": null}]','chinese-xinhua','0'),
