('2101143296007999493','赋','1','fù','贝','12',NULL,'[{"def": "赋", "example": null}, {"def": "(形声。从贝,武声。从贝”,表示与财物有关。本义征收)", "example": null}, {"def": "同本义", "example": null}, {"def": "赋,敛也。--《说文》", "example": null}, {"def": "赋,税也。--《广雅》", "example": null}, {"def": "厥赋惟上上错。--《书·禹贡》。传谓土地所生,以供天子。”", "example": null}, {"def": "七赋之所养。--《法言·问道》", "example": null}, {"def": "而令贡赋。--《小司徒》。注谓出车徒给徭役也。”", "example": null}, {"def": "太医以王命聚之,岁赋其二。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "又如赋银(征收税银);赋粟(征收田赋);赋里(征收商业税);赋币(征收财物)", "example": null}, {"def": "缴纳赋税", "example": null}, {"def": "讼者平,赋者均。--唐·柳宗元《送薛存义序》", "example": null}, {"def": "又如赋金(交纳税款)", "example": null}, {"def": "给予;授予", "example": null}, {"def": "赋 fù", "example": null}, {"def": "⒈赋税。旧时指田地税，各种捐税田～。薄～敛，则民富矣（薄减轻。敛征收）。", "example": null}, {"def": "⒉授予，给予～于。", "example": null}, {"def": "⒊一种文体，有韵，介于诗和散文之间诗词歌～。《风～》。《赤壁～》。", "example": null}, {"def": "⒋念诗或作诗临清流而～诗。", "example": null}]','chinese-xinhua','0'),
('2101143296007999494','椱','1','fù','','12',NULL,'[{"def": "椱fù 1.织机上卷丝织品的轴。", "example": null}]','chinese-xinhua','0'),
('2101143296007999495','缚','1','fù','纟','13',NULL,'[{"def": "缚", "example": null}, {"def": "(形声。从糸,表示与线丝或缠织等有关。尃声。本义捆绑)", "example": null}, {"def": "同本义", "example": null}, {"def": "缚,束也。--《说文》", "example": null}, {"def": "战之明日,晋襄公缚秦囚。--《左传·文公二年》", "example": null}, {"def": "主缚者亦然,不如所欲,缚时即先折筋骨。--清·方苞《狱中杂记》", "example": null}, {"def": "又如缚人(捆绑人);缚绑(捆绑);缚住(捆住);缚虎(捆住猛虎。比喻征服极难征服之人);缚送(捆住押送);缚扎(捆扎)", "example": null}, {"def": "约束;限制", "example": null}, {"def": "缚", "example": null}, {"def": "绳索", "example": null}, {"def": "夜半,童自转,以缚即炉火烧绝之。--唐·柳宗元《童区寄传》", "example": null}, {"def": "又如释缚(解缚。解绳)", "example": null}, {"def": "量词。用", "example": null}, {"def": "缚 fù缠束，捆绑束～。～鸡。", "example": null}]','chinese-xinhua','0'),
('2101143296007999496','腹','1','fù','月','13',NULL,'[{"def": "腹〈名〉", "example": null}, {"def": "(形声。从肉,复声。此为后起形声字,初文应即畐”字,象人腹部之形。本义肚子)", "example": null}, {"def": "同本义", "example": null}, {"def": "腹,厚也。--《说文》。按,脐上下两旁也。", "example": null}, {"def": "坤为腹。--《易·说卦传》", "example": null}, {"def": "入于左腹。--《易·明夷》", "example": null}, {"def": "腹者至阴之所居。--《素问·评热病论》", "example": null}, {"def": "自脐以下曰水腹。--《释名》", "example": null}, {"def": "腹饥不得食。--晁错《论贵粟疏》", "example": null}, {"def": "又如腹痛(肚子痛);腹肠(肚肠,肚子);腹围(腰带);腹如垂瓠(形容肚皮松瘪难看);腹便便(形容肚子肥满)", "example": null}, {"def": "比喻中央部分", "example": null}, {"def": "腹 fù", "example": null}, {"def": "⒈肚子。躯干的一部分，在胸部之下～部。～直肌。～背（前后）受敌。", "example": null}, {"def": "⒉", "example": null}, {"def": "【腹地】", "example": null}, {"def": "①内地。", "example": null}, {"def": "②客运、货运集散的中部地区。", "example": null}]','chinese-xinhua','0'),
('2101143296007999497','鲋','1','fù','鱼','13',NULL,'[{"def": "鲋", "example": null}, {"def": "鲫鱼", "example": null}, {"def": "蛤蟆", "example": null}, {"def": "井谷射鲋。--《易·井》", "example": null}, {"def": "鲋 fù古书上指鲫鱼。", "example": null}]','chinese-xinhua','0'),
