('2101143296007999508','腐','1','fǔ','肉','14',NULL,'[{"def": "腐〈动〉", "example": null}, {"def": "(形声。从肉,府声。本义腐烂变质)", "example": null}, {"def": "同本义", "example": null}, {"def": "腐,烂也。--《说文》", "example": null}, {"def": "腐,败也。--《广雅》", "example": null}, {"def": "人死,五藏腐朽。--汉·王充《论衡·订鬼篇》", "example": null}, {"def": "流水不腐。--《吕氏春秋·尽数》", "example": null}, {"def": "肉腐出虫,鱼枯生蠹。--《荀子·劝学》", "example": null}, {"def": "又如腐散(腐烂消散);腐坏(腐烂损坏);腐秽(腐烂肮脏);腐浊(腐臭浑浊)", "example": null}, {"def": "通拊”。拍;击", "example": null}, {"def": "此臣之日夜切齿腐心也,乃今得闻教!--《史记·刺客传》", "example": null}, {"def": "腐〈形〉", "example": null}, {"def": "指思想或文章陈旧、古板", "example": null}, {"def": "为天下安用腐儒?--《史记·黥布列传》", "example": null}, {"def": "又如腐板(迂腐古板);腐俗(陈腐", "example": null}, {"def": "腐 fǔ", "example": null}, {"def": "⒈烂，臭败～烂。～臭。～朽。流水不～。〈引〉思想陈旧，行为堕落，生活糜烂～儒。陈～。迂～。～败。严惩贪污～化。", "example": null}, {"def": "⒉豆制食品豆～。～乳。", "example": null}, {"def": "⒊", "example": null}, {"def": "【腐蚀】物体因化学作用而受到损坏的现象。〈喻〉使人逐渐腐化堕落。", "example": null}]','chinese-xinhua','0'),
('2101143296007999509','腑','1','fǔ','月','12',NULL,'[{"def": "腑〈名〉", "example": null}, {"def": "(形声。从肉,府声。本义腑脏)", "example": null}, {"def": "中医以胃、胆、膀胱、三焦、大小肠的总称", "example": null}, {"def": "六府。谓大肠、小肠、胃、膀胱、三焦、胆也。府者,为五藏宫府也。俗字作腑。--《白虎通·性情》", "example": null}, {"def": "又如腑脏(中医对人体内部器官的总称)", "example": null}, {"def": "喻内心,心怀", "example": null}, {"def": "腑〈形〉", "example": null}, {"def": "腐烂的", "example": null}, {"def": "腑 fǔ脏腑，中医对人体内脏的总称。心、肝、脾、肺、肾称脏，胆、胃、大肠、小肠、三焦、膀胱称腑，统称\\"五脏六腑\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296007999510','滏','1','fǔ','氵','13',NULL,'[{"def": "滏〈名〉", "example": null}, {"def": "古水名。即今滏阳河。源出河北省磁县西北石鼓山", "example": null}, {"def": "滏水出焉。--《山海经》", "example": null}, {"def": "滏 fǔ滏阳河，在河北省。", "example": null}]','chinese-xinhua','0'),
('2101143296007999511','辅','1','fǔ','车','11',NULL,'[{"def": "辅", "example": null}, {"def": "(形声。从车,甫声。本义车旁横木。辅所以益辐,使之能重载)", "example": null}, {"def": "同本义", "example": null}, {"def": "輔,人颊车也。--《说文》。按,当作木夹车也。", "example": null}, {"def": "若车之有辅。--《吕氏春秋·权勋》", "example": null}, {"def": "辅,小木。--《尔雅》。按,车辅木之小者。", "example": null}, {"def": "其车既载,乃弃尔辅。--《诗·小雅·正目》", "example": null}, {"def": "又如辅材(制作车轮外旁夹毂的直木材料)", "example": null}, {"def": "助手", "example": null}, {"def": "夫将者国之辅也。--《孙子·谋攻》", "example": null}, {"def": "面颊", "example": null}, {"def": "谚所谓辅车相依,唇亡齿寒”者,其虞、虢之谓也。--《左传·僖公五年》。杜预注辅,颊辅;车,牙车。”", "example": null}, {"def": "又如辅牙(颊辅和牙床。比喻相互", "example": null}, {"def": "辅 fǔ", "example": null}, {"def": "⒈车轮外的两个直条，用以增强车辐的承载力。〈引〉帮助，协助～助。～导有方。相～相成。", "example": null}, {"def": "⒉面颊小儿丰颊～。又指颊骨～车相依（车牙床。颊骨与牙床互相依靠。〈喻〉互相依存）。", "example": null}, {"def": "⒊", "example": null}, {"def": "【辅音】 也叫\\"子音\\"。发音时，从肺里出来的气，经口腔或鼻腔受到障碍所成的音。拼音字母b、c、d、g等都是辅音。", "example": null}]','chinese-xinhua','0'),
('2101143296007999512','椨','1','fǔ','','10',NULL,'[{"def": "椨fǔ 1.日本和字。", "example": null}]','chinese-xinhua','0'),
('2101143296007999513','焤','1','fǔ','','10',NULL,'[{"def": "焤fǔ", "example": null}, {"def": "⒈古同腐”。", "example": null}]','chinese-xinhua','0'),
('2101143296007999514','抚','1','fǔ','扌','7',NULL,'[{"def": "扶〈动〉", "example": null}, {"def": "(形声。从手,夫声。从手”,表示与手的动作有关。本义搀扶)", "example": null}, {"def": "同本义", "example": null}, {"def": "危而不持,颠而不扶,则将焉用彼相矣?--《论语·季氏》", "example": null}, {"def": "车至门扶。--《战国策·卫策》。注扶,谓下车。”", "example": null}, {"def": "遂扶以下。--《左传·宣公二年》", "example": null}, {"def": "扶杖望朱砂庵而登。--《徐霞客游记·游黄山记》", "example": null}, {"def": "又如扶绰(搀扶,扶托);扶策(扶助,搀扶);扶掖(搀扶;扶助);扶挈(以手搀扶);扶将(搀扶)", "example": null}, {"def": "扶持;护持", "example": null}, {"def": "蓬生麻中,不扶而直。--《荀子·劝学》", "example": null}, {"def": "又如扶树(扶持培植);扶舁(扶持;搀扶);扶舁(护持扛抬);扶倾(扶", "example": null}, {"def": "抚（撫） fǔ", "example": null}, {"def": "⒈扶持，保护，养育～养。～育。～其老弱。", "example": null}, {"def": "⒉慰问～恤。安～。优～。", "example": null}, {"def": "⒊按摩，轻轻地摸～摩。～摸。", "example": null}, {"def": "⒋拍，击～背。～掌欢笑。", "example": null}, {"def": "抚mó 1.仿效。 2.临摹。", "example": null}]','chinese-xinhua','0'),
('2101143296007999515','甫','1','fǔ','用','7',NULL,'[{"def": "甫〈名〉", "example": null}, {"def": "(象形。甲骨文字形,象田中有菜苗之形。金文字形,变为从田父声的形声字。本义苗)", "example": null}, {"def": "中国古代对男子的美称。多用于表字之后", "example": null}, {"def": "甫,男子美称也。--《说文》", "example": null}, {"def": "保兹天子,生仲山甫。--《诗·大雅·丞民》", "example": null}, {"def": "天启壬戌秋日,虞山王毅叔远甫刻。--明·魏学洢《核舟记》", "example": null}, {"def": "又如台甫(敬辞,旧时用于问人的表字)", "example": null}, {"def": "通父”。对男性长辈的通称,犹父老", "example": null}, {"def": "曰伯某甫,仲叔季唯所当。--《仪礼·士冠礼》", "example": null}, {"def": "忽兹遇众甫,欲彀羞断弦。--宋·叶适文", "example": null}, {"def": "又如众甫(各位父老)", "example": null}, {"def": "通圃”(鎑??)。种植果木瓜菜的园地", "example": null}, {"def": "甫 fǔ", "example": null}, {"def": "⒈才，刚刚年～八岁。", "example": null}, {"def": "⒉〈古〉在男子的名字下面所加的美称，又写作\\"父\\"◇来尊称别人的字号叫\\"台甫\\"。", "example": null}, {"def": "甫bǔ 1.见\\"甫田\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296007999516','府','1','fǔ','广','8',NULL,'[{"def": "府〈名〉", "example": null}, {"def": "(形声。从广,表示与房屋有关,付声。本义府库,府藏。古时国家收藏文书或财物的地方)", "example": null}, {"def": "同本义", "example": null}, {"def": "府,文书藏也。--《说文》", "example": null}, {"def": "开府库,出币帛。--《淮南子·时则》", "example": null}, {"def": "在府言府。--《礼记·曲礼》", "example": null}, {"def": "籍吏民,封府库,而待将军。--《史记·项羽本纪》", "example": null}, {"def": "以问公卿,亦以为虚费府帑。--《汉书·匈奴传》", "example": null}, {"def": "遇有水旱疾疫,则开仓廪悉府库以赈之。--清·洪亮吉《治平篇》", "example": null}, {"def": "又如府室(国家书库);府库(官府储存财物、兵甲的仓库);府实(府库中的财物);府帑(国库;国库所藏的金帛);府钱(府库的钱财)", "example": null}, {"def": "古代管理财货或文书的官吏", "example": null}, {"def": "府 fǔ", "example": null}, {"def": "⒈官署的通称，现指国家政权机关官～。政～。", "example": null}, {"def": "⒉旧指贵族或高级官员的住宅，现也称某些国家元首的住地王～。丞相～。总统～。", "example": null}, {"def": "⒊〈古〉行政区域名，等级在省与县之间京兆～。成都～。", "example": null}, {"def": "⒋储藏文书或财物的地方～库。仓～。天～（〈喻〉物产富饶的地方）之国。", "example": null}, {"def": "⒌事物或人物汇集的地方乐～。学～。", "example": null}, {"def": "⒍", "example": null}, {"def": "【府上】尊称别人的住宅、家庭或籍贯。", "example": null}]','chinese-xinhua','0'),
