('2101143296007999566','嘎','1','ɡā','口','14',NULL,'[{"def": "嘎", "example": null}, {"def": "(形声。从口,戛声。象声词) 形容短促而响亮的声音", "example": null}, {"def": "嘎巴", "example": null}, {"def": "嘎巴", "example": null}, {"def": "瞧,浆糊都嘎巴在你袖子上了", "example": null}, {"def": "嘎噔", "example": null}, {"def": "猛听得嘎噔一声,弓弦断了", "example": null}, {"def": "听到获奖的消息我心里嘎噔一震,再也无法平静", "example": null}, {"def": "嘎嘎", "example": null}, {"def": "咬咬嘎嘎水禽声,露松阴满院清。--唐·李山甫《方干隐居》", "example": null}, {"def": "嘎啦", "example": null}, {"def": "嘎啦一声响雷", "example": null}, {"def": "嘎gā", "example": null}, {"def": "⒈像声词。", "example": null}, {"def": "⒉", "example": null}, {"def": "①粘东西凝结在物体上。", "example": null}, {"def": "②凝结在物体上的东西这件衣服上有几个～巴儿。", "example": null}, {"def": "⒊", "example": null}, {"def": "①疮伤结的痂伤～渣。", "example": null}, {"def": "②食物烤黄的焦皮饭～渣儿。", "example": null}, {"def": "嘎gá", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉像嘎嘎的～～枣。", "example": null}, {"def": "嘎gǎ同\\"ga玽\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296007999567','旮','1','ɡā','日','6',NULL,'[{"def": "旮旮旯旯儿", "example": null}, {"def": "找遍了旮旮旯旯儿也没有找到丢失的东西", "example": null}, {"def": "旮旯", "example": null}, {"def": "从山旮旯来的孩子", "example": null}, {"def": "又如背旮旯", "example": null}, {"def": "旮旯儿", "example": null}, {"def": "每一个旮旯儿都打扫干净了", "example": null}, {"def": "解扣松裙,在炕旮旯里换上。--《儿女英雄传》", "example": null}, {"def": "炕旮旯儿", "example": null}, {"def": "旮gā", "example": null}, {"def": "①角落墙～旯子。屋～旯儿。", "example": null}, {"def": "②偏僻的地方岩～旯子∮～旯儿。", "example": null}]','chinese-xinhua','0'),
('2101143296007999568','伽','1','ɡā','亻','7',NULL,'[{"def": "伽--译音用字。如伽马射线", "example": null}, {"def": "伽利略", "example": null}, {"def": "使用科学实验和数学分析相结合的方法研究惯性运动、落体运动,为牛顿的第一、第二运动定律提供了启示。他推翻了亚里士多德关于不同重量的物体下落速度不同的论点。因", "example": null}, {"def": "为他支持和阐明哥白尼的地动说,1633 年被罗马教廷宗教裁判所判处 8 年软禁。但他在监狱中仍继续进行研究活动。1983 年罗马教廷正式承认 350 年前宗教裁判所对伽利略", "example": null}, {"def": "的审判是错误", "example": null}, {"def": "伽gā", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见jiā 、qié。", "example": null}, {"def": "伽jiā", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见gā、qié。", "example": null}, {"def": "伽qié", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296007999569','呷','1','ɡā','口','8',NULL,'[{"def": "呷", "example": null}, {"def": "鸭叫声", "example": null}, {"def": "笑声", "example": null}, {"def": "采樵人鼓掌呷呷笑。--元·关汉卿《鲁斋郎》", "example": null}, {"def": "呷xiā小口喝～茶。请～口酒。", "example": null}, {"def": "呷gā 1.象声词。鸭叫声。参见\\"呷呷\\"。 2.象声词。笑声。参见\\"呷呷\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296007999570','丐','1','ɡài','一','4',NULL,'[{"def": "丐", "example": null}, {"def": "乞求,乞讨", "example": null}, {"def": "求愿曰匃。--《通俗文》", "example": null}, {"def": "匃,求也。--《广雅》", "example": null}, {"def": "不强丐。--《左传·昭公六年》", "example": null}, {"def": "毋或匄夺。--《左传·昭公十六年》", "example": null}, {"def": "丐沐沐我。--《史记·外戚世家》", "example": null}, {"def": "丐,乞也。--《字汇》", "example": null}, {"def": "不抽屋,不强丐。--《左传·昭公六年》", "example": null}, {"def": "又如丐饭;丐物;丐食;丐计(乞求计策);丐施(乞求布施);丐贷(乞贷);丐养(给人收养为义子)", "example": null}, {"def": "求,请求", "example": null}, {"def": "邹君海滨,以所辑黄花冈烈士事略丐序于予。--孙文《序》", "example": null}, {"def": "又如丐命(乞命。请求饶命);丐祠(请求奉祠);丐退(请求辞职);丐留(请求留任);丐贷(请求借贷)", "example": null}, {"def": "丐gài", "example": null}, {"def": "⒈乞求，乞讨。", "example": null}, {"def": "⒉施予，给予。", "example": null}]','chinese-xinhua','0'),
