('2101143296007999577','戤','1','ɡài','戈','13',NULL,'[{"def": "戤", "example": null}, {"def": "以实物抵押", "example": null}, {"def": "倚;靠", "example": null}, {"def": "戤〈形〉", "example": null}, {"def": "为冒牌图利而制造", "example": null}, {"def": "戤gài", "example": null}, {"def": "⒈旧时指冒充或仿造别家的牌号，借以图利影～。", "example": null}, {"def": "⒉〈方〉倚靠，依仗～在壁上。～牌头（指依仗别人的势力）。", "example": null}]','chinese-xinhua','0'),
('2101143296012193792','概','1','ɡài','木','13',NULL,'[{"def": "概", "example": null}, {"def": "(形声。从木,既声。本义量米粟时刮平斗斛用的木板。量米粟时,放在斗斛上刮平,不使过满)", "example": null}, {"def": "同本义", "example": null}, {"def": "同权槩而就衡。--《楚辞·惜誓》", "example": null}, {"def": "斛甬,正权概。--《礼记·月令》", "example": null}, {"def": "槩者,平量者也。--《韩非子·外储说》", "example": null}, {"def": "又如概量(概和斗斛等量谷物的器具)", "example": null}, {"def": "节操,风度", "example": null}, {"def": "而不概于王心邪。--《史记·范雎传》。按,平也。", "example": null}, {"def": "夫西河魏土……漂然皆有节概,知去就之分。--《汉书·杨敞传》附杨恽《报孙会宗书》", "example": null}, {"def": "又如概尚(气节);气概(人遇事表现出来的态度、气势)", "example": null}, {"def": "景象;状况", "example": null}, {"def": "故山多药物,胜概(美丽的景象)", "example": null}, {"def": "概gài", "example": null}, {"def": "⒈大略，总括～论。～要。～括。", "example": null}, {"def": "⒉气度，节操气～。节～±爽有风～。", "example": null}, {"def": "⒊状况，景象～况。梗～。胜～。", "example": null}, {"def": "⒋一律一～。～不例外。", "example": null}, {"def": "⒌旧时量粮时，刮平斗、斛用的木板～者，平量也。", "example": null}, {"def": "⒍", "example": null}, {"def": "。", "example": null}]','chinese-xinhua','0'),
