('2101143296012193853','肝','1','ɡān','月','7',NULL,'[{"def": "肝", "example": null}, {"def": "(形声。从肉,干声。本义肝脏)", "example": null}, {"def": "同本义", "example": null}, {"def": "肝,木藏也。--《说文》", "example": null}, {"def": "肝,榦也。于五行属木,故其体状有枝干。--《释名·释形体》", "example": null}, {"def": "赞以肝从。--《仪礼·士昏礼》", "example": null}, {"def": "祭先肝。--《礼记·月令》", "example": null}, {"def": "吾师肺肝,皆铁石所铸造也。--清·方苞《左忠毅公逸事》", "example": null}, {"def": "又如肝肺(肝与肺);肝鬲(体内的肝和膈。鬲,通膈”,即横膈膜);肝脑(肝与脑);肝木(即肝。中医以五行之说释五脏,肝属木,故称)", "example": null}, {"def": "比喻人的内心", "example": null}, {"def": "聊为《义鹘行》,永激壮士肝。--唐·杜甫《义鹘行》", "example": null}, {"def": "又如肝怀(内心);肝心(比喻人的内心);肝血(比喻赤诚之心);肝脾(比", "example": null}, {"def": "肝gān", "example": null}, {"def": "⒈肝脏，人和高等动物重要器官之一。人的肝脏在腹腔右上部。它是体内物质代谢的中心，具有分泌、排泄胆汁，消化食物，解毒，免疫等多种功能。", "example": null}, {"def": "⒉", "example": null}, {"def": "①真心诚意～胆相照（真诚相处）。", "example": null}, {"def": "②勇气～胆过人。", "example": null}]','chinese-xinhua','0'),
('2101143296012193854','坩','1','ɡān','土','8',NULL,'[{"def": "坩", "example": null}, {"def": "盛物的陶器", "example": null}, {"def": "侃少为寻阳县吏,尝监鱼梁,以一坩鮳遗母。--《晋书》", "example": null}, {"def": "坩埚", "example": null}, {"def": "坩gān", "example": null}, {"def": "⒈陶土制做的盛物器。", "example": null}, {"def": "⒉", "example": null}, {"def": "①化学实验室用来熔融或烧灼的一种器皿，常以瓷土、镍、银、铂、石英或玻璃等制成。", "example": null}, {"def": "②工业上用来熔化金属或其它物质的器皿，多以耐火粘土或石墨等制成。", "example": null}]','chinese-xinhua','0'),
('2101143296012193855','泔','1','ɡān','氵','8',NULL,'[{"def": "泔〈名〉", "example": null}, {"def": "淘米水,洗过米的水", "example": null}, {"def": "周谓潘曰泔。从水,甘声,淅米汁也。--《说文》", "example": null}, {"def": "有水浊如泔。--苏轼《东湖》", "example": null}, {"def": "泔gān泔水，淘米留下的水。〈引〉洗过碗或洗过菜等的脏水洗碗～。", "example": null}, {"def": "泔hàn 1.见\\"泔淡\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296012193856','苷','1','ɡān','艹','8',NULL,'[{"def": "苷〈名〉", "example": null}, {"def": "甘草", "example": null}, {"def": "苷,甘草也。从苃,从甘,会意。甘亦声。--《说文》", "example": null}, {"def": "美丹,甘草也。--《广雅》", "example": null}, {"def": "甘草主生肉之药。--《淮南子·览冥》", "example": null}, {"def": "即糖苷", "example": null}, {"def": "苷", "example": null}, {"def": "苷gān", "example": null}, {"def": "⒈甘草，药草名。", "example": null}, {"def": "⒉甙的别称。见\\"dài甙\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296012193857','柑','1','ɡān','木','9',NULL,'[{"def": "柑〈名〉", "example": null}, {"def": "(形声。从木,甘声。本义木名,柑树,果实也称柑) 同本义", "example": null}, {"def": "丛生。果扁圆形,红色或橙黄色,中心柱大,味酸甜不一。种子多为多胚性。性较耐寒。用嫁接、压条、实生等法繁殖。果供生食或加工,果皮、核、叶供药用。亦指柑树的果实。", "example": null}, {"def": "如柑酒(以柑子为原料酿的酒)", "example": null}, {"def": "柑gān常绿灌木或小乔木，初夏开白花，果实球形，比橘子大，橙黄色，果皮较粗厚，种类很多。果实叫～子，可食。果皮可供药用。", "example": null}, {"def": "柑qián 1.见\\"柑马\\"。 2.闭。参见\\"柑口\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296012193858','竿','1','ɡān','竹','9',NULL,'[{"def": "竿〈名〉", "example": null}, {"def": "(形声。从竹,干声。本义竹竿)", "example": null}, {"def": "同本义。竹子的主干", "example": null}, {"def": "竿,竹梃也。--《说文》", "example": null}, {"def": "籫籫竹竿。--《诗·卫风·竹竿》", "example": null}, {"def": "禁藏母拊竿。--《管子》", "example": null}, {"def": "竿殳之所搉毕。--张衡《西京赋》", "example": null}, {"def": "大书一屈”字,以两竿夹揭之,走诉行御史台。--明·高启《书博鸡者事》", "example": null}, {"def": "又如立竿见影;揭竿为旗;竿木(古代艺人借以在其上表演各种技艺动作的长竿);竿殳(竹杖);竿首(竹竿顶端);竿头(竹竿的顶端)", "example": null}, {"def": "通简”。竹简", "example": null}, {"def": "不离苞苴竿牍。--《庄子·列御寇》", "example": null}, {"def": "阳翟田望勤于竿牍……日发数十函不倦。--宋·朱彧《萍洲可谈》", "example": null}, {"def": "竿gān竹子的主干，竹棍竹～子。钓鱼～儿。", "example": null}, {"def": "竿gǎn 1.箭干。", "example": null}, {"def": "竿gàn 1.衣架。", "example": null}]','chinese-xinhua','0'),
('2101143296012193859','疳','1','ɡān','疒','10',NULL,'[{"def": "疳〈名〉", "example": null}, {"def": "俗称疳积", "example": null}, {"def": "疳皆脾胃病,亡津液之所作也。--宋·钱乙《小儿药证直诀》", "example": null}, {"def": "疳gān见于病名。", "example": null}, {"def": "①", "example": null}, {"def": "②", "example": null}, {"def": "③", "example": null}]','chinese-xinhua','0'),
