('2101143296016388107','戅','1','ɡànɡ','心','25',NULL,'[{"def": "戇", "example": null}, {"def": "戆头戆脑", "example": null}, {"def": "戇", "example": null}, {"def": "愚蠢(侧重于迂直、不知变通)", "example": null}, {"def": "戆,愚也。从心,赣声。--《说文》", "example": null}, {"def": "悍戆好斗。--《荀子·大略》", "example": null}, {"def": "狂惑戆陋之人。--《荀子·儒效》", "example": null}, {"def": "然陵少戆,陈平可以助之。--《史记·高祖本纪》》", "example": null}, {"def": "甚矣,汲黯之戆也。--《史记·汲郑列传》", "example": null}, {"def": "又如戆冥(愚鲁昏昧);戆士(愚昧之人);戆大(方言。犹傻瓜);戆陋(愚昧浅陋);戆昧(愚昧);戆钝(愚笨)", "example": null}, {"def": "憨厚而刚直", "example": null}, {"def": "益戆由来未觉贤,终须南去吊", "example": null}, {"def": "戅zhuàng", "example": null}]','chinese-xinhua','0'),
('2101143296016388108','岗','1','ɡǎnɡ','山','7',NULL,'[{"def": "岗", "example": null}, {"def": "同岡”。山脊,山岭", "example": null}, {"def": "振衣千仞岗,濯足万里流。--晋·左思《咏史》之五", "example": null}, {"def": "岗", "example": null}, {"def": "(形声。从山,冈声。本义岗位,哨位)", "example": null}, {"def": "同 本 义", "example": null}, {"def": "土石坡儿", "example": null}, {"def": "岗（崗）gǎng", "example": null}, {"def": "⒈守卫的位置站～。～哨。门～。", "example": null}, {"def": "⒉高起的土坡土～子。黄泥～儿。", "example": null}, {"def": "⒊平面上突起的长道肉～子。", "example": null}, {"def": "⒋", "example": null}, {"def": "岗（崗）gāng山脊景阳～。上山～。到井～山。", "example": null}]','chinese-xinhua','0'),
('2101143296016388109','港','1','ɡǎnɡ','氵','12',NULL,'[{"def": "港〈名〉", "example": null}, {"def": "(形声。从水,巷声。本义江河的分流)", "example": null}, {"def": "同本义", "example": null}, {"def": "道于杨墨老庄佛之学,而欲之圣人之道,犹航断港绝潢,以望至于海也。--唐·韩愈《送王秀才序》", "example": null}, {"def": "又如港鱼(港养的鱼产);港养(养殖海产生物的一种方式);港渎(河渠)", "example": null}, {"def": "港湾;码头;港口", "example": null}, {"def": "香港的简称", "example": null}, {"def": "港gǎng", "example": null}, {"def": "⒈与河、沟相通的水渠汊道～口汊道。", "example": null}, {"def": "⒉可以停泊大船的江、海口岸军～。重庆～。上海～。", "example": null}, {"def": "⒊特指香港～人治～。～澳（香港和澳门）同胞喜洋洋。", "example": null}, {"def": "港hòng 1.见\\"港洞\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296016388110','纲','1','ɡānɡ','纟','7',NULL,'[{"def": "纲", "example": null}, {"def": "(形声。从糸,表示与线丝有关,冈声。本义提网的总绳)", "example": null}, {"def": "同本义", "example": null}, {"def": "纲,维紘绳也。--《说文》", "example": null}, {"def": "若网在纲,有条而不紊。--《书·盘庚》", "example": null}, {"def": "纲纪四方。--《诗·大雅·棫朴》。笺张之为纲,理之为纪。”", "example": null}, {"def": "四方之纲。--《诗·大雅·卷阿》", "example": null}, {"def": "举其宏纲。--《书·序》", "example": null}, {"def": "纪纲之仆。--《左传·僖公二十四年》", "example": null}, {"def": "善张网者引其纲,不一一摄万目而后得。则是劳而难,引其纲则鱼已囊矣。--《韩非记·外储说右下》", "example": null}, {"def": "又如纲挈目张(犹纲举目张);纲提领挈(提起网纲,挈住裘领。比喻抓住要领)", "example": null}, {"def": "事物的关键部分,事理的要", "example": null}, {"def": "纲（緑）gāng", "example": null}, {"def": "⒈鱼网上的总绳网之～。〈引〉事物的关键部分～要。提～挈领。～举目张。", "example": null}, {"def": "⒉唐、宋时代成批运输货物的编组，每批的车辆、船只计数编号叫做\\"一纲\\"茶～。花石～。生辰～。", "example": null}]','chinese-xinhua','0'),
('2101143296016388111','肛','1','ɡānɡ','月','7',NULL,'[{"def": "肛", "example": null}, {"def": "(形声。从肉,工声。本义肛门)", "example": null}, {"def": "同本义", "example": null}, {"def": "肛,肛门。--《集韵》", "example": null}, {"def": "大肠端,肛门也。”--《六书故》", "example": null}, {"def": "肛管和肛门的总称", "example": null}, {"def": "脱肛属气热、气虚、血虚、血热。--明·朱震享《丹溪先生心法·脱肛》", "example": null}, {"def": "肛gāng肛管和肛门的总称。直肠下段约三厘米的部分叫肛管。直肠末端的开口叫肛门。", "example": null}]','chinese-xinhua','0'),
