('2101143296020582432','纥','1','ɡē','纟','6',NULL,'[{"def": "纥", "example": null}, {"def": "如纥地(笑的声音);纥刺星(骂人的话。魔星,灾星)", "example": null}, {"def": "纥", "example": null}, {"def": "下等丝", "example": null}, {"def": "给,大丝。--《集韵》", "example": null}, {"def": "回纥", "example": null}, {"def": "姓", "example": null}, {"def": "纥gē", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见hé；jié。", "example": null}, {"def": "纥hé", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见gē、jié。", "example": null}]','chinese-xinhua','0'),
