('2101143296024776707','咯','1','ɡē','口','9',NULL,'[{"def": "咯〈名〉", "example": null}, {"def": "禽鸟的叫声", "example": null}, {"def": "鸡叫声", "example": null}, {"def": "咯〈象〉", "example": null}, {"def": "形容各种不大的尖声", "example": null}, {"def": "咯〈代〉", "example": null}, {"def": "这", "example": null}, {"def": "咯咯", "example": null}, {"def": "那只鸡咯咯叫个不停,肯定下了蛋了", "example": null}, {"def": "他说了个笑话,把她逗得咯咯笑个不停", "example": null}, {"def": "咯吱", "example": null}, {"def": "地震时房梁咯吱咯吱地直响", "example": null}, {"def": "肩上扁担压得咯吱咯吱直响", "example": null}, {"def": "咯〈动〉", "example": null}, {"def": "同喀”。用力使东西从食道或气管里出来", "example": null}, {"def": "咯gē", "example": null}, {"def": "⒈像声词～噔。～吱。母鸡～ ～地叫。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊见luò、kā、kǎ、lo。", "example": null}, {"def": "咯kǎ", "example": null}, {"def": "⒈咳，吐出来～脓痰。～血了。", "example": null}, {"def": "⒉见gē;lo;luò。", "example": null}, {"def": "咯lo", "example": null}, {"def": "⒈助词太好～。", "example": null}]','chinese-xinhua','0'),
('2101143296024776708','给','1','ɡěi','纟','9',NULL,'[{"def": "给  gei", "example": null}, {"def": "使对方得到或遭受到", "example": null}, {"def": "让;使;叫", "example": null}, {"def": "给", "example": null}, {"def": "表示对象、目的,相当于为”、替”", "example": null}, {"def": "给伤员包扎", "example": null}, {"def": "引进动作行为的主动者,或表示被动语态,相当于被”", "example": null}, {"def": "表示方向,相当于朝”、对”、向”", "example": null}, {"def": "给gěi", "example": null}, {"def": "⒈交，付，送与请～我一支笔。〈引〉将动作或态度加于对方～他一巴掌。", "example": null}, {"def": "⒉介词。", "example": null}, {"def": "①替，为～人民办好事。", "example": null}, {"def": "②被，遭受～水冲走了。", "example": null}, {"def": "⒊助词。", "example": null}, {"def": "①与前面的\\"让\\"、\\"叫\\"、\\"把\\"等相应， 可有可无椅子让（～）她坐。麦苗叫牛（～）吃了。把衣服解开（～）医生看看。", "example": null}, {"def": "②〈方〉走时随手～门关好。", "example": null}, {"def": "⒋见jǐ。", "example": null}, {"def": "给jǐ", "example": null}, {"def": "⒈供应～养。供～。自～自足。", "example": null}, {"def": "⒉富裕，丰足百姓充～。人～家足。", "example": null}, {"def": "⒊见gěi。", "example": null}]','chinese-xinhua','0'),
('2101143296024776709','哏','1','ɡén','口','9',NULL,'[{"def": "哏", "example": null}, {"def": "滑稽;可笑", "example": null}, {"def": "这段相声真哏", "example": null}, {"def": "又如这孩子笑的样子有点儿哏", "example": null}, {"def": "哏", "example": null}, {"def": "顿,稍停顿", "example": null}, {"def": "哏gén〈方〉", "example": null}, {"def": "⒈滑稽，逗人发笑的话或表情捧～。逗～。", "example": null}, {"def": "⒉好玩，使人喜爱乖孩子，长得真～。", "example": null}, {"def": "哏hěn 1.犹狠。凶恶;残忍。 2.副词。犹很。表示程度深。 3.叹词。表示愤怒。", "example": null}]','chinese-xinhua','0'),
('2101143296024776710','亘','1','ɡèn','二','6',NULL,'[{"def": "亘", "example": null}, {"def": "连绵不断,伸展开去", "example": null}, {"def": "亘,通也。--《广韵》", "example": null}, {"def": "旌旗亘千里。--《北史·雜本纪》", "example": null}, {"def": "广数十亩,楼宇连亘。--《聊斋志异·狐嫁女》", "example": null}, {"def": "其水之大,倍石渠三之一,亘石为底,达于两涯--唐·柳宗元《石涧记》", "example": null}, {"def": "又如连亘(绵连);亘带(绵延);亘绝(绵延阻绝)", "example": null}, {"def": "横贯;在空间横过或伸过去", "example": null}, {"def": "这亘古未有的壮举,像一柄锋利的匕首,直刺不共戴天的死敌。--《刑场上的婚礼》", "example": null}, {"def": "看桥亘长虹。--清·沈暭旦《摸鱼子》", "example": null}, {"def": "又如亘屏(横亘的屏障);亘舒(横空舒展);亘隔(横亘阻隔)", "example": null}, {"def": "亘", "example": null}, {"def": "穷尽,终;贯串", "example": null}, {"def": "亘万古犹一日。--", "example": null}, {"def": "亘（亙）gèn横贯，延续不断～古未有。长城绵～万里。", "example": null}, {"def": "亘xuān 1.?，回泉。 2.通\\"宣\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296024776711','艮','1','ɡèn','艮','6',NULL,'[{"def": "艮", "example": null}, {"def": "指食物不易咬动或嚼烂", "example": null}, {"def": "不松脆", "example": null}, {"def": "艮", "example": null}, {"def": "八卦之一,代表山", "example": null}, {"def": "珍禽怪兽、佳果文竹于此处)", "example": null}, {"def": "方位名。东北方", "example": null}, {"def": "艮gěn〈方〉", "example": null}, {"def": "⒈性直，说话生硬这人太～。", "example": null}, {"def": "⒉食物韧而不脆～饼。～萝卜。", "example": null}, {"def": "艮gèn八挂之一。代表山。", "example": null}]','chinese-xinhua','0'),
('2101143296024776712','茛','1','ɡèn','艹','9',NULL,'[{"def": "茛〈名〉", "example": null}, {"def": "又名野葛,钩吻", "example": null}, {"def": "毛茛", "example": null}, {"def": "茛gèn", "example": null}]','chinese-xinhua','0'),
