('2101143296024776715','根','1','ɡēn','木','10',NULL,'[{"def": "根", "example": null}, {"def": "(形声。从木,艮声。本义草木之根)", "example": null}, {"def": "植物生长于土中或水中吸收营养的部分", "example": null}, {"def": "根,木株也。--《说文》", "example": null}, {"def": "蔓根为根,直根为柢。--《说文通训定声》", "example": null}, {"def": "根深,则视久。--《韩非子·解老》", "example": null}, {"def": "是谓深根、固柢。--《老子》", "example": null}, {"def": "有根株于下,有荣叶于上。--《论衡·超奇》", "example": null}, {"def": "其无宿根者,候苗成而未有花时采,则根生已足而又未衰。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "斯亦伐根以求木茂,塞源而欲流长也。--唐·魏征《谏太宗十思疏》", "example": null}, {"def": "又如根莇(根。莇草根;又指根本,根源);根茇(植物的根部);根柢(草木的根);根垓(根核。植物的根;植根)", "example": null}, {"def": "事物的本源,", "example": null}, {"def": "根gēn", "example": null}, {"def": "⒈高等植物的营养器官之一。有固养植物体和支持其地上的部分，吸收土壤里的水和溶解在水里的无机盐，贮藏养料等之作用小草～。大树～。直～（如甜菜、向日癸的根）", "example": null}, {"def": "。须～（如稻、麦的根）。块～（如萝卜、土豆的可吃部分）。〈引〉", "example": null}, {"def": "①基部，基础～柢。～基。～本。～蒂。牙～儿。舌～儿。", "example": null}, {"def": "②事物或事情的本源～源。穷～。祸～。寻～究底。", "example": null}, {"def": "③彻底～治。～除。～绝。", "example": null}, {"def": "④凭证，依据～据。存～。", "example": null}, {"def": "⑤〈喻〉后代儿孙他是李家的独～。", "example": null}, {"def": "⒉量词。指长条状物两～火柴。三～塑料绳。", "example": null}, {"def": "⒊数学名词", "example": null}, {"def": "①代数方程式内未知数的值。", "example": null}, {"def": "②", "example": null}, {"def": "⒋化学上称带电的基硫酸～。碳酸氢～。", "example": null}]','chinese-xinhua','0'),
('2101143296024776716','跟','1','ɡēn','足','13',NULL,'[{"def": "跟", "example": null}, {"def": "(形声。从足,艮声。本义足后为跟)", "example": null}, {"def": "同本义", "example": null}, {"def": "跟,足踵也。--《说文》", "example": null}, {"def": "足后曰跟,在下方着地,一体任之,象木根也。--《释名·释形体》", "example": null}, {"def": "阽焦原而跟趾。--张衡《思玄赋》", "example": null}, {"def": "诘曲犹能辨跟肘。--苏轼《凤翔八观》", "example": null}, {"def": "又如跟蹠(脚后跟);跟踵(脚后跟);跟胫(脚跟与小腿);跟趾(脚后跟)", "example": null}, {"def": "器官的基底部分。亦指物体的底部或后部", "example": null}, {"def": "每册之跟,自书精楷以表之。--《清稗类钞·鉴赏类》", "example": null}, {"def": "又如崖跟(山崖底部);跟底(底部)", "example": null}, {"def": "跟", "example": null}, {"def": "追随于后", "example": null}, {"def": "有元地脚保识人前去跟寻。--吴自牧《梦粱录》", "example": null}, {"def": "又如跟我来;跟他走;小偷一", "example": null}, {"def": "跟gēn", "example": null}, {"def": "⒈脚的后部脚～儿。〈引〉鞋、袜的后部鞋～儿。袜后～。", "example": null}, {"def": "⒉随，紧接着紧～。～着共产党走。〈引〉赶，及～上。～到，莫掉队。", "example": null}, {"def": "⒊介词。向，对必须～群众讲清楚。请你～大家讲几句话。", "example": null}, {"def": "⒋连词⊥，同你去～群众商量。你～他一起走。", "example": null}, {"def": "⒌", "example": null}, {"def": "①身体摔倒或向下翻转。〈喻〉倒霉摔～头。栽～头。", "example": null}, {"def": "②筋斗翻～头。", "example": null}]','chinese-xinhua','0'),
('2101143296024776717','更','1','ɡènɡ','曰','7',NULL,'[{"def": "更", "example": null}, {"def": "(形声。从攴,更”的小篆形是个形声字。丙声。 本义改变)", "example": null}, {"def": "同本义", "example": null}, {"def": "更,改也。--《说文》", "example": null}, {"def": "更也,人皆仰之。--《论语·子张》", "example": null}, {"def": "更爵洗。--《仪礼·大射仪》", "example": null}, {"def": "更皮币。--《礼记·月令》", "example": null}, {"def": "更姓改物。--《国语·周语》", "example": null}, {"def": "应国之称号亦更矣。--《管子·侈靡》", "example": null}, {"def": "国更立法以典民则祥。--《管子·任法》", "example": null}, {"def": "更葬也。--《史记·晋世家》", "example": null}, {"def": "景公欲更晏子之宅。--《晏子春秋·内篇杂下》", "example": null}, {"def": "将军若能翻然改图,易迹更步,古人不难追,鄙士何足宰哉!--《三国志·吕凯传》", "example": null}, {"def": "曲沃武公已即位三十七年矣,更号曰晋武公。--《史记", "example": null}, {"def": "更gèng副词。", "example": null}, {"def": "①再，重，又 ～上一层楼。～进一步。", "example": null}, {"def": "②愈加，越发～加。～美好。～清楚。～受人尊敬。", "example": null}, {"def": "更gēng", "example": null}, {"def": "⒈改变，改动，调换～改。～动。～换。～正。变～。万象～新。", "example": null}, {"def": "⒉经历，经过～事。道必～匈奴中。", "example": null}, {"def": "⒊旧时将一夜分为五更，每更约两小时～深人静。夜半三～。", "example": null}]','chinese-xinhua','0'),
