('2101143296024776722','绠','1','ɡěnɡ','纟','10',NULL,'[{"def": "绠", "example": null}, {"def": "轮辐近轴处向外突出的部分", "example": null}, {"def": "绠,车轮也。--《类篇·系部》", "example": null}, {"def": "绠", "example": null}, {"def": "(形声。从糸),更声。本义井绳)", "example": null}, {"def": "同本义", "example": null}, {"def": "绠,汲井索也。--《说文》", "example": null}, {"def": "具绠缶。--《左传·襄公九年》", "example": null}, {"def": "绠短者,不可以汲深。--《庄子·至乐》", "example": null}, {"def": "又如绠缶(汲水的绳索和器具);绠短绝泉(绠短汲深)", "example": null}, {"def": "泛指绳索", "example": null}, {"def": "绠短汲深", "example": null}, {"def": "绠gěng吸水用的绳子∶～短汲深（喻才力不能胜任）", "example": null}, {"def": "绠bǐng 1.古时轮辐近轴处的突出部分。", "example": null}]','chinese-xinhua','0'),
('2101143296024776723','耿','1','ɡěnɡ','耳','10',NULL,'[{"def": "耿", "example": null}, {"def": "(形声。从火,圣省声。本义耳贴于颊)", "example": null}, {"def": "同本义", "example": null}, {"def": "通炯”。明亮,光明", "example": null}, {"def": "跪敷衽(铺开衣襟)以陈辞兮,耿吾既得此中正(指正道)。--《楚辞·屈原·离骚》", "example": null}, {"def": "又如耿耀(照耀);耿光(光明;光辉);耿晶晶(形容物体明亮闪光的样子);耿烈(光明炽热);耿介(光明正大)", "example": null}, {"def": "心情不安;悲伤", "example": null}, {"def": "耿耿不寐,如有隐忧。--《诗·邶风·柏舟》", "example": null}, {"def": "又如耿耿于心(形容心中有事牵挂,无法忘却);耿介(心中不安);耿灼(焦虑不安)", "example": null}, {"def": "刚直", "example": null}, {"def": "参差相叠重重,刚耿陵宇宙。", "example": null}, {"def": "耿gěng", "example": null}, {"def": "⒈正直，直爽～介。～直（也写作\\"梗直\\"、\\"鲠直\\"）。", "example": null}, {"def": "⒉光明。", "example": null}, {"def": "⒊", "example": null}, {"def": "①形容忠诚忠心～ ～。", "example": null}, {"def": "②有心事，心有所思～ ～于怀。～ ～不寐。", "example": null}, {"def": "③微光闪烁～ ～残灯。星河～ ～。", "example": null}]','chinese-xinhua','0'),
('2101143296024776724','梗','1','ɡěnɡ','木','11',NULL,'[{"def": "梗", "example": null}, {"def": "(形声。从木,更声。本义一种树)", "example": null}, {"def": "刺榆(hemiptelea davidii)的古名", "example": null}, {"def": "梗,山枌榆。荚可为芜荑也。--《说文》。按,叶小于常榆,刺如柘刺,其木坚韧,中犊车材,即诗之山有枢。", "example": null}, {"def": "有刺的草木", "example": null}, {"def": "凡草木刺人,自关而东,或谓之梗。--《西京赋》", "example": null}, {"def": "梗木为之靡拉。--《方言三》", "example": null}, {"def": "又如梗林(多刺的林丛);梗莽(荆棘草莽);梗刺(草木茎上有刺针)", "example": null}, {"def": "草本植物的枝茎", "example": null}, {"def": "桃梗土偶。--《战国策·秦策》", "example": null}, {"def": "今求柴胡桔梗于沮泽。--《战国策·齐策》", "example": null}, {"def": "又如菠菜梗;梗子(植物的枝或茎);荷梗;芹菜梗", "example": null}, {"def": "梗", "example": null}, {"def": "阻塞;", "example": null}, {"def": "梗gěng", "example": null}, {"def": "⒈植物的茎或枝菊花～。麦～子。薄荷～。玉米～儿。", "example": null}, {"def": "⒉直，挺着～胸。～着颈。", "example": null}, {"def": "⒊直爽，正直～直（也作\\"鲠直\\"、\\"耿直\\"）。", "example": null}, {"def": "⒋强硬，顽固强～。顽～不化。", "example": null}, {"def": "⒌阻塞，阻碍～阻。～塞。从中作～。", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296024776725','鲠','1','ɡěnɡ','鱼','15',NULL,'[{"def": "鲠", "example": null}, {"def": "(形声。从鱼(或从骨),更声。本义鱼骨,鱼刺)", "example": null}, {"def": "同本义", "example": null}, {"def": "鲠,鱼骨也。--《说文》", "example": null}, {"def": "又如如鲠在喉,不吐不快", "example": null}, {"def": "病患,祸害", "example": null}, {"def": "除鲠而避强。--《国语·晋语》。注害也。”", "example": null}, {"def": "又如鲠慰(悒郁中得到安慰)", "example": null}, {"def": "鲠", "example": null}, {"def": "假借为骾”。鱼刺卡在喉咙里", "example": null}, {"def": "骾,食骨留咽中也。--《说文》", "example": null}, {"def": "鱼去乙。--《礼记·内则》。注食之鲠人。”", "example": null}, {"def": "又如他被鱼刺鲠住了", "example": null}, {"def": "阻塞;堵塞", "example": null}, {"def": "楚师屠汉卒,睢河鲠其流。--《文选·刘孝标·辨命论》", "example": null}, {"def": "通哽”", "example": null}, {"def": "鲠（骾）gěng", "example": null}, {"def": "⒈鱼骨，鱼刺。", "example": null}, {"def": "⒉骨头卡在喉咙里。", "example": null}, {"def": "⒊直爽，正直～言。骨～。～直（也作\\"梗直\\"、\\"耿直\\"）。", "example": null}, {"def": "鲠biān 1.鳊鱼。", "example": null}]','chinese-xinhua','0'),
('2101143296024776726','哽','1','ɡěnɡ','口','10',NULL,'[{"def": "哽", "example": null}, {"def": "(形声。从口,更声。本义言语受阻,不能畅通)", "example": null}, {"def": "同本义", "example": null}, {"def": "哽,语为舌所介也。--《说文》", "example": null}, {"def": "祝哽在前,祝噎在后。--《汉书·礼乐志》", "example": null}, {"def": "闻之哽咽。--《后汉书·袁绍刘表传下》", "example": null}, {"def": "但是他哽住了,他说不下去了。--《最后一课》", "example": null}, {"def": "又如哽哽(悲痛气塞的样子);哽结(心胸悲伤郁结);哽恧(悲伤惭愧)", "example": null}, {"def": "食之鲠人不可出。--《礼记·内则》", "example": null}, {"def": "通鲠”。噎住,食物不能下咽", "example": null}, {"def": "食之鯁人,不可出。--《礼记·内则》", "example": null}, {"def": "口不容而强吞之者必哽。--《拘朴子·任能》", "example": null}, {"def": "阻塞", "example": null}, {"def": "哽gěng", "example": null}, {"def": "⒈喉咙阻塞，多因感情激动引起～咽。", "example": null}, {"def": "⒉食物不能下咽吞不下，～着了。～在喉头。", "example": null}, {"def": "哽縢 1.叹词。表示应诺或疑问﹑不满等。 2.象声词。", "example": null}, {"def": "哽? 1.叹词。表示应诺或疑问﹑不满等   2.象声词。", "example": null}]','chinese-xinhua','0'),
('2101143296024776727','埂','1','ɡěnɡ','土','10',NULL,'[{"def": "埂", "example": null}, {"def": "(形声。从土,更声。本义小坑)", "example": null}, {"def": "同本义", "example": null}, {"def": "埂,秦谓坑为埂。--《说文》", "example": null}, {"def": "埂,小坑也。--《玉篇》", "example": null}, {"def": "假借为防”。堤封,用泥土筑起来的堤防", "example": null}, {"def": "长条形的突出地面的地方", "example": null}, {"def": "田埂,田与田之间便于人走路或蓄水用的高起的长条地方", "example": null}, {"def": "埂子", "example": null}, {"def": "田地里稍稍高起的分界线,像狭窄的小路", "example": null}, {"def": "地埂子", "example": null}, {"def": "泛指条形隆起物", "example": null}, {"def": "被子没铺平,有个埂子", "example": null}, {"def": "埂gěng", "example": null}, {"def": "⒈田地间较高起的小路田～子。地～儿。", "example": null}, {"def": "⒉土坎，土堤土～子。小河～。堤～儿。", "example": null}]','chinese-xinhua','0'),
