('2101143296024776730','庚','1','ɡēnɡ','广','8',NULL,'[{"def": "庚", "example": null}, {"def": "天干的第七位,与地支相配,用以纪年、月、日", "example": null}, {"def": "庚,位西方。--《说文》", "example": null}, {"def": "先庚三日,后庚三日。--《易·巽》", "example": null}, {"def": "太岁在庚日上章,月在庚曰窒。--《尔雅》", "example": null}, {"def": "其日庚辛。--《淮南子》", "example": null}, {"def": "秋,日庚、辛。--《史记》", "example": null}, {"def": "又以配五行", "example": null}, {"def": "庚辛申酉,金也。--《淮南子·天文》", "example": null}, {"def": "年龄", "example": null}, {"def": "伏天”的代称", "example": null}, {"def": "姓", "example": null}, {"def": "庚", "example": null}, {"def": "赔偿,偿还", "example": null}, {"def": "庚gēng", "example": null}, {"def": "⒈天干第七位，也用作次序第七。", "example": null}, {"def": "⒉年龄年～。同～。", "example": null}]','chinese-xinhua','0'),
