('2101143296037359653','媾','1','ɡòu','女','13',NULL,'[{"def": "媾", "example": null}, {"def": "(形声。从女,冓声。本义交互为婚姻,亲上结亲)", "example": null}, {"def": "同本义", "example": null}, {"def": "媾,重婚也。--《说文》", "example": null}, {"def": "今将婚媾以从秦。--《国语·晋语》", "example": null}, {"def": "恢复亲善友好的关系,讲和,交好", "example": null}, {"def": "媾,和好也。--《正字通》", "example": null}, {"def": "无益也,不如发重使为媾。--《史记·平原君虞卿列传》", "example": null}, {"def": "楼缓言不媾,来年秦复攻,王得无更割其内而媾!--《战国策·赵策》", "example": null}, {"def": "又如媾和", "example": null}, {"def": "厚爱,宠爱", "example": null}, {"def": "彼其之了,不遂其媾。--《诗·曹风·侯人》", "example": null}, {"def": "交合", "example": null}, {"def": "会合", "example": null}, {"def": "媾gòu", "example": null}, {"def": "⒈讲和，求和～和。割六县而～。", "example": null}, {"def": "⒉结亲，结婚婚～。", "example": null}, {"def": "⒊交合交～。", "example": null}]','chinese-xinhua','0'),
('2101143296037359654','彀','1','ɡòu','弓','13',NULL,'[{"def": "彀〈动〉", "example": null}, {"def": "张满弓", "example": null}, {"def": "彀,张弩也。--《说文》", "example": null}, {"def": "彀弓弩,持满。--《汉书·周亚夫传》", "example": null}, {"def": "羿之教人射,必志于彀。--《孟子·告子上》", "example": null}, {"def": "通够”", "example": null}, {"def": "彀", "example": null}, {"def": "箭靶", "example": null}, {"def": "羿有以感弓矢,故彀可得而中也。--《管子·小称》", "example": null}, {"def": "目标,目的", "example": null}, {"def": "夫言行者,以功用为之的彀者也。--《韩非子·问辩》", "example": null}, {"def": "程式", "example": null}, {"def": "诗虽不入彀,而笔力甚雅,每出人意表。--刘献廷《广阳杂记》", "example": null}, {"def": "彀中", "example": null}, {"def": "游于羿之彀中。--《庄子·德充符》", "example": null}, {"def": "彀gòu将弓拉满～弩而射。", "example": null}]','chinese-xinhua','0'),
