('2101143296037359662','笱','1','ɡǒu','竹','11',NULL,'[{"def": "笱", "example": null}, {"def": "安放在堰口的竹制捕鱼器,大腹、大口小颈,颈部装有倒须,鱼入而不能出", "example": null}, {"def": "笱,曲竹捕鱼具也。从竹句,会意。句亦声。承于石梁之孔,鱼入不得出,又有以簿为梁笱承之者,谓之寡妇之笱。--《说文》", "example": null}, {"def": "无发我笱。--《诗·小雅·小弁》", "example": null}, {"def": "敝笱在梁。--《诗·齐风·敝笱》", "example": null}, {"def": "笱gǒu捕鱼的竹笼。大口窄颈，颈部倒置竹刺须，鱼可进而不可出～中有鱼。", "example": null}]','chinese-xinhua','0'),
('2101143296037359663','岣','1','ɡǒu','山','8',NULL,'[{"def": "岣嵝", "example": null}, {"def": "岣,岣嵝,山巅。--《广韵》", "example": null}, {"def": "岣gǒu", "example": null}]','chinese-xinhua','0'),
('2101143296037359664','狗','1','ɡǒu','犭','8',NULL,'[{"def": "狗", "example": null}, {"def": "(形声。从犬,句声。本义犬。原指小犬◇为狗犬的通称)", "example": null}, {"def": "同本义", "example": null}, {"def": "狗,犬也。大者为犬,小者为狗。--《说文》", "example": null}, {"def": "艮为狗。--《易·说卦传》", "example": null}, {"def": "故斗运狗三月而生也。--《春秋·考异郵》。注狗,斗之精所生也。”", "example": null}, {"def": "以狗御蛊。--《史记·秦本纪》", "example": null}, {"def": "效犬者左牵之。--《礼记·曲礼上》。疏大者为犬,小者为狗。”", "example": null}, {"def": "悍吏之来吾乡,…哗然而骇者,虽鸡狗不得宁焉。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "有念笑人齿缺曰狗窦大开”的。--《从百草园到三味书屋》", "example": null}, {"def": "属于犬科(canidae)的一种食肉类哺乳动物(canis familiaris)", "example": null}, {"def": "狗gǒu", "example": null}, {"def": "⒈家畜之一，又叫\\"犬\\"。听觉、嗅觉都很灵敏，善于看守门户。有的经过训练可用来帮助打猎、牧羊、警探等猎～。牧羊～。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296037359665','苟','1','ɡǒu','艹','8',NULL,'[{"def": "苟", "example": null}, {"def": "(形声。从苃,句声。本义草名。又菜名) 同本义", "example": null}, {"def": "苟,苟草也。--《说文》", "example": null}, {"def": "苟贞夫。--《急就篇》。注苟,草名也。”", "example": null}, {"def": "苟", "example": null}, {"def": "随便,轻率", "example": null}, {"def": "生亦我所欲,所欲有甚于生者,故不为苟得也。--《孟子·告子上》", "example": null}, {"def": "又如一丝不苟;不苟言笑;苟言(言谈轻率随便)", "example": null}, {"def": "贪求", "example": null}, {"def": "卑下", "example": null}, {"def": "苟", "example": null}, {"def": "姑且;暂且", "example": null}, {"def": "苟者,偷合之称。所以行为廉", "example": null}, {"def": "苟gǒu", "example": null}, {"def": "⒈暂且，姑息一日之～安。～全性命。", "example": null}, {"def": "⒉随便，马虎～同。一丝不～。", "example": null}, {"def": "⒊不正当～合。", "example": null}, {"def": "⒋假如～能如此。", "example": null}, {"def": "⒌", "example": null}, {"def": "①只图眼前，得过且过～且偷安。", "example": null}, {"def": "②草率，马虎决不～且。", "example": null}, {"def": "③不正当之事～且之事。", "example": null}, {"def": "⒍姓。", "example": null}]','chinese-xinhua','0'),
('2101143296037359666','枸','1','ɡǒu','木','9',NULL,'[{"def": "枸", "example": null}, {"def": "盘错的树根", "example": null}, {"def": "故枸木必将待櫽栝焌矫然后直。--《荀子·性恶》", "example": null}, {"def": "有木,青叶紫茎,…,下有九枸,其实如麻,其叶如芒。--《山海经》", "example": null}, {"def": "枸", "example": null}, {"def": "通钩”。弯曲", "example": null}, {"def": "故枸木必将待櫽括焌矫然后直。--《荀子·性恶》", "example": null}, {"def": "枸橘", "example": null}, {"def": "枸杞", "example": null}, {"def": "枸  ju", "example": null}, {"def": "植物名,即蒌叶", "example": null}, {"def": "tree]", "example": null}, {"def": "枸jǔ", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见gōu。", "example": null}, {"def": "枸gǒu", "example": null}, {"def": "枸gōu", "example": null}]','chinese-xinhua','0'),
