('2101143296037359669','聇','1','ɡǒu','','9',NULL,'[{"def": "聇gǒu 1.年老;高寿。 2.指老年人。 3.指老成人。", "example": null}]','chinese-xinhua','0'),
('2101143296037359670','鹹','1','ɡōu','','11',NULL,'[{"def": "鹹gōu(ㄍㄡˉ)字义未详。", "example": null}]','chinese-xinhua','0'),
('2101143296037359671','勾','1','ɡōu','勹','4',NULL,'[{"def": "勾", "example": null}, {"def": "本作句”。弯曲", "example": null}, {"def": "删除或截取", "example": null}, {"def": "谢安已令吏部郎袁彦伯撰策文,文成,安辄勾点,令更治改。--《魏书·司马叡传》", "example": null}, {"def": "把报上的新词勾出来", "example": null}, {"def": "又如勾除(勾销,除掉);勾抹(勾除;抹掉);勾却(勾销,取消)", "example": null}, {"def": "勾勒(用笔先勾一个轮廓)", "example": null}, {"def": "勾结", "example": null}, {"def": "都是这些和尚勾合光棍,在外诈作客商模样。--清·艾衲居《豆棚闲话》", "example": null}, {"def": "又如勾哄(勾结哄骗);勾合(勾结;串通,结合)", "example": null}, {"def": "勾引,引诱", "example": null}, {"def": "他在王婆茶房里,和武大娘子勾搭上了。--《水浒传》", "example": null}, {"def": "勾gōu", "example": null}, {"def": "⒈用笔打勾，删除或截取一笔～销。把这一句～掉。～注涂改甚多。", "example": null}, {"def": "⒉描绘，涂填，画出形象的边缘～脸。～简图。～墙缝。～出一个轮廓。", "example": null}, {"def": "⒊招引，引诱～引。～搭。～通。", "example": null}, {"def": "⒋不等腰直角三角形中构成直角的较短的边。", "example": null}, {"def": "⒌", "example": null}, {"def": "勾gòu", "example": null}, {"def": "⒈", "example": null}, {"def": "①办理，处理～当公事。", "example": null}, {"def": "②事情，多指坏事罪恶～当∶人会干这种～当吗？", "example": null}, {"def": "⒉达到～得到。", "example": null}, {"def": "⒊通\\"够\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296037359672','佝','1','ɡōu','亻','7',NULL,'[{"def": "佝", "example": null}, {"def": "佝偻", "example": null}, {"def": "佝,病偻。--《集韵》", "example": null}, {"def": "又如佝偻病", "example": null}, {"def": "佝偻", "example": null}, {"def": "佝偻病", "example": null}, {"def": "佝gōu", "example": null}, {"def": "闭，出牙迟，重者可有\\"肋骨串珠\\"、\\"鸡胸\\"、\\"漏斗胸\\"等。经常户外活动，合理喂养，服用维生素丁、钙片等可防治。", "example": null}, {"def": "佝kòu 1.见\\"佝瞀\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296037359673','沟','1','ɡōu','氵','7',NULL,'[{"def": "沟", "example": null}, {"def": "(形声。从水,冓声。本义田间水道)", "example": null}, {"def": "同本义", "example": null}, {"def": "沟,水渎,广四尺,深四尺。--《说文》", "example": null}, {"def": "九夫为井,井间广四尺、深四尺,谓之沟。--《考工记·匠人》", "example": null}, {"def": "十夫有沟,沟上有畛。--《周礼·遂人》", "example": null}, {"def": "苟为无本,七八月之间雨集,沟浍皆盈;其涸也,可立而待也。--《孟子·离娄下》", "example": null}, {"def": "又如沟洫(沟浍。田间水道与沟渠);沟洫(田间水道);沟塍(沟渠和田埂)", "example": null}, {"def": "泛指水道", "example": null}, {"def": "水注谷曰沟。--《尔雅》", "example": null}, {"def": "血流入沟中。--《汉书·刘尾氂传》", "example": null}, {"def": "鲁以五月起众为长沟。--《韩非子·外储说右上》", "example": null}, {"def": "兵法曰", "example": null}, {"def": "沟（溝）gōu", "example": null}, {"def": "⒈田间的水沟，泛指小的流水道水～。阴～。阳～。～渠。", "example": null}, {"def": "⒉类似沟的瓦～。交通～。", "example": null}, {"def": "⒊", "example": null}, {"def": "沟kòu 1.见\\"沟瞀\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296037359674','钩','1','ɡōu','钅','9',NULL,'[{"def": "钩", "example": null}, {"def": "(会意。从金,从句,句亦声。句”,弯曲。也具有表意作用。本义衣带上的钩。引申为 钓鱼或挂物用的钩”)", "example": null}, {"def": "形状弯曲,用于探取、悬挂器物的用品。可分为钓钩、挂钩、带钩等", "example": null}, {"def": "鉤,曲也。--《说文》。韵会引作曲鉤也。”", "example": null}, {"def": "鉤,曲也,所以鉤悬物也。--《玉篇》", "example": null}, {"def": "金路鉤。--《周礼·春官·巾车》", "example": null}, {"def": "申孙之矢,集于桓鉤。--《国语·晋语》。注带鉤也。”", "example": null}, {"def": "岂谓一鉤金。--《孟子》", "example": null}, {"def": "窃鉤者诛。--《庄子·胠箧》", "example": null}, {"def": "以尔鉤援。--《诗·大雅·皇矣》。传鉤梯也,所以引上城者。”", "example": null}, {"def": "作刀剑鉤鐔。--《汉书·韩延寿传》。", "example": null}, {"def": "钩（鉤）gōu", "example": null}, {"def": "⒈弯曲的器具，用于悬挂或探取东西等火～儿。钓鱼～。挂衣～子。", "example": null}, {"def": "⒉形状像钩的东西～鼻子。蝎子的～儿。", "example": null}, {"def": "⒊汉字的一种笔形（乙、s、t等）。", "example": null}, {"def": "⒋钩妊树上的枯枝～下来。〈引〉探寻，研究～深致远（钩取深处的，使远处的到来。〈喻〉探索深奥的道理）。", "example": null}, {"def": "⒌缝纫编结法之一～边。～花。", "example": null}, {"def": "⒍同\\"gōu㈠勾", "example": null}, {"def": "⒉\\"，描绘～图样。", "example": null}, {"def": "⒎〈古〉一种兵器，像剑而头部弯曲吴～（吴国的钩）。", "example": null}, {"def": "钩qú 1.见\\"钩町\\"。", "example": null}]','chinese-xinhua','0'),
