('2101143296037359691','崮','1','ɡù','山','11',NULL,'[{"def": "崮〈名〉", "example": null}, {"def": "四面陡峭上端较平的山", "example": null}, {"def": "崮gù四周陡峭，顶端较平的山。多用作地名孟良～，在山东省。", "example": null}]','chinese-xinhua','0'),
('2101143296037359692','梏','1','ɡù','木','11',NULL,'[{"def": "梏〈名〉", "example": null}, {"def": "(形声。从木,告声。本义木手铐)", "example": null}, {"def": "同本义", "example": null}, {"def": "梏,手械也。--《说文》", "example": null}, {"def": "命有司省囹圄,去桎梏。--《吕氏春秋·仲春》", "example": null}, {"def": "在足曰桎,在手曰梏。--《易·蒙》疏", "example": null}, {"def": "甫愍然为之改容,乃得并解桎梏。--《汉书·范滂传》", "example": null}, {"def": "凡囚者,上罪梏拲(两手关械)而桎,中罪桎梏,下罪梏。--《周礼·秋官·掌囚》", "example": null}, {"def": "又如梏桎(即桎梏。束缚手足的刑具);梏掠(用刑拷问);梏拲(古代刑具,也指械系)", "example": null}, {"def": "为了防牛触人而套在牛角上的横木。字本作告", "example": null}, {"def": "告,牛触人,角箸横木,所以告人也。--《说文》", "example": null}, {"def": "梏", "example": null}, {"def": "戴上手铐。也泛指械系,拘系", "example": null}, {"def": "梏gù", "example": null}, {"def": "⒈〈古〉木制的手铐。", "example": null}, {"def": "⒉监禁。", "example": null}, {"def": "梏jué 1.大。 2.正直。", "example": null}]','chinese-xinhua','0'),
('2101143296037359693','牿','1','ɡù','牜','11',NULL,'[{"def": "牿〈名〉", "example": null}, {"def": "关牛马的圈栏", "example": null}, {"def": "牿,牛马牢也。--《说文》", "example": null}, {"def": "无敢伤牿。--《史记·鲁世家》", "example": null}, {"def": "今惟淫舍牿牛马。--《书·费誓》", "example": null}, {"def": "又如牿亡(受遏制而亡);牿服(圈禁,制服)", "example": null}, {"def": "绑在牛角上使其不能触人的横木", "example": null}, {"def": "童牛之牿,元吉。--《易·大畜》", "example": null}, {"def": "牿", "example": null}, {"def": "束缚", "example": null}, {"def": "牿gù 1.养牛马的栅栏。 2.缚于牛角以防触人的横木。 3.桎梏;束缚。", "example": null}]','chinese-xinhua','0'),
('2101143296037359694','棝','1','ɡù','','11',NULL,'[{"def": "棝gù 1.地名用字。 2.见\\"棝斗\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296037359695','祻','1','ɡù','','11',NULL,'[{"def": "祻gù 1.祭祀。 2.用同\\"祸\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296037359696','雇','1','ɡù','隹','12',NULL,'[{"def": "雇", "example": null}, {"def": "(形声。从隹,表示与鸟类有关。户声。本义鸟名。即九雇,一种候鸟)", "example": null}, {"def": "出钱让人给自己做事", "example": null}, {"def": "雇,傭也。--《集韵》", "example": null}, {"def": "以见钱直。--《后汉书·桓帝纪》", "example": null}, {"def": "倍雇南部所得生口,以还北虏。--《冯书·南匈奴传》", "example": null}, {"def": "又如雇唤(雇请);雇觅(雇佣);雇募(出钱招募);雇直(雇用的酬劳);雇借(雇用);雇船", "example": null}, {"def": "受雇", "example": null}, {"def": "展筑外城一十一里有余,役兵及雇夫共五十七万有余工。--宋·苏轼《乞罢宿城状》", "example": null}, {"def": "又如雇伙(被雇用的人);雇夫(受雇用的人);雇役(受雇的仆役)", "example": null}, {"def": "出钱租赁", "example": null}, {"def": "雇（僱）gù", "example": null}, {"def": "⒈出钱叫人为自己做事～工。～店员。～保姆。", "example": null}, {"def": "⒉租赁运输工具～车。～船。～牲口。", "example": null}]','chinese-xinhua','0'),
('2101143296037359697','痼','1','ɡù','疒','13',NULL,'[{"def": "痼", "example": null}, {"def": "(形声。从疒,表示与疾病有关。固声。固”(顽固)也具有表意作用。本义疾病经久难愈的)", "example": null}, {"def": "同本义", "example": null}, {"def": "痼,久病也。--《玉篇》", "example": null}, {"def": "邓太后以皇子胜有痼疾。--《后汉书·周章传》", "example": null}, {"def": "又如痼瘵(积久难治的病。亦指患痼疾的人)", "example": null}, {"def": "引申为根深蒂固的,难改变的", "example": null}, {"def": "烟霞成痼癖,声价藉巢由。--元·潘音《反北山嘲》", "example": null}, {"def": "又如痼习;痼癖(不能改掉的积习)", "example": null}, {"def": "痼病", "example": null}, {"def": "痼疾", "example": null}, {"def": "平原王李被痼疾。--《后汉书·安帝", "example": null}, {"def": "痼gù经久难治好的疾病～疾。〈引〉长期养成的不容易克服的习惯～习。～僻难改。", "example": null}]','chinese-xinhua','0'),
('2101143296037359698','稒','1','ɡù','','11',NULL,'[{"def": "稒gù 1.稒阳。古县名。西汉置，属五原郡。治所在今内蒙古自治区包头市东。东汉废。 2.稒阳。古要塞名。战国魏惠王十九年筑。故址在今内蒙古自治区固阳县附近。", "example": null}]','chinese-xinhua','0'),
('2101143296041553920','锢','1','ɡù','钅','13',NULL,'[{"def": "锢", "example": null}, {"def": "(形声。从金,固声。本义用熔化的金属堵塞空隙)", "example": null}, {"def": "同本义", "example": null}, {"def": "锢,铸塞也。--《说文》。徐锴曰铸铜铁以塞隙也。”", "example": null}, {"def": "鈍锏键钻冶锢鐈。--《急就篇》", "example": null}, {"def": "冶铜锢其内。--《汉书·贾山传》", "example": null}, {"def": "又如锢露(亦作锢路。用熔化的金属堵塞金属物品的漏洞);锢南山(用铜铁熔液堵塞的南山。比喻胸中郁结不消的块垒)", "example": null}, {"def": "禁闭;禁锢", "example": null}, {"def": "(巫臣)遂奔晋,……子反请以重币锢之。--《左传·成公二年》", "example": null}, {"def": "可是在中国,那时是确无写处的,禁锢得比罐头还严密。--《为了忘却的记念》", "example": null}, {"def": "锢诏狱,昼夜搒讯。--《明史·", "example": null}, {"def": "锢gù", "example": null}, {"def": "⒈将金属熔化，浇灌阻塞空隙～漏锅。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296041553921','頋','1','ɡù','','11',NULL,'[{"def": "頋gù字义未详。", "example": null}]','chinese-xinhua','0'),
('2101143296041553922','恏','1','ɡù','','11',NULL,'[{"def": "恏hù 1.卫护。 2.漏。 3.常常。 4.安宁。", "example": null}]','chinese-xinhua','0'),
