('2101143296041553966','嫴','1','ɡū','','8',NULL,'[{"def": "嫴gū 1.保任，保信。 2.姑且。 3.估计，揣摸，大概◇作\\"估\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296041553967','估','1','ɡū','亻','7',NULL,'[{"def": "估", "example": null}, {"def": "(形声。从人,古声。本义物价)", "example": null}, {"def": "同本义", "example": null}, {"def": "乃高盐直,贱帛估。--《新唐书·陆长源传》", "example": null}, {"def": "通贾”。商人", "example": null}, {"def": "莫复临时不寄人,漫道江中无估客。--《玉台新咏·梁元帝·别诗》", "example": null}, {"def": "又如估人(商人)", "example": null}, {"def": "市场税", "example": null}, {"def": "估税悉除,市无二价。--《晋书·甘卓传》", "example": null}, {"def": "又如估税(古代的一种市场税)", "example": null}, {"def": "估 〈动〉", "example": null}, {"def": "引申为估价,估量", "example": null}, {"def": "硬要估住他赔。--艾芜《猪》", "example": null}, {"def": "又如估打成招;估逼(催逼;强逼)", "example": null}, {"def": "用同鼓”。凸起;", "example": null}, {"def": "估gū揣测，大略的推算粗略～计。大致～量。让她～价。～一～这只鸡有多重？", "example": null}, {"def": "估gù", "example": null}]','chinese-xinhua','0'),
('2101143296041553968','咕','1','ɡū','口','8',NULL,'[{"def": "咕〈象〉", "example": null}, {"def": "形容刹车、低声说话等的声音", "example": null}, {"def": "咕gū像声词。", "example": null}, {"def": "①鸽子～ ～地叫。", "example": null}, {"def": "②", "example": null}, {"def": "③", "example": null}, {"def": "④", "example": null}, {"def": "⑤", "example": null}]','chinese-xinhua','0'),
('2101143296041553969','姑','1','ɡū','女','8',NULL,'[{"def": "姑〈名〉", "example": null}, {"def": "(形声。从女,古声。本义丈夫的母亲)", "example": null}, {"def": "同本义", "example": null}, {"def": "姑,夫母也。--《说文》", "example": null}, {"def": "姑在则曰君姑,姑殁则曰先姑。又,妇谓夫之庶母为少姑。--《尔雅》", "example": null}, {"def": "如母而非母也,姑也。--《白虎通》", "example": null}, {"def": "既而将诉于舅姑;舅姑(公婆)爱其子,不能御。--唐·李朝威《柳毅传》", "example": null}, {"def": "又如翁姑;姑嫜(古时妻子对丈夫父母的称呼,即公婆)", "example": null}, {"def": "父亲的姐妹", "example": null}, {"def": "父之姊妹为姑。--《尔雅》", "example": null}, {"def": "问我诸姑。--《诗·邶风·泉水》", "example": null}, {"def": "姪其从姑。--《左传·僖公十五年》", "example": null}, {"def": "又如姑舅(姑母和舅父);姑姊(父之姐);姑", "example": null}, {"def": "姑gū", "example": null}, {"def": "⒈父亲的姐妹大～ ～。么～母。", "example": null}, {"def": "⒉丈夫的母亲拜见翁～（翁丈夫的父亲）。", "example": null}, {"def": "⒊丈夫的姐妹～嫂子。小～子。", "example": null}, {"def": "⒋出家修行或从事迷信职业的妇女或传说中的神女尼～。仙～。", "example": null}, {"def": "⒌暂且，姑且子（你）～待之。", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296041553970','孤','1','ɡū','子','8',NULL,'[{"def": "孤〈名〉", "example": null}, {"def": "(形声。从子,瓜声。本义幼年丧父,即孤儿)", "example": null}, {"def": "同本义", "example": null}, {"def": "孤,无父也。--《说文》", "example": null}, {"def": "如孤子。--《礼记·深衣》。注三十以下无父称孤。”", "example": null}, {"def": "司民协孤终。--《国语·周语》", "example": null}, {"def": "少伶俜而偏孤兮。--潘岳《寡妇赋》", "example": null}, {"def": "老而无子曰独,幼儿无父曰孤。--《孟子·梁惠王下》", "example": null}, {"def": "救灾患,宥孤寡。--《左传·昭公十四年》", "example": null}, {"def": "备答曰刘荆州临亡,讬我以遗孤,背信自济,吾所不为,死何面目见刘荆州乎?--孔衍《汉魏春秋》", "example": null}, {"def": "又如孤驹(无母的小马);孤遗(无父母的子女);孤雏(失去母鸟的幼鸟)。又如孤疾(孤儿和残疾人);六尺之孤(没有父亲的未", "example": null}, {"def": "孤gū", "example": null}, {"def": "⒈幼年丧父或父母双亡～儿寡母。～苦伶仃。", "example": null}, {"def": "⒉单独～独。～单。～掌难鸣。～军奋战。", "example": null}, {"def": "⒊〈古〉君王的自称～王。", "example": null}, {"def": "⒋通\\"gud辜", "example": null}, {"def": "⒉\\"～负。", "example": null}]','chinese-xinhua','0'),
('2101143296041553971','沽','1','ɡū','氵','8',NULL,'[{"def": "沽", "example": null}, {"def": "(形声。从水,古声。本义古水名)", "example": null}, {"def": "同本义", "example": null}, {"def": "沽,沽水,出渔阳塞外,东入海。--《说文》", "example": null}, {"def": "古水名,即今河北首河", "example": null}, {"def": "即今河北省州河。下流为蓟运河,经宁河县至天津市北塘入海", "example": null}, {"def": "天津市的别称", "example": null}, {"def": "沽 〈动〉", "example": null}, {"def": "买。多指买酒。通酤”", "example": null}, {"def": "沽酒市脯。--《论语·乡党》", "example": null}, {"def": "向了一回火,觉得身上寒冷,寻思却才老军所说,二里路外有那市井,何不去沽些酒来吃?--《水浒》", "example": null}, {"def": "又如沽酒市脯(买酒买菜);沽酒(从市场上买来的酒;买酒)", "example": null}, {"def": "卖,出售。通酤”", "example": null}, {"def": "有美玉于斯,韫厁而藏诸?求善贾而沽诸?--《论语·子罕》", "example": null}, {"def": "宋", "example": null}, {"def": "沽gū", "example": null}, {"def": "⒈买～酒待客。", "example": null}, {"def": "⒉卖～酒为生。待价而～。", "example": null}, {"def": "沽gǔ 1.卖酒的商贩。 2.粗劣;简略。", "example": null}]','chinese-xinhua','0'),
