('2101143296041553978','菇','1','ɡū','艹','11',NULL,'[{"def": "菇〈名〉", "example": null}, {"def": "蘑菇", "example": null}, {"def": "菇（菰）gū蕈香～。蘑～。草～。毒红～。", "example": null}]','chinese-xinhua','0'),
('2101143296041553979','菰','1','ɡū','艹','11',NULL,'[{"def": "菰", "example": null}, {"def": "植物名", "example": null}, {"def": "用。如菰稗(茭白和稗子);菰首(即茭白);菰苇(指茭白和苇)", "example": null}, {"def": "同菇”", "example": null}, {"def": "菰（苽）gū", "example": null}, {"def": "⒈多年生草本，在浅水里生长，秋季开紫红色小花。嫩茎经黑穗菌寄生后膨胀增大，叫茭白，果实叫菰米或雕胡米，都可食用。", "example": null}, {"def": "⒉同\\"gū ㈠菇\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296041553980','蛄','1','ɡū','虫','11',NULL,'[{"def": "蛄〈名〉", "example": null}, {"def": "蝼蛄", "example": null}, {"def": "蛄,蝼蛄也。--《说文·虫部》", "example": null}, {"def": "嘹嘹湿蛄声,咽源惊溅起。--唐·李贺《昌谷诗》", "example": null}, {"def": "蛄gū", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "蛄gǔ 1.见\\"蝲蝲蛄\\"﹑\\"蝲蛄\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296041553981','蓇','1','ɡū','','11',NULL,'[{"def": "蓇gū", "example": null}, {"def": "①指某种果实，如芍药、八角等的果实。", "example": null}, {"def": "②骨朵儿（没开的花朵）。", "example": null}]','chinese-xinhua','0'),
