('2101143296045748300','宄','1','ɡuǐ','宀','5',NULL,'[{"def": "宄〈动〉", "example": null}, {"def": "(形声。从宀,九声。本义 从内部作乱或窃夺 )同本义", "example": null}, {"def": "宄,奸也。--《说文》。外为盗,内为宄。", "example": null}, {"def": "冠贼奸宄。--《虞书》。注在内曰宄。”", "example": null}, {"def": "宄,内盗也。--《广韵》", "example": null}, {"def": "俾暴虐于百姓,以奸宄于商邑。--《书·牧誓》", "example": null}, {"def": "乱在内为宄,在外为奸。御宄以德,御奸以刑。--《国语·晋语六》", "example": null}, {"def": "宄〈名〉", "example": null}, {"def": "作乱或盗窃的人", "example": null}, {"def": "奸宄不得萌动而破灭。--《汉书·辛庆忌传》", "example": null}, {"def": "毁则者为贼,掩贼者为藏,窃宝者为宄,用宄之财者为奸。--《国语》", "example": null}, {"def": "宄guǐ犯人，坏人奸～逃窜。", "example": null}]','chinese-xinhua','0'),
('2101143296045748301','轨','1','ɡuǐ','车','6',NULL,'[{"def": "轨", "example": null}, {"def": "(形声。从车,九声。本义轨距,车两轮间的距离)", "example": null}, {"def": "同本义", "example": null}, {"def": "轨,车辙也。--《说文》", "example": null}, {"def": "经涂九轨。--《考工记·匠人》。注轨,谓辙广。”", "example": null}, {"def": "车不得方轨。--《战国策·齐策》。注车两轮间为轨。”按,谓两轮间相距之迹为轨也。", "example": null}, {"def": "今天下车同轨,书同文。--《礼记·中庸》", "example": null}, {"def": "又如轨距", "example": null}, {"def": "车轮的痕迹,车辙", "example": null}, {"def": "轨,迹也。--《广雅》", "example": null}, {"def": "轨,车辙也。--《玉篇》", "example": null}, {"def": "兵车之轨交于天下。--柳宗元《辩侵伐论》", "example": null}, {"def": "城门之轨,两马之力与?--《孟子·尽心下》", "example": null}, {"def": "又如轨迹(车的辙迹);轨躅(车轮辗过的痕迹)", "example": null}, {"def": "法则、法度", "example": null}, {"def": "轨guǐ", "example": null}, {"def": "⒈车子两轮之间的距离车同～。〈喻〉车轮的痕迹城门之～。", "example": null}, {"def": "⒉轨道，一定的线路五星循～而行。有～电车。特指铺设轨道的钢铁条铺铁～。架钢～。〈喻〉法度，规则，办法，秩序等纳入正～。制止越～行为。", "example": null}]','chinese-xinhua','0'),
('2101143296045748302','庋','1','ɡuǐ','广','7',NULL,'[{"def": "庋〈名〉", "example": null}, {"def": "置放器物的架子", "example": null}, {"def": "见床内绣庋上,乌纱帽存。--宋·洪迈《夷坚志·蔡河秀才》", "example": null}, {"def": "又如庋阁(搁置器物的架子)", "example": null}, {"def": "庋", "example": null}, {"def": "搁置,放置", "example": null}, {"def": "经尊道则尊,有合严庋宾(即置)。--元·柳贯《尊经堂》", "example": null}, {"def": "又如庋架(置放架上);庋置(搁置)", "example": null}, {"def": "收藏", "example": null}, {"def": "若业为吾所有,必高束焉,庋藏焉。--清·袁枚《黄生借书说》", "example": null}, {"def": "又如庋掌(收藏、管理);庋间(储藏室);庋藏(收藏)", "example": null}, {"def": "庋guǐ", "example": null}, {"def": "⒈放物品的板子或架子。", "example": null}, {"def": "⒉放置～妥。～藏。", "example": null}, {"def": "庋guì 1.擎起，托出。 2.指承托之物，如桥﹑阁道等。", "example": null}]','chinese-xinhua','0'),
('2101143296045748303','匦','1','ɡuǐ','匚','8',NULL,'[{"def": "匦", "example": null}, {"def": "(簋的古字) 匣子,小箱子", "example": null}, {"def": "匦", "example": null}, {"def": "藏于匦中", "example": null}, {"def": "日者相传,寸楮必匦,人往谒公,以我墨贽。--清·魏源《登太行绝顶》", "example": null}, {"def": "匦guǐ匣子，箱子钱～。首饰～。", "example": null}]','chinese-xinhua','0'),
('2101143296045748304','诡','1','ɡuǐ','讠','8',NULL,'[{"def": "诡", "example": null}, {"def": "(形声。从言,危声。本义责成,要求)", "example": null}, {"def": "同本义", "example": null}, {"def": "诡,责也。--《说文》", "example": null}, {"def": "自诡灭贼。--《汉书·赵充国传》", "example": null}, {"def": "今臣得出守郡,自诡效功,恐未效而死。--《汉书·京房传》", "example": null}, {"def": "又如诡求(要求,责求);诡驳(责难驳斥);诡责(责备;责问);诡令(责令)", "example": null}, {"def": "违反,自相矛盾", "example": null}, {"def": "诡,违也。--《西京赋》注引《说文》", "example": null}, {"def": "容服有仪谓之仪,反仪为诡。--《贾子道术》", "example": null}, {"def": "诡自然之性。--《淮南子·主术》", "example": null}, {"def": "古今诡趣。--《淮南子·辩亡论》", "example": null}, {"def": "言行相诡,不祥莫大焉。--《吕氏春秋", "example": null}, {"def": "诡guǐ", "example": null}, {"def": "⒈欺诈，奸滑～计。～辩。", "example": null}, {"def": "⒉奇异，怪异，出乎平常～谲。～殊。～秘。～异。", "example": null}, {"def": "⒊违反，违背～于常理。言行相～。", "example": null}]','chinese-xinhua','0'),
('2101143296045748305','陒','1','ɡuǐ','','8',NULL,'[{"def": "陒guǐ 1.毁;败坏。", "example": null}]','chinese-xinhua','0'),
('2101143296045748306','癸','1','ɡuǐ','癶','9',NULL,'[{"def": "癸〈名〉", "example": null}, {"def": "(象形。甲骨文字形,象二戣,古代兵器。交叉之形,盖即戣”之古文。①本义古代兵器。戟属。②天干的第十位),用作顺序的第十", "example": null}, {"def": "stems]", "example": null}, {"def": "癸", "example": null}, {"def": "估量", "example": null}, {"def": "癸之言揆也,言万物可揆度,故曰癸。--《史记》", "example": null}, {"def": "癸guǐ天干的第十位。也用作次序的第十。", "example": null}]','chinese-xinhua','0'),
('2101143296045748307','鬼','1','ɡuǐ','鬼','9',NULL,'[{"def": "鬼〈名〉", "example": null}, {"def": "(象形。甲骨文字形,下面是个人”字,上面象一个可怕的脑袋(非田”字),是人们想象中的似人非人的怪物。鬼”是汉字部首之一,从鬼”的字大多与迷信、鬼神有关。", "example": null}, {"def": "本义迷信的人认为人死后有灵魂”,称之为鬼”)", "example": null}, {"def": "同本义", "example": null}, {"def": "鬼,人所归为鬼。--《说文》", "example": null}, {"def": "众生必死,死必归士,此之谓鬼。--《礼记·祭义》", "example": null}, {"def": "载鬼一车。--《易·睽》", "example": null}, {"def": "为鬼为蜮。--《诗·小雅·何人斯》", "example": null}, {"def": "苍颉作书鬼夜哭。--《淮南子·本经》", "example": null}, {"def": "身既死兮神以灵,子魂魄兮为鬼雄。--《楚辞·屈原·国殇》", "example": null}, {"def": "吾作此书时,尚是世中一人;汝", "example": null}, {"def": "鬼guǐ", "example": null}, {"def": "⒈迷信者认为\\"人死后有灵魂\\"叫\\"鬼\\"没有～也没有神。物死不能为～，人死何故独能为～。", "example": null}, {"def": "⒉阴险，奸诈，不光明～主意。～ ～祟祟。心怀～胎（〈喻〉不可告人的事）。", "example": null}, {"def": "⒊机灵，多指小孩或对小孩的爱称～聪明。乖小～。这孩子～得很。", "example": null}, {"def": "⒋对人的蔑视或憎恨烟～。吝啬～。胆小～。吸血～。～子兵。", "example": null}, {"def": "⒌糟糕，恶劣遇上了～事情。这个～天气，太热了。", "example": null}, {"def": "⒍星宿名。二十八宿之一。", "example": null}]','chinese-xinhua','0'),
('2101143296045748308','祪','1','ɡuǐ','','8',NULL,'[{"def": "祪guǐ 1.已毁庙的远祖神主。", "example": null}]','chinese-xinhua','0'),
('2101143296045748309','晷','1','ɡuǐ','日','12',NULL,'[{"def": "晷〈名〉", "example": null}, {"def": "(形声。从日,咎声。本义日影)", "example": null}, {"def": "同本义", "example": null}, {"def": "晷,日景也。--《说文》", "example": null}, {"def": "白日未及移其晷,己猘其什七八。--汉·张衡《西京赋》", "example": null}, {"def": "相持既久,日晷渐移。--马中锡《中山狼传》", "example": null}, {"def": "又如晷昃(日影偏西);晷曜(圭表上投射的日影);晷仪(测日影以定时刻的仪器);晷景(晷表之投影;日影);晷柱(晷表)", "example": null}, {"def": "日光;亮光", "example": null}, {"def": "辉光所烛,万里同晷。--《汉书·李寻传》", "example": null}, {"def": "月晷呈祥。--《宋书·谢庄传》", "example": null}, {"def": "春来多困,正晷移帘影,银屏深闭。--宋·柴望《念奴娇》", "example": null}, {"def": "白昼", "example": null}, {"def": "究晷系夜,钓于台下。--晋·王嘉《拾遗记", "example": null}, {"def": "晷guǐ", "example": null}, {"def": "⒈日影。〈喻〉时光，时间寸～惟宝（惟宝是宝贝）。", "example": null}, {"def": "⒉日晷，也叫\\"日规\\"。按照日影测定时刻的仪器立～测影。", "example": null}]','chinese-xinhua','0'),
