('2101143296045748349','衮','1','ɡǔn','衣','10',NULL,'[{"def": "衮", "example": null}, {"def": "(衮为衮的俗字。形声。从衣,公声。本义画龙于衣。也指古代帝王或三公(古代最高的官)穿的礼服)", "example": null}, {"def": "同本义", "example": null}, {"def": "中国古代天子祭祀时所穿的绣有龙的礼服", "example": null}, {"def": "衮,天子享先王。卷龙绣于下常。幅一龙,蟠阿上乡(向)。--《说文》", "example": null}, {"def": "王之吉服,享先王则衮冕。--《周礼·司服》。司农注衮衣,卷龙衣也。”", "example": null}, {"def": "我觏之子,衮衣绣裳。--《诗·豳风·九羘》", "example": null}, {"def": "(羘(鑹??)九羘捕捉小鱼的细网)", "example": null}, {"def": "吾有布衣之心,子有衮冕之志,各从所好,不亦善乎?--《后汉书·孔僖传》", "example": null}, {"def": "(此处引申为登朝入仕)。又如衮袍(天子的礼服);衮龙裘(绣有飞龙图案的裘皮", "example": null}, {"def": "衮（袞）gǔn", "example": null}, {"def": "⒈〈古〉帝王或三公（高官）穿的礼服～袍。～服。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296045748350','惃','1','ɡǔn','','8',NULL,'[{"def": "惃gǔn 1.混乱。 2.昏迷，神志不清。", "example": null}]','chinese-xinhua','0'),
('2101143296045748351','绲','1','ɡǔn','纟','11',NULL,'[{"def": "绲", "example": null}, {"def": "织成的带子", "example": null}, {"def": "绲,织带也。从糸,昆声。--《说文》", "example": null}, {"def": "竹闭绲縢。--《诗·秦风·小戎》。传绳也。”", "example": null}, {"def": "绲带。--《后汉书·南匈奴传》。注织成布也。”", "example": null}, {"def": "通衮”", "example": null}, {"def": "帝王及公侯的礼服", "example": null}, {"def": "当穷台绲,松侨协轨。--汉《领校巴郡太守樊敏碑》", "example": null}, {"def": "衮职,三公之职", "example": null}, {"def": "维时假阶,将受绲职。--汉《卫尉卿方碑》", "example": null}, {"def": "通昆”◇代子孙", "example": null}, {"def": "于是刊碑,以示后绲。--汉《绥民校尉熊君碑》", "example": null}, {"def": "绲", "example": null}, {"def": "用带子保护、加强或装饰", "example": null}, {"def": "绲gǔn", "example": null}, {"def": "⒈绳。", "example": null}, {"def": "⒉编织成的带子。", "example": null}, {"def": "⒊绲边儿，沿着衣服等的边缘缝上布条或带子。", "example": null}, {"def": "绲hùn 1.混同。 2.绲戎，古西戎之一。", "example": null}]','chinese-xinhua','0'),
('2101143296045748352','辊','1','ɡǔn','车','12',NULL,'[{"def": "辊", "example": null}, {"def": "车毂匀整齐一", "example": null}, {"def": "辊,毂齐等貌。从车,昆声。谓干木正圆不桡减。--《说文》", "example": null}, {"def": "望其毂,欲其辊也。--《考工记·轮人》", "example": null}, {"def": "又如辊轴(古代一种碾草平地的农具)", "example": null}, {"def": "辊", "example": null}, {"def": "滚筒", "example": null}, {"def": "辊", "example": null}, {"def": "滚滚向前流动或运动;像车轮般很快地转动", "example": null}, {"def": "运行,运转", "example": null}, {"def": "犹混。形容苟且地生活", "example": null}, {"def": "辊gǔn", "example": null}, {"def": "⒈机器上能滚动的圆筒形机件～轴。皮～。", "example": null}, {"def": "⒉像车轮样飞快的转动～动。", "example": null}]','chinese-xinhua','0'),
('2101143296049942528','滚','1','ɡǔn','氵','13',NULL,'[{"def": "滚", "example": null}, {"def": "(形声。从水,衮声。本义大水奔流貌)", "example": null}, {"def": "同本义", "example": null}, {"def": "无边落叶萧萧下,不尽长江滚滚来。--唐·杜甫《登高》", "example": null}, {"def": "又如滚滚(水涌流的样子)", "example": null}, {"def": "连续不断,急速翻腾的样子", "example": null}, {"def": "尘滚滚东向驰去◇遂不复至。--明·魏禧《大铁椎传》", "example": null}, {"def": "又如滚滚滔滔(不绝的样子);滚滚当潮(滚滚当道。相继不断地掌握政权)", "example": null}, {"def": "圆的", "example": null}, {"def": "个个是生青滚壮。--茅盾《春蚕》", "example": null}, {"def": "滚〈动〉", "example": null}, {"def": "滚动,滚转", "example": null}, {"def": "球滚来滚去", "example": null}, {"def": "譬如甑蒸饭,气从下面滚到上面又滚下,只管在里面滚,便蒸得熟。--《朱子语类》", "example": null}, {"def": "又如滚落;滚碌(滚动);滚尘(翻", "example": null}, {"def": "滚（漧）gǔn", "example": null}, {"def": "⒈水流翻腾翻～。浪涛～ ～。", "example": null}, {"def": "⒉旋转着翻动或急速翻腾～动。黄沙～ ～。皮球～来～去。", "example": null}, {"def": "⒊液体沸腾水～了（水开了）。油～了。", "example": null}, {"def": "⒋责令对方走开～开。～出去。", "example": null}, {"def": "⒌极，特别水～烫。腰身～圆。", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296049942529','蓘','1','ɡǔn','','8',NULL,'[{"def": "蓘gǔn", "example": null}, {"def": "⒈用土培苗根譬如农夫，是穮是～。”", "example": null}]','chinese-xinhua','0'),
('2101143296049942530','磙','1','ɡǔn','石','15',NULL,'[{"def": "磙", "example": null}, {"def": "(形声。从石,衮声。本义石制滚压器) 同本义", "example": null}, {"def": "磙", "example": null}, {"def": "用滚子碾轧", "example": null}, {"def": "磙子", "example": null}, {"def": "碌碡", "example": null}, {"def": "一种农具、通常是中间粗两头略细的石头圆柱,装在轴架上,用以播种以后把覆土轧实", "example": null}, {"def": "磙gǔn", "example": null}, {"def": "⒈磙子，圆柱形的压、轧用的石或铁做器具。", "example": null}, {"def": "⒉用磙子压轧～压。", "example": null}]','chinese-xinhua','0'),
('2101143296049942531','鲧','1','ɡǔn','鱼','15',NULL,'[{"def": "鲧", "example": null}, {"def": "鱼名。古书上指一种大鱼", "example": null}, {"def": "马鲛,青斑色,无鳞有齿,又名章鮬。--明·屠本畯《闽中海错疏·鳞下》", "example": null}, {"def": "古人名,夏禹的父亲", "example": null}, {"def": "禹之父曰鲧。--《史记》", "example": null}, {"def": "鲧（鮬）gǔn", "example": null}, {"def": "⒈〈古〉传说中的一种大鱼。", "example": null}, {"def": "⒉〈古〉人名。夏朝，禹的父亲。", "example": null}]','chinese-xinhua','0'),
