('2101143296049942536','虢','1','ɡuó','虍','15',NULL,'[{"def": "虢", "example": null}, {"def": "(形声。从虎,寽声。本义虎所抓画之迹)", "example": null}, {"def": "同本义", "example": null}, {"def": "虢,虎所攫画明文也。--《说文》", "example": null}, {"def": "周代国名。有东、西、南、北四虢", "example": null}, {"def": "东虢。周文王弟虢叔所封之地,在今河南省荥阳,公元前767年为郑所灭", "example": null}, {"def": "西虢,周文王弟虢仲的封地,在今陕西省宝鸡县东,公元前665年为秦所灭", "example": null}, {"def": "南虢,周平王东迁,西虢徙于上阳,称南虢,春秋时灭于晋", "example": null}, {"def": "北虢。虢仲后代的封地,在今山西省平陆县", "example": null}, {"def": "谚所谓辅车相依,唇亡齿寒”者,其虞虢之谓也。--《左传·僖公五年》", "example": null}, {"def": "唐代州名", "example": null}, {"def": "虢", "example": null}, {"def": "猛烈;暴烈", "example": null}, {"def": "虢guó周代诸侯国名", "example": null}, {"def": "①在今陕西省宝鸡县东，后迁到河南省陕县东南。又称\\"东虢\\"。", "example": null}, {"def": "②在今河南省郑州西北。又称\\"西虢\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296049942537','馘','1','ɡuó','首','17',NULL,'[{"def": "馘", "example": null}, {"def": "(形声。从耳,或声。本义古代战争割取敌人的左耳,用以计数报功)同本义", "example": null}, {"def": "馘,军战断耳也。春秋传曰以为俘馘。--《说文》", "example": null}, {"def": "馘,获也。--《尔雅》", "example": null}, {"def": "攸馘安安。--《诗·大雅·皇矣》", "example": null}, {"def": "以馘馘告。--《礼记·王制》", "example": null}, {"def": "俘二百八十人,馘百人。--《左传》", "example": null}, {"def": "馘", "example": null}, {"def": "割下的左耳", "example": null}, {"def": "矫矫虎臣,在泮献馘。--《诗·鲁颂·泮水》", "example": null}, {"def": "献馘万计。--《三国志·武帝纪》", "example": null}, {"def": "馘（聝）guó〈古〉作战中割取敌人的左耳，用于计数报功献～万计。", "example": null}, {"def": "馘xù 1.脸，脸面。", "example": null}]','chinese-xinhua','0'),
