('2101143296049942548','过','1','ɡuò','辶','6',NULL,'[{"def": "过", "example": null}, {"def": "古国名", "example": null}, {"def": "处浇于过,处豷于戈。--《左传·襄公四年》", "example": null}, {"def": "姓,过国之后", "example": null}, {"def": "过", "example": null}, {"def": "(形声。从辵,表示与行走有关,唈声。本义走过,经过)", "example": null}, {"def": "同本义", "example": null}, {"def": "过,度也。--《说文》", "example": null}, {"def": "禹八年于外,三过其门而不入。--《孟子·滕文公上》", "example": null}, {"def": "雷霆乍惊,宫车过也。--杜牧《阿房宫赋》", "example": null}, {"def": "有过于江上者,见人方引婴儿而欲投之江中。--《吕氏春秋·察今》", "example": null}, {"def": "行过夷门,见侯生。--《史记·魏公子列传》", "example": null}, {"def": "又如过江;过马路;从这条街上过;从他门前过;路过(途中经过);过翼(经过的飞鸟);过宾(", "example": null}, {"def": "过（過）guò", "example": null}, {"def": "⒈经历，经历某个空间、时间、地点～去。经～。走～。度～。～节。～桥。～河。", "example": null}, {"def": "⒉进行某种处理～磅。～滤。～目。", "example": null}, {"def": "⒊超越，超出某种范围或限度胜～。太～分。莫～火。～于激动。刚刚～期。已～半数。", "example": null}, {"def": "⒋转移，传递，交往～户。～电。～从。", "example": null}, {"def": "⒌错误～失。～错。知～必改。", "example": null}, {"def": "⒍用在动词后面。", "example": null}, {"def": "①助词。〈表〉曾经或完毕看见～。去～了。曾用～。吃～了。", "example": null}, {"def": "②与\\"来\\"、\\"去\\"连用，〈表〉趋向搬～来。走～去。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①花费太多。", "example": null}, {"def": "②辜负。", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "⒔", "example": null}, {"def": "过（過）guō姓。", "example": null}, {"def": "过huò 1.车的盛膏器。 2.通\\"祸\\"。灾祸。", "example": null}]','chinese-xinhua','0'),
