('2101143296049942576','铪','1','hā','钅','11',NULL,'[{"def": "铪", "example": null}, {"def": "化学元素名,化学上与锆非常相似的一种灰色高熔点四价金属元素,它存在于大多数锆矿中,由于它容易发射电子而很有用处(如用作白炽灯的灯丝)", "example": null}, {"def": "铪 ke", "example": null}, {"def": "〔～匝〕周匝，环绕，如紫帷～～，翠屏环合”。", "example": null}, {"def": "铪hā金属化学元素。符号hf。银灰色，熔点高，用于x线管的阴极。铪的钨或钼合金用于高压放电管的电极。", "example": null}, {"def": "铪jiā 1.象声词。钻入坚物声;击乐器声。", "example": null}, {"def": "铪kē 1.见\\"铪匝\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296049942577','哈','1','hā','口','9',NULL,'[{"def": "哈〈动〉", "example": null}, {"def": "(形声。从口,合声。本义以唇啜饮。同歃”)", "example": null}, {"def": "张口呼气", "example": null}, {"def": "哈", "example": null}, {"def": "身子略弯,以此表示礼貌(不及鞠躬郑重)", "example": null}, {"def": "哈", "example": null}, {"def": "口", "example": null}, {"def": "臾儿、易牙,淄 渑之水合者,尝一哈水而甘苦知矣;故圣人之论贤也,见其一行而贤不肖分矣。--《淮南子·汜论训》", "example": null}, {"def": "哈〈叹〉", "example": null}, {"def": "--表示满意、惊喜或赞叹", "example": null}, {"def": "哈〈象〉", "example": null}, {"def": "笑声", "example": null}, {"def": "黄檗哈哈大笑。--道原《景德传灯录》", "example": null}, {"def": "哈", "example": null}, {"def": "哈hā", "example": null}, {"def": "⒈张口呼气～气。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "①含油食物，存放时久，起了变化的味道。", "example": null}, {"def": "②杀死（多见于元曲）。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "①我国少数民族之一。", "example": null}, {"def": "②哈萨克斯坦的主要民族。", "example": null}, {"def": "哈hǎ", "example": null}, {"def": "⒈姓。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "哈hà", "example": null}, {"def": "哈hē 1.饮;喝。", "example": null}]','chinese-xinhua','0'),
('2101143296049942578','孩','1','hái','子','9',NULL,'[{"def": "孩〈动〉", "example": null}, {"def": "(形声。从子,亥声。本义小儿笑)", "example": null}, {"def": "同本义。同咳”", "example": null}, {"def": "咳,小儿笑也。--《说文》。古文咳从子。内则,孟子则作此字。", "example": null}, {"def": "孤女藐焉始孩。--潘岳《寡妇赋》", "example": null}, {"def": "又如未孩(还不会笑)", "example": null}, {"def": "当作婴儿看待", "example": null}, {"def": "圣人在天下,歙歙为天下浑其心,百姓皆注其耳目,圣人皆孩之。--《老子》", "example": null}, {"def": "抚爱", "example": null}, {"def": "伏惟陛下,昧旦坐朝,留心政术,明罚以纠诸侯,申恩以孩百姓。--《北齐书》", "example": null}, {"def": "孩〈形〉", "example": null}, {"def": "幼小;幼稚", "example": null}, {"def": "孩,少也。--《广雅》", "example": null}, {"def": "忆昔十五心尚孩。--杜甫《百忧集行》", "example": null}, {"def": "又如孩赤无知(年幼无知);孩幼(幼儿);孩抱(幼", "example": null}, {"def": "孩hái幼儿，儿童婴～。小～子。小～儿。〈引〉子女一对夫妇只生一个～子好。", "example": null}]','chinese-xinhua','0'),
('2101143296049942579','骸','1','hái','骨','15',NULL,'[{"def": "骸〈名〉", "example": null}, {"def": "(形声。从骨,亥声。本义胫骨,小腿骨)", "example": null}, {"def": "同本义", "example": null}, {"def": "骸,胫骨也。--《说文》。段玉裁注《骨空论》曰‘膝解为骸关,侠膝之骨为连骸。’然则正谓胫骨为骸矣。”", "example": null}, {"def": "骸下为辅,辅上为膎。--《素问》", "example": null}, {"def": "析骸而炊之。--《公羊传·宣公十五年》", "example": null}, {"def": "骨,尸骨", "example": null}, {"def": "即如忠烈遗骸。--清·全祖望《梅花岭记》", "example": null}, {"def": "又如尸骸;骸炭(骨灰);骸筋(筋骨);骸骼(尸骨)", "example": null}, {"def": "身体", "example": null}, {"def": "有七尺之骸,手足之异,戴发含齿,倚有趣者,谓之人。--《列子·黄帝》", "example": null}, {"def": "又", "example": null}, {"def": "骸hái", "example": null}, {"def": "⒈骨，人骨～骨。尸～。", "example": null}, {"def": "⒉身体病～。", "example": null}]','chinese-xinhua','0'),
('2101143296049942580','还','1','hái','辶','7',NULL,'[{"def": "还  huan", "example": null}, {"def": "(形声。从辵(表示与行走有关),瞏声。本义返回)", "example": null}, {"def": "同本义", "example": null}, {"def": "还,復也。--《说文》", "example": null}, {"def": "还,返也。--《尔雅·释言》", "example": null}, {"def": "还而不入。--《诗·小雅·何人斯》", "example": null}, {"def": "吾其还也。--《左传·僖公三十年》", "example": null}, {"def": "势还不远,可先为起第。--《资治通鉴》", "example": null}, {"def": "既罢,还内。", "example": null}, {"def": "还部白府君。(回到府里报告太守。府君,太守。)--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "送儿还故乡。--《乐府诗集·木兰诗》", "example": null}, {"def": "便要还家。--晋·陶渊明《桃花源记》", "example": null}, {"def": "复还终业。--《后汉书·列女传》", "example": null}, {"def": "自南海还。--清·彭端淑《为学一首示子侄》", "example": null}, {"def": "又", "example": null}, {"def": "还（還）hái", "example": null}, {"def": "⒈仍旧，依然他身体～健康。工作～是干劲冲天。", "example": null}, {"def": "⒉更今年比去年～好。", "example": null}, {"def": "⒊再，又～来一个。既要增加产量，～要提高质量。", "example": null}, {"def": "⒋尚可，勉强过得去这篇文章～可以。他工作得～不算慢。", "example": null}, {"def": "⒌尚且这些老同志干劲～这样大，我们年青人更应加油干呀！", "example": null}, {"def": "⒍用来加强语气或〈表〉未料到的这～了得。她～真有办法。", "example": null}, {"def": "⒎", "example": null}, {"def": "①〈表〉比较好～是这个办法好。", "example": null}, {"def": "②连词。用于问句，〈表〉选择是去文化宫，～是去博物馆？", "example": null}, {"def": "⒏见huán。", "example": null}, {"def": "还(還）huán", "example": null}, {"def": "⒈返回～故乡。她～家了。", "example": null}, {"def": "⒉恢复～原。", "example": null}, {"def": "⒊回答，对付～礼。以眼～眼。以牙～牙。", "example": null}, {"def": "⒋交还，归还～地于民。借钱～钱。", "example": null}, {"def": "还xuán 1.旋转;回旋。 2.迅速;立即。 3.敏捷貌。", "example": null}]','chinese-xinhua','0'),
('2101143296049942581','亥','1','hài','亠','6',NULL,'[{"def": "亥〈名〉", "example": null}, {"def": "(象形。甲骨文字形,与豕”的写法相似,象猪形。古代亥”与豕”很容易写混,成语鲁鱼亥豕”讲的就是这种误写现象。本义猪)", "example": null}, {"def": "同本义", "example": null}, {"def": "豕与亥相似。--《吕氏春秋·慎行论》", "example": null}, {"def": "亥,豕也。--《论衡·物势》", "example": null}, {"def": "亥即豕,故曰首曰身也。--《左传·襄公三十年》", "example": null}, {"def": "地支的末一位", "example": null}, {"def": "与天干相配,用以纪年", "example": null}, {"def": "用以纪月,农历十月为亥", "example": null}, {"def": "与天干相配,用以纪日", "example": null}, {"def": "用以纪时,即夜里九点至十一点", "example": null}, {"def": "十二生肖属猪", "example": null}, {"def": "亥时", "example": null}, {"def": "亥hài", "example": null}, {"def": "⒈地支的末位，即第十二位。也用作次序第十二。", "example": null}, {"def": "⒉", "example": null}, {"def": "亥jiē 1.见\\"亥市\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296049942582','骇','1','hài','马','9',NULL,'[{"def": "骇", "example": null}, {"def": "(形声。从马,亥声。本义马受惊)", "example": null}, {"def": "同本义", "example": null}, {"def": "骇,惊也。--《说文》", "example": null}, {"def": "马方骇,鼓而惊之。--《汉书·梅乘传》", "example": null}, {"def": "又如骇驷(狂奔的驷马)", "example": null}, {"def": "惊骇;惊诧;惊动", "example": null}, {"def": "录事骇之。--明·高启《书博鸡者事》", "example": null}, {"def": "骇问。--清·纪昀《阅微草堂笔记》", "example": null}, {"def": "虎大骇。--唐·柳宗元《三戒》", "example": null}, {"def": "而所谓庸夫愚妇者,奔走骇汗,羞愧俯伏。--欧阳修《相州昼锦堂纪》", "example": null}, {"def": "又如骇汗(因惊恐而流汗);骇浪(骇人的大浪);骇突(受惊而乱窜);骇殚(惊惧)", "example": null}, {"def": "震动", "example": null}, {"def": "而国人大骇。--《战国策·宋策》", "example": null}, {"def": "庶人骇政。--《荀", "example": null}, {"def": "骇hài马受惊马～。〈引〉惊恐，害怕惊涛～浪。～人听闻。", "example": null}]','chinese-xinhua','0'),
('2101143296049942583','害','1','hài','宀','10',NULL,'[{"def": "害〈动〉", "example": null}, {"def": "(会意。从宀,从口,丰声。从宀”、从口”,意思是言从家起,而言”又往往是桅的根源。本义伤害,损害)", "example": null}, {"def": "同本义", "example": null}, {"def": "害,伤也。--《说文》", "example": null}, {"def": "害所得而恶也。--《墨子·经上》", "example": null}, {"def": "斗怒害也。--《荀子·臣道》", "example": null}, {"def": "害者,利之反也。--《韩非子·六反》", "example": null}, {"def": "周知其利害。--《周礼·职方式》", "example": null}, {"def": "志士仁人,无求生以害仁,有杀身以成仁。--《论语·卫灵公》", "example": null}, {"def": "邪曲之害公也。--《史记·屈原贾生列传》", "example": null}, {"def": "恐其害己。--《韩非子·五蠹》", "example": null}, {"def": "又如害心(害人害物的心思。即杀心);害马(本指损伤马的自然本性◇凡足", "example": null}, {"def": "害hài", "example": null}, {"def": "⒈祸患，坏处，跟\\"利\\"相对祸～。～处。国之大～。", "example": null}, {"def": "⒉灾患灾～。虫～。", "example": null}, {"def": "⒊有损害的～虫。～群之马。", "example": null}, {"def": "⒋使受损伤损～。伤～。～人～己。～国殃民。", "example": null}, {"def": "⒌逼迫，杀迫～。杀～。遇～。", "example": null}, {"def": "⒍患（病）～病。", "example": null}, {"def": "⒎心里产生不安的情绪有点～羞。莫～怕。别～臊。", "example": null}, {"def": "害hé 1.疑问代词。什么;什么时候。 2.副词。为什么;怎么。 3.阻止。", "example": null}]','chinese-xinhua','0'),
('2101143296049942584','氦','1','hài','气','10',NULL,'[{"def": "氦〈名〉", "example": null}, {"def": "化学元素名。一种极轻的无色惰性气态元素,是所有气体中最难液化的,存在于整个宇宙中,但只在某些天然气中含有在经济上值得提取的量,主要用于填充飞艇和气球", "example": null}, {"def": "--元素符号he", "example": null}, {"def": "氦hài化学元素。符号he。通常条件下为无色、无臭的气体，不易跟其它元素化合≤轻，可用于充填气球、电灯泡、电子管和潜水服等。", "example": null}]','chinese-xinhua','0'),
