('2101143296049942602','含','1','hán','口','7',NULL,'[{"def": "含〈动〉", "example": null}, {"def": "(形声。从口,今声。本义含在嘴里)", "example": null}, {"def": "同本义", "example": null}, {"def": "含,嗛也。--《说文》", "example": null}, {"def": "含,口也,合口亭之也。衔亦然也。--《释名·释饮食》", "example": null}, {"def": "含哺而熙,鼓腹而游。--《庄子·马蹄》", "example": null}, {"def": "生不布施,死何含珠为?--《庄子·外物》", "example": null}, {"def": "含杜若,握玉环。--《韩非子·内储说下》", "example": null}, {"def": "吾但当含饴弄孙。--《后汉书·明德马皇后传》", "example": null}, {"def": "口如含朱丹。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "儿含乳啼。--《虞初新志·秋声诗自序》", "example": null}, {"def": "含乳啼声。", "example": null}, {"def": "又如含哺(口衔食物);含殓(含口;含口垫背。死人入殓时,把珍珠等物放在死人嘴里,叫含口”。把金钱", "example": null}, {"def": "含hán", "example": null}, {"def": "⒈嘴里放着东西，不咽下去，也不吐出来～水漱口。～服药片。〈引〉藏在眼眶里饱～着泪。", "example": null}, {"def": "⒉带着，心里怀着～笑点头。～羞掩面。～怒日久。", "example": null}, {"def": "⒊包藏，里面存有包～。内～奶粉100克。", "example": null}, {"def": "⒋", "example": null}, {"def": "①不清楚，不明确话说得～ ～糊糊。", "example": null}, {"def": "②马虎，不认真这件事我们可不能～糊。", "example": null}, {"def": "③胆怯，懦弱比赛分胜负，我们绝不～糊。", "example": null}, {"def": "⒌", "example": null}, {"def": "含hàn 1.古代放在死者口中的珠﹑玉﹑米﹑贝等物。 2.指把琱放入死者口中。", "example": null}]','chinese-xinhua','0'),
('2101143296049942603','邯','1','hán','阝','7',NULL,'[{"def": "邯〈名〉", "example": null}, {"def": "古地名", "example": null}, {"def": "赵邯郸县。从邑,甘声。--《说文》。朱曰今直隶广平府邯郸县,甘地有邯山。", "example": null}, {"def": "进至邯郸。--《后汉书·光武纪》。注邯,山名。郸,尽也—山至此而尽。城郭字皆从邑,因以名焉。”", "example": null}, {"def": "又如邯郸丽步(赵地美女的优美舞蹈);邯郸梦(又称黄梁梦”)", "example": null}, {"def": "邯郸", "example": null}, {"def": "邯郸学步", "example": null}, {"def": "邯hán邯郸市，在河北省。", "example": null}, {"def": "邯hàn 1.见\\"邯淡\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296049942604','函','1','hán','凵','8',NULL,'[{"def": "函", "example": null}, {"def": "(象形。今隶误作函。本义舌)", "example": null}, {"def": "同本义", "example": null}, {"def": "圅,舌也。--《说文》", "example": null}, {"def": "若合而函吾中。--《国语·楚语》。注入也。”按,如舌之在口中也。", "example": null}, {"def": "口上曰臄,口下曰圅。--《通俗文》", "example": null}, {"def": "噱,圅舌也。--《广雅·释亲》", "example": null}, {"def": "盛物的匣子、套子", "example": null}, {"def": "函封之。--《战国策·燕策》", "example": null}, {"def": "函封。", "example": null}, {"def": "买五人之脰而函之。--明·张溥《五人墓碑记》", "example": null}, {"def": "又如蒋;镜函", "example": null}, {"def": "传达消息或指示的信件(古代寄信用木函)", "example": null}, {"def": "邮政", "example": null}, {"def": "信封", "example": null}, {"def": "发函伸纸,…。--《文选·吴", "example": null}, {"def": "函（圅）hán", "example": null}, {"def": "⒈匣(子)，套(子)钱～。得一石～。全书共五～。", "example": null}, {"def": "⒉信件，信封～件。来～已收。递送公～。发～伸纸（打开信封，拿出信纸）。", "example": null}, {"def": "⒊包含，包容～牛（容得下一头牛）之鼎沸，而蝇蚋（蚊类）弗敢入。", "example": null}]','chinese-xinhua','0'),
