('2101143296054136868','浩','1','hào','氵','10',NULL,'[{"def": "浩〈形〉", "example": null}, {"def": "(形声。从水,告声。本义水势浩大)", "example": null}, {"def": "同本义", "example": null}, {"def": "浩,浇也。从水,告声。虞书曰洪水浩浩。--《说文》。按,浇者,许以声训。”", "example": null}, {"def": "浩,遶也,水大也。--《字林》", "example": null}, {"def": "浩,浩流也。--《广雅》", "example": null}, {"def": "浩浩沅湘。--《楚辞·怀沙》", "example": null}, {"def": "浩浩瀚瀚。--《淮南子·俶真》", "example": null}, {"def": "曰浩泽。--《淮南子·地形》", "example": null}, {"def": "又如浩波(大波,洪波);浩汗(浩浩,浩然,浩瀚。水盛大的样子);浩洋(水流广阔洪大的样子)", "example": null}, {"def": "广远;盛大", "example": null}, {"def": "浩浩,滔天。--《书·尧典》。传盛大。”", "example": null}, {"def": "陈竽瑟兮浩倡。--《楚辞·东皇太一》。注大也。”", "example": null}, {"def": "又如浩壤(广阔的", "example": null}, {"def": "浩hào", "example": null}, {"def": "⒈广大～大。～瀚。～如烟海。", "example": null}, {"def": "①水大的样子洪水奔流，～ ～滔天。", "example": null}, {"def": "②广大～～苍天。", "example": null}, {"def": "⒉多～繁。", "example": null}, {"def": "浩gé 1.见\\"浩亹\\"。", "example": null}, {"def": "浩gǎo 1.以水滤酒。参见\\"浩酒\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296054136869','耗','1','hào','耒','10',NULL,'[{"def": "耗〈名〉", "example": null}, {"def": "(形声。从耒,毛声。本义一种稻子)", "example": null}, {"def": "消息;音信", "example": null}, {"def": "赤岭久无耗,鸿门犹合围。--李商隐《即日》", "example": null}, {"def": "又如耗音(音耗,音信,消息);耗问(消息;音信);耗息(消息);恶耗,凶耗", "example": null}, {"def": "方言称老鼠为耗子”。也简称耗”", "example": null}, {"def": "旧时官府征收钱粮时,以损耗为名,在正额外例有附加部分,称耗”", "example": null}, {"def": "耗 〈动〉", "example": null}, {"def": "假借为消”。亏损;消耗", "example": null}, {"def": "耗,消也。--《苍颉篇》", "example": null}, {"def": "永尝敢以耗气也。--《庄子·达生》。司马注损也。”", "example": null}, {"def": "改煎金锡则不耗。--《考工记·函人为量》", "example": null}, {"def": "耗,减", "example": null}, {"def": "耗hào", "example": null}, {"def": "⒈亏损，消费损～。消～。～钱～财。", "example": null}, {"def": "⒉拖延～时。别～着了，快做事吧！", "example": null}, {"def": "⒊音信，消息久无音～。噩～（人死的消息）。", "example": null}, {"def": "耗máo 1.罄尽，没有。", "example": null}, {"def": "耗mào 1.昏乱不明。", "example": null}]','chinese-xinhua','0'),
