('2101143296066719745','核','1','hé','木','10',NULL,'[{"def": "核", "example": null}, {"def": "(形声。从木,亥声。本义果核)", "example": null}, {"def": "同本义", "example": null}, {"def": "核,蛮夷以木皮为箧,状如籢尊。--《说文》", "example": null}, {"def": "桃李丑核。--《尔雅·释木》", "example": null}, {"def": "殽核维旅。--《诗·小雅·宾之初筵》", "example": null}, {"def": "其实濡核。--《素问·五常正大论》", "example": null}, {"def": "贻余核舟。--明·魏学洢《核舟记》", "example": null}, {"def": "桃核修狭者。", "example": null}, {"def": "又如枣核;樱桃核;葡萄核;橘核", "example": null}, {"def": "原子核的简称", "example": null}, {"def": "有核的果实", "example": null}, {"def": "门启,华堂复阁甚秀,馆中有樽酒盘核。--《太平广记》引", "example": null}, {"def": "核心;中心", "example": null}, {"def": "文吏不学,世之教无核也。--王", "example": null}, {"def": "核（", "example": null}, {"def": "⒋覈）hé", "example": null}, {"def": "⒈果实中心坚硬并包含果仁的部分桃～。枣～。杏～。", "example": null}, {"def": "⒉像核的东西细胞～。原子～。", "example": null}, {"def": "⒊核能，原子核等～电站。地下～试验。避免～战争。消毁～武器。", "example": null}, {"def": "⒋考察，仔细地对照审～。考～。～实。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍见gāi、kài。", "example": null}, {"def": "核hú", "example": null}, {"def": "⒈用于某些口语，如杏～。枣～儿。桃～儿。煤～儿等。", "example": null}, {"def": "⒉见hé。", "example": null}]','chinese-xinhua','0'),
('2101143296066719746','盍','1','hé','皿','10',NULL,'[{"def": "盍", "example": null}, {"def": "(会意。本作盿”,从血,从大。段玉裁《说文解字注》皿中有血而上覆之,覆必大于下,故从大。”本义覆盖) 合", "example": null}, {"def": "盍簪喧枥马,列炬散林鸦。--杜甫《杜位宅守岁》", "example": null}, {"def": "又如盍簪(友人聚会;朋友);盍朋簪(朋友聚会);盍彻(施行仁政)", "example": null}, {"def": "盍", "example": null}, {"def": "何不(盍是何不”的合音)", "example": null}, {"def": "盍,何不也。--《玉篇》", "example": null}, {"def": "盍请济师于王?--《左传·桓公十一年》", "example": null}, {"def": "子盍从众?--《左传·成公六年》", "example": null}, {"def": "子盍诘盗?--《左传·襄公二十一年》", "example": null}, {"def": "盍杀我?--《国语·晋语一》", "example": null}, {"def": "盍反其本。--《孟子·梁惠王上》", "example": null}, {"def": "祭酒计甚善,王盍用之?--《新唐书》", "example": null}, {"def": "盍（盿）hé何不，何～往观之。～不出走。", "example": null}, {"def": "盍kě 1.见\\"盍旦\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296066719747','荷','1','hé','艹','10',NULL,'[{"def": "荷〈名〉", "example": null}, {"def": "(形声。从苃,何声。本义植物名。也称莲,别称芙蕖、芙蓉。地下茎称藕,子实称莲,花叶供观赏)", "example": null}, {"def": "植物名。即莲", "example": null}, {"def": "荷,芙蕖叶。--《说文》", "example": null}, {"def": "隰有荷华。--《诗·郑风·山有扶苏》", "example": null}, {"def": "有蒲与荷。--《诗·陈风·泽陂》", "example": null}, {"def": "荷叶之清香。--明·李渔《闲情偶寄·种植部》", "example": null}, {"def": "又如荷月(指农历六月,以荷花盛开,故名荷月);荷衣(荷叶);荷芰(莲与菱);荷花(莲花。也作莲华”、荷华”);荷扇(荷叶形圆似团扇,故雅称为荷扇)", "example": null}, {"def": "荷叶", "example": null}, {"def": "荷hé", "example": null}, {"def": "⒈莲。也叫\\"芙蕖\\"、\\"菡萏\\"。多年生草本，生长在浅水中。叶大而圆，花粉红或白色。地下茎叫藕，种子叫莲子，都可吃∩叶和藕节可供药用。", "example": null}, {"def": "荷hè", "example": null}, {"def": "⒈扛，承当，担任～锄。～枪。～担。负～。～天下之重任。", "example": null}, {"def": "⒉感激别人的关心或帮助，常用在书信里。〈表〉礼貌深深感～。特致谢为～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌见hekz。", "example": null}, {"def": "荷kē 1.苛细;繁琐。", "example": null}, {"def": "荷hē 1.通\\"诃\\"。查察;诘问。 2.见\\"荷荷\\"。", "example": null}]','chinese-xinhua','0'),
