('2101143296066719777','褐','1','hè','衤','14',NULL,'[{"def": "褐〈名〉", "example": null}, {"def": "(形声。从衣,曷声。本义用粗麻织成的袜子)", "example": null}, {"def": "同本义", "example": null}, {"def": "褐,编枲袜。--《说文》。段玉裁注取未绩之麻,编之为足衣,如今草韕之类。”", "example": null}, {"def": "指粗布或粗布衣;最早用葛、兽毛,后通常指大麻、兽毛的粗加工品,古时贫贱人穿", "example": null}, {"def": "无衣无褐,何以卒岁。--《诗·豳风·七月》。郑玄笺褐,毛布也。”", "example": null}, {"def": "从者衣褐。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "又如褐巾(用粗布缝成的头巾);褐衣(粗布衣。借指平民);褐衫(粗布衣);褐夫(穿粗布衣服的人。指贫贱的人)", "example": null}, {"def": "卑贱的人", "example": null}, {"def": "褐hè", "example": null}, {"def": "⒈粗布或粗布衣服无衣无～，何以卒岁（卒岁过完一年）。", "example": null}, {"def": "⒉黄黑色～色。", "example": null}]','chinese-xinhua','0'),
('2101143296066719778','赫','1','hè','赤','14',NULL,'[{"def": "赫〈形〉", "example": null}, {"def": "(会意。从二赤。火赤。本义泛指赤色)", "example": null}, {"def": "红如火烧。亦泛指火红色", "example": null}, {"def": "赫,火赤貌。--《说文》", "example": null}, {"def": "赫如渥赭。--《诗·邶风·简兮》", "example": null}, {"def": "如赫日(红日);赫赤(深红;火红);赫赤赤(谓赤红如火);赫煌(赤色光明的样子)", "example": null}, {"def": "显耀", "example": null}, {"def": "以赫厥灵。--《诗·大雅·生民》", "example": null}, {"def": "又如赫奕(显耀盛大的样子);赫剌剌(威武显赫的样子);赫耀(显赫)", "example": null}, {"def": "显盛", "example": null}, {"def": "赫赫楚国,而君临之。--《国语·楚语》", "example": null}, {"def": "又如赫奕(光彩灿烂的样子);赫奕(显著盛大的样子);赫张(声势盛大的样子)", "example": null}, {"def": "炎热炽盛", "example": null}, {"def": "赫hè", "example": null}, {"def": "⒈火红色～如渥（浓厚）赭（红褐色）。", "example": null}, {"def": "⒉显著，显耀，盛大显～。辉～。～ ～有名。", "example": null}, {"def": "⒊发怒的样子～如雷霆。～ ～震怒。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "赫xì 1.见\\"赫蹏\\"。", "example": null}, {"def": "赫xià 1.吓唬;使害怕。", "example": null}]','chinese-xinhua','0'),
('2101143296066719779','鹤','1','hè','鸟','15',NULL,'[{"def": "鹤", "example": null}, {"def": "(形声。从鸟,隺声。本义鹤科各种类鸟的统称,皆为大型涉禽)同本义", "example": null}, {"def": ",羽毛更紧密,部分秃顶,嘴较钝并在近中央处有较大鼻孔,后趾向上抬起", "example": null}, {"def": "鹤,似鹄长喙。--《广韵》", "example": null}, {"def": "鹤鸣于九皋。--《诗·小雅·鹤鸣》", "example": null}, {"def": "腾群鹤于瑶光。--《楚辞·刘向·九叹·远游》", "example": null}, {"def": "又如鹤音(鹤鸣声);鹤侣(鹤的伴侣);鹤唳(鹤鸣);鹤胫(鹤的小腿);鹤语(鹤的叫声)", "example": null}, {"def": "鹤", "example": null}, {"def": "比喻白色", "example": null}, {"def": "鹤hè鸟儿，要保护，禁止猎杀。它的头小，颈和脚细长，嘴长而直，翼大善飞，羽毛白色或灰色。常见的是白～，又叫\\"仙～\\"、\\"丹顶～\\"。羽毛白色，头顶红色，叫声高而清脆", "example": null}, {"def": "。捕食鱼、虾等。", "example": null}]','chinese-xinhua','0'),
('2101143296066719780','壑','1','hè','土','17',NULL,'[{"def": "壑〈名〉", "example": null}, {"def": "(会意。本义深谷,深沟)", "example": null}, {"def": "同本义", "example": null}, {"def": "壑,沟也。--《说文》", "example": null}, {"def": "壑,溪壑也。--《尔雅·释诂》", "example": null}, {"def": "陆峦超壑。--《文选·张衡·西京赋》", "example": null}, {"def": "既窈窕以寻壑。--晋·陶渊明《归去来兮辞》", "example": null}, {"def": "林壑尤美。--宋·欧阳修《醉翁亭记》", "example": null}, {"def": "峭壑阴森。--《徐霞客游记·游黄山记》", "example": null}, {"def": "众壑纵横。", "example": null}, {"def": "如怒涛排壑。--孙文《序》", "example": null}, {"def": "又如壑谷(山谷;两山之间的洼地或水道);壑口(豁口,像山谷一样的缺口);壑子(豁口;缺口)", "example": null}, {"def": "小河沟;护城河", "example": null}, {"def": "实墉实壑,实亩实籍。--《诗·大雅·韩奕》。陆德明释文壑,城池也。”", "example": null}, {"def": "壑hè沟一～之水。〈引〉山沟千岩万～。众～纵横。", "example": null}]','chinese-xinhua','0'),
