('2101143296066719803','恨','1','hèn','忄','9',NULL,'[{"def": "恨〈动〉", "example": null}, {"def": "(形声。从心,艮声。本义怀恨在心,怨恨)", "example": null}, {"def": "同本义", "example": null}, {"def": "恨,怨也。--《说文》", "example": null}, {"def": "今财亡民罢,莫不怨恨。--《国语·周语下》", "example": null}, {"def": "役夫敢申恨。--唐·杜甫《兵车行》", "example": null}, {"def": "恨贯肌骨。--唐·李朝威《柳毅传》", "example": null}, {"def": "亡国之恨。--清·黄宗羲《柳敬亭传》", "example": null}, {"def": "又如恨命(恨恨地;拼命);恨恨(气 忿的样子);恨穷发极(愤恨到极点而发怒);恨五骂六(投骰子时的叫骂声);恨如头醋(比喻非常可恶,令人恨得切齿)", "example": null}, {"def": "遗憾;后悔", "example": null}, {"def": "臣死不恨矣!--《史记·萧相国世家》", "example": null}, {"def": "故死者不抱恨而入地,生者不衔怨而受罪。--《汉书·王嘉传》", "example": null}, {"def": "公子恨之复返。--", "example": null}, {"def": "恨hèn", "example": null}, {"def": "⒈遗憾，不满意～事。遗～。悔～。懊～。", "example": null}, {"def": "⒉怨，仇视怨～。仇～。民族～。～之入骨。", "example": null}]','chinese-xinhua','0'),
('2101143296066719804','很','1','hěn','彳','9',NULL,'[{"def": "很", "example": null}, {"def": "(形声。从彳,艮声。本义违逆,不听从)", "example": null}, {"def": "同本义", "example": null}, {"def": "很,不听从也。--《说文》", "example": null}, {"def": "美而很。--《左传·襄公二十六年》。服注戾不从教。”", "example": null}, {"def": "今王将很天而伐齐--《国语·吴语》", "example": null}, {"def": "又如很子(忤逆的儿子);很忤;很触(违犯", "example": null}, {"def": "争斗;争讼", "example": null}, {"def": "很毋求胜,分毋求多。--《礼记·曲礼》", "example": null}, {"def": "狠命", "example": null}, {"def": "很", "example": null}, {"def": "凶恶,残忍;暴戾,乖戾。假借为狠”", "example": null}, {"def": "大子痤美而很。--《左传·", "example": null}, {"def": "很hěn副词。非常，〈表〉程度高深～好的。～美丽。～热烈。～受欢迎。", "example": null}]','chinese-xinhua','0'),
('2101143296066719805','狠','1','hěn','犭','9',NULL,'[{"def": "狠〈形〉", "example": null}, {"def": "(形声。从犬,艮声。本义犬争斗声。又指凶狠,残忍)", "example": null}, {"def": "通很”。凶狠;凶残", "example": null}, {"def": "有能耐的,有本领的", "example": null}, {"def": "坚决", "example": null}, {"def": "狠 〈动〉", "example": null}, {"def": "下定决心", "example": null}, {"def": "他爱钱如命,可是为维持事情,不得不狠了心。--老舍《骆驼祥子》", "example": null}, {"def": "吃", "example": null}, {"def": "两人登时狠了七碗。--《金瓶梅》", "example": null}, {"def": "狠 〈副〉", "example": null}, {"def": "非常。同很”", "example": null}, {"def": "这家子远得狠哩!相去有五七千里之路。--《", "example": null}, {"def": "狠hěn", "example": null}, {"def": "⒈凶恶，残忍凶～。手段～毒。", "example": null}, {"def": "⒉严厉对敌～，对己和。～～打击贪污腐化。～ ～地镇压车匪路霸。", "example": null}, {"def": "⒊勉强抑制～着心把泪水止住。", "example": null}, {"def": "⒋坚决，全力以赴～抓科学技术。～命地奔跑。", "example": null}, {"def": "⒌同\\"很\\"好得～ 。", "example": null}, {"def": "狠hǎng 1.怨恨。", "example": null}]','chinese-xinhua','0'),
