('2101143296066719808','恒','1','hénɡ','忄','9',NULL,'[{"def": "恒", "example": null}, {"def": "(会意。金文,从心,从月,从二。二”,表示天地。本义永久,永恒)", "example": null}, {"def": "同本义", "example": null}, {"def": "恒,常也。--《说文》", "example": null}, {"def": "恒者,久也。--《易·序卦传》", "example": null}, {"def": "恒,德之固也。--《易·系辞下传》", "example": null}, {"def": "无恒安处。--《诗·小雅·小明》", "example": null}, {"def": "以求其恒。--唐·柳宗元《柳河东集》", "example": null}, {"def": "又如恒牙(恒齿。永久齿);恒风(持续吹佛的风);恒舞(历时长而不中断的舞);恒制(长久不变的法则)", "example": null}, {"def": "寻常;普通", "example": null}, {"def": "形貌奇伟,骨体不恒。--《三国志·吴主传》", "example": null}, {"def": "人恒状。--唐·柳宗元《童区寄传》", "example": null}, {"def": "又如恒态(常态);恒恣(经常的状态);恒情(常情);恒品", "example": null}, {"def": "恒（恆）héng", "example": null}, {"def": "⒈经常，常常，一般～言。～态。蜀（四川）之南，～雨少日。", "example": null}, {"def": "⒉永久，持久～久。有～心。永～。持之以～。", "example": null}, {"def": "⒊", "example": null}, {"def": "恒gèng 1.月上弦之貌。 2.周遍。 3.通\\"亘\\"。绵延;连续。", "example": null}]','chinese-xinhua','0'),
('2101143296066719809','桁','1','hénɡ','木','10',NULL,'[{"def": "桁〈名〉", "example": null}, {"def": "古代用于加在囚犯颈部的一种木刑具", "example": null}, {"def": "浮桥", "example": null}, {"def": "桁杨", "example": null}, {"def": "桁〈名〉", "example": null}, {"def": "梁上或门框、窗框等上的横木", "example": null}, {"def": "屋桁,屋横木也。--《玉篇》", "example": null}, {"def": "桁梧复叠。--《文选·曹植·洛神赋》。注桁,梁上所施也。”", "example": null}, {"def": "又如桁架", "example": null}, {"def": "葬具。长而矮的木几,用来摆设陪葬的明器,埋入圹内", "example": null}, {"def": "皆木桁,久之。--《礼仪》", "example": null}, {"def": "桁架", "example": null}, {"def": "桁héng梁上的横木（檩子）。", "example": null}, {"def": "桁háng 1.大械。古代加在犯人颈上或脚上的刑具。 2.航，浮桥。 3.量词。用于成横行的东西。", "example": null}, {"def": "桁hàng 1.衣架。 2.指晒衣竿。", "example": null}]','chinese-xinhua','0'),
