('2101143296066719857','鸿','1','hónɡ','鸟','11',NULL,'[{"def": "鸿", "example": null}, {"def": "(形声。从鸟,江声。本义大雁)", "example": null}, {"def": "同本义", "example": null}, {"def": "鸿,鹄也。--《说文》", "example": null}, {"def": "鸿渐于干。--《易·渐》", "example": null}, {"def": "鸿雁于飞。--《诗·小雅·鸿雁》", "example": null}, {"def": "又如鸿冥(鸿鸟飞入苍冥);鸿飞(鸿鸟飞翔);鸿爪(比喻往事遗留的痕迹);鸿渐(鸿鸟飞翔由低处逐渐进于高位。比喻官职升迁或渐入佳境);鸿嗷(鸿鸟哀鸣,比喻灾民的悲号)", "example": null}, {"def": "鹄。即天鹅", "example": null}, {"def": "燕雀安知鸿鹄之志。--《史记·陈涉世家》。按,凡鸿鹄连文者即鹄也。", "example": null}, {"def": "又如鸿骞凤立(鸿鹄高飞,凤凰挺立。比喻超群杰出);鸿翼(天鹅的羽翼);鸿举(天鹅高飞远翔)", "example": null}, {"def": "喻指", "example": null}, {"def": "鸿hóng", "example": null}, {"def": "⒈大型雁类的泛称。", "example": null}, {"def": "⒉通\\"洪\\"￠水禹有功，抑（遏制）下～。", "example": null}, {"def": "⒊大～文。～图。", "example": null}, {"def": "鸿hòng 1.见\\"鸿絧\\"。", "example": null}]','chinese-xinhua','0'),
