('2101143296070914076','候','1','hòu','亻','10',NULL,'[{"def": "候〈动〉", "example": null}, {"def": "(形声。古文作矦”。从人,侯声。本义守望;侦察)", "example": null}, {"def": "同本义", "example": null}, {"def": "矦,伺望也。--《说文》", "example": null}, {"def": "矦,覗也。--《广雅·释诂三》", "example": null}, {"def": "市有候馆。--《周礼·遗人》。注楼可以观望者也。”", "example": null}, {"def": "又如候馆(用以瞭望的高楼);候楼(用以瞭望的楼);侯遮(侦探敌情);候徼(在国境线上巡察警戒);候车(侦察敌情的战车)", "example": null}, {"def": "观测", "example": null}, {"def": "等候", "example": null}, {"def": "稚子候门。--晋·陶渊明《归去来兮辞》", "example": null}, {"def": "即候苗成。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "候春发遣。--清·方苞《狱中杂记》", "example": null}, {"def": "移顺天府", "example": null}, {"def": "候hòu", "example": null}, {"def": "⒈等待～车。～补。等～。", "example": null}, {"def": "⒉看望，问好特意问～。", "example": null}, {"def": "⒊征兆，时节征～。气～。季～。～鸟。时～到了。", "example": null}, {"def": "⒋事物变化中的情况火～。症～。", "example": null}, {"def": "⒌守望，观测，窥视～望。～伺。", "example": null}]','chinese-xinhua','0'),
('2101143296070914077','堠','1','hòu','土','12',NULL,'[{"def": "堠〈名〉", "example": null}, {"def": "(形声。从土,侯声。本义古代瞭望敌情的土堡)", "example": null}, {"def": "同本义", "example": null}, {"def": "古代记里程的土堆", "example": null}, {"def": "堠,牌堠,吾里一堠。--《玉篇》", "example": null}, {"def": "堠hòu", "example": null}, {"def": "⒈〈古〉瞭望敌情的土堡，哨所。", "example": null}, {"def": "⒉〈古〉记里程的土堆古～。", "example": null}]','chinese-xinhua','0'),
