('2101143296070914081','侯','1','hòu','亻','9',NULL,'[{"def": "侯", "example": null}, {"def": "(象形。从人,从厂,象张布,矢在其下。甲骨文字形,象射侯张布著矢之形。本义箭靶)", "example": null}, {"def": "同本义。以兽皮或画上兽形的为之", "example": null}, {"def": "矦,春饷所射矦也。--《说文》", "example": null}, {"def": "终日射侯。--《诗·齐风·猗嗟》", "example": null}, {"def": "射有张布谓之矦。--《小尔雅·广器》", "example": null}, {"def": "方十尺曰矦,四尺曰鹄,二尺曰正,四寸曰质。", "example": null}, {"def": "张矦。--《左传·成公二年》", "example": null}, {"def": "又如侯弓(古代较射时用以射侯之弓☆,箭靶);侯道(箭靶与射者间的距离)", "example": null}, {"def": "诸侯", "example": null}, {"def": "内诸侯禄也,外诸侯嗣也。--《礼记·王制》", "example": null}, {"def": "诸侯则共熊侯豹侯。--《周礼·司裘》。注", "example": null}, {"def": "侯hóu", "example": null}, {"def": "⒈〈古〉五等爵位的第二等公～伯子男。秦汉以后仅次于王的爵位王～将相宁有种乎！", "example": null}, {"def": "⒉泛指达官贵人～门似海。", "example": null}, {"def": "⒊箭靶终日射～，不出正兮（正靶的中心）。", "example": null}, {"def": "侯hòu", "example": null}]','chinese-xinhua','0'),
('2101143296070914082','吼','1','hǒu','口','7',NULL,'[{"def": "喉〈名〉", "example": null}, {"def": "喉头", "example": null}, {"def": "喉,咽也。--《说文》", "example": null}, {"def": "喉咽者,量肠之府也。--《后汉书·马融传》", "example": null}, {"def": "断其喉。--唐·柳宗元《三戒》", "example": null}, {"def": "又如喉吻(喉头与嘴唇);喉头气 (因生气发怒而感到喉头憋闷);喉韵(饮茶后喉头产生的甘爽的回味)", "example": null}, {"def": "喻要害之地;交通要道", "example": null}, {"def": "吼hǒu", "example": null}, {"def": "⒈兽大声叫狮～。", "example": null}, {"def": "⒉人在情绪激昂或愤怒时发出的巨大声音人民的～声。战士怒～。", "example": null}, {"def": "⒊泛指很大的声音狂风～。", "example": null}]','chinese-xinhua','0'),
