('2101143296070914093','囫','1','hú','囗','7',NULL,'[{"def": "囫 (形声。从囗,勿声)", "example": null}, {"def": "囫囵个儿", "example": null}, {"def": "由于家里穷,他小时候没穿过一件囫囵个儿的衣裳", "example": null}, {"def": "这么大的丸子他囫囵个儿吃下去了", "example": null}, {"def": "他累极了,刚往炕上一歪,就囫囵个儿睡着了", "example": null}, {"def": "囫囵吞枣", "example": null}, {"def": "囫hú", "example": null}]','chinese-xinhua','0'),
('2101143296070914094','弧','1','hú','弓','8',NULL,'[{"def": "弧〈名〉", "example": null}, {"def": "(形声。从弓,瓜声。本义木弓)", "example": null}, {"def": "同本义;泛指弓", "example": null}, {"def": "弧,木弓也。--《说文》", "example": null}, {"def": "弦木为弧。--《易·系传》", "example": null}, {"def": "檿弧箕服。--《国语·郑语》", "example": null}, {"def": "弧弓夭猎。--《汉书·韩安国传》", "example": null}, {"def": "又如弧弓(古代六弓之一。其力强,可以远射甲革坚硬之物。六弓王弓、弧弓、夹弓、庚弓、唐弓、大弓);孤矢(弓箭);孤室(弓袋);弧弦(开弓张弦)", "example": null}, {"def": "张旗用的竹弓", "example": null}, {"def": "载弧屬。--《礼记·明堂位》", "example": null}, {"def": "又如弧旌枉矢(谓以竹弓张悬旌旗的正幅,并在弓衣上绘流矢,作弧矢星状,以象征武事)", "example": null}, {"def": "弯曲如弓", "example": null}, {"def": "采其有弧矢之威。--《礼记·大射仪》注", "example": null}, {"def": "燕弧", "example": null}, {"def": "弧hú", "example": null}, {"def": "⒈木弓。", "example": null}, {"def": "⒉圆周的一段画个～形。一条～线。加括～。", "example": null}]','chinese-xinhua','0'),
('2101143296070914095','狐','1','hú','犭','8',NULL,'[{"def": "狐", "example": null}, {"def": "(形声。从犬,瓜声。本义狐狸)", "example": null}, {"def": "同本义", "example": null}, {"def": "朕狐疑。--《汉书·文帝纪》。注狐性多疑,每渡冰河,且听且渡,故言疑者称狐疑。”", "example": null}, {"def": "小狐汔济。--《易·未济》", "example": null}, {"def": "狐鸣呼曰。--《史记·陈涉世家》", "example": null}, {"def": "狐裘不暖锦衾薄。--唐·岑参《白雪歌送武判官归京》", "example": null}, {"def": "狐凭鼠伏。--《广东军务记》", "example": null}, {"def": "又如狐丘(狐穴居之小山);狐白(狐腋下的白毛);狐兔(狐和兔);狐仙(传说狐狸能修炼成仙,化为人形,与人来往)", "example": null}, {"def": "喻坏人,小人", "example": null}, {"def": "狐hú", "example": null}, {"def": "⒈通称\\"狐狸\\"，属受保护的动物，禁止猎杀。它的形状略像狼，面部较长，吻尖，尾长，尾毛蓬松。尾部能分泌恶臭，遇敌时从肛门放出，乘机逃跑。毛多为赤褐色。性狡猾，", "example": null}, {"def": "多疑，昼伏夜出，捕食鼠、鸟、家禽等。毛皮柔软，可做衣、帽等。今已能人工养殖。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
