('2101143296070914132','护','1','hù','扌','7',NULL,'[{"def": "护", "example": null}, {"def": "(形声。从言,蒦声。本义保卫;保护)", "example": null}, {"def": "同本义", "example": null}, {"def": "吏护还之乡。--唐·柳宗元《童区寄传》", "example": null}, {"def": "吾欲护汝。--明·魏禧《大铁椎传》", "example": null}, {"def": "从我杀贼护家室。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "贯铁絙护之。", "example": null}, {"def": "又如护队(行军所设防卫的军队);护藏(保护经藏);护梁(城楼上作护卫用的横梁);护镜(护心镜。衣甲上用以防护前心和后心的铜镜)", "example": null}, {"def": "爱护", "example": null}, {"def": "备极护爱。--《聊斋志异·促织》", "example": null}, {"def": "又如护书(收放文书用的长方形木匣子);护头(小孩子不肯剃头发);护槽(马吃草时,人难接近)", "example": null}, {"def": "袒护;包庇", "example": null}, {"def": "护（護）hù", "example": null}, {"def": "⒈保卫，照顾～卫。～厂。～航。～理。保～。爱～。〈引〉掩盖，包庇莫～短。你不要～着他。", "example": null}, {"def": "⒉", "example": null}, {"def": "①外交机构发给本国公民证明身份的执照，在进入另一国停留时使用。", "example": null}, {"def": "②旧时旅行或运货时所带的政府机关证明文件。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296070914133','沪','1','hù','氵','7',NULL,'[{"def": "沪", "example": null}, {"def": "捕鱼的竹栅", "example": null}, {"def": "潮生鱼沪短,风起鸭船斜。--陆游《村舍》", "example": null}, {"def": "列竹于海澨曰沪。--唐·陆龟蒙《渔具》诗序", "example": null}, {"def": "上海的简称", "example": null}, {"def": "沪（滬）hù", "example": null}, {"def": "⒈上海的简称。因境内的吴松江下流古称\\"沪渎\\"而得名。", "example": null}, {"def": "⒉捕鱼的竹栅。", "example": null}]','chinese-xinhua','0'),
('2101143296070914134','岵','1','hù','山','8',NULL,'[{"def": "岵〈名〉", "example": null}, {"def": "多草木的山", "example": null}, {"def": "山匪阻而是岵,川有清而无浊。--《宋书》", "example": null}, {"def": "岵hù多草木的山。", "example": null}]','chinese-xinhua','0'),
('2101143296070914135','怙','1','hù','忄','8',NULL,'[{"def": "怙〈动〉", "example": null}, {"def": "(形声。从心,古声。本义依仗,凭借)", "example": null}, {"def": "同本义", "example": null}, {"def": "怙,恃也。--《说文》", "example": null}, {"def": "无父何怙,无母何恃。--《诗·小雅·蓼莪》", "example": null}, {"def": "怙其俊才。--《左传·宣公十五年》", "example": null}, {"def": "怙势作威。--柳宗元《封建论》", "example": null}, {"def": "又如怙气(仗持勇气);怙终(仗恃作恶,终不悔改);怙势(倚恃权势);怙险(凭恃险固)", "example": null}, {"def": "坚持", "example": null}, {"def": "怙", "example": null}, {"def": "父母的合称", "example": null}, {"def": "孩失其怙,幼丧所亲;旁无弟兄,藐然一身。--白居易《寄乌江十五兄文》", "example": null}, {"def": "父亲", "example": null}, {"def": "怙、恃二字,分言之,父曰怙,母曰恃…合言之,父母", "example": null}, {"def": "怙hù依仗，凭恃～势作威。～恶不悛（一贯作恶，不肯悔改）。", "example": null}]','chinese-xinhua','0'),
('2101143296070914136','戽','1','hù','户','8',NULL,'[{"def": "戽", "example": null}, {"def": "(形声。从斗,户声。本义戽斗) 同本义。也指吸水灌田的农具", "example": null}, {"def": "戽", "example": null}, {"def": "用戽斗汲水", "example": null}, {"def": "用龙骨车汲水", "example": null}, {"def": "戽斗", "example": null}, {"def": "戽hù", "example": null}, {"def": "⒈戽斗，取水灌田的旧时农具，形状像斗，两边有绳，由两人拉绳牵斗取水。", "example": null}, {"def": "⒉用戽斗取水灌田～水抗旱。", "example": null}]','chinese-xinhua','0'),
