('2101143296075108434','焕','1','huàn','火','11',NULL,'[{"def": "焕", "example": null}, {"def": "(形声。从火,奂声。本义火光) 同本义", "example": null}, {"def": "焕,火光也。--《说文新附》", "example": null}, {"def": "焕", "example": null}, {"def": "光亮,鲜明", "example": null}, {"def": "焕乎其有文章。--《论语》。集解明也。”", "example": null}, {"def": "又如焕乎(光亮的样子);焕炳(光耀明亮);焕发(光彩四现);焕焕(显赫的样子)", "example": null}, {"def": "闪耀强烈光亮的", "example": null}, {"def": "焕", "example": null}, {"def": "照耀;焕发光彩,放射光芒", "example": null}, {"def": "焕huàn鲜明，光亮。", "example": null}]','chinese-xinhua','0'),
('2101143296075108435','逭','1','huàn','辶','11',NULL,'[{"def": "逭", "example": null}, {"def": "逃避", "example": null}, {"def": "逭,逃也。--《说文》", "example": null}, {"def": "行相避逃谓之逭。--《尔雅·释言樊》", "example": null}, {"def": "又如逭署(避署);逭诛(逃避杀头);逭责(逃避责任);逭咎(逃避责任)", "example": null}, {"def": "免除", "example": null}, {"def": "如逭我罪,施材百具,絮衣百领,肯之乎?--《聊斋志异》", "example": null}, {"def": "又如逭劳(消除疲劳)", "example": null}, {"def": "更迭", "example": null}, {"def": "逭,迭也。--《玉篇》", "example": null}, {"def": "逭huàn避，逃～暑。罪不可～。", "example": null}]','chinese-xinhua','0'),
