('2101143296075108461','閎','1','huánɡ','','13',NULL,'[{"def": "閎huáng", "example": null}, {"def": "⒈〈古〉一种兵器。", "example": null}, {"def": "⒉钟鼓声钟声～ ～。", "example": null}]','chinese-xinhua','0'),
('2101143296075108462','崲','1','huánɡ','','9',NULL,'[{"def": "崲huáng 1.地名用字。休崲湖，见《宋书．谢灵运传》。", "example": null}]','chinese-xinhua','0'),
('2101143296075108463','徨','1','huánɡ','彳','12',NULL,'[{"def": "徨徨", "example": null}, {"def": "侧焉徨徨商去留。--龚自珍《尊隐》", "example": null}, {"def": "徨huáng", "example": null}]','chinese-xinhua','0'),
('2101143296075108464','惶','1','huánɡ','忄','12',NULL,'[{"def": "惶", "example": null}, {"def": "(形声。从心,皇声。本义恐惧,惊慌) 同本义", "example": null}, {"def": "惶,惶恐也。--《说文》", "example": null}, {"def": "惶,惧也。--《广雅》", "example": null}, {"def": "秦王方环柱走,卒惶急,不知所为。--《史记·刺客列传》", "example": null}, {"def": "孟贲狎猛虎而不惶。--《潜夫论·卜列》", "example": null}, {"def": "多官惶惶,只得散去。--明·梦觉道人《三刻拍案惊奇》", "example": null}, {"def": "又如惶惶(惊恐不安);遑迫(惊慌);惶汗(惊惧而汗流);惶沮(恐惧沮丧);惶怖(恐惧害怕)", "example": null}, {"def": "惶huáng恐惧，惊慌～惑。～恐。～ ～不可终日。", "example": null}]','chinese-xinhua','0'),
('2101143296075108465','湟','1','huánɡ','氵','12',NULL,'[{"def": "湟", "example": null}, {"def": "水名", "example": null}, {"def": "湟,湟水也。出金城临羌塞外,东入河。--《说文》", "example": null}, {"def": "城池", "example": null}, {"def": "湟池纡曲。--枚乘《七发》。注城池也。”", "example": null}, {"def": "又如湟潦(低洼积水处)", "example": null}, {"def": "湟huáng", "example": null}, {"def": "⒈低洼的地方。", "example": null}, {"def": "⒉湟水，在青海省。", "example": null}]','chinese-xinhua','0'),
('2101143296075108466','葟','1','huánɡ','','9',NULL,'[{"def": "葟huáng 1.花美貌。", "example": null}]','chinese-xinhua','0'),
('2101143296075108467','遑','1','huánɡ','辶','12',NULL,'[{"def": "遑", "example": null}, {"def": "(形声。从辵,皇声。本义急迫)", "example": null}, {"def": "同本义", "example": null}, {"def": "墨子遑遑,闵世也。--《盐铁论·散不足》", "example": null}, {"def": "又如遑急(急迫不安);遑遽(急迫不安,恐惧慌张)", "example": null}, {"def": "通惶”。恐惧", "example": null}, {"def": "权于是大怒,手剑欲击之,侍坐者莫不遑遽。--《三国志·虞翻传》", "example": null}, {"def": "戚戚然以至于死,此天民之遑遽者也。--《列子·杨朱》", "example": null}, {"def": "满堂变容,迥遑如失。--谢庄《月赋》", "example": null}, {"def": "仲达闻阵而惕惕,子丹望风而遑遑!--明·梦觉道人《三刻拍案惊奇》", "example": null}, {"def": "遑", "example": null}, {"def": "空闲;闲暇", "example": null}, {"def": "遑,暇也。--《玉篇》", "example": null}, {"def": "何斯违斯?莫敢或遑。--《诗·召南·殷其雷》", "example": null}, {"def": "自朝至于日中昃,", "example": null}, {"def": "遑huáng", "example": null}, {"def": "⒈闲暇，空闲不～（没有空闲）。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296075108468','煌','1','huánɡ','火','13',NULL,'[{"def": "煌", "example": null}, {"def": "(形声。从火,皇声。皇”亦兼表字义。本义光明;光亮)", "example": null}, {"def": "同本义", "example": null}, {"def": "煌,煌煇也。--《说文》", "example": null}, {"def": "煌,光也。--《苍颉篇》", "example": null}, {"def": "煌光驰而星流。--《东京赋》", "example": null}, {"def": "煌然而成篇谓之篇。--姚华《论文后编》", "example": null}, {"def": "又如煌煌烨烨(明亮光辉。形容火势旺盛);煌熠(光明灿烂);煌荣(辉煌);煌荧(闪耀);煌熠(辉耀);煌耀(辉煌)", "example": null}, {"def": "有火光的,闪耀的", "example": null}, {"def": "煌,火状。--《广韵·唐韵》", "example": null}, {"def": "煌huáng", "example": null}, {"def": "⒈明亮辉～的灯火。明星～ ～。", "example": null}, {"def": "⒉鲜明～ ～荧荧，夺人目精（精通\\"睛\\"）。", "example": null}]','chinese-xinhua','0'),
