('2101143296075108486','皇','1','huánɡ','白','9',NULL,'[{"def": "皇", "example": null}, {"def": "(象形。金文,象灯火辉煌形。上面的三点,象灯光参差上出之形;中间的部分象灯缸;下面的土”是灯柱。皇”即煌”的古字。本义灯火辉煌)", "example": null}, {"def": "同本义", "example": null}, {"def": "服其命服,朱芾斯皇。--《诗·小雅·采芑》", "example": null}, {"def": "騰皇者,煌煌也。--《书·帝命》", "example": null}, {"def": "大", "example": null}, {"def": "皇,大也。从自。自始也。始王者,三皇大君也。--《说文》", "example": null}, {"def": "建用皇极。--《书·洪范》", "example": null}, {"def": "上帝是皇。--《诗·周颂·执竞》", "example": null}, {"def": "又如皇祜(大福);皇业(大业;帝王的事业);皇道(大道);皇竹(大竹名)", "example": null}, {"def": "美好", "example": null}, {"def": "皇,美也。--《广雅·释诂一》", "example": null}, {"def": "继序其皇之。--《诗·周颂·烈文》。", "example": null}, {"def": "皇huáng", "example": null}, {"def": "⒈传说中远古的帝王三～五帝。", "example": null}, {"def": "⒉君主～帝。", "example": null}, {"def": "⒊大，盛大富丽堂～。～ ～巨著。", "example": null}, {"def": "⒋〈古〉通\\"遑\\"、\\"惶\\"。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "皇wǎng 1.向往。", "example": null}]','chinese-xinhua','0'),
('2101143296075108487','偟','1','huánɡ','','9',NULL,'[{"def": "偟huáng 1.暇;空闲。 2.通\\"遑\\"。急迫。 3.通\\"惶\\"。恐惧;不安。参见\\"偟偟\\"﹑\\"偟遽\\"。 4.见\\"仿偟\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296075108488','凰','1','huánɡ','几','11',NULL,'[{"def": "凰", "example": null}, {"def": "中国古代传说中的鸟名,雄的叫凤”,雌的叫凰”", "example": null}, {"def": "凰（〈古〉写作\\"皇\\"）huáng", "example": null}]','chinese-xinhua','0'),
('2101143296075108489','隍','1','huánɡ','阝','11',NULL,'[{"def": "隍", "example": null}, {"def": "(形声。从阜,表示与地形地势的高低上下有关,皇声。本义没有水的护城壕) 同本义", "example": null}, {"def": "隍,城池也,有水曰池,无水曰隍。--《说文》", "example": null}, {"def": "城复干隍。--《易·泰》", "example": null}, {"def": "又如隍陴(城壕与女墙);隍阱(城壕、陷坑);隍堑(城壕)", "example": null}, {"def": "隍huáng 没有水的护城壕。", "example": null}]','chinese-xinhua','0'),
('2101143296079302656','黄','1','huánɡ','黄','11',NULL,'[{"def": "黄〈形〉", "example": null}, {"def": "(象形。金文象蝗虫形。当是蝗”的本字。本义蝗虫)", "example": null}, {"def": "黄色", "example": null}, {"def": "黄,地之色也。--《说文》", "example": null}, {"def": "黄为土色,位在中央。--《论衡·騰符》", "example": null}, {"def": "黄中之色也。--《左传·昭公十二年》", "example": null}, {"def": "黄者中也。--《礼记·郊特牲》", "example": null}, {"def": "天玄而地黄,解得黄矢。--《易·坤》", "example": null}, {"def": "绿衣黄里。--《诗·邶风·绿衣》", "example": null}, {"def": "绿衣黄裳。", "example": null}, {"def": "千里黄云白日曛。--唐·高适《别董大》", "example": null}, {"def": "地履其黄。--清·梁启超《饮冰室合集·文集》", "example": null}, {"def": "得张黄盖。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "又如黄烘烘(形容金黄色);黄干干(形容很黄);黄骝(黄红色的骏马);黄盖(帝王车上所用的", "example": null}, {"def": "黄huáng", "example": null}, {"def": "⒈像油菜花或向日葵花的颜色金～。～金。菜花～。", "example": null}, {"def": "①黄的颜色。", "example": null}, {"def": "②腐朽堕落的收缴及焚烧～色书刊。", "example": null}, {"def": "⒉事情失败或计划不能实现此事～不了。", "example": null}, {"def": "⒊指黄河引～工程。", "example": null}, {"def": "⒋", "example": null}, {"def": "①菊花。", "example": null}, {"def": "②黄花菜，又名\\"金针菜\\"。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "①地下的泉水。", "example": null}, {"def": "②人死后埋葬的地方。迷信者所谓的\\"阴间\\"。", "example": null}, {"def": "⒎黄山，在安徽省～山天下绝。", "example": null}, {"def": "⒏黄帝（传说中的古代帝王）的简称。", "example": null}]','chinese-xinhua','0'),
('2101143296079302657','喤','1','huánɡ','','11',NULL,'[{"def": "喤huáng像声词。", "example": null}, {"def": "①小儿啼哭声。", "example": null}, {"def": "②形容洪亮而和谐的声音。", "example": null}]','chinese-xinhua','0'),
