('2101143296079302663','晃','1','huànɡ','日','10',NULL,'[{"def": "晃〈形〉", "example": null}, {"def": "(会意。从日,光亦声。本义明亮)", "example": null}, {"def": "同本义", "example": null}, {"def": "晃,明也。--《说文》", "example": null}, {"def": "晃,暉也。--《广雅·释言》", "example": null}, {"def": "天晃朗以弥高兮。--潘岳《秋兴赋》", "example": null}, {"def": "或晃朗而拓落。--左思《魏都赋》", "example": null}, {"def": "又如晃烂(明亮有光彩);晃然(明亮的样子);晃朗(晃晃,明亮的样子);晃昱(明亮;辉煌)", "example": null}, {"def": "引申为美俊", "example": null}, {"def": "却怎睃趁着你头上放毫光,打扮的特来晃。--元·王实甫《西厢记》", "example": null}, {"def": "晃 〈动〉", "example": null}, {"def": "照耀", "example": null}, {"def": "一闪而过。闪电般地出现或来回经过", "example": null}, {"def": "闪耀,使失去清晰视觉,使人目眩", "example": null}, {"def": "晃huàng摇动，摆动～动。～荡。摇～。柳枝～来～去。", "example": null}, {"def": "晃huǎng", "example": null}, {"def": "⒈照耀～眼（光芒闪耀，强烈刺激眼睛）。", "example": null}, {"def": "⒉快速地闪过电光一～。一～就不见了。", "example": null}, {"def": "⒊亮明～ ～的钢刀。", "example": null}]','chinese-xinhua','0'),
('2101143296079302664','滉','1','huànɡ','氵','13',NULL,'[{"def": "滉", "example": null}, {"def": "水深广的样子。也泛指深广", "example": null}, {"def": "滉,水深广貌。--《集韵》", "example": null}, {"def": "又如滉漾(形容广阔无涯)", "example": null}, {"def": "滉", "example": null}, {"def": "波动。摇动", "example": null}, {"def": "滉huàng 1.水深广貌。参见\\"滉瀇\\"﹑\\"滉瀥\\"。 2.波动，摇荡。", "example": null}]','chinese-xinhua','0'),
