('2101143296079302672','谎','1','huǎnɡ','讠','11',NULL,'[{"def": "谎", "example": null}, {"def": "(形声。从言,荒声。本义谎言,假话)", "example": null}, {"def": "同本义", "example": null}, {"def": "梦中讲的话", "example": null}, {"def": "谎,梦言也。--《说文》", "example": null}, {"def": "不公平或欺骗的价格", "example": null}, {"def": "谎", "example": null}, {"def": "哄骗,用假话或手段骗人", "example": null}, {"def": "谎", "example": null}, {"def": "虚假", "example": null}, {"def": "谎huǎng", "example": null}, {"def": "⒈骗人，假话～骗。～话。～报。莫撒～。〈引〉商贩要的虚价要～。", "example": null}, {"def": "⒉说谎话～称。～说。", "example": null}]','chinese-xinhua','0'),
('2101143296079302673','幌','1','huǎnɡ','巾','13',NULL,'[{"def": "幌", "example": null}, {"def": "窗帘、帷幔", "example": null}, {"def": "幌,帷也。--《集韵》", "example": null}, {"def": "何时倚虚幌,双照泪痕干。--唐·杜甫《月夜》", "example": null}, {"def": "酒店的招子", "example": null}, {"def": "幌", "example": null}, {"def": "挥动;摇晃", "example": null}, {"def": "随意走动", "example": null}, {"def": "须是再多幌个时辰,才好去回话。--《西游记》", "example": null}, {"def": "幌huǎng帐幔，帘帷。", "example": null}]','chinese-xinhua','0'),
