('2101143296079302686','回','1','huí','囗','6',NULL,'[{"def": "回", "example": null}, {"def": "(囘为回的古字; 廻为迴的俗字。囬、迴同回。象形。甲骨文象渊水回旋之形。本义回旋;旋转)", "example": null}, {"def": "同本义", "example": null}, {"def": "回,转也。--《说文》", "example": null}, {"def": "昭回于天。--《诗·大雅·云汉》", "example": null}, {"def": "图回天下于掌上而辨白黑。--《荀子·儒效》", "example": null}, {"def": "诡文回波。--《淮南子·本经》", "example": null}, {"def": "畔回穴其若兹兮。--《汉书·叙传》", "example": null}, {"def": "虎鼓瑟兮鸾回车。--唐·李白《梦游天姥吟留别》", "example": null}, {"def": "山回路转不见君。--唐·岑参《白雪歌送武判官归京》", "example": null}, {"def": "廊腰缦回。--唐·杜枚《阿房宫赋》", "example": null}, {"def": "峰回路转。--宋·欧阳修《醉翁亭记》", "example": null}, {"def": "又如回湍(回旋的急流);回倒(回旋倾倒);回纡(迂", "example": null}, {"def": "回（囬）huí", "example": null}, {"def": "⒈返，还，归～家乡。～祖国。～来吧。", "example": null}, {"def": "⒉答复，报答～音。～电。～报。", "example": null}, {"def": "⒊掉转，看过去，忆往昔～首。～顾。～忆。～心转意。", "example": null}, {"def": "⒋曲折，环绕，旋转～形针。峰～路转。巡～医疗。", "example": null}, {"def": "⒌量词两～事。他去了一～北京。", "example": null}, {"def": "⒍长篇小说的章节章～小说。第八～。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "①头朝后转～头看。", "example": null}, {"def": "②等一会儿～头再说。", "example": null}, {"def": "③回归，返回切莫一去不～头。", "example": null}, {"def": "④醒悟，改邪归正～头是岸。", "example": null}, {"def": "⒑", "example": null}, {"def": "⒒", "example": null}]','chinese-xinhua','0'),
