('2101143296079302689','洄','1','huí','氵','9',NULL,'[{"def": "洄", "example": null}, {"def": "(会意。从水回,回亦声。本义逆流而上)", "example": null}, {"def": "同本义", "example": null}, {"def": "洄,溯洄也。--《说文》", "example": null}, {"def": "逆流而上曰泝洄。--《尔雅·释水》", "example": null}, {"def": "溯洄从之,道阻且长。--《诗·秦风·蒹葭》", "example": null}, {"def": "浔阳五溪水,沿洄直入巫山里。--李白《送别》", "example": null}, {"def": "又如洄沿(洄,逆流而上;沿,顺流而下);洄游(同回游)", "example": null}, {"def": "追溯往昔", "example": null}, {"def": "游今洄古,可以鉴矣。--《契丹国志·契丹国初兴本末》", "example": null}, {"def": "学生虽溯洄思切,自念风尘俗吏,未由再睹仙颜,今何幸于此处相遇!--《红楼梦》", "example": null}, {"def": "水回旋而流", "example": null}, {"def": "洄huí", "example": null}, {"def": "⒈水流回旋。", "example": null}, {"def": "⒉逆流而上。", "example": null}]','chinese-xinhua','0'),
('2101143296079302690','茴','1','huí','艹','9',NULL,'[{"def": "茴", "example": null}, {"def": "茴香", "example": null}, {"def": "茴,茴香。--《玉篇》", "example": null}, {"def": "蘹香,北人呼为茴香,声相近也。--《本草纲目》引苏颂《图经本草》", "example": null}, {"def": "该种植物种子,常用作香料", "example": null}, {"def": "茴香", "example": null}, {"def": "茴香豆", "example": null}, {"def": "茴香子", "example": null}, {"def": "茴huí", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "香油，供医药或工业用。", "example": null}]','chinese-xinhua','0'),
