('2101143296079302700','汇','1','huì','氵','5',NULL,'[{"def": "汇", "example": null}, {"def": "(形声。从匚,筐子,淮声。本义盛器)", "example": null}, {"def": "同本义", "example": null}, {"def": "汇,器也。--《说文》。段玉裁注谓有器名汇也。”", "example": null}, {"def": "用外币或本国货币兑换的票据", "example": null}, {"def": "收集、分类和分送各种信息或其它需要广泛分送的情况或项目", "example": null}, {"def": "能汇", "example": null}, {"def": "中子汇", "example": null}, {"def": "汇", "example": null}, {"def": "河流会合", "example": null}, {"def": "迂回,围绕", "example": null}, {"def": "东汇泽为彭蠡。--《书·禹贡》。传回也。”", "example": null}, {"def": "又如汇行(绕道行走)", "example": null}, {"def": "以即期汇票、", "example": null}, {"def": "汇（滙、卹、", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌彙）huì", "example": null}, {"def": "⒈水流会合～成江河。", "example": null}, {"def": "⒉从甲地寄款到乙地～款。～兑。电～。", "example": null}, {"def": "⒊外汇多出口，多创～。", "example": null}, {"def": "⒋综合，聚合。会聚在一起～集。～编。词～。总～。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296079302701','会','1','huì','人','6',NULL,'[{"def": "会", "example": null}, {"def": "(会意。古文从合,从彡。按彡亦众多意。本义会合)", "example": null}, {"def": "同本义", "example": null}, {"def": "会,合也。--《说文》", "example": null}, {"def": "会,聚也。--《广雅·释诂三》", "example": null}, {"def": "会同有绛。--《诗·小雅·车攻》", "example": null}, {"def": "会言近止。--《诗·唐风·杕杜》", "example": null}, {"def": "会朝清明。--《诗·大雅·大明》", "example": null}, {"def": "会诸其币。--《仪礼·聘礼》", "example": null}, {"def": "以会天地之藏。--《礼记·月令·季秋》", "example": null}, {"def": "然后天下会于一。--柳宗元《封建论》", "example": null}, {"def": "迁客骚人,多会于此。--范仲淹《岳阳楼记》", "example": null}, {"def": "又如会茶(一起喝茶);会酒(一起吃酒);会猎(原指会合打猎,又比喻会同作战);会衔(联名签署公文);会次(朝会停留的时刻)", "example": null}, {"def": "会（會）huì", "example": null}, {"def": "⒈聚合，联合～合。聚～。～师。～盟。宴～。", "example": null}, {"def": "⒉见面，对话～见。～面。～客。～话。", "example": null}, {"def": "⒊理解，懂得～意。能领～。", "example": null}, {"def": "⒋能，可能，善于共产主义一定～实现。他～开飞机。不～不懂吧！她能说～道。", "example": null}, {"def": "⒌时机机～。逢时遇～。适逢其～。", "example": null}, {"def": "⒍短促的时间这～儿。一～儿就来。请等～儿吧。", "example": null}, {"def": "⒎付钱～账。茶钱我～过了。", "example": null}, {"def": "⒏多数人的集合，或为共同目的所组成的团体纪念～。报告～。商～。学生～。董事～。人民代表大～。", "example": null}, {"def": "⒐城市（通常指行政中心）省～。都～。", "example": null}, {"def": "⒑恰巧，正好～天大雨，道不通。", "example": null}, {"def": "⒒见kuài。", "example": null}, {"def": "会（會）kuài", "example": null}, {"def": "⒈总计。", "example": null}, {"def": "①管理与计算财务的工作。", "example": null}, {"def": "②担任会计工作的人。。", "example": null}, {"def": "会kuò 1.见\\"会撮\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296079302702','讳','1','huì','讠','6',NULL,'[{"def": "讳", "example": null}, {"def": "(形声。从言,韦声。本义避忌。有顾忌而躲开某些事或不说某些话)", "example": null}, {"def": "同本义", "example": null}, {"def": "讳,説也。--《说文》", "example": null}, {"def": "讳,避也。--《广雅·释诂三》", "example": null}, {"def": "卒哭乃讳。--《礼记·曲礼》", "example": null}, {"def": "舍故而讳新。--《礼记·檀弓》", "example": null}, {"def": "昭王之忌讳。--《周礼·小史》", "example": null}, {"def": "讳名不讳姓。--《孟子·尽心下》", "example": null}, {"def": "《春秋》为尊者讳,为亲者讳,为贤者讳。--《公羊传·闵公元年》", "example": null}, {"def": "又如直言不讳;讳名(对尊长避免说写其名,表示尊敬的心意);讳恶(先王的名讳与国家的凶恶);讳亡(忌言亡国)", "example": null}, {"def": "隐;隐蔽", "example": null}, {"def": "恐犯忌而干讳。--《楚辞·谬谏》。注所隐", "example": null}, {"def": "讳（謒）huì", "example": null}, {"def": "⒈隐瞒，避忌，有顾忌不敢说或不愿说～莫如深。～疾忌医。无庸～言。不必忌～。", "example": null}, {"def": "⒉封建时代称死去了的皇帝或长者的名姓刘～邦。姓曹～操。", "example": null}]','chinese-xinhua','0'),
('2101143296079302703','烩','1','huì','火','10',NULL,'[{"def": "烩", "example": null}, {"def": "烹饪方法。菜炒熟后加芡粉拌和", "example": null}, {"def": "把饭和各种菜混合在一起烹煮", "example": null}, {"def": "比喻把不相关的人或事拉扯在一起", "example": null}, {"def": "烩（爖）huì", "example": null}, {"def": "⒈多种食物混合在一起烧煮～黰。杂～汤。", "example": null}, {"def": "⒉食物加浓计等烧～千张。羊肉～馍。", "example": null}]','chinese-xinhua','0'),
('2101143296079302704','贿','1','huì','贝','10',NULL,'[{"def": "贿", "example": null}, {"def": "(形声。从贝,有声。本义财物)", "example": null}, {"def": "同本义", "example": null}, {"def": "贿,财也。--《尔雅》", "example": null}, {"def": "窃贿为盗。--《左传·文公十八年》", "example": null}, {"def": "以尔车来,以我贿迁。--《诗·卫风·氓》", "example": null}, {"def": "商贾阜通货贿。--《周礼·太宰》。注金玉曰货,布帛曰贿。”", "example": null}, {"def": "贿用束纺。--《仪礼·聘礼》。注贿予人财之言也。”", "example": null}, {"def": "先诸侯之贿,聚于公室。--《左传·襄公二十四年》", "example": null}, {"def": "假货居贿。--《国语·晋语》", "example": null}, {"def": "又如贿交(以财物相交);贿货(财物);贿赂(财货)", "example": null}, {"def": "贿赂的财物", "example": null}, {"def": "贿", "example": null}, {"def": "赠送财物", "example": null}, {"def": "孟献子聘于周,王以为有礼", "example": null}, {"def": "贿huì", "example": null}, {"def": "⒈〈古〉财物货～。", "example": null}, {"def": "⒉〈古〉赠送财物厚～之（送很多的财物）。", "example": null}, {"def": "⒊用财物买通别人或指买通别人的财物被迫行～。索～受～，罪行累累。勤政廉洁，杜绝～赂。", "example": null}]','chinese-xinhua','0'),
('2101143296079302705','彗','1','huì','彐','11',NULL,'[{"def": "彗", "example": null}, {"def": "(会意。甲骨文象扫竹之形,本是象形字。小篆增加又”(手),构成了会意字。本义扫帚)", "example": null}, {"def": "同本义", "example": null}, {"def": "彗,埽竹也。--《说文》", "example": null}, {"def": "国中以策彗卹勿驱。--《礼记·曲礼》", "example": null}, {"def": "拥彗先驱。--《史记·孟荀传》", "example": null}, {"def": "忽若彗泛画涂。--《汉书·王褒传》", "example": null}, {"def": "太公拥彗。--《汉书·高帝纪》", "example": null}, {"def": "又如彗汜画涂(以帚扫秽,以刀划泥。比喻极其容易)", "example": null}, {"def": "彗星的简称", "example": null}, {"def": "彗所以除旧布新也。--《左传·昭公十七年》", "example": null}, {"def": "彗星者,天之旗也。--《河图帝通纪》", "example": null}, {"def": "又如彗光(彗星的光束);彗孛(彗星和孛星);彗孛干犯(彗星侵犯);彗勃(即彗孛。彗星和孛星)", "example": null}, {"def": "彗 <", "example": null}, {"def": "彗（篲）huì", "example": null}, {"def": "⒈扫帚。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296079302706','晦','1','huì','日','11',NULL,'[{"def": "晦", "example": null}, {"def": "(形声。从日,每声。本义阴历每月的最后一天)", "example": null}, {"def": "同本义", "example": null}, {"def": "晦,月尽也。--《说文》", "example": null}, {"def": "三十日日月合宿,谓之晦。--《论衡·四讳》", "example": null}, {"def": "陈不违晦。--《左传·成公十七年》", "example": null}, {"def": "朝菌不知晦朔。--《庄子·逍遥游》", "example": null}, {"def": "不知晦朔。--", "example": null}, {"def": "戊申晦。--清·姚鼐《登泰山记》", "example": null}, {"def": "又如晦望(农历每月末一日与十五日);晦景(晦日,晦节);晦日(农历每月最后的一天)", "example": null}, {"def": "夜;晚", "example": null}, {"def": "晦淫惑疾。--《左传·昭公元年》。注夜也。”", "example": null}, {"def": "又如晦明(从黑夜到天明。即昼夜);晦晓(夜晚与天明);晦魄(", "example": null}, {"def": "晦huì", "example": null}, {"def": "⒈昏暗，天黑，晚上～冥。幽～。风雨如～。自明及～，所行几里（及到）？", "example": null}, {"def": "⒉隐藏，不显著～迹。隐～。韬～。", "example": null}, {"def": "⒊阴历每月的末尾一天。", "example": null}, {"def": "⒋", "example": null}, {"def": "①不顺利，倒霉太～气。", "example": null}, {"def": "②气色难看满脸～气。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296079302707','秽','1','huì','禾','11',NULL,'[{"def": "秽", "example": null}, {"def": "(形声。从禾,岁声。本义荒废;长满野草)", "example": null}, {"def": "同本义", "example": null}, {"def": "秽,芜也。从草,岁声。字亦作秽。--《说文》", "example": null}, {"def": "涂薲则塞。--《荀子·王霸》", "example": null}, {"def": "国之薲孽也。--《荀子·大略》", "example": null}, {"def": "粤地涂泥多草薲。--《考工记·总目》注", "example": null}, {"def": "并稻潜秽。--《文选·班固·西都》", "example": null}, {"def": "民贫,则田瘠以秽。--《荀子·富国》", "example": null}, {"def": "又如秽草(杂草,恶草);秽荒(荒芜;杂草丛生);秽莽(杂草;恶草)", "example": null}, {"def": "弄脏,弄污", "example": null}, {"def": "面一旦不修饰,则尘垢秽之;心一朝不思善,则邪恶入之。--汉·蔡邕《女诫》", "example": null}, {"def": "秽", "example": null}, {"def": "杂乱", "example": null}, {"def": "即更取器用,铲刈秽草。--柳宗元", "example": null}, {"def": "秽（穢）huì", "example": null}, {"def": "⒈荒芜田地荒～。", "example": null}, {"def": "⒉污浊，肮脏污～。〈喻〉丑陋，丑恶形～。淫～。邪～。", "example": null}]','chinese-xinhua','0'),
('2101143296079302708','喙','1','huì','口','12',NULL,'[{"def": "喙", "example": null}, {"def": "(形声。从口,彖声。本义鸟兽的嘴)", "example": null}, {"def": "鸟兽及某些其它动物(如乌龟和章鱼)的嘴", "example": null}, {"def": "人的嘴", "example": null}, {"def": "器物的尖端", "example": null}, {"def": "庄王曰子无阻九鼎!楚国折钩之喙,足以为九鼎。”--《史记》", "example": null}, {"def": "喙", "example": null}, {"def": "疲困;喘气,喘息", "example": null}, {"def": "维其喙矣。--《诗·大雅·緜》", "example": null}, {"def": "又如喙息(犹喘息)", "example": null}, {"def": "喙突", "example": null}, {"def": "大多数哺乳动物退化的喙骨,它与肩胛骨融合并形成一个突起。在人类,喙突从肩胛骨向", "example": null}, {"def": "喙huì", "example": null}, {"def": "⒈鸟兽的嘴鸟～。虎～。", "example": null}, {"def": "⒉人的嘴无庸置～（不要插嘴）。", "example": null}]','chinese-xinhua','0'),
('2101143296079302709','惠','1','huì','心','12',NULL,'[{"def": "惠", "example": null}, {"def": "(会意。从心,从叀。本义仁爱)", "example": null}, {"def": "同本义", "example": null}, {"def": "惠,仁也。--《说文》", "example": null}, {"def": "爱民好与曰惠。柔质慈民曰惠。--《周书·谥法》", "example": null}, {"def": "分人以财谓之惠。--《孟子》", "example": null}, {"def": "心省恤人谓之惠。--《贾子道术》", "example": null}, {"def": "孙讨虏聪明仁惠。--《资治通鉴》", "example": null}, {"def": "夫慈者不忍,而惠者好与也。--《韩非子·内储说上》", "example": null}, {"def": "其养民也惠。--《论语·公冶长》", "example": null}, {"def": "彭有守多惠政。--明·高启《书博鸡者事》", "example": null}, {"def": "又如惠声(仁爱而有德泽的美名);惠育(用仁心爱德加以养育);惠化(仁爱的教化);惠心(仁慈的心)", "example": null}, {"def": "柔顺;顺从", "example": null}, {"def": "义征不惠。--《史记·司马相如传》", "example": null}, {"def": "荆", "example": null}, {"def": "惠、僡、憓huì", "example": null}, {"def": "⒈好处，给人好处受～。恩～。互～。以～天下。", "example": null}, {"def": "⒉敬词～书。～文。～赠。～临。", "example": null}, {"def": "⒊温和，柔顺温～。～风和畅。〈古〉\\"惠\\"通\\"慧\\"。聪明。", "example": null}]','chinese-xinhua','0'),
('2101143296079302710','缋','1','huì','纟','12',NULL,'[{"def": "缋", "example": null}, {"def": "布帛的头尾", "example": null}, {"def": "缋,织余也。--《说文》。段玉裁注此亦兼布帛言之也…缋之言遗也,故训为织余。今之呼为机头。”", "example": null}, {"def": "以五色缋为绳。--北魏·杨衒之《洛阳伽蓝记》", "example": null}, {"def": "同绘”。绘画", "example": null}, {"def": "缋huì同\'绘\'。", "example": null}]','chinese-xinhua','0'),
