('2101143296091885582','浍','1','huì','氵','9',NULL,'[{"def": "浍", "example": null}, {"def": "河名,浍河", "example": null}, {"def": "浍  kuai", "example": null}, {"def": "(形声。从水,会声。本义水名。也称浍河。源出河南省,流入安徽省) 田的排水沟", "example": null}, {"def": "以浍写水。--《周礼·稻人》。注田尾去水大沟。”", "example": null}, {"def": "而深山卡谷之水,四面而出,沟渠浍川,十百相通。--宋·王安石《上杜学士言开河书》", "example": null}, {"def": "浍（澮）kuài田间大沟渠沟～。", "example": null}]','chinese-xinhua','0'),
('2101143296091885583','绘','1','huì','纟','9',NULL,'[{"def": "绘", "example": null}, {"def": "(从糸(与线丝有关),会声。本义五彩绣品) 同本义。也作会”", "example": null}, {"def": "绘,会五采绣也。--《说文》", "example": null}, {"def": "杂彩曰绘。--《小尔雅·广训》", "example": null}, {"def": "山龙华虫作绘。--《虞书》", "example": null}, {"def": "又如绘绚(彩绘绚丽)", "example": null}, {"def": "绘", "example": null}, {"def": "绘画", "example": null}, {"def": "自绘败状。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "绘影写光。--蔡元培《图画》", "example": null}, {"def": "绘像祀之。--《明史》", "example": null}, {"def": "中绘殿阁。--《聊斋志异·促织》", "example": null}, {"def": "又如绘像(画像);绘画(作画);绘本(画册);绘卷(画卷);绘事后素(指绘画先以粉地为质然后施加五彩。比喻人有美质,然后可加文饰)", "example": null}, {"def": "用言辞形容", "example": null}, {"def": "绘（纋）、缋huì画，描画，描摹～图样。～影～形。～声～色。", "example": null}]','chinese-xinhua','0'),
('2101143296091885584','荟','1','huì','艹','9',NULL,'[{"def": "荟", "example": null}, {"def": "(形声。从苪,会声。本义草多的样子) 同本义", "example": null}, {"def": "荟,草多貌。--《说文》", "example": null}, {"def": "荟兮蔚兮。--《诗·曹风·候人》", "example": null}, {"def": "山林翳荟,必谨覆索之,此伏奸之所藏处也。--《孙子·行军》", "example": null}, {"def": "潜荟葱茏。--郭璞《江赋》", "example": null}, {"def": "又如荟蔚(草木茂盛的样子);荟郁(草木繁盛的样子);荟翳(指枝叶繁茂隐翳的草木)", "example": null}, {"def": "荟", "example": null}, {"def": "聚集", "example": null}, {"def": "遮掩;隐翳", "example": null}, {"def": "荟（薱）huì", "example": null}, {"def": "⒈草木茂盛。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296091885585','诲','1','huì','讠','9',NULL,'[{"def": "诲", "example": null}, {"def": "(形声。从言,每声。本义教导)", "example": null}, {"def": "同本义", "example": null}, {"def": "诲,说教也。--《说文》", "example": null}, {"def": "慢藏诲盗,野容诲淫。--《易·系辞》", "example": null}, {"def": "胥教诲。--《书·无逸》", "example": null}, {"def": "诲尔序爵。--《诗·大雅·桑柔》", "example": null}, {"def": "夫子诲之髽。--《礼记·檀弓》", "example": null}, {"def": "使师曹诲之琴。--《左传·襄公十四年》", "example": null}, {"def": "诲人不倦。--《论语·述而》", "example": null}, {"def": "又如诲示(教导,晓示);诲诱(教导循诱);诲谕(教诲晓喻);诲翰(诲函。对对方书信的敬称)", "example": null}, {"def": "明示,诱使", "example": null}, {"def": "诲", "example": null}, {"def": "教导的话", "example": null}, {"def": "诲huì教导，指教教～。学而不厌，～人不倦。", "example": null}]','chinese-xinhua','0'),
('2101143296091885586','恚','1','huì','心','10',NULL,'[{"def": "恚", "example": null}, {"def": "(形声。从心,圭声。本义怨恨,愤怒) 同本义", "example": null}, {"def": "恚,恨也。--《说文》", "example": null}, {"def": "恚,怒也。--《广雅·释诂二》", "example": null}, {"def": "故去忿恚之心;而成终身之名。--《战国策·齐策三》", "example": null}, {"def": "恚目。--《管子·地员》", "example": null}, {"def": "恚而语女曰。--明·崔铣《记王忠肃公翱三事》", "example": null}, {"def": "懋卿恚甚。--《明史》", "example": null}, {"def": "承畴大恚。--清·全祖望《梅花岭记》", "example": null}, {"def": "又如恚碍(愤怒抵触);恚忌(愤怒嫉忌);恚忿(愤怒);恚责(愤怒斥责)", "example": null}, {"def": "恚", "example": null}, {"def": "愤怒地,生气地;发怒地", "example": null}, {"def": "舍人恚曰朔擅诋欺天子从官”。--《汉书》", "example": null}, {"def": "磙", "example": null}, {"def": "恚怒", "example": null}, {"def": "恚huì愤怒，恨～恨。", "example": null}]','chinese-xinhua','0'),
