('2101143296091885605','麾','1','huī','麻','15',NULL,'[{"def": "麾", "example": null}, {"def": "(形声。从毛,麻声。本义古代供指挥用的旌旗)", "example": null}, {"def": "同本义", "example": null}, {"def": "喻将帅", "example": null}, {"def": "麾", "example": null}, {"def": "指挥,下命令行动", "example": null}, {"def": "麾,指麾。--《玉篇》", "example": null}, {"def": "又如麾军(指挥军队);麾众(指挥大众)", "example": null}, {"def": "同挥”", "example": null}, {"def": "王左杖黄钺,右秉白旄以麾。--《书·牧誓》", "example": null}, {"def": "瑕叔盈又以蝥弧(蝥弧,郑伯旗名)登,周麾而呼曰君登矣!”--《左传·隐公十一年》", "example": null}, {"def": "魏其侯去,麾灌夫出。--《史记·魏其武安侯列传》", "example": null}, {"def": "庄王亲", "example": null}, {"def": "麾huī〈古〉用于指挥作战的旗子。〈引〉指挥，挥动～军前进。", "example": null}]','chinese-xinhua','0'),
('2101143296091885606','徽','1','huī','彳','17',NULL,'[{"def": "徽", "example": null}, {"def": "(形声。从糸,表示与线丝有关,微省声。本义三纠绳)", "example": null}, {"def": "同本义", "example": null}, {"def": "徽,三股绳也。--《说文》", "example": null}, {"def": "系用徽纆。--《易·坎》。刘注三股为徽。”", "example": null}, {"def": "绳索", "example": null}, {"def": "免于徽索。--《汉书·扬雄传》。注绳也。”", "example": null}, {"def": "又如徽索(徽绳。捆绑俘虏、罪人的绳索);徽纆(绳索;捆绑);徽缠(绳索。亦比喻束缚,牵累);徽绳(徽索。指捆绑罪人的绳索)", "example": null}, {"def": "琴徽,系琴弦的绳", "example": null}, {"def": "今夫弦者,高张急徽,追趋逐耆,则坐者不期而附矣。--《汉书·扬雄传》", "example": null}, {"def": "后亦指七弦琴琴面十三个指示音节的标识", "example": null}, {"def": "徽huī", "example": null}, {"def": "⒈标志，符号～章。国～。党～。校～。", "example": null}, {"def": "⒉美好的～容。～音。", "example": null}]','chinese-xinhua','0'),
('2101143296091885607','隳','1','huī','阝','17',NULL,'[{"def": "隳〈动〉", "example": null}, {"def": "毁坏城墙或山头;毁坏", "example": null}, {"def": "隳名城。--汉·贾谊《过秦论》", "example": null}, {"def": "一夫作难而七庙隳。", "example": null}, {"def": "又如隳堕(毁坏;动摇);隳突(骚扰);隳圮(倾坍;倒塌);隳名(隐姓埋名)", "example": null}, {"def": "怠惰。通惰”", "example": null}, {"def": "隳突", "example": null}, {"def": "叫嚣乎东西,隳突乎南北。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "隳huī毁坏法令～。", "example": null}]','chinese-xinhua','0'),
