('2101143296091885611','诙','1','huī','讠','8',NULL,'[{"def": "诙", "example": null}, {"def": "诙谐;戏谑", "example": null}, {"def": "诙,调也。--《广雅》", "example": null}, {"def": "朔虽诙笑,然时观察颜色。--《汉书·东方朔传》", "example": null}, {"def": "诙啁大笑。--《三国志·马忠传》", "example": null}, {"def": "又如诙俳(诙谐戏谑);诙笑(嘲笑,戏谑);诙啁(诙谐嘲笑)", "example": null}, {"def": "诙huī嘲笑，有趣，开玩笑～谈。～趣。～谐。", "example": null}]','chinese-xinhua','0'),
('2101143296091885612','咴','1','huī','口','9',NULL,'[{"def": "咴咴", "example": null}, {"def": "咴儿咴儿", "example": null}, {"def": "咴huī", "example": null}, {"def": "①〈拟声〉骡马的叫声＞战马～～。", "example": null}, {"def": "②〈动〉喝斥＞他～了一声。", "example": null}]','chinese-xinhua','0'),
('2101143296091885613','恢','1','huī','忄','9',NULL,'[{"def": "恢", "example": null}, {"def": "(形声。从心,灰声。本义志气大;大;广大)", "example": null}, {"def": "同本义", "example": null}, {"def": "恢,大也。--《说文》", "example": null}, {"def": "不恢于夏家。--《左传·襄公四年》", "example": null}, {"def": "恢郭也。--《公羊传·文公十五年》", "example": null}, {"def": "配稷契兮恢唐功。--《楚辞·守志》", "example": null}, {"def": "恢恑谲怪。--《庄子·齐物论》", "example": null}, {"def": "酒量犹恢。--李曾伯《沁园春》", "example": null}, {"def": "以无厚入有间,恢恢乎其于游刃必有余地矣。--《庄子·养生主》", "example": null}, {"def": "又如恢伟(壮伟,魁伟);恢奇(雄伟杰出的样子);恢台(广大的样子);恢卓(宽大,高明);恢恢(宽大广阔的样子);恢郭(宽大的外城)", "example": null}, {"def": "同诙”。诙谐;怪诞", "example": null}, {"def": "恢huī", "example": null}, {"def": "⒈广大，宽广～弘。天网～ ～，疏而不失。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
