('2101143296091885637','混','1','hùn','氵','11',NULL,'[{"def": "混", "example": null}, {"def": "(形声。从水,昆声。本义水势盛大)", "example": null}, {"def": "同本义", "example": null}, {"def": "混,丰流也。--《说文》", "example": null}, {"def": "汩乎混流。--司马相如《子虚赋》", "example": null}, {"def": "或混沦乎泥沙。--郭璞《江赋》", "example": null}, {"def": "又如混沦(水旋转的样子);混澒(水流漫涌回旋的样子);混瀥(水大无边的样子)", "example": null}, {"def": "浑浊,水多泥多杂质而不清澈", "example": null}, {"def": "时混混兮浇饡。--《楚辞·王逸·九思·伤时》。注混混,浊也。”", "example": null}, {"def": "玄混之中。--《文选·班固·典引》", "example": null}, {"def": "又如混混(浑浊);混秽(使混浊污秽);混浑(浑浊不清)", "example": null}, {"def": "糊涂", "example": null}, {"def": "胡乱", "example": null}, {"def": "混hún同\\"浑", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉\\"。", "example": null}, {"def": "混hùn", "example": null}, {"def": "⒈杂，搀和～杂。～合。～而为一。", "example": null}, {"def": "⒉假充，假冒～充。蒙～。鱼目～珠。", "example": null}, {"def": "⒊敷衍了事，得过且过莫～日子。", "example": null}, {"def": "⒋胡乱～说。～闹。", "example": null}, {"def": "⒌", "example": null}, {"def": "①〈古〉传说宇宙形成以前凝的状态。", "example": null}, {"def": "②糊涂不清的样子。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "混gǔn 1.见\\"混混\\"。", "example": null}, {"def": "混kūn 1.见\\"混夷\\"。 2.通\\"昆\\"。 3.通\\"昆\\"。参见\\"混吾\\"。", "example": null}]','chinese-xinhua','0'),
