('2101143296096079898','戢','1','jí','戈','12',NULL,'[{"def": "戢", "example": null}, {"def": "收藏", "example": null}, {"def": "载戢干戈。--《诗·周颂·时迈》", "example": null}, {"def": "夫兵戢而时动。--《国语·周语》", "example": null}, {"def": "夫兵戢而时动,动则威。--《国语·周语》", "example": null}, {"def": "又如戢刃(收起刀剑等利器);戢戢(聚集);戢载(收集装载);戢藏(收藏)", "example": null}, {"def": "引申指停止战争", "example": null}, {"def": "弗戢,将自焚。--《左传·隐公四年》", "example": null}, {"def": "又如戢戈(息兵);戢兵(停用兵器,禁用武力);戢武(息兵)", "example": null}, {"def": "收敛", "example": null}, {"def": "戢,敛也。--《小尔雅》", "example": null}, {"def": "戢其左翼。--《诗·小雅·鸳鸯》", "example": null}, {"def": "不戢不难。--《诗·小雅·桑扈》", "example": null}, {"def": "翼翼归鸟,戢羽寒条。--陶渊明《归鸟》", "example": null}, {"def": "又如戢鳞(敛鳞。鱼止息不游。比喻怀志坐待", "example": null}, {"def": "戢jí收敛～羽。载～干戈（收藏兵器。载语气词）。〈引〉止息，禁止～怒。严～贪污腐败。", "example": null}]','chinese-xinhua','0'),
('2101143296096079899','棘','1','jí','木','12',NULL,'[{"def": "棘", "example": null}, {"def": "(会意。从二-朿。朿”是刺”的本字。两个朿”字并排立着,表示棘树多刺,是矮小而成丛莽的灌木。本义丛生的小枣树)", "example": null}, {"def": "酸枣树。一种落叶乔木,有刺。果实较枣小,味酸,种子、果皮、根可入药", "example": null}, {"def": "棘,小枣丛生者。--《说文》", "example": null}, {"def": "實于丛棘。--《易·坎》", "example": null}, {"def": "园有棘。--《诗·魏风·园有桃》", "example": null}, {"def": "伐棘枣以为矜。--《淮南子·兵略》", "example": null}, {"def": "香径长洲尽棘丛,奢云艳雨只悲风。--陆龟蒙《吴宫怀古》", "example": null}, {"def": "又如棘薪(指酸枣树已长成薪柴)", "example": null}, {"def": "泛指有芒刺的草木", "example": null}, {"def": "攀草牵棘。--《徐霞客游记·游黄山记》", "example": null}, {"def": "虫伏棘根。--《聊斋志异", "example": null}, {"def": "棘jí", "example": null}, {"def": "⒈酸枣树，落叶灌木，枝上多刺，初夏开黄绿色小花。果实较枣小，肉薄，味酸。种仁可供药用。", "example": null}, {"def": "⒉泛指有刺的草木荆～丛生。", "example": null}, {"def": "⒊针形的刺～皮动物。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296096079900','殛','1','jí','歹','12',NULL,'[{"def": "殛", "example": null}, {"def": "(形声。从歹,亟声。从歹”,表示与死亡有关。本义诛,杀死)", "example": null}, {"def": "同本义", "example": null}, {"def": "殛,诛也。--《说文》", "example": null}, {"def": "明神殛之。--《左传·襄公十一年》", "example": null}, {"def": "有夏多罪,天命殛之。--《书·汤誓》", "example": null}, {"def": "乃殛鲧于羽山。--《史记·夏本纪》", "example": null}, {"def": "愿丞相思舜帝殛鲧用禹之义。--《三国演义》", "example": null}, {"def": "又如雷殛", "example": null}, {"def": "惩罚", "example": null}, {"def": "爽惟天其罚殛我,我其不怨。--《书·康诰》", "example": null}, {"def": "又如殛罚(惩罚)", "example": null}, {"def": "流放,放逐。通极”", "example": null}, {"def": "我不负神兮,神何殛我越荒州?--汉·蔡琰《胡笳十八拍》", "example": null}, {"def": "殛jí诛杀，致死雷～。", "example": null}]','chinese-xinhua','0'),
