('2101143296096079919','汲','1','jí','氵','6',NULL,'[{"def": "汲", "example": null}, {"def": "(会意。从水,及声。本义从井里打水,取水)", "example": null}, {"def": "同本义", "example": null}, {"def": "汲,引水于井也。--《说文》", "example": null}, {"def": "汲,取也。--《广雅》", "example": null}, {"def": "可用汲。--《易·井》", "example": null}, {"def": "而出溉汲。--《吕氏春秋·慎行论》", "example": null}, {"def": "而谷汲者。--《韩非子·五蠹》", "example": null}, {"def": "每汲用。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "有泉可汲。--明·顾炎武《复庵记》", "example": null}, {"def": "又如汲古(钻研古书,如汲水于井);汲水(引水;取水)", "example": null}, {"def": "牵引", "example": null}, {"def": "凡任,索约,大汲其版,谓之无任。--《周礼·考工记·匠人》", "example": null}, {"def": "引导", "example": null}, {"def": "汲郑伯。--《谷梁传·襄公十年》", "example": null}, {"def": "又如汲善(引人向善)", "example": null}, {"def": "引荐;提拔", "example": null}, {"def": "汲jí", "example": null}, {"def": "⒈从井里取水，泛指打水、取水～水。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296096079920','级','1','jí','纟','6',NULL,'[{"def": "级", "example": null}, {"def": "(形声。从糸,表示与线丝有关,及声。本义丝的次第)", "example": null}, {"def": "同本义", "example": null}, {"def": "级,丝次弟也。--《说文》。段玉裁注本谓丝之次弟,故其字从系。引申为凡次弟之称。”", "example": null}, {"def": "引申为等级,特指官阶爵位的品级", "example": null}, {"def": "级,等也。--《广雅》", "example": null}, {"def": "拾级聚足。--《礼记·曲礼》。注等也。”", "example": null}, {"def": "级,阶次也。--《声类》", "example": null}, {"def": "以别贵贱等级之度。--《礼记·月令》", "example": null}, {"def": "百姓内粟千石,拜爵一级。--《史记·秦始皇本纪》", "example": null}, {"def": "又如超级(超过一般等级的);震级(地震等级);晋级(升到较高的等级);级差级 (等级之间的差距)", "example": null}, {"def": "石阶", "example": null}, {"def": "乃领宾者延之而", "example": null}, {"def": "级jí", "example": null}, {"def": "⒈等次等～。下～。高～。提～。降～。", "example": null}, {"def": "⒉特指年级（学校编制的名称）二年～。同～同学。", "example": null}, {"def": "⒊台阶石～。", "example": null}, {"def": "⒋层次此楼梯有十八～。七～浮屠（七层的塔）。", "example": null}, {"def": "⒌颗，〈古〉指斩下的人头首～。斩虏数百～。", "example": null}, {"def": "级zhuì 1.缵列。", "example": null}]','chinese-xinhua','0'),
('2101143296096079921','即','1','jí','卩','7',NULL,'[{"def": "即", "example": null}, {"def": "(会意。甲骨文作坐人形(后讹为卩)面对食器(皀)会意。本义走近去吃东西)", "example": null}, {"def": "同本义", "example": null}, {"def": "即,就食也。--《说文》", "example": null}, {"def": "席末取粮即稻。--《仪礼·公食礼》", "example": null}, {"def": "鼎有实,我仇有疾,不我能即。--《易·鼎》。高亨注《说文》‘即,就食也。’此用其本义。”", "example": null}, {"def": "基本义是接近、靠近、走向,与离”对举。", "example": null}, {"def": "将即席。--《礼记·曲礼》", "example": null}, {"def": "匪来贸丝,来即我谋。--《诗·卫风·氓》", "example": null}, {"def": "神即形也,形即神也。--范缜《神灭论》", "example": null}, {"def": "夜半,童自转,以缚即炉火烧绝之。--柳宗元《童区寄传》", "example": null}, {"def": "又如若即若离", "example": null}, {"def": "登上;走上", "example": null}, {"def": "即jí", "example": null}, {"def": "⒈便，立刻，马上立～办。用后～还，丰收～在眼前。", "example": null}, {"def": "⒉当时，当前，当地～刻就走。～日到达。～景赋诗。", "example": null}, {"def": "⒊就是武林～杭州。", "example": null}, {"def": "⒋靠近，接近若～若离。可望而不可～。", "example": null}, {"def": "⒌则，那就且壮士不死～已，死～举大名耳。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①入席就坐。", "example": null}, {"def": "②当场～席讲演。", "example": null}, {"def": "⒐", "example": null}, {"def": "①就位。", "example": null}, {"def": "②〈古〉指封建统治者开始做君主或诸侯。", "example": null}]','chinese-xinhua','0'),
('2101143296096079922','极','1','jí','木','7',NULL,'[{"def": "极", "example": null}, {"def": "(形声。从木,亟声。本义房屋的正梁)", "example": null}, {"def": "同本义", "example": null}, {"def": "榦,栋也。--《说文》。按,在屋之正中至高处。", "example": null}, {"def": "万载宫极。--《汉书·天文志》", "example": null}, {"def": "有夫妻臣妾登极。--《庄子·则阳》。司马注屋栋也。”", "example": null}, {"def": "茂初在广汉,梦坐大殿,极上有三穗禾,茂跳取之,得其中穗,辄复失之。--《后汉书·蔡茂传》", "example": null}, {"def": "最高的地位", "example": null}, {"def": "今以三寸之舌,为帝者师,封万户,位列侯,此布衣之极,于良足矣。--《史记·留侯世家》", "example": null}, {"def": "又如极峰(最高层的官员)", "example": null}, {"def": "特指君位", "example": null}, {"def": "建用皇极。--《书·洪范》", "example": null}, {"def": "又如登极(登君位)", "example": null}, {"def": "顶点,最高处;最高最", "example": null}, {"def": "极（榦）jí", "example": null}, {"def": "⒈顶端，最高点，尽头处～端。～点。登峰造～。〈引〉到极点乱～则治。暗～则光。", "example": null}, {"def": "⒉最，非常～重。～美好。穷凶～恶。", "example": null}, {"def": "⒊竭尽～力工作。～目远望。", "example": null}, {"def": "⒋指皇位登～。", "example": null}, {"def": "⒌标准建～闲邪（树立标准，防止邪恶。闲防止）。", "example": null}, {"def": "⒍电极（正～、负～、阴～、阳～）和磁极（南～、北～）的简称。", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
('2101143296096079923','亟','1','jí','二','8',NULL,'[{"def": "亟", "example": null}, {"def": "(会意。甲骨文字形,是亟”(古榦字)字的初文。中间是一个站着的人,上面一横表示极于顶”,下面一横表示极于踵。”金文繁化字形,与小篆的写法相似。本义极点,尽", "example": null}, {"def": "头) 快速;迅速(含有急迫之意)", "example": null}, {"def": "亟,急也。--《广雅》", "example": null}, {"def": "亟其乘屋。--《诗·豳风·七月》", "example": null}, {"def": "小饭而亟之。--《礼记·少仪》", "example": null}, {"def": "欲霸之亟成。--《战国策·宋策》", "example": null}, {"def": "亟言之。--《左传·昭公二十一年》", "example": null}, {"def": "君亟定变法之虑。--《商君书·更法》", "example": null}, {"def": "经始勿亟,庶民子来。--《孟子·梁惠王上》", "example": null}, {"def": "趣赵兵亟入关。--《史记·陈涉世家》", "example": null}, {"def": "亟请广州府余暨南", "example": null}, {"def": "亟qì", "example": null}, {"def": "⒈屡次～来探视。", "example": null}, {"def": "亟jí", "example": null}, {"def": "⒈赶快，急切～需办理。～待纠正。", "example": null}, {"def": "⒉见qì。", "example": null}]','chinese-xinhua','0'),
('2101143296096079924','佶','1','jí','亻','8',NULL,'[{"def": "佶", "example": null}, {"def": "正", "example": null}, {"def": "佶,正也。从人,吉声。--《说文》", "example": null}, {"def": "健壮", "example": null}, {"def": "四牡既佶。--《诗·小雅·六月》", "example": null}, {"def": "又如佶傈(慻悍雄壮的样子)", "example": null}, {"def": "佶屈,即诘屈。曲折的。引申为不顺", "example": null}, {"def": "耸动的样子", "example": null}, {"def": "战栗", "example": null}, {"def": "壮烈", "example": null}, {"def": "佶、", "example": null}, {"def": "⒉诘jí", "example": null}, {"def": "⒈壮健。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
