('2101143296096079976','稷','1','jì','禾','15',NULL,'[{"def": "稷", "example": null}, {"def": "(形声。从禾,畟声。表示与农作物有关。本义稷谷)", "example": null}, {"def": "植物名。我国古老的食用作物,即粟。一说为不粘的黍。又说为高粱", "example": null}, {"def": "稷,齮也。五谷之长。--《说文》", "example": null}, {"def": "黍稷无成。--《国语·晋语》。注粱也。”按,千谷粟三者为黍,稷稻梁之大名。梁则今小米子之大而不黏者,与稷别。", "example": null}, {"def": "黏者为黍,不黏者为稷。--《本草纲目》", "example": null}, {"def": "稷,粟也。--《尔雅·释草》注", "example": null}, {"def": "稷,今人谓之高粱。--《广雅疏证》", "example": null}, {"def": "又如稷食(稷米煮的饭。泛指粗粝的饭);稷饭(以稷谷为饭);稷馈(古代以稷为主的祭礼)", "example": null}, {"def": "引申为庄稼和粮食的总称", "example": null}, {"def": "稷jì", "example": null}, {"def": "⒈〈古〉指一种谷物，一说是黍属，一说是粟（谷子）。", "example": null}, {"def": "⒉〈古〉迷信指\\"谷神\\"（以稷为百谷之长）。", "example": null}, {"def": "稷zè 1.太阳西斜。", "example": null}]','chinese-xinhua','0'),
('2101143296096079977','鲫','1','jì','鱼','15',NULL,'[{"def": "鲫", "example": null}, {"def": "鲫鱼,亦称鲋”", "example": null}, {"def": "鲫溜", "example": null}, {"def": "鲫jì鲫鱼，体侧扁，背脊隆起，无触须，头小，背青褐色，腹银白色。生活在淡水中，供食用。变种\\"金鱼\\"供观赏。", "example": null}]','chinese-xinhua','0'),
('2101143296096079978','冀','1','jì','八','16',NULL,'[{"def": "冀", "example": null}, {"def": "(形声。从北,异声。本义冀州。古九州之一)", "example": null}, {"def": "同本义", "example": null}, {"def": "冀,北方州也。--《说文》", "example": null}, {"def": "两河间曰冀州。--《尔雅·释地》", "example": null}, {"def": "河内曰冀州。--《周礼·职方氏》。朱骏声曰地亘今盛京直隶山西、河南各府州,淮南地形,正中冀州,曰中土。”", "example": null}, {"def": "惟彼陶唐,有此冀方。--《书·五子之歌》。孔传陶唐帝尧氏,都冀州,统天下四方。”", "example": null}, {"def": "古代国名", "example": null}, {"def": "河北省的简称", "example": null}, {"def": "冀", "example": null}, {"def": "假借为觊”。希望,期望", "example": null}, {"def": "吾冀而朝夕修我。--《国语·鲁语》", "example": null}, {"def": "冀至珠庭焉。--《史记·孝武纪》", "example": null}, {"def": "冀jì", "example": null}, {"def": "⒈希望～复得兔（复再）。", "example": null}, {"def": "⒉河北省的简称。", "example": null}]','chinese-xinhua','0'),
