('2101143296096079980','穄','1','jì','','16',NULL,'[{"def": "穄jì穄子，也叫\\"糜子\\"一种黍类谷物，但不粘。", "example": null}]','chinese-xinhua','0'),
('2101143296096079981','縘','1','jì','','11',NULL,'[{"def": "縘xì", "example": null}, {"def": "⒈古同續”。", "example": null}]','chinese-xinhua','0'),
('2101143296096079982','髻','1','jì','髟','16',NULL,'[{"def": "髻", "example": null}, {"def": "(形声。从髟,表示与毛发有关,吉声。本义发髻) 同本义", "example": null}, {"def": "头上倭堕髻。--《乐府诗集·陌上桑》", "example": null}, {"def": "椎髻仰面。--明·魏学洢《核舟记》", "example": null}, {"def": "汝梳双髻(髻,梳在头顶上的发结。)--清·袁枚《祭妹文》", "example": null}, {"def": "又如髻珠(髻上的明珠;比喻主旨、善谛);髻丫(盘在头顶左右两侧的发结);髻根(发髻盘结如盘根错节);髻子(即发髻,头发拖到后面结成一个髻)", "example": null}, {"def": "髻鬟", "example": null}, {"def": "髻鬟之始掠。--明·袁宏道《满井游记》", "example": null}, {"def": "髻jì盘在头顶的发结发～。梳头扎～。", "example": null}, {"def": "髻jié 1.灶神。", "example": null}]','chinese-xinhua','0'),
('2101143296096079983','既','1','jì','旡','9',NULL,'[{"def": "既", "example": null}, {"def": "(会意。甲骨文字形,左边是食器的形状,右边象一人吃罢而掉转身体将要离开的样子。本义吃罢,吃过)", "example": null}, {"def": "同本义", "example": null}, {"def": "既,小食也。--《说文》。罗振玉曰即,象人就食;既,象人食既。许训既为小食,义与形不协矣。”", "example": null}, {"def": "君既食。--《礼记·玉藻》", "example": null}, {"def": "不拜既爵。--《义礼·乡饮酒礼》", "example": null}, {"def": "食尽。指日全食或月全食", "example": null}, {"def": "秋,七月,壬辰,朔,日有食之,既。--《春秋·桓公三年》。杜预注既,尽也。”", "example": null}, {"def": "其合相当如袭辟者,日既是也。--汉·王充《论衡》", "example": null}, {"def": "完毕;完了", "example": null}, {"def": "既而曰。--《公羊传·宣公元年》。注事毕也。”", "example": null}, {"def": "既jì", "example": null}, {"def": "⒈尽，完了，终了语未～。食～（指日蚀、月蚀的蚀尽）。", "example": null}, {"def": "⒉副词。已经～成事实。～往不咎。", "example": null}, {"def": "⒊副词。不久，后来～而缝合。", "example": null}, {"def": "⒋连词。常跟\\"且\\"、\\"又\\"、\\"也\\"等连用〈表〉两种情况并存～矮且小。～做得快，又做得好。～要数量多，也要质量高。", "example": null}, {"def": "⒌", "example": null}, {"def": "既xì 1.赠送人的谷物或饲料。", "example": null}]','chinese-xinhua','0'),
('2101143296096079984','洎','1','jì','氵','9',NULL,'[{"def": "洎", "example": null}, {"def": "(形声。从水,自声。本义往锅里添水)", "example": null}, {"def": "同本义", "example": null}, {"def": "洎,灌釜也。--《说文》", "example": null}, {"def": "洎镬水。--《周礼·士师》。注增其沃汁。”", "example": null}, {"def": "水而洎之。--《史记·封禅书》", "example": null}, {"def": "市丘之鼎以烹鸡,多洎之则淡而不可食,少洎之则焦而不熟。--《吕氏春秋·应言》", "example": null}, {"def": "浸润", "example": null}, {"def": "越之水,浊重而洎。 -- 《管子·水地》", "example": null}, {"def": "及,到达", "example": null}, {"def": "洎乎晚节,秽乱春宫。--骆宾王《为徐敬业讨武氏檄》", "example": null}, {"def": "洎", "example": null}, {"def": "等到", "example": null}, {"def": "洎牧以谗诛,邯郸为郡,惜其用武不终也。--宋·苏洵《六国论》", "example": null}, {"def": "又如自古洎今", "example": null}, {"def": "洎", "example": null}, {"def": "洎jì", "example": null}, {"def": "⒈到，至从古～今。", "example": null}, {"def": "⒉浸泡，浸润。", "example": null}, {"def": "⒊往锅里添水。", "example": null}]','chinese-xinhua','0'),
('2101143296096079985','济','1','jì','氵','9',NULL,'[{"def": "济", "example": null}, {"def": "(形声。从水,齐声。本义水名,即济水。古四渎之一)", "example": null}, {"def": "同本义。", "example": null}, {"def": "济,济水也。出常山房子赞皇山东入沞--《说文》", "example": null}, {"def": "济水源出赞皇山。--《穆天子传》", "example": null}, {"def": "阴谷皆入济。--清·姚鼐《登泰山记》", "example": null}, {"def": "发源于今河南省济源县西王屋山,原在山东境内与黄河并行入渤海◇因黄河改道,下游被黄河淹没。现在黄河下游的河道就是原来济水的河道", "example": null}, {"def": "州名", "example": null}, {"def": "北魏泰常八年(公元423年)置,治所在今山东省聊城东南", "example": null}, {"def": "五代周置,在今山东省巨野县", "example": null}, {"def": "金置,在今吉林省农安县", "example": null}, {"def": "济", "example": null}, {"def": "众多", "example": null}, {"def": "济济多士。--《左传·成公二年》", "example": null}, {"def": "济（濟）jǐ", "example": null}, {"def": "⒈济水，〈古〉水名。发源于河南省，流经山东省入渤海。今黄河下流河道即原济水河道。", "example": null}, {"def": "⒉济南市，济宁市，均在山东省。", "example": null}, {"def": "⒊", "example": null}, {"def": "济（濟）jì", "example": null}, {"def": "⒈渡，过河同船～水。同舟共～。", "example": null}, {"def": "⒉帮助，援救接～。救～。～穷扶贫。", "example": null}, {"def": "⒊有利，补益万民以～。", "example": null}, {"def": "⒋成夫～大事必以人为本。", "example": null}, {"def": "济qí 1.庄敬。 2.整治，使整齐。", "example": null}]','chinese-xinhua','0'),
