('2101143296100274181','际','1','jì','阝','7',NULL,'[{"def": "际", "example": null}, {"def": "(形声。从阜,祭声。本义两墙相合之缝)", "example": null}, {"def": "同本义", "example": null}, {"def": "际,壁会也。--《说文》。段玉裁注两墙相合之缝也。", "example": null}, {"def": "泛指合缝的地方;缝隙", "example": null}, {"def": "凿棺际而安之。--南朝 梁·江淹《铜剑赞》", "example": null}, {"def": "覆盖周密无际。--《后汉书·张衡传》", "example": null}, {"def": "边缘", "example": null}, {"def": "东南大海际。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "横无际涯。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "川原无际。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "又如岩际;水际;无边无际;边际;天际;九天之际;一望无际;分际;漫无边际", "example": null}, {"def": "时候;时机", "example": null}, {"def": "败军之际。--诸葛亮《出师表》", "example": null}, {"def": "去就之际", "example": null}, {"def": "际（雋）jì", "example": null}, {"def": "⒈交界处，边缘处海～。天～。一望无～。", "example": null}, {"def": "⒉彼此之间省～。国～。厂～竞争。", "example": null}, {"def": "⒊时候或先后交接的时候胜利之～。夏秋之～。", "example": null}, {"def": "⒋当，适逢～此美景。", "example": null}, {"def": "⒌会合，交流刚柔～也。广泛交～。", "example": null}, {"def": "⒍到，接近～天接地。", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
('2101143296100274182','剂','1','jì','刂','8',NULL,'[{"def": "剂", "example": null}, {"def": "(会意。从刀,齐声。齐”亦兼表字义。本义剪齐)", "example": null}, {"def": "同本义", "example": null}, {"def": "剂,齐也。--《说文》", "example": null}, {"def": "剂,剪齐也。--《后汉书·刘梁传》注", "example": null}, {"def": "其命剂也。--《太玄·永》。注剪绝也。”", "example": null}, {"def": "永不轨,其命剂也。--《太玄·永》", "example": null}, {"def": "剂,剪齐也。--《尔雅》。郭璞注南方人呼剪刀为剂刀。”", "example": null}, {"def": "割", "example": null}, {"def": "豫让剂面而变容,吞炭为哑。--《新书》", "example": null}, {"def": "调节;调和", "example": null}, {"def": "家之所有为剂。--清·方苞《狱中杂记》", "example": null}, {"def": "又如调剂;剂和(调药;调和);剂救(调和弥补);剂调(调节)", "example": null}, {"def": "剂", "example": null}, {"def": "古代买卖时用的契券", "example": null}, {"def": "以两剂禁民狱。--《周礼·大司寇》", "example": null}, {"def": "剂jì", "example": null}, {"def": "①齐，齐平。", "example": null}, {"def": "②剪绝;割截。", "example": null}, {"def": "③调和;调节。", "example": null}, {"def": "④指以多味药合成的药剂。", "example": null}, {"def": "⑤指制墨时用烟胶等掺调的剂型，因亦指墨。", "example": null}, {"def": "⑥剂子。指从和好的大块面中分出来的小块。", "example": null}, {"def": "⑦量词。多用于指称药物。", "example": null}, {"def": "⑧见\\"劑鋼\\"。", "example": null}, {"def": "⑨古代买卖所用的契据，长券叫质，短券叫剂。", "example": null}, {"def": "⑩谓决定买卖。", "example": null}, {"def": "⑾古代狱讼的要辞。", "example": null}]','chinese-xinhua','0'),
('2101143296100274183','季','1','jì','子','8',NULL,'[{"def": "季", "example": null}, {"def": "(会意。从子,从稚省。稚”亦兼表读音。本义即排行最后的)", "example": null}, {"def": "同本义(与老”相对)", "example": null}, {"def": "季,少称。--《说文》", "example": null}, {"def": "曰伯某甫仲叔季,唯其所当。--《仪礼·士冠礼》。注伯、仲、叔、季,长幼之称。”", "example": null}, {"def": "季者,有中之辞也。╠《谷梁传·昭公二十五年》", "example": null}, {"def": "季者,幼也。--《白虎通》", "example": null}, {"def": "有齐季女。--《诗·召南·采蘯》", "example": null}, {"def": "生四子,太祖其季也。--《明史·太祖本纪》", "example": null}, {"def": "又如季女(最小的女儿);季父(父亲的幼弟);季指(小指头);季弟(最小的弟弟)", "example": null}, {"def": "一年四季中,每季的最后一个月", "example": null}, {"def": "季春之月。", "example": null}, {"def": "季jì", "example": null}, {"def": "⒈兄弟排行，有时用伯、仲、叔、～为序。～最小，排在最后～弟十五岁。～父（小叔叔）来了。", "example": null}, {"def": "⒉一年中每三个月为一季第二～度。春、夏、秋、冬四～（上古时期称\\"四时\\"）。", "example": null}, {"def": "⒊具有某种特征的一段时期雨～。旺～儿。这个～子太清闲了。", "example": null}, {"def": "⒋一个时期或一个朝代的末了～冬风且凉『～（汉朝末年）失权柄，董卓乱天常。", "example": null}]','chinese-xinhua','0'),
('2101143296100274184','哜','1','jì','口','9',NULL,'[{"def": "哜", "example": null}, {"def": "微微尝一点", "example": null}, {"def": "哜,尝也。从口,齐声。--《说文》", "example": null}, {"def": "太保受同祭哜。--《书·顾命》", "example": null}, {"def": "哜肺一。--《仪礼·有司彻》", "example": null}, {"def": "主人以酢也哜之。--《礼记·杂记》", "example": null}, {"def": "管弦哜哜。--《玄元乐》", "example": null}, {"def": "鹍鸡鸣以哜哜。--班彪《北征赋》", "example": null}, {"def": "吸", "example": null}, {"def": "蚁喜甜芽,可哜其甜汁也。--清·徐珂《清稗类钞》", "example": null}, {"def": "哜哜嘈嘈", "example": null}, {"def": "屋里面哜哜嘈嘈,不知他们在说些什么", "example": null}, {"def": "哜jì〈动〉尝（滋味）＞古云∶\\"主人之酢也，～之。\\"", "example": null}, {"def": "哜jiē 1.见\\"哜哜\\"﹑\\"哜咨\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296100274185','迹','1','jì','辶','9',NULL,'[{"def": "迹", "example": null}, {"def": "同本义", "example": null}, {"def": "赵主父令工施钩梯而缘播吾(山名),刻疏人迹其上。--《韩非子·外储说左上》", "example": null}, {"def": "又如浪迹天涯;人迹(人的足迹);人急至;迹蹈(重复走过的路);迹状(行迹);迹响(踪纪声响)", "example": null}, {"def": "留下的印子", "example": null}, {"def": "蟆入草间,蹑迹披求。--《聊斋志异·促织》", "example": null}, {"def": "又如痕迹;血迹;笔迹;墨迹", "example": null}, {"def": "前人留下的事物(主要指建筑或器物)", "example": null}, {"def": "故平公之迹不可明也。--《韩非子·难一》", "example": null}, {"def": "又如古迹;胜迹;古城墙的遗迹;史迹;迹相(表露出来的不很显著的情况,可借以推断过去或将来)", "example": null}, {"def": "通绩”。功劳", "example": null}, {"def": "如是则其迹长矣。--《", "example": null}, {"def": "迹（踖、蹟）jì", "example": null}, {"def": "⒈脚印留有足～。寻觅踪～。〈引〉留下的印子，或前人遗留下的事物（多指建筑或器物）痕～。保存遗～。保护古～。", "example": null}, {"def": "⒉重要的，奇特的事情事～。奇～。", "example": null}, {"def": "⒊", "example": null}, {"def": "迹jī 1.脚印;足迹。 2.痕迹。 3.指手迹。 4.形迹;行动。 5.业绩;事迹。 6.追踪;追寻。 7.至;蹈。 8.遵循;仿效。 9.考核;推究。 10.量词。相当于\\"步\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296100274186','绩','1','jì','纟','11',NULL,'[{"def": "绩", "example": null}, {"def": "把麻纤维披开接续起来搓成线", "example": null}, {"def": "绩,缉也。从糸,责声。--《说文》", "example": null}, {"def": "不绩其麻。--《诗·陈风·东门之枌》", "example": null}, {"def": "八月载绩。--《诗·豳风·七月》。传载绩,丝事毕而麻事起矣。”", "example": null}, {"def": "公父文伯退朝,朝母。其母方绩。--《国语·鲁语下》", "example": null}, {"def": "又如绩绪(搓麻线);绩女(纺织的女郎);绩火(夜晚纺织时用来照明的灯火);绩纺(泛指纺纱,绩麻诸事。即纺绩)", "example": null}, {"def": "承继", "example": null}, {"def": "绩", "example": null}, {"def": "成就;功业", "example": null}, {"def": "绩,功也,又,业也,又,事也,又,成也。字亦作勣。--《尔雅》", "example": null}, {"def": "勣,功也。--《声类》", "example": null}, {"def": "庶绩", "example": null}, {"def": "绩（", "example": null}, {"def": "⒉勣）jì", "example": null}, {"def": "⒈缉线，将麻搓成绳或线纺～。", "example": null}, {"def": "⒉功业，成果业～。巨大成～。战～辉煌。丰功伟～。", "example": null}, {"def": "绩jī 1.功业。", "example": null}]','chinese-xinhua','0'),
