('2101143296100274203','泲','1','jǐ','','3',NULL,'[{"def": "泲jǐ 1.过滤。 2.同\\"挤\\"。用力使从孔隙中流出。 3.同\\"济\\"。古水名。古四渎之一。发源于河南省济源县王屋山，东流至山东省东北部入海。历代多次变迁，今已不可详考", "example": null}, {"def": "。 4.同\\"济\\"。古水名。发源于河北省赞皇山，东流至柏乡县东注入宁晋泊。", "example": null}]','chinese-xinhua','0'),
('2101143296100274204','虮','1','jǐ','虫','8',NULL,'[{"def": "虮", "example": null}, {"def": "虮子,即虱卵,虱的卵", "example": null}, {"def": "牛马之气蒸,生虮虱。--《淮南子·虮虱》", "example": null}, {"def": "又如虮子(虱的卵。常比喻微细的事物);虮虱(虱及其卵。比喻卑贱或微小);虮肝(比喻微小或珍贵的食物)", "example": null}, {"def": "酒面上的浮沫", "example": null}, {"def": "浮虮星沸,飞华萍接。--《晋书》", "example": null}, {"def": "虮（蟣）jǐ", "example": null}]','chinese-xinhua','0'),
('2101143296100274205','挤','1','jǐ','扌','9',NULL,'[{"def": "挤", "example": null}, {"def": "(形声。从手,齐声。本义推开;除去)", "example": null}, {"def": "同本义", "example": null}, {"def": "挤,排也。--《说文》", "example": null}, {"def": "挤,推也。--《广雅》", "example": null}, {"def": "小人老而无子,知挤于沟壑矣。--《左传·昭公十三年》", "example": null}, {"def": "汉军却,为楚所挤。--《史记·项羽本纪》", "example": null}, {"def": "又如挤住了(凑上遇上而又推脱不开)", "example": null}, {"def": "排斥;排挤", "example": null}, {"def": "故其君因其修以挤之。--《庄子·人间世》", "example": null}, {"def": "抑有功而挤有罪。--《荀子·仲尼》", "example": null}, {"def": "又如挤抑(排挤压抑);挤撮(合伙欺负;拿捏;排挤);挤陷(排挤陷害)", "example": null}, {"def": "毁坏;损坏", "example": null}, {"def": "挤社稷,失宗庙。--《逸周书", "example": null}, {"def": "挤（攄）jǐ", "example": null}, {"def": "⒈用力压使排出～牙膏。～羊奶。", "example": null}, {"def": "⒉想法子腾出来～时间。", "example": null}, {"def": "⒊拥，推，紧挨拥～。车厢里～满了人。街上也是人～人。〈引〉排斥相互排～。", "example": null}]','chinese-xinhua','0'),
('2101143296100274206','脊','1','jǐ','月','10',NULL,'[{"def": "脊", "example": null}, {"def": "(本义背中间的骨头)", "example": null}, {"def": "同本义", "example": null}, {"def": "脊,背吕也。--《说文》", "example": null}, {"def": "举肺脊。--《仪礼·特性礼》", "example": null}, {"def": "坎为美脊。--《易·说卦传》", "example": null}, {"def": "或碎脑以折脊。--李白《大猎赋》", "example": null}, {"def": "又如脊杖(在罪犯脊背上施加的杖刑);脊令(脊令原。即鹡鸰”,水鸟名。常比喻兄弟,或兄弟友爱,急难相顾)", "example": null}, {"def": "物体上像脊梁骨似的隆起部分", "example": null}, {"def": "理,条理", "example": null}, {"def": "有伦有脊。--《诗·小雅·正月》", "example": null}, {"def": "脊jǐ", "example": null}, {"def": "⒈人或动物背部的中轴骨骼～柱。通称～椎骨或～梁骨。", "example": null}, {"def": "⒉物体中间高起像脊的部分背～。山～。房屋～。", "example": null}, {"def": "脊jí 1.见\\"脊脊\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296100274207','掎','1','jǐ','扌','11',NULL,'[{"def": "掎", "example": null}, {"def": "掎,偏引也。从手,奇声。--《说文》", "example": null}, {"def": "伐木掎矣。--《诗·小雅·小弁》", "example": null}, {"def": "诸戎掎之。--《左传·襄公十四年》。疏言戾其足也。”", "example": null}, {"def": "掎止晏莱焉。--《国语·鲁语》。注从后曰掎。”", "example": null}, {"def": "躬掎禄曰。--《汉书·息夫躬传》。注从后引之也。”", "example": null}, {"def": "昔秦失其鹿,刘季遂而掎之。--《汉书·叙传》", "example": null}, {"def": "又如掎汩(犹牵动);掎拔(提引而出;挺拔);掎鹿(拉着鹿);掎裳连袂(牵裙连袖)", "example": null}, {"def": "发射", "example": null}, {"def": "机不虚掎。--班固《西都赋》", "example": null}, {"def": "牵制,拖住使不能自由行动", "example": null}, {"def": "掎jǐ拖住，牵制～角（也作\\"犄角\\"。捕鹿时，拖腿拉角。〈喻〉分兵牵制敌人）。", "example": null}]','chinese-xinhua','0'),
('2101143296100274208','鱾','1','jǐ','','10',NULL,'[{"def": "鱾jǐ 1.鱼类的一属。身体侧扁，略呈椭圆形，头小而钝，口小。生活在海底岩石间。", "example": null}]','chinese-xinhua','0'),
