('2101143296100274225','畿','1','jī','田','15',NULL,'[{"def": "畿", "example": null}, {"def": "(形声。从田,幾省声。本义国都四周的广大地区)", "example": null}, {"def": "古代王都所领辖的方千里地面◇指京城所管辖的地区", "example": null}, {"def": "畿,天子千里地。以逮近言之则曰畿也。--《说文》", "example": null}, {"def": "邦畿方千里。--《周礼·大行人》", "example": null}, {"def": "方千里曰王畿。--《周礼·职方式》", "example": null}, {"def": "邦畿千里。--《诗·商颂·玄鸟》", "example": null}, {"def": "视学京畿。--清·方苞《左忠毅公逸事》", "example": null}, {"def": "又如畿尉(卫戍京城的武官);畿限(王畿的界限);畿甸(京城效区);畿兵(驻京都的士兵)", "example": null}, {"def": "王畿之外的九畿", "example": null}, {"def": "乃以九畿之籍。--《周礼·大司马》。注犹限也。”按,九畿,", "example": null}, {"def": "畿 jī", "example": null}, {"def": "⒈〈古〉称国都周围的地区京～。", "example": null}, {"def": "⒉门槛。", "example": null}]','chinese-xinhua','0'),
('2101143296100274226','稽','1','jī','禾','15',NULL,'[{"def": "稽", "example": null}, {"def": "(形声。从禾,象树木曲头止住不上长的样子,从尤,旨声。本义停留;阻滞)", "example": null}, {"def": "同本义。引申为囤积", "example": null}, {"def": "稽,留止也。--《说文》", "example": null}, {"def": "司稽,察留连不时去者。--《周礼·司稽》注", "example": null}, {"def": "秦之水泔最而稽。--《管子·水地》", "example": null}, {"def": "令出而不稽。--《管子·君臣上》", "example": null}, {"def": "稽市物。--《汉书·食货志》。注贮滞也。”", "example": null}, {"def": "又如稽欠(滞留拖欠);稽身(拖住身子);稽留(在外久留);稽诣(停顿);稽固(稽留停滞)", "example": null}, {"def": "延迟", "example": null}, {"def": "明晨炊米尽,吾起不容稽。--陆游《冬夜不寐》", "example": null}, {"def": "稽废时月。--《后汉书·列女传》", "example": null}, {"def": "又如稽迟(延误推迟);稽延(迟延)", "example": null}, {"def": "考核;核", "example": null}, {"def": "稽qǐ", "example": null}, {"def": "⒈", "example": null}, {"def": "稽jī", "example": null}, {"def": "⒈停留，拖延莫～留。不得～延。切勿～迟。", "example": null}, {"def": "⒉考核，考证～核。～查。无～之言勿听。", "example": null}, {"def": "⒊计较，争辩反唇相～（反过口来责问对方）。", "example": null}, {"def": "⒋见qǐ。", "example": null}]','chinese-xinhua','0'),
