('2101143296100274258','丌','1','jī','一','3',NULL,'[{"def": "姓", "example": null}, {"def": "丌jì", "example": null}, {"def": "①器物的座垫。《说文·丌部》\\"丌，下基也，荐物之丌，象形。\\"", "example": null}, {"def": "②〈名〉姓。", "example": null}]','chinese-xinhua','0'),
('2101143296100274259','讥','1','jī','讠','4',NULL,'[{"def": "讥", "example": null}, {"def": "(形声。从言,幾声。本义旁敲侧击地批评)", "example": null}, {"def": "同本义", "example": null}, {"def": "讥,诽也。--《说文》", "example": null}, {"def": "此何以书讥。--《公羊传·隐公二年》。注犹谴也。”", "example": null}, {"def": "诛讥罢只。--《楚辞·大招》。注非也。”", "example": null}, {"def": "二者交讥。--《史记·游侠传》。正义非言也”>", "example": null}]','chinese-xinhua','0'),
('2101143296100274260','击','1','jī','凵','5',NULL,'[{"def": "击", "example": null}, {"def": "(形声。从手,毄声。本义敲击,敲打)", "example": null}, {"def": "同本义", "example": null}, {"def": "欲以击柱。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "不肯击缻。", "example": null}, {"def": "留击柝者。--《资治通鉴·唐纪》", "example": null}, {"def": "使击柝如故。", "example": null}, {"def": "援玉 枹兮击鸣鼓。--《楚辞·九歌·国殇》", "example": null}, {"def": "又如击壤(相传尧时有老人击壤而歌曰日出而作,日入而息,凿井而饮,耕田而食,率力于我何有哉?后因以比喻太平盛世);击节(打拍子);击鞠(击皮球)", "example": null}, {"def": "攻击;攻打", "example": null}, {"def": "而诸侯敢救者,已拔赵,必移兵击之。--《史记·魏公子列传》", "example": null}, {"def": "又如击排(攻击排斥);击排冒没(攻击排斥,轻率而不顾一切);击床(击杀于床上)", "example": null}, {"def": "击（擊）jī", "example": null}, {"def": "⒈打，敲打～鼓。敲～。～掌。〈引〉碰撞，接触冲～。目～（亲眼所见）。车毂～，人肩摩（车挨着车，人挨着人）。", "example": null}, {"def": "⒉攻打攻～。拳～。炮～。导弹～。〈引〉击杀～牛。", "example": null}, {"def": "⒊刺～剑。", "example": null}, {"def": "击xí 1.男巫。", "example": null}, {"def": "击jì 1.人名。春秋晋有屠击。见《左传．僖公二十八年》。", "example": null}]','chinese-xinhua','0'),
('2101143296100274261','叽','1','jī','口','5',NULL,'[{"def": "叽", "example": null}, {"def": "稍微吃一点", "example": null}, {"def": "嘰,小食也。从口,幾声。--《说文》", "example": null}, {"def": "叽琼华。--《大人赋》", "example": null}, {"def": "进秙(叽)进羞。--《礼记·玉藻》", "example": null}, {"def": "呼吸沆瀣兮餐朝霞,噍咀芝英", "example": null}, {"def": "茹,叽,食也。--唐·段成式《酉阳杂俎》", "example": null}, {"def": "悲叹", "example": null}, {"def": "纣为象箸而箕子叽。--《淮南子·缪称训》", "example": null}, {"def": "叽", "example": null}, {"def": "形容鸟声、说话声或各种嘈杂声", "example": null}, {"def": "叽jī拟声词小鸟～～地叫。［语］～咕 ～里旮旯儿(各个角落 哔 ～(纺织品)", "example": null}]','chinese-xinhua','0'),
('2101143296100274262','饥','1','jī','饣','5',NULL,'[{"def": "饥", "example": null}, {"def": "(形声。从食,幾声。本义荒年,五谷无收)", "example": null}, {"def": "同本义", "example": null}, {"def": "饑,谷不熟为饑。--《说文》", "example": null}, {"def": "五谷不熟谓之饥。--《墨子·七患》", "example": null}, {"def": "降丧饥馑。--《诗·小雅·雨无止》", "example": null}, {"def": "齐尝大饥,道旁饿死者不可数也。--《韩非子·外储说右上》", "example": null}, {"def": "凶年饥发,君之民老弱转乎沟壑。--《孟子·梁惠王下》", "example": null}, {"def": "四时不出,天下大饥。--《淮南子·天文》", "example": null}, {"def": "今山东饥馑,人庶相食。--《汉书·翼奉传》", "example": null}, {"def": "又如饥荒;饥馁(饥饿);饥时得一口(紧要处得人救济,恩德深厚);饥氓(逃荒的人);饥岁(荒年)", "example": null}, {"def": "饥（饑）jī", "example": null}, {"def": "⒈饿，跟\\"饱\\"相对～饿难熬。～肠辘辘。～不择食。", "example": null}, {"def": "⒉灾荒，年收成不好～荒。～岁。", "example": null}]','chinese-xinhua','0'),
('2101143296100274263','乩','1','jī','乙','6',NULL,'[{"def": "乩", "example": null}, {"def": "通过占卜问吉凶", "example": null}, {"def": "堂上设了乩坛。--《红楼梦》", "example": null}, {"def": "又如乩语(巫神在沙盘上写出的预示吉凶的话);乩坛(放扶乩用具的桌子);乩架(扶乩用的架子);扶乩(又叫扶鸾。二人扶丁字形木架在沙盘上划字,说是为人决疑治病,预示吉凶", "example": null}, {"def": ")", "example": null}, {"def": "乩jī", "example": null}]','chinese-xinhua','0'),
