('2101143296104468538','牮','1','jiàn','牛','9',NULL,'[{"def": "牮", "example": null}, {"def": "斜着支撑", "example": null}, {"def": "用土石挡水", "example": null}, {"def": "以土石遮水亦曰牮。--《字汇》", "example": null}, {"def": "牮jiàn", "example": null}, {"def": "⒈斜着支撑，用柱子支撑倾斜了的房屋打～拨正。", "example": null}, {"def": "⒉用土石等挡水。", "example": null}]','chinese-xinhua','0'),
('2101143296104468539','荐','1','jiàn','艹','9',NULL,'[{"def": "荐", "example": null}, {"def": "(形声。从草,存声。本义草垫子) 同本义", "example": null}, {"def": "荐,薦席也。--《说文》。按,凡亲地者谓之筵,加于筵者谓之席。席即因也,重于筵也。", "example": null}, {"def": "荐", "example": null}, {"def": "再;又;接连", "example": null}, {"def": "荐,再也。--《尔雅》", "example": null}, {"def": "荐,重也。--《小尔雅》", "example": null}, {"def": "晋荐饥。--《左传·僖公十三年》", "example": null}, {"def": "以荐食上国。--《左传·定公四年》", "example": null}, {"def": "饥馑荐降。--《国语·鲁语上》", "example": null}, {"def": "又如荐仍(接连而来);荐更(反复经历);荐臻(荐蓁。接连地来到;一再遇到);荐饥(连年灾荒;连续灾荒)", "example": null}, {"def": "荐", "example": null}, {"def": "同本义", "example": null}, {"def": "薦,黍蓬。--《尔雅》。按,蒿类也,或以为野茭。", "example": null}, {"def": "麋鹿食荐。--《庄", "example": null}, {"def": "荐（薦）jiàn", "example": null}, {"def": "⒈介绍，推举推～能人。举～贤人。", "example": null}, {"def": "⒉动物能吃的草鹿食～。", "example": null}, {"def": "⒊草席，草垫。〈引〉垫～鞋。", "example": null}]','chinese-xinhua','0'),
('2101143296104468540','贱','1','jiàn','贝','9',NULL,'[{"def": "贱", "example": null}, {"def": "(形声。从贝,戋声。本义价格低)", "example": null}, {"def": "同本义", "example": null}, {"def": "贱,买少也。--《说文》", "example": null}, {"def": "籴甚贵,伤民,甚贱伤农。--《汉书·食货志》", "example": null}, {"def": "心忧炭贱愿天寒。--唐·白居易《卖炭翁》", "example": null}, {"def": "又如贱敛贵出(低价买入,高价售出);贱酬(降价付钱);贱发(降价发卖);贱贸(低价出售);贱售(贱卖)", "example": null}, {"def": "地位低下,人格卑鄙", "example": null}, {"def": "贱,卑也。--《广雅》", "example": null}, {"def": "以辨其贵贱老幼废疾。--《周礼·小司徒》", "example": null}, {"def": "贫与贱。--《论语》。皇疏无位曰贱。”", "example": null}, {"def": "相如素贱人。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "鄙贱之人。", "example": null}, {"def": "无贵无贱。--唐·韩愈《师说》", "example": null}, {"def": "其辱", "example": null}, {"def": "贱（賤）jiàn", "example": null}, {"def": "⒈物价低，跟\\"贵\\"相对食（粮食）～则农贫。", "example": null}, {"def": "⒉地位低下，跟\\"高贵\\"相对卑～。贫～。", "example": null}, {"def": "⒊谦词～姓。～恙。", "example": null}, {"def": "⒋鄙视，轻视贵五谷而～金玉。", "example": null}]','chinese-xinhua','0'),
