('2101143296104468550','渐','1','jiàn','氵','11',NULL,'[{"def": "渐", "example": null}, {"def": "流入;入", "example": null}, {"def": "东渐于海。--《书·禹贡》", "example": null}, {"def": "又如渐渐(流淌的样子)", "example": null}, {"def": "淹没,浸泡", "example": null}, {"def": "其渐之滫,君子不近,庶人不服。--《荀子·劝学》", "example": null}, {"def": "淇水汤汤,渐车帏裳。--《诗·卫风·氓》", "example": null}, {"def": "渐,渍也。--《广雅》", "example": null}, {"def": "是渐之也。--《荀子·议兵》", "example": null}, {"def": "渐之滫中。--《史记·三王世家》", "example": null}, {"def": "治大地渐台。--《史记·孝武纪》", "example": null}, {"def": "泽兰渐被径。--《文选·谢灵运·游南亭诗》", "example": null}, {"def": "又如渐浸(浸润,渍染);渐涵(渐渍。犹浸润。引申为渍染,感化);渐摩(渐磨。浸润;教育感化);渐及(润泽普及)", "example": null}, {"def": "熏染,可染", "example": null}, {"def": "俗之渐民久。--《史记·货殖", "example": null}, {"def": "渐jiān", "example": null}, {"def": "⒈浸～渍。～染。", "example": null}, {"def": "⒉慢慢流入东～于海。〈引〉疏导禹功之大，～九川。", "example": null}, {"def": "渐jiàn", "example": null}, {"def": "⒈慢慢地，一点一点地，一步一步地逐～。～变。年齿（年龄）～长。循序～进。", "example": null}, {"def": "⒉事物的开端防微杜～。", "example": null}, {"def": "渐qián 1.潜伏。", "example": null}, {"def": "渐chán 1.山石高峻貌。", "example": null}]','chinese-xinhua','0'),
('2101143296104468551','谏','1','jiàn','讠','11',NULL,'[{"def": "谏", "example": null}, {"def": "(形声。从言,柬声。本义直言规劝)", "example": null}, {"def": "同本义", "example": null}, {"def": "谏,证也。--《说文》", "example": null}, {"def": "谏者,正也。--《楚辞·七谏序》", "example": null}, {"def": "谏,犹正也。以道正人行。--周礼·司谏》注", "example": null}, {"def": "掌谏五恶。--《周礼·保氏》。注以礼义正之。”", "example": null}, {"def": "三谏不从。--《公羊传·庄公二十四年》", "example": null}, {"def": "宫之奇之为人也,懦而不能强谏。--《左传·僖公二年》", "example": null}, {"def": "保氏常谏王恶。--《周礼·地官》", "example": null}, {"def": "大臣强谏。--《战国策·赵策》", "example": null}, {"def": "扶苏以数谏。--《史记·陈涉世家》", "example": null}, {"def": "忠谏之路。--诸葛亮《出师表》", "example": null}, {"def": "不为拒谏。--宋·王安石《游褒禅山记》", "example": null}, {"def": "又如谏阻纳质(", "example": null}, {"def": "谏jiàn〈古〉规劝君主、尊长或朋友，使其改正错误或过失进～。力～。", "example": null}]','chinese-xinhua','0'),
