('2101143296108662801','謇','1','jiǎn','言','17',NULL,'[{"def": "謇", "example": null}, {"def": "(形声。从言,寒省声。本义口吃) 同本义", "example": null}, {"def": "言不通利谓之謇吃。--《通俗文》", "example": null}, {"def": "因謇而徐言。--李延寿《北史·李谐传》", "example": null}, {"def": "又如謇吃(言语不流利)", "example": null}, {"def": "謇", "example": null}, {"def": "直言不讳,正直", "example": null}, {"def": "外似謇正,内实谄谀。--《北史·徐纥传》", "example": null}, {"def": "又如謇正(严肃正直);謇直(刚正耿直);謇謇(忠贞直言的样子;正直的言谈)", "example": null}, {"def": "謇jiǎn", "example": null}, {"def": "⒈口吃，结巴。", "example": null}, {"def": "⒉忠诚，正直～正。", "example": null}, {"def": "⒊文言句首，语气词。", "example": null}]','chinese-xinhua','0'),
('2101143296108662802','蹇','1','jiǎn','足','17',NULL,'[{"def": "蹇", "example": null}, {"def": "(形声。从足,寒省声。本义跛足)", "example": null}, {"def": "同本义", "example": null}, {"def": "蹇,跛也。--《说文》", "example": null}, {"def": "蹇膝伸不屈、易蹇、往蹇来连。--《素问·骨空论》", "example": null}, {"def": "驾蹇驴而无策兮。--《楚辞·谬谏》", "example": null}, {"def": "鄐克偻,而鲁使蹇。--《史记·晋世家》", "example": null}, {"def": "策蹇驴,囊图书。--马中锡《中山狼传》", "example": null}, {"def": "红装而蹇者。--明·袁宏道《满井游记》", "example": null}, {"def": "又如蹇兔(不能急走的跛脚兔。比喻弱小者);蹇驴(走不快的羸弱之驴);蹇人上天(跛子登天。比喻不可能的事)", "example": null}, {"def": "艰阻,不顺利", "example": null}, {"def": "蹇侘傺而含戚。--《楚辞·九章·哀郢》", "example": null}, {"def": "又如蹇拙(艰险;不走运);蹇蹇(艰难、不顺遂的样子);蹇剥(艰", "example": null}, {"def": "蹇jiǎn", "example": null}, {"def": "⒈跛，行动迟缓策～驴（策鞭打）。特指劣马或跛驴策～赴前程。", "example": null}, {"def": "⒉钝，困苦，不顺利～涩。～滞。前途多～。", "example": null}, {"def": "⒊〈古〉通\\"謇\\"。口吃，结巴。", "example": null}, {"def": "蹇qiān 1.通\\"褰\\"。揭;提起。参见\\"蹇裳\\"。 2.通\\"攓\\"﹑\\"搴\\"。拔取;得到。", "example": null}]','chinese-xinhua','0'),
