('2101143296117051399','睑','1','jiǎn','目','12',NULL,'[{"def": "睑", "example": null}, {"def": "眼皮,能够活动的眼皮盖", "example": null}, {"def": "倩人启睑拨视,则睛上生小翳。--《聊斋志异》", "example": null}, {"def": "唐时南诏人称州为睑", "example": null}, {"def": "夷语睑若州,曰云南睑,白崖睑。--《新唐书》", "example": null}, {"def": "睑板", "example": null}, {"def": "睑裂", "example": null}, {"def": "睑下垂", "example": null}, {"def": "睑炎", "example": null}, {"def": "睑（瞼）jiǎn眼睑，俗称\\"眼皮\\"～沿炎。", "example": null}]','chinese-xinhua','0'),
('2101143296117051400','硷','1','jiǎn','石','12',NULL,'[{"def": "硷（礆、鹼、鹻）jiǎn", "example": null}, {"def": "⒈通常指在水溶液中电离而生出氢氧根离子（）的化合物。如氢氧化钠、氢氧化钙等都是碱。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊被碱质侵蚀这堵墙壁～了。", "example": null}]','chinese-xinhua','0'),
