('2101143296117051410','戬','1','jiǎn','戈','14',NULL,'[{"def": "戬", "example": null}, {"def": "铲除,歼灭", "example": null}, {"def": "戬,灭也。从戈,晋声。--《说文》", "example": null}, {"def": "实始戬商。--《诗·鲁颂·閟宫》", "example": null}, {"def": "戬", "example": null}, {"def": "幸福;吉祥", "example": null}, {"def": "方凭戬福,伫咏丰年。--《隋书·音乐志下》", "example": null}, {"def": "又如戬福(幸福吉祥);戬谷(福禄)", "example": null}, {"def": "完美,无瑕", "example": null}, {"def": "戬jiǎn", "example": null}, {"def": "⒈剪除，灭除～灭。", "example": null}, {"def": "⒉吉祥，福。", "example": null}]','chinese-xinhua','0'),
('2101143296117051411','碱','1','jiǎn','石','14',NULL,'[{"def": "碱", "example": null}, {"def": "(碱”为鹼”的俗字。鹼”已简化为硷。而礆、鹻、塧、鹹、礆为过去俗用过的杂字)", "example": null}, {"def": "盐鹵", "example": null}, {"def": "鹹,北方味也。从鹵,咸声。--《说文》", "example": null}, {"def": "润下作鹹。--《书·洪范》", "example": null}, {"def": "以鹹养脉。--《周礼·疡医》", "example": null}, {"def": "在味为鹹。--《素问·阳阴应象大论》", "example": null}, {"def": "鹹音有二音咸者,润下之味;音减者,盐土之名◇人作鹼、作鹻,是矣。--《本草纲目》", "example": null}, {"def": "含氢氧根的化合物的统称。今作碱”。又专指纯碱", "example": null}, {"def": "碱", "example": null}, {"def": "被盐碱侵蚀", "example": null}, {"def": "碱（塧）jiǎn", "example": null}, {"def": "⒈通常指在水溶液中电离而生出氢氧根离子（）的化合物。如氢氧化钠、氢氧化钙等都是碱。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊被碱质侵蚀这堵墙壁～了。", "example": null}, {"def": "碱kǎn 1.坎，坑。", "example": null}, {"def": "碱xián 1.地名用字。碱厂，在辽宁省本溪县东南。", "example": null}]','chinese-xinhua','0'),
('2101143296117051412','翦','1','jiǎn','羽','15',NULL,'[{"def": "翦", "example": null}, {"def": "初生的羽毛", "example": null}, {"def": "翦,羽初生也。一曰矢羽。--《说文》。王筠注翦者谓新生之羽,整齐之状也。”段玉裁注羽初生如前齐也。前,古之翦字。”", "example": null}, {"def": "姓。", "example": null}, {"def": "翦", "example": null}, {"def": "剪整齐", "example": null}, {"def": "实始翦商。--《诗·鲁颂·閟宫》", "example": null}, {"def": "翦,齐也。--《释言》", "example": null}, {"def": "茅茨不翦。--《韩非子·五蠹》", "example": null}, {"def": "又如翦缀(裁剪缝纫);翦发(修剪头发);翦灯(修剪灯芯◇常指夜谈)", "example": null}, {"def": "割截;杀戮", "example": null}, {"def": "不翦其类也。--《礼记·文王世子》。注割截也。”", "example": null}, {"def": "又如翦刈(铲除);翦草除根(比喻彻底清除,不留后患);翦翎(剪除羽翎。常以喻因受羁缚,才能不", "example": null}, {"def": "翦jiǎn 1.斩断;除去。 2.消灭;削弱。 3.剪刀。 4.用剪刀铰。 5.删除。 6.挥动;扑打。 7.谓两手交叉。 8.量词。用于花枝。 9.通\\"践\\"。 10.通\\"浅\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296117051413','湔','1','jiān','氵','12',NULL,'[{"def": "湔", "example": null}, {"def": "(形声。从水,前声。本义水名。湔水,在四川)", "example": null}, {"def": "用水洗", "example": null}, {"def": "湔,濯也。--《三苍》", "example": null}, {"def": "湔,洒也。--《广雅》", "example": null}, {"def": "谁道湔裙人远。--王沂孙《南浦·春水》", "example": null}, {"def": "湔浣肠胃,漱涤五藏。--《史记》", "example": null}, {"def": "又如湔除(洗去污秽);湔汰(洗涤);湔刷(洗刷);湔拂(清洗、涤除)", "example": null}, {"def": "洗雪(耻辱);清除(过失、罪责等)", "example": null}, {"def": "近降赦恩,谋反大逆,皆蒙湔雪。--《金史·张特立传》", "example": null}, {"def": "又如湔雪(洗刷罪名,昭雪冤屈);湔改(洗去罪责,悔过自新);湔贷(洗罪赎罪);湔洒(洗刷,洗雪)", "example": null}, {"def": "浸入,浸润", "example": null}, {"def": "湔祓", "example": null}, {"def": "湔jiān", "example": null}, {"def": "⒈洗涤～洗。～雪（洗刷冤屈和耻辱）。", "example": null}, {"def": "⒉湔江，在四川省。", "example": null}, {"def": "湔jiàn 1.溅洒。", "example": null}]','chinese-xinhua','0'),
