('2101143296121245711','瀸','1','jiān','','13',NULL,'[{"def": "瀸jiān 1.浸渍;浸润。参见\\"瀸濇\\"﹑\\"瀸润\\"。 2.和洽。 3.泉水时有时无。 4.见\\"瀸污\\"。 5.通\\"歼\\"。消灭。参见\\"瀸积\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296121245712','戋','1','jiān','戈','5',NULL,'[{"def": "戋戋", "example": null}, {"def": "为数戋戋", "example": null}, {"def": "束帛戋戋", "example": null}, {"def": "戋（戔）jiān", "example": null}, {"def": "①少，微薄～ ～微物。", "example": null}, {"def": "②众多的样子灼灼（花艳盛）百朵红，～ ～五束素（素白绸）。", "example": null}, {"def": "戋chǎn 1.铲除;削平。", "example": null}]','chinese-xinhua','0'),
('2101143296121245713','奸','1','jiān','女','6',NULL,'[{"def": "奸", "example": null}, {"def": "(会意。从三女。本义奸邪,虚伪狡诈)", "example": null}, {"def": "同本义", "example": null}, {"def": "姦,私也。--《说文》", "example": null}, {"def": "姦,盗也。--《广雅》", "example": null}, {"def": "在内曰姦,在外曰宄。--《三苍》", "example": null}, {"def": "用轨之财者为姦。--《国语·鲁语》", "example": null}, {"def": "寇贼姦宄。--《书·舜典》", "example": null}, {"def": "是以其民饥寒并至,故为奸衺。--《墨子·辞过》", "example": null}, {"def": "故以刑治则民威,民威则无姦,无姦则民安其所乐。--《商君书·开塞》", "example": null}, {"def": "荡渨湋之姦咎兮。--《梦辞·惜贤》。注乱在内曰姦。”", "example": null}, {"def": "盗器为姦。--《左传·文公十八年》", "example": null}, {"def": "多贼姦些。--《楚辞·招魂》。注恶也。”", "example": null}, {"def": "姦宄是防。--张衡《西京赋》。注", "example": null}, {"def": "奸jiān", "example": null}, {"def": "⒈邪恶，狡诈～臣。～计。", "example": null}, {"def": "⒉男女间发生不正当的性行为通～。强～。", "example": null}, {"def": "⒊虚假～笑。", "example": null}, {"def": "⒋叛国的人汉～。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "奸gān 1.干犯，扰乱。 2.干求。", "example": null}]','chinese-xinhua','0'),
('2101143296121245714','尖','1','jiān','小','6',NULL,'[{"def": "尖", "example": null}, {"def": "(会意。从小,从大。一头小一头大为尖。本义物体的末端细削而锐利)", "example": null}, {"def": "同本义", "example": null}, {"def": "尖,锐也。--《广韵》", "example": null}, {"def": "按,尖”是后起的会意字。又如尖山(尖而高的山);尖屁股(借指坐不安稳);尖担担柴两头脱(比喻两头落空,什么也没捞着);尖顶木驴(尖头木驴。古代攻城战车)", "example": null}, {"def": "音调细而高,刺耳", "example": null}, {"def": "促织声尖尖似针,更深刺着旅人心。--贾岛《客思》", "example": null}, {"def": "又如尖声;尖嗓子;尖儿(戏曲中指忽然高亢的唱腔);尖脆(形容声音尖细清脆);尖厉(形容声音高而刺耳)", "example": null}, {"def": "新颖别致", "example": null}, {"def": "尖jiān", "example": null}, {"def": "⒈物体末端锐利或细小，也指物体细锐的末端塔～。钢笔～儿。小刀～儿。铅笔头太～了。牙签儿两头～。", "example": null}, {"def": "⒉声音高而细～嗓子。", "example": null}, {"def": "⒊感觉灵敏～耳朵。眼睛～。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "①大队伍前面执行侦察、警戒、突击等任务的兵员。", "example": null}, {"def": "②各行各业第一线的先进分子养鱼～兵。", "example": null}, {"def": "⒍", "example": null}, {"def": "①刺耳的～锐的呼啸声。", "example": null}, {"def": "②锋利的，深刻的～锐的锥子。～锐的批判。", "example": null}, {"def": "③激烈的～锐的战斗。", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
