('2101143296121245761','讲','1','jiǎnɡ','讠','6',NULL,'[{"def": "讲", "example": null}, {"def": "(形声。从言,冓声。本义和解)", "example": null}, {"def": "同本义", "example": null}, {"def": "讲,和解也。--《说文》", "example": null}, {"def": "而秦未与魏讲也。--《战国策·西周策》", "example": null}, {"def": "与魏讲罢兵。--《史记·樗里子甘茂传》", "example": null}, {"def": "以中情出,小曰閒,大曰讲。--《大载礼记·千乘》", "example": null}, {"def": "卒使公子池以三城讲于三国,之兵乃退。--《战国策·秦策》", "example": null}, {"def": "引兵而归,因使人索六城于赵而讲。--《战国策·赵策》", "example": null}, {"def": "又如讲息(和解息争);讲贡(讲和纳贡);讲款(讲和,议款);讲盟(订盟媾和)", "example": null}, {"def": "讲习(共同讨论研习学问)", "example": null}, {"def": "道士讲火经。--唐·李朝威《柳毅传》", "example": null}, {"def": "讲中外之故。--清·梁", "example": null}, {"def": "讲(講)jiǎng", "example": null}, {"def": "⒈谈，说～普通话。～故事。", "example": null}, {"def": "⒉解释，说明～解。～课。", "example": null}, {"def": "⒊注重，顾到，谋求～清洁。～政策。～团结。", "example": null}, {"def": "⒋商讨，商议～价。～条件。", "example": null}, {"def": "⒌", "example": null}, {"def": "①注重，探求～究整洁。～究效益。", "example": null}, {"def": "②精致，美观这个实验室相当～究。", "example": null}, {"def": "③一定的方法、道理或值得注意的翻译外国文学，在技巧上是大有～究的。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
('2101143296121245762','奖','1','jiǎnɡ','大','9',NULL,'[{"def": "奖", "example": null}, {"def": "(形声。字本作妜”,从犬,将省声。本义驱使狗猛进)", "example": null}, {"def": "同本义", "example": null}, {"def": "奖,嗾犬厉之也。--《说文》。段玉裁注《口部》‘嗾,使犬声也。’厉之,犹勉之也。”", "example": null}, {"def": "劝勉;鼓励", "example": null}, {"def": "奖,劝也。--《小尔雅》", "example": null}, {"def": "以奖善人。--《左传·昭公二十二年》。疏劝也。”", "example": null}, {"def": "奖厉太子。--《汉书·哀帝纪》。注劝使也。”", "example": null}, {"def": "奖率三军。--诸葛亮《出师表》", "example": null}, {"def": "又如奖导(劝勉诱导);奖激(劝勉激励);奖慰(劝勉安慰);奖鉴(勉励劝戒);奖蹙威柄(勉励促成其成为权威者);奖拔(勉励提拔)", "example": null}, {"def": "辅助", "example": null}, {"def": "皆奖王室。--", "example": null}, {"def": "奖（奬）jiǎng", "example": null}, {"def": "⒈劝勉，勉励当～率三军（应当勉励并率领三军）。", "example": null}, {"def": "⒉称赞，表扬夸～。嘉～。～罚分明。", "example": null}, {"def": "⒊为了鼓励、表扬而给予的荣誉或财物等～状。～章。～金。～品。", "example": null}, {"def": "⒋指彩金抽～券。中头～。", "example": null}]','chinese-xinhua','0'),
('2101143296121245763','桨','1','jiǎnɡ','木','10',NULL,'[{"def": "桨", "example": null}, {"def": "(形声。从木,将声。本义划船用具。短小者称桨) 同本义", "example": null}, {"def": "金桨木兰船,戏采江南莲。--南朝梁·刘孝威《采莲曲》", "example": null}, {"def": "桨（槳）jiǎng划船的工具。上端为圆杆，利于手握；下端为板状，用以拨水，使船前进。", "example": null}]','chinese-xinhua','0'),
('2101143296121245764','蒋','1','jiǎnɡ','艹','12',NULL,'[{"def": "蒋", "example": null}, {"def": "(形声。从苃,将声。本义植物名。即茭白”)", "example": null}, {"def": "古国名", "example": null}, {"def": "姓", "example": null}, {"def": "蒋（蕐）jiǎng姓。", "example": null}, {"def": "蒋jiāng 1.植物名。菰。即茭白。 2.见\\"蒋蒋\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296121245765','奬','1','jiǎnɡ','','12',NULL,'[{"def": "奬jiǎng 1.劝勉;鼓励。 2.辅助。 3.称许，赞美。 4.为了表扬﹑鼓励而给予荣誉或财物。 5.指奖给的荣誉或财物。 6.通\\"将\\"。成，顺成。", "example": null}]','chinese-xinhua','0'),
('2101143296121245766','耩','1','jiǎnɡ','耒','16',NULL,'[{"def": "耩", "example": null}, {"def": "用耧播种", "example": null}, {"def": "耕地", "example": null}, {"def": "锄得五遍,已上下不烦耩。--《齐民要术》", "example": null}, {"def": "用耧施肥", "example": null}, {"def": "耩jiǎng旧式农具，用耩播种或施肥～蚕豆。～有机肥。", "example": null}]','chinese-xinhua','0'),
('2101143296121245767','江','1','jiānɡ','氵','6',NULL,'[{"def": "江", "example": null}, {"def": "(形声。从水,工声。本义长江的专称)", "example": null}, {"def": "同本义", "example": null}, {"def": "江,江水也。犊", "example": null}, {"def": "江之永矣。--《诗·周南·汉广》", "example": null}, {"def": "滔滔江汉。--《诗·小雅·四月》", "example": null}, {"def": "江上几人在,天涯孤棹还。--温庭筠《送人东归》", "example": null}, {"def": "江间波浪兼天涌,塞上风云接地阴。--杜甫《秋兴八首》", "example": null}, {"def": "又如江汉(长江与汉水);江水(即长江);江左烟霞(江东的山水风景。江左指今江苏、安徽等长江沿江地带);江陵(县名。在今湖北省中部偏南、长江沿岸。向为我国南北陆路交", "example": null}, {"def": "通要冲)", "example": null}, {"def": "江河的通称", "example": null}, {"def": "南方的河流多称江”,如珠江”、沅江”;北方的河流多称河”,如", "example": null}, {"def": "江jiāng", "example": null}, {"def": "⒈泛指大的河流珠～。岷～。", "example": null}, {"def": "⒉特指长江（也叫\\"扬子江\\"）～淮地区。百万雄师过大～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296121245768','姜','1','jiānɡ','女','9',NULL,'[{"def": "姜", "example": null}, {"def": "(形声。从女,羊声。本义水名。姜水)", "example": null}, {"def": "同本义", "example": null}, {"def": "岐水经姜氏城为姜水。--《水经注·渭水》注", "example": null}, {"def": "黄帝以姬水成,炎帝以姜水成。--《国语》", "example": null}, {"def": "姓", "example": null}, {"def": "姜,神农居姜水,以为姓。--《说文》", "example": null}, {"def": "又如姜太公钓鱼(姜子牙世称姜太公,即吕尚。曾辅佐周文王、周武王灭商◇被封为齐侯。传说姜子牙在渭水边钓鱼的时候,钓绳端的直钓不设饵。歇后用法,愿者上钩,指事情", "example": null}, {"def": "出于自愿)", "example": null}, {"def": "姜", "example": null}, {"def": "生姜", "example": null}, {"def": "楠梓姜桂。--《史记·货殖列传》", "example": null}, {"def": "一种姜属多年生草本植物(z", "example": null}, {"def": "姜（薻）jiāng通称\\"生姜\\"。多年生草本，根茎呈块状，黄色，味辛辣，调味或供药用。", "example": null}]','chinese-xinhua','0'),
('2101143296121245769','将','1','jiānɡ','寸','9',NULL,'[{"def": "将", "example": null}, {"def": "(形声。从寸,酱省声。从寸”,表示与手有关。本义将领,带兵的人)", "example": null}, {"def": "扶持,扶助", "example": null}, {"def": "将,扶也。--《广雅》", "example": null}, {"def": "无将大车。--《诗·小雅·无将大车》", "example": null}, {"def": "天不我将。--《诗·大雅·桑柔》", "example": null}, {"def": "爷娘闻女来,出郭相扶将。--《乐府诗集·木兰诗》", "example": null}, {"def": "为人将车。--《史记·田叔传》。索隐犹御车也。”", "example": null}, {"def": "吏谨将之。--《荀子·成相》。注持也。”", "example": null}, {"def": "又如将美(助成好事);将引(扶助收纳);将扶(扶持;搀扶);将助(扶助;支持)", "example": null}, {"def": "奉行,秉承", "example": null}, {"def": "使臣将王命,岂不如贼焉?--元结《贼退示官吏》", "example": null}, {"def": "又如将明(大臣的辅佐赞助。将奉行;明", "example": null}, {"def": "将（將）jiāng", "example": null}, {"def": "⒈快要～要。她～去北京。", "example": null}, {"def": "⒉介词。把～祖国建设得更加美好。", "example": null}, {"def": "⒊拿，用，随顺～功补过。～计就计。", "example": null}, {"def": "⒋调养，保养～养。～息。", "example": null}, {"def": "⒌扶，持，带领出入相扶～。挈妇～雏。", "example": null}, {"def": "①对高级军官的称呼。", "example": null}, {"def": "②下象棋时攻击对方的\\"将\\"或\\"帅\\"。～军（又〈喻〉使人为难～了他一军）。", "example": null}, {"def": "⒍用语言刺激你把他～急了。", "example": null}, {"def": "⒎〈方〉兽类生子～驹子。～小猪儿。", "example": null}, {"def": "⒏副词。又，且～信～疑。", "example": null}, {"def": "⒐连词⊥，与，同暂伴月～影。", "example": null}, {"def": "⒑助词。用于动词\\"出来\\"、\\"起来\\"、\\"进去\\"等的中间跳～出来～起来。打～进去。迎～上去。", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "将（將）jiàng", "example": null}, {"def": "⒈带兵的人，高级武官～领。猛～。虎～。", "example": null}, {"def": "⒉敢想敢干的人闯～。", "example": null}, {"def": "⒊军衔名。在校级之上少～。上～。", "example": null}, {"def": "⒋统率，指挥～兵打仗。", "example": null}, {"def": "将qiāng 1.愿;请。", "example": null}]','chinese-xinhua','0'),
