('2101143296121245784','礓','1','jiānɡ','石','18',NULL,'[{"def": "礓", "example": null}, {"def": "小石", "example": null}, {"def": "礓jiāng砂礓，一种不透水的矿石块或颗粒。可作建筑材料。", "example": null}]','chinese-xinhua','0'),
('2101143296121245785','疆','1','jiānɡ','田','19',NULL,'[{"def": "疆", "example": null}, {"def": "(指事。从土,从弓,从畺。从弓”,表示以弓记步,即以弓来丈量土地。本义田界)", "example": null}, {"def": "同本义", "example": null}, {"def": "畺,界也。从田,三其界画也。指事。--《说文》", "example": null}, {"def": "疆埸有瓜。--《诗·小雅·信南山》", "example": null}, {"def": "有掌疆。--《周礼·夏官》", "example": null}, {"def": "又如疆陇(田界);疆畛(地界;界限);疆畎(指田地,垄亩沟渠)", "example": null}, {"def": "引申为国界、边界", "example": null}, {"def": "出疆必请。--《礼记·曲礼》", "example": null}, {"def": "固封疆。--《礼记·月令》", "example": null}, {"def": "又如疆宇(疆界的四陲。引申为国土);疆吏(驻防边疆的官吏);疆事(边疆的事故。多指边界的冲突、争执而言);疆略(疆界;境界);疆圻(疆界)", "example": null}, {"def": "疆域", "example": null}, {"def": "制其畿疆而沟", "example": null}, {"def": "疆jiāng", "example": null}, {"def": "⒈界限，边界，边境守卫～土。边～平和。恢复故～（故原有的）。", "example": null}, {"def": "⒉极限，尽头万寿无～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "疆jiàng 1.坚土。", "example": null}]','chinese-xinhua','0'),
