('2101143296121245787','嚼','1','jiáo','口','20',NULL,'[{"def": "嚼〈动〉 jiao", "example": null}, {"def": "(形声。从口,爵声。本义以牙磨碎食物)", "example": null}, {"def": "同本义", "example": null}, {"def": "嚼,削也。--《释名》", "example": null}, {"def": "嚼,噬嚼也。--《玉篇》", "example": null}, {"def": "又如嚼蜡(多指文章或讲话没有滋味,没有意思);嚼吞(咀嚼吞食);嚼咽(咀嚼吞咽);嚼头(经得起咀嚼的厚味(多用比喻义))", "example": null}, {"def": "吃", "example": null}, {"def": "剥蚀、蛀蚀、冲蚀或冰川侵蚀", "example": null}, {"def": "水嚼沙洲树出根。--宋·真山民《朱溪涧》", "example": null}, {"def": "干杯", "example": null}, {"def": "复嚼者,京都饮酒相强之辞也。--《续汉书·五行志》", "example": null}, {"def": "解姊子负解之势,与人饮,使之嚼。非其任疆必灌之。", "example": null}, {"def": "嚼jiáo", "example": null}, {"def": "⒈使用牙齿将食物磨碎。", "example": null}, {"def": "⒉", "example": null}, {"def": "嚼jiào", "example": null}, {"def": "嚼 jué", "example": null}, {"def": "⒈使用牙齿磨碎食物，用于一些复合词咀～。", "example": null}, {"def": "⒉见jiáo。", "example": null}]','chinese-xinhua','0'),
('2101143296121245788','叫','1','jiào','口','5',NULL,'[{"def": "叫〈动〉", "example": null}, {"def": "(形声。本义呼,喊)", "example": null}, {"def": "同本义", "example": null}, {"def": "叫,噁也。--《说文》", "example": null}, {"def": "或不知叫号。--《诗·小雅·北山》", "example": null}, {"def": "叫我友兮配耦。--《楚辞·疾世》。注急呼也。”", "example": null}, {"def": "叫帝阍使辟扉兮。--张衡《思玄赋》", "example": null}, {"def": "戍卒叫,函谷举。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如叫命(骂人话。临死时呼喊声);叫聒(声音吵杂刺耳);叫号(大声呼喊);叫头(戏剧用语。剧中人物之一,在剧情悲痛、情急愤怒之时,高喊对方,称为叫头);叫曲(唱曲时没有", "example": null}, {"def": "蕴藉的韵味、感情)", "example": null}, {"def": "招唤,招呼", "example": null}, {"def": "或叫于宋大庙。--《左传·襄公三十年》。注呼也。”", "example": null}, {"def": "高声叫道…--《", "example": null}, {"def": "叫（呌）jiào", "example": null}, {"def": "⒈呼喊呼～～。大声～。", "example": null}, {"def": "⒉动物发出声音狗～。鸟～。", "example": null}, {"def": "⒊招唤请你～他快来。", "example": null}, {"def": "⒋称为，称呼这～电视机。你～什么名字？", "example": null}, {"def": "⒌使，令～河水改道。要～人听得懂。", "example": null}, {"def": "⒍介词。被，让几个敌人～我们活捉了。别～人笑话咱。", "example": null}]','chinese-xinhua','0'),
