('2101143296125440034','浇','1','jiāo','氵','9',NULL,'[{"def": "浇〈动〉", "example": null}, {"def": "(形声。从水,尧声。本义沃灌,灌溉)", "example": null}, {"def": "同本义", "example": null}, {"def": "浇,沃也。--《说文》", "example": null}, {"def": "有酒唯浇赵州土。--李贺《浩歌》", "example": null}, {"def": "浇花亦自有时。--欧阳修《洛阳风俗记》", "example": null}, {"def": "又如浇花(用水灌花);浇溉(灌溉);浇沃(浇灌)", "example": null}, {"def": "饮酒", "example": null}, {"def": "淋;洒", "example": null}, {"def": "浇铸", "example": null}, {"def": "浇（澆）jiāo", "example": null}, {"def": "⒈灌溉～花。～菜地。", "example": null}, {"def": "⒉把液体倒入模子里～钢板。", "example": null}, {"def": "⒊淋～水洗头发。", "example": null}, {"def": "⒋刻薄，不厚道～薄。", "example": null}, {"def": "浇nào 1.急流回旋貌。 2.指湍流扬起波浪。 3.通\\"挠\\"。参见\\"浇滑\\"。", "example": null}, {"def": "浇xiāo 1.方言〓南长沙等地呼布帛薄而不坚为浇。", "example": null}]','chinese-xinhua','0'),
('2101143296125440035','茭','1','jiāo','艹','9',NULL,'[{"def": "茭〈名〉", "example": null}, {"def": "(形声。从草,交声。本义蔬类植物)", "example": null}, {"def": "喂牲口的干草", "example": null}, {"def": "茭,干刍。--《说文》", "example": null}, {"def": "峙乃刍茭。--《书·费誓》", "example": null}, {"def": "民茭牧其中耳。--《史记·河渠书》", "example": null}, {"def": "又如茭牧(收刈牧草及放养牲畜);茭草(茭刍。作饲料的干草)", "example": null}, {"def": "篾缆,即用薄竹片或芦苇编成的大索", "example": null}, {"def": "搴长茭兮沈美玉。--《史记·河渠书》。", "example": null}, {"def": "搴长茭兮沉美玉。--《汉书·沟洫志》", "example": null}, {"def": "茭白,菰的花茎经一种黑粉菌侵入后,刺激其细胞增生而形成的肥大嫩茎。可作蔬菜", "example": null}, {"def": "米是九谷", "example": null}, {"def": "茭jiāo菰的嫩茎经黑穗菌寄生后膨大，叫\\"茭白\\"，作蔬菜吃。", "example": null}, {"def": "茭xiào 1.草根。", "example": null}, {"def": "茭jī 1.弓檠。正弓之器。", "example": null}]','chinese-xinhua','0'),
('2101143296125440036','骄','1','jiāo','马','9',NULL,'[{"def": "骄〈名〉", "example": null}, {"def": "(形声。从马,乔声。本义六尺高的马) 同本义", "example": null}, {"def": "骄,马高六尺为骄。《诗》曰我马唯骄。”--《说文》", "example": null}, {"def": "四牡有骄。--《诗·卫风·硕人》", "example": null}, {"def": "骄 〈形〉", "example": null}, {"def": "马雄壮,泛指高大雄壮", "example": null}, {"def": "傲慢;骄矜", "example": null}, {"def": "不敢以其富贵骄士。--《史记·魏公子列传》", "example": null}, {"def": "谏而无骄。--《礼记·少仪》。注谓言行谋从恃知而慢也。”", "example": null}, {"def": "骄奢淫泆。--《左传·隐公三年》。注谓恃己凌物。”", "example": null}, {"def": "在上不骄。--《孝经》。注无礼为骄。”", "example": null}, {"def": "骄", "example": null}, {"def": "骄（驕）jiāo", "example": null}, {"def": "⒈马高大健壮的样子四牡有～（牡公马）。", "example": null}, {"def": "⒉自满，自高自大～傲自满。～兵必败。戒～戒躁。〈引〉放纵～奢淫逸。", "example": null}, {"def": "⒊猛烈～阳灼人。", "example": null}, {"def": "⒋", "example": null}, {"def": "①自高自大，瞧不起别人～傲使人落后。", "example": null}, {"def": "②自豪祖国的～傲。值得～傲。", "example": null}, {"def": "骄xiāo 1.犬名。参见\\"歇骄\\"。", "example": null}, {"def": "骄qiáo 1.人名用字。春秋时陈有袁骄。见《公羊传．僖公四年》\\"何以不称使\\"唐陆德明释文。", "example": null}]','chinese-xinhua','0'),
('2101143296125440037','胶','1','jiāo','月','10',NULL,'[{"def": "胶〈名〉", "example": null}, {"def": "(形声。古代胶”用动物的皮煮制而成,所以从肉”。段玉裁说皮近肉,故字从肉。”本义粘性物质,用动物的皮角或树脂制成)", "example": null}, {"def": "同本义", "example": null}, {"def": "胶也者,以为和也。--《考工记·弓人》", "example": null}, {"def": "又如胶鳔(用鱼鳔煮治而成的胶);胶漆(胶与漆。比喻事物的结合非常紧密;或比喻交情深厚);胶青(胶清。已制成的色质纯正的胶质);胶革(用皮革熬成的胶)", "example": null}, {"def": "古代大学之称,后泛指学校", "example": null}, {"def": "鸡鸣声,泛指禽类鸣声", "example": null}, {"def": "胶（膠）jiāo", "example": null}, {"def": "⒈粘性物质。用动物皮、角或树脂等制成。也有人工合成的牛皮～。树脂～。万能～。", "example": null}, {"def": "⒉制成胶质的药品阿～。鹿角～。", "example": null}, {"def": "⒊特指橡胶～轮。～底鞋。", "example": null}, {"def": "⒋像胶那样有粘性的～泥。～水。", "example": null}, {"def": "⒌粘住，粘合～着。～合。", "example": null}, {"def": "⒍", "example": null}, {"def": "胶jiǎo 1.见\\"胶胶扰扰\\"。", "example": null}, {"def": "胶háo 1.戾。参见\\"胶加\\"﹑\\"胶戾\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296125440038','椒','1','jiāo','木','12',NULL,'[{"def": "椒〈名〉", "example": null}, {"def": "(形声。从木,叔声。本义花椒)", "example": null}, {"def": "同本义。芸香科植物", "example": null}, {"def": "焚椒兰也。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如椒科(泛指各种调味佐料);椒图(椒涂。神话传说中一种形似螺蚌的动物,性好闭口,古代常把它画在门上做装饰)", "example": null}, {"def": "辣椒", "example": null}, {"def": "椒jiāo植物名。", "example": null}, {"def": "①花椒，落叶灌木或小乔木，有刺。果实暗红色，种子黑色，调味或供药用。", "example": null}, {"def": "②胡椒，常绿藤本。果实红色，干后变黑色叫\\"黑胡椒\\"，去皮后白色叫\\"白胡椒\\"，调味或供药用。", "example": null}, {"def": "③", "example": null}]','chinese-xinhua','0'),
('2101143296125440039','焦','1','jiāo','灬','12',NULL,'[{"def": "焦〈动〉", "example": null}, {"def": "(会意。金文字形,上面是隹”,短尾鸟,下面是火”。把鸟放在火上烤。本义物经火烧而变黄或成炭)", "example": null}, {"def": "同本义", "example": null}, {"def": "焦,火所伤也。--《说文》", "example": null}, {"def": "焦,火烧黑也。--《玉篇》", "example": null}, {"def": "濡灸之举焦。--《礼记·内则》", "example": null}, {"def": "凡气因火变则为焦。--《素问》", "example": null}, {"def": "又如焦盆(焦杯。焚纸的火池);焦鎚(一种烤熟的饼食);焦尾(焦桐,焦尾瑟。东汉蔡邕用一端有焦痕的桐木所制的琴◇多指名贵的琴);焦霹雳(能对人畜、植物或建筑物造成", "example": null}, {"def": "很大桅的霹雷)", "example": null}, {"def": "干枯;枯焦", "example": null}, {"def": "五谷焦死。--《墨子·非攻下》", "example": null}, {"def": "又如焦芽(枯焦的", "example": null}, {"def": "焦jiāo", "example": null}, {"def": "⒈物体经火烧变成炭样饭～了。～头烂额（头被火烧成重伤。〈喻〉十分窘迫难堪）。", "example": null}, {"def": "⒉酥，脆～麻花，很好吃。〈喻〉极干这捆柴～干。", "example": null}, {"def": "⒊着急，忧虑，烦躁～急。～心。～虑。～躁。～灼。", "example": null}, {"def": "⒋功、热、能量等单位名称\\"焦耳\\"的简称，符号j。", "example": null}, {"def": "⒌", "example": null}, {"def": "焦qiáo 1.通\\"谯\\"。 2.通\\"憔\\"。参见\\"焦瘁\\"。 3.用同\\"瞧\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296125440040','焳','1','jiāo','','12',NULL,'[{"def": "焳jué", "example": null}, {"def": "⒈古同爝”。", "example": null}]','chinese-xinhua','0'),
('2101143296125440041','蛟','1','jiāo','虫','12',NULL,'[{"def": "蛟〈名〉", "example": null}, {"def": "(形声。从虫,交声。本义古代传说中能发水的一种龙)", "example": null}, {"def": "同本义", "example": null}, {"def": "蛟,龙之属也。池鱼,满三千六百,蛟来为之长,能率鱼飞置笱水中,即蛟去。--《说文》", "example": null}, {"def": "其中有虎蛟。注蛟似蛇四足,龙属。”", "example": null}, {"def": "母龙曰蛟。--《抱朴子》", "example": null}, {"def": "义兴水中有蛟。(蛟,这里指鼍,鳄一类的动物。)--《世说新语·自新》", "example": null}, {"def": "又如蛟虬(蛟与虬。虬古代传说中一种有角的小龙。亦泛指水族);蛟螭(蛟龙。螭传说为蛟龙之属的一种动物);蛟兕(蛟龙与兕牛)", "example": null}, {"def": "又有古书说是无角龙", "example": null}, {"def": "蛟,龙属。无角曰蛟。--《韵会》", "example": null}, {"def": "乘六蛟兮蜿蝉。╠", "example": null}, {"def": "蛟jiāo〈古〉传说中能发洪水的一种龙投水搏～。", "example": null}]','chinese-xinhua','0'),
('2101143296125440042','跤','1','jiāo','足','13',NULL,'[{"def": "跤〈名〉", "example": null}, {"def": "跟头。也写作交”", "example": null}, {"def": "跤jiāo跟斗跌～。", "example": null}]','chinese-xinhua','0'),
('2101143296125440043','僬','1','jiāo','亻','14',NULL,'[{"def": "僬〈名〉", "example": null}, {"def": "僬侥", "example": null}, {"def": "南方有焦侥人,长三尺,短之极,从人,尧声。--《说文》", "example": null}, {"def": "从中州以东,四十万里,得僬侥国。--《列子·汤问》", "example": null}, {"def": "有小人,名曰焦侥之国,几姓,嘉谷是食。--《山海经·大荒南经》", "example": null}, {"def": "僬jiāo", "example": null}, {"def": "僬jiào 1.见\\"僬僬\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296125440044','艽','1','jiāo','艹','5',NULL,'[{"def": "艽--秦艽”草名。龙胆科。多年生草本,根入药", "example": null}, {"def": "艽jiāo", "example": null}, {"def": "艽qiú 1.荒远。参见\\"艽野\\"。 2.禽兽巢穴中的荐草。", "example": null}]','chinese-xinhua','0'),
('2101143296125440045','交','1','jiāo','亠','6',NULL,'[{"def": "交", "example": null}, {"def": "(象形。小篆字形,象人两腿交叉形。本义交叉)", "example": null}, {"def": "脚胫相交", "example": null}, {"def": "交,交胫也。--《说文》", "example": null}, {"def": "交足而待。--《战国策·秦策》", "example": null}, {"def": "雕题交趾。--《礼记·王制》", "example": null}, {"def": "又如交趾(古郡名『置,地处五岭以南一带。相传这里的人入睡时,两足相交)", "example": null}, {"def": "交叉;交错,错杂", "example": null}, {"def": "交臂厯指。--《庄子·天地》", "example": null}, {"def": "交韔二弓。--《诗·秦风·小戎》", "example": null}, {"def": "又如交裆(裤裆处);交拐(拐弯走);交戟(执戟相交);交牙(如犬牙相交叉);交歧(交错的路径)", "example": null}, {"def": "结交; 交往", "example": null}, {"def": "交游士林。--《资治通鉴》", "example": null}, {"def": "又如交友(结交朋友);交礼(交往的礼节);", "example": null}, {"def": "交jiāo", "example": null}, {"def": "⒈付给，付托～付。～任务。～货。", "example": null}, {"def": "⒉互相，相互关联～换。～流。～际。～往。～易。～涉。", "example": null}, {"def": "⒊一齐，同时惊喜～加。贫困～迫。", "example": null}, {"def": "⒋友谊，情谊～谊。～情。", "example": null}, {"def": "⒌结好～友。结～。", "example": null}, {"def": "⒍相连，相错，交叉～界。～织。犬牙～错。 〈引〉 接触～兵（打仗）。～战。", "example": null}, {"def": "⒎跟斗跌～。", "example": null}, {"def": "⒏", "example": null}, {"def": "①各种运输与邮电通讯事业的总称。", "example": null}, {"def": "②往来通达。", "example": null}, {"def": "③特指交通员。抗日战争及解放战争时期做通信联络工作的人员。", "example": null}, {"def": "⒐", "example": null}, {"def": "①将经手的事务移交给接替的人她已办好～代工作。", "example": null}, {"def": "②也作\\"交待\\"。将事情或意见向有关人员说清楚～代政策。～待问题。", "example": null}, {"def": "③嘱咐～代注意事项。", "example": null}]','chinese-xinhua','0'),
('2101143296125440046','郊','1','jiāo','阝','8',NULL,'[{"def": "郊〈名〉", "example": null}, {"def": "(形声。从邑,交声。从邑”,表示与城郭、行政区域有关。本义上古时代国都外百里以内的地区称郊”)", "example": null}, {"def": "郊区", "example": null}, {"def": "郊,距国百里为郊。--《说文》。按,周时距离国都五十里的地方叫近郊,百里的地方叫远郊。", "example": null}, {"def": "适彼乐郊。--《诗·魏风·硕鼠》", "example": null}, {"def": "素服郊次。--《左传·僖公三十二年》", "example": null}, {"def": "洒江郊。--唐·杜甫《茅屋为秋风所破歌》", "example": null}, {"def": "始知郊田。--明·袁宏道《满井游记》", "example": null}, {"def": "邑外谓之郊。--《尔雅·释地》", "example": null}, {"def": "郊二旬。--《周礼·质人》。注远郊也。”", "example": null}, {"def": "至于郊。--《仪礼·觐礼》。注谓近郊。”", "example": null}, {"def": "又如郊祀(古时帝", "example": null}, {"def": "郊jiāo城外，市区外东～。～区。出城～游。", "example": null}]','chinese-xinhua','0'),
('2101143296125440047','姣','1','jiāo','女','9',NULL,'[{"def": "姣〈形〉", "example": null}, {"def": "(形声。从女,交声。本义修长美丽)", "example": null}, {"def": "同本义", "example": null}, {"def": "姣,好也。--《说文》。段玉裁注姣谓容体壮大之好也。”徐灏笺凡从交声之字其义多为长…壮佼亦谓其壮而高长,非谓大也。”", "example": null}, {"def": "弃位而姣,不可为贞。--《左传·襄公九年》", "example": null}, {"def": "灵偃蹇兮姣服。--《楚辞·东方太一》", "example": null}, {"def": "古者桀纣长巨姣美,天下之杰也。--《荀子·非相》", "example": null}, {"def": "前有楼阙轩辕,后有长姣美人。--《史记》", "example": null}, {"def": "容貌美好的", "example": null}, {"def": "娇丽施只。--《大招》", "example": null}, {"def": "公姣且丽。--《吕氏春秋·达郁》", "example": null}, {"def": "左右言其姣好。--《汉书·东方朔传》。注美丽也。”", "example": null}, {"def": "又如姣艳(美", "example": null}, {"def": "姣jiāo美好～容。男女～服（服衣服）。", "example": null}, {"def": "姣xiáo 1.淫乱。", "example": null}]','chinese-xinhua','0'),
('2101143296125440048','娇','1','jiāo','女','9',NULL,'[{"def": "娇〈形〉", "example": null}, {"def": "(形声。从女,乔声。本义妩媚可爱)", "example": null}, {"def": "同本义(柔嫩美态)", "example": null}, {"def": "娇,姿也。--《说文新附》", "example": null}, {"def": "娇,女字,亦态。--《广韵》", "example": null}, {"def": "娇,娇姿也。--《玉篇》", "example": null}, {"def": "娇逸未有婚。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "自在娇莺恰恰啼。--唐·杜甫《江畔独步寻花》", "example": null}, {"def": "娇儿恶卧踏里裂。--唐·杜甫《茅屋为秋风所破歌》", "example": null}, {"def": "娇姿欲滴。--明·李渔《闲情偶寄·种植部》", "example": null}, {"def": "又如娇影(娇美动人的影子);娇娇痴痴(故作娇痴之态);娇婢侈童(娇贵奢侈的婢女童仆);娇羞(妩媚含羞的样子);娇娥(美丽的妇女);娇逸(俊美飘逸);娇颜(美丽的容貌);娇冶", "example": null}, {"def": "(艳", "example": null}, {"def": "娇（嬌）jiāo", "example": null}, {"def": "⒈美好可爱万紫千红分外～。", "example": null}, {"def": "⒉柔嫩，怕苦怕累～嫩。～气。", "example": null}, {"def": "⒊宠爱～惯。～生惯养。", "example": null}]','chinese-xinhua','0'),
