('2101143296125440075','诘','1','jié','讠','8',NULL,'[{"def": "诘  jie", "example": null}, {"def": "(形声。从言,吉声。本义询问,追问)", "example": null}, {"def": "同本义", "example": null}, {"def": "诘,问也。--《说文》", "example": null}, {"def": "度作刑以诘四方。--《书·吕刑》", "example": null}, {"def": "五曰刑典以诘邦国。--《周礼·大宰》", "example": null}, {"def": "毅诘之曰。--唐·李朝威《柳毅传》", "example": null}, {"def": "直诘袁曰。--清·梁启超《谭嗣同传》", "example": null}, {"def": "终不敢诘。--清·方苞《狱中杂记》", "example": null}, {"def": "又如反诘(反问);究诘(追问究竟);诘询(追问,询问);诘辩(刨根问底)", "example": null}, {"def": "责备;质问", "example": null}, {"def": "诘,责也。--《广雅》", "example": null}, {"def": "诘奸慝。--《左传·昭公十四年》", "example": null}, {"def": "仲冬之月…农有不收藏积聚者,马牛畜兽有", "example": null}, {"def": "诘jié", "example": null}, {"def": "⒈盘问，追问盘～。反～。〈引〉查，查办～查。～诛慢暴（慢怠慢）。", "example": null}, {"def": "⒉见jí。", "example": null}, {"def": "诘jí", "example": null}]','chinese-xinhua','0'),
('2101143296125440076','拮','1','jié','扌','9',NULL,'[{"def": "拮", "example": null}, {"def": "同揭”。向上举", "example": null}, {"def": "揭,举也。或作拮。--《集韵》", "example": null}, {"def": "拮据", "example": null}, {"def": "予手拮据。--《诗·豳风·鸱鸮》", "example": null}, {"def": "后比喻经济窘迫", "example": null}, {"def": "近来国家被抄以后,诸事运用不来,也是每形拮据。--《红楼梦》", "example": null}, {"def": "手头拮据", "example": null}, {"def": "拮抗", "example": null}, {"def": "拮抗药", "example": null}, {"def": "拮jié", "example": null}, {"def": "①操作劳苦。", "example": null}, {"def": "②困窘，经济情况不好正在～据之时。", "example": null}, {"def": "拮jiá 1.击，逼。", "example": null}]','chinese-xinhua','0'),
('2101143296125440077','洁','1','jié','氵','9',NULL,'[{"def": "洁", "example": null}, {"def": "(形声。从水,絜声。本义干净,清洁。按洁”和潔”本是不同的两个字。洁”是河流名,后来成为潔”的俗字,现在是潔”的简化字)", "example": null}, {"def": "同本义", "example": null}, {"def": "鲜而不垢,洁也。--《管子·水地》", "example": null}, {"def": "姑洗所以脩洁百物。--《国语·周语》", "example": null}, {"def": "直哉维静絜。--《史记·五帝纪》", "example": null}, {"def": "为人洁白皙。--《乐府诗集·陌上桑》", "example": null}, {"def": "又如整洁(整齐清洁);清洁(没有尘土,油垢等);洁癖(过分爱清洁的癖性);洁疾(过分爱清洁的特殊行为);洁粢(洁净的黍稷。粢供祭祀的谷类)", "example": null}, {"def": "操行清白,品德高尚", "example": null}, {"def": "联幼清以廉洁兮。--《楚辞·招魂》", "example": null}, {"def": "以著其洁", "example": null}, {"def": "洁（潔）jié干净清～。整～。～白无瑕。〈喻〉不贪污，品德好，作风正派纯～无私。勤政廉～。", "example": null}]','chinese-xinhua','0'),
('2101143296125440078','结','1','jié','纟','9',NULL,'[{"def": "结", "example": null}, {"def": "植物生长果实", "example": null}, {"def": "结", "example": null}, {"def": "坚硬;牢固", "example": null}, {"def": "健壮", "example": null}, {"def": "结", "example": null}, {"def": "用绳、线、皮条等绾成的疙瘩", "example": null}, {"def": "旧时向官府承担责任或承认了结的书面的字据", "example": null}, {"def": "关键", "example": null}, {"def": "诚信者,天下之结也。--《管子》", "example": null}, {"def": "被联结的状态", "example": null}, {"def": "通髻”。总发,挽发而结之于顶", "example": null}, {"def": "激楚之结,独秀先些。--《楚辞", "example": null}, {"def": "结jié", "example": null}, {"def": "⒈系，编织，扎缚打～。～绳。～毛衣。张灯～彩。〈引〉问题所在处症～。又指编结成的东西活～←蝶～。", "example": null}, {"def": "⒉聚，凝聚水已～冰。～晶体。", "example": null}, {"def": "⒊合，联合～合。～社。～交。", "example": null}, {"def": "⒋了毕，收束～业。～束。～账。", "example": null}, {"def": "⒌作为保证的一种字据具～。", "example": null}, {"def": "⒍搭，构建～庐在人境（庐房子。人境人间）。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "①各个组成部分的相互排列搭配 文章～构。经济～构。", "example": null}, {"def": "②建筑物上承担重力的构造砖木～构。", "example": null}, {"def": "③内部构造组织～构。机器～构。", "example": null}, {"def": "⒑", "example": null}, {"def": "⒒", "example": null}, {"def": "①植物长成所结的果实。", "example": null}, {"def": "②事情的终了或发展到一定阶段那件事已有了～果。", "example": null}, {"def": "③旧小说中指将人杀死～果了那厮的性命。", "example": null}, {"def": "⒓", "example": null}, {"def": "⒔见jiē。", "example": null}, {"def": "结jiē", "example": null}, {"def": "⒈植物长果实或种子这棵梨树，今年刚～果。", "example": null}, {"def": "⒉", "example": null}, {"def": "①植物长果实或种子。", "example": null}, {"def": "②坚固，牢靠这堵墙挺～实。", "example": null}, {"def": "③健壮他虽老，但身体很～实。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋见jié。", "example": null}, {"def": "结成。\\"执雠\\"。", "example": null}, {"def": "⑾ 朋友;至交。", "example": null}, {"def": "⑿殷代的世家大族。", "example": null}, {"def": "⒀通\\"墊\\"。陷下。姓。殷祖己之后迁于挚，分为挚执二姓。《随巢子》有执无鬼。", "example": null}, {"def": "结jì 1.发髻。", "example": null}]','chinese-xinhua','0'),
