('2101143296129634343','晋','1','jìn','日','10',NULL,'[{"def": "晋", "example": null}, {"def": "(会意。小篆字形,从日。指追着太阳一直前进。本义上进)", "example": null}, {"def": "进", "example": null}, {"def": "晉,进也。日出,万物进。--《说文》", "example": null}, {"def": "晋者,进也。--《易·序卦》", "example": null}, {"def": "王提马而走诸侯晋。--《周礼·田仆》", "example": null}, {"def": "盍孟晋以迨群兮。(盍为什么不;孟,勉力;迨,赶上;群大家。)--班固《幽通赋》", "example": null}, {"def": "又如晋谒(晋见;谒见);晋接(进见;接见);晋食(进献食品)", "example": null}, {"def": "晋升。提高地位、级别或荣誉", "example": null}, {"def": "以功晋知府。--《清史稿·桂中行传》", "example": null}, {"def": "晋封英王。--《陈玉成》", "example": null}, {"def": "又如晋封(晋升加封);晋秩(晋升官职或等级);晋阶(升级);晋号(晋升其称号)", "example": null}, {"def": "低,俯", "example": null}, {"def": "见梓晋然实而俯", "example": null}, {"def": "晋（晉）jìn", "example": null}, {"def": "⒈进，升，向前～见。～升。～级。", "example": null}, {"def": "⒉〈古〉通\\"搢\\"。插。", "example": null}, {"def": "⒊周代诸侯国名，疆域大部分在今山西省。", "example": null}, {"def": "⒋朝代名", "example": null}, {"def": "①晋朝（西晋、东晋），公元265-420年。司马炎灭魏后建立。", "example": null}, {"def": "②后晋，五代之一。公元936-946年。第一代君主是石敬塘。", "example": null}, {"def": "⒌山西省的简称。", "example": null}]','chinese-xinhua','0'),
('2101143296129634344','浸','1','jìn','氵','10',NULL,'[{"def": "浸", "example": null}, {"def": "(形声。从水,籀文寝声。本义古水名。浸水) 同本义", "example": null}, {"def": "浸,浸水也。出魏郡武安东北,入呼沱水。--《说文》。朱骏声按,出今河南彰德府武安县,入虖沱河。", "example": null}, {"def": "又如巨浸(大湖)", "example": null}, {"def": "浸", "example": null}, {"def": "泡在水里,被水渗入", "example": null}, {"def": "冽彼下泉,浸彼苞稂。--《诗·曹风·下泉》", "example": null}, {"def": "其浸五湖。--《周礼·职方氏》", "example": null}, {"def": "浸渊之草。--《吕氏春秋·木味》", "example": null}, {"def": "又如浸淬(把金属工件烧红,然后浸入水中急速冷却,以增加其硬度或改变其物理、化学性能);浸蚀(因液体浸泡而腐蚀或损伤);浸濡(因受水渍而湿透)", "example": null}, {"def": "灌溉", "example": null}, {"def": "一日浸百畦。--《", "example": null}, {"def": "浸jìn", "example": null}, {"def": "⒈泡，使渗入，使渗透～泡。～入。～透。～稻种。", "example": null}, {"def": "⒉逐渐～渐。～染。来往～密。", "example": null}, {"def": "浸qīn 1.见\\"浸淫\\"﹑\\"浸寻\\"﹑\\"浸浔\\"。 2.同\\"侵\\"。触犯;冒犯。 3.同\\"侵\\"。侵犯。参见\\"浸凌\\"。 4.同\\"侵\\"。侵占。参见\\"浸渔\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296129634345','烬','1','jìn','火','10',NULL,'[{"def": "烬", "example": null}, {"def": "(形声。从火,尽声。本义物体燃烧后的剩余)", "example": null}, {"def": "同本义", "example": null}, {"def": "请收合余烬。--《左传·成公二年》", "example": null}, {"def": "烛烬夜有数升。--《北史·吕思礼传》", "example": null}, {"def": "又如灰烬;余烬;烬灰(灰烬);烬骨(骨灰)", "example": null}, {"def": "残余、剩余或残迹", "example": null}, {"def": "民靡有黎,具祸以烬。--《诗·大雅·桑柔》", "example": null}, {"def": "烬", "example": null}, {"def": "烧毁;化成灰烬", "example": null}, {"def": "烬（燼）jìn", "example": null}, {"def": "⒈火烧物体之后剩下的东西灰～。烛～。", "example": null}, {"def": "⒉灾余。", "example": null}]','chinese-xinhua','0'),
('2101143296129634346','赆','1','jìn','贝','10',NULL,'[{"def": "赆", "example": null}, {"def": "临别时赠与、赠送或馈赠的财物", "example": null}, {"def": "赆送一无所取。--《梁书·杨公则传》", "example": null}, {"def": "又如赆礼(临别时赠送的财物,送行的路费或礼品);赆仪程仪(赆礼);赆赙之仪(赠送给上路或办丧事用的钱物。赙用钱财资助人办丧事)", "example": null}, {"def": "进贡的财物", "example": null}, {"def": "赆", "example": null}, {"def": "尽;全部", "example": null}, {"def": "遂将此诗赆看,不觉天明。--清·崔象川《白圭志》", "example": null}, {"def": "赆行", "example": null}, {"def": "赆仪", "example": null}, {"def": "赆（赽）jìn", "example": null}, {"def": "⒈临别时赠送的路费或财物～送。", "example": null}, {"def": "⒉进贡的财物纳～。", "example": null}]','chinese-xinhua','0'),
