('2101143296129634363','尽','1','jìn','尸','6',NULL,'[{"def": "尽〈副〉", "example": null}, {"def": "(尽为儘”和眒”的简化字)", "example": null}, {"def": "尽量,尽可能", "example": null}, {"def": "意思同最”,用在方位词的前面", "example": null}, {"def": "老是;总", "example": null}, {"def": "尽 〈动〉", "example": null}, {"def": "表示以某个范围为界限,不得超过", "example": null}, {"def": "让先", "example": null}, {"def": "任凭,纵使", "example": null}, {"def": "惟有落红不禁,尽教飞舞出宫墙。╠", "example": null}, {"def": "尽（俠、儘）jǐn", "example": null}, {"def": "⒈力所能及的限度～力。～量。", "example": null}, {"def": "⒉放在最先住房先～着分给教师。", "example": null}, {"def": "⒊任凭～你挑选。", "example": null}, {"def": "⒋极，最～前头。～下面。～先考虑。", "example": null}, {"def": "⒌老是，只管这几天～是晴天。", "example": null}, {"def": "⒍", "example": null}, {"def": "①纵然，即使～管如此。", "example": null}, {"def": "②只管，不必考虑的你～管放心。", "example": null}, {"def": "尽（眒）jìn", "example": null}, {"def": "⒈完无穷无～。取之不～。", "example": null}, {"def": "⒉全部用出，竭力做到～心竭力。～力而为。～职～责。～情欢唱。各～所能。", "example": null}, {"def": "⒊达到顶点已到～头。～善～美。", "example": null}, {"def": "⒋都，全部～人皆知。满城～带黄金甲。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍见jǐn。", "example": null}]','chinese-xinhua','0'),
('2101143296129634364','劲','1','jìn','力','7',NULL,'[{"def": "劲", "example": null}, {"def": "(形声。从力,坙声。①本义强劲有力。②力气)", "example": null}, {"def": "力量,力气", "example": null}, {"def": "精神;情绪", "example": null}, {"def": "神情;态度", "example": null}, {"def": "趣味;兴趣", "example": null}, {"def": "指某种程度,限度", "example": null}, {"def": "劲（勁）jìng", "example": null}, {"def": "⒈正直，挺拔，坚强有力～士。～松。～草。良将～旅。", "example": null}, {"def": "⒉见jiny。", "example": null}, {"def": "劲（勁）jìn", "example": null}, {"def": "⒈力气，力量使～。用～。〈引〉", "example": null}, {"def": "①精神、情绪、兴趣等干～。闯～。有～头。", "example": null}, {"def": "②指属性的程度你尝尝这个香～儿。这菜有点辣～儿。", "example": null}, {"def": "⒉见jìng。", "example": null}]','chinese-xinhua','0'),
('2101143296129634365','妗','1','jìn','女','7',NULL,'[{"def": "妗", "example": null}, {"def": "舅母。舅父的妻子", "example": null}, {"def": "儿少受舅妗抚育,尚无寸报。--《聊斋志异·公孙九娘》", "example": null}, {"def": "又如舅妗;妗娘(妗子,舅母);妗妗(妗子,舅母);妗奶奶(对父辈舅母的称呼);妗婆(父亲或母亲的舅母,即舅婆)", "example": null}, {"def": "妻兄妻弟的妻子", "example": null}, {"def": "妗子", "example": null}, {"def": "大妗子", "example": null}, {"def": "小妗子", "example": null}, {"def": "妗jìn", "example": null}, {"def": "⒈舅母。", "example": null}, {"def": "⒉妻兄、妻弟的妻子二～子。么～子。", "example": null}, {"def": "妗xiān 1.见\\"礞\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296129634366','近','1','jìn','辶','7',NULL,'[{"def": "近", "example": null}, {"def": "(形声。从辵,表示与行走有关,斤声。本义走近,接近)", "example": null}, {"def": "同本义", "example": null}, {"def": "近,附也。--《说文》", "example": null}, {"def": "为其近于道也。--《礼记·祭义》", "example": null}, {"def": "小大近丧。--《诗·大雅·荡》", "example": null}, {"def": "吾入关,秋毫不敢有所近。--《史记·项羽本纪》", "example": null}, {"def": "稍出近之。--唐·柳宗元《三戒》", "example": null}, {"def": "近出前后。", "example": null}, {"def": "稍近。", "example": null}, {"def": "时敌军已近寨。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如逼近(靠近;接近);挨近;近傍(接近;靠近);近晚(傍晚);近火(靠近火)", "example": null}, {"def": "引申追求,希求", "example": null}, {"def": "为近利市三倍。--《易·说卦》", "example": null}, {"def": "又如近名(追求名誉);近利(逐利)", "example": null}, {"def": "逼近", "example": null}, {"def": "近jìn", "example": null}, {"def": "⒈近，跟\\"远\\"相对～在咫尺。～几年来。～在眉睫。", "example": null}, {"def": "⒉关系密切，亲密，接近亲～。～亲。～朱者赤。～墨者黑。", "example": null}, {"def": "⒊相似，差不多太～似。性相～。年～八旬。", "example": null}, {"def": "⒋浅近，简单言～旨远。语言俚～（俚粗俗）。", "example": null}]','chinese-xinhua','0'),
('2101143296129634367','进','1','jìn','辶','7',NULL,'[{"def": "进", "example": null}, {"def": "(会意。甲骨文字形,上面是隹”,象小鸟形,下面是止”(趾)。鸟脚只能前进不能后退,故用以表示前进。本义前进,与退”相对)", "example": null}, {"def": "同本义", "example": null}, {"def": "进,登也。--《说文》", "example": null}, {"def": "巽为进退。--《易·说卦》", "example": null}, {"def": "进退维谷。--《诗·大雅·桑葇》", "example": null}, {"def": "徒衔枚而进。--《周礼·大司马》", "example": null}, {"def": "君子三揖而进。--《礼记·表记》", "example": null}, {"def": "进则引之,退则策之。--《韩非子·外储说右下》", "example": null}, {"def": "进兵击秦军。--《史记·魏公子列传》", "example": null}, {"def": "以次俱进。--《资治通鉴》", "example": null}, {"def": "水陆并进。", "example": null}, {"def": "贼环而进。--明·魏禧《大铁椎传》", "example": null}, {"def": "猱进鸷击。--清·徐珂《清稗类钞", "example": null}, {"def": "进（適）jìn", "example": null}, {"def": "⒈向前，跟\\"退\\"相对跃～。向前～。勇者不得独～。", "example": null}, {"def": "⒉入，到里面去～门。～厂。～中学。", "example": null}, {"def": "⒊收入或买入～钱。～衣服。", "example": null}, {"def": "⒋向上移动更～一层楼。", "example": null}, {"def": "⒌送上，奉呈～献。～酒。～言。～谏。", "example": null}, {"def": "⒍推荐，吸取荐～。引～。吸～。", "example": null}, {"def": "⒎旧时房院前后的层次，每一个院叫\\"一进\\"这座房屋是三～院子。", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "①向前发展，比原来好他已有很大的～步。", "example": null}, {"def": "②适应时代的要求，对社会发展起促进作用的～步思想。", "example": null}, {"def": "⒑", "example": null}, {"def": "⒈闭口，不说话～若寒蝉。〈引〉关闭～门。", "example": null}, {"def": "⒉因寒冷而哆嗦打寒～。", "example": null}]','chinese-xinhua','0'),
