('2101143296129634397','襟','1','jīn','衤','18',NULL,'[{"def": "襟〈名〉", "example": null}, {"def": "(形声。从衣,禁声。本义古代指衣的交领)", "example": null}, {"def": "同本义◇指衣的前幅。", "example": null}, {"def": "泣下沾襟。--宋·欧阳修《新五代史·伶官传》", "example": null}, {"def": "又如襟袂(襟袖。衣襟和衣袖);襟带(衣襟和腰带);襟卫(襟带周卫);襟子(衣襟);襟儿(衣襟)", "example": null}, {"def": "连襟的省称。本人与妻子的兄弟或姐妹的夫婿间的关系或两婿相称", "example": null}, {"def": "胸怀", "example": null}, {"def": "前面", "example": null}, {"def": "古衣襟左右相交,因用以比喻地势的交会扼要", "example": null}, {"def": "襟jīn", "example": null}, {"def": "⒈衣服胸前的部分大～。对～。底～。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296129634398','巾','1','jīn','巾','3',NULL,'[{"def": "巾", "example": null}, {"def": "(象形。甲骨文字形,象布巾下垂之形。本义佩巾,拭布,相当于现在的手巾)", "example": null}, {"def": "同本义", "example": null}, {"def": "巾,佩巾也。--《说文》", "example": null}, {"def": "沐巾一。--《仪礼·士冠礼》", "example": null}, {"def": "盥卒授巾。--《礼记·内则》", "example": null}, {"def": "布巾环幅不凿。--《仪礼·士丧礼》", "example": null}, {"def": "静其巾幂。--《仪礼·特牲馈食礼》", "example": null}, {"def": "儿女共沾巾。--《战国策·魏策》", "example": null}, {"def": "归来泪满巾。--宋·张俞《蚕妇》", "example": null}, {"def": "巾短情长。--清·林觉民《与妻书》", "example": null}, {"def": "又如花巾;小丝巾;巾栉(梳洗用品,即手巾和梳子;梳洗打扮);巾帚(拭巾和扫帚);巾帨(毛巾)", "example": null}, {"def": "缠束或覆盖用的织物", "example": null}, {"def": "巾袖无光。--唐·李朝威《柳毅", "example": null}, {"def": "巾jīn用于擦、抹、包裹、覆盖等的纺织物手～。抹桌～。头～。枕～。围～。", "example": null}]','chinese-xinhua','0'),
('2101143296129634399','今','1','jīn','人','4',NULL,'[{"def": "今", "example": null}, {"def": "(会意。从佶亼。本义现在)", "example": null}, {"def": "同本义", "example": null}, {"def": "今,是时也。--《说文》", "example": null}, {"def": "今,时辞也。--《苍颉篇》", "example": null}, {"def": "迨其今兮。--《诗·召南·摽有梅》", "example": null}, {"def": "于今三年。--《诗·豳风·东山》", "example": null}, {"def": "吾今召君矣。--《史记·汲郑传》", "example": null}, {"def": "今行而无信,则秦未可亲也。--《战国策·燕策》", "example": null}, {"def": "今乃于毛先生而失之也。--《史记·平原君虞卿列传》", "example": null}, {"def": "今其室十无一焉。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "今之高爵显位。--明·张溥《五人墓碑记》", "example": null}, {"def": "今年四月。(指清朝光绪二十四年(1898年),即戊戌年。四月,旧历。公历是六月。)--清·梁启超《谭嗣同传》", "example": null}, {"def": "又如今", "example": null}, {"def": "今jīn现在，现代，跟\\"古\\"相对～时。～日。～年。从～天起。古为～用。～昔对比。～非昔比。", "example": null}]','chinese-xinhua','0'),
('2101143296129634400','斤','1','jīn','斤','4',NULL,'[{"def": "斤〈名〉", "example": null}, {"def": "(象形。甲骨文字形,上面是横刃,下为曲柄,象斧斤形。本义斧子一类的工具)", "example": null}, {"def": "同本义", "example": null}, {"def": "今,斫木斧也。--《说文》。段注凡斫物者皆曰斧,斫木之斧,则谓之斤。”", "example": null}, {"def": "于是乎丌鈟锯制焉。以鈟为之。--《庄子·在宥》", "example": null}, {"def": "皆执利兵,无者执斤。--《左传·哀公二十五年》", "example": null}, {"def": "不夭斤斧。--《庄子·逍遥游》", "example": null}, {"def": "以斧斤考击而求之。--宋· 苏轼《石钟山记》", "example": null}, {"def": "又如斤斧(斧头);斤墨(斧头与墨斗);斤凿(斧头与凿子)", "example": null}, {"def": "古代一种似锄但比锄小的农具", "example": null}, {"def": "恶金以铸锄、夷、斤…--《国语》", "example": null}, {"def": "斤〈动", "example": null}, {"def": "斤（觔）jīn", "example": null}, {"def": "⒈重量单位市制一～为十两（旧制一斤为十六两），两斤等于一公斤。\\"觔\\"另见筋（觔）。", "example": null}, {"def": "⒉〈古〉斧子一类的工具。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
