('2101143296129634411','俓','1','jínɡ','亻','9',NULL,'[{"def": "古同径”，小路。", "example": null}, {"def": "经过。", "example": null}, {"def": "水的直波。", "example": null}, {"def": "直；直径。", "example": null}, {"def": "坚。", "example": null}, {"def": "俓jìng 1.经过，越过。 2.直;直接。", "example": null}]','chinese-xinhua','0'),
('2101143296129634412','浄','1','jìnɡ','','8',NULL,'[{"def": "浄jìng 1.干净;清洁。亦用于形容抽象事物。 2.指明净。 3.洗净。 4.净尽，无馀。 5.指扫除净尽。 6.指男子去掉生殖功能。 7.纯，纯粹。 8.用同\\"静\\"。宁静;", "example": null}, {"def": "寂静。 9.副词。单，光。 10.副词。全;都。 11.佛教语。清静。 12.指戒律。 13.戏曲角色。俗称\\"花脸\\"﹑\\"花面\\"。扮演性格﹑品质或像貌上有特异之点的男性人物", "example": null}, {"def": "。如张飞﹑鲁智深﹑曹操﹑严嵩等。", "example": null}]','chinese-xinhua','0'),
('2101143296129634413','胫','1','jìnɡ','月','9',NULL,'[{"def": "胫", "example": null}, {"def": "(形声。从肉,巠声。本义小腿)", "example": null}, {"def": "同本义", "example": null}, {"def": "胫,胻也。--《说文》", "example": null}, {"def": "以杖叩其胫。--《论语》。皇疏脚胫也。膝上曰股,膝下曰胫。”", "example": null}, {"def": "有赤胫之民。--《山海经·海内经》", "example": null}, {"def": "闻苦脚胫寒泄。--《汉书·赵充国传》", "example": null}, {"def": "析才士之胫。--《淮南子·俶真》", "example": null}, {"def": "又如胫无毛(形容奔走辛劳之甚);胫大于股(言本小末大。旧时喻臣下的力量大于君上);胫衣(套裤)", "example": null}, {"def": "泛指人或禽兽的腿", "example": null}, {"def": "方首,长胫,意似良。(胫,人的小腿,也指禽兽昆虫的腿,这里指蟋蟀的腿。)--《聊斋志异·促织》", "example": null}, {"def": "又如胫毛(谓物之细微者。犹言一丝一毫,多指个人得失)", "example": null}, {"def": "小", "example": null}, {"def": "胫（脛、踲）jìng", "example": null}, {"def": "⒈小腿，自膝盖到脚跟的部分。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296129634414','痉','1','jìnɡ','疒','10',NULL,'[{"def": "痉", "example": null}, {"def": "风强病。也称痉挛”", "example": null}, {"def": "痉,彊急也。--《说文》", "example": null}, {"def": "又如痉风(痉挛,风病);痉病(风强病,痉挛)", "example": null}, {"def": "痉挛", "example": null}, {"def": "痉笑", "example": null}, {"def": "痉(痙)jìng痉挛，俗称\\"抽筋\\"。肌肉不自主的收缩运动膈～挛（呃逆）。肠～挛（肠绞痛）。手足～挛。", "example": null}]','chinese-xinhua','0'),
('2101143296129634415','竞','1','jìnɡ','立','10',NULL,'[{"def": "竞", "example": null}, {"def": "(会意。甲骨文字形,象二人竞逐。本义争竞;角逐;比赛)", "example": null}, {"def": "同本义", "example": null}, {"def": "競,逐也。--《说文》", "example": null}, {"def": "职竞用力。--《诗·大雅·桑柔》", "example": null}, {"def": "犹不能与罗者竞多。--《淮南子·原道》", "example": null}, {"def": "相与优游,竞畅于宇宙之间。--《淮南子·俶真》", "example": null}, {"def": "竞于道德。--《韩非子·五蠹》", "example": null}, {"def": "负势竞上。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "物竞之无所争。--", "example": null}, {"def": "而与之竞火器。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如竞进(争逐拥进);竞斗(争斗,打斗);竞心(争强好胜之心);竞逐(角逐,竞争);竞爽(争胜,争强)", "example": null}, {"def": "争辩", "example": null}, {"def": "竞（競）jìng", "example": null}, {"def": "⒈争逐，比赛，互相争胜～走。～赛。～争。", "example": null}, {"def": "⒉强劲南风不～。", "example": null}]','chinese-xinhua','0'),
('2101143296129634416','逕','1','jìnɡ','','10',NULL,'[{"def": "逕jìng", "example": null}, {"def": "⒈小路山～。曲～。〈引〉取道，经过夜～泽中。〈喻〉达到目的之方法找门～。取捷～。", "example": null}, {"def": "⒉直往，直接，直截了当～往。～自去。～向对方联系。", "example": null}]','chinese-xinhua','0'),
