('2101143296133828609','竟','1','jìnɡ','立','11',NULL,'[{"def": "竟", "example": null}, {"def": "(会意。从音,从人。本义奏乐完毕)", "example": null}, {"def": "同本义", "example": null}, {"def": "竟,乐曲尽为竟。--《说文》", "example": null}, {"def": "凡乐成则告备。--《周礼》『·郑玄注成,谓所奏一竟。”", "example": null}, {"def": "泛指结束,完毕", "example": null}, {"def": "竟,终也。--《玉篇》", "example": null}, {"def": "竟,穷也。--《广雅》", "example": null}, {"def": "谮始竟背。--《诗·大雅·瞻卬》。笺犹终也。”", "example": null}, {"def": "振于无竟。--《庄子·齐物论》", "example": null}, {"def": "秦王竟酒。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "语竟。--唐·李朝威《柳毅传》", "example": null}, {"def": "不能竟书而欲搁笔。--清·林觉民《与妻书》", "example": null}, {"def": "又如竟学(学完,学到底);未竟之业;事竟", "example": null}, {"def": "追究", "example": null}, {"def": "竟jìng", "example": null}, {"def": "⒈完毕，终了看书既～（既已经）。未～的事业。〈引〉终于，到底，终究毕～获胜。有志～成。究～有什么用？", "example": null}, {"def": "⒉整，从头至尾～天。～世。", "example": null}, {"def": "⒊居然，〈表〉未料想到～然。～会。～敢。", "example": null}]','chinese-xinhua','0'),
('2101143296133828610','竫','1','jìnɡ','','8',NULL,'[{"def": "竫jìng 1.静;安。 2.造作。参见\\"竫言\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296133828611','敬','1','jìnɡ','攵','12',NULL,'[{"def": "敬", "example": null}, {"def": "(会意。从攴,以手执杖或执鞭,表示敲打,从苟,有紧急、急迫之义。本义恭敬;端肃。恭在外表,敬存内心)", "example": null}, {"def": "同本义", "example": null}, {"def": "敬,肃也。--《说文》", "example": null}, {"def": "毋不敬何允。--《礼记·曲礼》。注在貌为恭,在心为敬。”", "example": null}, {"def": "宾客主恭,祭祀主敬。--《礼记·少仪》", "example": null}, {"def": "入门主敬,升堂主慎。--《仪礼·聘礼》", "example": null}, {"def": "敬德之聚也。--《左传·僖公二十三年》", "example": null}, {"def": "敬诺。--《战国策·赵策》", "example": null}, {"def": "敬受命。--《史记·陈涉世家》", "example": null}, {"def": "敬进如姬。--《史记·魏公子列传》", "example": null}, {"def": "敬闻命关。--唐·李朝威《柳毅传》", "example": null}, {"def": "又如敬让(恭敬谦让);敬诚缉熙(恭敬诚实而光明);", "example": null}, {"def": "敬jìng", "example": null}, {"def": "⒈尊重，热爱，仰慕，佩服尊～。～业。～爱。～仰。～慕。～佩。", "example": null}, {"def": "⒉以礼貌待人～客。～之有礼。", "example": null}, {"def": "⒊有礼貌的送上～献。～茶。恭～奉送。", "example": null}, {"def": "⒋〈表〉敬意的礼物喜～。", "example": null}, {"def": "⒌严肃，慎重～慎。～始而慎终。", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296133828612','傹','1','jìnɡ','','8',NULL,'[{"def": "傹jìng 1.强。 2.同\\"竟\\"。终。", "example": null}]','chinese-xinhua','0'),
('2101143296133828613','靖','1','jìnɡ','青','13',NULL,'[{"def": "靖", "example": null}, {"def": "(形声。从立,青声。本义立容安静)", "example": null}, {"def": "同本义", "example": null}, {"def": "靖,立竫也。--《说文》", "example": null}, {"def": "自作不靖。--《书·盘庚》", "example": null}, {"def": "靖共尔位。--《诗·小雅·小明》", "example": null}, {"def": "虎靖衡门。--《樊阳令杨君碑》", "example": null}, {"def": "靖以待命犹可,动必忧。--《左传·昭公二十五年》", "example": null}, {"def": "清靖而无私虑。--《淮南子·精神》", "example": null}, {"def": "清靖寡欲,与物无竞。--《北史·袁韦修传》", "example": null}, {"def": "既防溢而靖志兮,迨我暇以翱翔。--张衡《思玄赋》", "example": null}, {"def": "又如靖密(安静致密);靖冥(宁静幽深);靖默(沉静缄默);靖重(安祥凝重)", "example": null}, {"def": "安定;和平", "example": null}, {"def": "靖,安也。--《广雅》", "example": null}, {"def": "又如靖晏(平静安逸,太平无事", "example": null}, {"def": "靖jìng", "example": null}, {"def": "⒈平安，安静安～。", "example": null}, {"def": "⒉安定，平定～平。～乱。", "example": null}, {"def": "⒊恭敬。", "example": null}]','chinese-xinhua','0'),
('2101143296133828614','境','1','jìnɡ','土','14',NULL,'[{"def": "境", "example": null}, {"def": "(形声。从土,竟声。本义边境,国境)", "example": null}, {"def": "同本义", "example": null}, {"def": "境,疆也。--《说文新附》", "example": null}, {"def": "至齐境。--《吕氏春秋·赞能》", "example": null}, {"def": "字本作竟”", "example": null}, {"def": "亡不越竟。--《左传·宣公二年》", "example": null}, {"def": "边竟有人焉。--《庄子·天道》", "example": null}, {"def": "其竟关之政尽察。--《荀子·富国》", "example": null}, {"def": "与燕王会境上。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "廉颇送至境。", "example": null}, {"def": "屯于境上。--《史记·魏公子列传》", "example": null}, {"def": "起视四境。--宋·苏洵《权书·六国论》", "example": null}, {"def": "又如出境(离开国境);入境(进入国境);境宇(国境,疆土);境人(境内之人;本地人);境头(结果;亦作景头”。神佛点化人制造的幻境);境土(疆域;领地)", "example": null}, {"def": "境jìng", "example": null}, {"def": "⒈边界，疆界边～。国～。出～。〈引〉地方，区域～内有石油。", "example": null}, {"def": "⒉境地，处境环～。佳～。危～。顺～。", "example": null}, {"def": "⒊", "example": null}, {"def": "①土地的界限。", "example": null}, {"def": "②事物所达到的程度或表现的情况思想～界。艺术～界。", "example": null}]','chinese-xinhua','0'),
('2101143296133828615','獍','1','jìnɡ','犭','14',NULL,'[{"def": "獍", "example": null}, {"def": "古书上说的一种像虎豹的兽,生下来就吃生它的母兽", "example": null}, {"def": "獍jìng〈古〉传说中的一种凶恶兽，形状像虎豹，生下来就吃生牠的母兽。", "example": null}]','chinese-xinhua','0'),
