('2101143296133828630','颈','1','jǐnɡ','页','11',NULL,'[{"def": "颈", "example": null}, {"def": "(形声。从刀,巠声。从页”,表示与头有关。本义颈项)", "example": null}, {"def": "同本义", "example": null}, {"def": "颈,头茎也。--《说文》", "example": null}, {"def": "小人莫不延颈举踵而愿曰。--《荀子·荣辱》", "example": null}, {"def": "譬之是犹欲寿而歾颈也。--《荀子·彊国》", "example": null}, {"def": "喜则交颈相靡。--《庄子·马蹄》", "example": null}, {"def": "折颈而死。--《韩非子·五蠹》", "example": null}, {"def": "颈血溅大王。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "伸颈,侧目。--《虞初新志·秋声诗自序》", "example": null}, {"def": "抚其颈曰。--清·梁启超《谭嗣同传》", "example": null}, {"def": "又如颈血(刎颈时流出的血。比喻不惜一死)", "example": null}, {"def": "器物像颈或部位相当于颈的部分", "example": null}, {"def": "脖子的前面部分", "example": null}, {"def": "颈（頸）jǐng", "example": null}, {"def": "⒈俗称\\"脖子\\"，头与躯干相连的部分引～高歌。", "example": null}, {"def": "⒉物体像颈的部分瓶～。", "example": null}, {"def": "颈gěng 1.见\\"脖颈\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296133828631','景','1','jǐnɡ','日','12',NULL,'[{"def": "景", "example": null}, {"def": "(形声。从日,京声。本义日光)", "example": null}, {"def": "同本义", "example": null}, {"def": "景,日光也。--《说文》", "example": null}, {"def": "浊明外景,清明内景。--《荀子·解蔽》", "example": null}, {"def": "四时和谓之景风。--《尔雅》", "example": null}, {"def": "南方景风。--《广雅》。按,犹日光风也。", "example": null}, {"def": "日出天而耀景。--江淹《别赋》", "example": null}, {"def": "朱光驰北陆,浮景忽西沈。--《文选·张载·七哀诗》", "example": null}, {"def": "流景曜之韡晔。--张衡《西京赋》", "example": null}, {"def": "景翳翳以将入。--晋·陶渊明《归去来兮辞》", "example": null}, {"def": "至若春和景明。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "又如景曜(光彩);景光(亮光);景焕(光彩照射);景辉(光辉)", "example": null}, {"def": "太阳", "example": null}, {"def": "景jǐng", "example": null}, {"def": "⒈日光耀～。", "example": null}, {"def": "⒉风光，风景～致。～色。佳～。美～。", "example": null}, {"def": "⒊状况，情况，景象盛～。情～。远～。背～。", "example": null}, {"def": "⒋敬慕，佩服～慕。～仰。", "example": null}, {"def": "⒌大～山与京（京高丘）。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐〈古〉通\\"影\\"。影子。", "example": null}, {"def": "景yǐng 1.后多作\\"影\\"。影子;阴影。《诗．墉风．二子乘舟》\\"二子乘舟，泛泛其景。\\"孔颖达疏\\"泛泛然见其影之去往而不碍。\\"一说，通\\"憬\\"。远行的样子。见清王引之《", "example": null}, {"def": "经义述闻．毛诗上》。", "example": null}]','chinese-xinhua','0'),
('2101143296133828632','儆','1','jǐnɡ','亻','14',NULL,'[{"def": "儆", "example": null}, {"def": "(形声。从人,敬声。本义警戒,戒备)", "example": null}, {"def": "同本义", "example": null}, {"def": "儆,戒也。--《说文》", "example": null}, {"def": "儆,备也。--《后汉书·东平宪王苍传》注", "example": null}, {"def": "使府人库人各儆其事。--《左传·昭公十八年》", "example": null}, {"def": "令司官、巷伯儆宫。--《左传·襄公九年》", "example": null}, {"def": "又如儆悟(儆醒。儆戒,醒悟);儆守(戒备防守);儆惧(戒惧;警惕和畏惧);儆懔(戒惧);儆戢(戒惧而有所收敛);儆儆(不安的样子);儆动(戒惧不安);儆畏(警惕和畏惧;戒惧)", "example": null}, {"def": "告诫;警告", "example": null}, {"def": "夜儆百工。--《国语·鲁语》", "example": null}, {"def": "乃儆公仲之行。--《战国策·韩策》", "example": null}, {"def": "所以儆人臣也。--《孔子家语·五仪》", "example": null}, {"def": "在军,无", "example": null}, {"def": "儆jǐng", "example": null}, {"def": "⒈警备，戒备～备。", "example": null}, {"def": "⒉告诫，警告杀一～百。～戒未然也（未然未发生的事）。", "example": null}, {"def": "⒊紧急情状或消息～备。～报。火～。告～。", "example": null}]','chinese-xinhua','0'),
