('2101143296133828639','警','1','jǐnɡ','言','19',NULL,'[{"def": "警", "example": null}, {"def": "(会意。从言,从敬,敬亦声。本义戒敕)", "example": null}, {"def": "同本义", "example": null}, {"def": "警,戒也。--《说文》", "example": null}, {"def": "正岁,则以法警戒群吏。--《周礼·宰夫》", "example": null}, {"def": "所以警众也。--《礼记·文王世子》", "example": null}, {"def": "乃一篇之警策。--《文赋》", "example": null}, {"def": "今年或者大警晋也。--《左传·宣公十二年》", "example": null}, {"def": "以警其余。--清·方苞《狱中杂记》", "example": null}, {"def": "又如警告;警励(告诫策励);警迹人(元代被列入盗贼户籍的人);警鼓(报警之鼓);警动(使人警觉悚动);警新(警策动人,语意新颖);警众(使众人警觉);警省(警觉省悟)", "example": null}, {"def": "戒备;防备", "example": null}, {"def": "军卫不彻,警也。--《左传·宣公十二年》", "example": null}, {"def": "又如警巡(警戒巡视", "example": null}, {"def": "警jǐng", "example": null}, {"def": "⒈警备，戒备～备。", "example": null}, {"def": "⒉告诫，警告杀一～百。～戒未然也（未然未发生的事）。", "example": null}, {"def": "⒊紧急情状或消息～备。～报。火～。告～。", "example": null}, {"def": "⒋敏锐，敏感～觉。～醒。机～。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296133828640','井','1','jǐnɡ','二','4',NULL,'[{"def": "井", "example": null}, {"def": "(象形。金文字形,外象井口,中间一点表示井里有水。本义水井)", "example": null}, {"def": "同本义", "example": null}, {"def": "改邑不改井。--《易·井》", "example": null}, {"def": "井道。--《易·杂卦》传", "example": null}, {"def": "宿息井树。--《周礼·野庐氏》。注井,共饮食。”", "example": null}, {"def": "为其井匽。--《周礼·官人》", "example": null}, {"def": "坐井观天,曰天小者,非天小也。--韩愈《原道》", "example": null}, {"def": "又如井池(井口旁储水的小池);井鱼(井中的鱼。比喻见识短浅);井养(井水源源不断,供人饮用。比喻领受别人的好处、恩惠);井华(清早初汲的井水);井干(井上木栏干)", "example": null}, {"def": "形似水井的坑穴", "example": null}, {"def": "井jǐng", "example": null}, {"def": "⒈凿地挖成能取出水的深洞水～。又指形状像井的煤～。油～。气～。天～。", "example": null}, {"def": "⒉整齐，有秩序～ ～有条。～然有序。", "example": null}, {"def": "⒊星宿名。二十八宿之一。", "example": null}]','chinese-xinhua','0'),
('2101143296133828641','阱','1','jǐnɡ','阝','6',NULL,'[{"def": "阱", "example": null}, {"def": "(形声。从阜,表示与地形地势的高低上下有关,井声。本义陷阱,为捕捉野兽的坑)", "example": null}, {"def": "同本义", "example": null}, {"def": "阱,陷也。--《说文》", "example": null}, {"def": "使入陷阱。--《汉书·食货志下》。师古曰阱,穿地以陷兽也。”", "example": null}, {"def": "春令为阱获沟渎之利于民者。--《周礼·雍氏》", "example": null}, {"def": "罟获陷阱。--《礼记·中庸》", "example": null}, {"def": "猛虎落陷阱。--李白《君马黄》", "example": null}, {"def": "又如猛虎落阱;阱鄂(捕野兽的陷坑和笼子);阱机(本指捕捉动物的陷阱。喻指陷害别人的计谋)", "example": null}, {"def": "比喻害人的圈套", "example": null}, {"def": "在地下掘的用来囚拘人的地方", "example": null}, {"def": "阱 <", "example": null}, {"def": "阱（穽）jǐng用于防御或捕捉野兽、敌人等所挖的陷坑陷～。", "example": null}]','chinese-xinhua','0'),
('2101143296133828642','刭','1','jǐnɡ','刂','7',NULL,'[{"def": "刭", "example": null}, {"def": "(形声。从刀,巠声。本义砍头;割颈) 同本义", "example": null}, {"def": "刭,刑也。--《说文》。段注刭,谓断头也。”", "example": null}, {"def": "刭而独鹿弃之法。--《荀子·成相》", "example": null}, {"def": "北乡自刭。--《史记·魏公子列传》", "example": null}, {"def": "果北乡自刭。", "example": null}, {"def": "句卑布裳,刭而裹之,藏其身,而以其首免。--《左传·定公四年》。杜预注司马已死,刭取其首。”", "example": null}, {"def": "是岁,入有自刭死以其头献者。--《韩非子·内储说上》", "example": null}, {"def": "又如刭拔(刭杀);刭杀(斩杀)", "example": null}, {"def": "刭（剄）jǐng用刀割颈兵败自～。", "example": null}]','chinese-xinhua','0'),
