('2101143296133828660','惊','1','jīnɡ','忄','11',NULL,'[{"def": "惊", "example": null}, {"def": "(形声。从马,敬声。本义马受惊)", "example": null}, {"def": "同本义", "example": null}, {"def": "驚,马骇也。--《说文》", "example": null}, {"def": "襄子至桥而马惊。--《战国策·赵策一》", "example": null}, {"def": "又如惊嘶(马受惊而嘶叫);惊尘(车马疾驶所扬起的尘土);惊镳(惊马)", "example": null}, {"def": "惊动;震惊", "example": null}, {"def": "宫庭震惊。--《楚辞·招魂》", "example": null}, {"def": "其生若惊。--《吕氏春秋·慎大》", "example": null}, {"def": "震惊百里。--《易·震卦》。郑注惊之言警戒也。”", "example": null}, {"def": "皆惊忙。--《乐府诗集·木兰诗》", "example": null}, {"def": "月出惊山鸟。--唐·王维《鸟鸣涧》", "example": null}, {"def": "惊问信之。--明·魏禧《大铁椎传》", "example": null}, {"def": "惊为生人。--清·薛福成《观巴黎油画", "example": null}, {"def": "惊（驚）jīng", "example": null}, {"def": "⒈骡、马等因受吓而发狂乱奔控制～马。〈引〉害怕，精神紧张～骇。～慌失措。～心动魄。～恐万状。", "example": null}, {"def": "⒉意料以外的感觉～喜交集。倍感～奇。", "example": null}, {"def": "⒊扰乱，震动～扰。～动。～天动地。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296133828661','旌','1','jīnɡ','方','11',NULL,'[{"def": "旌", "example": null}, {"def": "(形声。本义古代用牦牛尾或兼五采羽毛饰竿头的旗子)", "example": null}, {"def": "同本义", "example": null}, {"def": "旌,游车载旌析羽。--《说文》", "example": null}, {"def": "位所谓緌有虞氏旌也。--《礼记·明堂位》", "example": null}, {"def": "建旌提鼓。--《国语·吴语》", "example": null}, {"def": "又如旌旄(古代用牦牛尾与羽毛装饰的军旗,或代指各种旗帜);旌羽(旌旗。因有羽饰,故称)", "example": null}, {"def": "古代旗的总称", "example": null}, {"def": "旌蔽日兮敌若云。--《楚辞·九歌·国殇》", "example": null}, {"def": "旌麾南指,刘琮束手。--《资治通鉴》", "example": null}, {"def": "又如旌旃(泛指旗帜);旌幡(泛指旗帜);旌帜(旗帜);旌幢(旗幡);旌头(旗杆顶端的矛头)", "example": null}, {"def": "旌节,古代使者所持的节", "example": null}, {"def": "王婆道眼望旌节至,耳听到消息。”╠", "example": null}, {"def": "旌jīng", "example": null}, {"def": "⒈〈古〉用五色羽毛装饰的一种旗子建～提鼓。又是旗子的通称～旗招展。", "example": null}, {"def": "⒉表扬以～其美（美美德）。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296133828662','旍','1','jīnɡ','','8',NULL,'[{"def": "旍jīng 古同\\"旌\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296133828663','菁','1','jīnɡ','艹','11',NULL,'[{"def": "菁", "example": null}, {"def": "(形声。从苃,青声。本义韭菜花)", "example": null}, {"def": "同本义", "example": null}, {"def": "菁,韭华(花)也。--《说文》", "example": null}, {"def": "其实菁菹。--《周礼·醢人》。司农曰非菹也。”", "example": null}, {"def": "以西菁菹。--《仪礼·公食礼》。注萱菁也。”", "example": null}, {"def": "泛指盛开的花", "example": null}, {"def": "秋兰茝蕙,江离载菁。--《文选·宋玉·高唐赋》", "example": null}, {"def": "又如菁菁者莪(原是《诗经·小雅》的篇名,此诗赞美培育人材,后世遂用来比喻乐育英才)", "example": null}, {"def": "水草", "example": null}, {"def": "华采", "example": null}, {"def": "菁jīng", "example": null}, {"def": "⒈韭菜的花。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296133828664','晶','1','jīnɡ','日','12',NULL,'[{"def": "晶", "example": null}, {"def": "(会意。甲骨文字形,从三日,表示光亮之意。本义光亮,明亮)", "example": null}, {"def": "同本义", "example": null}, {"def": "晶,精光也。--《说文》。徐灏曰晶即星之象形文。”", "example": null}, {"def": "天高日晶。--欧阳修《秋声赋》", "example": null}, {"def": "又如晶天(清澈明亮的天空);晶沁(亮光透入);晶英(光亮;闪亮);晶波(闪亮的水波)", "example": null}, {"def": "同精”", "example": null}, {"def": "清明;晴朗", "example": null}, {"def": "八月凉风天气晶,万里无云河汉明。--宋之问《明河篇》", "example": null}, {"def": "又如晶莹;晶天(澄澈明亮的天空)", "example": null}, {"def": "晶", "example": null}, {"def": "晶体", "example": null}, {"def": "水晶的简称", "example": null}, {"def": "晶jīng", "example": null}, {"def": "⒈形容透明、光亮～莹的珠宝。亮～ ～。", "example": null}, {"def": "⒉水晶，矿物名。坚硬透明，有很多种，如墨～、茶～等。可用于制光学仪器等。", "example": null}, {"def": "⒊", "example": null}, {"def": "①由液体或气体变成若干有一定形状的小颗粒。", "example": null}, {"def": "②由结晶现象生成的小颗粒。", "example": null}, {"def": "③〈喻〉成果这项发明是她辛勤劳动的结～。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
