('2101143296133828666','腈','1','jīnɡ','月','12',NULL,'[{"def": "腈", "example": null}, {"def": "指以三价氮基n≡为特征的一类化合物", "example": null}, {"def": "的酰胺得到,完全水解时产生酸", "example": null}, {"def": "腈纶", "example": null}, {"def": "腈jīng含有氰基的一类有机化合物。通式r-cn。无色的液体或固体，有特殊的气味，遇酸或碱即分解。用途极广，它是合成纤维、合成橡胶等的重要原料。", "example": null}]','chinese-xinhua','0'),
('2101143296133828667','睛','1','jīnɡ','目','13',NULL,'[{"def": "睛", "example": null}, {"def": "(形声。从目,青声。本义眼珠)", "example": null}, {"def": "同本义", "example": null}, {"def": "虽达视犹不能见其睛。--《淮南子·主术》", "example": null}, {"def": "又如定睛一看;画龙点睛;火眼金睛", "example": null}, {"def": "眼睛", "example": null}, {"def": "那行者睁睛看处,真个的背在身上。--《西游记》", "example": null}, {"def": "偷睛斜望,春光只隔流苏帐。--明·陆采《明珠记》", "example": null}, {"def": "视力", "example": null}, {"def": "阳气上走于目而为睛,其别气走于耳而为听。--《灵枢经》", "example": null}, {"def": "睛jīng眼珠，眼球眼～。目不转～。画龙点～。", "example": null}]','chinese-xinhua','0'),
('2101143296133828668','粳','1','jīnɡ','米','13',NULL,'[{"def": "粳", "example": null}, {"def": "(形声。从禾,亢声,或从更声。本义粳稻,稻之不黏者。今指介于籼稻、糯稻之间的一种晚稻品种,米粒短而粗,米质黏性较强,胀性小) 同本义", "example": null}, {"def": "秔,稻属。--《说文》", "example": null}, {"def": "秔,不黏稻也。--《声类》", "example": null}, {"def": "更为秔稻。--《汉书·沟洫志》", "example": null}, {"def": "水澍稉。--左思《魏都赋》", "example": null}, {"def": "粳香等炊玉,韭美胜炮羔。--陆游《新凉》", "example": null}, {"def": "粳稻", "example": null}, {"def": "粳米", "example": null}, {"def": "粳（秔、稉）jīng粳稻，稻的一种。碾出的米称\\"粳米\\"。有粘性和不粘两种。", "example": null}]','chinese-xinhua','0'),
('2101143296133828669','兢','1','jīnɡ','儿','14',NULL,'[{"def": "兢", "example": null}, {"def": "(象形。金文字形,象二人头顶重物形。头上戴着重物,故常戒惕小心。本义小心谨慎的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "战战兢兢,如临深渊,如履薄冰。--《诗·小雅·小昮》", "example": null}, {"def": "又如兢惕(小心谨慎);兢持(矜持,拘束);兢兢切切(兢兢业业,小心翼翼);兢危(戒慎忧惧)", "example": null}, {"def": "强劲", "example": null}, {"def": "尔羊来思,矜矜兢兢,不骞不崩。--《诗·小雅·无羊》", "example": null}, {"def": "又如兢兢(强壮的样子)", "example": null}, {"def": "兢", "example": null}, {"def": "战栗;恐惧", "example": null}, {"def": "兢兢业业", "example": null}, {"def": "兢jīng", "example": null}]','chinese-xinhua','0'),
('2101143296133828670','精','1','jīnɡ','米','14',NULL,'[{"def": "精", "example": null}, {"def": "(形声。从米,青声。本义挑选过的好米,上等细米)", "example": null}, {"def": "同本义", "example": null}, {"def": "精,择也。--《说文》", "example": null}, {"def": "鼓筴播精。--《庄子·人间世》", "example": null}, {"def": "食不厌精。--《论语》", "example": null}, {"def": "又如精凿(舂过的净米);精粲(精米)", "example": null}, {"def": "精气", "example": null}, {"def": "祓除其心精也。--《国语·周语》", "example": null}, {"def": "精也者,气之精者也,气道乃生。--《管子·内业》", "example": null}, {"def": "天地之精。--《吕氏春秋·慎行论》", "example": null}, {"def": "二者用精至矣。--汉·王充《论衡·订鬼篇》", "example": null}, {"def": "又如精秀(精华灵秀之气);精气命脉神(生命与血汗。比喻辛苦);精血(精气和血液);精胆(精气);精耀(精气)", "example": null}, {"def": "精神;精力", "example": null}, {"def": "精jīng", "example": null}, {"def": "⒈细，细密，跟\\"粗\\"相对～细。～密。～致。～打细算。～雕细刻。～心策划。", "example": null}, {"def": "⒉专心，用功深～心设计。～研细琢。业～于勤。～益求～。", "example": null}, {"def": "⒊聪明，机警，能力强～明。～干。～得很。他是个～悍有为的人。", "example": null}, {"def": "⒋物质提炼出来的纯粹部分酒～。肝～。", "example": null}, {"def": "⒌经过提炼的～盐。", "example": null}, {"def": "⒍完美，最好～英。～粹。～华（也写作\\"菁华\\"）。", "example": null}, {"def": "⒎很，极～瘦。", "example": null}, {"def": "⒏男子及雄性动物的生殖物质～液。～子。", "example": null}, {"def": "⒐童话、神话中或迷信者所说的\\"妖怪\\"狐狸～。妖～（又指不正派的人）。～灵（又指乖巧聪明）。", "example": null}, {"def": "⒑明亮，光洁日月光～。～光（又指一点也没有）。", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "⒔", "example": null}, {"def": "①活力，活跃，有生气～神饱满。", "example": null}, {"def": "②跟物质相对立的哲学概念。即主观世界，包括意识、思维、心理状态等革命～神。", "example": null}, {"def": "③内容实质会议～神。", "example": null}, {"def": "⒕", "example": null}, {"def": "⒖", "example": null}, {"def": "⒗", "example": null}, {"def": "①精干简要～简会议。", "example": null}, {"def": "②减去不必要的，留下必要的。多指简缩机构，简化行政程序，节约开支，提高工作效能等～简机构。～简手续。", "example": null}]','chinese-xinhua','0'),
