('2101143296133828703','旧','1','jiù','日','5',NULL,'[{"def": "旧", "example": null}, {"def": "(形声。甲骨文字形,上面是萑”,鸱鸟类;下面是臼”,作声符。本义鸟名)", "example": null}, {"def": "鸺鷙,即猫头鹰", "example": null}, {"def": "故交,老交情", "example": null}, {"def": "待之若旧。--南朝梁·丘迟《与陈伯之书》", "example": null}, {"def": "与之有旧。--清·全祖望《梅花岭记》", "example": null}, {"def": "与相国有旧。--清·周容《芋老人传》", "example": null}, {"def": "又如怀旧;有旧;念旧;亲戚故旧;旧雨", "example": null}, {"def": "原有的典章制度", "example": null}, {"def": "不必循旧。--《淮南子·泛论》", "example": null}, {"def": "又如复旧;照旧", "example": null}, {"def": "指世族", "example": null}, {"def": "通丘”。丘冢,坟墓", "example": null}, {"def": "越王不隳旧冢。--《说苑·尊贤》", "example": null}, {"def": "越王", "example": null}, {"def": "旧（舊）jiù", "example": null}, {"def": "⒈陈的，过时的，跟\\"新\\"相对～的。～日。守～。～调重弹。〈引〉原来的，从前的～山河。～地重游。～恨新仇。", "example": null}, {"def": "⒉老朋友，有交情的人～友。～交。亲戚故～。～雨重逢（旧雨老朋友）。", "example": null}]','chinese-xinhua','0'),
('2101143296133828704','臼','1','jiù','臼','6',NULL,'[{"def": "臼", "example": null}, {"def": "(象形。小篆字形,象舂米器具形,中间的四点表示有米。本义中部下凹的舂米器具)", "example": null}, {"def": "同本义", "example": null}, {"def": "臼,舂也。古者掘地为臼,其后穿木石。--《说文》", "example": null}, {"def": "断木为杵,掘地为臼。--《易·系辞下》", "example": null}, {"def": "择满臼,舂之而不碎。--贾思勰《齐民要术》", "example": null}, {"def": "又如臼杵(臼与杵);臼塘(凿成船形的木臼,别称臼塘);臼中无釜(比喻妻子亡故)", "example": null}, {"def": "又指用以形容臼状物", "example": null}, {"def": "臼", "example": null}, {"def": "用臼舂米", "example": null}, {"def": "织纺井臼。(臼,用如动词舂米。)--清·周容《芋老人传》", "example": null}, {"def": "臼", "example": null}, {"def": "形如臼的", "example": null}, {"def": "臼jiù", "example": null}, {"def": "⒈旧时舂米的器具，一般用石凿成石～。", "example": null}, {"def": "⒉形状像臼的～齿。", "example": null}]','chinese-xinhua','0'),
('2101143296133828705','咎','1','jiù','口','8',NULL,'[{"def": "咎", "example": null}, {"def": "(会意。从人,从各。从各”,表示相违背。违背人的心愿。本义灾祸,灾殃)", "example": null}, {"def": "同本义", "example": null}, {"def": "咎,灾也。--《说文》", "example": null}, {"def": "弃宝者必离其咎。--《吕氏春秋·侈乐》。注殃也。”", "example": null}, {"def": "嗟苦先生,独离此咎。--贾谊《吊屈原赋》", "example": null}, {"def": "又如咎征(天降灾祸的征验);咎有应得(罹祸受罚是由于自己的原因,完全应得的);咎戒(上天所降的灾祸与警告)", "example": null}, {"def": "过失,罪过", "example": null}, {"def": "无咎者,善补过也。--《易·系辞》", "example": null}, {"def": "其作汝用咎。--《书·洪范》。疏咎是过之别名。”", "example": null}, {"def": "微我有咎。--《诗·小雅·伐木》", "example": null}, {"def": "以彰其咎。--诸葛亮《出师表》", "example": null}, {"def": "又如咎戾(罪过);", "example": null}, {"def": "咎jiù", "example": null}, {"def": "⒈过失，罪过～在人怨。～由自取。", "example": null}, {"def": "⒉凶，灾祸有～。休～（吉凶）难料。", "example": null}, {"def": "⒊归罪，处分既往不～。贪官必～。", "example": null}, {"def": "咎gāo 1.通\\"皋\\"。指虞舜的贤臣咎繇，即皋陶。 2.见\\"咎鼓\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296133828706','疚','1','jiù','疒','8',NULL,'[{"def": "疚", "example": null}, {"def": "(形声。从疒,表示与疾病有关,久声。本义久病)", "example": null}, {"def": "同本义", "example": null}, {"def": "无饥馑疾疚祸罪之殃。--《韩非子》", "example": null}, {"def": "又如疚病(疾病);疚疾(疾病);疚头怪脑(丑头怪脸的样子)", "example": null}, {"def": "贫穷", "example": null}, {"def": "维昔之富不如时,维今之疚不如兹。--《诗·大雅·召昮》", "example": null}, {"def": "缺陷", "example": null}, {"def": "行刑不疚。(不疚,无弊病。)--《国语·晋语》", "example": null}, {"def": "令章靡疚,亦善之亚。--《文心雕龙》", "example": null}, {"def": "害;灾殃", "example": null}, {"def": "行刑不疚。(不疚,无弊病。)--《国语·晋语》", "example": null}, {"def": "刚中正,履帝位而不疚,光明也。--《易·履》", "example": null}, {"def": "疚", "example": null}, {"def": "因有过失而感到内心惭愧痛苦", "example": null}, {"def": "使我心疚。╠", "example": null}, {"def": "疚jiù", "example": null}, {"def": "⒈久病。", "example": null}, {"def": "⒉忧苦，心内痛苦负～。使我心～。", "example": null}]','chinese-xinhua','0'),
('2101143296133828707','柩','1','jiù','木','9',NULL,'[{"def": "柩", "example": null}, {"def": "(形声。从木,从匚,盛东西的筐器,久声。本义装有尸体的棺材)", "example": null}, {"def": "同本义", "example": null}, {"def": "柩,棺也。--《说文》。", "example": null}, {"def": "古文湨字从匚久,后世又加木旁耳,虚者为棺,实者为柩。--《尔雅》", "example": null}, {"def": "先迁柩于庙。--《谷梁传·宣公八年》", "example": null}, {"def": "崩薨,柩之为言究也,久也,不复变也。--《白虎通》", "example": null}, {"def": "在床曰尸,在棺曰柩。--《礼记·曲礼》", "example": null}, {"def": "又如运柩;枢榇(装有尸体的棺材);柩尸(指灵柩);柩室(停放灵柩之室);柩路(载灵柩之车);柩殡(谓停放灵柩)", "example": null}, {"def": "铭,汉时谓刻在石碑上的字为柩", "example": null}, {"def": "设敖置铭。--《周礼》。贾公彦疏铭所以表柩,故汉时谓铭", "example": null}, {"def": "柩jiù装有尸体的棺材引～。灵～。迁其～。", "example": null}]','chinese-xinhua','0'),
