('2101143296133828710','桕','1','jiù','木','10',NULL,'[{"def": "桕", "example": null}, {"def": "乌桕", "example": null}, {"def": "药,有解毒、利尿等作用", "example": null}, {"def": "桕脂", "example": null}, {"def": "阶走枫林叶,窗催桕烛花。--宋·慕容百才诗", "example": null}, {"def": "旧式门上合榫的槽", "example": null}, {"def": "两个正是推门入桕。--《警世通言》", "example": null}, {"def": "桕jiù乌桕树，我国特产树之一。落叶乔木，叶略呈菱形，夏季开黄色小花。种子外面有一层白色脂质叫\\"桕脂\\"，可用于制肥皂和蜡烛。种子可榨油，供制造油漆、油墨等用。", "example": null}, {"def": "根皮和叶可供药用。", "example": null}]','chinese-xinhua','0'),
('2101143296133828711','厩','1','jiù','厂','11',NULL,'[{"def": "厩", "example": null}, {"def": "(形声。古文字中,厂”与广”常常通用,都表示与房舍、居住有关。本义马圈,马棚)", "example": null}, {"def": "同本义", "example": null}, {"def": "厩,马舍也。--《说文》", "example": null}, {"def": "六系为厩,厩一仆夫,计马二百十六匹也。--《周礼·校人》", "example": null}, {"def": "新延厩。--《左传·庄公二十九年》", "example": null}, {"def": "厩焚。--《论语》", "example": null}, {"def": "狗马实外厩。--《战国策·齐策四》", "example": null}, {"def": "厩中仆马。--明·宗臣《报刘一丈书》", "example": null}, {"def": "所立厩中。", "example": null}, {"def": "又如厩长(掌管马厩的官吏);厩苑(养马场);厩率(马夫);厩副(马厩的副职官长);厩圉(马棚); 厩闲(马房)", "example": null}, {"def": "泛指牲口棚", "example": null}, {"def": "厩肥", "example": null}, {"def": "厩（廄）jiù马圈乘马在～。泛指牲口圈～肥。", "example": null}]','chinese-xinhua','0'),
('2101143296133828712','救','1','jiù','攵','11',NULL,'[{"def": "救", "example": null}, {"def": "(形声。从攴,轻轻敲击,求声。本义止;禁止;阻止)", "example": null}, {"def": "同本义", "example": null}, {"def": "救,止也。--《说文》", "example": null}, {"def": "救,犹禁也。以礼防禁人之过者也。--《周礼·司救》注", "example": null}, {"def": "使之相救。--《周礼·大司徒》。注救,救凶灾也。”", "example": null}, {"def": "今有同室之人斗者,救之,虽被发缨冠而救之可也。--《孟子·离娄下》", "example": null}, {"def": "又如救止(阻止;纠正);救祸(消除祸乱);救灭(扑灭);救熄(亦作救息”。扑灭);救扑(扑灭)", "example": null}, {"def": "援救别人", "example": null}, {"def": "救,助也。--《广雅》", "example": null}, {"def": "扶服救之。--《礼记·檀弓》", "example": null}, {"def": "匍匐救之。--《孔子闲居》", "example": null}, {"def": "民困而不知救。--明·刘基《", "example": null}, {"def": "救（捄）jiù", "example": null}, {"def": "⒈帮助，援助，使脱离困境或危险～济。～援。～急。急～。拯～。患难相～。遇良医可～。", "example": null}, {"def": "⒉止～ 火。濯以～热（濯洗）。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296138022912','就','1','jiù','尢','12',NULL,'[{"def": "就", "example": null}, {"def": "(会意。京尤会意。京”意为高,尤”意为特别。本义到高处去住)", "example": null}, {"def": "同本义", "example": null}, {"def": "就,就高也。从京从尤。尤,异于凡也。--《说文》。桂馥注此言人就高以居也。”孔广居注京,高丘也。古时洪水横流,故高丘之异于凡者人就之。”", "example": null}, {"def": "靠近;走近;趋向", "example": null}, {"def": "就,即也。--《广韵》", "example": null}, {"def": "主人就东阶,客就西阶。--《礼记·曲礼》", "example": null}, {"def": "不就利,不违害。--《庄子·齐物论》", "example": null}, {"def": "不知就先,不知就后。--《庄子·大宗师》", "example": null}, {"def": "禹趋就下风,立而问焉。--《庄子·天地》", "example": null}, {"def": "夫子休就舍。--《庄子·说剑》", "example": null}, {"def": "金就砺", "example": null}, {"def": "就jiù", "example": null}, {"def": "⒈完成，达到已～。功成业～。", "example": null}, {"def": "⒉进入，开始，从事～位。～席。～业。～学。", "example": null}, {"def": "⒊接近，靠近～着灯光写字。", "example": null}, {"def": "⒋趋向，趁着避祸～福。～便看看。～空走走。", "example": null}, {"def": "⒌立刻，紧接着马上～到。她～要去北京。", "example": null}, {"def": "⒍便天刚亮雨～停了。", "example": null}, {"def": "⒎随，因，顺着～地取材。～事论事。～近乘车。", "example": null}, {"def": "⒏只，单，偏偏她～爱绘画。～不信邪，～不怕吓。", "example": null}, {"def": "⒐即使，即便～是。你～不说，我也知道。你～是白送给，我也不敢要。", "example": null}, {"def": "⒑〈表〉肯定语气的词这～对了。你不去～叫他去。", "example": null}, {"def": "⒒随同着吃下去炒肉片～饭。", "example": null}, {"def": "⒓", "example": null}, {"def": "⒔", "example": null}, {"def": "⒕", "example": null}]','chinese-xinhua','0');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`,`hit_count`) VALUES
('2101143296163188736','舅','1','jiù','臼','13',NULL,'[{"def": "舅", "example": null}, {"def": "(形声。从男,臼声。本义舅父,指母之兄或弟)", "example": null}, {"def": "同本义", "example": null}, {"def": "母之兄、弟。妻之父为外舅,从男,臼声。凡异姓之称,不得称父,则舅之。--《说文》", "example": null}, {"def": "王之元舅。--《诗·大雅·崧高》", "example": null}, {"def": "于舅家见。--宋·王安石《伤仲永》", "example": null}, {"def": "复到舅家。", "example": null}, {"def": "又如舅氏(对舅的尊称);舅公(父亲的舅父);舅弟(舅父的儿子,年纪小于自己的。即表弟);舅兄(舅父之子年长于己者)", "example": null}, {"def": "妻的弟或兄", "example": null}, {"def": "舅在则君舅,舅没则曰先舅。--朱骏声《说文通训定声》", "example": null}, {"def": "吾舅死于虎。--《礼", "example": null}, {"def": "舅jiù", "example": null}, {"def": "⒈母亲的弟或兄～父。～ ～好。", "example": null}, {"def": "⒉妻子的弟或兄大～子。妻～。", "example": null}, {"def": "⒊〈古〉称丈夫的父亲～姑（公婆）。", "example": null}]','chinese-xinhua','0'),
('2101143296163188737','僦','1','jiù','亻','14',NULL,'[{"def": "僦", "example": null}, {"def": "(形声。从人,就声。本义租赁)", "example": null}, {"def": "同本义", "example": null}, {"def": "僦屋以居。--韩愈《送郑权尚书序》", "example": null}, {"def": "又如僦居(租屋而居);僦舍(租屋居住);僦屋(租房子);僦田(租借田地);僦邸(租赁居宅);僦房(租赁房屋)", "example": null}, {"def": "雇", "example": null}, {"def": "僦", "example": null}, {"def": "租金,赁金", "example": null}, {"def": "令送粮无取僦。--《商君书》", "example": null}, {"def": "僦jiù租赁，雇～屋。～费（运费）。～牛输谷（输运输）。", "example": null}]','chinese-xinhua','0'),
('2101143296163188738','殧','1','jiù','','8',NULL,'[{"def": "殧jiù 1.寿终。 2.殧殄，灭尽。", "example": null}]','chinese-xinhua','0'),
('2101143296163188739','鹫','1','jiù','鸟','17',NULL,'[{"def": "鹫", "example": null}, {"def": "老雕", "example": null}, {"def": "鹫鸟,黑色,多子。师旷曰,南方有鸟,名曰羌鹫,黄头赤目,五色皆备。--《说文》", "example": null}, {"def": "鹫,雕也。--《广雅》", "example": null}, {"def": "生奇材木箭竿就(鹫)羽。--《汉书·匈奴传》。注大雕也。”", "example": null}, {"def": "产于温带和热带地区的若干种大型猛禽,与鹰类、雕类和隼类都有亲缘关系,但爪较弱,头多秃,主要或全部以腐肉为食,构成鹫科(aegypiidae)和新域鹫科(cathartidae),其中", "example": null}, {"def": "包括一些最大的飞禽。如鹫羽(老雕的羽毛。又叫鹫翎”)", "example": null}, {"def": "灵鹫山的简称", "example": null}, {"def": "鹫jiù大型猛禽的一类秃～（也叫\\"座山雕\\"），能捕食山羊、野兔等。已少见，禁止猎杀。", "example": null}]','chinese-xinhua','0'),
('2101143296163188740','麔','1','jiù','','8',NULL,'[{"def": "麔jiù 1.麋鹿中的雄性称麔。", "example": null}]','chinese-xinhua','0'),
('2101143296163188741','齨','1','jiù','','8',NULL,'[{"def": "齨jiù 1.老人似臼的齿。 2.八岁以上马之齿。马八岁以上齿亦如臼，故俗名\\"齨\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296163188742','廻','1','jiù','','8',NULL,'[{"def": "廻jiù 1.马房。 2.泛指牲口棚。 3.通\\"究\\"。深入。", "example": null}]','chinese-xinhua','0'),
