('2101143296163188747','韭','1','jiǔ','韭','9',NULL,'[{"def": "韭", "example": null}, {"def": "(象形。小篆,象韭菜长在地上的形状。本义韭菜)", "example": null}, {"def": "同本义", "example": null}, {"def": "韭,菜名,一种而久者,故谓之韭。--《说文》", "example": null}, {"def": "囿有见韭。--《夏小正·正月》", "example": null}, {"def": "丹熏之山,其草多韭。--《山海经·北山经》", "example": null}, {"def": "韭曰丰本。--《礼记·曲礼》", "example": null}, {"def": "四之日其蚤,献羔祭韭。--《诗·豳风·七月》", "example": null}, {"def": "某些葱属植物的通称", "example": null}, {"def": "韭（韮）jiǔ韭菜，多年生草本。叶细长而扁，丛生。夏秋开白色小花，种子黑色。叶和花苔是普通的蔬菜。种子和根可供药用。经软化栽培，叶成\\"韭黄\\"，也是普通的蔬菜。", "example": null}]','chinese-xinhua','0'),
('2101143296163188748','紤','1','jiǔ','','3',NULL,'[{"def": "紤jiǔ 1.镜。", "example": null}]','chinese-xinhua','0'),
('2101143296163188749','酒','1','jiǔ','酉','10',NULL,'[{"def": "酒", "example": null}, {"def": "(会意。从水,从酉。酉”本义就是酒。酉”亦兼表字音。本义用高粱、大麦、米、葡萄或其他水果发酵制成的饮料)", "example": null}, {"def": "同本义", "example": null}, {"def": "酒,就也。所以就人性之善恶。--《说文》", "example": null}, {"def": "酒曰清酌。--《礼记·曲礼》", "example": null}, {"def": "酒食者,所以令欢也。--《礼记·乐记》", "example": null}, {"def": "酒者所以养老也,所以养病也。--《礼记·射义》", "example": null}, {"def": "酒,百乐之长。又,酒者,天下之美禄。--《汉书·食货志》", "example": null}, {"def": "不为酒困。--《论语·子罕》", "example": null}, {"def": "又如酒肆(酒店);酒水(酒;筵席);酒生(酒保,酒店伙计);酒务(酒店)", "example": null}, {"def": "酒席,酒筵", "example": null}, {"def": "酒jiǔ", "example": null}, {"def": "⒈用粮食（高粱、麦、米等）或水果等发酵制成的含乙醇的饮料，有刺激性，多饮会中毒白～。啤～。葡萄～。茅梨～。酗～误事∪～多，会伤身。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296163188750','灸','1','jiǔ','火','7',NULL,'[{"def": "灸", "example": null}, {"def": "(形声。从火,久声。本义用艾火烧灼。中医的一种疗法)", "example": null}, {"def": "同本义", "example": null}, {"def": "灸,灼也。--《说文》", "example": null}, {"def": "所谓不病而灸,无忧而自默。--向秀《难养生论》", "example": null}, {"def": "又如灸刺(艾灸和针刺);灸客(接受灸疗的病人);灸眉(用艾炷烧灼眉头以治狂疾);灸师(以灸术治病的医师)", "example": null}, {"def": "烧灼", "example": null}, {"def": "拄,支撑", "example": null}, {"def": "灸诸墙,以眡其桡之均也。--《周礼》", "example": null}, {"def": "堵塞", "example": null}, {"def": "灸jiǔ灼、烧，祖国医学的一种治病疗法。用艾绒等做艾柱，烧灼或薰烤身体穴位或某一部位，或者在体表放置薄片生姜等，隔姜烧烤。以疏通经络，调和气血，达到治病。灸", "example": null}, {"def": "法和针刺常并用，称\\"针灸疗法\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296163188751','玖','1','jiǔ','王','7',NULL,'[{"def": "玖", "example": null}, {"def": "(形声。从玉,久声。本义似玉的黑色美石)", "example": null}, {"def": "同本义", "example": null}, {"def": "玖,石之次玉,黑色。--《说文》", "example": null}, {"def": "报之以琼玖。--《诗·卫风·木瓜》", "example": null}, {"def": "贻我佩玖。--《诗·王风·邱中有麻》", "example": null}, {"def": "数词九”的大写", "example": null}, {"def": "玖jiǔ", "example": null}, {"def": "⒈\\"九\\"的大写。", "example": null}, {"def": "⒉像玉的一种浅黑色石头。", "example": null}]','chinese-xinhua','0'),
