('2101143296163188762','究','1','jiū','穴','7',NULL,'[{"def": "究", "example": null}, {"def": "(形声。从穴,九声。本义穷;尽) 同本义", "example": null}, {"def": "究,穷也。--《说文》", "example": null}, {"def": "靡届靡究。--《诗·大雅·荡》", "example": null}, {"def": "害气将究。--《汉书·食货志》", "example": null}, {"def": "此告民究也。--《吕氏春秋·任地》", "example": null}, {"def": "靡届靡究。--《诗·大雅·荡》", "example": null}, {"def": "害气将究。--《汉书·食货志》", "example": null}, {"def": "此告民究也。--《吕氏春秋·任地》", "example": null}, {"def": "必须天道,", "example": null}, {"def": "又如究途(走完全部的路程。比喻做事有始有终);究年(终年);究归(终归)", "example": null}, {"def": "究", "example": null}, {"def": "谋划;研究;探求", "example": null}, {"def": "究,谋也。--《尔雅》", "example": null}, {"def": "不舒究之。--《诗·小雅·小弁》", "example": null}, {"def": "爰究爰度。--", "example": null}, {"def": "究jiū", "example": null}, {"def": "⒈终极，到底终～。九洲生气恃风雷，万马齐瘖～可哀（恃仗着。瘖哑，无声）。", "example": null}, {"def": "⒉追查，探求追～。深～。研～。", "example": null}, {"def": "⒊", "example": null}, {"def": "①结果，原委问个～竟。", "example": null}, {"def": "②到底他～竟是干啥的？", "example": null}]','chinese-xinhua','0'),
('2101143296163188763','鸠','1','jiū','鸟','7',NULL,'[{"def": "鸠", "example": null}, {"def": "(形声。从鸟,九声。本义鸟名)", "example": null}, {"def": "鸠鸽科的鸟的泛称", "example": null}, {"def": "鸠,鹘鸠也。--《说文》", "example": null}, {"def": "维鸠居之。--《诗·召南·鹊巢》", "example": null}, {"def": "维鸠盈之。", "example": null}, {"def": "维鸠方之。", "example": null}, {"def": "有雉鸠”(普通单称鸠)、祝鸠”、斑鸠”等,古时说有五种鸠祝鸠、鸤鸠、爽鸠、雎鸠、鹘鸠,祝鸠和鹘鸠是鸠类,鸤鸠是攀禽类的布谷,爽鸠是鹰类,雎鸠是鹗类。如鸠", "example": null}, {"def": "鸩(喻指专门诬陷好人的人);鸠杖(刻有鸠形的杖);鸠夺鹊巢(鸠性拙,不善筑巢,往往等鹊筑好巢后夺为己有。常喻指强占他人的地方)", "example": null}, {"def": "一种行于沙中的运载工具", "example": null}, {"def": "水用舟,陆用车,涂用榡,沙用鸠,山用欙。--《", "example": null}, {"def": "鸠jiū", "example": null}, {"def": "⒈鸟名。形状像鸽。种类很多，常见的有斑～、山～等，均已少见，要保护，禁止猎杀。", "example": null}, {"def": "⒉聚集～合（也作\\"纠合\\"）。", "example": null}, {"def": "鸠zhì 1.解决。", "example": null}]','chinese-xinhua','0'),
('2101143296163188764','赳','1','jiū','走','9',NULL,'[{"def": "赳", "example": null}, {"def": "(形声。从走,乴声。本义威武雄壮的样子) 同本义", "example": null}, {"def": "赳,轻劲有才力也。--《说文》", "example": null}, {"def": "赳,材也。--《广雅》", "example": null}, {"def": "赳赳武夫。--《诗·召南·兔羋》。传武貌。”", "example": null}, {"def": "赳赳,武也。--《尔雅》", "example": null}, {"def": "沛艾赳嗅。--《史记·司马相如传》。集解申颈低卬也。”", "example": null}, {"def": "又一日赳然有阵大风,从东南来,刮得山谷震动。--《女仙外史》", "example": null}, {"def": "赳jiū", "example": null}, {"def": "赳jiù 1.见\\"赳螑\\"。", "example": null}]','chinese-xinhua','0'),
