('2101143296163188812','惧','1','jù','忄','11',NULL,'[{"def": "惧", "example": null}, {"def": "(形声。从心,瞿声。本义害怕,恐惧)", "example": null}, {"def": "同本义", "example": null}, {"def": "惧,恐也。--《说文》", "example": null}, {"def": "是以举天下之人,皆恐惧振动惕栗,不敢为淫暴。--《墨子·尚同中》", "example": null}, {"def": "楚兵惧,自秦归。--《史记·屈原列传》", "example": null}, {"def": "夫大国,难测也,惧有伏焉。--《左传·庄公十年》", "example": null}, {"def": "故有知非以虑是,则谓之惧。--《荀子·解蔽》", "example": null}, {"def": "喜怒哀惧爱恶欲。--《礼记·礼运》", "example": null}, {"def": "勇者不惧。--《论语·子罕》", "example": null}, {"def": "又如惧思(因恐惧而慎重考虑);惧选(害怕获罪);惧高症(心理学名词。身处高处所产生的过分恐惧反应,不敢往下看、双腿发软、颤抖或晕眩等)", "example": null}, {"def": "惧（懼）jù害怕～怕。恐～。无所畏～。无私无～。", "example": null}]','chinese-xinhua','0'),
('2101143296163188813','据','1','jù','扌','11',NULL,'[{"def": "据", "example": null}, {"def": "(形声。本义手靠着;靠着)", "example": null}, {"def": "同本义", "example": null}, {"def": "据,杖持也。--《说文》", "example": null}, {"def": "冯几据杖。--《战国策·燕策》", "example": null}, {"def": "据轼低头。--《庄子·盗跖》", "example": null}, {"def": "依靠,凭借", "example": null}, {"def": "不可以据。--《诗·邶风·柏舟》", "example": null}, {"def": "神必据我。--《左传·僖公五年》", "example": null}, {"def": "诚据其势。--《史记·平原君虞卿列传》", "example": null}, {"def": "北据汉沔。--《三国志·诸葛亮传》", "example": null}, {"def": "向后据地。--《徐霞客游记·游黄山记》", "example": null}, {"def": "又如据着(凭着);据梧(依靠着梧桐树);据争(据理争辩);据恃(凭仗);据高临下(凭借高处俯控低处);据凭(依仗)", "example": null}, {"def": "根据", "example": null}, {"def": "据于德。--《论语》", "example": null}, {"def": "据", "example": null}, {"def": "据（據）jù", "example": null}, {"def": "⒈占，占有占～。盘～山洞。～为己有。", "example": null}, {"def": "⒉靠着，按着～栏杆。左手～膝。〈引〉依靠，凭借～险固守。", "example": null}, {"def": "⒊凭依，按照依～。引经～典。～理力争。", "example": null}, {"def": "⒋凭证凭～。证～。要收～。有根有～。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍见jū。", "example": null}, {"def": "据jū", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见jū。", "example": null}, {"def": "据jǐ 1.搏击;爪持。", "example": null}]','chinese-xinhua','0'),
('2101143296163188814','距','1','jù','足','11',NULL,'[{"def": "距", "example": null}, {"def": "(形声。从足,巨声。本义鸡爪)", "example": null}, {"def": "同本义", "example": null}, {"def": "距,鸡距也。--《说文》", "example": null}, {"def": "后阺为之金距。--《左传》", "example": null}, {"def": "不鸣不将无距。--《汉书·五行志》。注距,鸡附足骨,斗时所用刺之。”", "example": null}, {"def": "虽有钩针芒距。--《淮南子·原道》", "example": null}, {"def": "长皆及俎距。--《仪礼·少牢礼》。注胫中当横节也。”", "example": null}, {"def": "公输之刻凤也,冠距未成。--《列子》", "example": null}, {"def": "距离", "example": null}, {"def": "距随长武。--《仪礼·乡射礼记》", "example": null}, {"def": "又如苗距;槽距;差距;焦距;行距;株距;距国(介于大国之间,或两面受敌的国家);距随(古人射箭站立时两脚的间隔距离)", "example": null}, {"def": "倒刺", "example": null}, {"def": "古代兵器锋刃上的", "example": null}, {"def": "距jù", "example": null}, {"def": "⒈距离，离开两地相～十余里。～今五天。", "example": null}, {"def": "⒉鸡爪。特指雄鸡爪后突起像脚趾的部分。", "example": null}, {"def": "⒊〈古〉通\\"拒\\"。抗拒，抵御，拒绝。", "example": null}]','chinese-xinhua','0'),
