('2101143296163188825','遽','1','jù','辶','16',NULL,'[{"def": "遽", "example": null}, {"def": "(形声。从辵,表示与行走有关,本义送信的快车或快马)", "example": null}, {"def": "同本义", "example": null}, {"def": "遽,传也。--《说文》", "example": null}, {"def": "以待达穷者与遽令。--《周礼·大仆》", "example": null}, {"def": "掌邦国传遽之小事。--《周礼·行夫》。注若今时乘传骑驿而使者也。”", "example": null}, {"def": "且使遽告于郑。--《左传·僖公三十三年》。注传车。”", "example": null}, {"def": "士曰传遽之臣。--《礼记·玉藻》", "example": null}, {"def": "又如遽人(驿卒;传达命令的人);遽驿(传车和驿马);遽传(驿车和传舍);遽委(驿站车马和储存的粮食)", "example": null}, {"def": "乡名", "example": null}, {"def": "遽", "example": null}, {"def": "立刻;马上", "example": null}, {"def": "遽兴姜戎。", "example": null}, {"def": "遽jù", "example": null}, {"def": "⒈急速，匆忙急～。老至何～。", "example": null}, {"def": "⒉就，竟～以告人。", "example": null}, {"def": "⒊〈古〉迷信者所说的快车或快马乘～而至。", "example": null}, {"def": "⒋恐惧～怕。色～（色脸色）。", "example": null}]','chinese-xinhua','0'),
('2101143296163188826','句','1','jù','口','5',NULL,'[{"def": "句  gou", "example": null}, {"def": "(形声。从口。正当读今言钩,俗作勾。本义弯曲)", "example": null}, {"def": "同本义", "example": null}, {"def": "句,曲也。--《说文》。段注凡曲折之物,侈为倨,敛为句。考工记多言倨句。”", "example": null}, {"def": "越子为左右句卒。--《左传·哀公十七年》", "example": null}, {"def": "句兵欲无弹。--《考工记·庐人》", "example": null}, {"def": "覆之而角至谓之句弓。--《考工记·弓人》", "example": null}, {"def": "履句履者知地。--《庄子·田子方》。李注方也。”", "example": null}, {"def": "句者毕出。--《礼记·月令》", "example": null}, {"def": "古之人衣上有冒而句领者。--《尚书大传》", "example": null}, {"def": "句者毕出,萌者尽达。--《礼记·月令》", "example": null}, {"def": "(草木出土时,弯的叫句,直的叫萌。)。又如句爪(钩形的尖爪);句枉(曲枝);句曲(弯", "example": null}, {"def": "句jù", "example": null}, {"def": "⒈句子，能表达一个完整意思的语言单位造～。疑问～。", "example": null}, {"def": "⒉量词两～话。", "example": null}, {"def": "⒊见gōu。", "example": null}, {"def": "句gōu", "example": null}, {"def": "⒈〈古〉同\\"勾\\"。", "example": null}, {"def": "⒉见jù㈡。", "example": null}, {"def": "句gòu 1.通\\"彀\\"。张满弓。 2.见\\"句当\\"。", "example": null}, {"def": "句qú 1.通\\"絧\\"。鞋头的装饰品。 2.通\\"斪\\"。见\\"句欘\\"。", "example": null}, {"def": "句jiǔ 1.见\\"句婴\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296163188827','巨','1','jù','工','4',NULL,'[{"def": "巨", "example": null}, {"def": "(象形。金文字形,是矩”的本字,象人持矩形。本义画直角方形用的工具)", "example": null}, {"def": "同本义◇作矩”", "example": null}, {"def": "巨,规巨也。--《说文》", "example": null}, {"def": "是以君子有挈巨之道也。--《礼记·大学》", "example": null}, {"def": "成功之术,必有巨砮。--《管子·宙合》", "example": null}, {"def": "又如巨砮(法度。同矩砮”)", "example": null}, {"def": "通距”。距离", "example": null}, {"def": "守为台城,以临羊黔,左右出巨,各二十尺。--《墨子》", "example": null}, {"def": "姓", "example": null}, {"def": "巨", "example": null}, {"def": "大;很大", "example": null}, {"def": "巨,大也。--《小尔雅》", "example": null}, {"def": "力士举巨囊。--《公羊传·哀公六年》", "example": null}, {"def": "右巨指钩弦。--《仪礼·大射仪》", "example": null}, {"def": "穹崖巨谷。--宋·沈括《", "example": null}, {"def": "巨（钜）jù", "example": null}, {"def": "⒈大～国。～资。～型军舰。", "example": null}, {"def": "⒉〈古〉通\\"讵\\"。", "example": null}, {"def": "巨jǔ 1.规矩，法度。", "example": null}]','chinese-xinhua','0'),
('2101143296163188828','讵','1','jù','讠','6',NULL,'[{"def": "讵", "example": null}, {"def": "岂,难道", "example": null}, {"def": "无;非;不", "example": null}, {"def": "曾", "example": null}, {"def": "尔祭讵几时,朔望忽复尽。--晋·潘岳《悼亡诗》", "example": null}, {"def": "不料,哪知", "example": null}, {"def": "讵", "example": null}, {"def": "如果", "example": null}, {"def": "讵非圣人必偏而后可。--《国语》", "example": null}, {"def": "讵jù岂，难道，哪里～料。～知。～可闻？", "example": null}]','chinese-xinhua','0'),
