('2101143296163188841','钜','1','jù','钅','9',NULL,'[{"def": "锯", "example": null}, {"def": "(形声。从金,居声。本义析解木石等的齿形工具)", "example": null}, {"def": "同本义", "example": null}, {"def": "锯,枪唐也。--《说文》", "example": null}, {"def": "锯者所以治木也。--《列女传·仁智》。据古史考曰,孟庄子作锯,又按鲁语,中刑用刀锯。", "example": null}, {"def": "门者皆无得挟斧斤凿锯椎。--《墨子·备城门》", "example": null}, {"def": "又如手锯;电锯;拉锯;锯齿;锯梁(锯子当中支撑锯把的木梁)", "example": null}, {"def": "锯形物", "example": null}, {"def": "古刑具", "example": null}, {"def": "中刑用刀锯。--《国语·鲁语》", "example": null}, {"def": "又如刀锯(刀和锯,古代的刑具)", "example": null}, {"def": "锯", "example": null}, {"def": "用锯子切割", "example": null}, {"def": "绳锯木断,水滴石穿。--《鹤林玉露》", "example": null}, {"def": "又如锯木料;锯匠(锯木的工", "example": null}, {"def": "苣jù", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见qǔ。", "example": null}, {"def": "苣qǔ", "example": null}, {"def": "⒈", "example": null}]','chinese-xinhua','0'),
('2101143296163188842','俱','1','jù','亻','10',NULL,'[{"def": "俱", "example": null}, {"def": "(形声。从人,具声。本义走在一起,在一起)", "example": null}, {"def": "同本义", "example": null}, {"def": "俱,皆也。--《说文》", "example": null}, {"def": "而仪与之俱。--《战国策·齐策》。注偕也。”", "example": null}, {"def": "道可载而与之俱也。--《庄子·天运》", "example": null}, {"def": "臣客屠者朱亥可与俱。--《史记·魏公子列传》", "example": null}, {"def": "百余人俱。--《汉书·李广苏建传》", "example": null}, {"def": "与李陵俱。", "example": null}, {"def": "处与之俱。--《世说新语·自新》", "example": null}, {"def": "使与书俱。--清·袁枚《黄生借书说》", "example": null}, {"def": "等同", "example": null}, {"def": "所谓后者应不俱也。--《素问·三部九侯论》。注犹同也。”", "example": null}, {"def": "伊尹、箕子才俱也,伊尹为相,箕子为奴。--《论衡》", "example": null}, {"def": "俱", "example": null}, {"def": "俱jù", "example": null}, {"def": "⒈全，都～黑。～在。百废～兴。", "example": null}, {"def": "⒉在一起行则与～，止则相对。", "example": null}, {"def": "⒊", "example": null}, {"def": "俱jū 1.姓。晋有俱石公，唐有俱文珍。见《晋书．石勒载记》﹑《旧唐书．宦官传》。", "example": null}]','chinese-xinhua','0'),
('2101143296163188843','倨','1','jù','亻','10',NULL,'[{"def": "倨", "example": null}, {"def": "(形声。从人,居声。本义傲慢)", "example": null}, {"def": "同本义", "example": null}, {"def": "倨,不逊也。--《说文》", "example": null}, {"def": "游毋倨。--《礼记·曲礼》。疏慢也。”", "example": null}, {"def": "嫂何前倨而后恭也。--《战国策·秦策》", "example": null}, {"def": "与其倨也宁句。--《大戴礼记·曾子立事》。按,凡侈曰倨,敛曰句。", "example": null}, {"def": "体倨固而心执诈。--《脩身》", "example": null}, {"def": "又如倨忽(傲慢而疏忽);倨倨(一无思虑、神色傲慢的样子;盛服的样子);倨见(傲慢地接见或往见);倨侮(傲慢自大)", "example": null}, {"def": "直而折曲", "example": null}, {"def": "倨中矩,句中钩。--《礼记·乐记》", "example": null}, {"def": "又如倨句(器物弯曲的形状。曲度较小的叫倨,大的叫句);倨佝(倨拘。弯曲的,句为甚曲);倨", "example": null}, {"def": "倨jù", "example": null}, {"def": "⒈傲慢～傲。性～。前～后恭。", "example": null}, {"def": "⒉〈古〉通\\"踞\\"。蹲坐。", "example": null}]','chinese-xinhua','0'),
