('2101143296167383048','咀','1','jǔ','口','8',NULL,'[{"def": "咀", "example": null}, {"def": "(形声。从口,且声。本义品味,细嚼)", "example": null}, {"def": "同本义", "example": null}, {"def": "咀,含味也。--《说文》", "example": null}, {"def": "咀,嚼也。--《通俗文》", "example": null}, {"def": "三月如咀咀者何?--《管子·水地》", "example": null}, {"def": "沉浸浓郁,含英咀华。--韩愈《进学解》", "example": null}, {"def": "咀嚼", "example": null}, {"def": "咀果壳。--唐·柳宗元《贞符》", "example": null}, {"def": "咀嚼", "example": null}, {"def": "咀jǔ", "example": null}, {"def": "⒈品味，细嚼～觉。～嚼。", "example": null}, {"def": "⒉见zuī。", "example": null}, {"def": "咀zuǐ", "example": null}, {"def": "⒈口含在～里。", "example": null}, {"def": "⒉说话不要光动～不做事。", "example": null}, {"def": "⒊形状或作用像～的山～▲～子。烟～儿。", "example": null}]','chinese-xinhua','0'),
