('2101143296167383065','居','1','jū','尸','8',NULL,'[{"def": "居", "example": null}, {"def": "(象形。金文字形,是踞”的本字,象人曲胫蹲踞形。本义蹲着)", "example": null}, {"def": "同本义◇作踞”", "example": null}, {"def": "居,蹲也。从尸,古者居从古,俗居从足。--《说文》", "example": null}, {"def": "不宜居见长者。--《史记》", "example": null}, {"def": "昔阖庐食不二味,居不重席,室不崇坛。--《左传》", "example": null}, {"def": "居住", "example": null}, {"def": "则居可知矣。--《易·系辞下》", "example": null}, {"def": "仁者居之。--《吕氏春秋·离俗》", "example": null}, {"def": "卒不居赵地。--《吕氏春秋·达郁》", "example": null}, {"def": "寝居直梦。--《淮南子·地形》", "example": null}, {"def": "居者,居其所也。--《谷梁传·僖公二十四年》", "example": null}, {"def": "天王出居于郑。--《左传·僖公二十四年》", "example": null}, {"def": "面山而居。--《列子·汤问》", "example": null}, {"def": "楚人", "example": null}, {"def": "居jū", "example": null}, {"def": "⒈住～住。～民。面山而～。", "example": null}, {"def": "⒉住处迁～。故～。家～何处？", "example": null}, {"def": "⒊坐～中。〈引〉处于，位于～安思危。", "example": null}, {"def": "⒋当，任～职。不以功臣自～。", "example": null}, {"def": "⒌积蓄，储存～物积富。奇货可～。", "example": null}, {"def": "⒍占，占据～高临下。二者必～其一。", "example": null}, {"def": "⒎停留，固定岁月不～。", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "居jī 1.语助词。", "example": null}, {"def": "居jù 1.通\\"倨\\"。傲慢。 2.通\\"锯\\"。参见\\"居牙\\"﹑\\"居属\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296167383066','拘','1','jū','扌','8',NULL,'[{"def": "拘", "example": null}, {"def": "(会意。从手,从句,句亦声。本义拘留,拘禁)", "example": null}, {"def": "同本义", "example": null}, {"def": "拘,止也。--《说文》", "example": null}, {"def": "艮为拘随物系之。--《易·说卦》传", "example": null}, {"def": "拘系之乃从。--《易·随》", "example": null}, {"def": "盖文王拘而演。--《周易》", "example": null}, {"def": "狎徐君,拘齐庆封。--《韩非子·十过》", "example": null}, {"def": "又如拘证(缉拿审问);拘刷(通缉;拘捕);拘究(拘留审察);拘制(拘禁,系缚); 拘责(拘留责罚);拘闭(拘禁,扣押)", "example": null}, {"def": "束缚;限制", "example": null}, {"def": "使人拘而多畏。--《汉书·司马迁传》", "example": null}, {"def": "其流也,埤下裾拘,必循其理。--《荀子·宥坐》", "example": null}, {"def": "井蛙不可以语于海者,拘于虚也。--《庄子·秋水》", "example": null}, {"def": "拘,犹限也。", "example": null}, {"def": "拘jū", "example": null}, {"def": "⒈扣押或逮捕～留。～禁。", "example": null}, {"def": "⒉固执～泥。～谨。别太～。", "example": null}, {"def": "⒊束缚，限制～束。不～多少。～于成规。", "example": null}, {"def": "⒋", "example": null}, {"def": "①痉挛。", "example": null}, {"def": "②绻曲脚太冷，～挛儿。", "example": null}, {"def": "拘gōu 1.遮蔽。 2.轻微地牵引。 3.取。 4.弯曲。 5.勾拉。", "example": null}, {"def": "拘qú 1.参见\\"拘拘\\"。", "example": null}, {"def": "拘jǔ 1.拘涧，水名。", "example": null}]','chinese-xinhua','0'),
