('2101143296167383068','椐','1','jū','木','12',NULL,'[{"def": "椐", "example": null}, {"def": "木名,即灵寿木", "example": null}, {"def": "椐,樻也。从木,居声。--《说文》", "example": null}, {"def": "其柽其椐。--《诗·大雅·皇矣》", "example": null}, {"def": "虢山,其下多桐椐。--《山海经·北山经》。注樻木肿节,中杖。”", "example": null}, {"def": "椐,木名。肿节,可为杖。--《集韵》", "example": null}, {"def": "篱笆", "example": null}, {"def": "篱,…离也,青徐曰椐。--《释名》", "example": null}, {"def": "椐jū 1.木名。即灵寿木。 2.见\\"椐椐强强\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296167383069','琚','1','jū','王','12',NULL,'[{"def": "琚", "example": null}, {"def": "古人佩带的一种玉,系在珩和璜之间", "example": null}, {"def": "琚,琼琚。从玉,居声。--《说文》", "example": null}, {"def": "琚瑀以杂之。--《大戴礼记·保傅》", "example": null}, {"def": "投我以木瓜,报之以琼琚。--《诗·卫风·木瓜》", "example": null}, {"def": "琚jū〈古〉一种佩带的玉。", "example": null}]','chinese-xinhua','0'),
('2101143296167383070','趄','1','jū','走','12',NULL,'[{"def": "趄", "example": null}, {"def": "趄,行不进的样子", "example": null}, {"def": "阻隔", "example": null}, {"def": "经匣…上用趄尘眏顶,陷顶开带,四角打卯。--《营造法式》", "example": null}, {"def": "趄  qie", "example": null}, {"def": "倾斜", "example": null}, {"def": "宋江已有八分酒,脚步趄了,只顾踏去。--《水浒全传》", "example": null}, {"def": "又如趄趄(侧身而行,恭敬趋奉貌);趄趄趔趔(步履歪斜的样子)", "example": null}, {"def": "趄,翘起也。昆明俗语指把屁股趄着。--徐嘉瑞《金元戏曲方言考》", "example": null}, {"def": "斜靠,身斜", "example": null}, {"def": "席上正喧哗,不道玉人低趄。--元·王实甫《西厢记》", "example": null}, {"def": "又如趄着身子", "example": null}, {"def": "趄jū", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见qiè。", "example": null}, {"def": "趄qiè", "example": null}, {"def": "⒈倾斜～坡。～着身体。", "example": null}, {"def": "趄qiē 1.见\\"趄避\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296167383071','锔','1','jū','钅','12',NULL,'[{"def": "锔", "example": null}, {"def": "锔子", "example": null}, {"def": "锔", "example": null}, {"def": "用锔子修理", "example": null}, {"def": "锔碗儿的", "example": null}, {"def": "锔", "example": null}, {"def": "一种三价人造放射性金属元素(如用高能氦核轰击钚制得),原子序数96", "example": null}, {"def": "锔jū 1.见\\"锔子\\"。 2.用锔子补接器物。", "example": null}, {"def": "锔jú 1.化学元素。符号cm。人工获得的放射性元素。化学性质和稀土金属钆很相似。锔的某些同位素放射性极强，经常处于炽热状态，人造卫星和宇宙飞船上用它作热电源。", "example": null}, {"def": "2.焗。一种烹饪方法。利用蒸气使密闭容器中的食物变熟。", "example": null}]','chinese-xinhua','0'),
('2101143296167383072','裾','1','jū','衤','13',NULL,'[{"def": "裾", "example": null}, {"def": "衣服的前后襟", "example": null}, {"def": "裾,衣袌也。从衣,居声。--《说文》", "example": null}, {"def": "裾,衣之前襟也。今苏俗曰大襟。--《说文通训定声》", "example": null}, {"def": "楚庄王裾衣博袍。--《淮南子·齐俗》", "example": null}, {"def": "衣服的后襟", "example": null}, {"def": "古通倨”。傲慢", "example": null}, {"def": "彼浩裾自顺,不可以教下。--《晏子春秋·外篇》", "example": null}, {"def": "其流也埤下,裾拘必循其理,似义。--《荀子·宥坐》", "example": null}, {"def": "裾巴", "example": null}, {"def": "裾jū衣服的前襟，也叫大襟。〈引〉衣服的前后部分曳～而行。", "example": null}, {"def": "裾jù 1.通\\"倨\\"。傲慢。 2.通\\"据\\"。依据。", "example": null}]','chinese-xinhua','0'),
('2101143296167383073','雎','1','jū','隹','13',NULL,'[{"def": "雎", "example": null}, {"def": "(形声。从隹,短尾鸟,且声。本义雎鸠,即鱼鹰)", "example": null}, {"def": "同本义", "example": null}, {"def": "关关雎鸠,在河之洲。--《诗·周南》", "example": null}, {"def": "水名", "example": null}, {"def": "雎jū", "example": null}]','chinese-xinhua','0'),
