('2101143296167383078','鞠','1','jū','革','17',NULL,'[{"def": "鞠", "example": null}, {"def": "(形声。从革,匊声。从革”,表示与皮革有关。本义古时一种用来踢打玩耍的皮球。最早是结毛而成◇来用毛充填皮囊而成,宋代以后才有充气的皮球)", "example": null}, {"def": "同本义", "example": null}, {"def": "鞠,蹋鞠也。--《说文》", "example": null}, {"def": "蹋鞠黄帝所作或曰起战国时。--贾谊《新书》注", "example": null}, {"def": "穿域蹋鞠。--《史记·卫将军传》。索隐鞠戏以皮为之,中实以毛,蹴蹋为戏也。”", "example": null}, {"def": "又如鞠室(蹴鞠之所);鞠场(毬场);鞠戏(古代踢球的游戏);鞠院(古球场,有围墙)", "example": null}, {"def": "姓", "example": null}, {"def": "鞠", "example": null}, {"def": "弯曲,弯身", "example": null}, {"def": "鞠jū", "example": null}, {"def": "⒈养育，抚养～养。", "example": null}, {"def": "⒉〈古〉一种用来踢打的球蹴～（踢球）。", "example": null}, {"def": "⒊〈古〉通\\"鞫\\"。审讯，审问令～治之。", "example": null}, {"def": "⒋", "example": null}, {"def": "鞠qū 1.酵母。参见\\"鞠尘\\"。", "example": null}, {"def": "鞠qiōng 1.见\\"鞠穷\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296167383079','鞫','1','jū','革','18',NULL,'[{"def": "鞫", "example": null}, {"def": "审问", "example": null}, {"def": "鞫", "example": null}, {"def": "贫穷", "example": null}, {"def": "鞫哉庶正,疚哉冢宰。--《诗·大雅》", "example": null}, {"def": "穷尽", "example": null}, {"def": "鞫", "example": null}, {"def": "水涯的末端", "example": null}, {"def": "止旅乃密,芮鞫之即。--《诗·大雅》", "example": null}, {"def": "姓", "example": null}, {"def": "晋有鞫居", "example": null}, {"def": "鞫jū", "example": null}, {"def": "⒈审讯，审问～讯。", "example": null}, {"def": "⒉穷困～哉庶正（庶正指众官之长）。", "example": null}]','chinese-xinhua','0'),
