('2101143296167383081','狙','1','jū','犭','8',NULL,'[{"def": "狙", "example": null}, {"def": "猕猴", "example": null}, {"def": "众狙皆怒。--《庄子·齐物论》", "example": null}, {"def": "又如狙狯(猿猴一类的野兽);狙杙(系猴的木桩;谓猴椽木);狙猿(猿猴)", "example": null}, {"def": "狙", "example": null}, {"def": "窥伺;伏伺", "example": null}, {"def": "从狙而好小察。--《管子·七臣七主》", "example": null}, {"def": "又如狙刺(伏伺行刺);狙狙(伺察的样子);狙候(伏伺;觊觎);狙觑(窥视);狙缚(伺伏擒缚)", "example": null}, {"def": "狙", "example": null}, {"def": "狡猾", "example": null}, {"def": "狙击", "example": null}, {"def": "狙击手", "example": null}, {"def": "狙jū", "example": null}, {"def": "⒈猕猴众～皆怒。", "example": null}, {"def": "⒉窥伺，暗中观察。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296167383082','苴','1','jū','艹','8',NULL,'[{"def": "苴", "example": null}, {"def": "(形声。从苃,且声。本义鞋底的草垫,用以垫鞋底)", "example": null}, {"def": "同本义", "example": null}, {"def": "冠虽敝不以苴履。--《汉书》", "example": null}, {"def": "青麻的子实", "example": null}, {"def": "七月食瓜,八月断壶。九月叔苴,采荼薪樗,食我农夫。--《诗·幽风·七月》", "example": null}, {"def": "结子的麻,或粗黄麻布", "example": null}, {"def": "粗劣;粗恶", "example": null}, {"def": "苴麻", "example": null}, {"def": "苴jū", "example": null}, {"def": "⒈苴麻，又叫\\"种麻\\"。大麻的雌株，开花后能结果实。也指结子的麻～布。", "example": null}, {"def": "⒉枯草。", "example": null}, {"def": "⒊用草做成的鞋垫。", "example": null}, {"def": "⒋包裹。", "example": null}, {"def": "苴zhǎ 1.腐土;糟粕。 2.通\\"柤\\"。木名。", "example": null}, {"def": "苴chá 1.浮草;枯草。", "example": null}, {"def": "苴zū 1.见\\"苴秸\\"。", "example": null}, {"def": "苴bāo 1.古民族名。巴人的一支。", "example": null}, {"def": "苴xié 1.羊苴咩城，又名苴咩城。古城名。故址在今云南大理。唐代南诏国徙都于此，始建城。参阅《嘉庆一统志．云南．大理府》。", "example": null}]','chinese-xinhua','0'),
('2101143296167383083','驹','1','jū','马','8',NULL,'[{"def": "驹", "example": null}, {"def": "(形声。从马,句声。本义两岁以下的马)", "example": null}, {"def": "同本义", "example": null}, {"def": "驹,马二岁曰驹。--《说文》", "example": null}, {"def": "老马反为驹。--《诗·角弓》", "example": null}, {"def": "执驹。--《周礼·校人》", "example": null}, {"def": "武帝谓之千里驹。--《汉书·刘德传》。注年齿幼少,故谓之驹。”", "example": null}, {"def": "夫马之为草驹之时。--《淮南子·脩务》", "example": null}, {"def": "又如驹儿隙(白驹过隙。比喻人生的短促);驹阴(比喻易逝的光阴);驹隙(比喻光阴容易消逝)", "example": null}, {"def": "泛指少壮的马", "example": null}, {"def": "言秣其驹。--《诗·汉广》。传五尺以上曰驹。”", "example": null}, {"def": "乘我乘驹。--《诗·株林》。笺六尺以下曰驹。”", "example": null}, {"def": "执腾驹。--《淮南子·时则》。注", "example": null}, {"def": "驹jū", "example": null}, {"def": "⒈好马千里～。", "example": null}, {"def": "⒉", "example": null}, {"def": "驹jù 1.见\\"驹丽\\"。", "example": null}]','chinese-xinhua','0'),
