('2101143296171577366','娟','1','juān','女','10',NULL,'[{"def": "娟", "example": null}, {"def": "(形声。从女,胦声。本义美好,多指姿态美)", "example": null}, {"def": "同本义", "example": null}, {"def": "娟然如拭。--明·袁宏道《满井游记》", "example": null}, {"def": "又如娟好(秀丽);娟丽(秀丽);娟洁(秀丽,清雅);娟魄(月亮的别名);娟妩(清秀妩媚)", "example": null}, {"def": "同娟娟”。姿态柔美的", "example": null}, {"def": "美人娟娟隔秋水,濯足洞庭望八荒。--唐·杜甫《寄韩谏议注》", "example": null}, {"def": "遇一二八女郎,姿致娟娟,顾之微笑,似将有言。--《聊斋志异》", "example": null}, {"def": "同娟娟”。长曲的样子", "example": null}, {"def": "始出西南楼,纤纤如玉钩。未映东北墀,娟娟似娥眉。--鲍照诗", "example": null}, {"def": "同娟娟”。明媚貌", "example": null}, {"def": "月光娟娟,照见众齿。--鲁迅《集外集拾遗》", "example": null}, {"def": "娟juān秀丽，美好，多指姿态美～秀身材。～ ～美姿。", "example": null}]','chinese-xinhua','0'),
('2101143296171577367','捐','1','juān','扌','10',NULL,'[{"def": "捐", "example": null}, {"def": "(形声。从手,胦声。本义舍弃)", "example": null}, {"def": "同本义", "example": null}, {"def": "捐,弃也。--《说文》。按,粪除秽污谓之捐。故寺人谓之中涓。以涓为之。", "example": null}, {"def": "捐殡。--《谷梁传·宣公十八年》。注弃也。”", "example": null}, {"def": "而国无捐瘠者。--《汉书·食货志》。注骨不埋者。”孟康曰捐,谓民有饥相弃捐者,或谓贫乞者谓捐。”", "example": null}, {"def": "捐金于野。--《后汉书·列女传》", "example": null}, {"def": "捐失成功。", "example": null}, {"def": "又如捐世(弃世。人死的婉辞);捐馆(指弃房舍,死亡的婉称。也作捐馆舍”);捐身(牺牲生命);捐却(抛弃);捐灰(丢弃尘土)", "example": null}, {"def": "除去;废除", "example": null}, {"def": "捐不急之官。--《史记》", "example": null}, {"def": "捐juān", "example": null}, {"def": "⒈捐助，献出财物～献。～款。～衣～物。", "example": null}, {"def": "⒉抛弃，舍弃收～废物。为国～躯。", "example": null}, {"def": "⒊税收的名目房～。苛～杂税。", "example": null}, {"def": "⒋除去～不急之官（除去无关紧要的官）。", "example": null}]','chinese-xinhua','0'),
('2101143296171577368','涓','1','juān','氵','10',NULL,'[{"def": "涓", "example": null}, {"def": "(形声。从水,胦声。本义细小的水流)", "example": null}, {"def": "同本义", "example": null}, {"def": "涓,小流也。--《说文》", "example": null}, {"def": "涓流泱瀼。--木华《海赋》", "example": null}, {"def": "商攉涓浍。--郭璞《江赋》", "example": null}, {"def": "泉涓涓而始流。--晋·陶渊明《归去来兮辞》", "example": null}, {"def": "又如涓浍(细小的水流;卑微的地位);涓浅(指水流又细又浅);涓细(水流细小);涓尘(细水与微尘)", "example": null}, {"def": "水名", "example": null}, {"def": "源出今山东省诸城县西南,北注入潍水", "example": null}, {"def": "湘江支流。源出衡山北麓,北流至湘潭县注入湘江", "example": null}, {"def": "涓", "example": null}, {"def": "选择", "example": null}, {"def": "涓吉日,陟中坛,即帝位,改正朔。--左思《魏都赋》", "example": null}, {"def": "又如涓辰(选择吉日良辰);涓吉(选择大吉的日子);涓日(涓吉);", "example": null}, {"def": "涓juān", "example": null}, {"def": "⒈细小的水流～流。〈喻〉极少的，极微的～滴归公。", "example": null}, {"def": "⒉除去，清除～选休成（清除恶的，选取好的。休美好）。", "example": null}, {"def": "⒊选择～吉日。", "example": null}, {"def": "涓xuàn 1.泣貌。", "example": null}]','chinese-xinhua','0'),
