('2101143296171577385','诀','1','jué','讠','6',NULL,'[{"def": "诀", "example": null}, {"def": "(形声。从言,夬声。本义辞别,告别。特指长别)", "example": null}, {"def": "同本义", "example": null}, {"def": "与死者辞曰诀。--《通俗文》", "example": null}, {"def": "相诀而去。--《史记·孔子世家》", "example": null}, {"def": "与王诀曰。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "诀妻子。--《明史》", "example": null}, {"def": "梦汝来诀。--清·袁枚《祭妹文》", "example": null}, {"def": "早知诀汝。", "example": null}, {"def": "又如诀行(告别而行);诀去(话别离去);诀音(遗言);诀绝(诀别,长别)", "example": null}, {"def": "通决”。自杀", "example": null}, {"def": "帝大怒,遂赐后死,逼令引诀。--《周书·宣帝杨皇后传》", "example": null}, {"def": "未能引诀。--《隋书·薛道衡传》", "example": null}, {"def": "天元大怒,遂赐后死,逼令引诀。--《资治通鉴·陈宣帝太建十二年》", "example": null}, {"def": "诀", "example": null}, {"def": "诀jué", "example": null}, {"def": "⒈辞别，多指长别，永别与母～。～别。永～。", "example": null}, {"def": "⒉窍门，高明的办法～窍。这是秘～。她有妙～。", "example": null}, {"def": "⒊使用事物的主要内容编成顺口的便于记忆的词句编口～。写歌～。", "example": null}]','chinese-xinhua','0'),
('2101143296171577386','抉','1','jué','扌','7',NULL,'[{"def": "抉", "example": null}, {"def": "(形声。从手,夬声。本义挑出,挖出)", "example": null}, {"def": "同本义", "example": null}, {"def": "抉,挑也。--《说文》", "example": null}, {"def": "抉人之口。--《荀子》", "example": null}, {"def": "抉吾眼。--《史记·伍胥传》", "example": null}, {"def": "因自皮面抉眼,自屠出肠。--《战国策·韩策二》", "example": null}, {"def": "又如抉目(挖出眼睛);抉眼(挖出眼珠);抉耳(挖清耳朵);抉发(发掘);抉微(谓发掘事物的隐微)", "example": null}, {"def": "挑开;撬开", "example": null}, {"def": "鄖人纥抉之以出门者。--《左传·襄公十年》。注撅也。”", "example": null}, {"def": "又如抉关(撬开城门或关口的大门);抉拾(古代射箭用具。抉,即扳指,戴于右指上,用以钩弦。拾,即皮护臂)", "example": null}, {"def": "挑剔;揭发", "example": null}, {"def": "抉jué", "example": null}, {"def": "⒈挖出，挑出～眼。～择（挑选）。", "example": null}, {"def": "⒉戳穿～伤。", "example": null}]','chinese-xinhua','0'),
