('2101143296171577440','倔','1','juè','亻','10',NULL,'[{"def": "倔", "example": null}, {"def": "(形声。从人,屈声。本义顽强,固执)", "example": null}, {"def": "同本义", "example": null}, {"def": "倔强倨傲。--《盐铁论》", "example": null}, {"def": "倔强,谓强梁也。亦双声连语。--《后汉书·张李彭卢传》注", "example": null}, {"def": "又如倔僵(亦作倔彊”、倔犟”。强硬直傲,不屈于人)", "example": null}, {"def": "奇谲", "example": null}, {"def": "突出的。也作崛”", "example": null}, {"def": "蹑足行伍之间,而倔起阡陌之中。--《史记》", "example": null}, {"def": "又如倔起(突起,突然兴起)", "example": null}, {"def": "倔", "example": null}, {"def": "言语粗直,态度生硬", "example": null}, {"def": "倔juè言语粗直。态度生硬犟头～脑。", "example": null}, {"def": "倔jué", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉通\\"崛\\"。突出，高起。", "example": null}]','chinese-xinhua','0'),
('2101143296171577441','蹶','1','juě','足','19',NULL,'[{"def": "蹶", "example": null}, {"def": "(形声。从足,厥声。本义倒下,跌倒)", "example": null}, {"def": "同本义", "example": null}, {"def": "蹶,僵也。--《说文》", "example": null}, {"def": "小人之行,不蹶于山。--《吕氏春秋·慎行》", "example": null}, {"def": "处足则为萎,为蹶。--《吕氏春秋·尽数》", "example": null}, {"def": "毅恐蹶仆地。--唐·李朝威《柳毅传》。又如蹶角(额角叩地,表示恭敬诚恳);蹶踬(跌倒,颠仆);蹶躭(颠跌,奔波);蹶踣(颠仆,跌倒);蹶跌(跌倒)", "example": null}, {"def": "折损", "example": null}, {"def": "蹶上将军。--《史记·孙吴传》。索隐毙也。”", "example": null}, {"def": "又如一蹶不振;蹶衵(衰败;损伤)", "example": null}, {"def": "用一脚或双脚猛踢,尤指马、骡等动物用后腿向后踢", "example": null}, {"def": "蹶juě", "example": null}, {"def": "蹶（躡）jué", "example": null}, {"def": "⒈倒下，跌倒。〈引〉受挫折，失败一～不振。", "example": null}, {"def": "⒉踩，踏～崭岩（踏高峻的岩石）。", "example": null}, {"def": "⒊竭尽，枯竭不～。", "example": null}, {"def": "蹶guì 1.动乱;扰乱。 2.感动;感召。 3.事物改变原来的位置或脱离静止状态。", "example": null}]','chinese-xinhua','0'),
