('2101143296179965973','鲪','1','jūn','','7',NULL,'[{"def": "鲪jūn 1.鱼类的一属。体狭长，侧扁，灰褐色，有不规则黑色斑纹。口大而斜。尾鳍圆形。卵胎生。生活于近海岩礁间。", "example": null}]','chinese-xinhua','0'),
('2101143296179965974','麇','1','jūn','鹿','16',NULL,'[{"def": "麇", "example": null}, {"def": "獐子", "example": null}, {"def": "麇包(用包茅包的死獐子);麇獐(即獐子);麇窜(像獐子那样惊慌逃窜)", "example": null}, {"def": "古地名", "example": null}, {"def": "春秋时麇国之地,在今湖北省郧县西", "example": null}, {"def": "楚子代麇。--《左传》", "example": null}, {"def": "春秋时楚邑,在今湖南省岳阳东南", "example": null}, {"def": "楚王使由于城麇。--《左传》", "example": null}, {"def": "麇  qun", "example": null}, {"def": "成群", "example": null}, {"def": "求诸侯而麇至。--《左传·昭公五年》。杜预注麇,群也。”", "example": null}, {"def": "又如麇聚(麇集);麇至(成群而来);", "example": null}, {"def": "麇jūn", "example": null}, {"def": "⒈〈古〉指獐子。", "example": null}, {"def": "⒉见qún。", "example": null}, {"def": "麇（麕）qún", "example": null}, {"def": "⒈成群～集。", "example": null}, {"def": "麇kǔn 1.捆绑。", "example": null}]','chinese-xinhua','0'),
