('2101143296179966002','暟','1','kǎi','','12',NULL,'[{"def": "暟kǎi 1.《方言》第十三\\"暟，美也。\\"《广雅．释诂三》\\"暟，照也。\\"亦用于人名。", "example": null}]','chinese-xinhua','0'),
('2101143296179966003','锴','1','kǎi','钅','14',NULL,'[{"def": "锴", "example": null}, {"def": "好铁", "example": null}, {"def": "铜锴之垠。--《文选·左思·吴都赋》", "example": null}, {"def": "又如锴铁(好铁)", "example": null}, {"def": "铁的别称", "example": null}, {"def": "锴,铁也。九江谓铁曰锴。--《说文》", "example": null}, {"def": "锴kǎi好铁。多见于人名。", "example": null}, {"def": "锴jiē 1.精铁。", "example": null}]','chinese-xinhua','0'),
('2101143296179966004','凯','1','kǎi','几','8',NULL,'[{"def": "凯", "example": null}, {"def": "(会意,从豰,从几。几”象架子。字本作豰”,也作愷”。从豆,省声。本义军队得胜所奏的乐曲) 同本义", "example": null}, {"def": "豰,还师振旅乐也。--《说文》。按,经传多以愷为之。亦作刾。", "example": null}, {"def": "凯以强教之。即以豰胜豰乐为训。--《礼记·表记》", "example": null}, {"def": "汔可休而凯归。--左思《吴都赋》", "example": null}, {"def": "则令奏恺乐。--《周礼·大司乐》。注献功之乐。”", "example": null}, {"def": "恺乐献于社。--《周礼·大司马》。注兵乐曰恺。”", "example": null}, {"def": "振旅恺以入于晋。--《左传·僖公二十八年》。注乐也。”", "example": null}, {"def": "六军张凯声如雷。--刘克庄《破阵曲》", "example": null}, {"def": "又如凯入(奏着胜利的乐曲归来);", "example": null}, {"def": "凯（刾）kǎi", "example": null}, {"def": "⒈军队打胜仗后所奏的乐曲～歌。～旋（得胜归来）荣归。六军张～声如雷。", "example": null}, {"def": "⒉〈古〉通\\"恺\\"。欢乐～乐。", "example": null}]','chinese-xinhua','0'),
('2101143296179966005','剀','1','kǎi','刂','8',NULL,'[{"def": "剀", "example": null}, {"def": "(形声。从刀,豰声。本义大镰) 同本义", "example": null}, {"def": "剀,大镰也。切地以芟刈者,亦名鉪。字亦作鐖。--《说文》", "example": null}, {"def": "鐖凿棘矜也。--《史记·淮南衡山传》", "example": null}, {"def": "剀", "example": null}, {"def": "磨,磨刀", "example": null}, {"def": "剀…一曰摩也。--《说文》", "example": null}, {"def": "剀,磨也。--《广雅》", "example": null}, {"def": "规劝,讽喻", "example": null}, {"def": "言古以剀今,讽刺也。--《周礼》注", "example": null}, {"def": "又如言古以剀今;剀拂(劝戒匡正);剀讽(讽喻)", "example": null}, {"def": "杀;砍", "example": null}, {"def": "郡王这里是帝辇之下…如何胡乱剀得人?--《警世通言》", "example": null}, {"def": "剀", "example": null}, {"def": "中肯,切实", "example": null}, {"def": "其辞恳直剀。--《元史·朵罗台传》", "example": null}, {"def": "又如剀直(恳切直率);剀切(与事理完全", "example": null}, {"def": "剀（剴）kǎi", "example": null}, {"def": "⒈讽喻，以此喻彼～讽。", "example": null}, {"def": "⒉确实，切实～晓大义。", "example": null}, {"def": "⒊", "example": null}, {"def": "①切实～切开导。", "example": null}, {"def": "②与事理相符合～切中理。～切详明。", "example": null}, {"def": "剀ái 1.捱，挨。", "example": null}]','chinese-xinhua','0'),
('2101143296179966006','垲','1','kǎi','土','9',NULL,'[{"def": "垲", "example": null}, {"def": "地势高而干燥的", "example": null}, {"def": "请更诸爽垲者。--《左传·昭公三年》", "example": null}, {"def": "又如垲垲(干燥的样子)", "example": null}, {"def": "垲（塶）kǎi地势高而且干燥。", "example": null}]','chinese-xinhua','0'),
('2101143296179966007','恺','1','kǎi','忄','9',NULL,'[{"def": "恺", "example": null}, {"def": "(形声。从心,豰声。本义欢乐,和乐)", "example": null}, {"def": "同本义", "example": null}, {"def": "恺,乐也。--《说文》。按,豰,愷实同一字。", "example": null}, {"def": "中心物恺。--《庄子·天道》。又如恺悌(和乐平易,平易近人。也作恺弟,岂弟);恺恻(和乐恻隐);恺豫(和乐)", "example": null}, {"def": "明", "example": null}, {"def": "夫不勤勤则前人不当,不恳恳则觉德不恺。--《文选·扬雄·剧秦美新》", "example": null}, {"def": "恺", "example": null}, {"def": "假借为凯”。军队胜利后所奏之乐", "example": null}, {"def": "王师大献,则令奏恺乐。--《周礼·大司乐》。郑玄注恺乐,献功之乐。”", "example": null}, {"def": "秋七月丙申,振旅,恺以入于晋。--《左传·僖公二十八年》。杜预注", "example": null}, {"def": "恺（愷）kǎi", "example": null}, {"def": "⒈欢乐，和乐大～。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊〈古〉通\\"凯\\"奏～。", "example": null}]','chinese-xinhua','0'),
('2101143296179966008','闿','1','kǎi','','8',NULL,'[{"def": "闿（阦）kǎi", "example": null}, {"def": "⒈开。", "example": null}, {"def": "⒉通\\"恺\\"。欢乐。", "example": null}]','chinese-xinhua','0'),
('2101143296179966009','铠','1','kǎi','钅','11',NULL,'[{"def": "铠", "example": null}, {"def": "(形声。从金,豰声。本义用以护身的铠甲战衣)同本义(用金属薄片缀成)", "example": null}, {"def": "铠,甲也。--《说文》。段注古曰甲,汉人曰铠。”", "example": null}, {"def": "古用皮,谓之甲,今用金,谓之铠。--《周礼·考士记》疏", "example": null}, {"def": "禁民不得挟弩铠。--《汉书·王莽传》", "example": null}, {"def": "其铠胄精良。--《新唐书·吐蕃传》", "example": null}, {"def": "铠胄皆镔铁。--《阎典史传》", "example": null}, {"def": "又如铠马(铠甲和战马。披有铠甲的战马。也称铁马”);铠骑(穿铠甲的骑兵);铠胄(铠甲和头盔);铠袄(铠甲袍袄)", "example": null}, {"def": "铠甲", "example": null}, {"def": "铠衣", "example": null}, {"def": "铠（鎧）kǎi〈古〉打仗时穿的一种护身战衣，上面缀有金属片～甲。铁～。", "example": null}]','chinese-xinhua','0'),
('2101143296179966010','慨','1','kǎi','忄','12',NULL,'[{"def": "慨〈形〉", "example": null}, {"def": "(形声。从心,既声。本义不得志而愤激)", "example": null}, {"def": "同本义", "example": null}, {"def": "慨,忼慨壮士不得志也。--《说文》", "example": null}, {"def": "副将军史德威慨然任之。--清·全祖望《梅花岭记》", "example": null}, {"def": "又如愤慨;慨切(愤激而恳切);慨爽(慷慨爽朗);慨慷(情绪激昂)", "example": null}, {"def": "疲惫的样子", "example": null}, {"def": "慨焉如不及,其反而息。--《礼记·檀弓下》。注慨,惫貌。”", "example": null}, {"def": "慨", "example": null}, {"def": "假借为嘅”。感慨,叹息(因悲痛、不愉快而发出的叹息)", "example": null}, {"def": "情慨慨而长怀兮。--《楚辞·怨思》。注叹貌。”", "example": null}, {"def": "慨长思而怀古。--《文选·张衡·东京赋》", "example": null}, {"def": "慨含唏", "example": null}, {"def": "慨（", "example": null}, {"def": "⒈嘅）kǎi", "example": null}, {"def": "⒈叹息，叹气，感叹～叹。感～。深自～失。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "①感慨的～然咏怀。", "example": null}, {"def": "②情绪激昂的～然承诺。～然有矫世变俗之志（矫世矫正世道）。", "example": null}]','chinese-xinhua','0'),
('2101143296179966011','蒈','1','kǎi','艹','12',NULL,'[{"def": "蒈〈名〉", "example": null}, {"def": "有机化合物蒈烷的简称,分子式c10h18", "example": null}, {"def": "蒈kǎi人工制造的有机化合物。它的重要衍生物蒈酮，气味像樟脑。", "example": null}]','chinese-xinhua','0'),
('2101143296179966012','楷','1','kǎi','木','13',NULL,'[{"def": "楷〈名〉kai", "example": null}, {"def": "(形声。从木,皆声。 ①本义木名。即黄连木”。楷树枝干疏而不屈,因以形容刚直 ②法式,典范)", "example": null}, {"def": "法式,典范", "example": null}, {"def": "楷,法也。--《广雅》", "example": null}, {"def": "今世行之,后世以为楷。--《礼记·儒行》", "example": null}, {"def": "又如楷法(法则;典范);楷栻(同楷式”);楷素(楷模);为此所楷", "example": null}, {"def": "楷书『字形体之一,由隶书演变而来,也叫正书”,真书”", "example": null}, {"def": "姓", "example": null}, {"def": "jie", "example": null}, {"def": "楷树", "example": null}, {"def": "楷jiē", "example": null}, {"def": "⒈楷树，又叫\\"黄连木\\"。落叶乔木，羽状复叶，雌雄异株。果实近球形，红色或紫兰色。种子可榨油、可制肥皂或作润滑剂。木材可供建筑、制器具用。树皮和叶可提制栲胶。", "example": null}, {"def": "⒉见kǎi。", "example": null}, {"def": "楷kǎi", "example": null}, {"def": "⒈法式，典范～模。", "example": null}, {"def": "⒉楷书，也叫\\"正书\\"、\\"真书\\"。是现今通行的一种汉字字体，形体方正，笔画平直，由隶书演变而来写正～字。", "example": null}, {"def": "⒊见jiē。", "example": null}]','chinese-xinhua','0'),
('2101143296221908992','锎','1','kāi','钅','12',NULL,'[{"def": "锎", "example": null}, {"def": "用α粒子轰击锔-242而发现的一种放射性元素", "example": null}, {"def": "锎kāi 1.放射性金属元素。符号cf。是用甲种粒子轰击质量数为242的锔制得的。", "example": null}]','chinese-xinhua','0'),
('2101143296221908993','开','1','kāi','廾','4',NULL,'[{"def": "开", "example": null}, {"def": "(会意。小篆字形,两边是两扇门,中间一横是门闩,下面是一双手,表示两手打开门闩之意。本义开门)", "example": null}, {"def": "同本义", "example": null}, {"def": "開,张也。--《说文》", "example": null}, {"def": "天门开阖。--《老子》十章", "example": null}, {"def": "善闭,无关楗而不可开。--《老子》", "example": null}, {"def": "开物成务。--《易·系辞上》", "example": null}, {"def": "开我东阁门。--《乐府诗集·木兰诗》", "example": null}, {"def": "遂开门纳众。--《资治通鉴·唐记》", "example": null}, {"def": "开轩面场圃。--唐·孟浩然《过故人庄》", "example": null}, {"def": "午后又开西门归德门。--《广东军务记》", "example": null}, {"def": "又如开城(打开城门);开门钱(男家迎亲的轿子到女家,女家开门前索取的钱财)", "example": null}, {"def": "打开,开启", "example": null}, {"def": "微子开封于宋。--《荀", "example": null}, {"def": "开（開）kāi", "example": null}, {"def": "⒈跟\\"关\\"相对。把关着的东西打开～门。～窗。～锁。〈引〉", "example": null}, {"def": "①放散，张开百花盛～。笑逐颜～。～口讲话。", "example": null}, {"def": "②化整体为部分六十四～本。", "example": null}, {"def": "③凝合物融化～冻（解冻）。", "example": null}, {"def": "门、电键。", "example": null}, {"def": "⒉发掘，辟出，使显露出来～发。～辟。～煤矿。～荒山。～采黄金。", "example": null}, {"def": "⒊发动，发放，操纵～火车。～枪。～炮。～动机器。", "example": null}, {"def": "⒋起始～始。～头。～学。～春。", "example": null}, {"def": "⒌创立，建立，设置～创。～拓创新。～建。～国（建立新国家）大典。", "example": null}, {"def": "⒍举行～会讨论。～学典礼。", "example": null}, {"def": "⒎揭示，表明～诚布公。～宗明义。", "example": null}, {"def": "⒏通，启发，使通～通。～导。～窍。～路先锋。", "example": null}, {"def": "⒐列举，列出～清单。计～。〈引〉逐个付出～支。～销。", "example": null}, {"def": "⒑清除，革除～除。", "example": null}, {"def": "⒒摆脱～脱。", "example": null}, {"def": "⒓沸，滚喝～水。汤～了。", "example": null}, {"def": "⒔分离，分配分～。离～。三七～。", "example": null}, {"def": "⒕写～处方。～收据。", "example": null}, {"def": "⒖扩大，发展～拓。～展。～源节流。", "example": null}, {"def": "⒗广阔，爽朗，乐观～阔。～朗。", "example": null}, {"def": "⒘用在动词后面，〈表〉效果走～。传～了。打～窗户。张～嘴巴。睁～眼睛。放～双手。", "example": null}, {"def": "⒙〈外〉黄金的纯度单位，二十四～为纯金。⒚热力学温度单位\\"开尔文\\"的简称，符号k。⒛", "example": null}]','chinese-xinhua','0'),
('2101143296221908994','揩','1','kāi','扌','12',NULL,'[{"def": "揩〈动〉", "example": null}, {"def": "(形声。从手,皆声。本义擦抹;摩擦) 同本义", "example": null}, {"def": "揩,摩也。--《字林》", "example": null}, {"def": "揩,磨也。--《广雅》", "example": null}, {"def": "揩枳落,突棘藩。--张衡《西京赋》", "example": null}, {"def": "我方坐垢难磨揩。--梅尧臣《送方进士游庐山》", "example": null}, {"def": "又如揩锉(摩擦);揩面(洗脸;擦脸);揩磨(琢磨);揩背(揩擦背部);揩痒(在固定的硬物上摩擦以解痒);揩抹(擦去;抹去);把桌子揩干净;揩免(抹去)", "example": null}, {"def": "揩kāi擦，抹～桌椅。～眼泪。～油（占便宜）。", "example": null}, {"def": "揩jiá 1.见\\"揩击\\"。", "example": null}]','chinese-xinhua','0'),
