('2101143296226103319','刊','1','kān','刂','5',NULL,'[{"def": "刊", "example": null}, {"def": "(形声。从刀,干声。本义砍,砍削)", "example": null}, {"def": "同本义", "example": null}, {"def": "刊,剟也。--《说文》", "example": null}, {"def": "刊,削也。--《广雅》", "example": null}, {"def": "刊阳木而火之。--《周礼·柞氏夏日至令》。注谓斫去次地之皮。”", "example": null}, {"def": "刊其柄与末。--《礼记·杂记》。注犹削也。”", "example": null}, {"def": "随山刊木。--《书·益稷》", "example": null}, {"def": "又如刊山(砍伐山上树木);刊木(砍伐树木);刊藄(砍伐割除草木)", "example": null}, {"def": "删除", "example": null}, {"def": "诚不刊之典。--晁公武《郡斋读书志》", "example": null}, {"def": "又如刊落(删去冗赘多余的文字);刊削(削除);刊删(删改);刊革(删改);刊除(削除)", "example": null}, {"def": "刻;雕刻", "example": null}, {"def": "刊石作铭。--蔡邕《陈寔碑》", "example": null}, {"def": "重木刊凿之。--《仪礼", "example": null}, {"def": "刊kān", "example": null}, {"def": "⒈原指刻，雕刻。转化为排印出版～印。～石。～登。～载。创～。发～。停～。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊砍，削，修改～除。～误。～正。", "example": null}]','chinese-xinhua','0'),
('2101143296226103320','栞','1','kān','','12',NULL,'[{"def": "栞kān 1.砍，削除。 2.修订，修改。 3.刻，雕刻。 4.识，记。", "example": null}]','chinese-xinhua','0'),
('2101143296226103321','勘','1','kān','力','11',NULL,'[{"def": "勘〈动〉", "example": null}, {"def": "(形声。从力,甚声。本义校订,核对)", "example": null}, {"def": "同本义(考订核实异同)", "example": null}, {"def": "勘,校也。--《说文新附》", "example": null}, {"def": "每获一书,即共同勘校。--李清照《金石录后序》", "example": null}, {"def": "又如勘合(验证,核对。文书上加盖印信,一分为二,当事双方各执一半,作为凭证);勘对(核对;注定);勘婚(婚前男女两家互相查考生辰八字、门第等)", "example": null}, {"def": "审问", "example": null}, {"def": "当堂对勘。--《聊斋志异》", "example": null}, {"def": "又如勘正(审问核实);勘问(盘问;审问);勘鞠(审讯);勘当(审问核察)", "example": null}, {"def": "查看;调查", "example": null}, {"def": "又推勘妖魔作怪之由。--洪仁玕《太平天日》", "example": null}, {"def": "又如勘灾(查看灾情);勘破(看破)", "example": null}, {"def": "勘kān", "example": null}, {"def": "⒈校订，核对仔细校～。认真～正。～误表。", "example": null}, {"def": "⒉调查，探测～查。前去～探。～测完毕。", "example": null}]','chinese-xinhua','0'),
('2101143296226103322','龛','1','kān','龙','11',NULL,'[{"def": "龛", "example": null}, {"def": "(形声。从龙,合声。本义龙的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "龛,龙貌也。--《说文》", "example": null}, {"def": "小窟或小屋", "example": null}, {"def": "供奉佛像或神位的石室或小阁", "example": null}, {"def": "庄严龛像,首于西峰石壁。--江总《摄山栖霞寺碑》", "example": null}, {"def": "又如壁龛;龛火(壁龛中 灯火);龛牖(窗形的石龛);龛座(放神主的小室);龛像(壁龛中的佛像)", "example": null}, {"def": "盛放神圣物品的盒子", "example": null}, {"def": "塔,塔下室", "example": null}, {"def": "倘经三祖寺,一为礼龛坟。--贯休《送人旧夏口》", "example": null}, {"def": "又如龛室(寺塔下的小室或龛中的小室)", "example": null}, {"def": "龛", "example": null}, {"def": "容纳;盛", "example": null}, {"def": "龛（龕）kān", "example": null}, {"def": "⒈迷信的人供奉佛像、神像的石室或小阁子神～已成古物。", "example": null}, {"def": "⒉佛塔。", "example": null}, {"def": "⒊〈古〉通\\"戡\\"。平定。", "example": null}]','chinese-xinhua','0'),
('2101143296226103323','堪','1','kān','土','12',NULL,'[{"def": "堪〈名〉", "example": null}, {"def": "(形声。从土,甚声。本义地面高起)", "example": null}, {"def": "同本义", "example": null}, {"def": "堪,地突也。谓土之坟起者。--《说文》", "example": null}, {"def": "堪坏得之,以袭昆仑。--《庄子·大宗师》", "example": null}, {"def": "又如堪岩(山形幽深)", "example": null}, {"def": "指天道", "example": null}, {"def": "堪舆徐行。雄以音知雌。--《淮南子·天文》。许君注堪,天道,舆,地道。盖堪为高处,舆为下处。天高地下之义也。”", "example": null}, {"def": "屡堪舆以壁垒兮。--扬雄《甘泉赋》。注天地总名也。”", "example": null}, {"def": "倏然堪舆变。--陆龟蒙、皮日休《开元寺楼看雨联句》", "example": null}, {"def": "又如堪舆(天地;风水,亦指风水先生);堪舆家(古时为占候卜筮者之一种,后专称以相地看风", "example": null}, {"def": "堪kān", "example": null}, {"def": "⒈忍受，经得起难～。不～回首。疲惫不～。", "example": null}, {"def": "⒉能够，可以～当重任。不～设想。真～托生死。", "example": null}]','chinese-xinhua','0'),
('2101143296226103324','戡','1','kān','戈','13',NULL,'[{"def": "戡〈动〉", "example": null}, {"def": "(形声。从戈,甚声。本义刺杀)", "example": null}, {"def": "同本义", "example": null}, {"def": "戡,刺也。--《说文》。字亦作勘。", "example": null}, {"def": "西伯既戡黎。--《书·西伯戡黎》", "example": null}, {"def": "用武力平定", "example": null}, {"def": "戡,克也。--《尔雅》", "example": null}, {"def": "兴元戡难功。--《旧唐书·陆贽传》", "example": null}, {"def": "又如戡夷(平定,征讨使服从);戡平叛乱;戡殄(平定歼灭);戡复(犹言中兴。平定叛乱);戡剪(平定剪除);戡戮(平定诛戮);戡济(戡定。平定)", "example": null}, {"def": "戡乱", "example": null}, {"def": "戡kān攻克，平定～难。～乱。", "example": null}]','chinese-xinhua','0'),
('2101143296226103325','扛','1','kánɡ','扌','6',NULL,'[{"def": "扛  gang", "example": null}, {"def": "用两手举重物", "example": null}, {"def": "扛,横关对举也。--《说文》。字亦作掆.", "example": null}, {"def": "两人对举为扛。--《后汉书·费长房传》注", "example": null}, {"def": "翘关扛鼎。--左思《吴都赋》", "example": null}, {"def": "扛,举也。--《广雅》", "example": null}, {"def": "力能扛鼎,才气过人。--《史记·项羽本纪》", "example": null}, {"def": "又如扛鼎(举鼎);扛舁(举抬)", "example": null}, {"def": "两人或两人以上共抬一物", "example": null}, {"def": "磕;碰", "example": null}, {"def": "阻拦", "example": null}, {"def": "横架", "example": null}, {"def": "这时城门已经上", "example": null}, {"def": "扛gāng", "example": null}, {"def": "⒈使用两手举起东西力能～鼎。", "example": null}, {"def": "⒉〈方〉抬（东西）。\\"扛\\"另见káng。", "example": null}, {"def": "扛káng", "example": null}, {"def": "⒈用肩承担～枪。～货。～活（旧时指做长工）。", "example": null}, {"def": "⒉见gāng。", "example": null}]','chinese-xinhua','0'),
('2101143296226103326','亢','1','kànɡ','亠','4',NULL,'[{"def": "亢〈形〉", "example": null}, {"def": "(象形。小篆字形,从大(人)省,象人的颈脉形 ①本义人颈的前部,喉咙 ②高)", "example": null}, {"def": "高", "example": null}, {"def": "故解之以牛之白颡者与豚之亢鼻者。--《庄子·人间世》", "example": null}, {"def": "又如亢爽(天高气爽;性格直爽);亢山(高山);亢言(高谈阔论);亢昂(高昂;激扬)", "example": null}, {"def": "刚强", "example": null}, {"def": "恕在朝八年,其议论亢直,皆此类也。--《三国志·杜恕传》", "example": null}, {"def": "又如亢烈(刚毅);亢亮(刚直诚信);亢悍(刚烈强悍);亢藏(刚直孤僻)", "example": null}, {"def": "自高,无所屈", "example": null}, {"def": "信明蹇亢,以门望自负。--《新唐书·文艺传上》", "example": null}, {"def": "又如亢世(傲世);亢意(言恣意妄为);亢龙(本指骄横无德之君。借指热衷功名,铡愎躁进之人)", "example": null}, {"def": "亢kàng", "example": null}, {"def": "⒈高高～。〈引〉高傲不卑不～。", "example": null}, {"def": "⒉极，非常～旱（大旱）连年。", "example": null}, {"def": "⒊遮蔽，庇护～身。", "example": null}, {"def": "⒋〈古〉通\\"抗\\"。抵御，抵抗～敌。", "example": null}, {"def": "⒌星宿名。二十八宿之一。", "example": null}, {"def": "亢gāng 1.咽喉，喉咙。", "example": null}, {"def": "亢gēng 1.用于人名。", "example": null}]','chinese-xinhua','0'),
('2101143296226103327','伉','1','kànɡ','亻','6',NULL,'[{"def": "伉〈动〉", "example": null}, {"def": "(形声。从人,亢声。本义匹敌,相当)", "example": null}, {"def": "同本义", "example": null}, {"def": "天下莫之能伉。--《战国策·秦策一》", "example": null}, {"def": "已不能庇其伉俪。--《左传·成公十一年》。注敌也。”", "example": null}, {"def": "弃其伉俪妃嫔。--《国语·周语》。注对也。”", "example": null}, {"def": "可与乎比伉。--《后汉书·张衡传》。注偶也。”", "example": null}, {"def": "又如伉合(匹敌相等而配合)", "example": null}, {"def": "对敌,抵挡", "example": null}, {"def": "养及亲者,身伉其难。--《吕氏春秋·士节》", "example": null}, {"def": "又如伉礼(彼此以平等的礼节相对待。同抗礼”);伉衡(势均力敌,不相上下。同抗衡”)", "example": null}, {"def": "伉", "example": null}, {"def": "高大,高尚", "example": null}, {"def": "乃立皋门,皋门有伉。", "example": null}, {"def": "伉kàng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉强健，刚直～健。～直。", "example": null}, {"def": "⒊〈古〉通\\"抗\\"。抵御。", "example": null}, {"def": "⒋〈古〉通\\"亢\\"。高。", "example": null}, {"def": "伉gāng 1.质直;刚直。", "example": null}]','chinese-xinhua','0'),
