('2101143296226103334','闶','1','kānɡ','门','7',NULL,'[{"def": "闶", "example": null}, {"def": "门高。引申为高大", "example": null}, {"def": "高门有闶。--张衡《西京赋》", "example": null}, {"def": "又如闶门(高大的门庭);闶闳(高大的门框)", "example": null}, {"def": "闶kāng〈形〉门高大的样子＞诗曰∶\\"古公草创而高门～，宣王中兴而筑室百堵。\\"", "example": null}, {"def": "闶kàng 1.高大貌。 2.门限。", "example": null}]','chinese-xinhua','0'),
('2101143296226103335','康','1','kānɡ','广','11',NULL,'[{"def": "康", "example": null}, {"def": "(会意。康为穅的本字。从禾,康声。本义谷皮;米糠)", "example": null}, {"def": "同本义", "example": null}, {"def": "康,谷皮也。--《说文》。字亦作穅。", "example": null}, {"def": "尘垢粃穅。--《庄子·逍遥游》", "example": null}, {"def": "亦食穅何覈耳。--《汉书·陈平传》", "example": null}, {"def": "播康迷目。--《庄子·天运》", "example": null}, {"def": "五路通达的大路,泛指大路", "example": null}, {"def": "五达谓之康,六达谓之庄。--《尔雅》", "example": null}, {"def": "公驱及之康内。--《晏子春秋·内篇谏上》", "example": null}, {"def": "微服游于康衢。--《列子·仲尼》", "example": null}, {"def": "姓", "example": null}, {"def": "康", "example": null}, {"def": "安乐,安定", "example": null}, {"def": "民康乐。--《礼记·乐记》", "example": null}, {"def": "无己大康,职思其居。--《诗·唐风·蟋蟀》", "example": null}, {"def": "上下和洽,海内康平。--《汉书", "example": null}, {"def": "康kāng", "example": null}, {"def": "⒈平安,安乐,强讲～。～乐。～强。健～。", "example": null}, {"def": "⒉富裕，丰富值此～年。达到小～。", "example": null}, {"def": "⒊空，空虚～瓠瓜。～萝卜。", "example": null}, {"def": "⒋［康庄］宽阔平坦的～庄大道（〈喻〉美好光明的前途）。", "example": null}, {"def": "康kàng 1.举。", "example": null}]','chinese-xinhua','0'),
