('2101143296226103352','考','1','kǎo','聅','6',NULL,'[{"def": "考", "example": null}, {"def": "(形声。从老省,丂声。按甲骨文、金文均象偻背老人扶杖而行之状,与老同义。本义老,年纪大)同本义", "example": null}, {"def": "考,老也。--《说文》", "example": null}, {"def": "富贵寿考。--《新唐书》", "example": null}, {"def": "又如考寿(长寿);考终(考终年);考终年(享尽天年)", "example": null}, {"def": "考", "example": null}, {"def": "去世的父亲", "example": null}, {"def": "父为考。--《尔雅》", "example": null}, {"def": "考妣延年。--《苍颉篇》", "example": null}, {"def": "有子考无咎。--《易·蛊》", "example": null}, {"def": "奔走事厥考厥长。--《书·酒诰》", "example": null}, {"def": "生曰父,死曰考。--《礼记·曲礼》", "example": null}, {"def": "考庙、王考庙、皇考庙、显考庙、祖考庙。--《礼记·祭法》", "example": null}, {"def": "五曰考终命。--《书·洪范》。按,考者,有子孙为后之称。", "example": null}, {"def": "朕皇", "example": null}, {"def": "考（", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊攷）kǎo", "example": null}, {"def": "⒈试验，测验期末～试。～数学。", "example": null}, {"def": "⒉检查～察。～核。查～。～政绩。", "example": null}, {"def": "⒊推求，研究～古学。有待～证。～究（又指\\"讲究\\"、\\"精美\\"）。", "example": null}, {"def": "⒋老，年纪大寿～。", "example": null}, {"def": "⒌原指父亲，后称死去的父亲如丧～妣（妣母亲）。先～。", "example": null}, {"def": "⒍完成，落成。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
('2101143296226103353','拷','1','kǎo','扌','9',NULL,'[{"def": "拷〈动〉", "example": null}, {"def": "(形声。从手,考声。本义打;拷打) 同本义", "example": null}, {"def": "不听非法拷人。--《魏书·刑罚志》", "example": null}, {"def": "又如拷较(拷问刑讯);拷讯(拷打审问);拷究(拷打审问);拷掠(拷打逼供);拷勘(拷问)", "example": null}, {"def": "拷kǎo", "example": null}, {"def": "⒈打～问。", "example": null}, {"def": "⒉拷绸，一种涂上薯莨汁液的丝织品，简称\\"拷\\"香云～。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296226103354','栲','1','kǎo','木','10',NULL,'[{"def": "栲〈名〉", "example": null}, {"def": "木名。即山樗。常绿乔木,叶子长圆状,披针形,果实球形,表面有短刺,木材坚硬细密,可做轮轴等,树皮含鞣酸,可制染料与栲胶", "example": null}, {"def": "山有栲,隰有杻。--《诗·唐风·山有枢》", "example": null}, {"def": "指栲胶", "example": null}, {"def": "栲栳", "example": null}, {"def": "只见那小猴子挽着个柳笼栲栳在手里,籴米归来。--《水浒传》", "example": null}, {"def": "栲栳圈像笆斗那样的圆圈", "example": null}, {"def": "栲kǎo", "example": null}, {"def": "⒈栲树，常绿乔木，雌雄同株。木材坚硬，适于做船橹、轮轴等，也供建筑、做枕木等用。树皮含鞣酸，可制烤胶或做染料。种子可吃。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
