('2101143296226103374','缂','1','kè','纟','12',NULL,'[{"def": "缂", "example": null}, {"def": "织纬", "example": null}, {"def": "缂丝", "example": null}, {"def": "刻丝”,最早产生在我国宋代", "example": null}, {"def": "缂kè缂丝，又作\\"刻丝\\"。是我国特有的一种丝织的手工艺品。在织纬线时，留出需织各种花纹的地方，然后用有色丝线补织上去，致使花纹像雕刻出来的一样。", "example": null}]','chinese-xinhua','0'),
('2101143296226103375','克','1','kè','十','7',NULL,'[{"def": "克", "example": null}, {"def": "(象形。甲骨文字形,下面象肩形。整个字形,象人肩物之形。本义胜任)", "example": null}, {"def": "同本义", "example": null}, {"def": "克,肩也。--《说文》。按,以肩任物曰克。物高于肩,故从高省,下象肩形。古文亦象肩形。", "example": null}, {"def": "佛时仔肩。--《诗·周颂·敬之》。传仔肩,克也。”", "example": null}, {"def": "子克家。--《易·蒙》", "example": null}, {"def": "邾子克。--《左传·隐公元年》", "example": null}, {"def": "周王子克。--《左传·桓公十八年》", "example": null}, {"def": "伐柯如何?匪斧不克。--《诗·豳风·伐柯》", "example": null}, {"def": "克勤于邦,克俭于家。--《书·大禹谟》", "example": null}, {"def": "又如克当(担当,承受);克堪(胜利);克家(能承担家事);克祚(能继承祖辈的福禄);克家子(克家儿。能继承祖业", "example": null}, {"def": "克（", "example": null}, {"def": "⒈至", "example": null}, {"def": "⒋剋、", "example": null}, {"def": "⒈至", "example": null}, {"def": "⒋尅）kè", "example": null}, {"def": "⒈攻破，战胜连～数城。～敌制胜。", "example": null}, {"def": "⒉制伏，抑制～服。～制。奉公～己。", "example": null}, {"def": "⒊约定或限定（时间）～日起程。～期完成。", "example": null}, {"def": "⒋通\\"刻\\"。雕刻，苛刻～画。性俭～。", "example": null}, {"def": "⒌能够～勤～俭。～尽职责。", "example": null}, {"def": "⒍消化～食。", "example": null}, {"def": "⒎公制重量单位，旧称\\"公分\\"。一千克为一公斤。", "example": null}, {"def": "⒏藏族地区的容量单位，一克青稞约为二十五市斤。也是土地的面积单位，一克约为一市亩。", "example": null}, {"def": "克kēi 1.训斥;狠狠批评。 2.方言。抠取。", "example": null}]','chinese-xinhua','0'),
('2101143296226103376','刻','1','kè','刂','8',NULL,'[{"def": "刻〈动〉", "example": null}, {"def": "(形声。从刀,亥声。本义雕刻,在木头上雕刻)", "example": null}, {"def": "同本义", "example": null}, {"def": "刻,镂也。--《说文》", "example": null}, {"def": "金谓之镂,木谓之刻。--《尔雅·释器》", "example": null}, {"def": "器不刻镂。--《礼记·哀公问》", "example": null}, {"def": "二十四年春,刻其桷,皆非礼也。--《左传·庄公二十四年》", "example": null}, {"def": "又", "example": null}, {"def": "刻桓宫桷。", "example": null}, {"def": "泛指在各种材料上的雕刻", "example": null}, {"def": "用胶泥刻字,旋刻之。--宋·沈括《梦溪笔谈·活板》", "example": null}, {"def": "是日观道中石刻,其远方刻尽漫失。--清·姚鼐《登泰山记》", "example": null}, {"def": "右刻山高月小水落石出,左刻清风徐来水波不兴。--明·魏学洢《核舟记》", "example": null}, {"def": "又如刻图章;刻刀(雕刻所用的刀具);刻木(在木质器物上雕刻);刻饰(雕刻装", "example": null}, {"def": "刻kè", "example": null}, {"def": "⒈雕，刀子挖，铁笔划雕～。刀～。～蜡纸。", "example": null}, {"def": "⒉苛求，虐待，不厚道尖酸～薄≤苛～。他待人太～。", "example": null}, {"def": "⒊时间单位。十五分钟为一～。", "example": null}, {"def": "⒋时候此～。片～。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍刻苦]", "example": null}, {"def": "①不怕难，吃得苦～苦学习。", "example": null}, {"def": "②俭朴他生活很～苦。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏通\\"剋\\"。约定或限定（时间）～日决战。", "example": null}]','chinese-xinhua','0'),
