('2101143296226103393','苛','1','kē','艹','8',NULL,'[{"def": "苛〈名〉", "example": null}, {"def": "(形声。本义小草)", "example": null}, {"def": "同本义", "example": null}, {"def": "苛,小草也。--《说文》", "example": null}, {"def": "疥疮", "example": null}, {"def": "疾痛苛痒。--《礼记·内则》", "example": null}, {"def": "又如苛痒(疥疮痒)", "example": null}, {"def": "病。通疴”", "example": null}, {"def": "其形安而不移,能守一而弃万苛。--《管子·内业》", "example": null}, {"def": "身无苛殃。--《吕氏春秋·审时》。注病也。”", "example": null}, {"def": "又如苛殃(疾病和灾患);苛疾(疾病)", "example": null}, {"def": "苛 〈形〉", "example": null}, {"def": "繁杂,烦琐", "example": null}, {"def": "好苛礼。--《史记·郦生陆贾传》", "example": null}, {"def": "内无苛慝。--《国语·晋语》。注烦也。”", "example": null}, {"def": "去烦蠲苛。--王褒《四子讲德论》", "example": null}, {"def": "又如苛礼(苛刻微细的礼节);苛难(以琐事诘难);苛敛(烦重地征", "example": null}, {"def": "苛kē苛刻；过于严厉；繁琐。", "example": null}, {"def": "【苛察】苛刻繁琐，显示精明。", "example": null}, {"def": "【苛待】苛刻地对待。", "example": null}, {"def": "【苛捐杂税】指繁重的捐税。", "example": null}, {"def": "【苛刻】（条件、要求等）过高，过于严厉；刻薄。", "example": null}, {"def": "【苛求】过严地要求。", "example": null}, {"def": "【苛细】苛刻繁琐。也说苛碎。", "example": null}, {"def": "【苛杂】苛捐杂税。", "example": null}, {"def": "【苛责】过严地责备。", "example": null}, {"def": "【苛政】残酷压迫、剥削人民的政府。", "example": null}, {"def": "【苛性钾】无机化合物，成份是氢氧化钾。白色固体，容易潮解，呈强碱性。用来制造肥皂、洗涤剂及其他化学产品。", "example": null}, {"def": "苛kē", "example": null}, {"def": "①小草。烦", "example": null}, {"def": "②琐;繁细。~法﹑~細。", "example": null}, {"def": "③苛刻;狠虐；严厉。", "example": null}, {"def": "④骚扰。", "example": null}, {"def": "⑤重。~苛疾。", "example": null}, {"def": "⑥通\\"疴\\"。疾病;疥疮", "example": null}, {"def": "苛hē 1.谴责;诘问。", "example": null}]','chinese-xinhua','0'),
('2101143296226103394','柯','1','kē','木','9',NULL,'[{"def": "柯〈名〉", "example": null}, {"def": "(形声。从木,可声。本义斧柄)", "example": null}, {"def": "同本义", "example": null}, {"def": "柯,斧柄也。--《说文》", "example": null}, {"def": "柯,柄也。--《广雅》", "example": null}, {"def": "今若大其柯。--《国语·晋语》", "example": null}, {"def": "伐柯如何?匪斧不克。--《诗·豳风·伐柯》。毛传柯,斧柄也。”", "example": null}, {"def": "又如柯斧(喻法规);柯长三尺", "example": null}, {"def": "古长三尺之称。引申为法则", "example": null}, {"def": "柯,法也。--《尔雅》", "example": null}, {"def": "又如柯亭(法则、法度)", "example": null}, {"def": "树枝", "example": null}, {"def": "横柯上蔽。--《艺文类聚·吴均·与朱元思书》", "example": null}, {"def": "又如柯枝(枝条);柯条(枝条);柯叶(枝叶);柯干(枝干)", "example": null}, {"def": "柯属植物的泛称。常绿乔木,实为长卵形,外有硬壳", "example": null}, {"def": "柯kē", "example": null}, {"def": "⒈斧柄。", "example": null}, {"def": "⒉草木的枝茎交～错叶。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
