('2101143296226103396','珂','1','kē','王','9',NULL,'[{"def": "珂〈名〉", "example": null}, {"def": "(形声。从玉,可声。本义似玉的美石。白玛瑙)", "example": null}, {"def": "同本义", "example": null}, {"def": "马笼头上的装饰", "example": null}, {"def": "文轩树羽盖,乘马鸣玉珂。--张华《轻薄编》", "example": null}, {"def": "又如珂月(嵌在马头笼辔上的月形饰物);珂马(珂即马笼头上的玉饰,因称人所乘之马为珂马)", "example": null}, {"def": "珂里", "example": null}, {"def": "时号所居曰鸣珂里。--《新唐书·张嘉贞传》", "example": null}, {"def": "珂kē像玉的美石，多用作马笼头上的装饰品乘马鸣玉～。", "example": null}]','chinese-xinhua','0'),
('2101143296230297600','科','1','kē','禾','9',NULL,'[{"def": "科〈名〉", "example": null}, {"def": "(会意。从禾,从斗。斗”的意思是量”∠起来指衡量、分别谷子的等级品类。本义品类,等级)", "example": null}, {"def": "同本义", "example": null}, {"def": "科,程也。--《说文》", "example": null}, {"def": "为力不同科。--《论语·八佾》", "example": null}, {"def": "与此同科。--《论衡·幸偶》", "example": null}, {"def": "君歌且休听我歌,我歌今与君殊科。--韩愈《八月十五夜赠张巧曹》", "example": null}, {"def": "又如科品(种类;等级);科荣(科第荣华);科爵(指封建王朝官员的品级爵位)", "example": null}, {"def": "法令;刑律", "example": null}, {"def": "三仪同科。--《太玄·玄离》。注法也。”", "example": null}, {"def": "从水之科满。--《太玄·从》。注法也。”", "example": null}, {"def": "若有作奸犯科及为忠善者。--诸葛亮《出师表》", "example": null}, {"def": "又如", "example": null}, {"def": "科kē", "example": null}, {"def": "⒈类别", "example": null}, {"def": "①课程、学术或业务的分类文～。理～。儿～。妇～。", "example": null}, {"def": "②机关、企业、事业等内部组织的划分卫生～。业务～。财会～。", "example": null}, {"def": "③生物的分类单位之一虎属于食肉目，猫～。水稻属于颖花目，禾本～。", "example": null}, {"def": "⒉法律条文作奸犯～。～教严明，赏罚必信（信守信）。", "example": null}, {"def": "⒊征税，判罪～税。～以罚款。～与徒刑。", "example": null}, {"def": "⒋戏剧中演员的动作、表情插～打诨（诨开玩笑的话）。", "example": null}, {"def": "⒌", "example": null}, {"def": "①反映自然、社会、思维等的客观规律的分科的知识体系。", "example": null}, {"def": "②合乎科学的～学种田。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "科kè 1.滋生;发棵。", "example": null}]','chinese-xinhua','0'),
