('2101143296255463487','夸','1','kuā','大','6',NULL,'[{"def": "夸", "example": null}, {"def": "(形声。从大,于声。本义奢侈)", "example": null}, {"def": "同本义", "example": null}, {"def": "夸,奢也。--《说文》", "example": null}, {"def": "贵而不为夸。--《荀子·仲尼》。注奢侈也。”", "example": null}, {"def": "又如夸丽(虚美浮华);夸侈(奢侈,浮华);夸恣(奢侈放纵)", "example": null}, {"def": "通說”。自大;炫耀", "example": null}, {"def": "华言无实曰夸。--《周书·谥法》", "example": null}, {"def": "富有天下而不聘夸。--《吕氏春秋·下贤》。注诧而自大也。”", "example": null}, {"def": "石崇以奢靡夸人。--宋·司马光《训俭示康》", "example": null}, {"def": "又如夸妉(自大)", "example": null}, {"def": "大", "example": null}, {"def": "夸,大也。--《广雅·释诂一》", "example": null}, {"def": "夸者死权。--《史记·屈原贾生列传》。集解泰也。”", "example": null}, {"def": "妾夸布服,粝食。--班固《汉书", "example": null}, {"def": "夸（說）kuā", "example": null}, {"def": "⒈说大话～大其词。～下海口。过于～张。～耀自己。～ ～其谈。", "example": null}, {"def": "⒉赞赏，颂扬～奖∶人好事有人～。", "example": null}, {"def": "夸kuà 1.跨越。 2.引申为超过。参见\\"夸迈\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296255463488','姱','1','kuā','','6',NULL,'[{"def": "姱kuā 1.美丽，美好。 2.夸耀。参见\\"姱尚\\"﹑\\"姱美\\"。 3.奢侈;铺张。 4.通\\"跨\\"。超越。", "example": null}]','chinese-xinhua','0'),
('2101143296255463489','擓','1','kuai','','13',NULL,'[{"def": "擓kuǎi", "example": null}, {"def": "⒈搔，轻抓～痒。", "example": null}, {"def": "⒉挎在胳膊上～着菜篮子。", "example": null}]','chinese-xinhua','0'),
('2101143296255463490','块','1','kuài','土','7',NULL,'[{"def": "块", "example": null}, {"def": "(形声。从土,鬼声。字本作剆”,是个会意字,表示土块装在筐器之中◇来写作塳”,变成了形声字,现在简化为块”。本义土块)", "example": null}, {"def": "同本义", "example": null}, {"def": "剆,墣也。从土,一屈象形。--《说文》。张舜徽注凵象盛土之器,而土在其中也。”", "example": null}, {"def": "剆,坚土也。--《一切经音义》引《说文》", "example": null}, {"def": "寝苫枕块。--《仪礼·丧服传》。释文土也。”", "example": null}, {"def": "大块噫气。--《庄子·齐物论》", "example": null}, {"def": "大块禀群生。--《文选 ·张华诗》。注谓地也。”", "example": null}, {"def": "石块丛起则历。--《徐霞客游记·游黄山记》", "example": null}, {"def": "又如块阜(小土丘);块苏(土块和草堆。比喻卑微);块山(土", "example": null}, {"def": "块（塳）kuài", "example": null}, {"def": "⒈成片、团或疙瘩状的东西土～儿。石～儿。煤～儿。～根。～茎。", "example": null}, {"def": "⒉〈古〉孤独～独。", "example": null}, {"def": "⒊量词两～香皂。三～布。五～钱（五圆钱）。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296255463491','快','1','kuài','忄','7',NULL,'[{"def": "快〈形〉", "example": null}, {"def": "(形声。从心,声。本义高兴,痛快)", "example": null}, {"def": "同本义", "example": null}, {"def": "快,喜也。--《说文》", "example": null}, {"def": "文信侯去而不快。--《战国策·秦策》", "example": null}, {"def": "心不快。--《史记·魏公子列传》", "example": null}, {"def": "快意留之,非忠臣也。--《后汉书·班超传》", "example": null}, {"def": "则不快吾意。--明·魏禧《大铁椎传》", "example": null}, {"def": "若所为诚快。--明·高启《书博鸡者事》", "example": null}, {"def": "又如快观(让人看了高兴);快吾意(使吾意快,符合我的意思)", "example": null}, {"def": "舒适;舒畅", "example": null}, {"def": "有一士大夫不快。--《三国志·方伎传》", "example": null}, {"def": "又", "example": null}, {"def": "体中不快。", "example": null}, {"def": "使快弹数曲。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "快哉此风。--宋玉《风赋》", "example": null}, {"def": "又", "example": null}, {"def": "快kuài", "example": null}, {"def": "⒈迅速，跟\\"慢\\"相对～马。飞得～。跑得～。进步～。", "example": null}, {"def": "⒉将近，接近她～八十岁了。任务～完成了。", "example": null}, {"def": "⒊从速，赶紧～起床。赶～去办。～回家去。", "example": null}, {"def": "⒋锋利～刀。", "example": null}, {"def": "⒌直爽，直截了当耿直爽～。～人～语。心直口～。", "example": null}, {"def": "⒍高兴，舒服～ ～乐乐。非常～活。痛痛～ ～。十分～意。大～人心。", "example": null}]','chinese-xinhua','0'),
('2101143296255463492','侩','1','kuài','亻','8',NULL,'[{"def": "侩", "example": null}, {"def": "牙侩。两伙人之间的中间人或代理人等", "example": null}, {"def": "合市人也。--《声类》", "example": null}, {"def": "子货金钱千贯,节驵侩。--《汉书·货殖列传》。注合会二家交易者。”", "example": null}, {"def": "又如市侩;侩父(伢侩);侩佞(指唯利是图的奸佞小人)", "example": null}, {"def": "姓", "example": null}, {"def": "侩", "example": null}, {"def": "撮合。说合买卖之间的价钱以成交", "example": null}, {"def": "侩(儈)kuài旧时以拉拢买卖，从中取利为职业的人。", "example": null}]','chinese-xinhua','0'),
('2101143296255463493','郐','1','kuài','阝','8',NULL,'[{"def": "郐", "example": null}, {"def": "中国周朝国名", "example": null}, {"def": "郐,祝融之后,妘姓所封浍洧之间,郑灭之。从邑,会声。--《说文》", "example": null}, {"def": "公元前769年为郑所灭,在今河南密县东北。如郐下(郐下无讥。言其微不足道)", "example": null}, {"def": "姓", "example": null}, {"def": "郐（鄶）kuài周代诸侯国名，是个小国，在今河南省密县东北自～以下（〈喻〉其余的不值得一谈）。", "example": null}]','chinese-xinhua','0'),
('2101143296255463494','哙','1','kuài','口','9',NULL,'[{"def": "哙", "example": null}, {"def": "吞咽", "example": null}, {"def": "哙,咽也。--《说文》。王筠注此下咽之咽。”", "example": null}, {"def": "鲁颜哙字子声。--《史记·弟子传》", "example": null}, {"def": "喘息。张口舒气", "example": null}, {"def": "吱行哙息。--《淮南子·俶真》", "example": null}, {"def": "又如哙息(喘息。通喙息)", "example": null}, {"def": "哙", "example": null}, {"def": "通快”。畅快;快意", "example": null}, {"def": "当此之时,哙然得卧,则亲戚兄弟,欢然而嘉。--《淮南子·精神训》", "example": null}, {"def": "又如哙事(称心如意的事)", "example": null}, {"def": "宽明", "example": null}, {"def": "哙哙其正。--《诗·小雅·斯干》", "example": null}, {"def": "又如哙哙(宽敞明亮的样子)", "example": null}, {"def": "平庸", "example": null}, {"def": "哙（噲）kuài", "example": null}, {"def": "⒈咽下去。", "example": null}, {"def": "⒉〈古〉通\\"快\\"。畅快。", "example": null}, {"def": "哙kuò 1.见\\"肿哙\\"。", "example": null}, {"def": "哙huī 1.骡马打响鼻的声音。", "example": null}, {"def": "哙wèi 1.方言。句末语气助词。 2.叹词。", "example": null}]','chinese-xinhua','0'),
('2101143296255463495','狯','1','kuài','犭','9',NULL,'[{"def": "狯", "example": null}, {"def": "(形声。从犬,会声。本义狡猾) 同本义(含有诡计多端而又易败露的意思)", "example": null}, {"def": "狯,狡狯也。--《说文》", "example": null}, {"def": "马三宝,性敏狯。--《新唐书·裴寂传附马三宝》", "example": null}, {"def": "陟有吏干,性狡狯。--《宋史·侯陟传》", "example": null}, {"def": "又如狡狯(狡猾);狯猾(狡猾)", "example": null}, {"def": "狯（獪）kuài狡猾多诈狡～。", "example": null}]','chinese-xinhua','0'),
('2101143296255463496','脍','1','kuài','月','10',NULL,'[{"def": "脍", "example": null}, {"def": "(形声。从肉,会声。本义细切的肉、鱼) 同本义", "example": null}, {"def": "脍,细切肉也。--《说文》", "example": null}, {"def": "肉腥细者为脍。--《礼记·内则》", "example": null}, {"def": "生肉为脍。--《汉书·东方朔传》", "example": null}, {"def": "食不厌精,脍不厌细。--《论语·乡党》", "example": null}, {"def": "又如脍切(切细的肉或鱼)", "example": null}, {"def": "脍", "example": null}, {"def": "把鱼、肉切成薄片", "example": null}, {"def": "飞刀脍鲤。--张昭远《旧唐书》", "example": null}, {"def": "又如脍鲤;脍刀(切肉的刀);脍截(割切)", "example": null}, {"def": "脍炙人口", "example": null}, {"def": "一篇一咏,脍炙人口。--林嵩《周朴诗集》", "example": null}, {"def": "脍（膾）kuài细切，细切的肉飞刀～鲤。～炙人口（炙烤肉。美味的食品，人人爱吃。〈喻〉好的诗、文等被人传诵）。", "example": null}]','chinese-xinhua','0'),
('2101143296255463497','筷','1','kuài','竹','13',NULL,'[{"def": "筷〈名〉", "example": null}, {"def": "(形声。从竹,快声。本义筷子。也叫箸”,夹取食物的用具) 同本义", "example": null}, {"def": "筷kuài夹取食物的用具，用竹、木或金属等制成，细棍儿状用～子夹熟食。", "example": null}]','chinese-xinhua','0'),
