('2101143296255463502','蒯','1','kuǎi','艹','13',NULL,'[{"def": "蒯〈名〉", "example": null}, {"def": "蒯草", "example": null}, {"def": "虽有丝麻,无弃菅蒯。--《左传·成公九年》", "example": null}, {"def": "又如蒯席(蒯草编的席);蒯履(用蒯草打的草鞋)", "example": null}, {"def": "古地名", "example": null}, {"def": "姓", "example": null}, {"def": "蒯〈动〉", "example": null}, {"def": "用指甲挠", "example": null}, {"def": "我绰着经儿,只望着他那痒处替他蒯。--《醒世恒言》", "example": null}, {"def": "蒯kuǎi蒯草，多年生草本，丛生于水边。茎可织席、制绳索等。", "example": null}]','chinese-xinhua','0'),
('2101143296255463503','款','1','kuǎn','欠','12',NULL,'[{"def": "款", "example": null}, {"def": "(会意。从欠,塞。省。本义真诚;诚恳)", "example": null}, {"def": "同本义", "example": null}, {"def": "款,诚也。--《广雅·释诂一》", "example": null}, {"def": "谒款天神。--《史记·司马相如传》", "example": null}, {"def": "欲效其款款之愚。--《汉书·司马迁传》", "example": null}, {"def": "又", "example": null}, {"def": "辞气愿款,有足感动人者。--《后汉书·江革传》", "example": null}, {"def": "愚款端悫,则合之以礼乐。--《荀子·修身》", "example": null}, {"def": "又如款服(诚心归服);款款深深(亲切;恳挚);款交(至交);款语(亲切谈话);款语温言(真诚而柔和的话);款心(诚心);款迎(热情、殷切地欢迎);款住(殷勤地留住);款洽(诚恳", "example": null}, {"def": "接待;亲切交谈)", "example": null}, {"def": "通竨”。空;空洞,不真实", "example": null}, {"def": "款启寡闻之民。--《庄子·达生》", "example": null}, {"def": "实不中", "example": null}, {"def": "款（歟）kuǎn", "example": null}, {"def": "⒈经费，钱财～项。存～。取～。汇～子。", "example": null}, {"def": "⒉条目第五条第三～。", "example": null}, {"def": "⒊器物上铸刻的字钟鼎～识。〈引〉字画、书信等首尾上的具名上～。下～儿。落～儿（题写名字）。", "example": null}, {"def": "⒋缓慢～ ～而行。疲马行亦～。", "example": null}, {"def": "⒌诚恳，恳切愚（老实）～。忠～。", "example": null}, {"def": "⒍款待，招待～客。一茶可～。", "example": null}, {"def": "⒎空，不真实～言不听，奸乃不生。", "example": null}, {"def": "⒏敲，叩～门。～关请见。", "example": null}]','chinese-xinhua','0'),
