('2101143296255463515','圹','1','kuànɡ','土','6',NULL,'[{"def": "圹", "example": null}, {"def": "(形声。从土,广声。本义墓穴)", "example": null}, {"def": "同本义", "example": null}, {"def": "圹,堑穴也。--《说文》", "example": null}, {"def": "入圹。--《周礼·方相氏》。注穿地中也。”", "example": null}, {"def": "望其圹皋如也。--《荀子·大略》。注丘垅。”", "example": null}, {"def": "若从柩,及圹,皆执绋。--《礼记·夏官·方相氏》", "example": null}, {"def": "又如圹穴(墓穴);圹兆(墓穴的范围)", "example": null}, {"def": "原野", "example": null}, {"def": "兽之走圹也。--《孟子·离娄上》", "example": null}, {"def": "以处圹埌之野。--《庄子·应帝王》。崔注犹旷荡也。”", "example": null}, {"def": "又如圹野(原野);圹埌(原野空旷的样子)", "example": null}, {"def": "圹", "example": null}, {"def": "通旷”。荒废", "example": null}, {"def": "敬谋无圹,敬事无圹,敬吏无圹,敬众无圹,敬敌无圹,夫是之", "example": null}, {"def": "圹（壙）kuàng", "example": null}, {"def": "⒈墓穴。", "example": null}, {"def": "⒉圹野，野外。", "example": null}, {"def": "⒊〈古〉通\\"旷\\"。荒废，历时久远。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296255463516','纩','1','kuànɡ','纟','6',NULL,'[{"def": "纩", "example": null}, {"def": "古时指新丝绵絮◇泛指绵絮", "example": null}, {"def": "纩,絮也。--《说文》", "example": null}, {"def": "纩,绵也。絮之细者曰纩也。--《小尔雅》", "example": null}, {"def": "三军之士皆知挟纩。--《左传·宣公二年》", "example": null}, {"def": "丝纩竹箭。--《礼记·礼器》", "example": null}, {"def": "纩为茧。--《礼记·玉藻》", "example": null}, {"def": "厥篚纤纩。--《书·禹贡》", "example": null}, {"def": "又如厥篚纤纩(谓把新的丝绵装在竹筐里进贡);纩衣(纩服。绵衣。纩絮衣服的丝绵);纩息(弥留之际的呼吸。古人临死,置纩于其口鼻之上,以验气息之有无);纩絮(绵絮)", "example": null}, {"def": "纩（纊）kuàng绵絮。", "example": null}]','chinese-xinhua','0'),
('2101143296255463517','况','1','kuànɡ','冫','7',NULL,'[{"def": "况", "example": null}, {"def": "(形声。从水,兄声。本义寒冷的水)", "example": null}, {"def": "同本义", "example": null}, {"def": "況,寒水也。--《说文》。段玉裁注未得其证。…古矧兄、比兄,皆用兄字;后乃用況字,后又改作况。”", "example": null}, {"def": "情形,景况(侧重于整个事物的概况)", "example": null}, {"def": "乱况斯削。--《诗·大雅·桑柔》", "example": null}, {"def": "客有问雁山游况者,聊以塞责,不足观也。--韩愈《雁山杂记》", "example": null}, {"def": "又如况味(境况情味。有时专指境遇);闲况;状况;实况;战况;情况;盛况", "example": null}, {"def": "兄", "example": null}, {"def": "姓", "example": null}, {"def": "况 〈动〉", "example": null}, {"def": "比拟,比喻", "example": null}, {"def": "案火灭不能复燃以况之,死入不能复为鬼,明矣。╠", "example": null}, {"def": "况（況）kuàng", "example": null}, {"def": "⒈情形，状态情～。近～很好。", "example": null}, {"def": "⒉比，譬以古～今。", "example": null}, {"def": "⒊连词。〈表〉更进一层～且∥～。", "example": null}, {"def": "⒋副词。更加众～厚之。", "example": null}, {"def": "⒌〈古〉通\\"贶\\"。赐，赏赐厚～。", "example": null}]','chinese-xinhua','0'),
('2101143296255463518','旷','1','kuànɡ','日','7',NULL,'[{"def": "旷", "example": null}, {"def": "(会义兼形声。从日,广声。本义光明;明朗)", "example": null}, {"def": "同本义", "example": null}, {"def": "旷,明也。--《说文》", "example": null}, {"def": "旷,光明也。--《玉篇》", "example": null}, {"def": "此人谓照旷。--《庄子·天地》", "example": null}, {"def": "旷若发矇。--《后汉书》", "example": null}, {"def": "又如旷旷(光明;明亮)", "example": null}, {"def": "心境开阔,开朗", "example": null}, {"def": "则有心旷神怡。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "又如旷度(宽大的气度);旷澹(心胸豁达,不重名利);旷怀(开阔的心胸);旷逸(心胸开阔,性情超脱);旷士(胸襟开阔之士);旷如(开阔)", "example": null}, {"def": "空旷;开阔", "example": null}, {"def": "旷兮其若谷。--《老子》十五章", "example": null}, {"def": "居于旷林。--《左传·昭公元年》", "example": null}, {"def": "率彼旷", "example": null}, {"def": "旷（曠）kuàng", "example": null}, {"def": "⒈广大，空阔～野荒郊。空～无人。土地平～。", "example": null}, {"def": "⒉明朗，开朗～若发矇（发矇使瞎子睁开眼睛）。心～神怡。", "example": null}, {"def": "⒊空缺，荒废久～。～课。～工。～日持久。", "example": null}, {"def": "⒋历时久远～年。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296255463519','矿','1','kuànɡ','石','8',NULL,'[{"def": "矿", "example": null}, {"def": "(形声。从石,广声。本义矿产,矿物)", "example": null}, {"def": "同本义", "example": null}, {"def": "其下则金矿丹砾。--晋·郭璞《江赋》", "example": null}, {"def": "又如铁矿;矿田;矿丁(旧时对矿工的称呼);矿夫(即矿兵);矿屯(用驻军开采矿产以节省国家开支的一种措施);矿主(旧时占有矿山和开矿生产手段的资本家);矿务(采矿事务)", "example": null}, {"def": "开采矿物的场所或单位", "example": null}, {"def": "石针,古代的一种医疗工具", "example": null}, {"def": "汤剂不可理,矿艾不可攻。--皮日休《祀虐疠文》", "example": null}, {"def": "矿（祐、鑛）kuàng", "example": null}, {"def": "⒈蕴藏在地层中可供开采使用的自然资源铁～。煤～。金～。油～。气～。采～。", "example": null}, {"def": "⒉开采矿物的场所～山。～井。", "example": null}, {"def": "⒊特指矿石黄铁～。", "example": null}]','chinese-xinhua','0'),
