('2101143296255463526','贶','1','kuànɡ','贝','9',NULL,'[{"def": "贶", "example": null}, {"def": "(形声。从贝,兄声。本义赐,赏赐)", "example": null}, {"def": "同本义", "example": null}, {"def": "贶,赐也。--《说文》", "example": null}, {"def": "羞当白壁贶。--鲍照《拟古》", "example": null}, {"def": "又如厚贶(厚赏);贶赠(馈赠);贶寿(赠献寿礼);贶佑(赐福)", "example": null}, {"def": "通况”。比方", "example": null}, {"def": "更统世而自贶。--《楚辞·悲回风》", "example": null}, {"def": "贶", "example": null}, {"def": "赐赠之物", "example": null}, {"def": "天降嘉贶,将何德以酬之?--《魏书·世祖纪》", "example": null}, {"def": "贶kuàng赐，赠送，赏赐～赠●～。嘉～。", "example": null}]','chinese-xinhua','0'),
('2101143296255463527','框','1','kuànɡ','木','10',NULL,'[{"def": "框〈名〉", "example": null}, {"def": "(形声。从木,匡声。本义门窗的架子)", "example": null}, {"def": "同本义", "example": null}, {"def": "棺门", "example": null}, {"def": "两手据地而欧之不出,喀喀然遂伏而死。--《列子·说符》", "example": null}, {"def": "凡是四方的周边,今都叫框", "example": null}, {"def": "框 〈动〉", "example": null}, {"def": "约束", "example": null}, {"def": "框kuàng", "example": null}, {"def": "⒈门、窗的边架门～。窗～。", "example": null}, {"def": "⒉镶在器物外围起撑架或保护作用的东西镜～子。眼镜～儿。", "example": null}, {"def": "⒊周围的圈子。〈喻〉原有的范围、固有的格式等突破老～ ～。", "example": null}, {"def": "⒋加框把这幅画～起来。", "example": null}, {"def": "⒌约束，限制～得太严了。", "example": null}]','chinese-xinhua','0'),
