('2101143296263852058','匮','1','kuì','匚','11',NULL,'[{"def": "匮  kui", "example": null}, {"def": "(形声。从匚,表示与盛放东西有关,贵声。本义柜子)", "example": null}, {"def": "运装土的畚。通篑”", "example": null}, {"def": "纲纪咸张,成在一匮。--《汉书·王莽传上》", "example": null}, {"def": "孔子曰辟如为山,未成一匮。止,吾止也。”--《汉书·礼乐志》", "example": null}, {"def": "姓", "example": null}, {"def": "匮", "example": null}, {"def": "缺乏,空乏", "example": null}, {"def": "卼,乏也。--《广雅》", "example": null}, {"def": "财财不匮。--《礼记·月令仲秋》", "example": null}, {"def": "其财匮。--《礼记·乐记》", "example": null}, {"def": "虞不出财财匮少。--《史记·货殖列传》", "example": null}, {"def": "财匮少而山泽不辟矣。", "example": null}, {"def": "又如匮竭(穷尽,缺乏财货);匮粮(缺乏粮食);匮少(缺少);匮饿(缺粮饥饿);匮矮(缺粮饥饿);匮阕(缺乏)", "example": null}, {"def": "通潰”", "example": null}, {"def": "匮kuì", "example": null}, {"def": "⒈缺乏，不足～乏。", "example": null}, {"def": "⒉〈古〉通\\"篑\\"。盛土的竹筐。", "example": null}, {"def": "⒊〈古〉通\\"柜\\"。柜子。", "example": null}, {"def": "匮guì 1.大型藏物器。 2.引申指供军事用的蓄水池﹑水库。", "example": null}]','chinese-xinhua','0'),
('2101143296263852059','喟','1','kuì','口','12',NULL,'[{"def": "喟〈动〉", "example": null}, {"def": "(形声。从口,胃声。本义叹息) 同本义", "example": null}, {"def": "喟,大息也。--《说文》", "example": null}, {"def": "出游于观之上,喟然而叹。--《礼记·礼运》", "example": null}, {"def": "天子喟然叹曰。--《论语·先进》", "example": null}, {"def": "托遗编而叹喟兮,淆余涕之盈眶。--柳宗元《吊屈原文》", "example": null}, {"def": "喟然叹曰。--《汉书·李广苏建传》", "example": null}, {"def": "生喟然曰。--清·黄宗羲《柳敬亭传》", "example": null}, {"def": "喟然", "example": null}, {"def": "孔明喟然叹曰臣自出茅庐,得遇大王,相随至今,言听计从。”--《三国演义》", "example": null}, {"def": "喟然长叹", "example": null}, {"def": "喟叹", "example": null}, {"def": "喟kuì叹息～然。～叹。～ ～声声。", "example": null}]','chinese-xinhua','0'),
('2101143296263852060','媿','1','kuì','','11',NULL,'[{"def": "媿kuì 1.惭愧。 2.羞辱。 3.感谢。 4.姓『有媿牟﹑媿戊。", "example": null}]','chinese-xinhua','0'),
('2101143296263852061','愦','1','kuì','忄','12',NULL,'[{"def": "愦", "example": null}, {"def": "闷,烦乱", "example": null}, {"def": "心烦愦兮意无聊。--王逸《九思·逢尤》", "example": null}, {"def": "又如愦愦(混乱不安;糊涂);愦乱(昏乱不安,忧思烦乱);愦闹(混乱喧闹);愦毒(因中毒而烦乱)", "example": null}, {"def": "昏乱,神志不清", "example": null}, {"def": "则固僵仆烦愦。--唐·柳宗元《柳河东集》", "example": null}, {"def": "愦于忧。--《战国策·齐策四》", "example": null}, {"def": "又如愦眊(昏昧糊涂);愦耄(昏乱糊涂);愦慢(昏庸怠慢);愦瞀(昏乱)", "example": null}, {"def": "愦kuì糊涂，昏乱昏～。", "example": null}]','chinese-xinhua','0'),
('2101143296263852062','愧','1','kuì','忄','12',NULL,'[{"def": "愧〈动〉", "example": null}, {"def": "(形声。从心,鬼声。本义惭愧)", "example": null}, {"def": "同本义。同媿”", "example": null}, {"def": "小则如愧。--《礼记·儒行》", "example": null}, {"def": "尚不愧于屋漏。--《诗·大雅·抑》", "example": null}, {"def": "不愧于人。--《诗·小雅·何人斯》", "example": null}, {"def": "虽颜惭未知心愧。--《魏书·列女传》", "example": null}, {"def": "纵上不杀我,我不愧于心乎?--《史记·张耳陈余列传》", "example": null}, {"def": "谌虽暴抗,然闻言则大愧流汗。--柳宗元《段太尉逸事状》", "example": null}, {"def": "能不愧老人之言否。--清·周容《芋老人传》", "example": null}, {"def": "下恐愧吾师矣。--清·方苞《左忠毅公逸事》", "example": null}, {"def": "兹游快且愧矣。--《徐霞客游记·游黄山记》", "example": null}, {"def": "兼愧贵家子。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "又如愧心(", "example": null}, {"def": "愧（媿）kuì羞惭，心里觉得对不起～对。羞～。惭～。问心无～。闻言则大～。", "example": null}]','chinese-xinhua','0'),
('2101143296263852063','溃','1','kuì','氵','12',NULL,'[{"def": "溃", "example": null}, {"def": "(形声。从水,贵声。本义水冲破堤岸)", "example": null}, {"def": "同本义", "example": null}, {"def": "溃,决也。--《说文系传》", "example": null}, {"def": "溃,漏也。--《说文》", "example": null}, {"def": "溃,旁决也。--《苍颉篇》", "example": null}, {"def": "不遵其道曰洚,亦曰溃。--《水经注·河水》注", "example": null}, {"def": "沸溃渝溢。--木华《海赋》。注乱流貌。”", "example": null}, {"def": "溃淡淡而并入。--宋玉《高唐赋》。注水相交过也。”", "example": null}, {"def": "渟涔障溃。--《文选·长笛赋》", "example": null}, {"def": "千丈之堤,以蝼蚁之穴溃。--《韩非子·喻老》", "example": null}, {"def": "川壅而溃,伤人必多。--《国语·周语上》", "example": null}, {"def": "溃渭洞河。--班固《西都赋》", "example": null}, {"def": "又如溃围(突围);溃冒(冲决泛滥);溃溢(堤防崩溃,洪水", "example": null}, {"def": "溃kuì", "example": null}, {"def": "⒈水冲破堤坝～决。～溢。大水～出。〈引〉冲破包围～围而出。", "example": null}, {"def": "⒉散乱，垮台～散。败将～兵。～不成军。经济崩～。", "example": null}, {"def": "⒊腐烂，缺损～烂。～疡（局部皮肤或粘膜组织坏死、脱落所形成的缺损）。", "example": null}]','chinese-xinhua','0'),
('2101143296263852064','蒉','1','kuì','艹','12',NULL,'[{"def": "蒉", "example": null}, {"def": "(形声。从艹,贵声。本义草编的筐子) 同本义", "example": null}, {"def": "以一障江、河,用没其身。--《汉书》", "example": null}, {"def": "蒉kuì〈古〉草编的筐子。", "example": null}, {"def": "蒉kuài 1.芜秽。 2.姓。春秋时鲁国有蒉尚。见《礼记．檀弓下》。", "example": null}]','chinese-xinhua','0'),
('2101143296263852065','馈','1','kuì','饣','12',NULL,'[{"def": "馈", "example": null}, {"def": "(形声。从食,贵声。本义以食物送人)", "example": null}, {"def": "同本义", "example": null}, {"def": "馈,饷也。--《说文》", "example": null}, {"def": "陈浪簋。--《诗·小雅·伐木》", "example": null}, {"def": "君有馈焉曰献。--《礼记·檀弓》", "example": null}, {"def": "国胡以馈之。--汉·贾谊《论积贮疏》", "example": null}, {"def": "又如馈孰(献熟食);馈食(献熟食);馈飱(进献饭食);馈馔(以食物送人);馈献(献熟食)", "example": null}, {"def": "进食", "example": null}, {"def": "在中馈。--《易·家人》。释文食也。”", "example": null}, {"def": "又如馈养(进食奉养)", "example": null}, {"def": "烹调", "example": null}, {"def": "赠送", "example": null}, {"def": "馈,遗也。--《广雅》", "example": null}, {"def": "古者致物于人,尊之则曰献,通行曰馈。--《周礼·天官》注", "example": null}, {"def": "馈（餽）kuì", "example": null}, {"def": "⒈赠送～赠。", "example": null}, {"def": "⒉吃饭。", "example": null}]','chinese-xinhua','0'),
