('2101143296263852080','岿','1','kuī','山','8',NULL,'[{"def": "岿", "example": null}, {"def": "(形声。从山,归声。本义小山丛列)", "example": null}, {"def": "同本义", "example": null}, {"def": "山小而众,岿。--《尔雅·释山》", "example": null}, {"def": "高峻独立的", "example": null}, {"def": "唯巨石岿然挺立耳。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "又如岿然独存(坚固独存而屹立不摇的样子);岿然不动;岿崎(山势险峻的样子);岿巠(高峻)", "example": null}, {"def": "高大", "example": null}, {"def": "岿岿穹崇。--《文选·王延寿·鲁灵光赋》", "example": null}, {"def": "而灵光岿然独存。--《文选·王延寿·鲁灵光殿赋序》", "example": null}, {"def": "又如岿嵬", "example": null}, {"def": "岿然", "example": null}, {"def": "岿然不动", "example": null}, {"def": "岿然独存", "example": null}, {"def": "岿巍", "example": null}, {"def": "山峰岿巍", "example": null}, {"def": "岿（巋）kuī高大、独立的样子～然不动。～然独存。", "example": null}]','chinese-xinhua','0'),
('2101143296263852081','悝','1','kuī','忄','10',NULL,'[{"def": "悝〈动〉", "example": null}, {"def": "嘲笑。通诙”", "example": null}, {"def": "由余以西戎孤臣而悝缪公于宫室。--《文选·张衡·东京赋》", "example": null}, {"def": "悝kuī", "example": null}, {"def": "⒈嘲讽。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296263852082','盔','1','kuī','皿','11',NULL,'[{"def": "盔〈名〉", "example": null}, {"def": "(形声。从皿,灰声。本义钵)", "example": null}, {"def": "同本义。盂一类容器", "example": null}, {"def": "盔,盔器,盂属也。--《龙龛手鉴》", "example": null}, {"def": "首铠。古代战士用以保护头部的帽子。也指消防人员或矿工带的金属帽子", "example": null}, {"def": "三通鼓罢,袁绍金盔金甲,锦袍玉带,立马阵前。--《三国演义》", "example": null}, {"def": "又如盔缨(头盔上的丝织饰物)", "example": null}, {"def": "盔kuī", "example": null}, {"def": "⒈作战时用于保护头部的帽子，多用金属制成头～。钢～。", "example": null}, {"def": "⒉像盆子而较深的器皿瓦～子。", "example": null}]','chinese-xinhua','0'),
('2101143296263852083','窥','1','kuī','穴','13',NULL,'[{"def": "窥", "example": null}, {"def": "(形声。从穴,规声。本义从小孔或缝里看)", "example": null}, {"def": "暗中察看。亦泛指观看", "example": null}, {"def": "窥,小视也。--《说文》", "example": null}, {"def": "钻穴隙相窥,逾墙相从。--《孟子·滕文公下》", "example": null}, {"def": "窥见室家之好。--《论语·子路》", "example": null}, {"def": "妻从门间而窥其夫。--《史记·管晏列传》", "example": null}, {"def": "蔽林间窥之。--唐·柳宗元《三戒》", "example": null}, {"def": "又如窥觑(偷看);窥瞰(窥探;暗中偷看);窥欲(窥伺贪求)", "example": null}, {"def": "观察,侦探", "example": null}, {"def": "窥谷忘反。--吴均《与朱元思书》", "example": null}, {"def": "窥父不在。--《聊斋志异·促织》", "example": null}, {"def": "又如窥究(深究察觉);窥圃(窥园。观赏园景);窥深(观察深入细致);窥睹(观看;观察);窥览(阅览;观察)", "example": null}, {"def": "伺机图", "example": null}, {"def": "窥（阯）kuī从孔隙或隐蔽处偷看～视。管中～豹（从管子里看豹。〈喻〉看到的不是全部）。〈引〉观察，侦探～测方向。～敌观变。", "example": null}, {"def": "窥kuǐ 1.半步。言一举足即到。 2.引申为到。", "example": null}]','chinese-xinhua','0'),
