('2101143296263852090','悃','1','kǔn','忄','10',NULL,'[{"def": "悃〈形〉", "example": null}, {"def": "诚恳,诚挚", "example": null}, {"def": "悃,愊也。--《说文》", "example": null}, {"def": "悃,至诚。--《广韵》", "example": null}, {"def": "悃悃款款,朴以忠乎?--《楚辞·卜居》", "example": null}, {"def": "发愤悃愊。--《汉书·刘向传》", "example": null}, {"def": "优愿俯察悃诚,不遗贱小。--白居易《与陈给事书》", "example": null}, {"def": "又如悃愊无华(诚朴不浮华);悃忱(诚恳;忠诚);悃衷(诚恳之心)", "example": null}, {"def": "悃愊", "example": null}, {"def": "悃愊无华", "example": null}, {"def": "悃诚", "example": null}, {"def": "陈见悃诚。--《汉书·王褒传》", "example": null}, {"def": "悃kǔn诚实，诚恳。", "example": null}]','chinese-xinhua','0'),
('2101143296263852091','捆','1','kǔn','扌','10',NULL,'[{"def": "捆", "example": null}, {"def": "(形声。从手,困声。本义叩击使牢)", "example": null}, {"def": "同本义", "example": null}, {"def": "皆衣褐、捆屦、织席以为食。--《孟子·滕文公》。赵歧注织屦欲使坚,故叩之也。”", "example": null}, {"def": "用绳、链或带子系、拴、扎紧", "example": null}, {"def": "贾蓉忍不得便骂了几句,叫人捆起来。--《红楼梦》", "example": null}, {"def": "又如捆风(扯谎说瞎话);捆身子(内衣);捆行李;捆谷草;捆住手脚;把书捆起来", "example": null}, {"def": "捆 〈量〉", "example": null}, {"def": "捆扎在一起的东西,以便携带和搬运", "example": null}, {"def": "捆（綑）kǔn", "example": null}, {"def": "⒈用绳索等缠紧、绑扎起来～起来。～结实。", "example": null}, {"def": "⒉量词。指捆在一起的东西两～书。四～木柴。", "example": null}, {"def": "捆kùn 1.使之齐平。", "example": null}]','chinese-xinhua','0'),
('2101143296263852092','阃','1','kǔn','门','10',NULL,'[{"def": "阃", "example": null}, {"def": "(形声。从门,困声。本义门槛)", "example": null}, {"def": "同本义", "example": null}, {"def": "阃以内者寡人制之。--《史记·冯唐传》", "example": null}, {"def": "无阃外之非仪也。--《孔子家语·本命》", "example": null}, {"def": "特指城门的门槛", "example": null}, {"def": "送迎不越阃。--李延寿《南史》", "example": null}, {"def": "又如阃阈(门限;门槛);阃奥(门户。引申为要塞)", "example": null}, {"def": "指郭门", "example": null}, {"def": "阃以内者,寡人制之,阃以外者,将军制之。--《史记·张释之冯唐列传》", "example": null}, {"def": "又如阃外(本指城郭之外,引申为担任要职的人);阃外之寄(战地指挥调度);阃外将军(在都城以外领兵作战的将军)", "example": null}, {"def": "借指领兵在外的将帅或外任的大臣", "example": null}, {"def": "即具以北虚实告东西二阃", "example": null}, {"def": "阃kǔn", "example": null}, {"def": "⒈门槛。", "example": null}, {"def": "⒉〈古〉宫中的小巷。〈引〉妇女居住的内室。", "example": null}]','chinese-xinhua','0'),
('2101143296263852093','壸','1','kǔn','士','11',NULL,'[{"def": "壸", "example": null}, {"def": "古时宫中道路", "example": null}, {"def": "宫中衖谓之壸。--《尔雅》", "example": null}, {"def": "又如壸术(宫中的巷道)", "example": null}, {"def": "引申指内宫。亦泛指妇女居住的内室", "example": null}, {"def": "至壸以外事绝口不问。--明·王思任《高妇于节烈传》", "example": null}, {"def": "又如壸政(宫内事务;家政);壸奥(室内深处。也用以比喻事理深微隐奥的地方。也作壸闱,内宫);壸阁(闺阁;闺房);壸闱(宫闱;闺闱)", "example": null}, {"def": "妇女", "example": null}, {"def": "壸（壼）kǔn皇宫里的道路。", "example": null}]','chinese-xinhua','0'),
