('2101143296263852109','鲲','1','kūn','鱼','16',NULL,'[{"def": "鲲", "example": null}, {"def": "(形声。从鱼,昆声。本义鱼苗的总称)", "example": null}, {"def": "同本义", "example": null}, {"def": "传说中的一种大鱼", "example": null}, {"def": "北冥有鱼,其名为鲲。--《庄子·逍遥游》", "example": null}, {"def": "又如鲲鹏(古代传说中的大鱼和大鸟);鲲鹏展翅,九万里,翻动扶摇羊角。《庄子》里说,有一种大鱼叫鲲,变成一种大鸟叫鹏,能飞得又高又远。九万里", "example": null}, {"def": "容飞得极高。翻动,卷起。扶摇羊角,迅猛回旋的旋风。羊角,形状像羊角一样的旋风;鲲化(鲲鱼化为鹏鸟;比喻人高升);鲲龙(传说中的大鱼和蛟龙)", "example": null}, {"def": "鲲kūn〈古〉传说中的一种大鱼。", "example": null}]','chinese-xinhua','0'),
('2101143296263852110','坤','1','kūn','土','8',NULL,'[{"def": "坤", "example": null}, {"def": "(形声。从土,申声。本义八卦之一,象征地)", "example": null}, {"def": "地,大地", "example": null}, {"def": "坤,地也,易之卦也。--《说文》", "example": null}, {"def": "坤,土也。--《左传·庄公二十二年》", "example": null}, {"def": "坤也者,地也。--《易·说卦》", "example": null}, {"def": "山岳河渎,皆坤之灵。--《宋书·乐志》", "example": null}, {"def": "又如坤元(坤的元始之德,指大地资生万物之德);坤母(地;火);坤后(地);坤珍(象征大地的符瑞);坤轴(想像中的地轴);坤维(地维。指大地的四方);坤仪(大地。同坤舆)", "example": null}, {"def": "《易》卦名", "example": null}, {"def": "八卦之一", "example": null}, {"def": "坤为地、为母、为布、为釜、为吝啬。--《易·说卦》", "example": null}, {"def": "又如坤卦(八卦之一,代表地);", "example": null}, {"def": "坤（堃）kūn", "example": null}, {"def": "⒈八卦之一，代表地。", "example": null}, {"def": "⒉女性的，阴性的～伶。～包。～衣。 \\"堃\\"多见于人名。", "example": null}]','chinese-xinhua','0'),
('2101143296263852111','昆','1','kūn','日','8',NULL,'[{"def": "昆〈副〉", "example": null}, {"def": "(会意。从日,从比。金文字形,表示二人在日光下并肩行走 。本义一起,共同)", "example": null}, {"def": "同本义", "example": null}, {"def": "昆,同也。--《说文》", "example": null}, {"def": "理生昆群。--《太玄·玄摛》", "example": null}, {"def": "格也乖而昆也同。--《太玄·玄错》", "example": null}, {"def": "昆仑旁薄幽。--《太玄中》", "example": null}, {"def": "噍噍昆鸣。--扬雄《羽猎赋》", "example": null}, {"def": "又如昆群(同群)", "example": null}, {"def": "后,然后", "example": null}, {"def": "魂兮归徕,正始昆只。--《楚辞》", "example": null}, {"def": "昆 〈名〉", "example": null}, {"def": "哥哥,胞兄", "example": null}, {"def": "昆,兄也。--《广韵》", "example": null}, {"def": "终远兄弟,谓他人昆。--《诗·王风·葛藟》", "example": null}, {"def": "昔有昆弟三人。--《列子》", "example": null}, {"def": "又如昆友(兄弟和朋友);昆仲(称呼别人兄弟的敬词);昆玉(对别人兄", "example": null}, {"def": "昆（", "example": null}, {"def": "⒌崑）kūn", "example": null}, {"def": "⒈哥哥布衣（老百姓）～弟。～仲（称别人的兄弟）。", "example": null}, {"def": "⒉子孙，后裔后～。炎黄之～。", "example": null}, {"def": "⒊众多。", "example": null}, {"def": "⒋一齐，共同啾啾～鸣。", "example": null}, {"def": "⒌", "example": null}, {"def": "昆hùn 1.混同。", "example": null}]','chinese-xinhua','0'),
