('2101143296272240659','赉','1','lài','贝','11',NULL,'[{"def": "赉", "example": null}, {"def": "(形声。从贝,来声。本义赏赐)", "example": null}, {"def": "同本义", "example": null}, {"def": "赉,赐也。--《说文》", "example": null}, {"def": "予其大赉汝。--《商君·汤誓》", "example": null}, {"def": "赉,大封于庙也。赉,予也。--《诗·赉序》", "example": null}, {"def": "徂赉孝孙。--《诗·小雅·楚茨》", "example": null}, {"def": "赉我思成。--《诗·商颂·烈祖》", "example": null}, {"def": "周有大赉,善人是富。--《论语》", "example": null}, {"def": "抚军亦厚赉成名。--《聊斋志异·促织》", "example": null}, {"def": "又如赉假(古代帝王下诏赐给假期);赉赏(赏赐);赉奖(奖赏,赏赐);赉赐(赏赐);赉功(赏赐有功者)", "example": null}, {"def": "赠送", "example": null}, {"def": "赉（賚）lài赏赐～绢三千。lai癩lài", "example": null}, {"def": "⒈［癩病］即\\"麻风病\\"。", "example": null}, {"def": "⒉生癣疥等皮肤病，以致毛发脱落～皮狗。", "example": null}, {"def": "⒊表面凹凸不平或有斑点的～蛤蟆。～南瓜。", "example": null}]','chinese-xinhua','0'),
('2101143296272240660','睐','1','lài','目','12',NULL,'[{"def": "睐", "example": null}, {"def": "瞳仁不正", "example": null}, {"def": "睐,目瞳子不正也。从目,来声。--《说文》", "example": null}, {"def": "睐", "example": null}, {"def": "旁视,斜视", "example": null}, {"def": "明眸善睐。--曹植《洛神赋》。李善注睐,旁视也。”", "example": null}, {"def": "眺望", "example": null}, {"def": "极目睐左阁,回顾眺右狭。--南朝宋·谢灵运《登上戍石鼓山》", "example": null}, {"def": "睐（瞐）lài看，向旁边看眄～。青～（对人的喜欢或重视）。", "example": null}]','chinese-xinhua','0'),
('2101143296272240661','赖','1','lài','贝','13',NULL,'[{"def": "赖", "example": null}, {"def": "(形声。从贝,剌声。本义得益;赢利)", "example": null}, {"def": "同本义", "example": null}, {"def": "赖,赢也。--《说文》", "example": null}, {"def": "赖,取也。--《方言十三》", "example": null}, {"def": "先王岂有赖焉。--《国语·周语》。注利也。”", "example": null}, {"def": "相语以利,相示以赖,相陈以知贾。--《国语》", "example": null}, {"def": "为魏则益,为秦则不赖矣。--《战国策》", "example": null}, {"def": "又如赖利(得利)", "example": null}, {"def": "依靠;依赖;依恃、凭藉", "example": null}, {"def": "奸人赖赏而富。--《韩非子·诡使》", "example": null}, {"def": "王室之不坏,繄伯舅是赖。--《左传·襄公十四年》", "example": null}, {"def": "以有补于人君,人君赖之。--《论衡·逢遇》", "example": null}, {"def": "而赖吾之德。--《国语·晋语》", "example": null}, {"def": "又", "example": null}, {"def": "赖子存之。", "example": null}, {"def": "吾赖是以食吾躯。--明", "example": null}, {"def": "赖lài", "example": null}, {"def": "⒈倚靠，仗持依～。办好这件事，有～大家同心协力。", "example": null}, {"def": "⒉不承认～债。抵～。证据确凿，～是～不掉的。", "example": null}, {"def": "⒊诬陷，反过来怪人诬～。自己错了，别～他人。", "example": null}, {"def": "⒋怪罪，责备学习成绩差，只能～自己努力不够。", "example": null}, {"def": "⒌差，劣，坏这种电视机的质量不～。", "example": null}, {"def": "⒍停在某地，不愿离开～在家里。", "example": null}, {"def": "⒎［无赖］", "example": null}, {"def": "①生活无依无靠。", "example": null}, {"def": "②流氓市井（街市）无～。耍无～（又指赖着不走）。", "example": null}]','chinese-xinhua','0'),
('2101143296272240662','濑','1','lài','氵','16',NULL,'[{"def": "濑", "example": null}, {"def": "从沙石上流过的水", "example": null}, {"def": "濑,水流沙上也。--《说文》", "example": null}, {"def": "石濑兮浅浅。--《楚辞·九歌·湘君》", "example": null}, {"def": "北揭石濑。--《汉书·司马相如传下》", "example": null}, {"def": "溪谷之深,流者安洋;浅多沙石,激扬为濑。--《论衡》", "example": null}, {"def": "流得很急的水;急流", "example": null}, {"def": "抑渕怒濑,以扬激波。--《淮南子·本经》", "example": null}, {"def": "混涛并濑。--《文选·左思·吴都赋》", "example": null}, {"def": "石濑汤汤。--《魏都赋》", "example": null}, {"def": "涖涖下濑。--《汉书·司马相如传上》", "example": null}, {"def": "何必湘渊与涛濑。--《汉书·扬雄传上》", "example": null}, {"def": "濑lài急流的水。", "example": null}]','chinese-xinhua','0'),
