('2101143296272240701','烂','1','làn','火','9',NULL,'[{"def": "烂", "example": null}, {"def": "(形声。从火,阑声。本义煮烂)", "example": null}, {"def": "同本义", "example": null}, {"def": "実,孰也。--《说文》。字亦作爛。", "example": null}, {"def": "熟而不烂。--《吕氏春秋·本味》", "example": null}, {"def": "三日三夕不烂。--晋·干宝《搜神记》", "example": null}, {"def": "又", "example": null}, {"def": "此儿头不烂。", "example": null}, {"def": "是必烂也。", "example": null}, {"def": "三首俱烂。", "example": null}, {"def": "又如烂饭(加水较多而煮成的又软又烂的饭);烂煮(煮至熟烂);烂蒸(蒸至烂熟);烂椹(熟透的桑椹)", "example": null}, {"def": "火烧伤", "example": null}, {"def": "焦头烂额为上客。--《汉书·霍光传》", "example": null}, {"def": "头绪乱", "example": null}, {"def": "零碎,断片", "example": null}, {"def": "烂", "example": null}, {"def": "腐", "example": null}, {"def": "烂（爛）làn", "example": null}, {"def": "⒈稀软～泥。", "example": null}, {"def": "⒉过熟，熟透蚕豆煮～了。〈引〉极，甚这本书读得～熟。", "example": null}, {"def": "⒊腐朽，败坏敌人一天天～下去。", "example": null}, {"def": "⒋腐坏，破碎腐～。～桃子。～衣服。破铜～铁。", "example": null}, {"def": "⒌头绪乱～摊子。", "example": null}, {"def": "⒍［烂漫］［烂熳］［烂缦］", "example": null}, {"def": "①色彩鲜艳，光彩四射云霞～漫。", "example": null}, {"def": "②坦率自然，毫无做作天真～漫。", "example": null}, {"def": "③散乱忽～漫而无成。", "example": null}]','chinese-xinhua','0'),
('2101143296272240702','滥','1','làn','氵','13',NULL,'[{"def": "滥", "example": null}, {"def": "(形声。从水,监声。本义浮起,浮现)", "example": null}, {"def": "同本义", "example": null}, {"def": "滥,泛也。--《说文》", "example": null}, {"def": "江出于岷山,其始出也,其源可以滥觞。--《荀子·子道》", "example": null}, {"def": "滥泉正出。--《尔雅·释水》", "example": null}, {"def": "滥水之潘为渊。--《列子·黄帝》", "example": null}, {"def": "大水漫出,泛滥", "example": null}, {"def": "大水泛滥郡国十五有余。--《汉书·谷永传》", "example": null}, {"def": "其水阳焊不耗,阴霖不滥。--《水经注·湿水》", "example": null}, {"def": "当尧之时,水逆行,泛滥于中国。--《孟子·滕文公》", "example": null}, {"def": "又如泛滥(江河湖泊的水溢出);滥泉(从地下向上涌出的泉水);滥汜(泛滥,浮沉)", "example": null}, {"def": "浸渍,泡在水里", "example": null}, {"def": "滥车之水。--《管子·地图", "example": null}, {"def": "滥（瀍）làn", "example": null}, {"def": "⒈大水漫溢泛～成灾。〈引〉过度，无节制～用职权。", "example": null}, {"def": "⒉失真，不切实际采～忽真。～竽充数。陈词～调。", "example": null}, {"def": "⒊", "example": null}, {"def": "滥jiàn 1.泉水涌出貌。参见\\"滥泉\\"。 2.古水名。", "example": null}, {"def": "滥lǎn 1.以干果浸渍于水中作成的饮料。 2.谓以盐等腌渍食物。 3.揽聚。", "example": null}, {"def": "滥lán 1.春秋邾邑名，在今山东省滕县﹑枣庄市之间。", "example": null}]','chinese-xinhua','0'),
