('2101143296272240713','揽','1','lǎn','扌','12',NULL,'[{"def": "揽", "example": null}, {"def": "(形声。从手,览声。本义执,持)", "example": null}, {"def": "同本义", "example": null}, {"def": "俱可手揽。--《徐霞客游记·游黄山记》", "example": null}, {"def": "又如揽跋(揽辔跋涉);揽镜(持镜;对镜);揽持(把持;掌握);揽摄(把持)", "example": null}, {"def": "总揽(全面掌握);一把抓", "example": null}, {"def": "搂,拥抱,围抱", "example": null}, {"def": "采摘", "example": null}, {"def": "又如揽月(摘月。喻壮举);揽取(摘取,收取);揽结(采摘系结)", "example": null}, {"def": "挥", "example": null}, {"def": "招惹", "example": null}, {"def": "揽（攬、攇）lǎn", "example": null}, {"def": "⒈把持独～大权。", "example": null}, {"def": "⒉招来，拉过来～生意。个人包～。", "example": null}, {"def": "⒊捆，搂抱～木柴。母亲～着婴孩睡觉。", "example": null}]','chinese-xinhua','0'),
('2101143296272240714','缆','1','lǎn','纟','12',NULL,'[{"def": "缆", "example": null}, {"def": "(形声。从糸,表示与线丝有关,览声。本义系船用的粗绳)", "example": null}, {"def": "同本义", "example": null}, {"def": "结缆排鱼网。--杜甫《舟中》", "example": null}, {"def": "又如新船砍缆下水", "example": null}, {"def": "许多股绞成的粗绳", "example": null}, {"def": "缆", "example": null}, {"def": "拴;系", "example": null}, {"def": "急系缆。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "又如缆舟(以索系船);缆系(用缆栓住)", "example": null}, {"def": "缆（纜）lǎn", "example": null}, {"def": "⒈系船用的粗绳或铁索船～。解～（开船）。〈引〉许多股线绞成的粗绳索电～。～车道。", "example": null}, {"def": "⒉使用绳索将船系住～船。", "example": null}]','chinese-xinhua','0'),
