('2101143296272240731','廊','1','lánɡ','广','11',NULL,'[{"def": "廊〈名〉", "example": null}, {"def": "(形声。从广,郎声。从广”,表示与房屋有关。本义厅堂周围的屋)", "example": null}, {"def": "同本义", "example": null}, {"def": "平公恐惧,优于廊室之间。--《韩非子·十过》", "example": null}, {"def": "又如廊房(廊室。殿堂周围的房舍);廊屋(廊室);廊庑(堂前的廊屋;屋檐下的过道或独立有顶的通道)", "example": null}, {"def": "走廊", "example": null}, {"def": "高柳早莺啼,长廊春雨响。--王维《谒瑀上人》", "example": null}, {"def": "入门穿廊,过前后厅。--清·林觉民《与妻书》", "example": null}, {"def": "又如回廊(曲折环绕的走廊);游廊(连接两个或几个独立建筑物的走廊);廊牙(廊檐下像牙齿般的装饰);廊厩(围廊旁的房舍)", "example": null}, {"def": "朝廷、国家", "example": null}, {"def": "廊láng", "example": null}, {"def": "⒈有覆盖顶的过道长～。", "example": null}, {"def": "⒉屋檐下或屋内的过道～檐。走～。", "example": null}, {"def": "⒊厢房侧～。", "example": null}]','chinese-xinhua','0'),
('2101143296272240732','琅','1','lánɡ','王','11',NULL,'[{"def": "琅", "example": null}, {"def": "(形声。从玉,良声。本义似玉的美石或青色的珊瑚)", "example": null}, {"def": "同本义", "example": null}, {"def": "琅,琅玕似珠者。--《说文》", "example": null}, {"def": "厥贡惟球琳琅玕。--《书·禹贡》。传石似玉。”", "example": null}, {"def": "又如琳琅(美玉,比喻优美珍贵的东西);琅花(琅华。琅玕树所开之花,常以美称白花)", "example": null}, {"def": "门环", "example": null}, {"def": "木门仓琅根,谓宫门铜锾,言将尊贵也。--《汉书》", "example": null}, {"def": "姓", "example": null}, {"def": "琅", "example": null}, {"def": "形容清朗、响亮的声音。如琅玕(用铁链锁人。又指象声词);琅然(声音清朗的样子);琅诵(朗诵)", "example": null}, {"def": "琅 〈形〉", "example": null}, {"def": "洁白、华美如玉", "example": null}, {"def": "已过重阳半月天,琅华千点照寒烟", "example": null}, {"def": "琅（瑯）láng", "example": null}, {"def": "⒈玉的一种。［琅玕］珠子样的美石。", "example": null}, {"def": "⒉［琅琅］像声词。", "example": null}, {"def": "①玉石相击的声音。", "example": null}, {"def": "②响亮清脆的声音～～读书声。", "example": null}, {"def": "⒊琅琊山，在山东省。", "example": null}]','chinese-xinhua','0'),
