('2101143296272240734','阆','1','lánɡ','门','10',NULL,'[{"def": "阆", "example": null}, {"def": "门高大", "example": null}, {"def": "閬,门高也。从门,良声。--《说文》", "example": null}, {"def": "闶阆其寥廓兮。--《汉书·扬雄传》。注闶阆,空虚也。”", "example": null}, {"def": "又如阆阙(高大的门阙);阆阆(高大的样子)", "example": null}, {"def": "空旷", "example": null}, {"def": "郭外为之土阆。--《管子·度地》。注空旷也。”", "example": null}, {"def": "又如闶阆(建筑物中空阔的部分)", "example": null}, {"def": "阆", "example": null}, {"def": "隍,无水的城壕", "example": null}, {"def": "城外为之郭,郭外为之土阆。--《管子》", "example": null}, {"def": "胞有重阆。--《庄子·外物》。注阆谓隍,又为朗。”", "example": null}, {"def": "阆风巅的省称", "example": null}, {"def": "阆làng阆中县，在四川省。", "example": null}, {"def": "阆lǎng 1.宽大明亮。", "example": null}]','chinese-xinhua','0'),
('2101143296272240735','榔','1','lánɡ','木','12',NULL,'[{"def": "梠〈名〉", "example": null}, {"def": "同榔”。渔人结在船舷上敲击以驱鱼入网的长木棒", "example": null}, {"def": "榔láng", "example": null}, {"def": "⒈［榔头］锤子。", "example": null}, {"def": "⒉［榔槺］长、大、苯重，使用起来不方便的器物。", "example": null}]','chinese-xinhua','0'),
