('2101143296280629287','雷','1','léi','雨','13',NULL,'[{"def": "雷", "example": null}, {"def": "(象形。甲骨文,中间象闪电,圆圈和小点表示雷声。整个字形象雷声和闪电相伴而作。小篆变成了会意字,从雨,下象雷声相连之形,表示打雷下雨。本义云层放电时发出的巨响", "example": null}, {"def": ")", "example": null}, {"def": "同本义", "example": null}, {"def": "靬,阴阳薄动,靬雨生物者也。--《说文》", "example": null}, {"def": "阴阳合为雷。--《春秋·玄命苞》", "example": null}, {"def": "雷者,阴中之阳也。--《白虎通》", "example": null}, {"def": "仲春,雷乃发声,仲秋,雷始收声。--《礼记·月令》", "example": null}, {"def": "雷以动之,风以散之,雨以润之。--《易·说卦》", "example": null}, {"def": "阴阳相薄为雷。--《淮南子·坠形》", "example": null}, {"def": "天下应之如雷霆。--《荀子·儒效》", "example": null}, {"def": "如雷如霆,徐方震惊。--《诗·大雅·常武》", "example": null}, {"def": "峭壁", "example": null}, {"def": "雷léi", "example": null}, {"def": "⒈云层放电时发出的巨响～声。～电交加。", "example": null}, {"def": "却相同两份答卷～同。", "example": null}, {"def": "⒉一类爆炸性的武器地～。鱼～。", "example": null}, {"def": "⒊", "example": null}, {"def": "雷lèi 1.通\\"擂\\"。 2.通\\"祑\\"。古时作战用以击敌之石块。", "example": null}]','chinese-xinhua','0'),
('2101143296280629288','嫘','1','léi','女','14',NULL,'[{"def": "嫘", "example": null}, {"def": "姓", "example": null}, {"def": "嫘,姓也。黄帝娶于西陵氏之女,是为嫘祖。嫘祖好远游,死于道,后人祀以为行神。--《集韵》", "example": null}, {"def": "嫘祖", "example": null}, {"def": "嫘léi", "example": null}]','chinese-xinhua','0'),
('2101143296280629289','缧','1','léi','纟','14',NULL,'[{"def": "缧", "example": null}, {"def": "(形声。从糸,表示与绳索有关,累声。本义黑索) 同本义", "example": null}, {"def": "虽在缧絰之中。--《论语·公冶长》", "example": null}, {"def": "缧", "example": null}, {"def": "引申为捆绑,拘禁", "example": null}, {"def": "缠绕", "example": null}, {"def": "缧绁", "example": null}, {"def": "虽在缧绁之中,非其罪也。--《论语·公冶长》", "example": null}, {"def": "冤狱平反解缧绁,已死得生诬得雪。--陈基《乌夜啼引》", "example": null}, {"def": "缧léi捆绑犯人的绳索。〈引〉监狱～绁（拘禁，囚禁）。系～（捆绑，拘禁）。", "example": null}]','chinese-xinhua','0'),
