('2101143296280629301','肋','1','lèi','月','6',NULL,'[{"def": "肋〈名〉 lei", "example": null}, {"def": "(形声。从肉,力声。本义肋骨)", "example": null}, {"def": "同本义", "example": null}, {"def": "肋,肋骨也。--《说文》", "example": null}, {"def": "肋,勒也,所以捡勒五脏也。--《释名·释形体》", "example": null}, {"def": "又如肋下(腋下);肋肢(腋下,胳肢窝);肋窝(也作肋罗”。胸前腋下的部位。通称胳肢窝)", "example": null}, {"def": "房屋或其它建筑物中的构架木材", "example": null}, {"def": "胸部的侧面", "example": null}, {"def": "肋骨", "example": null}, {"def": "许多成对的骨质或部分为软骨的杆状体之一,起着加固大多数脊椎动物驱体侧壁并保护内脏的作用,通常其背部一端与脊柱相接合,而腹部一端有时也以形态学上认为是非骨化部", "example": null}, {"def": "分的肋软骨形式与胸骨连接,对哺乳动物来", "example": null}, {"def": "肋lē", "example": null}, {"def": "⒈", "example": null}, {"def": "肋lèi", "example": null}, {"def": "⒈胸部的两侧两～。～骨。", "example": null}]','chinese-xinhua','0'),
('2101143296280629302','泪','1','lèi','氵','8',NULL,'[{"def": "泪", "example": null}, {"def": "(形声。从水,戾声。简化字泪”是个从水”从目”的会意字。本义眼泪)", "example": null}, {"def": "同本义", "example": null}, {"def": "望其碑者莫不流涕,杜预因名为坠泪碑。--《晋书·羊祜传》", "example": null}, {"def": "士皆垂泪涕。--《战国策·燕策》", "example": null}, {"def": "剑外忽传收蓟北,初闻涕泪满衣裳。--杜甫《闻官军收河南河北》", "example": null}, {"def": "却与小姑别,泪落连珠子。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "又如涕泪(先秦时期,涕”指眼泪,后来出现了泪”,表示眼泪,与涕”同义并用);泪波(泪水如波);泪泉(指眼泪);泪球(泪珠,泪滴);泪晶(泪珠)", "example": null}, {"def": "引申指某些形似眼泪的东西", "example": null}, {"def": "泪（渋）lèi", "example": null}, {"def": "⒈眼泪，泪腺分泌出的液体热～。流～。", "example": null}, {"def": "⒉像泪的东西蜡炬成灰～始干。", "example": null}, {"def": "泪lì 1.疾貌。 2.见\\"凄泪\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296280629303','类','1','lèi','米','9',NULL,'[{"def": "类", "example": null}, {"def": "(形声。从犬,?", "example": null}, {"def": "同本义", "example": null}, {"def": "类,种类相似,惟犬最甚。--《说文》", "example": null}, {"def": "皆守株之类。--《韩非子·五蠹》", "example": null}, {"def": "无法者以类举。--《荀子·王制》", "example": null}, {"def": "壹统类。╠《荀子·非十二子》", "example": null}, {"def": "其负类反伦,不可胜言也。--《列子·仲尼》", "example": null}, {"def": "王之不王,是折枝之类也。--《孟子·梁惠王上》", "example": null}, {"def": "同类相从,同声相应,固天之理也。--《庄子·渔父》", "example": null}, {"def": "纸灰之类冒之。--宋·沈括《梦溪笔谈·活板》", "example": null}, {"def": "又", "example": null}, {"def": "亦类此耳。", "example": null}, {"def": "梨栗枣柿之类。--宋·司马光《训俭示康》", "example": null}, {"def": "又如类考(学院的科考);类族(事", "example": null}, {"def": "类（類）lèi", "example": null}, {"def": "⒈种，具有共同特征事物的综合同～。种～。分门别～。物伤其～。", "example": null}, {"def": "⒉似，像画虎～狗。刻鹄～鹜。", "example": null}, {"def": "⒊大抵，大致～多如斯。", "example": null}]','chinese-xinhua','0'),
('2101143296280629304','累','1','lèi','糸','11',NULL,'[{"def": "累", "example": null}, {"def": "(形声。从糸,表示与线丝有关,畾(雷)声。本义绳索)", "example": null}, {"def": "同本义。也作缧”", "example": null}, {"def": "累,一曰大索也。--《说文》", "example": null}, {"def": "两释累囚。--《左传·成公三年》", "example": null}, {"def": "以剑斫绝累。--《汉书·李广传》", "example": null}, {"def": "又如累绁(绑罪犯的绳索。引申为囚禁,牢狱);系累(系结绳索);累囚(被拘囚的人)", "example": null}, {"def": "指交配期的牡牛", "example": null}, {"def": "累", "example": null}, {"def": "重叠;接连成串", "example": null}, {"def": "层台累榭,临高山些。--《楚辞·招魂》", "example": null}, {"def": "又如累棋(堆叠棋子);累叠(堆叠);累纸(接连许多张纸)", "example": null}, {"def": "拘系;捆绑", "example": null}, {"def": "系累其弟子。--", "example": null}, {"def": "累lèi", "example": null}, {"def": "⒈疲劳劳～。", "example": null}, {"def": "⒉使疲劳莫～着她。", "example": null}, {"def": "累（纍）léi", "example": null}, {"def": "⒈连缀或捆。", "example": null}, {"def": "①连续成串硕果～ ～。", "example": null}, {"def": "②狼狈不堪的样子～ ～若丧家之犬。", "example": null}, {"def": "⒉绳索。〈引〉捆绑。", "example": null}, {"def": "⒊缠绕。", "example": null}, {"def": "累（纍）lěi", "example": null}, {"def": "⒈重叠，堆积～土为山。日积月～。", "example": null}, {"def": "⒉屡次，众多～战皆捷。罪行～ ～。", "example": null}, {"def": "⒊牵连～及。连～。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "累luǒ 1.裸露。", "example": null}]','chinese-xinhua','0'),
