('2101143296280629332','塄','1','lénɡ','土','12',NULL,'[{"def": "塄〈名〉", "example": null}, {"def": "(同棱。本义四方木;棱角)", "example": null}, {"def": "纷纷从稻地塄坎上的许多小径,向梁三老汉的草棚院走去。--柳青《创业史》", "example": null}, {"def": "塄léng也叫\\"地塄\\"。田边或地边的坡坎。", "example": null}]','chinese-xinhua','0'),
('2101143296280629333','棱','1','lénɡ','木','12',NULL,'[{"def": "棱", "example": null}, {"def": "不棱登”助词。常用为某些形容词的后缀。如红不棱登;花不棱登", "example": null}, {"def": "棱", "example": null}, {"def": "(俗作楞”和稜”。形声。从木,夌声。本义有四角的木)", "example": null}, {"def": "同本义", "example": null}, {"def": "上觚稜而栖金爵。--班固《西都赋》", "example": null}, {"def": "木四方为棱。--汉·服虔《通俗文》", "example": null}, {"def": "同一物体的面与面的交接处,即棱角", "example": null}, {"def": "棱 〈形〉", "example": null}, {"def": "威势", "example": null}, {"def": "威稜憺乎邻国。--《汉书·李广传》", "example": null}, {"def": "刚稜疾恶。--《后汉书·王允传》。注威稜也。”", "example": null}, {"def": "又如棱光(威严的目光);棱眼(威严的眼睛);棱棱(威严的样子)", "example": null}, {"def": "严厉", "example": null}, {"def": "棱（稜）、楞léng", "example": null}, {"def": "⒈物体上不同方向的两个平面连结的部分有～有角。", "example": null}, {"def": "⒉物体表面上突起的条状部分瓦～子。洗衣板～儿。", "example": null}, {"def": "棱（稜）líng", "example": null}, {"def": "⒈", "example": null}, {"def": "棱lèng 1.田埂。古亦用作约计田亩远近多少的单位。 2.失神，发呆。", "example": null}, {"def": "棱lēng 1.见\\"红不棱登\\"﹑\\"花不棱登\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296280629334','楞','1','lénɡ','木','13',NULL,'[{"def": "楞〈名〉", "example": null}, {"def": "(同棱”。本义四方木;棱角)", "example": null}, {"def": "同本义", "example": null}, {"def": "物体上一条条凸起来的部分", "example": null}, {"def": "楞〈形〉", "example": null}, {"def": "失神、发呆", "example": null}, {"def": "班惊楞,逡巡来答。--干宝《搜神记》", "example": null}, {"def": "又如楞子眼(因酒醉或其他原因而眼神呆滞);楞楞 (傻傻的模样);楞神(失神、发呆);楞然(惊奇发呆貌);楞中楞(发呆貌);楞柯柯(亦作楞磕磕”、楞呵呵”。形容发呆的", "example": null}, {"def": "样子)", "example": null}, {"def": "凶狠;蛮横", "example": null}, {"def": "冒失,鲁", "example": null}, {"def": "楞léng同\\"棱\\"。", "example": null}, {"def": "【楞场】木材采伐运输过程中，汇集、堆存和转运的场所。", "example": null}, {"def": "楞léng", "example": null}, {"def": "①棱角。~角。", "example": null}, {"def": "②物体上一条条凸起来的部分。", "example": null}, {"def": "③凸起，暴起。", "example": null}, {"def": "④量词。", "example": null}, {"def": "⑤译音用字。~伽。", "example": null}, {"def": "楞lèng", "example": null}, {"def": "①失神，发呆。", "example": null}, {"def": "②凶狠;蛮横。", "example": null}, {"def": "③冒失，鲁莽。", "example": null}, {"def": "④猛，猛烈。", "example": null}, {"def": "⑤副词。宁，宁愿。", "example": null}, {"def": "⑥副词。竟，竟然。", "example": null}, {"def": "⑦副词≤，非常。", "example": null}, {"def": "⑧词缀。", "example": null}]','chinese-xinhua','0'),
