('2101143296314183680','戾','1','lì','户','8',NULL,'[{"def": "戾〈动〉", "example": null}, {"def": "(会意。从犬,从户。犬从关着的门中挤出,必曲其身。本义弯曲)", "example": null}, {"def": "同本义", "example": null}, {"def": "戾,曲也。从犬,出户下身曲戾也。--《说文》", "example": null}, {"def": "饮必小咽,端直无戾。--《吕氏春秋》", "example": null}, {"def": "又如戾契(曲折辗转)", "example": null}, {"def": "至,到达", "example": null}, {"def": "翰飞戾天。--《诗·小雅·四月》", "example": null}, {"def": "鲁侯戾止。--《诗·鲁颂·泮水》", "example": null}, {"def": "戾于敝邑。--《国语·鲁语上》", "example": null}, {"def": "古者天灾降戾。--《国语·周语下》", "example": null}, {"def": "鸢飞戾天者。--吴均《与朱元思书》", "example": null}, {"def": "又如戾止(来临);戾于(至于)", "example": null}, {"def": "违背,违反", "example": null}, {"def": "如子之说,文虽相反,义不相戾。--唐·韩愈《论语笔解》", "example": null}, {"def": "举事戾苍天。--《淮南子·", "example": null}, {"def": "戾lì", "example": null}, {"def": "⒈罪，罪过免～。", "example": null}, {"def": "⒉凶暴，猛烈暴～。猛～。", "example": null}, {"def": "⒊违背，违反相～。〈引〉乖张，不讲情理猛贪而～。", "example": null}, {"def": "⒋至，到鸢飞～天（鸢老鹰）。", "example": null}, {"def": "戾liè 1.象声词。参见\\"戾戾\\"。 2.同\\"奼\\"。参见\\"戾契\\"。 3.通\\"捩\\"。扭转。 4.通\\"捩\\"。折断。", "example": null}]','chinese-xinhua','0'),
('2101143296314183681','枥','1','lì','木','8',NULL,'[{"def": "枥", "example": null}, {"def": "(形声。从木,厉声。本义喂马的槽)", "example": null}, {"def": "同本义", "example": null}, {"def": "养马器也。--《方言五》枥注", "example": null}, {"def": "老骥伏枥,志在千里。--汉·曹操《步出夏门行》", "example": null}, {"def": "骈死于槽枥之间。--唐·韩愈《杂说》", "example": null}, {"def": "又如枥马(拴在马槽上马);枥厩(饲马器和养马房);枥骥(俯首马槽上的骏马)", "example": null}, {"def": "马房", "example": null}, {"def": "气劳者,缓系之枥上。--《齐民要术·养牛马驴骡》", "example": null}, {"def": "古书上指栎树", "example": null}, {"def": "时见松枥皆十围。--唐·韩愈《山石》", "example": null}, {"def": "枥（櫪）lì马槽老骥伏～，志在千里（骥千里马）。", "example": null}]','chinese-xinhua','0'),
('2101143296314183682','隶','1','lì','隶','8',NULL,'[{"def": "隶", "example": null}, {"def": "(隶又樆尾会意。本义逮、捕、追及)", "example": null}, {"def": "同本义", "example": null}, {"def": "隶,及也,从又从尾省,又持尾者从后及之也。--《说文》", "example": null}, {"def": "跟从;附属", "example": null}, {"def": "隶而从者。--唐·柳宗元《至小丘西小石潭记》", "example": null}, {"def": "不隶于宫观之籍。--明·顾炎武《复庵记》", "example": null}, {"def": "又如隶事(以故事相互隶属)", "example": null}, {"def": "通离”。流离", "example": null}, {"def": "饿馑流隶,饥寒道路。--《汉书·叙传·王命论》", "example": null}, {"def": "通肄”", "example": null}, {"def": "检查", "example": null}, {"def": "关东吏隶郡国出入关者。--《史记·酷吏列传》", "example": null}, {"def": "练习", "example": null}, {"def": "廼令群臣习隶。--《史记·刘敬叔孙通列传》", "example": null}, {"def": "隶（隸、隷）lì", "example": null}, {"def": "⒈附属，属于～属。直～中央。", "example": null}, {"def": "⒉封建时代的衙役、差役～卒。皂～。", "example": null}, {"def": "⒊旧时地位低、被奴役的人奴～。仆～。", "example": null}, {"def": "⒋一种汉字字体，相传是秦朝程邈所创造～书。", "example": null}, {"def": "隶dài 1.及;捕获◇作\\"逮\\"。", "example": null}]','chinese-xinhua','0'),
