('2101143296318378003','奁','1','lián','大','7',NULL,'[{"def": "奁", "example": null}, {"def": "古代盛梳妆用品的匣子", "example": null}, {"def": "弹棋始自魏宫内用妆奁戏。--《世说新语·巧艺》", "example": null}, {"def": "凝走弄香奁,拔脱金屈戌。--李商隐《骄儿诗》", "example": null}, {"def": "又如妆奁(香奁。放梳妆用品的器具)", "example": null}, {"def": "泛指盛放器物的匣子", "example": null}, {"def": "…并两部书,茶奁、茶杯而已。--《红楼梦》", "example": null}, {"def": "又如一奁饭(一盒饭);茶奁(茶壶)", "example": null}, {"def": "陪嫁的衣物等", "example": null}, {"def": "奁资", "example": null}, {"def": "奁（妝、卾、卽）lián", "example": null}, {"def": "⒈〈古〉妇女梳妆用的镜匣和盛化妆品等的器皿。", "example": null}, {"def": "⒉精巧的匣子棋～。宝～。", "example": null}, {"def": "⒊旧时泛指嫁妆妆～。", "example": null}]','chinese-xinhua','0'),
('2101143296318378004','连','1','lián','辶','7',NULL,'[{"def": "连", "example": null}, {"def": "(会意。从辵,从车。本义人拉的车)", "example": null}, {"def": "同本义", "example": null}, {"def": "遙,负车也。--《说文》。段注连即古文輦也。", "example": null}, {"def": "连车组輓。--《周礼·故书巾车》", "example": null}, {"def": "与其輂连。--《周礼·乡师》", "example": null}, {"def": "行服连轺辇者。--《管者·海王》", "example": null}, {"def": "民相连而从之。--《庄子·让王》。郑君、房君、司马君皆云读为辇。”", "example": null}, {"def": "姻亲关系", "example": null}, {"def": "又如连亲(连姻);连昏(连婚。本有姻亲关系而又结亲。即", "example": null}, {"def": "连lián", "example": null}, {"def": "⒈连接，相接～年丰收。两岸～山。〈引〉连续～夜（夜间不休息）工作。烽火～三月。", "example": null}, {"def": "⒉联合外～友邦。", "example": null}, {"def": "⒊带，加上～说带拉。～根拔掉。～他俩总共四人。", "example": null}, {"def": "⒋就是，即使（常跟\\"都\\"、\\"也\\"连用）～几分钱的使用，她都要精打细算。～一个字也得弄明白。", "example": null}, {"def": "⒌军队编制单位，是\\"营\\"的下一级，\\"排\\"的上一级。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "连liǎn 1.艰难。", "example": null}, {"def": "连làn 1.见\\"连石\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296318378005','帘','1','lián','巾','8',NULL,'[{"def": "帘〈名〉", "example": null}, {"def": "旧时酒家、茶馆作店招的旗帜,用布做成", "example": null}, {"def": "白鸟窥鱼网,青帘认酒家。--唐·郑谷《旅寓洛南村舍》", "example": null}, {"def": "帘", "example": null}, {"def": "(形声。从竹,廉声。本义门帘)", "example": null}, {"def": "帘子,遮蔽门窗的用具", "example": null}, {"def": "簾,堂簾也。--《说文》", "example": null}, {"def": "簾,户蔽也。--《声类》。", "example": null}, {"def": "严持箧书,置饰室簾南。--《汉书》", "example": null}, {"def": "草色入簾青。--唐·刘禹錫《陋室銘》", "example": null}, {"def": "入其舍,则密室垂簾。--《聊斋志异·促織》", "example": null}, {"def": "又如簾帷(遮蔽閠窗的簾子、布幕);簾籠(窗簾和窗牖);簾旌(簾端所緔之布帛);簾政(皇太後垂簾聽政,故名);簾庑(指堂前廊檐垂簾之處)", "example": null}, {"def": "同奁”", "example": null}, {"def": "帘（", "example": null}, {"def": "⒈簾）lián", "example": null}, {"def": "⒈用布、塑料、竹片、或苇子等做成遮蔽门窗的东西门～。窗～。", "example": null}, {"def": "⒉旧时商店门口做标志的旗帜茶～。酒～。", "example": null}]','chinese-xinhua','0'),
('2101143296318378006','怜','1','lián','忄','8',NULL,'[{"def": "怜", "example": null}, {"def": "(形声。从心,粦声。本义哀怜,怜悯)", "example": null}, {"def": "同本义", "example": null}, {"def": "憐,哀也。从心。粦声。字亦作怜。--《说文》", "example": null}, {"def": "矜憐抚掩之也。--《尔雅》", "example": null}, {"def": "独不怜公子姊邪?--《史记·魏公子列传》", "example": null}, {"def": "若俯首贴耳,摇尾而乞怜者,非我之志也。--韩愈《应科目时与人书》", "example": null}, {"def": "且喜且怜之。--《史记·淮阴侯列传》", "example": null}, {"def": "天子怜百姓新劳苦,故且休之。--《史记·郦生陆贾列传》", "example": null}, {"def": "所怜者。--清·袁枚《祭妹文》", "example": null}, {"def": "又如可怜(值得怜悯);怜见(哀矜,怜悯);怜拯(怜悯拯救);怜鉴(哀怜审察);怜闵(哀怜,同情)", "example": null}, {"def": "爱,惜", "example": null}, {"def": "憐,爱也。--《尔雅》", "example": null}, {"def": "楚人怜之。--《史记·陈", "example": null}, {"def": "怜（憐）lián", "example": null}, {"def": "⒈同情～惜。～悯。", "example": null}, {"def": "⒉爱惜～爱。", "example": null}, {"def": "⒊", "example": null}, {"def": "①可爱百花高楼更可～。", "example": null}, {"def": "②值得同情可～身上衣正单。", "example": null}, {"def": "怜líng 1.见\\"怜悧\\"﹑\\"怜牙悧齿\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296318378007','涟','1','lián','氵','10',NULL,'[{"def": "涟", "example": null}, {"def": "小波,风吹水面所形成的波纹", "example": null}, {"def": "河水清且涟漪。--《诗·魏风·伐檀》", "example": null}, {"def": "又如涟猗(波纹,小水波)", "example": null}, {"def": "水名", "example": null}, {"def": "在江苏省涟水县北,一名涟河", "example": null}, {"def": "在湖南省中部,源出新邵县,东流经湘乡,至湘潭注入湘江", "example": null}, {"def": "涟", "example": null}, {"def": "泪流不断的样子", "example": null}, {"def": "不见复关,泣涕涟涟。--《诗·魏风·氓》", "example": null}, {"def": "中心孔悼,涕泪涟湎。--王粲《赠蔡子笃》", "example": null}, {"def": "又如涟如(涟洳,涟湎。泪涕交流的样子);涟落(泪珠下滴);涟涟(泪流不止的样子)", "example": null}, {"def": "细微", "example": null}, {"def": "涟lián风吹水面所起的波纹。", "example": null}, {"def": "①细小的水波。", "example": null}, {"def": "②泪流不止的样子涕泣～漪。", "example": null}, {"def": "涟lán 1.大波。", "example": null}]','chinese-xinhua','0'),
('2101143296318378008','莲','1','lián','艹','10',NULL,'[{"def": "莲", "example": null}, {"def": "(形声。从苃,连声。本义莲子,荷的种子)", "example": null}, {"def": "同本义", "example": null}, {"def": "莲,扶渠之实也。--《说文》", "example": null}, {"def": "荷其实莲。--《尔雅》。注谓房也。”", "example": null}, {"def": "益树莲茭。--《淮南子·本经》", "example": null}, {"def": "莲藕觚卢。--《汉书·司马相如传》", "example": null}, {"def": "又如莲的(莲房之实。即莲子);莲须(即莲心。本为莲花的雄蕊。又叫莲蕊须);莲子花(指爱怜儿子的老人。莲子谐音怜子)", "example": null}, {"def": "也称芙蓉、芙蕖、菡萏等。多年生草本植物,生浅水中。叶子大而圆,叫荷叶。花有粉红、白色两种。种子叫莲子,包在倒圆锥形的花托内,合称莲蓬。地下茎叫藕", "example": null}, {"def": "接天莲叶无穷碧。--唐·杜甫《江畔独步", "example": null}, {"def": "莲lián即\\"荷\\"。", "example": null}, {"def": "莲liǎn 1.地名用字『有莲勺县。故址在今陕西省渭南县东北。", "example": null}]','chinese-xinhua','0'),
