('2101143296318378070','踉','1','liànɡ','足','14',NULL,'[{"def": "跳踉”", "example": null}, {"def": "又如跳踉(纵跃;窜跳)", "example": null}, {"def": "踉liáng", "example": null}, {"def": "踉liàng", "example": null}, {"def": "踉làng 1.见\\"踉?\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296318378071','亮','1','liànɡ','亠','9',NULL,'[{"def": "亮〈形〉", "example": null}, {"def": "(《说文》一说本作倞”,后移人”于京”下,又变作儿”,并省去京”中一竖。本义明亮)", "example": null}, {"def": "同本义", "example": null}, {"def": "亮,明也。--《说文》。段注古人名亮者字明。”", "example": null}, {"def": "如诸葛亮,字孔明。", "example": null}, {"def": "皎皎亮月。--《文选·嵇康·杂诗》", "example": null}, {"def": "寸心若不亮。--谢灵运《初发·石首城诗》", "example": null}, {"def": "且火德承尧,虽昧必亮。--《后汉书·苏竟传》。李贤注亮,明也。”", "example": null}, {"def": "又如亮钟(更楼上报天亮的钟声);亮隔(亮槅。有透光花格的窗户、门窗等);亮色(明亮的色彩);亮油油(形容光亮而润泽);亮闪(明亮);亮莹莹(形容光亮透明);亮藿藿(形容明", "example": null}, {"def": "光耀眼);亮灼灼(犹亮晶", "example": null}, {"def": "亮、", "example": null}, {"def": "⒋喨liàng", "example": null}, {"def": "⒈明，光线，发光没～。天快～了。电灯～了。〈引〉灯、烛等快拿～儿来。", "example": null}, {"def": "⒉显示出来～相。～出来，大家看看。", "example": null}, {"def": "⒊明朗，清楚明～。照～了我的心。打开窗子说～话。", "example": null}, {"def": "⒋［嘹亮］", "example": null}, {"def": "⒌", "example": null}, {"def": "亮liáng 1.见\\"亮阴\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296318378072','谅','1','liànɡ','讠','10',NULL,'[{"def": "谅", "example": null}, {"def": "(形声。从言,京声。本义诚实;信实)", "example": null}, {"def": "同本义", "example": null}, {"def": "谅,信也。--《说文》", "example": null}, {"def": "众信曰谅。--《方言一》", "example": null}, {"def": "请肆简谅。--《礼记·内则》", "example": null}, {"def": "友直友谅。--《论语》", "example": null}, {"def": "易直子谅之心。--《礼记·祭义》", "example": null}, {"def": "私直怜兮何极,心怦怦兮谅直。--《楚辞·九辩》", "example": null}, {"def": "又如谅直(诚信正直) ;谅士(诚信之士);谅节(高尚的节操);谅实(真诚)", "example": null}, {"def": "固执,坚持己见", "example": null}, {"def": "君子贞而不谅。--《论语·卫灵公》", "example": null}, {"def": "谅", "example": null}, {"def": "谅解", "example": null}, {"def": "母也天只,不谅人只。--《诗·鄘风·柏舟》", "example": null}, {"def": "未必谅某此心也。--欧阳修《与刁景纯学士书》", "example": null}, {"def": "又如本着互谅互让", "example": null}, {"def": "谅liàng", "example": null}, {"def": "⒈原谅，体谅见～。～我此心。", "example": null}, {"def": "⒉料想～必。～他不敢。", "example": null}, {"def": "⒊诚信～哉斯言。", "example": null}, {"def": "⒋", "example": null}, {"def": "谅liáng 1.通\\"良\\"。《礼记．乐记》﹕\\"致乐以治心，则易﹑直﹑子﹑谅之心，油然生矣。\\"孙希旦集解﹕\\"朱子云﹕\'子﹑谅\'，当从《韩诗外传》作\'慈﹑良\'。\\"一说谅字仍用", "example": null}, {"def": "本义，义为诚信。孔颖达疏﹕\\"则和易﹑正直﹑子爱﹑诚信之心油油然从内而生矣。\\" 2.古州名。唐置。", "example": null}]','chinese-xinhua','0'),
('2101143296318378073','辆','1','liànɡ','车','11',NULL,'[{"def": "辆", "example": null}, {"def": "(形声。从车,两声。古代的车一般有两个轮子,故车一乘即称一两,后来写作辆”,总称为车辆”)", "example": null}, {"def": "用于车,指单个数", "example": null}, {"def": "指鞋一双", "example": null}, {"def": "一辆小鞋儿。--汤显祖《紫钗记》", "example": null}, {"def": "辆（輛）liàng量词，指车三～轿车。", "example": null}]','chinese-xinhua','0'),
