('2101143296322572342','列','1','liè','刂','6',NULL,'[{"def": "列〈动〉", "example": null}, {"def": "(形声。从刀,本义割,分)", "example": null}, {"def": "裂”的古字。分割;分解", "example": null}, {"def": "列,分解也。--《说文》", "example": null}, {"def": "古者列地建国。--《荀子》", "example": null}, {"def": "大袂列。--《管子·五辅》。注决之也。”", "example": null}, {"def": "两骖列两服入厩。--《荀子·哀公》。翱", "example": null}, {"def": "又如列断(裂断);列地(列土。分地封侯);列缺(高空中闪电所现出的空隙闪电);列土分茅(古代帝王用茅土分封诸侯的仪式)", "example": null}, {"def": "排列", "example": null}, {"def": "列敌度宜谓之义。--《太玄·玄摛》。注序也。”", "example": null}, {"def": "森然布列。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "张筵列鼎。--清·周容《芋老人传》", "example": null}, {"def": "奇峰错列。--《徐霞客游记·游黄山记》", "example": null}, {"def": "江", "example": null}, {"def": "列liè", "example": null}, {"def": "⒈排队，摆出，安排～队。陈～。～入议程。", "example": null}, {"def": "⒉行列。排成的行（纵行和横行的总称）队～。", "example": null}, {"def": "⒊分，类～开。～入。不在此～。", "example": null}, {"def": "⒋各，众多～位。～国。～星。", "example": null}, {"def": "⒌量词（用于成行列的）两～火车。排成三～。", "example": null}]','chinese-xinhua','0'),
('2101143296322572343','劣','1','liè','力','6',NULL,'[{"def": "劣〈形〉", "example": null}, {"def": "(会意。从力,从少。这是合并两个字的意思而构成的会意字。本义弱;小)", "example": null}, {"def": "同本义", "example": null}, {"def": "劣,弱也。--《说文》", "example": null}, {"def": "寿命长短,骨体强劣,各有人焉。--曹植《辩道论》", "example": null}, {"def": "又如劣马(瘦弱的马;又指烈性马);劣弱(衰弱;懦弱)", "example": null}, {"def": "少,不足", "example": null}, {"def": "夫德劣故用兵,犯法故施刑。--《论衡》", "example": null}, {"def": "不好;低劣,与优”相对", "example": null}, {"def": "优劣异名。--《论衡·气寿》", "example": null}, {"def": "必能使行阵和睦,优劣得所。--诸葛亮《出师表》", "example": null}, {"def": "羸牛劣马。--《齐民要术·养牛马》", "example": null}, {"def": "又如劣性(恶劣的品性);劣缺(不好,恶劣);劣衿(品行恶劣的生员)", "example": null}, {"def": "劣 〈动〉", "example": null}, {"def": "认为不好", "example": null}, {"def": "劣liè", "example": null}, {"def": "⒈恶，坏～迹。恶～。土豪～绅。", "example": null}, {"def": "⒉差的，弱小～等。～势。", "example": null}, {"def": "⒊副词。仅，只。", "example": null}]','chinese-xinhua','0'),
