('2101143296322572375','麟','1','lín','鹿','23',NULL,'[{"def": "麟", "example": null}, {"def": "(形声。从鹿,粦声。本义大鹿)", "example": null}, {"def": "同本义", "example": null}, {"def": "麟,大牝鹿也。--《说文》", "example": null}, {"def": "麐,牝麒也。--《说文》。朱骏声曰经典皆以麟为之。”段曰经典无作麐者。”", "example": null}, {"def": "射麋脚麟。--汉·司马相如《子虚赋》", "example": null}, {"def": "解罘放麟。--张衡《东京赋》。薛注大鹿曰麟。”", "example": null}, {"def": "惧失麟鹿而获艾貑。--《潜夫论·贤难》", "example": null}, {"def": "麒麟", "example": null}, {"def": "单呼麟者,大牡鹿也;呼麟麟者,仁兽也。麒麟可单呼麟。--《说文》段注", "example": null}, {"def": "西狩获麟。--《春秋·哀公十四年》", "example": null}, {"def": "又如凤毛麟角;麟阁(又称麟台。麒麟阁,汉宣帝时曾在麒麟阁内绘功臣图像,以表其功);", "example": null}, {"def": "麟（麐）lín", "example": null}]','chinese-xinhua','0'),
('2101143296322572376','邻','1','lín','阝','7',NULL,'[{"def": "邻", "example": null}, {"def": "(形声。从邑,粦声。从邑”,表示与行政区域有关。本义古代的一种居民组织。五家为邻)", "example": null}, {"def": "周朝地方基层组织的户口单位", "example": null}, {"def": "邻,五家为邻。--《说文》", "example": null}, {"def": "五家为邻,五邻为里。--《周礼·地官·遂人》", "example": null}, {"def": "渔翁家苇间,蜗舍无邻伍。--陈造《泊慈湖北岸》", "example": null}, {"def": "又如邻伍(古制一邻有五家,五家为伍,故称邻伍);邻里", "example": null}, {"def": "相连接的家户。邻居;邻国", "example": null}, {"def": "东邻杀牛。--《礼记·坊记》", "example": null}, {"def": "武义动于南邻。--《汉书·扬雄传》", "example": null}, {"def": "邻人京城氏。--《列子·汤问》", "example": null}, {"def": "其邻人之父。--《韩非子·说难》", "example": null}, {"def": "邻有敝舆。--《墨子·公", "example": null}, {"def": "邻（鄰、雘）lín", "example": null}, {"def": "⒈接近的，住处靠近的人家～近。～国。～居。四～。比～。", "example": null}, {"def": "⒉〈古〉一种居民组织。五家为～，五～为里。", "example": null}]','chinese-xinhua','0'),
('2101143296322572377','林','1','lín','木','8',NULL,'[{"def": "林〈名〉", "example": null}, {"def": "(会意。从二木。表示树木丛生。本义丛聚的树木或竹子)", "example": null}, {"def": "同本义", "example": null}, {"def": "林,平土有丛木曰林。--《说文》", "example": null}, {"def": "野外谓之林。--《尔雅·释地》", "example": null}, {"def": "有鹤在林。--《诗·小雅·白华》", "example": null}, {"def": "每大林麓。--《周礼·地官·序官·林衡》。注竹木生平地曰林。”", "example": null}, {"def": "山中丛木曰林。林,森也。--《释名》", "example": null}, {"def": "忽逢桃花林,夹岸数百步。--晋·陶潜《桃花源记》", "example": null}, {"def": "蔽林间窥之。--《黔之驴》", "example": null}, {"def": "又如竹木林;山林(有山有树林的地方);深山老林;防护林;林落(树林,丛林);林浪(林琅、琳琅、林郎。丛林);林麓(森林与山脚);林泉(林木与泉石);林错", "example": null}, {"def": "林lín", "example": null}, {"def": "⒈成片的树木或竹子等树～。竹～。森～。防护～。封山育～。", "example": null}, {"def": "⒉指林业农～牧副渔。", "example": null}, {"def": "⒊〈喻〉林立的、众多的，在一起的人或事石～。碑～。儒～。著作之～。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296322572378','临','1','lín','丨','9',NULL,'[{"def": "临", "example": null}, {"def": "(会意。金文字形,右边是人,左上角象人的眼睛,左下角象众多的器物。整个字形象人俯视器物的样子。本义从高处往低处察看)", "example": null}, {"def": "同本义", "example": null}, {"def": "临,监临也。从卧,品声。--《说文》。按,隐几视下之称。》", "example": null}, {"def": "临,视也。--《尔雅》", "example": null}, {"def": "不临深豨,不知地之厚也。--《荀子·劝学》", "example": null}, {"def": "上帝临女。--《诗·大雅·大明》", "example": null}, {"def": "有亭翼然临于泉上。--宋·欧阳修《醉翁亭记》", "example": null}, {"def": "又如居高临下;如临深渊;临轩(在殿前平台上接见臣属);临下(从高望下);临见(居上视下看见)", "example": null}, {"def": "引申为从上监视着", "example": null}, {"def": "临长晋国者。--《国语·晋语》", "example": null}, {"def": "临（舝）lín", "example": null}, {"def": "⒈从高处往低处看居高～下（形容不可阻挡的形势）。", "example": null}, {"def": "⒉到，遇到身～其境。双喜～门。～渴掘井。", "example": null}, {"def": "⒊将要～走。～别。", "example": null}, {"def": "⒋面对，挨着，靠近～战。～街。～危不惧。", "example": null}, {"def": "⒌对照着字、画摹仿～帖。～摹。", "example": null}, {"def": "⒍〈古〉帝王上朝～朝。～政。", "example": null}, {"def": "⒎", "example": null}, {"def": "①到时候，当时事先准备好，免得～时着急。", "example": null}, {"def": "②暂时，短期，非经常的～时措施。", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "临lìn 1.哭吊死者。", "example": null}]','chinese-xinhua','0'),
