('2101143296335155209','拎','1','līn','扌','8',NULL,'[{"def": "拎〈动〉", "example": null}, {"def": "把鱼接在手里…拎着尾巴,望汤锅里一掼。--《儒林外史》", "example": null}, {"def": "又如拎着桶去打水;拎东西", "example": null}, {"def": "拎līn〈方〉提把塑料袋～着。", "example": null}, {"def": "拎līng 1.用手提起。", "example": null}]','chinese-xinhua','0'),
('2101143296335155210','伶','1','línɡ','亻','7',NULL,'[{"def": "伶〈名〉", "example": null}, {"def": "(形声。从人,令声。本义古乐官名、相传黄帝时有伶伦,世掌乐官)", "example": null}, {"def": "同本义", "example": null}, {"def": "伶,弄臣也。--《说文》", "example": null}, {"def": "寺人之伶。--《韩诗·车邻》", "example": null}, {"def": "令伶箫咏歌。--《国语·鲁语》", "example": null}, {"def": "仕于伶官。--《诗·简兮序》", "example": null}, {"def": "问之伶州鸠。--《国语·周语》", "example": null}, {"def": "又如伶官(古代的乐官);伶工(旧指乐师或演员);伶伦(传说中黄帝时的乐官);伶界(旧称戏曲界)", "example": null}, {"def": "引申为表演歌舞的艺人", "example": null}, {"def": "伶,乐人。--《广韵》", "example": null}, {"def": "帝制新曲,教女伶数十百人。--《新唐书·礼乐志》", "example": null}, {"def": "教坊优伶。--《北梦琐言》", "example": null}, {"def": "去年西京寺,众伶集讲筵。--孟郊《教", "example": null}, {"def": "伶líng", "example": null}, {"def": "⒈〈古〉乐官。〈引〉表演、唱戏、歌舞等的人～人。优～。坤（女的）～。", "example": null}, {"def": "⒉被役使的人府～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296335155211','灵','1','línɡ','火','7',NULL,'[{"def": "灵", "example": null}, {"def": "(形声。从巫,靈声。本义巫)", "example": null}, {"def": "古时楚人称跳舞降神的巫为灵", "example": null}, {"def": "灵,灵巫也。以玉事神。--《说文》", "example": null}, {"def": "命灵氛为余占之。--《离骚》", "example": null}, {"def": "灵连踡兮既留。--《楚辞·云中君》", "example": null}, {"def": "灵偃蹇兮姣胶。--屈原《东皇太一》", "example": null}, {"def": "又如灵子(指巫。以舞导引神的人)", "example": null}, {"def": "神灵", "example": null}, {"def": "天神曰灵。--《尸子》", "example": null}, {"def": "灵者,神也。--《风俗通》", "example": null}, {"def": "阳之精气曰神,阴之精气曰灵。--《大戴礼记·曾子问》", "example": null}, {"def": "合五岳与八灵兮。--《楚辞·怨思》。注八方之神也。”", "example": null}, {"def": "灵之来兮如云。--屈原《九歌·湘夫人》", "example": null}, {"def": "又如灵神(神灵);灵祗(神明;神灵)", "example": null}, {"def": "灵（靈）líng", "example": null}, {"def": "⒈有效验～验。～丹妙药。", "example": null}, {"def": "⒉聪明，机敏，敏捷～敏。～活。～机。心～手巧。", "example": null}, {"def": "⒊活动迅速，准确这部仪器很～。失～。", "example": null}, {"def": "⒋传说中或迷信者称\\"神\\"及\\"关于神仙\\"的神～。", "example": null}, {"def": "⒌属于死人的～柩。移～（移动装着死人的棺材）。", "example": null}]','chinese-xinhua','0'),
('2101143296335155212','囹','1','línɡ','囗','8',NULL,'[{"def": "囹〈名〉", "example": null}, {"def": "(形声。从囗,表示与被围有关。令声。本义囹圄(鎚??)监狱) 同本义", "example": null}, {"def": "囹,狱也。--《说文》", "example": null}, {"def": "囹圄,周之狱名也。--《华严音义》引《说文》", "example": null}, {"def": "省囹圄。--《礼记·月令》。注所以禁守系者,若今之别狱矣。”", "example": null}, {"def": "囹,领也,圄,御也,领录囚徒禁御之也。--《释名》", "example": null}, {"def": "囹,令也,圄,与也。言令人幽闭思愆,改恶为善因原之也。--《风俗通》", "example": null}, {"def": "下险疑坠井,守官类拘囹。--唐·韩愈《答张彻》", "example": null}, {"def": "屏医却药疾良已,破械空囹盗自消。--宋·陆游《晚凉述怀》", "example": null}, {"def": "又如囹圉(牢狱)", "example": null}, {"def": "囹圄", "example": null}, {"def": "至于守司囹圄,禁制刑罚,", "example": null}, {"def": "囹líng", "example": null}]','chinese-xinhua','0'),
