('2101143296335155223','柃','1','línɡ','木','9',NULL,'[{"def": "柃〈名〉", "example": null}, {"def": "木名。柃木", "example": null}, {"def": "染媒剂。果为染料。木料作细木工和炭薪用材", "example": null}, {"def": "柃,柃木也。从木,令声。--《说文》", "example": null}, {"def": "果之美名,沙棠之实,槠似柃。--《吕氏春秋》", "example": null}, {"def": "栏杆的横木", "example": null}, {"def": "柃líng 1.常绿灌木或小乔木。叶椭圆形至长椭圆状披针形，边缘有钝齿。枝梢叶腋开白色小花。浆果近球形，紫黑色。枝叶可入药，烧成灰后，灰汁可作染媒剂。果实可作染", "example": null}, {"def": "料。 2.栏干的横木。 3.见\\"柃?\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296335155224','玲','1','línɡ','王','9',NULL,'[{"def": "玲〈象，形〉", "example": null}, {"def": "(形声。从玉,令声。玲玎玉石等相击的清脆声)", "example": null}, {"def": "象声词。玉声", "example": null}, {"def": "玲,玉声。--《说文》", "example": null}, {"def": "玲珑,玉声也。--《埤苍》", "example": null}, {"def": "和氏珑玲。--扬雄《甘泉赋》", "example": null}, {"def": "又如玲玲;玲琅(玉声)", "example": null}, {"def": "明亮或美好的样子", "example": null}, {"def": "珊瑚幽茂而玲珑。--左思《吴都赋》。注明貌。”", "example": null}, {"def": "又如玲珑", "example": null}, {"def": "玲líng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "①清脆的金玉声。", "example": null}, {"def": "②细致精巧小巧～珑。", "example": null}, {"def": "③灵活敏捷～珑活泼。", "example": null}]','chinese-xinhua','0'),
('2101143296335155225','瓴','1','línɡ','瓦','9',NULL,'[{"def": "瓴〈名〉", "example": null}, {"def": "(形声。从瓦,令声。从瓦”,表示与陶器有关。本义一种盛水的瓶子)", "example": null}, {"def": "同本义", "example": null}, {"def": "今夫救火者,汲水而趋之,或以瓮瓴,或以盆盂。--《淮南子》", "example": null}, {"def": "砖瓦砌的通水沟", "example": null}, {"def": "瓴líng", "example": null}, {"def": "⒈瓦沟，房屋上仰盖的瓦。", "example": null}, {"def": "⒉一种盛水的瓶子高屋建～（从屋顶上翻瓶向下倒水。〈喻〉居高临下，势不可挡）。", "example": null}]','chinese-xinhua','0'),
('2101143296335155226','凌','1','línɡ','冫','10',NULL,'[{"def": "聆〈动〉", "example": null}, {"def": "(形声。从耳,令声。本义细听)", "example": null}, {"def": "同本义", "example": null}, {"def": "聆广乐之九奏兮。--张衡《思玄赋》", "example": null}, {"def": "宝玉接过来,一面目视其文,耳聆其歌。--《红楼梦》", "example": null}, {"def": "扣而聆之。--宋·苏轼《石钟山记》", "example": null}, {"def": "又如聆偈(听经);聆受(倾听并接受);聆训(听受训教);聆教(聆听教晦);聆音察理(听到声音就能明察事理)", "example": null}, {"def": "明了,清楚", "example": null}, {"def": "观读之者,晓然若盲之开目,聆然若聋之通耳。--汉·王充《论衡》", "example": null}, {"def": "又如聆聆(明了,清楚)", "example": null}, {"def": "凌líng", "example": null}, {"def": "①冰；积聚的冰。", "example": null}, {"def": "②侵犯；欺压。", "example": null}, {"def": "③暴虐；凶恶。", "example": null}, {"def": "④压倒；胜过。", "example": null}, {"def": "⑤渡过；逾越。", "example": null}, {"def": "⑥乘，驾驭。", "example": null}, {"def": "⑦迎；冒。", "example": null}, {"def": "⑧升，登上。", "example": null}, {"def": "⑨迫近。~晨﹑~曉。", "example": null}, {"def": "⑩姓。", "example": null}]','chinese-xinhua','0'),
