('2101143296335155243','翎','1','línɡ','羽','11',NULL,'[{"def": "翎〈名〉", "example": null}, {"def": "(形声。从羽,令声。本义翎毛,鸟翅和尾上的长羽毛)", "example": null}, {"def": "同本义", "example": null}, {"def": "何当有翅翎,飞去堕尔前!--杜甫《彭衙行》", "example": null}, {"def": "如翎篁(指羽毛。借指毛发);翎羽(指鸟羽);翎鬣(上冲的羽毛)", "example": null}, {"def": "翎子", "example": null}, {"def": "翎毛", "example": null}, {"def": "翎子", "example": null}, {"def": "翎líng鸟尾巴或鸟翅膀上的长毛雁～。孔雀～。", "example": null}]','chinese-xinhua','0'),
('2101143296335155244','聆','1','línɡ','耳','11',NULL,'[{"def": "聆〈动〉", "example": null}, {"def": "(形声。从耳,令声。本义细听)", "example": null}, {"def": "同本义", "example": null}, {"def": "聆广乐之九奏兮。--张衡《思玄赋》", "example": null}, {"def": "宝玉接过来,一面目视其文,耳聆其歌。--《红楼梦》", "example": null}, {"def": "扣而聆之。--宋·苏轼《石钟山记》", "example": null}, {"def": "又如聆偈(听经);聆受(倾听并接受);聆训(听受训教);聆教(聆听教晦);聆音察理(听到声音就能明察事理)", "example": null}, {"def": "明了,清楚", "example": null}, {"def": "观读之者,晓然若盲之开目,聆然若聋之通耳。--汉·王充《论衡》", "example": null}, {"def": "又如聆聆(明了,清楚)", "example": null}, {"def": "聆líng仔细听～教。", "example": null}]','chinese-xinhua','0'),
('2101143296335155245','零','1','línɡ','雨','13',NULL,'[{"def": "零〈动〉", "example": null}, {"def": "(形声。从雨,令声。本义下雨。指落细雨)", "example": null}, {"def": "同本义", "example": null}, {"def": "零,余雨也。--《说文》", "example": null}, {"def": "零雨其濛。--《诗·豳风·东山》", "example": null}, {"def": "又如零雨(徐徐飘落的雨)", "example": null}, {"def": "引申为如雨一般地落下;降落", "example": null}, {"def": "今当远离,临表涕零。--诸葛亮《出师表》", "example": null}, {"def": "灵雨既零,命彼倌人。--《诗·鄘风·定之方中》", "example": null}, {"def": "阿母得闻之,零泪应声落。--《孔雀东南飞》", "example": null}, {"def": "零露溥兮。--《诗·郑风·野有蔓草》", "example": null}, {"def": "柯叶汇而而零茂。--《文选·班固·幽通赋》", "example": null}, {"def": "涕零如雨。--《诗·小雅·小明》", "example": null}, {"def": "又如零泪(落泪);零露(自天空陨落露珠);感激涕零", "example": null}, {"def": "凋零,凋落", "example": null}, {"def": "悼芳", "example": null}, {"def": "零líng", "example": null}, {"def": "⒈落，衰落，雕落～涕。～落。雕～。", "example": null}, {"def": "⒉细碎的，部分的～碎。～用。～件。～活。", "example": null}, {"def": "⒊整数以外的少数～头。～数。年已七十有～。", "example": null}, {"def": "⒋数目字。通\\"㈡o\\"。", "example": null}, {"def": "⒌无，没有等于～。", "example": null}, {"def": "⒍指温度表上的\\"零度\\"～下十度。", "example": null}, {"def": "⒎", "example": null}, {"def": "零lián 1.见\\"先零\\"﹑\\"西零\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296335155246','龄','1','línɡ','齿','13',NULL,'[{"def": "龄", "example": null}, {"def": "(形声。从齿,令声。从牙齿来看年龄的长幼,所以从齿”。本义年龄)", "example": null}, {"def": "同本义", "example": null}, {"def": "通子垂九龄,但觅梨与栗。--陶渊明《责子》", "example": null}, {"def": "又如学龄儿童;高龄;龄齿(年龄)", "example": null}, {"def": "年限;年数", "example": null}, {"def": "暂游越万里,少别数千龄。--鲍照《代升天行》", "example": null}, {"def": "又如工龄;党龄;教龄", "example": null}, {"def": "生物学上指某些动植物生长期中划分的阶段", "example": null}, {"def": "龄líng", "example": null}, {"def": "⒈岁数年～。", "example": null}, {"def": "⒉年数工～。教～。", "example": null}]','chinese-xinhua','0'),
