('2101143296360321033','溜','1','liū','氵','13',NULL,'[{"def": "溜〈动〉", "example": null}, {"def": "滑动", "example": null}, {"def": "偷偷地走", "example": null}, {"def": "瞟,偷偷地看", "example": null}, {"def": "说着,却把眼溜着金桂一笑。--《红楼梦》", "example": null}, {"def": "偷偷地拿", "example": null}, {"def": "差人各溜过几件细软东西。--《醒世恒言》", "example": null}, {"def": "略略热一下", "example": null}, {"def": "略微煮一下,或加淀粉汁急火快炒", "example": null}, {"def": "逢迎,拍马;奉承", "example": null}, {"def": "溜liū", "example": null}, {"def": "⒈滑行～冰。～下去。", "example": null}, {"def": "⒉光滑的样子～光。～圆。滑～。", "example": null}, {"def": "⒊偷着走开～走。他～跑了。", "example": null}, {"def": "⒋顺着，沿着～着山边走。～河岸前进。", "example": null}, {"def": "⒌同\\"熘\\"。", "example": null}, {"def": "溜（", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉靋）liù", "example": null}, {"def": "⒈从屋檐滴流下来的水檐～。", "example": null}, {"def": "⒉屋檐上的承水槽水～。", "example": null}, {"def": "⒊急流洪～。水～很大很急。", "example": null}, {"def": "⒋排，行，条一～儿五间房。", "example": null}, {"def": "溜liú 1.见\\"溜火\\"。", "example": null}]','chinese-xinhua','0'),
