('2101143296360321041','栊','1','lónɡ','木','9',NULL,'[{"def": "栊", "example": null}, {"def": "(形声。从木,龙声,与下形上声的龒别。本义养禽兽的笼槛)", "example": null}, {"def": "同本义", "example": null}, {"def": "栊,槛也。--《说文》", "example": null}, {"def": "栊所以盛禽兽栏槛也。今囚栊字当作此。--《三苍》", "example": null}, {"def": "顺栊槛以俯抑。--祢衡《鹦鹉赋》", "example": null}, {"def": "窗框格;分隔并支撑窗玻璃的细木条", "example": null}, {"def": "无奈夜长人不寐,数声和月到帘栊。--李煜《捣练子》", "example": null}, {"def": "又如窗栊", "example": null}, {"def": "栊（櫳）lóng", "example": null}, {"def": "⒈窗户窗～。", "example": null}, {"def": "⒉养禽兽的栅栏～槛。", "example": null}]','chinese-xinhua','0'),
('2101143296360321042','珑','1','lónɡ','王','9',NULL,'[{"def": "珑", "example": null}, {"def": "(会意。从玉,龙声。本义古人祈雨用的玉器,上刻龙文) 同本义", "example": null}, {"def": "珑,祷旱玉,龙文。--《说文》", "example": null}, {"def": "珑", "example": null}, {"def": "振玉之声", "example": null}, {"def": "和氏珑玲。--《汉书·扬雄传》", "example": null}, {"def": "珊瑚幽茂而玲珑。--左思《吴都赋》", "example": null}, {"def": "又如珑璁;珑玲", "example": null}, {"def": "珑璁", "example": null}, {"def": "珑玲", "example": null}, {"def": "珑（瓏）lóng", "example": null}]','chinese-xinhua','0'),
('2101143296360321043','胧','1','lónɡ','月','9',NULL,'[{"def": "胧", "example": null}, {"def": "(形声。从月,龙声。朦胧月色不明的样子。引申为凝不清”) 同本义", "example": null}, {"def": "灯在月胧明,觉来闻晓莺。--温庭筠《菩萨蛮》", "example": null}, {"def": "又如胧月(微明的月亮);胧明(微明);胧胧(微明的样子)", "example": null}, {"def": "胧（杤）lóng朦胧]见朦。", "example": null}, {"def": "胧lǒng 1.见\\"胧肿\\"。", "example": null}]','chinese-xinhua','0'),
