('2101143296360321045','砻','1','lónɡ','石','10',NULL,'[{"def": "砻", "example": null}, {"def": "磨", "example": null}, {"def": "磨砻底厉。--《汉书·枚乘传》", "example": null}, {"def": "钝金必将待砻厉然后利。--《荀子·性恶》", "example": null}, {"def": "造兹宝刀,既砻既砺。--曹植《宝刀铭》", "example": null}, {"def": "又如砻刻(磨光雕琢);砻淬(磨炼刀刃,比喻刻苦锻炼);砻琢(磨炼);砻斫(磨和砍削);砻错(磨治;磨炼;切磋研讨)", "example": null}, {"def": "用砻脱出稻谷的壳", "example": null}, {"def": "凡既砻,则风扇以去糠秕。--《天工开物》", "example": null}, {"def": "如砻坊;砻糠", "example": null}, {"def": "砻", "example": null}, {"def": "磨石", "example": null}, {"def": "凡稻去壳用砻。--宋应星《天工开物》", "example": null}, {"def": "又如砻砺(磨石)", "example": null}, {"def": "脱出稻壳的农具", "example": null}, {"def": "通垄”。坟墓", "example": null}, {"def": "砻（礱）lóng", "example": null}, {"def": "⒈去掉谷物壳的器具。", "example": null}, {"def": "⒉用砻去掉谷物的壳，也泛指磨～谷。～砺。", "example": null}]','chinese-xinhua','0'),
('2101143296360321046','龙','1','lónɡ','龙','5',NULL,'[{"def": "龙", "example": null}, {"def": "(象形。甲骨文,象龙形。本义古代传说中一种有鳞有须能兴云作雨的神异动物)", "example": null}, {"def": "同本义", "example": null}, {"def": "龍,鳞虫之长。能幽能明,能细能巨,能短能长。春分而登天,秋分而潜渊。--《说文》。徐铉注象宛转飞动之貌。”饶炯注龙之为物,变化无端,说解因着其灵异如此,以", "example": null}, {"def": "能升天,神其物,而命之曰灵。”", "example": null}, {"def": "飞龙在天。--《易·乾》", "example": null}, {"def": "麟、凤、龟、龙,谓之四灵。--《礼记·礼运》", "example": null}, {"def": "甲虫三百有六十,而龙为之长。--《孔子家语·执辔》", "example": null}, {"def": "叶公子高好龙。--刘向《新序·叶公好龙》", "example": null}, {"def": "又如龙工(像龙一样熟悉水性之功。也作龙功”);龙公(指龙王,龙", "example": null}, {"def": "龙（龍）lóng", "example": null}, {"def": "⒈〈古〉传说中的一种神异动物，有鳞、有角、有脚，能走、能飞、能游泳，还能兴云降雨飞～乘云。叶公好～。", "example": null}, {"def": "⒉〈古〉生物学上指一些早已绝灭的巨大爬行动物恐～。翼手～。", "example": null}, {"def": "⒊封建时代象征帝王或指帝王使用的东西～颜。～袍。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "龙máng 1.通\\"尨\\"。杂色，色斑驳。 2.通\\"?\\"。参见\\"龙鵤\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296360321047','咙','1','lónɡ','口','8',NULL,'[{"def": "咙", "example": null}, {"def": "喉咙,咽部和喉部的统称", "example": null}, {"def": "咙,喉也。--《说文》", "example": null}, {"def": "又如咙胡(咽喉)", "example": null}, {"def": "咙（嚨）lóng", "example": null}]','chinese-xinhua','0'),
('2101143296360321048','泷','1','lónɡ','氵','8',NULL,'[{"def": "泷", "example": null}, {"def": "湍急的流水", "example": null}, {"def": "中夜前泷吼。--清·魏源《阳朔舟行》", "example": null}, {"def": "又如泷船(在急流中行驶的船)", "example": null}, {"def": "古水名", "example": null}, {"def": "泷（瀧）shuāng", "example": null}, {"def": "⒈泷水，在广东省。", "example": null}, {"def": "泷（瀧）lóng", "example": null}, {"def": "⒈急流的水。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296360321049','茏','1','lónɡ','艹','8',NULL,'[{"def": "茏", "example": null}, {"def": "(形声。从苃,龙声。本义草名。即荭花”。蓼类植物) 同本义", "example": null}, {"def": "其山之浅,有茏与斥。--《管子·地员》", "example": null}, {"def": "茏", "example": null}, {"def": "形容草木青翠茂盛。也作葱茏”", "example": null}, {"def": "譬若周云之茏苁。--《淮南子·俶真》", "example": null}, {"def": "又如茏茸(丛聚的样子);茏苁(丛聚的样子。同茏葱”);葱茏(草木茂盛的样子)", "example": null}, {"def": "茏葱", "example": null}, {"def": "茏（蘢）lóng", "example": null}, {"def": "茏lǒng 1.见\\"笼茸\\"﹑\\"笼苁\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296360321050','笼','1','lónɡ','竹','11',NULL,'[{"def": "笼", "example": null}, {"def": "(形声。从竹,龙声。本义竹笼)", "example": null}, {"def": "用竹片编成的盛物的器具", "example": null}, {"def": "笼,举土器也。--《说文》", "example": null}, {"def": "共丘笼。--《周礼·遂师》", "example": null}, {"def": "貂裘而负笼。--《淮南子·说山》", "example": null}, {"def": "荷笼负锸。--《汉书·王莽传》", "example": null}, {"def": "青丝为笼系。--《乐府诗集·陌上桑》", "example": null}, {"def": "又", "example": null}, {"def": "桂枝为笼钩。", "example": null}, {"def": "又如笼臿(盛土的笼和铲挖泥土的锹);笼篰(竹笼和小竹篓);笼屉(蒸笼)", "example": null}, {"def": "饲养鸟、虫、家禽等的笼子", "example": null}, {"def": "闭以雕笼。--祢衡《鹦鹉赋》", "example": null}, {"def": "以天下为之笼,则雀无所逃。--《庄子·庚桑楚》", "example": null}, {"def": "若脱笼之鹄。--明·袁宏道《满井游记》", "example": null}, {"def": "中儿正织鸡笼。--宋·辛弃疾《清平乐·", "example": null}, {"def": "笼（籠、", "example": null}, {"def": "⒋儱）lǒng", "example": null}, {"def": "⒈遮盖，罩住～罩。烟～寒水，月～沙（月月光）。", "example": null}, {"def": "⒉较大的箱子箱～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "笼（籠）lóng", "example": null}, {"def": "⒈用竹篾、木条或塑料等制做的盛物器或罩物器筷～。灯～。", "example": null}, {"def": "⒉养鸟、兽等的器具鸡～。鸟～子。蝈蝈～。", "example": null}, {"def": "⒊囚禁犯人的刑具囚～。", "example": null}, {"def": "⒋有盖用以蒸东西的器具蒸～。～屉。", "example": null}, {"def": "⒌将手放在袖筒里～着手。", "example": null}]','chinese-xinhua','0'),
('2101143296360321051','聋','1','lónɡ','耳','11',NULL,'[{"def": "聋", "example": null}, {"def": "(形声。从耳,龙声。本义丧失听觉能力)", "example": null}, {"def": "同本义", "example": null}, {"def": "聋,无闻也。--《说文》", "example": null}, {"def": "聋者无以与乎钟鼓之声。--《庄子·逍遥游》", "example": null}, {"def": "耳不听五声之和为聋,目不别五色之章为昧。--《左传·僖公二十四年》", "example": null}, {"def": "又如聋聩(耳聋或天生的聋子。比喻愚昧无知,不明事理);聋昧(耳聋目盲);聋瞢(聋盲)。又指聋子", "example": null}, {"def": "发瞽披聋。--枚乘《七发》", "example": null}, {"def": "愚昧;不明事理", "example": null}, {"def": "郑昭,宋聋。--《左传·宣公十四年》", "example": null}, {"def": "又如聋言(比喻遮蔽,欺骗);聋俗(比喻愚昧无知的流俗,就如有耳而无闻);聋昧(比喻迟钝、愚昧无知)。又指不明事理的人", "example": null}, {"def": "一", "example": null}, {"def": "聋（聾）lóng耳朵听不到或听不清声音耳～。他是～子。", "example": null}]','chinese-xinhua','0'),
('2101143296360321052','隆','1','lónɡ','阝','11',NULL,'[{"def": "隆〈形〉", "example": null}, {"def": "(形声。从生,降省声。本义高)", "example": null}, {"def": "丰大;高", "example": null}, {"def": "隆,丰大也。--《说文》", "example": null}, {"def": "宛中隆。--《尔雅·释山》。注山中央高。”", "example": null}, {"def": "虽隆薛之城。--《战国策·齐策一》", "example": null}, {"def": "隆准而龙颜。--《史记·高祖纪》", "example": null}, {"def": "段干木之隆。--《吕氏春秋·秋期贤》", "example": null}, {"def": "降冲以攻。--《淮南子·泛论》", "example": null}, {"def": "德隆望尊。--明·宋濂《送东阳马生序》", "example": null}, {"def": "又如隆穷(隆起的样子);隆颓(高低不平的样子);隆岳(高山);隆恩(皇帝给予的特大的恩典)", "example": null}, {"def": "国家逢勃发展;隆盛", "example": null}, {"def": "陛下都洛阳,岂欲与周室比隆哉?--《史记·刘敬叔孙通列传》", "example": null}, {"def": "汉室之隆。--诸葛亮", "example": null}, {"def": "隆lóng", "example": null}, {"def": "⒈高～起。～土。", "example": null}, {"def": "⒉厚，盛大，程度深～重。～盛。～冬。～情厚谊。", "example": null}, {"def": "⒊兴旺生意兴～。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
