('2101143296360321086','陋','1','lòu','阝','8',NULL,'[{"def": "陋〈形〉", "example": null}, {"def": "(形声。本义狭窄,狭小)", "example": null}, {"def": "同本义", "example": null}, {"def": "陋,阨陕也。--《说文》", "example": null}, {"def": "百盖无筑,千聚无社,谓之陋。--《管子·侈靡》", "example": null}, {"def": "生于辟陋之国。--《淮南子·修务》", "example": null}, {"def": "渞恒山其若陋兮。--《楚辞·自悲》", "example": null}, {"def": "莒恃其陋,而不修城郭。--《左传》", "example": null}, {"def": "在陋巷,人不堪其忧,回也不改其乐。--《论语》", "example": null}, {"def": "又如陋巷蓬门(穷苦人的住处。狭巷草编门)", "example": null}, {"def": "简陋", "example": null}, {"def": "何陋之有。--唐·刘禹锡《陋室铭》", "example": null}, {"def": "又如陋宇(简陋的房屋);陋室;朴陋(朴素简陋);粗陋(粗糙简陋);简陋(房屋、设备等简单粗陋;不完备)", "example": null}, {"def": "知识浅薄", "example": null}, {"def": "陋lòu", "example": null}, {"def": "⒈丑，坏，不合理的形～。～习。～规。", "example": null}, {"def": "⒉狭小～室。～巷。", "example": null}, {"def": "⒊少，浅薄简～。浅～。孤～寡闻。", "example": null}, {"def": "⒋边远地区。", "example": null}]','chinese-xinhua','0'),
('2101143296360321087','漏','1','lòu','氵','14',NULL,'[{"def": "漏〈名〉", "example": null}, {"def": "(形声。从水,屚声。本义漏壶的简称。古代滴水计时的仪器)", "example": null}, {"def": "同本义", "example": null}, {"def": "漏尽钟鸣,箭驰风追。--《马稚暨妻张氏墓志》", "example": null}, {"def": "漏,以铜受水,刻节。--《说文》。按这就是铜壶滴漏的漏”。", "example": null}, {"def": "晷漏肃唱。--《文选·左思·魏都赋》", "example": null}, {"def": "漏刻,谓以筒受水,刻节,昼夜百刻也。--《华严经音义下引文字集略》", "example": null}, {"def": "又如漏下(漏刻的水面已经下落);漏永更长(比喻深夜);漏尽钟鸣(黎明时分);漏夜(深夜);漏板(古代报更用的铜板);漏刻(古计时器)", "example": null}, {"def": "孔隙,孔穴;漏洞", "example": null}, {"def": "禹耳参漏。--《淮南子·修务》", "example": null}, {"def": "又如漏目(漏洞);漏眼(漏洞,毛病);漏窗", "example": null}, {"def": "漏lòu", "example": null}, {"def": "⒈物体从孔隙透过或滴下～水。～油。～气。", "example": null}, {"def": "⒉泄露泄～。走～风声。", "example": null}, {"def": "⒊遗落遗～。挂一～万。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "漏lóu 1.一种臭气。", "example": null}]','chinese-xinhua','0'),
('2101143296360321088','瘘','1','lòu','疒','14',NULL,'[{"def": "瘘", "example": null}, {"def": "颈肿大的病。即颈部淋巴结核", "example": null}, {"def": "合水多鰧鱼,状如鳜…食者不痈,可以瘘。--《山海经》。郭璞注瘘,痈属也。”", "example": null}, {"def": "瘘管", "example": null}, {"def": "瘘,即漏也。经年成漏者,在颈则曰瘰瘘,在痔则曰痔瘘。--明·楼英《医学纲目》", "example": null}, {"def": "瘘（瘻、瘺）lòu", "example": null}, {"def": "瘘lǘ 1.佝偻，驼背。", "example": null}]','chinese-xinhua','0'),
('2101143296360321089','镂','1','lòu','钅','14',NULL,'[{"def": "镂", "example": null}, {"def": "(形声。从金,娄声。本义可供雕刻的坚铁)", "example": null}, {"def": "金刚钻", "example": null}, {"def": "厥贡璯、铁、银、镂、砮磬。--《书·禹贡》。孔传镂,刚铁。”", "example": null}, {"def": "釜,烹饪用的锅", "example": null}, {"def": "镂,釜也。--《说文》", "example": null}, {"def": "通漏”。孔穴", "example": null}, {"def": "生禹于石纽,虎鼻大耳,两耳参镂。--《宋书》", "example": null}, {"def": "姓", "example": null}, {"def": "镂", "example": null}, {"def": "雕刻", "example": null}, {"def": "锲而不舍,金石可镂。--《荀子·劝学》", "example": null}, {"def": "器不彤镂。--《左传·哀公元年》", "example": null}, {"def": "流苏金镂鞍。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "又如镂冰(于冰上雕刻。比喻徒劳而无功);镂板(本指雕刻以印书的木板,引申为雕板印刷);镂花(雕刻花纹);镂金(雕", "example": null}, {"def": "镂（鐄）lòu雕刻～花。～字。～金刻玉。", "example": null}, {"def": "镂lǘ 1.属镂。剑名。", "example": null}]','chinese-xinhua','0'),
