('2101143296364515338','卢','1','lú','卜','5',NULL,'[{"def": "卢", "example": null}, {"def": "(形声。甲骨文字形,从皿,虎声。本义饭器)", "example": null}, {"def": "同本义", "example": null}, {"def": "卢,饭器也。--《说文》", "example": null}, {"def": "通庐”。房屋", "example": null}, {"def": "君卢屋妾。--《荀子·富国》", "example": null}, {"def": "瞳人", "example": null}, {"def": "玉女无所眺其清卢兮。--《汉书·扬雄传》", "example": null}, {"def": "通颅”。头盖骨", "example": null}, {"def": "蹶蹏足以破卢陷匈。--《淮南子·修务》", "example": null}, {"def": "黑色", "example": null}, {"def": "卢弓一。--《书·文侯之命》", "example": null}, {"def": "是犹绁韩卢而责之获也。--《汉书·王莽传下》。师古曰韩卢,古韩国之名犬也≮色曰卢。”", "example": null}, {"def": "卢奴城内西北隅有水,渊而不流,…水色正黑,俗", "example": null}, {"def": "卢（眗）lú", "example": null}, {"def": "⒈黑色～弓（黑色的弓）。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296364515339','庐','1','lú','广','7',NULL,'[{"def": "庐", "example": null}, {"def": "(形声。从广,廬声。从广”,表示与房屋有关。本义特指田中看守庄稼的小屋)", "example": null}, {"def": "同本义", "example": null}, {"def": "庐,寄也。秋冬去,春夏居。--《说文》", "example": null}, {"def": "庐,舍也。--《广雅》", "example": null}, {"def": "余二十亩,以为庐舍。--《汉书·食货志》。注田中屋也。”", "example": null}, {"def": "庐井有伍。--《左传·襄公三十年》", "example": null}, {"def": "中田有庐,疆场有瓜。--《诗·小雅·信南山》", "example": null}, {"def": "亦泛指简陋居室", "example": null}, {"def": "屋室庐庾。--《荀子·正名》。注草屋也。”", "example": null}, {"def": "众鸟欣有托,吾亦爱吾庐。--晋·陶潜《读山海经诗》之一", "example": null}, {"def": "结庐在人境,而无车马喧。--晋·陶潜《饮酒》", "example": null}, {"def": "南阳诸葛庐。--唐·刘禹锡《陋室铭》", "example": null}, {"def": "庐（廬）lú", "example": null}, {"def": "⒈简陋的房屋草～。", "example": null}, {"def": "⒉居住可～。", "example": null}, {"def": "⒊宾客住的宿舍十里有～，～有饮食。", "example": null}, {"def": "⒋庐山，在江西省。", "example": null}, {"def": "庐lǘ 1.古邑名。一作\\"卢\\"。在今湖北襄阳西南。本春秋庐戎国，被楚灭后为楚邑。", "example": null}]','chinese-xinhua','0'),
('2101143296364515340','芦','1','lú','艹','7',NULL,'[{"def": "芦", "example": null}, {"def": "(形声。从苃,眗声。本义草名。芦菔)", "example": null}, {"def": "芦菔,似芜菁。今作萝卜", "example": null}, {"def": "芦,芦菔也。--《说文》。段注今之萝卜也。”", "example": null}, {"def": "芜菁,共紫华者谓之芦菔。--《方言》三", "example": null}, {"def": "又如芦萹(莱菔的别名。又名萝卜)", "example": null}, {"def": "芦苇", "example": null}, {"def": "地);芦衣(用芦花为絮所缝制的衣服);芦灰(芦苇烧成的灰。相传女娲氏堆积芦灰以防止泛滥的洪水)", "example": null}, {"def": "芦（蘪）lú", "example": null}]','chinese-xinhua','0'),
('2101143296364515341','垆','1','lú','土','8',NULL,'[{"def": "垆", "example": null}, {"def": "黑色坚实的土壤", "example": null}, {"def": "垆,刚土也。从土,卢声。--《说文》", "example": null}, {"def": "埴垆用豕。--《周礼·草人》", "example": null}, {"def": "垆土人大。--《淮南子·地形》", "example": null}, {"def": "下土坟垆。--《书·禹贡》", "example": null}, {"def": "又如垆土(黑色坚硬而质粗不粘的土壤)", "example": null}, {"def": "通罏”。古时酒店里安放酒瓮的土台子", "example": null}, {"def": "诣道边酒垆。--《南史·谢几卿传》", "example": null}, {"def": "垆边人似月,皓腕凝霜雪。--唐·韦庄《菩萨蛮》", "example": null}, {"def": "借指酒店", "example": null}, {"def": "垆坶", "example": null}, {"def": "垆埴", "example": null}, {"def": "垆（壚、", "example": null}, {"def": "⒉罏）lú", "example": null}, {"def": "⒈黑色坚硬的土。", "example": null}, {"def": "⒉酒店里放置酒坛的土台子。也指酒店。", "example": null}]','chinese-xinhua','0'),
