('2101143296364515376','录','1','lù','王','8',NULL,'[{"def": "录", "example": null}, {"def": "(形声。从金,录声。本义绿色金属)", "example": null}, {"def": "同本义", "example": null}, {"def": "録,金色也。--《说文》", "example": null}, {"def": "记载言行事物的册籍", "example": null}, {"def": "录,记之具也。--《广雅·释诂三》", "example": null}, {"def": "皆辨其物而奠其录。--《周礼·职币》", "example": null}, {"def": "又如言行录;名人录", "example": null}, {"def": "次第,次序", "example": null}, {"def": "今大国越录。--《国语·吴语》", "example": null}, {"def": "录", "example": null}, {"def": "总领", "example": null}, {"def": "融为太尉,并录尚书事。--《后汉书·章帝纪》", "example": null}, {"def": "又如录公(对总领台阁尚书事者的敬称)", "example": null}, {"def": "抄写(含有有选择地照样誊写的意味)", "example": null}, {"def": "手自笔录。--明·宋濂《送东阳马生序》", "example": null}, {"def": "又", "example": null}, {"def": "余之手录。", "example": null}, {"def": "又如抄录(抄写);录黄(宋代中书省枢密院", "example": null}, {"def": "录（録）lù", "example": null}, {"def": "⒈记载，登记～音。～功。", "example": null}, {"def": "⒉抄写抄～。摘～。", "example": null}, {"def": "⒊记载言行或事物的书刊、文本语～。回忆～。备忘～。", "example": null}, {"def": "⒋任用，采取～用。～取。收～。", "example": null}, {"def": "⒌审查并记载犯人的罪状～供。", "example": null}]','chinese-xinhua','0'),
