('2101143296364515378','赂','1','lù','贝','10',NULL,'[{"def": "赂", "example": null}, {"def": "(形声。从贝,各声。从贝”,表示与钱财有关。本义赠送财物)", "example": null}, {"def": "同本义", "example": null}, {"def": "赂,遗也。--《说文》", "example": null}, {"def": "大赂南金。--《诗·鲁颂·泮水》", "example": null}, {"def": "骊姬赂二王。--《国语·晋语》", "example": null}, {"def": "因厚赂单于,答其善意。--《汉书·苏武传》", "example": null}, {"def": "割国之锱铢而赂之。--《荀子·富国》", "example": null}, {"def": "仅汉,汉之赂遗王财物,不可胜言。--《汉书·张骞传》", "example": null}, {"def": "于是从散约解,争割地而赂秦。--贾谊《过秦论》", "example": null}, {"def": "又如赂贿(用财物买通别人)", "example": null}, {"def": "行贿,用钱、物买通别人", "example": null}, {"def": "六国破灭,非兵不利、战不善,弊在赂秦。--宋·苏洵《六国论》", "example": null}, {"def": "赂lù", "example": null}, {"def": "⒈〈古〉指赠送财物。", "example": null}, {"def": "⒉财物。", "example": null}]','chinese-xinhua','0'),
('2101143296364515379','辂','1','lù','车','10',NULL,'[{"def": "辂", "example": null}, {"def": "(形声。从车,各声。本义绑在车辕上用来牵引车子的横木)", "example": null}, {"def": "同本义", "example": null}, {"def": "辂,车輈前横木也。--《说文》。按,人挽之车施辂,与驾牛马者不同。", "example": null}, {"def": "当前辂。--《仪礼·既夕礼》。注辕缚所以属引。”", "example": null}, {"def": "脱輓辂。--《史记·刘敬传》。索隐鹿车前横木。”", "example": null}, {"def": "引申为古代的大车,多指帝王用的", "example": null}, {"def": "大辂、次辂。--《书·顾命》", "example": null}, {"def": "辂车十五乘。--《国语·晋语》", "example": null}, {"def": "乘殷之辂。--《论语》", "example": null}, {"def": "又如辂车(天子的乘车);辂马(天子乘车之驾马);辂车衮冕(大车与礼服)", "example": null}, {"def": "辂", "example": null}, {"def": "拉车", "example": null}, {"def": "服牛辂马。--《管子·小", "example": null}, {"def": "辂lù", "example": null}, {"def": "⒈〈古〉车前用来牵引车子的横木。", "example": null}, {"def": "⒉〈古〉一种大车玉～。", "example": null}, {"def": "辂yà 1.迎上前去。", "example": null}, {"def": "辂hé 1.车辕上用来挽车的横木。 2.驾。", "example": null}]','chinese-xinhua','0'),
