('2101143296364515424','噜','1','lū','口','15',NULL,'[{"def": "噜", "example": null}, {"def": "语", "example": null}, {"def": "噜,语也。--《玉篇》", "example": null}, {"def": "噜苏", "example": null}, {"def": "噜lū", "example": null}, {"def": "①话多，絮絮叨叨。", "example": null}, {"def": "②办事琐碎麻烦手续 太～苏。", "example": null}, {"def": "噜lu 1.语气助词。", "example": null}]','chinese-xinhua','0'),
('2101143296364515425','撸','1','lū','扌','15',NULL,'[{"def": "撸", "example": null}, {"def": "磨练", "example": null}, {"def": "那人恼羞成怒的狠狠撸了他几嘴巴子。--刘白羽《政治委员》", "example": null}, {"def": "撸lū 1.捋。 2.降;撤。 3.用手掌击。 4.摸;抹。 5.拿。 6.批评;训斥。", "example": null}]','chinese-xinhua','0'),
('2101143296364515426','驴','1','lǘ','马','7',NULL,'[{"def": "驴", "example": null}, {"def": "(形声。从马,眗声。本义驴子。家畜名)", "example": null}, {"def": "同本义", "example": null}, {"def": "驴,似马,长耳。--《说文》。段注按,‘驴、骡、駃騠’太史公皆谓为匈奴奇畜,本中国所不用,故字皆不见经传,盖秦人造之耳。”", "example": null}, {"def": "腾驾罢牛,骖蹇驴兮。--贾谊《吊屈原文》", "example": null}, {"def": "骐骥不能与罢驴为驷。--《史记·日者列传》", "example": null}, {"def": "黔无驴。--唐·柳宗元《三戒》", "example": null}, {"def": "又", "example": null}, {"def": "主将适蝼而麓不闻。--《国语·晋语》", "example": null}, {"def": "驴不胜怒。", "example": null}, {"def": "又如驴头(驴马头。骂人的话);驴王(指凶残恶狠的人);驴年(古代以生肖纪年,十二肖中没有驴。比喻没有期限);驴券(比喻为文或说话不得要领);驴颓(骂男子", "example": null}, {"def": "驴（骽）lǘ家畜。像马但比马小，耳和脸都较长。供乘骑、拉车、驮物等用。皮可熬制驴皮胶，供药用。", "example": null}]','chinese-xinhua','0'),
('2101143296364515427','闾','1','lǘ','门','9',NULL,'[{"def": "闾", "example": null}, {"def": "(形声。从门,吕声。本义里巷的大门)", "example": null}, {"def": "同本义", "example": null}, {"def": "闾,里门也。--《说文》", "example": null}, {"def": "二大夫出,相与踦闾而语。--《公羊传》", "example": null}, {"def": "便旋闾阎。--张衡《西京赋》", "example": null}, {"def": "门闾无关。--《吕氏春秋·仲夏》", "example": null}, {"def": "发闾左戍渔阳九百人。--《汉书·陈胜传》", "example": null}, {"def": "又如倚闾而望;闾阋(指内部斗争);闾墓(里巷和墓道的大门);闾闬(里巷的门)", "example": null}, {"def": "里巷", "example": null}, {"def": "闾,里也。--《广雅·释宫》", "example": null}, {"def": "魏文侯过段干木之闾而轼之。--《吕氏春秋·期贤》", "example": null}, {"def": "违郢都之旧闾兮。--《楚辞·刘向·九叹·思古》", "example": null}, {"def": "又如闾吏(里巷小吏);闾陌(里巷);闾社(闾里乡社);闾肆(街", "example": null}, {"def": "闾lǘ", "example": null}, {"def": "⒈〈古〉一种居民组织，五家为比，五比为～。", "example": null}, {"def": "⒉里巷的门倚～而望。", "example": null}, {"def": "⒊里巷穷～漏屋。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
