('2101143296372903936','捋','1','lǚ','扌','10',NULL,'[{"def": "捋〈动〉luo", "example": null}, {"def": "(形声。从手,寽声。寽”,以五指持物,在字中表意。本义手握着东西向一端抹取)", "example": null}, {"def": "同本义", "example": null}, {"def": "武松捋起双袖,握起尖刀。--《水浒传》", "example": null}, {"def": "堆,垒", "example": null}, {"def": "这边堆着木料--檩子、柱子和椽子。那边捋着从各社员家收集的干土坯。--柳青《创业史》", "example": null}, {"def": "捋臂揎拳", "example": null}, {"def": "为人性刚,喜则眉花眼笑,怒则捋臂揎拳,胆大心雄,头高气硬。--《野叟曝言》", "example": null}, {"def": "又叫捋袖揎拳”", "example": null}, {"def": "捋虎须", "example": null}, {"def": "捋luō", "example": null}, {"def": "⒈用手握东西，顺着向一端滑动～树枝儿。", "example": null}, {"def": "捋lǚ", "example": null}, {"def": "⒈用手指顺着抹过去，顺着整理～胡须。抚摸～发。", "example": null}]','chinese-xinhua','0'),
('2101143296372903937','吕','1','lǚ','口','6',NULL,'[{"def": "吕〈名〉", "example": null}, {"def": "(象形。甲骨文字形,象脊骨形,是膂”的本字。本义脊梁骨)", "example": null}, {"def": "同本义。膂”的古字", "example": null}, {"def": "吕,脊骨也。象形。--《说文》", "example": null}, {"def": "氏曰有吕。--《国语·周语下》。注吕之为言膂也。”", "example": null}, {"def": "尻髋脊膂腰背吕。--《急就篇》。颜师古注吕,脊骨也。”", "example": null}, {"def": "我国古代音乐,十二律中的阴律,有六种,总称六吕", "example": null}, {"def": "数的六个管称律”,成偶数的六个管称吕”,总称六吕”、六律”,简称律吕”)", "example": null}, {"def": "通旅”。客舍", "example": null}, {"def": "自今以来,", "example": null}, {"def": "吕lǚ〈古〉我国音乐用语。指乐器声音的清浊高低，分阴阳各六，共十二音，阴的称\\"吕\\"，阳的称\\"律\\"，合称\\"律吕\\"", "example": null}]','chinese-xinhua','0'),
('2101143296372903938','侣','1','lǚ','亻','8',NULL,'[{"def": "侣〈名〉", "example": null}, {"def": "(形声。从人,吕声。本义伴侣,同伴) 同本义", "example": null}, {"def": "命俦啸侣,或戏清流,或翔神渚。--曹植《洛神赋》", "example": null}, {"def": "我来无伴侣,把酒对南山。--唐·韩愈《把酒》", "example": null}, {"def": "故人念我寡徒侣,持用赠我比知音。--唐·韩愈《利剑》", "example": null}, {"def": "以元侣悲。--清·林觉民《与妻书》", "example": null}, {"def": "告其故侣。--清·侯方域《壮悔堂文集》", "example": null}, {"def": "携来百侣曾游。--毛泽东《游泳》", "example": null}, {"def": "又如仙侣;僧侣(出家修行的佛教徒);侣俦(朋友)", "example": null}, {"def": "侣 〈动〉", "example": null}, {"def": "结为伴侣;陪伴", "example": null}, {"def": "侣鱼虾而友麋鹿。--苏轼《赤壁赋》", "example": null}, {"def": "又如侣行(结伴而行)", "example": null}, {"def": "侣lǚ同伴伴～。", "example": null}]','chinese-xinhua','0'),
('2101143296372903939','旅','1','lǚ','方','10',NULL,'[{"def": "旅〈名〉", "example": null}, {"def": "(会意。甲骨文字形,象众人站在旗下。旗,指军旗;人,指士兵。小篆字形,表示旌旗;从从”,表示众人,即士兵。本义古代军队五百人为一旅)", "example": null}, {"def": "军队编制单位。上古一般以五百人为旅,齐制二千人为旅。现代指师以下的单位,基本上由司令部和两个或者两个以上的团或大队组成的战术和行政单位", "example": null}, {"def": "旅,军之五百人为旅。--《说文》", "example": null}, {"def": "孙策以天下为三分,众才一旅。--庾信《哀江南赋序》", "example": null}, {"def": "全旅为上。--《孙子·谋攻》", "example": null}, {"def": "又", "example": null}, {"def": "破旅次之。", "example": null}, {"def": "又如旅长;两旅兵", "example": null}, {"def": "军队", "example": null}, {"def": "加之以师旅。--《论语·先进》", "example": null}, {"def": "所以佐百姓之急,足军旅之费。--", "example": null}, {"def": "旅、稆（穭）lǚ", "example": null}, {"def": "⒈出行，在外作客～行。～途。～客。～居。～馆。", "example": null}, {"def": "⒉军队的编制单位，它是师的下一级，团的上一级。", "example": null}, {"def": "⒊军队劲～。军～之费。", "example": null}, {"def": "⒋共，同～进～退。", "example": null}, {"def": "⒌谷物等不种自生的～生。～黍。", "example": null}]','chinese-xinhua','0'),
