('2101143296377098288','萝','1','luó','艹','11',NULL,'[{"def": "萝", "example": null}, {"def": "(形声。从苃,罗声。本义植物名。指某些蔓生植物,即莪”) 同本义", "example": null}, {"def": "萝,莪也。蒿属。--《说文》", "example": null}, {"def": "又如女萝;藤萝;茑萝;萝蓏(女萝和瓜类)", "example": null}, {"def": "萝（蘿）luó", "example": null}, {"def": "⒈通常指某些能爬蔓的植物茑～。藤～。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296377098289','逻','1','luó','辶','11',NULL,'[{"def": "逻", "example": null}, {"def": "(形声。从辵,表示与行走有关,罗声。本义巡察,巡逻)", "example": null}, {"def": "同本义", "example": null}, {"def": "逻者数十骑。--宋·文天祥《指南录后序》", "example": null}, {"def": "又如逻伺(巡罗侦察);逻弋(巡逻);逻守(巡逻守卫);逻役(巡逻的差役);逻捕(巡察搜捕)", "example": null}, {"def": "遮拦", "example": null}, {"def": "蛛蝥结网工遮逻。--黄庭坚《演雅》", "example": null}, {"def": "又如逻打(拦截殴打);逻送(捕捉解送);逻惹(招惹);逻楂儿(找岔子)", "example": null}, {"def": "用同捋”", "example": null}, {"def": "又只见那洞外跳出几个小妖,在外边吆吆喝喝,伸拳逻袖,弄棒拈枪,依旧喜喜欢欢耍了。--《西游记》", "example": null}, {"def": "又如逻袖(捋起袖子)", "example": null}, {"def": "逻", "example": null}, {"def": "逻卒;巡行兵", "example": null}, {"def": "逻（邏）luó", "example": null}, {"def": "⒈巡察巡～。", "example": null}, {"def": "⒉", "example": null}, {"def": "①思维的规律讲得有理，符合～辑。", "example": null}, {"def": "②研究思维的形式和规律的科学，叫逻辑学，也叫\\"伦理学\\"。", "example": null}, {"def": "③有时义同\\"规律\\"这是什么～辑？", "example": null}]','chinese-xinhua','0'),
('2101143296377098290','椤','1','luó','木','12',NULL,'[{"def": "见桫椤”", "example": null}, {"def": "椤（欏）luó", "example": null}]','chinese-xinhua','0'),
('2101143296377098291','锣','1','luó','钅','13',NULL,'[{"def": "锣", "example": null}, {"def": "带卷边的青铜圆盘", "example": null}, {"def": "鸣锣聚众。--《广东军务记》", "example": null}, {"def": "又", "example": null}, {"def": "鸣锣会集。", "example": null}, {"def": "鸣锣传递。", "example": null}, {"def": "锣（鑼）luó打击乐器。铜制，圆形，像盘，用槌敲打发声敲～打鼓。", "example": null}]','chinese-xinhua','0'),
('2101143296377098292','箩','1','luó','竹','14',NULL,'[{"def": "箩", "example": null}, {"def": "(形声。从竹,罗声。本义竹制的盛器,多方底圆口)", "example": null}, {"def": "同本义", "example": null}, {"def": "箩,箕也。--《广雅·释器》", "example": null}, {"def": "所以注斛,陈魏宋楚之间谓之箩。--《方言》五", "example": null}, {"def": "又如箩斗(即箩兜。箩筐);箩兜(箩筐);箩头(即箩筐);箩担(挑有箩筐的担子);箩筛(竹编的筛子)", "example": null}, {"def": "箩筛", "example": null}, {"def": "量词", "example": null}, {"def": "桐膏千箩,蜡千斤,茧丝千两。--清·唐甄《潜书》", "example": null}, {"def": "箩", "example": null}, {"def": "用箩筛或滤", "example": null}, {"def": "箩（籮）luó竹篾编制的盛物器，多为底方口圆～筐。", "example": null}]','chinese-xinhua','0'),
('2101143296377098293','骡','1','luó','马','14',NULL,'[{"def": "骡", "example": null}, {"def": "动物名。骡子", "example": null}, {"def": "驘,驴父马母。--《说文》", "example": null}, {"def": "同驽驘与乘驵兮。--《楚辞·九叹·忧苦》。注马母騼父生子曰驘。”", "example": null}, {"def": "又如骡纲(驮载商旅货物结队而行的骡群);骡驴(骡和驴,比喻平庸的人;兽名,俗称四不像”)", "example": null}, {"def": "骡（驘）luó家畜。驴和马交配所生。鬃短，尾巴略扁，体力大，适应力强，可以拉车或驮物品。一般不能生殖。", "example": null}]','chinese-xinhua','0'),
