('2101143296377098303','落','1','luò','艹','12',NULL,'[{"def": "落〈动〉luo", "example": null}, {"def": "(形声。从苃,洛声。本义叶落,花落)", "example": null}, {"def": "同本义", "example": null}, {"def": "落,凡草曰零,木曰落。--《说文》", "example": null}, {"def": "草木黄落。--《礼记·月令》", "example": null}, {"def": "及荣华之未落兮。--《楚辞·离骚》", "example": null}, {"def": "唯草木之零落兮。", "example": null}, {"def": "桑之未落,其叶沃若。--《诗·卫风·氓》", "example": null}, {"def": "人闲桂花落。--唐·王维《鸟鸣涧》", "example": null}, {"def": "落英缤纷。--晋·陶渊明《桃花源记》", "example": null}, {"def": "叶落树下。--三国魏·邯郸淳《笑林》", "example": null}, {"def": "纷堕如落叶。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如落红(落花);落花媒人(不正当男女关系的撮合人);落英缤纷(落地零乱的样子);落木(落叶);落花时节(指暮春季节)", "example": null}, {"def": "脱离;脱身", "example": null}, {"def": "落lào", "example": null}, {"def": "⒈某些口头用语，如～枕、～坑等。", "example": null}, {"def": "落là", "example": null}, {"def": "⒈丢下，遗漏丢三～四。这里～了两个字。", "example": null}, {"def": "落luò", "example": null}, {"def": "⒈掉下，下降～下。～雨。花～。降～。也指掉下的～叶。～花。", "example": null}, {"def": "⒉衰败，飘零没～。沦～。", "example": null}, {"def": "⒊遗留在后面～后。～队。", "example": null}, {"def": "⒋归属把任务～在他身上。", "example": null}, {"def": "⒌得到～得。～个好名声。", "example": null}, {"def": "⒍停留，留下～脚。～户。不～痕迹。", "example": null}, {"def": "⒎聚居或停留的地方村～。下～。", "example": null}, {"def": "⒏写下～款。～账。", "example": null}, {"def": "⒐建筑物完工～成。", "example": null}, {"def": "⒑", "example": null}, {"def": "①若干血缘相近的氏族所结合成的集体。", "example": null}, {"def": "②我国史书上多指少数民族。", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "⒔", "example": null}, {"def": "⒕", "example": null}, {"def": "⒖", "example": null}, {"def": "⒗", "example": null}, {"def": "落luō 1.见\\"大大落落\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296377098304','摞','1','luò','扌','14',NULL,'[{"def": "摞〈动〉", "example": null}, {"def": "通常指整齐地堆积或堆起", "example": null}, {"def": "摆或放置成堆或好像成堆", "example": null}, {"def": "摞 〈量〉", "example": null}, {"def": "常为排列得整齐有序的叠堆", "example": null}, {"def": "堆在一起的或逐个叠放的大量东西", "example": null}, {"def": "摞luò", "example": null}, {"def": "⒈将东西重叠的放把书～起放。", "example": null}, {"def": "⒉重叠放着的东西瓦～。", "example": null}, {"def": "摞lèi 1.见\\"摞台\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296377098305','漯','1','luò','氵','14',NULL,'[{"def": "漯  lei", "example": null}, {"def": "古水名。又名治水", "example": null}, {"def": "漯河 luo", "example": null}, {"def": "漯tà", "example": null}, {"def": "⒈漯河，也作\\"漯川\\"，在山东省。", "example": null}, {"def": "漯luò", "example": null}, {"def": "⒈漯河市，在河南省。", "example": null}]','chinese-xinhua','0'),
('2101143296377098306','雒','1','luò','隹','14',NULL,'[{"def": "雒〈名〉", "example": null}, {"def": "鸟名", "example": null}, {"def": "雒,鵫鶀也。怪鸱。--《说文》。今称鸺鷙,也叫横纹小鴞", "example": null}, {"def": "又如雒诵(反复诵读)", "example": null}, {"def": "通骆”。白鬃的黑马", "example": null}, {"def": "净古都邑名", "example": null}, {"def": "古地名。西汉时置为雒县。自古为争蜀的战略要地。三国时刘备即因破雒城而得成都", "example": null}, {"def": "印烙◇作烙”", "example": null}, {"def": "烧之,剔之,刻之,雒之。--《庄子》", "example": null}, {"def": "通络”。用网状物兜住头", "example": null}, {"def": "烧之、剔之、刻之、雒之。--《庄子·马蹄》", "example": null}, {"def": "雒luò", "example": null}, {"def": "⒈水名。即洛水。", "example": null}, {"def": "⒉雒南县，在陕西省，1964年改为洛南县。", "example": null}]','chinese-xinhua','0'),
('2101143296377098307','纙','1','luò','','12',NULL,'[{"def": "纙luò 1.钱缗，用以穿铜钱的丝绳。", "example": null}]','chinese-xinhua','0'),
('2101143296377098308','泺','1','luò','氵','8',NULL,'[{"def": "泺", "example": null}, {"def": "古水名", "example": null}, {"def": "泺,泺水,齐鲁间水也。从水,乐声。--《说文》", "example": null}, {"def": "公会齐侯于泺。--《左传·桓公十八年》", "example": null}, {"def": "源出今山东济南市西南,北流至泺口入古济水(此段古济水即今黄河)", "example": null}, {"def": "泺（瀟）luò", "example": null}, {"def": "⒈泺水，在山东省。", "example": null}, {"def": "泺（瀟）pō", "example": null}, {"def": "⒈湖，地名湖～。血～（大滩血）。罗布～，在青海省。〈古〉梁山～，在今山东省。", "example": null}, {"def": "泺lì 1.中药贯众的别名。贯众，蕨科。以根状茎及叶柄残基入药，性寒，味苦，有小毒。功能清热﹑解毒﹑止血﹑杀虫。主治虫积腹痛﹑温热斑疹﹑疮痈肿毒﹑崩漏下血等症", "example": null}, {"def": "。 2.颗，块。", "example": null}]','chinese-xinhua','0'),
('2101143296377098309','洛','1','luò','氵','9',NULL,'[{"def": "洛〈名〉", "example": null}, {"def": "(形声。从水,各声。本义水名。指洛水)", "example": null}, {"def": "同本义", "example": null}, {"def": "洛,洛水,出左冯翊归德北夷界中,东南入渭。--《说文》", "example": null}, {"def": "北洛河。发源于陕西省定边县,东南流经志丹、洛川、蒲城等县", "example": null}, {"def": "洛河发源于陕西省雒南县华山东麓。本作雒”。如洛神(洛水女神洛嫔);洛浦(洛水之滨。传说这里是洛神出没处)", "example": null}, {"def": "洛阳的简称", "example": null}, {"def": "洛luò", "example": null}, {"def": "⒈洛河，在陕西省。", "example": null}, {"def": "⒉洛水〈古〉作\\"雒\\"。源出陕西省洛南，向东流经河南省入黄河。", "example": null}, {"def": "⒊洛阳市，在河南省。", "example": null}]','chinese-xinhua','0'),
('2101143296377098310','络','1','luò','纟','9',NULL,'[{"def": "络子 lao", "example": null}, {"def": "倒不如打个络子,把玉络上呢。--《红楼梦》", "example": null}, {"def": "络", "example": null}, {"def": "(形声。从糸,表示与丝线有关。各声。本义缠绕,捆缚)", "example": null}, {"def": "同本义", "example": null}, {"def": "络,缠也。--《广雅》", "example": null}, {"def": "有九丘,以水络之。--《海内经》", "example": null}, {"def": "郑绵络些。--《楚辞·招魂》", "example": null}, {"def": "绵络天地。--《汉书·扬雄传》", "example": null}, {"def": "蒙绵摇缀,参差披拂。--柳宗元《至小丘西小石潭记》", "example": null}, {"def": "罗绵其上。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "又如络着手(缠", "example": null}, {"def": "络lào", "example": null}, {"def": "⒈网状的东西。用于一些口语丝瓜～。", "example": null}, {"def": "①线绳结成的网状袋子用塑料～子装洗脸盆。", "example": null}, {"def": "②绕线、绕纱等的器具。", "example": null}, {"def": "络luò", "example": null}, {"def": "⒈网状的东西脉～。经～。丝瓜～。", "example": null}, {"def": "⒉罩住头上～着发网。", "example": null}, {"def": "⒊缠绕，缠裹，环绕～线。笼山～野。", "example": null}, {"def": "⒋拉拢笼～。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296377098311','荦','1','luò','艹','9',NULL,'[{"def": "荦", "example": null}, {"def": "(形声。从牛,劳省声。本义杂色的牛)", "example": null}, {"def": "同本义", "example": null}, {"def": "荦,驳牛也。--《说文》", "example": null}, {"def": "黄白杂谓之驳荦。--《通俗文》", "example": null}, {"def": "斯为朽关键,怒荦抉以入。--陆龟蒙《杂讽》", "example": null}, {"def": "古地名", "example": null}, {"def": "荦", "example": null}, {"def": "明显,分明", "example": null}, {"def": "此其荦荦大者。--《史记·天官书》。索隐事之分明也。”", "example": null}, {"def": "又如荦然(明显的样子)", "example": null}, {"def": "荦荦", "example": null}, {"def": "荦荦大端", "example": null}, {"def": "荦（犖）luò", "example": null}, {"def": "⒈杂色的牛。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
