('2101143296381292566','瞒','1','mán','目','15',NULL,'[{"def": "瞒", "example": null}, {"def": "(形声。本义眼睑低。闭目貌)", "example": null}, {"def": "同本义", "example": null}, {"def": "瞒,平目也。--《说文》", "example": null}, {"def": "酒食声色之中,则瞒瞒然。--《荀子》", "example": null}, {"def": "又如瞒瞒(闭目貌)", "example": null}, {"def": "通满”", "example": null}, {"def": "通颟”", "example": null}, {"def": "瞒", "example": null}, {"def": "隐藏实情", "example": null}, {"def": "什么事瞒的过我?--《红楼梦》", "example": null}, {"def": "又如瞒产(隐瞒产量);瞒落(隐瞒留下);瞒藏(隐匿);瞒天瞒地(犹言瞒上欺下);瞒昧(隐瞒欺骗);瞒瞒昧昧(隐瞒欺骗)", "example": null}, {"def": "欺骗(瞒当谩讲,是晚起字)", "example": null}, {"def": "我把你个泼猴!你瞒谁哩?--《西", "example": null}, {"def": "瞒（瞞）mán隐瞒实情隐～。欺～。", "example": null}, {"def": "瞒mén 1.惭愧。参见\\"瞒然\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296381292567','鞔','1','mán','革','16',NULL,'[{"def": "鞔", "example": null}, {"def": "鞋子", "example": null}, {"def": "南家工人也,为鞔者也。--《吕氏春秋》。高诱注鞔履也,作履之工也。”", "example": null}, {"def": "又如鞔韑(皮鞋)", "example": null}, {"def": "鞔", "example": null}, {"def": "蒙鼓,把皮革固定在鼓框上,做成鼓面", "example": null}, {"def": "把布蒙在鞋帮上", "example": null}, {"def": "通懑”。闷胀", "example": null}, {"def": "胃充则中大鞔。--《吕氏春秋·重己》", "example": null}, {"def": "鞔mán 1.鞋子。 2.蒙上;连缀。 3.以革补(履)。", "example": null}, {"def": "鞔mèn 1.闷胀。", "example": null}]','chinese-xinhua','0'),
('2101143296381292568','鳗','1','mán','鱼','19',NULL,'[{"def": "鳗", "example": null}, {"def": "鳗鱼,今俗曰鳗鲡", "example": null}, {"def": "鳗;海鳗", "example": null}, {"def": "许多种多少类似真正鳗的细长型鱼类(如合鳃目的鱼)的泛称", "example": null}, {"def": "鳗mán", "example": null}, {"def": "海洋中，也供食用。", "example": null}]','chinese-xinhua','0'),
