('2101143296414846988','们','1','mén','亻','5',NULL,'[{"def": "们", "example": null}, {"def": "用在代词或指人的名词后面,表示复数。如孩子们", "example": null}, {"def": "么”的变音字", "example": null}, {"def": "李逵道这们睡,闷死我也。”--《水浒传》", "example": null}, {"def": "注意名词前有数量词时，后面不加们”，例如不说三个孩子们”", "example": null}, {"def": "们men词尾，〈表〉人的复数我～。你～的。老师～。", "example": null}, {"def": "们mén 1.词的后缀。用在人称﹑物称代词或指人﹑指物的名词后面，表示复数。 2.词的后缀。用于具体的人名后，表示\\"等人\\"﹑\\"之辈\\"。 3.词的后缀。用在指示代词后面", "example": null}, {"def": "，相当于\\"这么\\"﹑\\"那么\\"的\\"么\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296414846989','闷','1','mèn','门','7',NULL,'[{"def": "闷", "example": null}, {"def": "气闷,因气不通畅而引起的不快之感", "example": null}, {"def": "闭则热而闷。--《素问·风论》", "example": null}, {"def": "又如闷吐(心闷想吐);闷绝(晕倒。一说窒息而死);闷痒(因身体不舒爽而发痒);闷窒(窒息);闷躁(气闷烦躁)", "example": null}, {"def": "沉默不出声或声音不响的样子", "example": null}, {"def": "闷然而后应。--《庄子·德充符》", "example": null}, {"def": "又如闷默(静默不出声);闷闷(闷声不响)", "example": null}, {"def": "闷", "example": null}, {"def": "密闭,使不透气", "example": null}, {"def": "呆在家里不出门", "example": null}, {"def": "过饱", "example": null}, {"def": "昏闷;失去知", "example": null}, {"def": "闷mēn", "example": null}, {"def": "⒈气压低或空气不流通等引起的不舒服～气。～热。", "example": null}, {"def": "⒉不出门～在家里。", "example": null}, {"def": "⒊紧闭，不让出气刚泡的茶～一～再喝。", "example": null}, {"def": "⒋不出声或声音不响亮～声不响。～声～气。", "example": null}, {"def": "闷mèn", "example": null}, {"def": "⒈心烦，不畅快烦～。～ ～不乐。", "example": null}, {"def": "⒉密封的～罐。～葫芦。", "example": null}]','chinese-xinhua','0'),
('2101143296414846990','焖','1','mèn','火','11',NULL,'[{"def": "焖", "example": null}, {"def": "紧盖锅盖,用微火把饭菜煮熟", "example": null}, {"def": "焖mèn盖紧锅盖，不使漏气，用微火将饭菜煮熟～饭。～鸡。肉～青豆。", "example": null}]','chinese-xinhua','0'),
