('2101143296414847038','弥','1','mí','弓','8',NULL,'[{"def": "弥", "example": null}, {"def": "(形声。从弓,尔声。本义放松弓弦)", "example": null}, {"def": "同本义", "example": null}, {"def": "彌,驰弓也。--《说文》", "example": null}, {"def": "弥,《说文》弛弓也。--《集韵》", "example": null}, {"def": "充满;填满", "example": null}, {"def": "弥缝其阙,而匡救其灾。--《左传》", "example": null}, {"def": "又如弥封;弥补;弥缝", "example": null}, {"def": "通弭”。停止", "example": null}, {"def": "不弥人争。--《管子·四称》", "example": null}, {"def": "以弥乱发姦,登大司马,职在内辅。--《汉书·王莽传》", "example": null}, {"def": "弥", "example": null}, {"def": "遍;满", "example": null}, {"def": "弥山跨谷。--《汉书·司马相如传》。注满也。”", "example": null}, {"def": "弥祀社稷祷祠。--《周礼·大祝》。注犹徧也。”", "example": null}, {"def": "马畜弥山。--《汉书·李广苏建传》", "example": null}, {"def": "又如弥天亘地(满天", "example": null}, {"def": "弥（彌）mí", "example": null}, {"def": "⒈满，遍～月（婴儿满月）。～天大谎。", "example": null}, {"def": "⒉补，合～补。～合。", "example": null}, {"def": "⒊更加～坚。欲盖～彰。", "example": null}, {"def": "⒋长，久旷日～久。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "弥mǐ 1.通\\"弭\\"。止息。 2.通\\"弭\\"。末端。参见\\"弥龙\\"。 3.通\\"靡\\"。奢侈。参见\\"弥侈\\"。", "example": null}, {"def": "弥nǐ 1.水深满貌。 2.深水。 3.充满，遍布。 4.见\\"弥迤\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296414847039','祢','1','mí','礻','9',NULL,'[{"def": "祢", "example": null}, {"def": "奉祀死父的宗庙", "example": null}, {"def": "古代军旅之事,常载神主而行,随行神主称弥", "example": null}, {"def": "侯氏裨冕,释历于祢。--《仪礼》", "example": null}, {"def": "姓", "example": null}, {"def": "祢（?", "example": null}, {"def": "祢nǐ 1.亲庙;父庙。 2.父死，神主入庙后称祢。 3.随军的神主。 4.继承;崇奉。 5.古地名。", "example": null}]','chinese-xinhua','0'),
('2101143296414847040','迷','1','mí','辶','9',NULL,'[{"def": "迷", "example": null}, {"def": "(形声。从辵,米声。本义迷路;分辨不清)", "example": null}, {"def": "同本义", "example": null}, {"def": "迷,惑也。--《说文》", "example": null}, {"def": "烈风雷雨弗迷。--《书·舜典》", "example": null}, {"def": "凡夫失其所欲之路,而妄行之,则为迷。--《韩非子·解老》", "example": null}, {"def": "及行迷之未远。--《离骚》", "example": null}, {"def": "迷不知宠之门。--《楚辞·惜诵》", "example": null}, {"def": "迷其所在。--《聊斋志异·促织》", "example": null}, {"def": "入溆浦余儃佪兮,迷不知吾所如。--《楚辞·九章·涉江》", "example": null}, {"def": "高低冥迷,不知西东。--杜牧《阿房宫赋》", "example": null}, {"def": "遂迷,不复得路。--晋·陶渊明《桃花源记》", "example": null}, {"def": "其若迷。--唐·韩愈《朱文公校昌黎先生集》", "example": null}, {"def": "无迷其途。", "example": null}, {"def": "道中迷雾。--清·姚鼐《登", "example": null}, {"def": "迷mí", "example": null}, {"def": "⒈分辨不清～航。～途知返。", "example": null}, {"def": "⒉神智昏乱～糊。～乱。", "example": null}, {"def": "⒊沉醉，对某种事物产生特殊的眷恋～恋。", "example": null}, {"def": "⒋入迷于某种事物的人球～。养兔～。", "example": null}, {"def": "⒌诱惑，陶醉～惑。景色～人。", "example": null}, {"def": "⒍", "example": null}, {"def": "①信仰神仙鬼怪和命运等愚昧者～信。～信者愚昧。对于搞～信活动者，按治安法规处罚；若有罪行，则按《刑法》惩办。", "example": null}, {"def": "②盲目信仰和崇拜切莫～信。", "example": null}]','chinese-xinhua','0'),
