('2101143296414847046','糜','1','mí','米','17',NULL,'[{"def": "糜子", "example": null}, {"def": "糜", "example": null}, {"def": "(形声。从米,麻声。本义粥) 同本义", "example": null}, {"def": "糜,糁也。--《说文》", "example": null}, {"def": "糜,煮米使糜烂也。--《释名·释饮食》", "example": null}, {"def": "糜,糜粥。--《广韵》", "example": null}, {"def": "粥之稠者曰糜。--《尔雅·释言》注", "example": null}, {"def": "他家但愿富贵,贱妾与君共餵糜。--古乐府《东门行》", "example": null}, {"def": "又如糜沸(比喻世事混乱之甚,如糜粥之沸于釜中);糜粥(粥)", "example": null}, {"def": "糜", "example": null}, {"def": "粉碎,捣烂", "example": null}, {"def": "以糜敝之。--《荀子·富国》。注散也”", "example": null}, {"def": "万钧之所压,无不糜灭者,--贾山《至言》", "example": null}, {"def": "又如糜没(粉碎毁灭);糜灭(粉碎毁灭);糜", "example": null}, {"def": "糜méi", "example": null}, {"def": "⒈即\\"穄\\"。跟黍相似的谷物～子。", "example": null}, {"def": "糜mí", "example": null}, {"def": "⒈粥饭已成～。", "example": null}, {"def": "⒉烂，粉碎～烂。", "example": null}, {"def": "⒊浪费～费粮食。", "example": null}]','chinese-xinhua','0'),
('2101143296414847047','縻','1','mí','糸','17',NULL,'[{"def": "縻", "example": null}, {"def": "(形声。从糸,麻声。本义牛缰绳) 同本义", "example": null}, {"def": "縻,牛辔也。--《说文》", "example": null}, {"def": "縻,牛缰也。--《苍颉篇》", "example": null}, {"def": "马曰羁,牛曰縻。--应劭《汉官仪》", "example": null}, {"def": "羁縻勿绝。--《史记·史马相如传》", "example": null}, {"def": "叟揽縻而对。--刘禹锡《叹牛》", "example": null}, {"def": "又如揽縻(拉着牛鼻绳);縻粃(牵牛的缰绳);縻绠(牵引的绳子)", "example": null}, {"def": "縻", "example": null}, {"def": "束缚,拘束", "example": null}, {"def": "是谓縻举。--《孙子·谋攻》", "example": null}, {"def": "辞言无所系縻。--《韩非子·说难》", "example": null}, {"def": "又如羁縻(牵制;笼络);縻系(拘禁;捆缚;牵制);縻职(被职务牵制束缚);縻絷(拘禁);縻络(拘囚);縻军(指受牵制而不能灵活机动的军队)", "example": null}, {"def": "消耗,通靡”", "example": null}, {"def": "縻mí", "example": null}, {"def": "⒈系牛的绳子。", "example": null}, {"def": "⒉系，捆，拴羁～（〈喻〉牵制，笼络）。", "example": null}, {"def": "⒊牵制，束缚～军。", "example": null}]','chinese-xinhua','0'),
