('2101143296414847067','秘','1','mì','禾','10',NULL,'[{"def": "秘  bi", "example": null}, {"def": "秘鲁的简称", "example": null}, {"def": "秘鲁", "example": null}, {"def": "秘", "example": null}, {"def": "(形声。从禾,必声。 本义一种香草)", "example": null}, {"def": "不可测知;不公开", "example": null}, {"def": "祕,神也。从示,必声。--《说文》", "example": null}, {"def": "祕舞更奏。--张衡《西京赋》", "example": null}, {"def": "祕器。--《后汉书·袁安传》。注棺也。”", "example": null}, {"def": "祕宝。--《后汉书·班彪传》。传河图之属。”", "example": null}, {"def": "祕经。--《后汉书·苏竟传》。注图纬书也。”", "example": null}, {"def": "其事秘,世莫知也。--《史记·武帝本纪》", "example": null}, {"def": "又如秘箓(秘文);秘法(秘术,秘密", "example": null}, {"def": "秘 bì", "example": null}, {"def": "①见【便秘】。", "example": null}, {"def": "②姓。又见mì。", "example": null}, {"def": "【秘鲁】全称秘鲁共和国。位于南美洲西北部。面积128.5万平方公里。人口2179万（1989），印第安人占41%，印欧混血种人占36%，白人占16%，其余还有华人等少数民族。", "example": null}, {"def": "官方语言为西班牙语。96%的人信奉天主教。首都利马。", "example": null}, {"def": "秘（祕）mì旧读bì", "example": null}, {"def": "⒈不公开的，不可测知的～密。～方。他是个神～的人。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296414847068','密','1','mì','宀','11',NULL,'[{"def": "密", "example": null}, {"def": "(形声。从山,宓声。本义形状象堂屋的山)", "example": null}, {"def": "同本义(意思是山多)", "example": null}, {"def": "密,山如堂者。--《说文》", "example": null}, {"def": "松柏之鼠,不知堂密之有美枞。--《尸子》", "example": null}, {"def": "隐蔽的地方", "example": null}, {"def": "不窥密。--《礼记·少仪》。注隐曲处也。”", "example": null}, {"def": "姓", "example": null}, {"def": "密", "example": null}, {"def": "假借为比”。稠密;多", "example": null}, {"def": "密,稠 也,疏之对也。--《增韵》", "example": null}, {"def": "密云不雨。--《易·小畜卦》", "example": null}, {"def": "加密石焉。--《国语·晋语八》", "example": null}, {"def": "以陈楚之密迩于楚。--《左传·文公十七年》", "example": null}, {"def": "密布字印。--宋·沈括《梦溪笔谈·活板》", "example": null}, {"def": "密则无态。--清·龚自珍《", "example": null}, {"def": "密mì", "example": null}, {"def": "⒈距离短，空隙小，跟\\"稀\\"、\\"疏\\"相对～植。稠～。", "example": null}, {"def": "⒉精致，细致精～。细～。", "example": null}, {"def": "⒊亲近，感情好～切。～友。情好日～。", "example": null}, {"def": "⒋隐蔽，不公开～约。～码。～谋。秘～。保～。", "example": null}]','chinese-xinhua','0'),
('2101143296414847069','幂','1','mì','巾','12',NULL,'[{"def": "幂", "example": null}, {"def": "(形声。从巾,冥声。本义盖东西用的巾)", "example": null}, {"def": "同本义", "example": null}, {"def": "大巾谓之幂。--《小尔雅·广诂》", "example": null}, {"def": "幂人,掌共巾幂。--《周礼·天官·幂人》。注共巾,可以覆物。”", "example": null}, {"def": "幂用锡若絺。--《仪礼·大射礼》。注幂,覆尊巾也。”", "example": null}, {"def": "幂用疏布。--《仪礼·既夕礼》", "example": null}, {"def": "簠有盖幂。--《仪礼·公食大夫礼》", "example": null}, {"def": "又如幂首(古代妇女障面的一种头巾);幂人(《周礼》官名。掌共巾幂);幂篱(古代少数民族的一种头巾)", "example": null}, {"def": "数学名词。表示一个数自乘若干次的形式,如a自乘n次的幂为an", "example": null}, {"def": "云南少数民族计算布帛的单位", "example": null}, {"def": "幂（冪）mì", "example": null}, {"def": "⒈覆盖东西的布。", "example": null}, {"def": "⒉覆盖。", "example": null}, {"def": "⒊数学名词。一个数自乘若干次的形式叫\\"幂\\"，如α自乘n次的幂，符号记作。乘幂也叫\\"乘方\\"，一个数自乘若干次的积数。如4的3乘方（４３）又叫4的3乘～或4的3次～。", "example": null}]','chinese-xinhua','0'),
('2101143296414847070','谧','1','mì','讠','12',NULL,'[{"def": "谧", "example": null}, {"def": "(形声。本义安静) 同本义(指环境的安静,没有动荡,没有骚扰)", "example": null}, {"def": "谧,静语也,一曰无声也。--《说文》", "example": null}, {"def": "其化清谧。--《素问·气交变大论》。注谧,静也。”", "example": null}, {"def": "其政谧。--《五常正大论》。注谧,静也。”", "example": null}, {"def": "海表谧然。--《三国志·东夷传》", "example": null}, {"def": "四海谧然,宇内晏清。--《魏书·于栗忠传》", "example": null}, {"def": "内外寂谧。--《汉武帝内传》", "example": null}, {"def": "又如谧然(平静的样子);谧宁(宁静);谧尔(安静的样子);谧谧(沉寂的样子)", "example": null}, {"def": "谧mì安宁，平静～静。安～。", "example": null}]','chinese-xinhua','0'),
