('2101143296423235620','湎','1','miǎn','氵','12',NULL,'[{"def": "湎", "example": null}, {"def": "(形声。从水,面声。本义沉迷于酒)", "example": null}, {"def": "同本义", "example": null}, {"def": "湎,沈于酒也。--《说文》", "example": null}, {"def": "罔敢湎于酒。--《书·酒诰》。郑注饮酒齐色曰湎。”", "example": null}, {"def": "天不湎尔以酒。--《诗·大雅·荡》", "example": null}, {"def": "湎于酒。--《谷梁传》", "example": null}, {"def": "又如湎淫(沉溺于酒色)", "example": null}, {"def": "沈迷,沈溺(因过度爱好而难以舍弃)", "example": null}, {"def": "故多言而类,圣人也,少言而法,君子也;多言无法,而流湎然,虽辩,小人也。--《荀子·非十二子》", "example": null}, {"def": "国家喜音湛湎,则语之非乐非命。--《墨子·鲁命》", "example": null}, {"def": "通偭”。背,背向", "example": null}, {"def": "湎", "example": null}, {"def": "水流貌", "example": null}, {"def": "湎miǎn沉迷（多指饮酒）～于酒。", "example": null}]','chinese-xinhua','0'),
('2101143296423235621','缅','1','miǎn','纟','12',NULL,'[{"def": "缅", "example": null}, {"def": "(形声。从糸,面声。本义微丝)", "example": null}, {"def": "同本义", "example": null}, {"def": "缅,微丝也。--《说文》", "example": null}, {"def": "缅甸的简称", "example": null}, {"def": "缅", "example": null}, {"def": "遥远", "example": null}, {"def": "举下缅也。--《谷梁传·庄公三年》", "example": null}, {"def": "缅然引领南望。--《国语·楚语》", "example": null}, {"def": "又如缅然(遥远的样子);缅求(远求);缅渺(遥远的样子);缅远(久远;辽远;遥远);缅迈(远行)", "example": null}, {"def": "尽貌", "example": null}, {"def": "冀阙缅其堙尽。--潘岳《西征赋》", "example": null}, {"def": "又如缅述(尽情叙说,备叙)", "example": null}, {"def": "缅miǎn遥远～想。～怀故土。", "example": null}]','chinese-xinhua','0'),
('2101143296423235622','苗','1','miáo','艹','8',NULL,'[{"def": "苗", "example": null}, {"def": "(会意。从田,从苃。田里生长的形状象草的东西。本义禾苗,未吐穗的庄稼)", "example": null}, {"def": "同本义;泛指初生的植物", "example": null}, {"def": "苗,草生于田者。--《说文》", "example": null}, {"def": "无食我苗。--《诗·魏风·硕鼠》。传嘉谷也。”", "example": null}, {"def": "无苗。--《公羊传·庄公七年》。注苗者禾也。生曰苗,秀曰禾。”", "example": null}, {"def": "宋人有闵其苗之不长而揠之者,芒芒然归。--《孟子》", "example": null}, {"def": "南门之外有黄犊食苗道左者。--《韩非子·内储说上》", "example": null}, {"def": "八月苗未枯。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "无苗时采。", "example": null}, {"def": "有苗时采。", "example": null}, {"def": "又如补苗;间苗;秧苗;麦苗;豆苗;壮苗(健壮的幼苗)", "example": null}, {"def": "指禾谷之实", "example": null}, {"def": "苗miáo", "example": null}, {"def": "⒈没有吐穗的庄稼。泛指初生的植物禾～。蒜～。树～。", "example": null}, {"def": "⒉某些初生的饲养动物鱼～。猪～（也叫苗猪）。", "example": null}, {"def": "⒊形状像苗的火～。", "example": null}, {"def": "⒋事物的原由、开端或早期显露的迹象根～。～头。矿～。", "example": null}, {"def": "⒌疫苗，能使机体产生免疫力的生物制剂卡介～。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
