('2101143296427429890','杪','1','miǎo','木','8',NULL,'[{"def": "杪", "example": null}, {"def": "(形声。从木,少声。本义树枝的细梢)", "example": null}, {"def": "同本义", "example": null}, {"def": "杪,木标末也。--《说文》", "example": null}, {"def": "树锋曰杪。--《通俗文》", "example": null}, {"def": "偃蹇杪颠。--司马相如《上林赋》", "example": null}, {"def": "或在木杪。--清·纪昀《阅微草堂笔记》", "example": null}, {"def": "又如杪颠(树木末梢);杪头(树梢)", "example": null}, {"def": "末尾,时间上的终止", "example": null}, {"def": "必于岁之杪。--《礼记·王制》", "example": null}, {"def": "又如岁杪(年尾);杪春(暮春);杪秋(晚秋);杪冬(暮冬);杪岁(岁末);杪节(候之末)", "example": null}, {"def": "杪", "example": null}, {"def": "微小;细微", "example": null}, {"def": "阔略杪小之礼。--《后汉书·冯衍传》", "example": null}, {"def": "又如杪小(细小,微小);杪杪(谓渺小);杪忽(极小的量度单位);杪黍(形容极其细微)", "example": null}, {"def": "杪miǎo", "example": null}, {"def": "⒈树枝的细梢树～。", "example": null}, {"def": "⒉年、月、季节的末尾岁～。秋～。", "example": null}, {"def": "⒊细小～ 小。微～。", "example": null}]','chinese-xinhua','0'),
('2101143296427429891','眇','1','miǎo','目','9',NULL,'[{"def": "眇", "example": null}, {"def": "(会意兼形声。从目,从少,少亦声。本义一只眼小)", "example": null}, {"def": "同本义", "example": null}, {"def": "眇,一目小也。--《说文》", "example": null}, {"def": "眇能视,跛能履。--《易·履》", "example": null}, {"def": "又指小目", "example": null}, {"def": "引申眼睛失明,或一目失明", "example": null}, {"def": "生而眇者不识日。--苏轼《日喻》", "example": null}, {"def": "见一先生,眇一目,跛一足。--明·罗贯中《全图绣像三国演义》", "example": null}, {"def": "又如眇视(偏盲,用一只眼看)", "example": null}, {"def": "通渺”。高远;久远", "example": null}, {"def": "不厌深眇而已矣。--《庄子·庚桑楚》", "example": null}, {"def": "彼王者不然;仁眇天下,义眇天下,威眇天下。--《荀子·王制》", "example": null}, {"def": "眇不知其所蹠。--《楚辞·九章》", "example": null}, {"def": "又如眇漫(辽远无际的样子);", "example": null}, {"def": "眇miǎo", "example": null}, {"def": "⒈〈古〉指瞎了一只眼睛～目◇来也泛指瞎了眼。〈引〉眯着眼睛看你来仔细～一～。", "example": null}, {"def": "⒉微小微～。", "example": null}, {"def": "⒊高远，遥远。", "example": null}, {"def": "眇miào 1.精微;奥妙。", "example": null}, {"def": "眇miāo 1.方言≤快地看一下;偷看。", "example": null}]','chinese-xinhua','0'),
('2101143296427429892','秒','1','miǎo','禾','9',NULL,'[{"def": "秒", "example": null}, {"def": "(形声。从禾,少声。本义禾芒)", "example": null}, {"def": "同本义", "example": null}, {"def": "秒,禾芒也。--《说文》", "example": null}, {"def": "造计秒忽。--《汉书·叙传下》。注引刘德秒,禾芒也。”", "example": null}, {"def": "又如秒忽(秒是禾芒,忽是细丝,比喻微细);秒末(微小)", "example": null}, {"def": "末端", "example": null}, {"def": "癸巳七月之秒,余从西俗避暑白雷登海口。--清·薛福成文", "example": null}, {"def": "秒", "example": null}, {"def": "计量单位的名称", "example": null}, {"def": "时间一分的1/60;特指厘米-克-秒制的时间单位", "example": null}, {"def": "角度一分的1/60", "example": null}, {"def": "作为测定液体粘度的一个测量单位的时间", "example": null}, {"def": "秒miǎo", "example": null}, {"def": "⒈谷物种子壳上的芒。", "example": null}, {"def": "⒉单位名称", "example": null}, {"def": "①时间六十～为一分钟。", "example": null}, {"def": "②圆周六十～为一分。", "example": null}, {"def": "③经纬度六十～为一分。", "example": null}]','chinese-xinhua','0'),
('2101143296427429893','淼','1','miǎo','水','12',NULL,'[{"def": "淼", "example": null}, {"def": "(会意。从三水。又作渺”。本义水大的样子) 同本义", "example": null}, {"def": "淼南渡之焉如?--《楚辞·九章·哀郢》", "example": null}, {"def": "又如淼淼(水势浩大的样子);淼渺(水广阔无际的样子);淼漫(水流广远的样子);淼漭(辽阔的样子)", "example": null}, {"def": "淼茫", "example": null}, {"def": "淼miǎo水大，望不见边际烟波浩～。", "example": null}]','chinese-xinhua','0'),
('2101143296431624192','渺','1','miǎo','氵','12',NULL,'[{"def": "渺", "example": null}, {"def": "(形声。从水,眇声。本义水面辽阔)", "example": null}, {"def": "同本义", "example": null}, {"def": "四际渺弥。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "又如浩渺(形容水面辽阔);渺冥(渺远);渺弥(水流旷远的样子);渺漭(水势辽阔的样子);渺绵(水流不断的样子)", "example": null}, {"def": "遥远;邈远;渺茫", "example": null}, {"def": "渺渺兮余怀,望美人兮天一方。--苏轼《前赤壁赋》", "example": null}, {"def": "又如渺茫(辽阔的样子;凝不清;虚妄无凭;难以预期;没有把握;空虚);渺莽(烟波辽阔无际的样子);渺无人烟(一片渺茫,没有人家);渺漠(广漠无际)", "example": null}, {"def": "微小;藐小", "example": null}, {"def": "寄蜉蝣于天地,渺沧海之一粟。--苏轼《", "example": null}, {"def": "渺miǎo", "example": null}, {"def": "⒈微小～不足道。", "example": null}, {"def": "⒉遥远，深远。", "example": null}, {"def": "⒊水大，望不见边际烟波浩～。", "example": null}, {"def": "⒋", "example": null}, {"def": "①〈喻〉时间长，相隔远音讯～茫。", "example": null}, {"def": "②〈喻〉看不清前途或捉摸不定希望～茫。", "example": null}]','chinese-xinhua','0'),
('2101143296431624193','缈','1','miǎo','纟','12',NULL,'[{"def": "缈 (形声)", "example": null}, {"def": "缥缈”隐隐约约,若有若无。亦作飘渺”", "example": null}, {"def": "缈miǎo", "example": null}]','chinese-xinhua','0'),
('2101143296431624194','藐','1','miǎo','艹','17',NULL,'[{"def": "藐", "example": null}, {"def": "(形声。从苃,貌声。本义小,幼稚)", "example": null}, {"def": "同本义", "example": null}, {"def": "孤女藐焉始孩。--潘岳《寡妇赋》", "example": null}, {"def": "又如藐孤(弱小的孤儿);藐躬(孱弱的躯体);藐然(幼小的样子);藐藐(幼小的样子)", "example": null}, {"def": "孤独的", "example": null}, {"def": "通邈”。远", "example": null}, {"def": "藐蔓蔓之不可量兮,缥绵绵之不可纡。--《楚辞·九章·悲回风》", "example": null}, {"def": "藐", "example": null}, {"def": "通眇”。轻视", "example": null}, {"def": "曰以是藐诸孤辱在大夫,其若之何?”--《左传·僖公九年》", "example": null}, {"def": "说大人则藐之。--《孟子·尽心下》", "example": null}, {"def": "又如藐法;藐视;藐玩(轻视玩忽)", "example": null}, {"def": "藐miǎo", "example": null}, {"def": "⒈小，幼稚～小。", "example": null}, {"def": "⒉轻视～视。", "example": null}, {"def": "⒊通\\"邈\\"。远。", "example": null}]','chinese-xinhua','0'),
('2101143296431624195','邈','1','miǎo','辶','17',NULL,'[{"def": "邈", "example": null}, {"def": "(形声。从辵,貌声。本义距离遥远)", "example": null}, {"def": "同本义,通藐”", "example": null}, {"def": "振景拔迹,顾邈同列。--陆机《谢平原内史表》", "example": null}, {"def": "互相轩邈。--吴均《与朱元思书》", "example": null}, {"def": "又如邈若山河(形容遥远得如隔山河);邈绵(遥远;旷远);邈廓(辽阔);邈远(遥远);邈然(遥远的样子)", "example": null}, {"def": "久远。指时间长", "example": null}, {"def": "渺茫,凝不清", "example": null}, {"def": "高远,超卓", "example": null}, {"def": "邈miǎo", "example": null}, {"def": "⒈远悠～。", "example": null}, {"def": "⒉通\\"藐\\"。轻视。", "example": null}]','chinese-xinhua','0'),
