('2101143296431624242','闵','1','mǐn','门','7',NULL,'[{"def": "闵", "example": null}, {"def": "(形声。从门,文声。本义吊唁)", "example": null}, {"def": "同本义", "example": null}, {"def": "闵,吊者在门也。--《说文》", "example": null}, {"def": "同悯”。怜恤,哀怜", "example": null}, {"def": "闵予小子,遭家不造。--《诗·周颂·闵予小子》", "example": null}, {"def": "又如闵察(怜悯审察);闵悼(怜恤哀悼);闵悔(怜恤而痛悔);闵笑(怜悯嘲笑)", "example": null}, {"def": "勉。黾勉", "example": null}, {"def": "予惟用闵于天越民。--《书·君奭》", "example": null}, {"def": "又如闵免(勤免不息。同黾勉。也作闵勉)", "example": null}, {"def": "忧虑", "example": null}, {"def": "宋人有闵其苗之不长而揠之者。--《孟子·公孙丑上》", "example": null}, {"def": "闵闵焉如农夫之望岁。--《左传·昭公三十二年》", "example": null}, {"def": "又如闵凶(忧伤的事", "example": null}, {"def": "闵mǐn", "example": null}, {"def": "⒈忧患，凶丧～凶。", "example": null}, {"def": "⒉忧虑，担心～人才之少（少缺少）。", "example": null}, {"def": "⒊（又写作\\"悯\\"）哀怜。", "example": null}, {"def": "闵mín 1.见\\"闵天\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296431624243','抿','1','mǐn','扌','8',NULL,'[{"def": "抿", "example": null}, {"def": "用手抚摸", "example": null}, {"def": "抿,《说文》抚也。--《集韵》", "example": null}, {"def": "用小刷子沾水或油擦抹或刻意整理", "example": null}, {"def": "拭", "example": null}, {"def": "稍稍合拢", "example": null}, {"def": "抿mǐn", "example": null}, {"def": "⒈刷，抹～皮鞋。", "example": null}, {"def": "⒉微微地合拢（多指嘴或翅）～着嘴笑。", "example": null}, {"def": "⒊微合嘴唇，少许沾尝她不会喝酒，～都不敢～。", "example": null}]','chinese-xinhua','0'),
('2101143296431624244','泯','1','mǐn','氵','8',NULL,'[{"def": "冺", "example": null}, {"def": "(形声。从水,民声。本义灭,尽) 同本义", "example": null}, {"def": "泯然众人。--宋·王安石《伤仲永》", "example": null}, {"def": "又如泯灭,泯没", "example": null}, {"def": "泯", "example": null}, {"def": "乱;混乱", "example": null}, {"def": "王室之乱,靡邦不泯。--陆机《答贾长渊》", "example": null}, {"def": "又如泯杂(混杂;乱杂);泯泯(纷乱的样子)", "example": null}, {"def": "泯除", "example": null}, {"def": "泯除杂念", "example": null}, {"def": "泯灭", "example": null}, {"def": "往者汉祚衰微,率土分崩,生民之命,几于泯灭。--《三国志·钟会传》", "example": null}, {"def": "难以泯灭的印象", "example": null}, {"def": "泯没", "example": null}, {"def": "严霜夏坠,从弟雕落,二子泯没,天丧予,何痛如之!", "example": null}, {"def": "泯mǐn〈动〉消灭，丧失＞诗曰∶\\"家国～绝，宗庙烧燔。\\"│～灭│～没│良心未～。", "example": null}, {"def": "泯miǎn 1.目不明貌。", "example": null}]','chinese-xinhua','0'),
('2101143296431624245','勄','1','mǐn','','5',NULL,'[{"def": "勄mǐn 1.敏捷。一说足大指名。", "example": null}]','chinese-xinhua','0'),
('2101143296431624246','闽','1','mǐn','门','9',NULL,'[{"def": "闽", "example": null}, {"def": "(形声。从虫,门声。本义古种族名。生活在浙江南部和福建一带,后因称福建为闽)", "example": null}, {"def": "同本义", "example": null}, {"def": "閩,东南越也。--《说文》", "example": null}, {"def": "七閩九貉。--《周礼·职方式》", "example": null}, {"def": "閩在海中。--《山海经·海内经》", "example": null}, {"def": "选自閩禺。--左思《吴都赋》", "example": null}, {"def": "又如闽中(泛指福建省地);闽江(水名。为福建省第一大河流);闽关(指福建通内地的关隘);闽岭(福建北部的山岭)", "example": null}, {"def": "五代十国之一", "example": null}, {"def": "闽mǐn福建省的简称。", "example": null}]','chinese-xinhua','0'),
('2101143296431624247','悯','1','mǐn','忄','10',NULL,'[{"def": "悯", "example": null}, {"def": "(形声。从心,闵声。本义怜恤) 同本义", "example": null}, {"def": "隋堤柳,悯亡国也。--白居易《新乐府序》", "example": null}, {"def": "人远悲天悯人之怀,岂为一己之不遇乎?--清·黄宗羲《朱人远墓志铭》", "example": null}, {"def": "又如悯人之凶(原谅、可怜凶恶之人。形容看透世情,慈悲为怀,无所计较);悯念(怜悯);悯宥(怜悯宽宥);悯笑(怜悯讪笑;可怜亦复可笑);悯贫(怜恤贫苦的人);悯然(哀怜的样", "example": null}, {"def": "子)", "example": null}, {"def": "悯", "example": null}, {"def": "忧愁;烦闷", "example": null}, {"def": "阨穷而不悯。--《孟子》", "example": null}, {"def": "曲罢悯然。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如悯默(因忧伤而沉默);悯悯(忧伤的样子);悯愧(忧伤怀惭);悯叹(忧", "example": null}, {"def": "悯mǐn", "example": null}, {"def": "⒈哀怜～惜。怜～。", "example": null}, {"def": "⒉忧愁。忧患。", "example": null}]','chinese-xinhua','0'),
('2101143296431624248','敏','1','mǐn','攵','11',NULL,'[{"def": "敏", "example": null}, {"def": "(形声。从攴,每声。甲骨文字形,像用手整理头发的样子。本义动作快)", "example": null}, {"def": "同本义", "example": null}, {"def": "敏,疾也。--《说文》", "example": null}, {"def": "曾孙不怒,农夫克敏。--《诗·小雅·甫田》", "example": null}, {"def": "君子欲纳于言而敏于行。--《论语·里仁》", "example": null}, {"def": "敏于事而慎于言。--《论语·学而》", "example": null}, {"def": "又如敏给(敏捷);敏赡(敏捷而多智);敏睿(敏捷聪慧);敏疾(敏捷,迅速);敏思(才思敏捷);敏才(敏捷的才思)", "example": null}, {"def": "思想敏锐,反应快", "example": null}, {"def": "回虽不敏,请事斯语矣。--《论语·颜渊》", "example": null}, {"def": "是故聪与敏,可恃而不可恃也。--彭端淑《为学一首示子侄》", "example": null}, {"def": "我虽不敏。--《孟子·梁惠", "example": null}, {"def": "敏mǐn", "example": null}, {"def": "⒈聪明，机智，迅速，反应快～锐。～捷。～感。灵～。～而好学。", "example": null}, {"def": "⒉努力，奋勉～行而不敢怠。", "example": null}]','chinese-xinhua','0'),
('2101143296431624249','笢','1','mǐn','','5',NULL,'[{"def": "笢mǐn 1.青竹篾。 2.见\\"笢笏\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296431624250','湣','1','mǐn','氵','12',NULL,'[{"def": "湣〈名〉", "example": null}, {"def": "古代谥号用字。同闵”", "example": null}, {"def": "及其綦也,索为匹夫,不可得也,齐湣、宋献是也。--《荀子》", "example": null}, {"def": "湣mǐn〈古〉谥号用字。战国时有齐～王。泯mǐn灭，尽～灭。～绝。", "example": null}]','chinese-xinhua','0'),
('2101143296431624251','皿','1','mǐn','皿','5',NULL,'[{"def": "皿", "example": null}, {"def": "(象形。小篆字形,象碗、盆之类的食器。本义器皿) 同本义。泛指碗碟杯盘一类饮食用具", "example": null}, {"def": "皿,饭器之用器也。--《说文》", "example": null}, {"def": "于交皿虫为衜。--《左传·昭公元年》。注器也。”", "example": null}, {"def": "是不昭谷明而皿衜也。--《国语·晋语》", "example": null}, {"def": "牲杀器皿。--《孟子》。注皿所以覆器者也。”", "example": null}, {"def": "器皿非满案。--宋·司马光《训俭示康》", "example": null}, {"def": "又如皿金(金属器皿);皿卷(清代科举,顺天乡试监生的试卷);皿器(盛物用具的统称)", "example": null}, {"def": "皿mǐn", "example": null}]','chinese-xinhua','0'),
