('2101143296431624253','茗','1','mínɡ','艹','9',NULL,'[{"def": "茖葱", "example": null}, {"def": "茗míng", "example": null}, {"def": "⒈茶树的嫩芽。", "example": null}, {"def": "⒉茶香～。渴饮～汁。", "example": null}]','chinese-xinhua','0'),
('2101143296431624254','冥','1','mínɡ','冖','10',NULL,'[{"def": "冥", "example": null}, {"def": "(会意。小篆字形,从日,从六,冖声。日,太阳,日数十,十六日而月始亏,幽暗也。本义昏暗)", "example": null}, {"def": "同本义", "example": null}, {"def": "冥,幽也。--《说文》", "example": null}, {"def": "冥,暗也。--《广雅》", "example": null}, {"def": "冥者,明之藏也。--《太玄·玄文》", "example": null}, {"def": "维尘冥冥。--《诗·无将大车》", "example": null}, {"def": "擿埴索涂,冥行而已矣。--《法言·修身》", "example": null}, {"def": "冥火薄天,兵车雷运。--枚乘《七发》", "example": null}, {"def": "其庙独冥。--《汉书·五行志》", "example": null}, {"def": "又如冥冥(昏暗);冥冥灭灭(昏暗不明的样子);冥蒙(晦暗不明);冥升(暗升;后指不断攀登);冥幻(暗淡虚幻)", "example": null}, {"def": "深远;幽深", "example": null}, {"def": "临万丈之绝冥。--孙绰", "example": null}, {"def": "冥míng", "example": null}, {"def": "⒈昏暗晦～。", "example": null}, {"def": "⒉愚昧～顽。", "example": null}, {"def": "⒊深远高低～迷，不知东西。〈引〉深入的（思索）～思苦想。", "example": null}, {"def": "⒋夜～行（夜里行路）。", "example": null}, {"def": "⒌迷信者所谓\\"人死后进入的世界\\"\\"～间\\"\\"～府\\"等是人们虚构的。", "example": null}, {"def": "冥mián 1.见\\"颠冥\\"。", "example": null}, {"def": "冥miàn 1.见\\"冥眴\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296431624255','眳','1','mínɡ','','5',NULL,'[{"def": "眳míng 1.眉与睫之间。 2.见\\"眳蒙\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296431624256','铭','1','mínɡ','钅','11',NULL,'[{"def": "铭", "example": null}, {"def": "(形声。从金,名声。从金,与钟鼎器物有关。本义在器物上雕刻文字)", "example": null}, {"def": "同本义", "example": null}, {"def": "铭者,自名也。自名以称扬其先祖之美而明著之后世者也。--《礼记·祭统》", "example": null}, {"def": "铭,明旌也。--《礼记·檀弓》", "example": null}, {"def": "铭书于王之大常。--《周礼·司勋》。注铭之言名也。”", "example": null}, {"def": "名,题勒也。--《字林》", "example": null}, {"def": "其铭有之。--《国语·晋语》。注刻器曰铭。”", "example": null}, {"def": "铭功会稽岭。--李白《古风五十九首·三》", "example": null}, {"def": "又如铭功(在金石上刻文字来记下功勋);铭戒(在金石等物品上,刻下言辞,以为劝诫);铭勒(镌刻金石,以记述功德)", "example": null}, {"def": "牢记不忘", "example": null}, {"def": "铭心立报,永矣无贰。", "example": null}, {"def": "铭míng", "example": null}, {"def": "⒈刻写在器物上记述生平、事业或警语等的文字鼎～。墓志～。座右～。", "example": null}, {"def": "⒉在器物上刻字～刻。也〈喻〉深刻记住～记在心。", "example": null}, {"def": "⒊文体的一种陋室～。", "example": null}]','chinese-xinhua','0'),
('2101143296431624257','鄍','1','mínɡ','阝','12',NULL,'[{"def": "姓", "example": null}, {"def": "鄍míng 1.春秋虞邑◇属晋。在今山西平陆东北。", "example": null}]','chinese-xinhua','0'),
