('2101143296431624262','瞑','1','mínɡ','目','15',NULL,'[{"def": "瞑", "example": null}, {"def": "(形声。从目,民声。本义闭上眼睛)", "example": null}, {"def": "同本义", "example": null}, {"def": "眠,寐也。--《玉篇》", "example": null}, {"def": "吾子有疾,虽不能省视,而竟夕不眠。--《后汉书·第五伦传》", "example": null}, {"def": "致命于帝,然后得眠些。--《楚辞·招魂》", "example": null}, {"def": "余峨之山有兽焉,见人则眠。--《山海经·东山经》", "example": null}, {"def": "久之,目似瞑,意暇甚。--《聊斋志异·狼》", "example": null}, {"def": "睡觉", "example": null}, {"def": "不眠忧战伐。--杜甫《宿江边阁》", "example": null}, {"def": "春眠不觉晓,处处闻啼鸟。--孟浩然《春晓》", "example": null}, {"def": "又如不眠之夜;失眠(夜间睡不着);安眠(安稳地熟睡);眠食(睡眠和饮食)", "example": null}, {"def": "横卧;平放", "example": null}, {"def": "眠琴绿阴,上有飞瀑。--司空图《诗品》", "example": null}, {"def": "又如眠桅(", "example": null}, {"def": "瞑míng", "example": null}, {"def": "⒈闭上眼睛通夜不～。", "example": null}, {"def": "⒉", "example": null}, {"def": "①闭眼～目不答。", "example": null}, {"def": "②死他已～目作古。", "example": null}, {"def": "瞑mián 1.通\\"眠\\"。假寐，小睡。亦泛指睡觉。 2.见\\"瞑眩\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296431624263','螟','1','mínɡ','虫','16',NULL,'[{"def": "螟", "example": null}, {"def": "螟虫,螟蛾的幼虫", "example": null}, {"def": "稻的害虫);螟蠹(两种害虫名)", "example": null}, {"def": "螟蛾", "example": null}, {"def": "螟蛉", "example": null}, {"def": "螟蛉作食物。古人误认为蜾赢不产子,喂养螟蛉为子,因此用螟蛉”比喻义子", "example": null}, {"def": "周侗年迈,巴不得将平生一十八般武艺,尽心传授与螟蛉之子。--", "example": null}, {"def": "螟míng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296431624264','名','1','mínɡ','口','6',NULL,'[{"def": "名", "example": null}, {"def": "(会意。甲骨文字形。从口夕。本义自己报出姓名;起名字)", "example": null}, {"def": "同本义", "example": null}, {"def": "名,自命也。--《说文》", "example": null}, {"def": "黄帝正名百物。--《礼记·祭法》", "example": null}, {"def": "名之曰幽厉。--《孟子》", "example": null}, {"def": "名公器也。--《庄子·天运》", "example": null}, {"def": "秦氏有好女,自名为罗敷。--《乐府诗集》", "example": null}, {"def": "以故其后名之曰褒禅”。--宋·王安石《游褒禅山记》", "example": null}, {"def": "名之者谁。--宋·欧阳修《醉翁亭记》", "example": null}, {"def": "自名蟹壳青”。--《聊斋志异·促织》", "example": null}, {"def": "又如名品(辨明品级)", "example": null}, {"def": "称说;说出", "example": null}, {"def": "不能名其一处。--《虞初新志·秋声诗自序》", "example": null}, {"def": "又如不可名状;莫名其妙;名状(形容描述)", "example": null}, {"def": "出名,有名", "example": null}, {"def": "名míng", "example": null}, {"def": "⒈人或事物的称谓～字。～称。地～。", "example": null}, {"def": "⒉说出，叫出莫～其妙。无以～之。", "example": null}, {"def": "⒊声誉，有声誉的出～。有～。～人。～言。～医。～将。", "example": null}, {"def": "⒋计人数的量词教师五～。", "example": null}, {"def": "⒌", "example": null}, {"def": "①借用作某件事的身份、资格我以工会会员的～义。", "example": null}, {"def": "②指表面上、形式上的名称，也简作\\"名\\"挂～。有～无实。", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296431624265','明','1','mínɡ','日','8',NULL,'[{"def": "明", "example": null}, {"def": "(会意。甲骨文以日、月”发光表示明亮。小篆从月囧,从月,取月之光;从囧,取窗牖之明亮。本义明亮,清晰明亮)", "example": null}, {"def": "同本义。与昏暗”相对", "example": null}, {"def": "杔,照也。--《说文》", "example": null}, {"def": "照临四方曰明。--《左传·昭公二十八年》", "example": null}, {"def": "东方明矣。--《诗·齐风·鸡鸣》", "example": null}, {"def": "明,精白也。--《国语·周语》", "example": null}, {"def": "视曰明。--《书·洪范》", "example": null}, {"def": "明则著。--《礼记·中庸》", "example": null}, {"def": "明星谓之启明。--《尔雅》", "example": null}, {"def": "东有启明。--《诗·小雅·大东》", "example": null}, {"def": "在天者莫明于日月。--《荀子·天论》", "example": null}, {"def": "不知明镜里,何处得秋霜。--唐·李白《秋浦歌》", "example": null}, {"def": "月明星稀,乌", "example": null}, {"def": "明míng", "example": null}, {"def": "⒈亮，照亮～晃晃。天～。灯火通～。", "example": null}, {"def": "⒉清楚，懂得，了解～白。～确。～礼。深～大义。～见万里。", "example": null}, {"def": "⒊公开，不隐蔽，显露在外，跟\\"暗\\"相对～说。～码实价。～枪暗箭。", "example": null}, {"def": "⒋视力，视力好左丘失～（左丘〈古〉人名）。聪耳～目。", "example": null}, {"def": "⒌看得清，认得准，见识高～智。英～。心～眼亮。", "example": null}, {"def": "⒍次，下一个（专指日、年）～天。～年。", "example": null}, {"def": "⒎迷信者称神灵神～。", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐朝代名。明朝，公元1368-1644年。第一代君主是朱元璋。", "example": null}]','chinese-xinhua','0'),
('2101143296431624266','鸣','1','mínɡ','鸟','8',NULL,'[{"def": "鸣", "example": null}, {"def": "(会意。从口,从鸟。本义鸟叫)", "example": null}, {"def": "同本义", "example": null}, {"def": "鸣,鸟声也。--《说文》", "example": null}, {"def": "鸟兽之音曰鸣。--《管辂别传》", "example": null}, {"def": "鸣鹤在阴。--《易·中孚》", "example": null}, {"def": "凤皇鸣矣。--《诗·大雅·卷阿》", "example": null}, {"def": "鸡既鸣矣,朝既盈矣。--《诗·鸡鸣》", "example": null}, {"def": "狗吠深巷中,鸡呜桑树巅。--陶渊明《归园田居》", "example": null}, {"def": "又如∶鸣管(鸟类的发声装置);鸣凤(凤鸟鸣叫);鸣雁(雁鸣叫)", "example": null}, {"def": "泛指发声", "example": null}, {"def": "震为鸣。--《易·说卦传》", "example": null}, {"def": "萧萧马鸣。--《诗·小雅·车攻》", "example": null}, {"def": "鸣玉者,佩玉也。--《南子·贾经》", "example": null}, {"def": "驴一鸣。--唐·柳宗元《三戒》", "example": null}, {"def": "虽大风不能鸣也。--宋· 苏轼《石钟山记》", "example": null}, {"def": "又", "example": null}, {"def": "鸣míng", "example": null}, {"def": "⒈禽兽或虫叫鸡～。鹿～。蝉～。", "example": null}, {"def": "⒉发响，使发响雷～。自～钟。～礼炮。", "example": null}, {"def": "⒊〈表〉感情，喊叫～谢。～不平。～冤叫屈。", "example": null}, {"def": "⒋表达意见、主张等百家争～。", "example": null}]','chinese-xinhua','0'),
