('2101143296431624275','酩','1','mǐnɡ','酉','13',NULL,'[{"def": "酩", "example": null}, {"def": "(形声。从酉,名声。酉”与酒有关)", "example": null}, {"def": "大醉的样子", "example": null}, {"def": "暗地里,暗中", "example": null}, {"def": "酩酊", "example": null}, {"def": "日夕倒载归,酩酊无所知。--《晋书》", "example": null}, {"def": "酩mǐng", "example": null}]','chinese-xinhua','0'),
('2101143296431624276','谬','1','miù','讠','13',NULL,'[{"def": "谬", "example": null}, {"def": "(形声。本义极端错误,非常不合情理)", "example": null}, {"def": "同本义", "example": null}, {"def": "谬,狂者之妄言也。--《说文》", "example": null}, {"def": "考之三王而不谬。--礼记·中庸》", "example": null}, {"def": "天下悦之以谬悠之说。--《庄子》", "example": null}, {"def": "解心之谬。--《庄子·庚桑楚》", "example": null}, {"def": "故《易》曰差以毫厘,谬以千里。”--《汉书·司马迁传》", "example": null}, {"def": "园喜以谬赏。--唐·魏征《谏太宗十思疏》", "example": null}, {"def": "故闻之而不见,虽博必谬。--《荀子·儒效》", "example": null}, {"def": "今言华”如华实”之华”者,盖音谬也。--王安石《游褒禅山记》", "example": null}, {"def": "又如谬戾(荒谬乖僻);谬谈(谬语妄说);谬举(妄举,举用不适当的人才);谬种流传(荒谬错误的文章或议论辗", "example": null}, {"def": "谬miù", "example": null}, {"def": "⒈错误，与客观事实不符～论。～误。荒～。大～。", "example": null}, {"def": "⒉差误差以毫厘，～以千里。", "example": null}]','chinese-xinhua','0'),
('2101143296431624277','缪','1','miù','纟','14',NULL,'[{"def": "缪", "example": null}, {"def": "纰缪;错误", "example": null}, {"def": "多辞缪说,不耕而食,不织而衣。--《庄子·盗跖》", "example": null}, {"def": "又如缪舛(舛错,谬误);缪戾(错舛,违背);缪悠(妄诞不经);缪说(荒谬错误的言论);缪妄(荒缪无稽)", "example": null}, {"def": "通穆”。穆然,静思", "example": null}, {"def": "孔子有所缪然思焉。--《孔子家语·辨乐》", "example": null}, {"def": "通穆”。虔诚", "example": null}, {"def": "太公召公乃缪卜。--《史记·鲁周公世家》", "example": null}, {"def": "缪", "example": null}, {"def": "诈伪", "example": null}, {"def": "故相如缪与令相重。--《史记·司马相如列传》", "example": null}, {"def": "又如缪数(诈伪之术);缪丑(宋秦桧之谥。借指奸佞)", "example": null}, {"def": "通樛”。绞结", "example": null}, {"def": "其妻鲁人也,衣衰而缪緻。--", "example": null}, {"def": "缪miào", "example": null}, {"def": "⒈姓。", "example": null}, {"def": "缪miù", "example": null}, {"def": "⒈通\\"谬\\"。错误纰～。", "example": null}, {"def": "⒉假装～为恭敬。", "example": null}, {"def": "缪móu", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉\\"。", "example": null}, {"def": "缪jiū 1.通\\"樛\\"。绞结。 2.通\\"纠\\"。", "example": null}, {"def": "缪mù 1.古时宗庙所列次序，父子辈递为昭穆，左为昭，右为穆。 2.调和;和悦。 3.虔诚貌。参见\\"缪卜\\"。", "example": null}, {"def": "缪liáo 1.缠绕。", "example": null}, {"def": "缪lù 1.并;合。参见\\"缪力同心\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296431624278','摩','1','mó','手','15',NULL,'[{"def": "摩", "example": null}, {"def": "(形声。从手,麻声。本义摩擦,磨蹭)", "example": null}, {"def": "同本义", "example": null}, {"def": "摩,研也。--《说文》", "example": null}, {"def": "刮摩之工。--《考工记》", "example": null}, {"def": "鎋击摩车而相过。--《战国策·齐策》", "example": null}, {"def": "人肩摩。--《战国策·秦策》", "example": null}, {"def": "濯手以摩之,去其皱。--《礼记·内则》", "example": null}, {"def": "又如摩戛(摩擦。也作磨戛);摩厉(磨物使锐。引申有磨炼、钻研的意思);摩肩接毂(肩挨着肩,车子擦着车子);摩肩(肩挨着肩);摩拭(揩擦)", "example": null}, {"def": "迫近,接近", "example": null}, {"def": "又如摩近(接近);摩垒(迫近敌垒);摩霄(接近云天,冲天)", "example": null}, {"def": "通磨”。磨砺", "example": null}, {"def": "阴阳相摩,天地相荡。--《礼记·乐记》", "example": null}, {"def": "是故刚柔相摩,八", "example": null}, {"def": "摩mā", "example": null}, {"def": "①用手按住物体一下一下地轻轻移动把衣服～挲平。", "example": null}, {"def": "摩mó", "example": null}, {"def": "⒈摸，擦，接触按～。抚～。～破了点皮。～肩继踵。～拳擦掌。", "example": null}, {"def": "⒉接近，迫近～近。～天岭。～天大楼。", "example": null}, {"def": "⒊研究，切磋，揣测观～。心～意揣。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "①物体与物体紧密接触，来回移动。", "example": null}, {"def": "②（也写作\\"磨擦\\"）〈喻〉制造事端，引起纠纷、冲突。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "摩ma 1.助词。表示疑问。", "example": null}]','chinese-xinhua','0'),
