('2101143296431624314','殁','1','mò','歹','8',NULL,'[{"def": "殁", "example": null}, {"def": "(形声。从歺声。歺残骨,与死亡有关。本义死)", "example": null}, {"def": "同本义", "example": null}, {"def": "殁,终也。--《广雅·释诂四》", "example": null}, {"def": "伯乐既殁兮。--《史记·屈原贾生列传》", "example": null}, {"def": "管仲殁矣。--《国语·晋语四》", "example": null}, {"def": "少者殁而长者存。--韩愈《祭十二郎文》", "example": null}, {"def": "又如既殁(既已死亡);殁世(终生;终其一生;去世);殁命(舍命,拚死);殁齿(没齿,终生)", "example": null}, {"def": "通刎”。自杀", "example": null}, {"def": "消灭", "example": null}, {"def": "道逢匈奴骑兵,皆为所殁。--《后汉书》", "example": null}, {"def": "通没”。隐没;沦没", "example": null}, {"def": "神女殁幽境,汤池流大川。--唐·李白《安州应城玉", "example": null}, {"def": "殁mò死。", "example": null}]','chinese-xinhua','0'),
('2101143296431624315','沫','1','mò','氵','8',NULL,'[{"def": "沫", "example": null}, {"def": "(形声。从水,末声。本义沫水)", "example": null}, {"def": "同本义", "example": null}, {"def": "沫,沫水也。出蜀西徼外东南入江。--《说文》", "example": null}, {"def": "古水名,即今四川省大渡河", "example": null}, {"def": "泡沫,沫子", "example": null}, {"def": "瀑下一曰沫也。--《说文》", "example": null}, {"def": "沫流赭。--《汉书·礼乐志》。注言汗流沫出也。”", "example": null}, {"def": "又如沫血(水面上的泡沫像血一样);沫雨(骤雨成潦,上浮泡沫);沫流(冒着泡沫的水流。指激流;流派)", "example": null}, {"def": "唾沫", "example": null}, {"def": "余干骨之沫为斯弥。--《庄子·主乐》。李注口中汁也。”", "example": null}, {"def": "沫", "example": null}, {"def": "通末”。竭,终止", "example": null}, {"def": "芳菲菲而难亏兮,芬至今犹未沫。--《楚辞·离骚》", "example": null}, {"def": "沫mò液体形成的细泡泡～。肥皂～。又指有泡沫样的泡～塑料。", "example": null}]','chinese-xinhua','0'),
('2101143296435818496','茉','1','mò','艹','8',NULL,'[{"def": "茉莉,茉莉花 (形声。从苃,末声。茉莉,植物名)", "example": null}, {"def": "茉mò", "example": null}, {"def": "①常绿灌木，夏季开白花，香味浓。供观赏。花可提取芳香油，也常用来熏制茶叶。", "example": null}, {"def": "②", "example": null}]','chinese-xinhua','0'),
('2101143296435818497','陌','1','mò','阝','8',NULL,'[{"def": "陌", "example": null}, {"def": "(形声。从阜,百声。阜,土山,与地形有关。本义田间小路)", "example": null}, {"def": "田间东西方向的小路。也泛指田间小路", "example": null}, {"def": "为田开阡陌封疆,而赋税平。--《史记·商君列传》", "example": null}, {"def": "阡陌交通,鸡犬相闻。--陶渊明《桃花源记》", "example": null}, {"def": "又如南陌(南方的田间小路);陌路(田间的小路);陌头(路旁)", "example": null}, {"def": "泛指道路", "example": null}, {"def": "素骥鸣广陌,慷慨送我行。--陶潜《咏荆轲》", "example": null}, {"def": "越陌度阡,枉用相存。--曹操《短歌行》", "example": null}, {"def": "又如陌头杨柳", "example": null}, {"def": "田野", "example": null}, {"def": "蹑足行伍之间,而倔起阡陌之中。--贾谊《过秦论》", "example": null}, {"def": "街道", "example": null}, {"def": "寻常巷陌,人道寄奴曾住", "example": null}, {"def": "陌mò", "example": null}, {"def": "⒈田间的小路，南北为\\"阡\\"，东西为\\"陌\\"。〈引〉路广～。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
