('2101143296435818530','牟','1','móu','牛','6',NULL,'[{"def": "牟", "example": null}, {"def": "(会意。小篆字形。从牛,从厶。厶象气从口出。本义牛叫声)", "example": null}, {"def": "同本义", "example": null}, {"def": "牟,牛鸣也。--《说文》", "example": null}, {"def": "牟然而鸣。--柳宗元《牛赋》", "example": null}, {"def": "又如野牛牟牟地叫", "example": null}, {"def": "力求得到;目的在于", "example": null}, {"def": "游居厚养,牟食之民也。--《韩非子》", "example": null}, {"def": "又如牟利", "example": null}, {"def": "通侔”。等同", "example": null}, {"def": "德牟往初,功无与二。--《汉书·司马相如传·封禅书》", "example": null}, {"def": "牟", "example": null}, {"def": "大麦", "example": null}, {"def": "贻(送)我来(小麦)牟。--《诗·周颂·思文》", "example": null}, {"def": "通眸”。瞳人", "example": null}, {"def": "尧、舜参牟子。--《荀子·非相》", "example": null}, {"def": "假借为眉”。眉毛,眉寿", "example": null}, {"def": "天与厥福,永享牟寿", "example": null}, {"def": "牟móu", "example": null}, {"def": "⒈取,求取～取暴利。", "example": null}, {"def": "⒉牛叫声。", "example": null}, {"def": "⒊通\\"侔\\"。相等，等同。", "example": null}, {"def": "牟mù", "example": null}, {"def": "⒈牟平县，在山东省。", "example": null}]','chinese-xinhua','0'),
('2101143296435818531','侔','1','móu','亻','8',NULL,'[{"def": "侔", "example": null}, {"def": "(形声。从人,牟声。本义等同;齐等;相等)", "example": null}, {"def": "同本义", "example": null}, {"def": "侔,齐等也。--《说文》", "example": null}, {"def": "侔也者,比辞而俱行也。--《墨子·小取》", "example": null}, {"def": "权之以眡其轻重之侔也。--《考工记·轮人》", "example": null}, {"def": "疏数必侔。--《考工记·弓人》", "example": null}, {"def": "畸于人而侔于天。--《庄子·大宗师》。司马注等也。”", "example": null}, {"def": "智侔则有数者禽无数。--《淮南子》", "example": null}, {"def": "又如侔尊(等尊,齐尊);侔德(德业相等);侔名(齐名;名望相等);侔迹(与他人的行为、业迹相等); 侔拟(拟,比)", "example": null}, {"def": "谋取;求", "example": null}, {"def": "静默以侔免。--《管子·宙合》。注取也。”", "example": null}, {"def": "又如侔利(谋取利益)", "example": null}, {"def": "侔móu", "example": null}, {"def": "⒈相等，等同众寡不～。", "example": null}, {"def": "⒉通\\"牟\\"。取，求取。", "example": null}]','chinese-xinhua','0'),
