('2101143296435818534','眸','1','móu','目','11',NULL,'[{"def": "眸", "example": null}, {"def": "(形声。从目,牟声。本义瞳人,眼珠)", "example": null}, {"def": "同本义", "example": null}, {"def": "眸,目童子也。--《说文新附》", "example": null}, {"def": "胸中正,则眸子瞭焉。--《孟子·离娄上》", "example": null}, {"def": "清之为明,杯水见眸子。--《淮南子·说山》", "example": null}, {"def": "回眸一笑百媚生。--白居易《长恨歌》", "example": null}, {"def": "又如眸子(瞳人。泛指眼睛);眸瞯(瞳人和眼白)", "example": null}, {"def": "眼睛。视觉器官", "example": null}, {"def": "眸", "example": null}, {"def": "低目谨视", "example": null}, {"def": "非目益明也,眸而见之也。--《荀子·大略》", "example": null}, {"def": "又如眸瞩(定睛注视)", "example": null}, {"def": "眸móu瞳人。泛指眼睛凝～。明～皓齿。", "example": null}]','chinese-xinhua','0'),
('2101143296435818535','谋','1','móu','讠','11',NULL,'[{"def": "谋", "example": null}, {"def": "(形声。从言,某声。本义考虑;谋划)", "example": null}, {"def": "同本义(侧重于商议出办法或盘算出主意)", "example": null}, {"def": "虑难曰谋。--《说文》", "example": null}, {"def": "聪作谋。--《书·洪范》", "example": null}, {"def": "咨难为谋。--《左传·襄公四年》", "example": null}, {"def": "谁适与谋。--《诗·小雅·苍伯》", "example": null}, {"def": "在事为诗,未发为谋。--《春秋·说题辞》", "example": null}, {"def": "心思为谋。--《论衡·超奇》", "example": null}, {"def": "谋及子孙,可谓死君乎。--《左传·僖公三十三年》", "example": null}, {"def": "未能远谋。--《左传·庄公十年》", "example": null}, {"def": "肉食者谋之。", "example": null}, {"def": "聚室而谋。--《列子·汤问》", "example": null}, {"def": "谋诸漆工。--明·刘基《郁离子·千里马篇》", "example": null}, {"def": "又如谋谟殚神(筹谋划策,竭尽全力);不谋而合;合谋(", "example": null}, {"def": "谋móu", "example": null}, {"def": "⒈计划，计策，主意～划。～略。计～。足智多～。", "example": null}, {"def": "⒉商议，商量不～而合。", "example": null}, {"def": "⒊设法寻求为人民～幸福。", "example": null}]','chinese-xinhua','0'),
('2101143296435818536','鍪','1','móu','金','17',NULL,'[{"def": "鍪", "example": null}, {"def": "古代炊器,青铜制,圆底敛口,反唇。流行于汉代", "example": null}, {"def": "鍪,釜也。--《广雅》", "example": null}, {"def": "古代武士戴的头盔", "example": null}, {"def": "鍪móu", "example": null}, {"def": "⒈〈古〉锅。", "example": null}, {"def": "⒉〈古〉武士的头盔。", "example": null}, {"def": "⒊像头盔的帽子。", "example": null}]','chinese-xinhua','0'),
