('2101143296435818553','睦','1','mù','目','13',NULL,'[{"def": "睦", "example": null}, {"def": "(形声。从目,坴声。本义和好,亲近)", "example": null}, {"def": "同本义", "example": null}, {"def": "睦,目顺也。--《说文》", "example": null}, {"def": "讲信修睦。--《礼记·礼运》。注皆训亲。”", "example": null}, {"def": "睦于父母之堂。--《礼记·坊记》", "example": null}, {"def": "则百姓亲睦。--《孟子》", "example": null}, {"def": "九族既睦。--《书·尧典》", "example": null}, {"def": "又如睦友(和睦友爱);睦睦(和睦,亲密);睦亲(对宗族和睦,对外亲友好);睦族(和睦亲族)", "example": null}, {"def": "调和", "example": null}, {"def": "通穆”", "example": null}, {"def": "睦,敬和也。--《说文》", "example": null}, {"def": "又如睦睦(恭敬的样子)", "example": null}, {"def": "睦", "example": null}, {"def": "古州名。睦州的简称", "example": null}, {"def": "隋置。故地在今湖北省", "example": null}, {"def": "睦mù和好，亲近和～。亲～。～邻。", "example": null}]','chinese-xinhua','0'),
('2101143296435818554','木','1','mù','木','4',NULL,'[{"def": "木", "example": null}, {"def": "(象形。甲骨文字形。象树木形。上为枝叶,下为树根。木”是汉字的一个部首。从木”的字表示树木或木器的名称。本义树木)", "example": null}, {"def": "同本义", "example": null}, {"def": "木,冒也。冒地而生。东方之行,从草,下象其根。--《说文》", "example": null}, {"def": "五行,木之为言触也。阳气动跃,触地而出也。--《白虎通》", "example": null}, {"def": "木者,春生之性。农之本也。--《春秋繁露》", "example": null}, {"def": "一树十获者木也。--《管子·权修》", "example": null}, {"def": "庄子行于山中,见大木,枝叶盛茂。--《庄子·山木》", "example": null}, {"def": "舜之居深山之中,与木石居,与鹿豕游。--《孟子·尽心上》", "example": null}, {"def": "草木之花。--宋·周敦颐《爱莲说》", "example": null}, {"def": "鸟兽木石。--明·魏学洢《核舟", "example": null}, {"def": "木mù", "example": null}, {"def": "⒈树栽植树～。封山育林，禁止伐～。", "example": null}, {"def": "⒉指木料，砍下的成材的树～头。～材。", "example": null}, {"def": "⒊用木料制成的～器家具。～牛流马。", "example": null}, {"def": "⒋质朴，朴实此人～实。", "example": null}, {"def": "⒌感觉不灵敏，失去知觉麻～。嘴唇发～。", "example": null}, {"def": "⒍棺材寿～。行将就～。", "example": null}, {"def": "⒎五行（金～水火土）之一。", "example": null}]','chinese-xinhua','0'),
('2101143296435818555','仫','1','mù','亻','5',NULL,'[{"def": "仫佬族", "example": null}, {"def": "仫mù", "example": null}]','chinese-xinhua','0'),
('2101143296435818556','目','1','mù','目','5',NULL,'[{"def": "目", "example": null}, {"def": "(象形。甲骨文和小篆字形。象眼睛形,外边轮廓象眼眶,里面象瞳孔。小篆处理为线条。先秦时期多用目”,两汉以后,用眼逐渐多起来。目”具有书面语色彩。本义眼睛)", "example": null}, {"def": "同本义", "example": null}, {"def": "目,人眼,象形。--《说文》", "example": null}, {"def": "目者,气之清明者也。--《礼记·郊特牲。》", "example": null}, {"def": "目者,心之符也。--《韩诗外传》", "example": null}, {"def": "夫妻反目。--《易·小畜卦》", "example": null}, {"def": "睅其目,皤其腹。--《左传·宣公二年》", "example": null}, {"def": "满目萧然。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "瞋目大怒。--晋·干宝《搜神记》", "example": null}, {"def": "目似瞑。--《聊斋志异·狼三则》", "example": null}, {"def": "目不忍睹。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "又如目", "example": null}, {"def": "目mù", "example": null}, {"def": "⒈眼睛～不暇接。有～共睹。", "example": null}, {"def": "⒉看众～睽睽。众～昭彰。", "example": null}, {"def": "⒊孔，网眼网～。纲举～张。", "example": null}, {"def": "⒋名称，标题～录。书～。题～。", "example": null}, {"def": "⒌条文，大项中再分的小项条～。大纲细～。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "①射击、攻击或寻找的对象对准～标。", "example": null}, {"def": "②想要达到的境地或标准奋斗的～标。", "example": null}, {"def": "⒑", "example": null}]','chinese-xinhua','0'),
('2101143296435818557','沐','1','mù','氵','7',NULL,'[{"def": "沐", "example": null}, {"def": "(形声。从水,木声。本义洗头发)", "example": null}, {"def": "同本义", "example": null}, {"def": "沐,濯发也。--《说文》", "example": null}, {"def": "予发曲局,薄言归沫。--《诗·小雅·采绿》", "example": null}, {"def": "共王之沐浴。--《周礼·宫人》", "example": null}, {"def": "沐则心覆。--《左传》", "example": null}, {"def": "诸侯皆有汤沐之邑也。--《公羊传·隐公八年》", "example": null}, {"def": "夫子助之沫椁。--《礼记·檀弓》", "example": null}, {"def": "且沐者,去首垢也,洗去足垢,盥去手垢,浴去身垢,皆去一形之垢,其实等也。--《论衡·讥日》", "example": null}, {"def": "新沐者必弹冠,新浴者必振衣。--《史记·屈原贾生列传》", "example": null}, {"def": "又如沐发(洗发);沐澡(洗头洗澡);沐濯(洗头洗澡);沐芳(用香草水洗头);沐巾(洗发用的巾);沐盆", "example": null}, {"def": "沐mù洗头发～雨栉风（旅途奔波辛苦勤劳）。泛指洗～浴（洗澡）。", "example": null}]','chinese-xinhua','0'),
