('2101143296440012820','纳','1','nà','纟','7',NULL,'[{"def": "纳", "example": null}, {"def": "(形声。从糸,内声。本义丝被水浸湿)", "example": null}, {"def": "同本义", "example": null}, {"def": "纳,丝湿纳纳也。--《说文》", "example": null}, {"def": "衣纳纳而掩露。--刘向《九叹·逢纷》", "example": null}, {"def": "又如纳纳(潮湿的样子)", "example": null}, {"def": "收藏;收入", "example": null}, {"def": "察纳雅言。--诸葛亮《出师表》", "example": null}, {"def": "又如采纳;容纳;藏垢纳污(包藏容纳污秽之物。比喻包容坏人坏事)", "example": null}, {"def": "纳”假借为接纳”;接受", "example": null}, {"def": "几以不纳死。--宋·文天祥《指南录·后序》", "example": null}, {"def": "遂开门纳众。--《资治通鉴·唐纪》", "example": null}, {"def": "诬守纳己赇。--明·高启《书博鸡者事》", "example": null}, {"def": "纳钱案上。--《聊斋志异·促织》", "example": null}, {"def": "又如纳质(接受质证;接受质询);纳采(", "example": null}, {"def": "纳nà", "example": null}, {"def": "⒈收进，接收～入。接～。吐故～新。", "example": null}, {"def": "⒉接受采～。", "example": null}, {"def": "⒊缴付～税。～公粮。", "example": null}, {"def": "⒋享受～凉。～福。", "example": null}, {"def": "⒌缝补～鞋底。补补～ ～。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
