('2101143296444207121','囊','1','nánɡ','口','22',NULL,'[{"def": "囊揣", "example": null}, {"def": "同囊膪”", "example": null}, {"def": "囊膪", "example": null}, {"def": "囊〈名〉", "example": null}, {"def": "(形声。大篆字形象两头扎起的口袋。本义有底的口袋)", "example": null}, {"def": "同本义", "example": null}, {"def": "囊,橐也。--《说文》", "example": null}, {"def": "括囊。--《易·坤》。疏所以贮物。”", "example": null}, {"def": "于橐于囊。--《诗·大雅·公刘》。传小曰橐,大曰囊。”", "example": null}, {"def": "所载不过囊衣。--《汉书·王吉传》。注有底曰囊,无底曰橐。”", "example": null}, {"def": "药囊提轲。--《战国策·燕策》", "example": null}, {"def": "先生如其指,内狼于囊。--马中锡《中山狼传》", "example": null}, {"def": "置书囊中。--唐·李朝威《柳毅传》", "example": null}, {"def": "锥", "example": null}, {"def": "囊nāng", "example": null}, {"def": "囊náng", "example": null}, {"def": "⒈口袋，盛物的袋子麻布～。探～取物。～空如洗。", "example": null}, {"def": "⒉像口袋的东西胆～。", "example": null}, {"def": "⒊用口袋盛物～米。～沙堵水。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
