('2101143296444207144','闹','1','nào','门','8',NULL,'[{"def": "闹", "example": null}, {"def": "(会意。从市,从閠(斗)。市场上的争吵、喧闹。本义嘈杂,喧扰)", "example": null}, {"def": "同本义", "example": null}, {"def": "鸣声相呼和,无理只取闹。--韩愈《食虾蟆》", "example": null}, {"def": "召闹取怒。--唐·柳宗元《答韦中立论师道书》", "example": null}, {"def": "渐不喜闹", "example": null}, {"def": "又如闹里(闹哄哄的场合中);人声吵闹;喧闹(喧哗吵闹);闹耳朵(形容嘈杂);闹吵(喧闹,大声争吵)", "example": null}, {"def": "热闹", "example": null}, {"def": "门巷不教当闹市,诗篇转觉足工夫。--张籍《奇元员外》", "example": null}, {"def": "又如闹篮(热闹多事的场合);闹杂(热闹嘈杂);闹热(热闹);闹猛(方言。繁忙热闹);闹洋洋(热闹得很);闹盈盈(热热闹闹);闹闹和和(热闹和睦)", "example": null}, {"def": "浓盛", "example": null}, {"def": "闹（?", "example": null}, {"def": "⒈人多声音杂乱～市。热～。", "example": null}, {"def": "⒉吵，喧哗，搅扰～翻了。～得可欢。无理取～。", "example": null}, {"def": "⒊戏耍，玩笑～着玩的。", "example": null}, {"def": "⒋发生～水灾。", "example": null}, {"def": "⒌发作～情绪。", "example": null}, {"def": "⒍干，搞，弄～春耕。～革新。～清情况。", "example": null}]','chinese-xinhua','0'),
('2101143296444207145','淖','1','nào','氵','11',NULL,'[{"def": "淖〈名〉", "example": null}, {"def": "(形声。从水,卓声。本义泥沼;深泥,烂泥)", "example": null}, {"def": "同本义", "example": null}, {"def": "淖,泥也。--《说文》", "example": null}, {"def": "天雨淖。--《汉书·韦元成传》", "example": null}, {"def": "世沉淖而难论兮。--《楚辞·怨世》", "example": null}, {"def": "和泥曰淖。--《通俗文》", "example": null}, {"def": "有淖于前,乃皆左右相违于淖。--《左传·成公十六年》", "example": null}, {"def": "濯淖污泥之中。--《资治通鉴·汉纪》", "example": null}, {"def": "又如淖泞(泥烂滑溜);淖湴(淤泥);淖污(泥水混浊);淖田(烂泥田);淖潦(烂泥积水)", "example": null}, {"def": "流体", "example": null}, {"def": "漆淖水淖,合两淖则为蹇。--《吕氏春秋》", "example": null}, {"def": "姓", "example": null}, {"def": "淖 〈形〉", "example": null}, {"def": "湿润", "example": null}, {"def": "淖乎如在于海。--《管子·内业》。", "example": null}, {"def": "淖,湿也。--《广雅》", "example": null}, {"def": "又如淖泽(湿润)", "example": null}, {"def": "淖nào", "example": null}, {"def": "⒈泥沼，烂泥泥～。", "example": null}, {"def": "⒉柔，柔和～弱。", "example": null}, {"def": "⒊", "example": null}, {"def": "淖zhào 1.中和，调和。", "example": null}, {"def": "淖zhuō 1.姓。战国楚有淖齿。见《韩非子．内储说上》。", "example": null}, {"def": "淖chuò 1.宽。 2.见\\"淖约\\"﹑\\"淖弱\\"﹑\\"淖溺\\"。", "example": null}]','chinese-xinhua','0'),
