('2101143296469372931','伲','1','nì','亻','7',NULL,'[{"def": "伲", "example": null}, {"def": "同你”", "example": null}, {"def": "伲,汝也。或作你。--《集韵》", "example": null}, {"def": "伲〈代〉", "example": null}, {"def": "我的;我们的", "example": null}, {"def": "伲nì", "example": null}, {"def": "①方言。我;我们。", "example": null}, {"def": "②方言。我的;我们的。", "example": null}]','chinese-xinhua','0'),
('2101143296469372932','你','1','nǐ','亻','7',NULL,'[{"def": "你", "example": null}, {"def": "(形声。从人,尔声。本义称说话的对方)", "example": null}, {"def": "同本义", "example": null}, {"def": "武平元年童谣曰狐截尾,你欲除我我除你。”--《隋书·五行志上》", "example": null}, {"def": "又如你咱(你);你懑(你们);你娘(骂人的话,相当于你娘的”);你老(对尊长的敬称);你那(你老人家);你伫(您);你等(你们)", "example": null}, {"def": "不明确指明的集团中的某一个体;任何一个;一般的一个", "example": null}, {"def": "泛指任何一个人;无论什么人;无论哪一个人", "example": null}, {"def": "每人;人人", "example": null}, {"def": "你好", "example": null}, {"def": "你nǐ称谈话的对方～好。", "example": null}]','chinese-xinhua','0'),
('2101143296469372933','拟','1','nǐ','扌','7',NULL,'[{"def": "拟", "example": null}, {"def": "(形声。从手,以声。本义揣度,猜测)", "example": null}, {"def": "同本义", "example": null}, {"def": "拟,度也。--《说文》", "example": null}, {"def": "行止而拟度焉。--《周礼·射人》注", "example": null}, {"def": "拟之而后言,议之而后动。--《易·系辞上》", "example": null}, {"def": "先生说的可单是拟题?--《儒林外史》", "example": null}, {"def": "又如悬拟(凭空虚构);拟足(揣度脚步);拟度(揣度;推测);拟迹(揣度足迹);拟题(应试举子揣度命题)", "example": null}, {"def": "类似;比拟", "example": null}, {"def": "复举剑拟之。--《汉书·李广苏建传》", "example": null}, {"def": "客以剑拟王,王头随堕汤中。(拟比划,作砍的样子。拟”后有于”省略。客用剑向楚王一比划,楚王的人头就落到开水里。--晋·干宝《搜神记》)", "example": null}, {"def": "拟（攎）nǐ", "example": null}, {"def": "⒈准备，打算～办。～往广州。", "example": null}, {"def": "⒉起草，初步设想～稿。～订。草～计划。", "example": null}, {"def": "⒊模仿，仿照模～。～制。", "example": null}, {"def": "⒋比，比划，用兵器作杀人的样子比～。举剑～之。", "example": null}]','chinese-xinhua','0'),
