('2101143296469372957','捻','1','niǎn','扌','11',NULL,'[{"def": "捻〈动〉", "example": null}, {"def": "(形声。从手,念声。本义用手指搓转)", "example": null}, {"def": "同本义", "example": null}, {"def": "轻拢慢捻抹复挑。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如捻就(揉缩);捻髯(用手指搓着腮上的胡须);捻断髭须(比喻费尽心思);捻绳;捻灯芯;将两股纱捻成一根线", "example": null}, {"def": "领导", "example": null}, {"def": "驱梨园领袖,总编修师首,捻杂剧班头。--贾仲明《凌波仙》", "example": null}, {"def": "驱逐;追赶", "example": null}, {"def": "聚;聚合成股。因称成群的人为捻。亦为清代中叶后反政府农民武装捻子或捻军的简称", "example": null}, {"def": "用同捞”", "example": null}, {"def": "捻（撚）niǎn", "example": null}, {"def": "⒈用手指搓转～线。～麻绳。", "example": null}, {"def": "⒉用纸、线、布条等搓成的条状物纸～子。药～儿。", "example": null}, {"def": "捻niē 1.捏，揉塑。 2.握持;取。 3.堵塞。 4.按。乐器演奏手法。 5.用同\\"蹑\\"。参见\\"捻脚捻手\\"。 6.量词。犹把。一捻，形容细或少。", "example": null}]','chinese-xinhua','0'),
('2101143296469372958','辇','1','niǎn','车','12',NULL,'[{"def": "辇", "example": null}, {"def": "(会意。从车,两夫”(男子)并行,拉车前进。本义古时用人拉或推的车)", "example": null}, {"def": "同本义", "example": null}, {"def": "輦,挽车也。--《说文》", "example": null}, {"def": "与其輂辇。--《周礼·乡师》。注人挽行。”", "example": null}, {"def": "我任我辇。--《诗·小雅·黍苗》", "example": null}, {"def": "以乘车辇其母。--《左传·庄公十二年》", "example": null}, {"def": "辇重如役。--《左传·襄公十年》", "example": null}, {"def": "恃辇而行。--《战国策·赵策》", "example": null}, {"def": "扶辇下除。--《汉书·李广苏建传》", "example": null}, {"def": "又如辇车(古代用人挽拉的辎重车;古代宫中用的一种便车,多用人挽拉);辇舆(用人拉车;人抬的车,即后世轿子);辇夫(车夫);辇道(车道)", "example": null}, {"def": "秦汉后特指君后所乘的车", "example": null}, {"def": "辇niǎn", "example": null}, {"def": "⒈用人力推拉着走的车子。秦汉以后专指帝王的车子。", "example": null}, {"def": "⒉乘坐～舆就马（舆车子）。", "example": null}]','chinese-xinhua','0'),
('2101143296469372959','撵','1','niǎn','扌','15',NULL,'[{"def": "撵", "example": null}, {"def": "(形声。从手,辇声。本义驱逐)", "example": null}, {"def": "同本义", "example": null}, {"def": "你趁早与我出去,我不着丫头撵你。--《金瓶梅》", "example": null}, {"def": "又如撵山(闯山,在山上转);撵逐(驱逐);撵他下台;撵蹿(赶走);把孩子撵回屋;把猪撵进圈;你不好好干活,老板会撵你;把人撵走", "example": null}, {"def": "催", "example": null}, {"def": "贾母亦知因贾政一人在所致,酒过三巡,便撵贾政去歇息。--《红楼梦》", "example": null}, {"def": "c出", "example": null}, {"def": "因不付租金被撵出", "example": null}, {"def": "好像要把她撵出屋子似的", "example": null}, {"def": "如果你不能自爱,我就要把", "example": null}, {"def": "撵niǎn", "example": null}, {"def": "⒈驱逐，赶走～出去。～走他。", "example": null}, {"def": "⒉追赶快，～上。", "example": null}]','chinese-xinhua','0'),
('2101143296469372960','碾','1','niǎn','石','15',NULL,'[{"def": "碾〈动〉", "example": null}, {"def": "(形声。从石,展声。本义磙压;碾轧)", "example": null}, {"def": "同本义", "example": null}, {"def": "碾,所以轹物器也。--《集韵》", "example": null}, {"def": "又如碾米;碾轧(磙压);碾械(木制者称檑木”,石制者称礌石”。战时从高处推下打击敌人)", "example": null}, {"def": "碾磨", "example": null}, {"def": "小娥旋拂碾新茶。--司空图《暮春对柳》", "example": null}, {"def": "又如碾转(一种食品。制作时,先将还未完全成熟的麦穗煮熟,然后搓下麦粒,再用磨推成面条状);碾米;碾谷;碾场。又指车磨玉石。如碾玉匠;碾玉作(打磨雕琢玉器的作坊)", "example": null}, {"def": "撵;赶", "example": null}, {"def": "碾 〈名〉", "example": null}, {"def": "用于使谷物等破碎、去皮或使场地、道路等变平的工具", "example": null}, {"def": "遂教民为碾。--《魏", "example": null}, {"def": "碾niǎn", "example": null}, {"def": "⒈轧碎或压平东西的器具石～子。", "example": null}, {"def": "⒉轧，压～米。～药。", "example": null}]','chinese-xinhua','0'),
