('2101143296469372987','涅','1','niè','氵','10',NULL,'[{"def": "涅", "example": null}, {"def": "(形声。从水,从土,曰声。本义可做黑色染料的矾石)", "example": null}, {"def": "同本义", "example": null}, {"def": "涅,黑土在水中者也。--《说文》", "example": null}, {"def": "女床之山,其阴多石涅。--《西山经》", "example": null}, {"def": "今以涅染缁,则黑于涅。--《淮南子·俶真》", "example": null}, {"def": "又如涅石(黑矾石,可为染料)", "example": null}, {"def": "黑泥", "example": null}, {"def": "蓬生麻中,不扶而直,白沙在涅,与之俱黑。--《荀子》", "example": null}, {"def": "古代河流名", "example": null}, {"def": "涅 〈动〉", "example": null}, {"def": "染黑", "example": null}, {"def": "涅而不缁。--《论语·阳货》", "example": null}, {"def": "又如涅齿(染黑牙齿);涅污(染污)", "example": null}, {"def": "纹身", "example": null}, {"def": "是主家私自黥涅。--范成大《清远店诗·序》", "example": null}, {"def": "又如涅墨(在人身", "example": null}, {"def": "涅niè", "example": null}, {"def": "⒈一种矿物，〈古〉用作黑色染料～石。", "example": null}, {"def": "⒉用黑色染，染黑～其面。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296469372988','聂','1','niè','耳','10',NULL,'[{"def": "聂", "example": null}, {"def": "(会意。从三耳。本义附耳小语)", "example": null}, {"def": "同本义", "example": null}, {"def": "聂,附耳私小语也。--《说文》", "example": null}, {"def": "乃效女儿咕嗫私语。--《史记·魏其武安侯列传》", "example": null}, {"def": "又如聂许(附耳私语);聂聂(轻小,轻虚平和的样子)", "example": null}, {"def": "假借为摄”。握持", "example": null}, {"def": "为人两手聂其耳。--《山海经·海外北经·聂耳国》", "example": null}, {"def": "聂", "example": null}, {"def": "古代地名", "example": null}, {"def": "姓", "example": null}, {"def": "聂政之刺韩傀也,白虹贯日。--《战国策·魏策》", "example": null}, {"def": "聂（聶）niè姓。", "example": null}, {"def": "聂zhé 1.切成薄片的肉。", "example": null}, {"def": "聂shè 1.\\"摄\\"的古字。握持。 2.惧怕。", "example": null}]','chinese-xinhua','0'),
('2101143296469372989','臬','1','niè','自','10',NULL,'[{"def": "臬", "example": null}, {"def": "箭靶", "example": null}, {"def": "臬,射准的也。--《说文》", "example": null}, {"def": ";引申为目标;准则", "example": null}, {"def": "所发无臬。--张衡《东京赋》", "example": null}, {"def": "又如臬极(准则;标准)", "example": null}, {"def": "古代测日影的标杆", "example": null}, {"def": "陈圭置臬,瞻星揆地。--《石阙铭·序》", "example": null}, {"def": "刑法;法度", "example": null}, {"def": "王曰外事,汝陈时臬,司师兹殷罚有伦。”--《书·康诰》", "example": null}, {"def": "古代主管一省司法的官员", "example": null}, {"def": "访);臬使(即按察使);臬府(即臬司。指肃政廉访使);臬宪(旧时对按察使的敬称)", "example": null}, {"def": "终极", "example": null}, {"def": "臬niè", "example": null}, {"def": "⒈箭靶子。", "example": null}, {"def": "⒉〈古〉用于测日影的标竿。", "example": null}, {"def": "⒊法度，标准。", "example": null}, {"def": "⒋极限。", "example": null}]','chinese-xinhua','0'),
('2101143296469372990','啮','1','niè','口','11',NULL,'[{"def": "啮", "example": null}, {"def": "(会意。从口,从齿。表示咬。本字从齿,本义用嘴咬)", "example": null}, {"def": "同本义", "example": null}, {"def": "囓,噬也。--《说文》。字亦作啮。鸟曰啄,兽曰囓。", "example": null}, {"def": "武卧啮雪。--《汉书·李广苏建传》", "example": null}, {"def": "众蛇竞来,啮索且断。--《后汉书·费长房传》", "example": null}, {"def": "勚感涕,因啮指流血。--《新唐书·李勚传》", "example": null}, {"def": "以啮人,无御之者。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "又如啮指(咬指头。形容极为痛心);啮咬(啃咬。比喻折磨);啮啃(啃咬);啮齿(咬牙切齿);啮噬(咬嚼);啮心(比喻痛苦至极);啮雪吞毡(比喻为坚持气节而过艰苦的生活);啮臂", "example": null}, {"def": "(咬臂出血;以示诚信和坚决)", "example": null}, {"def": "侵蚀", "example": null}, {"def": "水皆啮石出。--明·", "example": null}, {"def": "啮（齧、囓）niè", "example": null}, {"def": "⒈咬鼠～。", "example": null}, {"def": "⒉缺口剑之折，必有～。", "example": null}]','chinese-xinhua','0'),
