('2101143296481955867','挪','1','nuó','扌','9',NULL,'[{"def": "挪", "example": null}, {"def": "(形声。从手,那声。本义揉搓)", "example": null}, {"def": "同本义", "example": null}, {"def": "两手自相挪。--韩愈《读东方朔杂事》", "example": null}, {"def": "移动,从一处移到另一处", "example": null}, {"def": "行者叩头,启上如来千万望挪玉一降。”--《西游记》", "example": null}, {"def": "又如挪玉(移动玉步;劳动大驾);挪桌子;那个理发店挪地方了;把椅子挪开;挪步(移动脚步)", "example": null}, {"def": "移用", "example": null}, {"def": "他向日挪我的五十两银子,得便叫他算还给我。--《儒林外史》", "example": null}, {"def": "挪nuó移动～动。不能～用公款。", "example": null}]','chinese-xinhua','0'),
('2101143296481955868','傩','1','nuó','亻','12',NULL,'[{"def": "傩", "example": null}, {"def": "(形声。从人,难声。本义步行有节度)", "example": null}, {"def": "同本义", "example": null}, {"def": "巧笑之傩,佩玉之傩。--《诗·卫风·竹竿》", "example": null}, {"def": "指古迎神赛会", "example": null}, {"def": "乡人傩,朝服而立于阼阶。(阼古指东面的台阶。)--《论语·乡党》", "example": null}, {"def": "又如傩祓(驱除疫鬼,祓除灾邪);傩逐(驱除疫鬼仪式中所唱的歌);傩鼓(驱除疫鬼仪式中敲击的鼓声)", "example": null}, {"def": "傩神", "example": null}, {"def": "傩戏", "example": null}, {"def": "傩（儺）nuó〈古〉驱逐所谓\\"疫鬼\\"的一种迷信仪式活动。", "example": null}]','chinese-xinhua','0'),
