('2101143296481955895','呕','1','ǒu','口','7',NULL,'[{"def": "呕", "example": null}, {"def": "(形声。从口,区声。本义东西在胃喉中上涌,从口中出来)", "example": null}, {"def": "同本义", "example": null}, {"def": "欧,吐也。--《说文》。字亦作呕。", "example": null}, {"def": "吾伏噄呕血。--《左传·哀公二年》", "example": null}, {"def": "其音如呕。--《山海经·东山经》", "example": null}, {"def": "有女子方跪,据树而呕丝北海外也。--《博物志·异人》", "example": null}, {"def": "老夫情怀恶,呕泄卧数日。--唐·杜甫《北征》", "example": null}, {"def": "又如呕逆(恶心想吐);呕泄(吐泻);呕家(平素患有恶心、呕吐的病人)", "example": null}, {"def": "古通讴”。唱歌", "example": null}, {"def": "其妻亦负戴相随,数止买臣毋歌呕道中。--《汉书·朱买臣传》", "example": null}, {"def": "如呕吟(歌吟);呕唱(唱歌)", "example": null}, {"def": "逗弄;故意惹人生怒", "example": null}, {"def": "呕（噄）ǒu吐～吐。～血。", "example": null}, {"def": "呕ōu 1.象声词。参见\\"呕轧\\"﹑\\"呕哑\\"。 2.通\\"讴\\"。歌唱。 3.叹词。表示招呼﹑应答﹑提醒等。 4.语气助词。", "example": null}, {"def": "呕òu 1.使人生气。 2.多用于故意逗引人生气。 3.呕气，生闷气。", "example": null}, {"def": "呕xū 1.和悦貌。参见\\"呕呕\\"﹑\\"呕喻\\"。 2.通\\"煦\\"。抚育。", "example": null}]','chinese-xinhua','0'),
('2101143296481955896','偶','1','ǒu','亻','11',NULL,'[{"def": "偶〈名〉", "example": null}, {"def": "(形声。从人,禺声。本义仿人形制成的木偶)", "example": null}, {"def": "同本义", "example": null}, {"def": "偶,相人也。--《说文》。按,相人者,像人也。一名俑。", "example": null}, {"def": "鲁以偶人,而孔子叹。--《淮南子·缪称》", "example": null}, {"def": "见偶人与偶人相与语。--《史记·孟尝君列传》", "example": null}, {"def": "又如头偶;偶戏(木偶戏)", "example": null}, {"def": "伙伴;同伴;与人共处", "example": null}, {"def": "乃率其曹偶,亡之江中。--《史记·黥布列传》", "example": null}, {"def": "又如偶行(结伴同行);偶攻(结伙攻击);偶耕(两人并耕);偶影(与影为偶,形容孤独);偶寝(同睡)", "example": null}, {"def": "对偶", "example": null}, {"def": "偶ǒu", "example": null}, {"def": "⒈木头或泥土等制成的人像木～。～像。", "example": null}, {"def": "⒉双，成对，跟\\"奇\\"相对～数。无独有～。", "example": null}, {"def": "⒊婚配配～。佳～。", "example": null}, {"def": "⒋碰巧，不经常，不是必然的～然。～尔。～遇。", "example": null}, {"def": "偶yù 1.寄;寄托。", "example": null}]','chinese-xinhua','0'),
('2101143296481955897','耦','1','ǒu','耒','15',NULL,'[{"def": "耦〈动〉", "example": null}, {"def": "(形声。从耒,禺声。耒,翻土工具。本义二人并肩耕地)", "example": null}, {"def": "同本义", "example": null}, {"def": "耦,耒广五寸为伐,二伐为耦。--《说文》", "example": null}, {"def": "十千维耦。--《诗·周颂·噫嘻》", "example": null}, {"def": "譬如农夫作耦。--《国语·吴语》", "example": null}, {"def": "禹见耕者耦立而式。--《荀子·大略》", "example": null}, {"def": "长沮、桀溺耦而耕。--《论语·微子》", "example": null}, {"def": "又如耦耕(两人并力一起耕种。为古代犁田的一种方式);耦犁(一种耕作法)。引申为二人一组。如耦俱无猜(双方都无猜疑);耦居(谓两人同处);耦俱(指相处融洽)", "example": null}, {"def": "匹敌;相对", "example": null}, {"def": "遇,逢", "example": null}, {"def": "耦ǒu", "example": null}, {"def": "⒈两人在一起耕地。", "example": null}, {"def": "⒉同\\"偶\\"。双，对。也指配偶。", "example": null}]','chinese-xinhua','0'),
('2101143296481955898','蕅','1','ǒu','','11',NULL,'[{"def": "蕅ǒu同\\"藕\\"。", "example": null}, {"def": "【蕅益】（1599-1655）明朝僧人、学者。本姓钟，名智旭，字以行，苏州吴县（今属江苏）木渎人。初学儒家，曾作《辟佛论》。十七岁读高僧莲池著作信佛。二十四岁出家", "example": null}, {"def": "。初撞徽九华山，晚年移居浙江孝丰灵峰寺。遍阅律藏，尤专天台教义。主张佛教诸宗融合，释、道、儒三教一致。与憨山、紫柏、莲池并称明代四大高僧。著有《毗尼事义", "example": null}, {"def": "要集》、《楞严玄义》、《楞严文句》、《阅藏知津》等。", "example": null}]','chinese-xinhua','0'),
('2101143296481955899','藕','1','ǒu','艹','18',NULL,'[{"def": "藕〈名〉", "example": null}, {"def": "莲的地下茎,肥大有节,中间有管状小孔,可以吃,也可作中药", "example": null}, {"def": "莲实与藕。--明·李渔《闲情偶寄·种植部》", "example": null}, {"def": "又如藕心(古代钱币名称,汉时所铸,四方而有孔,形似破藕);藕灰(藕色);藕合(藕荷);藕荷(浅紫而略带红的颜色);藕色(浅灰而略带红的颜色);藕花(即荷花)", "example": null}, {"def": "藕ǒu", "example": null}, {"def": "⒈莲的地下茎，肥大而长，有节，中间有数个管状小孔，折断后有丝。生或熟食均可。还可制藕粉等食品。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296481955900','澫','1','ǒu','','13',NULL,'[{"def": "澫màn 1.见\\"澫澫\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296481955901','櫙','1','ōu','','8',NULL,'[{"def": "櫙ōu 1.即刺榆。 2.树木枯萎而死。", "example": null}]','chinese-xinhua','0'),
('2101143296481955902','鏂','1','ōu','','8',NULL,'[{"def": "鏂ōu 1.古代容量单位。 2.盛酒器。似簋形。长沙汤家岭出土有西汉鏂，铭文有﹕\\"张端君酒鏂一。\\" 3.浮沤钉。作为装饰物的门上所钉凸形大钉。", "example": null}]','chinese-xinhua','0'),
('2101143296481955903','沤','1','ōu','氵','7',NULL,'[{"def": "沤", "example": null}, {"def": "长时间地浸泡", "example": null}, {"def": "沤,久渍也。--《说文》", "example": null}, {"def": "东门之池,可以沤麻。--《诗·陈风·东门之池》", "example": null}, {"def": "又如沤麻池(沤麻的水池);沤纻(亦作沤苎”。沤麻);沤罨(长时间地浸泡并覆以泥,使之腐烂);沤营(水浸茅草使柔韧)", "example": null}, {"def": "壅埋堆积", "example": null}, {"def": "用润肤的香蜜涂抹皮肤。香蜜即称沤子”", "example": null}, {"def": "沤", "example": null}, {"def": "水中浮泡", "example": null}, {"def": "沤（漚）òu长时间浸泡～麻。～肥料。", "example": null}, {"def": "沤（漚）ōu水炮浮～。", "example": null}]','chinese-xinhua','0'),
('2101143296481955904','熰','1','ōu','','8',NULL,'[{"def": "熰ōu 1.极热。 2.燃而不甚炽烈。", "example": null}]','chinese-xinhua','0'),
('2101143296481955905','讴','1','ōu','讠','6',NULL,'[{"def": "讴", "example": null}, {"def": "(形声。从言,区声。本义无伴奏;齐声歌唱)", "example": null}, {"def": "同本义", "example": null}, {"def": "讴,齐歌也。--《说文》", "example": null}, {"def": "齐讴楚声。--曹植诗", "example": null}, {"def": "皆讴歌思东归。--《楚辞·大招》", "example": null}, {"def": "筑者讴曰泽门之皙,实兴我役。”--《左传·襄公十七年》", "example": null}, {"def": "薛谭学讴于秦青。--《列子·汤问》", "example": null}, {"def": "昔日王豹处于淇,而河西善讴--《孟子·告子下》", "example": null}, {"def": "故近者歌讴而乐之。--《荀子·议兵》", "example": null}, {"def": "又如讴者(讴歌的人);讴咏(讴歌吟咏);讴诵(歌讼);讴谣(唱歌)區", "example": null}, {"def": "歌颂;赞颂", "example": null}, {"def": "民讴思之。--《苗防备览·李瑜》", "example": null}, {"def": "讴", "example": null}, {"def": "歌曲", "example": null}, {"def": "京洛出名讴", "example": null}, {"def": "讴（謳）ōu", "example": null}, {"def": "⒈唱歌歌～。", "example": null}, {"def": "⒉歌曲名～。", "example": null}]','chinese-xinhua','0'),
('2101143296481955906','欧','1','ōu','欠','8',NULL,'[{"def": "欧", "example": null}, {"def": "通讴”。歌唱", "example": null}, {"def": "百姓欧歌。--《隶释·三公山碑》", "example": null}, {"def": "又如欧歌(讴歌,歌颂)", "example": null}, {"def": "同驱”", "example": null}, {"def": "或导之以德教,或欧之以法令。。--《大戴礼·礼察》", "example": null}, {"def": "驱使;疾行", "example": null}, {"def": "通殴”。殴打", "example": null}, {"def": "(老父)顾谓良曰孺子下取履!良鄂然,欲欧之。--《汉书·张良传》", "example": null}, {"def": "欧", "example": null}, {"def": "通区”", "example": null}, {"def": "通瓯”。种族名", "example": null}, {"def": "欧罗巴洲的简称", "example": null}, {"def": "欧姆的简称", "example": null}, {"def": "欧（歸）ōu〈外〉欧洲，全称\\"欧罗巴洲\\"。世界七大洲之一，东与亚洲相连。", "example": null}, {"def": "欧ǒu 1.\\"呕\\"的古字。呕吐。 2.指呕吐声。 3.通\\"殴\\"。捶击。", "example": null}]','chinese-xinhua','0'),
('2101143296481955907','殴','1','ōu','殳','8',NULL,'[{"def": "殴", "example": null}, {"def": "(形声。从殳,区声。殳,古代兵器,用以撞击。本义打击,捶击)", "example": null}, {"def": "同本义", "example": null}, {"def": "殴,捶击物也。--《说文》", "example": null}, {"def": "后数复殴伤郎。--《汉书·梁王襄传》", "example": null}, {"def": "或至相殴。--清·纪昀《阅微草堂笔记》", "example": null}, {"def": "又如殴曳(殴打拖曳);殴仗(以仗殴打);殴逐(殴打追逐);殴伤(殴斗致伤,打伤);殴击(殴打);殴骂(打骂);殴挞(殴打,鞭挞)", "example": null}, {"def": "同怄”。气恼", "example": null}, {"def": "杨志骂道这畜生不殴死俺,只是打便了。”--《水浒传》", "example": null}, {"def": "假借为驱”。驱赶", "example": null}, {"def": "以弓矢殴乌鸢。--《唐石经《周礼·夏官·射乌氏》", "example": null}, {"def": "殴除群厉。--", "example": null}, {"def": "殴（毆）ōu打人～打。～伤。斗～。", "example": null}, {"def": "殴kōu 1.见\\"殴蛇\\"。", "example": null}, {"def": "殴qū 1.驱赶;驱使。", "example": null}, {"def": "殴ǒu 1.呕，呕吐。参见\\"殴血\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296481955908','瓯','1','ōu','瓦','8',NULL,'[{"def": "瓯", "example": null}, {"def": "(形声。从瓦,区声。本义盆盂类瓦器)", "example": null}, {"def": "同本义", "example": null}, {"def": "瓯,小盆也。--《说文》", "example": null}, {"def": "流丸止于瓯臾。--《荀子·大略》", "example": null}, {"def": "我国家犹若金瓯,无一伤缺。--《南史·朱异传》", "example": null}, {"def": "又如瓯杓(瓦盆和木瓢)", "example": null}, {"def": "杯;盅", "example": null}, {"def": "超宗既坐,饮酒数瓯。--《南齐书·谢超宗传》", "example": null}, {"def": "又如茶瓯;酒瓯;瓯臾(瓯与臾。比喻地面凹陷不平之处);瓯窭(狭小的高地);瓯抠(凹凸不平。形容相貌奇异)", "example": null}, {"def": "古代地名", "example": null}, {"def": "古水名,即永宁江,今称瓯江", "example": null}, {"def": "瓯（畉）ōu", "example": null}, {"def": "⒈小盆。", "example": null}, {"def": "⒉杯子茶～。", "example": null}, {"def": "⒊瓯江，在浙江省。", "example": null}, {"def": "瓯ǒu 1.古代部落名。", "example": null}]','chinese-xinhua','0'),
('2101143296481955909','鸥','1','ōu','鸟','9',NULL,'[{"def": "鸥", "example": null}, {"def": "(形声。从鸟,区声。《说文》水鸮也。”本义水鸮)", "example": null}, {"def": "水鸟名", "example": null}, {"def": "惊起一滩鸥鹭。--宋·李清照《如梦令》", "example": null}, {"def": "鸥鹭灭没。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "鸥科(laridae)。此类鸟善飞,能游水,常随潮而翔,有海鸥、银鸥、燕鸥等种类。为长翼蹼足水鸟,形体较大,身体较粗壮,喙较厚,喙端略呈弯钩状,通常呆在岸边或内陆水域附近", "example": null}, {"def": ",是港口重要的食腐动物 。如鸥汀(群鸥栖息的沙洲);鸥没(鸥鸟没入水中);鸥眠(鸥鸟息眠);鸥鹭忘机(指人无机心,鸥鸟也能和其相亲近);鸥水相依(比喻离不开赖以生存的环", "example": null}, {"def": "境);鸥闲(鸥鸟悠闲自在)", "example": null}, {"def": "鸥（鷗）ōu鸟名。常见的有海～、银～、燕～等，均已少见，要保护，禁止猎杀。羽毛多为白色或灰色，生活在湖边、海边，捕食鱼、螺等。", "example": null}]','chinese-xinhua','0'),
('2101143296481955910','塸','1','ōu','','8',NULL,'[{"def": "塸ōu 1.坟墓。 2.同\\"瓯\\"。 3.一块田地按一定距离分成的若干部分，每部分长宽深有定。 4.犹躯。用于塑像。 5.犹间﹑所。用于房屋﹑住宅。", "example": null}]','chinese-xinhua','0'),
('2101143296481955911','杷','1','pá','木','8',NULL,'[{"def": "杷", "example": null}, {"def": "碎土、平地的农具", "example": null}, {"def": "杷pá", "example": null}, {"def": "杷bà 1.耙。碎土﹑平地的农具。用牛等牵引。 2.用杷碎土﹑平地。", "example": null}]','chinese-xinhua','0'),
('2101143296481955912','爬','1','pá','爪','8',NULL,'[{"def": "爬〈动〉", "example": null}, {"def": "(形声。从爪,巴声。爪,手爪。本义搔,爬梳)", "example": null}, {"def": "同本义", "example": null}, {"def": "爬,搔也。--《广韵》", "example": null}, {"def": "怯烦类决痈,惬兴剧爬疥。--韩愈等《雨中寄孟刑部几道联句》", "example": null}, {"def": "支分闲事了,爬背向阳眠。--白居易《自咏老身示诸家属》", "example": null}, {"def": "又如爬挲(爬搔,摩挲);爬栉(梳理,整理。同爬梳);爬耳搔腮(急切无奈貌);爬拉(频频拨饭菜入口)", "example": null}, {"def": "爬行,匍匐。躯体贴地(如虫、蛇、龟)缓慢向前行", "example": null}, {"def": "爬沙脚手钝,谁使女解缘青冥。--韩愈《月蚀诗效玉川子作》", "example": null}, {"def": "又如爬蹉(来回爬动);爬沙(缓慢地爬动);爬坑缸弗上(屎尿失控,来不及上厕所;离死不远);爬滩弗动(趴在地", "example": null}, {"def": "爬pá", "example": null}, {"def": "⒈上下肢伏地行走，虫类、爬行动物等的行走～着走。不吃苍蝇～过的食物。龟在慢慢地～。", "example": null}, {"def": "⒉攀登～树。～山坡。～上屋顶。", "example": null}, {"def": "爬bà 1.一种带齿的农具，用以碎土平地。 2.指用耙碎土﹑平地。", "example": null}]','chinese-xinhua','0'),
('2101143296481955913','耙','1','pá','耒','10',NULL,'[{"def": "耙", "example": null}, {"def": "用于碎土、平地和消灭杂草的整地农具", "example": null}, {"def": "耙", "example": null}, {"def": "用耙碎土平地", "example": null}, {"def": "耙地", "example": null}, {"def": "耙路机", "example": null}, {"def": "耙 bà", "example": null}, {"def": "①用以碎土和整地的农具。有钉齿和圆盘耙等。", "example": null}, {"def": "②用耙弄碎土块这块地还没～。又见pá。", "example": null}, {"def": "耙pá", "example": null}, {"def": "⒈", "example": null}]','chinese-xinhua','0'),
('2101143296481955914','琶','1','pá','王','12',NULL,'[{"def": "琶(形声。《说文新附》琵琶也。”)--见琵琶”", "example": null}, {"def": "琶pa", "example": null}, {"def": "琶pá 1.见\\"琵琶\\"。 2.明代的一种酷刑。", "example": null}]','chinese-xinhua','0'),
