('2101143296490344480','炮','1','pào','火','9',NULL,'[{"def": "炮  bao", "example": null}, {"def": "一种烹调方法", "example": null}, {"def": "用锅等在旺火上急炒", "example": null}, {"def": "中药制法之一。把药物放在高温铁锅里急炒,使其焦黄爆裂。如炮姜", "example": null}, {"def": "把物品放在器物上烘烤或焙", "example": null}, {"def": "炮  pao", "example": null}, {"def": "(形声。从火,包声。(艰??))本义古烹饪法的一种。用烂泥等裹物而烧烤)", "example": null}, {"def": "同本义", "example": null}, {"def": "炮,毛炙肉也。字亦作炰。以铁匕贯肉,加于火炙之。--《说文》", "example": null}, {"def": "炮之燔之。--《诗·小雅·瓠叶》", "example": null}, {"def": "亨羊炰羔。--《汉书·杨恽传》", "example": null}, {"def": "炮取豚台若将。--《礼记·内则》。注以涂烧之为名也。", "example": null}, {"def": "炮 bā0 烹调方法。", "example": null}, {"def": "①在旺火上速炒（牛羊肉片等）。", "example": null}, {"def": "②烘焙。又见páo；pào。", "example": null}, {"def": "炮（砲、礮）pào", "example": null}, {"def": "⒈一类重型武器的统称大～。迫击～。火箭～。", "example": null}, {"def": "⒉爆竹～仗。鞭～。", "example": null}, {"def": "炮páo", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "炮bāo 1.一种烹调方法。将鱼肉片等放在锅或铛中置于旺火上迅速搅拌。 2.烘焙。", "example": null}]','chinese-xinhua','0'),
('2101143296490344481','跑','1','pǎo','足','12',NULL,'[{"def": "跑", "example": null}, {"def": "急走", "example": null}, {"def": "跑,趵也。--《广雅·释言》", "example": null}, {"def": "红缰跑骏马,金镞掣秋鹰。--唐·马戴《边将》", "example": null}, {"def": "又如长跑(长距离跑步);跑解马(表演马术);跑冰(滑冰;溜冰);跑竹马(民间娱乐活动之一种);跑搭(奔走,奔忙);跑路(奔走);跑踏(奔走;奔忙)", "example": null}, {"def": "逃走;躲避", "example": null}, {"def": "你当真叫他回去,跑不了一顿饱打。--《老残游记》", "example": null}, {"def": "又如逃跑(逃走);别让特务跑了;跑走(逃走;走掉)", "example": null}, {"def": "走;走路", "example": null}, {"def": "为某种事物或利益而奔走", "example": null}, {"def": "跑páo兽用脚刨土～槽（刨槽根）。虎～泉，在杭州。", "example": null}, {"def": "跑pǎo", "example": null}, {"def": "⒈奔，快速移动～步。赛～。火车～得快。", "example": null}, {"def": "⒉走，逃～路。逃～。敌人～不了。", "example": null}, {"def": "⒊漏出，挥发～电。～气。～油。", "example": null}, {"def": "⒋为某种事而奔走～街。～马头。", "example": null}]','chinese-xinhua','0'),
('2101143296490344482','抛','1','pāo','扌','7',NULL,'[{"def": "拋", "example": null}, {"def": "(形声。本义丢弃)", "example": null}, {"def": "同本义", "example": null}, {"def": "管儿不作供奉儿,抛在东都双鬓丝。--唐·元稹《琵琶歌》", "example": null}, {"def": "纸片抛落。--《聊斋志异·促织》", "example": null}, {"def": "又如抛漾(抛弃);抛撒(抛弃;脱落;洒落);抛撇(抛开;撇弃);抛官(辞官,弃官);抛除(丢弃,抛掉)", "example": null}, {"def": "抛,掷", "example": null}, {"def": "忆昔花间相见后,只凭纤手,暗抛红豆。--唐·欧阳炯《贺明朝》", "example": null}, {"def": "又如抛砖引玉;抛丸(杂技之一。两手上下抛接多个弹丸不使落地);抛扔(投掷);抛珠滚玉(比喻流泪);抛声炫俏(故意声张卖弄);抛泊(抛锚停泊)", "example": null}, {"def": "以低价大量卖出", "example": null}, {"def": "抛（拋）pāo", "example": null}, {"def": "⒈投，扔～物。", "example": null}, {"def": "⒉丢掉～弃。", "example": null}, {"def": "⒊暴露～头露面。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "①车、船等发生故障，中途停止行驶。", "example": null}, {"def": "②事情在进行中因故停止。", "example": null}]','chinese-xinhua','0'),
('2101143296490344483','脬','1','pāo','月','11',NULL,'[{"def": "脬〈名〉", "example": null}, {"def": "膀胱", "example": null}, {"def": "风瘅客脬,难于大小溲,溺赤。--《史记》。张守节正义脬……膀胱也。”", "example": null}, {"def": "称鼓起而轻软之物", "example": null}, {"def": "借指水聚积之处", "example": null}, {"def": "脬〈量〉", "example": null}, {"def": "同泡”。用于屎、尿", "example": null}, {"def": "脬pāo", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉量词，用于屎尿一～尿。", "example": null}]','chinese-xinhua','0'),
