('2101143296490344487','培','1','péi','土','11',NULL,'[{"def": "培〈动〉", "example": null}, {"def": "(形声。从土,咅声。本义给植物或墙堤等的根基垒土)", "example": null}, {"def": "同本义", "example": null}, {"def": "培,培敦土田山川也。--《说文》。按,垒土也。", "example": null}, {"def": "若见垒培。--《国语·晋语》。注垒墼曰培。”", "example": null}, {"def": "故栽者培之。--《礼记·中庸》", "example": null}, {"def": "凿培而遁之。--《淮南子·齐俗》。注培屋后墙也。”", "example": null}, {"def": "高培则拔。--《吕氏春秋·辨土》。注培田侧也。”", "example": null}, {"def": "又如培户(昆虫把土堆在洞穴周围)", "example": null}, {"def": "增益;增添", "example": null}, {"def": "培养,教育", "example": null}, {"def": "把东西埋在灰、沙中保存", "example": null}, {"def": "培péi", "example": null}, {"def": "⒈在植物、墙堤等的根基部分加土～土。", "example": null}, {"def": "⒉", "example": null}, {"def": "①训练教育～养科学技术人才。", "example": null}, {"def": "②养育繁殖～养细胞。", "example": null}, {"def": "⒊", "example": null}, {"def": "培pǒu 1.土丘。", "example": null}]','chinese-xinhua','0'),
