('2101143296498733059','沛','1','pèi','氵','7',NULL,'[{"def": "沛〈名〉", "example": null}, {"def": "(形声。从水,市声。本义沛水)", "example": null}, {"def": "同本义", "example": null}, {"def": "沛,沛水。出辽东番汗塞外,西南入海。--《说文》", "example": null}, {"def": "泽名。沛泽", "example": null}, {"def": "齐侯田于沛。--《左传·昭二十年》。注沛,泽名。”", "example": null}, {"def": "多水草的沼泽地", "example": null}, {"def": "大陷于沛泽之中。--《公羊传·僖公四年》。注草棘曰沛。”", "example": null}, {"def": "犹逸禽之赴深林,蝱虫内之趣大沛。--《后汉书·崔髎传》", "example": null}, {"def": "蓄积用来灌田的水", "example": null}, {"def": "浙中…少水,人家多于山上置闸蓄水,遇旱岁开以灌田,名之曰沛,取沛然之义也。--《三余赘笔》", "example": null}, {"def": "通旆”。旗,幡", "example": null}, {"def": "丰其沛,日中见沫。--", "example": null}, {"def": "沛pèi", "example": null}, {"def": "⒈杂草丛生的湖泊～泽。", "example": null}, {"def": "⒉水奔流的样子。〈引〉大，广阔～然。", "example": null}, {"def": "⒊行动迅速的样子。", "example": null}, {"def": "⒋盛，充足力～。充～。", "example": null}]','chinese-xinhua','0'),
('2101143296498733060','佩','1','pèi','亻','8',NULL,'[{"def": "佩", "example": null}, {"def": "(会意。从人凡巾。本义系在衣带上的装饰品)", "example": null}, {"def": "同本义", "example": null}, {"def": "佩,大带佩也。--《说文》", "example": null}, {"def": "青青子佩。--《诗·郑风·子衿》", "example": null}, {"def": "共王之服玉佩玉。--《周礼·王府》。注王之所带者。”", "example": null}, {"def": "遗余佩兮澧浦。--《楚辞·湘君》", "example": null}, {"def": "又如佩玖(作佩饰用的浅黑色美石);佩玦(有缺口的环形佩玉);佩珂(用黄黑色玉石制成的佩饰);佩衽(佩玉和衣襟)", "example": null}, {"def": "姓", "example": null}, {"def": "佩 〈动〉", "example": null}, {"def": "佩带,把徽章、符号、手枪等戴在或挂在胸前、臂上、肩上或腰间", "example": null}, {"def": "佩之金玦。--《左传·闵公二年》", "example": null}, {"def": "古代君子,必佩玉。", "example": null}, {"def": "佩pèi", "example": null}, {"def": "⒈〈古〉系在衣带上的装饰品，又特指此装饰品上的玉～带。解～欲西去。", "example": null}, {"def": "⒉挂，戴～剑。腰间～着手枪。～戴纪念章。", "example": null}, {"def": "⒊敬服～服。敬～。", "example": null}]','chinese-xinhua','0'),
('2101143296498733061','帔','1','pèi','巾','8',NULL,'[{"def": "帔〈名〉", "example": null}, {"def": "(形声。从巾,皮声。巾,裹头或缠束、覆盖用的织物。本义裙)", "example": null}, {"def": "同本义", "example": null}, {"def": "弘农谓裙帔也。--《说文》", "example": null}, {"def": "古代披在肩背上的服饰。妇女用的帔绣着各种花纹,大领对襟", "example": null}, {"def": "指帔子和裙袄);凤冠霞帔", "example": null}, {"def": "一种类似僧人袈裟的衣服", "example": null}, {"def": "其服黄帔,乃是古贤之衣。--《笑道论》", "example": null}, {"def": "帔 pèi〈古〉披在肩背上的服饰。", "example": null}, {"def": "帔pī 1.戏曲传统服装。剧中帝王﹑后妃﹑将相﹑官绅的便服。大领，对襟，水袖，左右胯下开衩，其颜色与图案花纹，因人物身份而异。女帔长仅及膝。", "example": null}]','chinese-xinhua','0'),
