('2101143296502927414','毗','1','pí','比','9',NULL,'[{"def": "毗", "example": null}, {"def": "(形声。从田,比声。本义人脐)", "example": null}, {"def": "人的肚脐", "example": null}, {"def": "春秋时鲁国城邑名", "example": null}, {"def": "五年,春,城毗。--《春秋》", "example": null}, {"def": "毗 〈动〉", "example": null}, {"def": "通弼”。辅助,从旁协助", "example": null}, {"def": "辅毗安顺。--《太尉刘宽碑》", "example": null}, {"def": "为国毗辅。--《绥民校尉熊君碑》", "example": null}, {"def": "又如毗助(毗佐、毗奉、毗辅、毗翼。辅助);毗益(辅助;助益);毗赞(辅佐;襄助)", "example": null}, {"def": "邻连,与…相邻", "example": null}, {"def": "附和", "example": null}, {"def": "天之方懠,无所夸毗。--《诗·大雅》。朱熹集传夸,大也;毗,附也。”", "example": null}, {"def": "通裨”。增益", "example": null}, {"def": "轧言及政事,多所毗补。--《后汉书·明德马皇", "example": null}, {"def": "毗（毘）pí", "example": null}, {"def": "⒈辅助～佐。", "example": null}, {"def": "⒉紧靠，连接～邻。～连。", "example": null}]','chinese-xinhua','0'),
('2101143296502927415','疲','1','pí','疒','10',NULL,'[{"def": "疲〈形〉", "example": null}, {"def": "(形声。从疒,皮声。病字旁念 档芿杮Ｌ据甲骨据甲骨文,象人躺在床上害病的样子。以它作形旁的字一般与疾病有关。本义疲乏;困倦)", "example": null}, {"def": "同本义", "example": null}, {"def": "疲,劳也。--《说文》", "example": null}, {"def": "疲,乏也。--《玉篇》", "example": null}, {"def": "苶然疲役。--《庄子·齐物论》", "example": null}, {"def": "疲马之死也。--《淮南子·俶真》", "example": null}, {"def": "士民疲病于内。--《韩非子·初见秦》", "example": null}, {"def": "夫以疲病之卒御狐疑之众。--《资治通鉴》", "example": null}, {"def": "又如筋疲力尽;疲敝(疲乏困苦);疲玩(疲塌轻忽);疲曳(疲弱困顿,比喻年老);疲钝(疲倦困顿);疲顽(疲困倦怠);疲匮(疲累困乏);疲弊(困苦穷乏,是疲敝);疲人(疲困之人);颇(困顿耗损)", "example": null}, {"def": "疲pí", "example": null}, {"def": "⒈累，劳累，倦怠，乏力～累。～劳。～惫。～倦。～乏无力。筋～力尽。～于奔命。", "example": null}, {"def": "⒉［疲癃］衰老多病。", "example": null}, {"def": "⒊［疲塌］［疲沓］懈怠，不起劲再不能～塌的工作。", "example": null}]','chinese-xinhua','0'),
('2101143296502927416','蚍','1','pí','虫','10',NULL,'[{"def": "蚍〈名〉", "example": null}, {"def": "蚍蜉,一种大蚂蚁", "example": null}, {"def": "蚍?", "example": null}, {"def": "喻微小的力量", "example": null}, {"def": "蚍蜉", "example": null}, {"def": "蚍蜉撼大树", "example": null}, {"def": "蚍蜉撼大树,可笑不自量。--唐·韩愈《昌黎先生集》", "example": null}, {"def": "亦作蚍蜉撼树”", "example": null}, {"def": "蚍pí", "example": null}]','chinese-xinhua','0'),
