('2101143296536481872','颦','1','pín','页','21',NULL,'[{"def": "颦", "example": null}, {"def": "(形声。从频,卑声。本义皱眉) 同本义", "example": null}, {"def": "犹如含颦望巡狩,九疑如黛隔湘川。--唐·李群玉《黄陵庙》", "example": null}, {"def": "又如颦眉(皱眉);一颦一笑;颦笑(皱眉和欢笑);颦蛾(皱眉);东施效颦(西施病心而捧心皱眉,其里丑女以为美而模仿)", "example": null}, {"def": "颦", "example": null}, {"def": "忧愁", "example": null}, {"def": "颦pín皱眉头眉～。效～。", "example": null}]','chinese-xinhua','0'),
('2101143296536481873','玭','1','pín','','9',NULL,'[{"def": "玭pín珍珠。", "example": null}]','chinese-xinhua','0'),
('2101143296536481874','贫','1','pín','贝','8',NULL,'[{"def": "贫", "example": null}, {"def": "(会意兼形声。从贝从分,分亦声。贝”是古货币,一个贝”还要分开,表示贫困。本义缺少财物,贫困。与富”相对)", "example": null}, {"def": "同本义", "example": null}, {"def": "贫,财分少也。--《说文》", "example": null}, {"def": "无财谓之贫。--《庄子·让王》", "example": null}, {"def": "贫者,士之常也。--《说苑·杂言》", "example": null}, {"def": "分贫振穷。--《左传·昭公十四年》。疏贫、穷相类。细言,穷困于贫。”", "example": null}, {"def": "贫而无谄。--《论语》", "example": null}, {"def": "强本而节用,则天下不能贫。--《荀子·天论》", "example": null}, {"def": "楚人贫居。--三国魏·邯郸淳《笑林》", "example": null}, {"def": "家贫,无从致书以观。--明·宋濂《送东阳马生序》", "example": null}, {"def": "又如贫难(贫苦,困难);贫胎(骂人的话。穷鬼);", "example": null}, {"def": "贫pín", "example": null}, {"def": "⒈穷，跟\\"富\\"相对～穷。～病交迫。国富而～治，曰重富，重富者强（贫治当作贫国来治理，勤俭持国。重富富上加富）。", "example": null}, {"def": "⒉缺乏，不足～油。～血症。～乏（极不丰富）。", "example": null}, {"def": "⒊言语噜苏，令人讨厌他耍～嘴。她那张嘴太～。", "example": null}]','chinese-xinhua','0'),
('2101143296536481875','嫔','1','pín','女','13',NULL,'[{"def": "嫔", "example": null}, {"def": "(形声。从女,宾声。本义帝王的女儿出嫁)", "example": null}, {"def": "同本义", "example": null}, {"def": "嫔,服也。谓服事人者。--《说文》", "example": null}, {"def": "嫔妇也。--《尔雅》", "example": null}, {"def": "厘降二女于妫沬,嫔于虞。--《书·尧典》", "example": null}, {"def": "七月嫔妇。--《周礼·大宰》", "example": null}, {"def": "跟从", "example": null}, {"def": "日嫔月随。--《太玄·从》", "example": null}, {"def": "嫔", "example": null}, {"def": "古代妇女的通称。亦对妇人的美称", "example": null}, {"def": "帝王诸侯的姬妾", "example": null}, {"def": "九妃六嫔。--《国语·齐语》", "example": null}, {"def": "妃嫔媵嫱,王子皇孙。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如嫔妃(帝王的女官", "example": null}, {"def": "嫔（嬪）pín", "example": null}, {"def": "⒈〈古〉皇宫里的女官。", "example": null}, {"def": "⒉女子出嫁。", "example": null}, {"def": "⒊〈古〉妻死后的称呼。", "example": null}, {"def": "⒋［嫔然］形容众多。", "example": null}]','chinese-xinhua','0'),
('2101143296536481876','频','1','pín','页','13',NULL,'[{"def": "频", "example": null}, {"def": "(会意。从步,从页。页人头。《说文》认为步是涉”的省略。人将要渡河,见水深,皱眉而止。本义皱眉)", "example": null}, {"def": "同本义", "example": null}, {"def": "已频顣曰。--《孟子》", "example": null}, {"def": "又如频蹙(皱眉蹙额,忧愁不乐的样子)", "example": null}, {"def": "接近;临近", "example": null}, {"def": "百姓流亡,频于涂炭。--晋·潘岳文", "example": null}, {"def": "并列", "example": null}, {"def": "频", "example": null}, {"def": "重复,连续", "example": null}, {"def": "频,连也。--《字汇》", "example": null}, {"def": "频年服役。--《后汉书·杨终传》", "example": null}, {"def": "又如频日(连续多日);频世(连续两代);频岁(连年)", "example": null}, {"def": "危急;紧急", "example": null}, {"def": "于科有哀,国步斯频。--《诗·大雅·桑柔》", "example": null}, {"def": "频", "example": null}, {"def": "在一定时间(", "example": null}, {"def": "频pín", "example": null}, {"def": "⒈屡次，连续多次～繁。捷报～传。～～招手。", "example": null}, {"def": "⒉［频仍］连续不断，一再重复。", "example": null}, {"def": "⒊［频率］", "example": null}, {"def": "①物体在单位时间内完成振动的次数。常用的单位是赫兹（１赫兹＝１次／秒）、千赫、兆赫。", "example": null}, {"def": "②在一定的时间或范围内事物重复出现或反复发生的次数。", "example": null}, {"def": "频bīn 1.水边。", "example": null}]','chinese-xinhua','0'),
('2101143296536481877','牝','1','pìn','牜','6',NULL,'[{"def": "牝〈名〉", "example": null}, {"def": "(形声。从牛,匕声。依甲骨文,匕”为雌性动物的标志。本义雌性的禽兽)", "example": null}, {"def": "同本义", "example": null}, {"def": "牝,畜母也。--《说文》", "example": null}, {"def": "利牝马之贞。--《易·坤》", "example": null}, {"def": "畜牝牛,吉。--《易·离》", "example": null}, {"def": "牝鸡之晨,惟家之索。--《书·牧誓》", "example": null}, {"def": "又如牝朝(唐人称武后当政为牝朝);牝牡(雌雄两性)", "example": null}, {"def": "泛指阴性的事物", "example": null}, {"def": "豨谷为牝。--《大戴礼记·本命》", "example": null}, {"def": "肾者,牝藏也。--《素问·水热穴论》", "example": null}, {"def": "牝常以静胜牡。--《老子》", "example": null}, {"def": "锁孔", "example": null}, {"def": "键,牡;闭,牝也。--《礼记》。翱", "example": null}, {"def": "牝鸡司晨", "example": null}, {"def": "牝pìn雌的鸟兽。跟\\"牡\\"相对～鸽。～牛。", "example": null}]','chinese-xinhua','0'),
