('2101143296536481904','坪','1','pínɡ','土','8',NULL,'[{"def": "坪〈名〉", "example": null}, {"def": "(形声。从土,平声。本义平坦之地)", "example": null}, {"def": "同本义,泛指山区和丘陵地区局部的平地", "example": null}, {"def": "坪,地平也。--《说文》", "example": null}, {"def": "又如草坪;停机坪", "example": null}, {"def": "中国西北黄土地区的黄土阶地或台地。草多是良好的农耕场所", "example": null}, {"def": "日本面积单位名,等于一日亩的三十分之一,合3.3057平方米", "example": null}, {"def": "坪píng", "example": null}, {"def": "⒈平坦的场地草～。", "example": null}, {"def": "⒉泛指山区或丘陵地区内的小块平地。", "example": null}]','chinese-xinhua','0'),
('2101143296536481905','苹','1','pínɡ','艹','8',NULL,'[{"def": "苹", "example": null}, {"def": "(形声。从苃,平声。本义浮萍)", "example": null}, {"def": "同本义", "example": null}, {"def": "苹,无根浮水而生者。--《说文》", "example": null}, {"def": "蒿的一种。即青蒿", "example": null}, {"def": "呦呦鹿呜,食野之苹。--《诗·小雅·鹿鸣》", "example": null}, {"def": "又如苹藻主(妻子);苹敬(礼金)", "example": null}, {"def": "同蘯”。见苹果”", "example": null}, {"def": "通輟”。兵车的一种", "example": null}, {"def": "苹车之萃。--《周礼·春官·车仆》", "example": null}, {"def": "苹 〈形〉", "example": null}, {"def": "草丛生的样子", "example": null}, {"def": "苹（蘯）píng", "example": null}, {"def": "⒈［苹果］落叶乔木，花白或淡红色。果实球形也叫\\"苹果\\"，味酸甜或甜而略酸，品种很多，供生吃或制果酱等。", "example": null}, {"def": "苹pēng 1.见\\"苹萦\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296536481906','屏','1','pínɡ','尸','9',NULL,'[{"def": "屏", "example": null}, {"def": "退避;隐退", "example": null}, {"def": "侯生乃屏人间语。--《史记·魏公子列传》", "example": null}, {"def": "又如屏居(辞官隐居,不问世事);屏语(避开他人,私下交谈);屏伏(隐退,避匿);屏移(退隐)", "example": null}, {"def": "隐藏", "example": null}, {"def": "尔不许我,我乃屏璧与圭。--《书·金縢》", "example": null}, {"def": "又如屏匿(隐藏);屏迹(隐避);屏藏(隐藏)", "example": null}, {"def": "摈弃;除去,去掉", "example": null}, {"def": "保护", "example": null}, {"def": "抑制。抑止不出气", "example": null}, {"def": "宋将军屏息观之。--", "example": null}, {"def": "屏 bǐng", "example": null}, {"def": "①抑制住（呼吸）～气。", "example": null}, {"def": "②同\'摒\'。除去；放弃～弃。又见píng。", "example": null}, {"def": "【屏除】排去～恶习。", "example": null}, {"def": "【屏气凝神】形容精神高度紧张、集中。", "example": null}, {"def": "【屏弃】抛弃；废除。", "example": null}, {"def": "【屏息】屏气～聆听。", "example": null}, {"def": "屏píng", "example": null}, {"def": "⒈遮挡，遮挡物～风。～蔽。围～。外～。内～。", "example": null}, {"def": "⒉字画的条幅字～。画～。", "example": null}, {"def": "⒊［～障］遮挡，也指像屏风那样的遮挡物，多指山岭、岛屿等天然～障。", "example": null}, {"def": "屏bīng 1.见\\"屏营\\"。", "example": null}, {"def": "屏bìng 1.见\\"屏当\\"﹑\\"屏厕\\"。", "example": null}]','chinese-xinhua','0'),
