('2101143296540676157','璞','1','pú','王','16',NULL,'[{"def": "璞〈名〉", "example": null}, {"def": "(形声。从玉,菐声。本义蕴藏有玉的石头。也指未雕琢的玉)", "example": null}, {"def": "同本义", "example": null}, {"def": "含玉的矿石", "example": null}, {"def": "天真,淳朴", "example": null}, {"def": "夫质者朴也,有崇尚太璞之意。--郑观应《盛世危言》", "example": null}, {"def": "璞玉浑金", "example": null}, {"def": "王戎目山巨源如璞玉浑金,人皆钦其宝,莫知名其器。--南朝宋·刘义庆《赏誉上》", "example": null}, {"def": "璞pú含玉的石头或未雕琢过的玉浑金～玉。〈喻〉人的品质纯朴～实。", "example": null}]','chinese-xinhua','0'),
('2101143296540676158','濮','1','pú','氵','17',NULL,'[{"def": "濮〈名〉", "example": null}, {"def": "古水名", "example": null}, {"def": "濮,濮水出东郡濮阳,南入钜野。--《说文》", "example": null}, {"def": "桑间濮上之音。--《礼记·乐记》", "example": null}, {"def": "钓于濮水。--《庄子·秋水》", "example": null}, {"def": "古州名", "example": null}, {"def": "濮pú", "example": null}]','chinese-xinhua','0'),
('2101143296544870400','匍','1','pú','勹','9',NULL,'[{"def": "匍滴虫", "example": null}, {"def": "匍匐", "example": null}, {"def": "幸主者出,南面召见,则惊走匍匐阶下。--明·宗臣《报刘一丈书》", "example": null}, {"def": "巡逻兵在敌军炮火下匍匐过阵地", "example": null}, {"def": "匍匐前进", "example": null}, {"def": "匍匐在主子脚下", "example": null}, {"def": "匍匐而行", "example": null}, {"def": "朝东走,沿着阴暗的一边顽固地匍匐而行下去", "example": null}, {"def": "匍匐茎", "example": null}, {"def": "匍匐前进", "example": null}, {"def": "匍pú", "example": null}]','chinese-xinhua','0'),
