('2101143296549064763','骐','1','qí','马','11',NULL,'[{"def": "骐", "example": null}, {"def": "(形声。从马,其声。本义青黑色有如棋盘格子纹的马)", "example": null}, {"def": "同本义", "example": null}, {"def": "骐,马青骊文如博棋也。--《说文》", "example": null}, {"def": "四骐翼翼。--《诗·小雅·采芑》", "example": null}, {"def": "又如骐骝(身有青黑斑纹而黑鬣的马)", "example": null}, {"def": "骏马", "example": null}, {"def": "乘骐骥以驰聘兮。--《楚辞·离骚》", "example": null}, {"def": "又如骐骥(骏马);骐骥一毛(比喻珍贵物品的极小部分)", "example": null}, {"def": "通麒”。麒麟", "example": null}, {"def": "刳胎焚天,而骐麟不至。--《战国策·赵策四》", "example": null}, {"def": "骐骥", "example": null}, {"def": "骐骥一跃。--《荀子·劝学》", "example": null}, {"def": "骐qí", "example": null}, {"def": "⒈有青黑色纹理的马。", "example": null}, {"def": "⒉青黑色的。", "example": null}]','chinese-xinhua','0'),
('2101143296549064764','骑','1','qí','马','11',NULL,'[{"def": "骑", "example": null}, {"def": "(形声。从马,奇声。本义跨马)", "example": null}, {"def": "同本义", "example": null}, {"def": "骑,跨马也。--《说文》", "example": null}, {"def": "步骑罗些。--《楚辞·招魂》", "example": null}, {"def": "脱身独骑。--《史记·项羽本纪》", "example": null}, {"def": "其子好骑。--《淮南子·人间训》", "example": null}, {"def": "骑大马。--明·刘基《卖柑者言》", "example": null}, {"def": "骑马挟矢。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如骑射(骑马射箭);骑寇(骑马入侵的贼寇,也是对北方游牧民族的鄙称);骑猎(骑马打猎);骑战(骑马打仗)", "example": null}, {"def": "跨于物上或两边叫骑,跨坐", "example": null}, {"def": "不骑衡。--《史记·袁盎传》", "example": null}, {"def": "又如骑两头马(比喻两头观望,看风向);骑鲸(乘鲸;借指死亡或隐遁);骑驴觅驴(是说忘记自己已有又向", "example": null}, {"def": "骑qí", "example": null}, {"def": "⒈两腿跨坐在牲畜或其它东西上～马。～驴。～摩托车。", "example": null}, {"def": "⒉骑的马或其它牲畜坐～。", "example": null}, {"def": "⒊指骑兵轻～。铁～。也泛指骑马的人单～。", "example": null}, {"def": "⒋兼跨两边～缝盖章。", "example": null}]','chinese-xinhua','0'),
