('2101143296557453330','汔','1','qì','氵','6',NULL,'[{"def": "汔〈动〉", "example": null}, {"def": "水干涸", "example": null}, {"def": "汔,水涸也。--《说文》", "example": null}, {"def": "汔渊剖珠,倾岩刊玉。--晋·葛洪《抱朴子》", "example": null}, {"def": "尽;完成", "example": null}, {"def": "汔,尽也。--《广雅》", "example": null}, {"def": "壮狡汔尽穷屈。--《吕氏春秋·听言》", "example": null}, {"def": "汔尽(竭尽);汔事(完事)", "example": null}, {"def": "汔 〈副〉", "example": null}, {"def": "几乎,差不多", "example": null}, {"def": "民亦劳止,汔可小康。--《诗·大雅·民劳》", "example": null}, {"def": "终竟;一直", "example": null}, {"def": "汔qì", "example": null}, {"def": "⒈水涸。", "example": null}, {"def": "⒉庶几，差不多。", "example": null}]','chinese-xinhua','0'),
('2101143296557453331','迄','1','qì','辶','6',NULL,'[{"def": "迄〈动〉", "example": null}, {"def": "(形声。从辵,乞声。本义到;至) 同本义", "example": null}, {"def": "迄,至也。--《说文新附》", "example": null}, {"def": "以迄于今。--《诗·大雅·生民》", "example": null}, {"def": "迄于天下。--《国语·周语下》", "example": null}, {"def": "吴获迄古。--《楚辞·天问》", "example": null}, {"def": "声教迄于四海。--《汉书·艺文志》", "example": null}, {"def": "降周迄孔。--《汉书·扬雄传》", "example": null}, {"def": "夫普法之战,迄今虽为陈迹,而其事信而有征。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "迄今盛行。--蔡元培《图画》", "example": null}, {"def": "自皇古迄今。--", "example": null}, {"def": "又如迄至(至,到)", "example": null}, {"def": "迄 〈副〉", "example": null}, {"def": "竟,毕竟,终究", "example": null}, {"def": "迄无成功。--《后汉书·孔融传》", "example": null}, {"def": "迄无济。", "example": null}, {"def": "迄qì", "example": null}, {"def": "⒈至，到～今为止。", "example": null}, {"def": "⒉毕竟，终究～无效果。", "example": null}]','chinese-xinhua','0'),
('2101143296557453332','弃','1','qì','廾','7',NULL,'[{"def": "弃", "example": null}, {"def": "(会意。甲骨文字形,上面是个头向上的婴孩,三点表示羊水,头向上表示逆产。中间是只簸箕 ,下面是两只手∠起来表示将不吉利的逆产儿倒掉之意。小篆写法大同小异。本义", "example": null}, {"def": "扔掉;抛弃)", "example": null}, {"def": "同本义", "example": null}, {"def": "弃,捐也。--《说文》。段注弃者,不孝子人所弃也。”", "example": null}, {"def": "天之弃商也久矣。--《左传·僖公二十二年》", "example": null}, {"def": "抛子弃草间。--王粲《七哀》", "example": null}, {"def": "举以予人,如弃草芥。--苏洵《六国论》", "example": null}, {"def": "敌弃炮仓皇遁。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "子孙弃者。--清·袁枚《黄生借书说》", "example": null}, {"def": "弃其妇。--清·周容《芋老人传》", "example": null}, {"def": "弃", "example": null}, {"def": "弃（棄）qì舍去，抛掉舍～。抛～。～旧图新。", "example": null}]','chinese-xinhua','0'),
