('2101143296557453339','契','1','qì','大','9',NULL,'[{"def": "契〈名〉", "example": null}, {"def": "后时圣人易之以书契。--《易·系辞》", "example": null}, {"def": "掌稽布之书契。--《周礼·质人》。注取予市物之券也,其券之象书两札,刻其侧。”", "example": null}, {"def": "献粟者执右契。--《礼记·曲礼》", "example": null}, {"def": "翟璜操右契而乘轩。--《韩非子·外储说左下》", "example": null}, {"def": "得人遗契者。--《列子·说符》", "example": null}, {"def": "言已应,则执其契。--《韩非子·主道》", "example": null}, {"def": "又如契卷(互相约束的证据);契印(骑缝印。预备分离后对证用);契箭(作符契用的箭);契面银(回赎或悔约时,按照契约规定须付出的费用);立契为凭", "example": null}, {"def": "古代在龟甲、兽骨上灼刻文字和灼刻文字用的刀具,皆称契", "example": null}, {"def": "刻龟甲的凿子", "example": null}, {"def": "菙氏掌共燋契,以待", "example": null}, {"def": "契（栔）qì", "example": null}, {"def": "⒈合同，契约（证明买卖、抵押、租赁等的文书或字据）地～。房～。卖身～。", "example": null}, {"def": "⒉相合，情意相投～友。默～。", "example": null}, {"def": "⒊用刀刻，也指刻的文字～其舟。～文。书～。", "example": null}, {"def": "契（偰）xiè", "example": null}, {"def": "⒈传说是舜的臣，商族的祖先，曾帮助禹治洪水。", "example": null}, {"def": "契qiè 1.通\\"挈\\"。持，取。 2.见\\"契阔\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296557453340','砌','1','qì','石','9',NULL,'[{"def": "砌〈名〉", "example": null}, {"def": "(形声。从石,切声。本义台阶)", "example": null}, {"def": "同本义", "example": null}, {"def": "雕阑玉砌应犹在,只是朱颜改。--李煜《虞美人》词", "example": null}, {"def": "砌水(滴在台阶上的雨水);砌石(阶石);砌阶(台阶)", "example": null}, {"def": "门限,门槛", "example": null}, {"def": "于是玄墀釦砌,玉阶彤庭。--汉·班固《西都赋》", "example": null}, {"def": "砌〈动〉", "example": null}, {"def": "放置砖或石料以及粘结料(如砂浆)造墙或扶壁", "example": null}, {"def": "堆砌", "example": null}, {"def": "砌以青玉。--《战国策·魏策》", "example": null}, {"def": "砌石为磴。--清·姚鼐《登泰山记》", "example": null}, {"def": "砌红砌绿(形容春日花木繁荣的景象)", "example": null}, {"def": "连缀", "example": null}, {"def": "砌qì", "example": null}, {"def": "⒈用砖、石、泥等垒造房屋或炉灶等～墙。～灶。", "example": null}, {"def": "⒉台阶。", "example": null}, {"def": "砌qiè 1.见\\"砌末\\"。 2.指旧时戏曲中滑稽笑谑的动作。 3.嘲笑;讽刺。 4.串演;扮演。", "example": null}]','chinese-xinhua','0'),
('2101143296557453341','槭','1','qì','木','15',NULL,'[{"def": "槭〈名〉", "example": null}, {"def": "木名", "example": null}, {"def": "槭qì落叶小乔木。叶掌状分裂，秋季变为红色或黄色。花黄绿色。", "example": null}, {"def": "槭qī 1.木名。槭树科槭树属植物的泛称。主要特征为具对生叶和双翅果。我国产百余种。较著名的有鸡爪槭(也称鸡爪枫)﹑平基槭(也称元宝枫)﹑三角枫等。嫩叶可当蔬菜，", "example": null}, {"def": "种子可食。木材坚韧，可作器具。其叶入秋变红，供观赏。", "example": null}, {"def": "槭sè 1.草木凋落貌。 2.见\\"槭槭\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296557453342','起','1','qǐ','走','10',NULL,'[{"def": "起〈动〉", "example": null}, {"def": "(形声。从走,己声。本义由躺而坐;由坐而立)", "example": null}, {"def": "同本义", "example": null}, {"def": "起,能立也。--《说文》", "example": null}, {"def": "曩子坐,今子起。--《庄子·齐物论》", "example": null}, {"def": "载起载行。--《诗·小雅·沔水》", "example": null}, {"def": "请业则起。--《礼记·曲礼》", "example": null}, {"def": "子墨子起。--《墨子·公输》", "example": null}, {"def": "吾恂恂而起。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "夫起大呼。--《虞初新志·秋声诗自序》", "example": null}, {"def": "又", "example": null}, {"def": "妇亦起大呼。", "example": null}, {"def": "又如起在(起来);起舞(起身而舞。欢欣的样子);起坐(起立与坐下);起谢(起立谢过)", "example": null}, {"def": "起床", "example": null}, {"def": "起视四境。--宋·苏洵《六国论》", "example": null}, {"def": "不敢同卧起。--清·方苞《狱中杂记》", "example": null}, {"def": "又", "example": null}, {"def": "起qǐ", "example": null}, {"def": "⒈由卧而坐，由坐而立，由下而上等～来。～床。～立。～伏。～劲。", "example": null}, {"def": "⒉离开原来的位置～去。～动。～货。～钉子。", "example": null}, {"def": "⒊上升，涨大～飞。有～有落。发面～了。", "example": null}, {"def": "⒋转机，好转的～色。", "example": null}, {"def": "⒌开始～始。～点。从今天～。", "example": null}, {"def": "⒍发动，发生～兵。～疑。～作用。", "example": null}, {"def": "⒎长出～疙瘩。～疹子。", "example": null}, {"def": "⒏草拟～稿。～草。", "example": null}, {"def": "⒐建造，创立～住房。白手～家。", "example": null}, {"def": "⒑量词。指批、群、件、宗等一～货物。两～队伍。三～差错。四～案件。", "example": null}, {"def": "⒒〈表〉动作的趋向提～。拿～。抱～。举～。引～。问～。想～。", "example": null}, {"def": "⒓跟\\"来\\"连用，〈表〉觉醒或动作开始从梦中～来。打～锣鼓来。", "example": null}, {"def": "⒔跟\\"不\\"、\\"得\\"连用，〈表〉能或够格买不～。看得～。拿不～。用得～。经得～磨练。", "example": null}, {"def": "⒕", "example": null}, {"def": "①起床。", "example": null}, {"def": "②动身，身体移动明天～身去上海。～身让坐。", "example": null}, {"def": "⒖", "example": null}, {"def": "⒗", "example": null}, {"def": "⒘", "example": null}, {"def": "⒙", "example": null}, {"def": "①发动武装革命。", "example": null}, {"def": "②脱离反动集团投身到革命阵营。驾机～义。⒚", "example": null}]','chinese-xinhua','0'),
