('2101143296557453350','企','1','qǐ','人','6',NULL,'[{"def": "企〈动〉", "example": null}, {"def": "(会意。从人,从止。甲骨文字形,上面是一个人,下面是止”(脚),表示这个人在踮起后脚跟,有企立、企足的意思。本义踮起脚跟)", "example": null}, {"def": "同本义", "example": null}, {"def": "企,举踵也。--《说文》", "example": null}, {"def": "企者不立。--《老子》", "example": null}, {"def": "日夜企而望归。--《汉书·高帝纪》", "example": null}, {"def": "渠黄不能企其景。--郭璞《江赋》", "example": null}, {"def": "又如企望(举起脚跟而望);企仰(踮起脚来仰望);企足(踮起脚)", "example": null}, {"def": "立,站立", "example": null}, {"def": "鸟企山峙。--三国 魏·何晏《景福殿赋》", "example": null}, {"def": "又如企予(踮起脚后跟站着);企立(站立)", "example": null}, {"def": "企望,盼望", "example": null}, {"def": "企qǐ", "example": null}, {"def": "⒈踮起脚后跟，盼望， 仰望～盼。～望。～待。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296557453351','屺','1','qǐ','山','6',NULL,'[{"def": "屺〈名〉", "example": null}, {"def": "(形声。从山,己声。本义无草木的山) 同本义", "example": null}, {"def": "屺,山无草木也。--《说文》", "example": null}, {"def": "陟彼屺兮,瞻望母兮。--《诗·魏风·陟岵》", "example": null}, {"def": "屺qǐ没有草木的山。", "example": null}]','chinese-xinhua','0'),
('2101143296557453352','岂','1','qǐ','山','6',NULL,'[{"def": "岂", "example": null}, {"def": "同恺”。安乐", "example": null}, {"def": "王在在镐,岂乐饮酒。--《诗·小雅·鱼藻》", "example": null}, {"def": "既见君子,孔燕岂弟。--《诗·小雅·蓼萧》", "example": null}, {"def": "岂", "example": null}, {"def": "(形声。从壴省,微省声。壴,陈列乐器。本义回师时献功之乐)", "example": null}, {"def": "岂”假借作虚词,用在句中或句首,表示反问。", "example": null}, {"def": "相当于难道”,怎么”", "example": null}, {"def": "岂非计久长。--《战国策·赵策》", "example": null}, {"def": "岂若吾乡邻。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "岂其愤世疾邪者耶。--明·刘基《卖柑者言》", "example": null}, {"def": "岂独一琴哉。--明·刘基《郁离子·千里马篇》", "example": null}, {"def": "又如岂奈(何奈,无奈);岂不尔思(怎能不思念你);岂有他哉(表示没有其他原因)", "example": null}, {"def": "相当", "example": null}, {"def": "岂（豰）qǐ", "example": null}, {"def": "⒈助词。是否，怎么，难道（用于疑问或反诘句）～愿见乎？～敢违抗？～有此理！", "example": null}, {"def": "⒉〈古〉通\\"恺\\"、\\"凯\\"。柔和，快乐。", "example": null}, {"def": "岂kǎi 1.和乐。参见\\"岂乐\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296557453353','芑','1','qǐ','艹','6',NULL,'[{"def": "芑〈名〉", "example": null}, {"def": "一种良种谷子,白芑", "example": null}, {"def": "芑,白苗。--《尔雅》", "example": null}, {"def": "芑,白苗嘉谷也。--《说文》", "example": null}, {"def": "维糜维芑。--《诗·大雅·生民》", "example": null}, {"def": "有机化合物环己间二烯的简称", "example": null}, {"def": "野菜之一种,味苦", "example": null}, {"def": "通杞”。木名,枸杞", "example": null}, {"def": "其下多荆芑。--《山海经·东山经》", "example": null}, {"def": "芑qǐ〈古〉指一种植物，似苦菜。", "example": null}]','chinese-xinhua','0'),
('2101143296557453354','启','1','qǐ','口','7',NULL,'[{"def": "启", "example": null}, {"def": "(会意。从户,从口。甲骨文字形,左边是手(又),右边是户(单扇门);用手开门,即开启的意思◇繁化加口”,或省去手(又)而成启”。金文又加攴”成啓”。现简化为", "example": null}, {"def": "启”。本义开,打开)", "example": null}, {"def": "同本义", "example": null}, {"def": "启,开也。--《说文》", "example": null}, {"def": "经传皆作啟”", "example": null}, {"def": "公将啟之。--《左传·隐公元年》", "example": null}, {"def": "疆埸无主,则啟戒心。--《国语·晋语一》", "example": null}, {"def": "凡啟塞从时。--《左传·僖公二十年》。注门户道桥谓之啟。”", "example": null}, {"def": "啟户。--《仪礼·士虞礼》", "example": null}, {"def": "门启而入。--《左传》", "example": null}, {"def": "启窗而观。--明·魏学洢《核舟记》", "example": null}, {"def": "不能启口。--清·林觉民《与妻书》", "example": null}, {"def": "又如", "example": null}, {"def": "启（啟、啓）qǐ", "example": null}, {"def": "⒈开，打开，开发，开拓～开。～封。～地三千里。", "example": null}, {"def": "⒉开导～蒙。～示。～发。", "example": null}, {"def": "⒊开始～程。～用。", "example": null}, {"def": "⒋陈述，说明～事。～告。敬～者。", "example": null}, {"def": "⒌书信书～。小～。", "example": null}, {"def": "⒍", "example": null}, {"def": "①开口难于～齿。", "example": null}, {"def": "②笑。", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
