('2101143296557453390','萋','1','qī','艹','11',NULL,'[{"def": "萋〈形〉", "example": null}, {"def": "(形声。从苃,妻声。本义草茂盛的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "萋,草盛也。--《说文》", "example": null}, {"def": "中庭萋兮鲜草生。--《汉书·外戚传》", "example": null}, {"def": "又如萋迷(草丛生茂密,造成视线阻隔。也指景象凝不清);萋芊(草木茂密的样子);萋蒨(荫蔽;深密);萋翳(茂密;荫蔽)", "example": null}, {"def": "花纹交错的样子", "example": null}, {"def": "萋兮斐兮。--《诗·小雅·巷伯》", "example": null}, {"def": "又如萋斐(萋菲。花纹交错的样子)", "example": null}, {"def": "通凄”", "example": null}, {"def": "萋萋", "example": null}, {"def": "芳草萋萋鹦鹉洲。--唐·崔颢《黄鹤楼》诗", "example": null}, {"def": "萋qī形容草长得茂盛芳草～ ～。", "example": null}]','chinese-xinhua','0'),
('2101143296557453391','期','1','qī','月','12',NULL,'[{"def": "期〈动〉", "example": null}, {"def": "(形声。从月,其声。金文从日,其声。战国古文从日,丌声。日、月都有表时间的意思。本义约会,约定)", "example": null}, {"def": "同本义", "example": null}, {"def": "期,会也。--《说文》。段注会者,合也,期者,邀约之意,所以为会合也。”", "example": null}, {"def": "归妹愆期。--《易·归妹》", "example": null}, {"def": "若旬虚期于月津。--《管子·侈靡》。注匝一月曰期。”", "example": null}, {"def": "而不能期月守也。--《礼记·中庸》", "example": null}, {"def": "叔孙旦而立期焉。--《左传·昭公二十三年》", "example": null}, {"def": "与老人期,后何也?--《史记·留侯世家》", "example": null}, {"def": "与友期行。--《世说新语·方正》", "example": null}, {"def": "又", "example": null}, {"def": "期日中。", "example": null}, {"def": "期我决斗。--明·魏禧《大铁椎传》", "example": null}, {"def": "又如期要(约定,预先约定);", "example": null}, {"def": "期（杘）jī", "example": null}, {"def": "⒈〈古〉周年，一个月～年。～月。", "example": null}, {"def": "⒉见qī。", "example": null}, {"def": "期qī", "example": null}, {"def": "⒈规定的时间如～完工。定～办理。", "example": null}, {"def": "⒉一段时间本学～。潜伏～。", "example": null}, {"def": "⒊刊物出版的编号第八～。", "example": null}, {"def": "⒋约定的时间莫误佳～。按～赴约。", "example": null}, {"def": "⒌盼望，希望～望。～待。～求解决。", "example": null}]','chinese-xinhua','0'),
('2101143296557453392','欺','1','qī','欠','12',NULL,'[{"def": "欺〈动〉", "example": null}, {"def": "(形声。从欠,其声。欠”与出气、说话有关。本义欺骗)", "example": null}, {"def": "同本义", "example": null}, {"def": "欺,诈欺也。--《说文》", "example": null}, {"def": "仁义修立谓之任,反任为欺。--《贾子道术》", "example": null}, {"def": "禄不遂行兹谓欺。--《京房易传》", "example": null}, {"def": "徒见欺。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "又", "example": null}, {"def": "尚不相欺。", "example": null}, {"def": "甚矣哉为欺也。--明·刘基《卖柑者言》", "example": null}, {"def": "又", "example": null}, {"def": "世之为欺者。", "example": null}, {"def": "又如欺诳(欺瞒);欺上罔下(对上欺骗,对下隐瞒);欺诞(夸大欺骗);欺谩(欺骗);欺三瞒四(隐蔽实情欺骗他人);欺天罔人(骗天骗人);欺天罔地(欺骗天地。极言人之背理昧心)", "example": null}, {"def": ";欺心(自己欺骗自己心怀不轨,起坏心思);欺君罔上(欺骗蒙", "example": null}, {"def": "欺qī", "example": null}, {"def": "⒈骗，蒙混～骗。伪科学是自～ ～人。", "example": null}, {"def": "⒉压迫，凌辱，侵犯～负。～压。～凌。仗势～人。", "example": null}]','chinese-xinhua','0'),
