('2101143296557453397','恰','1','qià','忄','9',NULL,'[{"def": "恰〈副〉", "example": null}, {"def": "(形声。从心,合声。本义用心)", "example": null}, {"def": "同本义", "example": null}, {"def": "恰,用心也。--《说文新附》", "example": null}, {"def": "又如恰恰(用心的样子)", "example": null}, {"def": "才,刚刚", "example": null}, {"def": "岂;难道", "example": null}, {"def": "恰 〈形〉", "example": null}, {"def": "适当;正好", "example": null}, {"def": "恰是湘妃泪尽时。--贾岛《赠人斑竹柱杖》", "example": null}, {"def": "野航恰受两三人。--杜甫《南邻》", "example": null}, {"def": "又如恰则(恰恰);恰恨(正不巧);恰合(正相符合);恰限(正遇上);恰便似(正好像);恰贴(恰当、妥贴);恰意(适合心意);", "example": null}, {"def": "恰qià正好，适当，合适～好。～巧。～当。～到好处。～如其分。", "example": null}]','chinese-xinhua','0'),
('2101143296557453398','洽','1','qià','氵','9',NULL,'[{"def": "洽〈动〉", "example": null}, {"def": "(形声。从水,合声。本义沾湿,浸润)", "example": null}, {"def": "同本义", "example": null}, {"def": "洽,沾也。--《说文》", "example": null}, {"def": "仁洽道丰。--张衡《东京赋》", "example": null}, {"def": "是泽南洽而威北畅也。--《汉书·终军传》", "example": null}, {"def": "内洽五藏。--《淮南子·要略》", "example": null}, {"def": "又如洽濡(沾湿,滋润);洽润(润泽);洽衿(沾湿衣襟)", "example": null}, {"def": "合,符合", "example": null}, {"def": "以洽百礼。--《诗·小雅·载芟》", "example": null}, {"def": "则无以祖洽于众也。--《礼记·仲尼燕居》", "example": null}, {"def": "又如洽愿(称心如愿);洽意(合意;中意);洽悉(与事切合而详尽)", "example": null}, {"def": "商量,协商意见", "example": null}, {"def": "假借为给”。供应", "example": null}, {"def": "不洽而爟之,使客无得以助攻", "example": null}, {"def": "洽qià", "example": null}, {"def": "⒈与人联系，商量接～。商～。～谈。", "example": null}, {"def": "⒉和谐和～。融～。", "example": null}, {"def": "⒊广博，普遍博物～闻。", "example": null}, {"def": "洽hé 1.古水名。一名瀵水，现称金水河。源出陕西省合阳县北部，东南流入黄河。", "example": null}]','chinese-xinhua','0'),
