('2101143296557453412','黔','1','qián','黑','16',NULL,'[{"def": "黔〈形〉", "example": null}, {"def": "(形声。从黑,今声。本义黑色) 同本义", "example": null}, {"def": "黔,黎也。从黑,今声。秦谓民为黔首,谓黑发也,同谓之黎民。--《说文》", "example": null}, {"def": "以为黔首则。--《礼记·祭义》", "example": null}, {"def": "邑中之黔。--《左传·襄公十六年》", "example": null}, {"def": "又如黔口(黑嘴巴);黔黑(深黑);黔丑(污黑丑陋)", "example": null}, {"def": "黔 〈名〉", "example": null}, {"def": "指百姓", "example": null}, {"def": "贵州省的简称", "example": null}, {"def": "姓", "example": null}, {"def": "黔 〈动〉", "example": null}, {"def": "晒黑,染黑,熏黑", "example": null}, {"def": "乌不日黔而黑。--《庄子·天运", "example": null}, {"def": "黔qián", "example": null}, {"def": "⒈黑色～口。", "example": null}, {"def": "⒉贵州的简称。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296557453413','虔','1','qián','虍','10',NULL,'[{"def": "虔〈形〉", "example": null}, {"def": "(会意。从虍,文声。虍,虎头。本义虎行走的样子)", "example": null}, {"def": "同本义。引申为勇武、强固", "example": null}, {"def": "虔,虎行皃。--《说文》", "example": null}, {"def": "有虔秉钺。--《诗·商颂·长发》", "example": null}, {"def": "诚敬;诚心", "example": null}, {"def": "以告虔也。--《左传·庄公二十四年》", "example": null}, {"def": "虔卜于先君也。--《左传·成公十二年》", "example": null}, {"def": "纠虔天刑。--《国语·鲁语》", "example": null}, {"def": "薛姨妈笑道果然如此,算我的孝心虔了。”--《红楼梦》", "example": null}, {"def": "又如虔谢(真诚地感谢);虔恳(诚恳祈求);虔洁(诚实而纯洁);虔肃(诚实而严肃);虔恭(诚敬)", "example": null}, {"def": "虔 〈动〉", "example": null}, {"def": "杀戳", "example": null}, {"def": "虔,杀也。秦晋之北,鄙谓贼为虔。--《方言》一", "example": null}, {"def": "虔刘我边陲", "example": null}, {"def": "虔qián恭敬～心。～敬。～肃。", "example": null}]','chinese-xinhua','0'),
('2101143296557453414','钱','1','qián','钅','10',NULL,'[{"def": "钱", "example": null}, {"def": "(形声。从金,戔声。本义农具名,即铁铲。上古时期曾以农具作为交易媒介,其后铸造货币又仿其形为之,因此引申为货币、钱财)", "example": null}, {"def": "金属货币。特指铜钱", "example": null}, {"def": "一曰货也。古者货贝而宝龟。周太公立九府圜法,乃用泉,至秦废贝行钱。--《说文解字》锴注", "example": null}, {"def": "龟贝金钱。--《史记·平准书》。索隐本名泉,言货之如流泉也。”", "example": null}, {"def": "景王二十一年将铸大钱。--《国语·周语》。注钱者,金币之名,古曰泉,后转曰钱。”", "example": null}, {"def": "下有积钱。--《史记·天官书》", "example": null}, {"def": "卖炭得钱何所营?--唐·白居易《卖炭翁》", "example": null}, {"def": "以钱覆其上。--宋·欧阳修《", "example": null}, {"def": "钱（鍃）qián", "example": null}, {"def": "⒈货币～币。铜～。金～。三块～。", "example": null}, {"def": "⒉费用，款项米～。菜～。一笔～。", "example": null}, {"def": "⒊财物无～难办。有～有势。", "example": null}, {"def": "⒋重量单位十分为一～。十～为一两。", "example": null}, {"def": "⒌圆形像铜钱的东西榆～（榆荚）。", "example": null}, {"def": "钱jiǎn 1.古农具名。臿属，似今之铁铲。", "example": null}]','chinese-xinhua','0'),
('2101143296557453415','钳','1','qián','钅','10',NULL,'[{"def": "钳", "example": null}, {"def": "(形声。从金,甘声。本义金属夹具)", "example": null}, {"def": "古刑具。束颈的铁圈", "example": null}, {"def": "钳,以铁有所劫束也。--《说文》", "example": null}, {"def": "皆弛解钳。--《后汉书·光武纪》", "example": null}, {"def": "古之刑在项曰钳,今之链锁。--清·阮葵生《茶余客话》", "example": null}, {"def": "又如钳铁(古代束颈的刑具);钳髠(钳和髠。古代束颈、剃发之刑);钳鈑(古代两种刑具名,钳与鈑);钳扭(束颈缚手的刑具);钳锁(小儿的金属首饰;又指古代用以束颈、锁身的", "example": null}, {"def": "两种刑具)", "example": null}, {"def": "夹持东西的用具", "example": null}, {"def": "钳", "example": null}, {"def": "古代刑罚。用铁圈束颈、手、足", "example": null}, {"def": "烧", "example": null}, {"def": "钳（箝、", "example": null}, {"def": "⒉拑）qián", "example": null}, {"def": "⒈夹东西的工具止血～。老虎～子。", "example": null}, {"def": "⒉用工具夹住。〈引〉用强力限制，约束～制。", "example": null}]','chinese-xinhua','0'),
('2101143296557453416','乾','1','qián','乙','11',NULL,'[{"def": "乾〈动〉", "example": null}, {"def": "(俗作乹。形声。从乙,倝声。乙,象植物屈曲生长的样子。本义上出) 同本义", "example": null}, {"def": "乾,上出也。--《说文》。段注此乾字之本义也。自有文字以后,乃用为卦名,而孔子释之曰健也。健之义生于上出,上出为乾,下注则为湿,故乾与湿相对,俗别其音,古无是也", "example": null}, {"def": "。”", "example": null}, {"def": "乾 〈名〉", "example": null}, {"def": "八卦的首卦;天", "example": null}, {"def": "达于上者谓之乾。凡上达者莫若气,天为积气,故乾为天。--朱骏声《说文通训定声》", "example": null}, {"def": "乾,天也。--《易·说卦传》", "example": null}, {"def": "乾,阳物也。--《易·系辞传》", "example": null}, {"def": "乾刚坤柔。--《易·杂卦传》", "example": null}, {"def": "乾为天、为圜、为君、为父、", "example": null}, {"def": "乾qián", "example": null}, {"def": "⒈八卦之一，代表天。", "example": null}, {"def": "⒉见干（乾）。", "example": null}]','chinese-xinhua','0'),
