('2101143296565841924','堑','1','qiàn','土','11',NULL,'[{"def": "堑", "example": null}, {"def": "(形声。从土,斩声。本义护城河,壕沟)", "example": null}, {"def": "同本义", "example": null}, {"def": "堑,防也。--《说文》", "example": null}, {"def": "堑山堙谷。--《史记·秦本纪》。索引绕城水也。", "example": null}, {"def": "深堑而守。--《史记·高祖纪》", "example": null}, {"def": "雙墙填堑。--《史记·司马相如传》", "example": null}, {"def": "又如堑渊(沟壑深潭);堑垒(深壕与堡垒);堑坎(深坑);堑谷(沉陷的坑谷);天堑", "example": null}, {"def": "挫折", "example": null}, {"def": "堑", "example": null}, {"def": "挖掘", "example": null}, {"def": "环而堑之。--《左传》。注沟堑也。”", "example": null}, {"def": "厕足而堑之。--《庄子·外物》。释文掘也。”", "example": null}, {"def": "堑qiàn", "example": null}, {"def": "⒈壕沟，护城河深～。沟～。天～变通途。", "example": null}, {"def": "⒉陷坑。〈喻〉挫折，吃亏吃一～，长一智。", "example": null}, {"def": "⒊挖沟环而～之。", "example": null}, {"def": "堑jiàn 1.低下。", "example": null}]','chinese-xinhua','0'),
('2101143296565841925','歉','1','qiàn','欠','14',NULL,'[{"def": "歉〈形〉", "example": null}, {"def": "(形声。从欠,兼声。本义吃不饱)", "example": null}, {"def": "同本义", "example": null}, {"def": "歉,食不满也。--《说文》", "example": null}, {"def": "健儿立霜雪,腹歉衣裳单。--李商隐《行次西郊作诗》", "example": null}, {"def": "收成不好", "example": null}, {"def": "一谷不升曰歉。--《广雅》", "example": null}, {"def": "又如歉荒(歉收;灾荒);歉俭(荒歉);歉薄(收成微薄)", "example": null}, {"def": "贫困", "example": null}, {"def": "惭愧。对不住人的心情", "example": null}, {"def": "俯仰谬恩方自歉。--王安石《酬吴季野见寄》", "example": null}, {"def": "又如抱歉(心中不安,觉着对不住别人);道歉;歉惜(遗憾与惋惜)", "example": null}, {"def": "少;不足", "example": null}, {"def": "歉,少也。╠", "example": null}, {"def": "歉qiàn", "example": null}, {"def": "⒈觉得对不起人抱～。道～。深表～意。", "example": null}, {"def": "⒉收成不好～年。荒～。大麦～收。", "example": null}, {"def": "⒊缺少，不足腹～衣裳单。", "example": null}]','chinese-xinhua','0'),
('2101143296565841926','嵌','1','qiàn','山','12',NULL,'[{"def": "嵌〈形〉", "example": null}, {"def": "(形声。本义山谷深的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "张开的样子", "example": null}, {"def": "金人仡仡其承钟虚兮,嵌岩岩其龙鳞。--《文选·扬雄·甘泉赋》", "example": null}, {"def": "嵌岩窦穴。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "险峻", "example": null}, {"def": "嵌 〈动〉", "example": null}, {"def": "镶嵌", "example": null}, {"def": "紧紧埋入", "example": null}, {"def": "下陷,凹陷", "example": null}, {"def": "嵌 〈名〉", "example": null}, {"def": "山洞,岩洞", "example": null}, {"def": "结庐就嵌窟,剪苕通径行。--唐·孟浩然《游明禅师", "example": null}, {"def": "嵌qiàn", "example": null}, {"def": "⒈填镶，将东西卡在空隙里～入。镶～。～花。", "example": null}, {"def": "⒉山石像张开的样子。", "example": null}, {"def": "嵌kàn 1.古地名用字。赤嵌，在今台湾台南市一带。", "example": null}]','chinese-xinhua','0'),
