('2101143296565841936','谴','1','qiǎn','讠','15',NULL,'[{"def": "谴", "example": null}, {"def": "(形声。本义责备,斥责)", "example": null}, {"def": "同本义", "example": null}, {"def": "谴,谪问也。--《说文》", "example": null}, {"def": "谴,呵也。--《苍颉篇》", "example": null}, {"def": "畏此谴怒。--《诗·小雅·小明》", "example": null}, {"def": "闻而谴友。--《孔子家语·五行》", "example": null}, {"def": "某时有客过而予汝金,因谴之。--《韩非子·外储说左上》", "example": null}, {"def": "前者,失救泾河老龙,获谴于我皇后帝。--《西游记》", "example": null}, {"def": "又如谴谪(责备);谴斥(受责备);谴告(谴责警告);谴呵(谴责申叱);谴咎(谴责罪过);谴怒(怒责)", "example": null}, {"def": "旧时官吏被贬或谪戍", "example": null}, {"def": "又不得已而谴,则为之择地而居。--刘禹锡《上杜司徒书》", "example": null}, {"def": "又如谴谪(官吏因罪降级,调往边", "example": null}, {"def": "谴qiǎn", "example": null}, {"def": "⒈责备～责。", "example": null}, {"def": "⒉〈古〉指官吏被贬谪承（受）朝～。", "example": null}]','chinese-xinhua','0'),
('2101143296565841937','缱','1','qiǎn','纟','16',NULL,'[{"def": "缱", "example": null}, {"def": "紧束;牵住", "example": null}, {"def": "偶然间心似缱,梅树边。--明·汤显祖《牡丹亭》", "example": null}, {"def": "缱", "example": null}, {"def": "用同纤”。拉船用的绳索", "example": null}, {"def": "来往不凭风力,归舟挽缱多至二十余人。--《天工开物》", "example": null}, {"def": "缱绻", "example": null}, {"def": "缱,缱绻,不相离也。--《说文新附》", "example": null}, {"def": "无纵诡随,以谨缱绻。--《诗·大雅》", "example": null}, {"def": "少尽缱绻。--唐·李朝威《柳毅传》", "example": null}, {"def": "以后对饮对唱,缠绵缱绻。--《红楼梦》", "example": null}, {"def": "缱qiǎn", "example": null}]','chinese-xinhua','0'),
('2101143296565841938','浅','1','qiǎn','氵','8',NULL,'[{"def": "浅", "example": null}, {"def": "通践”。实行,实现", "example": null}, {"def": "臣之梦浅矣。--《韩非子·难四》", "example": null}, {"def": "浅", "example": null}, {"def": "(形声。从水,戔声。本义水不深)", "example": null}, {"def": "同本义。与深”相对", "example": null}, {"def": "浅,不深也。--《说文》", "example": null}, {"def": "石濑兮浅浅。--《楚辞·湘君》", "example": null}, {"def": "审知卑城浅城而错守焉。--《墨子·备城门》", "example": null}, {"def": "水浅而舟大也。--《庄子·逍遥游》", "example": null}, {"def": "徐而察之,则山下皆石穴罅,不知其浅深。--宋·苏轼《石钟山记》", "example": null}, {"def": "河汉清且浅,相去复几许?--《古诗十九首》", "example": null}, {"def": "从上到下或从外到内距离小(跟深”相反)", "example": null}, {"def": "浅草才能没马蹄。--唐·白居易《钱塘湖春行》", "example": null}, {"def": "麦田浅鬣寸许", "example": null}, {"def": "浅（淺）jiān", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉\\"浅\\"另见qiǎn。", "example": null}, {"def": "浅（淺）qiǎn", "example": null}, {"def": "⒈从面到底或从外到里的距离小，跟\\"深\\"相对～井∮水～。巷道～。", "example": null}, {"def": "⒉不久，时间短年代～。结识的日子尚～。", "example": null}, {"def": "⒊程度不深，简明易懂～见。阅历～。学识～。功夫～。交情～。深入～出。", "example": null}, {"def": "⒋颜色淡～黄。～蓝。", "example": null}, {"def": "浅jiàn 1.灭，没。 2.通\\"践\\"。灭除;践踏。 3.通\\"諓\\"。参见\\"浅浅\\"。", "example": null}]','chinese-xinhua','0'),
