('2101143296565841978','芊','1','qiān','艹','6',NULL,'[{"def": "芊〈形〉", "example": null}, {"def": "草木茂盛的样子", "example": null}, {"def": "碧绿色", "example": null}, {"def": "芊绵，芊眠", "example": null}, {"def": "芊芊", "example": null}, {"def": "蚤是伤春梦雨天,可堪芳草更芊芊。--韦庄《长安清明》", "example": null}, {"def": "亦作阡阡”、仟仟”", "example": null}, {"def": "仰视山巅,肃何芊芊。--《文选·宋玉·高唐赋》", "example": null}, {"def": "芊qiān", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "芊qiàn 1.见\\"芊萰\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296565841979','迁','1','qiān','辶','6',NULL,'[{"def": "迁", "example": null}, {"def": "(形声。从辵,辵”表移动。形声字声旁有时有表意作用,此即一例。本义向高处迁移)", "example": null}, {"def": "同本义", "example": null}, {"def": "迁,登也。--《说文》", "example": null}, {"def": "迁,徙也。--《尔雅》", "example": null}, {"def": "迁,移也。--《广雅》", "example": null}, {"def": "既其女迁。--《诗·小雅·巷伯》", "example": null}, {"def": "出自幽谷,迁于乔马。--《诗·小雅·伐木》", "example": null}, {"def": "又如迁莺(指迁升飞翔的黄莺。喻登第)", "example": null}, {"def": "晋升或调动", "example": null}, {"def": "帝迁明德。--《诗·大雅·皇矣》", "example": null}, {"def": "迁至栘中。--《汉书·李广苏建传》", "example": null}, {"def": "迁为太史令。--《后汉书·张衡传》", "example": null}, {"def": "迁我如振落叶。--崔铣《记王忠肃公翱三事》", "example": null}, {"def": "迁淳安知县。--《明史》", "example": null}, {"def": "又如迁于乔木(比喻升", "example": null}, {"def": "迁（遷）qiān", "example": null}, {"def": "⒈搬移，换地点～移。～徙。～都。～厂。搬～。", "example": null}, {"def": "⒉改变变～。事（时）过境～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296565841980','佥','1','qiān','人','7',NULL,'[{"def": "佥", "example": null}, {"def": "(会意。从亼,从吅,从从。亼,集合。吅、从,都表示人多。本义皆,咸) 同本义", "example": null}, {"def": "佥,皆也。--《说文》", "example": null}, {"def": "佥曰于,鲧哉!”--《书·尧典》", "example": null}, {"def": "又如佥言(皆云;都说)", "example": null}, {"def": "佥", "example": null}, {"def": "众人;大家", "example": null}, {"def": "佥莈何忧。--《楚辞·天问》。注众也。”", "example": null}, {"def": "佥,夥也。--《方言十二》", "example": null}, {"def": "又如佥言(众人的意见);佥望(众望);佥谋(众人筹划);佥议(众人公开评议)", "example": null}, {"def": "佥", "example": null}, {"def": "连枷,打谷的农具", "example": null}, {"def": "《方言》佥”郭璞注今连枷,所以打谷者。”", "example": null}, {"def": "佥", "example": null}, {"def": "用同签”。签署", "example": null}, {"def": "汝等各自佥名,共成此事。--《三国演义》", "example": null}, {"def": "又如佥押(在", "example": null}, {"def": "佥（僱）qiān", "example": null}, {"def": "⒈都，皆～同。", "example": null}, {"def": "⒉众，大家以副～望（副符合）。", "example": null}]','chinese-xinhua','0'),
('2101143296565841981','岍','1','qiān','山','7',NULL,'[{"def": "岍〈名〉", "example": null}, {"def": "岍山,中国陕西省西南部陇山山脉的支脉", "example": null}, {"def": "导岍及岐至于荆山。--《书·禹贡》", "example": null}, {"def": "岍qiān［岍山］山名。在陕西省。", "example": null}]','chinese-xinhua','0'),
