('2101143296591007747','炝','1','qiànɡ','火','8',NULL,'[{"def": "炝", "example": null}, {"def": "烹饪方法", "example": null}, {"def": "将菜肴放在沸水中略煮,取出后再用酱油、醋等作料来拌。如炝蛤蜊;炝芹菜", "example": null}, {"def": "先把肉、葱等用热油略炒,再加作料和水煮。如炝锅肉丝面;用葱花儿炝炝锅", "example": null}, {"def": "用同呛”", "example": null}, {"def": "闻不得鼻口内干烟炝。--元·李好古《张生煮海》", "example": null}, {"def": "炝（熗）qiàng把菜肴放在沸水或热油中稍煮一下即取出，加作料拌～芹菜。", "example": null}]','chinese-xinhua','0'),
('2101143296591007748','唴','1','qiànɡ','','7',NULL,'[{"def": "唴qiàng 1.古代方言。哭泣不止或悲哭过度而无声。", "example": null}]','chinese-xinhua','0'),
('2101143296591007749','呛','1','qiànɡ','口','7',NULL,'[{"def": "呛", "example": null}, {"def": "鸟啄食物", "example": null}, {"def": "呛,鸟食。--《玉篇》", "example": null}, {"def": "呛", "example": null}, {"def": "愚笨", "example": null}, {"def": "呛", "example": null}, {"def": "有刺激性的气体进入嗅觉器官、呼吸器官或视觉器官,使人感觉难受", "example": null}, {"def": "受;又比喻说话有火气,生硬而尖刻);烟呛人;尘土呛人", "example": null}, {"def": "吃、喝或游泳时水或食物进入气管引起咳嗽又突然喷出", "example": null}, {"def": "难受", "example": null}, {"def": "受,忍受", "example": null}, {"def": "没出过远门,怕呛不住。--", "example": null}, {"def": "呛（嗆）qiàng有刺激性的气体使鼻子、嗓子等感到难受莫吸烟嘛，太～人了。辣椒味～得难受。", "example": null}, {"def": "呛（嗆）qiāng", "example": null}, {"def": "⒈水或食物等进入气管而引起咳嗽、不适慢点喂奶，别把小孩～着。", "example": null}, {"def": "⒉〈方〉咳嗽。", "example": null}, {"def": "呛chéng 1.见\\"呛啍\\"。", "example": null}, {"def": "呛qiǎng 1.见\\"呛白\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296591007750','抢','1','qiǎnɡ','扌','7',NULL,'[{"def": "抢", "example": null}, {"def": "撞;碰;触", "example": null}, {"def": "飞抢榆枋支遁。--《庄子·逍遥游》。注突也”", "example": null}, {"def": "抢,刺也。--《汉书·扬雄传》注", "example": null}, {"def": "以头抢地。--《战国策·魏策》", "example": null}, {"def": "抢呼欲绝。--《聊斋志异·促织》", "example": null}, {"def": "又如抢地(碰触地面。指叩头求饶);抢地呼天(以头撞地,悲呼苍天。形容极其伤痛);抢跪(屈一膝的半跪礼)", "example": null}, {"def": "推,搡", "example": null}, {"def": "逆;顶;挡", "example": null}, {"def": "创伤,伤", "example": null}, {"def": "足伤金距缩,头抢花冠翻。--唐·白居易《赎鸡》诗", "example": null}, {"def": "代替", "example": null}, {"def": "冲;闯", "example": null}, {"def": "抢出一条吊桶大小,雪花也似", "example": null}, {"def": "抢（搶）qiǎng", "example": null}, {"def": "⒈夺，硬拿～夺。～球。～劫。", "example": null}, {"def": "⒉赶快，争时间～先。～救。～收～种。", "example": null}, {"def": "⒊刮，擦（去掉表层）～菜刀。～猪皮。", "example": null}, {"def": "抢（搶）qiāng", "example": null}, {"def": "⒈通\\"戗\\"。逆，反方向。", "example": null}, {"def": "⒉碰，撞～壁。以头～地。", "example": null}, {"def": "抢qiàng 1.同\\"鎗\\"。在器物上填嵌金银等饰物。参见\\"抢金\\"。 2.同\\"呛\\"。因异物刺激气管引起气逆咳嗽。", "example": null}, {"def": "抢chéng 1.见\\"抢攘\\"。", "example": null}, {"def": "抢chēng 1.见\\"搀抢\\"。 2.美丽，漂亮。", "example": null}]','chinese-xinhua','0'),
('2101143296591007751','羟','1','qiǎnɡ','羊','11',NULL,'[{"def": "羟氨基", "example": null}, {"def": "羟基", "example": null}, {"def": "羟（羥）qiǎng", "example": null}, {"def": "羟qiān 1.羊名。", "example": null}]','chinese-xinhua','0'),
