('2101143296591007754','襁','1','qiǎnɡ','衤','17',NULL,'[{"def": "襁", "example": null}, {"def": "(形声。从衣,强声。本义婴儿的被子或布幅)", "example": null}, {"def": "同本义", "example": null}, {"def": "襁,负儿衣也。--《说文》", "example": null}, {"def": "曾孙虽在襁褓。--《汉书·宣帝纪》", "example": null}, {"def": "夫如是,则四方之民襁负其子而至矣。--《论语》", "example": null}, {"def": "又如襁抱(同襁褓,背婴儿用的布幅或系带);襁负(以布幅包裹幼儿于背上);襁褓物(指婴儿)", "example": null}, {"def": "泛指绳索", "example": null}, {"def": "古代一种捕捉老虎的器械", "example": null}, {"def": "又有设襁胶布制虎法。--方以智《物理小识》", "example": null}, {"def": "襁褓", "example": null}, {"def": "襁（纇）qiǎng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296591007755','羌','1','qiānɡ','羊','7',NULL,'[{"def": "羌", "example": null}, {"def": "(会意兼形声。从人,从羊,羊亦声。本义羌族,古代西部民族之一)", "example": null}, {"def": "同本义", "example": null}, {"def": "西戎牧羊人也。--《说文》", "example": null}, {"def": "庸蜀羌髳。--《书·牧誓》", "example": null}, {"def": "中国少数民族。主要聚居在四川省茂汶县、汶川县、松潘县境内", "example": null}, {"def": "西戎", "example": null}, {"def": "羌笛", "example": null}, {"def": "羌笛", "example": null}, {"def": "羌qiāng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉〈古〉我国西部的一个少数民族，居住区域在今四川、甘肃、青海一带。东晋时曾经建立后秦。", "example": null}]','chinese-xinhua','0'),
('2101143296591007756','戕','1','qiānɡ','戈','8',NULL,'[{"def": "戕〈动〉", "example": null}, {"def": "(会意。从戈,从爿。戈,古代用以横击、钩杀的重要武器。爿,劈开的竹木片。本义残杀、杀害)", "example": null}, {"def": "同本义", "example": null}, {"def": "戕汝家矣。--明·高启《书博鸡者事》", "example": null}, {"def": "又如自戕(自杀);戕虐(残暴;残害);戕杀(残杀,损伤)", "example": null}, {"def": "毁坏", "example": null}, {"def": "伤害", "example": null}, {"def": "戕身损寿。--《亢仓子·用道》", "example": null}, {"def": "又如戕扰(伤害骚扰);戕生(伤害生命);戕夷(伤害摧残);戕伐(伤害;自残,指纵欲”)", "example": null}, {"def": "戕害", "example": null}, {"def": "至于五彪,有谓田尔耕、许显纯、孙云鹤、崔应元、杨寰等,狐假鸱张,戕害多命。--《梼杌闲评--明珠缘》", "example": null}, {"def": "戕贼", "example": null}, {"def": "戕qiāng", "example": null}, {"def": "⒈残杀，杀害～害。自相～。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296591007757','戗','1','qiānɡ','戈','8',NULL,'[{"def": "戗", "example": null}, {"def": "逆,不顺", "example": null}, {"def": "冲突,决裂", "example": null}, {"def": "两个说戗了,揪着领子,一顿乱打。--《儒林外史》", "example": null}, {"def": "戗（戧）qiàng", "example": null}, {"def": "⒈支持，支撑～住，不能倒下。", "example": null}, {"def": "⒉", "example": null}, {"def": "戗（戧）qiāng", "example": null}, {"def": "⒈逆，反方向～水。～风。", "example": null}, {"def": "⒉决裂，言语冲突话说～了。", "example": null}, {"def": "戗chuāng", "example": null}]','chinese-xinhua','0'),
