('2101143296591007796','俏','1','qiào','亻','9',NULL,'[{"def": "俏〈形〉", "example": null}, {"def": "(形声。从人,肖声。本义相貌美好)", "example": null}, {"def": "同本义", "example": null}, {"def": "俏", "example": null}, {"def": "灵巧", "example": null}, {"def": "有利可图", "example": null}, {"def": "没点胆子哪能找到这么俏的事!--老舍《骆驼祥子》", "example": null}, {"def": "货物销路好", "example": null}, {"def": "这一批货,现在可俏得很呢!--茅盾《霜叶红似二月花》", "example": null}, {"def": "俏 〈动〉", "example": null}, {"def": "通肖”。相似", "example": null}, {"def": "佹佹成者,俏成也,初非成也;佹佹败者,俏", "example": null}, {"def": "俏qiào", "example": null}, {"def": "⒈漂亮，貌美～丽。俊～。", "example": null}, {"def": "⒉货物销路好～货。", "example": null}, {"def": "⒊〈方〉烹饪时加上少量香菜、木耳或蒜苗等，以增加色泽、味道～荤菜。", "example": null}, {"def": "⒋", "example": null}, {"def": "俏xiào 1.象;似。", "example": null}]','chinese-xinhua','0'),
('2101143296591007797','诮','1','qiào','讠','9',NULL,'[{"def": "诮", "example": null}, {"def": "(形声。从言,肖声。《说文》作谯”。本义责备)", "example": null}, {"def": "同本义", "example": null}, {"def": "诮,呵也。--《龙龛手鉴》", "example": null}, {"def": "丈人归,酒醒而诮其子。--《吕氏春秋·疑似》", "example": null}, {"def": "又如诮责(责备;谴责);诮诘(责问);诮噪(谴责和讥刺);诮让(责问);诮斥(斥责);诮项(指樊哙在鸿门宴上斥责项羽之事)", "example": null}, {"def": "嘲讽", "example": null}, {"def": "列壑争讥,攒峰竦诮。--孔稚圭《北山移文》", "example": null}, {"def": "又如诮谤(讥诮毁谤);讥诮(冷言冷语地讥讽);诮骂(讥笑谩骂);诮讽(讥笑讽刺);诮戏(嘲笑逗乐);诮辱(讥讽侮辱)", "example": null}, {"def": "诮", "example": null}, {"def": "简直,完全", "example": null}, {"def": "诮qiào", "example": null}, {"def": "⒈讥讽讥～。", "example": null}, {"def": "⒉责备，谴责～他几句。", "example": null}]','chinese-xinhua','0'),
