('2101143296591007817','悄','1','qiāo','忄','10',NULL,'[{"def": "悄悄", "example": null}, {"def": "悄悄离开", "example": null}, {"def": "他悄悄地全跟我说了", "example": null}, {"def": "悄悄话", "example": null}, {"def": "开会不准说悄悄话", "example": null}, {"def": "悄〈形〉", "example": null}, {"def": "(形声。从心,肖声。本义忧愁的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "悄,忧也。--《说文》", "example": null}, {"def": "忧心悄悄。--《诗·邶风·柏舟》", "example": null}, {"def": "劳心悄兮。--《诗·陈风·月出》", "example": null}, {"def": "诀后悄切。--《文选·潘岳·笙赋》", "example": null}, {"def": "又如悄切(形容声音忧愁凄切);悄怆(哀伤,忧伤);悄悄(忧愁的样子);悄悒(因思念而忧郁);悄戚(悲痛忧伤)", "example": null}, {"def": "寂静无声", "example": null}, {"def": "悄qiǎo", "example": null}, {"def": "⒈忧愁～然落泪。～ ～令人悲。", "example": null}, {"def": "⒉静，低声或无声～ ～话。～然无声。", "example": null}, {"def": "悄qiāo寂静，没有声音或声音很低深夜静～ ～。他～ ～地起床了。", "example": null}]','chinese-xinhua','0'),
('2101143296591007818','硗','1','qiāo','石','11',NULL,'[{"def": "硗", "example": null}, {"def": "(形声。从石,尧声。本义土地坚硬而瘠薄)", "example": null}, {"def": "同本义", "example": null}, {"def": "硗,磐石也。字亦作墝。--《说文》", "example": null}, {"def": "则地有肥硗。--《孟子》。注薄也。”", "example": null}, {"def": "瘠硗之地。--《国语·楚语》", "example": null}, {"def": "又如硗薄(土地坚硬而不肥沃);硗瘠(土地坚硬而贫瘠);硗秃(贫瘠多石不生草木之地)", "example": null}, {"def": "高低不平", "example": null}, {"def": "坚硬", "example": null}, {"def": "田者争处墝埆。--《淮南子·原道》", "example": null}, {"def": "物坚硬谓之硗埆。--《通俗文》", "example": null}, {"def": "又如硗确(坚石;多石而坚硬的路)", "example": null}, {"def": "恶坏", "example": null}, {"def": "薄", "example": null}, {"def": "硗（磽）qiāo土地坚硬而贫瘠～薄。～瘠。～土。", "example": null}, {"def": "硗qiào 1.土地不平。", "example": null}]','chinese-xinhua','0'),
('2101143296591007819','跷','1','qiāo','足','13',NULL,'[{"def": "跷", "example": null}, {"def": "(形声。从足,尧声。本义举足)", "example": null}, {"def": "同本义", "example": null}, {"def": "躥,举足行高也。从足,喬声。--《说文》", "example": null}, {"def": "可躥足而待也。--《汉书·高帝纪》", "example": null}, {"def": "莫不躥足抗首。--扬雄《长杨赋》", "example": null}, {"def": "又如跷蹄辇脚(高举脚,轻落足);跷着腿坐着;跷足(举足);跷腿(抬脚举步)", "example": null}, {"def": "竖起", "example": null}, {"def": "踮起脚后跟", "example": null}, {"def": "跷起脚来,把一个一个脸面都看遍,哪个也不是菊英。--赵树理《三里湾》", "example": null}, {"def": "又如跷足(踮起脚跟)", "example": null}, {"def": "跛", "example": null}, {"def": "他一跷一拐地努力走着。--茅盾《脱险杂记》", "example": null}, {"def": "又如跷足(跛足);跷脚(跛足;瘸腿)", "example": null}, {"def": "用同", "example": null}, {"def": "跷（躤、躥）qiāo举足，竖起～脚。～腿。～起大拇指。", "example": null}]','chinese-xinhua','0'),
