('2101143296599396411','擎','1','qínɡ','手','16',NULL,'[{"def": "擎〈动〉", "example": null}, {"def": "举", "example": null}, {"def": "与翠叶并擎。--明·李渔《亲情偶寄·种植部》", "example": null}, {"def": "又如擎赍(拿着);擎奇(举,持);擎拳(举拳);众擎易举", "example": null}, {"def": "支撑,承受住压力", "example": null}, {"def": "力量)", "example": null}, {"def": "执持", "example": null}, {"def": "今朝擎剑去,何日刺蛟回?--李贺《送秦光禄北征诗》", "example": null}, {"def": "拱手", "example": null}, {"def": "擎qíng举，向上托～拳撑脚。一柱～天。众～易举。", "example": null}]','chinese-xinhua','0'),
('2101143296599396412','檠','1','qínɡ','木','16',NULL,'[{"def": "檠", "example": null}, {"def": "( 形声。从木,敬声。本义矫正弓弩的器具)", "example": null}, {"def": "同本义", "example": null}, {"def": "檠,榜也。…弛弓防损伤,以竹若木辅于里绳约之。--《说文》", "example": null}, {"def": "不能绁檠巧用。--《诗·角弓》传", "example": null}, {"def": "檠不正而可以正弓。--《淮南子·说山》", "example": null}, {"def": "弓待檠而后能调。--《淮南子·脩务》", "example": null}, {"def": "檠弓弩。--《汉书·苏武传》", "example": null}, {"def": "又如檠枻(矫正弓弩的器具);檠榜( 矫正弓弩的器具)", "example": null}, {"def": "灯台", "example": null}, {"def": "梦断酒醒山雨绝,笑看饥鼠上灯檠。--苏轼《侄安节远来夜坐》", "example": null}, {"def": "灯", "example": null}, {"def": "投僧避夜雨,古檠昏无膏。--王安石《自州追送朱氏女弟》", "example": null}, {"def": "檠qíng", "example": null}, {"def": "⒈灯架灯～。也指灯孤～（孤灯）。", "example": null}, {"def": "⒉矫正弓弩的器具。", "example": null}, {"def": "檠jìng 1.有脚的盘碟。", "example": null}]','chinese-xinhua','0'),
('2101143296599396413','黥','1','qínɡ','黑','20',NULL,'[{"def": "黥", "example": null}, {"def": "(会意。从黑,京声。刻其面以墨窒之。字亦作剠”。本义古代一种肉刑,墨刑的异称)", "example": null}, {"def": "刺字", "example": null}, {"def": "黥,墨刑在面也。--《说文》", "example": null}, {"def": "放黥者马竿人面也。--《书·刑德》", "example": null}, {"def": "又如黥首刖足(刻额染墨,截断双脚);黥布(英布,汉高祖的大将、功臣。因犯罪被黥面);黥首(汉代刑法之一。其法在罪人额上刻字染墨);黥面(在脸上刺字涂墨);黥徒(受黥刑", "example": null}, {"def": "的犯人。引申泛指囚徒,罪犯)", "example": null}, {"def": "镌刻", "example": null}, {"def": "声明走百灵,结构黥幽谷。--清·魏源《白岳东崖》", "example": null}, {"def": "黥 〈名〉", "example": null}, {"def": "受过黥刑的人", "example": null}, {"def": "自唐失其政,天下乘", "example": null}, {"def": "黥（剠）qíng", "example": null}, {"def": "⒈〈古〉在犯人面额刺刻涂墨的酷刑，又叫\\"墨刑\\"。", "example": null}, {"def": "⒉在人身上刺成带颜色的花纹、图形或文字。", "example": null}]','chinese-xinhua','0'),
('2101143296599396414','磬','1','qìnɡ','石','16',NULL,'[{"def": "磬〈名〉", "example": null}, {"def": "(象形。甲骨文字形。手又持小槌像击磬的形象。本义古代乐器。用石或玉雕成。悬挂于架上,击之而鸣)", "example": null}, {"def": "同本义", "example": null}, {"def": "磬,乐石也。--《说文》", "example": null}, {"def": "小华之山多磬石。--《山海经·西山经》", "example": null}, {"def": "泗滨浮磬。--《书·禹贡》", "example": null}, {"def": "笙磬同音。--《诗·小雅·鼓钟》", "example": null}, {"def": "依我磬声。--《诗·商颂·那》", "example": null}, {"def": "语寡人以忧者击磬。--《淮南子·泛论》", "example": null}, {"def": "钟磬置于水中。--宋·苏轼《石钟山记》", "example": null}, {"def": "西门豹簪笔磬折,向河立待良久。--《西门豹治邺》", "example": null}, {"def": "又如磬人(负责治磬的官员);磬工(负责制磬的官员);磬色(玉磬的光彩);磬师(古乐官名)", "example": null}, {"def": "磬qìng", "example": null}, {"def": "⒈〈古〉一种石或玉制的敲击乐器，悬在架上，形似曲尺。", "example": null}, {"def": "⒉寺庙中和尚敲打的铜铁铸的鸣器，形状似钵敲～声。", "example": null}, {"def": "磬qīng 1.古代打击乐器。状如曲尺。用玉﹑石或金属制成。悬挂于架上，击之而鸣。 2.适宜制磬的美石。 3.寺院中召集众僧用的云板形鸣器或诵经用的钵形打击乐器。", "example": null}, {"def": "4.南齐时报更用的响器◇因以借指时钟。 5.弯腰。表示谦恭。 6.泛指身形曲折如磬。 7.形容鸣声如击磬。 8.放马疾驰。参见\\"磬控\\"。 9.古死刑之一。悬而缢杀。", "example": null}, {"def": "10.副词。方言。适才。参见\\"盘子\\"。 11.通\\"俔\\"。譬如，如同。 12.通\\"罄\\"。空，中空。 13.通\\"罄\\"。尽，罄尽。 14.通\\"罄\\"。全;遍。参见\\"磬地\\"。 15.通\\"罄\\"。", "example": null}, {"def": "形容声音坚致。 16.通\\"謦\\"。轻声咳嗽。参见\\"磬欬\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296599396415','罄','1','qìnɡ','缶','17',NULL,'[{"def": "罄〈形〉", "example": null}, {"def": "(形声。本义器中空)", "example": null}, {"def": "同本义", "example": null}, {"def": "罄,器中空也。--《说文》", "example": null}, {"def": "缾之罄矣。--《诗·小雅·蓼莪》", "example": null}, {"def": "罄无不宜。--《诗·小雅·天保》", "example": null}, {"def": "又如罄身人(身无分文的人);罄然(空无一物的样子);罄身(空着身子)", "example": null}, {"def": "严整", "example": null}, {"def": "师旷罄然。--《周书·太子晋》", "example": null}, {"def": "又如罄然(严肃整饬的样子)", "example": null}, {"def": "满;全", "example": null}, {"def": "罄 〈动〉", "example": null}, {"def": "用尽;消耗殆尽", "example": null}, {"def": "罄,尽也。--《尔雅》", "example": null}, {"def": "罄南山之竹,书罪未穷。--《旧唐书·李密传》", "example": null}, {"def": "罄qìng", "example": null}, {"def": "⒈器皿空瓶已～。", "example": null}, {"def": "⒉尽，用尽告～。粟～。～竹难书（诉说书写不完，多指罪恶）。", "example": null}]','chinese-xinhua','0'),
('2101143296599396416','櫦','1','qìnɡ','','6',NULL,'[{"def": "櫦qing", "example": null}, {"def": "⒈义未详。", "example": null}]','chinese-xinhua','0'),
('2101143296599396417','庆','1','qìnɡ','广','6',NULL,'[{"def": "庆", "example": null}, {"def": "(会意。甲骨文字形,左边是个文”字,中间有个心,表示心情诚恳;右边是一张鹿皮∠起来表示带着鹿皮,真诚地对人庆贺。小篆字形上面是鹿字省略一部分;中间是心”字", "example": null}, {"def": ",表心意;下边是攵”,表示往”。意思跟甲骨文相同。本义棕;庆贺)", "example": null}, {"def": "同本义", "example": null}, {"def": "庆,行贺人也。…吉礼以鹿皮为挚,故从鹿省。--《说文》。段注谓心所喜而行也。”", "example": null}, {"def": "庆,贺也。--《广雅·释言》", "example": null}, {"def": "庆子家驹。--《公羊传·昭公二十五年》", "example": null}, {"def": "故庆其喜。--《国语·鲁语》", "example": null}, {"def": "是以有庆矣。--《诗·小雅·裳者华》", "example": null}, {"def": "蜀遣卫尉陈震庆权践位。╠", "example": null}, {"def": "庆（慶）qìng", "example": null}, {"def": "⒈棕～祝。～贺。～丰收。～功大会。", "example": null}, {"def": "⒉可棕的事佳～。国～。喜～。", "example": null}, {"def": "庆qiāng 1.发语词。", "example": null}]','chinese-xinhua','0'),
