('2101143296599396421','箐','1','qìnɡ','竹','14',NULL,'[{"def": "箐〈名〉", "example": null}, {"def": "山间大竹林。竹木丛生的山谷", "example": null}, {"def": "林中的山洞);箐砦(竹木丛中的山寨);箐道(竹木丛中的山路)", "example": null}, {"def": "箐qìng〈方〉山间的大竹林。泛指竹木丛生的山谷。", "example": null}, {"def": "箐jīng 1.小笼。", "example": null}, {"def": "箐qiāng 1.细竹名。", "example": null}]','chinese-xinhua','0'),
('2101143296599396422','苘','1','qǐnɡ','艹','8',NULL,'[{"def": "苘麻", "example": null}, {"def": "和温带地方作为逸生植物被广泛归化", "example": null}, {"def": "苘（檾）qǐng", "example": null}]','chinese-xinhua','0'),
('2101143296599396423','顷','1','qǐnɡ','页','8',NULL,'[{"def": "顷", "example": null}, {"def": "(会意。从匕,从页。匕有排列比较义,也有不正之义。页,头∠起来表示头偏。本义头不正)", "example": null}, {"def": "同本义", "example": null}, {"def": "顷,头不正也。--《说文》。段玉裁注顷者,头也。”徐灏注顷、倾古今字。”", "example": null}, {"def": "通倾”。倾斜;偏侧", "example": null}, {"def": "妇人擅国兹谓顷。--《汉书·五行志》", "example": null}, {"def": "不盈顷筐。--《诗·周南·卷耳》", "example": null}, {"def": "又如 顷筐(倾斜口的竹筐。形似今之畚箕);顷危(倾斜而危险);顷宫(十分高大的宫殿);顷倒(倒下)", "example": null}, {"def": "頃顷", "example": null}, {"def": "田地面积的单位,等于一百亩", "example": null}, {"def": "凡为田一顷十二亩半。--《", "example": null}, {"def": "顷qǐng", "example": null}, {"def": "⒈地积单位。1百市亩＝1市～＝6.6667公～。", "example": null}, {"def": "⒉时间短，跟\\"久\\"相对～刻。俄～。有～。少～。", "example": null}, {"def": "⒊刚才～闻。～接家书。", "example": null}, {"def": "⒋〈古〉通\\"倾\\"。侧，斜～耳。", "example": null}, {"def": "顷qīng 1.同\\"倾\\"。头不正。 2.同\\"倾\\"。倾斜;偏侧。 3.同\\"倾\\"。倾注。 4.同\\"倾\\"。倾覆。 5.同\\"倾\\"。古指妇人专擅国政。谓不正规，非正统。 6.姓『代有顷宪", "example": null}, {"def": "。见《印薮》。", "example": null}]','chinese-xinhua','0'),
('2101143296599396424','请','1','qǐnɡ','讠','10',NULL,'[{"def": "请", "example": null}, {"def": "通情”。情况,实情", "example": null}, {"def": "上下请通。--《墨子·尚同中》", "example": null}, {"def": "四璧而知请。--《管子·白心》", "example": null}, {"def": "请", "example": null}, {"def": "(形声。从言,青声。本义拜访)", "example": null}, {"def": "同本义", "example": null}, {"def": "请,谒也。--《说文》", "example": null}, {"def": "使人为秋请。--《史记·吴王濞传》。集解引律云秋曰请。”", "example": null}, {"def": "不得入朝请『律盖改周礼之觐为请也。--《史记·魏其武安侯传》", "example": null}, {"def": "公子往,数请之,朱亥故不复谢。--《史记·魏公子列传》", "example": null}, {"def": "公卿相造请禹。--《史记·酷吏列传》", "example": null}, {"def": "又如请谒(拜见)", "example": null}, {"def": "请求;要求", "example": null}, {"def": "请,求也。--《广雅", "example": null}, {"def": "请qǐng", "example": null}, {"def": "⒈求，请求～示。～假。～命。～战。", "example": null}, {"def": "⒉敬词。用于动词前～进。～坐。～喝茶。", "example": null}, {"def": "⒊邀请，邀约，延聘～客。～医师。～专家指导。聘～教师。", "example": null}, {"def": "⒋", "example": null}, {"def": "请qìng 1.朝会名。", "example": null}, {"def": "请qíng 1.后又作\\"?\\"。认领;接受。 2.通\\"情\\"。实情;情况。 3.通\\"情\\"。实在;的确。 4.通\\"情\\"。情感。", "example": null}, {"def": "请qīng 1.参见\\"请靓\\"﹑\\"请室\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296599396425','謦','1','qǐnɡ','言','18',NULL,'[{"def": "謦欬", "example": null}, {"def": "利喉曰謦欬--《通俗文》", "example": null}, {"def": "行路过者,稍顾视謦欬皆呵止也。--陆游《老学庵笔记》", "example": null}, {"def": "昆弟亲戚之謦欬。--《庄子·徐无鬼》", "example": null}, {"def": "隔颜色而可亲謦欬。--《清史稿》", "example": null}, {"def": "謦qǐng", "example": null}]','chinese-xinhua','0'),
('2101143296599396426','青','1','qīnɡ','青','8',NULL,'[{"def": "青〈形〉", "example": null}, {"def": "(会意。从生,从丹。金文字形上面是个生”字;下面是丹”字,丹是井字之变。青”是汉字部首之一。本义蓝色)", "example": null}, {"def": "同本义", "example": null}, {"def": "青,东方色也。--《说文》", "example": null}, {"def": "正东曰青州。--《周礼·职方氏》", "example": null}, {"def": "时则有青眚青祥。--《洪范五行传》。注木色也。”", "example": null}, {"def": "其色青。--《素问·风论》。注肝色。”", "example": null}, {"def": "掌凡金玉锡石丹青之戒令。--《周礼·职金》。注青,空青也。”", "example": null}, {"def": "青取之于蓝,而青于蓝。--《荀子·劝学》", "example": null}, {"def": "又如青磷(磷火。俗称鬼火);青靛(深蓝色);青焰焰(青蓝色);青云万里(比喻前程远大);青云干吕(庆云翔集,应乎六吕。是一种吉", "example": null}, {"def": "青qīng", "example": null}, {"def": "⒈颜色", "example": null}, {"def": "①深蓝色～天。～，取之于蓝，而～于蓝。", "example": null}, {"def": "②深绿色～草。草色入簾～。", "example": null}, {"def": "③黑色～线。～布。", "example": null}, {"def": "⒉深绿色的东西，多指嫩苗的庄稼、花草等看～。踏～。～苗。～黄不接（新苗未成熟，陈粮已经吃完。〈喻〉暂时缺乏或前后接不上）。", "example": null}, {"def": "⒊〈喻〉年轻，也指青年～春。～工。共～团。老中～。", "example": null}, {"def": "⒋", "example": null}, {"def": "青jīng 1.见\\"青青\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296599396427','氢','1','qīnɡ','气','9',NULL,'[{"def": "氢", "example": null}, {"def": "化学元素名。一价非金属元素。在正常情况下,氢是无色、无臭、极易燃烧的双原子气体,在地球上和地球大气中只存在极稀少的游离状态氢", "example": null}, {"def": "氢（氫）qīng化学元素。符号h。它是现在所知元素中最轻的。通常条件下为气体，无色，无臭，无味，化学性质较活泼，与氧化合成水。工业上用途广泛，液态氢可用作高能", "example": null}, {"def": "燃料。", "example": null}]','chinese-xinhua','0'),
('2101143296599396428','轻','1','qīnɡ','车','9',NULL,'[{"def": "轻", "example": null}, {"def": "(形声。本义车名)", "example": null}, {"def": "轻车", "example": null}, {"def": "轻,轻车也。--《说文》。段玉裁注轻本车名,故字从车。引申为凡轻重之轻。”", "example": null}, {"def": "轻车之萃。谓驰敌致师之车也。--《周礼·车仆》", "example": null}, {"def": "使轻车锐骑冲雍门。--《战国策·齐策》", "example": null}, {"def": "轻工业的简称", "example": null}, {"def": "化学元素氢的旧译", "example": null}, {"def": "轻 ?", "example": null}, {"def": "分量不大。与重”相对", "example": null}, {"def": "轻重同。--《孟子》。注谓斤两。”", "example": null}, {"def": "权然后知轻重,度然后知长短。--《孟子》", "example": null}, {"def": "渭城朝雨浥轻尘。--唐·王维《送元二使安西》", "example": null}, {"def": "又如轻单(", "example": null}, {"def": "轻（輕）qīng", "example": null}, {"def": "⒈份量小，跟\\"重\\"相对这张桌子较～。～于鸿毛。", "example": null}, {"def": "⒉数量少，程度浅工作～。～伤。", "example": null}, {"def": "⒊用力小～放。～声。", "example": null}, {"def": "⒋认为无所谓，不重要～敌。～视。", "example": null}, {"def": "⒌随便，不庄重～易。～率。～佻。", "example": null}, {"def": "⒍浅薄，便当～微。～便。～舟已过万重山。", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
('2101143296599396429','倾','1','qīnɡ','亻','10',NULL,'[{"def": "倾", "example": null}, {"def": "(会意兼形声。从人,从顷,顷亦声。顷”有偏侧的意思。从人,多表示人的动作行为。本义偏侧)", "example": null}, {"def": "同本义", "example": null}, {"def": "倾,仄也。--《说文》", "example": null}, {"def": "倾则奸。--《礼记·曲礼下》。注倾或为侧。”疏倾,欹侧也。”", "example": null}, {"def": "安无倾。--《论语·季氏》", "example": null}, {"def": "重钧则衡不倾。--《淮南子·说山》", "example": null}, {"def": "日既西倾。--曹植《洛神赋》", "example": null}, {"def": "倾耳而听。--《战国策·秦策》", "example": null}, {"def": "高下相倾。--《老子》。释文不正貌。”", "example": null}, {"def": "俯身倾耳。--明·宋濂《送东阳马生序》", "example": null}, {"def": "又如倾葵(向日葵。借指尽忠);倾倚(偏斜不正);倾低(倾斜,歪斜);倾昃(偏斜;不正);倾返(形", "example": null}, {"def": "倾qīng", "example": null}, {"def": "⒈侧，斜，歪～耳。～斜。前～。", "example": null}, {"def": "⒉（政治思想上的）趋向，偏向～向。左～。右～。", "example": null}, {"def": "⒊倒塌～覆。～颓。", "example": null}, {"def": "⒋倒出，竭尽～诉。～箱倒箧。～其全力。", "example": null}, {"def": "⒌钦佩，爱慕～慕。一座尽～（一座满座的人）。", "example": null}, {"def": "⒍相互排挤～轧。以利相～。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①斜倒墙壁～倒。", "example": null}, {"def": "②佩服，钦佩令人～倒。", "example": null}, {"def": "③倒出把这筐果皮、纸屑～倒在垃圾箱里。", "example": null}, {"def": "倾qǐng 1.顷，不久。", "example": null}]','chinese-xinhua','0'),
('2101143296599396430','卿','1','qīnɡ','卩','10',NULL,'[{"def": "卿〈名〉", "example": null}, {"def": "(会意。甲骨文字形,像二人向食之形。《说文》从卯,皂声。”卯,事之制也。”本义飨食)", "example": null}, {"def": "古时高级长官或爵位的称谓『以前有六卿,汉设九卿,北魏在正卿下还有少卿。以后历代相沿,清末始废", "example": null}, {"def": "卿,六卿。天官冢宰、地官司徒、春官宗伯、夏官司马、秋官司寇、冬官司空也。--《说文》", "example": null}, {"def": "诸侯之上大夫卿。--《礼记·王制》。注上大夫曰卿。”", "example": null}, {"def": "卿大夫豹饰。--《管子·揆度》", "example": null}, {"def": "大国三卿,皆命于天子;次国三卿,二卿命于天子,一卿命于其君;小国二卿,皆命于其君。--《礼记·王制", "example": null}, {"def": "卿qīng", "example": null}, {"def": "⒈〈古〉高级官名。在公之下，大夫之上～相。上～。三公九～。", "example": null}, {"def": "⒉〈古〉君对臣，长辈对晚辈的称呼爱～。", "example": null}, {"def": "⒊旧时对朋友、夫对妻或夫妻间表示亲热的称呼。", "example": null}]','chinese-xinhua','0'),
('2101143296599396431','圊','1','qīnɡ','囗','11',NULL,'[{"def": "圊〈名〉", "example": null}, {"def": "茅厕,厕所", "example": null}, {"def": "圊 〈动〉", "example": null}, {"def": "清除", "example": null}, {"def": "圊qīng厕所～土。", "example": null}]','chinese-xinhua','0'),
