('2101143296599396451','邛','1','qiónɡ','阝','5',NULL,'[{"def": "邛〈名〉", "example": null}, {"def": "故地名。邛城", "example": null}, {"def": "邛,邛地在济阴县。从邑,工声。按汉书外戚侯表,邛城属济阴,此地字盖城字之误。…在今山东东昌府。--《说文通训定声》", "example": null}, {"def": "中国古州名", "example": null}, {"def": "山名。即邛崃山", "example": null}, {"def": "匪其止共,维王之邛。--《诗·小雅·巧言》", "example": null}, {"def": "邛 qióng邛崃山，邛崃市，均在四川省。", "example": null}]','chinese-xinhua','0'),
('2101143296599396452','穷','1','qiónɡ','穴','7',NULL,'[{"def": "穷", "example": null}, {"def": "(形声。从穴,躬声。躬,身体,身在穴下,很窘困。简化字为会意,力在穴下,有劲使不出。本义穷尽,完结)", "example": null}, {"def": "同本义", "example": null}, {"def": "穷,极也。--《说文》", "example": null}, {"def": "穷,竟也。--《小尔雅·广诂》", "example": null}, {"def": "横四海兮焉穷?--《楚辞·九歌·云中君》", "example": null}, {"def": "赤水穷焉。--《山海经·大荒南经》。注流极于此山也。”", "example": null}, {"def": "与物变化而无所终穷。--《吕氏春秋·下贤》", "example": null}, {"def": "穷高极远,而测深厚。--《礼记·乐记》", "example": null}, {"def": "儒有博学而不穷。--《礼记·儒行》", "example": null}, {"def": "图穷而匕首见。--《战国策·燕策》", "example": null}, {"def": "欲穷其林。--晋·陶渊明《桃花源记》", "example": null}, {"def": "欲穷千里目,更上一层楼。--唐·王之", "example": null}, {"def": "穷（竑）qióng", "example": null}, {"def": "⒈不得志，不显贵，跟\\"达\\"相对～不失义。", "example": null}, {"def": "⒉阻塞，不通，走投无路，跟\\"通\\"相对日暮途～。追～寇。", "example": null}, {"def": "⒊生活、处境困难～苦。～困。～则思变。", "example": null}, {"def": "⒋尽，完结理屈词～。无～无尽。", "example": null}, {"def": "⒌极端，彻底推究～凶极恶。～根究底。", "example": null}, {"def": "穷gōng 1.身体。", "example": null}]','chinese-xinhua','0'),
('2101143296603590656','穹','1','qiónɡ','穴','8',NULL,'[{"def": "穹 〈形〉", "example": null}, {"def": "(形声。从穴,弓声。本义穷尽)", "example": null}, {"def": "同本义", "example": null}, {"def": "穹,穷也。从穴,弓声。--《说文》", "example": null}, {"def": "又如穹窒(完全堵塞)", "example": null}, {"def": "高", "example": null}, {"def": "郁并起而穹崇。--司马相如《长门赋》", "example": null}, {"def": "又如穹枝(犹高枝);穹穹(高大的样子);穹官(高官);穹居(高大的住所);穹宫(高大的宫室,祠堂)", "example": null}, {"def": "大", "example": null}, {"def": "穹,大也。--《尔雅·释诂》。注穹隆亦为大也。”", "example": null}, {"def": "穹崖巨谷。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "又如穹石(大岩石);穹穹(高而大貌);穹龟(大龟)", "example": null}, {"def": "漫远", "example": null}, {"def": "深", "example": null}, {"def": "穹〈名", "example": null}, {"def": "穹qióng", "example": null}, {"def": "⒈隆起成拱形的～隆。也指天苍～。", "example": null}, {"def": "⒉大～石。", "example": null}, {"def": "⒊深～谷。", "example": null}]','chinese-xinhua','0'),
('2101143296603590657','茕','1','qiónɡ','艹','8',NULL,'[{"def": "茕", "example": null}, {"def": "回旋着飞", "example": null}, {"def": "茕,回飞也。从凡,煢省声。鸟回转疾飞曰茕。--《说文》", "example": null}, {"def": "孤独,无兄弟", "example": null}, {"def": "无虐茕独。--《书·洪范》。传单无兄弟也。”", "example": null}, {"def": "哀此茕独。--《诗·小雅·正月》", "example": null}, {"def": "夫何茕独而不余听。--《离骚》。注孤也。”", "example": null}, {"def": "如茕子(孤儿);茕孑(孤单);茕困(孤苦);茕妻(寡妇);茕疚(因孤单而感忧伤);茕居(寡居)", "example": null}, {"def": "悲愁", "example": null}, {"def": "神茕茕以遥思兮,…。--《汉书》", "example": null}, {"def": "茕（煢、惸）qióng", "example": null}, {"def": "⒈没有弟兄，孤独～独。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊忧愁。", "example": null}]','chinese-xinhua','0'),
