('2101143296607785040','阒','1','qù','门','12',NULL,'[{"def": "阒", "example": null}, {"def": "寂静", "example": null}, {"def": "林塘闻寂偏宜夜,烟火稀疏便似村。--《曲江夜思》", "example": null}, {"def": "又如阒静(寂静);阒无人声(静得没有一点人声);阒寥(寂静);阒黑(漆黑)", "example": null}, {"def": "空虚", "example": null}, {"def": "窥其户,阒其无人。--《易·丰》", "example": null}, {"def": "如阒旷(空阔);阒如(空虚);阒其无人(空荡荡无人)", "example": null}, {"def": "阒寂", "example": null}, {"def": "阒寂的原野", "example": null}, {"def": "阒然", "example": null}, {"def": "庭园阒然", "example": null}, {"def": "阒qù寂静～无一人。", "example": null}]','chinese-xinhua','0'),
('2101143296607785041','觑','1','qù','见','15',NULL,'[{"def": "觑", "example": null}, {"def": "(形声。从见,虚声。本义窥视,偷偷地看)", "example": null}, {"def": "同本义", "example": null}, {"def": "狙击秦皇帝。--《史记·留侯世家》。以狙为之,字亦作觑。", "example": null}, {"def": "又如觑探(探看);觑了她一眼", "example": null}, {"def": "把眼睛眯成一条细缝", "example": null}, {"def": "刘姥姥也觑着眼看,口里不住地念佛。--《红楼梦》", "example": null}, {"def": "仔细瞄准", "example": null}, {"def": "花荣搭上箭,曳满弓,觑得亲切,望空中只一箭射去。--《水浒全传》", "example": null}, {"def": "照看,照顾", "example": null}, {"def": "离,距", "example": null}, {"def": "因而忧闷成疾,昼夜无眠;眼见的觑天远,入地近,无那活的人也。--《东堂老》楔子》", "example": null}, {"def": "瞧;看", "example": null}, {"def": "觑（觧、觵）qù看，窥伺偷～。面面相～。", "example": null}]','chinese-xinhua','0'),
('2101143296607785042','趣','1','qù','走','15',NULL,'[{"def": "趣〈形〉", "example": null}, {"def": "(形声。从走,取声。本义急,赶快) 同本义", "example": null}, {"def": "趣,疾也。--《说文》", "example": null}, {"def": "若不趣降汉,汉今虏若,若非汉敌也。--《史记》", "example": null}, {"def": "趣 〈动〉", "example": null}, {"def": "通促”。催促;督促", "example": null}, {"def": "趣其稼事。--《周礼·县正》", "example": null}, {"def": "趣民收敛。--《礼记·月令》", "example": null}, {"def": "趣为我语。--《汉书·周勃传》", "example": null}, {"def": "督趣司隶。--《汉书·翟方进传》", "example": null}, {"def": "巫妪何久也?弟子趣之。--褚少孙《西门豹治邺》", "example": null}, {"def": "通趋”。趋向;奔向", "example": null}, {"def": "左右趣之。--《诗·大雅·棫朴》", "example": null}, {"def": "来朝趣马。--《诗·大雅·棫》", "example": null}, {"def": "汝先观吾趣。--《列子", "example": null}, {"def": "趣qù", "example": null}, {"def": "⒈趋向，意向，奔赴志～。旨～。百里而～利者蹶上将（蹶挫败）。", "example": null}, {"def": "⒉兴味，有兴味的～味。～事。～闻。兴～。乐～≤有～。", "example": null}, {"def": "⒊〈古〉通\\"促\\"。催促。", "example": null}, {"def": "⒋", "example": null}, {"def": "趣cù 1.督促;催促。 2.促使;逼使。 3.引申为驱赶。 4.赶快;从速。 5.急，急于。 6.拘束;拘谨。", "example": null}, {"def": "趣qū 1.趋向;归向。 2.引申为赶上;与……相应。 3.赴;前往。 4.小步快走。古代一种示敬的礼节。 5.引申为进见。 6.佛教语。指众生轮回的去处。", "example": null}, {"def": "趣cǒu 1.周代掌管王马的官员。参见\\"趣马\\"。", "example": null}, {"def": "趣zōu 1.巡夜。参见\\"争趣\\"。", "example": null}]','chinese-xinhua','0'),
