('2101143296607785056','岖','1','qū','山','7',NULL,'[{"def": "岖", "example": null}, {"def": "(形声。从山,区声。崎岖,地面高低不平的样子)", "example": null}, {"def": "道路险阻不平", "example": null}, {"def": "形容山势峻险", "example": null}, {"def": "岖（嶇）qū", "example": null}]','chinese-xinhua','0'),
('2101143296607785057','诎','1','qū','讠','7',NULL,'[{"def": "诎", "example": null}, {"def": "(形声。从言,出声。本义言语钝拙)", "example": null}, {"def": "同本义", "example": null}, {"def": "诎,辞塞。--《广韵》", "example": null}, {"def": "诎,字从言,当与吃同意。--《说文通训定声》", "example": null}, {"def": "公输盘诎。--《墨子·公输》", "example": null}, {"def": "轻财重士,辩于心而诎于口。--《史记·李斯列传》", "example": null}, {"def": "尽,穷尽", "example": null}, {"def": "利出于一孔者,其国无敌;出二孔者,其兵不诎;出三孔者,不可以举兵;出四孔者,其国必亡。--《管子》", "example": null}, {"def": "理诎势穷。--清·林则徐文", "example": null}, {"def": "声音戛然而止貌", "example": null}, {"def": "叩之,其声清越以长,其终诎然。--《礼记》。孔颖达疏诎谓止绝也。”", "example": null}, {"def": "诎", "example": null}, {"def": "通屈”。弯曲", "example": null}, {"def": "诎,屈也。--《广雅·释", "example": null}, {"def": "诎qū", "example": null}, {"def": "⒈短缩，嘴笨。", "example": null}, {"def": "⒉通\\"屈\\"。弯曲，屈服。", "example": null}, {"def": "诎chù 1.贬黜，贬退。", "example": null}]','chinese-xinhua','0'),
