('2101143296607785059','驱','1','qū','马','7',NULL,'[{"def": "驱", "example": null}, {"def": "(形声。从马,区声。本义奔驰;疾行)", "example": null}, {"def": "同本义", "example": null}, {"def": "驱,马驰也。--《说文》", "example": null}, {"def": "驱,奔也。--《广雅·释室》", "example": null}, {"def": "王用三驱。--《易·比》", "example": null}, {"def": "驱马悠悠。--《诗·鄘风·载驰》", "example": null}, {"def": "负而前驱。--宋·欧阳修《新五代史·伶官传》", "example": null}, {"def": "并驱如故。--《聊斋志异·狼三则》", "example": null}, {"def": "又如驱弛;驰驱(骑马快跑);长驱(迅速地向很远的目的地走);驱侵(驱车侵袭);驱劳(奔走辛劳);驱突(驱驰奔跑);驱骇(奔走惊骇)", "example": null}, {"def": "赶马", "example": null}, {"def": "并驱从两肩兮。--《诗·齐风·还》", "example": null}, {"def": "并驱从两牡兮。", "example": null}, {"def": "驱而之薛。--《战国策·齐策四》", "example": null}, {"def": "冯谖先", "example": null}, {"def": "驱（驅、敺）qū", "example": null}, {"def": "⒈赶马。〈引〉赶，赶走～马。～虫。～逐。～车前进。", "example": null}, {"def": "⒉快跑驰～。并驾齐～。长～直入。", "example": null}, {"def": "⒊", "example": null}, {"def": "①差遣，迫使～使他去干。", "example": null}, {"def": "②推动为好奇心所～使。", "example": null}, {"def": "驱ōu 1.捶击，殴打。", "example": null}]','chinese-xinhua','0'),
('2101143296607785060','屈','1','qū','尸','8',NULL,'[{"def": "屈〈动〉", "example": null}, {"def": "(形声。从尸,出声。尸,古文字中是假卧着的人形。本义弯曲)", "example": null}, {"def": "同本义", "example": null}, {"def": "屈,拗曲。--《广韵》", "example": null}, {"def": "凡曲而不伸者皆曰屈。--《正字通》", "example": null}, {"def": "尺蠖之屈,以求信也。--《易·系辞》", "example": null}, {"def": "猬缩蠖屈。--马中锡《中山狼传》", "example": null}, {"def": "不可屈伸。--明·宋濂《送东阳马生序》", "example": null}, {"def": "安能屈豪杰。--明·张溥《五人墓碑记》", "example": null}, {"def": "屈膝叩首。--清·方苞《狱中杂记》", "example": null}, {"def": "不当屈。--清·张廷玉《明史》", "example": null}, {"def": "又如屈指询算(迷信指用手指占算);屈律(弯曲的样子);屈卮(有弯曲把手的酒杯);屈申(屈伸。屈曲和伸展);诎屈(曲折;弯曲);屈伸(屈曲);屈屈(弯弯曲曲);屈蠖(曲身", "example": null}, {"def": "屈qū", "example": null}, {"def": "⒈弯曲，跟伸相对～膝。～指可数。", "example": null}, {"def": "⒉低头，妥协，服输，顺从～服。～从。不～不挠。", "example": null}, {"def": "⒊冤枉，使人不痛快冤～。委～。受～。", "example": null}, {"def": "⒋理亏理～词穷。", "example": null}, {"def": "⒌", "example": null}, {"def": "屈jué 1.短。 2.竭尽，穷尽。 3.见\\"屈奇。\\" 4.通\\"倔\\"。参见\\"屈强\\"。 5.通\\"崛\\"。参见\\"屈起\\"。", "example": null}]','chinese-xinhua','0'),
