('2101143296616173598','荃','1','quán','艹','9',NULL,'[{"def": "荃〈名〉", "example": null}, {"def": "(形声。从苃,全声。本义香草名,即荪)", "example": null}, {"def": "香草名。即菖蒲”,又名荪”。古用以比喻君主", "example": null}, {"def": "荃不揆余之中情兮。--《离骚》。注香草也。”", "example": null}, {"def": "荃者,所以在鱼得鱼而忘荃。--《庄子·外物》。释文香草也。”", "example": null}, {"def": "荃蕙蔽匿兮,胡久而不芳?--柳宗元《吊屈原文》", "example": null}, {"def": "又如荃宰(指君臣);荃荪(香草。古代常用以喻贤良的人);荃察(旧时书信中常用为希望对方鉴谅的敬辞);荃芜(香草名)", "example": null}, {"def": "细切的腌芥菜", "example": null}, {"def": "荃,芥脃也。从草,全声。谓以芥为斋、鲜脃也。--《说文》", "example": null}, {"def": "通筌”。捕鱼具", "example": null}, {"def": "荃者所以在鱼,", "example": null}, {"def": "荃quán〈古〉", "example": null}, {"def": "⒈指一种香草。", "example": null}, {"def": "⒉通\\"筌\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296616173599','拳','1','quán','手','10',NULL,'[{"def": "拳〈名〉", "example": null}, {"def": "(形声。夲义紧握的手。俗称拳头)", "example": null}, {"def": "同本义", "example": null}, {"def": "拳,手也。--《说文》。按,张之为掌,卷之为拳。”", "example": null}, {"def": "鲁君许诺,乃使吏韆其拳。--《吕氏春秋》", "example": null}, {"def": "又如挥拳;赤手空拳", "example": null}, {"def": "拳术;拳击", "example": null}, {"def": "通弮”。弓弩", "example": null}, {"def": "士张空拳。--《汉书·李广传》", "example": null}, {"def": "姓", "example": null}, {"def": "拳 〈动〉", "example": null}, {"def": "通蜷”。屈曲;卷曲", "example": null}, {"def": "其棱细则拳曲。--《庄子·人间世》", "example": null}, {"def": "手不得拳,膝不得屈。--《颜氏家训·勉学》", "example": null}, {"def": "又如拳拳弯弯(卷曲的样子);拳毛(卷曲的毛发);拳挛(拳曲;屈曲);拳毛(毛", "example": null}, {"def": "拳quán", "example": null}, {"def": "⒈屈指卷握起来的手～头。握～。", "example": null}, {"def": "⒉徒手的武术～术。练太极～。", "example": null}, {"def": "⒊曲～着腿。", "example": null}, {"def": "⒋勇力无～无勇。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
