('2101143296616173601','辁','1','quán','车','10',NULL,'[{"def": "辁", "example": null}, {"def": "古代无辐的木制车轮", "example": null}, {"def": "辁,藩车下庳轮也。--《说文》", "example": null}, {"def": "辁,轮也。--《广雅·释器》", "example": null}, {"def": "两轮为辁,车梯也。--《墨子·经说》", "example": null}, {"def": "载以辁车。--《礼记·杂记》", "example": null}, {"def": "又如辁轮(没有条辐的车轮);辁车(一种车轮没有条辐的车子)", "example": null}, {"def": "辁", "example": null}, {"def": "浅薄;小", "example": null}, {"def": "后世辁人讽说之徒。--《庄子·外物》", "example": null}, {"def": "又如辁才(小才;浅薄之才);辁朴(浅薄朴拙不堪重任的人)", "example": null}, {"def": "辁quán", "example": null}, {"def": "⒈没有辐的车轮。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296616173602','劝','1','quàn','力','4',NULL,'[{"def": "劝", "example": null}, {"def": "(形声。从力,雚声。简化字中又”仅是一个符号。本义勉励)", "example": null}, {"def": "同本义", "example": null}, {"def": "劝,勉也。--《说文》", "example": null}, {"def": "劝防之事。--《周礼·丧祝》。司农注劝防引柩也。”", "example": null}, {"def": "则楚之应之也,必劝。--《战国策·秦策》。注进也”。", "example": null}, {"def": "子文无后,何以劝善?--《左传·宣公四年》", "example": null}, {"def": "我戮之不祥,赦之以劝事君者。--《左传·成公二年》", "example": null}, {"def": "昔尧治天下,不赏而民劝。--《庄子·天地》", "example": null}, {"def": "各劝其业。--《史记·货殖列传》", "example": null}, {"def": "太公劝其女功。", "example": null}, {"def": "所以劝之。--唐·韩愈《朱文昌校昌黎先生集》", "example": null}, {"def": "又如劝进(劝勉,策进);劝蚕(勉励种桑养蚕);劝戒(劝勉警戒", "example": null}, {"def": "劝（勸）quàn", "example": null}, {"def": "⒈讲明事理，使人听从～说。～解。～告。～阻。", "example": null}, {"def": "⒉勉励，奖励～勉。", "example": null}]','chinese-xinhua','0'),
('2101143296616173603','券','1','quàn','刀','8',NULL,'[{"def": "券〈名〉quan", "example": null}, {"def": "(形声。 券要分成两半,故从刀”。本义契据)", "example": null}, {"def": "同本义。古代用于买卖或债务的契据。书于简牍,常分为两半,双方各执其一,以为凭证◇用纸帛书写", "example": null}, {"def": "券,契也。……券别之书,以刀判契其旁,故曰契券。--《说文》", "example": null}, {"def": "使吏召诸民当偿者悉来合券。--《战国策·齐策》", "example": null}, {"def": "因烧其券。", "example": null}, {"def": "裁券而行。", "example": null}, {"def": "又如券契(契据);券要(契约);券约(契据);券书(契约,文书);券剂(契据;凭证);券证(契据)", "example": null}, {"def": "可作凭证的物件;票证", "example": null}, {"def": "比喻事情可以", "example": null}, {"def": "券quàn", "example": null}, {"def": "⒈票证或凭据国库～。凭～入场。", "example": null}, {"def": "券xuàn", "example": null}, {"def": "⒈门、窗、桥梁等建筑成弧形的部分拱～。", "example": null}]','chinese-xinhua','0'),
