('2101143296616173624','悫','1','què','心','11',NULL,'[{"def": "悫", "example": null}, {"def": "恭谨", "example": null}, {"def": "悫,谨也。--《说文》", "example": null}, {"def": "共容悫。--《荀子·非十二子》", "example": null}, {"def": "如悫素(恭谨朴实);悫讷(谨慎寡言)", "example": null}, {"def": "厚道;朴实", "example": null}, {"def": "夫称上古之传颂,辩而不悫。--《韩非子·外储说左上》", "example": null}, {"def": "高言谨悫。--《荀子·非十二子》", "example": null}, {"def": "如悫士(质朴诚实之士);悫直(朴实耿直);悫善(朴实善良);悫实(朴实);悫励(笃诚奋勉)", "example": null}, {"def": "悫（憉、愨）què诚实，谨慎法正则民～。", "example": null}]','chinese-xinhua','0'),
('2101143296616173625','雀','1','què','隹','11',NULL,'[{"def": "雀子 qiao", "example": null}, {"def": "义同雀”。方言。用于家雀儿”、雀盲眼” qiao", "example": null}, {"def": "雀盲眼", "example": null}, {"def": "雀 〈名〉que", "example": null}, {"def": "(会意。从小隹。隹”是短尾鸟的泛称,上加三点表示小。本义麻雀)", "example": null}, {"def": "同本义", "example": null}, {"def": "雀,依人小乌也。--《说文》", "example": null}, {"def": "从雀嗷嗷。--宋玉《高唐赋》", "example": null}, {"def": "雀跃而游。--《庄子·在宥》", "example": null}, {"def": "小者至于燕雀。--《礼记·月令》", "example": null}, {"def": "青雀白鹄舫。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "又如雀盲症;雀舌牙茶(嫩芽茶);雀子(麻雀);雀爪(像麻雀的爪形,为绘画法中的一种名称);雀立(跳跃。一说竦身而", "example": null}, {"def": "雀qiǎo鸟的一类，用于一些口语家～儿。", "example": null}, {"def": "雀qiāo［雀子］雀斑。", "example": null}, {"def": "雀què", "example": null}, {"def": "⒈鸟的一类，体小，翼长，嘴呈圆锥状，雌雄羽毛颜色多不相同，吃粮食种子也吃昆虫。种类很多，如麻～、黄～、锡嘴～等,但都已稀少，要保护，禁止猎杀。又泛指小鸟", "example": null}, {"def": "～鸟。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296616173626','确','1','què','石','12',NULL,'[{"def": "确", "example": null}, {"def": "(形声。左形,右声。本作碻”、塽”。本义坚固)", "example": null}, {"def": "同本义", "example": null}, {"def": "确乎能其事者而已矣。--《庄子·应帝王》", "example": null}, {"def": "確乎其不可拔。--《易·乾卦》", "example": null}, {"def": "夫乾確然,示人易矣。--《易·系辞下》", "example": null}, {"def": "乐则行之,忧则违之,确乎其不可拔,潜龙也。--《易·乾》", "example": null}, {"def": "坚定;坚决", "example": null}, {"def": "真实;符合事实", "example": null}, {"def": "确", "example": null}, {"def": "通搉”。敲击", "example": null}, {"def": "乐亦不复", "example": null}, {"def": "确（確、塽、碻）、", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋埆què", "example": null}, {"def": "⒈真实，实在～实。千真完～。～有其事。", "example": null}, {"def": "⒉肯定，坚定～认。～保不误。", "example": null}, {"def": "⒊土地瘠薄。", "example": null}, {"def": "⒋地不平。", "example": null}]','chinese-xinhua','0'),
