('2101143296616173634','炔','1','quē','火','8',NULL,'[{"def": "炔〈名〉", "example": null}, {"def": "姓", "example": null}, {"def": "炔〈名〉", "example": null}, {"def": "炔quē有机化合物的一类，分子式可用ＣnＨ2n-2表示。它们具有很不饱和的性质。其中的乙炔，是烧焊及制作有机玻璃、合成橡胶、聚氯乙烯等的重要原料。", "example": null}, {"def": "炔guì 1.烟出貌。 2.姓。春秋时齐有炔钦。见《汉书．儒林传．周堪》。", "example": null}]','chinese-xinhua','0'),
('2101143296616173635','缺','1','quē','缶','10',NULL,'[{"def": "缺〈形〉", "example": null}, {"def": "(形声。从缶,夬声。缶,瓦器。夬”也有表意作用。水缺为决”,玉缺为玦”,器缺为缺”,都有破损之意。本义器具破损) 同本义。引申为缺漏而不完整", "example": null}, {"def": "缺,器破也。--《说文》", "example": null}, {"def": "入休乎缺甽之崖。--《庄子·秋水》", "example": null}, {"def": "周室既微,载籍残缺。--《汉书·艺文志》", "example": null}, {"def": "既破我斧,又缺我斨。--《诗·豳风·破斧》", "example": null}, {"def": "又如墙缺了一块;缺落(破损剥落);缺啮(折角,破损);缺坏(破缺损坏);缺触(残缺剥蚀);缺唇(又叫缺嘴”,上唇缺损。一名兔唇);缺圮(残缺倒塌)", "example": null}, {"def": "缺 〈动〉", "example": null}, {"def": "短少;缺乏", "example": null}, {"def": "缺王道之仪。", "example": null}, {"def": "缺quē", "example": null}, {"def": "⒈残破～口。残～。月～。刀尖～。", "example": null}, {"def": "⒉短少，不够～乏。～少。～水。～粮。", "example": null}, {"def": "⒊该到未到～课。～勤。", "example": null}, {"def": "⒋空额（指职位）空～。补～。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "缺kuǐ 1.见\\"缺项\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296616173636','裙','1','qún','衤','12',NULL,'[{"def": "裙", "example": null}, {"def": "(形声。从衣,君声。《说文》从巾”。本义下裳,古代男女都有下裳)", "example": null}, {"def": "古指下裳,今专指裙子", "example": null}, {"def": "裙,下裳也。--《说文》", "example": null}, {"def": "裙,下裳也。裙,群也,联接群幅也。--《释名》", "example": null}, {"def": "著我绣夹裙,事事四五通。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "缃绮为下裙。--《乐府诗集·陌上桑》", "example": null}, {"def": "揽裙脱丝履。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "出入无完裙。--唐·杜甫《石壕吏》", "example": null}, {"def": "血色罗裙翻酒污。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如连衣裙;连衫裙;围裙;短裙;超短裙;裙布钗荆(形容妇女服饰俭朴);裙袄(衣裤);裙门(裙子的前幅);裙刀(压衣服用", "example": null}, {"def": "裙（帬）qún裙子，裙儿，一种围在下身的服装围～子。连衣～。", "example": null}]','chinese-xinhua','0'),
('2101143296616173637','群','1','qún','羊','13',NULL,'[{"def": "群", "example": null}, {"def": "(形声。从羊,君声。本义羊群;兽群;人群)", "example": null}, {"def": "三个以上的禽兽相聚而成的集体", "example": null}, {"def": "群,辈也。--《说文》", "example": null}, {"def": "兽三为群。--《国语·周语》", "example": null}, {"def": "或群或友。--《诗·小雅·吉日》", "example": null}, {"def": "三百维群。--《诗·小雅·无羊》", "example": null}, {"def": "大夫不掩群。--《礼记·曲礼》", "example": null}, {"def": "群疑满服,众难塞胸。--诸葛亮《后出师表》", "example": null}, {"def": "故近者聚而为群。--柳宗元《封建论》", "example": null}, {"def": "又如群才(有才能的人们);群生(一切生物);群立(站立在人群中);群有(佛教指众生或万物);群儿(一群小儿。多用作轻蔑之辞);群品(万事万物;佛教指众生)。也指其他动物相聚而成的集体。又如猪群;马", "example": null}, {"def": "群（羣）qún", "example": null}, {"def": "⒈〈古〉指羊群。泛指聚在一起的人或物人～。南沙～岛。三五成～。", "example": null}, {"def": "⒉聚集，会合～天下之英杰。", "example": null}, {"def": "⒊众，许多～众。～策～力。～威～胆。", "example": null}, {"def": "⒋量词两～孩子。", "example": null}]','chinese-xinhua','0'),
