('2101143296616173671','嚷','1','rǎnɡ','口','20',NULL,'[{"def": "嚷嚷", "example": null}, {"def": "谁在那儿嚷嚷", "example": null}, {"def": "屋里一片乱嚷嚷", "example": null}, {"def": "这件事,你可别嚷嚷", "example": null}, {"def": "嚷", "example": null}, {"def": "吵闹", "example": null}, {"def": "叫喊", "example": null}, {"def": "责备;训斥", "example": null}, {"def": "嚷", "example": null}, {"def": "叫喊声", "example": null}, {"def": "只觉得耳朵边满是嘈杂的嚷。--鲁迅《故事新编》", "example": null}, {"def": "嚷叫", "example": null}, {"def": "嚷rāng", "example": null}, {"def": "①吵闹，喧哗～闹。乱～。吵吵～ ～。", "example": null}, {"def": "②声张～ ～出去，大家听。", "example": null}, {"def": "嚷rǎng大声叫喊，高声说话大叫大～。别～了，该睡觉了。", "example": null}]','chinese-xinhua','0'),
('2101143296616173672','壤','1','rǎnɡ','土','20',NULL,'[{"def": "壤", "example": null}, {"def": "(形声。从土,襄声)声。本义柔土,即经耕作的土地)", "example": null}, {"def": "土壤", "example": null}, {"def": "壤,柔土也。--《说文》", "example": null}, {"def": "凡穿地四尺,为壤五尺,为坚三尺。--《九章算法》。按,息土曰壤,筑土曰坚。", "example": null}, {"def": "厥土惟白壤。--《书·禹贡》", "example": null}, {"def": "深耕细锄,厚加粪壤。--《论衡·率性》", "example": null}, {"def": "又如壤坟(柔细肥沃,适于耕种的土地);壤芥(泥土和小草);沃壤", "example": null}, {"def": "泛指泥土", "example": null}, {"def": "夫太山不辞壤石。--《说文·尊贤》", "example": null}, {"def": "又如霄壤;壤力(地力);壤未(地下);壤水(地下水;泉水);壤室(土室;土屋);壤陛(土做的台阶);天壤之别", "example": null}, {"def": "也指一般的土地", "example": null}, {"def": "东据成皋之险,割膏腴之壤。--李", "example": null}, {"def": "壤rǎng", "example": null}, {"def": "⒈松软的土沃～。〈引〉土地～界。土～。", "example": null}, {"def": "⒉地天～之别。", "example": null}, {"def": "⒊〈古〉通\\"穰\\"。丰收丰年～ ～。", "example": null}, {"def": "壤ráng 1.通\\"穰\\"。丰收。 2.见\\"壤子\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296620367872','攘','1','rǎnɡ','扌','20',NULL,'[{"def": "攘", "example": null}, {"def": "(形声。从手,襄声。本义推让,退让)", "example": null}, {"def": "同本义", "example": null}, {"def": "攘,推也。--《说文》。谓推手使前拱揖之容也,字亦作儴。", "example": null}, {"def": "左右攘辟。--《礼记·曲礼上》", "example": null}, {"def": "小子何敢攘焉。--《史记·太史公自序》", "example": null}, {"def": "随流而攘。--《汉书·司马相如传》。注却退也。”", "example": null}, {"def": "盛揖攘之容。--《汉书·礼乐志》", "example": null}, {"def": "合于尧之克攘。--《汉书·艺文志》", "example": null}, {"def": "排斥,努力消去", "example": null}, {"def": "攘,除也。--《广韵》", "example": null}, {"def": "攘夷狄。--《公羊传·僖公四年》", "example": null}, {"def": "反离谤而见攘。--《楚辞·七谏·沈江》", "example": null}, {"def": "攘白翟之地。--《国语·", "example": null}, {"def": "攘rǎng", "example": null}, {"def": "⒈排斥，排除～敌。～除。～弃。", "example": null}, {"def": "⒉偷，窃取。", "example": null}, {"def": "⒊侵夺～夺。", "example": null}, {"def": "⒋撩起，挽起～袖。", "example": null}, {"def": "⒌", "example": null}, {"def": "攘ràng 1.退让;谦让◇作\\"让\\"。", "example": null}, {"def": "攘ráng 1.通\\"禳\\"。祈禳。 2.通\\"穰\\"。众多，丰盛。参见\\"攘攘\\"。 3.通\\"躟\\"。疾行貌。", "example": null}, {"def": "攘níng 1.见\\"抢攘\\"。", "example": null}, {"def": "攘xiǎng 1.馈食。", "example": null}]','chinese-xinhua','0'),
