('2101143296620367874','荛','1','ráo','艹','9',NULL,'[{"def": "荛", "example": null}, {"def": "(形声。从苃,尧声。本义柴草)", "example": null}, {"def": "同本义", "example": null}, {"def": "荛,薪也。--《说文》", "example": null}, {"def": "询于刍荛。--《诗·板》", "example": null}, {"def": "淫刍荛者。--《左传·昭公十三年》。疏供然火之草也。", "example": null}, {"def": "卖其薪荛。--《管子·轻重甲》。注大曰薪,小曰荛。”", "example": null}, {"def": "又如荛子(樵夫)", "example": null}, {"def": "芜菁,菜名", "example": null}, {"def": "樵夫,打柴的人", "example": null}, {"def": "荛", "example": null}, {"def": "打柴草", "example": null}, {"def": "童区寄者,郴州荛牧儿也。--唐·柳宗元《童区寄传》", "example": null}, {"def": "又如荛牧(打草与放牧)", "example": null}, {"def": "荛花", "example": null}, {"def": "荛（蕘）ráo", "example": null}, {"def": "⒈柴草。", "example": null}, {"def": "⒉砍柴草的人。", "example": null}, {"def": "荛yáo 1.指荛花。落叶灌木。花黄色，核果黑色，茎皮纤维可造纸。花供药用，有润喉消肿之效。参阅《神农本草经》卷三﹑明李时珍《本草纲目．草六．荛花》。", "example": null}]','chinese-xinhua','0'),
('2101143296620367875','饶','1','ráo','饣','9',NULL,'[{"def": "饶", "example": null}, {"def": "(形声。从食,尧声。本义饱)", "example": null}, {"def": "同本义", "example": null}, {"def": "饶,饱也。--《说文》。", "example": null}, {"def": "富裕,丰足", "example": null}, {"def": "饶,多也。--《小尔雅》", "example": null}, {"def": "饶,益也『时谣曰今年尚可后年饶。今苏俗买物请益谓之讨饶头。--《广雅》", "example": null}, {"def": "原大则饶,原小则鲜。--《史记·货殖列传序》", "example": null}, {"def": "七十子之徒,赐(子贡)最为饶益--《史记·货殖列传》", "example": null}, {"def": "又如饶裕(富足;富裕);饶益(富裕);饶美(丰美);饶富(富饶,丰足);饶益(富裕,使人受益);饶余(富足有余);饶足(生活富裕);饶野(富饶的田野)", "example": null}, {"def": "余;剩", "example": null}, {"def": "饶,余也。--《玉篇》", "example": null}, {"def": "子弟衣食自有余饶。--诸葛亮《自表", "example": null}, {"def": "饶(饒）ráo", "example": null}, {"def": "⒈多，富足～有兴趣。～舌（多话）。物产富～。", "example": null}, {"def": "⒉宽容，宽恕～恕。～他这一次。", "example": null}, {"def": "⒊添～上两元。", "example": null}]','chinese-xinhua','0'),
('2101143296620367876','桡','1','ráo','木','10',NULL,'[{"def": "桡", "example": null}, {"def": "曲木;木头弯曲;泛指弯曲", "example": null}, {"def": "桡,曲木。从木,荛声。--《说文》", "example": null}, {"def": "栋桡。--《易·大过》", "example": null}, {"def": "竿木桡。--《列子·汤问》", "example": null}, {"def": "桡之以视其鸿杀之称也。--《考工记·矢人》", "example": null}, {"def": "又如桡木(曲木。使木弯曲);桡曲(弯曲曲木)", "example": null}, {"def": "扰动;搅乱", "example": null}, {"def": "屈服", "example": null}, {"def": "重死持义而不桡,是士君子之勇也。--《荀子》", "example": null}, {"def": "又如桡辞(屈服的言词)", "example": null}, {"def": "屈弱,削弱", "example": null}, {"def": "上已桡功臣。--《史记·萧相国世家》", "example": null}, {"def": "汉王恐忧,与郦食其谋桡楚权。--《史记·留侯世家》", "example": null}, {"def": "又如桡败(挫败);桡折(摧折)", "example": null}, {"def": "桡", "example": null}, {"def": "柔弱长艳", "example": null}, {"def": "桡（橈）ráo", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉划船的桨。", "example": null}, {"def": "桡náo 1.弯曲。 2.谓使弯曲。 3.屈从;屈服。 4.枉屈。 5.扰动;搅乱。 6.干预;冒犯。 7.削弱。 8.顾望。古代军法术浯。 9.见\\"桡桃\\"。", "example": null}]','chinese-xinhua','0'),
