('2101143296620367878','娆','1','ráo','女','9',NULL,'[{"def": "娆", "example": null}, {"def": "柔弱", "example": null}, {"def": "娆,弱也。--《广雅》", "example": null}, {"def": "妍媚", "example": null}, {"def": "看红装素裹,分外妖娆。--毛泽东《沁园春·雪》", "example": null}, {"def": "又如妖娆(妩媚多姿);娇娆(柔美妩媚)", "example": null}, {"def": "嬈娆", "example": null}, {"def": "(形声。从女,尧声。本义烦扰;扰乱)", "example": null}, {"def": "同本义", "example": null}, {"def": "娆,苛也。--《说文》", "example": null}, {"def": "娆,烦也。亦恼也。--《纂文》", "example": null}, {"def": "除苛解娆。--《汉书·晁错传》", "example": null}, {"def": "其神不娆。--《淮南子·原道》", "example": null}, {"def": "伤死者其鬼娆。--《淮南子·俶真》", "example": null}, {"def": "又如娆乱(扰乱);娆固(扰乱蛊惑);娆害(捣乱破坏);娆败(扰乱破坏);娆恼(烦忧)", "example": null}, {"def": "戏弄", "example": null}, {"def": "娆,戏弄也。--《说文》", "example": null}, {"def": "娆（嬈）ráo", "example": null}, {"def": "娆（嬈）rǎo烦扰，扰乱。", "example": null}, {"def": "娆yǎo 1.柔弱貌。参见\\"娆娆\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296620367879','绕','1','rào','纟','9',NULL,'[{"def": "绕", "example": null}, {"def": "(形声。从糸,尧声。本义缠束)", "example": null}, {"def": "同本义", "example": null}, {"def": "绕,缠也。--《说文》", "example": null}, {"def": "绕黄山而款牛首。--张衡《西京赋》。注裹也。”", "example": null}, {"def": "又如把丝绕在卷筒上;绕搭(缠绕);绕缭(缭绕,盘旋围绕);绕手(犹棘手);绕网(陷入罗网);绕结(回旋缠结)", "example": null}, {"def": "环绕", "example": null}, {"def": "白水绕东城。--唐·李白《送友人》", "example": null}, {"def": "黄芦苦竹绕宅生。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如绕梁声(形容歌声优美动听,长久萦回耳畔);绕袭(迂回突袭敌人)", "example": null}, {"def": "迂回绕过", "example": null}, {"def": "一边是陡山,一边是深峪,更无别处好绕。--《老残游记》", "example": null}, {"def": "又如绕弯(波折);", "example": null}, {"def": "绕（繞、", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋遶）rào", "example": null}, {"def": "⒈缠～线。", "example": null}, {"def": "⒉纠缠，弄迷糊把他～住。这两个字总算将他～着了。", "example": null}, {"def": "⒊围着转～场一周。月亮～地球运行。", "example": null}, {"def": "⒋走弯路或迂回的路～了一段路。～到敌人背后。", "example": null}, {"def": "绕rǎo 1.弯曲。 2.姓。春秋秦有绕朝。见《左传．文公十三年》。", "example": null}]','chinese-xinhua','0'),
