('2101143296624562186','纫','1','rèn','纟','6',NULL,'[{"def": "纫", "example": null}, {"def": "(形声。从糸,刃声。本义搓绳)", "example": null}, {"def": "同本义", "example": null}, {"def": "纫,禅绳也。--《说文》。朱骏声曰凡单展曰纫,合绳曰纠, 织绳曰辫。”", "example": null}, {"def": "纫针请补缀。--《礼记·内则》", "example": null}, {"def": "纫秋兰以为佩,岂惟纫夫蕙茝。--《离骚》", "example": null}, {"def": "并纫茅,丝以为索。--《楚辞·惜誓》", "example": null}, {"def": "又如纫佩(捻缀秋兰,佩带在身)", "example": null}, {"def": "缝纫; 缝补", "example": null}, {"def": "公受珠,内所著披袄中,纫之。--明·崔铣《记王忠肃公翱三事》", "example": null}, {"def": "又如纫缉(联缀修补);纫缝(缝纫);纫捺(缝制)", "example": null}, {"def": "穿", "example": null}, {"def": "今亦以线贯针为纫。--《方言》注", "example": null}, {"def": "又如纫针(以线穿针。引申为缝制衣服)", "example": null}, {"def": "连缀,联结", "example": null}, {"def": "纫rèn", "example": null}, {"def": "⒈引线穿针～针。", "example": null}, {"def": "⒉缝补缝～。", "example": null}]','chinese-xinhua','0'),
('2101143296624562187','妊','1','rèn','女','7',NULL,'[{"def": "妊", "example": null}, {"def": "(形声。从女,壬声。) 同本义", "example": null}, {"def": "妊,孕也。--《说文》", "example": null}, {"def": "今诸怀妊者。--《后汉书·章帝纪》", "example": null}, {"def": "又如妊娘(孕妇);妊身(怀孕);妊娠", "example": null}, {"def": "妊(姙)rèn怀孕～娠。～妇。", "example": null}]','chinese-xinhua','0'),
