('2101143296624562190','轫','1','rèn','车','7',NULL,'[{"def": "轫", "example": null}, {"def": "(形声。从车,刃声。本义支住车轮使其不能转动的木头)", "example": null}, {"def": "同本义", "example": null}, {"def": "轫,碍车也。--《说文》", "example": null}, {"def": "车不发轫。--《淮南子·兵略》。注车下支。”", "example": null}, {"def": "朝发轫于苍梧兮,夕吾至乎县圃。--《楚辞·离骚》", "example": null}, {"def": "通仞”。古时的一种长度单位", "example": null}, {"def": "掘井九轫而不及泉。--《孟子》", "example": null}, {"def": "车轮", "example": null}, {"def": "水渐轫以凝冱。--《文选》。李善注引颜延年《篡要解》曰车轮谓之轫。”", "example": null}, {"def": "轫", "example": null}, {"def": "柔弱;懒散", "example": null}, {"def": "通韧”。柔软而坚固", "example": null}, {"def": "轫rèn支住车轮不使旋转的木头发～（把轫抽出，开动车子。〈喻〉出发或事业的开始）。", "example": null}]','chinese-xinhua','0'),
('2101143296624562191','韧','1','rèn','韦','7',NULL,'[{"def": "韧", "example": null}, {"def": "(形声。从韦,刃声。韦,熟牛皮。本义柔软而结实,受外力作用时虽变形而不易折断) 同本义", "example": null}, {"def": "故凡用兵者,攻坚则韧,乘暇则神。--《管子·制分》", "example": null}, {"def": "韧劲,韧劲儿", "example": null}, {"def": "韧（韌、靭）rèn柔软而结实～性。坚～。", "example": null}]','chinese-xinhua','0'),
('2101143296624562192','饪','1','rèn','饣','7',NULL,'[{"def": "饪", "example": null}, {"def": "(形声。从食,壬声。本义做饭做菜) 同本义", "example": null}, {"def": "饪,大熟也。--《说文》", "example": null}, {"def": "餁,熟也。--《广雅》", "example": null}, {"def": "烹饪也。--《易·鼎》", "example": null}, {"def": "失饪不食。--《论语》", "example": null}, {"def": "又如失饪(烹调失当);饪鼎(烹饪的鼎);饪熟(烹调)", "example": null}, {"def": "饪（餁）rèn制作饭菜食物烹～。", "example": null}]','chinese-xinhua','0'),
