('2101143296624562207','戎','1','rónɡ','戈','6',NULL,'[{"def": "戎", "example": null}, {"def": "(会意。从戈,从十。戈”是兵器,十”是铠甲的甲”。本义古代兵器的总称。弓、殳、矛、戈、戟为古代五戎)", "example": null}, {"def": "同本义", "example": null}, {"def": "戎,兵也。--《说文》", "example": null}, {"def": "以习五戎。--《礼记·月令》", "example": null}, {"def": "戎器不粥于市。--《礼记·王制》。注军器也。”", "example": null}, {"def": "伏戎于莽。--《易·同人》", "example": null}, {"def": "弓矢戎兵。--《诗·大雅·抑》", "example": null}, {"def": "又如戎仗(兵器,军械);戎器(兵器);戎储(兵器储备);戎钺(泛指兵器。钺,古兵器名);戎具(兵器)", "example": null}, {"def": "兵车", "example": null}, {"def": "元戎十乘。--《诗·小雅·六月》。传夏曰钩车,殷曰寅车,周曰元戎。", "example": null}, {"def": "梁弘御戎。--《左传·僖公三十三年》", "example": null}, {"def": "又", "example": null}, {"def": "戎róng", "example": null}, {"def": "⒈军队，士兵～装。从～。～阵整齐。", "example": null}, {"def": "⒉〈古〉指武器五～（弓殳矛戈戟）。", "example": null}, {"def": "⒊军事，战争～机。", "example": null}, {"def": "⒋〈古〉我国对西部民族的统称西～。", "example": null}]','chinese-xinhua','0'),
('2101143296624562208','肜','1','rónɡ','月','7',NULL,'[{"def": "肜", "example": null}, {"def": "商代祭祀的名称。指祭祀之后第二天又进行的祭祀", "example": null}, {"def": "肜", "example": null}, {"def": "通融”⊥乐", "example": null}, {"def": "殷日肜,周日绎。--《公羊传·宣公八年》", "example": null}, {"def": "肜róng 1.殷祭名。 2.见\\"肜肜\\"。", "example": null}]','chinese-xinhua','0');
