('2101143296649728004','茸','1','rónɡ','艹','9',NULL,'[{"def": "茸", "example": null}, {"def": "(形声。本义草初生时又细又柔软) 同本义", "example": null}, {"def": "茸,草茸茸貌。--《说文》", "example": null}, {"def": "在阘茸之中。--司马迁《报任安书》。注细毛也。”", "example": null}, {"def": "又如茸壑(长着青草、苔藓的山洞、土穴)", "example": null}, {"def": "茸", "example": null}, {"def": "鹿茸的简称", "example": null}, {"def": "河天月晕鱼分子,槲叶风微鹿养茸。--黄庭坚《诗》", "example": null}, {"def": "柔细的毛", "example": null}, {"def": "刺绣用的丝缕。同绒”", "example": null}, {"def": "其桑其松,其杞其茸。--《管子·地员》", "example": null}, {"def": "茸róng", "example": null}, {"def": "⒈草初生的样子绿～ ～的草坪。", "example": null}, {"def": "⒉", "example": null}, {"def": "茸rǒng 1.推入。", "example": null}]','chinese-xinhua','0'),
('2101143296649728005','荣','1','rónɡ','艹','9',NULL,'[{"def": "荣", "example": null}, {"def": "(形声。从木,荧省声。本义梧桐。又金文字形,象两支如火把相互照耀的花朵或穗头形)", "example": null}, {"def": "同本义", "example": null}, {"def": "荣,桐木也。--《说文》", "example": null}, {"def": "荣,桐木。--《尔雅》。注即梧桐。”", "example": null}, {"def": "草本植物的花。又为花的通称", "example": null}, {"def": "木谓之华,草谓之荣,不荣而实者谓之秀,荣而不实者谓之英。--《尔雅》", "example": null}, {"def": "攀条折其荣。--《古诗十九首》", "example": null}, {"def": "又如荣悴(草木的开花与凋萎);荣年(百花争艳的季节);荣色(花的色彩)", "example": null}, {"def": "飞檐,屋檐两头翘起的部分", "example": null}, {"def": "直于东荣。--《仪礼·士冠礼》。注屋翼也。”", "example": null}, {"def": "暴于南荣。--《上林赋》。注", "example": null}, {"def": "荣（榮）róng", "example": null}, {"def": "⒈草开花，草的花或谷类结穗草～。无叶无～。黍～。", "example": null}, {"def": "⒉茂盛，兴盛欣欣向～。繁～富强。", "example": null}, {"def": "⒊光荣，受人 敬重～誉。～耀。～军。", "example": null}]','chinese-xinhua','0'),
('2101143296649728006','容','1','rónɡ','宀','10',NULL,'[{"def": "容", "example": null}, {"def": "(会意兼形声。小徐本从宀,谷。”大徐本看作会意。宀”是房屋,谷”是空虚的山洼,都有盛受的意思。本义容纳)", "example": null}, {"def": "同本义", "example": null}, {"def": "容,盛也。--《说文》", "example": null}, {"def": "君子以容民畜众。--《易·师》", "example": null}, {"def": "言宽大包容。--《汉书·五行志》", "example": null}, {"def": "故曰心容。--《荀子·解蔽》", "example": null}, {"def": "广则容奸。--《史记·乐书》", "example": null}, {"def": "可容一人居。--明·归有光《项脊轩志》", "example": null}, {"def": "又如容隐(包庇,隐瞒);容足(仅容立足);容接(容纳接待);容盛(覆载,容纳);容民(容纳民众);容民畜众(容纳畜养民众);容畜(容纳养育);容受(容纳接受);容放(容纳置放)", "example": null}, {"def": "宽容", "example": null}, {"def": "则今高爵", "example": null}, {"def": "容róng", "example": null}, {"def": "⒈盛，包含～器。～纳。～量。内～。", "example": null}, {"def": "⒉原谅，对人度量大～忍。宽～。", "example": null}, {"def": "⒊让，允许～人说话。～许他去干。", "example": null}, {"def": "⒋相貌，仪表，姿态～貌。仪～。姿～。", "example": null}, {"def": "⒌或许，可能～或有之。～有阴谋。", "example": null}, {"def": "⒍事物所呈现的景象、状态、样子市～。阵～。", "example": null}]','chinese-xinhua','0'),
