('2101143296649728034','揉','1','róu','扌','12',NULL,'[{"def": "揉", "example": null}, {"def": "(形声。从手, 柔声。本义 使木弯曲或伸直)", "example": null}, {"def": "同本义", "example": null}, {"def": "揉木为耒。--《易·系辞下》", "example": null}, {"def": "揉辐必齐。--《考工记·轮人》", "example": null}, {"def": "又如揉辐(烤木使直,以作车轴);揉斫(砍削烤揉);揉木为耒", "example": null}, {"def": "用手来回擦或搓", "example": null}, {"def": "混合;融和", "example": null}, {"def": "琢磨", "example": null}, {"def": "摆弄;摆布", "example": null}, {"def": "揉róu", "example": null}, {"def": "⒈来回、旋转地搓或擦～面。～ ～腿。别～眼。", "example": null}, {"def": "⒉使弯曲～木为轮。", "example": null}]','chinese-xinhua','0'),
('2101143296649728035','蹂','1','róu','足','16',NULL,'[{"def": "蹂", "example": null}, {"def": "(形声。从足,柔声。本义践踏)", "example": null}, {"def": "同本义", "example": null}, {"def": "蹂,履也。--《广雅》", "example": null}, {"def": "蹂,蹂践,蹋也。--《玉篇》", "example": null}, {"def": "余骑相蹂践争项王。--《史记·项羽本纪》", "example": null}, {"def": "又如蹂若(蹂践、蹂蹈、践踏);蹂蹈(践踏);蹂踏(犹踩踏);蹂抑(践踏压制);蹂促(犹践踏)", "example": null}, {"def": "欺压、侵凌;侵袭", "example": null}, {"def": "蹂强翼弱,名四驰也。--戴良《李促宾像赞》", "example": null}, {"def": "又如蹂藉(侵害;侵扰);蹂剔(侵害)", "example": null}, {"def": "揉擦。通揉”", "example": null}, {"def": "或簸或蹂。--《诗·大雅·生民》", "example": null}, {"def": "蹂践", "example": null}, {"def": "自蹂践相杀死者数千。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "蹂róu踩，践踏～践。～躏（〈喻〉用暴力欺压、侮辱、侵害）。", "example": null}]','chinese-xinhua','0'),
