('2101143296649728055','铷','1','rú','钅','11',NULL,'[{"def": "铷", "example": null}, {"def": "一个质地柔软具有银白色光泽的碱金属元素,原子序数37,以化合物状态少量地存在于许多矿物、矿泉水以及许多植物的灰中,通常伴有更少量的铯,金属铷由电解或化学还原铷的", "example": null}, {"def": "化合物制得,它剧烈地使水分解,在空气中可自燃", "example": null}, {"def": "铷(ruk)rú金属化学元素之一。符号rb。银白色，软而轻，熔点低。用于制光电管、真空管等。铷的碘化物可供药用。", "example": null}]','chinese-xinhua','0'),
('2101143296649728056','孺','1','rú','子','17',NULL,'[{"def": "孺", "example": null}, {"def": "(形声。从子,需声。子,古代指小孩子,不分性别都称子。本义小孩子,尤指幼儿)", "example": null}, {"def": "同本义", "example": null}, {"def": "孺,乳子也。--《说文》", "example": null}, {"def": "孺子早寝晏起。--《礼记·内则》", "example": null}, {"def": "今人乍见孺子。--《孟子》", "example": null}, {"def": "又如孺童(小孩,幼童);孺弱(幼弱的孩子);孺慕(幼童爱慕父母之情);孺齿(幼儿,幼童);孺儿(幼儿);孺子欢(为使父母欢心,故意装出孩子般的神态动作);孺月(分娩后的第一", "example": null}, {"def": "个月);孺齿(幼儿)", "example": null}, {"def": "指亲属", "example": null}, {"def": "孺,属也。--《尔雅》。李注骨肉相亲属也。”", "example": null}, {"def": "又如孺泣(对父母的哀悼哭泣);孺止(敬仰)", "example": null}, {"def": "姓", "example": null}, {"def": "孺", "example": null}, {"def": "幼稚,年小", "example": null}, {"def": "公将不", "example": null}, {"def": "孺rú", "example": null}, {"def": "⒈小孩子～子可教。", "example": null}, {"def": "⒉亲睦和乐且～。", "example": null}]','chinese-xinhua','0'),
('2101143296649728057','濡','1','rú','氵','17',NULL,'[{"def": "濡", "example": null}, {"def": "古水名", "example": null}, {"def": "濡,濡水,出涿郡故安,东入涞。--《说文》", "example": null}, {"def": "在河北省", "example": null}, {"def": "尿", "example": null}, {"def": "病方今客肾濡,此所谓肾痹”也。--《史记》", "example": null}, {"def": "通儒”。儒士,学者", "example": null}, {"def": "海内称之曰濡术之宗。--《济阴太守孟郁修尧庙碑》", "example": null}, {"def": "少以濡术。--《尉卫卿衡方碑》", "example": null}, {"def": "假借为堧”。空地", "example": null}, {"def": "自以城池道濡麦。--《鲁相史晨飨孔庙后碑》", "example": null}, {"def": "濡", "example": null}, {"def": "沾湿", "example": null}, {"def": "不濡其翼。--《诗·曹风·候人》", "example": null}, {"def": "春雨露既濡。--《礼记·祭义》", "example": null}, {"def": "濡濯弃于坎。--《礼记·丧大记》", "example": null}, {"def": "今客贤濡。--《史记·扁仓传》", "example": null}, {"def": "又如濡墨", "example": null}, {"def": "濡rú", "example": null}, {"def": "⒈潮湿～衣。", "example": null}, {"def": "⒉浸，润泽～笔。", "example": null}, {"def": "⒊沾染耳～目染。", "example": null}, {"def": "⒋停留，迟慢～滞。～缓。", "example": null}, {"def": "⒌柔软，含忍～木。～忍。", "example": null}, {"def": "濡nuán 1.水名。今河北省滦河。", "example": null}, {"def": "濡ér 1.谓以汁调和烹煮。", "example": null}, {"def": "濡róu 1.见\\"濡忍\\"﹑\\"濡愞\\"。", "example": null}, {"def": "濡ruǎn 1.柔软;柔弱。", "example": null}, {"def": "濡nuò 1.水貌。见《集韵．去过》。 2.通\\"糯\\"。黏性的。", "example": null}]','chinese-xinhua','0'),
