('2101143296653922307','溽','1','rù','氵','13',NULL,'[{"def": "溽", "example": null}, {"def": "(形声。从水,辱声。本义湿热)", "example": null}, {"def": "同本义", "example": null}, {"def": "溽,湿暑也。--《说文》", "example": null}, {"def": "土润溽暑。--《礼记·月令》。注;润溽谓涂湿也。”", "example": null}, {"def": "又如溽夏(湿热的夏天);溽景(溽暑的烈日);溽蒸(溽热,湿热);溽润(湿润);溽露(繁多的露水)", "example": null}, {"def": "味浓厚,尤指美味", "example": null}, {"def": "其居处不淫,其饮食不溽。--《礼记·儒行》", "example": null}, {"def": "溽", "example": null}, {"def": "古水名,溽水。在今江苏省溧阳县", "example": null}, {"def": "己酉,天子饮于溽水之上。--《穆天子传》", "example": null}, {"def": "溽rù", "example": null}, {"def": "⒈湿润～暑（闷热的天）。", "example": null}, {"def": "⒉浓厚。", "example": null}]','chinese-xinhua','0'),
('2101143296653922308','缛','1','rù','纟','13',NULL,'[{"def": "缛", "example": null}, {"def": "(形声。从糸,辱声。本义繁密的彩饰)", "example": null}, {"def": "同本义", "example": null}, {"def": "缛,繁采色也。--《说文》", "example": null}, {"def": "绸缪缛绣。--左思《吴都赋》", "example": null}, {"def": "又如缛旨(繁饰的文旨);缛丽(繁饰华丽);缛绣(彩色繁丽,有如锦绣)", "example": null}, {"def": "通褥”。褥子", "example": null}, {"def": "缛", "example": null}, {"def": "繁多", "example": null}, {"def": "烦琐;对…阐述过详", "example": null}, {"def": "文有粗缛。--《周礼·大宗伯》注", "example": null}, {"def": "又如缛礼烦仪(烦琐的礼仪);繁文缛节", "example": null}, {"def": "缛rù", "example": null}, {"def": "⒈繁密的彩色装饰采饰纤～（纤细巧）。〈引〉繁多，繁琐～礼。繁文～节。", "example": null}, {"def": "⒉〈古〉通\\"褥\\"。褥子。", "example": null}]','chinese-xinhua','0'),
('2101143296653922309','蓐','1','rù','艹','13',NULL,'[{"def": "蓐", "example": null}, {"def": "(形声。从苃,辱声。本义陈草复生)", "example": null}, {"def": "同本义", "example": null}, {"def": "蓐,陈草复生也。--《说文》。徐锴系传陈根更生繁缛也。…言草繁多也。”", "example": null}, {"def": "吃饱", "example": null}, {"def": "蓐", "example": null}, {"def": "草席;草垫", "example": null}, {"def": "蓐谓之兹。--《尔雅》。注;兹者,蓐席也。”", "example": null}, {"def": "左追蓐。--《左传·宣公十二年》。注在左者追求草蓐为宿备。”疏蓐,谓卧土之草。”", "example": null}, {"def": "范乃令军中蓐食。--《后汉书·廉范传》", "example": null}, {"def": "又如蓐母(产婆,接生婆);蓐妇(产妇;生产之妇女);蓐劳(中医病名。", "example": null}, {"def": "蓐rù草垫子，草席（多指产妇用的）。", "example": null}]','chinese-xinhua','0'),
('2101143296653922310','褥','1','rù','衤','15',NULL,'[{"def": "褥", "example": null}, {"def": "(形声。从衣,辱声。本义坐卧的垫具) 同本义", "example": null}, {"def": "褥,荐也。--《三苍》", "example": null}, {"def": "寝必重褥。--明·刘基《苦斋记》", "example": null}, {"def": "又如褥甸(小的褥子,供坐卧);坐褥;褥垫;褥席(坐卧用的垫具或席具);褥子;褥位(铺有锦褥的座位);褥草(一种主要的垫料。如稿杆、草皮等;也指垫料的别名)", "example": null}, {"def": "褥rù坐或卧用的铺垫物～子。皮～。被～。", "example": null}]','chinese-xinhua','0'),
('2101143296653922311','汝','1','rǔ','氵','6',NULL,'[{"def": "汝", "example": null}, {"def": "(形声。从水,女声。本义汝水)", "example": null}, {"def": "同本义", "example": null}, {"def": "汝水出宏农卢氏,还归山东入淮。--《说文》。按,出今河南,至安徽入淮,为淮河支流", "example": null}, {"def": "指汝窑或汝窑所产瓷器", "example": null}, {"def": "姓", "example": null}, {"def": "汝", "example": null}, {"def": "你", "example": null}, {"def": "多用于称同辈或后辈", "example": null}, {"def": "汝陟帝位。--《书·舜典》", "example": null}, {"def": "格汝众。--《书·盘庚上》", "example": null}, {"def": "汝父为楚王作剑。--晋·干宝《搜神记》", "example": null}, {"def": "汝亦知射乎。--宋·欧阳修《归田录》", "example": null}, {"def": "吾与汝毕力平险。--《列子·汤问》", "example": null}, {"def": "又如汝们(你们);汝辈(你们)", "example": null}, {"def": "汝rǔ你，你的～等∥年待～归？", "example": null}]','chinese-xinhua','0'),
('2101143296653922312','乳','1','rǔ','乙','8',NULL,'[{"def": "乳", "example": null}, {"def": "(会意。从孚)。甲骨文中象手抱婴儿哺乳形。孚”是以爪抱子哺乳。本义生子,生产", "example": null}, {"def": "同本义", "example": null}, {"def": "人及鸟生子曰乳,兽曰产。--《说文》", "example": null}, {"def": "乳化曰孽。--《书·尧典》传", "example": null}, {"def": "胎生曰乳。--《尸子》", "example": null}, {"def": "菑川王美人怀子而不乳。--《史记·扁仓传》", "example": null}, {"def": "主人方乳。--《吕氏春秋·音初》", "example": null}, {"def": "使牧羝,羝乳乃得归。--《汉书·李广苏建传》", "example": null}, {"def": "又如乳子(产子;分娩);乳舍(产房);乳妇(产妇);乳卵(产(下)蛋);乳抱(繁殖)", "example": null}, {"def": "喂奶", "example": null}, {"def": "妪,先大母婢也,乳二世。--明·归有光《项脊轩志》", "example": null}, {"def": "妇抚儿乳。--林嗣环《口技》", "example": null}, {"def": "又如乳狗(育子的", "example": null}, {"def": "乳rǔ", "example": null}, {"def": "⒈分泌奶汁的器官～房。", "example": null}, {"def": "⒉奶汁母～。代～粉。", "example": null}, {"def": "⒊像乳头或乳汁的东西钟～石。豆～。", "example": null}, {"def": "⒋生，生殖孳～。", "example": null}, {"def": "⒌初生的，幼小的～燕。～虎。～瓜。～臭未干（奶腥气尚存。讥刺人年幼无知）。", "example": null}]','chinese-xinhua','0'),
('2101143296653922313','辱','1','rǔ','辰','10',NULL,'[{"def": "辱", "example": null}, {"def": "(会意。甲骨文字形,是辰”下加脚(止)或加手(又,寸)的形象。①本义耕作。辰”是蜃”的本字,古代以蜃为农具进行耕作。这个意义后来写作耨”(遮??))。②引申", "example": null}, {"def": "义耻辱) 同引申义", "example": null}, {"def": "辱,耻也。--《说文》", "example": null}, {"def": "恭近于礼,远耻辱也。--《论语·学而》", "example": null}, {"def": "心旷神怡,宠辱皆忘。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "衣食足而知荣辱。--《史记·货殖列传序》", "example": null}, {"def": "又如奇耻大辱;荣辱;羞辱;忍辱负重;蒙受屈膝之辱;辱害(耻辱和损害);辱残(受耻辱和残害)", "example": null}, {"def": "辱", "example": null}, {"def": "使…受辱;侮辱", "example": null}, {"def": "南辱于楚,寡人耻之。--《孟子·梁惠王上》", "example": null}, {"def": "使于", "example": null}, {"def": "辱rǔ", "example": null}, {"def": "⒈羞耻耻～。奇耻大～。", "example": null}, {"def": "⒉使人丢脸～没。～命。侮～。屈～。不可～。", "example": null}, {"def": "⒊谦词～承。～蒙。", "example": null}]','chinese-xinhua','0'),
