('2101143296653922342','若','1','ruò','艹','8',NULL,'[{"def": "若", "example": null}, {"def": "(象形。甲骨文字形,象一个女人跪着,上面中间象头发,两边两只手在梳发,表示顺从”。本义顺从)", "example": null}, {"def": "同本义", "example": null}, {"def": "若,顺也。--《尔雅·释名》", "example": null}, {"def": "万民是若。--《诗·鲁颂·阙宫》", "example": null}, {"def": "天子是若。--《诗·大雅·焌民》", "example": null}, {"def": "有孚禺若。--《易·观》", "example": null}, {"def": "钦若昊天。--《书·尧典》", "example": null}, {"def": "不逢不若。--《左传·宣公三年》", "example": null}, {"def": "又如若时(顺应天时);若淑(温顺而善良)", "example": null}, {"def": "如同;像", "example": null}, {"def": "圣人之德,若天之高,若地之普。--《墨子·尚贤中》", "example": null}, {"def": "肌肤若 冰雪,绰约若处子。--《庄子·逍遥游》", "example": null}, {"def": "关山度若飞。--《乐府诗集·木兰诗》", "example": null}, {"def": "若ruò", "example": null}, {"def": "⒈如，像，似乎欣喜～狂。～明～暗。～即～离。", "example": null}, {"def": "⒉如果，假如～是。天～有情天亦老。", "example": null}, {"def": "⒊你，你的～辈。～翁（你的父亲）。", "example": null}, {"def": "⒋奈～之何？", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "若rě 1.见\\"般若\\"。 2.见\\"若干\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296653922343','偌','1','ruò','亻','10',NULL,'[{"def": "偌", "example": null}, {"def": "如此;这样", "example": null}, {"def": "偌", "example": null}, {"def": "--用同喏”。表示提醒注意", "example": null}, {"def": "偌,那不是哥哥和妈妈么!--茅盾《过年》", "example": null}, {"def": "偌ruò这么，那么～大高个子。", "example": null}]','chinese-xinhua','0'),
('2101143296653922344','弱','1','ruò','弓','10',NULL,'[{"def": "弱", "example": null}, {"def": "(会意。小篆字形,两把弯曲的弓,彡”象毛羽之形,合起来表示柔弱。本义气力小;势力差)", "example": null}, {"def": "同本义。与强”相对", "example": null}, {"def": "弱,桡也。上象桡曲,彡象毛氂桡弱也。--《说文》", "example": null}, {"def": "栋桡,本末弱也。--《易·大过》", "example": null}, {"def": "颉遇王子弱焉。--《左传·襄公二十六年》", "example": null}, {"def": "志弱而事强。--《淮南子·原道》", "example": null}, {"def": "辅隙者则国必弱。--《孙子·谋攻》", "example": null}, {"def": "众散为弱。--《左传·哀公十年》", "example": null}, {"def": "有土者不可以言贫,有民者不可以言弱。--《商君书·错法》", "example": null}, {"def": "两争曰弱。--《周书·武顺》", "example": null}, {"def": "然操能克绍,以弱为强者,非惟天时,抑亦人谋也。--陈寿《隆中对》", "example": null}, {"def": "弱ruò", "example": null}, {"def": "⒈力小，势差，跟\\"强\\"相对体～。瘦～。软～。力～。", "example": null}, {"def": "⒉不够，差一点儿四分之三～。", "example": null}, {"def": "⒊〈古〉年少方～（方正）。", "example": null}, {"def": "⒋减少，丧亡又～了一个。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296653922345','鄀','1','ruò','','8',NULL,'[{"def": "鄀ruò 1.春秋列国名。古鄀地有上鄀﹑下鄀之分。(1)上鄀，一作\\"若\\"，在今湖北宜城东南，后灭于楚，春秋后期为楚都。《左传．定公六年》\\"楚国大惕，惧亡……于是乎自", "example": null}, {"def": "郢迁鄀。\\"《文选．曹植》\\"投戈编鄀，稽颡汉北。\\"李善注\\"《汉书》南郡有鄀县。\\"张铣注\\"编鄀，二县名。\\"唐刘元济《经庐岳回望江州想洛川有作》诗\\"云雨", "example": null}, {"def": "散吴会，风波腾鄢鄀。\\"(2)下鄀。金文亦作\\"蠚\\"﹑或\\"h\\"。地在今河南省内乡县﹑陕西省商州市之间◇灭于晋，为晋邑。《左传．僖公二十五年》\\"秦晋伐鄀。\\"杜预注\\"鄀", "example": null}, {"def": "本在商密，秦晋界上小国。\\"参阅郭沫若《两周金文辞大系考释》。", "example": null}]','chinese-xinhua','0'),
