('2101143296653922389','丧','1','sànɡ','一','8',NULL,'[{"def": "丧", "example": null}, {"def": "(会意。小篆字形,上面是哭’,下面是亡”。表示哭已死去的人。本义丧失)", "example": null}, {"def": "同本义", "example": null}, {"def": "喪,亡也。--《说文》", "example": null}, {"def": "东北丧朋。--《易·坤》。马注失也。”", "example": null}, {"def": "受禄无丧。--《诗·大雅·皇矣》", "example": null}, {"def": "问丧无夫子乎。又,丧人无以为宝。--《礼记·檀弓》", "example": null}, {"def": "宣王既丧南国之师。--《国语·周语》", "example": null}, {"def": "非独贤者有是心也,人皆有之,贤者能勿丧耳。--《孟子·告子上》", "example": null}, {"def": "偃王行仁义而丧其国。--《韩非子·五蠹》", "example": null}, {"def": "又如丧明(眼睛失明);丧检(丧失德行,失去检点);丧履(失去庇护);丧精(失神);丧心(心理反常;丧失理智);丧志(丧失心志)", "example": null}, {"def": "丧（喪）sāng有关死者的事～事。治～。", "example": null}, {"def": "丧（喪）sàng", "example": null}, {"def": "⒈失掉，死亡～失。～胆。～命。", "example": null}, {"def": "⒉", "example": null}, {"def": "①事情进行不顺利而情绪低落垂头～气。", "example": null}, {"def": "②迷信者所谓\\"不吉利\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296653922390','嗓','1','sǎnɡ','口','13',NULL,'[{"def": "嗓〈名〉", "example": null}, {"def": "喉咙", "example": null}, {"def": "嗓音", "example": null}, {"def": "嗓", "example": null}, {"def": "爱打击、揭发别人的短处或隐私", "example": null}, {"def": "播开门闩钻进来,抹抹索索找饭嗓。--清·蒲松龄《聊斋俚曲集》", "example": null}, {"def": "嗓sǎng", "example": null}, {"def": "⒈喉咙。～子。", "example": null}, {"def": "⒉声带与发出的声音低～音。高～儿。", "example": null}]','chinese-xinhua','0'),
('2101143296653922391','搡','1','sǎnɡ','扌','13',NULL,'[{"def": "搡〈动〉", "example": null}, {"def": "被丁言志搡了一交。--《儒林外史》", "example": null}, {"def": "伊…装好一碗饭,搡在七斤的面前。--鲁迅《呐喊》", "example": null}, {"def": "搡sǎng用力推使力～。将他～了个跟头。", "example": null}, {"def": "搡sàng 1.顶撞。", "example": null}]','chinese-xinhua','0'),
('2101143296653922392','磉','1','sǎnɡ','石','15',NULL,'[{"def": "磉〈名〉", "example": null}, {"def": "柱子底下的石礅", "example": null}, {"def": "磉,石磉也。--《说文》", "example": null}, {"def": "又如磉石敦;石磉。如磉石;磉盘(柱下石礅)", "example": null}, {"def": "磉sǎng柱子底下的石墩～盘。", "example": null}]','chinese-xinhua','0'),
