('2101143296666505241','霎','1','shà','雨','16',NULL,'[{"def": "霎〈名〉", "example": null}, {"def": "(从雨,妾声。本义小雨)", "example": null}, {"def": "同本义", "example": null}, {"def": "很短时间;瞬间", "example": null}, {"def": "小街上霎时间沉寂起来。--《梁生宝买稻种》", "example": null}, {"def": "又如霎那间(片刻间);霎时间(极短时间)", "example": null}, {"def": "霎,雨声。--《集韵》", "example": null}, {"def": "又连用,多指风雨声。如霎霎(状声词,形容风雨声)", "example": null}, {"def": "用同闸”。水闸", "example": null}, {"def": "泾水内旧有石霎,以堰水入白渠溉田。--清·顾炎武《天下郡国利病书》", "example": null}, {"def": "霎", "example": null}, {"def": "用同眨”。眼睛闭上又立刻睁开", "example": null}, {"def": "像对着我们霎眼。--刘复《敲冰》", "example": null}, {"def": "霎shà", "example": null}, {"def": "⒈小雨。", "example": null}, {"def": "⒉一会儿，短暂的时间～时。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296666505242','厦','1','shà','厂','12',NULL,'[{"def": "厦  sha", "example": null}, {"def": "(厦俗作厦。古通作夏。形声。从广,夏声。广表示房屋。夏”古有大”的意思。见《尔雅·释诂》。本义大屋子)", "example": null}, {"def": "同本义", "example": null}, {"def": "安得广厦千万间,大庇天下寒士俱欢颜。--唐·杜甫《茅屋为秋风所破歌》", "example": null}, {"def": "又如厦子(小厢房;小屋);厦处(住所)", "example": null}, {"def": "门庑;廊屋;披屋", "example": null}, {"def": "厦", "example": null}, {"def": "大", "example": null}, {"def": "厦屋一揆,华屏齐荣。--晋·左思《魏都赋》", "example": null}, {"def": "又如厦屋(高大的屋)", "example": null}, {"def": "厦  xia", "example": null}, {"def": "形声。从厂,夏声。厂山厓石穴。本义大屋) 厦门的简称", "example": null}, {"def": "厦（廱）xià", "example": null}, {"def": "⒈厦门市，在福建省。", "example": null}, {"def": "厦（廱）shà", "example": null}, {"def": "⒈大房子大～。广～。", "example": null}]','chinese-xinhua','0'),
