('2101143296666505267','讪','1','shàn','讠','5',NULL,'[{"def": "讪", "example": null}, {"def": "(形声。从言,山声。本义毁谤)", "example": null}, {"def": "同本义", "example": null}, {"def": "讪,谤也。与姗略同。--《说文》", "example": null}, {"def": "讪,诽毁也。--《苍颉篇》", "example": null}, {"def": "恶居下流而讪上者。--《论语》", "example": null}, {"def": "居下而讪上,处贫而非富。--《盐铁论·地广》", "example": null}, {"def": "有谏而无讪。--《礼记·少仪》", "example": null}, {"def": "又如讪上(毁谤在上位的人);讪议(毁谤议论);讪刺(毁谤讽刺)", "example": null}, {"def": "讥刺,挖苦", "example": null}, {"def": "见朝廷有所任使,非其资序,则相议而讪之。--王安石《上仁宗皇帝言事书》", "example": null}, {"def": "偏加些恶谑毒讪。--清·孔尚任《桃花扇》", "example": null}, {"def": "又如讪人(让人下不了台;小看人);讪语(说讽剌话);讪嘴(斗嘴);讪侮(讥笑轻侮);讪诮(", "example": null}, {"def": "讪shàn", "example": null}, {"def": "⒈讥笑，诽谤～笑。～言。", "example": null}, {"def": "⒉难为情，不好意思的样子搭～。她～～地回家了。", "example": null}]','chinese-xinhua','0'),
('2101143296666505268','汕','1','shàn','氵','6',NULL,'[{"def": "汕", "example": null}, {"def": "鱼游水", "example": null}, {"def": "汕,鱼游水貌。从水,山声。--《说文》", "example": null}, {"def": "南有嘉鱼,焌然汕汕。--《诗·小雅·南有嘉鱼》", "example": null}, {"def": "又如汕汕(鱼游水的样子)", "example": null}, {"def": "用鱼笼捕鱼", "example": null}, {"def": "冲洗,冲刷", "example": null}, {"def": "骗人,诱人上当", "example": null}, {"def": "作成圈套儿来汕你的。--《儿女英雄传》", "example": null}, {"def": "汕 〈名〉", "example": null}, {"def": "鱼梁", "example": null}, {"def": "羜谓之汕。--《尔雅·释器》", "example": null}, {"def": "汕头的简称", "example": null}, {"def": "汕shàn汕头市，在广东省。", "example": null}, {"def": "汕shuàn 1.一种烹饪方法。把薄切的肉片放在沸水中烫熟。参见\\"汕?子\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296666505269','疝','1','shàn','疒','8',NULL,'[{"def": "疝〈名〉", "example": null}, {"def": "心腹气痛", "example": null}, {"def": "疝,腹痛也。从疒,山声。--《说文》", "example": null}, {"def": "腹痛不得大小便,病名曰疝。--《素问·长俠节论》", "example": null}, {"def": "五藏六府疝十六病四十卷。--《汉书·艺文志》。注心腹气病。”", "example": null}, {"def": "又如疝瘕(病名,腹中气郁积结块所致)", "example": null}, {"def": "疝气", "example": null}, {"def": "疝shàn疝气，病名。常见于腹腔内脏向腹腔外突出鼓起膈～。股～。腹股沟～。", "example": null}]','chinese-xinhua','0'),
('2101143296666505270','扇','1','shàn','户','10',NULL,'[{"def": "扇", "example": null}, {"def": "摇扇", "example": null}, {"def": "吹,扇助也。--《方言十二》", "example": null}, {"def": "艳妻扇方处。--《诗·小雅·十月之交》。毛本作煽。", "example": null}, {"def": "一扇息火,二扇生风,三扇下雨。--《西游记》", "example": null}, {"def": "又如扇风(摇扇以生风);扇暍(传说周武王曾替中暑人扇风取凉);扇枕温衾(对父母老人极尽孝道之意)", "example": null}, {"def": "以掌批面", "example": null}, {"def": "施展", "example": null}, {"def": "宋官御史,坐行赇免,居林下,大扇威虐。--《聊斋志异》", "example": null}, {"def": "扇 〈动〉", "example": null}, {"def": "煽动、鼓动", "example": null}, {"def": "奸谄颇相扇构。--《晋书·谢安传》", "example": null}, {"def": "又如扇构(煽动众人借机迫害);扇诱(煽惑引诱);扇惑(煽动", "example": null}, {"def": "扇shān", "example": null}, {"def": "⒈摇动扇子或别的东西～ ～风。～炉子。", "example": null}, {"def": "⒉使手掌打～他两巴掌。", "example": null}, {"def": "⒊鼓动，唆使～动。～风点火。", "example": null}, {"def": "扇shàn", "example": null}, {"def": "⒈摇动生风（取凉）的用具葵～。纸～子。电～。", "example": null}, {"def": "⒉门、窗上可以开合的板片物门～。窗～。", "example": null}, {"def": "⒊量词门两～。四～屏。", "example": null}]','chinese-xinhua','0'),
