('2101143296666505277','缮','1','shàn','纟','15',NULL,'[{"def": "缮", "example": null}, {"def": "(形声。从糸,善声。本义修补;修整)", "example": null}, {"def": "同本义", "example": null}, {"def": "缮,补也。--《说文》", "example": null}, {"def": "缮完葺墙,以待宾客。--《左传·襄公三十一年》", "example": null}, {"def": "凡治,故造新皆谓之缮也。--《珠丛》", "example": null}, {"def": "缮城郭。--《左传·襄公三十年》", "example": null}, {"def": "又如缮治(修补;整治);缮完(修整,营建);缮饰(修理整治;修葺装饰);缮理(修理;修缮);缮修(修缮;修补);缮造(修造);缮性(涵养本性);缮葺(修理房屋、墙垣等)", "example": null}, {"def": "制造;整治", "example": null}, {"def": "缮兵甲,具卒乘。--《左传·隐公元年》", "example": null}, {"def": "又如缮甲(整治武器装备);缮兵(整治武备);缮理(整治,整顿)", "example": null}, {"def": "工整地抄写", "example": null}, {"def": "然后", "example": null}, {"def": "缮shàn", "example": null}, {"def": "⒈修补，整治修～。～治。", "example": null}, {"def": "⒉抄写～写文稿。", "example": null}]','chinese-xinhua','0'),
('2101143296666505278','嬗','1','shàn','女','16',NULL,'[{"def": "嬗〈动〉", "example": null}, {"def": "(形声。从女,亶声。①本义缓。②变迁。如嬗变)", "example": null}, {"def": "自然的演变", "example": null}, {"def": "形气转续,变化而嬗。--贾谊《鹏鸟赋》", "example": null}, {"def": "又如嬗迭(演变)", "example": null}, {"def": "禅位", "example": null}, {"def": "尧嬗以天下。--《汉书·律历志下》", "example": null}, {"def": "更替", "example": null}, {"def": "五年之间,号令三嬗。--《史记·秦楚之际月表》", "example": null}, {"def": "又如嬗代(嬗更,嬗替,嬗易。更替)", "example": null}, {"def": "传与,传递◇作禅”", "example": null}, {"def": "变化而嬗。--《汉书·贾谊传》。注相传与也。”", "example": null}, {"def": "以不同形相嬗也。--《淮南子·精神》。高诱注嬗,传也。”", "example": null}, {"def": "尧嬗以天下。--《汉书·律历志下》", "example": null}, {"def": "留其人于京师,而无", "example": null}, {"def": "嬗shàn变迁，更替～变。", "example": null}, {"def": "嬗chán 1.见\\"嬗娟\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296666505279','擅','1','shàn','扌','16',NULL,'[{"def": "擅〈动〉", "example": null}, {"def": "(形声。从手,亶声。本义独揽,专权)", "example": null}, {"def": "同本义", "example": null}, {"def": "擅,专也。--《说文》。按,谓媾壹也。", "example": null}, {"def": "权臣擅命也。--《诗·狡童序》", "example": null}, {"def": "擅将其兵。--《史记·魏豹彭越传》", "example": null}, {"def": "今乱世之君臣,区区然皆擅一国之利。--《商君书·修权》", "example": null}, {"def": "又如擅恣(专权放肆);擅政(独揽朝政);擅柄(独揽权柄);擅朝(独揽朝政)", "example": null}, {"def": "占有,据有", "example": null}, {"def": "方五百里,赵独擅之。--《战国策·秦策》", "example": null}, {"def": "又如擅宠(专宠,特受宠信);擅利(独占利益);擅市(独占市场);擅夕(独占宠爱);擅兵(掌握兵权);擅爱(独占宠爱);擅声(享有名声);擅名(享有名声)", "example": null}, {"def": "擅shàn", "example": null}, {"def": "⒈独揽，独占～权。～利。", "example": null}, {"def": "⒉自作主张～自决断。～离职守。", "example": null}, {"def": "⒊专长～长。～书画。", "example": null}, {"def": "⒋〈古〉据有，拥有独～。", "example": null}]','chinese-xinhua','0'),
