('2101143296674893838','伤','1','shānɡ','亻','6',NULL,'[{"def": "伤", "example": null}, {"def": "(形声。从人。本义皮肉破损处;创伤)", "example": null}, {"def": "同本义", "example": null}, {"def": "伤,创也。--《说文》", "example": null}, {"def": "命理瞻伤。--《礼记·月令》。注创之浅者曰伤。”", "example": null}, {"def": "以杙抉其伤。--《左传·襄公十七年》", "example": null}, {"def": "无面伤。--《左传·哀公元年》", "example": null}, {"def": "匠石运斤成风,听而斵之,尽垩而鼻不伤。--《庄子·徐无鬼》", "example": null}, {"def": "唂其叶,则口烂而受伤。--《庄子·人间世》", "example": null}, {"def": "则援剑戟而逐之,不避死伤。--《荀子·正论》", "example": null}, {"def": "其伤于缚者,即幸留,病数月乃瘳。--清·方苞《狱中杂记》", "example": null}, {"def": "城中死伤日积,巷哭声相闻。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "又如枪伤;两虎相斗,必有一伤;负", "example": null}, {"def": "伤（傷）shāng", "example": null}, {"def": "⒈受到损害、损坏受～。枪～。重～。", "example": null}, {"def": "⒉损害，妨碍～害。损～。～点皮肉。无～大局。", "example": null}, {"def": "⒊遭受某种致病因素而得病～风。～暑。", "example": null}, {"def": "⒋悲哀～心。悲～。", "example": null}, {"def": "⒌使用过度以致厌烦这种菜吃～了。", "example": null}, {"def": "⒍得罪，诋毁有意中～。出口～人。", "example": null}, {"def": "⒎", "example": null}, {"def": "①伤寒杆菌引起的急性传染病。", "example": null}, {"def": "②中医学上泛指各种热病或风寒引起的疾病。", "example": null}]','chinese-xinhua','0'),
('2101143296674893839','殇','1','shānɡ','歹','9',NULL,'[{"def": "殇", "example": null}, {"def": "(形声。从歺,伤省声。歺”是剔肉剩下的骨头,与死”有关。本义未成年而死)", "example": null}, {"def": "同本义。亦称殇折”、殇夭”", "example": null}, {"def": "殇,不成人也。--《说文》", "example": null}, {"def": "年十九至十六为长殇,十五至十二为中殇,十一至八岁为下殇,不满八岁以下为无服之殇。--《仪礼·丧服传》", "example": null}, {"def": "未家短折曰殇。--《周礼·谥法》", "example": null}, {"def": "固知一死生为虚诞,齐彭殇为亡作。--晋·王羲之《兰亭集序》", "example": null}, {"def": "又如殇折,殇夭(夭折)", "example": null}, {"def": "横死,非正常死亡", "example": null}, {"def": "殇", "example": null}, {"def": "未成年而死的人。亦称殇子”", "example": null}, {"def": "病变而药不变,向之寿民,今", "example": null}, {"def": "殇（殤）shāng未到成年就死亡。", "example": null}]','chinese-xinhua','0'),
('2101143296674893840','商','1','shānɡ','口','11',NULL,'[{"def": "商〈动〉", "example": null}, {"def": "(会意。从阩,章省声。本义计算,估量)", "example": null}, {"def": "同本义", "example": null}, {"def": "商,从外知内也。--《说文》。段注汉律志云商之言章也。物成熟可章度也。”", "example": null}, {"def": "商,度也。--《广雅》", "example": null}, {"def": "虏必商军进退,稍引去。--《汉书·赵充国传》", "example": null}, {"def": "又如商略(估计);商算(计算);商度(测量);商羊(传说中一种能预知雨的鸟);商谜(猜谜);商功(古代九章算术之一,即测量体积、计算工程用工的方法)", "example": null}, {"def": "引申为商议,商讨;商量", "example": null}, {"def": "商兑。--《易·兑》。注商量裁判之谓也。”", "example": null}, {"def": "操与众商议,欲立植为世子。--《三国演义·杨修之死》", "example": null}, {"def": "又如商通(勾通;相互商", "example": null}, {"def": "商shāng", "example": null}, {"def": "⒈买卖，做生意，也指做生意的人～业。～人。经～。通～。富～。", "example": null}, {"def": "⒉交换意见，讨论～量。～议。～讨。相～。", "example": null}, {"def": "⒊除法中的得数二除十～五。六被三除～数是二。", "example": null}, {"def": "⒋星宿名。二十八宿之一，即\\"心\\"宿。", "example": null}, {"def": "⒌〈古〉五音（宫～角徵羽）之一。相当于简谱中的\\"2\\"。", "example": null}, {"def": "⒍朝代名。商朝，约在公元前16世纪至公元前11世纪。第一代君主是成汤。公元前十四世纪中叶，商王盘庚迁都于殷之后，又称殷朝（殷在今河南什阳市西北）。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}]','chinese-xinhua','0'),
('2101143296674893841','觞','1','shānɡ','角','12',NULL,'[{"def": "觞", "example": null}, {"def": "(形声。从角,傷声。金文从爵”。本义古代盛酒器) 同本义", "example": null}, {"def": "觞,爵实曰觞,虚曰觯。--《说文》", "example": null}, {"def": "请行觞。--《礼记·投壶》", "example": null}, {"def": "引壶觞以自酌,眄庭柯以怡颜。--晋·陶渊明《归去来兮辞》", "example": null}, {"def": "又如觞勺(指觞与勺。都是盛酒器);觞令(即酒令。今俗谓猜拳、划拳);觞豆(酒器与笾豆。皆为饮食的用具。借喻饮食);觞爵(酒器);觞觥(泛指酒器);觞酌(饮酒器)", "example": null}, {"def": "觞", "example": null}, {"def": "向人敬酒", "example": null}, {"def": "管仲觞桓公。--《吕氏春秋》", "example": null}, {"def": "觞酒豆肉。--《礼记·表记》", "example": null}, {"def": "王觞将军。--《战国策·秦策》", "example": null}, {"def": "楚王觞之。--《庄子·徐无鬼》", "example": null}, {"def": "又如", "example": null}, {"def": "觞（觴）shāng〈古〉喝酒用的器具举～棕。", "example": null}]','chinese-xinhua','0'),
('2101143296674893842','墒','1','shānɡ','土','14',NULL,'[{"def": "墒〈名〉", "example": null}, {"def": "耕地时开出的垄沟", "example": null}, {"def": "田地里土壤的湿度", "example": null}, {"def": "墒沟", "example": null}, {"def": "墒情", "example": null}, {"def": "墒土", "example": null}, {"def": "保住墒土,按时播种", "example": null}, {"def": "墒shāng土壤里的湿度～情。保～。验～。够～。", "example": null}]','chinese-xinhua','0'),
