('2101143296674893862','筲','1','shāo','竹','13',NULL,'[{"def": "筲", "example": null}, {"def": "(形声。从竹,肖声。本义盛饭的竹器)", "example": null}, {"def": "同本义", "example": null}, {"def": "桶", "example": null}, {"def": "筲箕", "example": null}, {"def": "筲shāo", "example": null}, {"def": "⒈〈古〉一种竹器。", "example": null}, {"def": "⒉桶水～。两～水。", "example": null}]','chinese-xinhua','0'),
('2101143296674893863','艄','1','shāo','舟','13',NULL,'[{"def": "艄〈名〉", "example": null}, {"def": "船尾", "example": null}, {"def": "舵", "example": null}, {"def": "本,本钱", "example": null}, {"def": "要想日子过得好,穷人指望翻个艄。--《中国歌谣资料第二集》", "example": null}, {"def": "艄公", "example": null}, {"def": "老艄公不顾自己正在发喘……二话不说,驾起船,直奔河心。--《为了六十一个阶级弟兄》", "example": null}, {"def": "艄shāo船尾船～。又指船的舵掌～。～公（掌舵的人。〈引〉船夫）。", "example": null}]','chinese-xinhua','0'),
