('2101143296674893867','捎','1','shāo','扌','10',NULL,'[{"def": "捎〈动〉", "example": null}, {"def": "(形声。从手,肖声。本义选取)", "example": null}, {"def": "同本义", "example": null}, {"def": "捎,择也。--《广雅·释诂》", "example": null}, {"def": "捎,自关已西,凡取物之上为挢捎。--《说文》", "example": null}, {"def": "捎,选也。--《方言》", "example": null}, {"def": "掠拂", "example": null}, {"def": "风捎檐滴难开幌。--张耒《春阴》", "example": null}, {"def": "曳捎星之旃。--杨雄《羽猎赋》", "example": null}, {"def": "又如捎(抽打割勒。捎拂掠);捎儿(手巾);捎星(拂到天上的星,形容极高);捎捩(拂掠转折)", "example": null}, {"def": "破除;砍杀;芟除", "example": null}, {"def": "拔剑捎罗网。--曹植《野田黄雀行》", "example": null}, {"def": "捎带;顺带", "example": null}, {"def": "孟姜女时常到村口去看,希望过路的人给捎封信来。--《孟姜女》", "example": null}, {"def": "又如捎搭(装载在牲口", "example": null}, {"def": "捎shāo顺便带东西或言语给别人～带。～点东西。～个口信。", "example": null}, {"def": "捎shǎo 1.击打。", "example": null}, {"def": "捎xiāo 1.挖去;除去。", "example": null}, {"def": "捎shào 1.见\\"捎马子\\"﹑\\"捎色\\"。", "example": null}, {"def": "捎qiào 1.同\\"撬\\"。拨开，挑开。 2.同\\"俏\\"。参见\\"捎货\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296674893868','梢','1','shāo','木','11',NULL,'[{"def": "梢〈名〉", "example": null}, {"def": "(形声。从木,肖声。本义树木的末端)", "example": null}, {"def": "同本义", "example": null}, {"def": "梢,梢木也。--《说文》", "example": null}, {"def": "梢,梢擢。--《尔雅》。注谓木无枝柯,梢擢长而杀者。”", "example": null}, {"def": "开花寄树梢。--白居易《有木诗》", "example": null}, {"def": "高者挂羒长林梢。--唐·杜甫《茅屋为秋风所破歌》", "example": null}, {"def": "又如树梢;枝梢", "example": null}, {"def": "树木的枝条", "example": null}, {"def": "曳梢肆柴。--《淮南子·兵略》。注小柴也。”", "example": null}, {"def": "如梢头;梢条;梢棒(亦作哨棒”。一种兵器,木棒)", "example": null}, {"def": "事物的末尾或一段时间的尽头", "example": null}, {"def": "被云梢。--《汉书·扬雄传》", "example": null}, {"def": "又如眉梢;春梢", "example": null}, {"def": "舵尾", "example": null}, {"def": "梢,船舵尾也。--《广韵》。又", "example": null}, {"def": "梢shāo", "example": null}, {"def": "⒈树枝的末端树～儿。〈引〉末尾，末端，尽头眉～。船～。年～。", "example": null}, {"def": "⒉事情的完结，下场收～。下～。", "example": null}, {"def": "梢xiāo 1.谓流水冲激。参见\\"梢沟\\"。", "example": null}, {"def": "梢shào 1.砍伐树木的枝叶。", "example": null}]','chinese-xinhua','0'),
('2101143296674893869','烧','1','shāo','火','10',NULL,'[{"def": "烧", "example": null}, {"def": "(形声。从火,尧声。本义使物着火)", "example": null}, {"def": "同本义", "example": null}, {"def": "烧,爇也。--《说文》", "example": null}, {"def": "雏烧。--《礼记·内则》。注烧烟,于火中也。”", "example": null}, {"def": "齐之北泽烧火。--《管子·轻重甲》。注猎而行火曰烧。”", "example": null}, {"def": "卖炭翁,伐薪烧炭南山中。--唐·白居易《卖炭翁》", "example": null}, {"def": "烧尽北船,延及岸上营落。--《资治通鉴》", "example": null}, {"def": "又如干柴好烧;他把衣服烧了一个洞;烧葬(烧焚祭品);烧丹炼汞(道家用朱砂水银等物炼成金丹以求长生不老);烧糊了卷子(喻外貌丑陋);烧埋钱(烧化埋葬死人的费用);烧冷灶", "example": null}, {"def": "(敷衍不得时的人);烧利市(商人在开始营业时烧纸祭献福神);烧琴煮鹤(比喻糟蹋美", "example": null}, {"def": "烧（燒）shāo", "example": null}, {"def": "⒈使物体着火～ 火。燃～。", "example": null}, {"def": "⒉用热能使物体受热起变化～瓦。～饭。～汤。", "example": null}, {"def": "⒊烹饪方法之一炒煎～炸。蘑芋～鸭子。", "example": null}, {"def": "⒋发热，体温升高发～。高～。～退了。", "example": null}, {"def": "⒌用肥过多，致使植物枯萎、死亡～了秧蔸。", "example": null}, {"def": "烧shào 1.放火烧野草以肥田。 2.泛指野火。 3.指彩霞。", "example": null}]','chinese-xinhua','0'),
('2101143296674893870','舌','1','shé','舌','6',NULL,'[{"def": "舌〈名〉", "example": null}, {"def": "(会意。从干,从口。本义舌头)", "example": null}, {"def": "同本义", "example": null}, {"def": "舌,在口所以言也,别味也。从干,从口,会意。言犯口而出,食犯口而入也。--《说文》", "example": null}, {"def": "兑为口舌。--《易·说卦》", "example": null}, {"def": "心在窍为舌。--《素问·阴阳应象大论》", "example": null}, {"def": "人有百口,口有百舌,不能名其一处也。--《虞初新志·秋声诗自序》", "example": null}, {"def": "又如舌举(舌翘起而不能动。指理屈词穷);舌挢不下(翘起舌头。形容惊讶或害怕的样子);舌刺刺(形容嘴舌不停地说话);舌敞唇穿(舌烂辰破,舌烂唇干);舌簧(巧舌);舌干唇焦", "example": null}, {"def": "(说话过多,舌头干燥,嘴唇焦裂。形容费尽口舌、反复申说、劝道。也作舌敝唇焦)", "example": null}, {"def": "代指言语", "example": null}, {"def": "舌shé", "example": null}, {"def": "⒈辨别滋味，帮助咀嚼和发音的器官，位于口腔底部～头。", "example": null}, {"def": "⒉铃、铎等内部的锤。", "example": null}, {"def": "⒊像舌的东西帽～。火～。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
