('2101143296674893884','慑','1','shè','忄','13',NULL,'[{"def": "慑", "example": null}, {"def": "(形声。从心,聂声。本义恐惧)", "example": null}, {"def": "同本义", "example": null}, {"def": "慑,失气也。--《说文》", "example": null}, {"def": "柔气不慑。--《礼记·乐记》。注犹恐惧也。”", "example": null}, {"def": "则志不慑。--《礼记·曲礼》。注犹怯惑也。”", "example": null}, {"def": "不至于隘慑伤生。--《荀子·礼论》", "example": null}, {"def": "贼连毙者三,气慑,扬帆去。--邵长蘅《阎典史传》", "example": null}, {"def": "使其心志安于斩刈杀伐之际而不慑。--宋·苏轼《教战守》", "example": null}, {"def": "又如慑怯(畏惧);慑气(因畏惧而屏住气息);慑息(因害怕而不敢出声);慑慑(有所畏惧而丧失勇气);慑惮(畏惧忌惮);慑怖(恐惧);慑畏(畏惧);慑愕(惊讶);慑栗(恐惧战栗)", "example": null}, {"def": "威胁", "example": null}, {"def": "威动天地,声", "example": null}, {"def": "慑（懾、慴）shè恐惧，害怕～服。震～。无～意。", "example": null}]','chinese-xinhua','0'),
('2101143296674893885','厍','1','shè','厂','6',NULL,'[{"def": "厍", "example": null}, {"def": "姓。库的俗字", "example": null}, {"def": "厍钧为金城太守。--《后汉书·窦融传》", "example": null}, {"def": "厍shè〈方〉村庄。多见于村庄名。", "example": null}]','chinese-xinhua','0'),
('2101143296674893886','设','1','shè','讠','6',NULL,'[{"def": "设", "example": null}, {"def": "(会意。从言,从殳。本义摆设;陈列)", "example": null}, {"def": "同本义", "example": null}, {"def": "詏,施陈也。--《说文》", "example": null}, {"def": "钟鼓既设。--《诗·小雅·彤弓》", "example": null}, {"def": "整设于门外。--《礼记·月令》。注陈也。”", "example": null}, {"def": "规矩陈设。--《礼记·经解》", "example": null}, {"def": "张乐设饮。--《战国策·秦策》", "example": null}, {"def": "入其舍,则密室垂帘,帘外设香几。--《聊斋志异·促织》", "example": null}, {"def": "设树险阻。--《淮南子·本经》", "example": null}, {"def": "设酒杀鸡作食。--晋·陶渊明《桃花源记》", "example": null}, {"def": "又如陈设(摆设);设醮修禳(僧道为禳除灾祟而设的道场);设蓍(占卦。蓍蓍草,古人常用其占卜);设弧(摆设木弓。表示生男);设帨(摆设佩巾。表示", "example": null}, {"def": "设shè", "example": null}, {"def": "⒈布置，装置，安排～置。～立。～防。", "example": null}, {"def": "⒉筹划，规划，制定方案、图样等～法。～想。～计。", "example": null}, {"def": "⒊假使，如果，若是，假想～若。～如。～或。假～。", "example": null}, {"def": "⒋", "example": null}, {"def": "①工作上、生产上、生活上等所需要的各种设施和器械用品。", "example": null}, {"def": "②设置以备施用。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296674893887','社','1','shè','礻','7',NULL,'[{"def": "社〈名〉", "example": null}, {"def": "(会意。从示从土。土亦声。社土同字。本义土地神)", "example": null}, {"def": "同本义", "example": null}, {"def": "社,地主也。--《说文》", "example": null}, {"def": "共工之子句龙为社神。--《春秋传》", "example": null}, {"def": "社,土也。--《论衡·顺鼓》", "example": null}, {"def": "以社以方。--《诗·小雅·甫田》。传社,后土也。”", "example": null}, {"def": "命民社。--《礼记·月令·仲春》。注社,后土也。”", "example": null}, {"def": "故社,祭社也。--《荀子·礼论》。注社,土神。”", "example": null}, {"def": "故祀以为社。--《国语·鲁语上》。注社,后土之神也。”", "example": null}, {"def": "不谓之土”何?封土为社,故变名谓之社”,利于众土也。--《白虎通·社稷》", "example": null}, {"def": "又", "example": null}, {"def": "社者,土地之神也。", "example": null}, {"def": "后土为社。--《左传", "example": null}, {"def": "社shè", "example": null}, {"def": "⒈〈古〉迷信指土地神。又指祭祀土地神或祭祀土地神的地方。", "example": null}, {"def": "⒉指某些集体组织、团体、机构合作～。集会结～。信用～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①以一定的物质生产活动为基础与相应的上层建筑构成的总体原始～会。奴隶～会。封建～会。资本主义～会。社会主义～会。", "example": null}, {"def": "②指同阶层的人群贵族～会。上层～会。", "example": null}]','chinese-xinhua','0'),
