('2101143296683282453','申','1','shēn','田','5',NULL,'[{"def": "申〈动〉", "example": null}, {"def": "同本义;约束", "example": null}, {"def": "申,束身也。--《说文》", "example": null}, {"def": "约车申辕。--《淮南子·原道》。注束也。”", "example": null}, {"def": "畏忌自申。--《汉书·韦元成传》。注言自约束也。”", "example": null}, {"def": "勒兵申教令。--《汉书·元帝纪》", "example": null}, {"def": "朱绿带申加大带于上。--《礼记·杂记》", "example": null}, {"def": "申体防以自持。--曹植《洛神赋》", "example": null}, {"def": "又如申束(约束)", "example": null}, {"def": "舒展。通伸”。伸展,伸张", "example": null}, {"def": "形可劫而使诎申。--《荀子·解蔽》", "example": null}, {"def": "大夫执圭而使,所以申信也。--《礼记·郊特牲》", "example": null}, {"def": "咎犯申其左臂而诎五指。--《说苑·正谏》", "example": null}, {"def": "行止屈申,与时息兮。--班超《北征赋》", "example": null}, {"def": "又如申张(伸张;扩大", "example": null}, {"def": "申shēn", "example": null}, {"def": "⒈地支的第九位。也用作次序第九。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊陈述，表白～述。～诉。～明。～辩。", "example": null}, {"def": "⒋告诫三令五～。", "example": null}, {"def": "⒌上海市的简称。", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
