('2101143296683282482','盛','1','shènɡ','皿','11',NULL,'[{"def": "盛  cheng", "example": null}, {"def": "放在祭器里的谷物", "example": null}, {"def": "盛,黍稷在器中以祀者也。--《说文》", "example": null}, {"def": "天子亲耕以共粢盛。--《谷梁传·桓公十四年》。注黍稷曰粢,在器曰盛。”", "example": null}, {"def": "又如粢盛", "example": null}, {"def": "器皿,如杯、碗之类", "example": null}, {"def": "旨酒一盛兮。--《左传·哀公十三年》。注一器也。”", "example": null}, {"def": "食粥于盛。--《礼记·丧大记》", "example": null}, {"def": "春秋时国名", "example": null}, {"def": "盛", "example": null}, {"def": "把东西放进去", "example": null}, {"def": "用勺舀或运送", "example": null}, {"def": "容纳", "example": null}, {"def": "盛 chéng", "example": null}, {"def": "①把饭、菜等放入碗、盘、桶等器具内。", "example": null}, {"def": "②容纳电影院可～两千人。又见shèng。", "example": null}, {"def": "盛chéng", "example": null}, {"def": "⒈容纳，将东西放入这车可～八人。～饭～菜。～入电冰箱。", "example": null}, {"def": "盛shèng", "example": null}, {"def": "⒈兴旺，繁茂兴～。旺～。昌～。茂～。～极一时。", "example": null}, {"def": "⒉强烈，炽烈～怒。年少气～。", "example": null}, {"def": "⒊丰富，规模大～产。～大。～行。～传。～况。～会。", "example": null}, {"def": "⒋深，厚～夏。～情。", "example": null}, {"def": "⒌华丽～装。", "example": null}, {"def": "⒍声望大～名之下，其实难副。。", "example": null}]','chinese-xinhua','0'),
('2101143296683282483','剩','1','shènɡ','刂','12',NULL,'[{"def": "剩", "example": null}, {"def": "(形声。从刀,乘声。本义剩余;余下)", "example": null}, {"def": "同本义", "example": null}, {"def": "一屠晚归,担中肉尽,止有剩骨。--《聊斋志异·狼三则》", "example": null}, {"def": "使野无闲田,民无剩力。--清·洪亮吉《治平篇》", "example": null}, {"def": "又如剩员(多余的人员);剩语(多余的话);剩货", "example": null}, {"def": "多", "example": null}, {"def": "且容侬,多种竹,剩栽梅。--宋·方岳《最高楼》", "example": null}, {"def": "剩", "example": null}, {"def": "表示程度,相当于更”、更加”", "example": null}, {"def": "剩,盖也。--《字汇》", "example": null}, {"def": "表示无条件限制,相当于尽管”", "example": null}, {"def": "老去风情应不到,凭君剩把芳尊倒。--宋·欧阳修《蝶恋花》", "example": null}, {"def": "剩", "example": null}, {"def": "余留下来", "example": null}, {"def": "剩（賸）shèng多余，余留下的～余。～菜。～钱。", "example": null}]','chinese-xinhua','0'),
('2101143296683282484','胜','1','shènɡ','月','9',NULL,'[{"def": "胜", "example": null}, {"def": "(形声。从力,朕声。本义胜任,禁得起)", "example": null}, {"def": "同本义", "example": null}, {"def": "胜,任也。--《说文》", "example": null}, {"def": "胜,克也。--《尔雅》", "example": null}, {"def": "莫之胜说。--《易·遯》。虞注能也。”", "example": null}, {"def": "武王靡不胜。--《诗·商颂·烈祖》。传任也。”", "example": null}, {"def": "子有幼弱不胜养为累者。--《管子·入国》。注堪也。”", "example": null}, {"def": "白头搔更短,浑欲不胜簪。--唐·杜甫《春望》", "example": null}, {"def": "言讫,?", "example": null}, {"def": "又如不胜其苦(苦得受不住);胜任愉快(有能力承担并能愉快地完成任务);胜兵(能充当士兵参战的人)", "example": null}, {"def": "战胜,打败", "example": null}, {"def": "胜殷遏刘。--《诗·周颂·武》", "example": null}, {"def": "胜,克", "example": null}, {"def": "胜（勝）", "example": null}, {"def": "⒈赢，跟\\"败\\"、\\"负\\"相对～利。～仗。～不骄。", "example": null}, {"def": "⒉打败（对方）战～。以弱～强。", "example": null}, {"def": "⒊超过～过。～似。～于。略～一筹。", "example": null}, {"def": "⒋优美的，盛大的～地。～景。～会。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍（旧读shēng）", "example": null}, {"def": "①能担当得起或承受得住～任愉快。不～其烦。", "example": null}, {"def": "②尽不可～数。", "example": null}, {"def": "③又叫\\"肽\\"。见肽。", "example": null}, {"def": "胜xīng 1.同\\"腥\\"。 2.瘦。参见\\"膌胜\\"。", "example": null}, {"def": "胜qìng 1.见\\"胜遇\\"。", "example": null}, {"def": "胜shèng 1.能够承受，禁得起。 2.尽。 3.陵，欺凌。", "example": null}]','chinese-xinhua','0'),
('2101143296683282485','嵊','1','shènɡ','山','13',NULL,'[{"def": "嵊", "example": null}, {"def": "山名。嵊山,在浙江省嵊县东", "example": null}, {"def": "嵊,山名。在剡县也。--《广韵》", "example": null}, {"def": "嵊县", "example": null}, {"def": "嵊shèng嵊县，在浙江省。", "example": null}]','chinese-xinhua','0'),
