('2101143296683282491','省','1','shěnɡ','目','9',NULL,'[{"def": "省  sheng", "example": null}, {"def": "(会意。从眉省,从屮。甲骨文和小篆字形,象眼睛观察草。本义察看)", "example": null}, {"def": "王宫禁署,禁中", "example": null}, {"def": "禁台省中,连闼对门。--左思《魏都赋》", "example": null}, {"def": "又如省中(宫禁之中);省内(宫禁之内)", "example": null}, {"def": "官署名称", "example": null}, {"def": "投词院直至省,将冤屈叫几声,诉出咱这实情。--《陈州粜米》", "example": null}, {"def": "行政区域名", "example": null}, {"def": "宋,怀庆青华镇人,工技击,七省好事者皆来学。--明·魏禧《大铁椎传》", "example": null}, {"def": "又如省元(礼部考试中的第一", "example": null}, {"def": "省xǐng", "example": null}, {"def": "⒈检查，察看反～。览～远方。", "example": null}, {"def": "⒉知觉不～人事。", "example": null}, {"def": "⒊觉悟～悟。", "example": null}, {"def": "⒋看望父母或亲的尊长～亲。", "example": null}, {"def": "省shěng", "example": null}, {"def": "⒈我国第一级地方行政区域河北～。四川～。", "example": null}, {"def": "⒉节约，减少，化费少节～。～吃。～用。～时间。～财物。", "example": null}, {"def": "⒊简略～略。～称。", "example": null}, {"def": "⒋〈古〉我国官署名中书～。", "example": null}, {"def": "省xiǎn 1.古代天子秋季狩猎。 2.指秋季狩猎前的祭祀。", "example": null}]','chinese-xinhua','0'),
('2101143296683282492','眚','1','shěnɡ','目','10',NULL,'[{"def": "眚", "example": null}, {"def": "(形声。从目,生声。本义眼睛生翳长膜)", "example": null}, {"def": "同本义", "example": null}, {"def": "眚,目病生翳也。--《说文》。挚", "example": null}, {"def": "目眚昏花烛穗垂。--范成大《晚步宣华旧苑》", "example": null}, {"def": "又如眚目(眼病之一。眼睛生白翳)", "example": null}, {"def": "通省”。削减", "example": null}, {"def": "以荒政十有二,聚万民,……七曰眚礼。--《周礼·地官·大司徒》", "example": null}, {"def": "眚", "example": null}, {"def": "过失", "example": null}, {"def": "眚,过也。--《广韵》", "example": null}, {"def": "孤之过也,大夫何罪?且吾不以一眚掩大德。--《左传·僖公三十三年》", "example": null}, {"def": "又如眚灾(亦作眚烖”。因过失而造成灾害)", "example": null}, {"def": "日食", "example": null}, {"def": "非日月之眚。--《左传·庄公二十五年》。注月侵日为眚", "example": null}, {"def": "眚shěng", "example": null}, {"def": "⒈眼睛生翳目～。", "example": null}, {"def": "⒉过失。", "example": null}, {"def": "⒊灾祸。", "example": null}, {"def": "⒋疾苦。", "example": null}]','chinese-xinhua','0'),
