('2101143296683282529','飠','1','shí','','8',NULL,'[{"def": "飠shí 1.汉字部首。通称\\"食字旁\\"。用\\"食\\"作部首的例字有﹕饮﹑饲﹑饰等。", "example": null}]','chinese-xinhua','0'),
('2101143296683282530','识','1','shí','讠','7',NULL,'[{"def": "识", "example": null}, {"def": "(形声。从言。戠声。善于言谈,表示有知识,故从言。本义知道;懂得)", "example": null}, {"def": "同本义", "example": null}, {"def": "譺,知也。--《说文》", "example": null}, {"def": "君子是识。--《诗·大雅·瞻卬》。笺知也。”", "example": null}, {"def": "壹宥曰不识。--《周礼·司刺》", "example": null}, {"def": "草荣识节和,木衰知风厉。--陶潜《桃花源诗》", "example": null}, {"def": "知可以战与不可以战者胜,识众寡之用者胜。--《孙子·谋攻》", "example": null}, {"def": "不识有诸?--《孟子·梁惠王上》", "example": null}, {"def": "苟有险,余必下推车,子岂识之?--《左传·成公二年》", "example": null}, {"def": "使汝不识诗书,或未必艰贞若是。--清·袁枚《祭妹文》", "example": null}, {"def": "又如识味(知味);识空便(知趣;识相);识道(知圣道);识义(知义", "example": null}, {"def": "识（譺）shí", "example": null}, {"def": "⒈知道，认得，能辨别～字。认～。～别。～途老马。", "example": null}, {"def": "⒉学问，应知的，所知道的学～。知～。常～。有～之士。", "example": null}, {"def": "⒊见解，辨别是非的能力见～。远见卓～。", "example": null}, {"def": "⒋", "example": null}, {"def": "识（譺）zhì", "example": null}, {"def": "⒈记住，做记号，也指记号、标志博闻强～。表～。款～。", "example": null}]','chinese-xinhua','0'),
('2101143296683282531','实','1','shí','宀','8',NULL,'[{"def": "实", "example": null}, {"def": "(会意。从宀,从贯。宀,房屋。贯,货物,以货物充于屋下。本义财物粮食充足,富有)", "example": null}, {"def": "同本义", "example": null}, {"def": "實,富也。--《说文》", "example": null}, {"def": "实,满也,塞也。--《小尔雅》", "example": null}, {"def": "实,荣也。--《墨子经上》", "example": null}, {"def": "有者为实,故凡中质充满皆曰实。--《素问·调经论》", "example": null}, {"def": "而君之仓廪实,府库充。--《孟子·梁惠王下》", "example": null}, {"def": "管子曰仓廪实而知礼节。”--汉·贾谊《论积贮疏》", "example": null}, {"def": "公家虚而大臣实。--《韩非子·亡征》", "example": null}, {"def": "又如殷实;实核(种子);实谷(子粒饱满的谷类作物)", "example": null}, {"def": "真实;诚实", "example": null}, {"def": "实,诚也。--《广雅》", "example": null}, {"def": "夫图画,", "example": null}, {"def": "实（實、寔）shí", "example": null}, {"def": "⒈满，充满～心铅球。～足岁数。仓库充～。", "example": null}, {"def": "⒉种子，果子果～。", "example": null}, {"def": "⒊真，诚恳，不狡猾真～。诚～。老～。说～话。", "example": null}, {"def": "⒋客观存在的～事。～际。～力。～况。事～。", "example": null}, {"def": "⒌的确确～。", "example": null}, {"def": "⒍用于加强语气～难从命。", "example": null}, {"def": "⒎施，执行，推行～施。～行。\\"", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "①真，的确～在对。", "example": null}, {"def": "②不虚假，不马虎他干活很～在。", "example": null}, {"def": "③其实，实际他说懂了，～在是哄骗人。", "example": null}, {"def": "⒒", "example": null}, {"def": "①客观的真实情况。也指实践联系～际。", "example": null}, {"def": "②具体的～际效果。", "example": null}, {"def": "⒓", "example": null}, {"def": "①人们改造自然和改造社会的活动。", "example": null}, {"def": "②实行及履行自己的主张或诺言。", "example": null}, {"def": "⒔", "example": null}, {"def": "⒕", "example": null}, {"def": "①为了检验某种科学理论或假设而进行的观察和研究活动。", "example": null}, {"def": "②指实验的工作。", "example": null}, {"def": "⒖", "example": null}, {"def": "实zhì 1.到达。", "example": null}]','chinese-xinhua','0'),
('2101143296683282532','寔','1','shí','','9',NULL,'[{"def": "寔shí", "example": null}, {"def": "⒈放置。", "example": null}, {"def": "⒉这，此～为（这就是）。", "example": null}, {"def": "⒊实，实在～繁有徒（这类人实在有很多）。", "example": null}, {"def": "⒋见实（寔）。", "example": null}]','chinese-xinhua','0');
