('2101143296716836902','贳','1','shì','贝','9',NULL,'[{"def": "贳shì", "example": null}, {"def": "⒈赊～酒。", "example": null}, {"def": "⒉出赁，出借。", "example": null}, {"def": "⒊宽大，赦免～罪。", "example": null}]','chinese-xinhua','0'),
('2101143296716836903','适','1','shì','辶','9',NULL,'[{"def": "适", "example": null}, {"def": "(形声。从辵,啻声。本义往,到)", "example": null}, {"def": "同本义", "example": null}, {"def": "適,之也。--《说文》。段曰往自发动言之,适自所到言之。”", "example": null}, {"def": "十一月,沛公引兵之薛。--《汉书·高帝纪》", "example": null}, {"def": "辍耕之垄上。--《史记·陈涉世家》", "example": null}, {"def": "适,往也。--《尔雅》", "example": null}, {"def": "民不适攸居。--《书·盘庚》", "example": null}, {"def": "爰其适归。--《诗·小雅·四月》", "example": null}, {"def": "适彼乐土。--《诗·魏风·硕鼠》", "example": null}, {"def": "使适四方。--《周礼·小行人》", "example": null}, {"def": "以适父母舅姑之所。--《礼记·内则》", "example": null}, {"def": "逝将去女,适彼乐国。--《诗·魏风·硕鼠》", "example": null}, {"def": "余自齐安舟行适临汝。--宋· 苏轼《石钟山记》", "example": null}, {"def": "又如无所适从;何适;适秦;适远(到", "example": null}, {"def": "适（適）shì", "example": null}, {"def": "⒈相合，妥当，切合～合。～宜。～当。～龄。～度。～中。正好～用。", "example": null}, {"def": "⒉恰好，正巧～得其反。～逢其会。～销对路。", "example": null}, {"def": "⒊才，刚才～从何地来？", "example": null}, {"def": "⒋舒服她身体不～。", "example": null}, {"def": "⒌往，去～长沙。无所～从。", "example": null}, {"def": "⒍旧称女子嫁人～人。", "example": null}, {"def": "适kuò", "example": null}, {"def": "⒈〈古〉疾速。多见于人名。", "example": null}, {"def": "适dí 1.专主，作主。 2.同\\"嫡\\"。正妻称\\"嫡妻\\"，正妻所生之子称\\"嫡子\\"。 3.指正统，正宗。 4.亲厚。 5.通\\"谛\\"。注意，仔细。 6.通\\"的\\"。指的，对象。 7.通\\"", "example": null}, {"def": "的\\"。清楚，分明。", "example": null}, {"def": "适tì 1.见\\"适适\\"。", "example": null}, {"def": "适zhé 1.责备，谴责。 2.责罚，惩罚。 3.贬谪。 4.毛病;过失。 5.旧指天象变异。", "example": null}]','chinese-xinhua','0'),
