('2101143296721031170','寿','1','shòu','寸','7',NULL,'[{"def": "寿", "example": null}, {"def": "(形声。从老省,畴声(依《说文》),从老省,即上面象老”的上半部。本义长寿) 同本义", "example": null}, {"def": "寿,久也。--《说文》", "example": null}, {"def": "寿命也。--《韩非子·显学》", "example": null}, {"def": "观其形骨,必不寿,不可与婚。--《世说新语·贤媛》", "example": null}, {"def": "死而不忘者寿。--《老子》", "example": null}, {"def": "则无遗寿聈。--《书·召诰》", "example": null}, {"def": "如南山之寿。--《诗·小雅·天保》", "example": null}, {"def": "长于上古,而不为寿。--《庄子·天道》。注寿者,期之远耳。”", "example": null}, {"def": "病变而药不变,向之寿民,今为殇子矣。--《吕氏春秋·察今》", "example": null}, {"def": "神龟虽寿,犹有竟时。--曹操《步出夏门行》", "example": null}, {"def": "斯役之价值,直可惊天地,泣鬼神,与武", "example": null}, {"def": "寿（壽）shòu", "example": null}, {"def": "⒈生命的年限，又指岁数大～命。高～。～比南山。", "example": null}, {"def": "⒉生日～辰。祝～。", "example": null}, {"def": "⒊装殓死人的～衣。", "example": null}]','chinese-xinhua','0'),
('2101143296721031171','受','1','shòu','又','8',NULL,'[{"def": "受", "example": null}, {"def": "(会意。甲骨文字形,象两手中间有一只舟,表示传递东西。本义接受;承受)", "example": null}, {"def": "同本义", "example": null}, {"def": "受,相付也。--《说文》”王筠曰手部授,人部付,皆曰予也。”今以付说受,则是受授同字矣。”", "example": null}, {"def": "受其币。--《周礼·天官·司书》", "example": null}, {"def": "主妇拜受爵。--《仪礼·特牲馈食礼》", "example": null}, {"def": "则受之。--《周礼·司干》。注取藏之。”", "example": null}, {"def": "受以小功衰。--《仪礼·丧服》。注犹承也。”", "example": null}, {"def": "颛顼受之。--《国语·楚语》。注承也。”", "example": null}, {"def": "釜十五,吾受,而宫出之以百。--《管子·海南》", "example": null}, {"def": "志士不饮盗泉之水,廉者不受嗟来之食。--《后汉书·列女传》", "example": null}, {"def": "臣", "example": null}, {"def": "受shòu", "example": null}, {"def": "⒈接纳～纳。接～。承～。不～礼物。～教育。", "example": null}, {"def": "⒉遭到遭～。～伤。～寒。～湿。～累。", "example": null}, {"def": "⒊忍耐忍～。～得起。", "example": null}, {"def": "⒋中，适合，得益，舒服～听。～用。享～。", "example": null}]','chinese-xinhua','0'),
('2101143296721031172','狩','1','shòu','犭','9',NULL,'[{"def": "狩", "example": null}, {"def": "(形声。从犬,守声。犬”是狩猎的助手,故从犬。本义冬季打猎)", "example": null}, {"def": "同本义", "example": null}, {"def": "狩,犬田也。--《说文》", "example": null}, {"def": "明夷于南狩。--《易》。按,田必有犬,故从犬。”", "example": null}, {"def": "岁终田猎曰狩。--《易·荀》注", "example": null}, {"def": "冬猎为狩。--《尔雅》", "example": null}, {"def": "狩者何?田狩也。--《公羊传·桓公四年》", "example": null}, {"def": "冬大阅以狩。--《汉书·刑法志》", "example": null}, {"def": "狩于中山。--《列子·黄帝》。注火田为狩”", "example": null}, {"def": "春蒷,夏苗,秋猘,冬狩。--《左传·隐公五年》", "example": null}, {"def": "又如狩田(冬季打猎);狩地(古代天子、诸侯冬猎之地)", "example": null}, {"def": "打猎", "example": null}, {"def": "不狩不猎,胡瞻尔庭有县貆兮?--《诗·魏风·伐檀》", "example": null}, {"def": "又", "example": null}, {"def": "狩shòu〈古〉冬天打猎冬～。泛指打猎～猎。", "example": null}]','chinese-xinhua','0'),
('2101143296721031173','兽','1','shòu','乺','11',NULL,'[{"def": "兽", "example": null}, {"def": "(象形。小篆字形。上象耳,中象头,下象足踩地。兽本是禽兽的总称。古另有玣”字,指捕捉禽兽的活动。二字通用。本义禽兽的总称)", "example": null}, {"def": "四足的哺乳动物,多指野兽", "example": null}, {"def": "兽,守备者。--《说文》", "example": null}, {"def": "四足而毛谓之兽。--《尔雅·释鸟》", "example": null}, {"def": "兽毛虫总号。--《释兽释文》。按,兽中可畜养者则曰兽。", "example": null}, {"def": "兽,狐狼之属。--《周礼·庭氏》注", "example": null}, {"def": "大兽公之。--《周礼·兽人》", "example": null}, {"def": "搏兽于敖。--《诗·小雅·车攻》", "example": null}, {"def": "猛兽步高岗。--曹操《却东西门行》", "example": null}, {"def": "兽同足者而俱行。--《战国策·齐策》", "example": null}, {"def": "山有猛兽。--《淮南子·说山训》", "example": null}, {"def": "山深而兽往之", "example": null}, {"def": "兽（玣）shòu指有四条腿、全身长毛的哺乳动物野～。〈喻〉野蛮，残忍，下流～行。～心。～性大发。", "example": null}]','chinese-xinhua','0'),
('2101143296725225472','售','1','shòu','口','11',NULL,'[{"def": "售", "example": null}, {"def": "(形声。从口,雔省声。本义卖出去)", "example": null}, {"def": "同本义", "example": null}, {"def": "售,卖出手也。--《说文新附》", "example": null}, {"def": "卖之,不可偻售也。--《荀子·儒效》", "example": null}, {"def": "吾售之,人取之,未尝有言,而独不足子所乎?--明·刘基《卖柑者言》", "example": null}, {"def": "又如售卖(卖出;出售)", "example": null}, {"def": "买", "example": null}, {"def": "欲居之以为利,而高其值,亦无售者。--《聊斋志异·促织》", "example": null}, {"def": "问其价,曰止四百。”余怜而售之。--唐·柳宗元《钴鉧潭西小丘记》", "example": null}, {"def": "欲居之以为利,而高其直,亦无售者。--《聊斋志异·促织》", "example": null}, {"def": "又如售世(行世)", "example": null}, {"def": "引申为酬谢", "example": null}, {"def": "一日,以花来献,予售以斗酒。--宋·沈", "example": null}, {"def": "售shòu卖，卖出去～货。～出。零～。～奖券。〈引〉施展，实现以～其奸。挟邪作蛊，于是不～。", "example": null}]','chinese-xinhua','0'),
('2101143296725225473','授','1','shòu','扌','11',NULL,'[{"def": "授", "example": null}, {"def": "(会意。从手,从受,受声。本义给予;交给)", "example": null}, {"def": "同本堰", "example": null}, {"def": "授,予也。--《说文》。按,授”应是后起字。", "example": null}, {"def": "则从而授之。--《周礼·邻长》", "example": null}, {"def": "献俘授馘。--《左传·僖公二十八年》。注数也。”", "example": null}, {"def": "今日必授。--《国语·鲁语》。注与也。”", "example": null}, {"def": "君言当击,甚与孤合,此天以君授孤也。--《资治通鉴》", "example": null}, {"def": "议法度而修之于朝廷,以授之于有司,不为侵官。--宋·王安石《答司马谏议书》", "example": null}, {"def": "又如授受(交接;交付和接受);授兵(把武器给战士);授官厅(官府;衙门);授玉(给予玉圭);授室(把家事交给新妇);授赏(奖赏);授简(给予简札);授", "example": null}, {"def": "授shòu", "example": null}, {"def": "⒈给，予，任命～给。～予。以功～官。～权。～奖。", "example": null}, {"def": "⒉教，教导～课。讲～。传～。", "example": null}, {"def": "⒊", "example": null}, {"def": "①下命令～命改组。", "example": null}, {"def": "②献出自己的生命临危～命。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296725225474','绶','1','shòu','纟','11',NULL,'[{"def": "绶", "example": null}, {"def": "(形声。从糸,受声。本义丝带。古代用以系佩玉、官印等。绶带的颜色常用以标志不同的身分与等级) 同本义", "example": null}, {"def": "绶,绂维也。--《说文》", "example": null}, {"def": "绂谓之绶。--《小尔雅》。按,绶者,组带之大名。", "example": null}, {"def": "掌帷幕幄帟绶之事。--《周礼·幕人》。司农注组绶所以系帷也。”", "example": null}, {"def": "天子佩白玉而玄组绶。--《礼记·玉藻》", "example": null}, {"def": "古者君佩玉,尊卑有序。及秦,以采组连结于纙,谓之绶。--《董巴舆服志》", "example": null}, {"def": "守邸与共食,食且饱,少见其绶。--《汉书·朱买臣传》", "example": null}, {"def": "怀黄金之印,结紫绶于要。--《史记·范睢蔡泽列传》", "example": null}, {"def": "绶shòu丝带。〈古〉用来拴玉、印或帷幕印～。", "example": null}]','chinese-xinhua','0'),
('2101143296725225475','痩','1','shòu','','6',NULL,'[{"def": "痩 shòu 通假字，古同\\"瘦\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296725225476','瘦','1','shòu','疒','14',NULL,'[{"def": "瘦", "example": null}, {"def": "(形声。从疒,叟声。从疒,表明与疾病有关。本义肌肉不丰满)", "example": null}, {"def": "同本义", "example": null}, {"def": "瘦,舑也。--《说文》。", "example": null}, {"def": "毁瘠羸瘦。--《孝经》", "example": null}, {"def": "久则瘦舑腐败。--《周礼·廛人》注", "example": null}, {"def": "有书生避雨檐下,衣湿袖单,影乃益瘦。--清·周容《芋老人传》", "example": null}, {"def": "又如瘦怯(瘦弱;瘦削);瘦怯怯(瘦弱的样子);瘦亭亭(亦作瘦棱楼”。十分瘦削的样子);瘦岩岩(纤细瘦削的样子);瘦恹恹(瘦厌厌。形容瘦弱消瘦);瘦伶伶(形容瘦的样子);", "example": null}, {"def": "瘦伶仃(十分瘦弱的样子);瘦客(消瘦衰弱之人);瘦悴(消瘦憔悴);瘦容(消瘦的容的样子)", "example": null}, {"def": "细小;不茁壮", "example": null}, {"def": "瘦shòu", "example": null}, {"def": "⒈体内脂肪少，肌肉不丰，跟\\"肥\\"相对他太～。她体～。老来～。面黄肌～（形容人营养不良或不健康）。", "example": null}, {"def": "⒉窄小的，瘠薄的，纤细的这鞋～了点。那块土地～。笔杆～。字体～。", "example": null}]','chinese-xinhua','0'),
('2101143296725225477','夀','1','shòu','','6',NULL,'[{"def": "夀shòu1.古同\\"寿\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296725225478','獣','1','shòu','','6',NULL,'[{"def": "獣shòu 1.\\"兽\\"的日本用简体汉字。", "example": null}]','chinese-xinhua','0'),
('2101143296725225479','守','1','shǒu','宀','6',NULL,'[{"def": "守", "example": null}, {"def": "(会意。从宀,从寸。宀表示房屋;寸是法度∠起来表示掌管法度。本义官吏的职责,职守)", "example": null}, {"def": "同本义", "example": null}, {"def": "守,官守也。从门,寺府之事也。--《说文》。寺,廷也;府,文书藏也。", "example": null}, {"def": "五载一巡守。--《书·舜典》", "example": null}, {"def": "王巡虢守。--《左传·二十一年》", "example": null}, {"def": "均地守。--《周礼均人》。注地守,衡虞之属。”", "example": null}, {"def": "纠其守。--《周礼·内宰》。注宿卫者。”", "example": null}, {"def": "虽守者益。--《荀子·王制》。注谓地也。”", "example": null}, {"def": "官司之守,非君所及也。--《左传·隐公五年》", "example": null}, {"def": "我无官守,我无言责也。--《孟子·公孙丑下》", "example": null}, {"def": "节操;操守", "example": null}, {"def": "守shǒu", "example": null}, {"def": "⒈保卫，卫护～卫。防～。坚～阵地。", "example": null}, {"def": "⒉看护，等候～夜。看～。～候。～株待兔。", "example": null}, {"def": "⒊遵照，服从遵～。～信用。遵纪～法。", "example": null}, {"def": "⒋靠近，依傍～着水池，可多养鱼。", "example": null}, {"def": "⒌旧时郡一级的长官名太～。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①防守戒备。", "example": null}, {"def": "②明代、清代的武官名。", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "守shòu 1.戍守疆域土地。 2.指天子出行。 3.守臣，地方长官◇用为郡守﹑太守﹑刺史等的简称。 4.犹摄。暂时署理职务。多指官阶低而署理较高的官职。 5.指任", "example": null}, {"def": "事﹑任职。 6.专指任郡守﹑太守﹑刺史等职。 7.职守。 8.州郡地方政府所在地。", "example": null}]','chinese-xinhua','0'),
('2101143296725225480','首','1','shǒu','首','9',NULL,'[{"def": "首", "example": null}, {"def": "(象形。金文字形,上面是头发和头皮,用以表示头盖;下面是眼睛,用以代表面部。本义头)", "example": null}, {"def": "同本义", "example": null}, {"def": "首,阳也。--《汉书·天文志》", "example": null}, {"def": "首身离兮心不惩。--《楚辞·九歌·国殇》", "example": null}, {"def": "愿言思伯,甘心首疾。--《诗·卫风·伯兮》", "example": null}, {"def": "搔首踟蹰。--《诗·邶风·静女》", "example": null}, {"def": "愿得将军之首以献秦。--《战国策·燕策》", "example": null}, {"def": "以刀劈狼首。--《聊斋志异·狼三则》", "example": null}, {"def": "又如昂首;叩首;搔首;首功(以获敌首论功);首虏(指斩获敌人的首级);首枕其股(让死者的头枕在自己的腿上。这是古代臣下对横遭杀害的君主表示哀痛之礼);首丘(归葬故乡;", "example": null}, {"def": "亦指怀念故乡);首身", "example": null}, {"def": "首shǒu", "example": null}, {"def": "⒈头～饰。昂～阔步。俯～帖耳。", "example": null}, {"def": "⒉头头，最大的～领。罪魁祸～。", "example": null}, {"def": "⒊领导人～长。", "example": null}, {"def": "⒋最先，最早，第一～先。～创。～次。～席。～当其冲。～屈一指。", "example": null}, {"def": "⒌方面北～。下～。", "example": null}, {"def": "⒍有罪自陈或出面告发自～。出～。", "example": null}, {"def": "⒎量词。指诗词歌赋等民歌三～。唐诗三百～。", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "①最重要的，第一位的。", "example": null}, {"def": "②首脑～要人物。", "example": null}, {"def": "⒔", "example": null}, {"def": "①为首的人或机关。", "example": null}, {"def": "②国家的主要领导人。", "example": null}]','chinese-xinhua','0'),
('2101143296725225481','艏','1','shǒu','舟','15',NULL,'[{"def": "艏", "example": null}, {"def": "船的前端或前部", "example": null}, {"def": "艏楼", "example": null}, {"def": "艏shǒu 1.船的前端或前部。 2.见\\"艗艏\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296725225482','手','1','shǒu','手','4',NULL,'[{"def": "手", "example": null}, {"def": "(象形。小篆字形,象伸出五指形。本义人体上肢的总称,一般指腕以下的部分)", "example": null}, {"def": "同本义", "example": null}, {"def": "手,拳也。--《说文》。段注今人舒之为手,卷之为拳。其实一也。故以手与拳二篆互训。”", "example": null}, {"def": "艮为手。--《易·说卦》", "example": null}, {"def": "三阴在手。--《素问·阴阳别论》。注手谓气口。”", "example": null}, {"def": "则不手拜。--《礼记·少仪》。注手拜,手至地也。”", "example": null}, {"def": "头至手曰拜手。--《公羊传·宣公六年》注", "example": null}, {"def": "携手同行。--《诗·邶风·北风》", "example": null}, {"def": "携手同归。", "example": null}, {"def": "执子之手,与子偕老。--《诗·邶风·击鼓》", "example": null}, {"def": "又如手纽(手铐);手杻(手铐之类的刑具);手脚了得(手脚厉害,指有", "example": null}, {"def": "手shǒu", "example": null}, {"def": "⒈人体的上肢（多指腕以下部分）～背。～掌。拍～。", "example": null}, {"def": "⒉拿着钥匙在～里。", "example": null}, {"def": "⒊亲身～书。亲～。", "example": null}, {"def": "⒋做某种事的人，擅长某种技能的人水～。助～。选～。神枪～。种稻能～。", "example": null}, {"def": "⒌本领，技能显两～儿给大家看看。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "①文学、艺术作品等表现的技巧。", "example": null}, {"def": "②待人处世的不正当方法，也称\\"手腕\\"。", "example": null}, {"def": "⒒", "example": null}, {"def": "①本领，能耐。", "example": null}, {"def": "②为达到某种目的而采取的方法和措施。", "example": null}, {"def": "③同\\"手法", "example": null}, {"def": "②\\"。", "example": null}, {"def": "⒓", "example": null}, {"def": "①手做的姿势〈表〉某种含义。", "example": null}, {"def": "②某种操作姿势。", "example": null}, {"def": "⒔", "example": null}]','chinese-xinhua','0'),
('2101143296725225483','收','1','shōu','攵','6',NULL,'[{"def": "收", "example": null}, {"def": "(形声。从攴,收声)", "example": null}, {"def": "同本义", "example": null}, {"def": "收,捕也。--《说文》", "example": null}, {"def": "女反收之。--《诗·大雅·瞻卬》。传拘收也。”", "example": null}, {"def": "单于壮其节,朝夕遣人候问武,而收系张胜。--《汉书·李广苏建传》", "example": null}, {"def": "一时收禽,上下肃然,称为政理。--《后汉书·张衡传》", "example": null}, {"def": "又如收领(捉拿);收系(逮捕下狱);收付(拘捕罪犯,交付办案);收考(拘捕考问);收夷(捕杀);收劾(拘捕弹劾);收案(拘捕案问);收掩(收捕);收执(捉拿);收禁(拘押监禁);收领", "example": null}, {"def": "(拘禁)", "example": null}, {"def": "收拾;收取", "example": null}, {"def": "收,取也。--《广雅》", "example": null}, {"def": "收以奔褒。--《国语·郑语》。注取也。”", "example": null}, {"def": "勤", "example": null}, {"def": "收（収）shōu", "example": null}, {"def": "⒈接到，接受，接纳～到。～留。～入。～款。～容。接～。招～。征～。不～礼。", "example": null}, {"def": "⒉聚集，合拢～集。～拢。～罗。～网。创伤～口了。", "example": null}, {"def": "⒊割取成熟的农作物～割。麦～。秋～冬藏。〈喻〉成果～获。～成。", "example": null}, {"def": "⒋藏，放置妥当～藏。把东西～好。", "example": null}, {"def": "⒌招回，取回～回。～取。～兵。～复。", "example": null}, {"def": "⒍结束，停止～工。～尾。～场。", "example": null}, {"def": "⒎约束，减弱或消失～心。～敛笑容。", "example": null}, {"def": "⒏逮捕，拘押～捕。～监。", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "①整理，整顿。", "example": null}, {"def": "②整治，惩罚。", "example": null}, {"def": "③消灭，杀死。", "example": null}, {"def": "⒒", "example": null}, {"def": "①物体由大变小或由长变短。", "example": null}, {"def": "②紧缩。", "example": null}, {"def": "⒓", "example": null}, {"def": "①吸收任用（人员）。", "example": null}, {"def": "②边收听边记录或录音。", "example": null}, {"def": "③汇编集子所采用的诗文等。", "example": null}]','chinese-xinhua','0'),
('2101143296725225484','尗','1','shú','','15',NULL,'[{"def": "尗shū 1.\\"菽\\"的古字。豆。 2.同\\"叔\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296725225485','秫','1','shú','禾','10',NULL,'[{"def": "秫", "example": null}, {"def": "(象形。从古文术,加禾。本义谷物之有粘性者。也指不粘者)", "example": null}, {"def": "同本义", "example": null}, {"def": "秫,稷之黏者也。--《说文》", "example": null}, {"def": "稻黍秫稷粟麻秔。--《急就篇》", "example": null}, {"def": "染羽以朱湛丹秫。盖有赤白二种。今北地谓高粱之粘者为秫,秫亦胡秫。--《考工记·钟氏》", "example": null}, {"def": "春秫作美酒,酒熟吾自斟。--陶渊明《和郭主簿》", "example": null}, {"def": "又如秫田(种植黏粟之田);秫酒(用秫酿成的酒);秫蘖(制酒用的糯黍与曲);秫稻(即糯稻);秫谷(黍米);秫黍(高粱)", "example": null}, {"def": "通鉥”。长针", "example": null}, {"def": "黑齿雕题,鳀冠秫缝。--《战国策·赵策》", "example": null}, {"def": "秫秸", "example": null}, {"def": "秫shú粘高粱（可以酿酒）～米。有的地方泛称高粱～ ～米。～秸（高粱秆）。", "example": null}, {"def": "秫shù 1.长针。参见\\"秫缝\\"。", "example": null}]','chinese-xinhua','0'),
