('2101143296729419780','输','1','shū','车','13',NULL,'[{"def": "输", "example": null}, {"def": "(形声。从车,俞声。本义转运,运送)", "example": null}, {"def": "同本义", "example": null}, {"def": "输,委输也。--《说文》", "example": null}, {"def": "运所有,输所无。--《淮南子·泛南训》", "example": null}, {"def": "输积聚以贷。--《左传·襄公九年》", "example": null}, {"def": "春申道缀基毕输。--《荀子·成相》", "example": null}, {"def": "秦于是乎输粟于晋。--《左传·僖公十三年》", "example": null}, {"def": "输之于宫以为食器。--《韩非子·十过》", "example": null}, {"def": "一旦不能有,输来其间。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如输供(输送供给);输将(运送);输场(唐代转运物资的货场);输发(输送和调发粮草、军队);输转(转运);输将(运送,输运);输遣(运送)", "example": null}, {"def": "交出;缴纳", "example": null}, {"def": "已乃劝输巨室,令", "example": null}, {"def": "输shū", "example": null}, {"def": "⒈运送，注入运～。～入。～血。", "example": null}, {"def": "⒉送给，捐献～财。捐～。", "example": null}, {"def": "⒊负，败～了两盘棋。", "example": null}, {"def": "输shù 1.经穴。", "example": null}]','chinese-xinhua','0'),
('2101143296729419781','誼','1','shuà','','9',NULL,'[{"def": "誼shuà 1.俊言。 2.作人名用字。宋有赵师誼。见《宋史．宗室世系表四》。", "example": null}]','chinese-xinhua','0'),
('2101143296729419782','耍','1','shuǎ','而','9',NULL,'[{"def": "耍", "example": null}, {"def": "(会意。从而,从女。而,颊毛。盖谓用颊毛戏弄女子。本义戏耍。一般指不正当的行为)", "example": null}, {"def": "玩耍,游玩;消闲取乐", "example": null}, {"def": "长颦知有恨,贪耍不成妆。--宋·周邦彦《意难忘》", "example": null}, {"def": "一群猴子耍了一会,都去那山涧洗澡。--《西游记》", "example": null}, {"def": "又如耍水(玩水,游泳);耍货(玩具);耍拳(打拳);耍歇(玩耍休息)", "example": null}, {"def": "戏谑;捉弄", "example": null}, {"def": "等他来时,诱他去粪窖边,只做参贺他,双手抢住脚,翻筋斗,攧那厮下粪窖去,只是小耍他。--《水浒传》", "example": null}, {"def": "又如耍处(开玩笑;闹着玩儿);耍窨(假装糊涂;捉迷藏)", "example": null}, {"def": "舞弄;使用武器、器物等", "example": null}, {"def": "耍shuǎ", "example": null}, {"def": "⒈玩，游戏玩～、子们在操场上～。", "example": null}, {"def": "⒉玩弄，戏弄～猴。～弄人。", "example": null}, {"def": "⒊弄，施展，多指不良行为～手法。～无赖。～花招。～手腕。", "example": null}, {"def": "⒋挥舞～刀～枪。", "example": null}, {"def": "耍shá 1.方言。什么。", "example": null}]','chinese-xinhua','0'),
('2101143296729419783','刷','1','shuā','刂','8',NULL,'[{"def": "刷", "example": null}, {"def": "(形声。本义清扫;揩拭;冲洗)", "example": null}, {"def": "同本义", "example": null}, {"def": "刷,刮也。礼有刷巾。--《说文》", "example": null}, {"def": "刷羽汎清源。--《文选·沈约和谢宣城诗》", "example": null}, {"def": "旦刷幽燕,昼秼荆越。--颜延之《赫白马赋》", "example": null}, {"def": "秋刷。--《周礼·凌人》", "example": null}, {"def": "洗兵海岛,刷马江州。--晋·左思《魏都赋》", "example": null}, {"def": "又如刷刮(擦拭);刷涤(洗刷;洗除);刷刨(刮擦;刷拭);刷剃(擦眼泪)", "example": null}, {"def": "清除;洗雪", "example": null}, {"def": "王虽东取地于越,不足以刷耻。--《史记·楚世家》", "example": null}, {"def": "欲刷耻改行。--《汉书·武帝纪》", "example": null}, {"def": "刷会稽之耻。--班固《汉书》", "example": null}, {"def": "又如刷淤(清除淤泥);刷剔(删汰)", "example": null}, {"def": "刷抹;涂", "example": null}, {"def": "刷shuā", "example": null}, {"def": "⒈清除或涂抹东西的用具，用成束的毛、棕或尼龙等制成牙～。棕毛～。鞋～子。", "example": null}, {"def": "⒉用刷子等清洗或涂抹～牙。～洗。～碗。～墙壁。", "example": null}, {"def": "⒊淘汰他在第二轮比赛中被～掉了。", "example": null}, {"def": "⒋像声词。同\\"唰\\" ～ ～ ～下雨了。", "example": null}, {"def": "⒌", "example": null}, {"def": "刷shuà", "example": null}]','chinese-xinhua','0'),
('2101143296729419784','唰','1','shuā','口','11',NULL,'[{"def": "唰", "example": null}, {"def": "鸟理毛", "example": null}, {"def": "唰,鸟治毛也。--《集韵》", "example": null}, {"def": "唰", "example": null}, {"def": "形容迅速的样子", "example": null}, {"def": "唰", "example": null}, {"def": "形容迅速擦过去的声音", "example": null}, {"def": "唰shuā像声词～ ～ ～下起雨来了。", "example": null}]','chinese-xinhua','0'),
('2101143296729419785','帅','1','shuài','巾','5',NULL,'[{"def": "帅", "example": null}, {"def": "(形声)", "example": null}, {"def": "同本义", "example": null}, {"def": "无感我帨兮。--《诗·野有死麕》", "example": null}, {"def": "毋施衿结帨。--《仪礼·士昏礼》", "example": null}, {"def": "左佩纷帨。又,女子设帨于门右。--《礼记·内则》", "example": null}, {"def": "军队中的主将、统帅", "example": null}, {"def": "帅刘良佐拥骑至城下,呼曰吾与阎雅故,为我语阎君,欲相见。”--清·邵长蘅《阎典史传》", "example": null}, {"def": "予自度不得脱,则直前诟虏帅失信,数吕师孟叔侄为逆。--宋·文天祥《指南录·后序》", "example": null}, {"def": "又如挂帅;帅甸(甸地的统帅", "example": null}, {"def": "帅（帥）shuài", "example": null}, {"def": "⒈军队中最高级的指挥者元～。统～。", "example": null}, {"def": "⒉（也可写作\\"率\\"）主将将～之书。〈古〉又称地方的长官县～。", "example": null}, {"def": "⒊（也可写作\\"率\\"）带领，率领～领。～众出征。", "example": null}]','chinese-xinhua','0'),
('2101143296729419786','蟀','1','shuài','虫','17',NULL,'[{"def": "蟀", "example": null}, {"def": "蟋蟀", "example": null}, {"def": "秋蟀载吟,竞鸣机杼。--《徐州刺史侯安都德政碑》", "example": null}, {"def": "蟀shuài 1.\\"蟋蟀\\"的省称。", "example": null}]','chinese-xinhua','0'),
('2101143296729419787','甩','1','shuǎi','用','5',NULL,'[{"def": "甩", "example": null}, {"def": "扔;抛开", "example": null}, {"def": "将手里的绢子一甩,向宝玉脸上甩来。--《红楼梦》", "example": null}, {"def": "等我紧走慢赶地快要走近他时,他又噔噔地自个儿向前走了,一下又把我甩下几丈远。--《百合花》", "example": null}, {"def": "脱,脱掉", "example": null}, {"def": "摆动", "example": null}, {"def": "遗弃或放弃", "example": null}, {"def": "虫类产卵", "example": null}, {"def": "甩shuǎi", "example": null}, {"def": "⒈抡，摆动～手。～脚。", "example": null}, {"def": "⒉扔～石头。", "example": null}, {"def": "⒊丢开，抛弃～掉它。～到垃圾箱里。蟀shuài", "example": null}]','chinese-xinhua','0'),
('2101143296729419788','衰','1','shuāi','衣','10',NULL,'[{"def": "衰  cui", "example": null}, {"def": "古代用粗麻布制成的毛边丧服", "example": null}, {"def": "共丧衰亦如之。--《周礼·天官·内司服》", "example": null}, {"def": "无衰麻之服。--《荀子·礼论》", "example": null}, {"def": "子墨衰緻,梁弘御戎,莱驹为右。--《左传·僖公三十三年》", "example": null}, {"def": "又如衰衣(衰服。古代的丧服);衰杖(居丧用的麻緻与哭丧棒);衰冠(丧服,衰衣丧冠)", "example": null}, {"def": "下,从上到下的次序", "example": null}, {"def": "衰", "example": null}, {"def": "由大到小依照一定的标准递减", "example": null}, {"def": "衰 cuī用于\'等衰\'（等次）。又见shuāi。", "example": null}, {"def": "衰shuāi", "example": null}, {"def": "⒈微弱，事物发展转向微弱～弱。～退。～落。～败。年老力～。", "example": null}, {"def": "衰suō 1.蓑衣。", "example": null}]','chinese-xinhua','0'),
('2101143296729419789','摔','1','shuāi','扌','14',NULL,'[{"def": "摔", "example": null}, {"def": "(形声。从手,率声。本义用力扔在地上)", "example": null}, {"def": "同本义", "example": null}, {"def": "盛酒瓮摔做碎瓷瓯。--元·康进之《李逵负荆》", "example": null}, {"def": "小王把书包往地上一摔,气呼呼地走了", "example": null}, {"def": "又如摔丧驾灵(即摔盆引灵。摔丧出殡起动棺材时,孝子在棺前摔碎烧纸的瓦盆,也称摔盆”。驾灵孝子抬扶灵柩或在灵柩前领路);摔打(抓住东西往地上猛扔)", "example": null}, {"def": "甩开,摆脱", "example": null}, {"def": "摆动", "example": null}, {"def": "摆出", "example": null}, {"def": "摔", "example": null}, {"def": "摔shuāi", "example": null}, {"def": "⒈用力扔～掉。～出去。", "example": null}, {"def": "⒉掉下花瓶～坏了。房上的人注意，别～下来。", "example": null}, {"def": "⒊跌倒～倒。他～了一跤。", "example": null}, {"def": "摔shuǎi 1.见\\"摔手\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296729419790','缞','1','shuāi','','15',NULL,'[{"def": "缞cuī 1.旧时丧服。用麻布条披于胸前。服三年之丧(臣为君﹑子为父﹑妻为夫)者用之。", "example": null}]','chinese-xinhua','0'),
('2101143296729419791','涮','1','shuàn','氵','11',NULL,'[{"def": "涮", "example": null}, {"def": "(形声。从水,刷声。本义荡洗。用水摇动或放在水里摆动洗清)", "example": null}, {"def": "同本义", "example": null}, {"def": "涮,涮洗也。--《广韵》", "example": null}, {"def": "又如涮罐子;把衣服涮一涮;把瓶子涮干净", "example": null}, {"def": "把生的肉片、鱼片之类放在开水锅里略煮一下就吃", "example": null}, {"def": "欺骗或哄骗", "example": null}, {"def": "涮shuàn", "example": null}, {"def": "⒈稍微洗洗，摇动或摆动着刷洗、冲洗～ ～手。～瓶子。～一～衣服。", "example": null}, {"def": "⒉将生肉片、生鱼片等放入沸水里，烫一下即取出来，蘸着调料吃～羊肉。～火锅子。", "example": null}]','chinese-xinhua','0'),
('2101143296729419792','闩','1','shuān','门','4',NULL,'[{"def": "闩", "example": null}, {"def": "(指事。从门,一”象门闩形。本义门上的横插) 同本义", "example": null}, {"def": "闩,门横关也。--范成大《桂海虞衡志·杂志》", "example": null}, {"def": "又如上闩;门闩", "example": null}, {"def": "闩", "example": null}, {"def": "插上门闩", "example": null}, {"def": "闩紧", "example": null}, {"def": "闩紧大门", "example": null}, {"def": "闩shuān", "example": null}, {"def": "⒈关门时插在门后拴住门所用的棍棒门～。", "example": null}, {"def": "⒉插上门闩将门～好。", "example": null}]','chinese-xinhua','0'),
('2101143296729419793','拴','1','shuān','扌','9',NULL,'[{"def": "拴", "example": null}, {"def": "(形声。从手,全声。本义绑住)", "example": null}, {"def": "同本义", "example": null}, {"def": "拴了倪二,拉着就走。--《红楼梦》", "example": null}, {"def": "又如把你的马拴在树上;应当把恶狗拴好;拴束(捆绑;收拾)", "example": null}, {"def": "插上门闩", "example": null}, {"def": "武松把门关上,拴了。--《水浒传》", "example": null}, {"def": "出租", "example": null}, {"def": "拴", "example": null}, {"def": "门闩", "example": null}, {"def": "门子只得捻脚捻手,把拴拽了。--《水浒全传》", "example": null}, {"def": "拴shuān系上，缚住～船。～狗。～牛。", "example": null}, {"def": "拴quán 1.铨叙。", "example": null}]','chinese-xinhua','0'),
('2101143296729419794','栓','1','shuān','木','10',NULL,'[{"def": "栓", "example": null}, {"def": "(形声。从木,全声。本义木钉;插子)", "example": null}, {"def": "同本义", "example": null}, {"def": "塞子,也泛指形状像塞子的东西", "example": null}, {"def": "栓shuān", "example": null}, {"def": "⒈器物上用作开关的机件枪～。消火～。", "example": null}, {"def": "⒉塞子，起塞子作用的软木～。～剂。血～。", "example": null}]','chinese-xinhua','0'),
