('2101143296729419807','双','1','shuānɡ','又','4',NULL,'[{"def": "双", "example": null}, {"def": "(会意。从雔,从又,持之。雔,两只鸟。又,手。本义一对)", "example": null}, {"def": "禽鸟二只", "example": null}, {"def": "雙,隹二枚也。--《说文》", "example": null}, {"def": "飞鸟曰双。--《方言六》", "example": null}, {"def": "其诸为其双双而俱至者与。--《公羊传·宣公五年》。正义双双之鸟,一身二首尾,有雌雄,随便而偶,常不离散。”", "example": null}, {"def": "中有双飞鸟,自名为鸳鸯。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "云南等地少数民族计算田亩的单位", "example": null}, {"def": "官为田,四十双为二百亩。--《唐书》", "example": null}, {"def": "姓", "example": null}, {"def": "双", "example": null}, {"def": "成双的,一对", "example": null}, {"def": "云有第三郎,窈窕世无双。--", "example": null}, {"def": "双（雙）shuāng", "example": null}, {"def": "⒈一对，两个～脚。～方。～瞳剪水（形容眼睛清亮）。", "example": null}, {"def": "⒉偶，与\\"单\\"相对～号。～日。", "example": null}, {"def": "⒊加倍的～料。", "example": null}, {"def": "⒋匹敌举世无～。", "example": null}, {"def": "⒌量词。指成对的一～绣花鞋。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "双shuāng", "example": null}]','chinese-xinhua','0'),
('2101143296729419808','霜','1','shuānɡ','雨','17',NULL,'[{"def": "霜", "example": null}, {"def": "(形声。从雨,相声。本义在气温降到摄氏零度以下时,近地面空气中水汽的白色结晶)", "example": null}, {"def": "同本义", "example": null}, {"def": "霜,露所凝也。士气津液从地而生,薄以寒气则结为霜。--《说文》", "example": null}, {"def": "霜者,天之所以杀也。--《汉书·董仲舒传》", "example": null}, {"def": "履霜坚冰至。--《易·坤》", "example": null}, {"def": "白露为霜。--《诗·秦风·蒹葭》", "example": null}, {"def": "羌管悠悠霜满地,人不寐,将军白发征夫泪。--宋· 范仲淹《渔家傲》", "example": null}, {"def": "每寒夜起立,振衣裳,甲上冰霜迸落,铿然有声。--清·方苞《左忠毅公逸事》", "example": null}, {"def": "又如霜雪(比喻高洁清白);霜瓦(覆盖着白霜的瓦片);霜旦(下霜的早晨);霜甲(沾着霜的战甲);霜衣(寒衣);霜妃(指", "example": null}, {"def": "霜shuāng", "example": null}, {"def": "⒈地面上或近地面的水汽冷至摄氏零度以下凝结而成微细冰粒，附着于物体上有～。地上～。草上～。瓦上～。", "example": null}, {"def": "⒉白色鬓将～（〈喻〉年将老）。", "example": null}, {"def": "⒊像霜的柿～。", "example": null}, {"def": "⒋年白骨横千～。", "example": null}]','chinese-xinhua','0'),
('2101143296729419809','谁','1','shuí','讠','10',NULL,'[{"def": "谁", "example": null}, {"def": "(形声。从言,隹声。金文字形,象鸟在叫。①基本义什么人。《左传·隐公元年》其谁曰不然?”②什么。《说文》何也。”)", "example": null}, {"def": "哪个人或哪些人", "example": null}, {"def": "莫愁前路无知己,天下谁人不识君--唐·高适《别董大》", "example": null}, {"def": "又如那是谁;站在门口的人是谁;这个单位谁当政;你把书给了谁?谁承望(谁想到);谁家子(谁,何人);谁子(谁氏,何人);谁当(谁人,何人)", "example": null}, {"def": "某人", "example": null}, {"def": "每个人", "example": null}, {"def": "表示疑问。指事物,相当于什么”", "example": null}, {"def": "谁shéi(又读shuí)代词。", "example": null}, {"def": "⒈疑问代词。什么人～在说话？", "example": null}, {"def": "⒉任何人这件事～都能做。", "example": null}]','chinese-xinhua','0'),
