('2101143296733614087','瞚','1','shùn','','7',NULL,'[{"def": "瞚shùn 1.眼珠转动;眨眼。", "example": null}]','chinese-xinhua','0'),
('2101143296733614088','瞤','1','shùn','','12',NULL,'[{"def": "瞤shùn眼跳。", "example": null}]','chinese-xinhua','0'),
('2101143296733614089','瞬','1','shùn','目','17',NULL,'[{"def": "瞬", "example": null}, {"def": "(形声。从目,舜声。本义眨眼)", "example": null}, {"def": "同本义", "example": null}, {"def": "尔先学不瞬,而后可言射矣。--《列子·汤问》", "example": null}, {"def": "又如一瞬(一眨眼工夫)", "example": null}, {"def": "眼珠转动", "example": null}, {"def": "直视,不能瞬。--张机《金匮要略》", "example": null}, {"def": "视,看", "example": null}, {"def": "惊恐。同眴”", "example": null}, {"def": "适见豚子食于其死母者,少焉眴若,皆亲之而走。--《庄子》。陆德明释文眴若,本亦作‘瞬’。司马云惊貌。”", "example": null}, {"def": "瞬", "example": null}]','chinese-xinhua','0'),
('2101143296733614090','鬮','1','shùn','','7',NULL,'[{"def": "鬮shùn 1.乱发。 2.泛指头发。", "example": null}]','chinese-xinhua','0'),
('2101143296733614091','吮','1','shǔn','口','7',NULL,'[{"def": "吮", "example": null}, {"def": "(形声。从口,允声。本义用口含吸,缓饮)", "example": null}, {"def": "同本义", "example": null}, {"def": "医善吮人之伤,含人之血。--《韩非子·备内》", "example": null}, {"def": "磨牙吮血,杀人如麻。--李白《蜀道难》", "example": null}, {"def": "母曰非然也。往年吴公吮其父,其父战不旋踵,遂死于敌。吴公今又吮其子,妾不知其死矣。”--《史记·孙子吴起列传》", "example": null}, {"def": "卒有病疽者,起为吮之。", "example": null}, {"def": "又如吮痈(用嘴吸痈疽的脓血以祛毒);吮疮(以口嘬吸疮疽之毒);吮卒(为士兵嘬吸疮口的脓血);吮嘬(用嘴吸)", "example": null}, {"def": "舐", "example": null}, {"def": "吮shǔn嘬，聚拢嘴唇吸～奶。～吸。", "example": null}, {"def": "吮xuàn 1.箭括。", "example": null}]','chinese-xinhua','0'),
('2101143296733614092','槊','1','shuò','木','14',NULL,'[{"def": "槊", "example": null}, {"def": "(形声。从木,朔声。本义古代兵器,即长杆矛) 同矟”。长杆矛", "example": null}, {"def": "此非孟德之困于周郎者乎?…酾酒临江,横槊赋诗,固一世之英雄,而今安在哉?--宋·苏轼《前赤壁赋》", "example": null}, {"def": "槊shuò〈古〉一种兵器，即长矛利～。", "example": null}]','chinese-xinhua','0'),
('2101143296733614093','搠','1','shuò','扌','13',NULL,'[{"def": "搠", "example": null}, {"def": "戳,刺", "example": null}, {"def": "林冲举手,胕察的一枪,先搠倒差拨。--《水浒传》", "example": null}, {"def": "又如搠杀(刺死);搠番(刺倒;扎倒)", "example": null}, {"def": "插", "example": null}, {"def": "只见女墙边虚搠旌旗,无人守护。--《三国演义》", "example": null}, {"def": "用力推", "example": null}, {"def": "那妇人将盘一搠,且不收拾。--《初刻拍案惊奇》", "example": null}, {"def": "掉换", "example": null}, {"def": "执,持", "example": null}, {"def": "寻访", "example": null}, {"def": "捞水底月觅衣食,如投吕先生访故友,似寻吴文政搠如相知。--元·郑廷玉《金凤钗》", "example": null}, {"def": "蘸;沾", "example": null}, {"def": "只拣那卖不去的菜叶儿,将来煨熟了,又不要蘸盐搠酱,", "example": null}, {"def": "搠shuò刺，戳～伤。～死。", "example": null}]','chinese-xinhua','0'),
('2101143296733614094','蒴','1','shuò','艹','13',NULL,'[{"def": "蒴", "example": null}, {"def": "果实的一种类型", "example": null}, {"def": "结蒴似荞麦蒴而圆,中有小子,如油子大。--《救荒本草》", "example": null}, {"def": "蒴苞", "example": null}, {"def": "蒴果", "example": null}, {"def": "蒴轴", "example": null}, {"def": "蒴shuò", "example": null}]','chinese-xinhua','0'),
('2101143296733614095','妁','1','shuò','女','6',NULL,'[{"def": "妁", "example": null}, {"def": "媒人", "example": null}, {"def": "妁,媒也。--《集韵》", "example": null}, {"def": "妁shuò旧时称婚姻介绍人媒～。", "example": null}]','chinese-xinhua','0'),
('2101143296733614096','烁','1','shuò','火','9',NULL,'[{"def": "烁", "example": null}, {"def": "(形声。从火,乐声。本义发光的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "中夜有大流星长数丈,光烁如电。--《新唐书·天文志》", "example": null}, {"def": "热;烫;烤灼", "example": null}, {"def": "烁", "example": null}, {"def": "摇曳;闪烁", "example": null}, {"def": "其外浅处,紫碧浮映,日光所烁也。--《徐霞客游记》", "example": null}, {"def": "通铄”。销熔", "example": null}, {"def": "烁金以为刃。--《周礼·考工记·总敍》", "example": null}, {"def": "众口烁金。--《国语·周语》", "example": null}, {"def": "又如烁金(熔化金属;另指伤人的谗言)", "example": null}, {"def": "烁（爍）shuò发光的样子闪～。光～如闪电。", "example": null}, {"def": "烁luò 1.见\\"爆烁\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296733614097','朔','1','shuò','月','10',NULL,'[{"def": "朔", "example": null}, {"def": "(会意。从月,从屰,屰亦声。本义农历每月初一)", "example": null}, {"def": "同本义", "example": null}, {"def": "朔,月一日始苏也。--《说文》。按,凡月与日同经度不同纬度则为合朔,同经度又同纬度即为日蚀。计173日有奇。", "example": null}, {"def": "朔,月初之名也。--《释名》", "example": null}, {"def": "月言朔。--《白虎通·四时篇》", "example": null}, {"def": "朔月奠。--《仪礼·士丧礼》。注朔月,月朔也。”", "example": null}, {"def": "朔月辛卯。--《诗·小雅·十月之交》", "example": null}, {"def": "初,藄发令下,诸生许用德者以闰六月朔,县明太祖御容明伦堂,率众拜且苦。--清·邵长蘅《阎典史传》", "example": null}, {"def": "又如朔参官(能在朔日朝参的官员);朔望之礼(指初一、十五到祀堂", "example": null}, {"def": "朔shuò", "example": null}, {"def": "⒈夏历每月初一十月～。初一谓之～。", "example": null}, {"def": "⒉北～方。～风吹。", "example": null}]','chinese-xinhua','0'),
('2101143296733614098','铄','1','shuò','钅','10',NULL,'[{"def": "铄", "example": null}, {"def": "(形声。从金,乐声。本义熔化)", "example": null}, {"def": "同本义", "example": null}, {"def": "铄,销金也。--《说文》", "example": null}, {"def": "流金铄石些。--《楚辞·招魂》", "example": null}, {"def": "夫铄金在炉,庄躥不顾。--《盐铁论·诏圣》", "example": null}, {"def": "大热铄石流金。--《淮南子·诠言训》", "example": null}, {"def": "人无筋骨之强,爪牙之利,故割革而为甲,铄铁而为刃。--《淮南子·兵略》", "example": null}, {"def": "又如铄金(销熔金属);铄石流金(使金石熔化。比喻酷热。同流金铄石”);铄化(熔化);铄金点玉(熔化金属,玷污美玉)", "example": null}, {"def": "销毁", "example": null}, {"def": "彼人含其明,则天下铄矣。--《庄子·胠箧》", "example": null}, {"def": "又如铄绝竽瑟(完全销毁乐器)", "example": null}, {"def": "削弱", "example": null}, {"def": "秦先得齐宋,则韩氏铄,韩氏铄则楚孤而", "example": null}, {"def": "铄（鑠）shuò", "example": null}, {"def": "⒈发光的样子闪～。光～如闪电。", "example": null}, {"def": "⒉熔化金属～金。销～。", "example": null}, {"def": "⒊削弱，毁坏，消灭。", "example": null}, {"def": "铄yuè 1.烙;烧灼。", "example": null}]','chinese-xinhua','0'),
('2101143296733614099','硕','1','shuò','石','11',NULL,'[{"def": "硕", "example": null}, {"def": "(形声。从页,石声。页,头。本义头大)", "example": null}, {"def": "同本义", "example": null}, {"def": "硕,头大也。--《说文》", "example": null}, {"def": "引申为大", "example": null}, {"def": "硕鼠硕鼠,无食我黍。--《诗·魏风·硕鼠》", "example": null}, {"def": "硕果不食。--《易·剥》", "example": null}, {"def": "彼其之子,硕大无朋。--《诗·唐风·椒聊》", "example": null}, {"def": "又如壮硕;肥硕;硕德(大德);硕见(高见);硕大;硕画;硕望;硕量;硕谋(远大的谋略);硕虑(深远的思虑)", "example": null}, {"def": "通石”。比喻坚固", "example": null}, {"def": "孤与将军,恩如骨肉…而忍绝王命,明弃硕交,实为佞人所构会也。--《文选·阮瑀·为曹公作书与孙权》", "example": null}, {"def": "学识渊博、德高望重的", "example": null}, {"def": "又患无硕师名人与游,", "example": null}, {"def": "硕shuò", "example": null}, {"def": "⒈大～果累累。～大无朋（朋比）。", "example": null}, {"def": "⒉", "example": null}, {"def": "硕shí 1.通\\"石\\"。比喻坚固。参见\\"硕交\\"。 2.通\\"石\\"(今读dàn)。容量单位。容十斗。 3.通\\"石\\"(今读dàn)。重量单位。重一百二十四斤。", "example": null}]','chinese-xinhua','0'),
('2101143296733614100','矟','1','shuò','','11',NULL,'[{"def": "矟shuò 1.古代兵器。长矛，槊。", "example": null}]','chinese-xinhua','0'),
('2101143296733614101','说','1','shuō','讠','9',NULL,'[{"def": "说  shui", "example": null}, {"def": "说服;劝说", "example": null}, {"def": "义兴人谓为三横,而处尤剧。或说处杀虎斩蛟,实冀三横唯余其一。--《世说新语·自新》", "example": null}, {"def": "鲰生说我曰距关,毋内诸侯,秦地可尽王也。”--《史记·项羽本纪》", "example": null}, {"def": "公子患之,数请魏王,及宾客辩士说王万端。--《史记·魏公子列传》", "example": null}, {"def": "又如游说;说士(游说的人);说客(游说之士);说项(本意为称道人善,后引申凡替人游说,阐说人情都可称说项”);说难(指用言语说服他人并不容易);说城(劝说举城投降);说", "example": null}, {"def": "导(劝说开导);说辞(游说的话);说谏(劝说进谏);说调(怂恿,撺掇)", "example": null}, {"def": "休憩;止息。通税”", "example": null}, {"def": "说yuè", "example": null}, {"def": "⒈〈古〉同\\"悦\\"。", "example": null}, {"def": "说shuì", "example": null}, {"def": "⒈说动别人，使他听从自己的意见～客。游～。", "example": null}, {"def": "说shuō", "example": null}, {"def": "⒈讲话，用话表达意思你～。～到做到。", "example": null}, {"def": "⒉言论，主张学～。著书立～。", "example": null}, {"def": "⒊批评，指责～了他几句。", "example": null}, {"def": "⒋解释解～。一～就懂。", "example": null}, {"def": "⒌指说合，介绍～婆家（介绍对象）。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "说tuō 1.简易。参见\\"说唃\\"。 2.通\\"脱\\"。解脱;免除。 3.通\\"脱\\"。急骤。", "example": null}]','chinese-xinhua','0'),
('2101143296733614102','洍','1','sì','','6',NULL,'[{"def": "洍sì", "example": null}, {"def": "⒈古同汜”，从主流分出又流回主流的岔流。", "example": null}]','chinese-xinhua','0'),
