('2101143296733614104','笥','1','sì','竹','11',NULL,'[{"def": "笥", "example": null}, {"def": "(形声。从竹,司声。本义一种盛饭食或衣物的竹器)", "example": null}, {"def": "同本义", "example": null}, {"def": "笥,盛食器也。--《说文》", "example": null}, {"def": "不见辒车,见有奉笥而与李氏语者。--《韩非子·内储说上》", "example": null}, {"def": "晔为市吏,馈饵一笥,帝德之不忘。--《后汉书·酷吏传》", "example": null}, {"def": "王以巾笥而藏之庙堂之上。--《庄子·秋水》", "example": null}, {"def": "又如笥箧(竹制的匣子)", "example": null}, {"def": "铠甲一类的防护物", "example": null}, {"def": "材官驺发,矢道同的,则匈奴之革笥木荐弗能支也。--《汉书》", "example": null}, {"def": "笥", "example": null}, {"def": "装;藏", "example": null}, {"def": "今夫考居室必以闳门丰屋为美,笥衣裳必以文章遒泽为甲。--唐·刘禹锡《论书》", "example": null}, {"def": "笥sì〈古〉一种盛饭食或盛衣物的竹器。", "example": null}]','chinese-xinhua','0'),
('2101143296733614105','耜','1','sì','耒','11',NULL,'[{"def": "耜", "example": null}, {"def": "(形声。从耒,以声。耒,翻土的工具。本义古代农具名,耒耜的主要部件,似锹) 耒下端铲土的部分,装在犁上,用以翻土", "example": null}, {"def": "字亦作耜。", "example": null}, {"def": "耜,来下剌臿也。古以木为之,后世以金。--《六书故》", "example": null}, {"def": "斵木为耜。--《易·系辞》", "example": null}, {"def": "禹亲自操耜。--《庄子·天下》", "example": null}, {"def": "古者剡耜而耕。--《淮南子·泛率》", "example": null}, {"def": "脩来耜。--《礼记·月令》", "example": null}, {"def": "民无悬耜,野无奥草。--《国语·周语中》。韦昭注入土曰耜,耜柄曰耒。”", "example": null}, {"def": "耜", "example": null}, {"def": "引申为以耜铲土", "example": null}, {"def": "藄氏掌杀草…冬日至而耜之。--《周礼·藄氏》", "example": null}, {"def": "耜sì", "example": null}, {"def": "⒈〈古〉一种似锹的农具。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒉\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296733614106','覗','1','sì','','8',NULL,'[{"def": "覗sì窥视。", "example": null}]','chinese-xinhua','0'),
('2101143296733614107','嗣','1','sì','口','13',NULL,'[{"def": "嗣", "example": null}, {"def": "(形声。从册,从口,司声。册,帝王对臣下封土授爵的文书。口,下令。甲骨文从大,从子,从册,会意。大子,即嫡长子。本义诸侯传位给嫡长子)", "example": null}, {"def": "同本义", "example": null}, {"def": "嗣,诸侯嗣国也。--《说文》", "example": null}, {"def": "舜让于德,弗嗣。--《书·舜典》", "example": null}, {"def": "将使嗣位。--《书·舜典序》", "example": null}, {"def": "又如嗣王(继位之王);嗣君(继位的君主);嗣主(继位的国君);嗣位(继承君位);嗣皇(继位的帝王);嗣圣(新继位的皇帝);嗣临(继登皇位)", "example": null}, {"def": "继承;接续", "example": null}, {"def": "嗣,继也。--《尔雅》", "example": null}, {"def": "禹乃嗣兴。--《书·洪范》。传继也。”", "example": null}, {"def": "其弟嗣书。--《左传·襄公二十", "example": null}, {"def": "嗣sì", "example": null}, {"def": "⒈继承，接续，随后～位。～子。～随。", "example": null}, {"def": "⒉子孙后～（子孙后代）", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296733614108','肆','1','sì','聿','13',NULL,'[{"def": "肆", "example": null}, {"def": "(形声。从长,聿声。本义摆设;陈列)", "example": null}, {"def": "同本义", "example": null}, {"def": "肆,极陈也。--《说文》。朱骏声曰此字本训长。”", "example": null}, {"def": "肆,陈也。--《广韵》", "example": null}, {"def": "或剥或享,或肆或将。--《诗·小雅·楚茨》", "example": null}, {"def": "肆筵设席,授几有缉御。--《诗·大雅·行苇》", "example": null}, {"def": "又如肆筵(摆设筵席);肆肆(并列的样子)", "example": null}, {"def": "古时处死刑后陈尸示众", "example": null}, {"def": "吾力犹能肆诸市朝。--《论语·宪局》", "example": null}, {"def": "又如肆刑(极刑);肆掠(陈尸示众和鞭笞);肆鬯(陈尸设鬯。为古浴尸之礼)肆器(古代陈尸之器)", "example": null}, {"def": "进献解体牺牲", "example": null}, {"def": "以肆献裸享先王。--《周礼·春官·大宗伯》", "example": null}, {"def": "肆sì", "example": null}, {"def": "⒈\\"四\\"的大写。", "example": null}, {"def": "⒉放纵，任意放～。～无忌惮。", "example": null}, {"def": "⒊店铺的旧称茶～。酒～。", "example": null}, {"def": "肆tī 1.解剔牲体。", "example": null}, {"def": "肆yì 1.习。 2.余，多余。", "example": null}]','chinese-xinhua','0'),
