('2101143296733614114','巳','1','sì','巳','3',NULL,'[{"def": "巳", "example": null}, {"def": "(象形。甲骨文字形,像在胎包中生长的小儿。本义在胎包中成长的小儿)", "example": null}, {"def": "同本义", "example": null}, {"def": "巳,似也。象子在包中形,包字从之。╠朱骏声《说文通训定声》", "example": null}, {"def": "巳则生已定也。--《淮南子·天文》", "example": null}, {"def": "地支的第六位", "example": null}, {"def": "与天干相配,用以纪年。如一九四一年为农历辛巳年", "example": null}, {"def": "用以纪月,即农历四月", "example": null}, {"def": "用以纪时,即上午九时至十一时。如巳牌(九时到十一时)", "example": null}, {"def": "十二生肖属蛇", "example": null}, {"def": "巳,火也,其禽蛇也。--《论衡》", "example": null}, {"def": "巳sì", "example": null}, {"def": "⒈地支的第六位，也用作次序第六。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296733614115','亖','1','sì','','15',NULL,'[{"def": "亖sì 1.《说文．四部》\\"亖，籀文四。\\"清周中孚《郑堂札记》卷四﹕\\"竹垞《讀篇書後》，祗以書日之法疑其爲僞，但\'四\'字古文作\'亖\'，偏護古文者，亦可籍口脱去", "example": null}, {"def": "上一畫爲辭。\\"一说\\"二\\"的古字。", "example": null}]','chinese-xinhua','0'),
('2101143296737808384','四','1','sì','囗','5',NULL,'[{"def": "四", "example": null}, {"def": "(指事。甲骨文字形,象鼻子喘息呼气之形。本义数目。三加一所得) 同本义", "example": null}, {"def": "四,阴数也。四分之。--《说文》", "example": null}, {"def": "阴数次三也。--《玉篇》", "example": null}, {"def": "路下四亚之。--《仪礼·觐礼》。注谓乘马也。”", "example": null}, {"def": "光被四表。--《书·尧典》", "example": null}, {"def": "闰月定四时成岁。", "example": null}, {"def": "良马四之--《诗·鄘风·干旄》", "example": null}, {"def": "安得猛士兮守四方!--刘邦《大风歌》", "example": null}, {"def": "又如四垂(四边);四梢(城镇四方边缘地方);四隅头(四方街口,四处);四柱(指人出生的年、月、日、时);四不拗六(少数拗不过多数);四趁(相称,各处都合适);四门(四方之门", "example": null}, {"def": ");四鼓(四更);四知(天知、神知、我知、子知);四", "example": null}, {"def": "四sì数目字三～五。", "example": null}]','chinese-xinhua','0'),
('2101143296737808385','罒','1','sì','','15',NULL,'[{"def": "罒sì 1.汉字部首。通称\\"罒字头\\"。用\\"罒\\"作部首的例字有﹕罪﹑买﹑詈等。", "example": null}]','chinese-xinhua','0'),
('2101143296737808386','寺','1','sì','寸','6',NULL,'[{"def": "寺", "example": null}, {"def": "(形声。小篆字形,从寸,之声。寸,与法度有关。本义古代官署的名称。秦以官员任职之所,通称为寺。如大理寺(职掌审核刑狱案件))", "example": null}, {"def": "同本义", "example": null}, {"def": "寺,廷也,有法度者也。--《说文》", "example": null}, {"def": "寺,治也,官舍也。--《一切经音义》", "example": null}, {"def": "寺,官舍也。--《三苍 》", "example": null}, {"def": "寺,官也。--《广雅》。按,朝中官曹所止理事之处。", "example": null}, {"def": "令骑奴还至寺门。--《汉书·何竝传》。注诸官曹之所,通呼为寺。”", "example": null}, {"def": "城郭官寺。--《汉书·元帝纪》。注凡府廷所在,皆谓之寺。”", "example": null}, {"def": "列寺七里。--左思《吴都赋》", "example": null}, {"def": "又如寺正(大理寺正卿的略称);寺舍(官舍。官署", "example": null}, {"def": "寺sì", "example": null}, {"def": "⒈〈古〉中央机构名或官署名大理～。府～宽敞。", "example": null}, {"def": "⒉佛教、伊斯兰教等居住或进行宗教活动的地方～庙。佛～。清真～。", "example": null}, {"def": "寺shì 1.近侍。常指阉人。", "example": null}]','chinese-xinhua','0'),
('2101143296737808387','汜','1','sì','氵','6',NULL,'[{"def": "汜", "example": null}, {"def": "由干流分出又汇合到干流的水", "example": null}, {"def": "汜,水别复入水也。从水,巳声。--《说文》", "example": null}, {"def": "江有汜,之子归,不我以。--《诗·召南·江有汜》", "example": null}, {"def": "不流通的水沟", "example": null}, {"def": "穷渎,汜。--《尔雅·释丘》。郭璞注水无所通者。”", "example": null}, {"def": "水名", "example": null}, {"def": "汜水,源出方山。--《读史方舆纪要》", "example": null}, {"def": "水边", "example": null}, {"def": "出自汤谷,次于蒙汜。--《楚辞》", "example": null}, {"def": "汜sì汜水，在河南省。", "example": null}]','chinese-xinhua','0'),
('2101143296737808388','伺','1','sì','亻','7',NULL,'[{"def": "伺候", "example": null}, {"def": "伺候柴进回庄,林冲便说道…--《水浒传》", "example": null}, {"def": "si", "example": null}, {"def": "伺", "example": null}, {"def": "(形声。从人,司声。本义候望,探察)", "example": null}, {"def": "同本义", "example": null}, {"def": "伺,候望也。--《说文新附》", "example": null}, {"def": "其后阁下位益尊,伺侯于门墙者日益进。--唐·韩愈《与陈给事书》", "example": null}, {"def": "如伺候(等候;服侍;衙役);伺觇(窥探);伺闲(窥测时机)", "example": null}, {"def": "观察", "example": null}, {"def": "伺,视也。--《方言十》", "example": null}, {"def": "童微伺其睡,以缚背刃,力上下,得绝。--唐·柳宗元《童区寄传》", "example": null}, {"def": "逆阉防伺甚严,虽家仆不得近。--清·方苞《左忠毅公逸事》", "example": null}, {"def": "又如伺察(观察;侦察);伺望(守望;察看);伺漏(", "example": null}, {"def": "伺 cì又见sì。", "example": null}, {"def": "【伺候】旧指侍奉或供使唤。现也指照料人的饮食起居等日常生活～病人。～病人。", "example": null}, {"def": "伺sì", "example": null}, {"def": "⒈探察，侦候～敌。～机。窥～。", "example": null}]','chinese-xinhua','0'),
('2101143296737808389','似','1','sì','亻','6',NULL,'[{"def": "似", "example": null}, {"def": "(形声。从人,以声。本义像;相像)", "example": null}, {"def": "同本义", "example": null}, {"def": "似,象也。--《说文》", "example": null}, {"def": "似,有以相攖,有不相櫻也。--《墨子经上》", "example": null}, {"def": "见似目瞿。--《礼记·杂记》。注谓容貌似其父母。”", "example": null}, {"def": "寡人虽无似也。--《礼记·哀公问》。注无似犹言不肖。”", "example": null}, {"def": "似,类也。--《广雅》", "example": null}, {"def": "凄然似秋,暖然似春。--《庄子·大宗师》", "example": null}, {"def": "夫马似鹿者而题之千金。--《韩非子·外储说右上》", "example": null}, {"def": "玉人之所患,患石之似玉者。--《吕氏春秋·疑似》", "example": null}, {"def": "今世之主法先王之法也,有似于此。--《吕氏春秋·察今》", "example": null}, {"def": "布衾多年冷似铁,娇儿恶卧踏里裂。--唐·", "example": null}, {"def": "似shì", "example": null}, {"def": "⒈", "example": null}, {"def": "似sì", "example": null}, {"def": "⒈像。相像类～。相～。", "example": null}, {"def": "⒉好像，〈表〉不确定～乎。～懂非懂。～曾相识。～觉不妥。", "example": null}, {"def": "⒊〈表〉比较，相当于\\"过\\"、\\"超过\\"一个强～一个。生活一年甚～一年。", "example": null}]','chinese-xinhua','0'),
('2101143296737808390','兕','1','sì','儿','7',NULL,'[{"def": "兕", "example": null}, {"def": "(象形。本义雌性犀牛) 同本义", "example": null}, {"def": "兕,如野牛而青,象形。--《说文》", "example": null}, {"def": "唐叔射兕于徒林。--《国语·晋语》", "example": null}, {"def": "兕甲寿二百年。--《考工记·函人》", "example": null}, {"def": "虎兕出于柙,龟玉毁于椟中,是谁之过与?--《论语·季氏》", "example": null}, {"def": "兕sì〈古〉指雌性的犀牛。", "example": null}]','chinese-xinhua','0'),
('2101143296737808391','姒','1','sì','女','7',NULL,'[{"def": "姒", "example": null}, {"def": "(形声。从女,以声。本义古代兄弟之妻年长者)", "example": null}, {"def": "同本义。古以兄妻为姒,弟妻为娣;相谓亦曰姒。弟妻称兄妻为姒", "example": null}, {"def": "娣妇谓长妇为姒妇。--《尔雅·释亲》", "example": null}, {"def": "吾不以妾为姒。--《左传·成公十一年》。注昆弟之妻,相谓为姒。”", "example": null}, {"def": "少妇谓长妇曰姒,言其先来已所当法似也。--《释名·释亲属》", "example": null}, {"def": "又如姒娣(妯娌);姒妇(古代弟之妻称兄之妻为姒妇)", "example": null}, {"def": "古代同夫诸妾称长者曰姒,幼者曰娣", "example": null}, {"def": "女子同出,谓先生为姒,后生为娣。--《尔雅·释亲》。郭璞注同", "example": null}, {"def": "姒sì〈古〉弟妻称兄妻娣～（妯娌）。", "example": null}]','chinese-xinhua','0'),
('2101143296737808392','泤','1','sì','','6',NULL,'[{"def": "泤sì", "example": null}, {"def": "⒈古水名。", "example": null}]','chinese-xinhua','0'),
('2101143296737808393','祀','1','sì','礻','7',NULL,'[{"def": "祀", "example": null}, {"def": "(形声。从示,巳声。示”常与祭祀有关。本义祭祀天神)", "example": null}, {"def": "同本义", "example": null}, {"def": "祀,祭无已也。--《说文》", "example": null}, {"def": "祀,国之大事也。", "example": null}, {"def": "左传·文公二年》", "example": null}, {"def": "五祀。--《周礼·在宗伯》。郑注五色之帝。”", "example": null}, {"def": "以雷鼓鼓神祀。--《周礼》。贾公彦疏天神称祀,地祗称祭,宗庙称享。”", "example": null}, {"def": "一说指祭祀地神", "example": null}, {"def": "祠,祭也,天祭也。祀,地祭也。--唐·玄应《一切经音义》", "example": null}, {"def": "祭祀", "example": null}, {"def": "国之大事,在祀与戎。--《左传·成公十三年》", "example": null}, {"def": "祭祀必祝之。--《战国策》", "example": null}, {"def": "瑞抚吴甫半岁,小民闻当去,号", "example": null}, {"def": "祀（秚）sì", "example": null}, {"def": "⒈指祭祀。", "example": null}, {"def": "⒉商代称\\"年\\"三～。", "example": null}]','chinese-xinhua','0'),
('2101143296737808394','価','1','sì','','6',NULL,'[{"def": "価sì 1.相像，类似。", "example": null}]','chinese-xinhua','0'),
('2101143296737808395','泗','1','sì','氵','8',NULL,'[{"def": "泗", "example": null}, {"def": "(形声。从水,四声。本义泗水)", "example": null}, {"def": "同本义", "example": null}, {"def": "泗滨浮磬。--《书·禹贡》", "example": null}, {"def": "宣公夏滥于泗渊。--《国语·鲁语》", "example": null}, {"def": "在山东省中部。如泗上(泛指泗水北岸的地域);泗川(泗水);泗石(泗水之滨的石头)", "example": null}, {"def": "鼻涕", "example": null}, {"def": "泗,涕泗也。--《广韵》", "example": null}, {"def": "涕泗滂沱。--《诗·陈风·泽陂》。传自目曰涕,自鼻曰泗。”", "example": null}, {"def": "悲泗淋漓,诚怛人心。--李朝威《柳毅传》", "example": null}, {"def": "面缚两降将,跪城下说降,涕泗交颐。--清·邵长蘅《阎典史传》", "example": null}, {"def": "又如泗涕(鼻液);泗涕(鼻涕和眼泪)", "example": null}, {"def": "泗sì鼻涕涕～（眼泪与鼻涕）如雨。", "example": null}]','chinese-xinhua','0'),
('2101143296737808396','饲','1','sì','饣','8',NULL,'[{"def": "饲", "example": null}, {"def": "(形声。从食,司声。本义给人吃,喂食。本作食”)", "example": null}, {"def": "同本义", "example": null}, {"def": "屈指计归,张颐待饲。--《旧唐书》", "example": null}, {"def": "饲养,给动物吃东西", "example": null}, {"def": "饲", "example": null}, {"def": "粮食", "example": null}, {"def": "饲,粮也。--《集韵》", "example": null}, {"def": "指饲料", "example": null}, {"def": "饲sì喂食～料。～蚕。～养鸡鸭。", "example": null}]','chinese-xinhua','0'),
('2101143296737808397','驷','1','sì','马','8',NULL,'[{"def": "驷", "example": null}, {"def": "(形声。从马,四声。本义同驾一辆车的四匹马。或驾四马之车)", "example": null}, {"def": "同本义", "example": null}, {"def": "驷,马一乘也。--《说文》。徐锴曰四马也。”", "example": null}, {"def": "驷,四马一乘也。--《玉篇》", "example": null}, {"def": "驷介旁旁。--《诗·郑风·清人》", "example": null}, {"def": "结驷千乘。--《庄子·人间世》", "example": null}, {"def": "齐景公有马千驷。--《论语·季氏》", "example": null}, {"def": "齐王闻之,君臣恐惧遣太傅赍黄金千斤,文东二驷,服剑一封书谢孟尝君。--《战国策·齐策》", "example": null}, {"def": "又如上驷(最好的驾四马之车);驷牡(同驾一车的四匹公马);驷马之门(能容驷马高车通过的大门。借指显贵);驷介(由四匹披甲战马拉的车);驷铁(驾一车的四匹赤黑", "example": null}, {"def": "驷sì〈古〉套着四匹马的车，也指一辆车套着的四匹马一言既出，～马难追（〈喻〉说了的话，一定算数）。", "example": null}]','chinese-xinhua','0'),
('2101143296737808398','俟','1','sì','亻','9',NULL,'[{"def": "俟", "example": null}, {"def": "(形声。从人,矣声。本义大) 同本义", "example": null}, {"def": "俟,大也。--《说文》", "example": null}, {"def": "儷儷俟俟,或群或友。--《诗·小雅·吉日》", "example": null}, {"def": "俟", "example": null}, {"def": "等待", "example": null}, {"def": "静女其姝,俟我于城隅。--《诗·邶风·静女》", "example": null}, {"def": "俟于门外。--《仪礼·士昏礼》", "example": null}, {"def": "如其礼乐,以俟君子。--《论语·先进》", "example": null}, {"def": "故君子居易以俟命,小人行险以徼幸。--《礼记·中庸》", "example": null}, {"def": "故为之说,以俟夫观人风者得焉。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "又如俟命(等待命令);俟吉(等待吉日);俟候(等待;等候);俟时(等待时机);俟望(等待盼望);俟嗣(等待继位);俟河之清(等待黄河水清,比喻希望不可能实现)", "example": null}, {"def": "俟qí", "example": null}, {"def": "⒈", "example": null}, {"def": "俟（竢）sì", "example": null}, {"def": "⒈等待～机行事。", "example": null}]','chinese-xinhua','0'),
