('2101143296737808420','斯','1','sī','斤','12',NULL,'[{"def": "斯", "example": null}, {"def": "(会意。从斤,其声。其所以盛木柿。斤,斧子。本义劈;砍)", "example": null}, {"def": "同本义", "example": null}, {"def": "斯,析也。--《说文》", "example": null}, {"def": "墓门有棘,斧以斯之。--《诗·陈风·墓门》", "example": null}, {"def": "有斯明享。--《书·酒诰》。郑注析也。”", "example": null}, {"def": "厮(斯)舆之卒。--《汉书·严助传》。注析薪者也。”", "example": null}, {"def": "扯裂", "example": null}, {"def": "斯,裂也。--《广雅》。王念孙疏证今俗语犹呼手裂为斯。”", "example": null}, {"def": "分开", "example": null}, {"def": "斯而析之,精至于无伦,大至于不可围。--《庄子》", "example": null}, {"def": "距离;离开", "example": null}, {"def": "华胥氏之国…不知斯齐国几千万里。--《列子·黄帝》", "example": null}, {"def": "斯", "example": null}, {"def": "斯”假借为此”,这,这个", "example": null}, {"def": "斯,此也。", "example": null}, {"def": "斯sī", "example": null}, {"def": "⒈指示代词。此，这个，这里～人。～时。如～。至于～。", "example": null}, {"def": "⒉连词。就，乃，那么天下之道，理安，～得人者也。", "example": null}, {"def": "⒊文言助词。同\\"兮\\"哀我人～。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296737808421','缌','1','sī','纟','12',NULL,'[{"def": "缌", "example": null}, {"def": "制作丧服的细麻布", "example": null}, {"def": "古代丧服名。五种丧服之最轻者,以细麻布为孝服,服丧三个月", "example": null}, {"def": "诸侯之丧服)", "example": null}, {"def": "较为疏远的亲属关系", "example": null}, {"def": "之轻者。借指关系疏远的族人);缌服(缌麻服。多指关", "example": null}, {"def": "缌sī细的麻布。", "example": null}]','chinese-xinhua','0'),
('2101143296737808422','蛳','1','sī','虫','12',NULL,'[{"def": "蛳", "example": null}, {"def": "螺蛳", "example": null}, {"def": "蛳,螺蛳。--《字汇》", "example": null}, {"def": "蛳（螄）sī", "example": null}]','chinese-xinhua','0'),
('2101143296737808423','楒','1','sī','','9',NULL,'[{"def": "楒sī 1.木名。即相思树。豆科，蔓生灌木。叶为羽状复叶，多椭圆形小叶。花呈蝶形，白色或带红色。豆科有些具有红色种子的树种，如红豆树等，也叫相思树。 2.人名用", "example": null}, {"def": "字。明有朱佑楒。见《明史·枣阳王佑楒传》。", "example": null}]','chinese-xinhua','0'),
('2101143296737808424','鉰','1','sī','','9',NULL,'[{"def": "鉰sī 1.金属元素\\"钪\\"的旧译。", "example": null}]','chinese-xinhua','0'),
('2101143296737808425','厶','1','sī','厶','2',NULL,'[{"def": "厶", "example": null}, {"def": "私”的古字。自营。为自己利益,不择手段去营求。与公”相对", "example": null}, {"def": "古者仓颉之作书也,自环者谓之厶,背厶谓之公。--《韩非子》", "example": null}, {"def": "厶sī\\"私\\"的古字。", "example": null}]','chinese-xinhua','0'),
('2101143296737808426','丝','1','sī','一','5',NULL,'[{"def": "丝", "example": null}, {"def": "(会意。从二糸。糸,细丝。本义蚕丝)", "example": null}, {"def": "同本义", "example": null}, {"def": "丝,蚕所吐也。--《说文》。段注凡蚕者为丝、麻者为缕。”", "example": null}, {"def": "素丝五总。--《诗·召南·羔羊》", "example": null}, {"def": "金石丝竹,乐之器也。谓弦也。”--《礼记·乐记》", "example": null}, {"def": "山东多鱼盐漆丝声色。--《史记·货殖列传序》", "example": null}, {"def": "此织生于蚕茧,成于机杼。一丝而累,以至于寸。--《后汉书·列女传》", "example": null}, {"def": "春蚕到死丝方尽,蜡炬成灰泪始干。--李商隐《无题》", "example": null}, {"def": "二月卖新丝,五月粜新谷。--聂夷中《咏田家》", "example": null}, {"def": "缯帛如山积,丝絮似云屯。--唐·白居易《重赋》", "example": null}, {"def": "又如丝棉;丝网;丝缰(丝制的马缰绳);丝人(治理蚕丝", "example": null}, {"def": "丝（絲）sī", "example": null}, {"def": "⒈蚕吐出的纤维。它是绸、缎等的原料新～。", "example": null}, {"def": "⒉像丝的东西蛛～。铁～。肉～儿。", "example": null}, {"def": "⒊细微，极少，细致一～不苟。～毫不差。～ ～入扣。", "example": null}, {"def": "⒋计量单位十～为一毫。百～为一厘。", "example": null}]','chinese-xinhua','0'),
('2101143296737808427','司','1','sī','口','5',NULL,'[{"def": "司", "example": null}, {"def": "(指事。甲骨文字形,表示一个人用口发布命令,有统治、管理义。从反后,意思说,与帝王后”相对为司”,即有司。本义职掌,主管)", "example": null}, {"def": "同本义(含负责掌握、处理之意)", "example": null}, {"def": "司,臣司事于外者。--《说文》", "example": null}, {"def": "司,臣也。--《广雅》", "example": null}, {"def": "司,主也。--《小尔雅》。按,周官四十有一司,司者,理其事也。", "example": null}, {"def": "司王朝。--《周礼·师氏》", "example": null}, {"def": "司,主也。--《广雅》", "example": null}, {"def": "曰司徒。--《礼记·曲礼》。疏凡言司者,总其领也。”", "example": null}, {"def": "至于守司囹圄,禁制刑罚,人臣擅之,此谓刑劫。--《韩非子·三守》", "example": null}, {"def": "使鸡司夜,令狸执鼠,皆用其能,上乃无事。--《韩", "example": null}, {"def": "司sī", "example": null}, {"def": "⒈主管，掌管～令。～法。～机。各～其事。", "example": null}, {"def": "⒉政府机关名称。我国部以下的办事单位外交部西欧～。", "example": null}, {"def": "⒊观察～日月之长短。", "example": null}, {"def": "司sì 1.通\\"伺\\"。侦察;探察。 2.通\\"伺\\"。守候;等待。 3.同\\"嗣\\"。继承。", "example": null}]','chinese-xinhua','0'),
('2101143296737808428','糹','1','sī','','5',NULL,'[{"def": "糹mì 1.汉字部首。通称\\"绞丝旁\\"或\\"乱绞丝\\"。用\\"糹\\"作部首的例字有﹕红﹑约﹑纯等。", "example": null}]','chinese-xinhua','0'),
('2101143296737808429','私','1','sī','禾','7',NULL,'[{"def": "私", "example": null}, {"def": "(形声。从禾,厶声。本义禾;庄稼)", "example": null}, {"def": "同本义", "example": null}, {"def": "私,禾也。北道名禾主人曰私主人。--《说文》。段玉裁注盖禾有名私者也。”", "example": null}, {"def": "中国古时女子称姊妹之夫为私", "example": null}, {"def": "谭公维私。--《诗·卫风·硕人》。孔颖达疏引孙炎曰私,无正亲之言。”", "example": null}, {"def": "男女阴部", "example": null}, {"def": "早有私病,不近妇人。--汉·伶玄《赵飞燕外传》", "example": null}, {"def": "又如私病;私处(生殖器)", "example": null}, {"def": "日常衣服", "example": null}, {"def": "薄污我私。--《诗·周南·葛覃》", "example": null}, {"def": "又如私衣(官吏日常的便衣)", "example": null}, {"def": "非法的货物", "example": null}, {"def": "私sī", "example": null}, {"def": "⒈个人的，跟\\"公\\"相对～事。～有。", "example": null}, {"def": "⒉为自己～心。自～。无～无畏。", "example": null}, {"def": "⒊秘密，偷偷地～自。～下。隐～。窃窃～语。", "example": null}, {"def": "⒋不合法的～货。走～。", "example": null}, {"def": "⒌不公道偏～。", "example": null}]','chinese-xinhua','0'),
('2101143296737808430','咝','1','sī','口','8',NULL,'[{"def": "咝", "example": null}, {"def": "形容尖细的长声", "example": null}, {"def": "咝咝声", "example": null}, {"def": "咝（噝）sī像声词子弹～ ～地从头顶飞过。热铁片烙在肉上～ ～地响。", "example": null}]','chinese-xinhua','0'),
