('2101143296737808472','嗾','1','sǒu','口','14',NULL,'[{"def": "嗾", "example": null}, {"def": "(形声。从口,族声。本义使狗;发出使狗咬人的声音)", "example": null}, {"def": "同本义", "example": null}, {"def": "公嗾夫獒焉--《左传·宣公二年》", "example": null}, {"def": "嗾犬狺狺相索索,舐掌偏宜佩兰客。--唐·李贺《公无出门》", "example": null}, {"def": "教唆,指使", "example": null}, {"def": "豪嗾家奴乱捶之…--《聊斋志异》", "example": null}, {"def": "泛指使唤;呼之使行", "example": null}, {"def": "那只白鹅,见地下有血,各处流动,就来吃血,穿珠人把鹅嗾去,不久又复走来。--沈从文《月下小景》", "example": null}, {"def": "嗾使", "example": null}, {"def": "观音坡那回事他其实没有嗾使别人去干,完全是那此侉子好管闲是闲非。--张天翼《清明", "example": null}, {"def": "嗾sǒu", "example": null}, {"def": "⒈用嘴发出声音，驱使狗活动。", "example": null}, {"def": "⒉怂恿，教唆指使～使。", "example": null}]','chinese-xinhua','0'),
('2101143296737808473','瞍','1','sǒu','目','14',NULL,'[{"def": "瞍", "example": null}, {"def": "眼睛瞎没有眼珠", "example": null}, {"def": "矇瞍不可使视,嚣喑不可使言。--《国语·晋语四》", "example": null}, {"def": "矇瞍奏公。--《诗·大雅·灵台》", "example": null}, {"def": "对长者的称呼", "example": null}, {"def": "负罪引慝,祗载见瞽瞍。--《书·大禹谟》。蔡沈传瞍,长者之称。”", "example": null}, {"def": "缩", "example": null}, {"def": "瞍,缩坏也。--《释名》。毕沅疏证缩与瞍一声之转,故得为训。”", "example": null}, {"def": "瞍sǒu瞎子，眼里没有瞳人。", "example": null}]','chinese-xinhua','0'),
('2101143296737808474','擞','1','sǒu','扌','16',NULL,'[{"def": "擞", "example": null}, {"def": "通", "example": null}, {"def": "擞（擻）sòu用扦子在火炉里摇拨抖灰～一～炉灰。", "example": null}, {"def": "擞（擻）sǒu", "example": null}]','chinese-xinhua','0'),
('2101143296737808475','薮','1','sǒu','艹','16',NULL,'[{"def": "薮", "example": null}, {"def": "(形声。从苃,数声。沼泽地带多长草,故从苃。本义湖泽的通称。也指水少而草木茂盛的湖泽)", "example": null}, {"def": "同本义", "example": null}, {"def": "薮,大泽也。--《说文》", "example": null}, {"def": "十薮。--《尔雅·释地》。李注薮,泽之别名也。”", "example": null}, {"def": "薮,物之归也。--《国语·周语下》", "example": null}, {"def": "度山林,鸠薮泽。--《左传·襄公二十五年》", "example": null}, {"def": "人或物聚集的地方", "example": null}, {"def": "为天下逋逃主,萃渊薮。--《书·武成》", "example": null}, {"def": "山薮藏疾。--《左传·宣公十五年》。注薮是草木积聚之处,近山近泽皆得称薮。”", "example": null}, {"def": "密迩奸薮。--郭璞《奏", "example": null}, {"def": "薮（藪）sǒu", "example": null}, {"def": "⒈水少而草木茂盛的湖泽～泽。", "example": null}, {"def": "⒉人或物聚集的地方渊～。", "example": null}, {"def": "薮còu 1.车毂中心穿孔以承轴的部分。", "example": null}]','chinese-xinhua','0'),
