('2101143296746196999','粟','1','sù','米','12',NULL,'[{"def": "粟", "example": null}, {"def": "(会意,象草木果实下垂的样子◇隶变为西”。本义粟子,谷子)", "example": null}, {"def": "同本义", "example": null}, {"def": "谷物、干草和饲料", "example": null}, {"def": "粟,嘉谷实也。--《说文》", "example": null}, {"def": "其粟麦粳稻之属各依土地,贮之州县。--《旧唐书·食货志下》", "example": null}, {"def": "输不必金,出粟、菽、帛、布及它物者听。--清·邵长蘅《阎典史传》", "example": null}, {"def": "又如粟入(税粟的收入);粟粒(谷物的颗粒)", "example": null}, {"def": "谷粒", "example": null}, {"def": "迁淳安知县。布袍脱粟,令老仆艺", "example": null}, {"def": "粟sù", "example": null}, {"def": "⒈谷子，去皮后称为\\"小米\\"。它是我国北方重要粮食作物之一。", "example": null}, {"def": "⒉泛指粮食。", "example": null}]','chinese-xinhua','0'),
('2101143296746197000','谡','1','sù','讠','12',NULL,'[{"def": "谡", "example": null}, {"def": "站起来", "example": null}, {"def": "谡谡", "example": null}, {"def": "谡谡长松", "example": null}, {"def": "谡谡风来", "example": null}, {"def": "谡sù", "example": null}, {"def": "⒈起来。", "example": null}, {"def": "⒉肃敬的样子。", "example": null}]','chinese-xinhua','0'),
('2101143296746197001','嗉','1','sù','口','13',NULL,'[{"def": "嗉", "example": null}, {"def": "许多鸟类的食管的扩大部分,形成一个小囊,用来贮存食物,并对其初步浸解", "example": null}, {"def": "岂无鵰,嗉中食饱不肯搏。--唐·白居易《秦吉了》", "example": null}, {"def": "装酒或饮料的容器", "example": null}, {"def": "嗉囊", "example": null}, {"def": "嗉子", "example": null}, {"def": "嗉sù", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉〈方〉装酒的一种小壶，底大，颈细长。", "example": null}]','chinese-xinhua','0'),
('2101143296746197002','塑','1','sù','土','13',NULL,'[{"def": "塑", "example": null}, {"def": "(形声。从土,朔声。本义用泥土抟成人物形象)", "example": null}, {"def": "同本义", "example": null}, {"def": "明道先生(程颢)坐如泥塑人。--《二程全书·传闻杂记》", "example": null}, {"def": "--宋·苏轼《凤翔八观维摩像唐杨惠之塑在天柱寺》", "example": null}, {"def": "又如塑人;塑像;泥塑;面塑", "example": null}, {"def": "呆愣", "example": null}, {"def": "把个公子如同泥塑一般,塑在那里。--《儿女英雄传》", "example": null}, {"def": "垒砌", "example": null}, {"def": "但奇妙的是在那堂屋的天井边上塑着一个一连有三口锅的长灶头。--郭沫若《革命春秋》", "example": null}, {"def": "塑sù", "example": null}, {"def": "⒈用泥土、石膏等做成的人物形象～像。泥～。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
