('2101143296746197004','愫','1','sù','忄','13',NULL,'[{"def": "愫", "example": null}, {"def": "诚意,真情实意", "example": null}, {"def": "披腹心,见情愫。--《汉书》", "example": null}, {"def": "愫sù诚意，真情情～。", "example": null}]','chinese-xinhua','0'),
('2101143296746197005','溯','1','sù','氵','13',NULL,'[{"def": "溯", "example": null}, {"def": "(形声。从水,朔声。本义端直地逆流而上)", "example": null}, {"def": "同本义", "example": null}, {"def": "逆流而上曰溯洄。--《尔雅》", "example": null}, {"def": "溯洄从之,道阻且长。--《诗·秦风·蒹葭》", "example": null}, {"def": "至于夏水襄陵,沿溯阻绝。--郦道元《水经注·江水》", "example": null}, {"def": "实以四日半溯流流行七百里云。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "又如溯涉(逆流跋涉);溯流(逆着水流方向);溯洄(逆流而上);溯游(顺着河流向下)", "example": null}, {"def": "追朔", "example": null}, {"def": "探求", "example": null}, {"def": "由此上溯到一千八百四十年,从那时起,为了反对内外敌人,争取民族独立和人民自由幸", "example": null}, {"def": "溯（泝、遡）sù", "example": null}, {"def": "⒈逆水流而上～江行。～水而上。", "example": null}, {"def": "⒉求索根源或回忆～源。回～。", "example": null}]','chinese-xinhua','0'),
