('2101143296746197030','笇','1','suàn','','8',NULL,'[{"def": "笇suàn 1.古代计数的竹筹。 2.计数;计算。 3.谋划;计谋。 4.寿命。", "example": null}]','chinese-xinhua','0'),
('2101143296746197031','筭','1','suàn','','14',NULL,'[{"def": "筭suàn", "example": null}, {"def": "⒈计算时使用的筹码，也作\\"算\\"。", "example": null}, {"def": "⒉通\\"算\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296746197032','蒜','1','suàn','艹','13',NULL,'[{"def": "蒜", "example": null}, {"def": "(形声。从苃,祘声。本义一种多年生草本植物。有大蒜、小蒜两种)", "example": null}, {"def": "同本义", "example": null}, {"def": "栽,从古已有。蒜苗、蒜苔作蔬菜,蒜头作佐料和入药", "example": null}, {"def": "蒜,荤菜也。--《说文》", "example": null}, {"def": "蒜,菜之美者--《齐民要术》引《说文》", "example": null}, {"def": "又如蒜果(蒜头);蒜气(腋下的气味。即狐臭);蒜锤子(禅杖柄上所装蒜头状的锤);蒜条(即蒜苗。蒜的花茎;亦指细长而形似蒜苗者)", "example": null}, {"def": "指这种植物的鳞茎", "example": null}, {"def": "蒜suàn通称\\"大蒜\\"，简称\\"蒜\\"。多年生草本，开白花。地下茎通常分瓣，也有不分瓣的（独蒜），供调味食用，也供药用。叶叫\\"蒜苗\\"，花茎嫩时叫\\"蒜薹\\"，都供食用。", "example": null}]','chinese-xinhua','0'),
('2101143296746197033','算','1','suàn','竹','14',NULL,'[{"def": "算", "example": null}, {"def": "(会意。从竹,从具。竹”跟算筹有关,具”表示齐备。本义计算)", "example": null}, {"def": "同本义", "example": null}, {"def": "算,数也。--《说文》", "example": null}, {"def": "无算爵。--《仪礼·乡饮酒礼》", "example": null}, {"def": "亲则月算如邦人。--《仪礼·丧服记》", "example": null}, {"def": "明衣不在算。--《仪礼·士丧礼》", "example": null}, {"def": "有算为之节文也。--《礼记·檀弓下》", "example": null}, {"def": "何足算也?--《论语·子路》", "example": null}, {"def": "只恐把铁棍子打完了,也算不到这笔帐上来。--《儒林外史》", "example": null}, {"def": "又如算还(结算支付);算尽镏铢(极微小的数量也要算);算来(计算起来);算刻(犹计算);算定(经过计算而确定或断定);算程(计算路程)", "example": null}, {"def": "推测;料想", "example": null}, {"def": "杜郎俊赏", "example": null}, {"def": "算（祘）suàn", "example": null}, {"def": "⒈核计，计数核～。～账。", "example": null}, {"def": "⒉计划，筹谋打～。暗～。失～。细～。", "example": null}, {"def": "⒊推测，料想我～他该回家了。", "example": null}, {"def": "⒋作为，当作，认为有效那个～他的。谁说了～？", "example": null}, {"def": "⒌作罢，了结～了。", "example": null}, {"def": "⒍终于，到底总～完成了。现在～是明白了。", "example": null}, {"def": "⒎", "example": null}, {"def": "①数学中最初等、最基础的部分。它研究数的性质及其运算。", "example": null}, {"def": "②承认你说话～数？", "example": null}]','chinese-xinhua','0'),
