('2101143296746197042','遂','1','suí','辶','12',NULL,'[{"def": "遂", "example": null}, {"def": "(形声。从辵", "example": null}, {"def": "同本义", "example": null}, {"def": "遂,亡也。--《说文》", "example": null}, {"def": "行,往", "example": null}, {"def": "遂,往也。--《广雅·释诂一》", "example": null}, {"def": "不能遂。--《易·大壮》", "example": null}, {"def": "遂贤良。--《礼记·月令》", "example": null}, {"def": "又如遂行(通行;顺适地进行)", "example": null}, {"def": "称心如意;使得到满足", "example": null}, {"def": "他年如遂隐,五老是知音。--唐·李中碧《庐山》", "example": null}, {"def": "王吉曰长卿久宦游不遂,而来过我。--《史记·司马相如列传》", "example": null}, {"def": "又如遂怀(遂愿);遂隐(满足隐遁的愿望);遂初(旧时辞去官职,实现隐退的本愿)", "example": null}, {"def": "顺利地完成;成功", "example": null}, {"def": "上无乏用,百事乃遂。--《礼记·月令》", "example": null}, {"def": "四者无一遂。--汉·司马迁《报任安书》", "example": null}, {"def": "令", "example": null}, {"def": "遂suí顺，听从使唤半身不～（身体一侧瘫痪）。", "example": null}, {"def": "遂suì", "example": null}, {"def": "⒈顺，如意～心。～愿。", "example": null}, {"def": "⒉成功已～。", "example": null}, {"def": "⒊就，于是乃拙地，～得水。按摩后，腰痛～止。", "example": null}]','chinese-xinhua','0'),
('2101143296746197043','谇','1','suì','讠','10',NULL,'[{"def": "谇", "example": null}, {"def": "(形声。从言,卒声。本义责骂)", "example": null}, {"def": "同本义", "example": null}, {"def": "谇,让也。--《说文》", "example": null}, {"def": "立而谇语。--《汉书·贾谊传》", "example": null}, {"def": "察士无凌谇之事。--《庄子·徐无鬼》", "example": null}, {"def": "又如谇语(骂人话);谇辱(辱骂);谇骂(责骂)", "example": null}, {"def": "劝告;谏诤", "example": null}, {"def": "謇朝谇而夕替。--《离骚》", "example": null}, {"def": "责问;用责备的口气问", "example": null}, {"def": "立而谇语。--《汉书·贾谊传》", "example": null}, {"def": "察士无凌谇之事。--《庄子·徐无鬼》", "example": null}, {"def": "又如谇候(讯问);谇诟(责难辱骂)", "example": null}, {"def": "谇", "example": null}, {"def": "古乐章的尾声。相当于乱”", "example": null}, {"def": "谇曰已矣,国其莫吾知兮,子独台郁其谁语!”--《汉书", "example": null}, {"def": "谇suì", "example": null}, {"def": "⒈骂，责怪。", "example": null}, {"def": "⒉直言规劝。", "example": null}, {"def": "⒊问。", "example": null}, {"def": "⒋告知。", "example": null}]','chinese-xinhua','0'),
