('2101143296783945741','汰','1','tài','氵','7',NULL,'[{"def": "汰〈动〉", "example": null}, {"def": "淘洗", "example": null}, {"def": "作热汤,于大盆中浸豆黄。良久,淘汰,挪去黑皮,漉而蒸之。--《齐民要术》", "example": null}, {"def": "淘汰", "example": null}, {"def": "洗涤、清洗", "example": null}, {"def": "总为设教令,明赏罚,磨治洗汰,其俗一变。--《新唐书·马总传》", "example": null}, {"def": "挑选", "example": null}, {"def": "汰 〈名〉", "example": null}, {"def": "波涛", "example": null}, {"def": "汰,波也。--《广雅》", "example": null}, {"def": "齐吴榜以击汰。--《楚词·屈原·涉", "example": null}, {"def": "汰tài", "example": null}]','chinese-xinhua','0'),
('2101143296783945742','态','1','tài','心','8',NULL,'[{"def": "态〈名〉", "example": null}, {"def": "(会意。从心,从能。简体字为形声。从心,太声。本义姿态,姿势与状态)", "example": null}, {"def": "同本义", "example": null}, {"def": "慴,意态也。--《说文》。段注意态者,有是意,因有是状,故曰意态。从心能,会意。心所能必见于外也。”", "example": null}, {"def": "柔远能迩。--《虞书》。郑注能,恣也,恣即态也。”", "example": null}, {"def": "人之态不如备。--《荀子·成相》。按诈态也。”", "example": null}, {"def": "尽变态乎其中。--张衡《西京赋》", "example": null}, {"def": "滂心淖态。--《楚辞·大招》", "example": null}, {"def": "狗偷致态。--傅毅《舞赋》", "example": null}, {"def": "宁溘死而流亡兮,予不忍为此态也。--《楚辞·离骚》", "example": null}, {"def": "有风既作飘摇之态,无风亦呈袅娜之态。--李渔《", "example": null}, {"def": "态（慴）tài", "example": null}, {"def": "⒈形状，样子形～。体～。状～。常～。姿～。", "example": null}, {"def": "⒉情况事～。", "example": null}, {"def": "⒊", "example": null}, {"def": "①说话与举止的神情～度自然。", "example": null}, {"def": "②对人对事所采取的立场或看法～度傲慢。表明～度。", "example": null}]','chinese-xinhua','0'),
('2101143296783945743','肽','1','tài','月','8',NULL,'[{"def": "肽〈名〉", "example": null}, {"def": "酰胺之一", "example": null}, {"def": "肽tài也叫\\"胜shēng\\"。它是氨基酸脱水而成的一种化合物，含有氨基和羧基，如蛋白质、某些激素、毒素、抗菌素等。", "example": null}]','chinese-xinhua','0'),
('2101143296783945744','钛','1','tài','钅','9',NULL,'[{"def": "钛〈名〉", "example": null}, {"def": "一种具有极高熔点的银灰色轻金属元素,原子序数22,低温下通常硬而脆,加热后有展性,纯钛有延性,常温时有良好的耐腐蚀性能,主要以钛铁形式用于炼钢及制造其他用作结构", "example": null}, {"def": "材料的合金", "example": null}, {"def": "钛tài金属化学元素之一。符号ti。银白色，质硬而轻。纯钛与合金主要用于制造飞机、船舰等航天及航海工业。", "example": null}]','chinese-xinhua','0'),
('2101143296783945745','泰','1','tài','水','10',NULL,'[{"def": "泰〈形〉", "example": null}, {"def": "(形声)", "example": null}, {"def": "同本义", "example": null}, {"def": "泰,亦作汰。疑泰、太、汰三形实同字。--朱骏声《说文通训定声》", "example": null}, {"def": "安定平和", "example": null}, {"def": "泰,安也。--《字汇》", "example": null}, {"def": "宇泰定者,发乎天光。--《庄子·庚桑楚》", "example": null}, {"def": "泰而不骄,威而不猛。--《论语·尧曰》", "example": null}, {"def": "以祈国泰民安。--吴自牧《梦梁录》", "example": null}, {"def": "家贫躬耕,粟熟则食粟,…处之泰然也。--《元史·许衡传》", "example": null}, {"def": "否泰如天地。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "如泰日(天下太平的时代);泰治(太平安定);泰定(安定);泰和(太平);泰平(政教清平,国泰民安。即太平);泰通(国泰政通)", "example": null}, {"def": "奢侈", "example": null}, {"def": "泰,侈也。--《", "example": null}, {"def": "泰tài", "example": null}, {"def": "⒈平安，安定～然自若。国～民安。", "example": null}, {"def": "⒉过分，过甚俭财用，禁侈～。〈引〉最，极～古。～西（指西方各国）。", "example": null}, {"def": "⒊", "example": null}, {"def": "①五岳中的东岳，在山东省登～山而小天下。", "example": null}, {"def": "②旧时称岳父。", "example": null}]','chinese-xinhua','0'),
