('2101143296783945751','漦','1','tāi','水','15',NULL,'[{"def": "漦", "example": null}, {"def": "渗流", "example": null}, {"def": "漦,顺流也。--《说文》", "example": null}, {"def": "卜请漦而藏之。--《国语·郑语》。注龙所吐沫,龙之精气也。”", "example": null}, {"def": "漦血也。--《汉书·五行志》", "example": null}, {"def": "鱼或龙之类的涎沫", "example": null}, {"def": "古水名", "example": null}, {"def": "漦,水名。--《说文》。朱骏声通训定声陕西乾州武功县南有古漦城,疑其地有漦水。", "example": null}, {"def": "漦chí 1.鱼﹑龙之类的涎沫。", "example": null}, {"def": "漦tāi 1.古地名。", "example": null}]','chinese-xinhua','0'),
('2101143296783945752','咍','1','tāi','','9',NULL,'[{"def": "咍hāi 1.嗤笑;讥笑。 2.欢乐;欢笑。 3.叹词。表示惊异﹑感叹等。 4.助词。元明戏曲中和声用字，起加强乐曲节奏的作用。", "example": null}]','chinese-xinhua','0'),
('2101143296783945753','胎','1','tāi','月','9',NULL,'[{"def": "胎〈名〉", "example": null}, {"def": "(形声。从肉,台声。本义未生的幼体,胚胎)", "example": null}, {"def": "同本义", "example": null}, {"def": "胎,妇孕三月也。--《说文》", "example": null}, {"def": "胎,始也。--《尔雅》", "example": null}, {"def": "九窍者胎生。--《庄子·知北游》", "example": null}, {"def": "毋杀孩虫胎天飞鸟。--《礼记·月令》", "example": null}, {"def": "三月而胎。--《淮南子·精神》", "example": null}, {"def": "又如胎夭(刚出生及尚未出生的小动物);胎胞(胎儿的胞衣);胎动(胎儿在母体内蠕动);胎卵(胎生与卵生);胎形;胎位", "example": null}, {"def": "怀孕或生育的次数", "example": null}, {"def": "衬在衣服、被褥等的面子和里子之间用作填充的材料", "example": null}, {"def": "器物的坯子;物体的初步而未修整的粗模", "example": null}, {"def": "胎tāi", "example": null}, {"def": "⒈母体内的幼体～儿。胚～。", "example": null}, {"def": "⒉怀孕或生育的次数头～。第二～。", "example": null}, {"def": "⒊根源祸～。", "example": null}, {"def": "⒋器物的粗坯或衬在里面的泥～儿。棉花～。", "example": null}, {"def": "⒌轮胎车～。内～。外～。", "example": null}]','chinese-xinhua','0'),
