('2101143296783945761','覃','1','tán','覀','12',NULL,'[{"def": "覃〈名〉qin", "example": null}, {"def": "姓", "example": null}, {"def": "覃〈形〉tan", "example": null}, {"def": "意味深长", "example": null}, {"def": "覃,长味也。--《说文》。段玉裁注此与酉部醰,音同义近。”", "example": null}, {"def": "长,悠长", "example": null}, {"def": "葛之覃兮。--《诗·周南·葛覃》", "example": null}, {"def": "又如覃恩(深厚广大的恩惠)", "example": null}, {"def": "覃 〈动〉", "example": null}, {"def": "蔓延,延伸,延伸到", "example": null}, {"def": "覃及鬼方。--《诗·大雅·荡》", "example": null}, {"def": "葛之覃兮,施于中谷。--《诗·王风·葛覃》", "example": null}, {"def": "又如覃覃(延展的样子)", "example": null}, {"def": "广施", "example": null}, {"def": "覃 〈副〉", "example": null}, {"def": "深入地", "example": null}, {"def": "研精覃思。--《书·孔安国序》", "example": null}, {"def": "扬雄覃思。--《汉书·叙传上》", "example": null}, {"def": "又如覃思(深思,深入而周详地思", "example": null}, {"def": "覃qín", "example": null}, {"def": "⒈姓。", "example": null}, {"def": "覃tán", "example": null}, {"def": "⒈深，长，延伸～思。葛之～兮。", "example": null}, {"def": "覃yǎn 1.锐利。", "example": null}]','chinese-xinhua','0'),
('2101143296783945762','痰','1','tán','疒','13',NULL,'[{"def": "痰〈名〉", "example": null}, {"def": "呼吸道分泌而由口、鼻腔排出的粘液", "example": null}, {"def": "痰tán气管或支气管粘膜分泌的粘稠液体～液。禁止随地吐～。", "example": null}]','chinese-xinhua','0'),
('2101143296783945763','锬','1','tán','钅','13',NULL,'[{"def": "锬", "example": null}, {"def": "长矛", "example": null}, {"def": "锬,长矛也。--《说文》", "example": null}, {"def": "锬tán长矛。", "example": null}, {"def": "锬yǎn 1.锋利。", "example": null}]','chinese-xinhua','0'),
('2101143296783945764','谭','1','tán','讠','14',NULL,'[{"def": "谭", "example": null}, {"def": "(形声。从言,覃声。本义同谈”,说)", "example": null}, {"def": "同本义", "example": null}, {"def": "夫子何不谭我于王。--《庄子·则阳》", "example": null}, {"def": "又如谭笑(谈笑);谭艺(谈论文学艺术);谭说(议论;谈论);谭吐(说话时的措词和态度);谭助(谈资);谭言微中(说话隐微曲折而切中事理)", "example": null}, {"def": "绵延相及", "example": null}, {"def": "不称而祀谭,次祖。犯诅渝盟,伤言。--《管子》", "example": null}, {"def": "谭", "example": null}, {"def": "宏大,广大", "example": null}, {"def": "富恭有本能图,修业居久而谭。--《大戴礼记》。王聘珍解诂《广韵》‘谭,大也。’业安于久而自大也。”", "example": null}, {"def": "谭", "example": null}, {"def": "同谈”。言论", "example": null}, {"def": "此老生之常", "example": null}, {"def": "谭tán", "example": null}, {"def": "⒈同\\"谈\\"老生常～。", "example": null}, {"def": "⒉周代诸侯国名，在今山东省济南市东。", "example": null}]','chinese-xinhua','0'),
