('2101143296783945797','摊','1','tān','扌','13',NULL,'[{"def": "摊〈动〉", "example": null}, {"def": "(形声。从手,难声。本义平铺)", "example": null}, {"def": "同本义", "example": null}, {"def": "摊派", "example": null}, {"def": "分摊(分担)", "example": null}, {"def": "把糊状食物倒在锅中使成为薄片", "example": null}, {"def": "摊 〈名〉", "example": null}, {"def": "摊子", "example": null}, {"def": "古代", "example": null}, {"def": "摊（攤）tān", "example": null}, {"def": "⒈展开，摆开～开。把意见～出来。", "example": null}, {"def": "⒉将糊状物放在热锅里铺成薄片煎熟～饼。～鸡蛋。", "example": null}, {"def": "⒊分派，分担～派。分～。", "example": null}, {"def": "⒋路旁或街旁摆的售货处书～。地～子。菜～儿。水果～。", "example": null}, {"def": "⒌凝集成一片一～水。一～稀泥。", "example": null}, {"def": "⒍遇到，碰上他～上了好事。", "example": null}]','chinese-xinhua','0'),
('2101143296783945798','滩','1','tān','氵','13',NULL,'[{"def": "滩〈名〉", "example": null}, {"def": "(形声。从水,难声。本义河道中水浅流急多沙石的地方)", "example": null}, {"def": "同本义", "example": null}, {"def": "却放轻舟下急滩。--《唐崔道融溪夜诗》", "example": null}, {"def": "滩,水滩。--《广韵·平声寒韵》", "example": null}, {"def": "按,滩濑”的滩”是后起字,是湍”的音转。又如滩燀(水中沙滩);滩碛(浅水下的沙石滩);滩声,滩响(水激滩石发出的声音)", "example": null}, {"def": "滩头。指江、河、湖、海边水涨淹没、水退显露的淤积平地", "example": null}, {"def": "云低岸花掩,水涨滩草没。--唐·岑参《江上阻风雨》", "example": null}, {"def": "惊起一滩鸥鹭。--宋·李清照《如梦令》", "example": null}, {"def": "等级", "example": null}, {"def": "这种奴隶叫作三滩娃子”。滩是等级的意思。管家娃子为头滩,普通娃子为", "example": null}, {"def": "滩（灘）tān", "example": null}, {"def": "⒈江、河或海边泥沙淤积的平地。也指水中的沙洲河～。～。沙～。", "example": null}, {"def": "⒉水浅、多石、流急的地方险～。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
