('2101143296783945807','瑭','1','tánɡ','王','14',NULL,'[{"def": "瑭〈名〉", "example": null}, {"def": "一种玉", "example": null}, {"def": "瑭碧坚忍之类,犹可刻镂,以成器用。--《淮南子》。高诱注唐碧,石似玉。唐与瑭通。”", "example": null}, {"def": "瑭táng〈古〉指一种玉。", "example": null}]','chinese-xinhua','0'),
('2101143296783945808','膛','1','tánɡ','月','15',NULL,'[{"def": "膛〈名〉", "example": null}, {"def": "(形声。从肉,堂声。本义胸腔)", "example": null}, {"def": "同本义", "example": null}, {"def": "休便要斩首开膛。--纪君祥《赵氏孤儿》", "example": null}, {"def": "又如开膛(剖开胸腔)", "example": null}, {"def": "器物中空的部分", "example": null}, {"def": "膛音,膛音儿", "example": null}, {"def": "这老人虽已年过半百,但讲话膛音很大,底气十足", "example": null}, {"def": "膛子", "example": null}, {"def": "膛táng", "example": null}, {"def": "⒈胸腔，体腔胸～。开～破肚。", "example": null}, {"def": "⒉器物的中空部分灶～。炮～。", "example": null}]','chinese-xinhua','0'),
('2101143296783945809','糖','1','tánɡ','米','16',NULL,'[{"def": "糖〈名〉", "example": null}, {"def": "(形声。从米,唐声。本义食用糖及糖制食品的统称)", "example": null}, {"def": "食糖。古代以麦作饴,即麦芽糖◇多用甘蔗、甜菜等制糖", "example": null}, {"def": "糖,饴也。--《广韵》", "example": null}, {"def": "更添糖,拼折本,供他几碗。--宋·史浩《粉蝶儿·咏圆子》", "example": null}, {"def": "又如红糖;白糖;冰糖;糖餵(一种甜饼);糖霜(细白沙糖);糖馈(一种甜饼。也作馈)", "example": null}, {"def": "糖果;糖块", "example": null}, {"def": "糖（", "example": null}, {"def": "⒊醣）táng", "example": null}, {"def": "⒈用甘蔗、甜菜或米麦等提制出来的甜东西白～§～。麦芽～。", "example": null}, {"def": "⒉用糖和其它食物制成的食品～食。～果。花生～。", "example": null}, {"def": "⒊碳水化合物。", "example": null}]','chinese-xinhua','0'),
('2101143296783945810','螗','1','tánɡ','虫','16',NULL,'[{"def": "螗〈名〉", "example": null}, {"def": "一种形体较小的蝉,背表绿色,头有花冠,喜鸣,声清亮", "example": null}, {"def": "螳螂", "example": null}, {"def": "锋蝟斧螗。--柳宗元《平淮夷雅》。潘纬注螗,虫也。《后汉史》作螳。”", "example": null}, {"def": "螗táng蝉的一类，又叫\\"螗蜩\\"。背青绿色，鸣声清亮。", "example": null}]','chinese-xinhua','0'),
