('2101143296783945817','镗','1','tánɡ','钅','16',NULL,'[{"def": "镗〈象〉", "example": null}, {"def": "钟鼓的声音或敲锣的声音", "example": null}, {"def": "镗,钟鼓之声。从金,堂声。--《说文》", "example": null}, {"def": "击鼓其镗。--《诗·邶风·击鼓》", "example": null}, {"def": "又如镗韔(钟鼓声);镗镗(钟鼓声)", "example": null}, {"def": "镗 〈名〉", "example": null}, {"def": "加工零件内孔的一种方法", "example": null}, {"def": "镗 〈动〉", "example": null}, {"def": "用镗孔刀内旋切", "example": null}, {"def": "镗tāng", "example": null}, {"def": "⒈像声词。打钟鼓或敲锣的声音。", "example": null}, {"def": "⒉乐器名。一种小锣，称\\"～儿\\"或\\"小～儿\\"。", "example": null}, {"def": "镗táng同\\"搪\\"。用泥土、涂料等抹涂。", "example": null}]','chinese-xinhua','0'),
('2101143296783945818','饧','1','tánɡ','饣','6',NULL,'[{"def": "饧", "example": null}, {"def": "用麦芽或谷芽熬成的饴糖", "example": null}, {"def": "泼火雨初晴。草色青青。傍檐垂柳卖春饧。--宋·李彭老《浪淘沙》", "example": null}, {"def": "湖鱼香胜肉,官酒重于饧。--唐·刘禹锡《历阳书事》", "example": null}, {"def": "又如饧糟(熬麦芽糖剩下的渣子);饧饼(一种糖饼);饧粥(甜粥);饧蜜(糖蜜);饧糖(麦芽糖);饧桃(甜桃)", "example": null}, {"def": "饧", "example": null}, {"def": "糖块、面剂子等变软", "example": null}, {"def": "形容眼色朦胧", "example": null}, {"def": "八戒饧眼偷看,你道他怎生打扮。--《西游记》", "example": null}, {"def": "只觉口齿缠绵,眉眼愈加饧涩,忙伏侍他睡下。--《红楼梦》", "example": null}, {"def": "又如饧涩(精神涣散,眼色朦胧);饧眼(脒着眼睛,朦胧而视)", "example": null}, {"def": "饧（餳）xíng", "example": null}, {"def": "⒈麦芽或谷芽等熬成的糖。", "example": null}, {"def": "⒉糖块或面剂子等变软糖～了。面团～了。", "example": null}, {"def": "⒊精神不振，眼光朦胧两眼发～。", "example": null}]','chinese-xinhua','0'),
