('2101143296783945823','唐','1','tánɡ','口','10',NULL,'[{"def": "唐〈形〉", "example": null}, {"def": "(形声。小篆作字形。从口,庚声。本义大话)", "example": null}, {"def": "唐,大言也。--《说文》", "example": null}, {"def": "荒唐之言。--《庄子·天下》", "example": null}, {"def": "唐之为言荡荡也。--王充《论衡》", "example": null}, {"def": "广大", "example": null}, {"def": "平原唐其坛曼兮。--扬雄《甘泉赋》", "example": null}, {"def": "又如唐唐(广大;浩荡);唐皇(气势宏伟盛大)", "example": null}, {"def": "在温室中生长的,人工培育的", "example": null}, {"def": "空;徒然", "example": null}, {"def": "唐 〈名〉", "example": null}, {"def": "朝代名。唐朝", "example": null}, {"def": "唐人尚未盛为之。--宋·沈括《梦溪笔谈", "example": null}, {"def": "唐táng", "example": null}, {"def": "⒈夸大，虚夸～大无验。荒～可笑。", "example": null}, {"def": "⒉空，徒然～捐（白费）。", "example": null}, {"def": "⒊传说中虞舜之前的朝代，著名的君主是尧。", "example": null}, {"def": "⒋周代诸侯国名，后改名叫\\"晋\\"。", "example": null}, {"def": "⒌朝代名", "example": null}, {"def": "①唐朝，公元618-907年。第一代君主是李渊。", "example": null}, {"def": "②五代之一，又称\\"后唐\\"，公元923-936年。第一代君主是李存勖。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
('2101143296783945824','堂','1','tánɡ','土','11',NULL,'[{"def": "堂〈名〉", "example": null}, {"def": "(形声。从土,尚声。尚”有高”义。本义殿堂。高于一般房屋,用于祭献神灵、祈求丰年)", "example": null}, {"def": "同本义", "example": null}, {"def": "堂,殿也。--《说文》。段注古曰堂,汉以后曰殿。古上下皆称堂,汉上下皆称殿。至唐以后,人臣无有称殿者矣。”", "example": null}, {"def": "殿,堂之高大者也。--《说文古本考》", "example": null}, {"def": "立于西堂。--《书·顾命》", "example": null}, {"def": "吾见封之若堂者矣。--礼记·檀弓》。注堂形四方而高。”", "example": null}, {"def": "王坐于堂上。--《孟子·梁惠王上》", "example": null}, {"def": "燕坐于华堂之上。--明·刘基《诚意伯刘文成公文集》", "example": null}, {"def": "观其坐高堂。--明·刘基《卖柑者言》", "example": null}, {"def": "华", "example": null}, {"def": "堂táng", "example": null}, {"def": "⒈〈古〉宫室。前为～，后为室。", "example": null}, {"def": "⒉正屋，高大宽敞的房子～屋。殿～。课～。礼～。会～。纪念～。", "example": null}, {"def": "⒊特指内室，因而以此尊称母亲令～（敬称别人的母亲）。", "example": null}, {"def": "⒋同祖的亲属～叔。～姐。～姨。", "example": null}, {"def": "⒌旧时官吏办政事的地方，又特指审案的地方公～。政事～。过～听审。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "①盛大的样子～ ～之阵。～～正正。", "example": null}, {"def": "②容貌俊伟出众的样子相貌～ ～。", "example": null}, {"def": "③无顾忌的样子～ ～自来去。", "example": null}]','chinese-xinhua','0'),
