('2101143296783945836','趟','1','tànɡ','走','15',NULL,'[{"def": "趟〈动〉", "example": null}, {"def": "从浅水中走过", "example": null}, {"def": "翻土", "example": null}, {"def": "踩,踏", "example": null}, {"def": "大洋马一纵一纵的趟起漫天尘土。--徐光耀《平原烈火》", "example": null}, {"def": "哪一辈子欠人的罪孽啊,都让我们李家人给趟上了。--《庚子风云》", "example": null}, {"def": "趟 〈量〉", "example": null}, {"def": "(形声。从走,尚声。本义次,回)", "example": null}, {"def": "遍,次。专指走动的次数", "example": null}, {"def": "我看你白跑这一趟。--《白雪遗音》", "example": null}, {"def": "泛指其他动作的次数", "example": null}, {"def": "行;条", "example": null}, {"def": "趟 〈名〉", "example": null}, {"def": "步子,步伐", "example": null}, {"def": "趟（蹚）tāng", "example": null}, {"def": "⒈从有水、草的地方走过去～着水过去。", "example": null}, {"def": "⒉用犁、锄等翻土，将草除掉～地。", "example": null}, {"def": "趟tàng", "example": null}, {"def": "⒈量词", "example": null}, {"def": "①次，回这～。来了三～。", "example": null}, {"def": "②行，成行的室内有四～沙发。请把这件衣服缝一～。", "example": null}, {"def": "趟zhēng 1.跳跃;跳动。", "example": null}]','chinese-xinhua','0'),
('2101143296783945837','帑','1','tǎnɡ','巾','8',NULL,'[{"def": "帑〈名〉", "example": null}, {"def": "古时收藏钱财的府库", "example": null}, {"def": "帑,金币所藏也。从巾,奴声。--《说文》", "example": null}, {"def": "库藏曰帑。--《通俗文》", "example": null}, {"def": "人食不足,而帑藏殷积。--《后汉书》", "example": null}, {"def": "又如帑实(府库中的财物);帑廪(国库与粮仓);帑弜(国家储藏金币和粮食的府库);帑藏(国库);帑储(府库储积);帑簿(国库登记财物的帐簿);帑银(国库中的银子)", "example": null}, {"def": "指国家库藏的金帛", "example": null}, {"def": "虚费府帑。--《汉书·匈奴传》", "example": null}, {"def": "又如国帑(国家的公款);帑金(钱币。多指国库所藏)", "example": null}, {"def": "裹金帛的囊", "example": null}, {"def": "行帑无寸金,卫兵不宿饱。--《旧唐书》", "example": null}, {"def": "帑 〈动〉", "example": null}, {"def": "藏匿", "example": null}, {"def": "帑tǎng", "example": null}, {"def": "⒈国库，国库里的钱财国～。公～。", "example": null}, {"def": "⒉〈古〉通\\"孥\\"。", "example": null}, {"def": "帑nú 1.通\\"孥\\"。儿女的通称。 2.用以指妻子和儿女。 3.通\\"孥\\"。俘虏;奴隶。 4.通\\"孥\\"。鸟尾。 5.雌。 6.通\\"弩\\"。参见\\"帑抹\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296788140032','倘','1','tǎnɡ','亻','10',NULL,'[{"def": "倘佯", "example": null}, {"def": "tang", "example": null}, {"def": "倘〈连〉", "example": null}, {"def": "表示假设。同黨”、儻”", "example": null}, {"def": "倘三年犹不得。--清·候方域《壮悔堂文集》", "example": null}, {"def": "倘复请之。--清·方苞《狱中杂记》", "example": null}, {"def": "汝倘有灵。--清·袁枚《祭妹文》", "example": null}, {"def": "倘国人皆…奋斗。--孙文 《黄花冈七十二烈士事略·序》", "example": null}, {"def": "又如倘若;倘或;倘或间;倘使;倘如;倘然(假如)", "example": null}, {"def": "相当于或许”、大概”", "example": null}, {"def": "倘 cháng又见tǎng。", "example": null}, {"def": "【倘佯】见【徜徉】。", "example": null}, {"def": "倘（儻）tǎng", "example": null}, {"def": "⒈如果，假使～若勤奋，必有成就。", "example": null}, {"def": "倘cháng", "example": null}]','chinese-xinhua','0'),
('2101143296788140033','淌','1','tǎnɡ','氵','11',NULL,'[{"def": "淌〈动〉", "example": null}, {"def": "(形声。从水,尚声。本义流下)", "example": null}, {"def": "同本义", "example": null}, {"def": "打大前日,河里就淌凌。--《老残游记》", "example": null}, {"def": "又如淌凌(流淌冰块);他脸上淌着汗水;淌眼泪;淌眼抹泪(一边哭泣,一边擦眼泪);伤口淌血", "example": null}, {"def": "迅速流动", "example": null}, {"def": "用同趟”,在浅水里走", "example": null}, {"def": "他咬上了牙,淌着水不管高低深浅的跑起来。--老舍《骆驼祥子》", "example": null}, {"def": "淌tǎng流～汗。眼泪直～。", "example": null}, {"def": "淌chàng 1.大波。", "example": null}, {"def": "淌chǎng 1.见\\"淌游\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296788140034','傥','1','tǎnɡ','亻','12',NULL,'[{"def": "傥〈形〉", "example": null}, {"def": "(形声。从人,党声。本义 洒脱不拘,不拘于俗)", "example": null}, {"def": "同本义", "example": null}, {"def": "赞陈汤傥荡。--《汉书·傅常郑甘陈段传》。注无行检也。”", "example": null}, {"def": "貌若傥荡不备。--《汉书·史丹传》", "example": null}, {"def": "又如倜傥(洒脱;不拘束)", "example": null}, {"def": "怅然自失,恍惚", "example": null}, {"def": "文候傥然,终日不言。--《庄子·田子方》", "example": null}, {"def": "又如傥然(失志的样子);傥莽(怅然自失)", "example": null}, {"def": "正直", "example": null}, {"def": "广大", "example": null}, {"def": "安闲自得", "example": null}, {"def": "傥（儻）tǎng", "example": null}, {"def": "⒈同上\\"倘\\"。", "example": null}, {"def": "⒉", "example": null}, {"def": "傥tàng 1.侥幸;偶然。", "example": null}]','chinese-xinhua','0'),
('2101143296788140035','躺','1','tǎnɡ','身','15',NULL,'[{"def": "躺〈动〉", "example": null}, {"def": "(形声。从身,尚声。本义平卧)", "example": null}, {"def": "同本义", "example": null}, {"def": "这无耻的畜生想必是躺尸了。--清·忧患余生《邻女语》", "example": null}, {"def": "又如躺在床上;躺着歇歇;躺尸(詈词。指睡觉);躺桥(方言。睡觉)", "example": null}, {"def": "停止劳动或努力", "example": null}, {"def": "引伸指物体平放或倒伏在地", "example": null}, {"def": "死的婉辞", "example": null}, {"def": "先母躺了下来,还是很热闹的。--《二十年目睹之怪现状》", "example": null}, {"def": "躺tǎng", "example": null}, {"def": "⒈身体横卧让他～一会儿。", "example": null}, {"def": "⒉物体横倒这儿～的什么？", "example": null}]','chinese-xinhua','0'),
