('2101143296788140073','弢','1','tāo','弓','8',NULL,'[{"def": "弢〈名〉", "example": null}, {"def": "(会意。从弓,比,象下垂的装饰物。本义弓袋)", "example": null}, {"def": "同本义", "example": null}, {"def": "弢,弓衣也。--《说文》", "example": null}, {"def": "弢无弓。--《国语·齐语》", "example": null}, {"def": "矢服谓之弢。--《小尔雅》", "example": null}, {"def": "吾伏弢呕血,鼓音不衰。--《左传》", "example": null}, {"def": "囊;套子", "example": null}, {"def": "乃内旌于弢中。--《左传·成公十六年》", "example": null}, {"def": "韬略,用兵的谋略", "example": null}, {"def": "从说之则以金版六弢。--《庄子·徐无鬼》", "example": null}, {"def": "《周史六弢》六篇。--《汉书·艺文志》", "example": null}, {"def": "弢 〈动〉", "example": null}, {"def": "通韬”。隐藏", "example": null}, {"def": "弢迹匿光。--陆机《汉高功臣颂》", "example": null}, {"def": "又如弢弓(藏弓入弢);弢光(弢迹匿光的省语。指隐藏光采才华,不表露于外);弢", "example": null}, {"def": "弢tāo 1.弓袋。 2.泛指袋子﹑套子。 3.引申为用袋子套起来。 4.束缚，禁锢。 5.同\\"韬\\"。隐藏，收敛。 6.同\\"韬\\"。韬略。古有兵书《六弢》。 7.铠甲。", "example": null}]','chinese-xinhua','0'),
('2101143296788140074','涛','1','tāo','氵','10',NULL,'[{"def": "涛〈名〉", "example": null}, {"def": "(形声。从水,寿声。本义大波)", "example": null}, {"def": "同本义", "example": null}, {"def": "涛,大波也。--《说文新附》", "example": null}, {"def": "扬波涛于碣石。--《后汉书·班彪传上》", "example": null}, {"def": "何必湘渊与涛濑?--《汉书·扬雄传上》", "example": null}, {"def": "水泫泇而涌涛。--《文选·张衡·思玄赋》", "example": null}, {"def": "烟涛微茫信难求。--唐·李白《梦游天姥吟留别》", "example": null}, {"def": "惊涛拍岸。--宋·苏轼《念奴娇·赤壁怀古》", "example": null}, {"def": "怒涛排壑。--孙文《黄花冈七十二烈士事略·序》", "example": null}, {"def": "又如涛水(波涛汹涌的大水);涛雪(波涛激汤,水花如雪);涛雷(波涛汹涌,声大如雷);涛波(大波,波涛)", "example": null}, {"def": "像波涛一样的声音", "example": null}, {"def": "阴壑寒生万树涛。--明·王世贞", "example": null}, {"def": "涛（濤）tāo", "example": null}, {"def": "⒈大波浪波～。", "example": null}, {"def": "⒉像波涛的声音松～。", "example": null}, {"def": "涛cháo 1.潮汐。", "example": null}, {"def": "涛dào 1.覆盖。", "example": null}]','chinese-xinhua','0'),
('2101143296788140075','绦','1','tāo','纟','10',NULL,'[{"def": "绦〈名〉", "example": null}, {"def": "(形声。从糸,条声。或从糸,攸声。本义用丝编织的带子或绳子) 同本义", "example": null}, {"def": "绦旋光堪摘,轩楹势可呼。--杜甫《画鹰》", "example": null}, {"def": "又如玉绦环;彩绦", "example": null}, {"def": "绦（縧、絛、縚）tāo", "example": null}, {"def": "⒈用丝线编织成的带子或绳子，用以装饰衣物～子。～带。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296788140076','掏','1','tāo','扌','11',NULL,'[{"def": "掏〈动〉", "example": null}, {"def": "(形声。从手,匋声。本义挖取)", "example": null}, {"def": "同搯”。挖取", "example": null}, {"def": "探手取物", "example": null}, {"def": "掏（搯）tāo", "example": null}, {"def": "⒈挖～个洞。", "example": null}, {"def": "⒉伸进去取～炉灰。把包里的糖果～出来。", "example": null}]','chinese-xinhua','0'),
