('2101143296796528647','替','1','tì','曰','12',NULL,'[{"def": "替〈动〉", "example": null}, {"def": "(形声。本作竝”。从竝,白声。竝,二人并立。本义废弃)", "example": null}, {"def": "同本义", "example": null}, {"def": "竝,废也。--《说文》。俗字作替。", "example": null}, {"def": "不替孟明。--《左传·僖公三十二年》", "example": null}, {"def": "勿替引之。--《诗·小雅·楚茨》", "example": null}, {"def": "胡不自替。--《诗·大雅·召》", "example": null}, {"def": "唯独居思念前世之崇替。--《国语·楚语》", "example": null}, {"def": "謇朝谇而夕替。--《离骚》", "example": null}, {"def": "又如久替(长期废弃)", "example": null}, {"def": "停止", "example": null}, {"def": "荐可而替不。--《国语·晋语》。注去也。”", "example": null}, {"def": "又如替手(停手)", "example": null}, {"def": "消亡,泯灭", "example": null}, {"def": "君之冢嗣其替乎。--《国语·晋语》。注灭也。”", "example": null}, {"def": "又如替罪(诛灭有罪者)", "example": null}, {"def": "衰微;衰落", "example": null}, {"def": "替tì", "example": null}, {"def": "⒈代，代理～代。～工。～身。", "example": null}, {"def": "⒉为，给～病人服务。～他人作想。", "example": null}, {"def": "⒊衰落，衰弱兴～。", "example": null}, {"def": "⒋废弃常度未～（度法度）。", "example": null}]','chinese-xinhua','0'),
('2101143296796528648','裼','1','tì','衤','13',NULL,'[{"def": "裼〈名〉ti", "example": null}, {"def": "婴儿的包被", "example": null}, {"def": "乃生女子,载寝之地,载衣之裼。--《诗·小雅·斯干》。毛传裼,褓也。”", "example": null}, {"def": "另见襸", "example": null}, {"def": "裼  xi", "example": null}, {"def": "脱去衣服露出上身", "example": null}, {"def": "裼,袒也。从衣,易声。--《说文》", "example": null}, {"def": "裼,脱衣见体也。--《玉篇》", "example": null}, {"def": "襢裼暴虎。--《诗·郑风·大叔于田》", "example": null}, {"def": "襢裼,肉袒。--《尔雅》", "example": null}, {"def": "徒裼以趋敌。--《史记·张仪传》", "example": null}, {"def": "闻战,顿足徒裼。--《战国策·初见秦》", "example": null}, {"def": "曹君袒裼而观之。--《韩非子·十过》", "example": null}, {"def": "又如袒裼(袒、裼都指脱去衣服,露出上身,但袒还指脱", "example": null}, {"def": "裼tì", "example": null}, {"def": "⒈婴儿的包被。", "example": null}, {"def": "裼xī", "example": null}, {"def": "⒈脱去或敞开上衣，露出部分身体袒～。", "example": null}]','chinese-xinhua','0'),
