('2101143296804917276','苕','1','tiáo','艹','8',NULL,'[{"def": "如红苕”", "example": null}, {"def": "苕〈名〉tiao", "example": null}, {"def": "(形声。从苃,召声。本义陵苕。亦名凌霄”、紫葳”。蔓生草”)", "example": null}, {"def": "同本义", "example": null}, {"def": "苕,苕草也。--《说文》", "example": null}, {"def": "邛有旨苕。--《诗·陈风·东门之枌》", "example": null}, {"def": "苕之华。--《诗·小雅·苕之华》", "example": null}, {"def": "紫葳科落叶木质藤本,借气根攀附在其他物上。花冠漏斗状钟形,大而鲜艳,橘红色,栽培供观赏,花入药,破血去瘀。", "example": null}, {"def": "如苕华(花名。即凌霄花);苕荣(陵苕花。亦喻容貌之美);苕颖(草花和禾穗。亦泛指植物的花、穗及其茎)", "example": null}, {"def": "苕菜,即紫云英", "example": null}, {"def": "苕tiáo", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉芦苇的花苇～。", "example": null}, {"def": "⒊〈古〉指凌霄花，也叫\\"紫葳\\"。落叶藤本。花橙黄色，供观赏，又可供药用。", "example": null}, {"def": "⒋", "example": null}, {"def": "苕sháo", "example": null}, {"def": "⒈〈方〉红苕，即甘薯。", "example": null}]','chinese-xinhua','0'),
('2101143296804917277','眺','1','tiào','目','11',NULL,'[{"def": "杋〈动〉", "example": null}, {"def": "(形声。从月,兆声。本义古称夏历月底月亮在西方出现) 同本义", "example": null}, {"def": "晦而月见西方谓之杋。--《说文》", "example": null}, {"def": "三月晦杋鲁卫分。--《汉书·五行志》", "example": null}, {"def": "日杋月蚀,昼冥宵光。--《汉书·张敞传》。", "example": null}, {"def": "又如杋杊(旧历月初月见于东方和月末月见于西方)", "example": null}, {"def": "杋 〈形〉", "example": null}, {"def": "快速;行疾", "example": null}, {"def": "杋,疾也。--《广雅·释诂》", "example": null}, {"def": "又如杋侧(日月疾缓合度。比喻行为规范)", "example": null}, {"def": "眺tiào", "example": null}, {"def": "⒈远看～望。", "example": null}, {"def": "⒉斜视。", "example": null}]','chinese-xinhua','0'),
('2101143296804917278','粜','1','tiào','米','11',NULL,'[{"def": "粜", "example": null}, {"def": "(会意兼形声。从出,从糶,糶亦声。本义卖出谷物)", "example": null}, {"def": "同本义", "example": null}, {"def": "粜,出谷也。--《说文》", "example": null}, {"def": "物踊腾粜。--《史记·平淮书》", "example": null}, {"def": "贩谷粜千钟。--《史记·货殖传》", "example": null}, {"def": "二月卖新丝,五月粜新谷。--唐·聂夷中《咏田家》", "example": null}, {"def": "泛指出卖", "example": null}, {"def": "想那粜风月的女娘,似饥狼饿狼。--《雍熙乐府》", "example": null}, {"def": "粜（糶）tiào卖出粮食～粮。五月～新谷。", "example": null}]','chinese-xinhua','0'),
('2101143296804917279','跳','1','tiào','足','13',NULL,'[{"def": "跳〈动〉", "example": null}, {"def": "(形声。从足,兆声。本义跃)", "example": null}, {"def": "同本义", "example": null}, {"def": "跳,…一曰跃也。--《说文》", "example": null}, {"def": "特跳此者。--《左传·襄公二十五年》", "example": null}, {"def": "跳往助之。--《列子·汤问》", "example": null}, {"def": "狂生跳掷叫号", "example": null}, {"def": "--清·纪昀《阅微草堂笔记》", "example": null}, {"def": "又如跳蹋(由生气或着急而顿足);跳索(杂技中的一种绳技);跳鳞(跳出水面的鱼);跳踯(上下跳跃)", "example": null}, {"def": "越过障碍", "example": null}, {"def": "如跳墙;跳过篱笆;跳读(跳越章节读书);跳墙蓦圈(指偷盗的行为);跳门限(另换门庭);跳河(越过河;投河)", "example": null}, {"def": "内动;一起一伏地跳", "example": null}, {"def": "如心跳;眼皮跳;跳跃(跳动);跳踉(跳跃;跳动)", "example": null}, {"def": "跳tiào", "example": null}, {"def": "⒈两脚离地蹦、跃～跃。～高。～远。～绳。", "example": null}, {"def": "⒉越过～过去。她读报，～了几段。", "example": null}, {"def": "⒊物体由于弹性突然向上运动皮球～了几下。", "example": null}, {"def": "⒋一起一伏地动眼皮～。脉搏在～。", "example": null}, {"def": "⒌", "example": null}, {"def": "①游泳跳水用的长板。", "example": null}, {"def": "②一端搭在车或船上，一端放在地面的长板，利于人员的上下。〈引〉道路踏上回乡的～板。", "example": null}, {"def": "跳táo 1.逃走，逃亡。", "example": null}, {"def": "跳tiǎo 1.挑战，挑动。 2.挖取。", "example": null}]','chinese-xinhua','0'),
('2101143296804917280','窕','1','tiǎo','穴','11',NULL,'[{"def": "窕〈形〉", "example": null}, {"def": "(形声。从穴,兆声。本义深邃)", "example": null}, {"def": "同本义", "example": null}, {"def": "窕,深肆也。--《说文》", "example": null}, {"def": "充盈大宇而不窕。--《荀子·赋》", "example": null}, {"def": "入小而不偪,处大而不窕。--《淮南子》", "example": null}, {"def": "又如窕邃(幽深的样子);窕窕(幽深的样子)", "example": null}, {"def": "未充满;间隙", "example": null}, {"def": "七者布诸天下而不窕,内诸寻常之室而不塞。--《大戴礼记》", "example": null}, {"def": "细;小", "example": null}, {"def": "夫天子省风以作乐, 小者不窕。--《汉书》", "example": null}, {"def": "虚浮不实", "example": null}, {"def": "语言辨,听之说(悦),不度于义,谓之窕言。--《韩非子》", "example": null}, {"def": "美;美色", "example": null}, {"def": "不至于窕冶。--《荀子·礼论》", "example": null}, {"def": "窕美也。美状为窕。--《方", "example": null}, {"def": "窕tiǎo", "example": null}]','chinese-xinhua','0'),
