('2101143296804917338','仝','1','tónɡ','人','5',NULL,'[{"def": "仝〈形〉", "example": null}, {"def": "同”的古字。相同;一样", "example": null}, {"def": "仝,同古文,出《道书》。--《广韵》", "example": null}, {"def": "仝 tóng", "example": null}, {"def": "⒈通\\"㈠同\\"。", "example": null}, {"def": "⒉姓。", "example": null}]','chinese-xinhua','0'),
('2101143296804917339','同','1','tónɡ','口','6',NULL,'[{"def": "同〈动〉", "example": null}, {"def": "(会意。从冃,从口。冃,重复。本义聚集)", "example": null}, {"def": "同本义", "example": null}, {"def": "同,合会也。--《说文》", "example": null}, {"def": "同重体合类。--《墨子·经上》", "example": null}, {"def": "同人亲也。--《易·杂卦》", "example": null}, {"def": "六曰同衣服。--《周礼·大司徒》", "example": null}, {"def": "又如云同(云彩聚集);同天(共存于人世间);同合(使相一致;融会);同流(诸水合流)", "example": null}, {"def": "相同,一样,共同(侧重于同样,齐一)", "example": null}, {"def": "同事之人,不可不审察也。--《韩非子·说林上》", "example": null}, {"def": "鸟兽不可与同群。--《论语·微子》", "example": null}, {"def": "同予者何人。--宋·周敦颐《爱莲说》", "example": null}, {"def": "同于真耶。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "同于幻耶。", "example": null}, {"def": "又如同心戮力(同心", "example": null}, {"def": "同tóng", "example": null}, {"def": "⒈一样～样。～等。～感。～工～酬。一视～仁。", "example": null}, {"def": "⒉共，一起共～。～学。～甘共苦。", "example": null}, {"def": "⒊和，跟我～你一道走。", "example": null}, {"def": "⒋相似如～。她的面貌～她妈一样。", "example": null}, {"def": "⒌指相同～上。～前。\\"弍\\"～\\"贰\\"。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "①志同道合的人。特指政治理想相同的人。", "example": null}, {"def": "②我国人民之间平等的称呼。", "example": null}, {"def": "⒏", "example": null}, {"def": "①同父母所生的人，即亲的兄弟姐妹。", "example": null}, {"def": "②同一国的人台湾～胞。千万万～胞一条心。", "example": null}, {"def": "⒐", "example": null}, {"def": "①对于别人的遭遇在感情上共鸣深表～情。", "example": null}, {"def": "②对于别人的言行表示赞同我～情他。", "example": null}, {"def": "⒑", "example": null}, {"def": "①同一个时候。", "example": null}, {"def": "②并且，〈表〉进一层这个水库既可抗旱防涝，～时也用于发电。", "example": null}, {"def": "⒒", "example": null}, {"def": "①生物体把摄取到的养料转化成自身细胞的成分并储存能量。", "example": null}, {"def": "②使不同于本身的事物转变成为与本身相同的事物。", "example": null}, {"def": "同（衕）tòng", "example": null}]','chinese-xinhua','0'),
('2101143296804917340','佟','1','tónɡ','亻','7',NULL,'[{"def": "佟〈名〉", "example": null}, {"def": "姓", "example": null}, {"def": "佟,姓也。《北燕录》有辽东佟万,以文章知名。--《广韵》", "example": null}, {"def": "佟tóng姓。", "example": null}]','chinese-xinhua','0'),
('2101143296804917341','彤','1','tónɡ','彡','7',NULL,'[{"def": "彤〈动〉", "example": null}, {"def": "(会意。从丹,从彡。丹,丹砂。彡,毛饰。本义彩色装饰) 同本义", "example": null}, {"def": "彤,丹饰也。--《说文》", "example": null}, {"def": "彤弓一。--《书·文侯之命》", "example": null}, {"def": "诸侯彤弓。--《荀子·大略》。按丹漆也。”", "example": null}, {"def": "又如彤几(朱漆几);彤镂(涂丹漆和雕刻花纹);彤辇(朱漆宫车);彤壶(朱漆漏壶);彤庭(彤宫,彤殿,彤廷『代宫廷。因以朱漆涂饰,故称);彤车(朱漆车);彤弓(朱漆弓);彤矢(", "example": null}, {"def": "朱漆箭);彤闱(朱漆宫门)", "example": null}, {"def": "彤 〈形〉", "example": null}, {"def": "赤色", "example": null}, {"def": "麻冕彤裳。--《书·顾命》", "example": null}, {"def": "贻我彤管。--《诗·邶风·静女》", "example": null}, {"def": "又如彤丹(朱漆);彤芝盖(朱伞);彤彤(通红貌);彤珠(烧红的铁丸)", "example": null}, {"def": "彤 〈", "example": null}, {"def": "彤tóng红色红～ ～的太阳。", "example": null}]','chinese-xinhua','0'),
