('2101143296809111566','统','1','tǒnɡ','纟','9',NULL,'[{"def": "统", "example": null}, {"def": "(形声。从糸,充声。本义丝的头绪)", "example": null}, {"def": "同本义", "example": null}, {"def": "统,纪也。--《说文》", "example": null}, {"def": "茧之性为丝,然非得工女煮以热汤而抽其统纪。--《淮南子·泰族训》", "example": null}, {"def": "又如统绪(头绪)", "example": null}, {"def": "世代相继的系统", "example": null}, {"def": "求其统类。--《荀子·解蔽》", "example": null}, {"def": "又如皇统(世代相传的帝系);道统;传统;统承(继承统绪);统系(系统);统贯(系统;条贯);统嗣(帝统的嗣续关系)", "example": null}, {"def": "纲纪,准则", "example": null}, {"def": "忠信以为质,端悫以为统。--《荀子·臣道》", "example": null}, {"def": "又如体统(体制、格局、规矩等);统纪(纲纪);统类(纲纪和条例)", "example": null}, {"def": "鞋袜等的筒状部分", "example": null}, {"def": "统tǒng", "example": null}, {"def": "⒈丝的头绪抽其～。", "example": null}, {"def": "⒉事物的连续或彼此相连的关系系～。传～。血～。", "example": null}, {"def": "⒊纲要，纲领不知其～。", "example": null}, {"def": "⒋总括，综合，全面地～计。～筹。～理。", "example": null}, {"def": "⒌全，都～共。～ ～（也作通通）合格。", "example": null}, {"def": "⒍主管，率领～管。～辖。～兵百万。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①部分结合成整体，分歧趋于一致全国～一。意见～一。", "example": null}, {"def": "②一致的，单一的～一认识。～一领导。", "example": null}, {"def": "⒐", "example": null}, {"def": "①凭借政权来控制、治理国家或地区。", "example": null}, {"def": "②占绝对优势，支配控制别的事物。", "example": null}]','chinese-xinhua','0'),
('2101143296809111567','捅','1','tǒnɡ','扌','10',NULL,'[{"def": "捅", "example": null}, {"def": "(形声。从手,甬声。本义引;招引)", "example": null}, {"def": "同本义", "example": null}, {"def": "重柔之兵,则噪而恐之,振而捅之,出则击之,不出则回之。--银雀山汉墓竹简《孙膑兵法》", "example": null}, {"def": "用棍、棒、刀或枪等戳刺", "example": null}, {"def": "刺激、触动、挑动", "example": null}, {"def": "用利器戳入致伤", "example": null}, {"def": "泄露,尤其口头上提示", "example": null}, {"def": "捅tǒng", "example": null}, {"def": "⒈扎，戳，刺～破了。～了一刀。", "example": null}, {"def": "⒉触动～马蜂窝（〈喻〉惹祸）。", "example": null}, {"def": "⒊揭露问题～出来了。", "example": null}]','chinese-xinhua','0'),
('2101143296809111568','桶','1','tǒnɡ','木','11',NULL,'[{"def": "桶", "example": null}, {"def": "(形声。从木,甬声。本义量器名)", "example": null}, {"def": "古量器名。方形斛", "example": null}, {"def": "桶,木方,受六升。--《说文》。段玉裁注疑当作方斛,受六升。”", "example": null}, {"def": "方斛谓之桶。--《广雅》", "example": null}, {"def": "角斗桶。--《吕氏春秋·仲春》", "example": null}, {"def": "平斗桶。--《史记·商君书》", "example": null}, {"def": "盛水或其他东西的圆柱形容器,有提梁", "example": null}, {"def": "供做皮衣用的兽毛皮的成件。因多缀成圆桶状,故称", "example": null}, {"def": "桶", "example": null}, {"def": "一桶的量", "example": null}, {"def": "桶tǒng", "example": null}, {"def": "⒈盛东西的器具，多较深，圆筒形铁～。水～。汽油～。", "example": null}, {"def": "⒉", "example": null}, {"def": "桶yǒng 1.古代量器名。方形的斛，受六斗。", "example": null}]','chinese-xinhua','0'),
('2101143296809111569','筒','1','tǒnɡ','竹','12',NULL,'[{"def": "筒", "example": null}, {"def": "(形声。从竹,同声。本义竹筒,粗大的竹管)", "example": null}, {"def": "同本义", "example": null}, {"def": "筒,通箫也。--《说文》", "example": null}, {"def": "筒,竹管也。--《三苍》", "example": null}, {"def": "筩,断竹也。--《说文》", "example": null}, {"def": "教吏为缿筩。--《汉书·李广汉传》。注竹筩也,如今官受密事筩也。”芽", "example": null}, {"def": "伶伦制十二筩,以听凤鸣。--《汉书·律历志》", "example": null}, {"def": "又如筒箭(放在竹筒里发射的箭矢);筒竹(竹筒);筒炙(古时利用竹筒熏烤的一种烹调方法。也叫黄炙”)", "example": null}, {"def": "捕鱼的器具", "example": null}, {"def": "泛指管筒状器物", "example": null}, {"def": "以筒水灌之。--《聊斋志异·促织》", "example": null}, {"def": "又如", "example": null}, {"def": "筒（筩）tǒng", "example": null}, {"def": "⒈粗大的竹管。", "example": null}, {"def": "⒉较粗的管形器物笔～。邮～。烟～。火箭～。", "example": null}, {"def": "⒊衣服、靴、袜等上面像筒的部分袖～。靴～。袜～儿。长～裤。", "example": null}, {"def": "筒dòng 1.洞箫。", "example": null}]','chinese-xinhua','0'),
