('2101143296830083089','凸','1','tū','凵','5',NULL,'[{"def": "凸〈形〉", "example": null}, {"def": "高出", "example": null}, {"def": "凸凹(高低不平);凸杯(满杯);凸岸;凸镜;凸透镜", "example": null}, {"def": "凸〈动〉", "example": null}, {"def": "使突出于周围表面或范围之外", "example": null}, {"def": "伸出;突出", "example": null}, {"def": "凸tū周围低，中间高。跟\\"凹\\"相对～形。这是～透镜。", "example": null}]','chinese-xinhua','0'),
('2101143296830083090','秃','1','tū','禾','7',NULL,'[{"def": "秃〈形〉", "example": null}, {"def": "(象形。从人,上象禾粟之形。本义头顶无发)", "example": null}, {"def": "同本义", "example": null}, {"def": "秃,无发也。--《说文》", "example": null}, {"def": "秃者不免。--《礼记·问丧》", "example": null}, {"def": "秃者不髽。--《礼记·丧服四制》", "example": null}, {"def": "齐人谓无发为秃揭。--《礼记·明堂位》注", "example": null}, {"def": "秃翁。--《后汉书·匈奴传》。注即乃翁也。”", "example": null}, {"def": "齿危发秃。--清·袁枚《祭妹文》", "example": null}, {"def": "又如秃厮(光头家伙);秃科子(秃脑瓜);秃驴(光头驴。骂和尚的话);秃颅(秃头);秃人(秃发的人);秃儿(犹秃奴);秃发(头发脱落)", "example": null}, {"def": "山无草木", "example": null}, {"def": "不戴帽、不穿鞋", "example": null}, {"def": "秃tū", "example": null}, {"def": "⒈无头发～顶。", "example": null}, {"def": "⒉鸟兽（头或尾）无毛～头鸡。～尾巴狗。", "example": null}, {"def": "⒊山无树木，树无枝叶～山。～树。", "example": null}, {"def": "⒋物体失去尖端～笔。", "example": null}, {"def": "⒌不圆满，不周全此文写得太～。", "example": null}]','chinese-xinhua','0'),
('2101143296834277376','突','1','tū','穴','9',NULL,'[{"def": "突〈动〉", "example": null}, {"def": "(会意。从穴,从犬。本义犬从洞穴中突然窜出)", "example": null}, {"def": "狗从穴中突然而出", "example": null}, {"def": "突,犬从穴中暂出也。--《说文》。徐锴系传犬匿于穴中伺人,人不意之,突然而出也。”", "example": null}, {"def": "是犹以韟而御騛突。--《汉书·刑法志》。注恶马也。”", "example": null}, {"def": "急速地向前或向外冲", "example": null}, {"def": "铁骑突出刀枪鸣。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "提九突奔客。--明·魏禧《大铁椎传》", "example": null}, {"def": "驰突巷战。--明·顾炎武《复庵记》", "example": null}, {"def": "突骑。--《后汉书·光武纪》。注言能冲突军陈。”", "example": null}, {"def": "又如突轶(袭击;冲击);突战(伏兵袭击的战术);突然", "example": null}, {"def": "突tū", "example": null}, {"def": "⒈鼓起，凸出来～凸。峰峦～起。", "example": null}, {"def": "⒉忽然～然。风云～变。～如其来。", "example": null}, {"def": "⒊冲破，超出～围。～破世界纪录。", "example": null}, {"def": "⒋烟囱烟～。曲～徙薪（把烟囱改弯，将柴堆搬开，避免火灾。〈喻〉防患于未然）。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
