('2101143296834277407','蛻','1','tuì','','9',NULL,'[{"def": "蛻tuì", "example": null}, {"def": "⒈蛇和昆虫等脱皮～皮。", "example": null}, {"def": "⒉蛇和昆虫等脱下的皮蛇～。蝉～。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296834277408','蜕','1','tuì','虫','13',NULL,'[{"def": "蜕〈动〉", "example": null}, {"def": "(形声。从虫,兑声。本义蝉、蛇之类脱皮去壳)", "example": null}, {"def": "蝉、蛇等脱皮。亦谓鸟换羽", "example": null}, {"def": "蜕,蝉蛇所解皮也。--《说文》", "example": null}, {"def": "蝉蜕于浊秽。--《史记·屈原贾生列传》", "example": null}, {"def": "又如蜕蝉(蝉脱壳)", "example": null}, {"def": "道家认为修道者死后留下形骸,魂魄散去成仙,称为尸解,也叫蜕”◇因以蜕为死的讳称", "example": null}, {"def": "解脱成仙);蜕衣(谓肉体仙去留下衣服);蜕壳(指遗骸)", "example": null}, {"def": "变化;变质", "example": null}, {"def": "脱去,除掉", "example": null}, {"def": "蜕tuì", "example": null}, {"def": "①蝉﹑蛇等脱皮。", "example": null}, {"def": "②谓鸟换毛(脱毛重长)。", "example": null}, {"def": "③蝉﹑蛇等脱下的皮壳。", "example": null}, {"def": "④指兽类的皮。", "example": null}, {"def": "⑤脱去;除掉。", "example": null}, {"def": "⑥变化;变质。", "example": null}, {"def": "⑦道家﹑佛家谓人死为解脱。", "example": null}, {"def": "⑧借指尸体。", "example": null}, {"def": "蜕yuè 1.见\\"蚴蜕\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296834277409','褪','1','tuì','衤','14',NULL,'[{"def": "褪〈动〉tui", "example": null}, {"def": "减色;消退", "example": null}, {"def": "退,后退", "example": null}, {"def": "褪色", "example": null}, {"def": "这幅油画珍藏40年没褪色", "example": null}, {"def": "褪〈动〉tun", "example": null}, {"def": "(形声。从衣,退声。这个后起字,解作卸衣、花谢、色减、退却。本义卸衣)", "example": null}, {"def": "同本义", "example": null}, {"def": "褪,卸衣也。--《韵会》", "example": null}, {"def": "那更梅花褪。--赵长卿《点绛唇》", "example": null}, {"def": "又如褪落(卸脱)", "example": null}, {"def": "消除", "example": null}, {"def": "春事阑珊,山村未褪寒。--陆游《蔬饭》", "example": null}, {"def": "凋萎", "example": null}, {"def": "梅子褪花时,直与黄梅接。--宋·辛弃", "example": null}, {"def": "褪tuì", "example": null}, {"def": "⒈", "example": null}, {"def": "褪tùn", "example": null}, {"def": "⒈脱去，脱下来把袖套～下来。狗挣～了套。〈引〉向内移动并藏起来将手～在袖筒里。袖内～有一封信。", "example": null}]','chinese-xinhua','0'),
('2101143296834277410','腿','1','tuǐ','月','13',NULL,'[{"def": "腿", "example": null}, {"def": "胫和股的总称", "example": null}, {"def": "石人战摇腿。--唐·韩愈《嘲鼾睡》", "example": null}, {"def": "又如腿花(棍子打在腿上;腿伤);大腿;粗腿;腿股(大腿);腿脡(腿码,腿銗腿,言其直而修长);腿胯(腰以下至大腿的部分。常指奔跑时用力之处);腿套(套在裤外使小腿保暖的用", "example": null}, {"def": "品);腿腕(脚与小腿之间的部分);腿裆,腿洼子(两股之间;胯下);腿弯(股胫间弯曲处)", "example": null}, {"def": "在用途上或形状上和动物的腿类似的东西", "example": null}, {"def": "供食", "example": null}, {"def": "腿tuǐ", "example": null}, {"def": "⒈胫部，股部，下肢小～。大～。脚～。", "example": null}, {"def": "⒉指腌制的猪腿火～。", "example": null}, {"def": "⒊器物上像腿的部分桌～。椅子～儿。", "example": null}]','chinese-xinhua','0'),
