('2101143296838471744','挖','1','wā','扌','9',NULL,'[{"def": "挖", "example": null}, {"def": "(挖为穵的俗字。形声。从手,穵声。本作穵”。穵,空大的意思。本义掘)", "example": null}, {"def": "同本义", "example": null}, {"def": "引申为探索;深入研究", "example": null}, {"def": "抓。用爪子或指甲抓", "example": null}, {"def": "镂,镂空", "example": null}, {"def": "头上戴着一顶挖云鹅黄片金里大红猩猩毡昭君套。--《红楼梦》", "example": null}, {"def": "又如挖云(镂穿成云头形的边饰);挖垫(旧时女红之一。把布帛镂穿成各种花样,在后面垫上不同颜色的布帛做衬托);挖镶(镂", "example": null}, {"def": "挖(穵）wā", "example": null}, {"def": "⒈掏，掘～井。～坑。～个洞。", "example": null}, {"def": "⒉发掘，探求～潜力。～空心思。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296838471745','洼','1','wā','氵','9',NULL,'[{"def": "洼", "example": null}, {"def": "(形声。从水,圭声。本义深池)", "example": null}, {"def": "同本义", "example": null}, {"def": "竏,深池也。从水，窐声。--《说文》", "example": null}, {"def": "马生渥洼水中。--《汉书·武帝纪》", "example": null}, {"def": "似洼者。--《庄子·齐物论》", "example": null}, {"def": "泽无洼水。--《淮南子·览冥》", "example": null}, {"def": "又如洼子(低洼存水的地方)", "example": null}, {"def": "低凹的地方", "example": null}, {"def": "古水名", "example": null}, {"def": "渥洼”的省称。是今甘肃省敦煌县党河的水源之一", "example": null}, {"def": "丹山彩凤,洼水神驹。--明·陆采《怀香记·司空受掾》", "example": null}, {"def": "古水,今未详", "example": null}, {"def": "洼,水名。--《广韵·佳韵》", "example": null}, {"def": "竏”的简化字", "example": null}, {"def": "洼", "example": null}, {"def": "清水", "example": null}, {"def": "洼（竏）wā", "example": null}, {"def": "⒈低陷的地方～地。水～儿。", "example": null}, {"def": "⒉深陷深～。眼眶都～了。", "example": null}, {"def": "洼guī 1.姓『代有洼丹。见《后汉书》本传。", "example": null}]','chinese-xinhua','0'),
('2101143296838471746','娲','1','wā','女','10',NULL,'[{"def": "娲", "example": null}, {"def": "古神女名", "example": null}, {"def": "娲,古之神圣女化万物者也。从女,唈声。--《说文》。按,女娲在大庭柏皇前,亦古皇之号,非必妇人也。", "example": null}, {"def": "女娲氏练五色石以补天阙。--《列子·汤问》", "example": null}, {"def": "如娲皇(女娲氏。古女帝王)", "example": null}, {"def": "姓", "example": null}, {"def": "娲（媧）wā", "example": null}, {"def": "娲guā 1.庖娲，古代神话传说中女娲氏的别称。", "example": null}]','chinese-xinhua','0'),
