('2101143296846860340','妄','1','wànɡ','女','6',NULL,'[{"def": "妄", "example": null}, {"def": "(形声。从女,亡声。本义胡乱)", "example": null}, {"def": "同本义", "example": null}, {"def": "妄,乱也。--《说文》", "example": null}, {"def": "不通于轻重谓之妄言。--《管子·山至数》", "example": null}, {"def": "以人自观谓之度,反度为妄。--《贾子道术》", "example": null}, {"def": "施妄者,乱之始也。--《春秋繁露》", "example": null}, {"def": "妄自菲薄。--诸葛亮《出师表》", "example": null}, {"def": "多求妄用。--宋·司马光《训俭示康》", "example": null}, {"def": "妄传伯夷。--清·黄宗羲《原君》", "example": null}, {"def": "毋妄发。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如妄口(胡说);妄系(无故抓人入罪);妄扳平人(胡乱牵连无辜之人);妄施(随便地施恩);妄折(无原则地屈从);妄行(随便行动);妄言(乱说)", "example": null}, {"def": "妄", "example": null}, {"def": "虚妄,极不真实", "example": null}, {"def": "妄wàng胡乱，荒诞，荒谬轻举～动。痴心～想。～自尊大。", "example": null}, {"def": "妄wáng 1.无。 2.连词，表示选择。抑或，还是。", "example": null}]','chinese-xinhua','0'),
('2101143296846860341','忘','1','wànɡ','心','7',NULL,'[{"def": "忘", "example": null}, {"def": "(会意兼形声。从心,从亡,亡亦声。本义忘记,不记得)", "example": null}, {"def": "同本义", "example": null}, {"def": "忘,不识也。--《说文》", "example": null}, {"def": "德音不忘。--《诗·郑风·有女同车》", "example": null}, {"def": "中年病忘。--《列子·周穆王》。释文不记事也。”", "example": null}, {"def": "忘路之远近。--晋·陶渊明《桃花源记》", "example": null}, {"def": "宠辱偕忘。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "忘身于外。--诸葛亮《出师表》", "example": null}, {"def": "又如忘魂(忘怀);忘昏(忘怀);忘反(流连忘归);忘年(忘记年岁);忘味(忘记美食的滋味);忘食(忘了吃饭);忘却(不记得);忘生舍死(忘却性命,不怕牺牲);忘先(忘记祖先)", "example": null}, {"def": "玩忽,怠忽", "example": null}, {"def": "夙夜不敢忘怠。", "example": null}, {"def": "忘wàng", "example": null}, {"def": "⒈不记得～记。～我劳动。～恩负义。", "example": null}, {"def": "⒉忽略，遗漏～却。～掉了。搞卫生，别～了死角。", "example": null}, {"def": "忘wáng 1.丧失，失去。 2.通\\"亡\\"。终止;断绝。", "example": null}, {"def": "忘wú 1.见\\"忘其\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296846860342','旺','1','wànɡ','日','8',NULL,'[{"def": "旺", "example": null}, {"def": "(形声。从日,王声。本义光美) 日晕", "example": null}, {"def": "旺,日晕。--《玉篇》", "example": null}, {"def": "旺", "example": null}, {"def": "火势炽烈", "example": null}, {"def": "翠环道屋里火盆旺着呢!快向屋里烘去罢!”--《老残游记》", "example": null}, {"def": "兴旺;旺盛", "example": null}, {"def": "旺", "example": null}, {"def": "使兴旺", "example": null}, {"def": "旺wàng盛，兴盛～盛。火～。兴～。购销两～。", "example": null}]','chinese-xinhua','0'),
('2101143296846860343','望','1','wànɡ','月','11',NULL,'[{"def": "望", "example": null}, {"def": "(会意。甲骨文字形,上面是臣”象眼睛,下面是壬”。象一个人站在土地上远望。小篆又加月”字,表望的对象。本义远望)", "example": null}, {"def": "同本义", "example": null}, {"def": "望,出亡在外望其还也。--《说文》。按,此字疑当训远视也。", "example": null}, {"def": "望,远视也。--《玉篇》", "example": null}, {"def": "豕望视而交睫腥。--《礼记·内则》。注望视,远视也。”", "example": null}, {"def": "邻邑相望,鸡狗之音相闻。--《庄子·胠箧》", "example": null}, {"def": "望之而不能见也,逐之而不能及也。--《庄子·天运》", "example": null}, {"def": "吾尝跂而望矣,不如登高之博见也。--《荀子·劝学》", "example": null}, {"def": "扁鹊望桓侯。--《韩非子·喻老》", "example": null}, {"def": "举头望明月。--唐·李白《静", "example": null}, {"def": "望wàng", "example": null}, {"def": "⒈向远处看，看得见远～。遥～。丰收在～。", "example": null}, {"def": "⒉拜访拜～。看～。", "example": null}, {"def": "⒊盼，期待，希望盼～。期～。希～。大喜过～。", "example": null}, {"def": "⒋有名声名～。声～。威～。", "example": null}, {"def": "⒌埋怨，责怪怨～。", "example": null}, {"def": "⒍朝，向～前走。～着我。", "example": null}, {"def": "⒎农历每月十五日十五谓之～。", "example": null}]','chinese-xinhua','0'),
