('2101143296846860349','往','1','wǎnɡ','彳','8',NULL,'[{"def": "往", "example": null}, {"def": "(会意。甲骨文字形,从止,从土。意为从这个地方走向目的地。本义去,到…去)", "example": null}, {"def": "同本义", "example": null}, {"def": "往,之也。--《说文》", "example": null}, {"def": "大夫有所往。--《礼记·玉藻》", "example": null}, {"def": "憧憧往来。--《易·咸》", "example": null}, {"def": "吾言既往矣。--《国语·晋语》", "example": null}, {"def": "往而不返。--《庄子·逍遥游》", "example": null}, {"def": "往见老聃。--《庄子·天道》", "example": null}, {"def": "跳往助之。--《列子·汤问》", "example": null}, {"def": "随其往。--晋·陶渊明《桃花源记》", "example": null}, {"def": "欣然前往。", "example": null}, {"def": "子何恃而往。--清·彭端淑《为学一首示子侄》", "example": null}, {"def": "又如前往(前去;去);往造(前去拜访);往教(老师前往学生处施教);往旋(往复回", "example": null}, {"def": "往wǎng", "example": null}, {"def": "⒈去，到有来有～。飞～广州。", "example": null}, {"def": "⒉从前，过去～昔。既～不咎。", "example": null}, {"def": "⒊通\\"望\\"。朝，向～里走。～这边看。", "example": null}, {"def": "⒋", "example": null}, {"def": "往wàng 1.归向。 2.介词。朝，向。", "example": null}]','chinese-xinhua','0'),
('2101143296846860350','徃','1','wǎnɡ','','8',NULL,'[{"def": "徃wǎng 1.去，逝去。 2.从前。", "example": null}]','chinese-xinhua','0'),
('2101143296846860351','枉','1','wǎnɡ','木','8',NULL,'[{"def": "枉", "example": null}, {"def": "(形声。从木,王声。本义弯曲;不正)", "example": null}, {"def": "同本义", "example": null}, {"def": "枉,邪曲也。--《说文》", "example": null}, {"def": "是犹立直木而求其景之枉也。--《荀子·王霸》", "example": null}, {"def": "枉道速祸。--宋·司马光《训俭示康》", "example": null}, {"def": "枉用三尺。--明·高启《书博鸡者事》", "example": null}, {"def": "又如枉法营私(曲解、破坏法律,以谋求私利);枉矢(不直的箭);枉径(弯曲的小路);枉策(弯曲的马鞭);枉路(弯曲的道路);枉渚(弯曲之渚);枉木(曲木,弯木);枉直(曲与直。", "example": null}, {"def": "比喻是非、好坏)", "example": null}, {"def": "邪恶", "example": null}, {"def": "举直错诸枉,能使枉者直。--《论语·颜渊》", "example": null}, {"def": "又如枉上(不正之君主);枉邪(邪恶不正,亦指邪恶不正的人);枉情", "example": null}, {"def": "枉wǎng", "example": null}, {"def": "⒈弯曲，不正直矫～过正。～己正人。", "example": null}, {"def": "⒉歪曲贪赃～法。", "example": null}, {"def": "⒊冤屈，受屈冤～。～害。", "example": null}, {"def": "⒋屈尊～驾。", "example": null}, {"def": "⒌徒然，白白地～然。～用心机。", "example": null}, {"def": "枉kuáng 1.汲具。 2.通\\"狂\\"。乱貌。参见\\"枉妆\\"﹑\\"枉攘\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296846860352','罔','1','wǎnɡ','网','8',NULL,'[{"def": "罔", "example": null}, {"def": "(形声。从网,亡声。本义渔猎用的网)", "example": null}, {"def": "同本义。同网”", "example": null}, {"def": "死于罔罟。--《庄子·逍遥游》", "example": null}, {"def": "列卒满泽,罘罔弥山。--《汉书·司马相如列传》", "example": null}, {"def": "是罔民也。--《孟子·梁惠王上》", "example": null}, {"def": "罔民而可为也。", "example": null}, {"def": "又如罔置(泛指捕猎的网具);罔罟(渔猎时所用的罗网);罔罗(渔猎所用的网。同罗网)", "example": null}, {"def": "法网", "example": null}, {"def": "天之降罔,维其优矣。--《诗·大雅》", "example": null}, {"def": "罔", "example": null}, {"def": "迷惑。失意。通惘”", "example": null}, {"def": "学而不思则罔。--《论语·为政》", "example": null}, {"def": "罔流涕以聊虑兮,惟著意而得之。--", "example": null}, {"def": "罔wǎng", "example": null}, {"def": "⒈蒙蔽，欺骗欺～。", "example": null}, {"def": "⒉无，没有～不。置若～闻。", "example": null}, {"def": "⒊不，不要～罪尔众（不归罪于你们）。～失法度，～游于逸（逸安逸），～淫于乐（淫过度，沉溺）。", "example": null}, {"def": "⒋通\\"网\\"。～罟。", "example": null}]','chinese-xinhua','0'),
('2101143296846860353','惘','1','wǎnɡ','忄','11',NULL,'[{"def": "惘", "example": null}, {"def": "(形声。从心;罔声。本义失意) 同本义", "example": null}, {"def": "惘,怅然失志貌。--《正字通》", "example": null}, {"def": "恺惘然自失。--《世说新语·汰侈》", "example": null}, {"def": "又如惘惘(遑遽而无所适从;伤感;失意;迷迷糊糊);惘惑(迷惑)", "example": null}, {"def": "惘wǎng失意，精神恍惚的样子怅～。～然（也作\\"罔然\\"）若失。", "example": null}]','chinese-xinhua','0'),
