('2101143296851054609','谓','1','wèi','讠','11',NULL,'[{"def": "谓", "example": null}, {"def": "(形声。从言,胃声。本义告诉)", "example": null}, {"def": "同本义", "example": null}, {"def": "谓,报也。--《说文》", "example": null}, {"def": "人以谓霍氏。--《汉书·霍光传》。注告语也。”", "example": null}, {"def": "太后明谓左右。--《战国策·赵策》", "example": null}, {"def": "谓安陵君曰。--《战国策·魏策》", "example": null}, {"def": "谓唐雎曰。", "example": null}, {"def": "谓岛曰。--宋·胡仔《苕溪渔隐丛话》", "example": null}, {"def": "说", "example": null}, {"def": "谓,说也。--《广雅·释诂二》", "example": null}, {"def": "世溷浊莫吾知,人心不可谓兮。--《楚辞·九章·怀沙》", "example": null}, {"def": "请往谓项伯,言沛公不敢背项王也。--《史记·项羽本纪》", "example": null}, {"def": "不可谓智。--《墨子·公输》", "example": null}, {"def": "不可谓仁。", "example": null}, {"def": "不可谓忠。", "example": null}, {"def": "不可谓知类。", "example": null}, {"def": "谓天盖高,不敢不局。--《诗·小雅》", "example": null}, {"def": "评论", "example": null}, {"def": "谓wèi", "example": null}, {"def": "⒈说，告诉可～。愚公～智叟曰。", "example": null}, {"def": "⒉叫做，称为，因为～之。称～∥～？", "example": null}, {"def": "⒊以为，所说的窃（私下）～。所～。", "example": null}, {"def": "⒋意义无～。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296851054610','喂','1','wèi','口','12',NULL,'[{"def": "喂", "example": null}, {"def": "(餵、喂是近代的餧”字) 喂食", "example": null}, {"def": "餧,饲也。--《玉篇》", "example": null}, {"def": "季春之月,餧兽之药,毋出九门。--《礼记·月令》", "example": null}, {"def": "如以肉餧虎。--《汉书·张耳陈馀传》", "example": null}, {"def": "骥不骤进而求服兮,凤亦不贪餧而妄食。--《楚辞·九辩》", "example": null}, {"def": "给动物吃东西。如给牛喂草", "example": null}, {"def": "把食物送到人口里。如给病人喂饭;喂眼(让眼睛看着感到舒服);喂指头(", "example": null}, {"def": "喂", "example": null}, {"def": "用于打招呼", "example": null}, {"def": "用于引起注意或鼓动", "example": null}, {"def": "喂wèi", "example": null}, {"def": "⒈将食物送进人的嘴里～奶。～饭。", "example": null}, {"def": "⒉饲养，拿东西给动物吃～鸡。～鱼。～狗。～马。～养。", "example": null}, {"def": "⒊叹词。〈表〉招呼～，请进！～，他是谁？", "example": null}]','chinese-xinhua','0'),
