('2101143296859443227','煨','1','wēi','火','13',NULL,'[{"def": "煨〈名〉", "example": null}, {"def": "(形声。从火,畏声。本义火盆中的火) 同本义", "example": null}, {"def": "煨,盆中火也。--《说文》", "example": null}, {"def": "热灰谓之煻煨。--《通俗文》", "example": null}, {"def": "一班大小徒弟,尽为煨尽之末。--明·罗懋登《三宝太监西洋记通俗演义》", "example": null}, {"def": "又如煨尘(灰烬;尘埃);煨烬(灰烬,燃烧后的残余物)", "example": null}, {"def": "煨 〈动〉", "example": null}, {"def": "用文火烧熟或加热", "example": null}, {"def": "把生的食物放在火灰里慢慢烤熟", "example": null}, {"def": "烘干", "example": null}, {"def": "焚烧", "example": null}, {"def": "煨wēi", "example": null}, {"def": "⒈使用微火慢慢地煮～猪蹄。～鸡肉。", "example": null}, {"def": "⒉将东西埋在带火的灰里烧熟～红薯。～包谷。", "example": null}]','chinese-xinhua','0'),
('2101143296859443228','詴','1','wēi','','7',NULL,'[{"def": "詴wēi 1.呼唤。 2.作人名用字。宋有赵汝詴。见《宋史．宗室世系表十五》。", "example": null}]','chinese-xinhua','0'),
('2101143296859443229','危','1','wēi','厄','6',NULL,'[{"def": "危", "example": null}, {"def": "(会意。小篆字形上面是人,中间是山崖,下面腿骨节形。人站在山崖上,表示很高。本义在高处而畏惧)", "example": null}, {"def": "同本义", "example": null}, {"def": "危,在高而惧也。--《说文》", "example": null}, {"def": "决危而美名者。--《鬼谷子》。注山高也。”", "example": null}, {"def": "榣木不生危。--《国语·晋语》。注高险也。”", "example": null}, {"def": "高而不危。--《孝经》。郑注殆也。”", "example": null}, {"def": "恐惧;忧惧", "example": null}, {"def": "窃为君危之。--《战国策·西周策》", "example": null}, {"def": "又如人人自危;危心(心存戒惧);危怖(恐惧不安);危栗(恐惧战栗);危气(气馁;危惧);危悚(危悰,危惧);危视(惊视);危睇(俯视而感到惊恐)", "example": null}, {"def": "威胁,摧败", "example": null}, {"def": "能危山东", "example": null}, {"def": "危wēi", "example": null}, {"def": "⒈不安全～险。～急。", "example": null}, {"def": "⒉损害～害。～及生命。", "example": null}, {"def": "⒊将死临～。病～。垂～。", "example": null}, {"def": "⒋高，陡～峰。～乎高哉！", "example": null}, {"def": "⒌正，端正～言～行。正襟～坐。", "example": null}, {"def": "⒍", "example": null}, {"def": "①讲正直的话。", "example": null}, {"def": "②使人吃惊的话～言耸听。", "example": null}, {"def": "⒎星宿名，二十八宿之一。", "example": null}]','chinese-xinhua','0'),
('2101143296859443230','威','1','wēi','女','9',NULL,'[{"def": "威", "example": null}, {"def": "威力;威风", "example": null}, {"def": "威,畏也。--《说文》", "example": null}, {"def": "威也者,力也。--《吕氏春秋·荡兵》", "example": null}, {"def": "有而可畏谓之威《史记·平原君虞卿列传》", "example": null}, {"def": "严大国之威。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "秦王之威。", "example": null}, {"def": "威天下不以兵革。--《孟子·公孙丑下》", "example": null}, {"def": "威棱威乎邻国。--《汉书·李广传》", "example": null}, {"def": "威振四海。--汉·贾谊《过秦论》", "example": null}, {"def": "为敛威去。--《明史》", "example": null}, {"def": "又如威风杀气(威风恶煞;盛气凌人);威弧(很有威力的弧矢);威折(以威力使之折服);威服(以威力慑服);威柄(威权,权力);威畏(以威势使之畏服);威约(威势为人制约);威凌", "example": null}, {"def": "(以威势相欺凌);威绥(以威力使之安", "example": null}, {"def": "威wēi", "example": null}, {"def": "⒈尊严，声誉，名望～严。声～。权～。～望。", "example": null}, {"def": "⒉使人敬畏的力量或气势～力。～风。示～。～振四海。", "example": null}, {"def": "⒊凭借力量或势力～协。～慑，～逼。", "example": null}]','chinese-xinhua','0'),
