('2101143296859443263','璺','1','wèn','玉','20',NULL,'[{"def": "璺", "example": null}, {"def": "玉器破裂", "example": null}, {"def": "璺,玉破。--《集韵》", "example": null}, {"def": "微裂,尤指陶瓷、玻璃等器物上出现的裂纹", "example": null}, {"def": "璺wèn器物上的裂痕那个杯上有一道～。打破沙锅～到底（〈喻〉对问题追根究底）。", "example": null}]','chinese-xinhua','0'),
('2101143296859443264','刎','1','wěn','刂','6',NULL,'[{"def": "刎", "example": null}, {"def": "(形声。从刀,勿声。本义割脖子)", "example": null}, {"def": "同本义", "example": null}, {"def": "刎,刭也。--《说文新附》", "example": null}, {"def": "卒相与欢,为刎颈之交。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "种霸越而灭吴兮,终刎颈于属镂。--刘基《述志赋》", "example": null}, {"def": "又如自刎(割颈部自杀);刎脰(刎颈。割脖子,自杀)", "example": null}, {"def": "割断", "example": null}, {"def": "刎,断也。--《博雅》", "example": null}, {"def": "刎,亡粉切,割也。--《玉篇》", "example": null}, {"def": "马前不得进,后不得退,遂避而逸,因下抽刀而刎其脚。--《韩非子·外储说右下》", "example": null}, {"def": "刎wěn割颈部自～。泛指割断～其脚。", "example": null}]','chinese-xinhua','0'),
('2101143296859443265','吻','1','wěn','口','7',NULL,'[{"def": "吻", "example": null}, {"def": "(形声。从口,勿声。本义嘴唇)", "example": null}, {"def": "同本义", "example": null}, {"def": "吻,唇两角头边也。--《华严经音义》", "example": null}, {"def": "黄吻澜漫赤。--左思《娇女诗》", "example": null}, {"def": "遂鼓吻奋爪以向先生。--马中锡《中山狼传》", "example": null}, {"def": "又如接吻;亲吻", "example": null}, {"def": "嘴;口", "example": null}, {"def": "使人之吻助己言谈。--《墨子·尚同中》", "example": null}, {"def": "又如吻舌(吻唇。口和舌);吻吮(用口吹奏);吻流(利口之辈);吻创(口疮);吻翰(口与笔);吻噤(闭口);吻儒(善谑利口的儒生)", "example": null}, {"def": "语气;口气", "example": null}, {"def": "指鸱吻。古建筑屋脊两端的装饰物", "example": null}, {"def": "其制设吻者为殿,无吻者不为殿矣。--宋", "example": null}, {"def": "吻（脗）wěn", "example": null}, {"def": "⒈嘴唇接～。", "example": null}, {"def": "⒉用嘴唇接触〈表〉喜爱～ ～孩子的脸。", "example": null}, {"def": "⒊某些动物头端的突出部分或口器。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
