('2101143296863637538','勿','1','wù','勹','4',NULL,'[{"def": "兀", "example": null}, {"def": "(指事。从一,在人上。人头上一横,表示高平。本义高耸特出的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "兀,高而上平也。--《说文》", "example": null}, {"def": "何时眼前突兀见此屋。--杜甫《茅屋为秋风所破歌》", "example": null}, {"def": "又如兀岸(直耸挺拔);兀嵝(险峻)", "example": null}, {"def": "光秃(如毛发)的", "example": null}, {"def": "蜀山兀。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如兀首(头发脱落)", "example": null}, {"def": "茫然无知", "example": null}, {"def": "临文乍了了,彻卷兀若天。--柳宗元《读书》", "example": null}, {"def": "又如兀兀陶陶(醉酒);兀楞楞(痴呆)", "example": null}, {"def": "不够稳定", "example": null}, {"def": "独立", "example": null}, {"def": "焉有翡翠横肩,援琴合膝,而能兀焉自立者也?--", "example": null}, {"def": "勿wù", "example": null}, {"def": "⒈别，不要～动。请～吸烟。", "example": null}, {"def": "⒉不～许。守而～失。", "example": null}, {"def": "勿mò 1.见\\"恤勿\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296863637539','务','1','wù','力','5',NULL,'[{"def": "务", "example": null}, {"def": "(形声。从力,務声。从力,表示要致力于某事。本义致力,从事)", "example": null}, {"def": "同本义", "example": null}, {"def": "非务相反也。--《吕氏春秋·察今》", "example": null}, {"def": "欲富国者,务广其地。--《战国策·秦策一》", "example": null}, {"def": "务耕织。--汉·贾谊《过秦论》", "example": null}, {"def": "又如务能(竭力);务精(极力求精;精益求精);务穑(务农);务法(致力于法治);务本(专心致力于根本);务外(谓研究学问,只致力于表面,不求深入);务纯(致力于深钻细研,以达", "example": null}, {"def": "炉火纯青);务本(致力于根本);务于东(在东方致力作战)", "example": null}, {"def": "操劳", "example": null}, {"def": "谋求", "example": null}, {"def": "不务文字奇。--白居易《寄唐生》", "example": null}, {"def": "追求", "example": null}, {"def": "务（務）wù", "example": null}, {"def": "⒈致力，从事～工。～农。", "example": null}, {"def": "⒉事情事～。业～。任～。公～。", "example": null}, {"def": "⒊必须，一定～必。除恶～尽。", "example": null}, {"def": "⒋追求好高～远。", "example": null}, {"def": "务mào 1.通\\"瞀\\"。眩惑。 2.通\\"冒\\"。《荀子．哀公》\\"古之王者有务而拘领者矣，其政好生而恶杀焉。\\"杨倞注\\"《尚书大传》曰\'古之人衣上有冒而句领者。\'郑康成注云", "example": null}, {"def": "\'……冒，覆项也。\'\\"一说，务通\\"鍪\\"。梁启雄释\\"务读为\'鍪\'，《淮南子．泛论》\'古者有鍪而绻领以王天下者矣，其德生而不杀。\'正作\'鍪\'字。\\"", "example": null}]','chinese-xinhua','0'),
('2101143296863637540','戊','1','wù','戈','5',NULL,'[{"def": "戊", "example": null}, {"def": "天干的第五位。方位属中央", "example": null}, {"def": "古代以十干配五方,戊居十干中,因以指中央", "example": null}, {"def": "五六者,天地之中合。--《汉书》", "example": null}, {"def": "指代土", "example": null}, {"def": "戊戌维新", "example": null}, {"def": "学习西方,提倡科学文化,改", "example": null}, {"def": "戊wù天干第五位，也用作次序第五。", "example": null}]','chinese-xinhua','0'),
('2101143296863637541','阢','1','wù','阝','5',NULL,'[{"def": "阢", "example": null}, {"def": "上面覆盖着土的石山", "example": null}, {"def": "阢,石山戴土也。--《说文》", "example": null}, {"def": "危急不安的样子", "example": null}, {"def": "阢陧", "example": null}, {"def": "邦之阢陧。--《书·秦誓》", "example": null}, {"def": "阢wù", "example": null}, {"def": "⒈", "example": null}]','chinese-xinhua','0'),
