('2101143296888803329','杌','1','wù','木','7',NULL,'[{"def": "杌", "example": null}, {"def": "树木无枝丫", "example": null}, {"def": "浑然无知", "example": null}, {"def": "见杌陧”", "example": null}, {"def": "杌", "example": null}, {"def": "摇,动摇", "example": null}, {"def": "扬翠叶,杌紫茎。--《史记·司马相如列传》", "example": null}, {"def": "杌", "example": null}, {"def": "蝎凳", "example": null}, {"def": "砍树剩余的桩子", "example": null}, {"def": "杌,刊余木。--《集韵》", "example": null}, {"def": "杌陧", "example": null}, {"def": "邦之杌陧,曰由一人。--《书·秦誓》", "example": null}, {"def": "杌陧之象。--孙文《黄花冈七十二烈士事略·序》", "example": null}, {"def": "杌wù", "example": null}, {"def": "⒈小凳～凳。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296888803330','芴','1','wù','艹','7',NULL,'[{"def": "芴〈副〉hu", "example": null}, {"def": "恍惚。谓凝不清或茫然无知的样子", "example": null}, {"def": "通忽”■然", "example": null}, {"def": "芴  wu", "example": null}, {"def": "植物名。", "example": null}, {"def": "芴,菲也。--《说文》", "example": null}, {"def": "一种无色结晶状烷烃", "example": null}, {"def": "芴 wū", "example": null}, {"def": "①〈名〉植物名\'即茜菜。一年生草本。可供观尝，兼作蔬菜。", "example": null}, {"def": "②〈名〉有机化合物的一种。白色片状晶体，由煤焦油制得。", "example": null}, {"def": "芴wù 1.即蓎菜。一年生草本，产于我国北部和中部，可供观赏，兼作蔬菜。 2.一种稠环芳香烃。由煤焦油制得。白色片状，有紫色荧光。可用作有机合成的原料。", "example": null}, {"def": "芴hū 1.恍惚。谓凝不清或茫然无知之貌。 2.忽然。无根本貌。", "example": null}]','chinese-xinhua','0'),
