('2101143296888803370','牾','1','wǔ','牜','11',NULL,'[{"def": "牾", "example": null}, {"def": "相逢", "example": null}, {"def": "重华不可牾兮,孰知余之从容。--《史记·屈原贾生列传》", "example": null}, {"def": "背逆", "example": null}, {"def": "牾,逆也。--《说文》", "example": null}, {"def": "自郡吏以下皆畏避之,莫敢与牾。--《汉书·严延年传》", "example": null}, {"def": "又如抵牾(矛盾。也作牴牾);牾逆(违逆,触犯)", "example": null}, {"def": "牾wǔ逆，抵触，冲突抵～。", "example": null}]','chinese-xinhua','0'),
('2101143296888803371','珷','1','wǔ','王','12',NULL,'[{"def": "珷", "example": null}, {"def": "似玉的石。同磇", "example": null}, {"def": "珷wǔ 1.见\\"珷玞\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296888803372','妩','1','wǔ','女','7',NULL,'[{"def": "妩", "example": null}, {"def": "(形声。从女,无声。本义媚)", "example": null}, {"def": "同本义", "example": null}, {"def": "妩,媚也。--《说文》", "example": null}, {"def": "娇美", "example": null}, {"def": "妩", "example": null}, {"def": "美女", "example": null}, {"def": "妩,美女。--《玉篇》", "example": null}, {"def": "妩（嫵、娬）wǔ", "example": null}]','chinese-xinhua','0'),
('2101143296888803373','庑','1','wǔ','广','7',NULL,'[{"def": "庑", "example": null}, {"def": "(形声。从广,无声。从广,与房屋有关。本义堂下周围的廊屋)", "example": null}, {"def": "同本义", "example": null}, {"def": "庑,堂下周屋。--《说文》", "example": null}, {"def": "居庑下,为人赁舂。--《后汉书·梁鸿传》", "example": null}, {"def": "合百草兮实庭,建芳馨兮庑门。--《楚辞》", "example": null}, {"def": "庑下一生伏案卧。--清·方苞《左忠毅公逸事》", "example": null}, {"def": "泛指房屋", "example": null}, {"def": "居大庑之下。--《史记》", "example": null}, {"def": "又如盖庑(盖屋);计殿(有四坡略呈弯曲的屋面的房子)", "example": null}, {"def": "廊", "example": null}, {"def": "庙中空无所有,唯一黑漆棺停庑下。--《夜谭随录》", "example": null}, {"def": "屋檐", "example": null}, {"def": "檐,其名有十四…十一曰庑。--李诫《营造法式》", "example": null}, {"def": "庑（弔）wǔ〈古〉", "example": null}, {"def": "⒈高堂下周围的廊房，厢房。", "example": null}, {"def": "⒉房屋～殿。大～。", "example": null}, {"def": "庑wú 1.草木茂盛。", "example": null}]','chinese-xinhua','0'),
('2101143296888803374','忤','1','wǔ','忄','7',NULL,'[{"def": "忤", "example": null}, {"def": "(形声。从心,午声。本义抵触,不顺从)", "example": null}, {"def": "同本义", "example": null}, {"def": "复忤宾客。--唐·李朝威《柳毅传》", "example": null}, {"def": "触忤当死。--清·张廷玉《明史》", "example": null}, {"def": "又如忤权(不屈服于权贵);忤物(触犯人;与人不合);忤怨(抵触而生怨);忤恨(违逆;反对);忤意(违逆心意);忤嫚(忤慢。违抗怠慢);忤触(触犯);忤鳞(直言犯上)", "example": null}, {"def": "触动", "example": null}, {"def": "临风悼亡,忤愁心,匹鸟河洲上。--明·汪道昆《洛水悲》", "example": null}, {"def": "交错", "example": null}, {"def": "阴阳散忤。--《春秋元命包》", "example": null}, {"def": "忤逆", "example": null}, {"def": "自小忤逆", "example": null}, {"def": "忤视", "example": null}, {"def": "忤wǔ逆，违反～逆。", "example": null}]','chinese-xinhua','0'),
('2101143296888803375','怃','1','wǔ','忄','7',NULL,'[{"def": "怃", "example": null}, {"def": "(形声。从心,无声。本义抚爱)", "example": null}, {"def": "同本义", "example": null}, {"def": "怃,爱也。--《说文》", "example": null}, {"def": "怃,抚也。--《尔雅》", "example": null}, {"def": "哀怜", "example": null}, {"def": "怃", "example": null}, {"def": "怅然失意的样子", "example": null}, {"def": "应之者咸怃然。--唐·柳宗元《柳河东集》", "example": null}, {"def": "君怃然曰。--唐·李朝威《柳毅传》", "example": null}, {"def": "又如怃然(失意;不痛快)", "example": null}, {"def": "惊愕的样子", "example": null}, {"def": "表怃然为骇。--《后汉书》", "example": null}, {"def": "通妩”。媚好的样子", "example": null}, {"def": "又为妇画眉,长安中传张京兆眉怃。--《汉书·张敞传》", "example": null}, {"def": "怃（憮）wǔ", "example": null}, {"def": "⒈茫然失意的样子～然。", "example": null}, {"def": "⒉惊愕。", "example": null}, {"def": "怃hū 1.傲慢。参见\\"怃敖\\"。 2.通\\"幠\\"。大;粗。", "example": null}]','chinese-xinhua','0'),
('2101143296888803376','迕','1','wǔ','辶','7',NULL,'[{"def": "迕", "example": null}, {"def": "(形声。从辵,午声。本义相逢;相遇)", "example": null}, {"def": "同本义", "example": null}, {"def": "迕,遇也。--《玉篇》", "example": null}, {"def": "王甫时出,与蕃相迕。--《后汉书·陈蕃传》", "example": null}, {"def": "违反;违背", "example": null}, {"def": "倒道而言,迕道而说者,人之所治也,安能治人?--《庄子》", "example": null}, {"def": "上下相反,好恶乘迕。--《汉书·食货志上》", "example": null}, {"def": "交错;夹杂", "example": null}, {"def": "百年三万日,老病常居半。其间迕忧乐,歌笑杂悲欢。--宋·苏轼《乔太傅见和复次韵答之》", "example": null}, {"def": "触犯", "example": null}, {"def": "公貌宽而内忌,不亮吾忠,而吾数以至言忤之。--《资治通鉴》", "example": null}, {"def": "迕wǔ", "example": null}, {"def": "⒈相遇相～。", "example": null}, {"def": "⒉逆，违反违～。", "example": null}]','chinese-xinhua','0'),
('2101143296888803377','武','1','wǔ','止','8',NULL,'[{"def": "武", "example": null}, {"def": "(会意。从止,从戈。据甲骨文,人持戈行进,表示要动武。本义勇猛;猛烈) 同本义", "example": null}, {"def": "楚庄王曰,夫文止戈为武。又曰,夫武禁暴戢兵保大定功安民和财者也。--《左氏春秋·宣公十二年》", "example": null}, {"def": "武大为于大君。--《易·履》", "example": null}, {"def": "孔武有力。--《诗·郑风·羔裘》", "example": null}, {"def": "诚既勇兮又以武。--《楚辞·九歌·国殇》", "example": null}, {"def": "又如英武(英俊威武);威武(武力;权势;力量强大);武色(凶猛的神色);武车(威猛的兵车);武健(勇武刚健);武断乡曲(以威势主断曲直)", "example": null}, {"def": "武", "example": null}, {"def": "指干戈军旅之事", "example": null}, {"def": "德不厚而行武。--《韩非子·五蠹》", "example": null}, {"def": "用武之国。--《三国志", "example": null}, {"def": "武wǔ", "example": null}, {"def": "⒈关于军事或技击的，跟\\"文\\"相对～将。～装。～器。～艺。～术。", "example": null}, {"def": "⒉搏斗，殴打～斗。动～。", "example": null}, {"def": "⒊勇猛，勇敢英～。威～。", "example": null}, {"def": "⒋半步。〈古〉以六尺为步，半步为武不过步～尺寸之间。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296888803378','五','1','wǔ','二','4',NULL,'[{"def": "五", "example": null}, {"def": "(五,会意。从二,从乿。二”代表天地,乿”表示互相交错。本义交午,纵横交错) 同本义", "example": null}, {"def": "五,阴阳在天地之间交午也。--《说文》", "example": null}, {"def": "葛屦五两。--《诗·齐风·南山》", "example": null}, {"def": "羔羊之皮,素丝五絝。--《诗·召南·羔羊》", "example": null}, {"def": "五", "example": null}, {"def": "四加一的和", "example": null}, {"def": "五,数也。--《广韵》", "example": null}, {"def": "五载一巡守。--《书·舜典》", "example": null}, {"def": "塞其五山。--唐·李朝威《柳毅传》", "example": null}, {"def": "五战于秦。--宋·苏洵《六国论》", "example": null}, {"def": "起则五六揖。--明·宗臣《报刘一丈书》", "example": null}, {"def": "监五室。--清·方苞《狱中杂记》", "example": null}, {"def": "又如五路总口(通往东、西、南、北、中五路的交叉口);五车腹笥(腹中", "example": null}, {"def": "五wǔ", "example": null}, {"def": "⒈数目字～人。～员大将。", "example": null}, {"def": "⒉旧时乐谱记音符号之一，相当于简谱的\\"6\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296888803379','午','1','wǔ','十','4',NULL,'[{"def": "午", "example": null}, {"def": "(象形。本义御马索)", "example": null}, {"def": "同本义", "example": null}, {"def": "地支的第七位", "example": null}, {"def": "与天干相配,用以纪年", "example": null}, {"def": "太岁在午曰敦羊。--《尔雅》", "example": null}, {"def": "用以纪月。即农历五月", "example": null}, {"def": "午,五月阴气午逆阳,冒地而出。--《说文》", "example": null}, {"def": "用以纪日", "example": null}, {"def": "庚午之日,日始有谪。--《左传》", "example": null}, {"def": "用以纪时,即十一时至十三时;正午,白天十二时", "example": null}, {"def": "午战于彼。--《左传·僖公三十二年》", "example": null}, {"def": "时已过午。--《徐霞客游记·游黄山记》", "example": null}, {"def": "过午已昏。--明·归有", "example": null}, {"def": "午wǔ", "example": null}, {"def": "⒈地支的第七位，也用作次序第七。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊特指正午（十二点）～餐。上～。中～。下～。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143296888803380','仵','1','wǔ','亻','6',NULL,'[{"def": "仵", "example": null}, {"def": "等同;匹敌", "example": null}, {"def": "以坚白同异之辩相訾,以觭偶不仵之辞相应。--《庄子·天下》", "example": null}, {"def": "违背", "example": null}, {"def": "自用则不虚,不虚则仵于物矣。--《管子》", "example": null}, {"def": "用同捂”。用手遮盖住", "example": null}, {"def": "只在二门外仵着脸,脱脱的哭起来。--《西游记》", "example": null}, {"def": "仵", "example": null}, {"def": "五", "example": null}, {"def": "檀越元囿鸾施地仵拾亩。--北魏《敬史君碑》", "example": null}, {"def": "通伍”。古代士兵五人为伍", "example": null}, {"def": "重振威仪,再排队仵。--《敦煌变文》", "example": null}, {"def": "仵人。亦称以代人殓葬为业的人", "example": null}, {"def": "天明就要入殓,只怕被仵作看出破绽来了。--《金瓶梅》", "example": null}, {"def": "仵wǔ", "example": null}]','chinese-xinhua','0'),
('2101143296888803381','伍','1','wǔ','亻','6',NULL,'[{"def": "伍", "example": null}, {"def": "(会意。从人,从五。五人为伍。本义五人构成一个集体)", "example": null}, {"def": "同本义", "example": null}, {"def": "伍,行伍。--《广韵》", "example": null}, {"def": "五人为伍。--《管子·小筐》", "example": null}, {"def": "会其什伍而教之道义。--《周礼·天官·宫正》", "example": null}, {"def": "先偏后伍。--《左传·桓公五年》", "example": null}, {"def": "林不狃之伍。--《左传·哀公十一年》", "example": null}, {"def": "古代军队编制单位。士兵五名编为一伍", "example": null}, {"def": "全伍为上。--《墨子·公输》", "example": null}, {"def": "破伍次之。", "example": null}, {"def": "又如伍伯(即伍长。古军队中五人为伍,一伍之长称伍长);伍什(指部队);伍老(伍长);伍壮(指乡武装丁壮);伍部(伍长);伍乘(同乘共伍的士卒)", "example": null}, {"def": "古代民户编制单位。五家编为一伍", "example": null}, {"def": "伍 wǔ", "example": null}, {"def": "⒈\\"五\\"的大写。", "example": null}, {"def": "⒉〈古〉军队编制，五人为一伍。〈引〉军队队～。入～。退～。", "example": null}, {"def": "⒊〈古〉一种居民组织，五家为一伍。", "example": null}, {"def": "⒋同类，一伙羞与为～。", "example": null}]','chinese-xinhua','0'),
