('2101143296897191982','稀','1','xī','禾','12',NULL,'[{"def": "稀", "example": null}, {"def": "(形声。从禾,希声。本义稀疏)", "example": null}, {"def": "同本义", "example": null}, {"def": "稀,疏也。--《说文》", "example": null}, {"def": "月明星稀。--《文选·曹操·短歌行》。经传皆以希为之。", "example": null}, {"def": "重露成涓滴,稀星乍有无。--唐·杜甫《倦夜》", "example": null}, {"def": "种豆南山下,草盛豆苗稀。--晋·陶潜《归园田居》", "example": null}, {"def": "又如稀棱挣(稀疏的样子);稀撒撒(稀剌剌);稀星(稀疏的星);稀零零(极稀疏);稀稀落落(稀疏的样子;稀疏冷落的样子)", "example": null}, {"def": "少,不多", "example": null}, {"def": "相见常日稀。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "鞍马稀。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "死者尚稀。--清·方苞《狱中杂记》", "example": null}, {"def": "自想此梦稀奇,", "example": null}, {"def": "稀xī", "example": null}, {"def": "⒈疏，跟\\"密\\"相对～疏。～客。地广人～。月明星～。", "example": null}, {"def": "⒉薄，浓度小，跟\\"稠\\"相对～薄。～饭。～盐酸。", "example": null}, {"def": "⒊少～少。～罕。～奇。～有。", "example": null}]','chinese-xinhua','0'),
('2101143296897191983','粞','1','xī','米','12',NULL,'[{"def": "粞", "example": null}, {"def": "碎米", "example": null}, {"def": "碓下糠粞幸不乏,何妨相倚过余生。--陆游《老鸡》", "example": null}, {"def": "粞xī碎米米～。糠～。", "example": null}]','chinese-xinhua','0'),
('2101143296897191984','翕','1','xī','羽','12',NULL,'[{"def": "翕", "example": null}, {"def": "(形声。从羽,合声。本义闭合;收拢)", "example": null}, {"def": "同本义", "example": null}, {"def": "蝘之兴,五日翕。--《夏小正》。按,飞起也。", "example": null}, {"def": "翕如也。--《论语》。皇疏习也。”", "example": null}, {"def": "伐翕伐张。--《荀子·议兵》", "example": null}, {"def": "唯南有箕,载翕其舌。--《诗·小雅·大东》", "example": null}, {"def": "将欲翕之,必固张之。--《韩非子·喻老》", "example": null}, {"def": "唇吻翕辟,不知何词。--《聊斋志异·促织》", "example": null}, {"def": "又如翕翼(合翼);翕敛(收敛;收缩)", "example": null}, {"def": "聚集", "example": null}, {"def": "翕集家门,倾动人物。--《世说新语·排调》", "example": null}, {"def": "又如翕集(聚集);翕翕(和合的样子);翕聚(会聚)", "example": null}, {"def": "顺从", "example": null}, {"def": "翕xī", "example": null}, {"def": "⒈合，收敛一张一～（张开）。", "example": null}, {"def": "⒉和顺，协调～和。", "example": null}]','chinese-xinhua','0'),
