('2101143296897192001','郗','1','xī','阝','9',NULL,'[{"def": "郗", "example": null}, {"def": "春秋周邑名", "example": null}, {"def": "郗,己姓。《说文》云周邑。”野王西北。--宋·罗泌《路史》", "example": null}, {"def": "姓。晋有郗超", "example": null}, {"def": "郗xī姓。", "example": null}]','chinese-xinhua','0'),
('2101143296897192002','饻','1','xī','','8',NULL,'[{"def": "饻xī旧时老解放区一种计算工资的单位，以几种实物价格的总和为一饻。", "example": null}]','chinese-xinhua','0'),
('2101143296897192003','唏','1','xī','口','10',NULL,'[{"def": "唏", "example": null}, {"def": "发笑", "example": null}, {"def": "夸父揶揄愚公唏。--陈士芑《甲辰二十八初度自述一百韵》", "example": null}, {"def": "又如唏唏(笑声)", "example": null}, {"def": "哀叹", "example": null}, {"def": "纣为象箸而箕子唏。--《淮南子》", "example": null}, {"def": "女仰天而唏。--苏曼殊《天涯红泪记》", "example": null}, {"def": "唏xī", "example": null}, {"def": "⒈叹息声。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296897192004','奚','1','xī','大','10',NULL,'[{"def": "奚", "example": null}, {"def": "(会意。据甲骨文,左为手(爪),右为绳索捆着的人。本义奴隶,又专指女奴)", "example": null}, {"def": "同本义", "example": null}, {"def": "凡奚隶聚而出入者,则司牧之。--《周礼·秋官·禁暴氏》。孙诒让正义奚为女奴,隶为男奴也。”", "example": null}, {"def": "酒人奄十人,女酒三十人,奚三百人。--《周礼·天官》", "example": null}, {"def": "又如奚女(婢女);奚奴(女奴。今泛指奴仆);奚童(奚僮。未成年男仆);奚隶(男女奴隶)", "example": null}, {"def": "大腹", "example": null}, {"def": "奚,大腹也。从大,籀文系省声。--《说文》", "example": null}, {"def": "晋祁奚。--《左传》", "example": null}, {"def": "又如奚奚(大腹便便的样子)", "example": null}, {"def": "姓", "example": null}, {"def": "奚", "example": null}, {"def": "什么,何", "example": null}, {"def": "奚取焉。--唐·韩愈《朱文公校昌黎先生集》", "example": null}, {"def": "复奚疑。", "example": null}, {"def": "奚xī", "example": null}, {"def": "⒈〈古〉指女奴隶，奴仆～隶。～奴。", "example": null}, {"def": "⒉文言疑问词。哪里，什么，为什么水～自至（水从哪里来的）？～谓轻法？子（你）～哭之悲也？", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143296897192005','娭','1','xī','女','10',NULL,'[{"def": "娭毑", "example": null}, {"def": "娭āi［娭毑］〈方〉祖母。也尊称年老的妇女。", "example": null}, {"def": "娭xī 1.嬉戏。 2.喜，乐。", "example": null}]','chinese-xinhua','0'),
('2101143296897192006','屖','1','xī','','8',NULL,'[{"def": "屖xī 1.见\\"屖遟\\"。 2.同\\"犀\\"。参见\\"屖弩\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296897192007','息','1','xī','心','10',NULL,'[{"def": "息", "example": null}, {"def": "(会意兼形声。从心,从自,自亦声。自,鼻子。古人以为气是从心里通过鼻子呼吸的。本义喘气;呼吸)", "example": null}, {"def": "同本义", "example": null}, {"def": "息,喘也。--《说文》", "example": null}, {"def": "亦孔之。--《诗·大雅·桑柔》。笺如仰疾风,不能息也。”", "example": null}, {"def": "尚不敢惕息。--《汉书·扬雄传》。注出入气也。”", "example": null}, {"def": "则心惕息。--《汉书·司马迁传》。注喘息也。”", "example": null}, {"def": "武气绝,半日复息。--《汉书·苏武传》", "example": null}, {"def": "随形势为沟墙,庶息响相闻,易于守御。--《明史·王复传》", "example": null}, {"def": "又如喘息(急促呼吸);息息(呼吸;气息出入);息窒(窒息,呼吸困难);息响(呼吸的声音);息贲(中医病名。指呼吸急", "example": null}, {"def": "息xī", "example": null}, {"def": "⒈呼吸喘～。～ ～相关。", "example": null}, {"def": "⒉叹叹～。", "example": null}, {"def": "⒊歇，停止休～。停～。～怒。～事宁人。", "example": null}, {"def": "⒋滋生，繁殖灾～。生～。", "example": null}, {"def": "⒌利钱利～。月～。年～。", "example": null}, {"def": "⒍新闻，音信消～。信～。", "example": null}, {"def": "⒎子女子～。弱～。", "example": null}]','chinese-xinhua','0'),
('2101143296897192008','悕','1','xī','','8',NULL,'[{"def": "悕xī 1.悲伤。 2.心念，愿望。 3.罕少。", "example": null}]','chinese-xinhua','0'),
('2101143296897192009','晞','1','xī','日','11',NULL,'[{"def": "晞", "example": null}, {"def": "(形声。从日,希声。本义晒干)", "example": null}, {"def": "同本义", "example": null}, {"def": "晞,日干也。--《说文》", "example": null}, {"def": "匪阳不晞。--《诗·小雅·湛露》", "example": null}, {"def": "发晞用象栉。--《礼记·玉藻》", "example": null}, {"def": "晞尔发兮阳之阿。--《楚辞·少司令》", "example": null}, {"def": "白露未晞。--《诗·秦风·蒹葭》", "example": null}, {"def": "青青园中葵,朝露待日晞。--《乐府诗集·长歌行》", "example": null}, {"def": "琼蚌晞曜以莹珠。--郭璞《江赋》", "example": null}, {"def": "又如晞发(把洗净的头发晒干);晞解(因日晒而消除);晞灭(受日照而消失);晞露(日晒使露水蒸发);晞土(干土);晞块(干土)", "example": null}, {"def": "通昕”。晓,天刚明", "example": null}, {"def": "东方未晞。--《诗·齐风·东方未明》", "example": null}, {"def": "晞xī晒，晒干～曜（曜日光）。白露未～。", "example": null}]','chinese-xinhua','0'),
