('2101143296905580574','闲','1','xián','门','7',NULL,'[{"def": "闲", "example": null}, {"def": "(会意。从门中有木。本义栅栏)", "example": null}, {"def": "同本义", "example": null}, {"def": "闲,阑也。--《说文》", "example": null}, {"def": "人闲有家。--《易·家》。注;阑也。”", "example": null}, {"def": "日闲舆卫。--《易·大畜》。注阂也。”", "example": null}, {"def": "舍则守王闲。--《周礼·虎贲氏》。郑玄注闲,梐枑。”贾公彦疏闲与梐枑皆禁卫之物。”", "example": null}, {"def": "马厩,关养马的地方", "example": null}, {"def": "天子十有二闲,马六种。--《周礼·夏官》", "example": null}, {"def": "龙与闲驹。--《汉书·百官表》", "example": null}, {"def": "又如闲厩(古代皇家养牲口的地方);闲驹(养马之所)", "example": null}, {"def": "伦理道德的规范、界限", "example": null}, {"def": "掌十有二闲之政教。--《周礼·痩人》", "example": null}, {"def": "大德不逾闲,小德出入可也。--《论语", "example": null}, {"def": "闲xián", "example": null}, {"def": "⒈没有事做空～。清～。～白了头。", "example": null}, {"def": "⒉放着，不使用～着。～置。", "example": null}, {"def": "⒊静，安静～夜。～庭。\\"閒\\"另见间(閒)。", "example": null}, {"def": "⒋与正事无关～话。～人勿进。", "example": null}, {"def": "⒌栅栏，养马的圈厩～。〈引〉防止建极～邪（建立准则，防止邪说）。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "闲jiàn 1.空隙;缝隙。 2.指空子，可乘的机会。 3.嫌隙，隔阂。 4.阻隔;间隔。 5.差别;距离。 6.间杂，夹杂。 7.离间。 8.间谍。 9.伺候;侦伺。 10.私下", "example": null}, {"def": "。 11.非难;毁谤。 12.参与。 13.引申为介绍。 14.干犯。 15.更迭，交替。 16.引申为代替。 17.痊愈。 18.间或。 19.拔去或锄去多馀的。 20.乘，趁(时", "example": null}, {"def": "间﹑机会)。", "example": null}, {"def": "闲jiān 1.中间;内。亦指事物两者的关系。 2.一定的空间或时间里。 3.一会儿;顷刻。 4.近来。 5.量词。房室单位。有时也指学校﹑工厂﹑商店等的单位。 6.量词", "example": null}, {"def": "。格﹑片﹑瓣。 7.量词。指动作次数。", "example": null}, {"def": "闲jiǎn 1.通\\"简\\"。检阅，视察。 2.通\\"简\\"。简省。 3.用同\\"涧\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296905580575','弦','1','xián','弓','8',NULL,'[{"def": "弦", "example": null}, {"def": "(会意。左为弓”,右为丝”。弓弦是用丝做成的。本义弓弦)", "example": null}, {"def": "同本义", "example": null}, {"def": "弦,弓弦也。从弓,象丝轸之形。--《说文》", "example": null}, {"def": "无待韦弦。--《文选·王文宪集序》", "example": null}, {"def": "故佩弦以自急。--《韩非子·观行》", "example": null}, {"def": "引弦而战。--《淮南子·人间训》", "example": null}, {"def": "抚弦登陴。--南朝梁·丘迟《与陈伯之书》", "example": null}, {"def": "又如弦箭(弦上之箭);弦栝(弓弦和箭末扣弦处)", "example": null}, {"def": "弓弩", "example": null}, {"def": "乐器上的肠线或金属丝", "example": null}, {"def": "弦而鼓之。--明·刘基《郁离子·千里马篇》", "example": null}, {"def": "朝歌夜弦。--唐·杜牧《阿房宫赋", "example": null}, {"def": "弦（絣）xián", "example": null}, {"def": "⒈弯弓上发箭的绳，一般用牛筋制成弓～。箭在～。", "example": null}, {"def": "⒉半圆的月亮上～（初八、初九的月亮）。下～（农历廿二、廿三日的月亮）。", "example": null}, {"def": "⒊数学名词", "example": null}, {"def": "①直线与圆相交，夹在圆周以内的部分。", "example": null}, {"def": "②直角三角形中对着直角的边。", "example": null}, {"def": "⒋乐器上用于发音的丝线、铜线、钢线等。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍钟表等的发条换个表～。", "example": null}]','chinese-xinhua','0'),
('2101143296905580576','贤','1','xián','贝','8',NULL,'[{"def": "贤", "example": null}, {"def": "(形声。从贝,与财富有关。本义多财)", "example": null}, {"def": "有德行;多才能", "example": null}, {"def": "贤,多才也。--《说文》", "example": null}, {"def": "以财分人之谓贤。--《庄子·徐无鬼》", "example": null}, {"def": "相如既归,赵王以为贤大夫。--《史记》", "example": null}, {"def": "闲贤臣。--诸葛亮《出师表》", "example": null}, {"def": "又如贤声远达(好的名声远扬四处);贤歌(品行技艺都好的歌妓);贤才(德才并美之人);时贤(指当代有贤能有声望的人)", "example": null}, {"def": "对人的敬称", "example": null}, {"def": "凡与人言……自叔父母以下,则加贤”字。--《颜氏家训》", "example": null}, {"def": "分明是如贤所教,但是小生自小坐书斋,不谙其他生活。╠", "example": null}, {"def": "贤（賢）xián", "example": null}, {"def": "⒈有道德、有才能的，也指德才兼备的人～明。选～与能。用人唯～。", "example": null}, {"def": "⒉胜过，甚于～于。", "example": null}, {"def": "⒊敬词。用于平辈或晚辈～妻。～甥。", "example": null}, {"def": "⒋〈古〉劳苦我从事独～。", "example": null}, {"def": "贤xiàn 1.车毂一端的大孔。", "example": null}]','chinese-xinhua','0'),
('2101143296905580577','咸','1','xián','口','9',NULL,'[{"def": "咸", "example": null}, {"def": "(会意。据甲骨文。从戌,从口。戌是长柄大斧,口”指人头∠起来表示大斧砍人头。本义杀)", "example": null}, {"def": "同本义", "example": null}, {"def": "咸刘厥敌。--《书·君奭》", "example": null}, {"def": "毕;终", "example": null}, {"def": "迄始皇三载而咸,时、激、地、保、人事乎?--汉·扬雄《法言》", "example": null}, {"def": "感应", "example": null}, {"def": "…窕则不咸。--《左传》", "example": null}, {"def": "又如咸腓(妄动);咸感(阴阳相感,夫妇相和)", "example": null}, {"def": "咸", "example": null}, {"def": "普遍都,全部", "example": null}, {"def": "咸,皆也,悉也。--《说文》", "example": null}, {"def": "庶绩咸熙。--《书·尧典》", "example": null}, {"def": "周邦咸喜。--《诗·大雅·崧高》", "example": null}, {"def": "村中闻有此人,咸来问讯。--晋·陶渊明《桃花源记》", "example": null}, {"def": "咸怃然。--唐·柳宗元《柳河东集》", "example": null}, {"def": "京城", "example": null}, {"def": "咸（", "example": null}, {"def": "⒉鹹）xián", "example": null}, {"def": "⒈都、皆～知。老少～宜。", "example": null}, {"def": "⒉盐的味道，跟\\"淡\\"相对～肉。菜～了。", "example": null}, {"def": "咸jiān 1.束棺木的绳索。", "example": null}, {"def": "咸jiǎn 1.通\\"减\\"。剪除;灭绝。参见\\"咸黜\\"。 2.姓。", "example": null}]','chinese-xinhua','0'),
('2101143296905580578','涎','1','xián','氵','9',NULL,'[{"def": "涎", "example": null}, {"def": "(形声。从水,延声。本义唾沫,口水)", "example": null}, {"def": "同本义", "example": null}, {"def": "涎,小儿唾也。--《三苍》", "example": null}, {"def": "喷浪飞唌(涎)。--郭璞《江赋》", "example": null}, {"def": "群犬垂涎。--柳宗元《三戒》", "example": null}, {"def": "又如口角流涎;垂涎三尺", "example": null}, {"def": "粘液", "example": null}, {"def": "咳则腰背相引而痛,甚则咳涎。--《素问》", "example": null}, {"def": "涎", "example": null}, {"def": "流口水", "example": null}, {"def": "见元妃痰塞口涎,不能言语。--《红楼梦》", "example": null}, {"def": "贪羡,贪图", "example": null}, {"def": "主人涎我色,奸我,不从,则鞭挞之。--清·袁枚《新齐谐》", "example": null}, {"def": "又如涎利(贪图利益)", "example": null}, {"def": "吐;流", "example": null}, {"def": "厚着脸皮;嬉皮笑脸", "example": null}, {"def": "涎xián口水，唾液流～。垂～欲滴。垂～三尺。", "example": null}]','chinese-xinhua','0'),
