('2101143296905580582','舷','1','xián','舟','11',NULL,'[{"def": "舷", "example": null}, {"def": "(形声。从舟,玄声。字义船边)", "example": null}, {"def": "船、飞机等两侧的边沿", "example": null}, {"def": "两兄弟凭舷痛饮,谈说古今的事。--《儒林外史》", "example": null}, {"def": "船的两侧", "example": null}, {"def": "舷xián船的两侧右～。左～。", "example": null}]','chinese-xinhua','0'),
('2101143296905580583','衔','1','xián','行','11',NULL,'[{"def": "衔", "example": null}, {"def": "口含", "example": null}, {"def": "蟾蜍衔之。--《后汉书·张衡传》", "example": null}, {"def": "又如燕子衔泥;衔环相报(衔环);衔刀(口中叼刀);衔土(口含泥土);衔口垫背(古代一种殓葬习俗给死人口含珠、玉或米。死尸褥下放钱)", "example": null}, {"def": "怀藏", "example": null}, {"def": "衔之次骨。--清·纪昀《阅微草堂笔记》", "example": null}, {"def": "如衔恩(感恩);衔悔(怀有悔恨之心);衔匿(深藏在心里);衔恤(心怀忧伤);衔哀(心怀哀痛)", "example": null}, {"def": "奉接,接受", "example": null}, {"def": "贾昌衔保家活命之恩,无从报效。--《醒世恒言》", "example": null}, {"def": "又如衔命(奉行命令)", "example": null}, {"def": "把两物互相接起来或缚住", "example": null}, {"def": "且把粮车首尾衔,权做寨栅。--《水浒全传》", "example": null}, {"def": "包含,", "example": null}, {"def": "衔xián", "example": null}, {"def": "⒈马嚼子勒紧～。", "example": null}, {"def": "⒉用嘴含，包含，含有结草～环。～花。～远山。", "example": null}, {"def": "⒊藏在心中，怀恨～悲。～恨。", "example": null}, {"def": "⒋奉，接受～命。", "example": null}, {"def": "⒌相接～接。", "example": null}, {"def": "⒍职位，职称职～。头～。官～。军～。大使～。", "example": null}]','chinese-xinhua','0'),
('2101143296905580584','啣','1','xián','','11',NULL,'[{"def": "啣xián", "example": null}, {"def": "⒈马嚼子勒紧～。", "example": null}, {"def": "⒉用嘴含，包含，含有结草～环。～花。～远山。", "example": null}, {"def": "⒊藏在心中，怀恨～悲。～恨。", "example": null}, {"def": "⒋奉，接受～命。", "example": null}, {"def": "⒌相接～接。", "example": null}]','chinese-xinhua','0'),
