('2101143296905580608','县','1','xiàn','厶','7',NULL,'[{"def": "县", "example": null}, {"def": "(会意。从系持倒首。象悬挂的样子。本义悬挂)", "example": null}, {"def": "县假借为寰”,为州县的县", "example": null}, {"def": "遂缚诣县。--三国魏·邯郸淳《笑林》", "example": null}, {"def": "南番二县。--《广东军务记》", "example": null}, {"def": "龙泉县。--明·刘基《诚意伯刘文成公文集》", "example": null}, {"def": "开道置县。--《明史》", "example": null}, {"def": "又如县尹(一县的长官);县学(旧制设在县里的学校,以培养人才,教育百姓,称县学);县委(中国共产党县一级委员会的简称)", "example": null}, {"def": "官府", "example": null}, {"def": "县（縣）xiàn", "example": null}, {"def": "⒈省、市、自治区领导下的一级行政区域。", "example": null}, {"def": "⒉〈古〉通\\"悬\\"。", "example": null}, {"def": "县xuán 1.挂。 2.古称悬挂的乐器，如钟磬等。 3.悬钟磬之具。 4.维系;拴系;系联。 5.差距;远。 6.揭示;颁立。 7.悬赏。 8.秤锤。 9.称量;衡量。 10.祭", "example": null}, {"def": "名。 11.姓。春秋时有县成。见《史记．仲尼弟子列传》。", "example": null}]','chinese-xinhua','0'),
('2101143296905580609','岘','1','xiàn','山','7',NULL,'[{"def": "岘", "example": null}, {"def": "小而险峻的山", "example": null}, {"def": "苕递陟陉岘。--谢灵运《从斤竹涧越岭溪行》。李善注《声类》曰岘,山岭小高也”", "example": null}, {"def": "山名,岘山", "example": null}, {"def": "在湖北省襄阳。又名岘首山", "example": null}, {"def": "在河南省信阳县南。又名凿砚山。如岘首(即岘山);岘山泪(百姓至岘山凭吊羊祜而流的眼泪◇指因感念地方官德政而流的泪)", "example": null}, {"def": "在江苏省丹徒县东南。也名兽窟。因建藏寺于此山,又名九华山", "example": null}, {"def": "在浙江省东阳县南。又名双岘", "example": null}, {"def": "在浙江省吴兴县南,本名显山,以唐庙讳改为岘山", "example": null}, {"def": "在浙江省长兴县", "example": null}, {"def": "岘xiàn岘山，在湖北省。", "example": null}]','chinese-xinhua','0'),
