('2101143296913969167','详','1','xiánɡ','讠','8',NULL,'[{"def": "详", "example": null}, {"def": "(形声。从言,羊声。本义审察,审理)", "example": null}, {"def": "同本义", "example": null}, {"def": "详,审议也。--《说文》", "example": null}, {"def": "度作详刑,以诘四方。--《书·吕刑》。郑注审察之也。”", "example": null}, {"def": "凤姐详情度理,说他们必不敢多说一句话。”--《红楼梦》", "example": null}, {"def": "愿明上详之。--《三国演义》", "example": null}, {"def": "又如详允(审判得当、公平);详当(详审而允当);详阅(审查批阅)", "example": null}, {"def": "详细说明", "example": null}, {"def": "又如详梦(解梦;析梦);内详;另详", "example": null}, {"def": "清楚地知道", "example": null}, {"def": "非君所详。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "亦不详其姓字。--陶潜《五柳先生传》", "example": null}, {"def": "又如详典(了", "example": null}, {"def": "详xiáng", "example": null}, {"def": "⒈细密，完备～细。～尽。～情。～实。～议法令。", "example": null}, {"def": "⒉清楚，知道内容～知。", "example": null}, {"def": "⒊说明，细说～谈。内～。～告之。", "example": null}, {"def": "⒋广泛，周遍～找。", "example": null}, {"def": "⒌审慎～刑慎罚（审慎使用刑罚）。", "example": null}, {"def": "⒍〈古〉通\\"佯\\"。假装。", "example": null}, {"def": "详yáng 1.诈，假装。", "example": null}]','chinese-xinhua','0'),
('2101143296913969168','庠','1','xiánɡ','广','9',NULL,'[{"def": "庠", "example": null}, {"def": "(形声。从广,羊声。广”与房屋有关。本义古代地方学校)", "example": null}, {"def": "殷、周时的学校", "example": null}, {"def": "痒,礼官养老,夏曰校,殷曰庠,周曰序。--《说文》", "example": null}, {"def": "殷曰序,周曰庠。--《孟子·滕文公上》", "example": null}, {"def": "庠序,官也。--《尔雅·释官》", "example": null}, {"def": "有虞氏养国老于上庠,养庶老于下庠。--《礼记》。郑玄注上庠,右学,大学也,在西郊。下庠,左学,小学也,在国中王宫之东。”", "example": null}, {"def": "古代的乡学", "example": null}, {"def": "主人拜迎宾于庠门之外。--《礼记·乡饮酒义》。注乡学也。”", "example": null}, {"def": "庠之制有堂有室也。--《仪礼·乡射礼》注", "example": null}, {"def": "党有庠。--《仪礼·学记》。注五百家为党,庾", "example": null}, {"def": "庠xiáng〈古〉指地方学校殷曰～，周曰序。", "example": null}]','chinese-xinhua','0'),
