('2101143296913969176','巷','1','xiànɡ','巳','9',NULL,'[{"def": "巷〈名〉hang", "example": null}, {"def": "矿坑里的通道", "example": null}, {"def": "巷  xiang", "example": null}, {"def": "同本义。直为街,曲为巷;大者为街,小者为巷", "example": null}, {"def": "斜阳草树,寻常巷陌,人道寄奴曾往。--辛弃疾《永遇乐》", "example": null}, {"def": "深巷中犬吠。--《虞初新志·秋声诗自序》", "example": null}, {"def": "巷哭声相闻。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "又如巷口(里弄的出入口);巷言,巷议(于里巷中议论是非)", "example": null}, {"def": "住宅", "example": null}, {"def": "在陋巷,人不堪其忧,回也不改其乐。--《论语·雍也》", "example": null}, {"def": "巷hàng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉见xiàng。", "example": null}, {"def": "巷xiàng", "example": null}, {"def": "⒈里弄，胡同小～。窄～子。", "example": null}]','chinese-xinhua','0'),
('2101143296913969177','项','1','xiànɡ','页','9',NULL,'[{"def": "项", "example": null}, {"def": "(形声。从页,工声。从页,与头有关。本义脖子的后部)", "example": null}, {"def": "同本义", "example": null}, {"def": "项,头后也。--《说文》", "example": null}, {"def": "延颈秀项,皓质呈露。--曹植《洛神赋》", "example": null}, {"def": "项背相望。--《后汉书·左雄传》", "example": null}, {"def": "又如项髻(挽发髻于颈后);项窝(脖子后部的凹处)", "example": null}, {"def": "泛指人颈", "example": null}, {"def": "老魔将芭蕉扇插在后项衣领。--《西游记》", "example": null}, {"def": "项掣金锁。--唐·李朝威《柳毅传》", "example": null}, {"def": "青项金翅。--《聊斋志异·促织》", "example": null}, {"def": "又如项头(头与脖项);项领(指颈部);项缩(缩颈。形容畏惧的样子)", "example": null}, {"def": "代数中不用加、减号连接的单式", "example": null}, {"def": "款项", "example": null}, {"def": "项xiàng", "example": null}, {"def": "⒈颈子的后部。泛指颈部～背。屈～。引～高歌。", "example": null}, {"def": "⒉事物的分类或条目事～。～目。八～注意。", "example": null}, {"def": "⒊钱，经费款～。收入～。", "example": null}, {"def": "⒋量词两～任务。", "example": null}]','chinese-xinhua','0'),
