('2101143296913969190','鲞','1','xiǎnɡ','鱼','14',NULL,'[{"def": "鲞", "example": null}, {"def": "干鱼;腊鱼", "example": null}, {"def": "石首鲞,食之消瓜成水。--晋·王羲之《杂帖五》", "example": null}, {"def": "又如鲞鹤(即勒鱼做成的鱼干);鲞铺(卖干鱼、腌腊食品的店铺)", "example": null}, {"def": "腌腊食品", "example": null}, {"def": "凤姐儿听说,依言夹些茄鲞,送入刘姥姥口中。--《红楼梦》", "example": null}, {"def": "又如鲞腊(干腊鱼肉)", "example": null}, {"def": "鲞（鯗）xiǎng剖开的去除内脏以后的晒干之鱼鳗～。鲤～。", "example": null}]','chinese-xinhua','0'),
('2101143296913969191','享','1','xiǎnɡ','亠','8',NULL,'[{"def": "享", "example": null}, {"def": "(会意。本作亯”。从高”省,曰”象进献熟物形。本义祭献,上供。用物品进献人,供奉鬼神使其享受)", "example": null}, {"def": "同本义", "example": null}, {"def": "享,献也。--《说文》", "example": null}, {"def": "享于祖考。--《诗·小雅·信南山》", "example": null}, {"def": "是用孝享。--《诗·小雅·天保》", "example": null}, {"def": "以享以祀。--《诗·小雅·楚茨》", "example": null}, {"def": "诸侯侯以享天子。--《考工记·玉人》", "example": null}, {"def": "王用享于西山。--《易·随》", "example": null}, {"def": "享尝乃止。--《礼记·祭法》", "example": null}, {"def": "相夺予享。--《左传·僖公三十一年》", "example": null}, {"def": "兹予大享于先王。--《书·盘庚》", "example": null}, {"def": "杀牛宰马,祭天享地。--《西游记》", "example": null}, {"def": "又如享厅(供奉祖宗木主或神佛偶像的地方);享牛(供", "example": null}, {"def": "享xiǎng", "example": null}, {"def": "⒈受用，满足～受。～有。～福。共～太平。", "example": null}]','chinese-xinhua','0'),
('2101143296913969192','亯','1','xiǎnɡ','','8',NULL,'[{"def": "亯xiǎng 1.《说文．京部》\\"享，献也……《孝经》曰\'祭则鬼享之。\'\\"今本《孝经．孝治》\\"亯\\"作\\"享\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296913969193','响','1','xiǎnɡ','口','9',NULL,'[{"def": "响", "example": null}, {"def": "(形声。从口,鄉声。本义回声)", "example": null}, {"def": "同本义", "example": null}, {"def": "響,声也。--《说文》", "example": null}, {"def": "炎光飞响。--《剧秦美新》", "example": null}, {"def": "黄玉响应。--《史晨奏铭》", "example": null}, {"def": "其受命也如响。--《易·系辞》", "example": null}, {"def": "空谷传响,哀转久绝。--《水经注·江水》", "example": null}, {"def": "云集响应。--汉·贾谊《过秦论上》", "example": null}, {"def": "绝无踪响。--《聊斋志异·促织》", "example": null}, {"def": "又如响臻(响应纷至);响彻;响效(同响应)", "example": null}, {"def": "声音", "example": null}, {"def": "泠泠作响。--吴均《与朱元思书》", "example": null}, {"def": "歌台暖响。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "枹止响腾,余韵徐歇。--苏轼《石钟山记》", "example": null}, {"def": "群响毕绝。--《虞初新志·秋声诗自序》", "example": null}, {"def": "又如响丁丁(响泠泠。形容清", "example": null}, {"def": "响（響）xiǎng", "example": null}, {"def": "⒈声音～声。音～。", "example": null}, {"def": "⒉发出声音铃～了。炮～了。", "example": null}, {"def": "⒊回声空谷传～。", "example": null}, {"def": "⒋声音大，洪亮～彻云霄。～亮的歌声。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296913969194','饷','1','xiǎnɡ','饣','9',NULL,'[{"def": "饷", "example": null}, {"def": "(形声。左形右声。本义给在田间里劳动的人送饭)", "example": null}, {"def": "同本义", "example": null}, {"def": "餫,饟也。--《说文》", "example": null}, {"def": "餫,餫馈。--《广韵》", "example": null}, {"def": "饟,周人谓餫曰饟。--《说文》", "example": null}, {"def": "饟,馈也。--《尔雅》", "example": null}, {"def": "种饟粮食。--《汉书·食货志下》", "example": null}, {"def": "輓车奉饟者。--《汉书·严助传》", "example": null}, {"def": "为雇耕佣,凭种餫。--《后汉书·章帝纪》。注餫,粮也,古餫字。”", "example": null}, {"def": "数声牛上笛,何处饷田归?--前蜀·韦庄《纪村事》", "example": null}, {"def": "又如饷田(送饭到田头);饷人(送饭食的人);饷馌(往田头送饭)", "example": null}, {"def": "招待,供给或提供", "example": null}, {"def": "有童子以黍肉", "example": null}, {"def": "饷（饟）xiǎng", "example": null}, {"def": "⒈军粮，又指军、警等的薪金粮～。关～。领～。", "example": null}, {"def": "⒉给在田间劳动的人送饭。", "example": null}, {"def": "⒊同\\"飨\\"。用酒饮食款待人～客。", "example": null}]','chinese-xinhua','0'),
('2101143296913969195','晑','1','xiǎnɡ','','8',NULL,'[{"def": "晑xiǎng 1.光明;明亮。", "example": null}]','chinese-xinhua','0'),
('2101143296913969196','飨','1','xiǎnɡ','飠','12',NULL,'[{"def": "飨", "example": null}, {"def": "(会意兼形声。从食,从乡,乡亦声。本义乡人相聚宴饮)", "example": null}, {"def": "同本义", "example": null}, {"def": "飨,乡人饮酒也。--《说文》", "example": null}, {"def": "飨,歆飨。--《广韵》", "example": null}, {"def": "尚蚸。--《仪礼·少牢馈食礼》", "example": null}, {"def": "将弗克飨为人而已。--《国语·晋语一》", "example": null}, {"def": "君其飨之。--《国语·晋语四》", "example": null}, {"def": "先祭而后飨。--《淮南子·说山》", "example": null}, {"def": "朋酒斯飨,曰杀羔羊。--《诗·豳风》。毛传飨,乡人饮酒也。”", "example": null}, {"def": "设盛宴待宾客", "example": null}, {"def": "钟鼓既没,一朝飨之。--《诗·小雅·彤弓》", "example": null}, {"def": "及飨日,帷诸门左。--《左传·昭公二十七年》", "example": null}, {"def": "夫人姜氏飨齐侯。--《谷梁传·庄公四年》。注", "example": null}, {"def": "飨（饗）xiǎng", "example": null}, {"def": "⒈受用，满足～受。～有。～福。共～太平。", "example": null}, {"def": "⒉用酒饮食款待人～客。以～读者（〈喻〉满足读者的需求）。", "example": null}]','chinese-xinhua','0'),
('2101143296913969197','想','1','xiǎnɡ','心','13',NULL,'[{"def": "想", "example": null}, {"def": "(形声。心形相声。本义想念;怀念;羡慕)", "example": null}, {"def": "同本义", "example": null}, {"def": "想,冀思也。--《说文》", "example": null}, {"def": "览物想故国。--杜甫《客居》", "example": null}, {"def": "遥想公瑾当年,小乔初嫁了,雄姿英发。--苏轼《念奴娇》", "example": null}, {"def": "又如想似(深切的怀念);想思(想念)", "example": null}, {"def": "思考,思索", "example": null}, {"def": "入景响之无应兮,闻省想而不可得。--《楚辞·九章·悲回风》", "example": null}, {"def": "后来还亏得文琴替我竭力想法,找了原经手人,向周中堂讨主意。--《二十年目睹之怪现状》", "example": null}, {"def": "又如冥思苦想;想来想去(反复的多方思考);想度(考虑,衡量)", "example": null}, {"def": "希望,想要", "example": null}, {"def": "那时他老人家正在用功,想中那名进士。--", "example": null}, {"def": "想xiǎng", "example": null}, {"def": "⒈思索，动脑筋～象。仔细～来。敢～敢干。", "example": null}, {"def": "⒉希望，打算～做实验。～去旅游。", "example": null}, {"def": "⒊推测，认为猜～。料～。我～应该这样办。", "example": null}, {"def": "⒋怀念，惦记～念。～家乡。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
