('2101143296913969202','缃','1','xiānɡ','纟','12',NULL,'[{"def": "缃", "example": null}, {"def": "浅黄色", "example": null}, {"def": "缃绮为下裙。--《乐府诗集·陌上桑》", "example": null}, {"def": "如缃苞(浅黄色的苞);缃裙(浅黄色的裙子);缃素(浅黄色书卷的代称);缃绮(淡黄色的丝织品)", "example": null}, {"def": "缃", "example": null}, {"def": "浅黄色的帛", "example": null}, {"def": "树名", "example": null}, {"def": "缃 xiāng淡黄色。", "example": null}]','chinese-xinhua','0'),
('2101143296913969203','葙','1','xiānɡ','艹','12',NULL,'[{"def": "［青葙］", "example": null}, {"def": "葙 xiāng［青葙］（qīng-）〈名〉植物名。俗称野鸡冠。花淡红色，供观尝。种子可入药。《本草纲目·草部·青葙》\\"～生田野间，嫩苗似苋可食，长则高三四尺。苗叶", "example": null}, {"def": "花实与鸡冠花一样无别。", "example": null}]','chinese-xinhua','0'),
('2101143296913969204','箱','1','xiānɡ','竹','15',NULL,'[{"def": "箱", "example": null}, {"def": "(形声。从竹,相声。本义车箱)", "example": null}, {"def": "同本义", "example": null}, {"def": "箱,大车牝服也。--《说文》", "example": null}, {"def": "不以服箱。--《诗·小雅·大东》。传箱,大车之箱也。”", "example": null}, {"def": "乃求万斯箱。--《诗·小雅·甫田》", "example": null}, {"def": "絷?", "example": null}, {"def": "尔乃乘露箱,御良马。--晋·夏侯湛《猎兔赋》", "example": null}, {"def": "厢房,古代居室前堂两旁的房屋,也称个”或序”◇作厢”", "example": null}, {"def": "?", "example": null}, {"def": "公揖,退于箱。--《仪礼·公食礼》。注东夹之前俟事之处。”", "example": null}, {"def": "俟几俟于东箱。--《仪礼·觐礼》。注东夹之前相翔待事之处。”", "example": null}, {"def": "箱xiāng", "example": null}, {"def": "⒈收藏衣物等的用具。一般为长立方形，上面有盖，可扣住皮～子。工具～。", "example": null}, {"def": "⒉像箱子的东西邮～。风～。意见～。书报～。", "example": null}, {"def": "⒊同\\"厢", "example": null}, {"def": "⒌\\"车～。", "example": null}]','chinese-xinhua','0'),
