('2101143296913969211','瓖','1','xiānɡ','','17',NULL,'[{"def": "瓖xiāng", "example": null}, {"def": "⒈将东西嵌进去或在外周加边～嵌。～牙。～金。～边。", "example": null}, {"def": "⒉马带上面的玉饰。", "example": null}]','chinese-xinhua','0'),
('2101143296913969212','镶','1','xiānɡ','钅','22',NULL,'[{"def": "镶", "example": null}, {"def": "(形声。从金,襄声。本义瓤子)", "example": null}, {"def": "铸铜铁器模型的瓤子", "example": null}, {"def": "镶,作型中肠也。--《说文》", "example": null}, {"def": "古兵器名", "example": null}, {"def": "手持白头镶。--晋·张华《博陵王宫侠曲二首》", "example": null}, {"def": "镶", "example": null}, {"def": "镶嵌物相嵌或相配合", "example": null}, {"def": "单拿了一双老年四楞象牙镶金的筷子给刘姥姥。--《红楼梦》", "example": null}, {"def": "又如镶滚(在衣服边缘加一道边;女服加宽边叫镶,加窄边叫滚)", "example": null}, {"def": "俗称修补其缺处", "example": null}, {"def": "今市肆有补齿,一云镶齿,如生。--清·叶名沣《桥西杂记》", "example": null}, {"def": "如镶牙", "example": null}, {"def": "镶xiāng", "example": null}, {"def": "⒈将东西嵌进去或在外周加边～嵌。～牙。～金。～边。", "example": null}, {"def": "⒉马带上面的玉饰。", "example": null}]','chinese-xinhua','0'),
