('2101143296913969225','孝','1','xiào','子','7',NULL,'[{"def": "孝", "example": null}, {"def": "(形声。从老省,从子。本义尽心奉养和服从父母)", "example": null}, {"def": "同本义", "example": null}, {"def": "孝,善事父母者。--《说文》", "example": null}, {"def": "孝利亲也。--《墨子经》", "example": null}, {"def": "子爱利亲谓之孝。--《贾子道术》", "example": null}, {"def": "慈惠爱亲为孝。协时肇享为孝、五宗安之曰孝,秉德不回曰孝。--《周书·谥法》", "example": null}, {"def": "众之本教曰孝。--《礼记·祭义》", "example": null}, {"def": "夫孝,德之本也。又,天之经也,民之行也。--《孝经》", "example": null}, {"def": "孝,文之本也。--《国语·周语》", "example": null}, {"def": "孝,礼之始也。--《左传·文公二年》", "example": null}, {"def": "中和祗庸孝友。--《周礼·大司乐》", "example": null}, {"def": "靡有不孝,自求伊祜。--《诗·鲁颂·泮水》", "example": null}, {"def": "孝悌之义。--《孟子·梁惠王", "example": null}, {"def": "孝xiào", "example": null}, {"def": "⒈旧指尽心奉养和绝对服从父母。现指尊敬、奉养父母～敬。～养。", "example": null}, {"def": "⒉有关居丧的事。～服。", "example": null}]','chinese-xinhua','0'),
('2101143296918163456','効','1','xiào','','7',NULL,'[{"def": "効xiào", "example": null}, {"def": "⒈成果，功用～果。成～。有～。", "example": null}, {"def": "⒉摹仿～法。仿～。", "example": null}, {"def": "⒊尽，致，送，献出～力。～劳。～命。纳地～玺。", "example": null}]','chinese-xinhua','0'),
('2101143296918163457','效','1','xiào','攵','10',NULL,'[{"def": "效", "example": null}, {"def": "(形声。从攴,交声。攴”有致力的意思。本义献出;尽力)", "example": null}, {"def": "同本义", "example": null}, {"def": "司城荡意诸来奔,效节于府人而出。--《左传》", "example": null}, {"def": "异日韩王纳地效玺。--《史记》", "example": null}, {"def": "又如效力;效绩(呈献功绩);效玺(呈献国君的印章,表示臣服);效己(贡献一己之力);效芹(自称贡献微薄)", "example": null}, {"def": "明白", "example": null}, {"def": "由此效之也。--《荀子·正论》", "example": null}, {"def": "乡也,效门室之辨。--《荀子·儒效》", "example": null}, {"def": "效,明也。--《方言十三》", "example": null}, {"def": "通校(榞澄????)”。考查。考核", "example": null}, {"def": "彼将任我以事而效我以功。--《庄子·列御寇》", "example": null}, {"def": "又如效试(考核试验);效", "example": null}, {"def": "效xiào", "example": null}, {"def": "⒈成果，功用～果。成～。有～。", "example": null}, {"def": "⒉摹仿～法。仿～。", "example": null}, {"def": "⒊尽，致，送，献出～力。～劳。～命。纳地～玺。", "example": null}, {"def": "⒋", "example": null}, {"def": "①单位时间内完成工作量的大小高～率的工作。", "example": null}, {"def": "②物理学上指作出来的有用之功跟所加上的功相比。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
('2101143296918163458','校','1','xiào','木','10',NULL,'[{"def": "校〈名〉jiao", "example": null}, {"def": "古代刑具。枷械的统称", "example": null}, {"def": "校,木囚也。从木,交声。--《说文》", "example": null}, {"def": "屦校灭趾。--《易·噬嗑》。", "example": null}, {"def": "何校灭耳。注若今枷项也。”", "example": null}, {"def": "大校重牢,五木被体。--《新唐书》", "example": null}, {"def": "栅栏", "example": null}, {"def": "天子校猎。--《汉书·司马相如传》。注以木相贯穿,总为栏校,遮止禽兽而猎取之。”", "example": null}, {"def": "又如校猎(用木栏遮阻而猎取禽兽。校木栏)", "example": null}, {"def": "校样", "example": null}, {"def": "校人”的省称。养马官", "example": null}, {"def": "六厩成校。--《周礼·校人》", "example": null}, {"def": "校正属焉。--《左传·成公十八年》。注主马官。”", "example": null}, {"def": "又", "example": null}, {"def": "校jiào", "example": null}, {"def": "⒈查对，订正～对。～正。", "example": null}, {"def": "⒉对抗，较量～场（旧时操练或比武的地方）。", "example": null}, {"def": "⒊见xiào。", "example": null}, {"def": "校xiào", "example": null}, {"def": "⒈指学校～友。母～。", "example": null}, {"def": "⒉军衔名，在\\"将\\"之下，\\"尉\\"之上。", "example": null}, {"def": "校jiǎo 1.牢固。 2.急速;急促。 3.暗绿色。", "example": null}, {"def": "校qiāo 1.器物的脚﹑腿。", "example": null}]','chinese-xinhua','0'),
