('2101143296918163473','小','1','xiǎo','小','3',NULL,'[{"def": "小", "example": null}, {"def": "(象形。据甲骨文,象沙粒形。小篆析为会意。从八,从|。本义细;微。与大”相对)", "example": null}, {"def": "同本义", "example": null}, {"def": "小,物之微也。--《说文》", "example": null}, {"def": "小往大来。--《易·泰》。疏阴生消耗,故称小。”", "example": null}, {"def": "彼所小言尽人毒也。--《庄子·列御寇》。注细巧入人为小言。”翱", "example": null}, {"def": "噂彼小星。--《诗·召南·小星》", "example": null}, {"def": "受小球大球。--《诗·商颂·长发》", "example": null}, {"def": "怨不在大,亦不在小。--《书·康诰》", "example": null}, {"def": "又如小鹿儿(喻指因紧张而剧烈跳动的心脏);小录(新科进士的题名录);小", "example": null}, {"def": "小xiǎo", "example": null}, {"def": "⒈跟\\"大\\"相对", "example": null}, {"def": "①面积、范围小的～山。～国。～块田。", "example": null}, {"def": "②量少的～量。～数。～雨。一～点。", "example": null}, {"def": "③程度浅的～学生。", "example": null}, {"def": "④声音低的～声。", "example": null}, {"def": "⑤年幼的，排行最末的～孩子。～妹妹。", "example": null}, {"def": "⑥谦词～弟。～女。～号。", "example": null}, {"def": "⒉轻视～看。", "example": null}, {"def": "⒊稍微～试锋芒。", "example": null}, {"def": "⒋时间短～住。～歇。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "①矮小的人～人国（童话）。", "example": null}, {"def": "②旧时指被统治者或地位低下的人。", "example": null}, {"def": "③人格卑鄙的人无耻～人。", "example": null}, {"def": "⒎", "example": null}, {"def": "①戏曲、杂技中的丑角。", "example": null}, {"def": "②〈喻〉轻浮，不顾廉耻的人跳梁～丑。", "example": null}, {"def": "⒏", "example": null}, {"def": "①寻常非同～可。", "example": null}, {"def": "②旧时谦称自己～可愿往。", "example": null}, {"def": "⒐", "example": null}]','chinese-xinhua','0'),
('2101143296918163474','晓','1','xiǎo','日','10',NULL,'[{"def": "晓", "example": null}, {"def": "(象形。从日,尧声。本义天明)", "example": null}, {"def": "同本义。今专指天刚亮", "example": null}, {"def": "晓,明也。--《说文》", "example": null}, {"def": "冥冥之中,独见晓焉。--《淮南子·俶真》", "example": null}, {"def": "晓驾炭车辗冰辙。--唐·白居易《卖炭翁》", "example": null}, {"def": "晓看红湿处。--唐·杜甫《春夜喜雨》", "example": null}, {"def": "晓当尽戮之。--《资治通鉴·唐纪》", "example": null}, {"def": "梳晓鬟也。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "晓风残月。--宋·柳永《雨霖铃》", "example": null}, {"def": "又如破晓(刚亮);拂晓(天快亮);晓雾;晓舌(鸟拂晓叫);晓暝(天将亮的时候);晓行;晓鸡初啼;晓星;晓岚;鸡鸣报晓;晓夕(日夜);晓天,晓色(拂晓时的天色);晓月,晓魄(拂晓残", "example": null}, {"def": "月)", "example": null}, {"def": "清晨", "example": null}, {"def": "晓光浮", "example": null}, {"def": "晓（曉）xiǎo", "example": null}, {"def": "⒈天亮拂～。天～。", "example": null}, {"def": "⒉知道，明白～得。家喻户～。", "example": null}, {"def": "⒊告知～以利弊。", "example": null}]','chinese-xinhua','0'),
('2101143296918163475','筱','1','xiǎo','竹','13',NULL,'[{"def": "筱〈名〉", "example": null}, {"def": "小竹,细竹", "example": null}, {"def": "筱,箭属,小竹也。--《说文》", "example": null}, {"def": "绿筱媚青涟。--谢灵运《过始宁墅》", "example": null}, {"def": "小", "example": null}, {"def": "筱（簊）xiǎo", "example": null}, {"def": "⒈细竹子。", "example": null}, {"def": "⒉同\\"小\\"。多见于人名。", "example": null}]','chinese-xinhua','0'),
('2101143296918163476','肖','1','xiāo','月','7',NULL,'[{"def": "肖", "example": null}, {"def": "姓。萧”字的俗写", "example": null}, {"def": "肖 〈形〉", "example": null}, {"def": "假借为小”。细微", "example": null}, {"def": "肖,小也。--《方言十二》", "example": null}, {"def": "肖翘之物。--《庄子·?箧》", "example": null}, {"def": "达生之情者傀,达于知者肖。--《庄子》", "example": null}, {"def": "又如肖翘(细小能飞的生物)", "example": null}, {"def": "肖 〈动〉", "example": null}, {"def": "假借为消”。消灭;消失;衰退,衰微", "example": null}, {"def": "达于知者肖。--《庄子·列御寇》", "example": null}, {"def": "申吕肖矣,尚父侧微。--《史记·太史公自序》", "example": null}, {"def": "肖", "example": null}, {"def": "(形声。从肉,小声。本义相似,相像)", "example": null}, {"def": "同本义(侧重于本质特点上的相像)", "example": null}, {"def": "肖,骨肉相似也。--《说文》。字亦作俏", "example": null}, {"def": "人俏天地", "example": null}, {"def": "肖xiào", "example": null}, {"def": "⒈相似，类似惟妙惟～。～像（相片，画像）。", "example": null}, {"def": "肖xiāo 1.细微。 2.衰微。《史记．太史公自序》\\"申吕肖矣，尚父侧微。\\"裴髎集解引徐广曰\\"肖音痟。痟犹衰微。\\"一说，削弱。 3.姓。", "example": null}]','chinese-xinhua','0'),
('2101143296918163477','哮','1','xiāo','口','10',NULL,'[{"def": "哮", "example": null}, {"def": "(形声。从口,孝声。本义野兽的吼声)", "example": null}, {"def": "同本义", "example": null}, {"def": "哮,豕惊声也。--《说文》", "example": null}, {"def": "虎声谓之哮唬。--《通俗文》", "example": null}, {"def": "哮阚之兽。--曹植《七启》。注虎怒也。”", "example": null}, {"def": "熊罴哮我东,虎豹号我西。--唐·杜甫《石龛》", "example": null}, {"def": "水声澎湃,兽群哮而游。--《游泸山记》", "example": null}, {"def": "又如哮吼(野兽吼叫);咆哮(吼叫);哮唬(虎啸声);哮阚(猛兽咆哮。多用以比喻震怒)", "example": null}, {"def": "呼喊", "example": null}, {"def": "哮,呼也。--《集韵》", "example": null}, {"def": "又如哮吼(泛指大声喊叫;又指声威震慑);哮唃(嚎啕。大声哭叫);哮悍(形容勇猛强悍)", "example": null}, {"def": "哮", "example": null}, {"def": "哮症的简称", "example": null}, {"def": "治哮治积方。--《丹溪先生心法》", "example": null}, {"def": "又如哮", "example": null}, {"def": "哮xiào", "example": null}, {"def": "⒈吼叫黄河在咆～。", "example": null}, {"def": "⒉", "example": null}, {"def": "哮xiāo 1.兽怒吼。 2.引申指大声喊叫。 3.风浪呼啸。 4.哮喘◆吸道的一种疾病。 5.干性罗音的一种◆吸时伴有口哨样声响。", "example": null}]','chinese-xinhua','0'),
