('2101143296922357774','消','1','xiāo','氵','10',NULL,'[{"def": "消", "example": null}, {"def": "(形声。从水,肖声。本义消除;消灭)", "example": null}, {"def": "同本义", "example": null}, {"def": "消,尽也。--《说文》", "example": null}, {"def": "消息阴阳。--枚乘《七发》。注消,灭也。”", "example": null}, {"def": "消雰埃于中宸。--张衡《西京赋》。注消,散也。”", "example": null}, {"def": "热多则筋弛骨消。--《素问·皮部论》。注消,烁也。”", "example": null}, {"def": "鸟兽之害人者消,然后人得平土而居之。--《孟子》", "example": null}, {"def": "诏求隐学之士能消灾复异者。--《三国志·魏志》", "example": null}, {"def": "娘娘一肚子气没地方散去,借酒消愁。--京剧《贵妃醉酒》", "example": null}, {"def": "又如消索(灭尽,散亡);消炎(消除炎症;消除炎热);消弭(消灭停止)", "example": null}, {"def": "消失,完全不存在", "example": null}, {"def": "内君", "example": null}, {"def": "消xiāo", "example": null}, {"def": "⒈溶解，散失～融。～散。～失。瓦解冰～。", "example": null}, {"def": "⒉除去，灭掉～除。～炎。～毒。～灭。", "example": null}, {"def": "⒊减少，耗费～磨。～耗。～费。", "example": null}, {"def": "⒋排遣，度过～遣。～愁。～夏。", "example": null}, {"def": "⒌需要不～说。只～两天。", "example": null}, {"def": "⒍经得起吃得～。更能～几番风雨。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①不利的，否定的除去～极因素。", "example": null}, {"def": "②不主动，不求进取克服～极态度。", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "⒒", "example": null}]','chinese-xinhua','0'),
('2101143296922357775','绡','1','xiāo','纟','10',NULL,'[{"def": "绡", "example": null}, {"def": "(形声。从糸,肖声。本义生丝或以生丝织成的薄绸子) 同本义", "example": null}, {"def": "绡,生丝也。--《说文》", "example": null}, {"def": "绡幕鲁也。--《礼记·檀弓》", "example": null}, {"def": "曳雾绡之轻裾。--曹植《洛神赋》", "example": null}, {"def": "泉室潜织而卷绡。--左思《吴都赋》", "example": null}, {"def": "半匹红绡一丈绫,系向牛头充炭直。--白居易《卖炭翁》", "example": null}, {"def": "红绡不知数。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "紫鹃放下绡帐,移灯掩门而去。--《红楼梦》", "example": null}, {"def": "又如绡巾(丝巾,薄纱巾);绡衣(用绫绡制成的衣裳)", "example": null}, {"def": "绡xiāo生丝，也指薄的生丝纺织品。", "example": null}, {"def": "绡shāo 1.船上挂帆的木柱。", "example": null}]','chinese-xinhua','0'),
