('2101143296922357788','销','1','xiāo','钅','12',NULL,'[{"def": "销", "example": null}, {"def": "(形声。从金,肖声。本义熔化金属)", "example": null}, {"def": "同本义", "example": null}, {"def": "销,铄金也。--《说文》", "example": null}, {"def": "销车以斗七命。--《淮南子·泛论》", "example": null}, {"def": "收天下兵,聚之咸阳,销以为钟鑜。--《史记·秦始皇本纪》", "example": null}, {"def": "销锋镐。--汉·贾谊《过秦论》", "example": null}, {"def": "今出黄金银物百五十种,千八百余斤,销冶以供军用。--《三国志·魏志》", "example": null}, {"def": "女娲销炼五色石以补苍天。--《论衡·谈天》", "example": null}, {"def": "又如销冶(熔炼,熔铸,熔冶);销炼(熔化冶炼);销钱(熔化钱币)", "example": null}, {"def": "溶化;消融", "example": null}, {"def": "雪霜顿销释,土脉膏且黏。--唐·韩愈《苦寒》", "example": null}, {"def": "一天大事,竟如此瓦解冰销。--《官场现形记》", "example": null}, {"def": "通消”。清失;消除;", "example": null}, {"def": "销xiāo", "example": null}, {"def": "⒈熔化金属，泛指熔化～金。～炼。", "example": null}, {"def": "⒉除去，解除～假。撤～。", "example": null}, {"def": "⒊售，出卖供～。推～。畅～。", "example": null}, {"def": "⒋消费开～。", "example": null}, {"def": "⒌通\\"消\\"。消失，消灭～声匿迹。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎将销子推上把窗子～好。", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
('2101143296922357789','潇','1','xiāo','氵','14',NULL,'[{"def": "潇", "example": null}, {"def": "(形声。从水,萧声。本义水清而深的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "潇者,水清深也。--《水经注》", "example": null}, {"def": "急疾", "example": null}, {"def": "潇", "example": null}, {"def": "水名。潇水", "example": null}, {"def": "潇（瀟）xiāo", "example": null}, {"def": "⒈水清且深。", "example": null}, {"def": "⒉风雨声风雨～ ～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋潇水，在湖南省。", "example": null}]','chinese-xinhua','0'),
('2101143296922357790','箫','1','xiāo','竹','14',NULL,'[{"def": "箫", "example": null}, {"def": "(形声。从竹,肃声。从竹,与乐器有关。本义洞箫,竹制的管乐器)", "example": null}, {"def": "同本义", "example": null}, {"def": "箫,参差管乐也。象凤之翼。--《说文》", "example": null}, {"def": "箫管弦歌。--《周礼·小师》。注编小竹。”", "example": null}, {"def": "若风之过箫。--《淮南子·齐俗》", "example": null}, {"def": "箫,编竹为之。长尺五寸。--《五经通义》", "example": null}, {"def": "秦地吹箫女,湘波鼓瑟妃。--唐·韩愈《梁国惠康公主挽歌》", "example": null}, {"def": "箫韶以随。--唐·李朝威《柳毅传》", "example": null}, {"def": "又如箫韶(大磬。泛指乐器;又指舜的乐曲。借指乐声);箫笛(箫与笛。泛指管乐器)", "example": null}, {"def": "弓", "example": null}, {"def": "箫（簫）xiāo一种管乐器。〈古〉用多个竹管排在一起，叫\\"排箫\\"◇来只用一根竹管，上开小孔，下不封底，直吹，又叫\\"洞箫\\"。", "example": null}, {"def": "箫xiǎo 1.小竹。", "example": null}]','chinese-xinhua','0'),
('2101143296922357791','硝','1','xiāo','石','12',NULL,'[{"def": "硝", "example": null}, {"def": "硝石", "example": null}, {"def": "硝,药石也。方书硝七种。--《正字通》", "example": null}, {"def": "又如硝子石(硝石。又称假水晶;也喻指眼睛);硝云弹雨(硝烟如云,子弹像雨。形容激烈的战斗)", "example": null}, {"def": "经过硝制变软的皮革", "example": null}, {"def": "若南方短毛革硝,其如纸薄。--《天工开物》", "example": null}, {"def": "硝", "example": null}, {"def": "用朴芒硝等鞣制皮革使变软", "example": null}, {"def": "要送到皮园里硝了,赶出来做成坐褥,新年好放在马上骑坐。--《醒世姻缘传》", "example": null}, {"def": "走了硝,天冷怎穿!--《西游记》", "example": null}, {"def": "又如硝熟(用芒硝、朴硝等揉制皮革使之变软)", "example": null}, {"def": "硝xiāo", "example": null}, {"def": "⒈矿物名。某些矿物盐的统称", "example": null}, {"def": "①硝石。无色晶体，成分为硝酸钾，可制火药。", "example": null}, {"def": "②芒硝。又名朴硝，皮硝。无色透明晶体，成分为硫酸钠，并含有硝酸钾、氯化钠等。", "example": null}, {"def": "⒉用芒硝、黄米面等鞣制毛皮～皮。", "example": null}, {"def": "硝qiào 1.坚硬。参见\\"硝瘠\\"。", "example": null}]','chinese-xinhua','0'),
