('2101143296934940684','偕','1','xié','亻','11',NULL,'[{"def": "偕", "example": null}, {"def": "(形声。从人,皆声。本义共同在一起)同本义", "example": null}, {"def": "偕,俱也。--《说文》", "example": null}, {"def": "与雨偕也。--《左传·庄公七年》", "example": null}, {"def": "夙夜必偕。--《诗·魏风·陟岵》", "example": null}, {"def": "故由由然与之偕而不自失焉。--《孟子·公孙丑上》", "example": null}, {"def": "俄人偕英、法、美三国合兵犯天津。--《清史稿·奕山传》", "example": null}, {"def": "偕数友出。--明·袁宏道《满井游记》", "example": null}, {"def": "即偕洋商。--《广东军务记》", "example": null}, {"def": "偕", "example": null}, {"def": "一同;一起", "example": null}, {"def": "宜言饮酒,与子偕老。--《诗·郑风·女日鸡鸣》", "example": null}, {"def": "与子偕行。--《诗·秦风·无衣》", "example": null}, {"def": "客不得已与偕行。--明·魏禧《大铁椎传", "example": null}, {"def": "偕xié共同，一块儿～同。～行。", "example": null}]','chinese-xinhua','0'),
('2101143296934940685','斜','1','xié','斗','11',NULL,'[{"def": "斜", "example": null}, {"def": "(形声。从斗,余声。本义用斗倒出)", "example": null}, {"def": "舀出", "example": null}, {"def": "斜,抒也。--《说文》", "example": null}, {"def": "又如斜酒(舀酒)", "example": null}, {"def": "侧着移动,向偏离正中或正前方的方向移动", "example": null}, {"def": "门子才斜签着坐下。--《葫芦僧判断葫芦案》", "example": null}, {"def": "飞腾暮景斜。--《杜位宅守岁》", "example": null}, {"def": "又如斜签(侧着身子);斜躺(斜着下垂)", "example": null}, {"def": "斜", "example": null}, {"def": "不正,歪斜", "example": null}, {"def": "明月斜挂。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "斜风细雨。--唐·张志和《渔歌子》", "example": null}, {"def": "青山郭外斜。--唐·孟浩然《过故人庄》", "example": null}, {"def": "烟斜雾横。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如斜月三星(心字的隐喻);斜射路(抄近", "example": null}, {"def": "斜xié", "example": null}, {"def": "⒈歪，不正～视。～坡。倾～。", "example": null}, {"def": "⒉", "example": null}, {"def": "斜yé 1.终南山山谷名。在陕西数城县东北。", "example": null}, {"def": "斜chá 1.人名用字。伊稚斜，汉代匈奴单于名。", "example": null}]','chinese-xinhua','0'),
('2101143296934940686','谐','1','xié','讠','11',NULL,'[{"def": "谐", "example": null}, {"def": "(形声。从言,皆声。本义和谐)", "example": null}, {"def": "同本义(强调配合得匀称)", "example": null}, {"def": "谐,和也。--《尔雅》", "example": null}, {"def": "克谐以孝。--《书·尧典》", "example": null}, {"def": "掌司万民之难而谐和之。--《周礼·调人》", "example": null}, {"def": "如乐之和,无所不谐。--《左传·襄公十一年》", "example": null}, {"def": "如其克谐,天下可定也。--《资治通鉴·赤壁之战》", "example": null}, {"def": "夫妻谐老。--《初刻拍案惊奇》", "example": null}, {"def": "又如 谐当(妥当);谐和(各组成部分之间协调地相互联系在一起的);谐调(和谐);谐奏(和协地演奏);谐律(谐合于音律)", "example": null}, {"def": "言语或行为有趣而引人发笑", "example": null}, {"def": "上以朔口谐辞给,好作问之。--《汉书·东方朔传》", "example": null}, {"def": "心亲不复异新旧,使脱", "example": null}, {"def": "谐xié", "example": null}, {"def": "⒈融洽，配合适当～作⊥～。", "example": null}, {"def": "⒉滑稽，谈笑随便诙～。～谈。亦庄亦～。", "example": null}]','chinese-xinhua','0'),
