('2101143296934940720','渫','1','xiè','氵','12',NULL,'[{"def": "渫", "example": null}, {"def": "淘,淘去泥污", "example": null}, {"def": "渫,除去也。从水,枼声。--《说文》", "example": null}, {"def": "井渫不食,为我心恻。--《易·井》", "example": null}, {"def": "排出气体或液体", "example": null}, {"def": "渫之以尾闾。--《文选·江赋》", "example": null}, {"def": "泄漏", "example": null}, {"def": "泰和二年,上以弥封官渫语于举人,敕自今女直司则用右选汉人封,汉人司则以女直司封。--《金史》", "example": null}, {"def": "散布;消散", "example": null}, {"def": "富人有爵,农民有钱,粟有所渫。--《汉书》", "example": null}, {"def": "又如渫云(飘散的云);渫雨(飘洒的雨)", "example": null}, {"def": "姓", "example": null}, {"def": "渫xiè", "example": null}, {"def": "⒈除去，淘去污泥。", "example": null}, {"def": "⒉分散，扩散。", "example": null}, {"def": "⒊歇，停止。", "example": null}, {"def": "渫dié 1.见\\"浃渫\\"。 2.见\\"渫渫\\"。", "example": null}, {"def": "渫zhá 1.在沸水中煮。", "example": null}, {"def": "渫yì 1.蒸葱。", "example": null}]','chinese-xinhua','0'),
('2101143296934940721','亵','1','xiè','亠','12',NULL,'[{"def": "亵", "example": null}, {"def": "(形声。从衣,执声。本义贴身的内衣) 同本义", "example": null}, {"def": "亵,私服也。--《说文》", "example": null}, {"def": "思有短褐之亵。--班固《汉书》", "example": null}, {"def": "季康子之母死,陈亵衣。--《礼记·檀弓下》", "example": null}, {"def": "又如亵衣(私服,家居的便服);亵绊(内衣);亵服(家居所穿的便服);亵裘(平时家居所穿的皮衣)", "example": null}, {"def": "亵", "example": null}, {"def": "轻慢,轻佻地亲近", "example": null}, {"def": "亵,狎也。--《广雅》", "example": null}, {"def": "祭服敝则焚之。--《礼记·曲礼上》。注不欲人亵之。”", "example": null}, {"def": "亵玩焉。(玩弄。亵亲近而不庄重。焉这里相当于现代语的啊”、呀”)。--宋·", "example": null}, {"def": "亵（襝）xiè", "example": null}, {"def": "⒈内衣。", "example": null}, {"def": "⒉轻慢，亲近且不庄重～渎。", "example": null}, {"def": "⒊淫秽，下流行为秽～。猥～", "example": null}]','chinese-xinhua','0'),
('2101143296934940722','谢','1','xiè','讠','12',NULL,'[{"def": "谢", "example": null}, {"def": "(形声。从言,射声。本义向人认错道歉)", "example": null}, {"def": "同本义", "example": null}, {"def": "自谢曰。--《战国策·赵策》", "example": null}, {"def": "长跪而谢。--《战国策·魏策》", "example": null}, {"def": "旦日不可不蚤自来谢项王。--《史记·项羽本纪》", "example": null}, {"def": "惊谢曰。--清·周容《芋老人传》", "example": null}, {"def": "又如谢咎(引咎自退;悔过;谢罪);谢错(认错赔不是);谢室(待罪之室)", "example": null}, {"def": "用言辞委婉地推辞拒绝", "example": null}, {"def": "乃召拜黯为淮阳太守,黯伏谢不受命。--《史记·汲黯列传》", "example": null}, {"def": "谢媒人。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "楚而谢。--唐·李朝威《柳毅传》", "example": null}, {"def": "谢客矣。--明·宗臣《报刘一丈书》", "example": null}, {"def": "谢xiè", "example": null}, {"def": "⒈感激～ ～你。感～。", "example": null}, {"def": "⒉道歉，认错～过。～罪。", "example": null}, {"def": "⒊〈古〉告诉多～后世人。", "example": null}, {"def": "⒋推辞，辞别～绝。～客。", "example": null}, {"def": "⒌衰亡，凋落新陈代～。花～花落。", "example": null}]','chinese-xinhua','0'),
