('2101143296934940762','锌','1','xīn','钅','12',NULL,'[{"def": "锌〈名〉", "example": null}, {"def": "一种蓝白色的晶状的二价金属元素,有低至中等的硬度,纯时有延性,主要用作钢铁的保护性涂层", "example": null}, {"def": "锌白", "example": null}, {"def": "锌版", "example": null}, {"def": "锌xīn金属化学元素。符号zn。青白色，质脆。用于电镀、造黄铜等。锌粉是有机合成工业的一种重要还原剂。氧化锌（锌白）是常用的白色颜料。", "example": null}]','chinese-xinhua','0'),
('2101143296934940763','新','1','xīn','斤','13',NULL,'[{"def": "新〈动〉", "example": null}, {"def": "(形声。从斤,从木,辛声。据甲骨文,左边是木,右边是斧子。指用斧子砍伐木材。本义用斧子砍伐木材。新”是薪”的本字)", "example": null}, {"def": "砍伐树木", "example": null}, {"def": "新,取木也。--《说文》", "example": null}, {"def": "且彼亦知新”之为义乎?衣之始裁为之初”,木之始伐谓之新”。--章炳麟《论承用维新”二字之荒谬》", "example": null}, {"def": "更新,使之新", "example": null}, {"def": "如何新畬。--《诗·周颂·臣工》", "example": null}, {"def": "旧染污俗,咸与唯新。--《书·胤征》", "example": null}, {"def": "又如新民(使民更新);新美(刷新使之美好);新醮(改嫁);新梢(新长出的树梢)", "example": null}, {"def": "新 〈形〉", "example": null}, {"def": "初次出现。与旧”相对", "example": null}, {"def": "于彼新田。--《", "example": null}, {"def": "新xīn", "example": null}, {"def": "⒈初出现或初产生的～生。～事物。～技术。", "example": null}, {"def": "⒉好的，进步的～风尚。～社会。", "example": null}, {"def": "⒊刚有的，还未用过的，跟\\"旧\\"相对～钢笔。～事。～方法。", "example": null}, {"def": "⒋刚才，最近～来。～近。", "example": null}, {"def": "⒌称结婚时的人或物～娘。～房。", "example": null}, {"def": "⒍新疆维吾尔自治区的简称。", "example": null}, {"def": "⒎", "example": null}]','chinese-xinhua','0'),
('2101143296934940764','歆','1','xīn','欠','13',NULL,'[{"def": "歆〈动〉", "example": null}, {"def": "飨,嗅闻", "example": null}, {"def": "其香始升,上帝居歆。--《诗·大雅》", "example": null}, {"def": "又如歆享(歆止,歆飨。神灵享受供物);歆嗅(歆飨);歆尝(神灵享用祭品)", "example": null}, {"def": "动", "example": null}, {"def": "无然歆羡。--《诗·大雅·皇矣》。朱熹集传歆,欲之动也。”", "example": null}, {"def": "以弗无子,履帝武敏歆。--《诗·大雅·生民》", "example": null}, {"def": "又如歆动(触动;惊动)", "example": null}, {"def": "贪图;羡慕", "example": null}, {"def": "若易中下,楚必歆之。--《国语·楚语上》", "example": null}, {"def": "又如歆美(钦羡赞美);歆淫(纵乐);歆叹(钦羡赞叹)", "example": null}, {"def": "歆 〈形〉", "example": null}, {"def": "悦服;欣喜", "example": null}, {"def": "以言德于民,民歆而德之,则归心焉。--《国语·周语下》", "example": null}, {"def": "又如歆服(", "example": null}, {"def": "歆xīn欣喜，羡慕～羡。", "example": null}]','chinese-xinhua','0'),
