('2101143296934940766','薪','1','xīn','艹','16',NULL,'[{"def": "薪〈名〉", "example": null}, {"def": "同本义", "example": null}, {"def": "薪,荛也。--《说文》", "example": null}, {"def": "收秩薪柴。--《礼记·月令》。注大者可析谓之薪。”", "example": null}, {"def": "薪蒸材木。--《周礼·委人》。注粗者曰薪,细者曰蒸。”", "example": null}, {"def": "以薪以蒸。--《诗·小雅·无羊》", "example": null}, {"def": "农夫得居装而卖其薪荛。--《管子·轻重甲》", "example": null}, {"def": "某有负薪之忧。--《礼记·曲礼》", "example": null}, {"def": "毁伤其薪木。--《孟子》", "example": null}, {"def": "顾野有麦场,场主积薪其中。--《聊斋志异·狼三则》", "example": null}, {"def": "又如薪火(柴火);薪桂(薪贵于桂。形容柴火昂贵);薪柴(柴火);薪樵(柴火)", "example": null}, {"def": "可以劈开来用的粗大木柴", "example": null}, {"def": "明足察秋毫之末,而不见舆薪。--《孟", "example": null}, {"def": "薪xīn", "example": null}, {"def": "⒈柴草，柴火釜底抽～。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296934940767','馨','1','xīn','香','20',NULL,'[{"def": "馨〈形〉", "example": null}, {"def": "(形声。从香,殸声。殸,籀文磬”。本义芳香,散布很远的香气)", "example": null}, {"def": "同本义", "example": null}, {"def": "馨,香之远闻者也。--《说文》", "example": null}, {"def": "其德足以昭其馨香。--《国语·周语》", "example": null}, {"def": "丹木五岁五味乃馨成。--《山海经·西山经》", "example": null}, {"def": "尔酒既清,尔淆既馨。--《诗·大雅·凫鷖》。毛传馨,香之远闻也。”", "example": null}, {"def": "惟吾德馨。--唐·刘禹锡《陋室铭》", "example": null}, {"def": "又如馨烈(芳香浓烈);馨逸(香气洋溢;芳香远播)", "example": null}, {"def": "比喻声誉流芳后世", "example": null}, {"def": "化盛隆周,垂馨千祀。--《晋书》", "example": null}, {"def": "又如馨烈(比喻流芳的事业);馨德(芳馨久传的美德和教化)引申为美", "example": null}, {"def": "黍", "example": null}, {"def": "馨xīn散布出很远的香气。泛指芳香～香。〈喻〉好的道德或声誉垂～千祀（祀年）。", "example": null}]','chinese-xinhua','0'),
('2101143296934940768','鑫','1','xīn','金','24',NULL,'[{"def": "鑫", "example": null}, {"def": "旧时商店字号、人名用字,取其金多兴旺之意", "example": null}, {"def": "鑫,金长。--《篇海类编》", "example": null}, {"def": "鑫,宋子虚名友,五子以鑫、森、淼、焱、垚立名。--《正字通》", "example": null}, {"def": "鑫xīn金多。兴旺之义。多见于人名或商店字号。", "example": null}]','chinese-xinhua','0'),
