('2101143296939134979','忻','1','xīn','忄','7',NULL,'[{"def": "忻〈动>", "example": null}, {"def": "(形声。从心,斤声。本义启发)", "example": null}, {"def": "同本义", "example": null}, {"def": "忻,闿也。--《说文》", "example": null}, {"def": "善者,忻民之善,闭民之恶。--《司马法》", "example": null}, {"def": "姜原出野,见巨人迹,心忻然说,欲践之。--《史记·周本纪》", "example": null}, {"def": "明察", "example": null}, {"def": "忻,察也。--《玉篇》", "example": null}, {"def": "忻", "example": null}, {"def": "假借为欣”。心喜", "example": null}, {"def": "姜原出野,见巨人迹,心忻然悦。--《史记·周本纪》", "example": null}, {"def": "忻忻然常自以为治。--《淮南子·览冥》。注得意之貌也。”", "example": null}, {"def": "又如忻幸(欣幸,欣喜而庆幸);忻悦(欣喜);忻然(喜悦貌;愉快貌);忻慰(欣慰);忻戚(悲喜);忻悚(喜悦与惶恐)", "example": null}, {"def": "忻xīn喜悦，快乐～喜。～赏。～然同意。欢～鼓舞。", "example": null}, {"def": "①高兴的样子～ ～然喜形于色。", "example": null}, {"def": "②草木旺盛的样子～ ～向荣。", "example": null}]','chinese-xinhua','0'),
('2101143296939134980','芯','1','xīn','艹','7',NULL,'[{"def": "芯〈名〉", "example": null}, {"def": "灯心草茎中的髓,俗称灯芯”", "example": null}, {"def": "家有千金,不添双芯,俭之积也。--光绪年修《黄岩县志》", "example": null}, {"def": "另见豸??餇", "example": null}, {"def": "芯铁", "example": null}, {"def": "芯线", "example": null}, {"def": "芯", "example": null}, {"def": "物体的中心部分", "example": null}, {"def": "芯子", "example": null}, {"def": "蜡烛芯子", "example": null}, {"def": "芯xìn", "example": null}, {"def": "⒈物体的中心部分矿～。岩～。", "example": null}, {"def": "⒉", "example": null}, {"def": "①装在某些东西中心的捻子蜡烛～子。", "example": null}, {"def": "②蛇的舌头。", "example": null}, {"def": "芯xīn灯心草去皮后的髓灯～。", "example": null}]','chinese-xinhua','0'),
('2101143296939134981','辛','1','xīn','辛','7',NULL,'[{"def": "辛〈名〉", "example": null}, {"def": "(象形。据甲骨文,像古代刑刀。本义大罪)", "example": null}, {"def": "同本义", "example": null}, {"def": "辛,大罪也。--《说文》。段注辛痛泣出,罪人之象。凡辠(罪)、宰、辜、辭皆从辛者由此。”", "example": null}, {"def": "辛所以煞伤之也。--《白虎通》", "example": null}, {"def": "葱蒜等带刺激性的蔬菜", "example": null}, {"def": "以辛养筋。--《周礼·疡医》", "example": null}, {"def": "辛甘行些。--《楚辞·招魂》。注谓椒姜也。”", "example": null}, {"def": "江南曰辣,中国曰辛。--《声类》", "example": null}, {"def": "大蒜勿食,荤辛害目。--《养生要》李善注", "example": null}, {"def": "五辛菜,乃元旦立春,以葱、蒜、韭、蓼、蒿、芥辛嫩之菜,杂和食之,", "example": null}, {"def": "辛xīn", "example": null}, {"def": "⒈辣～味。", "example": null}, {"def": "⒉劳苦，艰难～劳。～苦。艰～。千～万苦。", "example": null}, {"def": "⒊悲伤～酸。悲～。", "example": null}, {"def": "⒋天干第八位，也作次序第八。", "example": null}]','chinese-xinhua','0'),
('2101143296939134982','昕','1','xīn','日','8',NULL,'[{"def": "昕〈名〉", "example": null}, {"def": "(形声。从日,斤声。本义黎明) 同本义", "example": null}, {"def": "昕,旦明日将出也。--《说文》", "example": null}, {"def": "明日迟昕,帝出延秋门。--《新唐书》", "example": null}, {"def": "又如昕旦(黎明);昕夕(朝暮)", "example": null}, {"def": "昕 〈形〉", "example": null}, {"def": "明亮", "example": null}, {"def": "昕,明也。--《小尔雅》", "example": null}, {"def": "大昕鼓徵。--《礼记·文王世子》", "example": null}, {"def": "及大昕之朝。--《礼记·祭义》", "example": null}, {"def": "檀车孔夏,四騵孔昕。--《初学记》引《太仆箴》", "example": null}, {"def": "又如昕昕(明亮的样子)", "example": null}, {"def": "昕xīn拂晓，太阳将要升起的时候。", "example": null}, {"def": "昕xuān 1.高低貌。参见\\"昕天\\"。", "example": null}]','chinese-xinhua','0'),
