('2101143296939134987','刑','1','xínɡ','刂','6',NULL,'[{"def": "刑", "example": null}, {"def": "同本义", "example": null}, {"def": "利用刑人。--《易·蒙》。注兑折为刑。”", "example": null}, {"def": "刑人之父子也。--《吕氏春秋·顺说》。注杀也。”", "example": null}, {"def": "杀戮之谓刑。--《韩非子·二柄》", "example": null}, {"def": "阴为刑。--《易·本命》", "example": null}, {"def": "阴将始刑。--《吕氏春秋·音律》。注杀也。”", "example": null}, {"def": "刑人如恐不胜。--《史记·项羽本纪》", "example": null}, {"def": "刑马作誓。--南朝梁·丘迟《与陈伯之书》", "example": null}, {"def": "膑至,庞涓恐其贤于己,疾之,则以法刑断其两足而黥之。--《史记》", "example": null}, {"def": "又如刑牛(古代盟誓时作牺牲用的牛);刑牲(古时为了祭祀或盟约而杀牲畜);刑马(古代结盟要杀马歃血,立誓为信,称刑马”)", "example": null}, {"def": "惩罚", "example": null}, {"def": "刑xíng", "example": null}, {"def": "⒈刑罚，对犯人各种处罚的总称定～。徒～。死～。", "example": null}, {"def": "⒉特指对犯人的栲打、折磨等体罚～讯。动～。", "example": null}]','chinese-xinhua','0'),
('2101143296939134988','行','1','xínɡ','行','6',NULL,'[{"def": "行〈名〉hang", "example": null}, {"def": "(象形。本义道路)", "example": null}, {"def": "同本义", "example": null}, {"def": "行,道也。--《说文》", "example": null}, {"def": "行有死人。--《诗·小雅·小弁》", "example": null}, {"def": "遵彼微行。--《诗·豳风·七月》", "example": null}, {"def": "又如行苇(路旁芦苇);行阡(道路);行神(路神);行程(路程);行街(大路)", "example": null}, {"def": "直排为行,横排为列", "example": null}, {"def": "左右陈行,戒我师旅。--《诗·大雅·常武》", "example": null}, {"def": "凌余阵兮躐余行。--《楚辞·九歌·国殇》", "example": null}, {"def": "奉读书,五行并下。--《后汉书·应奉传》", "example": null}, {"def": "军队编制,二十五人为一行", "example": null}, {"def": "郑伯使卒出貑,行出犬鸡。--《左传·隐公十一年》", "example": null}, {"def": "队伍,军队", "example": null}, {"def": "陈胜、吴广皆次当行。--《史记·陈涉世家》", "example": null}, {"def": "行háng", "example": null}, {"def": "⒈排，队列～列♂～。", "example": null}, {"def": "⒉兄弟、姐妹长幼的次序你～几？我～二。", "example": null}, {"def": "⒊职业同～。内～。干一～，爱一～。", "example": null}, {"def": "⒋某些商店或营业性机构寄卖～。农业银～。", "example": null}, {"def": "⒌量词。成行的写两～字。栽三～树。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏见xíng。", "example": null}, {"def": "行xíng", "example": null}, {"def": "⒈走～走。～路。～军。远～。", "example": null}, {"def": "⒉跟出行有关的～装。～李。旅～社。", "example": null}, {"def": "⒊做，办事，活动，举动～事。～为。～动。～医。试～。执～。进～。举～。", "example": null}, {"def": "⒋品质，品德言～。品～。罪～。", "example": null}, {"def": "⒌将要～将就业。", "example": null}, {"def": "⒍可以这样做也～。", "example": null}, {"def": "⒎能干她真～。", "example": null}, {"def": "⒏流通，传递通～。推～。发～书报刊物。", "example": null}, {"def": "⒐流动的，临时的～商。～营。", "example": null}, {"def": "⒑乐府和古诗的一种体裁长干～。兵车～。", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "⒔", "example": null}, {"def": "⒕", "example": null}, {"def": "①行使国家权力的～政机关。", "example": null}, {"def": "②有关行政事务的～政人员。～政经费。", "example": null}, {"def": "行hàng 1.刚强貌。参见\\"行行\\"。 2.见\\"树行子\\"。", "example": null}, {"def": "行héng 1.口语中称僧道修行的功夫。参见\\"行望\\"﹑\\"道行\\"。", "example": null}]','chinese-xinhua','0'),
