('2101143296939134990','形','1','xínɡ','彡','7',NULL,'[{"def": "形", "example": null}, {"def": "同本义", "example": null}, {"def": "形,象形也。--《说文》", "example": null}, {"def": "物成生理谓之形。--《庄子·天地》", "example": null}, {"def": "雷雨之动满形。--《易·屯》", "example": null}, {"def": "在天成象,在地成形。--《礼记·乐记》", "example": null}, {"def": "形色天性也。--《孟子》", "example": null}, {"def": "形者,生之具也。--《史记·太史公自序》", "example": null}, {"def": "良马可形容筋骨相也。--《列子·说符》", "example": null}, {"def": "形似酒尊。--《后汉书·张衡传》", "example": null}, {"def": "鸟兽之形。", "example": null}, {"def": "形若土狗。--《聊斋志异·促织》", "example": null}, {"def": "因势象形。--明·魏学洢《核舟记》", "example": null}, {"def": "又如形物(有形之物);条形;线形;方形;圆形;球形;梯形;三角形;正方形;多角形;多边形;口形;体形", "example": null}, {"def": "形体,实体", "example": null}, {"def": "可以隐形。--三", "example": null}, {"def": "形xíng", "example": null}, {"def": "⒈样子～状。方～。地～。", "example": null}, {"def": "⒉体，实体～体。～影相随。又指容色，容貌面～。", "example": null}, {"def": "⒊表现，表露喜～于色。", "example": null}, {"def": "⒋对照，对比相～见绌。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "①形状和神态～态生动。", "example": null}, {"def": "②事物在一定条件下的表现形式物质～态。", "example": null}, {"def": "⒎", "example": null}, {"def": "①事物的状态、结构～式优美。", "example": null}, {"def": "②只图表面，不顾实际、效果流于～式。", "example": null}, {"def": "⒏", "example": null}, {"def": "①地势。", "example": null}, {"def": "②事物发展的状况和趋势国内外～势。", "example": null}, {"def": "⒐", "example": null}, {"def": "①形体容貌。", "example": null}, {"def": "②对事物的描述难以～容。", "example": null}, {"def": "⒑", "example": null}]','chinese-xinhua','0'),
('2101143296939134991','陉','1','xínɡ','阝','7',NULL,'[{"def": "陉", "example": null}, {"def": "山脉中断的地方", "example": null}, {"def": "山绝陉。--《尔雅·释山》。注连山中断绝。”", "example": null}, {"def": "盘互长干有绝陉,并包佳丽入江亭。--宋·王安石《雨花台》", "example": null}, {"def": "赵(希)与之陉,合军曲阳,攻取丹丘、华阳、鸱之塞。--《史记·赵世家》。集解常山有井陉,中山有苦陉。”", "example": null}, {"def": "太行山首始于河内,北至幽州,凡有八陉,是山凡中断皆曰陉。--《述征记》", "example": null}, {"def": "又如陉岘(山谷与山岭);陉阻(断崖险碍的地方)", "example": null}, {"def": "灶边承放器物处的形状、样子", "example": null}, {"def": "祀灶之礼,设主于灶陉。--《礼记·月令》郑玄注", "example": null}, {"def": "斜坡", "example": null}, {"def": "膺峭袘,腹陉阻。--马", "example": null}, {"def": "陉（陘）xíng", "example": null}, {"def": "⒈山口，山脉中断的地方。", "example": null}, {"def": "⒉灶边放东西的土台。", "example": null}, {"def": "陉jìng 1.狭窄的通道。", "example": null}]','chinese-xinhua','0'),
