('2101143296939134996','硎','1','xínɡ','石','11',NULL,'[{"def": "硎", "example": null}, {"def": "(形声。从石,刑声。本义磨刀石)", "example": null}, {"def": "同本义", "example": null}, {"def": "刀刃若新发于硎。--《庄子·养生主》", "example": null}, {"def": "胡不砺刃于硎以待?--明·马中锡《中山狼传》", "example": null}, {"def": "通铏”。盛食物的器皿", "example": null}, {"def": "衣布褐,饭土硎。--《盐铁论》", "example": null}, {"def": "用同型”。仪型;式样", "example": null}, {"def": "毋劳逖听,请从近硎。--明·钱肃乐《两试序》", "example": null}, {"def": "硎", "example": null}, {"def": "磨", "example": null}, {"def": "斩材竨坚,液矿硎鋩。--唐·刘禹锡《天论上》", "example": null}, {"def": "硎xíng磨刀石。", "example": null}, {"def": "硎kēng 1.石。 2.同\\"坑\\"。", "example": null}]','chinese-xinhua','0'),
