('2101143296939135022','惺','1','xīnɡ','忄','12',NULL,'[{"def": "惺", "example": null}, {"def": "聪明", "example": null}, {"def": "骨谗犹可忏,舌惺岂不悔。--明·袁宏道《靳尚祠》", "example": null}, {"def": "又如惺惺惜惺惺(聪明人爱惜聪明人。意谓性格、才能或境遇相同的相互爱惜、同情)", "example": null}, {"def": "惺", "example": null}, {"def": "领会", "example": null}, {"def": "俺如今已惺,也学的寡情。--明·冯惟敏《朝天子》", "example": null}, {"def": "又如惺悟(领会)", "example": null}, {"def": "清醒", "example": null}, {"def": "一声寒雁叫,唤起未惺人。--《五灯会元》", "example": null}, {"def": "惺xīng", "example": null}, {"def": "⒈聪明，醒悟。", "example": null}, {"def": "⒉", "example": null}, {"def": "①假充聪明。", "example": null}, {"def": "②假装善良。［惺惺作态］（惺惺假意，假惺惺）形容装模作样，故作姿态。", "example": null}]','chinese-xinhua','0'),
('2101143296939135023','猩','1','xīnɡ','犭','12',NULL,'[{"def": "猩", "example": null}, {"def": "猩猩的省称", "example": null}, {"def": "鲜红色", "example": null}, {"def": "俄而大轿内抬着一个乌帽猩袍的官府来了。--《红楼梦》", "example": null}, {"def": "猩xīng", "example": null}]','chinese-xinhua','0'),
