('2101143296939135029','胸','1','xiōnɡ','月','10',NULL,'[{"def": "胸", "example": null}, {"def": "(形声。从肉,匈声。本作匈”,胸是后起字。本义胸膛)", "example": null}, {"def": "同本义", "example": null}, {"def": "胸满腹胀。--《素问·腹中论》", "example": null}, {"def": "两手紧抱胸前。--宋·宋慈《洗冤录》", "example": null}, {"def": "又如胸雪(雪白的胸部。倒文。多见于五代词)", "example": null}, {"def": "内心;心里", "example": null}, {"def": "忧苦欲何为,缠绵胸与臆。--晋·陆机《赴洛》", "example": null}, {"def": "又如胸衾(胸怀;胸襟);胸藏锦绣(比喻富有才识);胸藏翰墨(比喻极有学识);胸中大有丘壑(比喻思虑深远;亦作胸中有了丘壑)", "example": null}, {"def": "喻指前面", "example": null}, {"def": "胸（胷）xiōng", "example": null}, {"def": "⒈人和动物躯干的一部分，在头颈和腹部之间～部。～膛。", "example": null}, {"def": "⒉指心里（跟气量、见识等有关）～襟。～怀。心～开朗。～有成竹。～怀祖国，放眼世界。", "example": null}]','chinese-xinhua','0'),
('2101143296939135030','凶','1','xiōnɡ','凵','4',NULL,'[{"def": "凶", "example": null}, {"def": "(指事。小篆字形,凵”象地陷形。乿”表示这里可陷人。兇”是会意字,从儿(人),在凶下。本义不吉利)", "example": null}, {"def": "同本义", "example": null}, {"def": "凶,恶也。象地穿交陷其中也。--《说文》", "example": null}, {"def": "凶,咎也。--《尔雅》", "example": null}, {"def": "吉凶者,言乎其得也。--《易·系辞》", "example": null}, {"def": "一曰凶短折。--《书·洪范》", "example": null}, {"def": "日月告凶。--《诗·小雅·十月之交》。笺告天下以凶亡之徵也。”", "example": null}, {"def": "此孰吉孰凶?”--《楚辞·卜居》", "example": null}, {"def": "又如凶兆(不祥的预兆);凶宿(凶星);吉凶未卜;凶星(不吉祥的星)", "example": null}, {"def": "凶恶可怕", "example": null}, {"def": "作凶事,为凶人。--《左传·昭公二年》", "example": null}, {"def": "顽凶", "example": null}, {"def": "凶xiōng", "example": null}, {"def": "⒈不吉祥，不幸的～多吉少。又多指死丧～讯。～事。～服。", "example": null}, {"def": "⒉庄稼收成不好～年。", "example": null}, {"def": "⒊恶，残暴，狠毒～恶。～残。～狠。～相毕露。", "example": null}, {"def": "⒋关于杀伤的～器。～手。行～。", "example": null}, {"def": "⒌厉害，过甚病情～险。吵得太～。", "example": null}]','chinese-xinhua','0'),
('2101143296939135031','兄','1','xiōnɡ','儿','5',NULL,'[{"def": "兄", "example": null}, {"def": "(会意。据甲骨文,上为口”,下为匍伏的人。小篆从口,从儿(人)。象一人在对天祈祷,是祝”的本字。本义兄长)", "example": null}, {"def": "同本义", "example": null}, {"def": "兄,长也。--《说文》", "example": null}, {"def": "男子先生为兄。--《尔雅》", "example": null}, {"def": "兄及弟矣,式相好矣。--《诗·小雅·斯干》", "example": null}, {"def": "又如乃兄(你的哥哥);令兄(尊兄,尊称对方的哥哥);愚兄(哥哥自己谦称);家兄(谦称自己的哥哥)", "example": null}, {"def": "亲戚中同辈男性中年龄比自己大的", "example": null}, {"def": "表兄下马步堤岸,上船拜吾兄。--唐·韩愈《此日足可惜赠张籍》", "example": null}, {"def": "又如表兄;内兄;姻克;堂兄", "example": null}, {"def": "对他人的尊称", "example": null}, {"def": "兄知之,勿为他人言也。--柳宗元《与", "example": null}, {"def": "兄xiōng", "example": null}, {"def": "⒈哥哥吾～。", "example": null}, {"def": "⒉敬词老～。仁～。赵～。", "example": null}, {"def": "⒊", "example": null}, {"def": "①弟弟。", "example": null}, {"def": "②兄和弟。", "example": null}, {"def": "③有亲密关系的亲如～弟。～弟之邦。", "example": null}, {"def": "兄kuàng 1.滋，更加。 2.引申为旷远，广大。 3.何况。", "example": null}]','chinese-xinhua','0'),
('2101143296939135032','兇','1','xiōnɡ','','5',NULL,'[{"def": "兇xiōng", "example": null}, {"def": "⒈恶，残暴，狠毒～恶。～残。～狠。～相毕露。", "example": null}, {"def": "⒉关于杀伤的～器。～手。行～。", "example": null}, {"def": "⒊厉害，过甚病情～险。吵得太～。", "example": null}]','chinese-xinhua','0'),
('2101143296939135033','匈','1','xiōnɡ','勹','6',NULL,'[{"def": "匈", "example": null}, {"def": "(形声。从勹,凶声。勹,裹。本义胸膛)", "example": null}, {"def": "胸”的古字", "example": null}, {"def": "匈,膺也。--《说文》。字亦作胷、作胸", "example": null}, {"def": "胸满。--《素问·腹中论》", "example": null}, {"def": "贯匈国。其为人胸有窍。--《海内南经》", "example": null}, {"def": "心胸;胸怀", "example": null}, {"def": "吾素刚急,有匈中气,不可不顺也。--《资治通鉴》", "example": null}, {"def": "又如匈臆(胸怀)", "example": null}, {"def": "匈xiōng", "example": null}, {"def": "⒈〈古〉同\\"胸\\"。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
