('2101143296939135070','羞','1','xiū','羊','10',NULL,'[{"def": "羞", "example": null}, {"def": "(会意兼形声。据甲骨文,以手持羊,表示进献。小篆从羊,从丑,丑亦声。丑”是手的讹变。本义进献)", "example": null}, {"def": "同本义", "example": null}, {"def": "羞,进献也。从羊,羊所进也。--《说文》", "example": null}, {"def": "以式法掌祭祀之戒具,与其荐羞。--《周礼·宰夫》。注庶羞,内羞”。按,内羞,房中之羞也。", "example": null}, {"def": "共其笾荐羞之实。--《周礼·笾人》。注荐羞皆进也。”", "example": null}, {"def": "可荐于鬼神,可羞于王公。--《左传》", "example": null}, {"def": "又如羞豆(古代祭祀宴享时进献食物的一种盛器);羞膳(进献食品)", "example": null}, {"def": "推荐;进用", "example": null}, {"def": "有武德以羞为正卿。--《国语·晋语九》", "example": null}, {"def": "假借为丑”。感到耻辱", "example": null}, {"def": "或承之羞", "example": null}, {"def": "羞xiū", "example": null}, {"def": "⒈害臊，难为情，使难为情～怯。～人答答。别～她。", "example": null}, {"def": "⒉感到耻辱～愧。～惭。～与为伍。", "example": null}, {"def": "⒊进献～玉芝（芝灵芝草）。", "example": null}, {"def": "⒋美好的食物珍～。", "example": null}]','chinese-xinhua','0'),
('2101143296939135071','修','1','xiū','亻','9',NULL,'[{"def": "修", "example": null}, {"def": "(形声。从彡,攸声。彡”有装饰义。本义修饰,装饰)", "example": null}, {"def": "同本义", "example": null}, {"def": "修,饰也。--《说文》", "example": null}, {"def": "义之修而礼之藏也。--《礼记·礼运》。注犹饰也。”", "example": null}, {"def": "美要眇兮宜修。--《楚辞》", "example": null}, {"def": "以修敬也。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "又如修容(整饰容貌);修词(修饰词句。亦指作文;文辞);修饰边幅(形容注意仪容、衣着祳恼);修娖(整理修补)", "example": null}, {"def": "整修;修理", "example": null}, {"def": "古不修墓。--《礼记·檀弓》", "example": null}, {"def": "修橹辪辒。--《孙子·谋攻》", "example": null}, {"def": "修守战之具。--汉·贾谊《过秦论》", "example": null}, {"def": "吾妻死,室坏不修。--归有光《项脊轩志》", "example": null}, {"def": "又如修娖(整理", "example": null}, {"def": "修（脩）xiū", "example": null}, {"def": "⒈装饰，使完善或恢复完善～饰。～理。～道路。～汽车。", "example": null}, {"def": "⒉整治，建筑～治。～建。～守战之具。重～岳阳楼。", "example": null}, {"def": "⒊学习，钻研自～。进～。", "example": null}, {"def": "⒋著作，撰写～史。～订。～书（又指写信）。", "example": null}, {"def": "⒌高，长～短合度（度标准）。茂林～竹。", "example": null}, {"def": "⒍善，美好～态。", "example": null}, {"def": "修yǒu 1.古代酒器。", "example": null}, {"def": "修dí 1.洗濯。", "example": null}, {"def": "修tiáo 1.纲目。 2.古县名『置，属冀州信都国，《汉书．地理志下》\\"修，莽曰修治。\\"颜师古注\\"修，音条。\\"", "example": null}]','chinese-xinhua','0'),
('2101143296939135072','咻','1','xiū','口','9',NULL,'[{"def": "咻", "example": null}, {"def": "嘘气;喘气", "example": null}, {"def": "众口同一咻。--清·黄遵宪《纪事》", "example": null}, {"def": "又如咻气(呼气;喘气)", "example": null}, {"def": "咻 象", "example": null}, {"def": "形容喘气声或某些动物的叫声", "example": null}, {"def": "草中咻咻有寒兔,孤隼下击千丈驰。--苏轼《江上值雪》", "example": null}, {"def": "又如咻咻", "example": null}, {"def": "咻咻", "example": null}, {"def": "形容喘气声", "example": null}, {"def": "咻咻的喘气", "example": null}, {"def": "形容某些动物的叫声", "example": null}, {"def": "小鸭咻咻地叫着", "example": null}, {"def": "咻xiū", "example": null}, {"def": "⒈吵，乱说话。", "example": null}, {"def": "⒉", "example": null}, {"def": "咻xǔ 1.病吟声或抚慰病者声。参见\\"咻噢\\"﹑\\"噢咻\\"。", "example": null}, {"def": "咻xù 1.温暖;温和。", "example": null}]','chinese-xinhua','0'),
('2101143296939135073','庥','1','xiū','广','9',NULL,'[{"def": "庥", "example": null}, {"def": "覆盖", "example": null}, {"def": "庥,荫也。--《释言》", "example": null}, {"def": "又如庥映(遮盖)", "example": null}, {"def": "庇护", "example": null}, {"def": "武当建天玄宝殿,以报神庥。--《英烈传》", "example": null}, {"def": "又如庥庇(荫庇,庇护);庥荫(保护;福祐)", "example": null}, {"def": "同休”。止息", "example": null}, {"def": "庥xiū", "example": null}, {"def": "⒈庇荫，保护。", "example": null}, {"def": "⒉美善，喜庆，福禄。", "example": null}]','chinese-xinhua','0'),
