('2101143296939135075','訏','1','xu','言','10',NULL,'[{"def": "訏", "example": null}, {"def": "诡诈", "example": null}, {"def": "訏,詭譮也。从言,于声。--《说文》", "example": null}, {"def": "犯则凌人,訏则诬人,伐则掩人。--《新书》", "example": null}, {"def": "大", "example": null}, {"def": "且往观乎?洧之外,洵訏且乐!--《诗·郑风》。毛传訏,大也。”", "example": null}, {"def": "又如訏訏(广大的样子);訏谟(重大的谋略);訏策(大计长策);訏猷(宏图远谋);訏谋(远大宏伟的谋划)", "example": null}, {"def": "砉huā", "example": null}, {"def": "⒈像声词。形容迅速动作所发出的声音雄鸡～的一声飞上墙了。", "example": null}, {"def": "砉xū", "example": null}, {"def": "⒈皮肉与骨脱离声。", "example": null}]','chinese-xinhua','0'),
('2101143296939135076','蓿','1','xu','艹','14',NULL,'[{"def": "见苜蓿”见苜”字注", "example": null}, {"def": "蓿 xu［苜蓿］多年生草本植物,叶子长圆形，花紫色，果实为荚果。可以喂牲口、做肥料，嫩苗可以吃。", "example": null}, {"def": "蓿xù 1.见\\"苜蓿\\"。", "example": null}, {"def": "蓿sù 1.见\\"苜蓿\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296939135077','徐','1','xú','彳','10',NULL,'[{"def": "徐", "example": null}, {"def": "(形声。从彳,余声。双人旁与行走有关。本义慢步走)", "example": null}, {"def": "同本义", "example": null}, {"def": "徐,安行也。--《说文》", "example": null}, {"def": "乃徐有说。--《易·困》。虞注坤为徐。”", "example": null}, {"def": "徐其攻而留其日。--《战国策·宋策》", "example": null}, {"def": "故其疾如风,其徐如林。--《孙子·军争》", "example": null}, {"def": "摄提运衡,徐至于射宫。--《文选·张衡·东京赋》", "example": null}, {"def": "散开", "example": null}, {"def": "執徐之岁,岁早旱,晚水。--《淮南子》", "example": null}, {"def": "徐", "example": null}, {"def": "缓慢", "example": null}, {"def": "不徐不疾,得之于手而应于心。--《庄子·天道》", "example": null}, {"def": "入而徐趋。--《战国策·赵策》", "example": null}, {"def": "此事当徐议之。--《宋史》", "example": null}, {"def": "徐有得也。--唐·韩愈《朱文公校昌黎", "example": null}, {"def": "徐xú缓慢，慢慢地不～不疾（疾快）。～ ～而行。栩xǔ", "example": null}, {"def": "⒈栎树，也叫\\"柞树\\"。", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
('2101143296939135078','煦','1','xù','灬','13',NULL,'[{"def": "煦", "example": null}, {"def": "(形声。从火,昫声。本义温暖;暖和)", "example": null}, {"def": "同本义", "example": null}, {"def": "煦,蒸也。一曰赤貌。一曰温润也。--《说文》", "example": null}, {"def": "煦,温也。--《广韵》", "example": null}, {"def": "煦而为阳春,散而为霖雨。--宋·王禹偁《送柴侍御赴阙序》", "example": null}, {"def": "晨烟暮霭,春煦秋阳。--颜延之《陶征士诔》", "example": null}, {"def": "又如煦风(暖风;和风);煦润(温暖滋润)", "example": null}, {"def": "和乐的样子", "example": null}, {"def": "伤夷受煦。--柳宗元《为裴中丞贺克东平赦表》", "example": null}, {"def": "又如煦愉(温煦,和悦);煦濡(温和;惠爱)", "example": null}, {"def": "煦", "example": null}, {"def": "日出时的霞光", "example": null}, {"def": "景光之人煦若射。--《墨子·经说下》", "example": null}, {"def": "恩惠", "example": null}, {"def": "堂侄余庆,承煦绍宗。--唐玄宗《诫励宗室诏》", "example": null}, {"def": "煦（昫）xù温暖～日⊥～。春～百花开。", "example": null}]','chinese-xinhua','0'),
('2101143296943329280','蓄','1','xù','艹','13',NULL,'[{"def": "蓄", "example": null}, {"def": "(形声。从苃,畜声。本义积聚,储藏)", "example": null}, {"def": "同本义", "example": null}, {"def": "蓄,积也。--《说文》", "example": null}, {"def": "蓄,聚也。--《广雅》", "example": null}, {"def": "我有旨蓄,亦以御冬。--《诗·邶风·谷风》", "example": null}, {"def": "洪恩素蓄。--张衡《东京赋》", "example": null}, {"def": "蓄积者,天下之太命也。--《贾子·无蓄》", "example": null}, {"def": "无三年之蓄。--《礼记·王制》", "example": null}, {"def": "蓄积索,田畴荒。--《韩非子·初见秦》", "example": null}, {"def": "积货滋多,蓄怨滋厚。--《国语·楚语下》", "example": null}, {"def": "将军蓄米,将疗饥乎;将破敌乎?--《新五代史》", "example": null}, {"def": "又如蓄火(蓄留火种);蓄菜(把蔬菜制成菜干、咸菜等加以储藏。也指菜干,咸菜等);蓄余(储蓄节余的财物);蓄毓(储积培育);蓄租(", "example": null}, {"def": "蓄xù", "example": null}, {"def": "⒈积聚，储藏，保存～积。～水。储～。养精～锐。", "example": null}, {"def": "⒉包藏，隐藏～意。～谋‖～。", "example": null}]','chinese-xinhua','0'),
