('2101143296943329290','勖','1','xù','力','11',NULL,'[{"def": "勖", "example": null}, {"def": "勉力;勉励", "example": null}, {"def": "勖,勉也。从力,冒声。--《说文》", "example": null}, {"def": "夫子勖哉。--《书·牧誓》", "example": null}, {"def": "以勖寡人。--《诗·邶风·燕燕》。传勖,勉也。”", "example": null}, {"def": "勖帅以敬先妣之嗣。--《仪礼·士昏礼》", "example": null}, {"def": "亦勖而已。--《法言·孝至》", "example": null}, {"def": "奋忠毅之操,躬史鱼之节,董臣严纲,勖臣懦弱。--《后汉书》", "example": null}, {"def": "讲制艺乡绅勖后进。--《官场现形记》", "example": null}, {"def": "以国人之读兹编者勖。--孙文《黄花冈七十二烈士事略·序》", "example": null}, {"def": "又如勖助(勖勉,帮助);勖率(勉力遵循);勖厉,勖励(勉励)", "example": null}, {"def": "勖（勗）xù勉力，勉励～勉。", "example": null}]','chinese-xinhua','0'),
('2101143296943329291','绪','1','xù','纟','11',NULL,'[{"def": "绪", "example": null}, {"def": "(形声。从糸,者声。本义丝的头)", "example": null}, {"def": "同本义", "example": null}, {"def": "绪,丝端也。--《说文》", "example": null}, {"def": "凡茧滚沸时,以竹签拨动水面丝绪。--《天工开物》", "example": null}, {"def": "又如绪余(抽丝后留在蚕茧上的残丝)", "example": null}, {"def": "头绪,开端", "example": null}, {"def": "反覆终始,不知其端绪。--《淮南子·精神训》", "example": null}, {"def": "扰百绪于眼前。--谢庄《曲池赋》", "example": null}, {"def": "又如端绪(头绪);入绪(有了头绪);绪次(头绪)", "example": null}, {"def": "情绪,心情", "example": null}, {"def": "都门帐饮无绪。--柳永《雨霖铃》", "example": null}, {"def": "幽情苦绪何人见。--《聊斋志异》", "example": null}, {"def": "霜轻两鬓欲相侵,悉绪无端不可寻。--唐·李频《长安寓居寄柏侍郎》", "example": null}, {"def": "又如愁绪(忧愁的情", "example": null}, {"def": "绪xù", "example": null}, {"def": "⒈丝头。〈喻〉开端头～。论端究～。", "example": null}, {"def": "⒉世系，事业先～。续未竟之～。", "example": null}, {"def": "⒊心情、思想等心～。情～。思～。意～。", "example": null}, {"def": "⒋残余的～余。～风。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296943329292','续','1','xù','纟','11',NULL,'[{"def": "续", "example": null}, {"def": "(形声。从糸,卖声。本义连接起来,接上)", "example": null}, {"def": "同本义", "example": null}, {"def": "续,联也。--《说文》", "example": null}, {"def": "续,继也。--《尔雅》", "example": null}, {"def": "续衽钩边。--《礼记·深衣》", "example": null}, {"def": "貂不足,狗尾续。--《晋书·赵王伦传》", "example": null}, {"def": "是断手而续以玉也。--《韩非子·用人》", "example": null}, {"def": "一时人急智生,把自己头发拔下一绺,登时把弓弦续好。--《儒林外史》", "example": null}, {"def": "又如续弦;续篇;续编", "example": null}, {"def": "继续", "example": null}, {"def": "岁时更续。--《周礼·巾车》", "example": null}, {"def": "刑者不可复续。--《史记·扁仓传》", "example": null}, {"def": "亡秦之续。--《史记·项羽本纪》", "example": null}, {"def": "以夜续昼,由是获声誉。--《三国志》", "example": null}, {"def": "续发众人。--宋·司马光《资治通鉴》", "example": null}, {"def": "又如续终", "example": null}, {"def": "续（續）xù", "example": null}, {"def": "⒈连接，接上一段～假。～编。断长～短。", "example": null}, {"def": "⒉连接不断连～。继～。延～。", "example": null}, {"def": "⒊继承～祖。", "example": null}, {"def": "⒋添加将茶～上。肉汤里再～些水。", "example": null}]','chinese-xinhua','0'),
('2101143296943329293','酗','1','xù','酉','11',NULL,'[{"def": "酗", "example": null}, {"def": "(形声。从酉,凶声。酉”与酒有关。本义无节制地喝酒,酒后昏迷乱来)", "example": null}, {"def": "同本义", "example": null}, {"def": "下邳周丘,无行酗酒。--《史记·吴王濞列传》", "example": null}, {"def": "酗淫自恣,前后告喻,曾无悛改。--《三国志》", "example": null}, {"def": "又如酗戕(酒后杀人);酗讼(因酗酒而争讼);酗淫(酗酒淫乐)", "example": null}, {"def": "撒酒疯", "example": null}, {"def": "弟弼,好酒而酗。--《北史·烹传》", "example": null}, {"def": "素酗于酒,戚党多畏避之。--《聊斋志异》", "example": null}, {"def": "又如酗讼(因酗酒而起争讼)", "example": null}, {"def": "酗xù沉迷于酒;醉而发怒。", "example": null}]','chinese-xinhua','0'),
('2101143296943329294','喣','1','xù','','9',NULL,'[{"def": "喣xǔ 1.同\\"呴\\"。吹气;吐出。 2.见\\"喣愉\\"﹑\\"喣喣呕呕\\"。 3.见\\"喣喣\\"。 4.同\\"煦\\"。温暖。引申为抚育，使成长。", "example": null}]','chinese-xinhua','0'),
('2101143296943329295','婿','1','xù','女','12',NULL,'[{"def": "婿", "example": null}, {"def": "(形声。从女,胥声。或作壻”。本义古时女子称夫为婿)", "example": null}, {"def": "同本义", "example": null}, {"def": "壻,夫也。--《说文》", "example": null}, {"def": "女子之夫为壻。--《尔雅》", "example": null}, {"def": "壻执雁入。--《礼记·昏义》", "example": null}, {"def": "壻御轮三周。--《诗·有女同车》笺", "example": null}, {"def": "赵有侧室曰穿,晋君之壻也。--《左传·文公十二年》", "example": null}, {"def": "东房少妇婿从军,每听乌啼知夜分。--李瑞《乌栖曲》", "example": null}, {"def": "汉贵将独有奉车都尉,天子姊婿,爵为通侯,当先降之。--《后汉书》", "example": null}, {"def": "若是姻缘早,把风流婿招,少什么美夫妻图画在碧云高。--汤显祖《牡丹亭·写真》", "example": null}, {"def": "又如夫婿(丈夫)", "example": null}, {"def": "成年男子的美称", "example": null}, {"def": "桓温有", "example": null}, {"def": "婿（壻）xù", "example": null}, {"def": "⒈女儿的丈夫女～。", "example": null}, {"def": "⒉妇人称自己的丈夫夫～。", "example": null}]','chinese-xinhua','0'),
('2101143296943329296','朂','1','xù','','9',NULL,'[{"def": "朂xù", "example": null}, {"def": "⒈古同勖”。", "example": null}]','chinese-xinhua','0'),
('2101143296943329297','溆','1','xù','氵','12',NULL,'[{"def": "溆", "example": null}, {"def": "水名", "example": null}, {"def": "入溆浦余儃佪兮,迷不知吾所如。--《楚辞·屈原·涉江》", "example": null}, {"def": "水边", "example": null}, {"def": "长飚落江树,秋月照沙溆。--南朝梁·何逊《赠江长史别》", "example": null}, {"def": "追欢于林溆之地。--清·吴锡麒《游西山记》", "example": null}, {"def": "溆xù", "example": null}]','chinese-xinhua','0'),
('2101143296943329298','絮','1','xù','糸','12',NULL,'[{"def": "絮", "example": null}, {"def": "(形声。从糸,如声。本义粗丝绵)", "example": null}, {"def": "同本义", "example": null}, {"def": "絮,敝绵也。--《说文》。按,好者为绵,恶者为絮。", "example": null}, {"def": "絮三斤。--《汉书·高帝纪》。古无木绵,以絮纳袷中,谓之装褚,曰袍。", "example": null}, {"def": "剖其中,干若败絮。--明·刘基《卖柑者言》", "example": null}, {"def": "败絮其中。", "example": null}, {"def": "又如絮衣(绵衣);絮缯(丝帛之类的总称)", "example": null}, {"def": "经过弹制的棉花胎", "example": null}, {"def": "他们的婴孩没有棉衣,只好成天躺在土炕上那一堆破絮里。--茅盾《战时景气”宠儿--宝鸡》", "example": null}, {"def": "又如絮帛(棉絮与布帛);絮棉;絮缕(棉絮与丝缕。泛指微细之物)", "example": null}, {"def": "像絮一样轻柔、洁白的东西", "example": null}, {"def": "絮xù", "example": null}, {"def": "⒈粗丝棉，棉花的纤维～衣。吐～。棉～。", "example": null}, {"def": "⒉像絮的东西芦～。杨花飞～。", "example": null}, {"def": "⒊在衣被等内面铺絮～被子。一夜～征袍。", "example": null}, {"def": "⒋连续重复，令人厌烦～语。～烦。～叨（话多，唠叨）。", "example": null}, {"def": "絮chù 1.调拌;调制。", "example": null}, {"def": "絮nǜ 1.姓『有絮舜。见《汉书．张敞传》。", "example": null}]','chinese-xinhua','0'),
