('2101143296943329304','叙','1','xù','又','9',NULL,'[{"def": "叙", "example": null}, {"def": "(形声。从攴,余声。本义秩序,次序)", "example": null}, {"def": "同本义(强调一个挨一个的序列)", "example": null}, {"def": "敘,次弟也。--《说文》。经传亦以序为之。", "example": null}, {"def": "百揆时敘。--《虞书》", "example": null}, {"def": "行其秩敘。--《周礼·宫伯》", "example": null}, {"def": "以官府之六叙正群吏。--《周礼·天官》", "example": null}, {"def": "四时不失其叙。--《淮南子·本经训》", "example": null}, {"def": "又如叙齿(序齿);叙齿而坐(按年齿大小的顺序入座)", "example": null}, {"def": "同序”。书籍的序言(早期写作叙”,后多写作序”)", "example": null}, {"def": "叙", "example": null}, {"def": "依次序排列", "example": null}, {"def": "惇叙九族。--《书·皋陶谟》", "example": null}, {"def": "以敘其财。--《周礼·司书》", "example": null}, {"def": "叙述,述说", "example": null}, {"def": "叙（敘、敍）xù", "example": null}, {"def": "⒈说，谈，陈述～说。～谈。～家常。写情～事。", "example": null}, {"def": "⒉ 同　\\"序", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296943329305','恤','1','xù','忄','9',NULL,'[{"def": "恤", "example": null}, {"def": "(形声。从心,血声。本义忧虑)", "example": null}, {"def": "同本义", "example": null}, {"def": "恤,忧也。--《说文》", "example": null}, {"def": "勿恤其孚。--《易·泰》", "example": null}, {"def": "不印自恤。--《书·大诰》", "example": null}, {"def": "告而忧恤。--《诗·大雅·桑柔》", "example": null}, {"def": "不恤国事。--王安石《答司马谏议书》", "example": null}, {"def": "所图者国恤家仇,所期望者豪杰事功。--明·张煌言《复郎廷佐书》", "example": null}, {"def": "又如恤功(担忧民众的事务);恤恤(忧虑的样子);恤民(忧虑人民的疾苦)", "example": null}, {"def": "体恤", "example": null}, {"def": "朝廷竟无恤赠之典。--《隋唐演义》", "example": null}, {"def": "恤病讨贰。--《左传》", "example": null}, {"def": "不知存恤。--《三国志·诸葛亮传》", "example": null}, {"def": "又如恤近忽远(体恤亲近的人而忽略疏远的人);恤金", "example": null}, {"def": "怜悯", "example": null}, {"def": "恤（卹、?", "example": null}, {"def": "⒈怜悯，同情怜～。体～。", "example": null}, {"def": "⒉救济，周济抚～。有无相～，患难相救。", "example": null}, {"def": "⒊担忧，忧虑～国事。", "example": null}, {"def": "恤sū 1.见\\"恤勿\\"。", "example": null}]','chinese-xinhua','0'),
