('2101143296943329316','许','1','xǔ','讠','6',NULL,'[{"def": "许", "example": null}, {"def": "(形声。从言,午声。本义应允,许可)", "example": null}, {"def": "同本义", "example": null}, {"def": "许,听也。--《说文》。按,听从其言也。", "example": null}, {"def": "王子许。--《吕氏春秋·首时》。注诺也。”", "example": null}, {"def": "亟请于武公,公弗许。--《左传·隐公元年》", "example": null}, {"def": "尔不许我,我乃屏璧与圭。--《书·金滕》", "example": null}, {"def": "杂然相许。--《列子·汤问》", "example": null}, {"def": "其许寡人。--《战国策·魏策》", "example": null}, {"def": "不可不许。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "遂许先帝以驱驰。--诸葛亮《出师表》", "example": null}, {"def": "又如特许;只许成功,不许失败;准许;默许;许认(同意,承认);许肯(应允);许允(答应", "example": null}, {"def": "许xǔ", "example": null}, {"def": "⒈应允，认可～可。允～。准～。", "example": null}, {"def": "⒉称赞赞～。推～。", "example": null}, {"def": "⒊预先答应给予～诺。以身～国。", "example": null}, {"def": "⒋可能，或者也～。或～。", "example": null}, {"def": "⒌处所，地方先生不知何～人也。", "example": null}, {"def": "⒍〈表〉约略估计的几～。只有少～。年七十～。", "example": null}, {"def": "⒎句末语气词。这样如～。一生长恨奈何～。", "example": null}, {"def": "⒏周代诸侯国名，在今河南省许昌一带。", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "许hǔ 1.见\\"许许\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296943329317','诩','1','xǔ','讠','8',NULL,'[{"def": "诩", "example": null}, {"def": "(形声。从言,羽声。本义说大话,夸耀)", "example": null}, {"def": "同本义", "example": null}, {"def": "诩,大言也。--《说文》", "example": null}, {"def": "合同主诩。--《礼记·少仪》", "example": null}, {"def": "尚泰奢,丽夸诩。--《汉书·扬雄传》", "example": null}, {"def": "儒行之对,多所诩张,非俭让之德也。--明·高拱《本语》", "example": null}, {"def": "墙头山自好,何必诩神仙。--清·黄遵宪《闭关》", "example": null}, {"def": "意气扬扬,若自矜诩。--方苞《狱中杂记》", "example": null}, {"def": "又如诩张(夸张)", "example": null}, {"def": "普及", "example": null}, {"def": "德发扬,诩万物。--《礼记·礼器》", "example": null}, {"def": "又如诩扬(发扬;张大)", "example": null}, {"def": "诩", "example": null}, {"def": "假借为妩”。妩媚", "example": null}, {"def": "不闻犯齐牧,犹闻画眉诩。--《次韵寄晃以道》", "example": null}, {"def": "又如诩畜(媚好,妩媚)", "example": null}, {"def": "诩xǔ夸耀，说大话。夸～。自～。", "example": null}]','chinese-xinhua','0'),
