('2101143296943329328','胥','1','xū','月','9',NULL,'[{"def": "胥", "example": null}, {"def": "(形声。从肉,疋声。本义蟹酱)", "example": null}, {"def": "同本义", "example": null}, {"def": "胥,蟹醢也。--《说文》", "example": null}, {"def": "青州之蟹胥。--《周礼·庖人》注", "example": null}, {"def": "蟹胥,取蟹藏之,使骨头解胥胥然也。--《释名》", "example": null}, {"def": "共祭祀之好胥。--《周礼》", "example": null}, {"def": "片刻,一会儿", "example": null}, {"def": "胡蝶胥也。--《列子·天瑞》", "example": null}, {"def": "胡蝶胥也化而为虫。--《庄子》", "example": null}, {"def": "胥", "example": null}, {"def": "古代官府中的小吏;特指古代掌管捕捉盗贼的小官吏◇作偦”", "example": null}, {"def": "里胥猾黠。--《聊斋志异·促织》", "example": null}, {"def": "就老胥而问。--清·方苞《狱中杂记》", "example": null}, {"def": "部中老胥。", "example": null}, {"def": "胥某谓曰。", "example": null}, {"def": "胥某笑曰。", "example": null}, {"def": "又如胥里(乡里小吏);胥役(胥吏与差役", "example": null}, {"def": "胥xū", "example": null}, {"def": "⒈都，全～备。民～傚矣（傚效法）。", "example": null}, {"def": "⒉〈古〉小官吏～吏。里～（一里之长）。钞～（管抄写的小官）。", "example": null}]','chinese-xinhua','0'),
('2101143296943329329','须','1','xū','页','9',NULL,'[{"def": "须", "example": null}, {"def": "(本字作须”◇来写成有魀,现在又简化为须”。象形。从页,从彡,页,头,彡,表毛饰。指人面上的毛。本义胡须)", "example": null}, {"def": "同本义", "example": null}, {"def": "须,面毛也。--《说文》", "example": null}, {"def": "须,谓颐下之毛。--《礼记·礼运》引《说文》", "example": null}, {"def": "有君子白皙鬷须眉。--《左传·昭公二十六年》", "example": null}, {"def": "大夫以鱼须文竹。--《礼记·玉藻》", "example": null}, {"def": "美须髯。--《汉书·高帝纪》", "example": null}, {"def": "下担捋髭须。--《乐府诗集·木兰诗》", "example": null}, {"def": "须发咀。--《汉书·李广苏建传》", "example": null}, {"def": "又如须眉浊物(指趋炎附势,丧失气节的男人);虬须(卷曲的胡子);银须;黄须;长须;软须;须麋(须眉)", "example": null}, {"def": "野兽的魀。泛指动、", "example": null}, {"def": "须xū", "example": null}, {"def": "⒈", "example": null}, {"def": "①须要务～注意、必～努力。", "example": null}, {"def": "②姓。", "example": null}, {"def": "⒉等待；等到。", "example": null}, {"def": "⒊", "example": null}, {"def": "①原来指长在下巴上的胡子，后来泛指胡须～发、～眉。", "example": null}, {"def": "②须子触～、花～。", "example": null}]','chinese-xinhua','0'),
('2101143296943329330','墟','1','xū','土','14',NULL,'[{"def": "墟", "example": null}, {"def": "(本作虚”。形声。从土,虚声。本义大土山)", "example": null}, {"def": "同本义", "example": null}, {"def": "墟土之人大,沙土之人细。--《孔子家语》", "example": null}, {"def": "又如墟土(丘陵之地);墟垒(犹堡垒)", "example": null}, {"def": "废址,故城", "example": null}, {"def": "使人之朝为草而国为墟。--《吕氏春秋·贵直》", "example": null}, {"def": "又如殷墟;墟棘,墟榛,墟莽(废墟榛莽;荒野)", "example": null}, {"def": "坟墓", "example": null}, {"def": "墟,墟墓。--《字汇》", "example": null}, {"def": "又如墟墓(墟坟,丘墓,墓地)", "example": null}, {"def": "乡村集市", "example": null}, {"def": "二豪贼劫持反接,布囊其口,去逾四十里之墟所卖之。--《童区寄传》", "example": null}, {"def": "又如墟市;墟集(乡村市集);墟期,墟日(市集日)", "example": null}, {"def": "场所", "example": null}, {"def": "古之至人,假道于仁,诧宿于义,以游逍遥之墟。", "example": null}, {"def": "墟xū〈古〉作\\"虚\\"。", "example": null}, {"def": "⒈有人住过但已荒废的地方废～。殷～（殷朝故城。在今河南什阳，西小屯）。", "example": null}, {"def": "⒉村庄～里。～落。", "example": null}, {"def": "⒊〈方〉通\\"圩\\"。集市。", "example": null}]','chinese-xinhua','0'),
('2101143296943329331','嬃','1','xū','','14',NULL,'[{"def": "嬃xū 1.古时女子人名用字。《楚辞．离骚》\\"女嬃之婵媛兮，申申其詈予。\\"王逸注\\"女嬃，屈原姊也。\\"《史记．吕太后本纪》\\"太后女弟吕嬃有女为营陵侯刘泽妻。\\"司马", "example": null}, {"def": "贞索隐引韦昭曰\\"吕嬃，樊哙妻，封林光侯。\\"一说，古时楚人谓姊为嬃。", "example": null}]','chinese-xinhua','0'),
