('2101143296943329341','窢','1','xū','','11',NULL,'[{"def": "窢xù 1.逆风声。《庄子．天下》\\"其风窢然，恶可而言。\\"郭象注\\"逆风所动之声。\\"一说，迅速貌。", "example": null}]','chinese-xinhua','0'),
('2101143296943329342','嘘','1','xū','口','14',NULL,'[{"def": "嘘", "example": null}, {"def": "(形声。从口,虚声。本义缓缓吐气;呵气)", "example": null}, {"def": "同本义", "example": null}, {"def": "嘘,吹也。--《说文》", "example": null}, {"def": "出气缓曰嘘。--《声类》", "example": null}, {"def": "仰天而嘘。--《庄子·齐物论》", "example": null}, {"def": "嘘为雨露,噫为风雷。--刘禹锡《天论下》", "example": null}, {"def": "龙嘘气成云。--韩愈《杂说》", "example": null}, {"def": "又如嘘咈(呼吸;呼气与吸气);嘘吸(吐纳呼吸);嘘呵(形容风扬火气;呵气使暖);嘘咻(形容喘气的样子);嘘歙(呼吸)", "example": null}, {"def": "叹息", "example": null}, {"def": "长嘘吸以于悒兮,涕横集而成行。--《楚辞·刘向·九叹·忧苦》", "example": null}, {"def": "言未卒,因嘘唏服臆。--《史记·扁鹊佳》", "example": null}, {"def": "魂梦天涯无暂歇,枕上长嘘。--《敦煌曲子词》", "example": null}, {"def": "又如嘘欷(哀叹", "example": null}, {"def": "嘘xū", "example": null}, {"def": "⒈呵气，慢慢地呼气～气。", "example": null}, {"def": "⒉叹气仰天而～。", "example": null}, {"def": "⒊火或汽的热力熏炙～着手了。将肉放在锅里～一～。", "example": null}, {"def": "⒋", "example": null}, {"def": "嘘shī", "example": null}, {"def": "⒈叹词。〈表〉制止或反对等～，别说了！", "example": null}]','chinese-xinhua','0'),
('2101143296943329343','需','1','xū','雨','14',NULL,'[{"def": "需", "example": null}, {"def": "(会意。从雨而声。需”指遇雨,停在那里等待。本义等待)", "example": null}, {"def": "同本义", "example": null}, {"def": "需,须也。--《易·需》。传需者,待也。”", "example": null}, {"def": "聂许闻之需役。--《庄子·大宗师》", "example": null}, {"def": "九江需次今几年,去去渌水依红莲。--宋·楼钥《送袁恭安赴江州节推》", "example": null}, {"def": "略举数端,以需善择。--清·包世臣《文谱》", "example": null}, {"def": "又如需次(候补官员依照资历补缺);需铨(等待铨选录用)", "example": null}, {"def": "需要", "example": null}, {"def": "零星需用亦在账房内开销。--《红楼梦》", "example": null}, {"def": "又如按需分配;必需;需用(需要的用度)", "example": null}, {"def": "索取", "example": null}, {"def": "只为前日毛延寿,指写丹青,遍需金帛。--明·陈玉阳《昭君出塞》", "example": null}, {"def": "需", "example": null}, {"def": "需xū", "example": null}, {"def": "⒈要求，应该有，必须有～要。～求。必～品。按～分配。", "example": null}, {"def": "⒉必须要用的物资军～品。", "example": null}, {"def": "需nuò 1.懦弱;畏怯。", "example": null}, {"def": "需ruǎn 1.柔软。", "example": null}]','chinese-xinhua','0'),
('2101143296943329344','戌','1','xū','戈','6',NULL,'[{"def": "戌", "example": null}, {"def": "(指事。从戊,含一。不详。戊武器。本义地支的第十一位)", "example": null}, {"def": "同本义", "example": null}, {"def": "戌时", "example": null}, {"def": "明日大利,宜用戌亥时。--《三国演义》", "example": null}, {"def": "又如戌亥时(戌时与亥时)", "example": null}, {"def": "夏正建寅,九月为戌", "example": null}, {"def": "九月之辰谓为戌,戌者灭也,谓时物皆衰灭也。--《晋书》", "example": null}, {"def": "十二生肖属狗", "example": null}, {"def": "戌xū", "example": null}, {"def": "⒈地支的第十一位，也作次序第十一。", "example": null}, {"def": "⒉", "example": null}, {"def": "戌qū 1.屈戌儿。门窗上的环纽;搭扣。", "example": null}]','chinese-xinhua','0'),
('2101143296943329345','盱','1','xū','目','8',NULL,'[{"def": "盱", "example": null}, {"def": "睁大眼睛", "example": null}, {"def": "盱,张目也。从目,于声。--《说文》", "example": null}, {"def": "乃盱衡而诰曰。--左思《魏都赋》。注举眉大视也。”", "example": null}, {"def": "盱盱然。--《荀子·非十二子》", "example": null}, {"def": "盱衡厉色,振扬武器。--《汉书·王莽传》", "example": null}, {"def": "又如盱目(张目),盱盱(张目直视);盱视(张目直视)", "example": null}, {"def": "睁开眼睛向上看;仰望", "example": null}, {"def": "盱,仰目也。--《龙龛手鉴》", "example": null}, {"def": "又如盱眙(张目向上看);盱睢(张目仰视)", "example": null}, {"def": "扩大", "example": null}, {"def": "又广盱营表,发人冢墓,断截骸骨,暴扬尸柩。--《汉书·谷永传》", "example": null}, {"def": "云何其盱。--《诗·小雅·何人斯》", "example": null}, {"def": "盱衡", "example": null}, {"def": "盱xū", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉张开眼睛。", "example": null}]','chinese-xinhua','0'),
