('2101143296943329347','繻','1','xū','糹','20',NULL,'[{"def": "繻", "example": null}, {"def": "彩色的丝织品", "example": null}, {"def": "繻,缯采色。从糸,需声。--《说文》", "example": null}, {"def": "亲解孝宗苃角之繻傅其首。--《宋史·韩彦直传》", "example": null}, {"def": "细密的丝织品", "example": null}, {"def": "繻,细密之罗也。--《玉篇》", "example": null}, {"def": "汉代出入关隘的帛制通行证,上写字,分为两半,出入时验合", "example": null}, {"def": "繻,帛边也。古者过关以符书帛裂而分之,若今券也。--《玉篇》", "example": null}, {"def": "又如繻卷(古代作通行证用的符帛)", "example": null}, {"def": "繻rú 1.彩色的缯帛。一说细密的罗。 2.古代作通行证用的帛。上写字，分成两半，过关时验合，以为凭信。", "example": null}, {"def": "繻xū 1.彩色的缯帛。一说细密的罗。 2.古代作通行证用的帛。上写字，分成两半，过关时验合，以为凭信。", "example": null}]','chinese-xinhua','0'),
('2101143296943329348','痃','1','xuán','疒','10',NULL,'[{"def": "痃〈名〉", "example": null}, {"def": "古病名。亦称痃气”。脐旁气块", "example": null}, {"def": "胀痛为痃气", "example": null}, {"def": "痃xuán", "example": null}]','chinese-xinhua','0'),
('2101143296943329349','悬','1','xuán','心','11',NULL,'[{"def": "悬", "example": null}, {"def": "(形声。从心,县声。本作县”,象断首倒挂,后加系”。假借为行政区域的县”后,另加心”字表示悬挂。本义吊挂)", "example": null}, {"def": "同本义", "example": null}, {"def": "悬者植梯接之。--《徐霞客游记·游黄山记》", "example": null}, {"def": "以叵幅悬之。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "倒悬之。--清·张廷玉《明史》", "example": null}, {"def": "又如悬丝诊脉(传说古代中医诊脉法之一。不见面将丝线系于病人腕上诊脉治病);悬壁(相学术语。指脸部接近耳垂下端处的部位)", "example": null}, {"def": "牵挂;挂念", "example": null}, {"def": "凭空设想;揣测", "example": null}, {"def": "悬（懸）xuán", "example": null}, {"def": "⒈吊，挂～挂。～灯。～梁刺股。", "example": null}, {"def": "⒉挂念，惦记，关切的心情～念。", "example": null}, {"def": "⒊无着落，没结果～案。～而未决。", "example": null}, {"def": "⒋无依据，凭空揣度～断。～揣。", "example": null}, {"def": "⒌距离远～隔。～殊。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
('2101143296943329350','旋','1','xuán','方','11',NULL,'[{"def": "旋", "example": null}, {"def": "同本义", "example": null}, {"def": "旋,周旋,旌旗之指麾也。--《说文》", "example": null}, {"def": "旋入雷渊。--《楚辞·招魂》。注旋,转也。”", "example": null}, {"def": "旋式正綦。--《史记·日者列传》。索隐旋,转也。”", "example": null}, {"def": "鲵旋之潘为渊。--《列子·黄帝》。注旋,谓盘旋也。”", "example": null}, {"def": "湍濑旋渊吕梁之深。--《淮南子·俶真》", "example": null}, {"def": "水深则回。--《荀子·致士》。注回,旋流也。水深不湍峻则多旋流也。”", "example": null}, {"def": "周旋中规,折旋中矩。--《礼记·玉藻》", "example": null}, {"def": "周旋序顺。--《国语·周语》。注周旋,容止也。”", "example": null}, {"def": "列星随旋,日月递炤。--《荀子·天论》", "example": null}, {"def": "又如旋辟(进退周旋,环绕);旋式(转动罗盘", "example": null}, {"def": "旋xuán", "example": null}, {"def": "⒈转动，弯转～转。盘～。螺～。", "example": null}, {"def": "⒉归，回凯～。未知何日～。", "example": null}, {"def": "⒊随即，不久～即离去。～亦悔之。", "example": null}, {"def": "旋xuàn", "example": null}, {"def": "⒈打转转的～风。她的头发有个～。", "example": null}, {"def": "⒉临时～买。～做～卖。", "example": null}, {"def": "⒊转着圈切削用～床～零件。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
