('2101143296943329360','炫','1','xuàn','火','9',NULL,'[{"def": "炫", "example": null}, {"def": "(形声。从火,玄声。本义晃眼)", "example": null}, {"def": "同本义", "example": null}, {"def": "炫,烂耀也。--《说文》", "example": null}, {"def": "炫光貌。--《埤仓》", "example": null}, {"def": "炫熿干道。--《战国策·秦策》", "example": null}, {"def": "大盆盛水,置剑其上,视之者精芒炫目。--《晋书》", "example": null}, {"def": "又如炫视(目光炫乱);炫目(光彩夺目);炫色(闪烁光芒);炫炫(光耀明亮的样子)", "example": null}, {"def": "迷惑;惑乱", "example": null}, {"def": "显示;夸耀", "example": null}, {"def": "生已沽名炫气豪,死犹虚伪惑儿曹。--《警世通言》", "example": null}, {"def": "又如炫的那家世(夸什么家阀世系;显什么眼);炫玉求售(自诩有才,以求施展)", "example": null}, {"def": "炫", "example": null}, {"def": "形容艳丽", "example": null}, {"def": "袨(炫", "example": null}, {"def": "炫xuàn", "example": null}, {"def": "⒈照耀光彩～目。", "example": null}, {"def": "⒉夸耀自～其能。", "example": null}]','chinese-xinhua','0'),
('2101143296943329361','绚','1','xuàn','纟','9',NULL,'[{"def": "绚", "example": null}, {"def": "(形声。从糸,旬声。本义美丽,漂亮有文采的样子)", "example": null}, {"def": "同本义(含有色彩灿烂多姿的意思)", "example": null}, {"def": "绚,文貌。--《玉篇》", "example": null}, {"def": "松门亘五里,碧彩高下绚。--皮日休《雨中游包山精舍》", "example": null}, {"def": "素以为绚兮。--《论语·八佾》", "example": null}, {"def": "江枫绚似红妆。--张草《河满子》", "example": null}, {"def": "又如绚丽;绚文(绚丽而有文采);绚采(文采);绚素(白绢绘以文采;在绘画上加施白采)", "example": null}, {"def": "通侚”。迅疾的样子", "example": null}, {"def": "别辈越群,绚练夐绝。--颜延之《赭白马赋》", "example": null}, {"def": "又如绚练(迅疾的样子)", "example": null}, {"def": "绚", "example": null}, {"def": "辉映;照耀", "example": null}, {"def": "点缀", "example": null}, {"def": "含烟绚碧彩,带露如珠缀。--", "example": null}, {"def": "绚xuàn有文彩，色彩华丽～丽。～烂。素章增～。", "example": null}]','chinese-xinhua','0'),
('2101143296943329362','眩','1','xuàn','目','10',NULL,'[{"def": "眩", "example": null}, {"def": "(形声。从目,玄声。本义眼花,看不清)", "example": null}, {"def": "同本义", "example": null}, {"def": "眩,目无常主也。--《说文》", "example": null}, {"def": "眩,视不明也。--《苍颉篇》", "example": null}, {"def": "靡瞻不眩。--《汉书·元帝纪》。注视乱也。”", "example": null}, {"def": "目眩眩兮寤终朝。--《楚辞·逢尤》。注视貌。”", "example": null}, {"def": "目眩良久。--《战国策·燕策》", "example": null}, {"def": "又如眩瞀(眼睛昏花,视物不明);眩精(眩目;耀眼);眩晃(耀眼);眩眼(光芒耀眼);眩移(目夺神移);眩顿(眼花体乏)", "example": null}, {"def": "迷惑;迷乱。引申为欺骗", "example": null}, {"def": "眩,乱也。--《广雅》", "example": null}, {"def": "眩,惑也。--《释言》", "example": null}, {"def": "敬大臣则不眩。--《礼记·中庸》。疏", "example": null}, {"def": "眩xuàn", "example": null}, {"def": "⒈眼花，看不清楚心乱目～。", "example": null}, {"def": "⒉迷惑，迷乱～惑。", "example": null}, {"def": "⒊", "example": null}, {"def": "①光辉明亮辉光～耀。", "example": null}, {"def": "②显示，夸耀。", "example": null}, {"def": "眩huàn 1.幻术;戏法。", "example": null}]','chinese-xinhua','0'),
