('2101143296943329387','轩','1','xuān','车','7',NULL,'[{"def": "轩", "example": null}, {"def": "(形声。从车,干声。本义中国古代一种前顶较高而有帷幕的车子,供大夫以上乘坐)", "example": null}, {"def": "同本义", "example": null}, {"def": "轩,曲輈藩车。--《说文》", "example": null}, {"def": "轩,安车也。--《声类》", "example": null}, {"def": "而乘轩者三百人也。--《左传·僖公二十八年》", "example": null}, {"def": "舍其文轩。--《战国策·宋策》", "example": null}, {"def": "俄轩冕。--扬雄《羽猎赋》。注车有辬曰轩。”", "example": null}, {"def": "如轾如轩。--《诗·小雅·六月》", "example": null}, {"def": "后重曰轩。--《通俗文》。按,后重曰轾,前高曰轩。", "example": null}, {"def": "舍其文轩。--《墨子·公输》", "example": null}, {"def": "文轩之与敝舆。", "example": null}, {"def": "卫懿公好鹤,鹤有乘轩者。--《左传·闵公二年", "example": null}, {"def": "轩xuān", "example": null}, {"def": "⒈〈古〉一种有帷幕的车，泛指车子乘～。", "example": null}, {"def": "⒉有窗槛的长廊或小屋西～。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "轩xiàn 1.大的肉片。", "example": null}]','chinese-xinhua','0'),
('2101143296943329388','宣','1','xuān','宀','9',NULL,'[{"def": "宣", "example": null}, {"def": "(形声。从宀,亘声。宀”与房屋有关。一说据甲骨文为云气舒卷自如之象。本义帝王的宫殿)", "example": null}, {"def": "古代帝王的大室,古宫室名", "example": null}, {"def": "宣,天子宣室也。--《说文》。按,当训大室也。与宽略同。", "example": null}, {"def": "武王破纣牧野,杀之于宣室。--《淮南子·本经》。注宣室,殷宫名,一曰狱也。”", "example": null}, {"def": "受釐坐宣室。--《汉书·孝文纪》。注未央前正室也。”", "example": null}, {"def": "宣室求贤访逐臣,贾生才调更无伦。--李商隐《贾生》", "example": null}, {"def": "帝王的诏书", "example": null}, {"def": "黄宣去把团营押。--汤显祖《紫钗记》", "example": null}, {"def": "宣纸的简称", "example": null}, {"def": "尝至琉璃厂购玉版宣,以瓜子金抵其值。", "example": null}, {"def": "宣xuān", "example": null}, {"def": "⒈发表，公开～言。～告。～布。秘而不～。", "example": null}, {"def": "⒉疏通，泄漏～泄。", "example": null}, {"def": "⒊发扬，广泛传播正直宜～（宜应该）。大肆～扬。普遍～传。", "example": null}, {"def": "⒋通，畅达政之不～，民之不宁。", "example": null}]','chinese-xinhua','0'),
('2101143296943329389','谖','1','xuān','讠','11',NULL,'[{"def": "谖", "example": null}, {"def": "(形声。从言,爰声。本义欺诈,欺骗)", "example": null}, {"def": "同本义", "example": null}, {"def": "谖,诈也。--《说文》", "example": null}, {"def": "谖,欺也。--《广雅》", "example": null}, {"def": "则上诈缓而弃其信。--《汉书·艺文志》", "example": null}, {"def": "虚造诈谖之策。--《汉书·息夫躬传》", "example": null}, {"def": "又如谖言(华而不实的言辞)", "example": null}, {"def": "忘记,忘却,遗忘", "example": null}, {"def": "有匪君子,终不可谖兮。--《诗·卫风·淇奥》", "example": null}, {"def": "焉得谖草,言树之背。--《诗·卫风·伯兮》", "example": null}, {"def": "谖xuān", "example": null}, {"def": "①欺诈。", "example": null}, {"def": "②通\\"萱\\"。忘记。", "example": null}, {"def": "③引申为停止。", "example": null}, {"def": "④通\\"諠\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296947523584','喧','1','xuān','口','12',NULL,'[{"def": "喧", "example": null}, {"def": "(形声。从口,宣声。宣”有宣扬”义,也有表义作用。本义声音大而嘈杂)", "example": null}, {"def": "同本义", "example": null}, {"def": "喧,大语也。--《玉篇》", "example": null}, {"def": "结庐在人境,而无车马喧。--陶潜《饮酒》", "example": null}, {"def": "上林催猎响,河桥争渡喧。--北周·庚信《同州还》", "example": null}, {"def": "夜风一何喧,大舶双橹。--宋·王安石《金山寺》", "example": null}, {"def": "蛙蛤徒自喧,蛟龙卧如蛰。--陆游《喜雨》", "example": null}, {"def": "又如喧议(喧闹议论);喧埃(尘世的喧嚷);喧吓(喧哗恐吓);喧卑(喧闹低下);喧哄(喧闹)", "example": null}, {"def": "喧（諠）xuān声音大，声音杂乱～哗。～嚣。锣鼓～天。", "example": null}, {"def": "喧xuǎn 1.哭泣。", "example": null}]','chinese-xinhua','0'),
