('2101143296947523622','恂','1','xún','忄','9',NULL,'[{"def": "恂", "example": null}, {"def": "(形声。从心,旬声。本义相信,信任)", "example": null}, {"def": "同本义", "example": null}, {"def": "恂,信心也。--《说文》", "example": null}, {"def": "恂,信也。--《方言一》", "example": null}, {"def": "为下国恂蒙。--《大戴礼记·卫将军文子》", "example": null}, {"def": "且恂士师之言可也。--《列子·周穆王》", "example": null}, {"def": "诚信", "example": null}, {"def": "迪知忱恂于九德之行。--《书·立政》", "example": null}, {"def": "恂", "example": null}, {"def": "恐惧", "example": null}, {"def": "木处则惴慄恂惧。--《庄子·齐物论》", "example": null}, {"def": "又如恂慄(恐惧战慄);恂惧(恐惧)", "example": null}, {"def": "严肃恭谨", "example": null}, {"def": "恂恂如也。--《论语》", "example": null}, {"def": "恂,栗也。--《礼记·大学》。注字或作峻。言其容貌严栗也。”", "example": null}, {"def": "参为人矜严,好修容仪,进退恂恂。--《汉书·冯", "example": null}, {"def": "恂xún", "example": null}, {"def": "⒈相信，信任。", "example": null}, {"def": "⒉害怕～惧。", "example": null}, {"def": "⒊", "example": null}, {"def": "①恭敬谨慎的样子进退～ ～。", "example": null}, {"def": "②恐惧担心的样子～ ～而起。", "example": null}, {"def": "③通\\"循循\\"。有步骤的样子～ ～善诱。", "example": null}, {"def": "恂shùn 1.急遽。 2.眨眼。参见\\"恂目\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296947523623','洵','1','xún','氵','9',NULL,'[{"def": "洵", "example": null}, {"def": "(形声。从水,旬声。本义水名) 同本义", "example": null}, {"def": "源出秦岭南麓沙罗幛,南流到两河关纳乾佑河,在旬阳县入汉水。长百余公里", "example": null}, {"def": "洵", "example": null}, {"def": "假借为恂”。诚然,确实", "example": null}, {"def": "洵有情兮。--《诗·陈风·宛丘》", "example": null}, {"def": "洵美且异。--《诗·邶风·静女》", "example": null}, {"def": "功有九转之妙,洵为希世奇珍。--《镜花缘》", "example": null}, {"def": "又如洵足(实在值得)", "example": null}, {"def": "通泫”。流", "example": null}, {"def": "请无瘠色,无洵涕。--《国语·鲁语下》", "example": null}, {"def": "又如洵涕(默默地流泪。洵,通泫”)", "example": null}, {"def": "洵xún诚然，确实～美且好。", "example": null}]','chinese-xinhua','0'),
