('2101143296947523648','驯','1','xùn','马','6',NULL,'[{"def": "驯", "example": null}, {"def": "(形声。从马,川声。本义马驯服)", "example": null}, {"def": "同本义。亦指鸟兽驯服", "example": null}, {"def": "驯,马训也。--《说文》", "example": null}, {"def": "养野鸟兽使服谓之训。--《一切经音义》引《说文》", "example": null}, {"def": "驯,性行调顺也。--《字林》", "example": null}, {"def": "乃驾驯駮之驷。--《史记·司马相如传》", "example": null}, {"def": "南越献驯象。--《汉书·武帝纪》", "example": null}, {"def": "马先驯而后求良。--《淮南子》", "example": null}, {"def": "江鱼不池活,野鸟难笼驯。--唐·韩愈《送惠师》", "example": null}, {"def": "又如驯兽(驯服之兽);驯雉(驯顺的雉);驯禽(驯养的禽鸟);驯鹿(驯养的鹿);驯乌(驯顺的乌鸦);驯象(驯养的象)", "example": null}, {"def": "泛指顺服", "example": null}, {"def": "能明驯德。--《史记·五", "example": null}, {"def": "驯xùn", "example": null}, {"def": "⒈顺从，听从指使～服。善于～兽。", "example": null}, {"def": "⒉善良～行。", "example": null}, {"def": "驯xún 1.马顺服。 2.泛指顺服。 3.使驯服，使和顺。 4.顺，不背理﹑不乱。 5.调顺，使和谐不乱。 6.美善。 7.循序渐进。 8.熟习。 9.通\\"训\\"。教训，教导", "example": null}, {"def": "。 10.通\\"训\\"。训释，解说。", "example": null}]','chinese-xinhua','0'),
('2101143296947523649','徇','1','xùn','彳','9',NULL,'[{"def": "徇 侚", "example": null}, {"def": "(形声。从彳,旬声。彳”与行有关。本义迅速,敏捷) 同本义", "example": null}, {"def": "侚,疾也。从人,旬声,字亦误作徇。--《说文》", "example": null}, {"def": "黄帝幼而徇齐。--《史记·五帝纪》。集解疾也,失之。”", "example": null}, {"def": "年逾五十则聪明思虑徇通矣。--《墨子》", "example": null}, {"def": "又如徇通(敏捷通达);徇智(敏慧);徇齐(疾速)", "example": null}, {"def": "徇", "example": null}, {"def": "巡行", "example": null}, {"def": "王乃徇师而誓。--《书·泰誓中》", "example": null}, {"def": "将兵徇蕲以东。--《史记·陈涉世家》", "example": null}, {"def": "又如徇铺(巡查街市里巷);徇察(巡行察访)", "example": null}, {"def": "巡行示众", "example": null}, {"def": "杀颠颉以徇于师。--《左传·僖公二十八年》", "example": null}, {"def": "以徇三军。--《史记·司马穰", "example": null}, {"def": "徇（猣）xùn", "example": null}, {"def": "⒈从，曲从不准～私舞弊。", "example": null}, {"def": "⒉巡行～于路。", "example": null}, {"def": "⒊示众车裂以～。", "example": null}, {"def": "⒋同\\"殉", "example": null}, {"def": "⒈\\"。为了某种目的而死。", "example": null}]','chinese-xinhua','0'),
('2101143296947523650','迿','1','xùn','','6',NULL,'[{"def": "迿xùn 1.争先。", "example": null}]','chinese-xinhua','0'),
('2101143296947523651','逊','1','xùn','辶','9',NULL,'[{"def": "逊", "example": null}, {"def": "(形声。从辵,孙声。本义逃遁)", "example": null}, {"def": "同本义", "example": null}, {"def": "遜,遁也。--《说文》", "example": null}, {"def": "吾家耄逊于荒。--《书·微子》", "example": null}, {"def": "是以耆儒硕老,抱其书而远逊。--汉·扬雄《剧秦美新》", "example": null}, {"def": "又如逊郊(天子逃遁于荒野)", "example": null}, {"def": "辞让;退让", "example": null}, {"def": "将逊于位。--《书·尧典序》", "example": null}, {"def": "用率我唐典,敬逊尔位。--《三国演义》", "example": null}, {"def": "以其逊职,是有进阶,式从彝序,无替成命。--唐·常衮《授李抱玉》", "example": null}, {"def": "心想挑了个斜岔儿,把大家逊出去就完了事了。--《儿女英雄传》", "example": null}, {"def": "又如逊受(谦让着接受);逊辞(辞让;推辞);唐尧逊位;逊国(让国);逊迹(退避;隐居);逊坐(让坐)", "example": null}, {"def": "不如,比不上", "example": null}, {"def": "逊（遜）xùn", "example": null}, {"def": "⒈让，退让唐尧～位。", "example": null}, {"def": "⒉谦让，恭顺谦～。傲慢不～。", "example": null}, {"def": "⒊逃远～。～于外。", "example": null}, {"def": "⒋差，次～色。略～一筹。", "example": null}]','chinese-xinhua','0'),
('2101143296947523652','殉','1','xùn','歹','10',NULL,'[{"def": "殉", "example": null}, {"def": "(形声。从歹(本作歺),旬声。歺,剔过肉剩下的骨头,常与死亡”有关。本义殉葬;以人从葬)", "example": null}, {"def": "同本义", "example": null}, {"def": "殉,用人送死也。--《玉篇》", "example": null}, {"def": "王缢于芋尹申亥氏。申亥以其二女殉而葬之。--《左传》", "example": null}, {"def": "死者用生者之器也,不殆于用殉乎哉。--《礼记·檀弓下》", "example": null}, {"def": "与城为殉。--清·全祖望《梅花岭记》", "example": null}, {"def": "又如殉死;殉葬", "example": null}, {"def": "献身或丧生", "example": null}, {"def": "今世俗之君子,多危身弃生以殉物。--《庄子·让王》", "example": null}, {"def": "又如殉义(为道义而死);殉财(为财而死);殉物(为追求物质利益而死);殉身(为达到某种目的而献身)", "example": null}, {"def": "贪,追求", "example": null}, {"def": "殉xùn", "example": null}, {"def": "⒈为了某种目的而死以身～职。～国（为国牺牲）。", "example": null}, {"def": "⒉〈古〉一种野蛮暴行。逼迫活着的妻妾、奴隶等陪同死人埋葬，也指用偶人或器物等随葬～葬。", "example": null}]','chinese-xinhua','0'),
('2101143296947523653','訙','1','xùn','','6',NULL,'[{"def": "訙xùn 1.为人名用字。宋有赵师訙。见《宋史．宗室世系表二》。", "example": null}]','chinese-xinhua','0'),
('2101143296947523654','巽','1','xùn','巳','12',NULL,'[{"def": "巽", "example": null}, {"def": "(会意。小篆。从丌)", "example": null}, {"def": "同本义", "example": null}, {"def": "巽,具也。--《说文》", "example": null}, {"def": "消散", "example": null}, {"def": "巽,散也,物皆生布散也。--《释名·释天》", "example": null}, {"def": "巽", "example": null}, {"def": "八卦之一。代表风", "example": null}, {"def": "巽为木,为风。--《易·说卦》", "example": null}, {"def": "又如巽地(吉利的地方);巽二郎(传说中的风神);巽二(古时传说中的风神名。《易·说卦》有巽为木,为风”,故名)", "example": null}, {"def": "东南方", "example": null}, {"def": "巽", "example": null}, {"def": "卑顺;怯懦", "example": null}, {"def": "童蒙之吉,顺以巽", "example": null}, {"def": "巽xùn八卦之一，代表风。", "example": null}]','chinese-xinhua','0'),
