('2101143296947523662','训','1','xùn','讠','5',NULL,'[{"def": "训", "example": null}, {"def": "(形声。从言,川声。本义教育,教导)", "example": null}, {"def": "同本义", "example": null}, {"def": "训,说教也。--《说文》", "example": null}, {"def": "大训。--《书·顾命》", "example": null}, {"def": "告之训典。--《左传·文公六年》", "example": null}, {"def": "是为明训。--《国语·晋语》。注教也。”", "example": null}, {"def": "务材训农,通商惠工。--《左传·闵公二年》", "example": null}, {"def": "而五人生于编伍之间,素不闻诗书之训。--张溥《五人墓碑记》", "example": null}, {"def": "训俭示康。--宋·司马光《训俭示康》", "example": null}, {"def": "又如训蒙(在私塾教授小学生);训蒙教授(教幼童的私塾先生);训人(负责教育的官员或师长);训章(训示规范)", "example": null}, {"def": "解说,注释。用通俗的话解释词语的意义", "example": null}, {"def": "但世人未之深亮训", "example": null}, {"def": "训xùn", "example": null}, {"def": "⒈教导，教诲～导。～练。吸取教～。", "example": null}, {"def": "⒉法则，规范，准则遗～。不足为～。", "example": null}, {"def": "⒊申斥～人。～诫。", "example": null}, {"def": "⒋词义解释～释。～诂。", "example": null}]','chinese-xinhua','0'),
('2101143296947523663','讯','1','xùn','讠','5',NULL,'[{"def": "讯", "example": null}, {"def": "同本义", "example": null}, {"def": "讯,问也。--《说文》。按,字亦作询『宣帝名询。", "example": null}, {"def": "讯之占梦。--《诗·小雅·正月》。传问也。”", "example": null}, {"def": "多其讯。--《礼记·学记》。注或为訾,按,訾犹咨也。”", "example": null}, {"def": "执讯而与之书。--《左传·文公十二年》。注通问之官。”", "example": null}, {"def": "君尝讯臣矣。--《公羊传·僖公十年》。注上问下曰讯。”", "example": null}, {"def": "以讯首或告。--《礼记·王制》", "example": null}, {"def": "讯鞫论报。--《汉书·张汤传》。注考问也。”", "example": null}, {"def": "卒从吏讯。--《汉书·邹阳传》。注谓鞠问也。”", "example": null}, {"def": "乃讯申胥。--《国语·吴语》", "example": null}, {"def": "昼夜搒讯。--清·张廷玉《明史》", "example": null}, {"def": "木讯", "example": null}, {"def": "讯xùn", "example": null}, {"def": "⒈问，询问，特指审问～问。传～。审～。", "example": null}, {"def": "⒉音信，消息音～。通～。新华社～。", "example": null}]','chinese-xinhua','0'),
