('2101143296947523684','醺','1','xūn','酉','21',NULL,'[{"def": "醺", "example": null}, {"def": "(形声。从酉,熏声。酉与酒有关。本义酒醉)", "example": null}, {"def": "同本义", "example": null}, {"def": "醺,醉也。--《说文》", "example": null}, {"def": "公尸来止醺醺。--《诗·大雅·凫鷖》", "example": null}, {"def": "才倾一盏即醺人。--杜甫《拨闷》诗", "example": null}, {"def": "又如醺然(醉酒的神态);醉醺醺;微醺;醺醺(酒醉的样子)", "example": null}, {"def": "受浸染。同熏”", "example": null}, {"def": "醺xūn醉，酒醉微～。醉～ ～。", "example": null}]','chinese-xinhua','0'),
('2101143296947523685','呀','1','ya','口','7',NULL,'[{"def": "呀", "example": null}, {"def": "(形声。从口,牙声。本义张口的样子)表示惊异", "example": null}, {"def": "呀", "example": null}, {"def": "吱吱嘎嘎的声音", "example": null}, {"def": "呀", "example": null}, {"def": "表示语气。啊”受前一字韵母的影响而发生变音。如他从小就没有了家呀!群众的力量真大呀!老张,快去呀", "example": null}, {"def": "呀yā", "example": null}, {"def": "⒈叹词。〈表〉惊疑～！你说怎么办？", "example": null}, {"def": "⒉像声词～的一声，门开了。", "example": null}, {"def": "呀ya助词。\\"啊\\"的变音好好学习～（啊）！努力工作～（啊）！", "example": null}, {"def": "呀xiā 1.空旷貌，敞开貌。 2.张口;张开。 3.高耸。参见\\"呀呀\\"﹑\\"呀空\\"。", "example": null}]','chinese-xinhua','0'),
