('2101143296947523697','崖','1','yá','山','11',NULL,'[{"def": "崖", "example": null}, {"def": "(形声。从山,厓声。本义岸;水边)", "example": null}, {"def": "同本义", "example": null}, {"def": "崖,高边也。--《说文》", "example": null}, {"def": "崖,岸。高边也。…此云高边,崖则水之边而峭高者也。--《说文句读》", "example": null}, {"def": "渊生珠而崖不枯。--《荀子·劝学》", "example": null}, {"def": "望厓洒而高岸。--《尔雅·释丘》。按厓之峻而高者,岸也,即岸也。”", "example": null}, {"def": "伯有廷劳于黄崖。--《左传·襄公二十八年》", "example": null}, {"def": "泾流之大,两涘渚崖之间,不辨牛马。--《庄子·秋水》", "example": null}, {"def": "君其涉于江而浮于海,望之而不见其崖。--《庄子·山水》", "example": null}, {"def": "穹崖巨谷。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "蹑履登崖。--明·刘基《诚意伯刘文成公文集》", "example": null}, {"def": "石崖", "example": null}, {"def": "崖yá山边或高地陡立的壁面山～。悬～。", "example": null}]','chinese-xinhua','0'),
('2101143296947523698','涯','1','yá','氵','11',NULL,'[{"def": "涯", "example": null}, {"def": "(会意兼形声。从水,从厓,厓亦声。厓,山边。本义水边)", "example": null}, {"def": "同本义", "example": null}, {"def": "涯,水边也。--《说文新附》", "example": null}, {"def": "各在天一涯。--《古诗十九首》", "example": null}, {"def": "大海亦有洼,高山亦有岑。--孟郊《病客吟》", "example": null}, {"def": "又如涯歡(水边;岸);涯灌(岸边丛木);涯邻(崖畔)", "example": null}, {"def": "岸,靠近大水体的陆地;特指靠近滨海的陆地", "example": null}, {"def": "驾舟载男女,筑宫东海涯。--虞集《题商学士画》", "example": null}, {"def": "边际;极限", "example": null}, {"def": "横无际涯。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "无涯之憾。--清·袁枚《祭妹文》", "example": null}, {"def": "又如望无涯;涯限(边际;限度);涯垠(涯泄、涯津、涯畔)", "example": null}, {"def": "限量;穷尽", "example": null}, {"def": "涯yá", "example": null}, {"def": "⒈水边～岸。", "example": null}, {"def": "⒉边际，极限天～。望不到～。", "example": null}]','chinese-xinhua','0'),
