('2101143296964300800','筵','1','yàn','竹','12',NULL,'[{"def": "筵", "example": null}, {"def": "(形声。从竹,延声。本义竹席)", "example": null}, {"def": "古时铺在地上供人坐的垫底的竹席,古人席地而坐,设席每每不止一层。紧靠地面的一层称筵,筵上面的称席", "example": null}, {"def": "筵亦席也。铺陈曰筵,藉之曰席。--《周礼》郑玄注", "example": null}, {"def": "又如筵几(座席和几案);筵第(筵席和床铺)", "example": null}, {"def": "席位", "example": null}, {"def": "张筵列鼎。--清·周容《芋老人传》", "example": null}, {"def": "又如筵席(酒宴时的座位和陈设);筵羞(酒宴美食)", "example": null}, {"def": "宴席", "example": null}, {"def": "筵", "example": null}, {"def": "铺设坐席", "example": null}, {"def": "主人筵于户西。--《仪礼·士冠", "example": null}, {"def": "筵yán", "example": null}, {"def": "⒈竹制的垫席铺设～席。〈引〉席位。", "example": null}, {"def": "⒉酒席喜～。开～。", "example": null}]','chinese-xinhua','0'),
('2101143296964300801','谚','1','yàn','讠','11',NULL,'[{"def": "谚", "example": null}, {"def": "(形声。从言,彦声。本义谚语) 同本义", "example": null}, {"def": "谚,传言也。字亦作喭。--《说文》", "example": null}, {"def": "故谚有之曰。--《礼记·大学》", "example": null}, {"def": "谵有之曰。--《国语·越语》。注谚俗之善谣也。”", "example": null}, {"def": "谚所谓辅车相依,唇亡齿寒”者,其虞、虢之谓也。--《左传》", "example": null}, {"def": "谚曰。--《史记·货殖列传》", "example": null}, {"def": "又如农谚;谚言(俗语、直语、直接明说的俗话);无知便是福”是个古谚", "example": null}, {"def": "谚", "example": null}, {"def": "通唁”。慰问死者家属", "example": null}, {"def": "谚者,直语也。丧言亦不及文,故吊亦称谚。--《文心雕龙·书记》", "example": null}, {"def": "谚", "example": null}, {"def": "粗野不恭", "example": null}, {"def": "乃逸乃谚,既", "example": null}, {"def": "谚yàn谚语，社会上流传的简练、通俗、具有固定性的语言民～。古～。", "example": null}]','chinese-xinhua','0'),
('2101143296964300802','滟','1','yàn','氵','13',NULL,'[{"def": "滟", "example": null}, {"def": "(形声。从水,艳声。本义水闪闪发光) 同本义", "example": null}, {"def": "水光潋滟晴方好。--苏轼《饮湖上初晴后雨》", "example": null}, {"def": "又如滟潋(水光耀貌);滟滟(水光貌)", "example": null}, {"def": "滟（灧）yàn", "example": null}]','chinese-xinhua','0'),
