('2101143296964300815','彦','1','yàn','彡','9',NULL,'[{"def": "彦", "example": null}, {"def": "(形声.小篆字形。从彣,厂声。彣,有文采。本义有才学的人)贤士。才德出众的人;贤才;俊才", "example": null}, {"def": "产,美士有彣也。--《说文》", "example": null}, {"def": "美士为彦。--《尔雅》", "example": null}, {"def": "人之彦圣。--《礼记·大学》", "example": null}, {"def": "彼其之子,邦之彦兮。--《诗·郑风·羔裘》", "example": null}, {"def": "又如彦哲(贤智之士);彦圣(善美明达,亦指善美明达之士);俊彦", "example": null}, {"def": "彦士", "example": null}, {"def": "彦yàn〈古〉称有才德的人。", "example": null}]','chinese-xinhua','0'),
('2101143296964300816','砚','1','yàn','石','9',NULL,'[{"def": "砚", "example": null}, {"def": "(形声。从石,见声。本义砚台,磨墨器)", "example": null}, {"def": "光滑的石头", "example": null}, {"def": "砚,石滑也。--《说文》。段玉裁注谓石性滑利也。", "example": null}, {"def": "砚,研也。研墨使和濡也。--《释名》", "example": null}, {"def": "砚台", "example": null}, {"def": "一砚。--清·周容《芋老人传》", "example": null}, {"def": "砚冰坚。--明·宋濂《送东阳马生序》", "example": null}, {"def": "又如砚瓦(砚台);笔砚", "example": null}, {"def": "砚", "example": null}, {"def": "制作砚", "example": null}, {"def": "砚yàn", "example": null}, {"def": "⒈磨墨用的文具～台。", "example": null}, {"def": "⒉有同学关系的～兄。", "example": null}]','chinese-xinhua','0'),
('2101143296964300817','唁','1','yàn','口','10',NULL,'[{"def": "唁", "example": null}, {"def": "(形声。从口,言声。本义对遭遇非常变故者的慰问◇多指对遭遇丧事的人的慰问)", "example": null}, {"def": "公孙于齐,齐侯唁公于野井。--《左传》", "example": null}, {"def": "又如唁奠(吊唁祭奠);唁劳(对遭丧事者进行慰问);唁慰(对死者家属表示安慰)", "example": null}, {"def": "唁yàn吊丧，对遭遇丧事者表示慰问～言。吊～。", "example": null}]','chinese-xinhua','0'),
('2101143296964300818','宴','1','yàn','宀','10',NULL,'[{"def": "宴", "example": null}, {"def": "(形声。从宀声。宀”表示房屋,妟”是安”意思,也有表意作用。本义请人吃饭喝酒,聚会在一起喝酒吃饭 )", "example": null}, {"def": "同本义", "example": null}, {"def": "宴,安也。--《说文》。按,此字当为宴飨正字,亦作醼,作讌。", "example": null}, {"def": "君子以饮食宴乐。--《易·需》。郑注宴,享宴也。”", "example": null}, {"def": "吉甫宴喜。--《汉书·陈汤传》引诗六月", "example": null}, {"def": "宾客大宴。--《虞初新志·秋声诗自序》", "example": null}, {"def": "太守宴。--宋·欧阳修《醉翁亭记》", "example": null}, {"def": "宴酣之乐。", "example": null}, {"def": "添酒回灯重开宴。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "又如宴犒(设宴犒赏);宴赏(设宴犒赏);宴饯(设宴招待);宴好(泛指宴饮聚会);宴衍", "example": null}, {"def": "宴yàn", "example": null}, {"def": "⒈用酒饭招待客人～客。今日良～会。", "example": null}, {"def": "⒉筵席，聚在一起吃酒饭设～。庆功～。", "example": null}, {"def": "⒊乐，快乐～乐。数年之不～。", "example": null}, {"def": "⒋安逸，安闲～居。～安鸩毒（鸩zhèn有毒的酒。贪图安逸享受等于喝毒酒自杀）。", "example": null}]','chinese-xinhua','0'),
('2101143296964300819','晏','1','yàn','日','10',NULL,'[{"def": "晏", "example": null}, {"def": "(形声。从日,安声。本义晴朗)", "example": null}, {"def": "同本义", "example": null}, {"def": "晏,天清也。--《说文》", "example": null}, {"def": "晏,明也。--《小尔雅》", "example": null}, {"def": "于是天清日晏。--杨雄《羽猎赋》。注无云之处也。”", "example": null}, {"def": "鷄日知晏阴蜡知雨。--《淮南子·缪称》。注无云也。”", "example": null}, {"def": "日出清济为晏。--《汉书·郊祀志上集》注", "example": null}, {"def": "又如晏日(晴天);晏阴(晴阴);晏温(天气晴暖)", "example": null}, {"def": "通安”(溁??)。平静;安逸", "example": null}, {"def": "以定晏阴之所成。--《礼记·月令》。注安也。阴称,晏。”", "example": null}, {"def": "而海内晏如。--《汉书·诸侯王表》。注安然也。”", "example": null}, {"def": "言笑晏晏。--《诗·卫风·氓》", "example": null}, {"def": "河清海晏,大德宽仁。╠", "example": null}, {"def": "晏yàn", "example": null}, {"def": "⒈晚，迟～起。～退。", "example": null}, {"def": "⒉〈古〉平静，平定清～。", "example": null}, {"def": "⒊通\\"宴\\"。筵席。", "example": null}]','chinese-xinhua','0'),
('2101143296964300820','艳','1','yàn','色','10',NULL,'[{"def": "艳", "example": null}, {"def": "从色。豷,丰大。色,色彩。丰大而有色彩。本义鲜艳,艳丽)", "example": null}, {"def": "同本义", "example": null}, {"def": "苂,好而长也。--《说文》", "example": null}, {"def": "目逆而送之,曰,美而艳。--《左传·桓公元年》", "example": null}, {"def": "艳妻煽方处。--《诗·小雅·十月之交》", "example": null}, {"def": "艳陆离些。--《楚辞·招魂》。注艳,好貌也。”", "example": null}, {"def": "窈窕艳城郭。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "又如艳色(常用以指美女、美色);艳段(宋元杂剧中,在正剧之前表演的一段短剧);艳质(美丽的姿质)", "example": null}, {"def": "文辞华丽", "example": null}, {"def": "信言不艳,贯居于好。--《三国志》", "example": null}, {"def": "又如艳才(写作美妙文章的才能)", "example": null}, {"def": "艳（苂、豾）yàn", "example": null}, {"def": "⒈长得漂亮美而～。", "example": null}, {"def": "⒉色彩鲜明，文辞华美～丽。鲜～。百花争～。信言不～。", "example": null}, {"def": "⒊喜爱，羡慕～羡。", "example": null}, {"def": "⒋指爱情方面的事～史。", "example": null}]','chinese-xinhua','0'),
('2101143296964300821','验','1','yàn','马','10',NULL,'[{"def": "验", "example": null}, {"def": "(形声。从马。佥声。本义马名)", "example": null}, {"def": "同本义", "example": null}, {"def": "验,马名。--《说文》", "example": null}, {"def": "证据;凭证", "example": null}, {"def": "何以为验。--《史记·晋世家》", "example": null}, {"def": "商君之法,舍人无验者坐之。--《史记·商君列传》", "example": null}, {"def": "又如验左(佐证;证据)", "example": null}, {"def": "效验,灵验", "example": null}, {"def": "自然之验。--《史记·货殖列传》", "example": null}, {"def": "又如验方(有效验的药方);明效大验(极为显著的效验)", "example": null}, {"def": "征象;征兆", "example": null}, {"def": "黄为物熟验,白为人老效。--《论衡》", "example": null}, {"def": "验", "example": null}, {"def": "检查;检验", "example": null}, {"def": "亦验其辞于正前。--《战国策·齐策》", "example": null}, {"def": "验之以理。--《吕氏春", "example": null}, {"def": "验（驗、騰）yàn", "example": null}, {"def": "⒈检查，察看～血。～光。～收。～证。", "example": null}, {"def": "⒉效果效～。应～。", "example": null}, {"def": "⒊〈古〉证据，凭证何以为～？", "example": null}]','chinese-xinhua','0'),
('2101143296964300822','燕','1','yàn','灬','16',NULL,'[{"def": "燕", "example": null}, {"def": "古国名", "example": null}, {"def": "周代诸侯国名。本作匽、郾。姬姓;周召公之后,世称北燕,拥有今河北省北部和辽宁省西端,建都蓟(今北京)。战国时成为七雄之一◇灭于秦", "example": null}, {"def": "燕赵韩魏。--《战国策·齐策》", "example": null}, {"def": "欲亡赵走燕。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "燕畏赵。", "example": null}, {"def": "燕赵之君。--宋·苏洵《六国论》", "example": null}, {"def": "燕赵之收藏,韩魏之经营,齐楚之精英。(互文,收藏、经营、精英均指金玉珍宝。)--唐·杜牧《阿房宫赋》", "example": null}, {"def": "燕地寒,花朝节后,余寒犹厉。(燕,古代燕国,这里指北京地区。)--明·袁宏道《满井游记》", "example": null}, {"def": "周代诸侯国名。姞姓;开国君主伯倏。在今河南省延津县东", "example": null}, {"def": "燕yān周代诸侯国名，战国时七雄之一，在今河北省北部和辽宁省南部一带。", "example": null}, {"def": "燕(鷰) yàn", "example": null}, {"def": "⒈燕子，翼尖而长，尾巴叉状像张开的剪刀。常见的有家～，它是候鸟，多在屋内或屋檐下用泥筑巢居住。捕食昆虫，是益鸟，要保护，禁止猎杀。", "example": null}, {"def": "⒉〈古〉通\\"宴\\"。酒宴，安闲～饮。～居。", "example": null}]','chinese-xinhua','0'),
('2101143296964300823','赝','1','yàn','贝','16',NULL,'[{"def": "赝", "example": null}, {"def": "(形声。从贝,雁声。本义假的,伪造的) 同本义", "example": null}, {"def": "居然见真赝。--韩愈《酬隹少府》", "example": null}, {"def": "又如赝钻石;赝作(伪造)", "example": null}, {"def": "赝本", "example": null}, {"def": "赝本杂出。--《翰墨志》", "example": null}, {"def": "赝币", "example": null}, {"def": "赝鼎", "example": null}, {"def": "文士既多赝鼎,佳人亦有虚名。--《五色石》", "example": null}, {"def": "赝碱", "example": null}, {"def": "赝品", "example": null}, {"def": "现在赝品充斥市场", "example": null}, {"def": "赝品", "example": null}, {"def": "赝yàn假的，伪造的～品。", "example": null}]','chinese-xinhua','0'),
