('2101143296964300825','曕','1','yàn','','6',NULL,'[{"def": "曕yàn 1.晒。", "example": null}]','chinese-xinhua','0'),
('2101143296964300826','堰','1','yàn','土','12',NULL,'[{"def": "堰", "example": null}, {"def": "(形声。从土,匽声。本义拦河坝)", "example": null}, {"def": "同本义", "example": null}, {"def": "东出千金堰。--《文选·沈约·三月三日率尔成篇诗》", "example": null}, {"def": "堰,潜堰也,潜筑土以壅水也。--《广雅》", "example": null}, {"def": "长分桥西有千金堰。--《洛阳伽蓝记》", "example": null}, {"def": "又如都江堰;堰塘(筑有堤堰的蓄水池);堰埭(截水的土堰);堰埭(壅水的土坝)", "example": null}, {"def": "田边用以分界或防止水土流失的土埂", "example": null}, {"def": "池塘", "example": null}, {"def": "桌椅板凳在田里堰里飘着。--闻一多《荒村》", "example": null}, {"def": "又如一口堰;满满的一堰水", "example": null}, {"def": "堰", "example": null}, {"def": "堵", "example": null}, {"def": "堰,壅水也。--《说文》", "example": null}, {"def": "谁家能堰东流水?--唐·卢照邻《行路难》", "example": null}, {"def": "堰yàn", "example": null}, {"def": "①挡水的低坝。", "example": null}, {"def": "② 田边用以分界或防止水土流失的埂子。", "example": null}, {"def": "堰yǎn 动词，筑堰堵塞。", "example": null}]','chinese-xinhua','0'),
('2101143296964300827','焰','1','yàn','火','12',NULL,'[{"def": "焰", "example": null}, {"def": "(形声。从火,臽声。本义火苗)", "example": null}, {"def": "同本义", "example": null}, {"def": "烟焰迷漫 。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "烟焰雾雨。--清·邵长蘅《青门剩稿》。又如内焰(火焰的中间部分);外焰(火焰最外层);焰段(见艳段”);焰烘烘(焰腾腾。火焰旺盛的样子;引申为情绪激昂);焰头上(喻", "example": null}, {"def": "指兴旺发达);焰焰(火苗起初的样子)", "example": null}, {"def": "火光;辉光", "example": null}, {"def": "凿石有余焰,年命已凋颓矣。--晋·葛洪《抱朴子》", "example": null}, {"def": "又如焰红(火红);焰光(光焰;光华);焰然(鲜明貌)", "example": null}, {"def": "光亮", "example": null}, {"def": "雨昏陋巷灯无焰,风过贫家壁有声。--袁枚《随园诗话》", "example": null}, {"def": "比喻气势", "example": null}, {"def": "焰（燄）yàn", "example": null}, {"def": "⒈火苗火～。〈喻〉气势气～。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒐\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296964300828','焱','1','yàn','火','12',NULL,'[{"def": "焱", "example": null}, {"def": "光华,光焰", "example": null}, {"def": "焱,光华也。--《说文》", "example": null}, {"def": "日暾暾其西舍兮,阳焱焱而复顾。--《楚辞》", "example": null}, {"def": "纷翼翼以徐戾兮,焱回回其扬灵。--《文选·张衡·思玄赋》", "example": null}, {"def": "又如焱飞(火花飞舞的样子);焱悠(火花飘舞);焱焰(火焰);焱焱(光采闪耀的样子);焱攸(焱悠);焱炎(形容太阳的光和热);焱烘烘(火炽热的样子)", "example": null}, {"def": "焱yàn火花，火焰。", "example": null}]','chinese-xinhua','0'),
