('2101143296964300846','衍','1','yǎn','行','9',NULL,'[{"def": "衍", "example": null}, {"def": "(会意。从水,从行。本义水流入海)", "example": null}, {"def": "水循河道流汇于海", "example": null}, {"def": "衍,水朝宗于海貌也。--《说文》", "example": null}, {"def": "至今衍于四海。--《书大传》。注犹溢也。”", "example": null}, {"def": "水直衍。--《太玄·法》。注达也。”", "example": null}, {"def": "溢出,水满而出", "example": null}, {"def": "东注太湖,衍溢陂池。--司马相如《上林赋》", "example": null}, {"def": "在中也。--《易·需》。虞注流也。”", "example": null}, {"def": "又如衍溢(水满溢);衍涝(谓雨水满溢)", "example": null}, {"def": "散开", "example": null}, {"def": "衍溢漂疾。--汉·枚乘《七发》", "example": null}, {"def": "分布", "example": null}, {"def": "千乘方毂,万骑骈罗,衍陈于岐、梁,东横乎大河。--《后汉书》", "example": null}, {"def": "通演”。推演;演述", "example": null}, {"def": "衍yǎn", "example": null}, {"def": "⒈蔓延，扩展推～。流～四方。", "example": null}, {"def": "⒉繁盛，余裕蕃～。国富人～。", "example": null}, {"def": "⒊多余的～文（书籍中多余的字句）。", "example": null}, {"def": "衍yán 1.引进;延聘。 2.祭名。 3.佛教语。梵文\\"摩诃衍\\"的省称。即所谓\\"乘\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296964300847','偃','1','yǎn','亻','11',NULL,'[{"def": "偃", "example": null}, {"def": "(形声。从人,匽声。本义仰卧;仰)", "example": null}, {"def": "同本义", "example": null}, {"def": "偃,僵也。--《说文》。按,伏而覆曰仆,仰而倒曰偃。", "example": null}, {"def": "偃,仰也。--《广雅》", "example": null}, {"def": "与一人俱毙,偃,且射子鉯。--《左传·定公八年》", "example": null}, {"def": "迎风则偃,背风则仆。--《吴越春秋》", "example": null}, {"def": "须臾祭毕,倦而偃。--《钟馗传--捉鬼传、平鬼传》", "example": null}, {"def": "或息偃在床。--《诗·小雅·北山》", "example": null}, {"def": "又如偃腹(仰腹而卧);偃寝(仰卧;躺下);偃斧(仰斧。指堆土为坟,坟顶窄狭如仰斧形状)", "example": null}, {"def": "通匽”。停止;停息", "example": null}, {"def": "反而定三革,偃五兵,合天下,立声乐。--《荀子》", "example": null}, {"def": "两君偃兵接好,日中为期", "example": null}, {"def": "偃yǎn", "example": null}, {"def": "⒈仰卧～在床。〈引〉向后倒，跟仆相对～跌于地。泛指倒下～旗息鼓。", "example": null}, {"def": "⒉停止，停息～武修文。～息争斗。", "example": null}]','chinese-xinhua','0'),
('2101143296964300848','厣','1','yǎn','厂','11',NULL,'[{"def": "厣", "example": null}, {"def": "蟹脐,蟹腹下面的薄壳", "example": null}, {"def": "厣（厴）yǎn", "example": null}, {"def": "⒈一般指螺类贝壳口处圆片状的盖，起保护的作用。", "example": null}, {"def": "⒉蟹腹部的薄壳，即蟹脐蟹～。", "example": null}]','chinese-xinhua','0'),
('2101143296964300849','掩','1','yǎn','扌','11',NULL,'[{"def": "掩", "example": null}, {"def": "(会意。从手,从奄,奄亦声。本义遮蔽)", "example": null}, {"def": "同本义", "example": null}, {"def": "掩,敛也。小上曰掩。--《说文》", "example": null}, {"def": "掩练帛,广终幅。--《仪礼·士丧礼》。注裹首也。”", "example": null}, {"def": "掩薄草渚。--《史记·司马相如传》", "example": null}, {"def": "空正掩日。--《周髀算经》", "example": null}, {"def": "掩口胡卢而笑。--《聊斋志异·促织》", "example": null}, {"def": "掩其上哉。--清·方域《壮梅堂文集》", "example": null}, {"def": "手巾掩口。--《玉台新咏·古诗为焦仲卿妻作》", "example": null}, {"def": "势拔五岳掩赤诚。--唐·李白《梦游天姥吟留别》", "example": null}, {"def": "又如掩圹(将棺木放入墓穴内,加土掩埋);掩心(护胸的铠甲);掩土(盖土埋葬);掩面(盖在尸体面部的白色的布或绢);掩著(掩盖剽窃", "example": null}, {"def": "掩（搑）yǎn", "example": null}, {"def": "⒈遮蔽，遮盖～盖。～耳。～饰。遮～。", "example": null}, {"def": "⒉关，合上～门。～卷。", "example": null}, {"def": "⒊关闭门、窗、箱等的时候被夹住关柜子～着了手。", "example": null}, {"def": "⒋乘其不备～入。～捕。～攻。～杀。", "example": null}, {"def": "⒌", "example": null}, {"def": "①用火力等压住敌方，以保护自己一方的进攻或转移。", "example": null}, {"def": "②利用某种条件或方式暗中保护那里有段土墙可作～护。秘密～护。", "example": null}]','chinese-xinhua','0'),
('2101143296964300850','眼','1','yǎn','目','11',NULL,'[{"def": "眼", "example": null}, {"def": "(形声。从目,艮声。本义眼珠)", "example": null}, {"def": "同本义", "example": null}, {"def": "眼,目也。--《说文》", "example": null}, {"def": "眼,限也。瞳子限限而出也。--《释名》", "example": null}, {"def": "巽为多白眼。--《易·说卦》", "example": null}, {"def": "比干剖心,子胥抉眼,忠之祸也。--《庄子·盗跖》", "example": null}, {"def": "泛指眼睛", "example": null}, {"def": "莫自使眼枯,收汝泪纵横。--杜甫《新安吏》", "example": null}, {"def": "又如眼馋肚饱(贪得无厌;不知足);眼意心期(眼中传意,心中期待);眼黄地黑(心怀叵测,见财起意);眼空四海(目中无人,妄自尊大);眼张失道(睁大眼睛,说不出话来。形容受惊而痴呆的样子);眼里出火(形容极贪婪的神情);眼同检验(会同人员,共同检验)。", "example": null}, {"def": "眼yǎn", "example": null}, {"def": "⒈眼睛，视觉器官～前。亲～所见。", "example": null}, {"def": "⒉孔洞，窟窿窗～。漏～。针～。钻个～儿。", "example": null}, {"def": "⒊关节，要点腰～。节骨～上。讲究字～。", "example": null}, {"def": "⒋戏曲的节拍有板有～。", "example": null}, {"def": "⒌围棋中几个子围住的一个交叉点。", "example": null}, {"def": "⒍量词打两～井。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①视线。", "example": null}, {"def": "②见识，眼力～光远大。～光锐利。", "example": null}, {"def": "眼wěn 1.谓如大眼之突出。", "example": null}]','chinese-xinhua','0'),
