('2101143296964300911','洋','1','yánɡ','氵','9',NULL,'[{"def": "洋", "example": null}, {"def": "(形声。从水,羊声。本义古水名)", "example": null}, {"def": "同本义", "example": null}, {"def": "洋水", "example": null}, {"def": "昆仓之丘…洋水出焉,而西南流注于丑涂之水。--《山海经》", "example": null}, {"def": "又名西乡河。在陕西省南部。源出西乡县星子山,北流合木马河会于西乡县东,东北流注于汉水", "example": null}, {"def": "汉水又东,右会洋水。--《水经注》", "example": null}, {"def": "旧指海之中心。亦泛指海域", "example": null}, {"def": "旧称银币为洋钱,简称洋", "example": null}, {"def": "洋", "example": null}, {"def": "盛多、广大", "example": null}, {"def": "洋,多也。--《尔雅》。注洋,溢也。”", "example": null}, {"def": "洋yáng", "example": null}, {"def": "①众多。", "example": null}, {"def": "②广大;盛大。", "example": null}, {"def": "③旧指海之中心。亦泛指海域。", "example": null}, {"def": "④今指地球表面上广袤的水域，约占地球总面积的十分之七﹑海洋总面积的百分之八十九。分为四个部分。即太平洋﹑大西洋﹑印度洋﹑北冰洋。", "example": null}, {"def": "⑤外国的;来自外国的。", "example": null}, {"def": "⑥新奇，与众不同。", "example": null}, {"def": "⑦指现代化的(区别于\\"土\\")。", "example": null}, {"def": "⑧洋钱，银元。", "example": null}, {"def": "⑨用同\\"烊\\"。熔化;溶化。", "example": null}, {"def": "⑩用同\\"漾\\"。晃动。", "example": null}, {"def": "⑾用同\\"漾\\"。抛掷。", "example": null}, {"def": "⑿水名。又名西乡河。在陕西省南部。源出西乡县星子山，北流合木马河会于西乡县东，东北流注于汉水。参阅清顾祖禹《读史方舆纪要．陕西五．汉中府》。", "example": null}, {"def": "洋yǎng \\"洋洋\\"﹑\\"洋然\\"。", "example": null}, {"def": "洋xiáng", "example": null}, {"def": "①通\\"翔\\"。引申指翼﹑侧。", "example": null}, {"def": "②通\\"祥\\"。福，赐福。", "example": null}, {"def": "③通\\"祥\\"。祥和。参见\\"洋飈\\"。", "example": null}, {"def": "④古水名。即今山东省的弥河。参阅《说文．水部》\\"洋，水\\"段玉裁注。", "example": null}, {"def": "⑤古州名。本为汉成固县，秦为汉中郡，北周为洋州，唐为洋州，均治今陕西省西乡县，明初改为洋县。参阅清顾祖禹《读史方舆纪要．陕西五．汉中府》。", "example": null}]','chinese-xinhua','0'),
('2101143296968495104','昫','1','yánɡ','日','7',NULL,'[{"def": "昫", "example": null}, {"def": "(形声。从日,?", "example": null}, {"def": "同本义", "example": null}, {"def": "昫,日出也。--《说文》", "example": null}, {"def": "曰昫谷。--《书·尧典》。传明也。”", "example": null}, {"def": "昫谷搏桑在东方。--《淮南子·地形》", "example": null}, {"def": "又如昫谷(古称日出之处)", "example": null}, {"def": "太阳", "example": null}, {"def": "薄吹消春冻,新昫破晓晴。--蔡襄《自渔梁驿至衢州大雪有怀》", "example": null}, {"def": "又如昫乌(太阳)", "example": null}, {"def": "昫", "example": null}, {"def": "晴;晴天", "example": null}, {"def": "昫（暘）yáng", "example": null}, {"def": "⒈晴天。", "example": null}, {"def": "⒉日出晨～。", "example": null}]','chinese-xinhua','0'),
('2101143296968495105','烊','1','yánɡ','火','10',NULL,'[{"def": "烊", "example": null}, {"def": "(形声。从火,羊声。本义金属熔化)", "example": null}, {"def": "半霎功夫,墨盒里冒白气,下半边已烊了。--《老残游记》", "example": null}, {"def": "又如烊铜热铁(烧热的铜铁器具。借指地狱中烙烫之类的刑具)", "example": null}, {"def": "烊yàng", "example": null}, {"def": "烊yáng熔化金属～铅。〈引〉（方言）溶化这包糖～了。", "example": null}]','chinese-xinhua','0'),
