('2101143296968495117','漾','1','yànɡ','氵','14',NULL,'[{"def": "漾", "example": null}, {"def": "古水名。漾水", "example": null}, {"def": "汉水上流,源出陕西省宁羌县北潘冢山", "example": null}, {"def": "即今嘉陵江上源的西汉水", "example": null}, {"def": "漾,漾水。出陇西相氐道,东至武都为汉。--《说文》", "example": null}, {"def": "漾", "example": null}, {"def": "水动荡。水面上起波纹;有细浪起伏", "example": null}, {"def": "涟漪繁波漾。--谢惠连《泛南湖至石帆》", "example": null}, {"def": "又如漾驰(水流平缓)", "example": null}, {"def": "因充满或盛满而溢出", "example": null}, {"def": "泛,荡", "example": null}, {"def": "飘动;晃动", "example": null}, {"def": "抛掷;丢弃", "example": null}, {"def": "把一大块石头漾在奉符县河里。--《喻世明言》", "example": null}, {"def": "又如漾开(抛开;离开);漾砖(投掷砖块)", "example": null}, {"def": "漾yàng", "example": null}, {"def": "⒈水动荡的样子微波荡～。", "example": null}, {"def": "⒉充满而溢出来茶水～了。奶～出来了。", "example": null}]','chinese-xinhua','0'),
('2101143296968495118','怏','1','yànɡ','忄','8',NULL,'[{"def": "怏", "example": null}, {"def": "(形声。从心,央声。《说文》不服怼也”。本义不满意、不服气的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "怏,心不服也。--《说文》", "example": null}, {"def": "郁郁不乐", "example": null}, {"def": "辛垣衍怏然不悦。--《战国策》", "example": null}, {"def": "又如怏恨(怨恨);怏悒(郁郁不乐的样子);怏闷(郁闷);怏怅(抱歉)", "example": null}, {"def": "怏", "example": null}, {"def": "勉强;强求", "example": null}, {"def": "怏他一路上汤风打浪。--元·关汉卿《拜月亭》", "example": null}, {"def": "无夜无明怏着也。--《牡丹亭》", "example": null}, {"def": "怏yàng不满意，不服气～然不悦。～ ～不服。", "example": null}]','chinese-xinhua','0'),
('2101143296968495119','恙','1','yànɡ','心','10',NULL,'[{"def": "恙", "example": null}, {"def": "(形声。从心,羊声。本义担忧)", "example": null}, {"def": "同本义", "example": null}, {"def": "何恙不已。--《史记》", "example": null}, {"def": "疾病", "example": null}, {"def": "当年秦大爷患恙,在我家庄上,住了年余,怎说不认得?--《隋唐演义》", "example": null}, {"def": "君其专精神,微恙不足论。--秦观《答文潜病中见寄》", "example": null}, {"def": "又如贱恙", "example": null}, {"def": "恙虫", "example": null}, {"def": "恙yàng病微～。平安无～。", "example": null}]','chinese-xinhua','0'),
('2101143296968495120','样','1','yànɡ','木','10',NULL,'[{"def": "样", "example": null}, {"def": "(形声。从木,羕声。本义栩实,字亦作橡)", "example": null}, {"def": "假借为像”。式样", "example": null}, {"def": "去年中使宣口敕,天上取样人间织。--唐·白居易《缭绫》", "example": null}, {"def": "又如样银(用于测定银子成色的样品);样儿(样子。指可供人模仿的式样或效法的标准);样子间(陈列样品的处所);样米(作为样品的米);样物(作为样品之物);样度(样式,法式)", "example": null}, {"def": ";样当(样子,模样);样制(物品的样式);样钱(钱币铸成后呈验的样品)", "example": null}, {"def": "形状,模样", "example": null}, {"def": "映日荷花别样红。--宋·杨万里《晓出净慈寺送林子方》", "example": null}, {"def": "又如样法(样范);样色(花样);式样(人造的物体的形状);走样(失去原来的样子);花样", "example": null}, {"def": "样（樣）yàng", "example": null}, {"def": "⒈形状～子。模～儿。走了～。", "example": null}, {"def": "⒉种类这两～。那几～。一个～儿。～ ～都行。", "example": null}, {"def": "⒊作为标准或代表的榜～。～板。～品儿。货～子。", "example": null}, {"def": "样xiàng 1.橡实。即栎实。", "example": null}]','chinese-xinhua','0'),
