('2101143296968495139','鞅','1','yānɡ','革','14',NULL,'[{"def": "鞅", "example": null}, {"def": "(形声。从革,央声。革,去了毛的兽皮。本义套在马颈或马腹上的皮带)", "example": null}, {"def": "同本义", "example": null}, {"def": "鞅,颈靼也。--《说文》", "example": null}, {"def": "绣鞅璁珑走钿车。--杜牧《街西长句》诗", "example": null}, {"def": "又如鞅绊(拘系马腹和马脚的绳带);鞅轭(马驾具);鞅勒(套马的绳带和勒马的索)", "example": null}, {"def": "借指车马", "example": null}, {"def": "野外罕人事,穷巷寡轮鞅。--陶潜《归园田居》", "example": null}, {"def": "姓", "example": null}, {"def": "鞅", "example": null}, {"def": "通怏”。郁郁不乐的样子", "example": null}, {"def": "心常鞅鞅。--《汉书·高帝纪》", "example": null}, {"def": "居常鞅鞅。--《汉书·韩信传》。注志不满也。”", "example": null}, {"def": "鞅yāng", "example": null}, {"def": "⒈〈古〉套在马脖子上的皮带，使马拉车。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "鞅yàng", "example": null}]','chinese-xinhua','0'),
('2101143296968495140','泱','1','yānɡ','氵','8',NULL,'[{"def": "泱", "example": null}, {"def": "(形声。从水,央声。本义水面广阔的)", "example": null}, {"def": "同本义", "example": null}, {"def": "泱,滃也。--《说文》", "example": null}, {"def": "瞻波洛矣,维水泱泱。--《诗·小雅·瞻波洛矣》", "example": null}, {"def": "云山苍苍,江水泱泱。--宋·范仲淹《严先生祠堂记》", "example": null}, {"def": "又如泱漭(广大无涯际的样子)", "example": null}, {"def": "气魄宏大的", "example": null}, {"def": "宅大齐之墟,振泱之风。--《晋书·齐王冏传》", "example": null}, {"def": "又如泱泱大国", "example": null}, {"def": "泱", "example": null}, {"def": "流;淌", "example": null}, {"def": "泱泱,流也。--《广雅》", "example": null}, {"def": "那佛祖轻轻用力撑开,只见上溜头泱下一个死尸。--《西游记》", "example": null}, {"def": "又如泱荡(荡漾)", "example": null}, {"def": "泱yāng", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉", "example": null}, {"def": "泱yǎng 1.见\\"泱漭\\"﹑\\"泱郁\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296968495141','殃','1','yānɡ','歹','9',NULL,'[{"def": "殃", "example": null}, {"def": "(形声。从歺,央声。歺,剔肉后残剩的骨头。多与死亡、灾祸有关。本义祸害,灾难) 同本义", "example": null}, {"def": "殃,咎也。--《说文》", "example": null}, {"def": "殃,败也。--《广雅》", "example": null}, {"def": "殃,禍也。--《释言》", "example": null}, {"def": "众以为殃。--《礼记·礼运》", "example": null}, {"def": "积善之家,必有余庆;积不善之家,必有余殃。--《易·坤》", "example": null}, {"def": "伍子逢殃兮。--《楚辞·屈原·涉江》", "example": null}, {"def": "又如殃煞(骂人话。祸害;灾星祸祟);殃榜(丧亡榜书);殃人货(骂人话。给人带来灾祸的东西);殃咎(灾祸);殃毒(祸害);殃祸(灾祸);殃孽(奸邪);遭殃;灾殃", "example": null}, {"def": "殃", "example": null}, {"def": "使受祸害败坏;为害", "example": null}, {"def": "不教民而用之,谓之殃民。╠", "example": null}, {"def": "殃yāng", "example": null}, {"def": "⒈祸害灾～。遭～。", "example": null}, {"def": "⒉残害祸国～民。", "example": null}]','chinese-xinhua','0'),
