('2101143296968495163','徭','1','yáo','彳','13',NULL,'[{"def": "徭", "example": null}, {"def": "通徭”", "example": null}, {"def": "姓", "example": null}, {"def": "徭", "example": null}, {"def": "(形声。从彳", "example": null}, {"def": "同本义", "example": null}, {"def": "徭役多则民苦。--《韩非子·备内》", "example": null}, {"def": "又如徭力(工役劳力);徭夫(服劳役的民夫)", "example": null}, {"def": "历史文献对瑶族的称谓", "example": null}, {"def": "徭役", "example": null}, {"def": "徭（傜）、繇yáo徭役（〈古〉统治者强迫人民承担的无偿劳动）。", "example": null}]','chinese-xinhua','0'),
('2101143296968495164','摇','1','yáo','扌','13',NULL,'[{"def": "摇", "example": null}, {"def": "(形声。从手,本义摇动;摆动)", "example": null}, {"def": "同本义", "example": null}, {"def": "摇,动也。--《说文》", "example": null}, {"def": "摇,作也。--《尔雅》", "example": null}, {"def": "摇者不定。--《管子·心术》", "example": null}, {"def": "复命摇作。--《庄子·则阳》", "example": null}, {"def": "夹而摇之。--《考工记·矢人》", "example": null}, {"def": "四顾何茫茫,东风屹草。--《古诗十九首》", "example": null}, {"def": "蒙络摇缀。--唐·柳宗元《至小丘西小石潭记》", "example": null}, {"def": "痒不得搔,痹不得摇。--柳宗元《断刑论》", "example": null}, {"def": "摇头而歌。--清·黄宗羲《柳敬亭传》", "example": null}, {"def": "动摇承之。--清·姚鼐《登泰山记》", "example": null}, {"def": "又如摇旗打鼓(四处张扬,闹得满城风雨);摇铃打鼓(摇旗打鼓);摇飍(亿颤动。形容女人走路的妖娆姿态);摇风(谓风吹摆动", "example": null}, {"def": "摇yáo", "example": null}, {"def": "⒈摆动～摆。～动。～晃。～手。树枝～。", "example": null}, {"def": "⒉转动～纱。", "example": null}, {"def": "⒊变动，不坚定动～。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍［飘摇］［飘飖］随风摆动。", "example": null}]','chinese-xinhua','0'),
