('2101143296968495176','繇','1','yáo','糸','17',NULL,'[{"def": "繇", "example": null}, {"def": "(形声。从系,本义随从)", "example": null}, {"def": "同本义", "example": null}, {"def": "鲁颜无繇。--《史记·弟子传》", "example": null}, {"def": "动摇", "example": null}, {"def": "我起乎宜阳而触平阳,二日而莫不尽繇。--《史记》", "example": null}, {"def": "繇", "example": null}, {"def": "力役,通徭”", "example": null}, {"def": "繇者揭钁,负笼土。--《淮南子·精神》。高注繇役也。”", "example": null}, {"def": "每吴中有大繇役及丧。--《史记·项羽本纪》", "example": null}, {"def": "减太官,省繇赋。--《汉书·景帝纪》", "example": null}, {"def": "又如繇戍(遣民到边境戍守,服役。同徭戍);繇役(古代百姓为朝庭服劳役的义务。同徭役);繇使(指供力役及为使者);繇赋(徭役和田赋捐税)", "example": null}, {"def": "通谣”。歌谣", "example": null}, {"def": "参人民繇俗。--《汉书·李寻传》。颜师古", "example": null}, {"def": "繇yóu", "example": null}, {"def": "⒈〈古〉同\\"由", "example": null}, {"def": "⒉", "example": null}, {"def": "⒍\\"。", "example": null}, {"def": "繇zhòu", "example": null}, {"def": "⒈〈古〉卜辞。", "example": null}, {"def": "繇yáo 1.草木茂盛貌。 2.通\\"徭\\"。徭役。 3.通\\"謡\\"。歌谣。 4.通\\"遥\\"。远。 5.通\\"摇\\"。动摇，摇动。 6.通\\"陶\\"。 7.古族名。古代越人的一支。原属闽越族，秦", "example": null}, {"def": "汉时分布在今福建北部﹑浙江南部的部分地区。 8.姓『有繇延。见《后汉书．郅恽传》。", "example": null}]','chinese-xinhua','0'),
('2101143296968495177','轺','1','yáo','车','9',NULL,'[{"def": "轺", "example": null}, {"def": "古代轻便的小马车", "example": null}, {"def": "轺,小车也。--《说文》", "example": null}, {"def": "朱家乃乘轺车之洛阳。--《史记·季布列传》", "example": null}, {"def": "亲迎立轺并马。--《汉书·平帝纪》", "example": null}, {"def": "又如轺车(用一匹马拉的轻便车子。可当兵车);轺轩(轻便的马车。也作轺辂、轺驾)", "example": null}, {"def": "使节所用之车", "example": null}, {"def": "轺yáo", "example": null}]','chinese-xinhua','0'),
