('2101143296968495185','耀','1','yào','羽','20',NULL,'[{"def": "耀", "example": null}, {"def": "(形声。从光,翟声。本义照耀)", "example": null}, {"def": "同本义", "example": null}, {"def": "耀,照也。--《说文》", "example": null}, {"def": "焜燿寡人之望。--《左传·昭公三年》", "example": null}, {"def": "以淳耀燿大。--《国语·郑语》", "example": null}, {"def": "星耀而玄运。--《淮南子·览冥》", "example": null}, {"def": "光远而自他有耀者也。--《左传》", "example": null}, {"def": "又如耀目晶光(光彩夺目);耀夜(萤火虫的别名);耀芒(光芒照射);耀采(光彩照耀);耀亮(照亮);耀燿(光辉照耀)", "example": null}, {"def": "晃眼", "example": null}, {"def": "炫耀", "example": null}, {"def": "耀明于子。--唐·柳宗元《柳河东集》", "example": null}, {"def": "又如夸耀;耀师(显示军队的威力;光荣出师);耀名(炫示虚名)", "example": null}, {"def": "显示;显耀", "example": null}, {"def": "耀灵。--《后", "example": null}, {"def": "耀（燿）yào", "example": null}, {"def": "⒈光线照射阳光照～。格外～眼。〈引〉光明增～。", "example": null}, {"def": "⒉显示，显扬夸～。炫～。～武扬威￡（大）谋～其奇（奇神奇）。", "example": null}, {"def": "⒊光荣荣～。", "example": null}, {"def": "耀shuò 1.销熔。", "example": null}, {"def": "耀shào 1.细长。", "example": null}]','chinese-xinhua','0'),
('2101143296968495186','药','1','yào','艹','9',NULL,'[{"def": "药", "example": null}, {"def": "(形声。从苃,乐声。本义治病的物品。药物;药材。一般是植物,故从苃)", "example": null}, {"def": "同本义", "example": null}, {"def": "药,治病草也。--《说文》", "example": null}, {"def": "以五味五谷五药养其病。--《周礼·疾医》。注五药,草木虫石谷也。”", "example": null}, {"def": "勿药有喜。--《易·无妄》", "example": null}, {"def": "求仙人不死之药。--《史记》", "example": null}, {"def": "又如药肆(药店);药贴(处方单);药封(用红纸袋封送的诊断费);药案(药方);药王(指治病用药如神的人);药引(中医处方中先选某种药物作为其他药物的导引,使药力可以达到", "example": null}, {"def": "病处,称为药引);药局(专司配药剂的机构;俗称出卖药品的部门为药局);药", "example": null}, {"def": "药（藥）yào", "example": null}, {"def": "⒈治病的物品中～。开～方。～物治疗。", "example": null}, {"def": "⒉有某些作用的化学物品火～。炸～。农～。消毒～。", "example": null}, {"def": "⒊治疗无可救～。", "example": null}, {"def": "⒋（用药物）毒杀～老", "example": null}, {"def": "药shuò 1.热貌。", "example": null}]','chinese-xinhua','0'),
('2101143296968495187','要','1','yào','覀','9',NULL,'[{"def": "要", "example": null}, {"def": "(象形。小篆字形。中间象人形,两旁为两手形。表示两手叉腰。本义人腰)", "example": null}, {"def": "腰”的古字", "example": null}, {"def": "昔者,楚灵王好细要。--《墨子》", "example": null}, {"def": "户服艾以盈要兮,谓幽兰其不可佩。--《楚辞》", "example": null}, {"def": "故量食而食之,量要而带之。--《荀子·礼论》", "example": null}, {"def": "又如要膂(腰和脊骨。比喻重要部位);要章(腰间所佩的印);要支(腰肢)", "example": null}, {"def": "五服之一。古代指离都城一千五百里至二千里的地区", "example": null}, {"def": "远之地为荒服,泛指远方之国);要蛮(极偏远的蛮荒之地)", "example": null}, {"def": "姓", "example": null}, {"def": "要", "example": null}, {"def": "约", "example": null}, {"def": "要yāo", "example": null}, {"def": "⒈求～求。", "example": null}, {"def": "⒉强求，仗势强求～狭。", "example": null}, {"def": "⒊〈古〉同\\"腰\\"及\\"邀\\"～带。～请。", "example": null}, {"def": "⒋", "example": null}, {"def": "①提出具体的，希望实现的～求加入共青团。～求到最需要人的地方去。", "example": null}, {"def": "②要达到的目的和目标可以满足你的这个要～。", "example": null}, {"def": "要yào", "example": null}, {"def": "⒈索取，希望得到～账。～束鲜花。", "example": null}, {"def": "⒉叫，请求他～你去一趟。", "example": null}, {"def": "⒊应该，必须～自觉。～努力工作。", "example": null}, {"def": "⒋即将将～。快～。天～晴了。", "example": null}, {"def": "⒌若，如果～是。他～不来，你就去。", "example": null}, {"def": "⒍重大，关键～事。～件。～害。～领。～紧。紧～。重～。", "example": null}, {"def": "⒎概括，总括概～。提～。纲～。", "example": null}, {"def": "⒏保留，作为己有这本书她还～咧。", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "要yǎo 1.见\\"要褭\\"。", "example": null}]','chinese-xinhua','0'),
