('2101143296968495222','腰','1','yāo','月','13',NULL,'[{"def": "腰", "example": null}, {"def": "(形声。从肉,要声。本作要”。本义紧接肋或胸以下的部分;胸和髋之间的身体的一部分)", "example": null}, {"def": "同本义", "example": null}, {"def": "楚王好细腰,宫中多饿死。--《后汉书》", "example": null}, {"def": "又如腰板(人的腰和背。多就姿势而言。亦借指体格);腰腿(腰部和腿部的活动能力)", "example": null}, {"def": "肾脏的俗称", "example": null}, {"def": "指所穿衣服在身体的腰部的部分", "example": null}, {"def": "缝在衣服里面的或旁边开口的小袋", "example": null}, {"def": "指某物的中部或中间部分", "example": null}, {"def": "半山腰", "example": null}, {"def": "又如腰房(两进院子中间的房子);腰封(束在礼品中间的绢带,上面写明送礼者和收礼人的名号);腰门(中门", "example": null}, {"def": "腰yāo", "example": null}, {"def": "⒈身体的中部，胁下胯上的部分～部。弯～。", "example": null}, {"def": "⒉裤、裙等围腰的部分裤～。", "example": null}, {"def": "⒊事物的中间、中段或当中狭窄像腰的部分山～。～。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143296968495223','邀','1','yāo','辶','16',NULL,'[{"def": "邀", "example": null}, {"def": "(形声。从辵,敫声。本义迎候)", "example": null}, {"def": "同本义", "example": null}, {"def": "邀相见。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "邀我至田家。--唐·孟浩然《过故人庄》", "example": null}, {"def": "北邀当国者。--宋·文天祥《指南录·后序》", "example": null}, {"def": "邀见讲钧礼。--清·周容《芋老人传》", "example": null}, {"def": "又如邀接(迎接);邀迓(迎请);邀迎(迎合)", "example": null}, {"def": "逢,遇到", "example": null}, {"def": "邀殊宠,一枝已傍日边红。--清·洪昻《长生殿》", "example": null}, {"def": "又如邀世(逢世);邀乐(遇到欢乐);邀天晴(逢天晴);邀幸(侥幸,幸运)", "example": null}, {"def": "阻拦;截击", "example": null}, {"def": "又怕山北诸州出兵,邀其归路而击之。--《新编五代史平话》", "example": null}, {"def": "又如邀截(阻截);邀留(婉", "example": null}, {"def": "邀yāo", "example": null}, {"def": "⒈约，请～请。特～。应～。", "example": null}, {"def": "⒉求取，希望得到～功。～准还乡。", "example": null}, {"def": "⒊迎候，半路拦截～路。～击。～截。", "example": null}]','chinese-xinhua','0'),
('2101143296968495224','幺','1','yāo','幺','3',NULL,'[{"def": "么", "example": null}, {"def": "小;幼小", "example": null}, {"def": "幺,小也。象子初生之形。俗字作么。--《说文》", "example": null}, {"def": "不长曰幺。--《通俗文》", "example": null}, {"def": "幺麽皆微小之称也。--《汉书·叙传注》", "example": null}, {"def": "又如幺微(微小);幺店(幺店子。路边的小店)", "example": null}, {"def": "细", "example": null}, {"def": "熠熠宵行,虫之微么;出自腐草,烟若散熛。--晋·郭璞《尔雅图赞》", "example": null}, {"def": "又如幺微(细微);幺蔑(细微);幺么(细小);幺魔(微小,细微);幺小(微小);幺末(细微);幺算(细致的考虑);幺袅(柔条摆动的样子);幺弱(瘦小赢弱);幺弦(幺弦。琵琶的第四弦", "example": null}, {"def": ",借指琵琶)", "example": null}, {"def": "指排行最末的", "example": null}, {"def": "幺yāo", "example": null}, {"def": "⒈小，排列最末的～婶。～妹。又\\"一\\"的另一个说法～二三。", "example": null}, {"def": "⒉［幺麽］微小～麽小丑。", "example": null}]','chinese-xinhua','0'),
('2101143296968495225','夭','1','yāo','大','4',NULL,'[{"def": "夭〈名〉", "example": null}, {"def": "刚出生的兽或禽", "example": null}, {"def": "毋覆巢,毋胎夭。--《淮南子》", "example": null}, {"def": "畋不掩群,不取麛夭;不涸泽而渔,不焚林而猎。--吴伯箫《猎户》", "example": null}, {"def": "初生的草木", "example": null}, {"def": "泽不伐夭。--《国语》", "example": null}, {"def": "夭  yao", "example": null}, {"def": "(象形。小篆字形,象头部屈曲的样子。本义屈,摧折) 同本义", "example": null}, {"def": "夭,屈也。--《说文》。按,从大而屈其首,指事,申者,腰之直,夭者头之曲。", "example": null}, {"def": "申申如也,夭夭如也。--《论语》", "example": null}, {"def": "毋伐木,毋夭英,毋附竿。--《管子·禁藏》", "example": null}, {"def": "又如夭英(折断幼苗)", "example": null}, {"def": "夭", "example": null}, {"def": "短命,早死。未成年而死", "example": null}, {"def": "少壮而死曰夭。--《释名》", "example": null}, {"def": "不殀夭。--", "example": null}, {"def": "夭（殀)yāo", "example": null}, {"def": "⒈", "example": null}, {"def": "①茂盛美丽桃之～ ～。", "example": null}, {"def": "②颜色和悦燕居（闲居）从容，申申～ ～（申申安详舒适）。", "example": null}, {"def": "⒉短命，早死～折。～亡。", "example": null}, {"def": "夭ǎo 1.动植物之初生者。", "example": null}, {"def": "夭wāi 1.见\\"夭斜\\"。", "example": null}, {"def": "夭wò 1.地名。", "example": null}]','chinese-xinhua','0'),
('2101143296968495226','吆','1','yāo','口','6',NULL,'[{"def": "吆", "example": null}, {"def": "大声喊。通常指大声斥责人,大声驱赶牲口,高声叫卖,喊劳动号子等", "example": null}, {"def": "现在皇帝还着人吆跑了。--《大波》", "example": null}, {"def": "又如吆号子(大声唱吆号子”);吆卖(大声叫卖);吆天喝地(大声喊叫);吆吆喝喝(大声喊叫)", "example": null}, {"def": "吆yāo", "example": null}]','chinese-xinhua','0'),
('2101143296968495227','妖','1','yāo','女','7',NULL,'[{"def": "妖", "example": null}, {"def": "(形声。从女,夭声。)", "example": null}, {"def": "同本义", "example": null}, {"def": "妖,妍也。--《三苍》", "example": null}, {"def": "妖夫曳衔。--《楚辞·天问》", "example": null}, {"def": "妖冶闲都。--《汉书·司马相如传》。注妖冶,美好也。”", "example": null}, {"def": "妖姬静女。--清·侯方域《壮梅堂文集》", "example": null}, {"def": "又如妖妍(艳丽);妖姿(艳丽的姿容);妖异(美艳奇异);妖丽(艳丽);妖靡(艳丽华美);妖蛊(艳丽);妖姬(美女);妖玩(美女)", "example": null}, {"def": "怪诞,怪异", "example": null}, {"def": "妖媚。淫邪,不正", "example": null}, {"def": "梁冀妻孙寿,色美而善为妖态,作愁眉。--《后汉书》", "example": null}, {"def": "又如妖红(妇", "example": null}, {"def": "妖yāo", "example": null}, {"def": "⒈神话传说或迷信者称\\"异常而且害人的怪物\\"～怪。～精。～魔。～术。～雾。", "example": null}, {"def": "⒉〈古〉称一切反常的东西或现象天反时为灾，地反物为～。", "example": null}, {"def": "⒊打扮奇特，神态不正派～里～气。", "example": null}, {"def": "⒋艳丽，美好～娆。～容姿。", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
