('2101143296972689469','荑','1','yí','艹','9',NULL,'[{"def": "荑〈名〉ti", "example": null}, {"def": "(形声。从苃,夷声。本义茅草的嫩芽)", "example": null}, {"def": "同本义,引申之为草木嫩芽", "example": null}, {"def": "荑,荑草也。--《说文》。按,茅之初生也。", "example": null}, {"def": "自牧归荑。--《诗·邶风·静女》", "example": null}, {"def": "手如柔荑,肤如凝脂。--《诗·卫风·硕人》", "example": null}, {"def": "五谷者,种之美者也;苟为不熟,不如荑稗。--《孟子·告子上》", "example": null}, {"def": "荑者,茅始熟中穰也,既白且滑。--《风俗通》", "example": null}, {"def": "又如荑英(新生的草);荑杨(新生的杨树)", "example": null}, {"def": "通稊”。草名。一种像稗子的草", "example": null}, {"def": "炳复次禁枯树,树即生荑。--《后汉书·方术传》", "example": null}, {"def": "生繁华于枯荑。--《晋书·元帝纪》", "example": null}, {"def": "荑yí", "example": null}, {"def": "⒈除去田地里的野草。", "example": null}, {"def": "⒉见tí㈠。", "example": null}, {"def": "荑tí", "example": null}, {"def": "⒈初生的茅草。", "example": null}, {"def": "⒉草木初生的嫩芽。", "example": null}, {"def": "⒊稗子一类的草。", "example": null}]','chinese-xinhua','0'),
('2101143296972689470','贻','1','yí','贝','9',NULL,'[{"def": "贻", "example": null}, {"def": "(形声。从贝,台声。从贝”,与财富有关。本义赠送)", "example": null}, {"def": "同本义", "example": null}, {"def": "贻我彤管。--《诗·邶风·静女》", "example": null}, {"def": "美人之贻。", "example": null}, {"def": "余嘉其能行古道,作《师说》以贻之。--唐·韩愈《师说》", "example": null}, {"def": "尝贻余核舟一,盖大苏泛赤壁云。--明·魏学洢《核舟记》", "example": null}, {"def": "古经传中诒、贻见互。清·郑珍说贻”字皆汉后所改。如贻饷(留赠);贻赠(馈赠,赠送)", "example": null}, {"def": "遗留", "example": null}, {"def": "贻我来牟。--《诗·周颂·思文》", "example": null}, {"def": "坐贻聋瞽。--唐·李朝威《柳毅传》", "example": null}, {"def": "又如贻累(连累);贻笑(诒笑。被人讥笑);贻谋(留下的主意);贻厥(贻留;厥其);贻燕(给后世子孙留下", "example": null}, {"def": "贻yí", "example": null}, {"def": "⒈赠给，送给～人。", "example": null}, {"def": "⒉遗留～害。～误。自～伊戚（伊是，此。戚忧愁。〈喻〉自寻烦恼）。", "example": null}]','chinese-xinhua','0'),
