('2101143296972689515','疫','1','yì','疒','9',NULL,'[{"def": "疫", "example": null}, {"def": "(形声。从疒,役省声。本义瘟役)", "example": null}, {"def": "同本义。急性传染病流行的通称", "example": null}, {"def": "疫,民皆疾也。--《说文》", "example": null}, {"def": "疫,病流行也。--《字林》", "example": null}, {"def": "氐为天根生疫。--《史记·天官书》", "example": null}, {"def": "鬻棺者欲岁之疫。--《汉书·刑法志》", "example": null}, {"def": "果实早成,民殃于疫。--《礼记·月令》", "example": null}, {"def": "又如时疫;疫死(因染患流行的传染病而死);疫旱(传染病与旱灾);疫症(疫病);疫疠(瘟疫);疫疾(疫病;疫病流行)", "example": null}, {"def": "疫鬼,古代迷信称施瘟疫的鬼", "example": null}, {"def": "疫yì指瘟疫，急性传染病的总称防～。治疗～病。", "example": null}]','chinese-xinhua','0'),
('2101143296972689516','羿','1','yì','羽','9',NULL,'[{"def": "羿", "example": null}, {"def": "鸟张翅旋风而上", "example": null}, {"def": "羿,羽之羿风。--《说文》。段玉裁注谓抟扶摇而上之状", "example": null}, {"def": "羿", "example": null}, {"def": "唐尧时的射师", "example": null}, {"def": "自开辟以来,太阳星原有十,后被羿善开弓,射落九乌坠地,止存金乌一星。--《西游记》", "example": null}, {"def": "又如羿弓(羿的弓矢所及);羿妃(指神话中羿妻嫦娥);羿毙十日(指羿射日的传说)", "example": null}, {"def": "夏时有穷氏国君", "example": null}, {"def": "羿犹不悛,将归自田,家众杀而亨之。--《左传》", "example": null}, {"def": "羿yì〈古〉人名，又称\\"后羿\\"。传说是夏朝有穷国的君主，善于射箭。", "example": null}]','chinese-xinhua','0'),
