('2101143296972689518','轶','1','yì','车','9',NULL,'[{"def": "轶", "example": null}, {"def": "(形声。从车,失声。本义超车)", "example": null}, {"def": "同本义。引申为超越", "example": null}, {"def": "轶,车相出也。--《说文》。段注车之后进突于前也。”", "example": null}, {"def": "轶云雨于太半。--班固《西都赋》", "example": null}, {"def": "轶,过也。--《广雅》", "example": null}, {"def": "轶鸡于姑苏。--《淮南子·览冥》。注自后过前曰轶。”", "example": null}, {"def": "超轶绝尘。--《庄子·徐无鬼》。成疏轶,过也。”", "example": null}, {"def": "轶五帝之遐迹兮,蹑三皇之高踪。--《汉书·扬雄传上》", "example": null}, {"def": "又如轶轨(超越);轶超;轶越(超越;超过);轶资(超越一般的资格)", "example": null}, {"def": "突击", "example": null}, {"def": "惧其侵轶我也。--《左传·隐公九年》", "example": null}, {"def": "又如轶犯(侵犯)", "example": null}, {"def": "通", "example": null}, {"def": "轶yì 1.后车超前车。引申为超越。 2.突袭，突击。 3.超绝。 4.散失。 5.通\\"逸\\"。安闲，逸乐。 6.通\\"逸\\"。奔驰;逃跑。 7.通\\"溢\\"。", "example": null}, {"def": "轶dié 1.更替;轮流。 2.见\\"轶荡\\"。", "example": null}, {"def": "轶zhé 1.车迹。", "example": null}]','chinese-xinhua','0'),
('2101143296972689519','绎','1','yì','纟','8',NULL,'[{"def": "绎", "example": null}, {"def": "(形声。从糸,瞘声。本义抽丝)", "example": null}, {"def": "同本义", "example": null}, {"def": "绎,抽丝也。--《说文》", "example": null}, {"def": "绎,理也。丝曰绎之。--《方言一》", "example": null}, {"def": "绎,抽也。--《三苍》", "example": null}, {"def": "引出头绪,寻求事理", "example": null}, {"def": "陈述", "example": null}, {"def": "庶言同则绎。--《书》。孔传众言同则陈而布之", "example": null}, {"def": "又如绎志(抒陈自己的志向;书名)", "example": null}, {"def": "陈列", "example": null}, {"def": "射之为言者绎也,或曰舍也。绎者,各绎己之志也。--《礼记》。孔颖达疏绎,陈也,言陈己之志。”", "example": null}, {"def": "继续,连续不断", "example": null}, {"def": "绎（?", "example": null}]','chinese-xinhua','0'),
('2101143296972689520','诣','1','yì','讠','8',NULL,'[{"def": "诣", "example": null}, {"def": "(形声。从言,旨声。本义前往,去到)", "example": null}, {"def": "同本义", "example": null}, {"def": "诣,候至也。--《说文》", "example": null}, {"def": "诣,进也。--《小尔雅》", "example": null}, {"def": "未得诣前。--《汉书·杨王孙传》。注至也。”", "example": null}, {"def": "诣,至也。--《苍颉篇》", "example": null}, {"def": "吏遂缚诣县。--三国魏·邯郸淳《笑林》", "example": null}, {"def": "先主遂诣亮。--《三国志·诸葛亮传》", "example": null}, {"def": "及郡下,诣太守,说如此。--晋·陶渊明《桃花源记》", "example": null}, {"def": "元济诣京师。--《资治通鉴·唐纪》", "example": null}, {"def": "与鲁肃俱诣孙权。--《资治通鉴》", "example": null}, {"def": "又如诣阙(亲自到达宫廷);诣门(上门,登门)", "example": null}, {"def": "晋谒;造访。古代到朝廷或上级、尊长处去之称", "example": null}, {"def": "及郡下,诣太守,说如此。--《桃花源", "example": null}, {"def": "诣yì", "example": null}, {"def": "⒈往，到～京。特指到尊长处专～请教。", "example": null}, {"def": "⒉［造诣］学问、技术等所达到的境地她对生物学造～很深。", "example": null}]','chinese-xinhua','0'),
('2101143296972689521','驿','1','yì','马','8',NULL,'[{"def": "驿", "example": null}, {"def": "(形声。从马,瞘声。本义古代供传递公文或传送消息用的马)", "example": null}, {"def": "同本义", "example": null}, {"def": "驿,置骑也。--《说文》", "example": null}, {"def": "即孟子置郵,所谓遽也。", "example": null}, {"def": "馹为传车,驿为马骑。", "example": null}, {"def": "楚子乘驿。--《左传·文公十六年》", "example": null}, {"def": "使驿谒诸王。--《左传·襄公二十七年》", "example": null}, {"def": "后数日驿至。--《后汉书·张衡传》", "example": null}, {"def": "驿站", "example": null}, {"def": "驿外断桥边,寂寞开无主。--陆游《卜算子·咏梅》", "example": null}, {"def": "又如驿递夫马(驿马);驿马星(星相家的迷信说法,若占卜得驿马星,表示将远行、赴任、移居);驿吏(管理驿站的官吏);驿亭(古代作为行旅中途休息住宿的处所);驿书(以驿马", "example": null}, {"def": "传送的文书);驿馆(旅馆,驿", "example": null}, {"def": "驿（骯）yì〈古〉供传递公文或传送消息用的马走～。〈引〉驿站（供驿马与传递人中途休息的地方）。", "example": null}]','chinese-xinhua','0'),
('2101143296972689522','奕','1','yì','大','9',NULL,'[{"def": "奕", "example": null}, {"def": "(形声。从大,亦声。本义大)", "example": null}, {"def": "同本义", "example": null}, {"def": "奕,大也。--《说文》", "example": null}, {"def": "往小来奕。--《太玄·格》", "example": null}, {"def": "四壮奕奕。--《诗·小雅·车攻》", "example": null}, {"def": "奕奕梁山。--《诗·大雅·韩奕》", "example": null}, {"def": "伯夷相唐,尚父宾周。受氏胙国,重光奕休。--宋·王安石《祭吕侍读文》", "example": null}, {"def": "美的", "example": null}, {"def": "自关而西,凡美容谓之奕。--《方言》", "example": null}, {"def": "万舞有奕。--《诗·商颂·那》", "example": null}, {"def": "累,重", "example": null}, {"def": "是仆与君奕世为通好也。--《世说新语·言语》", "example": null}, {"def": "又如奕世簪缨(子孙世代都为显宦贵族);奕世(累世,代代);奕代(奕世,累世);奕叶(累世,代代)", "example": null}, {"def": "光明", "example": null}, {"def": "故其华表则镐", "example": null}, {"def": "奕yì", "example": null}, {"def": "⒈累，重迭～世。～代。～叶。", "example": null}, {"def": "⒉高大，美丽。", "example": null}, {"def": "⒊", "example": null}, {"def": "①高大～ ～梁山。", "example": null}, {"def": "②精神焕发神采～ ～。", "example": null}, {"def": "③光明，明亮眼光～ ～。", "example": null}, {"def": "④心神不定忧心～ ～。", "example": null}]','chinese-xinhua','0'),
