('2101143296976883761','翳','1','yì','羽','17',NULL,'[{"def": "翳", "example": null}, {"def": "(形声。从羽,嫛声。本义用羽毛做的华盖,舞具)", "example": null}, {"def": "同本义", "example": null}, {"def": "翳,华盖也。--《说文》。朱骏声通训定声以羽覆车盖,所谓羽葆幢也。”", "example": null}, {"def": "病证名", "example": null}, {"def": "指引起黑睛(角膜)混浊或溃陷的外障眼病以及病变愈后遗留于黑睛的疤痕", "example": null}, {"def": "凡眼内、外障眼病所生遮蔽视线影响视力的症状皆可称翳", "example": null}, {"def": "起障蔽作用的东西", "example": null}, {"def": "鸟名", "example": null}, {"def": "翳", "example": null}, {"def": "遮蔽,掩盖", "example": null}, {"def": "翳,障也。--《广雅》", "example": null}, {"def": "百神翳其备降兮。--《楚辞·离骚》。注翳,蔽也。”", "example": null}, {"def": "石嵯以", "example": null}, {"def": "翳yì", "example": null}, {"def": "⒈遮蔽树大～日。", "example": null}, {"def": "⒉眼角膜所生的膜状物，能遮蔽视线白～（俗称翳子）。", "example": null}, {"def": "⒊〈古〉用羽毛做的舞具左手操～。", "example": null}]','chinese-xinhua','0'),
('2101143296976883762','翼','1','yì','羽','17',NULL,'[{"def": "翼", "example": null}, {"def": "(形声。从羽,異声。《说文》小篆从飞,異声。本义翅膀)", "example": null}, {"def": "同本义", "example": null}, {"def": "翼,翅也。--《说文》", "example": null}, {"def": "六足四翼。--《战国策·楚策》", "example": null}, {"def": "三年不翅,将以长羽翼。--《韩非子·喻老》", "example": null}, {"def": "南方有比翼鸟焉。--《尔雅》", "example": null}, {"def": "振鳞奋翼。--宋玉《高唐赋》", "example": null}, {"def": "又如翼虎(添上翅膀的老虎);翼张(如鸟展翅。形容分布的样子);翼膀(翅膀);翼翮(翅膀)", "example": null}, {"def": "鸟的翅膀", "example": null}, {"def": "明夷于飞,垂其翼。--《易·明夷》", "example": null}, {"def": "飞机的两翼。如翼型", "example": null}, {"def": "昆虫的翅膀", "example": null}, {"def": "以翼鸣者。--《周礼》", "example": null}, {"def": "一个队形(如战线、散兵线、行进纵队)左侧或右侧", "example": null}, {"def": "韩、魏翼而击之。--《韩非子·十过", "example": null}, {"def": "翼yì", "example": null}, {"def": "⒈翅膀举首奋～。双～飞机。", "example": null}, {"def": "⒉用翼遮盖，保护鸟覆～之（覆遮盖）。", "example": null}, {"def": "⒊两侧中之一侧～。张左右～击之。", "example": null}, {"def": "⒋辅佐，扶助辅～。", "example": null}, {"def": "⒌星宿名，二十八宿之一。", "example": null}, {"def": "⒍", "example": null}, {"def": "①严肃谨慎小心～ ～。", "example": null}, {"def": "②壮盛纷纷～ ～。", "example": null}, {"def": "③整齐都城～ ～。", "example": null}, {"def": "④轻松，悠闲高翱翔之～ ～。 刈yì", "example": null}, {"def": "⒈割～草。～麦。", "example": null}, {"def": "⒉镰刀一类的农具。", "example": null}]','chinese-xinhua','0'),
('2101143296976883763','臆','1','yì','月','17',NULL,'[{"def": "臆", "example": null}, {"def": "(形声。从肉,意声。又作胑”。本义胸骨)", "example": null}, {"def": "同本义", "example": null}, {"def": "臆,胸骨也。--《说文》", "example": null}, {"def": "胸部", "example": null}, {"def": "气交愤于胸臆。--王粲《登楼赋》", "example": null}, {"def": "臆,匈也。--《广雅》", "example": null}, {"def": "仪遗忏以臆对。--《汉书·序传上》", "example": null}, {"def": "丹臆兰臆。--潘岳《射雉赋》", "example": null}, {"def": "夜寒衣湿披短蓑,臆穿足裂忍痛何?--唐·王建《水夫谣》", "example": null}, {"def": "又如抚臆论心", "example": null}, {"def": "臆", "example": null}, {"def": "通意”。意料;推测", "example": null}, {"def": "乃知天下之事,不可尽知,而以臆断之,不可任也。--《抱朴子》", "example": null}, {"def": "请对以臆。--《史记·贾谊传》", "example": null}, {"def": "然而子长少臆中之说。--《论衡·案书》", "example": null}, {"def": "又如臆辨(只凭推测来辨别)", "example": null}, {"def": "臆 <", "example": null}, {"def": "臆（胑）yì", "example": null}, {"def": "⒈胸抚～扪心。", "example": null}, {"def": "⒉主观想象和揣测～说。～测。～造。～断。", "example": null}, {"def": "臆yǐ 1.梅浆。", "example": null}]','chinese-xinhua','0'),
