('2101143296976883821','屹','1','yì','山','6',NULL,'[{"def": "屹", "example": null}, {"def": "(形声。从山,乞声。本义山势直立高耸的样子)", "example": null}, {"def": "同本义◇泛指耸立的", "example": null}, {"def": "屹山峙以迂郁。(迂郁盘曲的样子。)--王延寿《鲁灵光殿赋》", "example": null}, {"def": "又如屹仡(挺拔雄劲的样子);屹峙(耸立)", "example": null}, {"def": "坚定不移的", "example": null}, {"def": "屹yì山峰高耸。〈喻〉稳固，坚定，不可动摇～立。～然。", "example": null}, {"def": "屹gē 1.见\\"屹?\\" 2.见\\"屹搭搭\\"。 3.见\\"屹剌剌\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296976883822','异','1','yì','廾','6',NULL,'[{"def": "异", "example": null}, {"def": "(会意。異”,甲骨文字形,象个有手、脚、头的人形。从廾从畀。畀,予也。本义奇特;奇异;奇怪)", "example": null}, {"def": "同本义", "example": null}, {"def": "异,怪也。--《玉篇》", "example": null}, {"def": "异,奇也。--《广韵》", "example": null}, {"def": "何以异哉。--《列子·杨朱》", "example": null}, {"def": "异乎交益之士。--左思《魏都赋》", "example": null}, {"def": "妇人异甚。--《战国策·赵策》", "example": null}, {"def": "产异蛇。--唐·柳宗元《捕蛇者说》", "example": null}, {"def": "觉无异能。--唐·柳宗元《三戒》", "example": null}, {"def": "父异焉。--宋·王安石《伤仲永》", "example": null}, {"def": "又如异疾(奇怪的病症);异形(怪异或奇特的形状)", "example": null}, {"def": "不同", "example": null}, {"def": "礼者为异。--《礼记·乐记》。注谓别贵贱也。”", "example": null}, {"def": "事为异别。--《礼", "example": null}, {"def": "异（異）yì", "example": null}, {"def": "⒈不同，不同的～乎寻常。同工～曲。", "example": null}, {"def": "⒉别的，另外的～地。～军突起。", "example": null}, {"def": "⒊分开～居。离～。", "example": null}, {"def": "⒋特殊的～味。优～。", "example": null}, {"def": "⒌惊奇，奇怪惊～。诧～。～想天开。", "example": null}, {"def": "⒍", "example": null}]','chinese-xinhua','0'),
