('2101143296993661006','楹','1','yínɡ','木','13',NULL,'[{"def": "楹", "example": null}, {"def": "(形声。从木,盈声。本义厅堂前部的柱子)", "example": null}, {"def": "同本义", "example": null}, {"def": "楹,柱也。--《说文》", "example": null}, {"def": "旅楹有闲。--《诗·商颂·殷武》", "example": null}, {"def": "刮楹达乡。--《礼记·明堂位》", "example": null}, {"def": "丹桓宫楹。--《春秋·庄公二十三年》", "example": null}, {"def": "又如楹柱(厅堂前部的柱子)", "example": null}, {"def": "量词。计算房屋多少的单位,一列为一楹", "example": null}, {"def": "楹yíng", "example": null}, {"def": "⒈厅堂前部的柱子～联（柱子上的对联）。", "example": null}, {"def": "⒉量词。旧时把一间房屋叫一楹有屋四～。", "example": null}]','chinese-xinhua','0'),
('2101143296993661007','滢','1','yínɡ','氵','13',NULL,'[{"def": "滢", "example": null}, {"def": "清澈的样子", "example": null}, {"def": "滢濙", "example": null}, {"def": "洪河左滢瀕。--杜甫《桥陵诗呈县内诸官》", "example": null}, {"def": "滢（瀅）yíng清澈。", "example": null}, {"def": "滢yìng 1.见\\"汀滢\\"。 2.见\\"汀滢\\"﹑\\"滢渟\\"﹑\\"滢滢\\"。 3.见\\"滢荧\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296993661008','蓥','1','yínɡ','艹','13',NULL,'[{"def": "蓥", "example": null}, {"def": "琢磨使发光。亦作莹”", "example": null}, {"def": "莹,磨也。--《广雅》", "example": null}, {"def": "蓥（鎣）yíng华蓥山，在四川省和重庆市交界处。", "example": null}, {"def": "蓥yīng 1.古代一种长颈瓶。短足，似眀。 2.磨拭使光亮。 3.明亮。", "example": null}]','chinese-xinhua','0'),
('2101143296993661009','潆','1','yínɡ','氵','14',NULL,'[{"def": "潆", "example": null}, {"def": "水流环绕回旋的样子", "example": null}, {"def": "潆洄澹兹土,平敞诚寡俦。--司马光《登宿州北楼诗》", "example": null}, {"def": "又如潆折(回旋曲折);潆波(回旋的水波);潆绕(水流环绕)", "example": null}, {"def": "潆", "example": null}, {"def": "水;大水", "example": null}, {"def": "潆,大水也。--《玉篇》", "example": null}, {"def": "如潆渟(水停滞不流的样子);潆潆(水波动荡的样子)", "example": null}, {"def": "潆洄", "example": null}, {"def": "石山峻立,江水潆洄。--《英烈传》", "example": null}, {"def": "潆（瀠）yíng", "example": null}]','chinese-xinhua','0'),
('2101143296993661010','蝇','1','yínɡ','虫','14',NULL,'[{"def": "蝇", "example": null}, {"def": "多指苍蝇。动物名。属昆虫类中的双翅类", "example": null}, {"def": "上无枝上蜩,下无盘中蝇。--唐·韩愈《秋怀诗》", "example": null}, {"def": "又如蝇头小楷(非常小的正楷毛笔字);蝇头细批(用小字密密批注);蝇附狗偷(比喻依附低俗下作的行径);蝇营(如蝇到处营钻。比喻赢小利而不休);蝇名蜗利(苍蝇头般的微名,", "example": null}, {"def": "蜗牛角样的小利。比喻微不足道的名利);蝇利(比喻微小的利益);蝇头小字(指极小的字);蝇声蛙噪(苍蝇、青蛙无休止地叫。比喻低劣的、无病呻呤的诗文)", "example": null}, {"def": "蝇（蠅）yíng苍蝇，昆虫。幼虫叫\\"蛆\\"，生活在粪便、垃圾等污物中。成虫全身有毛，复眼，翅一对。种类很多，有的能传播伤寒、痢疾、霍乱等病除四害（四害老鼠、苍", "example": null}, {"def": "～、蚊子、蟑螂）消灭苍～。", "example": null}]','chinese-xinhua','0'),
