('2101143296993661028','颍','1','yǐnɡ','页','12',NULL,'[{"def": "颍", "example": null}, {"def": "(形声。从水,顷声。本义水名。蛴,淮河最大的支流)", "example": null}, {"def": "同本义", "example": null}, {"def": "颍,颍水,出颍州阳城乾山东入淮。--《说文》", "example": null}, {"def": "发源于河南省登封县,至安徽流入淮河", "example": null}, {"def": "姓", "example": null}, {"def": "颍yǐng蛴，发源于河南省登封，流到安徽省正阳关入淮河。", "example": null}]','chinese-xinhua','0'),
('2101143296993661029','颖','1','yǐnɡ','页','13',NULL,'[{"def": "颖", "example": null}, {"def": "(形声。从禾,顷声。从禾与农作物有关。本义谷穗。亦称颖片”。指禾本科植物小穗基部的二枚苞片)", "example": null}, {"def": "同本义", "example": null}, {"def": "颖,禾末也。从禾,顷声。谓贯于穗及近于穗之芒秒。--《说文》", "example": null}, {"def": "禾穗谓之颖。--《小尔雅》", "example": null}, {"def": "异亩同颖。--《书·归禾序》", "example": null}, {"def": "实颖实贾。--《诗·大雅·生民》", "example": null}, {"def": "嘉禾重颖。--应贞《晋武帝华林园林》", "example": null}, {"def": "又如颖果(干果的一种,种皮和果皮合而为一,里面只有一粒种子)", "example": null}, {"def": "锥芒", "example": null}, {"def": "乃颖脱而出,非特其末见而已。--《史记·平原君虞卿列传》", "example": null}, {"def": "又如颖脱(将锥放在囊中,终将全部脱出。比喻能充分显露内在的才能);短颖羊", "example": null}, {"def": "颖yǐng", "example": null}, {"def": "⒈谷穗，禾的末端。稻、麦等禾本科植物小穗基部的苞片嘉禾重～。谷之～片。", "example": null}, {"def": "⒉东西末端的尖锐部分锥在袋中，～脱而出。", "example": null}, {"def": "⒊聪明幼便～悟。聪～过人。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
