('2101143296997855251','嘤','1','yīnɡ','口','14',NULL,'[{"def": "嘤", "example": null}, {"def": "(形声。从口,婴声。双音词嘤嘤”。本义鸟鸣声)", "example": null}, {"def": "同本义", "example": null}, {"def": "嘤,鸟鸣也。--《说文》", "example": null}, {"def": "鸟鸣嘤嘤。--《诗·小雅·伐木》", "example": null}, {"def": "山鹊兮嘤嘤。--《楚辞·悼乱》", "example": null}, {"def": "好鸟相鸣,嘤嘤成韵。--《艺文类聚·吴均·与朱元思书》", "example": null}, {"def": "又如嘤呦(鸟鸣);嘤鸟(鸣声相和之鸟);嘤声(鸟和鸣声)", "example": null}, {"def": "哽塞;哽咽。多含有抽泣、哭鼻子之意", "example": null}, {"def": "贪水者,脉必厥,其声嘤,咽喉塞。--汉·张仲景《伤寒论》", "example": null}, {"def": "又如嘤噯(啼泣);嘤唔(细弱哀怨之声)", "example": null}, {"def": "嘤鸣", "example": null}, {"def": "嘤鸣相召", "example": null}, {"def": "嘤yīng鸟叫声鸟鸣～ ～。", "example": null}]','chinese-xinhua','0'),
('2101143296997855252','撄','1','yīnɡ','扌','14',NULL,'[{"def": "撄", "example": null}, {"def": "(形声。从手,婴声。本义扰乱,干扰)", "example": null}, {"def": "同本义", "example": null}, {"def": "不以人物利害相撄。--《庄子·庚桑楚》", "example": null}, {"def": "又如撄宁(外物的扰乱);撄心(扰乱心神)", "example": null}, {"def": "缠绕", "example": null}, {"def": "勿挠勿撄,万物将自称。--《淮南子》。高诱注撄,缨也。”", "example": null}, {"def": "又如撄城(环城);撄挽(纠缠)", "example": null}, {"def": "触犯", "example": null}, {"def": "杀害既多,必撄鬼神之怒。--《绿野仙踪》", "example": null}, {"def": "又如撄怒(触怒);撄拂(触犯,拂逆);撄鳞(喻触怒帝王)", "example": null}, {"def": "触", "example": null}, {"def": "事势至此,陛下且忍之,不可撄其锋也。--《三国演义》", "example": null}, {"def": "又如撄宁(接触外物而不为所动,保持心神宁静);撄锋(触碰锋镝)", "example": null}, {"def": "向…挑战或撩斗", "example": null}, {"def": "虎负嵎,", "example": null}, {"def": "撄yīng", "example": null}, {"def": "⒈碰，触犯～其锋芒。无人敢～。", "example": null}, {"def": "⒉扰乱，干扰～人之心。", "example": null}]','chinese-xinhua','0'),
('2101143296997855253','缨','1','yīnɡ','纟','14',NULL,'[{"def": "缨", "example": null}, {"def": "(形声。从糸,婴声。本义系在脖子上的帽带)", "example": null}, {"def": "同本义", "example": null}, {"def": "缨,冠系也。--《说文》", "example": null}, {"def": "鲜冠组缨,绛衣博袍。--《墨子·公孟》", "example": null}, {"def": "正冠而缨绝。--《庄子·让王》", "example": null}, {"def": "沧浪之水清兮,可以濯吾缨。--《楚辞·渔父》", "example": null}, {"def": "戴朱缨宝饰之帽。--明·宋濂《送东阳马生序》", "example": null}, {"def": "又如缨冠(把帽带连同帽子一齐加于头上。形容极为急迫,来不及整束)", "example": null}, {"def": "彩带,古代女子许嫁时所佩", "example": null}, {"def": "套马的革带,驾车用。引申指绳索", "example": null}, {"def": "咸龙旂而繁缨。--张衡《东京赋》。薛注缨,马", "example": null}, {"def": "缨yīng", "example": null}, {"def": "⒈线、绳、彩带等做的装饰品彩灯～子§～枪。慷慨泪沾～。", "example": null}, {"def": "⒉像缨的东西萝卜～儿。蒜苗～子。", "example": null}, {"def": "⒊长带，拘捆人的绳子长～在手。", "example": null}]','chinese-xinhua','0'),
('2101143296997855254','罂','1','yīnɡ','缶','14',NULL,'[{"def": "罂", "example": null}, {"def": "大腹小口的瓦器。或作畂”", "example": null}, {"def": "罂,缶也。--《说文》", "example": null}, {"def": "自关而西,晋之旧都,河汾之间,其大者谓之,其中者谓之;自关而东,赵魏之郊,谓之瓮,或谓之罂。--《方言五》", "example": null}, {"def": "用瓦木罂,容十升以上者,五十步而十,盛水且用之。--《墨子》", "example": null}, {"def": "又如罂盎(泛指盛酒器);罂瓶(泛指盛酒器)", "example": null}, {"def": "泛指小口大腹的瓶", "example": null}, {"def": "火药三百罂。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "又如罂缶(大腹小口的瓶)", "example": null}, {"def": "植物名", "example": null}, {"def": "罂粟", "example": null}, {"def": "罂（畓）yīng", "example": null}, {"def": "⒈小口大腹的瓶子。", "example": null}, {"def": "⒉", "example": null}, {"def": "，需经高级医师处方，慎重使用。果壳叫\\"罂粟壳\\"，也可供药用。私种罂粟，吸食鸦片类毒品以及制毒、贩毒等，均违法，要受到严惩。", "example": null}]','chinese-xinhua','0'),
('2101143296997855255','譯','1','yīnɡ','','11',NULL,'[{"def": "譯yìng 1.应，答话。", "example": null}]','chinese-xinhua','0'),
('2101143296997855256','哟','1','yō','口','9',NULL,'[{"def": "哟", "example": null}, {"def": "表示轻微的惊异(有时带玩笑的语气)", "example": null}, {"def": "哟", "example": null}, {"def": "用在句尾表示祈使语气。如用力拉哟!", "example": null}, {"def": "用在歌词中做衬字。如呼儿海哟!", "example": null}, {"def": "哟yo助词。", "example": null}, {"def": "①用于句末或句中停顿处加把劲～。鲜菜～，鲜肉～，他都爱吃。", "example": null}, {"def": "②歌词中做衬字呼儿嗨～，他是人民大救星。", "example": null}, {"def": "哟yó 1.叹词。表示轻微的惊异。", "example": null}]','chinese-xinhua','0'),
('2101143296997855257','唷','1','yō','口','11',NULL,'[{"def": "见哼唷”、喔唷”", "example": null}, {"def": "唷yō", "example": null}, {"def": "⒈叹词。〈表〉惊讶或疑问～，一条大鱼！～，怎么办？", "example": null}, {"def": "⒉呼喊声哎～！", "example": null}, {"def": "唷yó 1.表示赞叹或惊讶。 2.见\\"哼唷\\"。", "example": null}]','chinese-xinhua','0'),
('2101143296997855258','喁','1','yónɡ','口','12',NULL,'[{"def": "喁", "example": null}, {"def": "(形声。从口,禺声。本义鱼口向 上露出水面)", "example": null}, {"def": "同本义", "example": null}, {"def": "喁,鱼口上见。--《说文》", "example": null}, {"def": "水浊则鱼喁,令苛则民乱。--《韩诗外传》", "example": null}, {"def": "仰望期待的样子", "example": null}, {"def": "喁喁", "example": null}, {"def": "同喁”", "example": null}, {"def": "天下英雄,喁喁冀有所望", "example": null}, {"def": "喁yóng", "example": null}, {"def": "⒈鱼嘴朝上，露出水面。", "example": null}, {"def": "⒉", "example": null}, {"def": "①众人景仰归向的样子～ ～向慕。", "example": null}, {"def": "②小声细语～ ～（yúyú）私语。", "example": null}]','chinese-xinhua','0'),
('2101143296997855259','鰫','1','yónɡ','','7',NULL,'[{"def": "鰫yōng 1.花鲢。 2.海鳙。", "example": null}]','chinese-xinhua','0'),
('2101143296997855260','用','1','yònɡ','用','5',NULL,'[{"def": "用", "example": null}, {"def": "(象形。甲骨文字形,象桶形。桶可用,故引申为用。本义使用,采用)", "example": null}, {"def": "同本义", "example": null}, {"def": "用,可施行也。--《说文》", "example": null}, {"def": "用,以也。--《苍颉篇》", "example": null}, {"def": "利用为大作。--《易·益》", "example": null}, {"def": "五行五用哉。--《虞书》", "example": null}, {"def": "乃攘窃神胝之牺牷牺用。--《书·微子》", "example": null}, {"def": "乘其财用出入。--《周礼·宰夫》", "example": null}, {"def": "乃会万民之卒伍而用之。--《周礼·小司徒》", "example": null}, {"def": "保甲之法,起于三代丘甲。管仲用之齐,子产用之郑,商君用之秦,仲长统言之汉,而非今日之立异也。--宋·王安石《上五事札子》", "example": null}, {"def": "皆不足用。--明·魏禧《大铁椎传》", "example": null}, {"def": "用水彩。--蔡元培《图画》", "example": null}, {"def": "兼用激刺", "example": null}, {"def": "用yòng", "example": null}, {"def": "⒈使人、物等发挥其功能使～。采～。应～。～心。～水。～机器人做工。", "example": null}, {"def": "⒉功能，效果～途。功～。效～。有～。", "example": null}, {"def": "⒊需要不～担心。你不做，还～你干啥。", "example": null}, {"def": "⒋化费～钱。费～。零～。", "example": null}, {"def": "⒌吃、喝的婉词～餐。请～茶。", "example": null}, {"def": "⒍因，因此～此。～特函达。", "example": null}, {"def": "⒎以儒者～文乱法。", "example": null}, {"def": "⒏", "example": null}, {"def": "①当权。", "example": null}, {"def": "②行事。", "example": null}, {"def": "⒐", "example": null}, {"def": "①居心。", "example": null}, {"def": "②企图。", "example": null}, {"def": "⒑", "example": null}, {"def": "①打仗。", "example": null}, {"def": "②指挥作战。", "example": null}, {"def": "③善于使用军队作战～兵如神。", "example": null}, {"def": "⒒", "example": null}]','chinese-xinhua','0'),
('2101143296997855261','砽','1','yònɡ','','10',NULL,'[{"def": "砽yong", "example": null}, {"def": "⒈义未详。", "example": null}]','chinese-xinhua','0'),
('2101143296997855262','佣','1','yònɡ','亻','7',NULL,'[{"def": "佣", "example": null}, {"def": "(形声。从人,庸声。本义受雇佣,出卖劳动力) 同本义", "example": null}, {"def": "佣,均直也。卖力受直曰佣。隋其力均其直也。--《说文》", "example": null}, {"def": "教民相与佣輓犁。--《汉书·食货志》", "example": null}, {"def": "尝与人佣耕。--《史记·陈涉世家》", "example": null}, {"def": "佣者笑而应。", "example": null}, {"def": "若为佣耕。", "example": null}, {"def": "子佣出。--清·周容《芋老人传》", "example": null}, {"def": "子不佣矣。", "example": null}, {"def": "又如 (1)∶雇佣。如佣伍(雇佣的军队);佣钱(雇佣的酬金、工钱) (2)∶受雇佣。如佣作(受雇于人,为人工作);佣债(受雇于人,从事劳役以取酬劳);佣耕(受雇于人,为人耕", "example": null}, {"def": "种);佣书(受雇于人,为人书写文字);佣客(受雇用的人);佣力(受雇出卖劳力)", "example": null}, {"def": "佣", "example": null}, {"def": "佣yòng", "example": null}, {"def": "佣（傭）yōng受雇佣，出卖劳动力的人～工。", "example": null}, {"def": "佣chōng 1.均;公平。", "example": null}]','chinese-xinhua','0'),
('2101143296997855263','永','1','yǒnɡ','水','5',NULL,'[{"def": "永", "example": null}, {"def": "(象形。小篆字形,象水流曲曲折折的样子。本义水流长)", "example": null}, {"def": "同本义", "example": null}, {"def": "永,水长也。象水巠理之长。--《说文》", "example": null}, {"def": "江之永矣,不可方思。--《诗·周南·汉广》。毛传永,长。”", "example": null}, {"def": "泛指长。兼指时间和空间", "example": null}, {"def": "施于众长谓之永。--《方言一》", "example": null}, {"def": "不永所事。--《易·讼》", "example": null}, {"def": "日永星火。--《书·尧典》", "example": null}, {"def": "维以不永怀。--《诗·周南·卷耳》", "example": null}, {"def": "永矢弗谖。--《诗·卫风·考槃》", "example": null}, {"def": "且以永日。--《诗·唐风·山有枢》", "example": null}, {"def": "求永贞。--《周礼·大祝》", "example": null}, {"def": "永乃保之。--《仪礼·士冠礼》", "example": null}, {"def": "以永终誉。--《礼记·中庸", "example": null}, {"def": "永yǒng", "example": null}, {"def": "⒈长，水流长～昼。江之～矣。", "example": null}, {"def": "⒉长久，久远～久。～远。～恒。～不生锈。～志不忘。～垂不朽。", "example": null}]','chinese-xinhua','0'),
('2101143296997855264','甬','1','yǒnɡ','用','7',NULL,'[{"def": "甬", "example": null}, {"def": "(形声。从兯,用声。小篆字形。兯,象花蓓蕾之形。①本义草木花结蓓蕾的样子。②钟柄)", "example": null}, {"def": "古代钟柄名", "example": null}, {"def": "甬本是钟,乃后人用字变迁,缩小其义为钟柄。--杨树达《积微居小学述林》", "example": null}, {"def": "古代两旁有墙垣遮蔽的通道", "example": null}, {"def": "仆役;佣工", "example": null}, {"def": "甬江", "example": null}, {"def": "宁波市的别称", "example": null}, {"def": "通桶”古斗斛一类量器", "example": null}, {"def": "谷口铜甬,容十斗,重四十斤。--《集", "example": null}, {"def": "甬yǒng", "example": null}, {"def": "⒈浙江省宁波市的简称。", "example": null}, {"def": "⒉", "example": null}, {"def": "①两边有墙的通道。", "example": null}, {"def": "②有棚顶的走廊、过道～ ～相连。", "example": null}]','chinese-xinhua','0'),
('2101143296997855265','咏','1','yǒnɡ','口','8',NULL,'[{"def": "咏", "example": null}, {"def": "(形声。从口,永声。又作詠”。本义曼声长吟;歌唱)", "example": null}, {"def": "同本义", "example": null}, {"def": "詠,歌也。或从口。--《说文》。段注尧典曰‘歌永言。’乐记曰‘歌为之言也,长言之也。说之,故言之;言之不足,故长言之。’”", "example": null}, {"def": "搏拊琴瑟以咏。--《虞书》。郑注谓歌诗也。”", "example": null}, {"def": "五曰夷则,所咏歌九则,平民无二也。--《国语·周语下》", "example": null}, {"def": "人喜则斯陶,陶斯咏。--《礼记·檀弓》", "example": null}, {"def": "咏而归。--《论语·先进》", "example": null}, {"def": "咏殷周之《诗》。--班固《东都赋》", "example": null}, {"def": "又如咏士(诗人);咏雪(咏絮。泛指有诗才的女子);咏哦(歌咏吟哦);咏吟(曼声诵读);咏言(吟诗)", "example": null}, {"def": "咏(詠）yǒng", "example": null}, {"def": "⒈声调抑扬地念诵或歌唱吟～。歌～。", "example": null}, {"def": "⒉用诗词等来赞颂或叙述～志。～梅。～雪。", "example": null}]','chinese-xinhua','0'),
('2101143296997855266','泳','1','yǒnɡ','氵','8',NULL,'[{"def": "泳", "example": null}, {"def": "(形声。从水,永声。本义潜行水中;游泳) 同本义", "example": null}, {"def": "泳,潜行水中也。--《说文》", "example": null}, {"def": "泳,游也。--《尔雅·释言》", "example": null}, {"def": "潜行为泳。--《尔雅·释水》", "example": null}, {"def": "泳之游之。--《诗·邶风·谷风》", "example": null}, {"def": "复从而泳之。--《列子·黄帝》", "example": null}, {"def": "汉之广矣,不可泳思。--《诗·周南·汉广》", "example": null}, {"def": "又如泳涵(涵泳,沉浸);游泳(人或动物在水里游动);仰泳;蛙泳", "example": null}, {"def": "泳yǒng游水游～。仰～。蛙～。自由～。", "example": null}]','chinese-xinhua','0'),
('2101143296997855267','俑','1','yǒnɡ','亻','9',NULL,'[{"def": "俑", "example": null}, {"def": "(形声。从人,甬声。本义古代陪葬用的偶人,一般为木制或陶制。因象人。故从人) 同本义", "example": null}, {"def": "俑,木人。送葬设关,而能跳踊,故名之。--《埤苍》", "example": null}, {"def": "俑有面目机发,似于生人。--《通典》引《礼记》", "example": null}, {"def": "孔子谓为刍灵者善,谓为俑者不仁,殆于用人乎哉。--《礼记·檀弓》", "example": null}, {"def": "又如陶俑;武士俑", "example": null}, {"def": "俑yǒng〈古〉陪葬用的偶像，一般是木制或陶制木～。陶～。兵马～。", "example": null}]','chinese-xinhua','0'),
('2101143296997855268','勇','1','yǒnɡ','力','9',NULL,'[{"def": "勇", "example": null}, {"def": "(本作勈,或作恿。形声。从力,甬声。从力,与力气有关。本义果敢,胆大)", "example": null}, {"def": "同本义", "example": null}, {"def": "勇,气也。--《说文》", "example": null}, {"def": "无拳无勇。--《诗·小雅·巧言》", "example": null}, {"def": "尔勇伊何。", "example": null}, {"def": "勇志之所以敢也。--《墨子经上》", "example": null}, {"def": "勇,文之帅也。--《国语·周语》", "example": null}, {"def": "知死不辟,勇也。--《左传·昭公二十年》", "example": null}, {"def": "勇于就死。--清·林觉民《与妻书》", "example": null}, {"def": "若素名勇。--明·高启《书博鸡者事》", "example": null}, {"def": "兴甚勇。--《徐霞客游记·游黄山记》", "example": null}, {"def": "勇而多艺。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如忠勇(忠诚而勇敢);英勇(勇敢出众);勇悍(勇敢强悍);勇烈(勇敢猛烈);勇夫(勇敢的人)", "example": null}, {"def": "勇yǒng", "example": null}, {"def": "⒈敢干，有胆量～敢。～猛。～士。～往直前。～冠三军。", "example": null}, {"def": "⒉不畏惧，不推诿～于献身。～于认错。～挑重担。", "example": null}, {"def": "⒊清代地方上临时招募的兵卒。", "example": null}, {"def": "⒋泛指兵卒散兵游～。", "example": null}]','chinese-xinhua','0'),
