('2101143296997855274','涌','1','yǒnɡ','氵','10',NULL,'[{"def": "涌", "example": null}, {"def": "(形声。从水,甬声。本义水向上冒)", "example": null}, {"def": "同本义", "example": null}, {"def": "涌,滕也。--《说文》", "example": null}, {"def": "涌,出也。--《广雅》", "example": null}, {"def": "滥泉正出。正出,涌出也。--《尔雅·释水》", "example": null}, {"def": "泉暴出者曰涌。--《论衡·状留》", "example": null}, {"def": "醴泉涌于清室,通川过于中庭。--汉·司马相如《上林赋》", "example": null}, {"def": "泉暴出者曰涌。--汉·王充《论衡》", "example": null}, {"def": "又如涌沸(喷涌出沸腾的水);涌泉(水向上喷出的泉)", "example": null}, {"def": "引申指云、雾、烟、气等上腾冒出", "example": null}, {"def": "洪波涌起。--《乐府诗集·曹操·步出夏门行》", "example": null}, {"def": "云烟沸涌。--唐·李朝威《柳毅传》", "example": null}, {"def": "亦浪涌。--宋·陆游《过小孤山大孤山》", "example": null}, {"def": "风云腾涌。", "example": null}, {"def": "涌（湧）yǒng", "example": null}, {"def": "⒈水从下向上冒出～泉。", "example": null}, {"def": "⒉像水那样向上涌或涌出风起云～。", "example": null}, {"def": "涌chōng 1.河汊。多用于地名。", "example": null}]','chinese-xinhua','0'),
('2101143296997855275','恿','1','yǒnɡ','心','11',NULL,'[{"def": "同勇”", "example": null}, {"def": "恿,古文勇从心。--《说文》", "example": null}, {"def": "恿", "example": null}, {"def": "见怂恿”", "example": null}, {"def": "恿（慂）yǒng", "example": null}]','chinese-xinhua','0'),
('2101143296997855276','愑','1','yǒnɡ','','10',NULL,'[{"def": "愑yǒng", "example": null}, {"def": "⒈满溢，涌出。", "example": null}, {"def": "⒉愤怒。", "example": null}, {"def": "⒊欢喜。", "example": null}]','chinese-xinhua','0'),
