('2101143296997855282','踊','1','yǒnɡ','足','14',NULL,'[{"def": "踊", "example": null}, {"def": "(形声。从足,勇声。从足,表示脚的动作行为。本义往上跳)", "example": null}, {"def": "同本义", "example": null}, {"def": "踊,跳也。--《说文》", "example": null}, {"def": "踊,上也。--《广雅》", "example": null}, {"def": "曲踊三百。--《左传·僖公二十八年》", "example": null}, {"def": "三踊于幕庭。--《左传·哀公八年》", "example": null}, {"def": "踊于柸而窥客。--《公羊传·成公二年》", "example": null}, {"def": "跛者不踊。--《礼记·丧服四制》", "example": null}, {"def": "又如踊骇(惊扰跳跃);踊跳(跳跃);踊身(纵身)", "example": null}, {"def": "登,登上", "example": null}, {"def": "景公为路寝之台,成,而不踊焉。--《晏子春秋》", "example": null}, {"def": "引申为高出,超过。如踊塔(多宝塔的涌现)", "example": null}, {"def": "物踊腾粜。--《史记·平准书》", "example": null}, {"def": "百姓疲于土木之功,金", "example": null}, {"def": "踊（踴）yǒng", "example": null}, {"def": "⒈跳跃。", "example": null}, {"def": "⒉登上，上涨腾～。", "example": null}]','chinese-xinhua','0'),
('2101143296997855283','鲬','1','yǒnɡ','','10',NULL,'[{"def": "鲬yǒng 1.鱼名。鲬科鱼类的总称。体长，平扁，黄褐色。一般头扁而宽，有黑褐色斑点。无鳔。生活于海洋。可供食用。", "example": null}]','chinese-xinhua','0'),
('2101143296997855284','秇','1','yǒnɡ','','10',NULL,'[{"def": "秇yǒng 1.古代禳灾之祭。为禳风雨﹑雪霜﹑水旱﹑疠疫而祭日月星辰﹑山川之神。", "example": null}]','chinese-xinhua','0'),
