('2101143296997855339','祐','1','yòu','礻','9',NULL,'[{"def": "祐〈动〉", "example": null}, {"def": "(形声。从示,右声。本义保祐,旧指天、神等的佑助)", "example": null}, {"def": "同本义", "example": null}, {"def": "自天祐之。--《易·系辞上》。传祐者助之。”释文祐,本作佑。”", "example": null}, {"def": "彼苍默祐。--《广东军务记》", "example": null}, {"def": "又如祐助(保佑);祐庇(保佑庇护)", "example": null}, {"def": "辅助;帮助", "example": null}, {"def": "管蔡为戮,周公祐王。--汉·王符《潜夫论》", "example": null}, {"def": "又如祐命(佑助授命);祐翊(护卫,辅助);祐饷(享受祭献,佑助降福)", "example": null}, {"def": "祐yòu", "example": null}]','chinese-xinhua','0'),
('2101143296997855340','诱','1','yòu','讠','9',NULL,'[{"def": "诱", "example": null}, {"def": "(形声。从言,秀声。字本作羑”,从厶,从羑。厶,同私”。羑,诱导。本义教导;引导;劝导)", "example": null}, {"def": "同本义", "example": null}, {"def": "诱,引也。--《广韵》", "example": null}, {"def": "不诱于誉,不恐于诽。--《荀子·非十二子》", "example": null}, {"def": "夫子循循然善诱人,博我以文,约我以礼,欲罢不能。--《论语·子罕》", "example": null}, {"def": "如诱动(劝诱打动);诱训(诱导教诲);诱进(诱导进取)", "example": null}, {"def": "引诱", "example": null}, {"def": "无诱于势利。--唐·韩愈《朱文公校昌黎先生集》", "example": null}, {"def": "盖以诱敌。--《聊斋志异·狼三则》", "example": null}, {"def": "又如诱兵(战争时诈败以引诱敌人中计的士兵或引诱敌兵);诱敌(诱引敌人进入埋伏的地方)", "example": null}, {"def": "向导,引", "example": null}, {"def": "诱yòu", "example": null}, {"def": "⒈引导，教导，劝导～导。循循善～。", "example": null}, {"def": "⒉使用计策或手段迷惑、招引别人引～。利～。～骗。～惑。～敌深入。", "example": null}, {"def": "⒊吸引景色～人。", "example": null}]','chinese-xinhua','0'),
('2101143296997855341','迶','1','yòu','','7',NULL,'[{"def": "迶yòu 1.行貌。 2.作人名用字。《宋史．宗室世系表二》有赵希迶。", "example": null}]','chinese-xinhua','0'),
