('2101143297002049574','优','1','yōu','亻','6',NULL,'[{"def": "优", "example": null}, {"def": "(形声。从人,尤声。本义古代表演乐舞、杂戏的艺人。宋元以后,亦泛称戏曲艺人、演员)", "example": null}, {"def": "同本义", "example": null}, {"def": "优,饶也。一曰倡也。--《说文》。按,倡者本训,饶者假借。", "example": null}, {"def": "陈氏鲍氏之圉人为优。--《左传·襄公二十八年》", "example": null}, {"def": "公之优曰施。--《国语·晋语》", "example": null}, {"def": "信谗喜优。--《国语·越语》", "example": null}, {"def": "优笑在前。--《国语·齐语》。注倡俳也。”", "example": null}, {"def": "优孟。--《史记·滑稽列传》", "example": null}, {"def": "所爱倡优巧匠之属。--《汉书·灌夫传》。注谐戏者也。”", "example": null}, {"def": "优施曰…我优也,言无邮。”--《国语》", "example": null}, {"def": "又如优人杂剧(乐舞戏曲);优孤(专演老年男子的优人", "example": null}, {"def": "优（優）yōu", "example": null}, {"def": "⒈美好。跟\\"劣\\"相对～等品。～美别致。～秀教师。～良品质。", "example": null}, {"def": "⒉旧称演戏，也指演戏的人观～（看戏）。～伶。名～。", "example": null}, {"def": "⒊", "example": null}, {"def": "①从容。", "example": null}, {"def": "②犹豫不决～柔寡断。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143297002049575','忧','1','yōu','忄','7',NULL,'[{"def": "忧", "example": null}, {"def": "(被嵋狻Ｐ闹杏辛擞浅黼必然在脸上(用页”即人头代表)反映出来◇加攵”(表示行走),形成憂”字。忧”是形声字。本义担忧;发愁)同本义", "example": null}, {"def": "忧,愁也。--《说文》", "example": null}, {"def": "忧,愁也。--《玉篇》", "example": null}, {"def": "忧悲者德之失也。--《淮南子·原道》", "example": null}, {"def": "勿忧。--《易·丰》", "example": null}, {"def": "坎为加忧。--《易·说卦》", "example": null}, {"def": "我心忧伤。--《诗·小雅·小弁》", "example": null}, {"def": "忧心忡忡。--《诗·召南·草虫》", "example": null}, {"def": "何忧令名不彰。--《世说新语·自新》", "example": null}, {"def": "心忧炭贱。--唐·白居易《卖炭翁》", "example": null}, {"def": "忧谗畏讥。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "忧其民。", "example": null}, {"def": "又如忧忿滞中(中医", "example": null}, {"def": "忧（憂）yōu", "example": null}, {"def": "⒈发愁，担心～愁。担～。～心如焚。", "example": null}, {"def": "⒉可忧愁的事～患。", "example": null}, {"def": "⒊〈古〉父或母的丧事称\\"丁忧\\"（丁遇到，遭遇）丁父～。", "example": null}]','chinese-xinhua','0'),
('2101143297002049576','攸','1','yōu','攵','7',NULL,'[{"def": "攸 〈形〉", "example": null}, {"def": "(会意。从攴,从人水省。表示人扶杖走水路。本义水流的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "攸,行水也,从攴,从人,水省。--《说文》。段玉裁注水之安行为攸。”", "example": null}, {"def": "水行攸攸也。--《六书故》引唐本说文", "example": null}, {"def": "安闲", "example": null}, {"def": "主人攸尔而笑曰。--《汉书·叙传》", "example": null}, {"def": "又如攸游(安闲从容,自得其乐的样子);攸乐(闲适安乐);攸心(心性弛放)", "example": null}, {"def": "长远", "example": null}, {"def": "令德攸兮宣重光。--汉《冀州从事张表碑》", "example": null}, {"def": "极攸远索。--《司农刘夫人碑》", "example": null}, {"def": "又如攸长(长远);攸隔(远隔);攸远(遥远,辽远)", "example": null}, {"def": "迅疾", "example": null}, {"def": "攸然而失。--《孟子·万章上》", "example": null}, {"def": "又如攸然(", "example": null}, {"def": "攸yōu", "example": null}, {"def": "⒈所责有～归。生死～关。", "example": null}, {"def": "⒉就风雨～除（除排除）。", "example": null}]','chinese-xinhua','0'),
('2101143297002049577','呦','1','yōu','口','8',NULL,'[{"def": "呦〈叹〉", "example": null}, {"def": "鹿鸣声", "example": null}, {"def": "呦呦鹿鸣,食野之苹。--《诗·小雅·鹿鸣》", "example": null}, {"def": "表示惊诧声", "example": null}, {"def": "呦呦", "example": null}, {"def": "呦呦鹿鸣", "example": null}, {"def": "呦yōu", "example": null}, {"def": "⒈叹词。〈表〉惊讶～，太危险啦！", "example": null}, {"def": "⒉", "example": null}]','chinese-xinhua','0'),
