('2101143297002049594','於','1','yú','方','8',NULL,'[{"def": "於", "example": null}, {"def": "表示感叹", "example": null}, {"def": "佥曰於!鲧哉!”--《书·尧典》", "example": null}, {"def": "於", "example": null}, {"def": "乌”的古字。乌鸦", "example": null}, {"def": "虎豹为群,於鹊与处。--《穆天子传》", "example": null}, {"def": "另见鉹??", "example": null}, {"def": "於乎,於戏", "example": null}, {"def": "於菟", "example": null}, {"def": "於wū", "example": null}, {"def": "⒈〈古〉叹词。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊见於。", "example": null}, {"def": "於yū", "example": null}, {"def": "⒈姓。", "example": null}, {"def": "⒉见於。", "example": null}, {"def": "於yú", "example": null}, {"def": "⒈介词。", "example": null}, {"def": "①引出动作的处所、时间和对象，义同\\"在\\"、\\"到\\"、\\"从\\"、\\"给\\"、\\"向\\"、\\"对\\"等生～北京。光荣归～人民。～此向前。己所不欲，勿施～人。请教～人。～民有益。～国有", "example": null}, {"def": "利。严～律己。", "example": null}, {"def": "②用在形容词后〈表〉比较，义同\\"过\\"大～。重～。高～。人浮～事。", "example": null}, {"def": "③用在动词后〈表〉被动见笑～大方。", "example": null}, {"def": "④自，由来～民间。出～自觉。", "example": null}]','chinese-xinhua','0'),
('2101143297002049595','盂','1','yú','皿','8',NULL,'[{"def": "盂〈名〉", "example": null}, {"def": "(形声。从皿,于声。皿表示器皿。本义盛饮食或其他液体的圆口器皿)", "example": null}, {"def": "同本义", "example": null}, {"def": "盂,饮器也。--《说文》", "example": null}, {"def": "置守宫盂下。--《汉书·东方朔传》", "example": null}, {"def": "操一豚蹄,酒一盂。--《史记·滑稽列传》", "example": null}, {"def": "又如盂方水方(水因器成形。喻上行下效);钵盂(古代和尚用的饭碗);痰盂(盛痰用的器皿)", "example": null}, {"def": "盛饭的器皿", "example": null}, {"def": "上尝使诸数家射覆,置守宫盂下,射之,皆不能中。--《汉书》", "example": null}, {"def": "盂yú一种敞口的盛液体的器皿痰～。钵～。", "example": null}]','chinese-xinhua','0'),
('2101143297002049596','臾','1','yú','臼','8',NULL,'[{"def": "臾", "example": null}, {"def": "(会意。《说文》从申,从乙。”不详。双音词须臾”,片刻,一会儿)捆住拖拉", "example": null}, {"def": "极天云一线异色,须臾成五彩。--清·姚鼐《登泰山记》", "example": null}, {"def": "臾", "example": null}, {"def": "善", "example": null}, {"def": "臾,善也。--《集韵》", "example": null}, {"def": "肥沃的◇作腴”", "example": null}, {"def": "郡县上臾之壤,守之若干。--《管子》", "example": null}, {"def": "臾yú", "example": null}, {"def": "臾yǔ 1.古弱弓名。", "example": null}, {"def": "臾yǒng 1.纵臾，怂恿。怂，亦作\\"纵\\"或\\"从\\";恿，亦作\\"臾\\"或\\"容\\"。", "example": null}, {"def": "臾kuì 1.草编的筐。\\"蒉\\"的古字。", "example": null}]','chinese-xinhua','0'),
('2101143297002049597','鱼','1','yú','鱼','8',NULL,'[{"def": "鱼", "example": null}, {"def": "(象形。甲骨文字形,象鱼形。本义一种水生脊椎动物)", "example": null}, {"def": "完全水生并在水中呼吸的有头冷血脊椎动物,包括圆口类、板鳃类和具有软骨或硬骨骨骼的高等有鳃水生脊椎动物", "example": null}, {"def": "鱼,水虫也。象形。鱼尾与燕尾相似。--《说文》", "example": null}, {"def": "豚鱼吉。--《易·中孚》", "example": null}, {"def": "鱼木精。--《论衡·指瑞》", "example": null}, {"def": "鱼十有五。--《仪礼·特牲礼》", "example": null}, {"def": "鱼网之设。--《诗·邶风·新台》", "example": null}, {"def": "鲜鱼曰脡祭。--《礼记·曲礼》", "example": null}, {"def": "鱼上冰,獭祭鱼。--《吕氏春秋》", "example": null}, {"def": "白鱼跃入王舟中。--《史记·周本记》", "example": null}, {"def": "又如鱼鲩冠儿(女道士戴的鱼脑骨似的尖形帽子);鱼鳞册(鱼鳞图册”的简称", "example": null}, {"def": "鱼（魚）yú脊椎动物的一类，生活在水里。通常身体侧扁，有鳞有鳍，用鳃呼吸，体温随外界温度而变化。种类很多，大多可供食用或制造鱼胶，有些种类的肝脏可制鱼肝油", "example": null}, {"def": "养～致富。", "example": null}]','chinese-xinhua','0'),
('2101143297002049598','俞','1','yú','人','9',NULL,'[{"def": "俞", "example": null}, {"def": "(会意。从亼,从舟,从刂,刂水也。”本义与造船有关,不详)古代挖空树木做船", "example": null}, {"def": "俞,空中木为舟也。--《说文》。段玉裁注空中木者,舟之始", "example": null}, {"def": "俞", "example": null}, {"def": "文言叹词。犹言然”。表示应答或肯首。是;对", "example": null}, {"def": "答应;允许", "example": null}, {"def": "俞", "example": null}, {"def": "安定", "example": null}, {"def": "愉快", "example": null}, {"def": "俞yú", "example": null}, {"def": "⒈文言叹词。〈表〉同意，许可～，愿闻！", "example": null}, {"def": "俞shù身体上的穴位～穴。胃～。肺～。", "example": null}, {"def": "俞yù 1.通\\"愈\\"。更加;越发。 2.通\\"愈\\"。病痊愈。 3.通\\"谕\\"。参见\\"俞咨\\"。 4.见\\"呴俞\\"。", "example": null}, {"def": "俞shū 1.汉侯国名。地在今山东夏津县。", "example": null}, {"def": "俞chòu 1.姓『有司徒掾俞连。见《广韵．去宥》。", "example": null}]','chinese-xinhua','0'),
