('2101143297002049619','愉','1','yú','忄','12',NULL,'[{"def": "愉〈形〉", "example": null}, {"def": "(形声。从心,俞声。本义和悦,快乐) 同本义", "example": null}, {"def": "愉,乐也。--《说文》", "example": null}, {"def": "愉,喜也;说也。--《广雅》", "example": null}, {"def": "他人是愉。--《诗·唐风·山有枢》", "example": null}, {"def": "其进之也,敬之愉。--《礼记·祭义》", "example": null}, {"def": "愉愉如也。--《论语》", "example": null}, {"def": "心愉于内。--《史记·司马相如传》", "example": null}, {"def": "桀之治天也,使天下瘁瘁焉,人苦其性,是不愉也。--《庄子》", "example": null}, {"def": "上称三皇五帝之业,以愉其意。--《吕氏春秋》", "example": null}, {"def": "又如愉怡(快乐和悦);愉心(愉悦心情);愉目(悦目);愉色(和悦的神色)", "example": null}, {"def": "愉yú喜悦，快乐～快。", "example": null}, {"def": "愉yù 1.晓谕。", "example": null}, {"def": "愉tōu 1.苟且。 2.盗取。", "example": null}]','chinese-xinhua','0'),
('2101143297002049620','揄','1','yú','扌','12',NULL,'[{"def": "揄〈动〉", "example": null}, {"def": "(形声。从手,俞声。本义引;挥动)", "example": null}, {"def": "同本义", "example": null}, {"def": "揄,引也。--《说文》", "example": null}, {"def": "神之揄临坛宇。--《汉书·郊祀志》", "example": null}, {"def": "被发揄袂。--《庄子·渔夫》", "example": null}, {"def": "御者因揄刀而劓美人。--《韩非子》", "example": null}, {"def": "孙子曰鼓而坐之,十而揄之。--《孙膑兵法》", "example": null}, {"def": "又如揄兵(引兵);揄袂(挥动衣袖)", "example": null}, {"def": "出,拿出", "example": null}, {"def": "使言之而非也,虽在卿相人君,揄策于庙堂之上,未必可用。--《淮南子·主术》", "example": null}, {"def": "逗引", "example": null}, {"def": "揄yú", "example": null}, {"def": "⒈拉，引。", "example": null}, {"def": "⒉", "example": null}, {"def": "揄yóu 1.舀取。", "example": null}, {"def": "揄shū 1.脱;抛弃。", "example": null}, {"def": "揄yáo 1.见\\"揄狄\\"﹑\\"揄绞\\"。", "example": null}]','chinese-xinhua','0'),
