('2101143297002049624','腴','1','yú','月','12',NULL,'[{"def": "腴", "example": null}, {"def": "(形声。从肉,臾声。本义腹下的肥肉)", "example": null}, {"def": "同本义", "example": null}, {"def": "腴,腹下肥也。--《说文》", "example": null}, {"def": "君子不食圂腴。--《礼记·少仪》", "example": null}, {"def": "又", "example": null}, {"def": "冬右腴。", "example": null}, {"def": "桀纣之君,垂腴尺余。--《论衡·语增》", "example": null}, {"def": "猪狗的肠子", "example": null}, {"def": "油脂", "example": null}, {"def": "稻粱之味,甘而多腴。--《论衡》", "example": null}, {"def": "腴", "example": null}, {"def": "肥胖;脂肪多;肥美", "example": null}, {"def": "食止一日,膳无鲜腴。--《南史》", "example": null}, {"def": "肥沃", "example": null}, {"def": "丰裕", "example": null}, {"def": "处腴能约。--《晋书》", "example": null}, {"def": "美好", "example": null}, {"def": "腴yú", "example": null}, {"def": "⒈腹下的肥肉垂～尺余。泛指肥胖充～。丰～。", "example": null}, {"def": "⒉肥美膏～之地。", "example": null}, {"def": "⒊丰裕处～能约（约节约）。舆yú", "example": null}, {"def": "⒈车厢。泛指车～马。又转指轿子肩～。", "example": null}, {"def": "⒉用车运载～粮。", "example": null}, {"def": "⒊众，众人的～论。～情。", "example": null}, {"def": "⒋地图，疆土～地。～图。", "example": null}]','chinese-xinhua','0'),
('2101143297002049625','逾','1','yú','辶','12',NULL,'[{"def": "逾", "example": null}, {"def": "(形声。从辵,俞声。本义越过,经过)", "example": null}, {"def": "同本义", "example": null}, {"def": "又如逾迈(走过;时光易逝);逾墙钻穴(指男女偷情;跳墙钻洞);逾墉(越过城墙);逾墙(越过矮墙);逾假不归(即假期已满而未归营);逾轨(越轨)", "example": null}, {"def": "超过;胜过", "example": null}, {"def": "无敢昏逾。--《书·顾命》", "example": null}, {"def": "日月逾迈。--《书·秦誓》", "example": null}, {"def": "物或逾秋不死,亦如人年多度百至于三百也。--汉·王充《论衡·气寿》", "example": null}, {"def": "越职逾法,以取名誉。--《汉书·宣帝纪》", "example": null}, {"def": "去逾四十里,之虚所卖之。--唐·柳宗元《童区寄传》", "example": null}, {"def": "又如逾千(超过一千);逾出(突出,超过一般);逾立(超过三十岁);逾世(超过", "example": null}, {"def": "逾（", "example": null}, {"def": "⒈踰）yú", "example": null}, {"def": "⒈越过，超过～越。～期。\\"踰\\"另见窬（踰）。", "example": null}, {"def": "⒉更，更加～甚。～远。", "example": null}, {"def": "逾tóu 1.古代的容量单位。一逾等于十六斗。 2.通\\"偷\\"。苟且。", "example": null}]','chinese-xinhua','0'),
