('2101143297006243848','喻','1','yù','口','12',NULL,'[{"def": "喻〈动〉", "example": null}, {"def": "(形声。从口,俞声。本义告知,把情况通知某人。同谕”)", "example": null}, {"def": "同本义", "example": null}, {"def": "喻,告也。--《广雅》", "example": null}, {"def": "教之以利,而喻诸德者也。--《礼记·文王世子》", "example": null}, {"def": "晓喻;开导", "example": null}, {"def": "前后告喻,曾无悛改。--《三国志》", "example": null}, {"def": "又如喻勉(开导勉励);喻教(开导教育)", "example": null}, {"def": "知晓;明白", "example": null}, {"def": "君子喻于义。--《论语·里仁》。皇疏喻,晓也。”", "example": null}, {"def": "单足以喻则单。--《荀子·正名》。注喻,晓也。”", "example": null}, {"def": "以喻客意。--《后汉书·杜笃传》", "example": null}, {"def": "征于色,发于声,而后喻。--《孟", "example": null}, {"def": "喻yù", "example": null}, {"def": "⒈比方比～。", "example": null}, {"def": "⒉知道，了解，明白已心～。不可理～。家～户晓。", "example": null}, {"def": "⒊告诉，说明，开导～意。～之以理。", "example": null}, {"def": "喻yú 1.欢愉;使愉快。", "example": null}]','chinese-xinhua','0'),
('2101143297006243849','寓','1','yù','宀','12',NULL,'[{"def": "寓", "example": null}, {"def": "(形声。从宀,禺声。宀,表示房屋。本义寄居,寄住)", "example": null}, {"def": "同本义", "example": null}, {"def": "寓,寄也。--《说文》", "example": null}, {"def": "国无寄寓。--《国琼·周语》", "example": null}, {"def": "诸侯不臣寓公。--《礼记·郊特牲》", "example": null}, {"def": "无寓人于我室。--《孟子》", "example": null}, {"def": "径造袁所寓。--唐·柳宗元《至小丘西小石潭记》", "example": null}, {"def": "寓逆旅主人。--明·宋濂《送东阳马生序》", "example": null}, {"def": "围所寓舍。--宋·文天祥《后序》", "example": null}, {"def": "同寓数十人。--清·纪昀《阅微草堂笔记》", "example": null}, {"def": "又如寄寓(寄居);寓士(寄居之人);寓泊(寄住);寓食(寄食。寄居在别人家里生活);寓客(寄居他乡的人;外来暂住的旅客)", "example": null}, {"def": "寄托", "example": null}, {"def": "寓（庽）yù", "example": null}, {"def": "⒈居住，寄居～居。～所。暂～朋友家。", "example": null}, {"def": "⒉住的地方客～。公～。", "example": null}, {"def": "⒊寄托，含蓄～言。～意。", "example": null}, {"def": "⒋寄，过～书（寄书信）。～目（过目，亲眼看）。", "example": null}]','chinese-xinhua','0'),
('2101143297006243850','庽','1','yù','','12',NULL,'[{"def": "庽yù1.同\\"寓\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297006243851','御','1','yù','彳','12',NULL,'[{"def": "御〈动〉", "example": null}, {"def": "(会意。甲骨文字形。左为行”的省写,中为绳索形,右是人”形。意为人握辔行于道中,即驾驶车马。本义驾驶车马)", "example": null}, {"def": "同本义。也作驭”", "example": null}, {"def": "御,使马也。--《说文》", "example": null}, {"def": "徒御不惊。--《诗·小雅·车攻》", "example": null}, {"def": "以御见,侍中。--《汉书·荀彘传》", "example": null}, {"def": "礼乐射御书数。--《周礼·大司徒》", "example": null}, {"def": "梁弘御戎。--《左传·僖公三十三年》", "example": null}, {"def": "夫以疲病之卒御狐疑众…甚未足畏。--《资治通鉴》", "example": null}, {"def": "又如御轮(赶车);御策(驾驭马匹的鞭子);御正(驾驶使不偏斜);御夫(驾驭车马的人)", "example": null}, {"def": "后亦泛指驾驭一切运行或飞行之物", "example": null}, {"def": "御轻舟而上溯,", "example": null}, {"def": "御yù", "example": null}, {"def": "⒈驾驭车马～车。又指驾驭车马的人～手。", "example": null}, {"def": "⒉驾驭，控制安上～下。振长策而～宇内（策鞭子。宇内天下）。", "example": null}, {"def": "⒊称与皇帝有关的～衣。～旨。～用。～河桥。", "example": null}, {"def": "⒋侍奉，敬献～于君。～欲王公。", "example": null}, {"def": "⒌抵挡，阻止～敌。抵～。～风寒。", "example": null}, {"def": "御yà 1.迎接。 2.向;面向。 3.逢迎;迎合。", "example": null}]','chinese-xinhua','0'),
