('2101143297006243857','裕','1','yù','衤','12',NULL,'[{"def": "裕", "example": null}, {"def": "(形声,从衣,谷声。衣物丰饶。本义富饶。财物多。也指使富饶)", "example": null}, {"def": "同本义", "example": null}, {"def": "裕,衣物饶也。--《说文》", "example": null}, {"def": "有孚裕无咎。--《易·晋》", "example": null}, {"def": "天地裕于万物。--《法言·孝至》", "example": null}, {"def": "包众容物谓之裕。--《贾子道术》", "example": null}, {"def": "裕其众庶。--《国语·吴语》", "example": null}, {"def": "此今兄弟,绰绰有裕。--《诗·小雅·角弓》", "example": null}, {"def": "又如泽光前(造阁辈,光耀祖先);裕民(使民众富裕);裕饶(富饶);裕民足国(裕国足民。使人民富裕,国家丰足)", "example": null}, {"def": "宽裕", "example": null}, {"def": "布施优裕也。--《国语·周语》", "example": null}, {"def": "又如裕利(大利,暴利);裕裕(宽余自如的样子);裕宽(松弛。不紧张);裕如(自如", "example": null}, {"def": "裕yù", "example": null}, {"def": "⒈丰富，宽绰富～。宽～。充～。应付～如。", "example": null}, {"def": "⒉使富足节用～民。", "example": null}, {"def": "⒊宽，宽宏包众容物谓之～（包众包含众物）。", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143297006243858','遇','1','yù','辶','12',NULL,'[{"def": "遇", "example": null}, {"def": "(形声。从辵,禺声。本义相逢,不期而会)", "example": null}, {"def": "同本义", "example": null}, {"def": "遇,逢也。--《说文》", "example": null}, {"def": "遇主于巷。--《易·暌》。崔注遇者,不期而会。”", "example": null}, {"def": "乃遇汝鸠汝方。--《书·序》", "example": null}, {"def": "诸侯未及期相见曰遇。--《礼记·曲礼》", "example": null}, {"def": "子路从而后,遇丈人。--《论语》", "example": null}, {"def": "夏,公及宋公遇于清;遇者何?不期也。--《公羊传》", "example": null}, {"def": "又如遇庭(和父母相见);遇人不淑(指女子嫁了不好的丈夫);遇缺补正(指遇到员额出缺时,得补任为官)", "example": null}, {"def": "遭受", "example": null}, {"def": "遇人之艰难矣。--《诗·卫风·中谷有蓷》", "example": null}, {"def": "又", "example": null}, {"def": "遇人之不淑矣。", "example": null}, {"def": "公等遇雨,皆已失期。--《史记", "example": null}, {"def": "遇yù", "example": null}, {"def": "⒈碰到，会见，相逢～到。～见。相～。", "example": null}, {"def": "⒉对待，款待待～。礼～。殊～。", "example": null}, {"def": "⒊遭到～险。～难。", "example": null}, {"def": "⒋机会机～。佳～。", "example": null}, {"def": "遇yóng 1.曲遇，古地名。", "example": null}, {"def": "遇ǒu 1.相对。 2.偶然。", "example": null}]','chinese-xinhua','0'),
('2101143297006243859','鹆','1','yù','鸟','12',NULL,'[{"def": "鹆", "example": null}, {"def": "鸟名。鸲鹆。又叫八哥儿”", "example": null}, {"def": "啼鹆无知惊好梦,舞鸡有意报残钟。--《梼杌闲评。--明珠缘》", "example": null}, {"def": "又如鹆歌(八哥儿的欢叫声);鹆眼(八哥儿眼);鹆研(有八哥儿眼的砚台)", "example": null}, {"def": "鹆yù", "example": null}]','chinese-xinhua','0'),
('2101143297006243860','愈','1','yù','心','13',NULL,'[{"def": "愈", "example": null}, {"def": "(形声。从心,俞声。本义病好了。这个意义后来又写作瘉”、発”) 同本义", "example": null}, {"def": "瘉,病瘳也。--《说文》", "example": null}, {"def": "幸上病瘉。--《汉书·卢绾传》", "example": null}, {"def": "至日中间差瘉。--《汉书·李寻传》", "example": null}, {"def": "周王病瘉。--《战国策·周策》", "example": null}, {"def": "武益愈。--《汉书·李广苏建传》", "example": null}, {"def": "因天气和暖,黛玉之疾渐愈。--《红楼梦》", "example": null}, {"def": "兼旬愈。--清·方苞《狱中杂记》", "example": null}, {"def": "又如愈合(伤口长好)", "example": null}, {"def": "愈", "example": null}, {"def": "胜过", "example": null}, {"def": "一暴之功,犹愈于十日之寒也。--清·顾炎武《与潘次耕札》", "example": null}, {"def": "愈", "example": null}, {"def": "更加;越发", "example": null}, {"def": "政事愈蹙。--《诗·小雅·小明》", "example": null}, {"def": "愈束缚牢甚。--", "example": null}, {"def": "愈（", "example": null}, {"def": "⒊瘉、", "example": null}, {"def": "⒊発）yù", "example": null}, {"def": "⒈贤，好，胜过孰～（哪个好）？此～于彼。", "example": null}, {"def": "⒉越，更加～甚。～益深入。生活～来～好。", "example": null}, {"def": "⒊病好了病已～。痊～了。", "example": null}, {"def": "愈yú 1.愉快，快乐。", "example": null}, {"def": "愈tōu 1.苟且。", "example": null}]','chinese-xinhua','0'),
