('2101143297006243862','煜','1','yù','火','13',NULL,'[{"def": "煜", "example": null}, {"def": "(形声。从火,昱声。本义照耀) 同本义", "example": null}, {"def": "日以煜乎昼,月以煜乎夜。--《太玄·元告》", "example": null}, {"def": "煜", "example": null}, {"def": "光耀;明亮", "example": null}, {"def": "煜煜", "example": null}, {"def": "煜yù", "example": null}, {"def": "⒈照耀。", "example": null}, {"def": "⒉火焰。", "example": null}]','chinese-xinhua','0'),
('2101143297006243863','峪','1','yù','山','10',NULL,'[{"def": "峪〈名〉", "example": null}, {"def": "(形声。从山,谷声。本义山谷)", "example": null}, {"def": "同本义", "example": null}, {"def": "你可便久镇着南边,夹山的那峪前,统领着军健,相持的那地面。--元·李直夫《虎头牌》", "example": null}, {"def": "山(多用作地名)", "example": null}, {"def": "峪口", "example": null}, {"def": "峪yù山谷。", "example": null}]','chinese-xinhua','0'),
('2101143297006243864','浴','1','yù','氵','10',NULL,'[{"def": "浴", "example": null}, {"def": "(形声。从水,谷声。本义洗澡)", "example": null}, {"def": "同本义", "example": null}, {"def": "浴,洒身也。--《说文》", "example": null}, {"def": "共王之沐浴。--《周礼·宫人》", "example": null}, {"def": "浴去身垢。--《论衡·讥月》", "example": null}, {"def": "浴乎沂。--《论语·先进》", "example": null}, {"def": "新浴者必振衣。--《史记·屈原贾生列传》", "example": null}, {"def": "浴于汤池。--《徐霞客游记·游黄山记》", "example": null}, {"def": "又如沐浴(洗澡;比喻受润泽);浴渪(洗澡);淋浴(喷水洗澡);浴桶(洗澡用的大桶)", "example": null}, {"def": "鸟飞忽上忽下", "example": null}, {"def": "黑鸟浴,黑鸟者何也?乌也。浴也者,飞乍高乍下也。--《大戴礼记》", "example": null}, {"def": "沉浸;浸染", "example": null}, {"def": "久浴文化,则渐悟人类之尊严。--鲁迅《坟·文化偏至论》", "example": null}, {"def": "又如浴蚕(浸", "example": null}, {"def": "浴yù洗澡～室。沐～。淋～。〈喻〉浑身浸染～血奋战。", "example": null}]','chinese-xinhua','0'),
