('2101143297006243866','钰','1','yù','钅','10',NULL,'[{"def": "钰", "example": null}, {"def": "珍宝", "example": null}, {"def": "钰,宝也。--《五音集韵》", "example": null}, {"def": "坚硬的金属", "example": null}, {"def": "钰,坚金。--《玉篇》", "example": null}, {"def": "钰yù", "example": null}, {"def": "⒈宝物。", "example": null}, {"def": "⒉坚硬的金属。", "example": null}]','chinese-xinhua','0'),
('2101143297006243867','预','1','yù','页','10',NULL,'[{"def": "预", "example": null}, {"def": "(形声。从页, 予声。本义安乐。经典通用豫”字)", "example": null}, {"def": "同本义", "example": null}, {"def": "仙亭日登眺,虎丘时游预。--唐·白居易《和微之诗》", "example": null}, {"def": "预先,事先。事先有准备。通豫”", "example": null}, {"def": "预备走舸。(豫备轻快的小船。豫,同预”,预先。舸,船;走舸,快船,偏正式词组。)--宋·司马光《资治通鉴》", "example": null}, {"def": "又如预虑(事先考虑);预筮(预卜吉凶);预借元宵(预先点放灯);预日(提前一天);预图(预先考虑);预置(事前陈设)", "example": null}, {"def": "预", "example": null}, {"def": "参与。通与”", "example": null}, {"def": "凡事相及为预。--《珠丛》", "example": null}, {"def": "且灌夫何预也?--《汉书·灌夫传》。师古曰预读曰豫", "example": null}, {"def": "预yù", "example": null}, {"def": "⒈在先，事前～先。～告。～言。～计。～约。～定。～防。～祝胜利。", "example": null}, {"def": "⒉加入，参加，参与～会。参～。干～其事。", "example": null}]','chinese-xinhua','0'),
('2101143297006243868','喐','1','yù','','8',NULL,'[{"def": "喐yù 1.见\\"喓喐\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297006243869','域','1','yù','土','11',NULL,'[{"def": "域〈名〉", "example": null}, {"def": "(形声。从土,或声。土,表示疆土。域”本作或”,与国”同义。从口,从戈,以守一。一,地也。”为会意字。本义疆界,疆域)", "example": null}, {"def": "同本义", "example": null}, {"def": "域,邦也。--《说文》。按,或者,封也,国者,邦也天子诸侯所守土为域,所建都为邦。", "example": null}, {"def": "以保尔域。--《汉书·韦元成传》。注谓封邑也。”", "example": null}, {"def": "正域彼四方。--《诗·商颂·玄鸟》", "example": null}, {"def": "驱一世之民,济之仁寿之域。--《汉书》", "example": null}, {"def": "又如域野(境内乡野);域内(域中);域外(境外;国外)", "example": null}, {"def": "地区,区域", "example": null}, {"def": "出百死,入绝域。--《汉书》", "example": null}, {"def": "卿曹与我俱在绝域", "example": null}, {"def": "域yù", "example": null}, {"def": "⒈疆界，一定范围之内的地方领～。地～。区～。长江流～。", "example": null}, {"def": "⒉〈古〉邦国，封邑邦～之内。以保尔～。", "example": null}]','chinese-xinhua','0'),
('2101143297006243870','堉','1','yù','','8',NULL,'[{"def": "堉yù 1.沃土。", "example": null}]','chinese-xinhua','0'),
('2101143297006243871','惐','1','yù','','8',NULL,'[{"def": "惐yù 1.痛心。", "example": null}]','chinese-xinhua','0'),
('2101143297006243872','欲','1','yù','欠','11',NULL,'[{"def": "欲", "example": null}, {"def": "(形声。从欠,谷声。欠”表示有所不足,故产生欲望。本义欲望;嗜欲) 同本义", "example": null}, {"def": "欲,贪欲也。--《说文》。俗字亦作慾。", "example": null}, {"def": "欲者,情之应也。--《荀子·正名》", "example": null}, {"def": "六欲。--《吕氏春秋·贵生》。注生死耳目口鼻也。”", "example": null}, {"def": "以欲竭其精。--《论语》。注乐色曰欲。”", "example": null}, {"def": "然则诸侯之地有限,暴秦之欲无厌。--苏洵《六国论》", "example": null}, {"def": "厉而不刚者,则欲夺之也。--三国魏·刘劭《人物志》", "example": null}, {"def": "又如欲令智昏(欲火使人丧失理智);欲障(嗜欲);欲海(佛教语。情欲令人迷本性,沉沦于生死大海);欲界(佛教语。三界之一,在色界", "example": null}, {"def": "欲yù", "example": null}, {"def": "⒈想要，想得到，想达到～要。～罢不能。～擒故纵。", "example": null}, {"def": "⒉希望，愿望～望。上下同～者胜。", "example": null}, {"def": "⒊需要胆～大而心～细。智～圆而行～方。", "example": null}, {"def": "⒋将要天～堕。东方～晓。", "example": null}, {"def": "⒌贪心，感情过盛贪～。利～。情～。", "example": null}]','chinese-xinhua','0'),
('2101143297006243873','袬','1','yù','','8',NULL,'[{"def": "袬yù", "example": null}, {"def": "⒈古同育”。", "example": null}]','chinese-xinhua','0'),
('2101143297006243874','谕','1','yù','讠','11',NULL,'[{"def": "谕", "example": null}, {"def": "(形声。从言,俞声。本义旧时上告下的通称。也指告诉)", "example": null}, {"def": "同本义", "example": null}, {"def": "谕,告也。--《说文》", "example": null}, {"def": "以谕九税之利。--《周礼·掌交》", "example": null}, {"def": "讶士掌四方之狱讼,谕罪刑于邦国。--《周礼·秋官》", "example": null}, {"def": "又如谕葬(圣上发旨的葬仪);面谕;谕知(告谕而使人知晓)", "example": null}, {"def": "明白、懂得", "example": null}, {"def": "谕,晓也。--《广雅》", "example": null}, {"def": "教之以事而谕诸德者也。--《周礼·师氏》注", "example": null}, {"def": "其言多当矣,而未谕也。--《荀子·儒效》", "example": null}, {"def": "又不能谕其内志。--《汉书·文帝纪》", "example": null}, {"def": "先生坐!何至于此!寡人谕矣。--《战国策·魏策》", "example": null}, {"def": "谕", "example": null}, {"def": "旧时用指上对下的文告、指示", "example": null}, {"def": "谕yù", "example": null}, {"def": "⒈告诉，叫人知道（旧时多用于上对下）～旨。面～。上～。手～。", "example": null}, {"def": "⒉〈古〉同\\"喻\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297006243875','阈','1','yù','门','11',NULL,'[{"def": "阈", "example": null}, {"def": "门槛", "example": null}, {"def": "阈,门榍也。--《说文》", "example": null}, {"def": "阈,门限也。--《玉篇》", "example": null}, {"def": "柣谓之阈。--《尔雅》。注阈,门限。”", "example": null}, {"def": "不践阈。--《礼记·曲礼》", "example": null}, {"def": "宾入不中门,不履阈。--《礼记·玉藻》", "example": null}, {"def": "见兄弟不踰阈。--《左传·僖公二十二年》", "example": null}, {"def": "思不出乎门阈。--《汉书·王莽传》", "example": null}, {"def": "仍增崖而衡阈。--《后汉书·班固传》", "example": null}, {"def": "立不中门,行不履阈。--《论语·乡党》", "example": null}, {"def": "又如阈闱(妇女所居的内室)", "example": null}, {"def": "泛指界限或范围", "example": null}, {"def": "门户;门口", "example": null}, {"def": "仰瞻城阈,俯惟阙庭。--三国魏·曹植《应诏》", "example": null}, {"def": "阈值", "example": null}, {"def": "阈yù门坎。〈引〉界限或范围～值。视～。", "example": null}]','chinese-xinhua','0'),
('2101143297006243876','喅','1','yù','','8',NULL,'[{"def": "喅yù 1.众声喧嚣。", "example": null}]','chinese-xinhua','0'),
('2101143297006243877','玉','1','yù','玉','5',NULL,'[{"def": "玉", "example": null}, {"def": "(象形。甲骨文字形。象一根绳子,串着一些玉石。玉”是汉字的一个部首。本义温润而有光泽的美石)", "example": null}, {"def": "同本义", "example": null}, {"def": "玉,石之美者,有五德,润泽以温,仁之方也…--《说文》", "example": null}, {"def": "君无故玉不去身。--《礼记·曲记》。疏玉谓佩也。”", "example": null}, {"def": "五玉。--《虞书》。郑注执之曰瑞,陈列曰玉。”", "example": null}, {"def": "王齐则共食玉。--《周礼·王府》", "example": null}, {"def": "惟辟玉食。--《书·洪范》", "example": null}, {"def": "牺牲玉帛,弗敢加也,必以信。--《左传》", "example": null}, {"def": "又如玉情儿(玉石的质量、成色);玉墀(白玉台阶);玉阙(宝座;皇宫);玉虚(道教指玉帝的居处);玉树(指槐树);玉砚(玉石制的砚台);玉雕(玉石雕成", "example": null}, {"def": "玉yù", "example": null}, {"def": "⒈一种珍贵的矿石，质细而坚硬，有光泽，微透明，可雕琢成簪、环等装饰品。〈喻〉洁白、美丽～颜。～龙。～人。", "example": null}, {"def": "⒉敬词～体。～照（人像照片）。", "example": null}, {"def": "⒊", "example": null}, {"def": "、穗可作饲料用。", "example": null}]','chinese-xinhua','0'),
('2101143297006243878','驭','1','yù','马','5',NULL,'[{"def": "驭", "example": null}, {"def": "(会意。从又,从马。又,手。用手驾御马匹。本义驾御车马)", "example": null}, {"def": "同本义", "example": null}, {"def": "驭,使马也。驭,古文御。--《广韵》", "example": null}, {"def": "驭者,操辔也。--《管子·形势解》", "example": null}, {"def": "王良造父者,善服驭者也。--《荀子·王霸》。注驭,与御同也。”", "example": null}, {"def": "东野子之善驭乎?--《荀子·哀公》", "example": null}, {"def": "予临兆民,懔乎若朽索之驭六马。--《书·五子之歌》", "example": null}, {"def": "又如驭夫(古官名。掌管驾驭车);驭吏(驾驭车马的役吏);驭人(驾车马的人)", "example": null}, {"def": "控制,制约", "example": null}, {"def": "廪藏虚罄,难用驭远。--《宋书·后废帝纪》", "example": null}, {"def": "又如驭远(控制远邦);驭教(掌握教化);驭控(驾驭控制)", "example": null}, {"def": "统治;治理", "example": null}, {"def": "驭yù", "example": null}, {"def": "⒈驾驭车马～车。又指驾驭车马的人～手。", "example": null}, {"def": "⒉驾驭，控制安上～下。振长策而～宇内（策鞭子。宇内天下）。", "example": null}]','chinese-xinhua','0'),
('2101143297006243879','吁','1','yù','口','6',NULL,'[{"def": "吁  xu", "example": null}, {"def": "(形声。从口,于声。本义表示惊怪、不然、感慨等) 同本义", "example": null}, {"def": "王曰吁!来!有邦有土,告尔祥刑。”--《书·吕刑》", "example": null}, {"def": "吁!惊也。--《说文》", "example": null}, {"def": "王曰吁,来!…”--《史记·周本纪》", "example": null}, {"def": "吁!是何言欤?--《法言·君子》。注吁!骇叹之声。”", "example": null}, {"def": "又如吁咈(表示不以为然之意);吁咈都俞(吁咈,吁俞。用以赞美君臣间论政之和洽。见《书·尧典》);吁嗟(表示忧伤或有所感;表示赞美)", "example": null}, {"def": "吁", "example": null}, {"def": "叹息,叹气", "example": null}, {"def": "香车辗尽关山日,弹罢琵琶只自吁。--《明珠记》", "example": null}, {"def": "又如吁唏(吁嘘。嘘唏,叹息);吁气(叹气);吁嗟(哀叹;叹息);吁嗟(慨叹);吁然", "example": null}, {"def": "吁（籲）yù", "example": null}, {"def": "⒈为某种要求而呼喊，多用于书面文章呼～。", "example": null}, {"def": "吁xū", "example": null}, {"def": "⒈叹息，叹气长～。", "example": null}, {"def": "⒉叹词。〈表〉惊疑，惊叹～，何故？～，可惜哉！", "example": null}, {"def": "吁yū 1.喝止牲口声。", "example": null}]','chinese-xinhua','0'),
('2101143297006243880','聿','1','yù','聿','6',NULL,'[{"def": "聿", "example": null}, {"def": "(指事。从聿一一者,牍也。秦以后皆作筽。本义毛笔。笔的本字,秦以后始加竹作笔)同本义", "example": null}, {"def": "聿,所以书也。楚谓之聿,吴谓之不律,燕谓之弗。--《说文》", "example": null}, {"def": "又如舌聿(即口笔”。用口所说的,用笔所写的)", "example": null}, {"def": "聿", "example": null}, {"def": "古汉语助词,用在句首或句中", "example": null}, {"def": "无念尔祖,聿修厥德。--《诗·大雅·文王》", "example": null}, {"def": "聿,循也。--《后汉书·傅毅传》注", "example": null}, {"def": "又如聿女(养女);聿遵(遵循。聿,发语词);聿追(聿本助词◇人往往训聿为述,因以聿追”谓追述先人德业)", "example": null}, {"def": "聿yù", "example": null}, {"def": "⒈笔。", "example": null}, {"def": "⒉文言句首或句中的语气助词。", "example": null}]','chinese-xinhua','0'),
('2101143297006243881','芋','1','yù','艹','6',NULL,'[{"def": "芋〈名〉", "example": null}, {"def": "(形声。从苃,于声。本义植物名。俗称芋艿”)", "example": null}, {"def": "同本义", "example": null}, {"def": "芋,大叶实根,骇人,故谓之芋也。--《说文》", "example": null}, {"def": "士卒食芋菽。--《史记·项羽本纪》", "example": null}, {"def": "其实葵菹芋。--《仪礼·士丧礼》", "example": null}, {"def": "又如芋火(煨芋的炭火);芋渠(大芋头。同芋魁”);芋荷(芋艿。因其叶似荷,故名。南方称芋头的叶及柄为芋荷);芋火(煨芋之火);芋郎君(抟芋酥作人形的食品);芋魁(芋的", "example": null}, {"def": "块茎。泛指薯类植物的块茎);芋魁豆饭(喻食物粗劣)", "example": null}, {"def": "泛指薯类植物", "example": null}, {"def": "芋yù", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉泛指薯类植物山～。", "example": null}, {"def": "芋yǔ 1.见\\"芋尹\\"。 2.通\\"宇\\"。居住。", "example": null}]','chinese-xinhua','0'),
('2101143297006243882','妪','1','yù','女','7',NULL,'[{"def": "妪", "example": null}, {"def": "以体相温", "example": null}, {"def": "羽者妪伏。--《淮南子·原道》。注以气剖卵也。”", "example": null}, {"def": "煦妪覆育万物。--《礼记·乐记》。注气曰煦,体曰妪。”", "example": null}, {"def": "柳下惠妪不逮门之女。--《诗·巷伯传》", "example": null}, {"def": "太子曰颜子缩屋称贞,柳下妪而不乱,未若此翁白首不娶者也。--《北齐书》", "example": null}, {"def": "又如妪伏(鸟类以体孵卵)", "example": null}, {"def": "养育;抚育", "example": null}, {"def": "以声华呕符妪掩万民百姓。--《淮南子》", "example": null}, {"def": "又如妪育(生育抚养);妪煦(生养覆育);妪拊(抚恤)", "example": null}, {"def": "妪", "example": null}, {"def": "(形声。从女,区声。本义母亲,妈妈)", "example": null}, {"def": "同本义", "example": null}, {"def": "妪,母也。--《说文》", "example": null}, {"def": "老妪夜哭。--《史记》", "example": null}, {"def": "东海莫贤", "example": null}, {"def": "妪（嫗）yù老年妇女。", "example": null}, {"def": "妪yǔ 1.以体相温。 2.指养育。 3.和悦貌。参见\\"妪然\\"﹑\\"妪妪\\"等。 4.恭顺貌。参见\\"妪\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297006243883','忬','1','yù','','6',NULL,'[{"def": "忬yù 1.迟疑不决。", "example": null}]','chinese-xinhua','0');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`,`hit_count`) VALUES
('2101143297014632448','饫','1','yù','饣','7',NULL,'[{"def": "饫", "example": null}, {"def": "吃饱", "example": null}, {"def": "饫,食过多。--《玉篇》", "example": null}, {"def": "饫,饱也,厌也。--《广雅》", "example": null}, {"def": "犀箸厌饫久未下,鸾刀缕切空纷纶。--杜甫《丽人行》", "example": null}, {"def": "饫肥之肠。--明·刘基《卖柑者言》", "example": null}, {"def": "又", "example": null}, {"def": "饫肥鲜者。又如饫闻(厌闻。所闻过多而感厌倦之意)", "example": null}, {"def": "赐", "example": null}, {"def": "饫,赐也。--《广韵》", "example": null}, {"def": "又如饫赐(赏赐丰足)", "example": null}, {"def": "饫礼,站立行礼", "example": null}, {"def": "夫礼之立成者为饫,昭明大节而已。--《国语·周语下》", "example": null}, {"def": "又如饫歌(行饫礼时所唱的歌诗)", "example": null}, {"def": "饫yù", "example": null}, {"def": "⒈饱。", "example": null}, {"def": "⒉私宴，宴饮。", "example": null}]','chinese-xinhua','0'),
('2101143297014632449','育','1','yù','月','8',NULL,'[{"def": "育〈动〉", "example": null}, {"def": "(会意。甲骨文字形,象妇女生孩子。上为母”及头上的装饰,下为倒着的子”。)", "example": null}, {"def": "同本义", "example": null}, {"def": "育,生也。--《广雅》", "example": null}, {"def": "无遗育。--《书·盘庚》", "example": null}, {"def": "至如今不育。--《国语·晋语》", "example": null}, {"def": "子孙蕃育之谓也。--《国语·周语》", "example": null}, {"def": "妇孕不育,失其道也。--《易·渐》", "example": null}, {"def": "又如节育(节制生育);育孕(怀胎足月以至分娩);生儿育女", "example": null}, {"def": "抚养;教育", "example": null}, {"def": "育,养子使作善也。--《说文》", "example": null}, {"def": "教育子。--《虞书》", "example": null}, {"def": "载生载育,时维后稷。--《诗·大雅·生民》", "example": null}, {"def": "又如育女(养女);育材(育才。培养人才);育德(培养德性);德育(政", "example": null}, {"def": "育yù", "example": null}, {"def": "⒈生，生养不～。做好计划生～。", "example": null}, {"def": "⒉养活，培植～蚕。～种。～苗。封山～林。", "example": null}, {"def": "⒊教育培～。德～。智～。体～。美～。", "example": null}, {"def": "育zhòu 1.古代帝王与贵族的后裔。 2.专指古代帝王与贵族的长子。参见\\"育子\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297014632450','郁','1','yù','阝','8',NULL,'[{"def": "郁", "example": null}, {"def": "郁夷", "example": null}, {"def": "郁,右扶风郁夷也。从邑,有声。--《说文》", "example": null}, {"def": "古地名『置县。在今陕西省陇县西", "example": null}, {"def": "物实无中核者谓之郁", "example": null}, {"def": "物实无中核者谓之郁,无刀斧之斫者谓之朴。--《论衡》", "example": null}, {"def": "又如郁朴(本指没有内核的果实或未加工的木料,借喻缺乏教养的人)", "example": null}, {"def": "郁 〈形〉", "example": null}, {"def": "文采美盛", "example": null}, {"def": "周监于二代,郁郁乎文哉!--《论语·八佾》", "example": null}, {"def": "纷郁郁其远承兮。--《楚辞·九章·思美人》", "example": null}, {"def": "又如郁郁桓桓(文采明盛、勇武出众的样子)", "example": null}, {"def": "丰盛", "example": null}, {"def": "蜜房郁毓被其阜。--左思《蜀都赋》。注盛多也。”", "example": null}, {"def": "又如郁毓(丰盛的样子);郁", "example": null}, {"def": "郁yù", "example": null}, {"def": "⒈茂盛，树木丛生葱～。", "example": null}, {"def": "⒉忧愁，愁闷忧～。抑～。", "example": null}, {"def": "⒊草木腐臭～气。", "example": null}, {"def": "⒋形容香气馥～。", "example": null}, {"def": "⒌〈古〉通\\"燠\\"。", "example": null}, {"def": "⒍", "example": null}, {"def": "①有文采文采～ ～。", "example": null}, {"def": "②忧愁，愁闷～ ～不乐。", "example": null}, {"def": "③香气浓烈岸芷汀兰，～ ～青青（芷一种香草）。", "example": null}]','chinese-xinhua','0'),
('2101143297014632451','彧','1','yù','彡','10',NULL,'[{"def": "彧〈形〉", "example": null}, {"def": "趣味高雅的,谈吐文雅的,有文采,有教养", "example": null}, {"def": "彧,文也。--《广雅》", "example": null}, {"def": "夏伯之乐舞谩彧。--《书·大传》。注长貌。言万物之滋曼彧然也。”", "example": null}, {"def": "茂盛", "example": null}, {"def": "疆场翼翼,黍稷彧彧。--《诗·小雅·信南山》", "example": null}, {"def": "彧yù", "example": null}]','chinese-xinhua','0'),
('2101143297014632452','昱','1','yù','日','9',NULL,'[{"def": "昱", "example": null}, {"def": "明天", "example": null}, {"def": "昱,明日也。从日,立声。--《说文》。段玉裁注凡经传子史,翌日字皆昱日之假借,翌与昱同立声,故相借。”", "example": null}, {"def": "又如昱日(明天)", "example": null}, {"def": "昱", "example": null}, {"def": "照耀", "example": null}, {"def": "日以昱乎昼,月以昱乎夜。--《太玄·告》", "example": null}, {"def": "昱", "example": null}, {"def": "光辉灿烂的,明亮而闪闪发光的", "example": null}, {"def": "焜昱错眩。--《淮南子·本经》", "example": null}, {"def": "后一日不亡,帝一日不得亲政。则此七年者,月之朗于夜,非日之昱于昼也。--王夫之《宋论·哲宗》", "example": null}, {"def": "又如昱昱,昱耀(明亮);昱奕(明盛)", "example": null}, {"def": "昱yù", "example": null}, {"def": "⒈日光。", "example": null}, {"def": "⒉明亮，照耀。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
('2101143297014632453','狱','1','yù','犭','9',NULL,'[{"def": "狱", "example": null}, {"def": "狱,确也。--《说文》", "example": null}, {"def": "而有狱讼者。--《周礼·大司徒》。注争罪曰狱。”", "example": null}, {"def": "利用狱。--《易·噬嗑》", "example": null}, {"def": "毋敢折狱。--《易·象上传》", "example": null}, {"def": "以两剂禁民狱。--《周礼·大司徒》", "example": null}, {"def": "谁谓女无家,何以速我狱?--《诗·召南》。毛传狱,讼也。”", "example": null}, {"def": "以两剂禁民狱。--《周礼》。郑玄注狱,谓相告以罪名者。”", "example": null}, {"def": "又如狱诉(告状);狱讼(诉讼);狱犴(诉讼);狱司(管理诉讼、牢狱的机构)", "example": null}, {"def": "狱", "example": null}, {"def": "讼案", "example": null}, {"def": "夫君臣无狱。--《国语·周语》", "example": null}, {"def": "君子以明庶政,无敢折狱。--《易·贲》", "example": null}, {"def": "又如狱辞(决狱之词);狱文(判决狱讼的文书);狱主(", "example": null}, {"def": "狱（獄）yù", "example": null}, {"def": "⒈监牢，监禁罪犯的场所监～。入～。", "example": null}, {"def": "⒉官司，罪案有～。冤～。文字～。", "example": null}]','chinese-xinhua','0'),
