('2101143297014632474','鹬','1','yù','鸟','17',NULL,'[{"def": "鹬", "example": null}, {"def": "(形声。从鸟,矞声。本义水鸟鹬)", "example": null}, {"def": "同本义", "example": null}, {"def": "鹬,翠鸟也。知天将雨。--《说文》", "example": null}, {"def": "知天文者冠鹬。--《礼记》", "example": null}, {"def": "鹬如鹑,色苍嘴长,在泥涂间鹬鹬声,村民云田鸡所化,亦鹌鹑类也。苏秦所谓鹬蚌相持者,即此。--《本草纲目》", "example": null}, {"def": "蚌方出曝,而鹬啄其肉。--《战国策》", "example": null}, {"def": "又如鹬鹬(水鹬鸟的叫声);鹬冠(鹬毛冠。古代为天文者之冠)", "example": null}, {"def": "鹬科多数种类鸟的通称", "example": null}, {"def": "栗色,尾和体侧具有横斑", "example": null}, {"def": "鹬蚌相争,渔翁得利", "example": null}, {"def": "鹬yù鸟名。鹬鸟，嘴和脚均长，趾间无蹼，羽毛茶褐色。常在水边或水田里捕食小鱼、小虫和贝类等。此鸟已少见，要保护，禁止猎杀。", "example": null}, {"def": "争斗，两败俱伤，让第三者得利。", "example": null}, {"def": "鹬shù 1.见\\"鹬子\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297014632475','蓹','1','yù','','13',NULL,'[{"def": "蓹yù 1.古代地名用字。参见\\"蓹儿\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297014632476','薁','1','yù','','13',NULL,'[{"def": "薁yù 1.蘡薁。又称野葡萄。果可酿酒，根叶可入药。 2.酸李。", "example": null}]','chinese-xinhua','0'),
('2101143297014632477','豫','1','yù','豕','15',NULL,'[{"def": "豫", "example": null}, {"def": "(形声。从象,予声。本义大象)", "example": null}, {"def": "同本义", "example": null}, {"def": "豫,象之大者。--《说文》", "example": null}, {"def": "豫焉若冬涉川。--《老子》。范应元注豫,象属。”", "example": null}, {"def": "地名。豫州,古九州之一", "example": null}, {"def": "指通豫南。--《列子·汤问》", "example": null}, {"def": "今河南省的简称", "example": null}, {"def": "姓", "example": null}, {"def": "豫", "example": null}, {"def": "假借为娱”。快乐", "example": null}, {"def": "豫,乐也。--《尔雅》", "example": null}, {"def": "豫,悦豫也。--《易·豫卦》释文。郑注豫,喜豫说乐之貌也。”", "example": null}, {"def": "心中和悦谓之豫。--《珠丛》", "example": null}, {"def": "何问之不豫也?--《庄子·应帝王》", "example": null}, {"def": "夫子若有不豫色然。╠", "example": null}, {"def": "豫 yù", "example": null}, {"def": "⒈快乐，安乐不～。逸～无期（无期无限度）。逸～亡身。", "example": null}, {"def": "⒉〈古〉通\\"预\\"。预备～则祸不生。", "example": null}, {"def": "⒊〈古〉通\\"与\\"。参加。", "example": null}, {"def": "⒋河南省的简称。", "example": null}, {"def": "豫xiè 1.古代州学名。", "example": null}, {"def": "豫shū 1.舒展，宽舒。", "example": null}]','chinese-xinhua','0'),
('2101143297014632478','繘','1','yù','','15',NULL,'[{"def": "繘yù 1.井上汲水用的绳索。 2.泛指绳索。 3.用绳汲井水。参见\\"繘井\\"。", "example": null}]','chinese-xinhua','0'),
