('2101143297014632487','鬻','1','yù','鬲','22',NULL,'[{"def": "鬻", "example": null}, {"def": "(形声。本义粥。引申为卖”)", "example": null}, {"def": "卖,出售", "example": null}, {"def": "鲋也鬻狱。--《左传·昭公十四年》", "example": null}, {"def": "市贱鬻贵。--《国语·齐语》", "example": null}, {"def": "人争鬻之。--明·刘基《卖柑者言》", "example": null}, {"def": "明告鬻梅者。--清·龚自珍《病梅馆记》", "example": null}, {"def": "又如鬻卜(卖卦);鬻文(为人撰写文章而接受酬劳。即卖文”);鬻技(出卖技艺以谋生);鬻歌(卖歌,以歌唱谋生);鬻爵(出卖官爵)", "example": null}, {"def": "使用", "example": null}, {"def": "盗取", "example": null}, {"def": "鬻", "example": null}, {"def": "幼小", "example": null}, {"def": "鬻狱", "example": null}, {"def": "鬻yù卖～文。", "example": null}, {"def": "鬻zhōu 1.同\\"粥\\"。 2.见\\"鬻鬻\\"。 3.通\\"煮\\"。", "example": null}]','chinese-xinhua','0'),
