('2101143297018826784','纡','1','yū','纟','6',NULL,'[{"def": "纡", "example": null}, {"def": "(形声。从糸,于声。本义屈曲;曲折)", "example": null}, {"def": "同本义", "example": null}, {"def": "纡,绌也,一曰萦也。--《说文》", "example": null}, {"def": "中弱则纡。--《考工记·矢人》。注曲也。”", "example": null}, {"def": "连行纡行。--《周礼·梓人》", "example": null}, {"def": "盘纡刻俨。--《淮南子·本经》", "example": null}, {"def": "水澹澹而盘纡兮。--宋玉《高唐赋》", "example": null}, {"def": "中弱则纡,中强则扬。--《周礼》", "example": null}, {"def": "又如纡远(曲折遥远);纡曲(迂回曲折);纡折(迂回曲折);纡余(迂回曲折);纡行(曲折而行)", "example": null}, {"def": "萦绕回旋", "example": null}, {"def": "水澹澹而盘纡兮,洪波淫淫之溶旐。--《文选·张衡·东京赋》", "example": null}, {"def": "又如纡回(屈曲回旋。也作迂回”);纡轸(盘旋曲折,乘车前往,未达目的而还);", "example": null}, {"def": "纡yū屈曲，绕弯～回。", "example": null}]','chinese-xinhua','0'),
('2101143297018826785','迂','1','yū','辶','6',NULL,'[{"def": "迂〈形〉", "example": null}, {"def": "(形声。从辵,于声。本义曲折,绕远)", "example": null}, {"def": "同本义", "example": null}, {"def": "迂,僻也。--《说文》。按,僻远也。", "example": null}, {"def": "迂乃心。--《书·盘庚》。传僻也。”", "example": null}, {"def": "子之迂也。--《论语》。皇疏远也。”", "example": null}, {"def": "彼岂乐为迂阔哉。--班固《答宾戏》", "example": null}, {"def": "寡人以为迂言也。”--《吕氏春秋·先已》", "example": null}, {"def": "却霍见其语迂。--《国语·周语》。注迂回加诬于人。”", "example": null}, {"def": "迂,曲也。--《后汉书·蔡邕传》注", "example": null}, {"def": "惩山北之塞,出入之迂也。--《列子·汤问》", "example": null}, {"def": "又如迂直(虽迂曲却是最直接有利的);迂折(迂回曲折);迂弘(深远宏大);迂邈(遥远);迂路(绕路);迂深", "example": null}, {"def": "迂yū", "example": null}, {"def": "⒈曲折，绕远～曲。～回。", "example": null}, {"def": "⒉陈旧，不合时宜～腐。～论。～时。", "example": null}]','chinese-xinhua','0'),
