('2101143297018826792','员','1','yuán','口','7',NULL,'[{"def": "员", "example": null}, {"def": "(会意。甲骨文字形,表示俯视鼎,看到鼎口是圆形的。小篆从贝,口声。本义物的数量;人员的数额。亦指人员)", "example": null}, {"def": "同本义", "example": null}, {"def": "员,物数也。--《说文》。木曰枚,竹曰箇,丝曰总,貝曰员。--《说文》", "example": null}, {"def": "员,众也。--《广雅》", "example": null}, {"def": "国人过员。--《汉书·高惠高后功臣表》。注数也。”", "example": null}, {"def": "责以员程。--《汉书·尹翁归传》", "example": null}, {"def": "今少一人,愿君即以遂备员而行矣。--《史记·平原君虞卿列传》", "example": null}, {"def": "又如员位(人员定额;职位);员次(员额等次)", "example": null}, {"def": "官员的定额。又指官员、官吏", "example": null}, {"def": "员yuán", "example": null}, {"def": "⒈在工作或学习的人公务～。售货～。演～。学～。", "example": null}, {"def": "⒉团体或组织中的分子会～。团～。党～。", "example": null}, {"def": "⒊周围幅～（指疆域）。", "example": null}, {"def": "⒋量词。指人数已满～。三～大将。", "example": null}, {"def": "⒌〈古〉通\\"圆\\"。圆形～石。", "example": null}, {"def": "员yùn姓。", "example": null}, {"def": "员yún见于古人名。", "example": null}]','chinese-xinhua','0'),
('2101143297018826793','园','1','yuán','囗','7',NULL,'[{"def": "园", "example": null}, {"def": "(形声。从囗,袁声。形符为囗”,表示范围。本义种蔬菜、花果、树木的地方)", "example": null}, {"def": "同本义", "example": null}, {"def": "园,所以树果也。--《说文》", "example": null}, {"def": "种树曰园。--《三苍》", "example": null}, {"def": "园圃毓草木。--《周礼·大宰》", "example": null}, {"def": "以场圃任园地。--《周礼·载师》。注樊圃谓之园。”", "example": null}, {"def": "于丘园。--《易·贲》", "example": null}, {"def": "园有桃。--《诗·魏风·园有桃》", "example": null}, {"def": "青青园中葵。--《乐府诗集·长歌行》", "example": null}, {"def": "田园将芜。--晋·陶渊明《归园田居》", "example": null}, {"def": "又", "example": null}, {"def": "园日涉以成趣。", "example": null}, {"def": "又如园头(禅寺内管菜园的人);果园;植物园;园公(即东园公。商山四皓之一;又指管理花园的仆人);园户(指唐宋时种植、制作茶", "example": null}, {"def": "园（園）yuán", "example": null}, {"def": "⒈种植蔬菜、花果等的地方菜～。桃～。花～儿。果～子。", "example": null}, {"def": "⒉供游玩、娱乐或保育等的地方公～。植物～。动物～。颐和～。游乐～。幼儿～。", "example": null}, {"def": "⒊", "example": null}, {"def": "园wán 1.削除棱角使圆。", "example": null}]','chinese-xinhua','0'),
