('2101143297018826799','媛','1','yuán','女','12',NULL,'[{"def": "媛 婵媛”", "example": null}, {"def": "姿态美好", "example": null}, {"def": "牵连,相连", "example": null}, {"def": "媛〈名〉", "example": null}, {"def": "美女", "example": null}, {"def": "媛,美女也,人所援也。从女,从爰,爰,于也。--《说文》", "example": null}, {"def": "美女为媛。--《尔雅》", "example": null}, {"def": "又如媛女(美女);媛德(女子的美德)", "example": null}, {"def": "年轻夫人", "example": null}, {"def": "媛yuàn美女。", "example": null}, {"def": "媛yuán", "example": null}]','chinese-xinhua','0'),
('2101143297018826800','垣','1','yuán','土','9',NULL,'[{"def": "垣〈名〉", "example": null}, {"def": "(形声。从土,亘声。本义矮墙,也泛指墙)", "example": null}, {"def": "同本义", "example": null}, {"def": "垣,墙也。--《说文》", "example": null}, {"def": "既勤垣墉。--《书·梓材》。马注卑曰垣,高曰墉。”", "example": null}, {"def": "周垣之高八尺。--《墨子·备城门》", "example": null}, {"def": "尽毁其馆之垣。--《左传·襄公三十一年》", "example": null}, {"def": "为家不治垣产。--《汉书·萧何传》", "example": null}, {"def": "又如垣衣(生在墙垣上的苔);垣堵(墙);垣屋(有围墙的房室;围墙和房屋)", "example": null}, {"def": "城墉", "example": null}, {"def": "官署的代称", "example": null}, {"def": "花隐掖垣暮,啾啾栖鸟过。--杜甫《春宿左省诗》", "example": null}, {"def": "姓", "example": null}, {"def": "垣 〈动〉", "example": null}, {"def": "筑墙围绕", "example": null}, {"def": "天云垣其既立兮,家愿得乎双逞。╠", "example": null}, {"def": "垣yuán矮墙。泛指墙城～。", "example": null}]','chinese-xinhua','0'),
('2101143297018826801','爰','1','yuán','爫','9',NULL,'[{"def": "爰〈动〉", "example": null}, {"def": "(会意。甲骨文字形。象两手相援引,中间一画表示瑗玉。本义引,援引)", "example": null}, {"def": "同本义。也作援”", "example": null}, {"def": "绵诸乞爰。--《史记》", "example": null}, {"def": "曰;称为", "example": null}, {"def": "土爰称穑。--《书·洪范》", "example": null}, {"def": "改易;更换", "example": null}, {"def": "既爰宅于兹,重我民,无尽刘。--《书·盘庚上》", "example": null}, {"def": "又如爰颁(另行颁布);爰田(变更旧日田土所有制,以公田赏赐众人。也称辕田”);爰居(迁居)", "example": null}, {"def": "爰 〈介〉", "example": null}, {"def": "于;从", "example": null}, {"def": "爰兹发迹,断蛇奋旅。--《汉书》", "example": null}, {"def": "爰 〈连〉", "example": null}, {"def": "于是", "example": null}, {"def": "乐土乐土,爰得我所。--《诗·魏风·硕鼠》", "example": null}, {"def": "爰yuán〈古〉", "example": null}, {"def": "⒈乃，于是～执笔而记之。～整驾而亟行（亟快）。", "example": null}, {"def": "⒉句首语气词～居～处，～丧其马。", "example": null}]','chinese-xinhua','0'),
('2101143297018826802','原','1','yuán','厂','10',NULL,'[{"def": "原", "example": null}, {"def": "(会意。小篆字形。象泉水从山崖里涌出来。从厂,象山崖石穴形。从泉。本义水源,源泉)", "example": null}, {"def": "源”的古字。水源,水流起头的地方", "example": null}, {"def": "原,水泉本也。--《说文》。俗字作源”。", "example": null}, {"def": "原泉混混。--《孟子》", "example": null}, {"def": "原流、泉浡。--《淮南子·原道》", "example": null}, {"def": "犹塞川原为潢洿也。--《汉书·食货志》", "example": null}, {"def": "有本有原。--唐·韩愈《原毁》", "example": null}, {"def": "又如原泉(源泉);原流(源流)", "example": null}, {"def": "起源;根本;根由", "example": null}, {"def": "必达于礼乐之原。--《礼记·孔子闲居》。注犹本也。”", "example": null}, {"def": "原小则鲜。--《史记·货殖列传》。", "example": null}, {"def": "又", "example": null}, {"def": "衣食之原。", "example": null}, {"def": "原yuán", "example": null}, {"def": "⒈水源，源泉水有～。", "example": null}, {"def": "⒉开始，最初的～始。〈引〉没有加工的～件。～料。～油。", "example": null}, {"def": "⒊本来，早先的～来。～先。～籍。请放～处。", "example": null}, {"def": "⒋根源，追究根源～因。～本穷末。", "example": null}, {"def": "⒌谅解，宽容～谅。情有可～。", "example": null}, {"def": "⒍宽广平坦的地方～野。草～。平～。高～。", "example": null}, {"def": "⒎四周陡，顶面平之高地。这也是我国西北黄土高原地区，因流水冲刷而形成的此种地貌。", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "①言行所持的准则按～则办事。", "example": null}, {"def": "②指总的方面，不是具体细节～则上应允。", "example": null}, {"def": "⒑", "example": null}, {"def": "原yuàn 1.谨慎老实。", "example": null}]','chinese-xinhua','0'),
('2101143297018826803','圆','1','yuán','囗','10',NULL,'[{"def": "圆", "example": null}, {"def": "(形声。从囗,员声。本义圆形)", "example": null}, {"def": "同本义", "example": null}, {"def": "圆,圜全也。--《说文》", "example": null}, {"def": "圆而神。--《易·系辞》", "example": null}, {"def": "天道曰圆,地道曰方。--《大戴礼记·曾子天圆》", "example": null}, {"def": "中吾规者谓之圆。--《墨子·天志》", "example": null}, {"def": "水圆折者有珠。--《淮南子·地形》", "example": null}, {"def": "百工为方以矩,为圆以规。--《墨子·法仪》", "example": null}, {"def": "方圆两炮台。--《广东军务记》", "example": null}, {"def": "又如圆丢丢(圆溜溜);圆浑(浑圆);圆领(明朝官员的常礼服。其胸前背后加有不同图案的补子以区别官阶的,叫补服);滚圆(极圆)", "example": null}, {"def": "圆通;灵活", "example": null}, {"def": "如今到外头去作官,自然非家居可比,总得学些", "example": null}, {"def": "圆yuán", "example": null}, {"def": "⒈在平面上，定点和定距离的动点之轨迹的称谓。定点称\\"～心\\"。定距离称\\"～的半径\\"。有时也称轨迹所围的部分为～。称轨迹为～周。", "example": null}, {"def": "⒉像球形的滚～。～房顶。", "example": null}, {"def": "⒊完备，周全～满。大团～。", "example": null}, {"def": "⒋使完备，使周全～谎。自～其说。", "example": null}, {"def": "⒌婉转字正腔～。深～似转簧。", "example": null}, {"def": "⒍货币名。也作\\"元\\"一百～。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
