('2101143297018826808','援','1','yuán','扌','12',NULL,'[{"def": "援", "example": null}, {"def": "(形声。从手,爰声。本义拉,引)", "example": null}, {"def": "同本义", "example": null}, {"def": "援,引也。--《说文》", "example": null}, {"def": "无然畔援。--《诗·大雅·皇矣》", "example": null}, {"def": "不援其所不及。--《礼记·缁衣》", "example": null}, {"def": "不援上。--《礼记·中庸》", "example": null}, {"def": "男女授受不亲,嫂溺手援非正。--《豆棚闲话》", "example": null}, {"def": "右抚剑,左援带,命驱之出。--《左传》", "example": null}, {"def": "又如援及(动起);援推(引之使来,推之使去)", "example": null}, {"def": "攀援", "example": null}, {"def": "猱蝯善援。--《尔雅》", "example": null}, {"def": "桃李之垂行者,莫之援也。--《吕氏春秋·下贤》", "example": null}, {"def": "夫为四邻之援。--《国语·鲁语上》", "example": null}, {"def": "猿猱欲渡愁攀援。--李白《蜀道难》", "example": null}, {"def": "石崖侧削则援崖。--《徐霞客游记·游黄山记", "example": null}, {"def": "援yuán", "example": null}, {"def": "⒈拉，拽，牵引攀～。～引。", "example": null}, {"def": "⒉引用～用。～例。", "example": null}, {"def": "⒊帮助，救助～助。求～。支～。", "example": null}, {"def": "援huàn 1.见\\"畔援\\"。", "example": null}]','chinese-xinhua','0'),
