('2101143297018826835','苑','1','yuàn','艹','8',NULL,'[{"def": "苑〈名〉", "example": null}, {"def": "(形声。从苃,夗声。本义养禽兽植树木的地方◇来多指帝王游乐打猎的地方)", "example": null}, {"def": "同本义", "example": null}, {"def": "苑,所以养禽兽囿也。--《说文》", "example": null}, {"def": "养牛马林木曰苑。--《三苍》", "example": null}, {"def": "有垣曰苑。--《字林》", "example": null}, {"def": "值林为苑。--左思《吴都赋》。刘注有木曰苑。”", "example": null}, {"def": "泛指园林,花园", "example": null}, {"def": "会幸苑中。--宋·王谠《唐语林·雅量》", "example": null}, {"def": "又如苑囿兵(禁兵);苑马(苑囿和马厩;亦指苑囿中的马)", "example": null}, {"def": "姓", "example": null}, {"def": "苑yuàn", "example": null}, {"def": "⒈养禽兽、植树木的地方。旧时多指帝王游乐打猎的场所。", "example": null}, {"def": "⒉（文艺、学术等）会聚的地方艺～。文～。", "example": null}, {"def": "苑yù 1.积聚;郁积。", "example": null}, {"def": "苑yùn 1.积聚;郁积。", "example": null}, {"def": "苑wǎn 1.草名。指紫菀﹑女菀等。", "example": null}, {"def": "苑yuān 1.姓。三国时有苑御。见《三国志．吴志．贺齐传》。", "example": null}]','chinese-xinhua','0'),
('2101143297018826836','怨','1','yuàn','心','9',NULL,'[{"def": "怨", "example": null}, {"def": "(形声。从心,夗声。本义怨恨;仇恨)", "example": null}, {"def": "同本义", "example": null}, {"def": "怨,恚也。--《说文》", "example": null}, {"def": "曰怨乎。--《论语》。皇疏恨也。”", "example": null}, {"def": "施行得理,谓之德。反德为怨。--《贾子道术》", "example": null}, {"def": "不怨人取之。--《淮南子·说山》", "example": null}, {"def": "天子甚怨。--《汉书·李广苏建传》", "example": null}, {"def": "人怨恶其君。--清·黄宗羲《原君》", "example": null}, {"def": "怨颇兴。--清·张廷玉《明史》", "example": null}, {"def": "怨愤所积。--孙文《序》", "example": null}, {"def": "又如怨怅(怨畅。怨恨);怨谤(怨恨诽谤);怨恶(怨恨憎恶);怨艾(悔恨自己的错误);怨詈(怨恨并咒骂);恩怨(恩惠和仇恨);宿怨(旧有的怨恨);怨痛(怨恨哀痛)", "example": null}, {"def": "责怪;", "example": null}, {"def": "怨yuàn", "example": null}, {"def": "⒈不满，责备～言。莫～他。劳而不～。～天者无识。", "example": null}, {"def": "⒉仇恨～恨。恩～分明。", "example": null}, {"def": "⒊", "example": null}, {"def": "怨yùn 1.蕴藏，蓄积。", "example": null}]','chinese-xinhua','0'),
('2101143297018826837','院','1','yuàn','阝','9',NULL,'[{"def": "院〈名〉", "example": null}, {"def": "(形声。从阜,完声。阜”是土山,与土、建筑有关。本义庭院,院子。房屋围墙以内的空地)", "example": null}, {"def": "同本义", "example": null}, {"def": "院,垣也。--《广雅》", "example": null}, {"def": "院,周垣也。--《玉篇》", "example": null}, {"def": "有垣墙者曰院。--《增韵》", "example": null}, {"def": "深院月明人静。--汉·司马光《西江月》", "example": null}, {"def": "又如前院;后院;深宫大院", "example": null}, {"def": "四周有墙垣围绕、自成部分的房屋", "example": null}, {"def": "院东五里。--宋·王安石《游褒禅山记》", "example": null}, {"def": "院僧夜闻大呼。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "驰往油画院。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "又如画院(书院)", "example": null}, {"def": "房屋周围的垣墙", "example": null}, {"def": "林园", "example": null}, {"def": "院yuàn", "example": null}, {"def": "⒈房屋围墙里面的空地～落。～坝子。庭～儿。", "example": null}, {"def": "⒉某些机关、单位和公共场所的名称法～。医～。剧～。电影～。", "example": null}, {"def": "⒊专指学院大专～校。研究生～。", "example": null}]','chinese-xinhua','0'),
