('2101143297023021112','韫','1','yùn','韦','13',NULL,'[{"def": "韫", "example": null}, {"def": "蕴葳;包含", "example": null}, {"def": "韫,裹也。--《广雅》犊", "example": null}, {"def": "韫于荆石。--《汉书·叙传上》", "example": null}, {"def": "石韫玉而山晖。--陆机《文赋》", "example": null}, {"def": "又如韫藏(蓄积而未显露);韫椟(隐藏其才不为世用。或指隐藏其才以待时;也指深闺中的才女);韫愚(愚笨的样子);韫椟而藏(比喻为才不为世用)", "example": null}, {"def": "韫（韞）yùn藏，收藏石～玉而山辉。～椟而藏诸（收入柜子里藏起来吧）。", "example": null}, {"def": "韫wēn 1.赤黄色。参见\\"韫韨\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297023021113','韵','1','yùn','音','13',NULL,'[{"def": "韵", "example": null}, {"def": "(形声。从音,员(匀)声。本义和谐悦耳的声音)", "example": null}, {"def": "同本义", "example": null}, {"def": "余韵徐歇。--宋· 苏轼《石钟山记》", "example": null}, {"def": "短笛无声,寒砧不韵。--《西游记》", "example": null}, {"def": "又如韵悠悠(声音悠扬)", "example": null}, {"def": "归本于喉的音。即语音学所称的韵母", "example": null}, {"def": "诗赋中的韵脚或押韵的字", "example": null}, {"def": "气韵;风度", "example": null}, {"def": "韵", "example": null}, {"def": "风韵雅致", "example": null}, {"def": "美,标致", "example": null}, {"def": "韵（韻）yùn", "example": null}, {"def": "⒈和谐悦耳的声音琴～悠扬。", "example": null}, {"def": "⒉字音中声母以外的，字音中后面的部分～母。押～。", "example": null}, {"def": "⒊诗歌、辞赋等的韵脚异声相从谓之和，同声相应谓之～。", "example": null}, {"def": "⒋风度，风致～度。风～。", "example": null}]','chinese-xinhua','0'),
('2101143297023021114','熨','1','yùn','火','15',NULL,'[{"def": "熨帖 yu", "example": null}, {"def": "熨帖的心情", "example": null}, {"def": "熨  yun", "example": null}, {"def": "(形声。从火,尉声。本义用金属器具加热,按压衣服,使之平贴)", "example": null}, {"def": "同本义", "example": null}, {"def": "衣裳不整,伏床熨之。--《南史》", "example": null}, {"def": "又如熨衣(烫平衣服)", "example": null}, {"def": "烘烤", "example": null}, {"def": "紧贴", "example": null}, {"def": "以身熨之。--《世说新语》", "example": null}, {"def": "又如熨贴(贴切;妥帖)", "example": null}, {"def": "用药热敷", "example": null}, {"def": "汤熨之所及。--《韩非子·喻老》", "example": null}, {"def": "熨斗", "example": null}, {"def": "熨平", "example": null}, {"def": "熨yùn", "example": null}, {"def": "⒈用热铁、金属器烫～衣服。", "example": null}, {"def": "⒉", "example": null}, {"def": "熨yù", "example": null}, {"def": "⒈", "example": null}, {"def": "熨wèi 1.热敷。中医一种外科疗法。", "example": null}]','chinese-xinhua','0'),
('2101143297023021115','蕴','1','yùn','艹','15',NULL,'[{"def": "蕴", "example": null}, {"def": "(形声。从苃,蕴声。本义积聚,蓄藏)", "example": null}, {"def": "同本义", "example": null}, {"def": "蘮,积也。--《说文》", "example": null}, {"def": "字亦作蕴”。", "example": null}, {"def": "蘮,聚也。--《广雅》", "example": null}, {"def": "芟夷蘮崇之。--《左传·隐公六年》", "example": null}, {"def": "蓄而弗治将蘮。--《左传·昭公二十五年》", "example": null}, {"def": "而以是相蕴。--《庄子·齐物论》", "example": null}, {"def": "我心蕴结兮。--《诗·桧风·素冠》", "example": null}, {"def": "蕴利生孽,姑使无蕴乎。--《左传·昭公十年》", "example": null}, {"def": "又如蕴积(蕴藏;积聚);蕴哲(蓄藏智慧);蕴艺(藏蓄的才华)", "example": null}, {"def": "包藏;包含", "example": null}, {"def": "万物尽然,而以是相蕴。--《庄子》", "example": null}, {"def": "蕴", "example": null}, {"def": "乱麻", "example": null}, {"def": "蕴yùn", "example": null}, {"def": "⒈积聚，蓄藏～藏。～蓄。", "example": null}, {"def": "⒉深奥精～。", "example": null}, {"def": "⒊郁结～愤。", "example": null}]','chinese-xinhua','0'),
