('2101143297027215371','攒','1','zǎn','扌','19',NULL,'[{"def": "攒  cuan", "example": null}, {"def": "簇拥;围聚;聚集", "example": null}, {"def": "攒,聚也。--《广韵》", "example": null}, {"def": "攒,族聚也。--《韵会》", "example": null}, {"def": "攒珍宝之玩好。--张衡《西京赋》", "example": null}, {"def": "攒戾莎。--《汉书·司马相如传上》", "example": null}, {"def": "复叠攒仄。--嵇康《琴赋》", "example": null}, {"def": "乡民蚁拥蜂攒,布满山麓。--《广东军务记》", "example": null}, {"def": "又如万头攒动;万箭攒心;攒簇(聚集;簇拥);攒绕(聚集围绕);攒仄(重叠相连);攒蛾(皱眉)", "example": null}, {"def": "结算", "example": null}, {"def": "装配起来", "example": null}, {"def": "拿;取", "example": null}, {"def": "攒", "example": null}, {"def": "待葬的棺柩", "example": null}, {"def": "攒 cuān聚拢起来；拼凑～钱。又见zǎn。", "example": null}, {"def": "【攒射】集中（火力）射击。", "example": null}, {"def": "攒（儹）zǎn", "example": null}, {"def": "⒈积聚，储蓄积～。～肥。～钱。", "example": null}, {"def": "攒zàn 1.周代地方组织单位之一。一百户为一攒。", "example": null}, {"def": "攒zuān 1.通\\"钻\\"。穿孔;钻入。亦指打孔眼的工具。 2.簪插，插。", "example": null}, {"def": "攒cuán 1.丛聚;积聚。 2.积竹杖。聚合细竹为之。 3.暂厝;停殡。谓临时安置灵柩以待安葬。", "example": null}]','chinese-xinhua','0'),
('2101143297027215372','儹','1','zǎn','亻','21',NULL,'[{"def": "儹", "example": null}, {"def": "积蓄;积聚", "example": null}, {"def": "积儧下许多家私金银。--《水浒传》", "example": null}, {"def": "又如儧钱(积蓄钱财);儧积(聚敛);儧那(统计,总括地核计)", "example": null}, {"def": "赶快,加快", "example": null}, {"def": "一面儧造雷车已了,装载法物,推到阵前。--《水浒传》", "example": null}, {"def": "又如儧运(赶运;催运);儧造(赶造)", "example": null}, {"def": "儹zǎn1.同\\"攒1\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297027215373','趱','1','zǎn','走','23',NULL,'[{"def": "趱", "example": null}, {"def": "催促;逼使", "example": null}, {"def": "皂隶挥鞭趱行路,躜尔今朝入关去。--姚燮《粮船行》", "example": null}, {"def": "又如趱逼(催迫);趱马向前", "example": null}, {"def": "赶;加快;加紧", "example": null}, {"def": "长江后浪催前浪,一替新人趱旧人。--《张协状元》", "example": null}, {"def": "又如趱工(赶工、赶活);趱快(犹赶快);趱行(趱路。赶路);趱办(趱干,赶快办理);趱运(赶快运送)", "example": null}, {"def": "积蓄", "example": null}, {"def": "你积趱的金银过北斗。--《陈州粜米》", "example": null}, {"def": "又如趱足(积蓄);趱钱;趱物;趱家私", "example": null}, {"def": "使,鼓", "example": null}, {"def": "移动", "example": null}, {"def": "趱zǎn赶，快走～路。～马前进。", "example": null}]','chinese-xinhua','0'),
