('2101143297027215384','驵','1','zǎnɡ','马','8',NULL,'[{"def": "驵", "example": null}, {"def": "骏马,好马", "example": null}, {"def": "驵,壮马也。《六书故》引作奘马,从马,且声。--《说文》", "example": null}, {"def": "苏驵军于泥阳。--《史记·樊郦滕灌列传》。索隐驵者,龙马也。”", "example": null}, {"def": "同驽骡与乘驵兮。--《楚辞·九叹·忧苦》", "example": null}, {"def": "驵疾(骏马疾驰);驵壮(马健壮);驵卒(马夫);驵骏(马健壮的样子)", "example": null}, {"def": "马贩子。泛指市侩", "example": null}, {"def": "节驵侩。--《汉书·货殖传》", "example": null}, {"def": "又如驵竖(市侩的鄙称);驵牙(市侩);驵棍(市侩恶棍)", "example": null}, {"def": "驵zǎng", "example": null}, {"def": "⒈好马，壮马。", "example": null}, {"def": "⒉", "example": null}, {"def": "驵zù 1.(又读zù)壮马;骏马。 2.马匹交易的经纪人。泛指市侩。 3.粗大。 4.平庸。参见\\"驵工\\"。 5.驱。 6.通\\"?\\"。盛饰。", "example": null}, {"def": "驵zǔ 1.通\\"组\\"。 2.通\\"阻\\"。 3.通\\"恑\\"。骄。", "example": null}]','chinese-xinhua','0'),
('2101143297027215385','脏','1','zānɡ','月','10',NULL,'[{"def": "脏", "example": null}, {"def": "(形声。左形,右声。本义中医学以心、肝、脾、肺、肾为五脏◇因以为身体内脏的通称)同本义", "example": null}, {"def": "脏,五脏也。--《正字通》", "example": null}, {"def": "脏的本字是藏。脏是藏”的后起分别字。如脏躁症(中医病名。主要症为神躁不宁,哭笑无常);脏象(指人体脏腑正常机能及发生病态变化时反映于外的征象);内脏;五脏六", "example": null}, {"def": "腑", "example": null}, {"def": "脏（髒）zāng污秽，不干净～水。衣服～了，快换一件。", "example": null}, {"def": "脏（舓）zàng指身体的内部器官内～。五～（心肝脾肺肾）。", "example": null}, {"def": "脏zǎng 1.见\\"骯脏\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297027215386','赃','1','zānɡ','贝','10',NULL,'[{"def": "赃", "example": null}, {"def": "(形声。左形,右声。本义赃物) 同本义", "example": null}, {"def": "以赃获罪,没其先居之财。--《列子·天瑞》", "example": null}, {"def": "又如赃仗(赃证);赃派(栽赃诬陷);栽赃(坐赃。把赃物或违禁物暗放在别人处,诬告他犯法);窝赃;追赃;分赃;退赃;销赃;赃品(赃物);赃银(赃款)", "example": null}, {"def": "赃", "example": null}, {"def": "贪污;行贿", "example": null}, {"def": "纳贿曰赃。--《广韵》", "example": null}, {"def": "南阳太守韩昭坐赃,下狱死。--《后汉书·质帝纪》", "example": null}, {"def": "所在虏掠,赃各千万计,并斩之。--《魏书·世祖纪》", "example": null}, {"def": "又如赃秽(贪赃纳贿);赃罪(贪污受贿罪);赃贿(贪赃纳贿)", "example": null}, {"def": "赃（趀、趎）zāng贪污、受贿或盗窃等所取得的财物～款。～物。窝～。贪～枉法。严惩～官。", "example": null}]','chinese-xinhua','0'),
('2101143297027215387','臧','1','zānɡ','臣','14',NULL,'[{"def": "臧", "example": null}, {"def": "收藏。通藏”", "example": null}, {"def": "臧于理宫。--《汉书·礼乐志》。师古曰古书怀藏之字本皆作臧,汉书例为臧耳。”", "example": null}, {"def": "繁启蕃长于春夏,畜积收臧于秋冬。--《荀子·天论》", "example": null}, {"def": "又如臧去(密藏,珍藏。去,弆的省文,即密藏)", "example": null}, {"def": "zang", "example": null}, {"def": "臧", "example": null}, {"def": "(形声。从臣,戕)声。臣,奴隶。本义男奴隶)", "example": null}, {"def": "同本义", "example": null}, {"def": "臧与谷二人相马牧羊--《庄子·骈拇》", "example": null}, {"def": "又如臧聚(仆隶役夫);臧获(古代对奴婢的贱称);臧仆(精选和训练驾御帝王所乘五辂的役夫,使皆善其事)", "example": null}, {"def": "成功", "example": null}, {"def": "执事顺成为臧,逆为否。--《左传》", "example": null}, {"def": "通赃”。赃物", "example": null}, {"def": "臧zāng", "example": null}, {"def": "⒈善，好何用不～？", "example": null}, {"def": "⒉", "example": null}, {"def": "①善恶，得失。", "example": null}, {"def": "②评论，说好说坏～否人物。", "example": null}, {"def": "臧cáng 1.收藏;隐藏。", "example": null}, {"def": "臧zàng 1.\\"脏\\"的古字。内脏，五脏。 2.库藏。", "example": null}]','chinese-xinhua','0'),
