('2101143297027215394','造','1','zào','辶','10',NULL,'[{"def": "造", "example": null}, {"def": "(形声。从辵,告声。本义到;往某地去)", "example": null}, {"def": "同本义", "example": null}, {"def": "造,就也。--《说文》", "example": null}, {"def": "咸造勿亵在王庭。--《书·盘庚》", "example": null}, {"def": "凡四方之宾 客造焉。--《周礼·司门》", "example": null}, {"def": "造于西阶下。--《仪礼·士丧礼》", "example": null}, {"def": "而造大国之城下。--《战国策·宋策》", "example": null}, {"def": "造饮辄尽。--陶渊明《五柳先生传》", "example": null}, {"def": "明日造朝。--唐·柳宗元《柳河东集》", "example": null}, {"def": "造玉清宫。--宋·沈括《梦溪笔谈》", "example": null}, {"def": "造左公第。--清·方苞《左忠毅公逸事》", "example": null}, {"def": "径造袁所寓之法华寺。--清·梁启超《谭嗣同传》", "example": null}, {"def": "又如造劫历世(佛教语。来到人世间经历一番苦难生活);造历幻缘(佛教语。去到", "example": null}, {"def": "造zào", "example": null}, {"def": "⒈做，制作制～。～纸。～林。～句。～飞船。", "example": null}, {"def": "⒉建设营～。", "example": null}, {"def": "⒊编，虚构～谣。捏～。编～。", "example": null}, {"def": "⒋成就，培养～诣。深～。", "example": null}, {"def": "⒌去，往，到～访。登峰～极。", "example": null}, {"def": "⒍两方面，法院指诉讼的两方两～。甲～。乙～。", "example": null}, {"def": "⒎时世末～（末世）。", "example": null}, {"def": "⒏次，指农作物种植到收获的次数一年两～大丰收。", "example": null}, {"def": "⒐", "example": null}, {"def": "①仓卒，匆忙～次之间。", "example": null}, {"def": "②轻率，鲁莽不可～次。", "example": null}, {"def": "⒑", "example": null}, {"def": "①构成。", "example": null}, {"def": "②致使。", "example": null}, {"def": "③培养造就。", "example": null}, {"def": "⒒", "example": null}, {"def": "①培养使有成就。", "example": null}, {"def": "②成就。", "example": null}, {"def": "⒓", "example": null}, {"def": "①进行反抗。", "example": null}, {"def": "②发动叛乱。", "example": null}]','chinese-xinhua','0'),
