('2101143297027215398','噪','1','zào','口','16',NULL,'[{"def": "噪", "example": null}, {"def": "(形声)", "example": null}, {"def": "同本义", "example": null}, {"def": "又如噪呤(鸣叫);噪天(鸟名。即云雀)", "example": null}, {"def": "大声喧嚷", "example": null}, {"def": "以毁谤言之,贞良见妒,高奇见噪。--汉·王充《论衡》", "example": null}, {"def": "又如噪逐(叫骂驱逐);噪儿巴喝(方言。哇啦哇啦乱嚷);噪呼(喧哗叫嚷);噪喧(喧闹);噪刺刺(沸沸扬扬);噪嘴(多嘴);噪噪(乱嚷嚷;议论纷纷);噪噪切切(弦乐器大弦和小弦发", "example": null}, {"def": "出不同的声音)", "example": null}, {"def": "噪zào", "example": null}, {"def": "⒈许多虫或鸟乱叫蝉～。柴门鸟雀～。", "example": null}, {"def": "⒉杂乱、烦扰的声音～音。", "example": null}, {"def": "⒊喧哗，很多人一起叫嚷吵闹呼～。鼓～奔走。", "example": null}]','chinese-xinhua','0'),
('2101143297027215399','燥','1','zào','火','17',NULL,'[{"def": "燥〈名〉 sao", "example": null}, {"def": "剁细的肉", "example": null}, {"def": "燥 〈形〉", "example": null}, {"def": "快", "example": null}, {"def": "从此以后,匡超人的肉和豆腐都卖得生意又燥,不到日中就卖完了,把钱拿来家伴着父亲。--《儒林外史》", "example": null}, {"def": "燥  zao", "example": null}, {"def": "(形声)", "example": null}, {"def": "同本义(没有水分或水分很少)", "example": null}, {"def": "燥,干也。--《说文》", "example": null}, {"def": "火就燥。--《易·文言传》", "example": null}, {"def": "燥,焦也。--《释名》", "example": null}, {"def": "唇焦口燥呼不得。--唐·杜甫《茅屋为秋风所破歌》", "example": null}, {"def": "燥荻枯柴。--《资治通鉴》", "example": null}, {"def": "又如燥吻(干燥的嘴唇);燥坼(干燥坼裂);燥劲(干燥强劲);燥刚(干燥刚劲);燥气(干燥之气);燥急(干渴得利害);燥渴", "example": null}, {"def": "燥zào干～热。干～。", "example": null}, {"def": "燥sào 1.方言。快速。 2.害臊。参见\\"燥不搭\\"。 3.见\\"燥子\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297027215400','趮','1','zào','','17',NULL,'[{"def": "趮zào 1.同\\"躁\\"。急躁。 2.因疾速而左右摆动。", "example": null}]','chinese-xinhua','0'),
('2101143297027215401','躁','1','zào','足','20',NULL,'[{"def": "躁", "example": null}, {"def": "(形声)", "example": null}, {"def": "同本义", "example": null}, {"def": "躁,疾也。--《说文》。字亦作躁。", "example": null}, {"def": "羽杀则躁。--《考工记·矢人》。按,今字作躁。", "example": null}, {"def": "躁者不静。--《管子·心术》", "example": null}, {"def": "巽为躁卦。--《易·说卦》", "example": null}, {"def": "震为决躁。", "example": null}, {"def": "处必掩身毋躁。--《礼记·月令》。注动也。”", "example": null}, {"def": "狗赤股而躁。--《礼记·内则》。注举动急疾。”", "example": null}, {"def": "言未及之而言谓之躁。--《论语》。郑注不安静也。”", "example": null}, {"def": "重为轻根,静为躁君。--《韩非子·喻老》", "example": null}, {"def": "又如躁暴(暴躁;急躁);躁妄(急躁轻率);躁忿(急躁易怒);躁扰(急躁好动);躁静(急躁与宁静);躁率(急躁轻率)", "example": null}, {"def": "急疾;迅", "example": null}, {"def": "躁zào性急，不冷静急～。暴～。戒骄戒～。", "example": null}]','chinese-xinhua','0'),
('2101143297027215402','讁','1','zào','','17',NULL,'[{"def": "讁zào喧哗，很多人一起叫嚷吵闹呼～。鼓～奔走。", "example": null}]','chinese-xinhua','0'),
