('2101143297027215470','札','1','zhá','木','5',NULL,'[{"def": "札", "example": null}, {"def": "(形声。从木,札声。本义古代用来写字的小木片)", "example": null}, {"def": "同本义", "example": null}, {"def": "札,牒也。--《说文》", "example": null}, {"def": "皆一札十行,细书成文。--《后汉书·循吏传》", "example": null}, {"def": "卿有札书。--《汉书·郊祀志上》", "example": null}, {"def": "上令尚书给笔札。--《汉书·司马相如传上》", "example": null}, {"def": "上许,令尚书给笔札。--《史记·司马相如列传》", "example": null}, {"def": "郡国诸户口黄籍,籍皆用一尺二寸札,已在官役者载名。--《太平御览》", "example": null}, {"def": "古代公文的泛称", "example": null}, {"def": ");札书(牒,公文);", "example": null}, {"def": "札zhá", "example": null}, {"def": "⒈信件信～。书～。来～收阅。", "example": null}, {"def": "⒉〈古〉写字用的木片。", "example": null}, {"def": "⒊札子，〈古〉一种公文奏～。论事～子。", "example": null}, {"def": "札zhā 1.扎;刺。 2.驻扎。 3.站立。 4.见\\"札客\\"。 5.见\\"札地\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297027215471','轧','1','zhá','车','5',NULL,'[{"def": "轧  ga", "example": null}, {"def": "挤入;拥挤", "example": null}, {"def": "结交", "example": null}, {"def": "核查", "example": null}, {"def": "象声词。如轧拉(形容物体摩擦或受压力后而发出的声音)", "example": null}, {"def": "轧  ya", "example": null}, {"def": "(形声。从车,本义辗压)", "example": null}, {"def": "同本义", "example": null}, {"def": "轧,辗也。--《说文》", "example": null}, {"def": "罪小者轧。--《史记·匈奴传》『书注辗辗其骨节。若今之压踝者。”", "example": null}, {"def": "鳃鳃然常恐天下之一合而轧己也。--《汉书·刑法志》", "example": null}, {"def": "又如把路面轧一下", "example": null}, {"def": "排挤,倾轧", "example": null}, {"def": "轧gá", "example": null}, {"def": "⒈〈方〉", "example": null}, {"def": "①挤，拥挤不要～。", "example": null}, {"def": "②结交～朋友。", "example": null}, {"def": "③核算，查对～清帐目。", "example": null}, {"def": "⒉见yà、zhá。", "example": null}, {"def": "轧yà", "example": null}, {"def": "⒈排挤，碾压倾～。～棉花。～马路。", "example": null}, {"def": "轧zhá", "example": null}, {"def": "⒈压～辊。～钢机。", "example": null}]','chinese-xinhua','0'),
('2101143297027215472','闸','1','zhá','门','8',NULL,'[{"def": "闸", "example": null}, {"def": "(形声。从门,甲声。本义开闭閠(根据枢转轧轧有声而造字)", "example": null}, {"def": "水闸", "example": null}, {"def": "完我岸闸,千夫奏功。--宋·苏轼《祭英烈王祝文》", "example": null}, {"def": "又如闸牌子(河道上管水闸的人);开闸;船闸;涵闸(涵洞和水闸的总称);闸头(水闸)", "example": null}, {"def": "制动器的通称", "example": null}, {"def": "电闸,在电路上用来接通、断开或转换电流的装置", "example": null}, {"def": "闸", "example": null}, {"def": "把水截住,关闸。引申为拦", "example": null}, {"def": "如水之流,夜间则闸得许多水住在这里,这一池水便满。--《朱子语类》", "example": null}, {"def": "查", "example": null}, {"def": "闸zhá", "example": null}, {"def": "⒈拦阻水流的建筑物，可随时开关，调节水量～门。排洪～。", "example": null}, {"def": "⒉使机器减速或停运的制动器车～。电～。", "example": null}, {"def": "⒊铁路上的转辙器。", "example": null}]','chinese-xinhua','0'),
