('2101143297031409664','诈','1','zhà','讠','7',NULL,'[{"def": "诈", "example": null}, {"def": "(形声。从言,乍声。从言,说明与言论有关。本义欺骗)", "example": null}, {"def": "同本义", "example": null}, {"def": "诈,欺也。--《说文》", "example": null}, {"def": "诈,伪也。--《尔雅》", "example": null}, {"def": "匿行曰诈。--《荀子·脩身》", "example": null}, {"def": "有掎挈伺诈。--《荀子·富国》", "example": null}, {"def": "繁战之君,不足于诈。--《吕氏春秋·义赏》", "example": null}, {"def": "无功伐而求荣富,诈也。--《吕氏春秋·务本》", "example": null}, {"def": "相如度秦王特以诈佯为予赵城,实不可得。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "禽兽之变诈。--《聊斋志异·狼三则》", "example": null}, {"def": "又如诈端(讹诈的理由);诈掯(敲诈勒索);诈哄(欺骗);诈伪(欺骗);诈力(诈术与暴力);诈人(专务诈欺作伪的人)", "example": null}, {"def": "假装;冒充", "example": null}, {"def": "诈zhà", "example": null}, {"def": "⒈欺骗～骗。欺～。他被～。～语（骗人的话）。", "example": null}, {"def": "⒉假装～败。～病。～降。", "example": null}]','chinese-xinhua','0'),
('2101143297031409665','咤','1','zhà','口','9',NULL,'[{"def": "咤", "example": null}, {"def": "诧异;惊奇", "example": null}, {"def": "那怪看得眼咤,小龙丢了花字,望妖精劈一刀来。--《西游记》", "example": null}, {"def": "zha", "example": null}, {"def": "吒", "example": null}, {"def": "(形声。从口,宅声。本义吃东西时口中作声)", "example": null}, {"def": "同本义", "example": null}, {"def": "毋咤食。--《礼记·曲礼上》", "example": null}, {"def": "痛惜", "example": null}, {"def": "痛惜曰咤也。--《一切经音义》引《通俗文》", "example": null}, {"def": "怒吼", "example": null}, {"def": "那行者一生性急, 那里容得, 大咤一声, 现了本相。--《西游记》", "example": null}, {"def": "又如咤叱(叱咤,怒斥);咤叱喑鸣(厉声怒喝)", "example": null}, {"def": "慨叹,叹息声", "example": null}, {"def": "哀咤良久。--唐·李朝威《柳毅传》", "example": null}, {"def": "咤（吒）zhà", "example": null}, {"def": "⒈怒斥，大声嚷叱～。", "example": null}, {"def": "咤zhā 1.见\\"哪咤\\"。", "example": null}, {"def": "咤chà 1.夸耀。 2.惊讶。", "example": null}]','chinese-xinhua','0'),
('2101143297031409666','乍','1','zhà','丿','5',NULL,'[{"def": "乍", "example": null}, {"def": "(会意。小篆字形,从亡从一。本义忽然)", "example": null}, {"def": "同本义", "example": null}, {"def": "乍,暂也。--《广雅》", "example": null}, {"def": "今人乍见孺子。--《孟子》", "example": null}, {"def": "银瓶乍破。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "雷霆乍惊。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如离乍(分离很骤然);乍乍(忽然);江上渔火乍明乍灭;乍冷乍热,天气很不正常", "example": null}, {"def": "刚;才", "example": null}, {"def": "波色乍明。--明·袁宏道《满井游记》", "example": null}, {"def": "乍出于匣。", "example": null}, {"def": "又如春寒乍暖,又下起了毛毛细雨;大雨乍停,球赛又继续进行", "example": null}, {"def": "初;开始", "example": null}, {"def": "韶光明媚,乍晴转暖清明后。--柳永《笛家弄词》", "example": null}, {"def": "又如初来乍到,", "example": null}, {"def": "乍zhà", "example": null}, {"def": "⒈初，刚，才～到。～一想。", "example": null}, {"def": "⒉忽然～雨～晴。", "example": null}, {"def": "乍zǎ 1.怎，怎么。", "example": null}, {"def": "乍zhā 1.参见\\"乍呼\\"。", "example": null}, {"def": "乍zuò 1.从事某种活动。 2.斮，砍击。", "example": null}]','chinese-xinhua','0'),
