('2101143297031409693','齩','1','zhā','鼻','25',NULL,'[{"def": "齩", "example": null}, {"def": "鼻子上的红斑,就是酒渣鼻的渣", "example": null}, {"def": "齩（皻）zhā鼻（酒糟鼻）上的红色小疮粒。", "example": null}]','chinese-xinhua','0'),
('2101143297031409694','债','1','zhai','亻','10',NULL,'[{"def": "债", "example": null}, {"def": "(形声。从人,责声。本作责”,债”为后起字。本义欠别人的钱财)", "example": null}, {"def": "同本义", "example": null}, {"def": "债,债负也。--《说文新附》", "example": null}, {"def": "于是有买田宅,鬻子孙,以偿债者矣。--《汉书·论贵粟疏》", "example": null}, {"def": "又如债壳子(负了一身债的穷官);债赖(债权人否认借债给他人);债累(负债;债务);债桩(比喻被债务包围的人);内债(国家向本国公民借的债);外债(国家向外国借的债);公债", "example": null}, {"def": "(国家向公民或向外国借的债);举债(借债);背债(欠债)", "example": null}, {"def": "喻指应兑现的事情或所造成的损失", "example": null}, {"def": "债", "example": null}, {"def": "借贷", "example": null}, {"def": "债车受载。--", "example": null}, {"def": "债zhài欠着的钱财～务。借～。公～。还～。", "example": null}]','chinese-xinhua','0'),
('2101143297031409695','砦','1','zhai','石','11',NULL,'[{"def": "砦", "example": null}, {"def": "同寨”。守卫用的栅栏、营垒", "example": null}, {"def": "今河东西不从敌国而保山砦者,不知其几。--《宋史·宗泽传》", "example": null}, {"def": "姓", "example": null}, {"def": "砦zhài 1.防卫用的栅栏。引申为营垒。 2.安营扎寨。 3.村寨。由营垒发展而成的居民点。 4.通\\"訾\\"。参见\\"砦嗸\\"。 5.通\\"呰\\"。参见\\"砦窳\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297031409696','寨','1','zhai','宀','14',NULL,'[{"def": "寨", "example": null}, {"def": "(形声。从木,赛省声。本义防卫所用的木栅)", "example": null}, {"def": "同本义", "example": null}, {"def": "敌军已近寨。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "寨中人踡伏。", "example": null}, {"def": "借寨墙为蔽。", "example": null}, {"def": "多指四面环围的驻军处,营垒", "example": null}, {"def": "时巴山陈定亦拥兵立寨。--《陈书》", "example": null}, {"def": "又如寨落(有栅栏或围墙的村落);寨垛(寨墙上的垛口);寨屋(营房)", "example": null}, {"def": "寨子,村庄", "example": null}, {"def": "寨（砦）zhài", "example": null}, {"def": "⒈防卫用的栅栏鹿～（军用障碍物。古多用竹尖，现多用铁蒺藜等）。", "example": null}, {"def": "⒉〈古〉指军营安营扎～。", "example": null}, {"def": "⒊村子，村庄村～。李家～。九～沟风景，誉满全球。", "example": null}]','chinese-xinhua','0'),
('2101143297031409697','瘵','1','zhai','疒','16',NULL,'[{"def": "瘵", "example": null}, {"def": "病。多指痨病", "example": null}, {"def": "念其服劳之久,悯其撄瘵之深。--宋·王安石《乞退表》", "example": null}, {"def": "又如瘵鬼(因患痨病而死者);瘵疾(疫病。亦指痨病)", "example": null}, {"def": "疾苦;困顿", "example": null}, {"def": "邦靡有定,士民其瘵。--《诗·大雅·瞻仰》。又如瘵瘼(凋敝,衰败)", "example": null}, {"def": "瘵zhài病，多指肺结核病痨～。", "example": null}]','chinese-xinhua','0'),
('2101143297031409698','宅','1','zhái','宀','6',NULL,'[{"def": "宅", "example": null}, {"def": "(形声。从宀,乇声。本义住所;住处)", "example": null}, {"def": "同本义", "example": null}, {"def": "宅,所托居也。--小徐本《说文》", "example": null}, {"def": "上以厚,下安宅。--《易·象传》", "example": null}, {"def": "五亩之宅。--《孟子·梁惠王上》", "example": null}, {"def": "便利田宅。--汉·刘向《列女传》", "example": null}, {"def": "方宅十余亩。--晋·陶渊明《归园田居》", "example": null}, {"def": "岐王宅里寻常见。--唐·杜甫《江南逢李龟年》", "example": null}, {"def": "住近湓江地低湿,黄芦苦竹绕宅生。--白居易《琵琶行》", "example": null}, {"def": "又如卜宅(卜择住处建都地或葬地);宅司(宅子;宅院);宅券(房契);宅相(住宅风水之相);宅神(住宅里的神鬼);宅屋(住房)", "example": null}, {"def": "家,常指大家族的家", "example": null}, {"def": "当日宁荣两宅,人口也极多,如", "example": null}, {"def": "宅zhái住宅，住所住～区。", "example": null}, {"def": "宅zhà 1.奠酒爵。", "example": null}, {"def": "宅chè 1.裂开。一说为草木的根。", "example": null}]','chinese-xinhua','0'),
('2101143297031409699','翟','1','zhái','羽','14',NULL,'[{"def": "翟  di", "example": null}, {"def": "长尾的野鸡", "example": null}, {"def": "翟羽", "example": null}, {"def": "舞人十六,执羽翟,以四为列。--《新唐书》", "example": null}, {"def": "姓", "example": null}, {"def": "翟  zhai", "example": null}, {"def": "姓", "example": null}, {"def": "翟 dí〈古〉长尾野鸡。又见zhái。", "example": null}, {"def": "翟zhái", "example": null}, {"def": "⒈姓。", "example": null}]','chinese-xinhua','0'),
('2101143297031409700','窄','1','zhǎi','穴','10',NULL,'[{"def": "窄", "example": null}, {"def": "(形声。从穴,乍声。本义狭小)", "example": null}, {"def": "同本义", "example": null}, {"def": "窄,陿也。--《广雅》", "example": null}, {"def": "齐室逼窄。--《华山亭碑》", "example": null}, {"def": "素标插人头,前途渐就窄。--陶潜《杂诗》", "example": null}, {"def": "又如窄索(窄小);窄溜溜(形容窄);窄逼逼(形容非常狭窄);窄鳖鳖(非常狭窄的样子);窄逼(狭隘;狭小);窄窄别别(形容非常狭隘);窄束(狭隘);窄仄(狭隘);窄生生(形容狭小)", "example": null}, {"def": ";窄陋(狭小简陋);窄窄(狭小,狭窄)", "example": null}, {"def": "短缺;生活不宽裕", "example": null}, {"def": "乱世诛求急,黎民糠窄。--唐·杜甫《驱竖子摘苍耳》", "example": null}, {"def": "又如窄巴", "example": null}, {"def": "紧迫;困难。也指窘迫", "example": null}, {"def": "窄zhǎi", "example": null}, {"def": "⒈横的距离小，跟\\"宽\\"相对狭～。～小。～路。〈引〉气量小，心胸不开阔他是个～心眼的人。", "example": null}, {"def": "⒉生活不宽裕～日子，要～打～用。富了，还得当～日子过。", "example": null}]','chinese-xinhua','0'),
