('2101143297031409709','战','1','zhàn','戈','9',NULL,'[{"def": "战", "example": null}, {"def": "(形声。从戈,单(占)声。本义作战,打仗)", "example": null}, {"def": "同本义", "example": null}, {"def": "战,斗也。--《说文》", "example": null}, {"def": "皆陈曰战。--《左传·庄公十一年》", "example": null}, {"def": "春秋敌者言战。--《公羊传·庄公三十年》", "example": null}, {"def": "忠之属也,可以一战。战则请从。--《左传·庄公十年》", "example": null}, {"def": "将军百战死。--《乐府诗集·木兰诗》", "example": null}, {"def": "脱我战时袍。", "example": null}, {"def": "挟矢以助战。--明·魏禧《大铁椎传》", "example": null}, {"def": "技击利巷战。--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "普法交战图。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "时北兵已迫修门外,战、守、迁皆不及施。--宋·文天祥《指南录后序》", "example": null}, {"def": "又如征战(出征作战);战阀(战功);战垒(", "example": null}, {"def": "战（戰）zhàn", "example": null}, {"def": "⒈打仗～争。《地道～》。《地雷～》。保家卫国，英勇善～。", "example": null}, {"def": "⒉发抖，极其害怕～栗。打～‘～。胆～心惊。～ ～兢兢。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "①指导战争全局的计划和策略～略上要藐视敌人。", "example": null}, {"def": "②有关战争全局的～略物资。", "example": null}, {"def": "③〈喻〉决定全局的策略～略措施。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "①作战双方的接触线。", "example": null}, {"def": "②指某项工作系统或方面教育～线。思想～线。", "example": null}, {"def": "⒑", "example": null}]','chinese-xinhua','0'),
('2101143297031409710','栈','1','zhàn','木','9',NULL,'[{"def": "栈", "example": null}, {"def": "(形声。从木,戔声。本义牲口棚)", "example": null}, {"def": "同本义", "example": null}, {"def": "栈,棚也。--《说文》。按,栅者,竖编之,棚者,横编之。", "example": null}, {"def": "埋之马栈之下。--《战国策·齐策》", "example": null}, {"def": "马栈最难。--《管子·小问》", "example": null}, {"def": "编之以皁栈。--《庄子·马蹄》。崔注木棚也。”", "example": null}, {"def": "毙于内栈。--颜延之《赭白马赋》", "example": null}, {"def": "驽马恋栈豆。--《晋书·宣帝纪》", "example": null}, {"def": "四墙其社,覆上栈下,示不得通。--《汉书》", "example": null}, {"def": "又如皂栈(马房中的栅栏和方格木条)", "example": null}, {"def": "古代用竹木条横排编成车箱的轻便车子", "example": null}, {"def": "栈,竹木之车曰栈。--《说文》", "example": null}, {"def": "有栈之车。--《诗·小雅·何草不黄》", "example": null}, {"def": "车乘栈车", "example": null}, {"def": "栈（棧）zhàn", "example": null}, {"def": "⒈关养牲畜的棚或栅栏羊～。", "example": null}, {"def": "⒉存放货物或供旅客住宿的地方货～。客～。", "example": null}, {"def": "⒊〈古〉在险峻绝壁的山上用竹木等架设的道路～道。", "example": null}, {"def": "⒋〈古〉竹木做成的车～车。", "example": null}, {"def": "栈zhǎn 1.古代乐器。小钟。", "example": null}, {"def": "栈chén 1.见\\"栈栈\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297031409711','站','1','zhàn','立','10',NULL,'[{"def": "站", "example": null}, {"def": "(形声。从立,占声。本义直立)", "example": null}, {"def": "站立,直立。以基本直立的姿势用双脚或一脚支撑自己", "example": null}, {"def": "凡射,或对贼、对把,站定观把子或贼人,不许看扣。--明·戚继光《纪效新书》", "example": null}, {"def": "又如站门子(妓女站在门口招人或接客);站眙(久立而不行走);站堂(旧时衙门开审时,差役排列在公堂上以应差);站柜台(指营业员在商品柜台内侧卖货)", "example": null}, {"def": "停止前进;直立不动", "example": null}, {"def": "在一场争论中从一方转到另一方", "example": null}, {"def": "站", "example": null}, {"def": "蒙古语的音译。驿站,古时传递军政文书的人中途换马、食宿或转递之所", "example": null}, {"def": "站zhàn", "example": null}, {"def": "⒈立，定～立。～岗。～稳立场。中国人民～起来了。", "example": null}, {"def": "⒉路途停留或转运的地方汽车～。正点到～。", "example": null}, {"def": "⒊某些机构名称医疗～。供应～。联络～。", "example": null}, {"def": "⒋停，停止不怕慢，就怕～。", "example": null}]','chinese-xinhua','0'),
