('2101143297031409725','展','1','zhǎn','尸','10',NULL,'[{"def": "展", "example": null}, {"def": "(形声。小篆字形假卧的人形。从尸,与人体动作有关。本义转动)", "example": null}, {"def": "同本义", "example": null}, {"def": "展,转也。--《说文》", "example": null}, {"def": "展,转,反侧也。--《广雅》", "example": null}, {"def": "展转伏枕。--《韩诗泽陂》", "example": null}, {"def": "忧心展转。--《楚辞·惜贤》", "example": null}, {"def": "展眼已是夏末秋初。--《红楼梦》", "example": null}, {"def": "又如展动(翻动);展轮(转轮。多指启程出行);展思(展转思念)", "example": null}, {"def": "舒展;伸展", "example": null}, {"def": "侈必展。--《国语·晋语》", "example": null}, {"def": "盗跖大怒,两展其足,案剑瞋目。--《庄子·盗跖》", "example": null}, {"def": "又如展放(舒展);展眉舒眼(眼、眉舒展开来。形容称心如意而高兴的样子);展舒(舒展);展怀(舒怀,开怀)", "example": null}, {"def": "张开;展现或进入视野", "example": null}, {"def": "展zhǎn", "example": null}, {"def": "⒈伸开，舒张开～开。～卷。～眉。～望。伸～。扩～。", "example": null}, {"def": "⒉发挥施～。一筹莫～。", "example": null}, {"def": "⒊陈，陈列～览。画～。", "example": null}, {"def": "⒋推迟，放宽～期。～限。", "example": null}]','chinese-xinhua','0'),
('2101143297031409726','盏','1','zhǎn','皿','10',NULL,'[{"def": "盏", "example": null}, {"def": "(形声。从皿,戔声。从皿,表示与器皿有关。本义浅而小的杯子) 同本义", "example": null}, {"def": "横飞玉盏家山晓,远蹀金珂塞草春。--唐·韩愈《酬振武胡十二丈》诗", "example": null}, {"def": "又如把盏(端着酒杯敬客);盏斝(泛指酒杯)", "example": null}, {"def": "盏", "example": null}, {"def": "酒、茶或灯的计量单位", "example": null}, {"def": "那妇人拿起一盏茶来,把帕子去茶盅口边一抹,双手递与和尚。--《水浒传》", "example": null}, {"def": "又如红灯一盏", "example": null}, {"def": "盏（眐）zhǎn", "example": null}, {"def": "⒈浅而小的杯子酒～。茶～。", "example": null}, {"def": "⒉量词（多指酒或灯）两～酒。三～灯。", "example": null}]','chinese-xinhua','0'),
('2101143297031409727','崭','1','zhǎn','山','11',NULL,'[{"def": "崭", "example": null}, {"def": "(形声。从山,斩声。双音词崭岩”。本义山高而险峻的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "崭岩嵾嵯。--《史记·司马相如传》", "example": null}, {"def": "豨谷崭岩兮水曾波。--《楚辞·招隐士》", "example": null}, {"def": "仰视所登之处,崭然在云汉。--《徐霞客游记》", "example": null}, {"def": "又如崭岩(险峻);崭崒(陡峭高峻);崭绝(险峻陡峭的样子;事物超群不寻常);崭阢(高峻);崭崖(陡峻的山崖);崭露头角(比喻显示出突出的才能和本领);崭崭(高峻;突出)", "example": null}, {"def": "崭", "example": null}, {"def": "程度副词≤,特别", "example": null}, {"def": "崭zhǎn高峻，突出～岩。～新。～露头角。", "example": null}, {"def": "崭chán 1.见\\"崭２岩\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297031409728','搌','1','zhǎn','扌','13',NULL,'[{"def": "搌", "example": null}, {"def": "拭抹", "example": null}, {"def": "如施之如彩画之上者,以乱线揩搌用之。--宋·李诫《营造法式》", "example": null}, {"def": "又如纸上落了一滴墨,快拿收墨纸搌一搌吧", "example": null}, {"def": "搌zhǎn擦抹，轻轻地按压～布。～一～纸上的墨汁。", "example": null}]','chinese-xinhua','0'),
