('2101143297031409749','粘','1','zhān','米','11',NULL,'[{"def": "粘〈形〉 nian", "example": null}, {"def": "(形声。从米,占声。本义具有粘性) 同本义", "example": null}, {"def": "厚而带粘性);粘粘涎涎(形容言语不简要)", "example": null}, {"def": "粘  zhan", "example": null}, {"def": "粘的东西互相连接或附着在别的东西上", "example": null}, {"def": "超脱)", "example": null}, {"def": "粘（黏）nián", "example": null}, {"def": "⒈像胶水或浆糊的性质～液。～米。发～。～性。", "example": null}, {"def": "粘zhān", "example": null}, {"def": "⒈贴，附着，胶合～贴。～标语。糖～在牙齿上。～在一块儿。", "example": null}]','chinese-xinhua','0'),
('2101143297031409750','嶂','1','zhànɡ','山','14',NULL,'[{"def": "嶂", "example": null}, {"def": "(形声。从山,章声。本义高险的山,如屏障的山峰)同本义", "example": null}, {"def": "嶂,峰嶂。--《广韵》", "example": null}, {"def": "嶂,山峰如屏障也。--《增韵》", "example": null}, {"def": "千嶂里,长烟落日孤城闭。--宋·范仲淹《渔家傲》", "example": null}, {"def": "又如嶂表(山外);嶂气", "example": null}, {"def": "嶂zhàng高耸险峻如同屏障的山峰重岩叠～。", "example": null}]','chinese-xinhua','0'),
('2101143297031409751','幛','1','zhànɡ','巾','14',NULL,'[{"def": "幛", "example": null}, {"def": "(形声。从巾,章声。巾,丝麻织品。本义旧时用布帛一副上面题字,作为庆吊的礼物)同本义", "example": null}, {"def": "condolences by friends]", "example": null}, {"def": "谨具祭幛一悬。--曾国藩《致相润芝中丞书》", "example": null}, {"def": "又如寿幛;挽幛;喜幛", "example": null}, {"def": "幛zhàng题有词句的整幅绸布，用作庆贺或吊唁的礼物贺～。挽～。", "example": null}]','chinese-xinhua','0'),
