('2101143297031409765','掌','1','zhǎnɡ','手','12',NULL,'[{"def": "掌", "example": null}, {"def": "本义手掌,手心", "example": null}, {"def": "掌,手中也。--《说文》", "example": null}, {"def": "指其掌。--《论语·八佾》", "example": null}, {"def": "易于反掌,安于泰山。--枚乘《谏吴王书》", "example": null}, {"def": "又如掌上(手掌之上。极言容易);掌上观纹(比喻极其容易,毫不费力);掌文(手掌纹路所呈现的近乎文字的形状)", "example": null}, {"def": "脚的底部", "example": null}, {"def": "四足动物带爪的脚", "example": null}, {"def": "熊掌,亦我所欲也。--《孟子·告子上》", "example": null}, {"def": "脚", "example": null}, {"def": "掌状物", "example": null}, {"def": "钉在马、驴、骡等蹄子底下的蹄铁", "example": null}, {"def": "又指钉或缝在鞋底后部的补钉", "example": null}, {"def": "掌zhǎng", "example": null}, {"def": "⒈手心，手的里面手～。巴～。拍～。易如反～。", "example": null}, {"def": "⒉脚底脚～。鸭～。熊～。", "example": null}, {"def": "⒊用手掌打～颊。～嘴。", "example": null}, {"def": "⒋把握，拿稳，主管～握。～管。～权。～舵。", "example": null}, {"def": "⒌钉在鞋底前后的皮、胶片、铁片等钉块鞋～儿。", "example": null}, {"def": "⒍钉在马、骡等蹄下的铁片马～。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}]','chinese-xinhua','0'),
('2101143297031409766','仉','1','zhǎnɡ','亻','4',NULL,'[{"def": "仉", "example": null}, {"def": "同掌”", "example": null}, {"def": "仉,古掌字。--《正字通》", "example": null}, {"def": "姓", "example": null}, {"def": "仉zhǎng姓。", "example": null}]','chinese-xinhua','0'),
('2101143297031409767','涨','1','zhǎnɡ','氵','10',NULL,'[{"def": "涨", "example": null}, {"def": "(形声。从水,张声。本义水上升)", "example": null}, {"def": "同本义", "example": null}, {"def": "江涨柴门外,儿童报急流。--唐·杜甫《江涨》", "example": null}, {"def": "冰入春风涨御沟,上林花气欲飞浮。--宋·王安石《祥云》", "example": null}, {"def": "渭流涨腻,弃脂水也。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "又如涨滩(由于河水上涨,泥沙堆积成可供耕植的陆地);涨痕(涨水的痕迹);涨溢(水流上涨泛滥)", "example": null}, {"def": "增长;高出", "example": null}, {"def": "涨少霾草树。(霾埋。)--杜甫《缆船苦风戏题》", "example": null}, {"def": "又如高涨;价格涨落;涨级(提高工资级别)", "example": null}, {"def": "涨", "example": null}, {"def": "大水貌", "example": null}, {"def": "涨,大水。--《广韵》", "example": null}, {"def": "跻江津而起涨。--《文选·郭璞·江赋》。注涨,水大之", "example": null}, {"def": "涨（漲）zhǎng", "example": null}, {"def": "⒈水量增大，水面高起来河水暴～。水～船高。", "example": null}, {"def": "⒉增高，特指物价提高～沙埋草。惩治乱～价。", "example": null}, {"def": "涨（漲）zhàng", "example": null}, {"def": "⒈体积增大～大。黄豆泡～了。", "example": null}, {"def": "⒉弥漫，充满烟尘～天。脸～得绯红。", "example": null}, {"def": "⒊多出来～出五元钱。", "example": null}, {"def": "涨zhāng 1.涨海。", "example": null}]','chinese-xinhua','0'),
