('2101143297043992588','照','1','zhào','灬','13',NULL,'[{"def": "照", "example": null}, {"def": "(形声。从火,昭声,字亦作炤。本义明亮;光明) 同本义", "example": null}, {"def": "照,明也。--《说文》", "example": null}, {"def": "亦孔之炤。--《诗·小雅·正月》", "example": null}, {"def": "月出照兮。--《诗·陈风·月出》", "example": null}, {"def": "昔者十日并出,万物皆照。--《庄子》", "example": null}, {"def": "远近照闻。--《郯令景君阙铭》", "example": null}, {"def": "盛德炤明。--《谯敏碑》", "example": null}, {"def": "炤之以祸灾。--《荀子·修身》", "example": null}, {"def": "又如照彻(透明晶莹 );照澄(明朗清爽)炤”", "example": null}, {"def": "照", "example": null}, {"def": "照射,照耀", "example": null}, {"def": "照耀煇煌。--《淮南子·本经》", "example": null}, {"def": "日月递炤。--《荀子·天论》。注炤与照同。”", "example": null}, {"def": "指日月使延照兮。--《楚辞·灵怀》。注知也。", "example": null}, {"def": "照zhào", "example": null}, {"def": "⒈光线射着～射。～耀。特指日光夕～。", "example": null}, {"def": "⒉明～察明著（明著显明）。", "example": null}, {"def": "⒊对着镜子或其它反光的东西看～镜子。对着池水～一～。", "example": null}, {"def": "⒋拍摄，又指画像或相片～相。～片。风景～。", "example": null}, {"def": "⒌依据，按着～样。～例。依～。按～。", "example": null}, {"def": "⒍凭证执～。护～。车～。", "example": null}, {"def": "⒎关心，看顾～看。～料。～应。～顾。关～。", "example": null}, {"def": "⒏对比察看对～。查～。", "example": null}, {"def": "⒐通告，通知知～。", "example": null}, {"def": "⒑知晓，明白心～不宣。", "example": null}, {"def": "⒒对着，向着～侵略者开炮。～着这条大道走。", "example": null}, {"def": "⒓", "example": null}, {"def": "照zhāo 1.明;显。", "example": null}]','chinese-xinhua','0'),
('2101143297043992589','罩','1','zhào','罒','13',NULL,'[{"def": "罩", "example": null}, {"def": "(形声。从网,卓声。本义捕鱼的竹笼)", "example": null}, {"def": "同本义", "example": null}, {"def": "持罩入深水,金鳞大如手。--唐·温庭筠《罩鱼歌》", "example": null}, {"def": "又如罩罗(泛指捕鱼或捕鸟的竹器);罩笼(泛指捕鱼的竹器)", "example": null}, {"def": "捕鸟的竹笼或掩网", "example": null}, {"def": "弛罩出凤雏。--三国魏·曹植《孟车篇》", "example": null}, {"def": "又指养家禽的竹笼。如鸡罩", "example": null}, {"def": "罩形的器物", "example": null}, {"def": "罩", "example": null}, {"def": "覆盖;套在外面", "example": null}, {"def": "荷塘烟罩小斋虚,景物皆宜入画图。--唐·司空图《王官》", "example": null}, {"def": "又如罩笼(笼罩);罩褂(罩衣);罩袖(方言。套在衣袖外", "example": null}, {"def": "罩zhào", "example": null}, {"def": "⒈捕鱼用的竹笼，也指养鸡的笼子渔～。鸡～子。", "example": null}, {"def": "⒉覆盖或遮盖用的东西灯～子。口～儿。", "example": null}, {"def": "⒊覆盖在外的～衣。外～。", "example": null}, {"def": "⒋使用罩盖将剩菜～起来。", "example": null}]','chinese-xinhua','0'),
