('2101143297043992606','招','1','zhāo','扌','8',NULL,'[{"def": "招", "example": null}, {"def": "(会意。从手。召声,呼唤。本义打手势叫人来)", "example": null}, {"def": "同本义", "example": null}, {"def": "招,手呼也。--《说文》", "example": null}, {"def": "招者,召也。以手曰招,以言曰召。--《楚辞·招魂序》", "example": null}, {"def": "招樊哙出。--《史记·项羽本纪》", "example": null}, {"def": "登高而招,臂非加长也,而见者远。--《荀子·劝学》", "example": null}, {"def": "又如招迎(招呼使接待;招引迎接);招求(招引导求);招招(招呼的样子);招诱(招唤劝导);招护(招呼,关照);招应(招呼、理睬)", "example": null}, {"def": "招收;招募", "example": null}, {"def": "上招贤良。--《汉书·晁错传》", "example": null}, {"def": "又如招拔(召来并加以擢用);招用(招收使用);招军(招募士兵)", "example": null}, {"def": "邀请", "example": null}, {"def": "招前日宾客。--清·侯方", "example": null}, {"def": "招zhāo", "example": null}, {"def": "⒈用手势叫人来或向人致意～手即来。打～呼。", "example": null}, {"def": "⒉用公开的方式使人来～集。～收。～来。～贤。失物～领。〈引〉惹起，引来～致。～事。～引。～人笑话。谦受益，满～损。", "example": null}, {"def": "⒊承认所犯的罪过～供。～认。", "example": null}, {"def": "⒋故意炫耀自己，引人注目～摇撞骗。", "example": null}, {"def": "⒌技艺，手法绝～。花～。", "example": null}, {"def": "⒍", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "⒑", "example": null}, {"def": "①呼唤或问候、致意。", "example": null}, {"def": "②关照，扶助，照料。", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "招qiáo 1.举。 2.见\\"招木\\"。", "example": null}, {"def": "招sháo 1.通\\"韶\\"。传为舜乐。 2.见\\"招摇\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297043992607','昭','1','zhāo','日','9',NULL,'[{"def": "昭", "example": null}, {"def": "(形声。从日,召声。本义明亮)", "example": null}, {"def": "同本义", "example": null}, {"def": "昭,日明也。--《说文》", "example": null}, {"def": "倬彼云汉,昭回于天。--《诗·大雅·云汉》", "example": null}, {"def": "青春受谢,白日昭只。--《楚辞·大招》", "example": null}, {"def": "又如昭式(光明的法度);昭列(光明);昭衍(光明广布);昭亮(明亮);昭美(光明美好)", "example": null}, {"def": "彰明,显著", "example": null}, {"def": "所以昭炯戒。--清·薛福成《观巴黎油画记》", "example": null}, {"def": "又如昭升(显著地升闻);昭名(显著的声名);昭灼(明显;显著);昭明(显明;显著);昭速(明显地招引)", "example": null}, {"def": "昭", "example": null}, {"def": "光;亮光", "example": null}, {"def": "倬彼云汉,昭回于天。--《诗·大雅·云汉》", "example": null}, {"def": "又如昭回(晨辰光耀回转);昭耀(光耀);昭晳", "example": null}, {"def": "昭zhāo", "example": null}, {"def": "⒈明白，显著～然。～著。众目～彰。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "①明亮，光明。", "example": null}, {"def": "②明辨事理使人～ ～。", "example": null}, {"def": "昭zhào 1.照亮;照耀。", "example": null}]','chinese-xinhua','0'),
