('2101143297043992623','谪','1','zhé','讠','13',NULL,'[{"def": "谪", "example": null}, {"def": "(形声。从言,啻声。本义有意指摘,责备)", "example": null}, {"def": "同本义", "example": null}, {"def": "谪,罚也。--《说文》", "example": null}, {"def": "罚罪者曰谪。--《通俗文》", "example": null}, {"def": "国子谪我。--《左传·成公十七年》", "example": null}, {"def": "则自取谪于日月之灾。--《左传·昭公七年》", "example": null}, {"def": "善言无瑕谪。--《老子》", "example": null}, {"def": "穷年不相谪发。--《列子·力命》", "example": null}, {"def": "公会齐侯于泺,遂及文姜如齐。齐侯通焉。公谪之。--《左传·桓公十八年》", "example": null}, {"def": "室人交遍谪我。--《诗·邶风·北门》", "example": null}, {"def": "又如谪疑(指摘怀疑);谪我(谴责我);谪骂(责骂);谪谴(谴责);众口交谪", "example": null}, {"def": "降职并外放", "example": null}, {"def": "谪（讁）zhé", "example": null}, {"def": "⒈谴责，责罚众口交～。", "example": null}, {"def": "⒉封建时代指被贬职、被流放贬～。～逐。又指被罚罪的人～戍（被罚守边）之徒。", "example": null}]','chinese-xinhua','0'),
('2101143297043992624','磔','1','zhé','石','15',NULL,'[{"def": "磔", "example": null}, {"def": "古代祭祀时分裂牲畜肢体", "example": null}, {"def": "磔,辜也。--《说文》。从桀,石声。刳鸡胸、腹而张之,令其干枯不收。故从桀", "example": null}, {"def": "磔,张也。--《广雅》", "example": null}, {"def": "旁磔。--《礼记·月令》。注攘也。”", "example": null}, {"def": "祭风曰磔。--《尔雅》。李注以牲头蹄及皮破之以祭。”", "example": null}, {"def": "又如磔禳(磔攘。分裂牲体祭神以除不祥);磔鸡(旧历正月初一杀鸡挂门外以除不祥)。又指古代的一种酷刑。以车分裂人体", "example": null}, {"def": "吴子胥不磔姑苏东门外乎!--《荀子》。注车裂也。”", "example": null}, {"def": "又如磔裂(车裂人体;分割,割裂)。", "example": null}, {"def": "磔zhé", "example": null}, {"def": "⒈〈古〉祭祀时，分裂牲畜的肢体。〈引〉古时一种分裂肢体的酷刑。", "example": null}, {"def": "⒉汉字笔形的捺笔（猓。", "example": null}]','chinese-xinhua','0'),
('2101143297043992625','辙','1','zhé','车','16',NULL,'[{"def": "辙", "example": null}, {"def": "(形声。从车,徹省声。本义车迹,车轮碾过的痕迹)", "example": null}, {"def": "同本义", "example": null}, {"def": "下,视其辙;登,轼而望之。--《左传·庄公十年》", "example": null}, {"def": "晓驾炭车辗冰辙。--《卖炭翁》", "example": null}, {"def": "车子", "example": null}, {"def": "会使辙交驰,北邀当国去相见。--文天祥《指南录后序》", "example": null}, {"def": "又如辙印(车子行驶的痕迹);辙迹(车子行驶的痕迹)", "example": null}, {"def": "道路", "example": null}, {"def": "欲驾巾车归去,有豺狼当辙。--宋·胡铨《好事近》", "example": null}, {"def": "又如辙轨(轨道)", "example": null}, {"def": "途径;门路;路数,路子", "example": null}, {"def": "总会旧辙,创立新意。--隋·潘徽《韵纂序》", "example": null}, {"def": "又如没辙(没有办法)", "example": null}, {"def": "比喻错误或教训", "example": null}, {"def": "辙zhé", "example": null}, {"def": "⒈车轮碾压出的痕迹车～。如出一～。〈引〉车行的路线顺～行。莫抢～儿。又〈引〉杂曲、戏曲、歌词等所押的韵这段戏词合～。", "example": null}, {"def": "⒉〈方〉办法有～了。", "example": null}]','chinese-xinhua','0'),
