('2101143297048186981','征','1','zhēnɡ','彳','8',NULL,'[{"def": "征", "example": null}, {"def": "(形声。从彳,正声。从彳,表示与行走有关。甲骨文从彳,从足。本义到很远的地方去,远行)", "example": null}, {"def": "同本义", "example": null}, {"def": "徴,正行也。从辵,正声。或从彳。--《说文》", "example": null}, {"def": "征,行也。--《尔雅》", "example": null}, {"def": "壮于趾征凶。--《易·大壮》", "example": null}, {"def": "而月斯征。--《诗·小雅·小宛》", "example": null}, {"def": "先王卜征五年。--《左传·襄公十三年》。注谓巡狩征行。”", "example": null}, {"def": "肃肃宵征,夙夜在公。--《诗·召南·小星》", "example": null}, {"def": "愿为市鞍马,从此替爷征。--古乐府《木兰词》", "example": null}, {"def": "孤蓬万里征。--唐·李白《送友人》", "example": null}, {"def": "又如征鼙(征战的军鼓);征衣(行旅在在外的御寒衣服);征客(游子。同征人);征鸟", "example": null}, {"def": "征zhēng", "example": null}, {"def": "⒈远行～途。～帆（远航）。", "example": null}, {"def": "⒉讨伐，用武力制服～讨。～服。南～北战。", "example": null}, {"def": "⒊争夺，夺取力～。", "example": null}, {"def": "⒋召集，收用～召。～集。～收。～用。～税。～调。～兵。", "example": null}, {"def": "⒌找请，寻求～聘。～求。～文。～询意见。", "example": null}, {"def": "⒍证明，证验有～。实物可～。", "example": null}, {"def": "⒎现象，迹象～象。～兆。特～。", "example": null}, {"def": "征chéng 1.通\\"惩\\"。警戒;惩罚。 2.古地名。在今陕西省澄城县。", "example": null}, {"def": "征zhǐ 1.古五音之一。", "example": null}]','chinese-xinhua','0'),
('2101143297048186982','怔','1','zhēnɡ','忄','8',NULL,'[{"def": "怔", "example": null}, {"def": "(形声。从心,正声。本义惶恐不安的样子)", "example": null}, {"def": "同本义", "example": null}, {"def": "军书交驰,羽檄狎至,乃复怔忪如前。--《潜夫论》", "example": null}, {"def": "又如怔忡之症(心脏跳动加速、节律不整的病症);怔忡(惊恐不安;又指患者心脏跳动剧烈的一种症状)", "example": null}, {"def": "发愣,发呆", "example": null}, {"def": "那丫鬟倒发了个怔。--《红楼梦》", "example": null}, {"def": "又如怔怔(呆愣的样子)", "example": null}, {"def": "怔", "example": null}, {"def": "惊恐", "example": null}, {"def": "宝玉怔了半天,方想过", "example": null}, {"def": "怔zhēng", "example": null}, {"def": "⒈因吃惊而呆住的样子发～。", "example": null}, {"def": "⒉", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143297048186983','峥','1','zhēnɡ','山','9',NULL,'[{"def": "峥", "example": null}, {"def": "(形声。从山,争声。本义山高峻的样子)同本义", "example": null}, {"def": "于是赢粮潜行,上峥山,逾深溪。--《战国策》", "example": null}, {"def": "又如峥峥(高峻的样子)", "example": null}, {"def": "峥zhēng", "example": null}, {"def": "①山势高峻经三峡之～嵘。", "example": null}, {"def": "②不平常，不平凡～嵘岁月。", "example": null}, {"def": "③深险临～嵘不测之深。", "example": null}, {"def": "④一年快完～嵘岁又除。", "example": null}]','chinese-xinhua','0'),
('2101143297048186984','筝','1','zhēnɡ','竹','12',NULL,'[{"def": "筝", "example": null}, {"def": "(形声。从竹,争声。从竹,与乐器有关。本义拨弦乐器。形似瑟。筝是拨弦乐器,战国时已流行于秦地,故又称秦筝”) 同本义", "example": null}, {"def": "five and later thirteen strings]", "example": null}, {"def": "筝,鼓弦竹身乐也。--《说文》", "example": null}, {"def": "筝,五弦筑身乐也。--《御览》引《说文》", "example": null}, {"def": "挟人筝而弹纬。--《楚辞·愍命》。注小琴也。”", "example": null}, {"def": "竽瑟空侯琴筑筝。--《急就篇》", "example": null}, {"def": "又如筝人(弹筝的人);筝阮(秦筝与阮咸。古代的两种拨弦乐器);筝妓(弹筝的艺妓);筝柱(筝上的弦柱)", "example": null}, {"def": "筝zhēng", "example": null}, {"def": "⒈〈古〉一种弦乐器。", "example": null}, {"def": "⒉", "example": null}, {"def": "①又叫\\"纸鸢\\"。玩具的一种，牵线放飞在空中。", "example": null}, {"def": "②簷前铁马。", "example": null}]','chinese-xinhua','0'),
('2101143297048186985','徰','1','zhēnɡ','','8',NULL,'[{"def": "徰zhēng", "example": null}, {"def": "⒈古同征”。", "example": null}]','chinese-xinhua','0'),
('2101143297048186986','蒸','1','zhēnɡ','艹','13',NULL,'[{"def": "蒸", "example": null}, {"def": "(形声。焌声。本义麻秆)", "example": null}, {"def": "同本义", "example": null}, {"def": "蒸,析麻中干也。--《说文》。今俗谓之麻骨棓,古烛用之,故凡用麻干葭苇竹木为烛皆曰蒸。", "example": null}, {"def": "蒸,炬也。--《广雅》", "example": null}, {"def": "故云烛用蒸也。--《仪礼》疏", "example": null}, {"def": "细小的木柴", "example": null}, {"def": "共祭祀之薪蒸材木。--《周礼·委人》。注给炊及燎,粗者曰薪,细者曰蒸。”", "example": null}, {"def": "蒸间容蒸然者处下。--《管子·弟子职》。注细薪也。”", "example": null}, {"def": "以薪以蒸。--《诗·小雅》", "example": null}, {"def": "又如蒸薪(木柴)", "example": null}, {"def": "以麻秸、竹木制成的火炬", "example": null}, {"def": "中药炮制法之一", "example": null}, {"def": "蒸zhēng", "example": null}, {"def": "⒈细小的木柴冬伐薪～。", "example": null}, {"def": "⒉热气上升～发。水～气。", "example": null}, {"def": "⒊用蒸气使物变热、变熟～饭。～肉。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌通\\"焌\\"。众，多。", "example": null}]','chinese-xinhua','0'),
('2101143297048186987','睁','1','zhēnɡ','目','11',NULL,'[{"def": "睁", "example": null}, {"def": "(形声。从目,争声。本义张开眼睛)", "example": null}, {"def": "同本义", "example": null}, {"def": "武行者睁着双眼喝道你这厮好不晓道理。”--《水浒传》", "example": null}, {"def": "又如睁眼苫眉(装模作样);睁着眼做,合着眼受(比喻自作自受,心甘情愿);睁着眼跳黄河(比喻进退维谷,走上绝路)", "example": null}, {"def": "看,望;瞪", "example": null}, {"def": "偏偏他却转回程,不敢上前来冲道,闪在傍边仔细睁。--《天雨花》", "example": null}, {"def": "又如目睁口呆(惊惧得瞪大双眼,说不出话来);圆睁环眼(眼睛瞪得又大又圆);睁目张须(瞪起眼,胡须竖起。形容怒气冲天的神态)", "example": null}, {"def": "睁zhēng张开眼睛把眼睛～大。", "example": null}]','chinese-xinhua','0'),
('2101143297048186988','铮','1','zhēnɡ','钅','11',NULL,'[{"def": "铮", "example": null}, {"def": "(形声。从金,争声。本义金属相击声) 同本义", "example": null}, {"def": "铮,金声也。--《说文》", "example": null}, {"def": "冲牙铮鎗。--潘岳《藉田赋》。注玉声。”", "example": null}, {"def": "铮鐆然有京都声。--唐·白居易《琵琶行(并序)》", "example": null}, {"def": "繁华远容绮,铮鐆美金错。--王禹偁《酬种放征君一百韵》", "example": null}, {"def": "却好那一鞭打将下来,正在刀口上,铮地一声响,火光迸散。--《水浒传》", "example": null}, {"def": "又如铮枪(玉相撞击声);铮鐆(争枞。形容金属触击声)", "example": null}, {"def": "铮", "example": null}, {"def": "铮zhēng像声词（多指金属撞击声）～ ～作响。〈喻〉刚强铁～ ～。", "example": null}, {"def": "铮zhèng 1.方言。形容器物表面光亮耀眼。参见\\"铮亮\\"﹑\\"铮明互亮\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297048186989','焌','1','zhēnɡ','','9',NULL,'[{"def": "焌zhēng", "example": null}, {"def": "⒈用火烘烤，用热气蒸。", "example": null}, {"def": "⒉同\\"蒸\\"。众，多。", "example": null}]','chinese-xinhua','0'),
('2101143297048186990','脀','1','zhēnɡ','','8',NULL,'[{"def": "脀zhēng 1.以牲体纳入俎中。亦指已盛牲体之俎。", "example": null}]','chinese-xinhua','0'),
('2101143297048186991','嶒','1','zhēnɡ','山','15',NULL,'[{"def": "嶒--崚嶒”形容山高的样子。", "example": null}, {"def": "嶒céng 1.高。参见\\"嶒峻\\"﹑\\"嶒峨\\"﹑\\"嶒崭\\"。 2.见\\"嶒\\" 3.见\\"嶒崚\\"。 4.见\\"嶒嶝\\"。", "example": null}]','chinese-xinhua','0'),
