('2101143297052381197','摭','1','zhí','扌','14',NULL,'[{"def": "摭", "example": null}, {"def": "(形声。从手,庶声。字又作拓”,从手,石声。本义有选择的拾取)", "example": null}, {"def": "同本义", "example": null}, {"def": "拓,拾也。陈、宋语。--《说文》", "example": null}, {"def": "摭,取也。--《方言一》", "example": null}, {"def": "有顺而摭也。--《礼记·礼器》", "example": null}, {"def": "乃摭于鱼腊俎。--《仪礼·有司彻》", "example": null}, {"def": "犹拾遗于涂,摭弃于野。--《论衡·逢遇》", "example": null}, {"def": "摭紫贝,搏耆龟。--张衡《西京赋》", "example": null}, {"def": "选取,摘取", "example": null}, {"def": "摭我华而不食我实。--《法言·问明》", "example": null}, {"def": "往往摭《离骚》文而反之。--《汉书·扬雄传》", "example": null}, {"def": "又如摭华(采摘其文章辞藻);摭裂(采摘细碎);摭实(摘取事实;据实)", "example": null}, {"def": "挑剔;指摘", "example": null}, {"def": "摭zhí拾取，摘取～拾。～言。", "example": null}, {"def": "摭zhē 1.阻拦;掩饰。参见\\"摭说\\"﹑\\"摭拦\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297052381198','执','1','zhí','扌','6',NULL,'[{"def": "执", "example": null}, {"def": "(右边是人,手被铐住。本义拘捕;捉拿)", "example": null}, {"def": "同本义", "example": null}, {"def": "执,捕罪人也。--《说文》", "example": null}, {"def": "而妻妾执。--《礼记·檀弓》。注拘也。”", "example": null}, {"def": "使执连尹。--《吕氏春秋·慎行》。注囚也。”", "example": null}, {"def": "遂袭虞,灭之,执虞公。--《左传·僖公五年》", "example": null}, {"def": "被执至南门。--清·全祖望《梅花岭记》", "example": null}, {"def": "又如执命(讨命;索命);执讯(捉命并加以审问);执囚(拘捕囚禁);执问(拘留讯问);执狱(治狱;审判案件)", "example": null}, {"def": "拿;持", "example": null}, {"def": "执之用黄牛之革。--《易·遯》", "example": null}, {"def": "执君之乘车。--《礼记·少仪》。注执辔也。”", "example": null}, {"def": "执竞武王。--《诗·周颂·执竞》。笺执,持也。”", "example": null}, {"def": "执zhí", "example": null}, {"def": "①拿；持。", "example": null}, {"def": "②掌握；保持。", "example": null}, {"def": "③主管；掌管。", "example": null}, {"def": "④选取。", "example": null}, {"def": "⑤控制；驾驭。", "example": null}, {"def": "⑥执行。", "example": null}, {"def": "【执一】专心一志。", "example": null}, {"def": "【执友】志同道合的朋友。", "example": null}, {"def": "【执中】遵守中正之道，不偏不倚，无过于不及。采取中间的态度。", "example": null}, {"def": "【执引】古代送葬时的一种礼节，送葬的宾客须挽牵引柩车的绳索。", "example": null}, {"def": "【执业】持书诵习。业，书版。", "example": null}, {"def": "【执礼】守礼，遵行礼节。", "example": null}, {"def": "【执行】", "example": null}, {"def": "①把政策法令或计划等付诸实施。", "example": null}, {"def": "②法律用语。公安机关为实现以发生法律效力的判决和裁定所进行的活动。即对刑事案件的被告人执行刑罚，对应负民事责任的当事人责令其履行义务。", "example": null}, {"def": "【执拗】固执倔强。", "example": null}, {"def": "【执照】由有关行政机关发给的准许作某种行业的凭证。如施工执照；驾驶执照。", "example": null}, {"def": "【执迷】固执不悟。", "example": null}, {"def": "【执意】坚持自己的意见。", "example": null}, {"def": "执zhí", "example": null}, {"def": "①拘捕。", "example": null}, {"def": "②拿;持。", "example": null}, {"def": "③持守。", "example": null}, {"def": "④主持;掌管。", "example": null}, {"def": "⑤控制;统御。", "example": null}, {"def": "⑥操持;从事。", "example": null}, {"def": "⑦行;施行。", "example": null}, {"def": "⑧固执;坚持。", "example": null}, {"def": "⑨依据;遵照。", "example": null}, {"def": "⑩判断。", "example": null}]','chinese-xinhua','0'),
('2101143297052381199','侄','1','zhí','亻','8',NULL,'[{"def": "侄", "example": null}, {"def": "(侄为姪的俗字)弟兄或其他同辈男性亲属的子女", "example": null}, {"def": "姪,兄之女也。从女,至声。--《说文》", "example": null}, {"def": "女子谓兄弟之子为姪。--《尔雅》", "example": null}, {"def": "谓吾姑者,吾谓之姪。--《仪礼·丧服传》", "example": null}, {"def": "大夫不名世臣姪娣。--《礼记·曲礼》。疏姪是妻之兄女。”", "example": null}, {"def": "继室以其姪。--《左传·襄公二十三年》", "example": null}, {"def": "姪其从姑。--《左传·僖公十五年》", "example": null}, {"def": "则我皇妣大姜之姪。--《国语·周语》。注女子谓昆弟之子,男女皆曰姪。”朱按,受姪称者,男女皆可通,而称人姪者,必妇人也。男子称兄弟之子曰从子。", "example": null}, {"def": "侄其从姑。--《左传·僖公十五年》", "example": null}, {"def": "又如侄少爷(旧时", "example": null}, {"def": "侄（姪）zhí兄、弟或同辈亲戚的儿子（也指女儿）～子。表～。内～。～女。", "example": null}]','chinese-xinhua','0'),
