('2101143297056575504','絺','1','zhǐ','糹','13',NULL,'[{"def": "絺", "example": null}, {"def": "(形声。从糸,希声。本义细葛布)", "example": null}, {"def": "同本义", "example": null}, {"def": "絺,细葛也。--《说文》", "example": null}, {"def": "葛之精者曰絺。--《小尔雅》", "example": null}, {"def": "厥贡盐絺。--《书·禹贡》", "example": null}, {"def": "幂用锡若絺。--《仪礼·大射仪》", "example": null}, {"def": "袗絺络不入公门。--《礼记·曲礼》", "example": null}, {"def": "又如絺衣(细葛布衣);絺素(细白葛布);絺葛(葛布);絺纩(葛布与丝绵)。也指细葛布的衣服。如絺服(葛布制的衣服);絺冕(祭社稷五祀时所穿的礼服)", "example": null}, {"def": "古邑名。春秋时周地。在今河南省沁阳县西南", "example": null}, {"def": "絺chī一种用葛纤维织成的细布。", "example": null}]','chinese-xinhua','0'),
('2101143297056575505','茝','1','zhǐ','艹','10',NULL,'[{"def": "茝", "example": null}, {"def": "古书上说的一种香草,即白芷”", "example": null}, {"def": "山茝,藁本也。--《广雅》", "example": null}, {"def": "茝兰芳。--《汉书·礼乐志》。注即今白芷。”", "example": null}, {"def": "侧载臭茝。--《史记·礼书》", "example": null}, {"def": "沅有茝兮澧有兰。--《楚辞·九歌·湘夫人》", "example": null}, {"def": "多用于人名", "example": null}, {"def": "茝chǎi〈古〉指一种香草，即\\"白芷\\"。", "example": null}, {"def": "茝zhǐ 1.香草名。即白芷。", "example": null}]','chinese-xinhua','0'),
