('2101143297056575570','踵','1','zhǒnɡ','足','16',NULL,'[{"def": "踵", "example": null}, {"def": "(形声。从足,重声。本义追逐)", "example": null}, {"def": "同本义", "example": null}, {"def": "踵,追也。从足,重声。一曰往来貌。--《说文》", "example": null}, {"def": "踵二皇之遐武。--张衡《东京赋》", "example": null}, {"def": "踵见仲尼。--《庄子·德充符》", "example": null}, {"def": "有司靡踵。--《史记·太史公自叙》。索隐曰继也。”", "example": null}, {"def": "踵,迹也。--《后汉书·皇后纪》注", "example": null}, {"def": "骑者,军之司候也,所以踵败军,绝粮道,击便寇也。--《六韬·均兵》", "example": null}, {"def": "吴踵楚,而疆场无备,邑能无亡乎?--《左传·昭公二十四年》", "example": null}, {"def": "又如踵呼(追随呐喊)", "example": null}, {"def": "跟随", "example": null}, {"def": "步兵踵军后数十万人。--《汉书·武帝纪》", "example": null}, {"def": "又如踵至(接踵而来);踵蹑(相继;接连)", "example": null}, {"def": "踵zhǒng", "example": null}, {"def": "⒈脚后跟接～而来。比肩继～。", "example": null}, {"def": "⒉到，走到～门致谢。", "example": null}, {"def": "⒊追随，继承～后。～事增华（继承前人的事业并加以发展）。", "example": null}, {"def": "踵zhòng 1.见\\"?", "example": null}]','chinese-xinhua','0'),
('2101143297056575571','肿','1','zhǒnɡ','月','8',NULL,'[{"def": "肿", "example": null}, {"def": "(形声。从肉,中(重)声。本义痈) 同本义", "example": null}, {"def": "肿,痈也。--《说文》", "example": null}, {"def": "肉暴长曰肿。--《论衡·状留》", "example": null}, {"def": "肿疡。--《周礼·疡医》。注痈而上创者。”", "example": null}, {"def": "郁处头,则为肿为风。--《吕氏春秋·尽数》", "example": null}, {"def": "疡医掌肿疡。--《周礼·天官》。郑玄注肿疡,痈而上生疮者”", "example": null}, {"def": "肿", "example": null}, {"def": "浮胀;肿胀", "example": null}, {"def": "看那店主人,打的半边脸都肿了,半日挣扎不起。--《水浒传》", "example": null}, {"def": "又如肿泄(病名。腹泻及手足浮肿);肿哙(虚肿);肿疡(痈;毒疮);肿病(病名。即水肿。通称浮肿)", "example": null}, {"def": "肿（?", "example": null}]','chinese-xinhua','0'),
('2101143297056575572','种','1','zhǒnɡ','禾','9',NULL,'[{"def": "种", "example": null}, {"def": "植物的种子", "example": null}, {"def": "诞降嘉种。--《诗·大雅·生民》", "example": null}, {"def": "其谷宜五种。谓黍、菽、麦、稻也。--《周礼·职方氏》", "example": null}, {"def": "种不得下。--《汉书·沟洫志》。注五谷之子也。”", "example": null}, {"def": "宁有种乎?--《史记·陈涉世家》", "example": null}, {"def": "黄芩之种。--", "example": null}, {"def": "又如点种(点播种子);种籽(即种子);种食(谷种种粮食);种粮(谷物的种子);种实(即种子);种粒(犹种子);种子田(也叫留种田”)", "example": null}, {"def": "人的种族或其他生物的族类", "example": null}, {"def": "种马一物。--《周礼·校人》", "example": null}, {"def": "单于一平荡,种落自奔亡。--李白《出自蓟北门行》", "example": null}, {"def": "又如种落(部族居", "example": null}, {"def": "种 chóng姓。又见zhōng；zhòng。", "example": null}, {"def": "种chóng", "example": null}, {"def": "⒈姓。", "example": null}, {"def": "种（穘）zhǒng", "example": null}, {"def": "⒈植物果实中能长成新植物的部分选～子。播～儿。泛指生物传代的东西配～。良～。", "example": null}, {"def": "⒉类别，式样～类。品～。各～。凡此～ ～。", "example": null}, {"def": "⒊特指人的类别～族。黄～人≮～人。", "example": null}, {"def": "⒋", "example": null}, {"def": "种（穘）zhòng植，栽植～植。～瓜得瓜。～豆得豆。", "example": null}]','chinese-xinhua','0'),
('2101143297056575573','冢','1','zhǒnɡ','冖','10',NULL,'[{"def": "冢", "example": null}, {"def": "(形声。从宀,豕声。冖,表地覆盖。将死者覆盖于墓中,故从冖。本义高而大的坟)", "example": null}, {"def": "同本义", "example": null}, {"def": "冢,高坟也。--《说文》", "example": null}, {"def": "掌公墓之地。--《周礼·冢人》", "example": null}, {"def": "冢,秦晋之间或谓之陇。--《方言十三》", "example": null}, {"def": "乃立冢土。--《诗·大雅·緜》。传大社也。”即祭土神的高大土坛。", "example": null}, {"def": "项羽烧秦宫室,掘始皇帝冢。--《史记·高祖本纪》", "example": null}, {"def": "其下两冢。--清·袁枚《祭妹文》", "example": null}, {"def": "又如野冢(荒郊野外的乱坟);疑冢(古代富贵之家所设的假坟,为的是与真坟相混,不让后人认出真坟);冢人(古代管理墓葬的官吏);冢土(墓土;又指大社,天子祭神的地方);冢", "example": null}, {"def": "冢（塿）zhǒng高大的坟墓皇帝～。泛指坟墓荒～。", "example": null}]','chinese-xinhua','0'),
