('2101143297056575581','钟','1','zhōnɡ','钅','9',NULL,'[{"def": "钟", "example": null}, {"def": "(形声。左形,右声。鐘本义古代打击乐器,青铜制)", "example": null}, {"def": "同本义", "example": null}, {"def": "钟,乐钟也。--《说文》。杨树达曰钟者,可捶之物。”", "example": null}, {"def": "钟,铃也。--《广雅·释器》", "example": null}, {"def": "垂之和钟。--《礼记·明堂位》", "example": null}, {"def": "钟音之器也。--《左传·昭公二十一年》", "example": null}, {"def": "大钟鼎。--《淮南子·本经》", "example": null}, {"def": "细钧有乐,钟兑音也。--《国语·周语》", "example": null}, {"def": "声如洪钟。--宋· 苏轼《石钟山记》", "example": null}, {"def": "又", "example": null}, {"def": "钟磬置水中。", "example": null}, {"def": "又", "example": null}, {"def": "独以此钟名。", "example": null}, {"def": "又", "example": null}, {"def": "如钟鼓不绝。", "example": null}, {"def": "又如钟磬(两种古代乐器);钟鼎之家(宴享时列鼎、击钟奏乐的古代贵族家庭);钟石(指乐器中的钟和磬);钟板(钟和云板);钟乳(古钟面", "example": null}, {"def": "钟（鐘）zhōng", "example": null}, {"def": "⒈一种金属制的响器，中空，悬挂在架上，用槌敲击发声撞～。打～。警～。", "example": null}, {"def": "⒉计时器闹～。电～。石英～。", "example": null}, {"def": "⒊时间，小时五分～。八点～。", "example": null}, {"def": "⒋杯子，〈古〉一种盛酒器聚酒千～。", "example": null}, {"def": "⒌专注，特别～情。～爱。", "example": null}, {"def": "⒍积聚泽（湖泽），水之～也。", "example": null}]','chinese-xinhua','0'),
('2101143297056575582','舯','1','zhōnɡ','舟','10',NULL,'[{"def": "舯", "example": null}, {"def": "船体长度的中点或中部", "example": null}, {"def": "舯zhōng 1.船体长度的中点。民用船常指\\"垂线间长\\"中点，军用船常指\\"载重水线长\\"中点。 2.船体长度的中部。", "example": null}]','chinese-xinhua','0'),
('2101143297056575583','衷','1','zhōnɡ','衣','10',NULL,'[{"def": "衷", "example": null}, {"def": "(形声。从衣。中声。本义贴身的内衣)", "example": null}, {"def": "同本义", "example": null}, {"def": "衷,里亵衣。--《说文》。段玉裁注亵衣有在外者,衷则在内者也。”", "example": null}, {"def": "又如衷衣(里衣,内衣);衷服(贴身内衣)", "example": null}, {"def": "通中”。内心", "example": null}, {"def": "汝不察吾衷。--清·林觉民《与妻书》", "example": null}, {"def": "又如衷怀歉仄(心里感到内疚抱歉);衷言(心里话);衷素(内心真情)", "example": null}, {"def": "中心,中央", "example": null}, {"def": "佩,衷之旗也。--《左传·闵公二年》", "example": null}, {"def": "发命之不衷。--《左传·昭公十六年》", "example": null}, {"def": "服之不衷。--《左传·僖公二十四年》", "example": null}, {"def": "又如衷正(中正)", "example": null}, {"def": "姓", "example": null}, {"def": "衷", "example": null}, {"def": "贴身穿着;穿在里面", "example": null}, {"def": "或衷其襦。--《", "example": null}, {"def": "衷zhōng", "example": null}, {"def": "⒈贴身的内衣。〈引〉穿在里面的。", "example": null}, {"def": "⒉内心由～之言。～心感谢。", "example": null}, {"def": "⒊通\\"中\\"。中间折～。", "example": null}, {"def": "⒋", "example": null}, {"def": "衷zhòng 1.适当，恰当。", "example": null}]','chinese-xinhua','0'),
