('2101143297056575596','妯','1','zhóu','女','8',NULL,'[{"def": "妯娌", "example": null}, {"def": "两妯娌", "example": null}, {"def": "妯zhóu", "example": null}, {"def": "妯chōu 1.悲恸。", "example": null}]','chinese-xinhua','0'),
('2101143297056575597','轴','1','zhóu','车','9',NULL,'[{"def": "轴", "example": null}, {"def": "(形声。从车,由声。本义轮轴)", "example": null}, {"def": "同本义", "example": null}, {"def": "轴,持轮也。--《说文》", "example": null}, {"def": "輑谓之轴。--《方言九》", "example": null}, {"def": "服重任,行远道,正直而固者,轴也。--《列女传·母仪》", "example": null}, {"def": "迁于袒,用轴。--《仪礼·既夕礼》。注輁轴也。状如转辚,刻两头为轵。”", "example": null}, {"def": "天寒日短银灯续, 欲往从之车脱轴。 -- 宋·苏轼 《次韵王巩独眠》", "example": null}, {"def": "又如车轴;主轴;轴心(轮轴)", "example": null}, {"def": "车子", "example": null}, {"def": "字画下端便于悬挂或卷起的圆杆", "example": null}, {"def": "把平面或立体分成对称部分的直线", "example": null}, {"def": "轴zhóu", "example": null}, {"def": "⒈支持轮子或其它机件的圆柱形部件，有固定的和转动的两种汽车～。飞轮～。曲～磨床。", "example": null}, {"def": "⒉像轴的东西～儿线。", "example": null}, {"def": "⒊将平面或立体分成对称部分的直线～线。", "example": null}, {"def": "⒋指字、画卷下面的木杆，因而借指装裱成卷的书或字画壁上挂有三～画。", "example": null}, {"def": "⒌", "example": null}, {"def": "⒍", "example": null}, {"def": "轴zhòu", "example": null}]','chinese-xinhua','0'),
('2101143297056575598','碡','1','zhóu','石','14',NULL,'[{"def": "见碌碡”", "example": null}, {"def": "碡zhou", "example": null}, {"def": "碡zhóu 1.见\\"?碡\\"。 2.见\\"碡碌\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297056575599','胄','1','zhòu','月','9',NULL,'[{"def": "胄", "example": null}, {"def": "(形声。胄”古有两个字。小篆字形从肉,由声。本义头盔)", "example": null}, {"def": "同本义", "example": null}, {"def": "胄,兜鍪也。从月,由声。--《说文》", "example": null}, {"def": "离为甲胄。--《易·说卦》", "example": null}, {"def": "惟甲胄起戎。--《书·伪说命》", "example": null}, {"def": "贝胄朱綅。--《诗·鲁颂·閟宫》", "example": null}, {"def": "献甲者执胄。--《礼记·曲礼》", "example": null}, {"def": "左右免胄而下。--《左传·僖公三十三年》", "example": null}, {"def": "冠輘(胄)带剑。--《荀子·议兵》", "example": null}, {"def": "铠胄皆镔铁。--清·邵长蘅《青门剩稿》", "example": null}, {"def": "又如甲胄", "example": null}, {"def": "古代称帝王或贵族的后代", "example": null}, {"def": "刘公乃帝室之胄,德广才高,可领徐州。--《全图绣像三国演义》", "example": null}, {"def": "帝室之胄。--《", "example": null}, {"def": "胄zhòu〈古〉", "example": null}, {"def": "⒈作战时戴的头盔。", "example": null}, {"def": "⒉后代人帝室之～。", "example": null}]','chinese-xinhua','0'),
('2101143297056575600','荮','1','zhòu','艹','9',NULL,'[{"def": "荮", "example": null}, {"def": "用草包裹", "example": null}, {"def": "荮,草包物也。--《集韵》", "example": null}, {"def": "荮", "example": null}, {"def": "碗碟等用草绳束成一捆叫一荮。如一荮碗", "example": null}, {"def": "荮zhòu", "example": null}, {"def": "⒈用草包裹。", "example": null}, {"def": "⒉量词。用草绳束扎碗、碟等一捆为\\"一荮\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297060769792','皱','1','zhòu','皮','10',NULL,'[{"def": "皱", "example": null}, {"def": "(形声。从皮,刍声。本义皮肤因松弛而起的纹路)", "example": null}, {"def": "同本义", "example": null}, {"def": "莫道韶华镇长在,发白面皱专相待。--唐·李贺《嘲少年》", "example": null}, {"def": "面皮嘴唇烧的紫绛皱裂。--《红楼梦》", "example": null}, {"def": "又如皱皮(皮肤上的皱纹);皱文(皱纹)", "example": null}, {"def": "衣、物等经折叠而显出痕迹", "example": null}, {"def": "前低划开阔,烂漫堆众皱。--唐·韩愈《南山诗》", "example": null}, {"def": "又如皱褶(褶皱。指衣服上折叠的纹路);皱彀(喻指水面的微波)", "example": null}, {"def": "皱", "example": null}, {"def": "收缩;紧蹙", "example": null}, {"def": "琼窗春断双蛾皱。--南唐·李煜《采桑子》", "example": null}, {"def": "又如皱白(指残花);打皱(起皱纹);衣裳皱了", "example": null}, {"def": "皱（皺）zhòu", "example": null}, {"def": "⒈皮肤上起的褶纹满脸～纹。〈引〉物体上的褶纹衣服～了。", "example": null}, {"def": "⒉使生褶纹紧～眉头。", "example": null}, {"def": "皱zhōu 1.栗蓬，包在栗子外面的多刺壳斗。", "example": null}]','chinese-xinhua','0'),
('2101143297060769793','酎','1','zhòu','酉','10',NULL,'[{"def": "酎", "example": null}, {"def": "经过两次以至多次复酿的醇酒", "example": null}, {"def": "酎,三重醇酒也。--《说文》", "example": null}, {"def": "天子饮酎。--《明堂月令》", "example": null}, {"def": "酎之言醇也。--《礼记·月令孟夏注》", "example": null}, {"def": "见于尝酎。--《左传·襄公二十二年》。酒之新熟重者为酎。”", "example": null}, {"def": "四酎并熟。--《楚辞·大招》", "example": null}, {"def": "(孟夏之月)天子饮酎,用礼乐。--《礼记·月令》", "example": null}, {"def": "又如酎金(汉代诸侯在宗庙祭祀时献给皇帝的助祭金)", "example": null}, {"def": "酎zhòu醇酒。", "example": null}]','chinese-xinhua','0'),
