('2101143297060769797','骤','1','zhòu','马','17',NULL,'[{"def": "骤", "example": null}, {"def": "(形声。从马,聚声。本义马奔驰)", "example": null}, {"def": "同本义", "example": null}, {"def": "骤,马疾步也。--《说文》", "example": null}, {"def": "车骤徒趋。--《周礼·大司马》", "example": null}, {"def": "步及骤处兮。--《楚辞·招魂》。注走也。”", "example": null}, {"def": "车驱而驺(骤)。--《礼记·曲礼》", "example": null}, {"def": "驾彼四骆,载骤髒髒。--《诗·小雅·四牡》", "example": null}, {"def": "又如骤骥(疾驰的骏马)", "example": null}, {"def": "使马奔驰", "example": null}, {"def": "遇春骤马追到,便活擒于马上。--《英烈传》", "example": null}, {"def": "又如骤马(策马奔驰)", "example": null}, {"def": "泛指奔驰", "example": null}, {"def": "麋鹿见之快骤。--《庄子》", "example": null}, {"def": "骤", "example": null}, {"def": "迅疾,猛快", "example": null}, {"def": "杞伯于是骤朝于晋。--《左传·成公十八年》", "example": null}, {"def": "飘风不终朝,骤雨不终", "example": null}, {"def": "骤zhòu", "example": null}, {"def": "⒈马奔驰弛～。〈引〉急速，快速暴风～雨。", "example": null}, {"def": "⒉忽然，突然～然。狂风～起。天色～变。", "example": null}, {"def": "⒊〈古〉屡次，多次～谏（多次进谏）。", "example": null}]','chinese-xinhua','0'),
('2101143297060769798','籀','1','zhòu','竹','19',NULL,'[{"def": "籀", "example": null}, {"def": "同本义", "example": null}, {"def": "籀,读书也。--《说文》", "example": null}, {"def": "卜籀云。--《春秋传》。按,今本《左传》凡卦兆之词皆以繇为之。", "example": null}, {"def": "重籀《论语》诸书。--章炳麟《检论·订孔下》", "example": null}, {"def": "瞞河海之行、帝王、妃后、臣宰、农工、徒隶之法,无不籀也。--清·龚自珍《知归子赞》", "example": null}, {"def": "又如籀读(诵读);籀书(即籀文)", "example": null}, {"def": "通抽”。抽取;引出", "example": null}, {"def": "挥兔豪而匪固,籀鱼网而终灭。--唐·李俨《益州多宝寺道因法师碑文》序", "example": null}, {"def": "又如籀演(引申;演绎)", "example": null}, {"def": "籀", "example": null}, {"def": "汉字的一种文体。一名大篆", "example": null}, {"def": "周宣王史名籀,其所著文字曰籀文。亦曰大篆。--朱骏声《", "example": null}, {"def": "籀zhòu", "example": null}, {"def": "⒈", "example": null}, {"def": "⒉阅读～读。讽～（诵读）。", "example": null}]','chinese-xinhua','0'),
('2101143297060769799','纣','1','zhòu','纟','6',NULL,'[{"def": "纣", "example": null}, {"def": "驾车马后部的革带", "example": null}, {"def": "纣,马緧也。从糸,肘省声。--《说文》", "example": null}, {"def": "车纣,自关而东,周、洛、韩、汝、颍而东谓之韌,或谓之曲绹,或谓之曲纶;自关而西谓之纣。--扬雄《方言》", "example": null}, {"def": "商代最末的君主名,史称纣王", "example": null}, {"def": "桀纣贵为天子。--《吕氏春秋·功名》。注贱仁多累曰纣。”", "example": null}, {"def": "残义损善曰纣。--蔡邕《独断》", "example": null}, {"def": "以同言楚威王于侧纣之间。--《战国策·秦策》", "example": null}, {"def": "纣zhòu", "example": null}, {"def": "⒈驾车时系在牲口后的皮带子。", "example": null}, {"def": "⒉〈古〉人名。商朝末代君主。", "example": null}]','chinese-xinhua','0'),
