('2101143297060769801','咒','1','zhòu','口','8',NULL,'[{"def": "咒", "example": null}, {"def": "(呪俗作咒。会意。从口从兄。兄”,祝”的本字。祝、呪本同一词。祝愿和诅呪是一件事的两面。本义祝告)", "example": null}, {"def": "同本义", "example": null}, {"def": "时夏大旱,…辅乃自暴庭中,慷慨呪曰。--《后汉书·谅辅传》", "example": null}, {"def": "尸呪齐戒。--《淮南子·说山》", "example": null}, {"def": "崇替在人,咒何预焉?--《文心雕龙》", "example": null}, {"def": "又如咒延(祝祷延年益寿);咒祝(祝祷祈福);咒愿(向天或神佛祷祝,希望顺遂或表示心愿)", "example": null}, {"def": "诅咒,乞求神灵降祸", "example": null}, {"def": "忳咒曰有何枉状,可前求理乎?”--《后汉书·王忳》", "example": null}, {"def": "又如他没完没了地咒骂;咒念(诅咒;咒骂);咒詈(咒骂);咒罚(诅咒惩罚)", "example": null}, {"def": "咒", "example": null}, {"def": "旧时僧、道、方士", "example": null}, {"def": "咒（呪）zhòu", "example": null}, {"def": "⒈某些宗教或（迷信）巫术的密语或符号～语。符～。", "example": null}, {"def": "⒉说希望别人遭难的话或用恶毒的话骂诅～。～骂。～人伤自身。", "example": null}, {"def": "⒊发誓赌～。", "example": null}]','chinese-xinhua','0'),
('2101143297060769802','宙','1','zhòu','宀','8',NULL,'[{"def": "宙", "example": null}, {"def": "(形声。从宀,由声。宀”,表示房屋。本义栋梁)", "example": null}, {"def": "同本义", "example": null}, {"def": "宙,舟舆所极覆也。--《说文》。按,舟舆上覆如屋极者,或曰覆也,舟舆所极也。", "example": null}, {"def": "而燕雀佼之,以为不能与之争于宇宙之间。--刘安《淮南子·览冥》。高诱注宇,屋檐也。宙,栋梁也。”", "example": null}, {"def": "古往今来的时间;时间的总称", "example": null}, {"def": "往古来今谓之宙,四方上下谓之宇。--刘安《淮南子·齐俗》", "example": null}, {"def": "有实而无乎处者宇也,有长而无本剽者宙也。--《庄子·庚桑楚》。注宙者,有古今之长。”", "example": null}, {"def": "又如宙始(远古);宙合(囊括上下古今之道)", "example": null}, {"def": "天空", "example": null}, {"def": "功烛上宙,", "example": null}, {"def": "宙zhòu古往今来，无限的时间有长而无本剽者～也（本剽本末。指开始和尽头）。", "example": null}]','chinese-xinhua','0'),
('2101143297060769803','绉','1','zhòu','纟','8',NULL,'[{"def": "绉", "example": null}, {"def": "细葛布", "example": null}, {"def": "绉,絺之细也。从糸,刍声。--《说文》", "example": null}, {"def": "蒙彼绉絺。--《诗·鄘风·君子偕老》。传霑之靡者为绉。”", "example": null}, {"def": "又如绉絺(精细的葛布)", "example": null}, {"def": "织出皱纹的丝织品", "example": null}, {"def": "绉", "example": null}]','chinese-xinhua','0'),
