('2101143297060769830','啁','1','zhōu','口','11',NULL,'[{"def": "啁哳，嘲哳 zhao", "example": null}, {"def": "鵾鸡啁哳而悲鸣。--《楚辞·九辩》", "example": null}, {"def": "也作嘲哳”", "example": null}, {"def": "呕哑嘲哳难为听。--白居易《琵琶行》(并序)", "example": null}, {"def": "啁  zhou", "example": null}, {"def": "形容鸟叫等各种声音", "example": null}, {"def": "啁啾", "example": null}, {"def": "乳雀啁啾日气浓。--林逋《初夏》", "example": null}, {"def": "丝管啁啾空翠来。--唐·杜甫《渼陂行》", "example": null}, {"def": "啁zhāo", "example": null}, {"def": "啁zhōu", "example": null}, {"def": "⒈", "example": null}, {"def": "啁tiáo 1.戏谑;嘲笑。", "example": null}]','chinese-xinhua','0'),
('2101143297060769831','竹','1','zhú','竹','6',NULL,'[{"def": "竹", "example": null}, {"def": "(象形。小篆字形,象竹茎与下垂的叶片。竹”是汉字的一个部首。从竹”的字大部分是乐器、竹器和记载文字的东西。本义竹子)", "example": null}, {"def": "同本义", "example": null}, {"def": "竹,冬生草也。象形。--《说文》", "example": null}, {"def": "伐竹取道,下见小潭。--柳宗元《小石潭记》", "example": null}, {"def": "官用竹,皆令录厚头,积之如山。--《世说新语·政事》", "example": null}, {"def": "又如竹笋汤(竹板子);竹夫人(中空、有孔的竹编床上用品);竹撞(竹编提盒);竹箨(竹笋的皮;笋衣);竹笥(竹箱);竹蓖(竹棍。一端劈开的篾条,用于打人的一种刑具);竹笆(竹", "example": null}, {"def": "篱);竹皮", "example": null}, {"def": "竹zhú", "example": null}, {"def": "⒈多年生常绿植物。竿多节，节间一般中空。种类很多，常见的有慈～、毛～、淡～、苦～子等。竿可造纸、供建筑、制器具等。", "example": null}, {"def": "⒉称箫管类的乐器～笛。～箫。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}, {"def": "①史册，书籍。", "example": null}, {"def": "②竹简和绢帛（〈古〉刻写材料）著之～帛。", "example": null}]','chinese-xinhua','0'),
('2101143297060769832','竺','1','zhú','竹','8',NULL,'[{"def": "竺", "example": null}, {"def": "(形声。从二,竹声。本义竹)", "example": null}, {"def": "同本义", "example": null}, {"def": "竺,竹也。--《广雅》。王念孙疏证竺、竹同声字。方言有重轻,故又谓竹为竺也。”", "example": null}, {"def": "印度古译名天竺”的简称", "example": null}, {"def": "双匣犹传竺国经。--林景熙《梦中作》", "example": null}, {"def": "又如竺经(佛经);竺国(天竺。古印度的别称);竺域(指天竺。即今印度);竺土(指天竺国。指古印度)", "example": null}, {"def": "山名", "example": null}, {"def": "朝游三竺,暮宿两峰。--《西湖佳话》", "example": null}, {"def": "古代的一种乐器", "example": null}, {"def": "高渐离击竺。--《战国策·燕策》", "example": null}, {"def": "非丝非竺。--宋·欧", "example": null}, {"def": "竺zhú", "example": null}, {"def": "竺dǔ 1.通\\"笃\\"●;深。 2.通\\"毒\\"。憎恨;憎恶。", "example": null}]','chinese-xinhua','0'),
