('2101143297060769854','箸','1','zhù','竹','14',NULL,'[{"def": "箸", "example": null}, {"def": "(形声。从竹,者声。本义筷子。又作筯”) 同本义", "example": null}, {"def": "羹之有菜者用梜。--《礼记·曲礼》。注今人或谓箸为梜。”", "example": null}, {"def": "纣为象箸,而箕子唏。--《史记·十二诸侯年表》", "example": null}, {"def": "停杯投箸不能食。--唐·李白《行路难》", "example": null}, {"def": "辍箸叹曰。--清·周容《芋老人传》", "example": null}, {"def": "又", "example": null}, {"def": "亦辍箸曰。", "example": null}, {"def": "又", "example": null}, {"def": "独一箸间。", "example": null}, {"def": "又如长箸(较长的筷子);箸长碗短(比喻餐具凌乱不齐);箸筩(盛筷子的竹筒);箸子(筷子)", "example": null}, {"def": "箸", "example": null}, {"def": "通著”。显明;显示", "example": null}, {"def": "知命者也,箸是者也。--《荀子·非十二子》", "example": null}, {"def": "霸者之善箸焉。--《荀子·强国》", "example": null}, {"def": "致忠信,箸仁义。--《", "example": null}, {"def": "箸zhù 1.筷子。", "example": null}, {"def": "箸zhuó 1.附着。 2.穿着。", "example": null}]','chinese-xinhua','0'),
('2101143297060769855','翥','1','zhù','羽','14',NULL,'[{"def": "翥", "example": null}, {"def": "(形声。从羽,者声。本义振翼而上,高飞) 同本义", "example": null}, {"def": "魂随南翥鸟,泪尽北枝花。--宋之问《度大庾岭》", "example": null}, {"def": "鸾鸟轩翥而翔飞。--《楚辞·远游》", "example": null}, {"def": "翥zhù鸟飞，鸟高飞凤～。鹰～。轩（高）～。", "example": null}]','chinese-xinhua','0'),
