('2101143297064964117','铢','1','zhū','钅','11',NULL,'[{"def": "铢", "example": null}, {"def": "(形声。从金,朱声。从金”与货币有关。本义古代重量单位,二十四铢为一两)", "example": null}, {"def": "同本义", "example": null}, {"def": "虽分国如锱铢。--《礼记·儒行》", "example": null}, {"def": "现代泰国基本货币单位", "example": null}, {"def": "铢,权十分黍之重也。--《说文》", "example": null}, {"def": "铢", "example": null}, {"def": "钝,不锋利", "example": null}, {"def": "其兵戈铢而无刃。--《淮南子·齐俗》", "example": null}, {"def": "细微", "example": null}, {"def": "陛下铢分邪正,升黜分明,天下幸甚。--《辽史》", "example": null}, {"def": "铢积寸累", "example": null}, {"def": "为学须铢积寸累。--曾国藩《克勤小物》", "example": null}, {"def": "铢两悉称", "example": null}, {"def": "铢zhū〈古〉我国重量单位。约三十八～等于一市两。〈喻〉极少～两。～积寸累（一～一寸地积累。形容得来不易）。", "example": null}]','chinese-xinhua','0'),
('2101143297064964118','蛛','1','zhū','虫','12',NULL,'[{"def": "蛛", "example": null}, {"def": "蜘蛛", "example": null}, {"def": "蚁穿万孔萃,蛛挂千丝扰。--《次韵王子钦》", "example": null}, {"def": "又如蛛丝(蜘蛛吐出腹内分泌物而形成的丝);蛛煤(蜘蛛网和烟尘);蛛蝥(蜘蛛的别名);蛛螫(毒害)", "example": null}, {"def": "蛛丝马迹", "example": null}, {"def": "大开通同转假之门,泛滥转博,几疑天下无字不可通用,而实则蛛丝马迹,原原本本,具在古书。--清·王家贲《别雅序》", "example": null}, {"def": "蛛网", "example": null}, {"def": "蛛zhū蛛，俗称\\"蜘蛛\\" ，种类很多，如蟹～、球腹～等。蜘蛛，节肢动物，有足四对。肛门周围有腺体，能分泌粘液，用来结网捕食虫子密如～网。～丝马迹（〈喻〉线索和", "example": null}, {"def": "迹象）。～网尘埃（〈喻〉陈旧、腐朽、肮脏的东西）。", "example": null}]','chinese-xinhua','0'),
('2101143297064964119','槠','1','zhū','木','14',NULL,'[{"def": "槠", "example": null}, {"def": "槠树", "example": null}, {"def": "沙堂栎槠。--司马相如《上林赋》", "example": null}, {"def": "槠zhū常绿乔木。初夏开黄绿色的花，果实外面或下面有壳斗。种类多。木材坚硬，可供建筑、造船、制器具等用。", "example": null}]','chinese-xinhua','0'),
('2101143297064964120','潴','1','zhū','氵','14',NULL,'[{"def": "潴", "example": null}, {"def": "(形声。从水,猪声。本义水停聚的地方) 同本义", "example": null}, {"def": "以潴畜水。--《周礼·地官·稻人》", "example": null}, {"def": "又如潴泺(湖泊)", "example": null}, {"def": "潴", "example": null}, {"def": "蓄积", "example": null}, {"def": "渚水潴涨,方广数里。--《水经注》", "example": null}, {"def": "又如潴水(蓄水);潴泄(蓄水和放水);潴畜,潴蓄(指蓄洪贮水);潴溉(蓄聚灌溉)", "example": null}, {"def": "指水停聚", "example": null}, {"def": "又如潴淤(停聚淤泥);潴潦(聚汇的水;停积的水)", "example": null}, {"def": "潴留", "example": null}, {"def": "尿潴留", "example": null}, {"def": "潴（瀦）zhū", "example": null}, {"def": "⒈积聚～留。", "example": null}, {"def": "⒉水停聚的地方。", "example": null}]','chinese-xinhua','0'),
('2101143297064964121','朱','1','zhū','木','6',NULL,'[{"def": "朱", "example": null}, {"def": "(指事。小篆字形,从木,一在其中指出这种木是红心的。 本义赤心木)", "example": null}, {"def": "同本义", "example": null}, {"def": "朱,赤心木,松柏属。--《说文》", "example": null}, {"def": "指朱色的物品", "example": null}, {"def": "…朱(此指朱色缯帛)四百裹。--《穆天子传》", "example": null}, {"def": "姓", "example": null}, {"def": "朱孝纯子颍。(朱孝纯,字子颍,山东历城人,乾隆进士,当时任泰安知府,善诗画。)--清·姚鼐《登泰山记》", "example": null}, {"def": "朱", "example": null}, {"def": "朱色,大红色 。古代称为正色", "example": null}, {"def": "网户朱缀。--《楚辞·招魂》", "example": null}, {"def": "紫衣而朱冠。--《庄子·达生》", "example": null}, {"def": "朱衣冠,执朱弓,挟朱矢。--《墨子·明鬼下》", "example": null}, {"def": "朱门酒肉臭,路有冻死骨。--", "example": null}, {"def": "朱zhū", "example": null}, {"def": "⒈大红色～门（〈古〉又用作豪门的代称）。", "example": null}, {"def": "⒉", "example": null}, {"def": "朱shū 1.见\\"朱提\\"。", "example": null}]','chinese-xinhua','0'),
