('2101143297064964123','侏','1','zhū','亻','8',NULL,'[{"def": "侏", "example": null}, {"def": "短小", "example": null}, {"def": "侏,短也。--《广雅·释诂》", "example": null}, {"def": "侏儒不可使援。--《国语·晋语》", "example": null}, {"def": "又如侏优(侏儒与优伶)", "example": null}, {"def": "肥大", "example": null}, {"def": "侏侏", "example": null}, {"def": "修侏侏,比于朱儒。--《太玄经·童》", "example": null}, {"def": "侏儒", "example": null}, {"def": "奉化应方伯,在京与试,成绩很优;因为貌颇侏儒,未能列选。--阿英《明朝的笑话》", "example": null}, {"def": "侏儒症", "example": null}, {"def": "由一个隐性基因引起的侏儒症", "example": null}, {"def": "侏zhū矮小。", "example": null}, {"def": "侏zhōu 1.见\\"侏张\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297064964124','诛','1','zhū','讠','8',NULL,'[{"def": "诛", "example": null}, {"def": "(形声。从言,朱声。本义声讨、谴责)", "example": null}, {"def": "同本义", "example": null}, {"def": "诛,讨也。--《说文》", "example": null}, {"def": "诛,代。诛犹责也。--《白虎通》", "example": null}, {"def": "诛以驭其过。--《周礼·太宰》", "example": null}, {"def": "诛求无厌。--《左传·襄公三十一年》", "example": null}, {"def": "齿路马有诛。--《礼记·曲礼》。注罚也。”", "example": null}, {"def": "得志于诸侯,而诛无理,曹其首也。--《左传·僖公二十三年》", "example": null}, {"def": "于予与何诛?--《论语·公冶长》", "example": null}, {"def": "甚悖逆不轨,宜诛讨之日久矣。--汉·桓宽《盐铁论·本议》", "example": null}, {"def": "又如诛放(责斥其罪并予以放逐);诛远(斥退疏远);诛惩(声讨惩处);诛心(揭露、指责人的用心)", "example": null}, {"def": "杀戮。夺去生命", "example": null}, {"def": "立诛杀曹无伤", "example": null}, {"def": "诛zhū", "example": null}, {"def": "⒈杀死，铲除～戮ˇ民者～。～锄杂草。", "example": null}, {"def": "⒉谴责，责罚，讨伐口～笔伐。兴兵～之。", "example": null}]','chinese-xinhua','0'),
('2101143297064964125','邾','1','zhū','阝','8',NULL,'[{"def": "邾", "example": null}, {"def": "古国名", "example": null}, {"def": "邾,周武王时所封曹姓国也。始封之君曰侠,为鲁附庸。从邑,朱声。--《说文》", "example": null}, {"def": "在今山东邹县", "example": null}, {"def": "古邑名", "example": null}, {"def": "邾zhū周代诸侯国名，后改名为\\"邹\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297064964126','洙','1','zhū','氵','9',NULL,'[{"def": "洙", "example": null}, {"def": "古水名", "example": null}, {"def": "洙水出泰山盖临乐山,北入泗。从水,朱声。--《说文》", "example": null}, {"def": "源出今山东省新泰县东北,折西南与泗水合流◇世上源在泰安县东南改道西流合入汶水,今为小汶河上游,已与泗水隔绝", "example": null}, {"def": "洙zhū［洙水］泗水的支流，在山东省，流入南阳湖。", "example": null}]','chinese-xinhua','0'),
('2101143297064964127','茱','1','zhū','艹','9',NULL,'[{"def": "茱萸", "example": null}, {"def": "茱zhū", "example": null}]','chinese-xinhua','0'),
('2101143297064964128','株','1','zhū','木','10',NULL,'[{"def": "株", "example": null}, {"def": "(形声。从木,朱声。本义露出地面的树根)", "example": null}, {"def": "同本义", "example": null}, {"def": "株,木根也。--《说文》。今语转曰桩。", "example": null}, {"def": "命曰株送徒。--《史记·平准书》。集解根蒂也。”", "example": null}, {"def": "若厥株驹。--《列子·黄帝》。释文枯树本也。”", "example": null}, {"def": "田中有株,兔走触株,折颈而死。--《韩非子·五蠹》", "example": null}, {"def": "又", "example": null}, {"def": "释其来而守株。", "example": null}, {"def": "又", "example": null}, {"def": "皆守株之类。", "example": null}, {"def": "又如株橛(树桩、木根);株蘖(树木砍伐后根株生出的枝条)", "example": null}, {"def": "泛指草木", "example": null}, {"def": "泽涸无鱼,山童无株。--汉·焦赣《易林》", "example": null}, {"def": "植根", "example": null}, {"def": "大株于土;萍于水。--晋·干宝《搜神记》", "example": null}, {"def": "又如株榾(残根断树);株柢(根祗);株枸(", "example": null}, {"def": "株zhū", "example": null}, {"def": "⒈露出地面的树根守～待兔（〈喻〉死守狭隘经验或妄想不劳而得）。", "example": null}, {"def": "⒉棵儿，植物体植～。病～。良～。", "example": null}, {"def": "⒊量词。指植物有桑八百～。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}]','chinese-xinhua','0'),
('2101143297064964129','珠','1','zhū','王','10',NULL,'[{"def": "珠", "example": null}, {"def": "(形声。从玉,朱声。本义珍珠。蛤蚌壳内由分泌物结成的有光小圆体)", "example": null}, {"def": "同本义", "example": null}, {"def": "珠,蚌之阴精。--《说文》。按,水精也,或生于蚌,阴精所凝。", "example": null}, {"def": "珠足以御火灾。--《国语·楚语》", "example": null}, {"def": "水方折者有玉,员折者有珠。--《尸子》", "example": null}, {"def": "渊生珠而岸不枯。--《淮南子·说山》", "example": null}, {"def": "珠盘玉敦。--《周礼·玉府》", "example": null}, {"def": "大珠四枚。--明·崔铣《记王忠肃公翱三事》", "example": null}, {"def": "又", "example": null}, {"def": "所货西洋珠。", "example": null}, {"def": "又", "example": null}, {"def": "公受珠。", "example": null}, {"def": "又", "example": null}, {"def": "出珠授之。", "example": null}, {"def": "又如珠户(采珠的民户;珠饰的门户);珠履(以珍珠为饰的鞋子);珠碧(珍珠与碧玉);珠英(美如珍珠的花);珠翠(珍珠与翠玉);珠市(买卖珍珠的集", "example": null}, {"def": "珠zhū", "example": null}, {"def": "⒈", "example": null}, {"def": "。", "example": null}, {"def": "⒉样子像珍珠的东西水～。露～儿。眼～子。", "example": null}, {"def": "⒊", "example": null}, {"def": "⒋", "example": null}]','chinese-xinhua','0'),
('2101143297064964130','诸','1','zhū','讠','10',NULL,'[{"def": "诸", "example": null}, {"def": "(形声。从言,者声。本义辩,问辩) 同本义", "example": null}, {"def": "诸,辩也。--《说文》。按,者亦意辩词也。", "example": null}, {"def": "诸诸便便,辩也。--《尔雅》", "example": null}, {"def": "穷研细诸问,岂得信虚辞!--《敦煌变文集·燕子赋》", "example": null}, {"def": "又如诸问(问辩)", "example": null}, {"def": "诸", "example": null}, {"def": "众;各", "example": null}, {"def": "诸郡县苦秦吏。--《史记·陈涉世家》", "example": null}, {"def": "西和诸戎。--《三国志·诸葛亮传》", "example": null}, {"def": "诸道桥梁。--《资治通鉴·唐纪》", "example": null}, {"def": "又", "example": null}, {"def": "诸将皆失色。", "example": null}, {"def": "诸越则桃李冬实。(诸越,即百越”,指两广地区。)--宋·沈括《梦溪笔谈》", "example": null}, {"def": "诸峰之顶,亦低于山顶之地面。--宋·沈括《梦溪笔谈·活板》", "example": null}, {"def": "仆必能从", "example": null}, {"def": "诸zhū", "example": null}, {"def": "⒈各，众，许多～军。～位。～君。～子百家。", "example": null}, {"def": "⒉义同文言中的\\"之于\\"（\\"之\\"代词，相当于现代汉语的\\"他、她、它\\"）投～渤海。公～于世。付～实施。", "example": null}, {"def": "⒊义同文言中的\\"之乎\\"（\\"乎\\"疑问语气词，相当于现代汉语的\\"吗\\"）有～？闻～（听说过这件事吗）？", "example": null}, {"def": "诸chú 1.蟾蜍。", "example": null}]','chinese-xinhua','0'),
('2101143297064964131','猪','1','zhū','犭','11',NULL,'[{"def": "猪", "example": null}, {"def": "猪只", "example": null}, {"def": "达,热时喜浸水散热;特指家养种的成员", "example": null}, {"def": "猪,豕而三毛丛居者。从豕,者声。--《说文》。按,豕子也。", "example": null}, {"def": "如猪魈(猪怪;猪精);猪膀胱(又称猪尿泡”、猪胞”、猪尿脬”、猪脬”);小猪(又叫猪牙子”、猪仔”、猪娃”、猪娃子”);母猪(又叫猪婆”、猪婆", "example": null}, {"def": "子”、猪娘”)", "example": null}, {"def": "十二生肖之一,配地支的亥”", "example": null}, {"def": "猪（豬）zhū家畜之一。体胖肉多，耳大头大，四肢短。肉供食用，皮、毛和骨是工业原料，粪与尿是很好的有机肥料。", "example": null}]','chinese-xinhua','0'),
