('2101143297077547027','颛','1','zhuān','页','15',NULL,'[{"def": "颛", "example": null}, {"def": "善良", "example": null}, {"def": "猛兽食颛民。--《淮南子》", "example": null}, {"def": "又如颛愚(忠厚善良);颛醇(善良淳朴)", "example": null}, {"def": "顽愚", "example": null}, {"def": "某比兴非工,颛蒙有素。--李商隐《献侍郎钜鹿公启》", "example": null}, {"def": "又如颛庸(愚昧平庸);颛颛(愚昧无知的样子);颛蒙(愚昧);颛甿(愚昧的乡下人)", "example": null}, {"def": "通专”。专门", "example": null}, {"def": "彭祖安乐各颛门教授。--《汉书·儒林严彭祖传》", "example": null}, {"def": "相国产颛兵秉政。--《汉书·高后纪》", "example": null}, {"def": "兼业颛利。--《汉书·货殖列传》", "example": null}, {"def": "颛", "example": null}, {"def": "专擅。通专”", "example": null}, {"def": "颛妄言。--《史记·陈涉世家》", "example": null}, {"def": "颛作威福庙堂之上。--《汉书·诸侯王表》", "example": null}, {"def": "光颛权自恣。--《", "example": null}, {"def": "颛zhuān", "example": null}, {"def": "⒈愚昧。", "example": null}, {"def": "⒉通\\"专\\"。", "example": null}, {"def": "⒊", "example": null}]','chinese-xinhua','0'),
