('2101143297077547035','壮','1','zhuànɡ','士','6',NULL,'[{"def": "壮", "example": null}, {"def": "(形声。从士,爿声。本义人体高大,肌肉壮实)", "example": null}, {"def": "同本义", "example": null}, {"def": "壮,大也。--《说文》", "example": null}, {"def": "壮,健也。--《广雅》", "example": null}, {"def": "秦晋之间凡人之大谓之奘,或谓之壮。--《方言》", "example": null}, {"def": "三十曰壮。--《礼记·曲礼》", "example": null}, {"def": "壮士,赐之卮酒。--《史记·项羽本纪》", "example": null}, {"def": "右贤王惊,夜逃,独与其爱妾一人,壮骑数百驰。--《史记·卫将军骠骑列传》", "example": null}, {"def": "男气壮力。--《逸周书》", "example": null}, {"def": "壮哉我中国少年。--清·梁启超《饮冰室合集·文集》", "example": null}, {"def": "三小姐长远勿见,好像壮仔点哉。--清·韩邦庆《海上花列传》", "example": null}, {"def": "又如壮浪(健壮);壮盛(强壮旺盛);壮勇(强壮而勇敢);", "example": null}, {"def": "壮（壯）zhuàng", "example": null}, {"def": "⒈强健，有力强～。健～。年青力～√苗～。", "example": null}, {"def": "⒉雄伟，宏伟，有气魄雄～。～丽。～观。～志。～烈。气～山河。", "example": null}, {"def": "⒊增大，加强～大。他为你～胆。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "壮zhuàng", "example": null}, {"def": "壮qiāng 1.伤。", "example": null}, {"def": "壮zhuāng 1.姓。春秋时有壮驰兹。见《国语．晋语九》。", "example": null}]','chinese-xinhua','0'),
('2101143297077547036','状','1','zhuànɡ','犬','7',NULL,'[{"def": "状", "example": null}, {"def": "(形声。从犬,爿声。用具体的动物犬”表示事物各具形态。本义犬形)", "example": null}, {"def": "同本义。引申为形状,形态", "example": null}, {"def": "状,犬形也。--《说文》", "example": null}, {"def": "且曰献状。--《左传·文公十五年》。谓献其骈肋之状也。", "example": null}, {"def": "凡铸金之状。--《考工记·桌氏》。杜注谓形状。”", "example": null}, {"def": "以筒水灌之,始出,状极俊健。--《聊斋志异》", "example": null}, {"def": "有双石高竦,其状若门。--郦道元《水经注》", "example": null}, {"def": "若啸呼状。--明·魏学洢《核舟记》", "example": null}, {"def": "又如状类(形似);粉状;杆状;块状;粒状;絮状;海绵状;奇形怪状", "example": null}, {"def": "情形;状况", "example": null}, {"def": "舍人弟上变,告信欲反状于吕后。--《史记·淮阴侯列", "example": null}, {"def": "状（狀）zhuàng", "example": null}, {"def": "⒈样子，形态，情形～态。～况。形～。喜笑～。重病～。", "example": null}, {"def": "⒉陈述，描绘自～其过。景色奇丽，殆不可～（殆几乎）。", "example": null}, {"def": "⒊文体的一种，叙述事情的文字行～（死者传略）。", "example": null}, {"def": "⒋诉讼～纸。告～。", "example": null}, {"def": "⒌特殊格式的凭证。指嘉奖、委任等奖～。委任～。军令～。", "example": null}, {"def": "⒍", "example": null}, {"def": "居首位的人养鸡～元。种菜～元。", "example": null}, {"def": "⒎", "example": null}, {"def": "语。状语后有时要用助词\\"地\\"，如\\"非常地激烈\\"。", "example": null}, {"def": "状zhuàng", "example": null}]','chinese-xinhua','0'),
