('2101143297081741322','坠','1','zhuì','土','7',NULL,'[{"def": "坠", "example": null}, {"def": "(形声。从土,队声。坠落到地上,故从土。本义落下,掉下)", "example": null}, {"def": "同本义", "example": null}, {"def": "隊,从高陨也。--《说文》。俗字作墜。", "example": null}, {"def": "墜,落也。--《尔雅》", "example": null}, {"def": "墜,堕也。--《广雅》", "example": null}, {"def": "死而坠也。--《公羊传·文公三年》", "example": null}, {"def": "朝饮木籣之坠露兮。--《楚辞·离骚》", "example": null}, {"def": "矢交坠兮士争先。--《楚辞·九歌·国殇》", "example": null}, {"def": "自舟中坠于水。--《吕氏春秋·察今》", "example": null}, {"def": "又", "example": null}, {"def": "剑之所从坠。", "example": null}, {"def": "抗坠疾徐。(坠,声音低沉。)--清·侯方域《壮悔堂文集》", "example": null}, {"def": "杞国有人,忧天地崩坠。--《列子·天瑞》", "example": null}, {"def": "坠入深渊难以复出。--《汉书·枚乘传》", "example": null}, {"def": "又如坠睫(落泪);坠楼(从楼上掉", "example": null}, {"def": "坠（墜）zhuì", "example": null}, {"def": "⒈落，掉下，下沉～落。～下。天欲～。船锚正在下～。", "example": null}, {"def": "⒉系在物体上的垂着之东西扇～儿。耳～子。", "example": null}, {"def": "⒊", "example": null}, {"def": "①耳坠。", "example": null}, {"def": "②河南、山东等地的一种曲艺河南～子。", "example": null}]','chinese-xinhua','0'),
('2101143297081741323','缀','1','zhuì','纟','11',NULL,'[{"def": "缀", "example": null}, {"def": "同本义", "example": null}, {"def": "缀,合箸也。--《说文》", "example": null}, {"def": "缀衣。--《书·立政》。传掌衣服。”", "example": null}, {"def": "出缀衣于庭。--《书·顾命》", "example": null}, {"def": "为下国缀旒。--《诗·大雅·长发》", "example": null}, {"def": "缀甲厉兵。--《战国策·秦策一》", "example": null}, {"def": "又如缀甲(缝制甲衣);缀拾(采集连缀);缀纯(连缀杂彩以为缘边);缀葺(修补;缝补);缀缀(相连缀的样子)", "example": null}, {"def": "著作。组织文字以成篇章", "example": null}, {"def": "伺其疲倦,即谕之缀诗赋。--白行简《李娃传》", "example": null}, {"def": "李藩侍郎尝缀李贺歌诗,为之集序未成。--《李长吉歌诗》", "example": null}, {"def": "夜书细字缀语言,雨目眵昏头雪白。--韩愈《短灯檠歌》", "example": null}, {"def": "又如缀集(连缀", "example": null}, {"def": "缀zhuì", "example": null}, {"def": "⒈缝，连结～合。～上。～补。～辞成文。", "example": null}, {"def": "⒉装饰点～。", "example": null}, {"def": "缀chuò 1.拘束。 2.牵制。 3.通\\"辍\\"。停;中止。", "example": null}]','chinese-xinhua','0'),
('2101143297081741324','惴','1','zhuì','忄','12',NULL,'[{"def": "惴", "example": null}, {"def": "(形声。从心,聑声。本义忧愁恐惧) 同本义", "example": null}, {"def": "惴,忧惧也。--《说文》", "example": null}, {"def": "惴,忧也。--《广雅》", "example": null}, {"def": "人皆惴恐。--《汉书·宁成传》", "example": null}, {"def": "惴惴其栗。--《诗·秦风·黄鸟》", "example": null}, {"def": "惴惴,惧也。--《尔雅》", "example": null}, {"def": "小恐惴惴。--《庄子·齐物论》", "example": null}, {"def": "自返而不缩,虽褐宽博,吾不惴焉。--《孟子·公孙丑》", "example": null}, {"def": "屯田数十万,堤防常慴惴。--杜牧《感怀诗一首》", "example": null}, {"def": "又如惴怯(胆怯,恐惧);惴畏(畏惧);惴恐(恐惧);惴息(害怕得不敢喘息);惴惕(恐惧,忧戚);惴悸(惊惧)", "example": null}, {"def": "惴zhuì既恐惧又担忧～ ～不安。～ ～其慄（慄发抖）。", "example": null}]','chinese-xinhua','0'),
('2101143297081741325','缒','1','zhuì','纟','12',NULL,'[{"def": "缒", "example": null}, {"def": "(形声。从糸,追声。本义糸在绳子上放下去)", "example": null}, {"def": "同本义", "example": null}, {"def": "缒,以绳有所悬也。--《说文》", "example": null}, {"def": "夜缒纳师。--《左传·襄公十九年》", "example": null}, {"def": "子占使师夜缒而登。--《左传·昭公十九年》", "example": null}, {"def": "敌兵攻城,纲身督战,募壮士缒城而下。--《宋史》", "example": null}, {"def": "又如缒关(从关门旁缘绳而下);缒城(由城上以绳索垂至平地,缘之而下)", "example": null}, {"def": "拽;拉", "example": null}, {"def": "缒", "example": null}, {"def": "绳索", "example": null}, {"def": "登者六十人,缒绝,师鼓噪,城上之人亦噪。--《左传》", "example": null}, {"def": "又如缒绝(绳断);系缒(系结绳索)", "example": null}, {"def": "缒zhuì用绳索拴住人或物从高处往下送将这些砖块从楼上～下去。", "example": null}]','chinese-xinhua','0'),
