('2101143297081741328','隹','1','zhuī','隹','8',NULL,'[{"def": "隹", "example": null}, {"def": "(象形。甲骨文字形,象鸟形。《说文》鸟之短尾之总名也。”与鸟”同源。隹”是汉字的一个部首,从隹”的字与禽类有关。本义短尾鸟的总名)", "example": null}, {"def": "同本义", "example": null}, {"def": "隹,鸟之短尾总名也。--《说文》", "example": null}, {"def": "柘树的果实", "example": null}, {"def": "柘实曰隹。--崔豹《古今注》", "example": null}, {"def": "隹zhuī短尾巴鸟的总称。", "example": null}, {"def": "隹cuī 1.参见\\"畏隹\\"。", "example": null}, {"def": "隹wéi 1.助词。", "example": null}]','chinese-xinhua','0'),
('2101143297081741329','追','1','zhuī','辶','9',NULL,'[{"def": "追", "example": null}, {"def": "(本义追赶)", "example": null}, {"def": "同本义(使追赶对象回来)", "example": null}, {"def": "追,逐也。--《说文》", "example": null}, {"def": "以比追胥。--《周礼·小司徒》。注逐寇也。”", "example": null}, {"def": "公追戎于济西。--《左传·庄公十八年》", "example": null}, {"def": "驰车充国者,追寇之马也。--《管子·七臣七主》", "example": null}, {"def": "追亡逐北。--汉·贾谊《过秦论》", "example": null}, {"def": "壶子曰追之!”列子追之不及。--《庄子·应帝王》", "example": null}, {"def": "公使阳处父追之。--《左传·僖公三十三年》", "example": null}, {"def": "汉主追韩信,苍生起谢安。--唐·杜甫《宴王使君宅题二首》", "example": null}, {"def": "闻追豫州。--《资治通鉴》", "example": null}, {"def": "又", "example": null}, {"def": "追操至南郡。", "example": null}, {"def": "追购又急。--宋·文天祥《后序》", "example": null}, {"def": "又如穷寇勿", "example": null}, {"def": "追zhuī", "example": null}, {"def": "⒈赶，紧跟～赶。～逐。～随。～击。奋起直～。", "example": null}, {"def": "⒉查问，寻求，竭力探求～问。～求。～究责任。～本穷源。～根究底。", "example": null}, {"def": "⒊回顾过去～念。～悼。～溯。", "example": null}, {"def": "⒋事后补做～认。～加预算。", "example": null}, {"def": "追duī 1.钟纽。参见\\"追蠡\\"。 2.古代冠名。 3.通\\"雕\\"。雕琢。 4.通\\"堆\\"。小丘。", "example": null}]','chinese-xinhua','0'),
('2101143297081741330','骓','1','zhuī','马','11',NULL,'[{"def": "骓", "example": null}, {"def": "毛色苍白相杂的马", "example": null}, {"def": "骓,马苍黑杂毛也。从马,隹声。--《说文》", "example": null}, {"def": "苍白杂毛骓。--《尔雅·释畜》", "example": null}, {"def": "有骓有駓。--《诗·鲁颂·駉》", "example": null}, {"def": "三青马三骓。--《山海经·大荒东经》", "example": null}, {"def": "骏马名骓。--《汉书·项籍传》", "example": null}, {"def": "力拔山兮气盖世,时不利兮骓不逝。--《史记·项羽本纪》", "example": null}, {"def": "姓", "example": null}, {"def": "骓zhuī毛色青白混杂的马乌～。", "example": null}]','chinese-xinhua','0'),
('2101143297081741331','椎','1','zhuī','木','12',NULL,'[{"def": "椎", "example": null}, {"def": "(形声。从木,隹声。本义槌子,敲击的器具)", "example": null}, {"def": "捶击的工具◇亦为兵器", "example": null}, {"def": "椎,所以击也。--《说文》", "example": null}, {"def": "椎,棒椎也。--《广韵》", "example": null}, {"def": "杼上终葵首。--《考工记·玉人》。疏终葵,椎也。”", "example": null}, {"def": "又如椎拍(用椎拍击);椎斧(椎和斧);椎凿(槌子和凿子);椎锻(锤子和打铁用的砧石);椎额(额头突出如椎);椎塘(臼)", "example": null}, {"def": "椎髻。盘在头顶上的一种椎形高髻", "example": null}, {"def": "椎", "example": null}, {"def": "用椎打击", "example": null}, {"def": "椎,击也。--《说文》", "example": null}, {"def": "五日一椎牛。--《史记·张释之", "example": null}, {"def": "椎 chuí", "example": null}, {"def": "①同\'槌\'。", "example": null}, {"def": "②同\'捶\'。又见zhuī。", "example": null}, {"def": "【椎心泣血】手捶胸脯，眼睛因哭泣而红肿，像要流出血来了。形容万分悲痛的样子。", "example": null}, {"def": "椎chuí", "example": null}, {"def": "⒈敲击的器具铁～。木～。", "example": null}, {"def": "⒉用椎打击～鼓。～杀。", "example": null}, {"def": "⒊朴实，迟钝～鲁。", "example": null}, {"def": "椎zhuī", "example": null}, {"def": "⒈椎骨，脊椎骨。组成人和脊椎动物背部脊柱的短骨，可分颈～、胸～、腰～、骶～、尾～等。人的～骨共有三十三个。", "example": null}]','chinese-xinhua','0'),
('2101143297081741332','锥','1','zhuī','钅','13',NULL,'[{"def": "锥", "example": null}, {"def": "(形声。从金,隹声。本义钻孔的工具)", "example": null}, {"def": "同本义", "example": null}, {"def": "锥,锐也。--《说文》", "example": null}, {"def": "锥,利也。--《释名·释用器》", "example": null}, {"def": "引锥自刺其股。--《战国策·秦策一》", "example": null}, {"def": "锥之处囊中。--《史记·平原君虞卿列传》", "example": null}, {"def": "又如锥刀(用以雕刻的锥形小刀。比喻微小);锥矢(一种税利的短箭);锥囊(锥处囊中);锥行衰(立锥形);锥行之陈(前尖如锥的阵形);锥毛(喻细微之物);锥刀之末(比喻微小利", "example": null}, {"def": "益,也比喻小事)", "example": null}, {"def": "形如尖锥的东西", "example": null}, {"def": "疾如锥矢。--《淮南子·兵略》。注金镞翦羽之矢也。”", "example": null}, {"def": "冰销田地芦锥短,春入枝条柳眼低。--元稹《寄", "example": null}, {"def": "锥zhuī", "example": null}, {"def": "⒈一端尖锐可钻孔的工具圆～子。", "example": null}, {"def": "⒉形状像锥子的毛～（毛笔）。", "example": null}, {"def": "⒊用锥形的东西钻在这儿～个孔。", "example": null}]','chinese-xinhua','0'),
('2101143297081741333','准','1','zhǔn','冫','10',NULL,'[{"def": "准", "example": null}, {"def": "(准本为凖的俗字,现为凖的简化字。但在未简化前,准习用的意义,与凖字有别)", "example": null}, {"def": "公文用语", "example": null}, {"def": "乃于战所,准当时兵士,人种树一株,以旌武功。--《周书·文帝纪下》", "example": null}, {"def": "又如批准;照准;准如所请 (2) 引申为比照,作某类事物看待。如准前例办理;准平原;准尉 (3) 表示依据、根据。如准某部函", "example": null}, {"def": "决定,必定", "example": null}, {"def": "这准是使猛了劲,岔了气了。--《儿女英雄传》", "example": null}, {"def": "折充;抵充", "example": null}, {"def": "连身上外盖衣服,脱下准了店钱。--《醒世恒言》", "example": null}, {"def": "新旧钱暂兼行,新钱", "example": null}, {"def": "准zhǔn", "example": null}, {"def": "⒈允许，许可～许。～假。照～。", "example": null}, {"def": "⒉依照，按照～此制作。", "example": null}, {"def": "⒊跟某类事物相似的～平原。", "example": null}, {"def": "⒋法则，标准～则。按此为～。", "example": null}, {"def": "⒌通\\"埻\\"。箭靶。", "example": null}, {"def": "⒍测定水平的东西～绳。水～。", "example": null}, {"def": "⒎正确～确。说得～。放之四海皆～。", "example": null}, {"def": "⒏一定，确实她～来。～能按时到达。", "example": null}, {"def": "⒐鼻子隆（高）～。", "example": null}, {"def": "⒑把握这件事我没～儿。", "example": null}]','chinese-xinhua','0'),
