('2101143297081741339','肫','1','zhūn','月','8',NULL,'[{"def": "肫", "example": null}, {"def": "面颊", "example": null}, {"def": "肫,面颊也。--《说文》", "example": null}, {"def": "肫,俗谓之两颧也。--朱骏声《说文通训定声》", "example": null}, {"def": "禽类的胃", "example": null}, {"def": "臀", "example": null}, {"def": "胯大肫高,决片牛唇口,粗能饮村酒。--《刘知远诸宫调》", "example": null}, {"def": "肫", "example": null}, {"def": "恳切,真挚", "example": null}, {"def": "夫焉有所倚,肫肫其仁,渊渊其渊,浩浩其天。--《礼记·中庸》", "example": null}, {"def": "又如肫切(真诚恳切);肫宏(诚挚而宽宏);肫肫(诚恳);肫肫煦煦(形容恳挚而热忱)", "example": null}, {"def": "肫zhūn", "example": null}, {"def": "⒈鸟类的胃鸡～。鹅～。", "example": null}, {"def": "⒉恳切，真挚～笃。～ ～友谊。", "example": null}, {"def": "肫chún 1.古代祭祀用牲后体的一部分。 2.通\\"纯\\"。精密。参见\\"肫肫\\"。 3.通\\"纯\\"。整体。", "example": null}, {"def": "肫tún 1.小猪。", "example": null}]','chinese-xinhua','0'),
('2101143297081741340','窀','1','zhūn','穴','9',NULL,'[{"def": "窀穸", "example": null}, {"def": "惟汝之窀穸尚未谋耳。--清·袁枚《祭妹文》", "example": null}, {"def": "轮移北隍,窀穸东麓。--《文选·谢惠连·祭古冢文》", "example": null}, {"def": "窀zhūn", "example": null}]','chinese-xinhua','0'),
('2101143297081741341','谆','1','zhūn','讠','10',NULL,'[{"def": "谆", "example": null}, {"def": "(形声。本义教诲恳切耐心的样子)", "example": null}, {"def": "同本义。多叠用,也单用", "example": null}, {"def": "谆,告晓之熟也。--《说文》。字亦作詒。", "example": null}, {"def": "诲尔谆谆。--《诗·大雅·抑》", "example": null}, {"def": "不必谆谆。--《史记·司马相如传》。集解告之丁宁也。”", "example": null}, {"def": "天与之者,谆谆然命之乎?--《孟子》", "example": null}, {"def": "通使也与唐敖行礼,再再谆托。--《镜花缘》", "example": null}, {"def": "又如谆谆醇醇(恳切淳厚);谆谆教导;谆谕(谆谆告谕);谆熟(再三告诫要牢记在心)", "example": null}, {"def": "诚恳;忠诚", "example": null}, {"def": "谆谆忠谨之貌也。--《后汉书·卓茂传》注", "example": null}, {"def": "吾嫉惰游者,怜子愚且谆。--韩愈《送惠师》", "example": null}, {"def": "又如谆笃(诚恳笃实", "example": null}, {"def": "谆zhūn恳切。", "example": null}]','chinese-xinhua','0'),
