('2101143297081741356','茁','1','zhuó','艹','8',NULL,'[{"def": "茁", "example": null}, {"def": "(会意。从苃,从出,出亦声。本义植物才生长出来的样子)同本义", "example": null}, {"def": "茁,草初生出地貌。--《说文》", "example": null}, {"def": "彼茁者葭。--《诗·召南·驺虞》", "example": null}, {"def": "向东风种就,一亭兰茁,玉香初茂。--陈允平《过秦楼》", "example": null}, {"def": "又如茁茁(草刚长出的样子);茁茂(茂盛);茁肥(肥壮);茁实(扎实;健壮结实)", "example": null}, {"def": "茁", "example": null}, {"def": "生出;生长", "example": null}, {"def": "牛羊茁壮长而已矣。--《孟子》。注生长貌。”", "example": null}, {"def": "曝干则为干看蕈,今深山穷民以此代耕,殆天茁此品,以遗其利也。--王祯《农书》", "example": null}, {"def": "又如茁芽(发芽)", "example": null}, {"def": "绽开,开", "example": null}, {"def": "蠹树高枝茁朵稠,嫩苞开破雪搓球。--张建《咏梨花》", "example": null}, {"def": "茁zhuó植物初生的样子。又指动植物的生长～壮（壮盛，健壮）成长。", "example": null}, {"def": "茁zhú 1.草芽。", "example": null}]','chinese-xinhua','0'),
('2101143297081741357','斫','1','zhuó','斤','9',NULL,'[{"def": "斫", "example": null}, {"def": "(形声。从斤,石声。斤,斧属。本义斧刃)", "example": null}, {"def": "同本义", "example": null}, {"def": "斧以金为斫。--《墨子》", "example": null}, {"def": "大锄", "example": null}, {"def": "二月冰解地干,烧而耕之,仍即下水,十日块既散液,持木斫平之,纳种如前法。--《齐民要术》", "example": null}, {"def": "斫", "example": null}, {"def": "用刀、斧等砍劈", "example": null}, {"def": "因拔刀斫前奏案。--宋·司马光《资治通鉴》", "example": null}, {"def": "斫而为琴,弦而鼓之。--明·刘基《郁离子·千里马篇》", "example": null}, {"def": "斫直、删密、锄正。--清·龚自珍《病梅馆记》", "example": null}, {"def": "挥刀奋斫所当无不披靡。(奋斫尽力砍杀)--清·徐珂《清稗类钞·战事类》", "example": null}, {"def": "又如斫旗(砍倒彩旗);斫柴(砍柴);斫柴", "example": null}, {"def": "斫（斲）zhuó砍，削～削。～木。～轮老手（斫木制造车轮的老工人。〈喻〉经验丰富，技艺精湛的人）。", "example": null}]','chinese-xinhua','0'),
('2101143297081741358','浊','1','zhuó','氵','9',NULL,'[{"def": "浊", "example": null}, {"def": "(形声。从水,蜀声。本义浊水) 同本义", "example": null}, {"def": "浊水出齐郡厉伪山,东北入钜定。--《说文》。今曰北阳水。", "example": null}, {"def": "源出山东省益都县西南,北流注入小清河", "example": null}, {"def": "浊", "example": null}, {"def": "液体浑浊。与清”相对", "example": null}, {"def": "载清载浊。--《诗·小雅·四月》", "example": null}, {"def": "浑兮其若浊--《老子》", "example": null}, {"def": "蝉蜕于浊秽。--《史记·屈原贾生列传》", "example": null}, {"def": "浊浪排空。--宋·范仲淹《岳阳楼记》", "example": null}, {"def": "又如浊河(混浊的河流。特指黄河);浊酒(用糯米、黄米等酿制的酒,较混浊)", "example": null}, {"def": "脏,不干净", "example": null}, {"def": "雨门延风凉,洗我昏浊肌。--姚合《过张邯郸庄》", "example": null}, {"def": "又如浊醪(浊酒);浊污(污秽);浊秽(污", "example": null}, {"def": "浊（濁）zhuó", "example": null}, {"def": "⒈水不清，水不干净，跟\\"清\\"相对～流。浑～。〈引〉声音低沉粗重～声。～音（发音时，声带颤动）。", "example": null}, {"def": "⒉混乱～世（混乱的时代）。", "example": null}]','chinese-xinhua','0'),
('2101143297081741359','浞','1','zhuó','氵','10',NULL,'[{"def": "浞", "example": null}, {"def": "沾湿;浸渍", "example": null}, {"def": "浞,水湿。--《广雅》", "example": null}, {"def": "又如浞浞(浸湿的样子)", "example": null}, {"def": "浞", "example": null}, {"def": "富足", "example": null}, {"def": "浞,转注为饶益之意,经传皆以足”为之。--朱骏声《说文通训定声》", "example": null}, {"def": "浞zhuó淋，使湿遭雨～了。", "example": null}]','chinese-xinhua','0'),
('2101143297081741360','诼','1','zhuó','讠','10',NULL,'[{"def": "诼", "example": null}, {"def": "(形声。从言,豿声。本义造谣,谗谤) 同本义", "example": null}, {"def": "众女嫉余之蛾眉兮,谣诼谓余以善淫。--《楚辞》", "example": null}, {"def": "被诼谮兮虚获尤。--王逸《九思·逢尤》", "example": null}, {"def": "又如诼潜(造谣诬陷);诼谣(毁谤)", "example": null}, {"def": "诼zhuó造谣，毁谤谣～。", "example": null}]','chinese-xinhua','0'),
('2101143297081741361','酌','1','zhuó','酉','10',NULL,'[{"def": "酌", "example": null}, {"def": "(形声。从酉,从勺,勺亦声。从酉”与酒有关。本义斟酒)", "example": null}, {"def": "同本义", "example": null}, {"def": "酌,盛酒行觞也。--《说文》", "example": null}, {"def": "尸升,坐取爵酌。--《仪礼·有司彻》。", "example": null}, {"def": "酒曰清酌。--《礼记·曲礼》", "example": null}, {"def": "缩酌用茅。--《礼记·郊特牲》", "example": null}, {"def": "盖酌之也。--《公羊传·僖公八年》", "example": null}, {"def": "及祭,酌仆。--《周礼·夏官》", "example": null}, {"def": "引壶觞以自酌。--晋·陶渊明《归去来兮辞》", "example": null}, {"def": "因命酌互举。--唐·李朝威《柳毅传》", "example": null}, {"def": "以我酌油知之。--宋·欧阳修《归田录》", "example": null}, {"def": "以钱覆其口,徐以杓酌油沥之。--欧阳修《卖油翁》", "example": null}, {"def": "无多酌我,我乃酒狂。--《汉书·盖宽饶传》", "example": null}, {"def": "又如", "example": null}, {"def": "酌zhuó", "example": null}, {"def": "⒈斟酒自～。对～。〈引〉酒宴小～。便～。", "example": null}, {"def": "⒉考虑，权衡～量。斟～。～情处理。", "example": null}]','chinese-xinhua','0'),
('2101143297081741362','啄','1','zhuó','口','11',NULL,'[{"def": "啄", "example": null}, {"def": "(形声。从口,豿声。本义鸟用嘴取食)", "example": null}, {"def": "同本义", "example": null}, {"def": "啄,鸟食也。--《说文》", "example": null}, {"def": "啄啮也。--《广雅》", "example": null}, {"def": "谁家燕子啄春泥。--唐·白居易《钱塘湖春行》", "example": null}, {"def": "檐牙高啄。--唐·杜牧《阿房宫赋》", "example": null}, {"def": "径进以啄。--《聊斋志异·促织》", "example": null}, {"def": "又", "example": null}, {"def": "幸啄不中。", "example": null}, {"def": "又如啄抱(禽鸟幼雏破壳而出);啄啄(禽鸟取食的样子);啄饮(啄食饮水);啄噪(啄食鸣叫);啄木", "example": null}, {"def": "用嘴理", "example": null}, {"def": "敲击", "example": null}, {"def": "归来残月窥窗角,星初落,几回欲把朱扉啄,人知觉。--潘必正《杨柳枝》", "example": null}, {"def": "咬", "example": null}, {"def": "虎豹九关,啄害下人些。--《楚辞·宋玉·招魂》", "example": null}, {"def": "啄zhuó", "example": null}, {"def": "⒈鸟类用嘴扣击并夹取东西鸡～食。～木鸟～虫。", "example": null}, {"def": "⒉", "example": null}, {"def": "啄zhòu 1.鸟嘴。", "example": null}]','chinese-xinhua','0'),
