('2101143297081741382','字','1','zì','子','6',NULL,'[{"def": "字", "example": null}, {"def": "(会意兼形声。从宀从子,子亦声。在屋内生孩子。本义生孩子)", "example": null}, {"def": "同本义", "example": null}, {"def": "字,乳也。--《说文》。", "example": null}, {"def": "字,生也。--《广雅》", "example": null}, {"def": "妇人疏字者子活,数乳者子死。--《论衡·气寿》", "example": null}, {"def": "六畜遂字。--《汉书》。颜师古注字,生也。”", "example": null}, {"def": "苦山有木,服之不字。--《山海经·中山经》", "example": null}, {"def": "亭有畜字马,岁课息。--《汉书·食货志下》", "example": null}, {"def": "又如字乳(生育);字育(生育、蕃育)", "example": null}, {"def": "怀孕,体内怀着胎儿", "example": null}, {"def": "女子贞不字,十年乃字。--《易·屯》", "example": null}, {"def": "乘字牝者,傧而不得聚会。--《史记·平准书》", "example": null}, {"def": "又如字牝(怀孕的母畜);字孕(怀胎;生殖)", "example": null}, {"def": "字zì", "example": null}, {"def": "⒈记录语言的符号～体『～。难～。拼音～。", "example": null}, {"def": "⒉音咬～清楚。～正腔圆。", "example": null}, {"def": "⒊字的形体柳～。正楷～。", "example": null}, {"def": "⒋书法作品～画。", "example": null}, {"def": "⒌用文字写成的条据、凭证、契约等～条。～据。", "example": null}, {"def": "⒍人的姓名或别名（也叫表字或号）签～。刘备～玄德。", "example": null}, {"def": "⒎旧时称女子许嫁待～。", "example": null}, {"def": "⒏生子，〈引〉养育妇人疏～者子活（疏稀疏）。", "example": null}, {"def": "⒐", "example": null}, {"def": "字义未详。", "example": null}]','chinese-xinhua','0'),
('2101143297081741383','自','1','zì','自','6',NULL,'[{"def": "自", "example": null}, {"def": "(象形。小篆字形。象鼻形。自”是汉字的一个部首。本义鼻子)", "example": null}, {"def": "同本义", "example": null}, {"def": "自,鼻也。--《说文》。段玉裁注许谓自与鼻义同音同,而用自为鼻者绝少也。”", "example": null}, {"def": "始;开头", "example": null}, {"def": "故法者,王之本也;刑者,爱之自也。--《韩非子》", "example": null}, {"def": "起源", "example": null}, {"def": "知风之自,知微之显,可以入德也。--《礼记》", "example": null}, {"def": "又如自顷(近来)", "example": null}, {"def": "自", "example": null}, {"def": "自己,自我;本身", "example": null}, {"def": "不自为政,卒劳百姓。--《诗·小雅 ·节南山》", "example": null}, {"def": "自引而起,绝袖。--《战国策·燕策》", "example": null}, {"def": "人必自侮,然后人侮之;家必自毁,而后人毁之;国必自伐,而后人伐之。--《", "example": null}, {"def": "自zì", "example": null}, {"def": "⒈本人，己身～己。亲～。～作～受。～成一家。～强不息。", "example": null}, {"def": "⒉从，由～从。～始至终。～成都到武汉。", "example": null}, {"def": "⒊当然～属无妨。～有话说。", "example": null}, {"def": "⒋", "example": null}, {"def": "⒌", "example": null}, {"def": "①自己主动。", "example": null}, {"def": "②不依靠人为的力量水会～动下流。", "example": null}, {"def": "③全部是机械操作～动化。", "example": null}, {"def": "⒍", "example": null}, {"def": "①自己负担。", "example": null}, {"def": "②自以为了不起。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "①天然存在的～然界。", "example": null}, {"def": "②不造作，不勉强听凭～然。", "example": null}, {"def": "③当然～然好办。", "example": null}, {"def": "⒐", "example": null}, {"def": "①自己感觉到。", "example": null}, {"def": "②自己认识和觉悟到～觉地遵纪守法。", "example": null}, {"def": "⒑", "example": null}, {"def": "⒒", "example": null}, {"def": "⒓", "example": null}, {"def": "⒔", "example": null}, {"def": "①自己制造。", "example": null}, {"def": "②克制自己。", "example": null}, {"def": "⒕", "example": null}, {"def": "⒖", "example": null}, {"def": "⒗", "example": null}, {"def": "①不受约束，不受限制请大家～由发表意见。", "example": null}, {"def": "②在法律规定的范围内，随自己意愿活动的权利人身～由。～由选举。", "example": null}, {"def": "③哲学上指人们在实践中认识了客观规律并能掌握它，自觉地运用它来改造世界。", "example": null}, {"def": "⒘", "example": null}, {"def": "⒙", "example": null}]','chinese-xinhua','0'),
