('2101143297081741389','渍','1','zì','氵','11',NULL,'[{"def": "渍", "example": null}, {"def": "(本义短时间浸泡)", "example": null}, {"def": "同本义", "example": null}, {"def": "渍,沤也。--《说文》", "example": null}, {"def": "剥削淹渍以为菹。--《诗·楚茨》笺", "example": null}, {"def": "水浸曰渍。--《通俗文》", "example": null}, {"def": "《神农》、《后稷》藏种之方,煮马屎以渍种者。--《论语·商虫》", "example": null}, {"def": "净淘种子,渍经三宿。--贾思勰《齐民要术》", "example": null}, {"def": "又如渍酒(浸泡在酒里);渍痕(水侵蚀的污迹);渍渍(满是汗水或泪水的样子)", "example": null}, {"def": "冲洗", "example": null}, {"def": "染", "example": null}, {"def": "钟氏染羽以朱湛丹秫,三月而炽之,淳而渍之。--《周礼·考工记·钟氏》", "example": null}, {"def": "又如渍浸(浸染)", "example": null}, {"def": "沾染", "example": null}, {"def": "飞毛遍绿野,洒血渍芳丛。", "example": null}, {"def": "渍zì", "example": null}, {"def": "⒈浸，泡～豆。～麻。淹～。", "example": null}, {"def": "⒉染渐～。", "example": null}, {"def": "⒊积水～水。排～。", "example": null}, {"def": "⒋积在物体上难于除去的油、泥、污垢等油～。墨～。", "example": null}, {"def": "渍sè 1.雨或泪洒落。", "example": null}]','chinese-xinhua','0'),
('2101143297085935616','眦','1','zì','目','11',NULL,'[{"def": "眦", "example": null}, {"def": "(形声。从目,此声。本义眼角)", "example": null}, {"def": "同本义", "example": null}, {"def": "眥,目厓也。--《说文》", "example": null}, {"def": "拭眥扬眉而望之。--《列子·汤问》", "example": null}, {"def": "目赤痛眥疡。--《素问·气交变大论》", "example": null}, {"def": "瞋目视项王,头发上指,目眦尽裂。--《史记·项羽本纪》", "example": null}, {"def": "泛指眼睛", "example": null}, {"def": "眼眶", "example": null}, {"def": "中必决眦。--司马相如《子虚赋》", "example": null}, {"def": "又如眦裂(张目怒视,眼眶破裂)", "example": null}, {"def": "眦睚", "example": null}, {"def": "以眦睚杀之。--宋·王谠《唐语林·雅量》", "example": null}, {"def": "眦（眥）zì上下眼睑交结处。近鼻的叫内～。近脸侧鬓发的叫外～。", "example": null}]','chinese-xinhua','0'),
