('2101143297090129934','觜','1','zī','角','13',NULL,'[{"def": "觜  zi", "example": null}, {"def": "即觜宿", "example": null}, {"def": "名。觜宿”的早期名称);觜陬(十二星次之一)", "example": null}, {"def": "觜  zui", "example": null}, {"def": "猫头鹰类头上的毛角", "example": null}, {"def": "段玉裁注角觜,萑下云‘毛角’是也。毛角,头上毛似角者也。”", "example": null}, {"def": "鸟嘴", "example": null}, {"def": "裂膆破觜。--潘岳《射雉赋》", "example": null}, {"def": "秦政利觜长距,终得擅场。--《文选·张衡·东京赋》", "example": null}, {"def": "觜銛剑戟,爪握刀锥。--唐·李白《壁画苍鹰赞》", "example": null}, {"def": "又如觜吻(某些动物头部向前突出", "example": null}, {"def": "觜zuǐ", "example": null}, {"def": "⒈同\\"嘴\\"。", "example": null}, {"def": "觜zī", "example": null}, {"def": "⒈星宿名。二十八宿之一。", "example": null}]','chinese-xinhua','0'),
('2101143297090129935','趑','1','zī','走','13',NULL,'[{"def": "趑趄", "example": null}, {"def": "一人荷锄,万夫趑趄。--张载《剑阁铭》", "example": null}, {"def": "彼则趑趄于卿士之门,我则婆娑于圣贤之域。--皇浦湜《谕业》", "example": null}, {"def": "陈顼因循伪业,自擅金陵,屡遣丑徒,趑趄江北。--《隋书》", "example": null}, {"def": "趑zī", "example": null}]','chinese-xinhua','0'),
('2101143297090129936','锱','1','zī','钅','13',NULL,'[{"def": "锱", "example": null}, {"def": "(形声。从金,甾声。本义古代的重量单位) 同本义", "example": null}, {"def": "锱,六铢也。--《说文》", "example": null}, {"def": "锱锤之冠。--《淮南子·说山》", "example": null}, {"def": "八铢为锱。--《广韵》", "example": null}, {"def": "铢六则锤,锤晖也;二锤则锱,锱炽也;二锱则两也。--《风俗风义》", "example": null}, {"def": "虽分国如锱铢。--《礼记·儒行》。郑玄注八两曰锱。”", "example": null}, {"def": "说法不一。等于6铢、8铢、12铢、6两或8两不等。引申为微小。如锱毫(比喻细微处);锱介(比喻微小);锱锤(比喻微小之物);锱铢不爽(分毫不差)", "example": null}, {"def": "锱铢", "example": null}, {"def": "奈", "example": null}, {"def": "锱zī〈古〉重量单位。一说\\"六铢\\"为\\"一锱\\"，\\"四锱\\"为\\"一两\\"。", "example": null}]','chinese-xinhua','0'),
