('2101143297094324224','滋','1','zī','氵','12',NULL,'[{"def": "滋", "example": null}, {"def": "滋水", "example": null}, {"def": "滋水出牛饮山白陉谷,东入呼沱。从水,兹声。--《说文》", "example": null}, {"def": "一名兹水,今名磁河。源出河北省阜平县西部南坨山东,今为潴龙河支流", "example": null}, {"def": "浆,液汁", "example": null}, {"def": "墨井盐池,玄滋素液。--左思《魏都赋》", "example": null}, {"def": "流光驿驿,甘滋泥泥。--邹阳《酒赋》", "example": null}, {"def": "滋味", "example": null}, {"def": "丧有疾,食肉饮酒,必有草木之滋焉,以为姜桂之谓也。--《礼记》", "example": null}, {"def": "滋", "example": null}, {"def": "通孳”。滋生;繁殖", "example": null}, {"def": "滋,益也。--《说文》", "example": null}, {"def": "无使滋蔓。--《左传·隐公元年》。服注益也。”", "example": null}, {"def": "草木庳小不滋。--《吕氏春秋·明理》", "example": null}, {"def": "事滋无成。--《左传·襄公八", "example": null}, {"def": "滋zī", "example": null}, {"def": "①滋生；生长。", "example": null}, {"def": "②栽种；培植。", "example": null}, {"def": "③增长；增加。", "example": null}, {"def": "④润泽；浸染。", "example": null}, {"def": "⑤繁盛；茂盛。", "example": null}, {"def": "⑥水；汁液。", "example": null}, {"def": "⑦美味；滋味。", "example": null}, {"def": "⑧谓调和滋味。", "example": null}, {"def": "⑨愈益；更加。", "example": null}, {"def": "⑩喷射。", "example": null}, {"def": "⑾黑；污浊。《左传．哀公八年》\\"初，武城人或有因於吴竟田焉，拘鄫人之漚菅者，曰\'何故使吾水滋？\'\\"杜预注\\"滋，浊也。", "example": null}, {"def": "⑿方言。快活；高兴。", "example": null}, {"def": "⒀通\\"慈\\"。慈爱；体恤。", "example": null}, {"def": "⒁水名。即今河北省磁河。", "example": null}, {"def": "⒂水名。陕西省渭河支流灞河的古名。", "example": null}, {"def": "⒂泉名。在渭水。", "example": null}]','chinese-xinhua','0'),
('2101143297094324225','粢','1','zī','米','12',NULL,'[{"def": "粢", "example": null}, {"def": "(形声。从米,次声。本义古代供祭祀用的谷物)", "example": null}, {"def": "稷,即谷子", "example": null}, {"def": "粢,稷米也。--《玉篇》", "example": null}, {"def": "又如粢粝(粗劣的饭食)", "example": null}, {"def": "特指祭祀用的谷物", "example": null}, {"def": "谷类的总称", "example": null}, {"def": "上帝之粢盛于是乎出。--《国语》", "example": null}, {"def": "粢zī〈古〉1供祭祀用的谷物。2稻饼。", "example": null}]','chinese-xinhua','0'),
