('2101143297094324270','奏','1','zòu','大','9',NULL,'[{"def": "奏", "example": null}, {"def": "(会意。小篆字形。上为屮”,初生的草,有上进义;中为双手形;下为本”,行趋之义。本义奉献,送上)", "example": null}, {"def": "同本义", "example": null}, {"def": "奏,进也。--《说文》", "example": null}, {"def": "敷奏以言。--《虞书》", "example": null}, {"def": "以奏肤公。--《诗·小雅·六月》", "example": null}, {"def": "各奏尔能。--《诗·小雅·宾之初筵》", "example": null}, {"def": "予乘四载,随水刊木,既益奏庶鲜食。--《书·益稷》", "example": null}, {"def": "相如奉璧奏秦王。--《史记·廉颇蔺相如列传》", "example": null}, {"def": "使奏其技。--清·黄宗羲《柳敬亭传》", "example": null}, {"def": "以夏进炉,以冬奏扇。--《论衡·逢遇》", "example": null}, {"def": "燕姬奏妙舞,郑女发清歌。--萧纪《同萧长史看妓》", "example": null}, {"def": "俟封奏时潜易之而己。--方苞《狱中杂记》", "example": null}, {"def": "奏zòu", "example": null}, {"def": "⒈作乐，按照曲调吹打乐器～乐。伴～。独～。", "example": null}, {"def": "⒉呈现，取得～效。～捷。", "example": null}, {"def": "⒊〈古〉指向君王进言或上书～本。～章。", "example": null}, {"def": "奏zǒu 1.奔走。 2.趋向。", "example": null}, {"def": "奏còu 1.通\\"凑\\"。聚集﹔会合。 2.通\\"腠\\"。皮肤的纹理。", "example": null}]','chinese-xinhua','0'),
('2101143297094324271','揍','1','zòu','扌','12',NULL,'[{"def": "揍", "example": null}, {"def": "(形声。从手,奏声。本义打)", "example": null}, {"def": "揍zòu", "example": null}, {"def": "⒈打，打击。", "example": null}, {"def": "⒉〈方〉打碎。", "example": null}, {"def": "揍còu 1.插。 2.同\\"腠\\"。肌肉的纹理。 3.通\\"凑\\"。凑集。", "example": null}]','chinese-xinhua','0'),
