('2101143297094324278','鄹','1','zōu','阝','16',NULL,'[{"def": "鄹", "example": null}, {"def": "古邑名", "example": null}, {"def": "鄖,鲁下邑。孔子之乡。从邑,取声。--《说文》。字亦作鄹。在今山东兖州府邹县西北之东邹邨、西邹集、孔子生于鄖之阙里,长徒曲阜,仍号阙里。", "example": null}, {"def": "又如鄹里(孔子故里);鄹阙(鄹里和阙里的并称。鄹里,孔子故里)", "example": null}, {"def": "鄹zōu", "example": null}, {"def": "①古邑名。春秋鲁国地。孔子家乡。在今山东省曲阜市东南。", "example": null}, {"def": "②同\\"鄒\\"。古国名。", "example": null}]','chinese-xinhua','0'),
('2101143297094324279','鲰','1','zōu','鱼','16',NULL,'[{"def": "鲰", "example": null}, {"def": "小鱼,小杂鱼", "example": null}, {"def": "鲰,白鱼也。--《说文》。按,白小鱼。", "example": null}, {"def": "鲰千石,鲍千钧。--《史记·货殖列传》", "example": null}, {"def": "又如鲰鲜(小杂鱼);鲰鳞(小杂鱼)", "example": null}, {"def": "鲰", "example": null}, {"def": "浅陋;愚昧", "example": null}, {"def": "鲰生说我。--《史记·项羽本纪》。服虔注鲰,小人貌也。”", "example": null}, {"def": "又如鲰儒(穷酸的儒士);鲰愚(浅陋愚昧);鲰浅(浅薄)", "example": null}, {"def": "鲰zōu", "example": null}, {"def": "⒈杂小鱼。", "example": null}, {"def": "⒉", "example": null}, {"def": "①〈古〉用于骂人的词，指卑小愚陋的人。", "example": null}, {"def": "②〈古〉作为自称的谦词。", "example": null}]','chinese-xinhua','0'),
('2101143297094324280','齺','1','zōu','','7',NULL,'[{"def": "齺zōu 1.牙齿咬物时上下相交切貌。比喻往来交错。 2.牙齿咬物时上下相交切貌。比喻上下相迎。", "example": null}]','chinese-xinhua','0'),
('2101143297094324281','邹','1','zōu','阝','7',NULL,'[{"def": "邹", "example": null}, {"def": "古国名", "example": null}, {"def": "邹,鲁县古邾国,帝颛顼之后所封。--《说文》。朱按,曹姓。邹者,邾娄之合音,战国时穆公改号邾娄为邹,后为楚所灭,若今济南府邹平县之邹。", "example": null}, {"def": "邹人与楚人战。--《孟子·梁惠王上》", "example": null}, {"def": "又", "example": null}, {"def": "邹敌楚战。", "example": null}, {"def": "通驺”", "example": null}, {"def": "姓", "example": null}, {"def": "邹忌讽齐王纳谏。(邹忌,齐国人,善鼓琴,有辩才。曾为齐相,封成侯。讽用含蓄的话劝告或讽喻。纳采纳,", "example": null}, {"def": "邹（鄒）zōu周代诸侯国名，又叫\\"邾\\"。在今山东省邹县一带。", "example": null}, {"def": "邹jù 1.颜浊邹，人名。", "example": null}]','chinese-xinhua','0'),
('2101143297094324282','驺','1','zōu','马','8',NULL,'[{"def": "驺", "example": null}, {"def": "(形声。从马,刍声。本义主驾车马的小吏)", "example": null}, {"def": "同本义", "example": null}, {"def": "驺,厩御也。--《说文》", "example": null}, {"def": "命仆及七驺咸驾。--《礼记·月令》", "example": null}, {"def": "于嗟乎驺虞。--《诗·召南·驺虞》", "example": null}, {"def": "孟氏之御驺。--《左传·襄公二十三年》。疏掌马之官,兼掌御事,谓之御驺。”", "example": null}, {"def": "武士驺比外郎。--《汉书·惠帝纪》", "example": null}, {"def": "使训群驺知礼。--《左传》", "example": null}, {"def": "又如驺卒(掌管车马的奴仆);驺御(驾驭车马的人);驺皂(养马驾车的差役)", "example": null}, {"def": "骑士,侍从", "example": null}, {"def": "黄门从官驺蹋踧蕃曰死老魅!复能损我曹员数,寺我曹禀假不?--《后汉书》", "example": null}, {"def": "又如", "example": null}, {"def": "驺（騶）zōu〈古〉", "example": null}, {"def": "⒈养马的人，也兼管赶车。", "example": null}, {"def": "⒉骑马的侍从～从。", "example": null}, {"def": "驺zhū 1.古地名。在今山东省邹县。", "example": null}, {"def": "驺zhòu 1.迅疾。", "example": null}, {"def": "驺qū 1.快走。", "example": null}]','chinese-xinhua','0'),
('2101143297094324283','诹','1','zōu','讠','10',NULL,'[{"def": "诹", "example": null}, {"def": "(形声。从言,取声。本义咨询;询问)", "example": null}, {"def": "同本义(征求关于祭祀、征伐或行政管理方面的意见)", "example": null}, {"def": "诹,聚谋也。--《说文》", "example": null}, {"def": "诹,谋也。--《尔雅》", "example": null}, {"def": "周爰咨诹。--《诗·小雅·皇皇者华》", "example": null}, {"def": "咨事为诹。--《左传·襄公四年》", "example": null}, {"def": "咨才为诹。--《国语·鲁语》", "example": null}, {"def": "以咨诹善道。--诸葛亮《出师表》", "example": null}, {"def": "又如诹访(咨询);诹咨(询问);诹询(咨询)", "example": null}, {"def": "挑选", "example": null}, {"def": "特牲馈食之礼,不诹日。--《仪礼》", "example": null}, {"def": "又如诹日(诹吉。选择吉日)", "example": null}, {"def": "商议", "example": null}, {"def": "预柬凡十有八人,德棻为先进,故类例多所诹定。--《新", "example": null}, {"def": "诹zōu商议～吉（商订好日子）。〈引〉询问谘～善道。", "example": null}]','chinese-xinhua','0'),
('2101143297094324284','陬','1','zōu','阝','10',NULL,'[{"def": "陬", "example": null}, {"def": "(形声。从阜(鑦??),取声。阜”是土山,与区域有关。本义山的角落)", "example": null}, {"def": "同本义", "example": null}, {"def": "陬,阪隅也。--《说文》", "example": null}, {"def": "陬,角也。--《广雅》", "example": null}, {"def": "在陵之诹。--《补亡诗》", "example": null}, {"def": "五岳之土…若在陬,陵之阳。--《管子》", "example": null}, {"def": "归路意昏,落日在岭陬。--杨万里《次日醉归》", "example": null}, {"def": "隅,", "example": null}, {"def": "又如陬隅(室内西南角);陬维(边隅,角隅)", "example": null}, {"def": "春秋鲁地。在今山东曲阜东南", "example": null}, {"def": "孔子生鲁昌平乡陬邑。--《史记》", "example": null}, {"def": "边远偏僻的地方", "example": null}, {"def": "其荒陬谲诡。--左思《吴都赋》", "example": null}, {"def": "监土木于僻陬,绝交通于首", "example": null}, {"def": "陬zōu角，角落。〈引〉山脚。", "example": null}]','chinese-xinhua','0'),
('2101143297094324285','鄖','1','zōu','阝','10',NULL,'[{"def": "姓", "example": null}, {"def": "鄖zōu 1.春秋鲁地，孔子乡邑。在今山东曲阜东南。", "example": null}]','chinese-xinhua','0'),
('2101143297098518528','足','1','zú','足','7',NULL,'[{"def": "足", "example": null}, {"def": "(会意。甲骨文字形,上面的方口象膝,下面的止”即脚,合起来指整个脚。本义脚)", "example": null}, {"def": "(同本义。秦汉以前,足”和’趾”都表示脚”;脚”表示小腿。魏晋以后,三者都表示脚,但在书面语中,多用足”)", "example": null}, {"def": "足,人之足也,在下,从止口。--《说文》。按,膝下至跖之总名也。从止,即趾字,从口,象膝形。", "example": null}, {"def": "震为足。--《易·说卦》", "example": null}, {"def": "足恭而口圣。--《大戴礼记》", "example": null}, {"def": "手足胼胝,面目黧。--《韩非子·外储说左上》", "example": null}, {"def": "郑人有欲买履者,先自度其足而置之其坐。--《韩非子》", "example": null}, {"def": "假舆马者,非利足也,而致千里。--《荀子·劝学》", "example": null}, {"def": "折臂断足。--清", "example": null}, {"def": "足zú", "example": null}, {"def": "⒈脚～迹。手舞～蹈。", "example": null}, {"def": "⒉满，够量，充分满～。～够。充～。富～。", "example": null}, {"def": "⒊补上补～。以昼～夜。", "example": null}, {"def": "⒋完全此项工作一人～可完成。", "example": null}, {"def": "⒌尽情地，尽量地他们～玩了半天。", "example": null}, {"def": "⒍值得不～为奇。微不～道。", "example": null}, {"def": "⒎够得上这本书～有八万字。", "example": null}, {"def": "⒏", "example": null}, {"def": "足jù 1.(今读zú)补足;凑满。 2.拥，增益。参见\\"足本\\"。 3.过分。参见\\"足恭\\"。", "example": null}]','chinese-xinhua','0'),
('2101143297098518529','卒','1','zú','十','8',NULL,'[{"def": "卒  cu", "example": null}, {"def": "同猝”。仓促,急速", "example": null}, {"def": "行西逾陇卒。--《汉书·食货志》。注仓卒也。”", "example": null}, {"def": "兴卒暴之作。--《汉书·成帝纪》", "example": null}, {"def": "而卒惶急无以击轲,而乃以手共搏之。--《战国策·燕策》", "example": null}, {"def": "又如卒拔(仓猝攻取);卒迫(仓促紧迫)", "example": null}, {"def": "突然", "example": null}, {"def": "则亡以应卒。--《汉书·辛庆忌传》", "example": null}, {"def": "卒然边境有急,数千百万之众,国胡以馈之?--贾谊《论积贮疏》", "example": null}, {"def": "又如卒倒(突然晕倒);卒暴(突然);卒然(忽然,突然)", "example": null}, {"def": "卒  zu", "example": null}, {"def": "(指事。小篆字形,在衣”上加一点标记,表示穿这种衣服的人。本义古代供隶役穿的一种衣服。衣上著有标记,以区别于常人)", "example": null}, {"def": "卒 cù同\'猝\'。又见zú。", "example": null}, {"def": "卒zú", "example": null}, {"def": "⒈兵士～。小～。", "example": null}, {"def": "⒉旧称差役狱～。走～。", "example": null}, {"def": "⒊死病～。", "example": null}, {"def": "⒋完毕，结束～业。语～。", "example": null}, {"def": "⒌终于～成大业。", "example": null}, {"def": "卒cuì 1.通\\"倅\\"。副职。 2.通\\"萃\\"。聚集。", "example": null}, {"def": "卒zuó 1.争斗。", "example": null}]','chinese-xinhua','0'),
