('2101143297098518595','怍','1','zuò','忄','8',NULL,'[{"def": "怍", "example": null}, {"def": "惭愧", "example": null}, {"def": "怍,惭也。从心,作省声。--《说文》。按,乍声。", "example": null}, {"def": "容无怍。--《礼记·曲礼》", "example": null}, {"def": "孝子临尸而不怍。--《礼记·祭义》", "example": null}, {"def": "灵公心怍焉。--《公羊传·宣公六年》", "example": null}, {"def": "自憎惭怍。--《聊斋志异·促织》", "example": null}, {"def": "面色改变", "example": null}, {"def": "颜色毋怍。--《管子·弟子职》。注谓变其容貌。”", "example": null}, {"def": "将即席,容毋怍。--《礼记·曲礼》", "example": null}, {"def": "怍zuò惭愧，脸面变色愧～。面无～色。", "example": null}]','chinese-xinhua','0'),
('2101143297098518596','祚','1','zuò','礻','9',NULL,'[{"def": "祚", "example": null}, {"def": "(形声。从示,乍声。本义福;福运)", "example": null}, {"def": "同本义", "example": null}, {"def": "若能类善物,以混厚民人者,必有章誉蕃育之祚。--《国语》", "example": null}, {"def": "今当祚永运隆之日,太平无为之世。--《红楼梦》", "example": null}, {"def": "真主已出,隋祚不长。--《隋唐演义》", "example": null}, {"def": "又如祚长(福运久长);祚薄(福分微薄);祚土(福地;疆土);祚胤(福运及于后代子孙);祚庆(福祐)", "example": null}, {"def": "帝位", "example": null}, {"def": "往者王莽作逆,汉祚中缺。--《东都赋》", "example": null}, {"def": "祚", "example": null}, {"def": "赐福", "example": null}, {"def": "天祚明德。--《左传》", "example": null}, {"def": "皇天嘉之,祚以天下。--《国语》", "example": null}, {"def": "今吾兄嗣位未几,辄思篡汉,皇天必不祚尔!--《全图绣像三国演义》", "example": null}, {"def": "又", "example": null}, {"def": "祚zuò", "example": null}, {"def": "⒈福，赐福。", "example": null}, {"def": "⒉通\\"阼\\"。皇帝的地位陛下践～（践祚即位）。", "example": null}]','chinese-xinhua','0'),
('2101143297098518597','胙','1','zuò','月','9',NULL,'[{"def": "胙", "example": null}, {"def": "(形声。从肉,乍声。本义祭祀用的肉)", "example": null}, {"def": "同本义", "example": null}, {"def": "胙,祭福肉也。--《说文》", "example": null}, {"def": "夏曰福胙。--《尔雅》", "example": null}, {"def": "王使宰孔赐齐侯胙。--《左传·僖公九年》", "example": null}, {"def": "彻王之胙俎。--《周礼·膳夫》。注主人饮食之俎皆为胙俎。”", "example": null}, {"def": "祝凫已疵献胙。--《管子·小问》", "example": null}, {"def": "太子祭于曲沃,归胙于公。--《左传·僖公四年》", "example": null}, {"def": "将军胙土分茅。(古代帝王分封诸侯,用五色土筑坛,一方一色,分封某方的诸侯,就用白茅包取某方的土,连同祭肉授给他,这就叫做胙土分茅”。)--清·邵长蘅《青门剩稿", "example": null}, {"def": "》", "example": null}, {"def": "又如胙肉(祭祀时供神的肉);胙侑(赐以祭肉,", "example": null}, {"def": "胙zuò", "example": null}, {"def": "⒈〈古〉祭祀用的肉。", "example": null}, {"def": "⒉赏赐。", "example": null}]','chinese-xinhua','0'),
('2101143297098518598','唑','1','zuò','口','10',NULL,'[{"def": "唑", "example": null}, {"def": "氮杂茂", "example": null}, {"def": "小类(如二唑类、三唑类、噻唑类)", "example": null}, {"def": "唑zuò", "example": null}, {"def": "唑shì 1.啮;吃。", "example": null}, {"def": "唑zuò", "example": null}, {"def": "唑shì 1.啮;吃。", "example": null}, {"def": "唑zuò", "example": null}, {"def": "唑shì 1.啮;吃。", "example": null}]','chinese-xinhua','0'),
('2101143297098518599','座','1','zuò','广','10',NULL,'[{"def": "座", "example": null}, {"def": "(形声。从广,坐声。坐”的后起字。本义座位)", "example": null}, {"def": "同本义。供人坐的地方,也指位置,座次", "example": null}, {"def": "隔座送钩春酒暖。--唐·李商隐《无题》", "example": null}, {"def": "座上有健啖客。--明·魏禧《大铁椎传》", "example": null}, {"def": "又如宝座(指帝王或神佛的座位);上座(坐位分尊卑时,最尊的坐位叫上座);落座(坐到位置上);满座;空座;首座;末座;楼座;茶座;专座;雅座", "example": null}, {"def": "坐具", "example": null}, {"def": "清辇道于上林,肃华台之金座。--《梁书》", "example": null}, {"def": "又如石座;软座;硬座;玉座;蒲座", "example": null}, {"def": "旧时对官长或对他人的敬称", "example": null}, {"def": "座zuò", "example": null}, {"def": "⒈坐位～位。～右铭（写上格言，放在座位旁边。泛指激励、警戒自己的语言）。〈引〉", "example": null}, {"def": "①在座的人～谈。依此入～。举～欢然。〈引〉", "example": null}, {"def": "②旧时敬称高级长官处～。 军～。", "example": null}, {"def": "⒉托着器物的垫子钟～子。洗衣机～儿。", "example": null}, {"def": "⒊指星座天琴～。", "example": null}, {"def": "⒋量词两～山。五～楼房。", "example": null}]','chinese-xinhua','0'),
