('2101143297098518604','左','1','zuǒ','工','5',NULL,'[{"def": "左", "example": null}, {"def": "(会意。甲骨文字形,象手的象形。本义辅佐,从旁帮助◇作佐”)", "example": null}, {"def": "同本义", "example": null}, {"def": "左,手相左助也。--《说文》。俗字作佐”。", "example": null}, {"def": "以左右民。--《易·象上传》", "example": null}, {"def": "予欲左右有民。--《虞书》", "example": null}, {"def": "实左右商王。--《诗·商颂·长发》", "example": null}, {"def": "以左右刑罚。--《周礼·士师》", "example": null}, {"def": "左右就养无方。--《礼记·檀弓》。注谓扶持之。”", "example": null}, {"def": "辅相天地之宜,以左右民。--《易·泰》", "example": null}, {"def": "朕且继礼左助听政。--《后汉书·殇帝纪》", "example": null}, {"def": "贬谪,从朝廷下放到地方为官", "example": null}, {"def": "左,谪官为左迁。自汉起至唐,亦谓去朝廷为州县曰左迁。--《增韵", "example": null}, {"def": "左zuǒ", "example": null}, {"def": "⒈方位词。跟\\"右\\"相对，面向南时在东的一边～脚。～边。江～（江东）。山～（太行山以东，特指山东）。", "example": null}, {"def": "⒉思想政治上属于进步的或激进的～派。～翼。", "example": null}, {"def": "⒊相反，不合意见相～。", "example": null}, {"def": "⒋偏，差错，邪僻想～了。别说～了。旁门～道。", "example": null}, {"def": "⒌附近～近。～邻。", "example": null}, {"def": "⒍证据，证人～证。", "example": null}, {"def": "⒎", "example": null}, {"def": "⒏", "example": null}, {"def": "⒐", "example": null}, {"def": "①左和右两方面～右开弓。～右为难。", "example": null}, {"def": "②上下五十～右。", "example": null}, {"def": "③影响，操纵不受他人～右。", "example": null}, {"def": "④反正，横竖算了吧，～右都一样。", "example": null}, {"def": "⑤侍从，随从有～右相随。", "example": null}, {"def": "⒑", "example": null}]','chinese-xinhua','0'),
('2101143297098518605','佐','1','zuǒ','亻','7',NULL,'[{"def": "佐", "example": null}, {"def": "(本作左。形声。从人,左声。本义辅助,帮助)", "example": null}, {"def": "同本义(古人以右”为尊,左”为卑。佐”常用于下对上、弱对强的帮助。上对下,强对弱时用佑”)", "example": null}, {"def": "佐,助也。--《广雅》", "example": null}, {"def": "故周公旦佐相天子。--《墨子·贵义》", "example": null}, {"def": "陈胜佐之。--《史记·陈涉世家》", "example": null}, {"def": "太宰之职,常建邦之六典,以佐王治邦国。--《周礼·天官》", "example": null}, {"def": "四岳佐之。--《国语·周语下》", "example": null}, {"def": "予佐尔贾。--明·崔铣《记王忠肃公翱三事》", "example": null}, {"def": "佐以科学。--蔡元培《图画》", "example": null}, {"def": "佐读勤苦。--清·周容《芋老人传》", "example": null}, {"def": "又如佐理(助理,帮助处理);佐事(辅助事奉);佐戎(参与军事);", "example": null}, {"def": "佐zuǒ辅助，帮助，也指辅助别人的人～治。辅～。僚～。", "example": null}]','chinese-xinhua','0'),
