('2101143299917090873','笔底春风','2','bǐ dǐ chūn fēng',NULL,NULL,NULL,'[{"def": "形容绘画、诗文生动，如春风来到笔下。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090874','笔底龙蛇','2','bǐ dǐ lóng shé',NULL,NULL,NULL,'[{"def": "犹言笔走龙蛇。形容书法生动而有气势。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090875','笔伐口诛','2','bǐ fá kǒu zhū',NULL,NULL,NULL,'[{"def": "伐声讨，攻打；诛痛斥，责罚。从口头和书面上对坏人坏事进行揭露和声讨。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090876','笔歌墨舞','2','bǐ gē mò wǔ',NULL,NULL,NULL,'[{"def": "指文笔奇妙精采。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090877','笔耕砚田','2','bǐ gēng yàn tián',NULL,NULL,NULL,'[{"def": "比喻从事脑力劳动，以读写为业。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090878','笔酣墨饱','2','bǐ hān mò bǎo',NULL,NULL,NULL,'[{"def": "指文章表达流畅，内容充足。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090879','笔翰如流','2','bǐ hàn rú liú',NULL,NULL,NULL,'[{"def": "指文笔快捷无滞。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090880','笔老墨秀','2','bǐ lǎo mò xiù',NULL,NULL,NULL,'[{"def": "指笔姿老到而墨韵清秀。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090881','笔墨官司','2','bǐ mò guān sī',NULL,NULL,NULL,'[{"def": "笔墨指文字或文章。比喻用文字进行的辩论、争执。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090882','笔墨横姿','2','bǐ mò héng zī',NULL,NULL,NULL,'[{"def": "指书画诗文美妙多姿。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090883','笔墨之林','2','bǐ mò zhī lín',NULL,NULL,NULL,'[{"def": "斯文萃集的地方。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090884','笔扫千军','2','bǐ sǎo qiān jūn',NULL,NULL,NULL,'[{"def": "形容笔力雄健，如同有横扫千军万马的气势。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090885','笔头生花','2','bǐ tóu shēng huā',NULL,NULL,NULL,'[{"def": "比喻写作能力大有进步。也形容文章写得很出色。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090886','笔下超生','2','bǐ xià chāo shēng',NULL,NULL,NULL,'[{"def": "超生佛家语，指人死后灵魂投生为人。为了免使他人受难，书写时，在用意和措词方面都给予宽容或开脱。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090887','笔下生花','2','bǐ xià shēng huā',NULL,NULL,NULL,'[{"def": "比喻文人才思俊逸，写作的诗文极佳。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090888','笔削褒贬','2','bǐ xuē bāo biǎn',NULL,NULL,NULL,'[{"def": "笔记载。削删改。古时在竹简或木简上写字，写错要修改时就用刀削。原指孔子作《春秋》，用文字来评文论物的好坏。也指用文字褒扬、贬斥人或事。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090889','笔冢研穿','2','bǐ zhǒng yán chuān',NULL,NULL,NULL,'[{"def": "秃笔成坟，砚磨穿孔。指写作著述功力极深。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090890','笔诛墨伐','2','bǐ zhū mò fá',NULL,NULL,NULL,'[{"def": "笔、墨指文字。诛谴责。伐声讨。通过文字加以谴责，进行声讨。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090891','笔走龙蛇','2','bǐ zǒu lóng shé',NULL,NULL,NULL,'[{"def": "形容书法生动而有气势。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090892','鄙俚浅陋','2','bǐ lǐ qiǎn lòu',NULL,NULL,NULL,'[{"def": "鄙俚粗俗；浅陋见闻不多。多形容文章或言谈粗俗浅薄。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090893','鄙吝复萌','2','bǐ lìn fù méng',NULL,NULL,NULL,'[{"def": "鄙吝庸俗；萌发生。庸俗的念头又发生了。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090894','鄙夷不屑','2','bǐ yí bù xiè',NULL,NULL,NULL,'[{"def": "指轻视；看不起。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090895','鄙于不屑','2','bǐ yú bù xiè',NULL,NULL,NULL,'[{"def": "鄙粗俗卑鄙。不屑认为不值得（做或看）。粗俗卑鄙到不值得一顾的程度。指既丑陋又下贱，叫人看不上眼。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299917090896','币重言甘','2','bì zhòng yán gān',NULL,NULL,NULL,'[{"def": "币指礼物；厚重。礼物丰厚，言辞好听。指为了能达到某种目的而用财物诱惑。", "example": null}]','chinese-xinhua-idiom','0');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`,`hit_count`) VALUES
('2101143299925479424','必不得已','2','bì bù dé yǐ',NULL,NULL,NULL,'[{"def": "必然不能得止。指形势使得非如此不可。表示无可奈何的意思。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479425','必不挠北','2','bì bù náo běi',NULL,NULL,NULL,'[{"def": "挠北败北，作战失败。必定不会失败。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479426','必操胜券','2','bì cāo shèng quàn',NULL,NULL,NULL,'[{"def": "操持，拿；券凭证；胜券胜利的把握。一定有胜利的把握。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479427','必恭必敬','2','bì gōng bì jìng',NULL,NULL,NULL,'[{"def": "恭、敬端庄而有礼貌。形容态度十分恭敬。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479428','必躬必亲','2','bì gōng bì qīn',NULL,NULL,NULL,'[{"def": "指凡事都要自己经手。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479429','必经之路','2','bì jīng zhī lù',NULL,NULL,NULL,'[{"def": "经经过。一定要经过的道路。亦作必由之路”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479430','必里迟离','2','bì lǐ chí lí',NULL,NULL,NULL,'[{"def": "阴历九月九日。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479431','必也正名','2','bì yě zhèng míng',NULL,NULL,NULL,'[{"def": "指必须按照正统伦理观念和礼仪关系来端正纲纪名分。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479432','必由之路','2','bì yóu zhī lù',NULL,NULL,NULL,'[{"def": "由经由。必定要经过的道路。泛指事物必须遵循的规律或做事必须遵守的法则。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479433','必争之地','2','bì zhēng zhī dì',NULL,NULL,NULL,'[{"def": "敌对双方非争夺不可的战略要地。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479434','毕恭毕敬','2','bì gōng bì jìng',NULL,NULL,NULL,'[{"def": "形容态度十分恭敬。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479435','毕力同心','2','bì lì tóng xīn',NULL,NULL,NULL,'[{"def": "犹言齐心协力。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143299925479436','毕其功于一役','2','bì qí gōng yú yī yì',NULL,NULL,NULL,'[{"def": "把应该分成几步做的事一次做完。亦以形容急于求成。", "example": null}]','chinese-xinhua-idiom','0'),
