('2101143300005171200','蹉跎岁月','2','cuō tuó suì yuè',NULL,NULL,NULL,'[{"def": "蹉跎时光白白过去。把时光白白地耽误过去。指虚度光阴。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171201','蹉跎自误','2','cuō tuó zì wù',NULL,NULL,NULL,'[{"def": "蹉跎时间白白地消耗掉。人生虚度年华，耽误了自己的前程。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171202','厝火积薪','2','cuò huǒ jī xīn',NULL,NULL,NULL,'[{"def": "厝放置；薪柴草。把火放到柴堆下面。比喻潜伏着很大危险。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171203','厝火燎原','2','cuò huǒ liǎo yuán',NULL,NULL,NULL,'[{"def": "放火燎原，比喻小乱子酿成大祸患。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171204','挫骨扬灰','2','cuò gǔ yáng huī',NULL,NULL,NULL,'[{"def": "死后将骨头挫成灰撒掉。形容罪孽深重或恨之极深。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171205','措手不及','2','cuò shǒu bù jí',NULL,NULL,NULL,'[{"def": "措手着手处理。来不及动手应付。指事出意外，一时无法对付。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171206','措心积虑','2','cuò xīn jī lǜ',NULL,NULL,NULL,'[{"def": "犹言处心积虑。指长久考虑在心。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171207','措置裕如','2','cuò zhì yù rú',NULL,NULL,NULL,'[{"def": "措置处理，安排；裕如从容不迫，很有办法的样子。处理事情从容不迫。常用来称赞人有办事的才能和经验。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171208','错彩镂金','2','cuò cǎi lòu jīn',NULL,NULL,NULL,'[{"def": "错涂饰；镂雕刻。形容诗文的词藻十分华丽。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171209','错节盘根','2','cuò jié pán gēn',NULL,NULL,NULL,'[{"def": "错交错；节枝节；盘盘曲。树木的根枝盘旋交错。①比喻事情纷难复杂。②形容人坚韧不拔。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171210','错落不齐','2','cuò luò bù qí',NULL,NULL,NULL,'[{"def": "形容极不整齐。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171211','错落高下','2','cuò luò gāo xià',NULL,NULL,NULL,'[{"def": "犹言长短高低。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171212','错落有致','2','cuò luò yǒu zhì',NULL,NULL,NULL,'[{"def": "错落参差不齐。致情趣。形容事物的布局虽然参差不齐，但却极有情趣，使人看了有好感。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171213','错认颜标','2','cuò rèn yán biāo',NULL,NULL,NULL,'[{"def": "形容懵懂浅陋。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171214','错综复杂','2','cuò zōng fù zá',NULL,NULL,NULL,'[{"def": "错交错，交叉；综合在一起。形容头绪多，情况复杂。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171215','搭搭撒撒','2','dā dā sā sā',NULL,NULL,NULL,'[{"def": "眼皮下垂。引申为没精打采的样子。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171216','嗒然若丧','2','tà rán ruò sàng',NULL,NULL,NULL,'[{"def": "形容懊丧的神情。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171217','达地知根','2','dá dì zhī gēn',NULL,NULL,NULL,'[{"def": "指根底清楚、明白。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171218','达观知命','2','dá guān zhī mìng',NULL,NULL,NULL,'[{"def": "达观指一切听其自然或看得开；命命运；知命指知天命。指对不如意的事情看得开，任凭命运摆布，无所烦恼。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171219','达官贵人','2','dá guān guì rén',NULL,NULL,NULL,'[{"def": "达官大官。指地位高的大官和出身侯门身价显赫的人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171220','达官贵要','2','dá guān guì yào',NULL,NULL,NULL,'[{"def": "犹言达官贵人。指地位高的大官和出身侯门身价显赫的人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171221','达官显宦','2','dá guān xiǎn huàn',NULL,NULL,NULL,'[{"def": "达显贵；宦官。旧指职位高而声势显赫的官员。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171222','达官要人','2','dá guān yào rén',NULL,NULL,NULL,'[{"def": "犹言达官贵人。指地位高的大官和出身侯门身价显赫的人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171223','达官知命','2','dá guān zhī mìng',NULL,NULL,NULL,'[{"def": "达观旧指一切听其自然，也指看得开。知命旧指知天命，想念人的命运是由天决定的。指对不如意的事情看得开，任凭命运安排，无。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171224','达权通变','2','dá quán tōng biàn',NULL,NULL,NULL,'[{"def": "通、达通晓，懂得；权、变权宜，变通。做理能适应客观情况的变化，懂得变通，不死守常规。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171225','达权知变','2','dá quán zhī biàn',NULL,NULL,NULL,'[{"def": "指不死守常规，根据实际情况，随机应变。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171226','达人知命','2','dá rén zhī mìng',NULL,NULL,NULL,'[{"def": "达人通达事理的人。指心胸豁达的人，安于命运。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171227','达士通人','2','dá shì tōng rén',NULL,NULL,NULL,'[{"def": "通人学识渊博贯通古今的人。指心胸豁达，学识渊博的人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171228','怛然失色','2','dá rán shī sè',NULL,NULL,NULL,'[{"def": "怛畏惧，恐惧。指因害怕而变脸色。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171229','沓冈复岭','2','tà gāng fù lǐng',NULL,NULL,NULL,'[{"def": "指冈峦重沓。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171230','沓来麕至','2','tà lái yǒu zhì',NULL,NULL,NULL,'[{"def": "指纷纷到来。同沓来踵至”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171231','沓来踵至','2','tǎ lái zhǒng zhì',NULL,NULL,NULL,'[{"def": "指纷纷到来。亦作踏来麕至”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171232','答非所问','2','dá fēi suǒ wèn',NULL,NULL,NULL,'[{"def": "回答的不是所问的内容。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171233','打抱不平','2','dǎ bào bù píng',NULL,NULL,NULL,'[{"def": "遇见不公平的事，挺身而出，帮助受欺负的一方。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171234','打边鼓','2','dǎ biān gǔ',NULL,NULL,NULL,'[{"def": "指从旁鼓吹、协助。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171235','打草惊蛇','2','dǎ cǎo jīng shé',NULL,NULL,NULL,'[{"def": "打草惊了草里的蛇。原比喻惩罚了甲而使乙有所警觉◇多比喻做法不谨慎，反使对方有所戒备。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171236','打草蛇惊','2','dǎ cǎo shé jīng',NULL,NULL,NULL,'[{"def": "打草惊了草里的蛇。原比喻惩罚了甲而使乙有所警觉◇多比喻做法不谨慎，反使对方有所戒备。同打草惊蛇”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171237','打成一片','2','dǎ chéng yī piàn',NULL,NULL,NULL,'[{"def": "原指形成一个整体。现多形容感情融洽，成为一体。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171238','打得火热','2','dǎ dé huǒ rè',NULL,NULL,NULL,'[{"def": "形容关系十分亲密。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171239','打凤捞龙','2','dǎ fèng lāo lóng',NULL,NULL,NULL,'[{"def": "凤、龙这里指人才。比喻搜索、物色难得的人才。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171240','打凤牢龙','2','dǎ fèng láo lóng',NULL,NULL,NULL,'[{"def": "比喻安排圈套使强有力的对手中计。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171241','打富济贫','2','dǎ fù jì pín',NULL,NULL,NULL,'[{"def": "打击豪绅、地主，贪官污吏，夺取其财物救济穷人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171242','打恭作揖','2','dǎ gōng zuò yī',NULL,NULL,NULL,'[{"def": "旧时礼节，弯身抱拳，上下摆动，表示恭敬。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171243','打躬作揖','2','dǎ gōng zuō yī',NULL,NULL,NULL,'[{"def": "拱、揖两手合抱致敬。弯身报拳行礼。表示恭敬顺从或恳求的样子。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171244','打拱作揖','2','dǎ gǒng zuò yī',NULL,NULL,NULL,'[{"def": "旧时礼节，弯身抱拳，上下摆动，表示恭敬。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171245','打狗看主','2','dǎ gǒu kàn zhǔ',NULL,NULL,NULL,'[{"def": "狗有主人，打不打它，要看给其主人留不留情面。比喻处理坏人下事要顾全其后台的情面。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171246','打滚撒泼','2','dǎ gǔn sā pō',NULL,NULL,NULL,'[{"def": "躺倒在地上打滚，嘴里骂着泼辣的话。同撒泼打滚”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171247','打虎牢龙','2','dǎ hǔ láo lóng',NULL,NULL,NULL,'[{"def": "犹言打凤牢龙。比喻安排圈套使强有力的对手中计。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300005171248','打诨插科','2','dǎ hùn chā kē',NULL,NULL,NULL,'[{"def": "诨诙谐逗趣的话。科指古典戏曲中的表情和动作；戏曲、曲艺演员在表演中穿插进去的引人发笑的动作或语言。同插科打诨”。", "example": null}]','chinese-xinhua-idiom','0'),
