('2101143300017754160','倒箧倾筐','2','dǎo qiè qīng kuāng',NULL,NULL,NULL,'[{"def": "形容倾其所有。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300017754161','倒箧倾囊','2','dǎo qiè qīng náng',NULL,NULL,NULL,'[{"def": "倾囊倒箧。形容倾尽其所有。", "example": null}]','chinese-xinhua-idiom','0'),
