('2101143300051308587','睹物伤情','2','dǔ wù shāng qíng',NULL,NULL,NULL,'[{"def": "看到东西就因想起它的主人而伤感动情。形容深切的怀念。睹看见。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308588','睹物思人','2','dǔ wù sī rén',NULL,NULL,NULL,'[{"def": "睹看；思思念。看见死去或离别的人留下的东西就想起了这个人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308589','睹物兴情','2','dǔ wù xīng qíng',NULL,NULL,NULL,'[{"def": "见到眼前景物便激起某种感情。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308590','睹著知微','2','dǔ zhù zhī wēi',NULL,NULL,NULL,'[{"def": "从明显的表象，推知到隐微的内情。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308591','睹着知微','2','dǔ zhe zhī wēi',NULL,NULL,NULL,'[{"def": "从明显的表象，推知到隐微的内情。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308592','妒能害贤','2','dù néng hài xián',NULL,NULL,NULL,'[{"def": "贤、能有德有才的人；害陷害。嫉妒有才能的人，陷害贤明的人。指容不下才能、品德比自己高的人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308593','妒贤疾能','2','dù xián jí néng',NULL,NULL,NULL,'[{"def": "对品德、才能比自己强的人心怀怨恨。同妒贤嫉能”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308594','妒贤嫉能','2','dù xián jí néng',NULL,NULL,NULL,'[{"def": "妒、嫉因别人好而忌恨。对品德、才能比自己强的人心怀怨恨。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308595','杜弊清源','2','dù bì qīng yuán',NULL,NULL,NULL,'[{"def": "杜绝弊端，廓清来源。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308596','杜断房谋','2','dù duàn fáng móu',NULL,NULL,NULL,'[{"def": "喻指多谋善断。同房谋杜断”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308597','杜耳恶闻','2','dù ěr è wén',NULL,NULL,NULL,'[{"def": "塞住耳朵不愿听。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308598','杜渐除微','2','dù jiàn chú wēi',NULL,NULL,NULL,'[{"def": "在事故或灾害尚未发生时就预防。同杜渐防萌”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308599','杜渐防萌','2','dù jiàn fáng méng',NULL,NULL,NULL,'[{"def": "杜堵住；渐指事物的开端；萌萌芽。在事故或灾害尚未发生时就预防。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308600','杜渐防微','2','dù jiàn fáng wēi',NULL,NULL,NULL,'[{"def": "杜堵住；渐指事物的开端；微微小。错误或坏事刚冒头就及时制止，不让它发展。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308601','杜鹃啼血','2','dù juān tí xuě',NULL,NULL,NULL,'[{"def": "传说杜鹃昼夜悲鸣，啼至血出乃止。常用以形容哀痛之极。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300051308602','杜绝后患','2','dù jué hòu huàn',NULL,NULL,NULL,'[{"def": "杜绝堵塞、断绝；患祸害、祸患。指彻底消除以后可能产生的祸患。", "example": null}]','chinese-xinhua-idiom','0');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`,`hit_count`) VALUES
('2101143300055502848','杜绝人事','2','dù jué rén shì',NULL,NULL,NULL,'[{"def": "杜绝断绝；人事人与人的交往。即断绝与别人的一切交往。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502849','杜绝言路','2','dù jué yán lù',NULL,NULL,NULL,'[{"def": "杜绝断绝，阻塞；言路进言之路。堵塞和断绝一切进言之路，指不纳谏言。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502850','杜口裹足','2','dù kǒu guǒ zú',NULL,NULL,NULL,'[{"def": "杜口闭住嘴；裹足止步不前。闭着嘴不敢说，停住脚不敢走。比喻有顾虑而不敢接近，远远避开。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502851','杜口结舌','2','dù kǒu jié shé',NULL,NULL,NULL,'[{"def": "犹言杜口吞声。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502852','杜口绝言','2','dù kǒu jué yán',NULL,NULL,NULL,'[{"def": "犹言杜口无言。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502853','杜口吞声','2','dù kǒu tūn shēng',NULL,NULL,NULL,'[{"def": "形容一句话也不说。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502854','杜口无言','2','dù kǒu wú yán',NULL,NULL,NULL,'[{"def": "闭住嘴巴，不出一言。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502855','杜门不出','2','dù mén bù chū',NULL,NULL,NULL,'[{"def": "关闭门户，不外出与人交往接触。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502856','杜门晦迹','2','dù mén huì jì',NULL,NULL,NULL,'[{"def": "晦隐匿。关上门，隐匿自己的踪迹。指隐居起来，不让别人知道自己的踪迹或动态。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502857','杜门绝迹','2','dù mén jué jì',NULL,NULL,NULL,'[{"def": "指隐居不出。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502858','杜门绝客','2','dù mén jué kè',NULL,NULL,NULL,'[{"def": "指不与人往来。同杜门谢客”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502859','杜门面壁','2','dù mén mian bì',NULL,NULL,NULL,'[{"def": "指闭门修养。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502860','杜门屏迹','2','dù mén píng jì',NULL,NULL,NULL,'[{"def": "指隐居不出。同杜门晦迹”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502861','杜门却扫','2','dù mén què sǎo',NULL,NULL,NULL,'[{"def": "杜堵塞；却扫不再扫径迎客。关上大门，扫除车迹。指闭门谢客，不和外界往来。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502862','杜门谢客','2','dù mén xiè kè',NULL,NULL,NULL,'[{"def": "杜门闭门不出；谢客谢绝宾客。指不与人往来。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502863','杜门自绝','2','dù mén zì jué',NULL,NULL,NULL,'[{"def": "杜门关门不出；绝断绝。闭门不出，将自己与外界隔绝。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502864','杜门自守','2','dù mén zì shòu',NULL,NULL,NULL,'[{"def": "关闭大门，安分守已。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502865','杜默为诗','2','dù mò wéi shī',NULL,NULL,NULL,'[{"def": "杜杜撰、臆造。杜默指孤陋寡闻。孤陋寡闻，随意杜撰之诗。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502866','杜微慎防','2','dù wēi shèn fáng',NULL,NULL,NULL,'[{"def": "杜杜绝，断绝；慎谨慎。杜绝细微，谨慎防备萌芽。即消灭祸患难与共于萌芽状态之中。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502867','杜隙防微','2','dù xī fāng wēi',NULL,NULL,NULL,'[{"def": "杜隙杜绝疏失。杜绝疏失，防患于未然。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502868','肚里蛔虫','2','dù lǐ huí chóng',NULL,NULL,NULL,'[{"def": "蛔虫因寄生在人的肠胃中，故用以比喻对别人的心里活动知道得十分清楚。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502869','肚里泪下','2','dù lǐ lèi xià',NULL,NULL,NULL,'[{"def": "眼泪往肚里流。形容有苦说不出。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502870','度长絜大','2','dù cháng xié dà',NULL,NULL,NULL,'[{"def": "指比量长短大小。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502871','度长絜短','2','dù cháng xié duǎn',NULL,NULL,NULL,'[{"def": "见度长絜大”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502872','度德量力','2','duó dé liàng lì',NULL,NULL,NULL,'[{"def": "度估量；德德行♀量自己的德行是否能够服人，估计自己的能力是否能够胜任。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502873','度己以绳','2','duó jǐ yǐ shéng',NULL,NULL,NULL,'[{"def": "绳纠正，约束。指一定的道德标准要求自己，使自己的行为合乎法度。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502874','度日如年','2','dù rì rú nián',NULL,NULL,NULL,'[{"def": "过一天象过一年那样长。形容日子很不好过。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502875','度日如岁','2','dù rì rú suì',NULL,NULL,NULL,'[{"def": "过一天象过一年那样长。形容日子很不好过。同度日如年”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502876','度外之人','2','dù wài zhī rén',NULL,NULL,NULL,'[{"def": "度外心在计度之外。指与某人或某集团没有关系或关系不近的人。即局外人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300055502877','蠹国病民','2','dù guó bìng mín',NULL,NULL,NULL,'[{"def": "桅国家和人民。同蠹国害民”。", "example": null}]','chinese-xinhua-idiom','0'),
