('2101143300068085806','反败为胜','2','fǎn bài wéi shèng',NULL,NULL,NULL,'[{"def": "扭转败局，变为胜利。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300068085807','反哺之情','2','fǎn bǔ zhī qíng',NULL,NULL,NULL,'[{"def": "比喻子女长大奉养父母，报答恩情。", "example": null}]','chinese-xinhua-idiom','0'),
