('2101143300672065564','文无加点','2','wén wú jiā diǎn',NULL,NULL,NULL,'[{"def": "形容文思敏捷，写作技巧纯熟。同文不加点”。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143300672065565','文武差事','2','wén wǔ chà shì',NULL,NULL,NULL,'[{"def": "比喻明劫暗偷。", "example": null}]','chinese-xinhua-idiom','0');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`,`hit_count`) VALUES
