INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`,`hit_count`) VALUES
('2101143301066330112','至诚高节','2','zhì chéng gāo jié',NULL,NULL,NULL,'[{"def": "至最。最忠诚，最高尚的节操。形容人品高尚。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143301066330113','至大至刚','2','zhì dà zhì gāng',NULL,NULL,NULL,'[{"def": "至最，极。极其正大、刚强。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143301066330114','至当不易','2','zhì dàng bù yì',NULL,NULL,NULL,'[{"def": "至极；当恰当；易改变。形容极为恰当，不能改变。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143301066330115','至高无上','2','zhì gāo wú shàng',NULL,NULL,NULL,'[{"def": "至最。高到顶点，再也没有更高的了。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143301066330116','至理名言','2','zhì lǐ míng yán',NULL,NULL,NULL,'[{"def": "至最；名有名声的。最正确的道理，最精辟的言论。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143301066330117','至亲骨肉','2','zhì qīn gǔ ròu',NULL,NULL,NULL,'[{"def": "关系最近的亲人。", "example": null}]','chinese-xinhua-idiom','0'),
('2101143301066330118','至亲好友','2','zhì qīn hǎo yǒu',NULL,NULL,NULL,'[{"def": "关系至深的亲戚，感情最好的朋友。", "example": null}]','chinese-xinhua-idiom','0'),
